private func streamStatusText(_ message: String) -> String {
    let trimmed = message.trimmingCharacters(in: .whitespacesAndNewlines)
    let lower = trimmed.lowercased()
    if trimmed.isEmpty || lower.contains("trailer resolver") || lower.contains("resolving trailer") || lower == "trailer ready." || lower.contains("split video/audio") {
        return ""
    }
    return trimmed
}


// vBRDC307: device-side frame pacing probe. This measures the UI presentation cadence
// instead of inferring "60 FPS" from how scrolling looks. It is intentionally lightweight:
// one CADisplayLink, rolling counters only, no per-frame SwiftUI publication.
@MainActor
final class SignalSurfaceGenerationRegistry {
    static let shared = SignalSurfaceGenerationRegistry()
    private var generations: [String: UInt64] = [:]

    func begin(_ key: String) -> UInt64 {
        let next = (generations[key] ?? 0) &+ 1
        generations[key] = next
        return next
    }

    func isCurrent(_ key: String, token: UInt64) -> Bool {
        generations[key] == token
    }
}

@MainActor
private final class SignalFramePacingMonitor: ObservableObject {
    static let shared = SignalFramePacingMonitor()

    @Published private(set) var fps: Double = 0
    @Published private(set) var refreshHz: Int = 0
    @Published private(set) var hitchCount: Int = 0
    @Published private(set) var worstFrameMS: Double = 0
    @Published private(set) var physicalFootprintMB: Double? = nil
    @Published private(set) var liveArtworkJobs: Int = 0

    private var displayLink: CADisplayLink?
    private var lastTimestamp: CFTimeInterval = 0
    private var sampleStart: CFTimeInterval = 0
    private var sampleFrames = 0
    private var sampleHitches = 0
    private var sampleWorst: Double = 0

    func start() {
        guard displayLink == nil else { return }
        let link = CADisplayLink(target: self, selector: #selector(tick(_:)))
        if #available(tvOS 15.0, *) {
            link.preferredFrameRateRange = CAFrameRateRange(
                minimum: 30,
                maximum: Float(SignalVisionWindowMetrics.estimatedMaximumFramesPerSecond),
                preferred: Float(SignalVisionWindowMetrics.estimatedMaximumFramesPerSecond)
            )
        }
        link.add(to: .main, forMode: .common)
        displayLink = link
        refreshHz = SignalVisionWindowMetrics.estimatedMaximumFramesPerSecond
    }

    func stop() {
        displayLink?.invalidate()
        displayLink = nil
        lastTimestamp = 0
        sampleStart = 0
        sampleFrames = 0
    }

    @objc private func tick(_ link: CADisplayLink) {
        let now = link.timestamp
        if sampleStart == 0 { sampleStart = now }
        if lastTimestamp > 0 {
            let frameMS = (now - lastTimestamp) * 1000
            sampleWorst = max(sampleWorst, frameMS)
            let expectedMS = 1000.0 / Double(max(1, SignalVisionWindowMetrics.estimatedMaximumFramesPerSecond))
            if frameMS > expectedMS * 1.75 { sampleHitches += 1 }
        }
        lastTimestamp = now
        sampleFrames += 1

        let elapsed = now - sampleStart
        guard elapsed >= 1.0 else { return }
        fps = Double(sampleFrames - 1) / elapsed
        hitchCount = sampleHitches
        worstFrameMS = sampleWorst
        // Opt-in HUD only; reuse the existing one-second sample rather than
        // scheduling an additional memory poll/display link in the app.
        physicalFootprintMB = LiveTVMemoryAuditManager.currentFootprintMegabytes()
        liveArtworkJobs = LiveTVBoundedArtworkLoader.activeJobCount
        sampleStart = now
        sampleFrames = 0
        sampleHitches = 0
        sampleWorst = 0
    }

    deinit { displayLink?.invalidate() }
}

private struct SignalPerformanceHUD: View {
    @ObservedObject var monitor: SignalFramePacingMonitor
    @AppStorage("signalPerformanceHUDEnabledV1") private var enabled = false

    var body: some View {
        if enabled {
            HStack(spacing: 10) {
                Text("\(monitor.refreshHz) Hz")
                Text(String(format: "%.1f FPS", monitor.fps))
                Text("H \(monitor.hitchCount)")
                Text(String(format: "Worst %.1f ms", monitor.worstFrameMS))
                if let footprint = monitor.physicalFootprintMB {
                    Text(String(format: "Mem %.0f MB", footprint))
                }
                Text("Art Jobs \(monitor.liveArtworkJobs)")
            }
            .font(.system(size: 14, weight: .black, design: .monospaced))
            .foregroundStyle(.white)
            .padding(.horizontal, 14)
            .frame(height: 34)
            .background(Capsule().fill(Color.black.opacity(0.82)))
            .overlay(Capsule().stroke(Color.cyan.opacity(0.65), lineWidth: 1))
            .padding(.top, 12)
            .allowsHitTesting(false)
        }
    }
}


private final class SignalMainThreadStallWatchdog {
    static let shared = SignalMainThreadStallWatchdog()
    private let queue = DispatchQueue(label: "com.debridchannels.signal.stallwatchdog", qos: .userInteractive)
    private var timer: DispatchSourceTimer?
    private var pingInFlight = false
    private var pingStarted: UInt64 = 0
    private var stallStarted: UInt64?
    private var lastSurface: String = "launch"
    private let lock = NSLock()

    private init() {}

    func start() {
        queue.async { [weak self] in
            guard let self, self.timer == nil else { return }
            let timer = DispatchSource.makeTimerSource(queue: self.queue)
            timer.schedule(deadline: .now() + .milliseconds(500), repeating: .milliseconds(16))
            timer.setEventHandler { [weak self] in self?.tick() }
            self.timer = timer
            timer.resume()
            print("[SignalStall][vBRDC328] watchdog started threshold=35ms")
        }
    }

    func stop() {
        queue.async { [weak self] in
            guard let self else { return }
            self.timer?.cancel()
            self.timer = nil
            self.pingInFlight = false
            self.stallStarted = nil
        }
    }

    func markSurface(_ value: String) {
        lock.lock(); lastSurface = value; lock.unlock()
    }

    private func tick() {
        let now = DispatchTime.now().uptimeNanoseconds
        if pingInFlight {
            let elapsed = Double(now - pingStarted) / 1_000_000
            if elapsed >= 35, stallStarted == nil {
                stallStarted = pingStarted
                lock.lock(); let surface = lastSurface; lock.unlock()
                print("[SignalStall][vBRDC328] START \(String(format: "%.1f", elapsed))ms surface=\(surface)")
            }
            return
        }

        pingInFlight = true
        pingStarted = now
        DispatchQueue.main.async { [weak self] in
            guard let self else { return }
            let returned = DispatchTime.now().uptimeNanoseconds
            self.queue.async {
                if let start = self.stallStarted {
                    let total = Double(returned - start) / 1_000_000
                    self.lock.lock(); let surface = self.lastSurface; self.lock.unlock()
                    print("[SignalStall][vBRDC328] END \(String(format: "%.1f", total))ms surface=\(surface)")
                    self.stallStarted = nil
                }
                self.pingInFlight = false
            }
        }
    }
}

