private enum BluetoothVODMediaCommand: String {
    case toggle
    case play
    case pause
}

/// Concrete media classification published to MediaRemote. `MPNowPlayingInfoPropertyMediaType`
/// only distinguishes audio/video; `MPMediaItemPropertyMediaType` carries the movie vs TV identity
/// that Home Assistant/pyatv and other accessories can use to classify the current item.
private enum DebridNowPlayingContentKind {
    case movie
    case tvShow
    case liveTV

    var mediaItemType: MPMediaType {
        switch self {
        case .movie: return .movie
        case .tvShow, .liveTV: return .tvShow
        }
    }
}

private enum DebridNowPlayingArtworkURL {
    static func url(_ input: String?) -> URL? {
        guard var raw = PremiumArtworkURL.upgraded(input) else { return nil }
        // Now Playing artwork never needs the app's full-resolution hero budget. Avoid
        // downloading multi-megabyte TMDB originals while video is decoding.
        if raw.contains("image.tmdb.org/t/p/original/") {
            raw = raw.replacingOccurrences(of: "/t/p/original/", with: "/t/p/w780/")
        }
        if let direct = URL(string: raw), direct.scheme != nil { return direct }
        if let encoded = raw.addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed),
           let result = URL(string: encoded), result.scheme != nil {
            return result
        }
        return nil
    }
}

private extension Notification.Name {
    static let debridBluetoothVODMediaCommand = Notification.Name("DebridChannels.BluetoothVODMediaCommand")
}


/// vBRDC211: one authoritative tvOS Now Playing publisher for Debrid Channels.
///
/// KSPlayer/VLC remain the real video/audio renderers. A tiny bundled, permanently-muted
/// local AVQueuePlayer exists only as the AVFoundation ownership anchor required by
/// MPNowPlayingSession. The session-scoped Now Playing and remote-command centers are the
/// authoritative MediaRemote surface; the hidden player never replaces, transcodes, or
/// clocks the actual Debrid Channels stream.
private final class DebridNowPlayingManager {
    static let shared = DebridNowPlayingManager()

    static let systemSessionStatusDefaultsKey = "debridSystemNowPlayingStatusV2"
    static let systemSessionLastClaimDefaultsKey = "debridSystemNowPlayingLastClaimV2"
    static let systemMediaRemoteLastEventDefaultsKey = "debridSystemMediaRemoteLastEventV2"

    private let lock = NSLock()
    private var ownerSessionID: UUID?
    private var ownerIsLive = false
    private var ownerIsPlaying = false
    private var ownerContentKind: DebridNowPlayingContentKind = .movie
    private var ownerTimingElapsed: Double = 0
    private var ownerTimingDuration: Double = 0
    private var ownerTimingUptime: TimeInterval = 0
    private var lastPublishedInfo: [String: Any] = [:]
    private var activationGeneration: UInt64 = 0
    // vBRDC220: an MPNowPlayingSession has no explicit resign/deactivate API. After a
    // completed playback we fully discard its AVPlayer/session pair and require the next
    // movie, episode, or Live TV channel to perform a brand-new MediaRemote claim. This
    // avoids trusting a stale `isActive` value after Home Assistant has already observed Idle.
    private var requiresFreshSystemMediaClaim = true
    private var defaultCenterFallbackActive = false
    private var artworkGeneration: UInt64 = 0
    private var heartbeatTimer: Timer?
    private var activeArtworkURL: URL?

    // Now Playing artwork is tiny compared with the app-wide artwork reservoir. Keep a small
    // independent cache so Home Assistant/MediaRemote refreshes never perturb catalog scrolling.
    private let artworkCache: NSCache<NSURL, UIImage> = {
        let cache = NSCache<NSURL, UIImage>()
        cache.countLimit = 8
        cache.totalCostLimit = 24 * 1024 * 1024
        return cache
    }()
    private lazy var artworkSession: URLSession = {
        let configuration = URLSessionConfiguration.ephemeral
        configuration.requestCachePolicy = .returnCacheDataElseLoad
        configuration.timeoutIntervalForRequest = 8
        configuration.timeoutIntervalForResource = 12
        configuration.httpMaximumConnectionsPerHost = 3
        return URLSession(configuration: configuration)
    }()

    // vBRDC211: MPNowPlayingSession can only represent AVPlayer instances. KSPlayer/VLC do
    // not provide one to MediaPlayer, so this muted local loop is the system-media anchor.
    // vBRDC220: this pair is retained only for the current MediaRemote ownership epoch and is
    // rebuilt after a completed playback so every new item can perform a clean system claim.
    private var mediaAnchorPlayer: AVQueuePlayer?
    private var mediaAnchorLooper: AVPlayerLooper?
    private var nowPlayingSession: MPNowPlayingSession?

    private init() {
        UserDefaults.standard.set("Idle", forKey: Self.systemSessionStatusDefaultsKey)
        if UserDefaults.standard.string(forKey: Self.systemSessionLastClaimDefaultsKey) == nil {
            UserDefaults.standard.set("None", forKey: Self.systemSessionLastClaimDefaultsKey)
        }
        if UserDefaults.standard.string(forKey: Self.systemMediaRemoteLastEventDefaultsKey) == nil {
            UserDefaults.standard.set("None", forKey: Self.systemMediaRemoteLastEventDefaultsKey)
        }
    }

    /// Creates the real AVPlayer-backed MPNowPlayingSession once. This must happen before
    /// Bluetooth command targets are installed so the session-scoped command center is the
    /// first-class route instead of the old process-wide-only compatibility route.
    @discardableResult
    private func prepareSystemMediaAnchorIfNeededOnMain() -> Bool {
        assert(Thread.isMainThread)
        if mediaAnchorPlayer != nil, defaultCenterFallbackActive || nowPlayingSession != nil { return true }

        // vBRDC220: never stitch a new session onto a partially-retained ownership graph.
        // A released MPNowPlayingSession can continue to look active in-process after
        // mediaremoted has already removed it. Start from a coherent anchor/session pair.
        nowPlayingSession?.nowPlayingInfoCenter.nowPlayingInfo = nil
        nowPlayingSession = nil
        mediaAnchorLooper = nil
        mediaAnchorPlayer?.pause()
        mediaAnchorPlayer?.removeAllItems()
        mediaAnchorPlayer = nil
        defaultCenterFallbackActive = false

        guard let url = Bundle.main.url(forResource: "DebridSystemMediaAnchor", withExtension: "m4a") else {
            UserDefaults.standard.set("Unavailable", forKey: Self.systemSessionStatusDefaultsKey)
            UserDefaults.standard.set("Anchor resource missing", forKey: Self.systemSessionLastClaimDefaultsKey)
            print("[NowPlaying][vBRDC211] Missing DebridSystemMediaAnchor.m4a")
            return false
        }

        let templateItem = AVPlayerItem(url: url)
        let player = AVQueuePlayer(items: [])
        player.isMuted = true
        player.volume = 0
        player.automaticallyWaitsToMinimizeStalling = false
        let looper = AVPlayerLooper(player: player, templateItem: templateItem)

        mediaAnchorPlayer = player
        mediaAnchorLooper = looper
        if !defaultCenterFallbackActive {
            let session = MPNowPlayingSession(players: [player])
            session.automaticallyPublishesNowPlayingInfo = false
            nowPlayingSession = session
            requiresFreshSystemMediaClaim = true
        }
        // vBRDC214: keep the default center alive too. Apple's custom-player tvOS sample
        // publishes through MPNowPlayingInfoCenter.default(); the MPNowPlayingSession center
        // remains mirrored for explicit session ownership. Publishing both avoids a session-
        // scoped-only metadata path that some tvOS MediaRemote surfaces do not expose.
        return true
    }

    private func preparedCommandCentersOnMain() -> [MPRemoteCommandCenter] {
        assert(Thread.isMainThread)
        // vBRDC214: Apple's custom-player guidance uses the shared command center for
        // external accessories. Register it first/authoritatively, then mirror the session
        // center for MPNowPlayingSession ownership. Duplicate delivery is still de-duplicated.
        var centers: [MPRemoteCommandCenter] = [MPRemoteCommandCenter.shared()]
        if prepareSystemMediaAnchorIfNeededOnMain(), let session = nowPlayingSession {
            centers.append(session.remoteCommandCenter)
        }

        var seen = Set<ObjectIdentifier>()
        return centers.filter { seen.insert(ObjectIdentifier($0)).inserted }
    }

    func remoteCommandCenters() -> [MPRemoteCommandCenter] {
        if Thread.isMainThread { return preparedCommandCentersOnMain() }
        return DispatchQueue.main.sync { self.preparedCommandCentersOnMain() }
    }

    private func activateSystemMediaSession() {
        let activate: () -> Void = {
            let session = AVAudioSession.sharedInstance()
            do {
                try session.setCategory(.playback, mode: .moviePlayback, options: [])
                try session.setActive(true)
                UIApplication.shared.beginReceivingRemoteControlEvents()
            } catch {
                print("[NowPlaying][vBRDC211] Unable to activate tvOS media session: \(error.localizedDescription)")
            }
        }
        if Thread.isMainThread { activate() } else { DispatchQueue.main.async(execute: activate) }
    }

    private func publishSnapshotOnMain(_ info: [String: Any]) {
        assert(Thread.isMainThread)
        // vBRDC217: when an MPNowPlayingSession exists, Apple treats its info center as the
        // authoritative publisher and may ignore the default center. Publish the active session
        // first, then mirror the same complete dictionary to the default center for older
        // accessories/Home Assistant paths that still observe the process-wide center.
        if prepareSystemMediaAnchorIfNeededOnMain(), let session = nowPlayingSession {
            session.automaticallyPublishesNowPlayingInfo = false
            session.nowPlayingInfoCenter.nowPlayingInfo = info
        }
        MPNowPlayingInfoCenter.default().nowPlayingInfo = info
    }

    private func ensureHeartbeatOnMain() {
        assert(Thread.isMainThread)
        guard heartbeatTimer == nil else { return }
        heartbeatTimer = Timer.scheduledTimer(withTimeInterval: 10.0, repeats: true) { [weak self] _ in
            guard let self else { return }
            let now = ProcessInfo.processInfo.systemUptime
            self.lock.lock()
            let ownerID = self.ownerSessionID
            var snapshot = self.lastPublishedInfo
            let shouldPlay = self.ownerIsPlaying
            let baseElapsed = self.ownerTimingElapsed
            let duration = self.ownerTimingDuration
            let baseUptime = self.ownerTimingUptime
            self.lock.unlock()
            guard let ownerID, !snapshot.isEmpty else { return }

            // vBRDC217: MediaRemote clients such as pyatv/Home Assistant can age an otherwise
            // valid custom-player item to idle if no state changes occur for a long period.
            // Publish a fresh elapsed value every ten seconds. The VOD decoder still replaces
            // this with its real ~5-second clock snapshots; Live TV gets a monotonic heartbeat
            // even when no programme boundary or UI event has occurred.
            let delta = shouldPlay && baseUptime > 0 ? max(0, now - baseUptime) : 0
            let extrapolated = duration > 0
                ? min(max(0, baseElapsed + delta), duration)
                : max(0, baseElapsed + delta)
            snapshot[MPNowPlayingInfoPropertyElapsedPlaybackTime] = extrapolated
            snapshot[MPNowPlayingInfoPropertyPlaybackRate] = shouldPlay ? 1.0 : 0.0
            if duration > 0 {
                snapshot[MPNowPlayingInfoPropertyPlaybackProgress] = min(max(extrapolated / duration, 0), 1)
            }

            self.lock.lock()
            guard self.ownerSessionID == ownerID else {
                self.lock.unlock()
                return
            }
            self.lastPublishedInfo = snapshot
            self.lock.unlock()

            self.publishSnapshotOnMain(snapshot)
            self.synchronizeAnchorPlaybackOnMain(isPlaying: shouldPlay)
            self.requestSystemSessionActivationOnMain(reason: "10-second MediaRemote heartbeat")
        }
        heartbeatTimer?.tolerance = 1.0
    }

    private func stopHeartbeatOnMain() {
        assert(Thread.isMainThread)
        heartbeatTimer?.invalidate()
        heartbeatTimer = nil
    }

    private func downsampleNowPlayingArtwork(data: Data, maxPixelSize: Int = 1280) -> UIImage? {
        let options = [kCGImageSourceShouldCache: false] as CFDictionary
        guard let source = CGImageSourceCreateWithData(data as CFData, options) else { return nil }
        let thumbnailOptions = [
            kCGImageSourceCreateThumbnailFromImageAlways: true,
            kCGImageSourceCreateThumbnailWithTransform: true,
            kCGImageSourceThumbnailMaxPixelSize: maxPixelSize,
            kCGImageSourceShouldCacheImmediately: true
        ] as CFDictionary
        guard let cgImage = CGImageSourceCreateThumbnailAtIndex(source, 0, thumbnailOptions) else { return nil }
        return UIImage(cgImage: cgImage)
    }

    private func loadArtwork(for sessionID: UUID, url: URL?) {
        let start: () -> Void = {
            self.lock.lock()
            guard self.ownerSessionID == sessionID else {
                self.lock.unlock()
                return
            }
            self.artworkGeneration &+= 1
            let generation = self.artworkGeneration
            self.activeArtworkURL = url
            self.lock.unlock()

            guard let url else { return }
            if let cached = self.artworkCache.object(forKey: url as NSURL) {
                self.applyArtworkOnMain(cached, sessionID: sessionID, url: url, generation: generation)
                return
            }

            var request = URLRequest(url: url)
            request.timeoutInterval = 8
            request.setValue("image/*", forHTTPHeaderField: "Accept")
            self.artworkSession.dataTask(with: request) { [weak self] data, response, error in
                guard let self, error == nil, let data, !data.isEmpty else { return }
                if let http = response as? HTTPURLResponse, !(200...299).contains(http.statusCode) { return }
                guard let image = self.downsampleNowPlayingArtwork(data: data) else { return }
                let cost = max(1, Int(image.size.width * image.size.height * 4))
                self.artworkCache.setObject(image, forKey: url as NSURL, cost: cost)
                DispatchQueue.main.async {
                    self.applyArtworkOnMain(image, sessionID: sessionID, url: url, generation: generation)
                }
            }.resume()
        }
        if Thread.isMainThread { start() } else { DispatchQueue.main.async(execute: start) }
    }

    private func applyArtworkOnMain(_ image: UIImage, sessionID: UUID, url: URL, generation: UInt64) {
        assert(Thread.isMainThread)
        lock.lock()
        guard ownerSessionID == sessionID, artworkGeneration == generation, activeArtworkURL == url else {
            lock.unlock()
            return
        }
        var info = lastPublishedInfo
        let shouldPlay = ownerIsPlaying
        lock.unlock()

        let artwork = MPMediaItemArtwork(boundsSize: image.size) { _ in image }
        info[MPMediaItemPropertyArtwork] = artwork

        lock.lock()
        guard ownerSessionID == sessionID, artworkGeneration == generation else {
            lock.unlock()
            return
        }
        lastPublishedInfo = info
        lock.unlock()

        publishSnapshotOnMain(info)
        synchronizeAnchorPlaybackOnMain(isPlaying: shouldPlay)
        requestSystemSessionActivationOnMain(reason: "Now Playing artwork ready")
    }

    private func synchronizeAnchorPlaybackOnMain(isPlaying: Bool) {
        assert(Thread.isMainThread)
        guard prepareSystemMediaAnchorIfNeededOnMain(), let player = mediaAnchorPlayer else { return }
        // vBRDC214: never pause the silent ownership anchor while a real media session exists.
        // Pausing the only AVPlayer in MPNowPlayingSession after the first headphone Pause can
        // make tvOS stop routing the following Play press to a custom KSPlayer/VLC app. The
        // real paused/playing state is represented by MPNowPlayingInfoPropertyPlaybackRate;
        // this muted local loop only keeps MediaRemote ownership eligible.
        lock.lock()
        let hasOwner = ownerSessionID != nil
        lock.unlock()
        if hasOwner, player.timeControlStatus != .playing { player.play() }
    }

    private func activateDefaultCenterFallbackOnMain(reason: String) {
        assert(Thread.isMainThread)
        lock.lock()
        guard ownerSessionID != nil else {
            lock.unlock()
            return
        }
        defaultCenterFallbackActive = true
        requiresFreshSystemMediaClaim = false
        activationGeneration &+= 1
        let snapshot = lastPublishedInfo
        let shouldPlay = ownerIsPlaying
        lock.unlock()

        // If tvOS refuses this synthetic AVPlayer's MPNowPlayingSession, keeping that session
        // alive can suppress MPNowPlayingInfoCenter.default(). Apple's normal custom-player
        // path uses the default center + shared command center, so fall back to that exact path
        // while retaining the already-working silent AVPlayer/audio-session ownership anchor.
        nowPlayingSession?.nowPlayingInfoCenter.nowPlayingInfo = nil
        BluetoothVODMediaButtonCoordinator.shared.retainSharedCommandCenterOnlyForDefaultNowPlayingFallback()
        nowPlayingSession = nil
        if !snapshot.isEmpty { MPNowPlayingInfoCenter.default().nowPlayingInfo = snapshot }
        synchronizeAnchorPlaybackOnMain(isPlaying: shouldPlay)
        ensureHeartbeatOnMain()
        UserDefaults.standard.set("Active", forKey: Self.systemSessionStatusDefaultsKey)
        UserDefaults.standard.set("Default-center fallback", forKey: Self.systemSessionLastClaimDefaultsKey)
        #if DEBUG
        print("[NowPlaying][vBRDC220] Using default-center fallback: \(reason)")
        #endif
    }

    private func requestSystemSessionActivationOnMain(reason: String) {
        assert(Thread.isMainThread)
        if defaultCenterFallbackActive {
            ensureHeartbeatOnMain()
            return
        }
        guard prepareSystemMediaAnchorIfNeededOnMain(), let session = nowPlayingSession else { return }
        if !session.canBecomeActive {
            activateDefaultCenterFallbackOnMain(reason: "session cannot become active • \(reason)")
            return
        }

        lock.lock()
        guard ownerSessionID != nil else {
            lock.unlock()
            return
        }
        activationGeneration &+= 1
        let generation = activationGeneration
        lock.unlock()

        // vBRDC220: `isActive` is only a useful fast path while the exact same playback
        // ownership epoch is still alive. After release/reclaim (or a system lifecycle
        // reassert) we deliberately call becomeActiveIfPossible again even if the object
        // reports active, because mediaremoted may already have dropped the old publication.
        if session.isActive && !requiresFreshSystemMediaClaim {
            UserDefaults.standard.set("Active", forKey: Self.systemSessionStatusDefaultsKey)
            UserDefaults.standard.set("Active", forKey: Self.systemSessionLastClaimDefaultsKey)
            ensureHeartbeatOnMain()
            return
        }

        UserDefaults.standard.set(requiresFreshSystemMediaClaim ? "Reclaiming" : "Requesting", forKey: Self.systemSessionStatusDefaultsKey)
        session.becomeActiveIfPossible { [weak self, weak session] accepted in
            guard let self else { return }
            DispatchQueue.main.async {
                self.lock.lock()
                let stillOwned = self.ownerSessionID != nil && self.activationGeneration == generation
                self.lock.unlock()
                guard stillOwned else { return }

                let active = accepted || (session?.isActive ?? false)
                let result = active ? "Active" : "Rejected"
                UserDefaults.standard.set(result, forKey: Self.systemSessionStatusDefaultsKey)
                UserDefaults.standard.set(result, forKey: Self.systemSessionLastClaimDefaultsKey)

                if active {
                    self.requiresFreshSystemMediaClaim = false
                    // vBRDC217: the previous builds published metadata before asking the
                    // MPNowPlayingSession to become active. Bluetooth could work through the
                    // shared command center while the activation happened later, leaving the
                    // session's metadata invisible to MediaRemote/Home Assistant. Re-publish
                    // the latest complete snapshot only after activation has actually won.
                    self.lock.lock()
                    let snapshot = self.lastPublishedInfo
                    let shouldPlay = self.ownerIsPlaying
                    self.lock.unlock()
                    if !snapshot.isEmpty {
                        self.publishSnapshotOnMain(snapshot)
                        self.synchronizeAnchorPlaybackOnMain(isPlaying: shouldPlay)
                    }
                    self.ensureHeartbeatOnMain()
                } else {
                    self.activateDefaultCenterFallbackOnMain(reason: "MPNowPlayingSession rejected • \(reason)")
                }
                #if DEBUG
                print("[NowPlaying][vBRDC220] MPNowPlayingSession claim \(result.lowercased()) reason=\(reason)")
                #endif
            }
        }
    }

    func reassertCurrentSession(reason: String) {
        lock.lock()
        let hasOwner = ownerSessionID != nil
        let snapshot = lastPublishedInfo
        let shouldPlay = ownerIsPlaying
        lock.unlock()
        guard hasOwner, !snapshot.isEmpty else { return }

        activateSystemMediaSession()
        let publish: () -> Void = {
            // vBRDC220: a reassert is only requested after an app/audio/media-service
            // lifecycle edge. Do not trust the old MPNowPlayingSession active bit here.
            self.requiresFreshSystemMediaClaim = true
            self.publishSnapshotOnMain(snapshot)
            self.synchronizeAnchorPlaybackOnMain(isPlaying: shouldPlay)
            self.requestSystemSessionActivationOnMain(reason: reason)
            #if DEBUG
            print("[NowPlaying][vBRDC211] Reasserted session-scoped Now Playing: \(reason)")
            #endif
        }
        if Thread.isMainThread { publish() } else { DispatchQueue.main.async(execute: publish) }
    }

    func claimVODSession(
        _ sessionID: UUID,
        title: String,
        duration: Double,
        elapsed: Double,
        isPlaying: Bool
    ) {
        lock.lock()
        ownerSessionID = sessionID
        ownerIsLive = false
        ownerIsPlaying = isPlaying
        ownerContentKind = .movie
        artworkGeneration &+= 1
        activeArtworkURL = nil
        lock.unlock()
        activateSystemMediaSession()
        updateVODTiming(
            sessionID: sessionID,
            title: title,
            duration: duration,
            elapsed: elapsed,
            isPlaying: isPlaying,
            reset: true
        )
        DebridNowShowingDirectPushManager.shared.claimVOD(
            sessionID: sessionID,
            title: title,
            duration: duration,
            elapsed: elapsed,
            isPlaying: isPlaying
        )
    }

    func enrichVODSession(
        _ sessionID: UUID,
        title: String,
        artist: String?,
        albumTitle: String?,
        externalContentID: String?,
        assetURL: URL?,
        contentKind: DebridNowPlayingContentKind,
        artworkURL: URL?
    ) {
        lock.lock()
        if ownerSessionID == sessionID { ownerContentKind = contentKind }
        lock.unlock()
        mutate(sessionID: sessionID, reset: false) { info in
            info[MPMediaItemPropertyTitle] = title
            if let artist, !artist.isEmpty { info[MPMediaItemPropertyArtist] = artist }
            else { info.removeValue(forKey: MPMediaItemPropertyArtist) }
            if let albumTitle, !albumTitle.isEmpty { info[MPMediaItemPropertyAlbumTitle] = albumTitle }
            else { info.removeValue(forKey: MPMediaItemPropertyAlbumTitle) }
            if let externalContentID, !externalContentID.isEmpty {
                info[MPNowPlayingInfoPropertyExternalContentIdentifier] = externalContentID
            }
            if let assetURL { info[MPNowPlayingInfoPropertyAssetURL] = assetURL }
            info[MPNowPlayingInfoPropertyMediaType] = NSNumber(value: MPNowPlayingInfoMediaType.video.rawValue)
            info[MPMediaItemPropertyMediaType] = NSNumber(value: contentKind.mediaItemType.rawValue)
            info[MPNowPlayingInfoPropertyIsLiveStream] = false
        }
        loadArtwork(for: sessionID, url: artworkURL)
        let directContentType: String
        switch contentKind {
        case .movie: directContentType = "movie"
        case .tvShow: directContentType = "episode"
        case .liveTV: directContentType = "live"
        }
        DebridNowShowingDirectPushManager.shared.enrichVOD(
            sessionID: sessionID,
            title: title,
            artist: artist,
            albumTitle: albumTitle,
            externalContentID: externalContentID,
            contentType: directContentType,
            artworkURL: artworkURL
        )
    }

    func updateVODTiming(
        sessionID: UUID,
        title: String,
        duration: Double,
        elapsed: Double,
        isPlaying: Bool,
        reset: Bool = false
    ) {
        let safeElapsed = elapsed.isFinite ? max(0, elapsed) : 0
        let safeDuration = duration.isFinite ? max(0, duration) : 0
        lock.lock()
        if ownerSessionID == sessionID {
            ownerIsPlaying = isPlaying
            ownerTimingElapsed = safeElapsed
            ownerTimingDuration = safeDuration
            ownerTimingUptime = ProcessInfo.processInfo.systemUptime
        }
        lock.unlock()
        mutate(sessionID: sessionID, reset: reset) { info in
            if info[MPMediaItemPropertyTitle] == nil { info[MPMediaItemPropertyTitle] = title }
            if safeDuration > 0 { info[MPMediaItemPropertyPlaybackDuration] = safeDuration }
            else { info.removeValue(forKey: MPMediaItemPropertyPlaybackDuration) }
            info[MPNowPlayingInfoPropertyElapsedPlaybackTime] = safeElapsed
            info[MPNowPlayingInfoPropertyPlaybackRate] = isPlaying ? 1.0 : 0.0
            info[MPNowPlayingInfoPropertyDefaultPlaybackRate] = 1.0
            info[MPNowPlayingInfoPropertyMediaType] = NSNumber(value: MPNowPlayingInfoMediaType.video.rawValue)
            if safeDuration > 0 {
                info[MPNowPlayingInfoPropertyPlaybackProgress] = min(max(safeElapsed / safeDuration, 0), 1)
            } else {
                info.removeValue(forKey: MPNowPlayingInfoPropertyPlaybackProgress)
            }
            info[MPNowPlayingInfoPropertyIsLiveStream] = false
        }
        DebridNowShowingDirectPushManager.shared.updateVODTiming(
            sessionID: sessionID,
            title: title,
            duration: safeDuration,
            elapsed: safeElapsed,
            isPlaying: isPlaying
        )
    }

    func claimLiveSession(
        _ sessionID: UUID,
        title: String,
        channelName: String,
        subtitle: String?,
        duration: Double,
        elapsed: Double,
        externalContentID: String?,
        assetURL: URL?,
        artworkURL: URL?
    ) {
        lock.lock()
        ownerSessionID = sessionID
        ownerIsLive = true
        ownerIsPlaying = true
        ownerContentKind = .liveTV
        artworkGeneration &+= 1
        activeArtworkURL = nil
        lock.unlock()
        activateSystemMediaSession()
        publishLiveSession(
            sessionID,
            title: title,
            channelName: channelName,
            subtitle: subtitle,
            duration: duration,
            elapsed: elapsed,
            externalContentID: externalContentID,
            assetURL: assetURL,
            artworkURL: artworkURL,
            reset: true
        )
    }

    func updateLiveSession(
        _ sessionID: UUID,
        title: String,
        channelName: String,
        subtitle: String?,
        duration: Double,
        elapsed: Double,
        externalContentID: String?,
        assetURL: URL?,
        artworkURL: URL?
    ) {
        publishLiveSession(
            sessionID,
            title: title,
            channelName: channelName,
            subtitle: subtitle,
            duration: duration,
            elapsed: elapsed,
            externalContentID: externalContentID,
            assetURL: assetURL,
            artworkURL: artworkURL,
            reset: false
        )
    }

    func updateLivePlaybackState(_ sessionID: UUID, isPlaying: Bool) {
        let now = ProcessInfo.processInfo.systemUptime
        lock.lock()
        if ownerSessionID == sessionID {
            if ownerIsPlaying, !isPlaying, ownerTimingUptime > 0 {
                let delta = max(0, now - ownerTimingUptime)
                ownerTimingElapsed = ownerTimingDuration > 0
                    ? min(ownerTimingElapsed + delta, ownerTimingDuration)
                    : ownerTimingElapsed + delta
            }
            ownerIsPlaying = isPlaying
            ownerTimingUptime = now
        }
        let currentElapsed = ownerSessionID == sessionID ? ownerTimingElapsed : 0
        let currentDuration = ownerSessionID == sessionID ? ownerTimingDuration : 0
        lock.unlock()
        mutate(sessionID: sessionID, reset: false) { info in
            info[MPNowPlayingInfoPropertyElapsedPlaybackTime] = currentElapsed
            info[MPNowPlayingInfoPropertyPlaybackRate] = isPlaying ? 1.0 : 0.0
            info[MPNowPlayingInfoPropertyDefaultPlaybackRate] = 1.0
            if currentDuration > 0 {
                info[MPNowPlayingInfoPropertyPlaybackProgress] = min(max(currentElapsed / currentDuration, 0), 1)
            }
            info[MPNowPlayingInfoPropertyIsLiveStream] = true
        }
        DebridNowShowingDirectPushManager.shared.updatePlaybackState(sessionID: sessionID, isPlaying: isPlaying)
    }

    private func publishLiveSession(
        _ sessionID: UUID,
        title: String,
        channelName: String,
        subtitle: String?,
        duration: Double,
        elapsed: Double,
        externalContentID: String?,
        assetURL: URL?,
        artworkURL: URL?,
        reset: Bool
    ) {
        let safeDuration = duration.isFinite ? max(0, duration) : 0
        let safeElapsed = elapsed.isFinite ? max(0, elapsed) : 0
        lock.lock()
        let isPlaying = ownerSessionID == sessionID ? ownerIsPlaying : true
        if ownerSessionID == sessionID {
            ownerTimingElapsed = safeElapsed
            ownerTimingDuration = safeDuration
            ownerTimingUptime = ProcessInfo.processInfo.systemUptime
        }
        lock.unlock()
        mutate(sessionID: sessionID, reset: reset) { info in
            info[MPMediaItemPropertyTitle] = title
            if !channelName.isEmpty { info[MPMediaItemPropertyArtist] = channelName }
            if let subtitle, !subtitle.isEmpty { info[MPMediaItemPropertyAlbumTitle] = subtitle }
            else { info.removeValue(forKey: MPMediaItemPropertyAlbumTitle) }
            if safeDuration > 0 {
                info[MPMediaItemPropertyPlaybackDuration] = safeDuration
                info[MPNowPlayingInfoPropertyElapsedPlaybackTime] = min(safeElapsed, safeDuration)
            } else {
                info.removeValue(forKey: MPMediaItemPropertyPlaybackDuration)
                info[MPNowPlayingInfoPropertyElapsedPlaybackTime] = safeElapsed
            }
            info[MPNowPlayingInfoPropertyPlaybackRate] = isPlaying ? 1.0 : 0.0
            info[MPNowPlayingInfoPropertyDefaultPlaybackRate] = 1.0
            info[MPNowPlayingInfoPropertyMediaType] = NSNumber(value: MPNowPlayingInfoMediaType.video.rawValue)
            info[MPMediaItemPropertyMediaType] = NSNumber(value: MPMediaType.tvShow.rawValue)
            if safeDuration > 0 {
                info[MPNowPlayingInfoPropertyPlaybackProgress] = min(max(safeElapsed / safeDuration, 0), 1)
            } else {
                info.removeValue(forKey: MPNowPlayingInfoPropertyPlaybackProgress)
            }
            info[MPNowPlayingInfoPropertyIsLiveStream] = true
            if let externalContentID, !externalContentID.isEmpty {
                info[MPNowPlayingInfoPropertyExternalContentIdentifier] = externalContentID
            }
            if let assetURL { info[MPNowPlayingInfoPropertyAssetURL] = assetURL }
        }
        loadArtwork(for: sessionID, url: artworkURL)
        DebridNowShowingDirectPushManager.shared.publishLive(
            sessionID: sessionID,
            title: title,
            channelName: channelName,
            subtitle: subtitle,
            duration: safeDuration,
            elapsed: safeElapsed,
            externalContentID: externalContentID,
            artworkURL: artworkURL,
            isPlaying: isPlaying
        )
    }

    func releaseSession(_ sessionID: UUID) {
        lock.lock()
        guard ownerSessionID == sessionID else {
            lock.unlock()
            return
        }
        ownerSessionID = nil
        ownerIsLive = false
        ownerIsPlaying = false
        ownerContentKind = .movie
        ownerTimingElapsed = 0
        ownerTimingDuration = 0
        ownerTimingUptime = 0
        activationGeneration &+= 1
        artworkGeneration &+= 1
        activeArtworkURL = nil
        lastPublishedInfo = [:]
        lock.unlock()

        DebridNowShowingDirectPushManager.shared.release(sessionID: sessionID)

        let clear: () -> Void = {
            self.lock.lock()
            let stillUnowned = self.ownerSessionID == nil
            self.lock.unlock()
            guard stillUnowned else { return }

            self.stopHeartbeatOnMain()

            // vBRDC220 hard lifecycle boundary:
            // MPNowPlayingSession exposes becomeActiveIfPossible but no matching resign API.
            // Clearing metadata and deactivating AVAudioSession left the retained session and
            // its command center alive, so the second movie could see a stale in-process
            // `isActive` while Home Assistant/mediaremoted stayed Idle. Tear down every
            // transient session-scoped owner so the next playback creates a fresh AVPlayer +
            // MPNowPlayingSession and performs the exact first-launch claim sequence again.
            self.nowPlayingSession?.nowPlayingInfoCenter.nowPlayingInfo = nil
            MPNowPlayingInfoCenter.default().nowPlayingInfo = nil
            BluetoothVODMediaButtonCoordinator.shared.dropSessionScopedCommandCentersForPlaybackRelease()
            if let session = self.nowPlayingSession, let player = self.mediaAnchorPlayer {
                session.removePlayer(player)
            }

            self.nowPlayingSession = nil
            self.mediaAnchorLooper = nil
            self.mediaAnchorPlayer?.pause()
            self.mediaAnchorPlayer?.removeAllItems()
            self.mediaAnchorPlayer = nil
            self.defaultCenterFallbackActive = false
            self.requiresFreshSystemMediaClaim = true

            UserDefaults.standard.set("Idle", forKey: Self.systemSessionStatusDefaultsKey)
            UserDefaults.standard.set("Released — fresh claim required", forKey: Self.systemSessionLastClaimDefaultsKey)
            _ = try? AVAudioSession.sharedInstance().setActive(false, options: [.notifyOthersOnDeactivation])
        }
        if Thread.isMainThread { clear() } else { DispatchQueue.main.async(execute: clear) }
    }

    private func mutate(
        sessionID: UUID,
        reset: Bool,
        _ update: @escaping (inout [String: Any]) -> Void
    ) {
        let publish: () -> Void = {
            self.lock.lock()
            let isOwner = self.ownerSessionID == sessionID
            let shouldPlay = self.ownerIsPlaying
            let contentKind = self.ownerContentKind
            self.lock.unlock()
            guard isOwner else { return }

            self.lock.lock()
            var info: [String: Any] = reset ? [:] : self.lastPublishedInfo
            self.lock.unlock()
            update(&info)

            // vBRDC217: keep the broad Now Playing media type as video, but publish the
            // concrete movie/TV classification through MPMediaItemPropertyMediaType. The
            // old unconditional `.anyVideo` write erased the specific type set by VOD/Live
            // metadata immediately before publication.
            info[MPNowPlayingInfoPropertyMediaType] = NSNumber(value: MPNowPlayingInfoMediaType.video.rawValue)
            info[MPMediaItemPropertyMediaType] = NSNumber(value: contentKind.mediaItemType.rawValue)
            info[MPNowPlayingInfoPropertyPlaybackQueueCount] = 1
            info[MPNowPlayingInfoPropertyPlaybackQueueIndex] = 0
            info[MPNowPlayingInfoPropertyServiceIdentifier] = Bundle.main.bundleIdentifier ?? "Debrid Channels"

            self.lock.lock()
            guard self.ownerSessionID == sessionID else {
                self.lock.unlock()
                return
            }
            self.lastPublishedInfo = info
            self.lock.unlock()

            self.activateSystemMediaSession()
            self.publishSnapshotOnMain(info)
            self.synchronizeAnchorPlaybackOnMain(isPlaying: shouldPlay)
            self.ensureHeartbeatOnMain()
            self.requestSystemSessionActivationOnMain(reason: reset ? "new playback session" : "metadata/timing update")
        }
        if Thread.isMainThread { publish() } else { DispatchQueue.main.async(execute: publish) }
    }
}

/// Bridges system media-button events from Bluetooth headphones, keyboards/remotes,
/// and other accessory transports into the active full-screen media session. vBRDC211
/// registers on both the authoritative MPNowPlayingSession command center and the shared
/// compatibility center. Catalog previews/navigation never claim either route.
final class BluetoothVODMediaButtonCoordinator {
    static let shared = BluetoothVODMediaButtonCoordinator()

    private let lock = NSLock()
    private var installed = false
    private var activeSessionID: UUID?
    private var activeSessionIsLive = false
    private struct CommandRegistration {
        let center: MPRemoteCommandCenter
        let toggleTarget: Any
        let playTarget: Any
        let pauseTarget: Any
    }
    private var commandRegistrations: [CommandRegistration] = []
    private var lastExternalCommandAt: TimeInterval = 0
    private var lastExternalCommand: BluetoothVODMediaCommand?
    private var lastSwiftUIPlayPauseAt: TimeInterval = 0
    private var lastNowPlayingElapsed: Double = -1
    private var lastNowPlayingIsPlaying: Bool?
    // vBRDC121: retain the latest authoritative VOD Now Playing snapshot so tvOS media
    // ownership can be reasserted after Bluetooth route changes, audio interruptions,
    // media-service resets, or app reactivation without polling the player.
    private var activeTitle: String = ""
    private var activeDuration: Double = 0
    private var activeElapsed: Double = 0
    private var activeIsPlaying: Bool = true
    private var systemObserverTokens: [NSObjectProtocol] = []

    private init() {}

    func installIfNeeded() {
        if installed {
            // vBRDC220: the shared command center is process-lifetime, but the
            // MPNowPlayingSession command center is playback-lifetime. Reconcile targets on
            // every new claim so a freshly-created session never inherits registrations that
            // still point at the released session.
            refreshCommandCenterRegistrations()
            syncAvailability()
            return
        }
        installed = true
        refreshCommandCenterRegistrations()
        installSystemOwnershipObserversIfNeeded()
        syncAvailability()
    }

    private func addCommandRegistration(on center: MPRemoteCommandCenter) -> CommandRegistration {
        let toggle = center.togglePlayPauseCommand.addTarget { [weak self] _ in
            self?.receive(.toggle) ?? .commandFailed
        }
        let play = center.playCommand.addTarget { [weak self] _ in
            self?.receive(.play) ?? .commandFailed
        }
        let pause = center.pauseCommand.addTarget { [weak self] _ in
            self?.receive(.pause) ?? .commandFailed
        }
        return CommandRegistration(center: center, toggleTarget: toggle, playTarget: play, pauseTarget: pause)
    }

    private func removeCommandRegistration(_ registration: CommandRegistration) {
        registration.center.togglePlayPauseCommand.removeTarget(registration.toggleTarget)
        registration.center.playCommand.removeTarget(registration.playTarget)
        registration.center.pauseCommand.removeTarget(registration.pauseTarget)
    }

    private func refreshCommandCenterRegistrations() {
        let apply = {
            let desiredCenters = DebridNowPlayingManager.shared.remoteCommandCenters()

            self.lock.lock()
            let existing = self.commandRegistrations
            self.lock.unlock()

            var existingByID: [ObjectIdentifier: CommandRegistration] = [:]
            for registration in existing {
                existingByID[ObjectIdentifier(registration.center)] = registration
            }

            var refreshed: [CommandRegistration] = []
            refreshed.reserveCapacity(desiredCenters.count)
            var desiredIDs = Set<ObjectIdentifier>()
            for center in desiredCenters {
                let id = ObjectIdentifier(center)
                desiredIDs.insert(id)
                if let registration = existingByID[id] {
                    refreshed.append(registration)
                } else {
                    refreshed.append(self.addCommandRegistration(on: center))
                }
            }

            for registration in existing where !desiredIDs.contains(ObjectIdentifier(registration.center)) {
                self.removeCommandRegistration(registration)
            }

            self.lock.lock()
            self.commandRegistrations = refreshed
            self.lock.unlock()
        }
        if Thread.isMainThread { apply() } else { DispatchQueue.main.sync(execute: apply) }
    }

    /// vBRDC220: release only the command targets tied to a transient MPNowPlayingSession.
    /// The shared center is deliberately retained because it is the hardware-proven
    /// Bluetooth route and must survive movie -> Idle -> movie cycles.
    func dropSessionScopedCommandCentersForPlaybackRelease() {
        let apply = {
            let sharedID = ObjectIdentifier(MPRemoteCommandCenter.shared())
            self.lock.lock()
            let registrations = self.commandRegistrations
            let kept = registrations.filter { ObjectIdentifier($0.center) == sharedID }
            self.commandRegistrations = kept
            self.lock.unlock()

            for registration in registrations where ObjectIdentifier(registration.center) != sharedID {
                self.removeCommandRegistration(registration)
            }
        }
        if Thread.isMainThread { apply() } else { DispatchQueue.main.sync(execute: apply) }
    }

    /// vBRDC217: if tvOS refuses the synthetic MPNowPlayingSession, release its secondary
    /// command-center registration so that session can fully deallocate and the standard
    /// default Now Playing center can become authoritative. The shared command center remains
    /// installed; that is the route proven by vBRDC214-vBRDC216 Bluetooth hardware testing.
    func retainSharedCommandCenterOnlyForDefaultNowPlayingFallback() {
        dropSessionScopedCommandCentersForPlaybackRelease()
    }

    /// vBRDC117: a custom KS/VOD surface must explicitly become tvOS's Now Playing app
    /// so Bluetooth/headset media transport buttons are routed to MPRemoteCommandCenter.
    /// Registration alone is not sufficient for a custom player.
    func claimVODSession(
        _ sessionID: UUID,
        title: String,
        duration: Double,
        elapsed: Double,
        isPlaying: Bool
    ) {
        installIfNeeded()
        lock.lock()
        activeSessionID = sessionID
        activeSessionIsLive = false
        lastExternalCommandAt = 0
        lastExternalCommand = nil
        lastNowPlayingElapsed = -1
        lastNowPlayingIsPlaying = nil
        activeTitle = title
        activeDuration = duration.isFinite ? max(0, duration) : 0
        activeElapsed = elapsed.isFinite ? max(0, elapsed) : 0
        activeIsPlaying = isPlaying
        lock.unlock()
        UserDefaults.standard.set("None", forKey: DebridNowPlayingManager.systemMediaRemoteLastEventDefaultsKey)

        // vBRDC211: enable session-scoped and compatibility commands BEFORE activating the non-mixable
        // playback audio session. Apple describes those two conditions together as the
        // moment a custom player becomes eligible to be the system Now Playing app.
        syncAvailability()
        activateVODAudioSession()
        // Re-apply after activation too. Some tvOS media-service transitions can rebuild
        // command availability while the audio session is being claimed; this keeps the
        // handler targets enabled on both sides of the ownership transition.
        syncAvailability()
        DebridNowPlayingManager.shared.claimVODSession(
            sessionID,
            title: title,
            duration: duration,
            elapsed: elapsed,
            isPlaying: isPlaying
        )
        updateNowPlaying(
            sessionID: sessionID,
            title: title,
            duration: duration,
            elapsed: elapsed,
            isPlaying: isPlaying,
            force: true
        )
    }

    /// vBRDC211: Live TV is also a real system media session. Keeping remote commands
    /// disabled for Live TV prevented Debrid Channels from satisfying tvOS Now Playing
    /// eligibility even though metadata was being published.
    func claimLiveControlSession(_ sessionID: UUID, title: String) {
        installIfNeeded()
        lock.lock()
        activeSessionID = sessionID
        activeSessionIsLive = true
        lastExternalCommandAt = 0
        lastExternalCommand = nil
        lastNowPlayingElapsed = -1
        lastNowPlayingIsPlaying = nil
        activeTitle = title
        activeDuration = 0
        activeElapsed = 0
        activeIsPlaying = true
        lock.unlock()
        UserDefaults.standard.set("None", forKey: DebridNowPlayingManager.systemMediaRemoteLastEventDefaultsKey)
        // vBRDC211: command eligibility must exist before Live TV starts/activates audio,
        // otherwise tvOS can keep the app outside MediaRemote even though metadata arrives.
        syncAvailability()
        activateVODAudioSession()
        syncAvailability()
    }

    func releaseVODSession(_ sessionID: UUID) {
        lock.lock()
        if activeSessionID == sessionID {
            activeSessionID = nil
            activeSessionIsLive = false
            lastNowPlayingElapsed = -1
            lastNowPlayingIsPlaying = nil
            activeTitle = ""
            activeDuration = 0
            activeElapsed = 0
            activeIsPlaying = true
        }
        lock.unlock()

        // vBRDC206: Now Playing ownership is process-wide and may also belong to Live TV.
        // Always release this exact presentation from the central publisher; the publisher
        // ignores stale IDs so a departing VOD can never clear a newer episode/channel.
        DebridNowPlayingManager.shared.releaseSession(sessionID)
        // vBRDC208: DebridNowPlayingManager owns process-wide audio/MediaRemote lifetime.
        // A VOD release must not deactivate the session underneath a newly claimed Live TV owner.
        syncAvailability()
    }

    func updateNowPlaying(
        sessionID: UUID,
        title: String,
        duration: Double,
        elapsed: Double,
        isPlaying: Bool,
        force: Bool = false
    ) {
        let safeElapsed = elapsed.isFinite ? max(0, elapsed) : 0
        let safeDuration = duration.isFinite ? max(0, duration) : 0

        lock.lock()
        guard activeSessionID == sessionID else {
            lock.unlock()
            return
        }
        activeTitle = title
        activeDuration = safeDuration
        activeElapsed = safeElapsed
        activeIsPlaying = isPlaying
        let stateChanged = lastNowPlayingIsPlaying != isPlaying
        let elapsedChangedEnough = lastNowPlayingElapsed < 0 || abs(safeElapsed - lastNowPlayingElapsed) >= 5.0
        guard force || stateChanged || elapsedChangedEnough else {
            lock.unlock()
            return
        }
        lastNowPlayingElapsed = safeElapsed
        lastNowPlayingIsPlaying = isPlaying
        lock.unlock()

        DebridNowPlayingManager.shared.updateVODTiming(
            sessionID: sessionID,
            title: title,
            duration: safeDuration,
            elapsed: safeElapsed,
            isPlaying: isPlaying
        )
    }

    /// Restore tvOS media ownership after a system/audio lifecycle edge.
    /// This is event-driven only: no timer or polling; vBRDC211 covers both VOD and Live TV.
    func reassertActiveVODOwnership(reason: String) {
        // vBRDC327: MPNowPlayingSession is playback-lifetime. tvOS can rebuild/revoke its
        // command center across app switcher, Bluetooth route and media-service lifecycle.
        // Reconcile targets before reasserting ownership so Pause/Play never points at a
        // released command center.
        refreshCommandCenterRegistrations()
        // vBRDC208: the observer is installed process-wide, so use it to recover either
        // a VOD or Live TV MediaRemote publication after tvOS media-service lifecycle edges.
        DebridNowPlayingManager.shared.reassertCurrentSession(reason: reason)
        lock.lock()
        let sessionID = activeSessionID
        let sessionIsLive = activeSessionIsLive
        let title = activeTitle
        let duration = activeDuration
        let elapsed = activeElapsed
        let isPlaying = activeIsPlaying
        lock.unlock()

        guard let sessionID else {
            syncAvailability()
            return
        }

        activateVODAudioSession()
        if !sessionIsLive {
            updateNowPlaying(
                sessionID: sessionID,
                title: title,
                duration: duration,
                elapsed: elapsed,
                isPlaying: isPlaying,
                force: true
            )
        }
        syncAvailability()
        #if DEBUG
        print("[BluetoothVOD][vBRDC121] Reasserted VOD media ownership: \(reason)")
        #endif
    }

    private func installSystemOwnershipObserversIfNeeded() {
        guard systemObserverTokens.isEmpty else { return }
        let notifications = NotificationCenter.default

        systemObserverTokens.append(
            notifications.addObserver(forName: UIApplication.didBecomeActiveNotification, object: nil, queue: .main) { [weak self] _ in
                self?.reassertActiveVODOwnership(reason: "app became active")
            }
        )
        systemObserverTokens.append(
            notifications.addObserver(forName: AVAudioSession.routeChangeNotification, object: nil, queue: .main) { [weak self] _ in
                // Route changes include Bluetooth connect/disconnect. Reassert on the next
                // MainActor turn so AVAudioSession has committed the new route first.
                DispatchQueue.main.async {
                    self?.reassertActiveVODOwnership(reason: "audio route changed")
                }
            }
        )
        systemObserverTokens.append(
            notifications.addObserver(forName: AVAudioSession.interruptionNotification, object: nil, queue: .main) { [weak self] note in
                guard let raw = note.userInfo?[AVAudioSessionInterruptionTypeKey] as? UInt,
                      AVAudioSession.InterruptionType(rawValue: raw) == .ended else { return }
                self?.reassertActiveVODOwnership(reason: "audio interruption ended")
            }
        )
        systemObserverTokens.append(
            notifications.addObserver(forName: AVAudioSession.mediaServicesWereResetNotification, object: nil, queue: .main) { [weak self] _ in
                self?.reassertActiveVODOwnership(reason: "media services reset")
            }
        )
    }

    /// De-duplicates accessories that surface the same physical press through both
    /// MPRemoteCommandCenter and SwiftUI's onPlayPauseCommand. Whichever arrives first
    /// owns that press; the second delivery is ignored for 180 ms.
    func shouldSuppressSwiftUIPlayPause() -> Bool {
        let now = ProcessInfo.processInfo.systemUptime
        lock.lock()
        let suppress = (now - lastExternalCommandAt) < 0.18
        if !suppress { lastSwiftUIPlayPauseAt = now }
        lock.unlock()
        return suppress
    }

    private func receive(_ command: BluetoothVODMediaCommand) -> MPRemoteCommandHandlerStatus {
        let now = ProcessInfo.processInfo.systemUptime
        lock.lock()
        let sessionID = activeSessionID
        let duplicateOfSwiftUI = (now - lastSwiftUIPlayPauseAt) < 0.18
        // vBRDC211: the same physical accessory press can be surfaced by both the
        // MPNowPlayingSession center and the process-wide compatibility center. Treat a
        // callback inside 180 ms as one physical press so Play/Pause can never double-toggle.
        let duplicateExternalRoute = (now - lastExternalCommandAt) < 0.18
        if sessionID != nil && !duplicateOfSwiftUI && !duplicateExternalRoute {
            lastExternalCommandAt = now
            lastExternalCommand = command
        }
        lock.unlock()

        guard let sessionID else {
            return .commandFailed
        }
        guard !duplicateOfSwiftUI, !duplicateExternalRoute else { return .success }

        UserDefaults.standard.set("\(command.rawValue.capitalized) received", forKey: DebridNowPlayingManager.systemMediaRemoteLastEventDefaultsKey)
        DispatchQueue.main.async {
            NotificationCenter.default.post(
                name: .debridBluetoothVODMediaCommand,
                object: nil,
                userInfo: [
                    "sessionID": sessionID,
                    "command": command.rawValue
                ]
            )
        }
        return .success
    }

    private func activateVODAudioSession() {
        let activate = {
            let session = AVAudioSession.sharedInstance()
            do {
                try session.setCategory(.playback, mode: .moviePlayback, options: [])
                try session.setActive(true)
                UIApplication.shared.beginReceivingRemoteControlEvents()
            } catch {
                print("[BluetoothVOD][vBRDC211] Unable to activate Now Playing audio session: \(error.localizedDescription)")
            }
        }
        if Thread.isMainThread { activate() } else { DispatchQueue.main.async(execute: activate) }
    }

    private func syncAvailability() {
        lock.lock()
        let available = activeSessionID != nil
        let registrations = commandRegistrations
        lock.unlock()

        let apply = {
            for registration in registrations {
                registration.center.togglePlayPauseCommand.isEnabled = available
                registration.center.playCommand.isEnabled = available
                registration.center.pauseCommand.isEnabled = available
            }
        }
        if Thread.isMainThread { apply() } else { DispatchQueue.main.async(execute: apply) }
    }
}


final class DebridChannelsAppDelegate: NSObject, UIApplicationDelegate, UNUserNotificationCenterDelegate {
    func application(_ application: UIApplication, didFinishLaunchingWithOptions launchOptions: [UIApplication.LaunchOptionsKey : Any]? = nil) -> Bool {
        UNUserNotificationCenter.current().delegate = self
        UNUserNotificationCenter.current().requestAuthorization(options: [.alert, .sound, .badge]) { _, _ in }
        // v981: invalidate any cached static Top Shelf result after an updated app
        // install so tvOS asks the embedded TVServices extension for poster content.
        #if os(tvOS)
        TVTopShelfContentProvider.topShelfContentDidChange()
        #endif
        // vBRDC135: Bluetooth/headset transport controls are an invisible VOD capability,
        // not a user preference. Clear the retired key so an old saved Off value can never
        // suppress media-button ownership after an upgrade.
        UserDefaults.standard.removeObject(forKey: "bluetoothVODPlayPauseEnabledV1")
        // vBRDC211: configure the media category and build the MPNowPlayingSession command route at process start,
        // while deferring audio activation until actual playback. This keeps
        // Now Playing/Bluetooth eligibility deterministic from the first session.
        try? AVAudioSession.sharedInstance().setCategory(.playback, mode: .moviePlayback, options: [])
        UIApplication.shared.beginReceivingRemoteControlEvents()
        BluetoothVODMediaButtonCoordinator.shared.installIfNeeded()
        return true
    }

    func userNotificationCenter(_ center: UNUserNotificationCenter, willPresent notification: UNNotification, withCompletionHandler completionHandler: @escaping (UNNotificationPresentationOptions) -> Void) {
        completionHandler([.banner, .sound])
    }
}

