struct SilentVideoBackground: UIViewControllerRepresentable {
    let url: URL
    var isMuted: Bool = true

    final class Coordinator {
        var player: AVPlayer?
        var endObserver: NSObjectProtocol?

        func configure(url: URL, isMuted: Bool, controller: AVPlayerViewController) {
            if let current = player?.currentItem?.asset as? AVURLAsset, current.url == url {
                player?.isMuted = isMuted
                player?.volume = isMuted ? 0.0 : 1.0
                controller.player = player
                controller.showsPlaybackControls = false
                controller.videoGravity = .resizeAspectFill
                player?.play()
                return
            }

            cleanup()

            let item = AVPlayerItem(url: url)
            let nextPlayer = AVPlayer(playerItem: item)
            nextPlayer.isMuted = isMuted
            nextPlayer.volume = isMuted ? 0.0 : 1.0
            item.preferredForwardBufferDuration = isMuted ? 0.0 : 1.0
            controller.player = nextPlayer
            controller.showsPlaybackControls = false
            controller.videoGravity = .resizeAspectFill
            endObserver = NotificationCenter.default.addObserver(
                forName: .AVPlayerItemDidPlayToEndTime,
                object: item,
                queue: .main
            ) { [weak nextPlayer] _ in
                nextPlayer?.seek(to: .zero)
                nextPlayer?.play()
            }
            player = nextPlayer
            nextPlayer.play()
        }

        func cleanup() {
            if let endObserver {
                NotificationCenter.default.removeObserver(endObserver)
                self.endObserver = nil
            }
            player?.pause()
            player?.replaceCurrentItem(with: nil)
            player = nil
        }
    }

    func makeCoordinator() -> Coordinator { Coordinator() }

    func makeUIViewController(context: Context) -> AVPlayerViewController {
        let controller = AVPlayerViewController()
        controller.showsPlaybackControls = false
        controller.videoGravity = .resizeAspectFill
        context.coordinator.configure(url: url, isMuted: isMuted, controller: controller)
        return controller
    }

    func updateUIViewController(_ controller: AVPlayerViewController, context: Context) {
        context.coordinator.configure(url: url, isMuted: isMuted, controller: controller)
    }

    static func dismantleUIViewController(_ controller: AVPlayerViewController, coordinator: Coordinator) {
        coordinator.cleanup()
        controller.player = nil
    }
}

@MainActor
private func waitForAuxiliaryVideoHandoffIfNeeded(reason: String) async {
    let released = AuxiliaryVideoPlaybackCoordinator.shared.releaseAll(reason: reason)
    guard released || AuxiliaryVideoPlaybackCoordinator.shared.requiresDecoderHandoffCooldown() else { return }
    try? await Task.sleep(nanoseconds: 400_000_000)
}

private extension Notification.Name {
    static let debridTrailerExclusivePlaybackDidBegin = Notification.Name("DebridChannels.TrailerExclusivePlaybackDidBegin")
    static let debridTrailerExclusivePlaybackDidEnd = Notification.Name("DebridChannels.TrailerExclusivePlaybackDidEnd")
}

@MainActor
private func beginTrailerExclusivePlayback(reason: String) -> UUID {
    let identifier = AuxiliaryVideoPlaybackCoordinator.shared.beginExclusivePlayback(reason: reason)
    NotificationCenter.default.post(name: .debridTrailerExclusivePlaybackDidBegin, object: nil)
    return identifier
}

@MainActor
private func endTrailerExclusivePlayback(_ identifier: UUID?) {
    guard let identifier else { return }
    AuxiliaryVideoPlaybackCoordinator.shared.endExclusivePlayback(identifier)
    // Let the full-trailer decoder/player unwind before the catalog is allowed to recreate
    // its muted preview. The coordinator keeps the auxiliary lane suppressed for this handoff.
    DispatchQueue.main.asyncAfter(deadline: .now() + 0.40) {
        NotificationCenter.default.post(name: .debridTrailerExclusivePlaybackDidEnd, object: nil)
    }
}

private struct AuxiliaryVideoActivityModifier: ViewModifier {
    let active: Bool
    @State private var registrationID: UUID? = nil

    func body(content: Content) -> some View {
        content
            .onAppear { synchronizeRegistration() }
            .onChange(of: active) { _ in synchronizeRegistration() }
            .onDisappear { releaseRegistration() }
    }

    private func synchronizeRegistration() {
        if active {
            if registrationID == nil {
                registrationID = AuxiliaryVideoPlaybackCoordinator.shared.beginTransientSurface()
            }
        } else {
            releaseRegistration()
        }
    }

    private func releaseRegistration() {
        AuxiliaryVideoPlaybackCoordinator.shared.endTransientSurface(registrationID)
        registrationID = nil
    }
}

private extension View {
    func marksAuxiliaryVideoActivity(_ active: Bool) -> some View {
        modifier(AuxiliaryVideoActivityModifier(active: active))
    }
}

// v1011 Phase 4C / vBRDC107: a dedicated, muted player used only for the settled
// focused catalog identity. It never reuses the main VOD, trailer, episode, or Live TV
// player. vBRDC116 bounds each focused identity to one 35-second muted preview session.
private final class FocusedCardPreviewPlayerView: UIView {
    override class var layerClass: AnyClass { AVPlayerLayer.self }

    var playerLayer: AVPlayerLayer {
        guard let playerLayer = layer as? AVPlayerLayer else {
            fatalError("FocusedCardPreviewPlayerView requires AVPlayerLayer")
        }
        return playerLayer
    }
}

private final class SignalCatalogPreviewPlayerPool {
    static let shared = SignalCatalogPreviewPlayerPool()

    private let player = AVPlayer()
    private var currentURL: URL?
    private var currentOwner: UUID?
    private weak var currentLayer: AVPlayerLayer?
    private var boundaryObserver: Any?
    private var endObserver: NSObjectProtocol?
    private var timeControlObservation: NSKeyValueObservation?
    private var itemStatusObservation: NSKeyValueObservation?
    private var auxiliaryReleaseRegistrationID: UUID?
    private var didFinish = false
    private var didPublishPlaybackStarted = false
    private var onPlaybackStarted: (() -> Void)?
    private var onPlaybackStopped: (() -> Void)?
    private var onFinished: (() -> Void)?

    private init() {
        player.appliesMediaSelectionCriteriaAutomatically = false
        player.isMuted = true
        player.volume = 0
        player.automaticallyWaitsToMinimizeStalling = true
    }

    func attach(
        owner: UUID,
        url: URL,
        layer: AVPlayerLayer,
        onPlaybackStarted: @escaping () -> Void,
        onPlaybackStopped: @escaping () -> Void,
        onFinished: @escaping () -> Void
    ) {
        dispatchPrecondition(condition: .onQueue(.main))
        layer.videoGravity = .resizeAspectFill

        guard !AuxiliaryVideoPlaybackCoordinator.shared.isAuxiliaryPlaybackSuppressed() else {
            if currentOwner == owner { release(owner: owner) }
            layer.player = nil
            return
        }

        self.onPlaybackStarted = onPlaybackStarted
        self.onPlaybackStopped = onPlaybackStopped
        self.onFinished = onFinished

        // Nuvio-style ownership: keep one AVPlayer/AVPlayerLayer decoder lane alive and
        // replace only its item after settled focus. Never construct a new player per card.
        if currentOwner == owner, currentURL == url, player.currentItem != nil {
            currentLayer = layer
            layer.player = player
            if !didFinish { player.play() }
            return
        }

        teardownCurrentItem(publishStopped: currentOwner != nil)
        currentOwner = owner
        currentURL = url
        currentLayer = layer
        didFinish = false
        didPublishPlaybackStarted = false

        let asset = AVURLAsset(url: url)
        let item = AVPlayerItem(asset: asset)
        item.preferredPeakBitRate = 0
        item.preferredForwardBufferDuration = 1.5
        if #available(tvOS 11.0, *) {
            item.preferredMaximumResolution = CGSize(width: 1280, height: 720)
        }

        player.replaceCurrentItem(with: item)
        player.isMuted = true
        player.volume = 0
        layer.player = player

        itemStatusObservation = item.observe(\.status, options: [.initial, .new]) { item, _ in
            guard item.status == .readyToPlay else { return }
            Task { @MainActor in
                if let audibleGroup = try? await item.asset.loadMediaSelectionGroup(for: .audible) {
                    item.select(nil, in: audibleGroup)
                }
            }
        }
        timeControlObservation = player.observe(\.timeControlStatus, options: [.initial, .new]) { [weak self] player, _ in
            guard player.timeControlStatus == .playing else { return }
            DispatchQueue.main.async { self?.publishPlaybackStartedOnce() }
        }
        auxiliaryReleaseRegistrationID = AuxiliaryVideoPlaybackCoordinator.shared.registerReleaseHandler { [weak self] in
            DispatchQueue.main.async { self?.releaseAll() }
        }

        let previewBoundary = CMTime(seconds: 35.0, preferredTimescale: 600)
        boundaryObserver = player.addBoundaryTimeObserver(
            forTimes: [NSValue(time: previewBoundary)],
            queue: .main
        ) { [weak self] in
            self?.finishCurrentPreview(reason: "35-second cap")
        }
        endObserver = NotificationCenter.default.addObserver(
            forName: .AVPlayerItemDidPlayToEndTime,
            object: item,
            queue: .main
        ) { [weak self] _ in
            self?.finishCurrentPreview(reason: "asset ended")
        }
        player.play()
    }

    func release(owner: UUID) {
        dispatchPrecondition(condition: .onQueue(.main))
        guard currentOwner == owner else { return }
        teardownCurrentItem(publishStopped: true)
        currentLayer?.player = nil
        currentLayer = nil
        currentOwner = nil
        currentURL = nil
        onPlaybackStarted = nil
        onPlaybackStopped = nil
        onFinished = nil
    }

    func releaseAll() {
        dispatchPrecondition(condition: .onQueue(.main))
        teardownCurrentItem(publishStopped: currentOwner != nil)
        currentLayer?.player = nil
        currentLayer = nil
        currentOwner = nil
        currentURL = nil
        onPlaybackStarted = nil
        onPlaybackStopped = nil
        onFinished = nil
    }

    private func publishPlaybackStartedOnce() {
        guard !didPublishPlaybackStarted else { return }
        didPublishPlaybackStarted = true
        onPlaybackStarted?()
    }

    private func finishCurrentPreview(reason: String) {
        guard !didFinish else { return }
        didFinish = true
        player.pause()
        // Phase 3: the preview has no reason to keep its decoder/compositor item alive
        // after the 35-second cap. Keep the single AVPlayer object pooled, but release the
        // AVPlayerItem immediately so system overlays and catalog scrolling stop competing
        // with a dormant video decode surface.
        player.replaceCurrentItem(with: nil)
        currentLayer?.player = nil
        onPlaybackStopped?()
        print("[FocusedCardPreview][vBRDC327] finished reason=\(reason) cap=35s decoderReleased=true")
        onFinished?()
    }

    private func teardownCurrentItem(publishStopped: Bool) {
        AuxiliaryVideoPlaybackCoordinator.shared.unregisterReleaseHandler(auxiliaryReleaseRegistrationID)
        auxiliaryReleaseRegistrationID = nil
        if let boundaryObserver {
            player.removeTimeObserver(boundaryObserver)
        }
        boundaryObserver = nil
        if let endObserver { NotificationCenter.default.removeObserver(endObserver) }
        endObserver = nil
        timeControlObservation?.invalidate()
        timeControlObservation = nil
        itemStatusObservation?.invalidate()
        itemStatusObservation = nil
        player.pause()
        if publishStopped { onPlaybackStopped?() }
        player.replaceCurrentItem(with: nil)
        didFinish = false
        didPublishPlaybackStarted = false
    }
}

private struct FocusedCardPreviewSurface: UIViewRepresentable {
    let url: URL
    let onPlaybackStarted: () -> Void
    let onPlaybackStopped: () -> Void
    let onFinished: () -> Void

    final class Coordinator {
        let owner = UUID()
    }

    func makeCoordinator() -> Coordinator { Coordinator() }

    func makeUIView(context: Context) -> FocusedCardPreviewPlayerView {
        let view = FocusedCardPreviewPlayerView()
        view.backgroundColor = .black
        SignalCatalogPreviewPlayerPool.shared.attach(
            owner: context.coordinator.owner,
            url: url,
            layer: view.playerLayer,
            onPlaybackStarted: onPlaybackStarted,
            onPlaybackStopped: onPlaybackStopped,
            onFinished: onFinished
        )
        return view
    }

    func updateUIView(_ uiView: FocusedCardPreviewPlayerView, context: Context) {
        SignalCatalogPreviewPlayerPool.shared.attach(
            owner: context.coordinator.owner,
            url: url,
            layer: uiView.playerLayer,
            onPlaybackStarted: onPlaybackStarted,
            onPlaybackStopped: onPlaybackStopped,
            onFinished: onFinished
        )
    }

    static func dismantleUIView(_ uiView: FocusedCardPreviewPlayerView, coordinator: Coordinator) {
        SignalCatalogPreviewPlayerPool.shared.release(owner: coordinator.owner)
        uiView.playerLayer.player = nil
    }
}


private enum MembershipBootstrapV584 {
    static let buildKey = "v584_24_hour_membership_trial"
    static let bootstrapKey = "membershipBootstrapBuild"
    static let trialExpiresKey = "membershipTrialExpiresAt"
    static let trialStartedKey = "membershipTrialStartedAt"
    static let trialConsumedKey = "membershipTrialConsumed"
    static let activeKey = "membershipActive"

    static func auditAndBootstrapFreshTrialIfNeeded() {
        // v650: Backend entitlement is the source of truth. This method is retained
        // for older call sites, but it must never create or extend a local trial.
        UserDefaults.standard.set(buildKey, forKey: bootstrapKey)
    }

    static func markExpiredIfNeeded(now: Date = Date()) {
        let defaults = UserDefaults.standard
        guard !defaults.bool(forKey: activeKey),
              let raw = defaults.string(forKey: trialExpiresKey),
              let expires = ISO8601DateFormatter().date(from: raw),
              now >= expires else { return }
        defaults.set(true, forKey: trialConsumedKey)
    }
}

enum ProductionEntitlementStatus: String {
    case unknown
    case trialActive = "trial_active"
    case trialExpired = "trial_expired"
    case paidActive = "paid_active"
    case adminActive = "admin_active"
    case locked

    init(rawBackendValue: String?) {
        switch rawBackendValue?.lowercased() {
        case "trial_active", "trial": self = .trialActive
        case "trial_expired", "expired": self = .trialExpired
        case "paid_active", "active", "supporter", "lifetime": self = .paidActive
        case "admin_active", "admin": self = .adminActive
        case "locked": self = .locked
        default: self = .unknown
        }
    }
}

struct ProductionEntitlementResult {
    let status: ProductionEntitlementStatus
    let trialStartedAt: String?
    let trialExpiresAt: String?
    let planType: String?
}

enum StableDeviceIdentity {
    private static let service = "com.debridchannels.tvos"
    private static let account = "production-device-id"
    private static let defaultsKey = "DebridChannelsDeviceId"

    static func deviceId() -> String {
        if let value = readKeychainValue(), !value.isEmpty {
            UserDefaults.standard.set(value, forKey: defaultsKey)
            return value
        }
        if let value = UserDefaults.standard.string(forKey: defaultsKey), !value.isEmpty {
            writeKeychainValue(value)
            return value
        }
        let value = UUID().uuidString
        writeKeychainValue(value)
        UserDefaults.standard.set(value, forKey: defaultsKey)
        return value
    }

    private static func readKeychainValue() -> String? {
        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: account,
            kSecReturnData as String: true,
            kSecMatchLimit as String: kSecMatchLimitOne
        ]
        var item: CFTypeRef?
        guard SecItemCopyMatching(query as CFDictionary, &item) == errSecSuccess,
              let data = item as? Data else { return nil }
        return String(data: data, encoding: .utf8)
    }

    private static func writeKeychainValue(_ value: String) {
        let data = Data(value.utf8)
        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: account
        ]
        let attributes: [String: Any] = [kSecValueData as String: data]
        if SecItemUpdate(query as CFDictionary, attributes as CFDictionary) != errSecSuccess {
            var add = query
            add[kSecValueData as String] = data
            add[kSecAttrAccessible as String] = kSecAttrAccessibleAfterFirstUnlock
            SecItemAdd(add as CFDictionary, nil)
        }
    }
}

enum ProductionEntitlementService {
    static func fetchStatus(backendBaseURL: URL, deviceId: String, deviceName: String, email: String? = nil) async throws -> ProductionEntitlementResult {
        let url = backendBaseURL.appendingPathComponent("membership/entitlement/check")
        var payload: [String: Any] = [
            "deviceId": deviceId,
            "deviceName": deviceName,
            "platform": "tvOS",
            "appVersion": "v650"
        ]
        if let email, !email.isEmpty { payload["email"] = email }
        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        request.httpBody = try JSONSerialization.data(withJSONObject: payload)
        let (data, _) = try await URLSession.shared.data(for: request)
        let json = (try? JSONSerialization.jsonObject(with: data)) as? [String: Any]
        let entitlement = json?["entitlement"] as? [String: Any]
        let statusRaw = (entitlement?["entitlementStatus"] as? String)
            ?? (json?["entitlementStatus"] as? String)
            ?? (entitlement?["status"] as? String)
            ?? (json?["status"] as? String)
        let active = (entitlement?["active"] as? Bool) ?? (json?["active"] as? Bool) ?? false
        let tier = (entitlement?["planType"] as? String)
            ?? (json?["planType"] as? String)
            ?? (entitlement?["tier"] as? String)
            ?? (json?["tier"] as? String)
        var status = ProductionEntitlementStatus(rawBackendValue: statusRaw)
        if status == .unknown, active == true {
            let lowerTier = tier?.lowercased() ?? ""
            status = (lowerTier == "trial_24" || lowerTier == "trial") ? .trialActive : (lowerTier == "admin" ? .adminActive : .paidActive)
        }
        if status == .unknown, active == false {
            status = .locked
        }
        return ProductionEntitlementResult(
            status: status,
            trialStartedAt: (entitlement?["trialStartedAt"] as? String) ?? (json?["trialStartedAt"] as? String),
            trialExpiresAt: (entitlement?["trialExpiresAt"] as? String) ?? (json?["trialExpiresAt"] as? String) ?? (entitlement?["expiresAt"] as? String),
            planType: tier
        )
    }
}

private struct MediaFlowConnectionStatusBanner: View {
    @ObservedObject var monitor: MediaFlowConnectionMonitor

    private var iconName: String {
        switch monitor.phase {
        case .disabled: return "network.slash"
        case .checking: return "arrow.triangle.2.circlepath"
        case .connected: return "checkmark.shield.fill"
        case .failed: return "exclamationmark.shield.fill"
        }
    }

    private var accent: Color {
        switch monitor.phase {
        case .disabled: return .gray
        case .checking: return .orange
        case .connected: return .green
        case .failed: return .red
        }
    }

    private var title: String {
        switch monitor.phase {
        case .disabled: return "MediaFlow Proxy Off"
        case .checking: return "Checking MediaFlow Proxy"
        case .connected: return "MediaFlow Connected"
        case .failed: return "MediaFlow Connection Required"
        }
    }

    private var detail: String {
        switch monitor.phase {
        case .connected:
            return monitor.detectedIP.isEmpty ? "Home proxy verified" : "Streaming As  \(monitor.detectedIP)"
        case .failed:
            return "Playback is protected from direct-IP fallback • \(monitor.statusText)"
        case .checking:
            return "Verifying home proxy and outbound IP before media use"
        case .disabled:
            return monitor.statusText
        }
    }

    var body: some View {
        HStack(spacing: 12) {
            Image(systemName: iconName)
                .font(.system(size: 22, weight: .black))
                .foregroundStyle(accent)
            VStack(alignment: .leading, spacing: 2) {
                Text(title)
                    .font(.system(size: 16, weight: .black, design: .rounded))
                    .foregroundStyle(.white)
                Text(detail)
                    .font(.system(size: 12, weight: .bold, design: .rounded))
                    .foregroundStyle(.white.opacity(0.68))
                    .lineLimit(2)
            }
        }
        .padding(.horizontal, 18)
        .padding(.vertical, 11)
        .frame(maxWidth: 760, alignment: .leading)
        .background(
            RoundedRectangle(cornerRadius: 18, style: .continuous)
                .fill(Color.black.opacity(0.88))
        )
        .overlay(
            RoundedRectangle(cornerRadius: 18, style: .continuous)
                .stroke(accent.opacity(0.82), lineWidth: 1.5)
        )
        .shadow(radius: 18)
        .allowsHitTesting(false)
    }
}


// vBRDC134: non-visual asynchronous owners live outside SwiftUI presentation state.
// Assigning/cancelling a Task or observer has no visual meaning and must not invalidate
// Root, catalog, Live TV, or VOD view trees during navigation/playback.
private final class RootAsyncTaskRuntime: ObservableObject {
    var nextQueuedNewEpisodeAlertTask: Task<Void, Never>?
    var newEpisodeHeartbeatTask: Task<Void, Never>?
    var activeNewEpisodeAlertDismissTask: Task<Void, Never>?
    var membershipClockTask: Task<Void, Never>?
    var appBootstrapTask: Task<Void, Never>?
    var entitlementSyncTask: Task<Void, Never>?
    var newEpisodeScannerVerificationTask: Task<Void, Never>?
    var catalogInteractionRecoveryTask: Task<Void, Never>?
    var postPlaybackExitRecoveryTask: Task<Void, Never>?
    var unitySurfaceHandoffTask: Task<Void, Never>?
    var unityCatalogTransitionTask: Task<Void, Never>?
    var catalogCompletenessWatchdogTask: Task<Void, Never>?
    var guideStartupTask: Task<Void, Never>?

    func cancelAll() {
        nextQueuedNewEpisodeAlertTask?.cancel(); nextQueuedNewEpisodeAlertTask = nil
        newEpisodeHeartbeatTask?.cancel(); newEpisodeHeartbeatTask = nil
        activeNewEpisodeAlertDismissTask?.cancel(); activeNewEpisodeAlertDismissTask = nil
        membershipClockTask?.cancel(); membershipClockTask = nil
        appBootstrapTask?.cancel(); appBootstrapTask = nil
        entitlementSyncTask?.cancel(); entitlementSyncTask = nil
        newEpisodeScannerVerificationTask?.cancel(); newEpisodeScannerVerificationTask = nil
        catalogInteractionRecoveryTask?.cancel(); catalogInteractionRecoveryTask = nil
        postPlaybackExitRecoveryTask?.cancel(); postPlaybackExitRecoveryTask = nil
        unitySurfaceHandoffTask?.cancel(); unitySurfaceHandoffTask = nil
        unityCatalogTransitionTask?.cancel(); unityCatalogTransitionTask = nil
        catalogCompletenessWatchdogTask?.cancel(); catalogCompletenessWatchdogTask = nil
        guideStartupTask?.cancel(); guideStartupTask = nil
    }

    deinit { cancelAll() }
}

