private final class LiveTVScreenAsyncTaskRuntime: ObservableObject {
    // vBRDC307: callbacks from an old Guide/Live session must never publish into a new
    // screen after a rapid channel-enter -> Back -> tab switch.
    private(set) var generation: UInt64 = 0
    func beginNewGeneration() -> UInt64 { generation &+= 1; return generation }
    func isCurrent(_ token: UInt64) -> Bool { token == generation }

    var liveTVFocusHandoffTask: Task<Void, Never>?
    var liveTVCoveredCompactionTask: Task<Void, Never>?
    var guideHintHideTask: Task<Void, Never>?
    var guideExitHintHideTask: Task<Void, Never>?
    var liveRefreshTask: Task<Void, Never>?
    // vBRDC203: low-frequency self-healing EPG owner. It lives outside SwiftUI State so
    // retry bookkeeping never invalidates the Live TV grid.
    var liveGuideRecoveryTask: Task<Void, Never>?
    var liveTVForcedArtworkBootstrapTask: Task<Void, Never>?
    var liveTVVisibilityResumeTask: Task<Void, Never>?
    var liveForceRefreshTask: Task<Void, Never>?
    var liveTVFocusRestoreTask: Task<Void, Never>?
    var liveTVScheduleBoundaryTask: Task<Void, Never>?

    func cancelAll() {
        liveTVFocusHandoffTask?.cancel(); liveTVFocusHandoffTask = nil
        liveTVCoveredCompactionTask?.cancel(); liveTVCoveredCompactionTask = nil
        guideHintHideTask?.cancel(); guideHintHideTask = nil
        guideExitHintHideTask?.cancel(); guideExitHintHideTask = nil
        liveRefreshTask?.cancel(); liveRefreshTask = nil
        liveGuideRecoveryTask?.cancel(); liveGuideRecoveryTask = nil
        liveTVForcedArtworkBootstrapTask?.cancel(); liveTVForcedArtworkBootstrapTask = nil
        liveTVVisibilityResumeTask?.cancel(); liveTVVisibilityResumeTask = nil
        liveForceRefreshTask?.cancel(); liveForceRefreshTask = nil
        liveTVFocusRestoreTask?.cancel(); liveTVFocusRestoreTask = nil
        liveTVScheduleBoundaryTask?.cancel(); liveTVScheduleBoundaryTask = nil
    }

    deinit { cancelAll() }
}


