private final class VODPlayerAsyncTaskRuntime: ObservableObject {
    var playbackMetadataTask: Task<Void, Never>?
    var playbackMetadataGeneration: UInt64 = 0
    var vodReviewTask: Task<Void, Never>?
    var vodProductionMetadataTask: Task<Void, Never>?
    var vodProductionMetadataGeneration: UInt64 = 0
    var castExplorerTask: Task<Void, Never>?
    var vodCastExplorerOnboardingTask: Task<Void, Never>?
    var vodEpisodeBrowserTask: Task<Void, Never>?
    var pendingVODSwitchTask: Task<Void, Never>?
    var runtimeLookupTask: Task<Void, Never>?
    var timelineMetadataRecoveryTask: Task<Void, Never>?
    var hideTask: Task<Void, Never>?
    var renderWatchdogTask: Task<Void, Never>?
    var nativePrepareTask: Task<Void, Never>?
    var automaticResumeTask: Task<Void, Never>?
    var playbackClockTask: Task<Void, Never>?
    var startupLoadingTask: Task<Void, Never>?
