    var aetherCompatibilityWatchdogTask: Task<Void, Never>?
    var startupSameSourceRetryTask: Task<Void, Never>?
    var automaticSourceFailoverToastTask: Task<Void, Never>?
    var firstFrameProbeTask: Task<Void, Never>?
