    var seekFeedbackTask: Task<Void, Never>?
    var playerDismissalTask: Task<Void, Never>?
    var vodControlShelfHideTask: Task<Void, Never>?
    var timeObserver: Any?
    var statusObserver: NSKeyValueObservation?
    var endObserver: NSObjectProtocol?

    func cancelTasks() {
        playbackMetadataGeneration &+= 1
        playbackMetadataTask?.cancel(); playbackMetadataTask = nil
        vodReviewTask?.cancel(); vodReviewTask = nil
        vodProductionMetadataGeneration &+= 1
        vodProductionMetadataTask?.cancel(); vodProductionMetadataTask = nil
        castExplorerTask?.cancel(); castExplorerTask = nil
        vodCastExplorerOnboardingTask?.cancel(); vodCastExplorerOnboardingTask = nil
        vodEpisodeBrowserTask?.cancel(); vodEpisodeBrowserTask = nil
        pendingVODSwitchTask?.cancel(); pendingVODSwitchTask = nil
        runtimeLookupTask?.cancel(); runtimeLookupTask = nil
        timelineMetadataRecoveryTask?.cancel(); timelineMetadataRecoveryTask = nil
        hideTask?.cancel(); hideTask = nil
        renderWatchdogTask?.cancel(); renderWatchdogTask = nil
        nativePrepareTask?.cancel(); nativePrepareTask = nil
        automaticResumeTask?.cancel(); automaticResumeTask = nil
        playbackClockTask?.cancel(); playbackClockTask = nil
        startupLoadingTask?.cancel(); startupLoadingTask = nil
        automaticSourceFailoverWatchdogTask?.cancel(); automaticSourceFailoverWatchdogTask = nil
        aetherCompatibilityWatchdogTask?.cancel(); aetherCompatibilityWatchdogTask = nil
        startupSameSourceRetryTask?.cancel(); startupSameSourceRetryTask = nil
        automaticSourceFailoverToastTask?.cancel(); automaticSourceFailoverToastTask = nil
        firstFrameProbeTask?.cancel(); firstFrameProbeTask = nil
        upNextPreparationTask?.cancel(); upNextPreparationTask = nil
        upNextSourcePreparationTask?.cancel(); upNextSourcePreparationTask = nil
        upNextCountdownTask?.cancel(); upNextCountdownTask = nil
        upNextWatchdogTask?.cancel(); upNextWatchdogTask = nil
        upNextPostEOFTask?.cancel(); upNextPostEOFTask = nil
        naturalEpisodeEndReason = ""
        upNextDecorationTask?.cancel(); upNextDecorationTask = nil
        latestBufferedPlaybackSeconds = 0
        skipIntroCountdownTask?.cancel(); skipIntroCountdownTask = nil
        introSegmentLookupTask?.cancel(); introSegmentLookupTask = nil
        alternateAudioDiscoveryTask?.cancel(); alternateAudioDiscoveryTask = nil
        alternateAudioBridgeTask?.cancel(); alternateAudioBridgeTask = nil
        alternateAudioHandoffRecoveryTask?.cancel(); alternateAudioHandoffRecoveryTask = nil
        liveQuickGuideTipTask?.cancel(); liveQuickGuideTipTask = nil
        liveQuickGuideRefreshTask?.cancel(); liveQuickGuideRefreshTask = nil
        liveQuickGuideAutoDismissTask?.cancel(); liveQuickGuideAutoDismissTask = nil
        livePlaybackExitBackTask?.cancel(); livePlaybackExitBackTask = nil
        livePlayerFocusTask?.cancel(); livePlayerFocusTask = nil
        timelineScrubAutoSeekTask?.cancel(); timelineScrubAutoSeekTask = nil
        seekFeedbackTask?.cancel(); seekFeedbackTask = nil
        playerDismissalTask?.cancel(); playerDismissalTask = nil
        vodControlShelfHideTask?.cancel(); vodControlShelfHideTask = nil
    }

    deinit { cancelTasks() }
}

struct RootView: View {
    @EnvironmentObject var store: CatalogStore
    @EnvironmentObject var unityCore: UnityAppCore
    /// Build 31: one RootView can be the ordinary Vision window OR the immersive screen,
    /// but only one of those roots is allowed to own a playback surface at a time.
    /// This prevents a hidden/dismissing window from keeping a second KS/Aether decoder audible.
    var visionTheaterSurface: Bool = false
    @Environment(\.scenePhase) private var scenePhase
    @ObservedObject private var mediaFlowConnection = MediaFlowConnectionMonitor.shared
    private let unityAnimations = UnityAnimationCoordinator.shared
    private let unityLifecycle = UnitySurfaceLifecycleCoordinator.shared
    @AppStorage("gridLockedMode") private var gridLockedMode: Bool = false
    @AppStorage("appCanvasExpandedV1") private var appCanvasExpanded: Bool = false
    @State private var didRequestDefaultCatalogLoad = false
    @State private var focusedCatalogCardFrame: CGRect = .zero
    @State private var searchMenuIconFrame: CGRect = .zero
    @AppStorage("hasSeenFirstRunOnboarding") private var hasSeenFirstRunOnboarding: Bool = false
    @AppStorage("membershipActive") private var membershipActive: Bool = false
    @AppStorage("membershipEntitlementStatus") private var membershipEntitlementStatus: String = ProductionEntitlementStatus.unknown.rawValue
    @AppStorage("membershipTrialStartedAt") private var membershipTrialStartedAt: String = ""
    @AppStorage("membershipTrialExpiresAt") private var membershipTrialExpiresAt: String = ""
    @AppStorage("membershipPlanType") private var membershipPlanType: String = ""
    @AppStorage("backendBaseURL") private var backendBaseURLString: String = "https://api.skylinejay187.it.com"
    @AppStorage("liveTVGridThemePreset") private var liveTVGridThemePreset: String = "Classic Dark"
    @AppStorage("mainGridBackgroundPreset") private var unityMainGridBackgroundPreset: String = "Midnight Graphite"
    @AppStorage("topMenuAccentColor") private var unityTopMenuAccentColor: String = "Orange"
    @AppStorage("launchAppInGuide") private var launchAppInGuide: Bool = false
    @AppStorage("followAlertsEnabled") private var followAlertsEnabled: Bool = true
    @AppStorage("followNewEpisodesEnabled") private var followNewEpisodesEnabled: Bool = true
    @AppStorage("followedShowIds") private var rootFollowedShowIdsRaw: String = ""
    @AppStorage("newEpisodeAlertScanFrequencyMinutes") private var newEpisodeAlertScanFrequencyMinutesRaw: String = NewEpisodeAlertScanFrequency.five.rawValue
    @AppStorage("newEpisodeAlertStyle") private var newEpisodeAlertStyleRaw: String = NewEpisodeAlertStyle.banner.rawValue
    @AppStorage("newEpisodeAlertBannerSide") private var newEpisodeAlertBannerSideRaw: String = NewEpisodeAlertBannerSide.topRight.rawValue
    @AppStorage("newEpisodeAlertTheme") private var newEpisodeAlertThemeRaw: String = NewEpisodeAlertTheme.glass.rawValue
    @AppStorage("newEpisodeAlertBannerDurationSeconds") private var newEpisodeAlertBannerDurationSecondsRaw: String = NewEpisodeAlertBannerDuration.fifteen.rawValue
    @AppStorage("newEpisodeAlertPresentationScopeV1") private var newEpisodeAlertPresentationScopeRaw: String = NewEpisodeAlertPresentationScope.mainAndVOD.rawValue
    @AppStorage("sportsScoreTickerEnabled") private var sportsScoreTickerEnabled: Bool = false
    @AppStorage("moviesShowsReleaseTickerEnabled") private var moviesShowsReleaseTickerEnabled: Bool = false
    @AppStorage("sportsFavoriteTeams") private var sportsFavoriteTeams: String = ""
    @AppStorage("sportsTickerPosition") private var sportsTickerPosition: String = "Bottom"
    @AppStorage("sportsCustomSourcesJSON") private var sportsCustomSourcesForTicker: String = ""
    @StateObject private var globalSportsLiveZone = SportsLiveZoneModel()
    // UNITY: retain the real Live TV source owner above the shared visual root.
    // Root view keeps both channel state and the visual donor alive across catalog tabs.
    @StateObject private var liveTVModel = LiveTVSourceModel()
    @State private var membershipClockNow: Date = Date()
    @State private var activeNewEpisodeAlert: NewEpisodeAlertHit? = nil
    @State private var activeNewEpisodeAlertFocus: Int = 0
    @State private var pendingEpisodeAlertOpenIntent: NewEpisodeAlertHit? = nil
