            get { rootAsyncRuntime.newEpisodeScannerVerificationTask }
            nonmutating set { rootAsyncRuntime.newEpisodeScannerVerificationTask = newValue }
        }
    private var catalogInteractionRecoveryTask: Task<Void, Never>? {
            get { rootAsyncRuntime.catalogInteractionRecoveryTask }
            nonmutating set { rootAsyncRuntime.catalogInteractionRecoveryTask = newValue }
        }
    // vBRDC078: VOD exit owns a separate recovery task so catalog focus can reclaim
    // the Siri Remote before entitlement/catalog/artwork work is allowed to resume.
    private var postPlaybackExitRecoveryTask: Task<Void, Never>? {
            get { rootAsyncRuntime.postPlaybackExitRecoveryTask }
            nonmutating set { rootAsyncRuntime.postPlaybackExitRecoveryTask = newValue }
        }
    // vBRDC081: every major tab/surface return uses one bounded UNITY ownership handoff.
    private var unitySurfaceHandoffTask: Task<Void, Never>? {
            get { rootAsyncRuntime.unitySurfaceHandoffTask }
            nonmutating set { rootAsyncRuntime.unitySurfaceHandoffTask = newValue }
        }
    // vBRDC093: the catalog branch is a motion layer over the persistent Live TV root.
    // Keep the outgoing catalog mounted through its reverse transition so Back never
    // exposes a newly-created Live TV tree or a one-frame channel-logo placeholder.
    @State private var unityPresentedCatalogTab: AppTab? = nil
    // vBRDC104: keep one catalog surface physically mounted across Live TV <-> catalog handoffs.
    // This remembers which branch content the hidden shell owns while Live TV is on top.
    @State private var unityPersistentCatalogTab: AppTab = .home
    @State private var unityCatalogBranchProgress: CGFloat = 0
    // vBRDC109: one explicit visual-geometry owner for Live TV <-> catalog presentation.
    // While this is true the catalog rail pins its focused card at final geometry; only the
    // root branch progress is allowed to move pixels. Focus can bind/release invisibly.
    @State private var unityCatalogBranchTransitionActive: Bool = false
    private var unityCatalogTransitionTask: Task<Void, Never>? {
            get { rootAsyncRuntime.unityCatalogTransitionTask }
            nonmutating set { rootAsyncRuntime.unityCatalogTransitionTask = newValue }
        }
    private var catalogCompletenessWatchdogTask: Task<Void, Never>? {
            get { rootAsyncRuntime.catalogCompletenessWatchdogTask }
            nonmutating set { rootAsyncRuntime.catalogCompletenessWatchdogTask = newValue }
        }
    private var guideStartupTask: Task<Void, Never>? {
            get { rootAsyncRuntime.guideStartupTask }
            nonmutating set { rootAsyncRuntime.guideStartupTask = newValue }
        }
    @State private var didApplyGuideStartupPreference: Bool = false
    @State private var mediaFlowWasInSettings: Bool = false
    @State private var guideStartupPreferenceAtLaunch: Bool? = nil
    @FocusState private var activeNewEpisodeAlertFocused: Bool

    private var newEpisodeAlertScanIntervalSeconds: TimeInterval {
        episodeAlertIntervalSeconds(for: newEpisodeAlertScanFrequency)
    }

    private var newEpisodeAlertBannerDuration: NewEpisodeAlertBannerDuration {
        NewEpisodeAlertBannerDuration(rawValue: newEpisodeAlertBannerDurationSecondsRaw) ?? .fifteen
    }

    private var newEpisodeAlertPresentationScope: NewEpisodeAlertPresentationScope {
        NewEpisodeAlertPresentationScope(rawValue: newEpisodeAlertPresentationScopeRaw) ?? .mainAndVOD
    }

    private var episodeAlertFullScreenPlaybackActive: Bool {
        // vBRDC192: the Episode Alert system follows the actual full-screen player
        // surface, regardless of whether that player currently owns VOD or Live TV.
        // The same root scheduler/queue remains the single source of truth.
        store.playbackURL != nil
    }

    private var episodeAlertPresentationAllowedOnCurrentSurface: Bool {
        if store.playbackURL == nil { return true }
        return episodeAlertFullScreenPlaybackActive && newEpisodeAlertPresentationScope == .mainAndVOD
    }

    private var effectiveNewEpisodeAlertStyle: NewEpisodeAlertStyle {
        episodeAlertFullScreenPlaybackActive ? .banner : newEpisodeAlertStyle
    }

    private var onboardingActive: Bool {
        // v651: when entitlement lockout is active, Membership must remain usable.
        // First-run onboarding should not cover/disable Membership, Restore, Manage Devices, or owner access.
        !membershipLocked && !hasSeenFirstRunOnboarding && store.playbackURL == nil
    }

    private var membershipTrialExpiryDate: Date? {
        MembershipEntitlementManager.trialExpiryDate(from: membershipTrialExpiresAt)
    }

    private var membershipLocked: Bool {
        MembershipEntitlementManager.isLocked(
            active: membershipActive,
            entitlementStatusRaw: membershipEntitlementStatus,
            trialExpiresAt: membershipTrialExpiresAt,
            now: membershipClockNow
        )
    }


    // v800 / vBRDC093: Any Home/Movies/Shows/Sports quick-panel surface owns the
    // card lanes. During catalog Back, ownership remains with the outgoing branch until
    // its reverse UNITY transition is visually complete; the top menu/tickers must not
    // wake up underneath that transition.
    private var catalogQuickPanelActive: Bool {
        let activeTab = unityCore.activeTab
        let catalogTransitionOwnsSurface = unityPresentedCatalogTab != nil
            || (store.catalogRowsPresented && UnitySurfaceSystem.catalogBranchActive(for: activeTab))
        let sportsOwnsSurface = activeTab == .sports
        return (catalogTransitionOwnsSurface || sportsOwnsSurface)
        && store.selectedDetail == nil
        && !store.searchActive
        && store.playbackURL == nil
    }

    private var unityCatalogPresentationTab: AppTab? {
        if let unityPresentedCatalogTab { return unityPresentedCatalogTab }
        guard store.catalogRowsPresented,
              UnitySurfaceSystem.catalogBranchActive(for: store.selectedTab) else { return nil }
        return store.selectedTab
    }

    // vBRDC104: rendering identity is intentionally separate from presentation ownership.
    // The catalog tree remains alive while Live TV owns focus, preserving row/card/hero state
    // so opening the catalog is only a compositor handoff rather than a mount + rebuild.
    private var unityCatalogRenderTab: AppTab {
        if let presented = unityCatalogPresentationTab { return presented }
        return unityPersistentCatalogTab
    }

    private var globalTickerOverlaysAllowed: Bool {
        let activeTab = unityCore.activeTab
        return !membershipLocked
        && !catalogQuickPanelActive
        && !store.liveQuickPanelOpen
        && activeTab != .settings
        && activeTab != .sports
        && activeTab != .favorites
        && activeTab != .membership
        && store.selectedDetail == nil
        && !store.searchActive
        && onboardingActive == false
        && store.playbackURL == nil
    }

    // vBRDC182: the global navigation shell remains physically mounted for every normal
    // app surface. Visibility and focus ownership change, but the menu view identity does not.
    private var unityTopNavigationVisible: Bool {
        let activeTab = unityCore.activeTab
        return (!membershipLocked || activeTab == .membership)
        && store.playbackURL == nil
        && !store.searchActive
        && (!store.liveQuickPanelOpen || activeTab == .favorites || activeTab == .membership || activeTab == .sports)
    }

    private var unityTopNavigationOwnsFocus: Bool {
        let activeTab = unityCore.activeTab
        let contentOwnsFocus = (
            activeTab == .sports
            || unityPresentedCatalogTab != nil
            || (store.catalogRowsPresented && UnitySurfaceSystem.catalogBranchActive(for: activeTab))
        )
        && store.selectedDetail == nil
        && !store.searchActive
        && store.playbackURL == nil
        return unityTopNavigationVisible
            && !onboardingActive
            && !contentOwnsFocus
            && store.selectedDetail == nil
    }

    private func synchronizeUnityCoreTheme(reason: String) {
        unityCore.synchronizeTheme(
            backgroundPreset: unityMainGridBackgroundPreset,
            accentPreset: unityTopMenuAccentColor,
            liveTVThemePreset: liveTVGridThemePreset
        )
        print("[UNITY Core][Theme] sync reason=\(reason)")
    }

    private func synchronizeUnityAnimationContext(reason: String) {
        let playbackActive = store.playbackURL != nil || store.vodExclusivePlaybackActive
        unityCore.synchronizeSurfaceOwnership(
            searchActive: store.searchActive,
            detailActive: store.selectedDetail != nil,
            playbackActive: playbackActive,
            reason: reason
        )
        unityAnimations.synchronizeGlobal(
            sceneActive: scenePhase == .active,
            globalSearchActive: store.searchActive,
            settingsActive: unityCore.activeTab == .settings,
            detailActive: store.selectedDetail != nil,
            fullScreenPlaybackActive: playbackActive
        )
        SignalMainThreadStallWatchdog.shared.markSurface(unityCore.effectiveSurface.rawValue)
        print("[UNITY Animation][Root] sync reason=\(reason) surface=\(unityCore.effectiveSurface.rawValue)")
    }

    private func seedTenMinuteTrialIfNeeded() {
        MembershipEntitlementManager.auditAndBootstrapFreshTrialIfNeeded()
        syncProductionEntitlement(reason: "launch")
    }

    private func migrateReleaseTickersOffByDefaultIfNeeded() {
        let defaults = UserDefaults.standard
        let migrationKey = "v1033ReleaseTickersDefaultOffMigration"
        guard !defaults.bool(forKey: migrationKey) else { return }
        sportsScoreTickerEnabled = false
        moviesShowsReleaseTickerEnabled = false
        defaults.set(true, forKey: migrationKey)
        print("[ReleaseDefaults] Movie/show and sports tickers defaulted to Off")
    }

    // vBRDC184 compile containment: vBRDC183 crossed Swift's type-check budget at the
    // RootView body after the UNITY composition grew into one enormous generic expression.
    // These four opaque stages preserve the exact modifier order and runtime hierarchy while
    // giving the compiler bounded expressions it can solve independently.
    private var rootVisualTree: some View {
        ZStack(alignment: .top) {
            // v972 Phase 1: full-screen playback removes Live TV, catalogs,
            // sports, settings, artwork rails, and their view-local timers from the render
            // tree. Live TV focus restoration will be rebuilt from lightweight state in
            // the next phase instead of retaining the heavy grid during playback.
            // The new-episode alert layer remains mounted separately below.
            if store.playbackURL != nil {
                StaticAppBackground()
                    .ignoresSafeArea()
                    .allowsHitTesting(false)
            } else {
                // vBRDC096 / Code Name UNITY: the real Live TV grid is the one persistent
                // visual root for every non-playback app surface, including Settings,
                // Favorites, Membership, Sports and the catalog branches. vBRDC095 preserved
                // decoded card pixels only while the LiveTVScreen instance stayed mounted;
                // dedicated surfaces still destroyed that instance, so returning from
                // Settings/Favorites rebuilt generic channel cards until Gracenote artwork
                // loaded again. Keep one physical root and suspend its work instead of
                // substituting/recreating its visual tree.
                let activeUnityTab = unityCore.activeTab
                let catalogPresentationTab = unityCatalogPresentationTab
                let liveRootInteractive = activeUnityTab == .live
                    && catalogPresentationTab == nil
                    && store.selectedDetail == nil
                    && !store.searchActive
                    && store.playbackURL == nil

                // UNITY visual contract (restored): the real Live TV surface supplies the
                // continuous shared backdrop beneath Home/Movies/TV Shows. It must remain
                // physically mounted throughout non-playback navigation, not just persist
                // its model. Dedicated screens hide its pixels but retain its identity;
                // covered background/preview work remains suspended inside LiveTVScreen.
                let dedicatedSurfaceOwnsPixels = !UnitySurfaceSystem.shouldCompositeLiveTVRoot(for: activeUnityTab)
                    || (membershipLocked && activeUnityTab != .membership)

                LiveTVScreen(liveModel: liveTVModel)
                    .modifier(SignalVisionLayerSurface(level: .base,
                         active: liveRootInteractive, visible: !dedicatedSurfaceOwnsPixels))
                    .opacity(dedicatedSurfaceOwnsPixels ? 0 : 1)
                    .disabled(onboardingActive || !liveRootInteractive)
                    .allowsHitTesting(!onboardingActive && liveRootInteractive)
                    .accessibilityHidden(dedicatedSurfaceOwnsPixels)
                    .zIndex(0)

                // Dedicated surfaces cover the same retained Live TV pixels. Their own
                // z-order/focus ownership is unchanged; LiveTVScreen's selectedTab observer
                // compacts to the 24-card corridor and cancels refresh/EPG/prefetch work.
                if membershipLocked && activeUnityTab != .membership {
                    MembershipScreen()
                        .disabled(false)
                        .allowsHitTesting(true)
                        .zIndex(4300)
                } else if activeUnityTab == .settings {
                    SettingsScreen(
                        store: store,
                        onTestNewEpisodeAlert: triggerDeveloperNewEpisodeAlert,
                        onVerifyNewEpisodeScanner: verifyNewEpisodeScanner
                    )
                        .disabled(onboardingActive || store.selectedDetail != nil)
                        .allowsHitTesting(!onboardingActive && store.selectedDetail == nil)
                        .accessibilityHidden(store.selectedDetail != nil)
                        .zIndex(4100)
                } else if activeUnityTab == .membership {
                    MembershipScreen()
                        .disabled(false)
                        .allowsHitTesting(true)
                        .zIndex(4300)
                } else if activeUnityTab == .favorites {
                    // Favorites still owns its isolated artwork cache and local details
                    // presentation. The Live TV root behind it remains mounted but inert.
                    if !store.searchActive && store.playbackURL == nil {
                        GlobalFavoritesScreen()
                            .environment(\.premiumArtworkCacheDomain, .favorites)
                            .disabled(onboardingActive || store.selectedDetail != nil)
                            .allowsHitTesting(!onboardingActive && store.selectedDetail == nil)
                            .zIndex(4100)
                    } else {
                        StaticAppBackground()
                            .ignoresSafeArea()
                            .allowsHitTesting(false)
                            .zIndex(4100)
                    }
                } else {
                    if activeUnityTab == .sports {
                        SportsHubScreen()
                            .environment(\.premiumArtworkCacheDomain, .sports)
                            .disabled(onboardingActive || store.selectedDetail != nil || store.searchActive || store.playbackURL != nil)
                            .allowsHitTesting(!(onboardingActive || store.selectedDetail != nil || store.searchActive || store.playbackURL != nil))
                            .zIndex(4100)
                    }

                    // vBRDC104: keep the catalog shell mounted even while Live TV owns the screen.
                    // vBRDC103 made rows persistent *inside* this view, but the root still removed
                    // the whole GridOSCatalogOverlay at the end of every Back transition. That
                    // forced onAppear, row projection, Hero setup and focus recovery on every open.
                    // The hidden shell now retains those decoded/layout resources and only this
                    // lightweight presentation scalar moves at the compositor boundary.
                    let catalogRenderTab = unityCatalogRenderTab
                    let catalogSurfacePresented = catalogPresentationTab != nil
                    // vBRDC201: visible main catalogs follow the actual presented category.
                    // catalogRenderTab remains only the hidden-shell retention identity.
                    let visibleCatalogTab = catalogPresentationTab ?? (UnitySurfaceSystem.catalogBranchActive(for: store.selectedTab) ? store.selectedTab : catalogRenderTab)
                    let progress = catalogSurfacePresented ? min(max(unityCatalogBranchProgress, 0), 1) : 0
                    GridOSCatalogOverlay(
                        filter: visibleCatalogTab == .movies ? "movie" : (visibleCatalogTab == .shows ? "series" : nil),
                        surfaceHandoffActive: unityCatalogBranchTransitionActive,
                        // vBRDC327 visual lock: full trailers must NOT dismiss/unmount the
                        // catalog rows. The old Signal presentation kept the catalog surface
                        // visually resident behind the trailer. Performance isolation belongs
                        // in decoder/task ownership, not in changing UNITY/catalog presentation.
                        presentationActive: (catalogSurfacePresented || unityCatalogBranchTransitionActive || progress > 0.001)
                            && store.playbackURL == nil
                            && !store.searchActive
                    )
                        // Build 31: the catalog is the original UNITY surface again.
                        // Do not attach any Vision Pro depth/popup modifier here. Media Information
                        // is the only spatial popup above this flat catalog canvas.
                        .opacity(progress)
                        .offset(y: (1 - progress) * 18)
                        .disabled(onboardingActive || store.selectedDetail != nil || store.searchActive || store.playbackURL != nil || !catalogSurfacePresented || !UnitySurfaceSystem.catalogBranchActive(for: store.selectedTab) || progress < 0.985)
                        .allowsHitTesting(!onboardingActive && store.selectedDetail == nil && !store.searchActive && store.playbackURL == nil && catalogSurfacePresented && UnitySurfaceSystem.catalogBranchActive(for: store.selectedTab) && progress >= 0.985)
                        .accessibilityHidden(store.selectedDetail != nil || !catalogSurfacePresented)
                        .zIndex(4200)
                }

            }

            // vBRDC182 UNITY shell: keep the one real top navigation view mounted at all times.
            // Covered/exclusive surfaces only hide or disable it; they never destroy/recreate it.
            UnityPersistentTopNavigationHost(
                store: store,
                visible: unityTopNavigationVisible,
                interactive: unityTopNavigationOwnsFocus
            )
            .zIndex(6100)

            if store.playbackURL == nil, let detail = store.selectedDetail {
                MediaInfoPopup(
                    item: detail,
                    sourceCardFrame: store.detailPresentationOrigin == .search ? searchMenuIconFrame : focusedCatalogCardFrame,
                    connectorOrigin: store.detailPresentationOrigin,
                    pendingEpisodeAlertOpenIntent: $pendingEpisodeAlertOpenIntent
                )
                    // Favorites-owned details can contain full-resolution background/poster
                    // decodes. Keep them in the Favorites cache domain too so opening one
                    // cannot evict the warm Home/Movies/Shows artwork cache before Back.
                    .environment(\.premiumArtworkCacheDomain, store.detailPresentationOrigin == .favorites ? .favorites : .persistent)
                    // v720: force a fresh details/media-info view identity for every title.
                    // This prevents SwiftUI from reusing the previous popup artwork tree for
                    // one frame when opening a different movie/show.
                    .id("media-info-\(store.detailPresentationRevision)-\(detail.id)")
                    .modifier(SignalVisionLayerSurface(level: .detail, active: true, visible: true))
                    .zIndex(5500)
            }

            if store.searchActive && store.playbackURL == nil {
                GlobalSearchScreen(liveModel: liveTVModel)
                    // v1128: Search details are a true modal stage. Keep the query/results
                    // mounted for exact restoration, but remove the results grid from the
                    // focus and hit-test graph while its media information is open.
                    .disabled(store.selectedDetail != nil)
                    .allowsHitTesting(store.selectedDetail == nil)
                    .accessibilityHidden(store.selectedDetail != nil)
                    .zIndex(5000)
            }

            if visionPlaybackSurfaceAllowed, let url = store.playbackURL, let item = store.playbackItem {
                VODPlayerScreen(
                    item: item,
                    url: url,
                    playbackPresentationID: store.playbackPresentationID,
                    episodeAlert: newEpisodeAlertPresentationScope == .mainAndVOD ? activeNewEpisodeAlert : nil,
                    episodeAlertSide: newEpisodeAlertBannerSide,
                    episodeAlertTheme: newEpisodeAlertTheme,
                    onEpisodeAlertPresented: { alert in
                        confirmEpisodeAlertPresentation(alert)
                    }
                )
                    // URL handles normal Live TV changes; launch UUID guarantees a fresh
                    // VOD screen even when the exact same source is reopened.
                    .id("\(store.playbackPresentationID.uuidString)::\(url.absoluteString)")
                    .zIndex(9000)
            }

            // vBRDC232 continuous handoff: arm the exact media artwork before the playback
            // URL replaces Media Information and keep it above the player until KSPlayer
            // proves a real first rendered frame/advancing decoder clock.
            if store.playbackLaunchCoverActive,
               let coverItem = store.playbackLaunchCoverItem,
               store.playbackLaunchCoverPresentationID == store.playbackPresentationID {
                VODLoadingBackdrop(item: coverItem, message: "Opening Player…")
                    .ignoresSafeArea()
                    .allowsHitTesting(false)
                    .transition(.identity)
                    .zIndex(9040)
            }

            if store.playbackURL == nil && membershipLocked && store.selectedTab != .membership {
                MembershipLockoutOverlay {
                    withAnimation(.easeInOut(duration: 0.20)) {
                        unityCore.select(.membership, store: store, reason: "membership lockout overlay")
                    }
                }
                .zIndex(9000)
            }

            realNewEpisodeAlertLayer

            if store.playbackURL == nil {
                newEpisodeScannerVerificationLayer
            }

            if sportsScoreTickerEnabled && globalTickerOverlaysAllowed {
                GlobalSportsTickerOverlay(position: sportsTickerPosition, favoriteTeams: sportsFavoriteTeams, liveItems: globalSportsLiveZone.ticker)
                    .zIndex(9050)
            }

            if moviesShowsReleaseTickerEnabled && globalTickerOverlaysAllowed {
                MoviesShowsReleaseTickerOverlay()
                    .environmentObject(store)
                    .zIndex(9045)
            }

            if store.playbackURL == nil && mediaFlowConnection.bannerVisible {
                MediaFlowConnectionStatusBanner(monitor: mediaFlowConnection)
                    .padding(.top, 86)
                    .zIndex(9725)
                    .transition(.move(edge: .top).combined(with: .opacity))
            }

            if onboardingActive && !membershipLocked {
                FirstRunOnboardingOverlay(isVisible: $hasSeenFirstRunOnboarding)
                    .zIndex(9800)
            }
        }
        .background(UnitySurfaceBackdrop())
        .ignoresSafeArea(.all)
        .onReceive(NotificationCenter.default.publisher(for: SignalVisionRemoteEvent.home)) { _ in
            store.searchActive = false
            store.selectedDetail = nil
            store.liveQuickPanelOpen = false
            unityCore.select(.live, store: store, reason: "vision virtual remote home")
        }
        .onPreferenceChange(FocusedCatalogCardFramePreferenceKey.self) { frame in
            guard frame.width > 40, frame.height > 40, frame != focusedCatalogCardFrame else { return }
            focusedCatalogCardFrame = frame
        }
        .onPreferenceChange(SearchMenuIconFramePreferenceKey.self) { frame in
            guard frame.width > 20, frame.height > 20, frame != searchMenuIconFrame else { return }
            searchMenuIconFrame = frame
        }
    }

    private var rootPlaybackLifecycleTree: some View {
        rootVisualTree
        // vBRDC304: Expanded App Canvas is layout-driven, never a compositor zoom.
        // Scaling the entire 1920x1080 root pushed the SIGNAL mark, focused cards and
        // media-profile surfaces offscreen. Individual full-screen surfaces now reclaim
        // their safe margins instead, while playback keeps native 1:1 geometry.
        .onAppear {
            // vBRDC208 regression lock: register the shared MediaRemote command handlers at
            // app-root lifetime, not only after the first VOD session. This gives tvOS a stable
            // custom-player command registration for Live TV and lets the same lifecycle
            // observers reassert the active Now Playing publication after sleep/media resets.
            BluetoothVODMediaButtonCoordinator.shared.installIfNeeded()
            unityCore.bootstrap(tab: store.selectedTab)
            synchronizeUnityCoreTheme(reason: "root appear")
            synchronizeUnityAnimationContext(reason: "root appear")
            if UnitySurfaceSystem.catalogBranchActive(for: store.selectedTab) {
                unityPersistentCatalogTab = store.selectedTab
                unityPresentedCatalogTab = store.selectedTab
                unityCatalogBranchProgress = 1
            }
            mediaFlowWasInSettings = store.selectedTab == .settings
            mediaFlowConnection.setAppActive(true)
            mediaFlowConnection.setPlaybackActive(store.playbackURL != nil)
            mediaFlowConnection.refresh(reason: "app opened", showBanner: true, allowFreshReuse: false)
            print("DEBRID_CHANNELS_TVOS_BUILD_V1086_ALWAYS_ON_EPISODE_ALERTS")
            if guideStartupPreferenceAtLaunch == nil {
                guideStartupPreferenceAtLaunch = launchAppInGuide
            }
            migrateReleaseTickersOffByDefaultIfNeeded()
            store.handlePhase7SceneBecameActive()
            NewEpisodeAlertsManager.migrateDefaultFrequencyToFiveIfNeeded()
            seedTenMinuteTrialIfNeeded()
            membershipClockNow = Date()
            startMembershipClockIfAllowed()
            startAppBootstrapIfNeeded()
            startCatalogCompletenessWatchdogIfNeeded()
            if membershipLocked {
                unityCore.select(.membership, store: store, reason: "membership lock on launch")
            } else {
                applyGuideStartupPreferenceIfNeeded(reason: "cold launch")
            }
        }
        .task {
            // vBRDC193: import any Trakt cloud resume checkpoints early enough that
            // catalog cards and the next VOD presentation can use them without blocking
            // startup. The manager reuses its persisted cache immediately and refreshes
            // network state only when a linked account is configured.
            _ = await TraktSyncManager.shared.refreshConnectedAccountIdentityIfNeeded(
                force: TraktSyncManager.shared.connectedAccountName.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            )
            // vBRDC210: cold launch owns Trakt restoration as one ordered transaction.
            // Waiting for the playback snapshot here prevents Resume from first mounting
            // timing-only cards and only gaining artwork after the user visits another tab.
            if TraktSyncManager.shared.isConnected && TraktSyncManager.shared.isEnabled {
                await TraktSyncManager.shared.refreshPlaybackProgress(force: false)
            }
            store.refreshPlaybackDerivedCatalogRows(scheduleAccountRefresh: false)
            store.hydrateResumeArtworkOnColdLaunchIfNeeded(force: false)
            store.refreshTraktCatalogRowsIfNeeded(force: false)
            restorePersistedEpisodeAlertsIfNeeded()
            // RootView can start before scene/entitlement state is ready. Activation is
            // eligibility-driven so the scheduler cannot remain stopped until a setting
            // is manually toggled.
            await Task.yield()
            activateNewEpisodeAlertScheduler(reason: "launch")
            startMembershipClockIfAllowed()
            startAppBootstrapIfNeeded()
            startCatalogCompletenessWatchdogIfNeeded()
        }
        .onChange(of: unityMainGridBackgroundPreset) { _, _ in
            synchronizeUnityCoreTheme(reason: "main background")
        }
        .onChange(of: unityTopMenuAccentColor) { _, _ in
            synchronizeUnityCoreTheme(reason: "top menu accent")
        }
        .onChange(of: liveTVGridThemePreset) { _, _ in
            synchronizeUnityCoreTheme(reason: "Live TV appearance")
        }
        .onChange(of: store.vodExclusivePlaybackActive) { active in
            synchronizeUnityAnimationContext(reason: "VOD exclusive gate")
            if active {
                catalogInteractionRecoveryTask?.cancel()
                catalogInteractionRecoveryTask = nil
                postPlaybackExitRecoveryTask?.cancel()
                postPlaybackExitRecoveryTask = nil
                stopCatalogCompletenessWatchdog()
                suspendNonAlertRootWorkForVOD()
                if newEpisodeAlertPresentationScope == .mainAndVOD, let activeAlert = activeNewEpisodeAlert {
                    activeNewEpisodeAlertFocused = false
                    prepareAlertPresentation(for: activeAlert)
                }
            } else if store.playbackURL == nil {
                // vBRDC078: do not restart catalog/entitlement/alert work on the same
                // render turn that the heavy catalog hierarchy remounts. Focus recovery
                // owns the exit first; normal root work resumes after interaction is proven.
                store.setFullScreenPlaybackResourceSuspended(false, reason: "VOD gate closed")
                schedulePostPlaybackExitRecovery(reason: "VOD gate closed")
            }
        }
        .onChange(of: store.playbackURL) { value in
            synchronizeUnityAnimationContext(reason: "playback URL")
            mediaFlowConnection.setPlaybackActive(value != nil)
            if value == nil {
                // vBRDC105: Live TV returns use a dedicated fast lane. A Live TV focus
                // snapshot proves the destination is the grid/guide, so do not wake the
                // catalog-wide premium artwork rehydration sweep on the same frame that the
                // new LiveTVScreen is rebuilding its focus corridor. VOD/catalog exits keep
                // the existing recovery path unchanged.
                let returningToLiveTV = store.liveTVFocusSnapshot != nil
                LiveTVBoundedArtworkLoader.endFullScreenPlaybackSuspension()
                if returningToLiveTV && store.selectedTab == .live {
                    LiveTVBoundedArtworkLoader.resumeRetainedRequests()
                } else {
                    // VOD returns to Home/Movies/Settings must not restart persistent
                    // Live TV decode tasks behind the currently visible surface.
                    LiveTVBoundedArtworkLoader.suspendForCoveredSurface(reason: "playback returned to covered Live TV")
                }
                if !returningToLiveTV {
                    PremiumArtworkRehydrationCoordinator.shared.force(reason: "full-screen playback closed")
                }
                store.setFullScreenPlaybackResourceSuspended(false, reason: "full-screen playback closed")
                schedulePostPlaybackExitRecovery(reason: returningToLiveTV ? "Live TV playback closed" : "playback closed")
            } else {
                postPlaybackExitRecoveryTask?.cancel()
                postPlaybackExitRecoveryTask = nil
                unitySurfaceHandoffTask?.cancel()
                unitySurfaceHandoffTask = nil
                unityCatalogTransitionTask?.cancel()
                unityCatalogTransitionTask = nil
                unityLifecycle.cancelHandoff(reason: "playback mounted")
                unityAnimations.setSurfaceHandoffActive(false)
                catalogInteractionRecoveryTask?.cancel()
                catalogInteractionRecoveryTask = nil
                stopCatalogCompletenessWatchdog()
                // vBRDC004: Live TV and VOD both own the full frame budget. The old root
                // suspension only covered VOD-exclusive sessions, so catalog bootstrap /
                // entitlement work could still publish while a Live TV decoder was active.
                suspendNonAlertRootWorkForVOD()
                store.setFullScreenPlaybackResourceSuspended(true, reason: "full-screen playback mounted")
                LiveTVBoundedArtworkLoader.beginFullScreenPlaybackSuspension(reason: "full-screen playback mounted")

                // vBRDC023 physical-test correction: entering a real VOD surface is now an
                // explicit Episode Alert delivery checkpoint. The same existing scheduler is
                // re-armed only if needed and any already-persisted/queued alert is drained
                // immediately. No playback timer or second polling loop is introduced.
                if episodeAlertFullScreenPlaybackActive && newEpisodeAlertPresentationScope == .mainAndVOD {
                    activateNewEpisodeAlertScheduler(
                        reason: store.vodExclusivePlaybackActive
                            ? "VOD full-screen playback mounted"
                            : "Live TV full-screen playback mounted"
                    )
                    if let activeAlert = activeNewEpisodeAlert {
                        prepareAlertPresentation(for: activeAlert)
                    } else {
                        presentNextQueuedNewEpisodeAlertIfPossible(delaySeconds: 0)
                    }
                }
            }
        }
    }

    private var rootSurfaceObservationTree: some View {
        rootPlaybackLifecycleTree
        .onChange(of: scenePhase) { phase in
            synchronizeUnityAnimationContext(reason: "scene phase")
            if phase == .active {
                DebridNowPlayingManager.shared.reassertCurrentSession(reason: "root scene became active")
                Task {
                    _ = await TraktSyncManager.shared.refreshConnectedAccountIdentityIfNeeded(
                        force: TraktSyncManager.shared.connectedAccountName.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                    )
                    if TraktSyncManager.shared.isConnected && TraktSyncManager.shared.isEnabled {
                        await TraktSyncManager.shared.refreshPlaybackProgress(force: false)
                    }
                    await MainActor.run {
                        store.refreshPlaybackDerivedCatalogRows(scheduleAccountRefresh: false)
                        store.hydrateResumeArtworkOnColdLaunchIfNeeded(force: false)
                        store.refreshTraktCatalogRowsIfNeeded(force: false)
                    }
                }
                mediaFlowConnection.setAppActive(true)
                mediaFlowConnection.refresh(reason: "app resumed", showBanner: true, allowFreshReuse: false)
                store.handlePhase7SceneBecameActive()
                if store.selectedTab == .live && store.playbackURL == nil && !VODExclusivePlaybackGate.isActive {
                    LiveTVBoundedArtworkLoader.resumeRetainedRequests()
                }
                // Rehydrate only the visible catalog. The persistent catalog
                // remains mounted under Live TV and would otherwise restart
                // its blank poster requests during the first scrolling frames.
                if UnitySurfaceSystem.catalogBranchActive(for: store.selectedTab) {
                    PremiumArtworkRehydrationCoordinator.shared.force(reason: "scene became active")
                }
                resumeRootWorkAfterInactiveScene()
                scheduleCatalogInteractionRecovery(reason: "scene became active")
                startCatalogCompletenessWatchdogIfNeeded()
                if !store.vodExclusivePlaybackActive { syncProductionEntitlement(reason: "resume") }
                activateNewEpisodeAlertScheduler(reason: "resume")
            } else {
                mediaFlowConnection.setAppActive(false)
                store.handlePhase7SceneBecameInactive()
                suspendRootWorkForInactiveScene()
                stopCatalogCompletenessWatchdog()
                catalogInteractionRecoveryTask?.cancel()
                catalogInteractionRecoveryTask = nil
                postPlaybackExitRecoveryTask?.cancel()
                postPlaybackExitRecoveryTask = nil
                unitySurfaceHandoffTask?.cancel()
                unitySurfaceHandoffTask = nil
                unityCatalogTransitionTask?.cancel()
                unityCatalogTransitionTask = nil
                unityCatalogBranchTransitionActive = false
                unityLifecycle.cancelHandoff(reason: "scene inactive")
                // vBRDC201: tvOS may suspend the process before navigation/recovery timers
                // get their final callback. Clear every transient frame owner at the sleep
                // boundary so a later Guide/catalog publication cannot inherit a stale
                // navigation or surface-handoff lock from hours earlier. Playback ownership
                // itself is preserved by synchronizeGlobal/context and is not cleared here.
                unityAnimations.resetTransientOwnership()
                stopNewEpisodeHeartbeat(reason: "scene inactive")
            }
        }
        .onChange(of: unityCore.activeTab) { oldTab, tab in
            synchronizeUnityAnimationContext(reason: "selected tab")
            // vBRDC131: changing to a catalog category means "open its rows"; changing
            // away means the explicit row-presentation bit follows the new surface.
            // Back/Menu does not change selectedTab, so it can dismiss rows independently.
            if UnitySurfaceSystem.catalogBranchActive(for: tab) {
                if !store.catalogRowsPresented { store.catalogRowsPresented = true }
            } else if store.catalogRowsPresented {
                store.catalogRowsPresented = false
            }
            synchronizeUnityCatalogBranchPresentation(from: oldTab, to: tab)
            // vBRDC091: dedicated heavyweight surfaces own isolated decoded-artwork caches.
            // Release them before the incoming catalog begins scrolling so Sports/Favorites
            // can never evict or leave GPU/decoded-image pressure behind on Home.
            if oldTab == .sports, tab != .sports {
                PremiumRemoteImageLoader.releaseTransientSurfaceResources(domain: .sports, reason: "root tab handoff \(oldTab.rawValue) → \(tab.rawValue)")
            }
            if oldTab == .favorites, tab != .favorites {
                PremiumRemoteImageLoader.releaseTransientSurfaceResources(domain: .favorites, reason: "root tab handoff \(oldTab.rawValue) → \(tab.rawValue)")
            }

            // vBRDC086 hard invariant: a Favorites-owned detail/restore identity is never
            // allowed to cross into a shared catalog surface. This catches top-menu and
            // post-playback exits even if the Favorites view disappears before its local
            // Back handler can run.
            if oldTab == .favorites, tab != .favorites, store.playbackURL == nil {
                store.clearFavoritesPresentationStateForNavigation(reason: "root tab handoff \(oldTab.rawValue) → \(tab.rawValue)")
            }
            scheduleUnitySurfaceHandoff(from: oldTab, to: tab, reason: "tab \(oldTab.rawValue) → \(tab.rawValue)")
            if tab == .settings {
                mediaFlowWasInSettings = true
            } else if mediaFlowWasInSettings && store.playbackURL == nil {
                // vBRDC081: the returning surface/focus tree owns the first frames. Keep the
                // latch set; MediaFlow refresh runs only after the lifecycle settle point.
            }
        }
        .onChange(of: store.catalogRowsPresented) { _, presented in
            // vBRDC131: Back from a catalog is a presentation close, not a tab change.
            // The selected top-menu category remains Home/Movies/TV Shows while the same
            // resident catalog branch animates out to the persistent UNITY root. Re-entry
            // reverses this exact compositor scalar without mounting a new catalog tree.
            synchronizeUnityCatalogMenuPresentation(presented: presented)
        }
        .onChange(of: sportsScoreTickerEnabled) { _, enabled in
            if enabled, scenePhase == .active, store.playbackURL == nil, !store.vodExclusivePlaybackActive {
                Task { @MainActor in
                    await globalSportsLiveZone.load(
                        favoriteTeams: sportsFavoriteTeams,
                        xtreamAccounts: "",
                        customSources: sportsCustomSourcesForTicker
                    )
                }
            } else if !enabled {
                globalSportsLiveZone.suspendForSurfaceExit()
            }
        }
        .onChange(of: store.searchActive) { _ in
            synchronizeUnityAnimationContext(reason: "global search")
        }
        .onChange(of: store.selectedDetail?.id) { _ in
            synchronizeUnityAnimationContext(reason: "detail ownership")
            if store.selectedDetail == nil {
                unityAnimations.setSourceIntelligence(searching: false, opening: false)
            }
        }
        .onChange(of: unityCore.trailerExclusiveActive) { _, active in
            unityAnimations.setTrailerExclusiveActive(active)
        }
        .onChange(of: store.rows.count) { _ in
            guard scenePhase == .active,
                  store.playbackURL == nil,
                  !store.vodExclusivePlaybackActive,
                  unityLifecycle.permitsNonessentialBackgroundWork else { return }
            Task { @MainActor in
                await store.ensureDebridChannelsCatalogCompleteness(reason: "visible row count changed")
            }
        }
    }

    private var rootStateObservationTree: some View {
        rootSurfaceObservationTree
        .onChange(of: unityCore.memoryPressureRevision) { _, _ in
            store.handlePhase7MemoryPressure()
            SourceMediaTrackProbeCache.handleReleaseStabilityMemoryPressure()
            AdvisoryOMDbFactCache.handleReleaseStabilityMemoryPressure()
            AdvisoryTMDBFactCache.handleReleaseStabilityMemoryPressure()
            RottenTomatoesScoreCache.handleReleaseStabilityMemoryPressure()
            TopBarAdvisorSession.handleReleaseStabilityMemoryPressure()
            // vBRDC182: one process-wide UNITY observer fans memory pressure into the
            // active subsystems instead of every surface subscribing to UIKit separately.
            LiveTVBoundedArtworkLoader.releaseCacheAndPrefetch(reason: "memory warning")
            LiveTVBoundedArtworkLoader.releaseTransientResources(reason: "memory warning", preserveVisibleRequests: true)
            ReleaseStabilityMemoryAuditManager.shared.markMemoryPressure()
        }
        .onChange(of: membershipLocked) { locked in
            if locked {
                stopNewEpisodeHeartbeat(reason: "membership unavailable")
                // vBRDC226: lock transition is an authoritative entitlement boundary.
                // Tear down any stale playback/search/detail/catalog route before selecting
                // Membership so repeated remote movement can never reach playable content.
                if store.playbackURL != nil { store.closePlayer() }
                store.searchActive = false
                store.selectedDetail = nil
                store.detailBackStack.removeAll()
                store.catalogRowsPresented = false
                store.liveQuickPanelOpen = false
                store.topMenuSelectionHoldTab = nil
                store.topMenuFocusLocked = false
                unityCore.select(.membership, store: store, reason: "membership lock became authoritative")
                unityCore.requestTopNavigationFocus(origin: .membership, reason: "membership lock focus")
            } else {
                // This is the cold-launch path that was missing: entitlement commonly
                // becomes valid after RootView's first task has already run.
                applyGuideStartupPreferenceIfNeeded(reason: "membership became eligible")
                activateNewEpisodeAlertScheduler(reason: "membership became eligible")
            }
        }
        .onChange(of: membershipEntitlementStatus) { _ in
            restartMembershipClockForEntitlementChange()
        }
        .onChange(of: membershipTrialExpiresAt) { _ in
            restartMembershipClockForEntitlementChange()
        }
        .onChange(of: membershipActive) { _ in
            restartMembershipClockForEntitlementChange()
        }
        .onChange(of: newEpisodeAlertPresentationScopeRaw) { _ in
            if episodeAlertPresentationAllowedOnCurrentSurface {
                if let active = activeNewEpisodeAlert {
                    prepareAlertPresentation(for: active)
                } else {
                    presentNextQueuedNewEpisodeAlertIfPossible(delaySeconds: 0)
                }
            }
        }
        .onChange(of: newEpisodeAlertScanFrequencyMinutesRaw) { _ in
            // Selecting 1/5/10/30 minutes always creates a new countdown from now.
            // If entitlement or scene activation is still pending, the rearm request
            // remains latched and starts automatically when eligibility becomes true.
            rearmNewEpisodeAlertSchedulerFromNow(reason: "frequency changed")
        }
        .onChange(of: rootFollowedShowIdsRaw) { _ in
            // A newly followed show receives a complete selected interval. This avoids
            // inheriting the prior show's almost-expired deadline.
            rearmNewEpisodeAlertSchedulerFromNow(reason: "follow list changed")
        }
        .onChange(of: followAlertsEnabled) { enabled in
            if enabled {
                rearmNewEpisodeAlertSchedulerFromNow(reason: "follow alerts enabled")
            } else {
                stopNewEpisodeHeartbeat(reason: "follow alerts disabled")
            }
        }
        .onChange(of: followNewEpisodesEnabled) { enabled in
            if enabled {
                rearmNewEpisodeAlertSchedulerFromNow(reason: "new episode alerts enabled")
            } else {
                stopNewEpisodeHeartbeat(reason: "new episode alerts disabled")
            }
        }
    }

    private var visionPlaybackSurfaceAllowed: Bool {
        // Clean-reset build: no immersive playback owner exists yet.
        // Keep the ordinary app playback path independent of the new immersive foundation.
        return true
    }

    var body: some View {
        rootStateObservationTree
    }
    @MainActor
    private func applyGuideStartupPreferenceIfNeeded(reason: String) {
        guard guideStartupPreferenceAtLaunch == true,
              !didApplyGuideStartupPreference,
              !membershipLocked,
              store.playbackURL == nil else { return }

        didApplyGuideStartupPreference = true
        guideStartupTask?.cancel()
        store.searchActive = false
        store.selectedDetail = nil
        store.liveQuickPanelOpen = false
        store.selectedTab = .live

        guideStartupTask = Task { @MainActor in
            await Task.yield()
            do {
                try await Task.sleep(nanoseconds: 300_000_000)
            } catch {
                guideStartupTask = nil
                return
            }
            guard !Task.isCancelled,
                  guideStartupPreferenceAtLaunch == true,
                  store.playbackURL == nil,
                  store.selectedTab == .live else {
                guideStartupTask = nil
                return
            }
            store.guideStartupRequestToken &+= 1
            guideStartupTask = nil
            print("[GuideStartup][v1082] opened full guide reason=\(reason)")
        }
    }

    @MainActor
    private func startCatalogCompletenessWatchdogIfNeeded() {
        guard scenePhase == .active,
              store.playbackURL == nil,
              !store.vodExclusivePlaybackActive,
              UnitySurfaceSystem.catalogBranchActive(for: store.selectedTab),
              unityLifecycle.permitsNonessentialBackgroundWork,
              store.catalogCompletenessNeedsRecovery,
              catalogCompletenessWatchdogTask == nil else { return }

        // vBRDC004: completeness recovery is event-driven after the initial protected-cache
        // check. The former permanent 12-second MainActor loop could wake during Live TV,
        // catalog navigation, and full-screen channel playback. Row-count changes and scene
        // activation already re-arm recovery, so a repeating process-lifetime poll is redundant.
        catalogCompletenessWatchdogTask = Task { @MainActor in
            do {
                try await Task.sleep(nanoseconds: 1_500_000_000)
            } catch {
                catalogCompletenessWatchdogTask = nil
                return
            }
            guard !Task.isCancelled,
                  scenePhase == .active,
                  store.playbackURL == nil,
                  !store.vodExclusivePlaybackActive else {
                catalogCompletenessWatchdogTask = nil
                return
            }
            await store.ensureDebridChannelsCatalogCompleteness(reason: "initial/event-driven watchdog")
            catalogCompletenessWatchdogTask = nil
        }
    }

    @MainActor
    private func stopCatalogCompletenessWatchdog() {
        catalogCompletenessWatchdogTask?.cancel()
        catalogCompletenessWatchdogTask = nil
    }

    @MainActor
    private func schedulePostPlaybackExitRecovery(reason: String) {
        postPlaybackExitRecoveryTask?.cancel()
        catalogInteractionRecoveryTask?.cancel()
        catalogInteractionRecoveryTask = nil

        let returningToLiveTV = store.liveTVFocusSnapshot != nil
        postPlaybackExitRecoveryTask = Task { @MainActor in
            if returningToLiveTV {
                // vBRDC105: Live TV already has a precise store-owned channel/category/window
                // snapshot. One post-mount focus nudge is enough; the old four checkpoints
                // repeatedly rebuilt focus and fired catalog artwork recovery for ~630 ms,
                // which made the newly visible guide feel frozen. No catalog rehydration is
                // permitted on this fast lane.
                await Task.yield()
                try? await Task.sleep(nanoseconds: 32_000_000)
                guard !Task.isCancelled,
                      scenePhase == .active,
                      store.playbackURL == nil,
                      store.liveTVFocusSnapshot != nil else {
                    postPlaybackExitRecoveryTask = nil
                    return
                }
                store.liveTVFocusRestoreToken &+= 1

                // Resume optional root/network owners only after the grid has had several
                // render turns to bind. This work is intentionally not part of focus restore.
                try? await Task.sleep(nanoseconds: 220_000_000)
                guard !Task.isCancelled, scenePhase == .active, store.playbackURL == nil else {
                    postPlaybackExitRecoveryTask = nil
                    return
                }
                mediaFlowConnection.refresh(reason: "returned from Live TV playback", showBanner: true, allowFreshReuse: false)
                resumeNonAlertRootWorkAfterVOD()
                startCatalogCompletenessWatchdogIfNeeded()
                postPlaybackExitRecoveryTask = nil
                return
            }

            // vBRDC078: VOD dismissal is a strict ownership handoff. Let the player view
            // leave first, then repeatedly restore the mounted focus tree before restarting
            // background catalog/entitlement/alert work. Repeated checkpoints are cheap and
            // cover tvOS devices that mount the focused rail one or two render turns later.
            await Task.yield()
            let delays: [UInt64] = [35_000_000, 95_000_000, 180_000_000, 320_000_000]
            for (index, delay) in delays.enumerated() {
                try? await Task.sleep(nanoseconds: delay)
                guard !Task.isCancelled,
                      scenePhase == .active,
                      store.playbackURL == nil,
                      !store.vodExclusivePlaybackActive,
                      !VODExclusivePlaybackGate.isActive else {
                    postPlaybackExitRecoveryTask = nil
                    return
                }

                store.recoverCatalogInteractivity(reason: "\(reason) checkpoint \(index + 1)")
                if store.liveTVFocusSnapshot != nil {
                    store.liveTVFocusRestoreToken &+= 1
                }
                // vBRDC099: the first render turn can happen before remounted LazyHStack/
                // LiveTV tile image owners exist. A second bounded artwork pass at the 95 ms
                // checkpoint catches those newly mounted owners without a repeating timer.
                if index == 1 {
                    _ = store.forceVisibleCatalogReadiness(reason: "\(reason) post-playback readiness")
                    PremiumArtworkRehydrationCoordinator.shared.force(reason: "\(reason) post-playback checkpoint")
                    // A VOD exit to Home/Movies/Shows must not revive the
                    // persistent Live TV grid behind that catalog after 95 ms.
                    if store.selectedTab == .live {
                        LiveTVBoundedArtworkLoader.resumeRetainedRequests()
                    }
                }
                await Task.yield()
            }

            guard !Task.isCancelled, scenePhase == .active, store.playbackURL == nil else {
                postPlaybackExitRecoveryTask = nil
                return
            }

            // Only after the remote/focus tree has had several opportunities to bind do
            // optional network and scheduler owners come back online.
            mediaFlowConnection.refresh(reason: "returned from playback", showBanner: true, allowFreshReuse: false)
            resumeNonAlertRootWorkAfterVOD()
            startCatalogCompletenessWatchdogIfNeeded()
            postPlaybackExitRecoveryTask = nil
        }
    }

    @MainActor
    private func synchronizeUnityCatalogBranchPresentation(from oldTab: AppTab, to newTab: AppTab) {
        let oldWasCatalog = UnitySurfaceSystem.catalogBranchActive(for: oldTab)
        let newIsCatalog = UnitySurfaceSystem.catalogBranchActive(for: newTab)

        unityCatalogTransitionTask?.cancel()
        unityCatalogTransitionTask = nil

        if newIsCatalog {
            // vBRDC104: the persistent hidden shell switches its branch identity before the
            // visible handoff begins, so Home/Movies/Shows never mount a fresh catalog tree.
            unityPersistentCatalogTab = newTab
            // Catalog-to-catalog changes keep one branch shell at full presentation. Only
            // the row/filter content changes; there is no root teardown or artificial fade.
            unityPresentedCatalogTab = newTab
            if oldWasCatalog {
                unityCatalogBranchTransitionActive = false
                unityCatalogBranchProgress = 1
                return
            }

            // vBRDC109: enter a hidden preflight with the rail already visually focused.
            // The card does not grow/bounce while the surface is appearing; only the branch
            // compositor is allowed to move during the visible transaction.
            unityCatalogBranchTransitionActive = true
            unityCatalogBranchProgress = 0
            let frameProfile = UnityFrameRuntime.shared.catalogTransitionProfile(
                leavingCatalogForLiveRoot: false,
                enteringCatalogFromLiveRoot: true
            )
            unityCatalogTransitionTask = Task { @MainActor in
                // vBRDC102: the one frame runtime owns preflight, visible motion and settle.
                // Cached/provisional art binds behind opacity 0; no theme-specific timing
                // owner is allowed to wake independently during this transaction.
                await Task.yield()
                try? await Task.sleep(nanoseconds: UnityFrameRuntime.nanoseconds(frameProfile.preflight))
                guard !Task.isCancelled, UnitySurfaceSystem.catalogBranchActive(for: store.selectedTab) else { return }
                withAnimation(.timingCurve(0.16, 1.0, 0.30, 1.0, duration: frameProfile.visibleDuration)) {
                    unityCatalogBranchProgress = 1
                }
                try? await Task.sleep(nanoseconds: UnityFrameRuntime.nanoseconds(frameProfile.branchSettle))
                guard !Task.isCancelled else { return }
                unityCatalogBranchTransitionActive = false
                unityCatalogTransitionTask = nil
            }
            return
        }

        guard oldWasCatalog else {
            unityPresentedCatalogTab = nil
            unityCatalogBranchProgress = 0
            unityCatalogBranchTransitionActive = false
            return
        }

        // vBRDC133: Catalog -> Live/Sports/dedicated must never resurrect a branch that
        // Back/Menu already dismissed. vBRDC132 forced progress 0 -> 1 -> 0 whenever the
        // previous selected tab was a catalog, which produced a one-frame row flash when
        // Down returned from the top menu to the persistent Live TV grid. If the compositor
        // branch is already invisible, clear stale presentation ownership and hand off
        // directly. If it is genuinely still visible, reverse smoothly from its *current*
        // progress without jumping back to full opacity.
        if unityCatalogBranchProgress <= 0.001 {
            unityPresentedCatalogTab = nil
            unityCatalogBranchProgress = 0
            unityCatalogBranchTransitionActive = false
            return
        }
        if unityPresentedCatalogTab == nil { unityPresentedCatalogTab = oldTab }
        // vBRDC109: pin catalog focus geometry for the complete visible close. selectedTab
        // changes immediately for routing, but the outgoing card is not allowed to shrink or
        // replay focus motion until opacity has reached zero.
        unityCatalogBranchTransitionActive = true
        let frameProfile = UnityFrameRuntime.shared.catalogTransitionProfile(
            leavingCatalogForLiveRoot: true,
            enteringCatalogFromLiveRoot: false
        )
        withAnimation(.timingCurve(0.32, 0.0, 0.22, 1.0, duration: frameProfile.visibleDuration)) {
            unityCatalogBranchProgress = 0
        }
        unityCatalogTransitionTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: UnityFrameRuntime.nanoseconds(frameProfile.branchSettle))
            guard !Task.isCancelled, !UnitySurfaceSystem.catalogBranchActive(for: store.selectedTab) else { return }
            unityPresentedCatalogTab = nil
            unityCatalogBranchProgress = 0
            unityCatalogBranchTransitionActive = false
            unityCatalogTransitionTask = nil
        }
    }

    @MainActor
    private func synchronizeUnityCatalogMenuPresentation(presented: Bool) {
        guard UnitySurfaceSystem.catalogBranchActive(for: store.selectedTab),
              store.playbackURL == nil else { return }

        let tab = store.selectedTab

        // A selected-tab handoff may already be opening/closing this exact branch. Do not
        // restart that transition merely because the explicit presentation bit caught up.
        if presented,
           unityPresentedCatalogTab == tab,
           unityCatalogBranchTransitionActive {
            return
        }

        unityCatalogTransitionTask?.cancel()
        unityCatalogTransitionTask = nil

        if presented {
            unityPersistentCatalogTab = tab
            unityPresentedCatalogTab = tab

            if unityCatalogBranchProgress >= 0.999, !unityCatalogBranchTransitionActive {
                unityCatalogBranchProgress = 1
                return
            }

            unityCatalogBranchTransitionActive = true
            let frameProfile = UnityFrameRuntime.shared.catalogTransitionProfile(
                leavingCatalogForLiveRoot: false,
                enteringCatalogFromLiveRoot: true
            )

            unityCatalogTransitionTask = Task { @MainActor in
                await Task.yield()
                try? await Task.sleep(nanoseconds: UnityFrameRuntime.nanoseconds(frameProfile.preflight))
                guard !Task.isCancelled,
                      store.catalogRowsPresented,
                      store.selectedTab == tab else { return }
                withAnimation(.timingCurve(0.16, 1.0, 0.30, 1.0, duration: frameProfile.visibleDuration)) {
                    unityCatalogBranchProgress = 1
                }
                try? await Task.sleep(nanoseconds: UnityFrameRuntime.nanoseconds(frameProfile.branchSettle))
                guard !Task.isCancelled,
                      store.catalogRowsPresented,
                      store.selectedTab == tab else { return }
                unityCatalogBranchTransitionActive = false
                unityCatalogTransitionTask = nil
            }
            return
        }

        // Back/Menu from Home/Movies/TV Shows closes only the visible catalog branch.
        // Keep selectedTab unchanged so the same category remains highlighted in the top
        // menu. Keep the outgoing catalog mounted and visually focused until the reverse
        // motion is completely invisible, then give the menu the one focus token.
        if unityPresentedCatalogTab == nil {
            unityPresentedCatalogTab = tab
        }
        if unityCatalogBranchProgress <= 0.001 {
            unityCatalogBranchProgress = 0
            unityPresentedCatalogTab = nil
            unityCatalogBranchTransitionActive = false
            store.menuFocusToken &+= 1
            return
        }

        unityCatalogBranchTransitionActive = true
        let frameProfile = UnityFrameRuntime.shared.catalogTransitionProfile(
            leavingCatalogForLiveRoot: true,
            enteringCatalogFromLiveRoot: false
        )
        withAnimation(.timingCurve(0.32, 0.0, 0.22, 1.0, duration: frameProfile.visibleDuration)) {
            unityCatalogBranchProgress = 0
        }

        unityCatalogTransitionTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: UnityFrameRuntime.nanoseconds(frameProfile.branchSettle))
            guard !Task.isCancelled,
                  !store.catalogRowsPresented,
                  store.selectedTab == tab else { return }
            unityPresentedCatalogTab = nil
            unityCatalogBranchProgress = 0
            unityCatalogBranchTransitionActive = false
            unityCatalogTransitionTask = nil
            store.menuFocusToken &+= 1
        }
    }

    @MainActor
    private func scheduleUnitySurfaceHandoff(from oldTab: AppTab, to newTab: AppTab, reason: String) {
        guard oldTab != newTab, store.playbackURL == nil else { return }

        unitySurfaceHandoffTask?.cancel()
        let generation = unityLifecycle.beginTabHandoff(from: oldTab, to: newTab, reason: reason)
        unityAnimations.setSurfaceHandoffActive(true)

        // Do not let a delayed completeness pass race an outgoing Sports/Favorites tree
        // against the incoming catalog focus tree. This task is event-driven and safe to rearm.
        stopCatalogCompletenessWatchdog()

        // Reset ownership flags immediately, but do not fire a content-focus token on the
        // same render turn as the outgoing surface. The first token belongs to the mounted
        // destination, never to a view that is in the process of disappearing.
        store.liveQuickPanelOpen = false
        store.topMenuFocusLocked = false
        // vBRDC128: a top-menu click changes the selected surface without implicitly
        // moving focus into its content. This is a narrow recovery suppression only; it
        // does not alter the destination focus graph. Down from the menu clears the hold.
        let topMenuSelectionHeld = store.topMenuSelectionHoldTab == newTab

        let leavingCatalogForLiveRoot = UnitySurfaceSystem.catalogBranchActive(for: oldTab) && (newTab == .live || newTab == .sports)
        let enteringCatalogFromLiveRoot = (oldTab == .live || oldTab == .sports) && UnitySurfaceSystem.catalogBranchActive(for: newTab)
        // vBRDC101: bind the incoming catalog focus while the branch is still in its
        // 24 ms invisible preflight. Previously the focus token landed ~80 ms into the
        // visible open animation, so the selected card could snap from preview geometry
        // into its large focused poster mid-transition. On both open and close, keep
        // ambient/perpetual work isolated slightly beyond the branch's final motion frame.
        let frameProfile = UnityFrameRuntime.shared.catalogTransitionProfile(
            leavingCatalogForLiveRoot: leavingCatalogForLiveRoot,
            enteringCatalogFromLiveRoot: enteringCatalogFromLiveRoot
        )
        let firstCheckpointDelay = UnityFrameRuntime.nanoseconds(frameProfile.focusBind)
        let secondCheckpointDelay = UnityFrameRuntime.nanoseconds(frameProfile.focusSettle)
        let ambientResumeDelay = UnityFrameRuntime.nanoseconds(frameProfile.ambientTail)

        unitySurfaceHandoffTask = Task { @MainActor in
            // First checkpoint: on catalog Back, wait until the visible branch is mostly
            // through its reverse motion before restoring Live TV focus. Entry can bind the
            // catalog rail early while it is still fading/sliding over the persistent root.
            await Task.yield()
            try? await Task.sleep(nanoseconds: firstCheckpointDelay)
            guard !Task.isCancelled,
                  scenePhase == .active,
                  store.playbackURL == nil,
                  generation == unityLifecycle.generation else { return }
            if !topMenuSelectionHeld,
               (newTab == .home || newTab == .movies || newTab == .shows || newTab == .sports || newTab == .favorites || newTab == .live) {
                store.contentFocusToken &+= 1
            }

            // Second checkpoint: tvOS focus engine has a stable focusable destination.
            try? await Task.sleep(nanoseconds: secondCheckpointDelay)
            guard !Task.isCancelled,
                  scenePhase == .active,
                  store.playbackURL == nil,
                  generation == unityLifecycle.generation else { return }
            store.topMenuFocusLocked = false
            // Dedicated surfaces unmount the shared Live TV/catalog tree. They receive one
            // additional bounded checkpoint after remount; shared-root Sports/Live handoffs
            // deliberately avoid redundant focus-token churn.
            let returningFromDedicatedSurface = oldTab == .favorites || oldTab == .settings || oldTab == .membership
            if !topMenuSelectionHeld,
               returningFromDedicatedSurface,
               (newTab == .home || newTab == .movies || newTab == .shows || newTab == .favorites || newTab == .live) {
                store.contentFocusToken &+= 1
            }

            // Only now may perpetual/ambient animation and nonessential root work resume.
            try? await Task.sleep(nanoseconds: ambientResumeDelay)
            guard !Task.isCancelled,
                  scenePhase == .active,
                  store.playbackURL == nil,
                  generation == unityLifecycle.generation else { return }
            unityLifecycle.finishTabHandoff(generation: generation, reason: "settled \(reason)")
            unityAnimations.setSurfaceHandoffActive(false)
            // vBRDC101: ordinary Live/Sports <-> catalog navigation is not an artwork
            // recovery event. vBRDC099's global blank-loader sweep here released a burst of
            // network/decode/publication work on the exact final animation frame. Playback
            // return and real completeness failures retain their dedicated recovery lanes.
            startCatalogCompletenessWatchdogIfNeeded()

            if mediaFlowWasInSettings && newTab != .settings {
                mediaFlowWasInSettings = false
                mediaFlowConnection.refresh(reason: "returned from Settings", showBanner: true, allowFreshReuse: false)
            }
            unitySurfaceHandoffTask = nil
        }
    }

    @MainActor
    private func scheduleCatalogInteractionRecovery(reason: String) {
        catalogInteractionRecoveryTask?.cancel()
        catalogInteractionRecoveryTask = Task { @MainActor in
            // First turn lets the player view disappear and the catalog hierarchy mount.
            await Task.yield()
            try? await Task.sleep(nanoseconds: 300_000_000)
            guard !Task.isCancelled,
                  scenePhase == .active,
                  store.playbackURL == nil else { return }

            store.recoverCatalogInteractivity(reason: reason)

            // A second token after the focusable rail exists handles tvOS focus-engine
            // restoration after long inactivity/screen saver suspension.
            await Task.yield()
            try? await Task.sleep(nanoseconds: 140_000_000)
            guard !Task.isCancelled,
                  scenePhase == .active,
                  store.playbackURL == nil else { return }
            store.contentFocusToken &+= 1
            catalogInteractionRecoveryTask = nil
        }
    }

    @MainActor
    private func startMembershipClockIfAllowed() {
        guard scenePhase == .active, !store.vodExclusivePlaybackActive, membershipClockTask == nil else { return }
        membershipClockTask = Task { @MainActor in
            // vBRDC002 resource-lifecycle correction: membership lock state is not a
            // visible one-second clock. The previous loop mutated RootView state every
            // second on every screen for the lifetime of the app. Evaluate once now, then
            // sleep directly to the only time-based transition that matters: trial expiry.
            let now = Date()
            membershipClockNow = now
            MembershipEntitlementManager.markExpiredIfNeeded(now: now)
            if membershipLocked && store.selectedTab != .membership { store.selectedTab = .membership }

            let status = ProductionEntitlementStatus(rawBackendValue: membershipEntitlementStatus)
            guard status == .trialActive,
                  let expiry = membershipTrialExpiryDate,
                  expiry > now,
                  !Task.isCancelled,
                  !store.vodExclusivePlaybackActive else {
                membershipClockTask = nil
                return
            }

            let delay = max(0.20, expiry.timeIntervalSince(now) + 0.08)
            do {
                try await Task.sleep(nanoseconds: UInt64(delay * 1_000_000_000))
            } catch {
                membershipClockTask = nil
                return
            }
            guard !Task.isCancelled, scenePhase == .active, !store.vodExclusivePlaybackActive else {
                membershipClockTask = nil
                return
            }

            let expiryNow = Date()
            membershipClockNow = expiryNow
            MembershipEntitlementManager.markExpiredIfNeeded(now: expiryNow)
            if membershipLocked && store.selectedTab != .membership { store.selectedTab = .membership }
            membershipClockTask = nil
        }
    }

    @MainActor
    private func restartMembershipClockForEntitlementChange() {
        membershipClockTask?.cancel()
        membershipClockTask = nil
        membershipClockNow = Date()
        startMembershipClockIfAllowed()
    }

    @MainActor
    private func startAppBootstrapIfNeeded() {
        guard scenePhase == .active, !store.vodExclusivePlaybackActive, !didRequestDefaultCatalogLoad, appBootstrapTask == nil else { return }
        appBootstrapTask = Task { @MainActor in
            await store.loadAllManifests()
            guard !Task.isCancelled, !store.vodExclusivePlaybackActive else {
                appBootstrapTask = nil
                return
            }
            let repairedFollowSnapshots = store.repairFollowedShowSnapshotsFromLoadedRows()
            // vBRDC091: the global sports model exists only for the optional score ticker.
            // When that ticker is Off (the default), do not spend launch CPU/network/memory
            // building sports schedules that have no visible consumer. SportsHub owns its
            // own short-lived model only while the Sports surface is actually open.
            if sportsScoreTickerEnabled {
                await globalSportsLiveZone.load(favoriteTeams: sportsFavoriteTeams, xtreamAccounts: "", customSources: sportsCustomSourcesForTicker)
            }
            guard !Task.isCancelled, !store.vodExclusivePlaybackActive else {
                appBootstrapTask = nil
                return
            }
            didRequestDefaultCatalogLoad = true
            appBootstrapTask = nil
            recoverEpisodeAlertSchedulerAfterCatalogLoad(repairedSnapshots: repairedFollowSnapshots)
        }
    }

    @MainActor
    private func recoverEpisodeAlertSchedulerAfterCatalogLoad(repairedSnapshots: Int) {
        guard scenePhase == .active,
              followAlertsEnabled,
              followNewEpisodesEnabled,
              !membershipLocked,
              !rootFollowedShowIdsRaw.isEmpty else {
            activateNewEpisodeAlertScheduler(reason: "catalog load complete")
            return
        }
        let schedule = NewEpisodeAlertsManager.loadScheduleState()
        let needsReliabilityCatchUp = repairedSnapshots > 0
            || schedule.lastSuccessAt == nil
            || schedule.consecutiveFailureCount > 0
        guard needsReliabilityCatchUp else {
            activateNewEpisodeAlertScheduler(reason: "catalog load complete")
            return
        }
        stopNewEpisodeHeartbeat(reason: "catalog identity/snapshot recovery")
        restartNewEpisodeHeartbeat(
            reason: repairedSnapshots > 0 ? "follow snapshot repaired after catalog load" : "episode alert reliability catch-up",
            runImmediateScan: true,
            resetCountdown: false
        )
    }

    @MainActor
    private func suspendRootWorkForInactiveScene() {
        membershipClockTask?.cancel()
        membershipClockTask = nil
        appBootstrapTask?.cancel()
        appBootstrapTask = nil
        entitlementSyncTask?.cancel()
        entitlementSyncTask = nil
        entitlementSyncRunning = false
        newEpisodeScannerVerificationTask?.cancel()
        newEpisodeScannerVerificationTask = nil
        newEpisodeScannerVerificationRunning = false
        // vBRDC002: scene suspension is a safe point to discard Live TV display-sized
        // artwork retained by the still-mounted Artwork 3 grid. It will reload on demand
        // after activation instead of surviving indefinitely across sleep/screensaver cycles.
        LiveTVBoundedArtworkLoader.releaseTransientResources(
            reason: "scene inactive",
            preserveVisibleRequests: true,
            preservePlaybackReturnCache: true
        )
    }

    @MainActor
    private func resumeRootWorkAfterInactiveScene() {
        guard !store.vodExclusivePlaybackActive else { return }
        startMembershipClockIfAllowed()
        startAppBootstrapIfNeeded()
    }

    @MainActor
    private func suspendNonAlertRootWorkForVOD() {
        // vBRDC208: Episode Alerts are an explicitly playback-visible feature. Keep the single
        // low-frequency heartbeat alive during both VOD and Live TV so a newly released episode
        // can be discovered and presented without forcing the viewer to leave playback. All other
        // non-alert root work still yields the frame budget below.
        membershipClockTask?.cancel()
        membershipClockTask = nil
        appBootstrapTask?.cancel()
        appBootstrapTask = nil
        entitlementSyncTask?.cancel()
        entitlementSyncTask = nil
        entitlementSyncRunning = false
        newEpisodeScannerVerificationTask?.cancel()
        newEpisodeScannerVerificationTask = nil
        newEpisodeScannerVerificationRunning = false
        newEpisodeScannerVerificationReport = nil
        globalSportsLiveZone.suspendForVODPlayback()
    }

    @MainActor
    private func resumeNonAlertRootWorkAfterVOD() {
        startMembershipClockIfAllowed()
        startAppBootstrapIfNeeded()
        if scenePhase == .active {
            syncProductionEntitlement(reason: "playback ended")
            activateNewEpisodeAlertScheduler(reason: "playback ended")
        }
        if let pending = pendingEpisodeAlertOpenIntent, store.playbackURL == nil {
            store.openDetail(pending.show)
        }
        if let active = activeNewEpisodeAlert {
            prepareAlertPresentation(for: active)
        } else {
            presentNextQueuedNewEpisodeAlertIfPossible(delaySeconds: 0)
        }
    }

    private func syncProductionEntitlement(reason: String) {
        guard !entitlementSyncRunning else { return }
        guard let context = MembershipEntitlementManager.entitlementRequestContext(backendBaseURLString: backendBaseURLString) else {
            membershipActive = false
            if membershipEntitlementStatus.isEmpty {
                membershipEntitlementStatus = ProductionEntitlementStatus.unknown.rawValue
            }
            return
        }
        guard !store.vodExclusivePlaybackActive else { return }
        entitlementSyncRunning = true
        entitlementSyncTask?.cancel()
        entitlementSyncTask = Task {
            do {
                let result = try await ProductionEntitlementService.fetchStatus(backendBaseURL: context.backendBaseURL, deviceId: context.deviceId, deviceName: context.deviceName)
                guard !Task.isCancelled else { return }
                await MainActor.run {
                    guard !store.vodExclusivePlaybackActive else {
                        entitlementSyncRunning = false
                        entitlementSyncTask = nil
                        return
                    }
                    applyProductionEntitlement(result)
                    entitlementSyncRunning = false
                    entitlementSyncTask = nil
                    if membershipLocked && store.selectedTab != .membership { store.selectedTab = .membership }
                }
            } catch {
                guard !Task.isCancelled else { return }
                await MainActor.run {
                    guard !store.vodExclusivePlaybackActive else {
                        entitlementSyncRunning = false
                        entitlementSyncTask = nil
                        return
                    }
                    entitlementSyncRunning = false
                    entitlementSyncTask = nil
                    if membershipEntitlementStatus.isEmpty || membershipEntitlementStatus == ProductionEntitlementStatus.unknown.rawValue {
                        membershipActive = false
                        membershipEntitlementStatus = ProductionEntitlementStatus.locked.rawValue
                    }
                    if membershipLocked && store.selectedTab != .membership { store.selectedTab = .membership }
                }
            }
        }
    }

    @MainActor
    private func applyProductionEntitlement(_ result: ProductionEntitlementResult) {
        let applied = MembershipEntitlementManager.apply(
            result: result,
            currentTrialStartedAt: membershipTrialStartedAt,
            currentTrialExpiresAt: membershipTrialExpiresAt
        )
        membershipActive = applied.membershipActive
        membershipEntitlementStatus = applied.entitlementStatus
        membershipPlanType = applied.planType
        membershipTrialStartedAt = applied.trialStartedAt
        membershipTrialExpiresAt = applied.trialExpiresAt
        if membershipLocked {
            stopNewEpisodeHeartbeat(reason: "entitlement locked")
        } else {
            activateNewEpisodeAlertScheduler(reason: "entitlement ready")
        }
    }

    @MainActor
    private func rearmNewEpisodeAlertSchedulerFromNow(reason: String) {
        episodeAlertNeedsFreshLaunchCountdown = true
        stopNewEpisodeHeartbeat(reason: "rearming: \(reason)")
        activateNewEpisodeAlertScheduler(reason: reason)
    }

    @MainActor
    private func activateNewEpisodeAlertScheduler(reason: String) {
        guard scenePhase == .active,
              followAlertsEnabled,
              followNewEpisodesEnabled,
              !membershipLocked else {
            return
        }
        guard newEpisodeHeartbeatTask == nil || !newEpisodeHeartbeatTaskActive else {
            return
        }

        if episodeAlertNeedsFreshLaunchCountdown {
            episodeAlertNeedsFreshLaunchCountdown = false
            restartNewEpisodeHeartbeat(reason: reason, runImmediateScan: false, resetCountdown: true)
        } else {
            restartNewEpisodeHeartbeat(
                reason: reason,
                runImmediateScan: shouldRunImmediateEpisodeAlertCatchUp(),
                resetCountdown: false
            )
        }
    }

    private func shouldRunImmediateEpisodeAlertCatchUp(now: Date = Date()) -> Bool {
        let storedNext = NewEpisodeAlertsManager.persistedNextScanAt()
        if newEpisodeAlertScanFrequency == .oneMinuteTest, storedNext == nil {
            return false
        }
        return NewEpisodeAlertsManager.shouldRunImmediateCatchUp(now: now, storedNext: storedNext)
    }

    @MainActor
    private func restartNewEpisodeHeartbeat(reason: String, runImmediateScan: Bool, resetCountdown: Bool = false) {
        guard scenePhase == .active,
              followAlertsEnabled,
              followNewEpisodesEnabled,
              !membershipLocked else {
            stopNewEpisodeHeartbeat(reason: reason)
            return
        }
        if newEpisodeHeartbeatTaskActive, newEpisodeHeartbeatTask != nil {
            duplicateNewEpisodeHeartbeatPreventedCount += 1
        }
        newEpisodeHeartbeatGeneration += 1
        let generation = newEpisodeHeartbeatGeneration
        newEpisodeHeartbeatTask?.cancel()
        activeNewEpisodeHeartbeatIntervalSeconds = NewEpisodeAlertsManager.selectedScanFrequencySeconds()
        newEpisodeHeartbeatTaskActive = true

        let now = Date()
        let storedNext = resetCountdown ? nil : NewEpisodeAlertsManager.persistedNextScanAt()
        var delay = NewEpisodeAlertsManager.initialHeartbeatDelay(
            now: now,
            storedNext: storedNext,
            intervalSeconds: activeNewEpisodeHeartbeatIntervalSeconds,
            runImmediateScan: runImmediateScan
        )
        nextNewEpisodeHeartbeatScanAt = now.addingTimeInterval(delay)
        NewEpisodeAlertsManager.recordDeadline(
            nextNewEpisodeHeartbeatScanAt ?? now,
            frequencyRawValue: NewEpisodeAlertsManager.selectedScanFrequencyRawValue()
        )
        print("[EpisodeAlerts][v970] armed reason=\(reason) frequency=\(NewEpisodeAlertsManager.selectedScanFrequencyRawValue())m delay=\(Int(delay))s deadline=\(NewEpisodeAlertsManager.scheduleFormatter.string(from: nextNewEpisodeHeartbeatScanAt ?? now))")

        newEpisodeHeartbeatTask = Task(priority: .utility) { @MainActor in
            var fireReason = reason
            while !Task.isCancelled {
                if delay > 0 {
                    do {
                        try await Task.sleep(nanoseconds: NewEpisodeAlertsManager.sleepNanoseconds(for: delay))
                    } catch {
                        break
                    }
                }
                guard !Task.isCancelled,
                      generation == newEpisodeHeartbeatGeneration,
                      scenePhase == .active,
                      followAlertsEnabled,
                      followNewEpisodesEnabled,
                      !membershipLocked else { break }

                delay = await fireNewEpisodeHeartbeat(generation: generation, reason: fireReason)
                guard !Task.isCancelled, generation == newEpisodeHeartbeatGeneration else { break }
                fireReason = "heartbeat"
                activeNewEpisodeHeartbeatIntervalSeconds = Int(delay)
                nextNewEpisodeHeartbeatScanAt = Date().addingTimeInterval(delay)
                NewEpisodeAlertsManager.recordDeadline(
                    nextNewEpisodeHeartbeatScanAt ?? Date(),
                    frequencyRawValue: NewEpisodeAlertsManager.selectedScanFrequencyRawValue()
                )
            }
            if generation == newEpisodeHeartbeatGeneration {
                newEpisodeHeartbeatTaskActive = false
                newEpisodeHeartbeatTask = nil
                nextNewEpisodeHeartbeatScanAt = NewEpisodeAlertsManager.persistedNextScanAt()
            }
        }
    }

    @MainActor
    private func stopNewEpisodeHeartbeat(reason: String) {
        newEpisodeHeartbeatGeneration += 1
        newEpisodeHeartbeatTask?.cancel()
        newEpisodeHeartbeatTask = nil
        newEpisodeHeartbeatTaskActive = false
        activeNewEpisodeHeartbeatIntervalSeconds = 0
        nextNewEpisodeHeartbeatScanAt = NewEpisodeAlertsManager.persistedNextScanAt()
        lastNewEpisodeScanReason = reason
    }

    @MainActor
    private func fireNewEpisodeHeartbeat(generation: Int, reason: String) async -> TimeInterval {
        guard generation == newEpisodeHeartbeatGeneration else {
            return TimeInterval(NewEpisodeAlertsManager.selectedScanFrequencySeconds())
        }
        lastNewEpisodeHeartbeatFiredAt = Date()
        lastNewEpisodeScanReason = reason
        activeNewEpisodeHeartbeatIntervalSeconds = NewEpisodeAlertsManager.selectedScanFrequencySeconds()
        return await runRealEpisodeAlertScan(reason: reason)
    }

    @ViewBuilder
    private var realNewEpisodeAlertLayer: some View {
        // vBRDC192: full-screen VOD and Live TV render the same passive Episode Alert
        // banner inside VODPlayerScreen's own ZStack. This root layer is reserved for
        // non-playback surfaces so a UIKit-backed video surface cannot occlude it.
        if store.playbackURL == nil, let alert = activeNewEpisodeAlert, episodeAlertPresentationAllowedOnCurrentSurface {
            switch effectiveNewEpisodeAlertStyle {
            case .banner:
                RootNewEpisodeAlertBanner(
                    showTitle: alert.show.title,
                    showPosterURL: alert.show.posterURL ?? "",
                    episode: alert.episode,
                    side: newEpisodeAlertBannerSide,
                    theme: newEpisodeAlertTheme
                )
                .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: newEpisodeAlertBannerSide.alignment)
                .padding(newEpisodeAlertBannerSide.verticalEdgeSet, newEpisodeAlertBannerVerticalPadding)
                .padding(newEpisodeAlertBannerSide.horizontalEdgeSet, newEpisodeAlertScreenEdgeInset)
                .allowsHitTesting(false)
                .transition(.asymmetric(
                    insertion: .move(edge: newEpisodeAlertBannerSide.transitionEdge).combined(with: .opacity),
                    removal: .move(edge: newEpisodeAlertBannerSide.transitionEdge).combined(with: .opacity)
                ))
                .animation(.spring(response: 0.48, dampingFraction: 0.86), value: activeNewEpisodeAlert?.id)
                .onAppear { confirmEpisodeAlertPresentation(alert) }
                .zIndex(9600)
            case .interactivePopup:
                RootNewEpisodeInteractivePopup(
                    showTitle: alert.show.title,
                    showPosterURL: alert.show.posterURL ?? "",
                    episode: alert.episode,
                    selectedAction: activeNewEpisodeAlertFocus,
                    theme: newEpisodeAlertTheme
                )
                .signalVisionFocusSection()
                .focusable(true)
                .focused($activeNewEpisodeAlertFocused)
                .signalMoveCommand { direction in
                    routeRealEpisodeAlert(direction)
                }
                .onTapGesture { activateRealEpisodeAlert() }
                .signalVisionPlayPauseCommand { activateRealEpisodeAlert() }
                .signalVisionExitCommand { dismissRealEpisodeAlert(consume: false) }
                .onAppear {
                    confirmEpisodeAlertPresentation(alert)
                    activeNewEpisodeAlertFocused = true
                    DispatchQueue.main.async { activeNewEpisodeAlertFocused = true }
                }
                .animation(.spring(response: 0.42, dampingFraction: 0.86), value: activeNewEpisodeAlert?.id)
                .zIndex(9600)
            }
        }
    }

    private var newEpisodeAlertBannerVerticalPadding: CGFloat {
        // vBRDC118: edge-tight by design. Keep a tiny overscan safety inset while
        // removing the large floating offset from every non-playback surface.
        newEpisodeAlertScreenEdgeInset
    }

    @ViewBuilder
    private var newEpisodeScannerVerificationLayer: some View {
        if let report = newEpisodeScannerVerificationReport {
            NewEpisodeScannerVerificationOverlay(report: report, isRunning: newEpisodeScannerVerificationRunning)
                .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topTrailing)
                .padding(.top, 86)
                .padding(.trailing, 54)
                .allowsHitTesting(false)
                .zIndex(9700)
        }
    }

    @MainActor
    private func runRealEpisodeAlertScan(reason: String) async -> TimeInterval {
        let selectedInterval = newEpisodeAlertScanIntervalSeconds
        guard followAlertsEnabled, followNewEpisodesEnabled else { return selectedInterval }
        guard !membershipLocked else { return selectedInterval }
        guard !realEpisodeAlertScanRunning else {
            return 15
        }

        realEpisodeAlertScanRunning = true
        defer { realEpisodeAlertScanRunning = false }
        let attemptDate = Date()
        lastRealEpisodeAlertScanAt = attemptDate
        lastNewEpisodeScanReason = reason
        NewEpisodeAlertsManager.recordScanAttempt(at: attemptDate, reason: reason)

        // vBRDC004: CatalogStore is a root EnvironmentObject. Scanner-only status text
        // must not publish through it while Live TV/catalogs/playback own the frame budget.
        // Keep the diagnostics text visible only when Settings is actually on screen.
        if store.playbackURL == nil && store.selectedTab == .settings {
            store.status = "Episode alert scanner running: \(NewEpisodeAlertsManager.scheduleFormatter.string(from: attemptDate))."
        }

        // vBRDC208: the configured Episode Alert heartbeat remains eligible during VOD and
        // Live TV when playback alerts are enabled. This is still one bounded scheduler, not a
        // playback clock, so alerts can arrive in-session without reviving unrelated root work.
        let allowExistingScannerDuringPlayback = episodeAlertFullScreenPlaybackActive
            && newEpisodeAlertPresentationScope == .mainAndVOD
        if store.playbackURL != nil && !allowExistingScannerDuringPlayback {
            lastNewEpisodeScanReason = "deferred while protected full-screen playback owns frame budget"
            return min(selectedInterval, 60)
        }

        let report = await store.runFollowedEpisodeAlertScanReport(reason: reason)
        guard !Task.isCancelled else { return selectedInterval }
        if !report.hits.isEmpty {
            enqueueNewEpisodeAlerts(report.hits, resetCycleCount: true)
        }

        let completionDate = Date()
        let state = NewEpisodeAlertsManager.recordScanCompletion(
            success: report.scanCompletedSuccessfully,
            partial: report.scanWasPartial,
            at: completionDate,
            outcome: report.scanOutcome
        )

        if report.scanCompletedSuccessfully {
            completeOneMinuteTestModeIfNeeded(afterScheduledScanReason: reason)
            let next = TimeInterval(NewEpisodeAlertsManager.selectedScanFrequencySeconds())
            if store.playbackURL == nil && store.selectedTab == .settings {
                store.status = report.hits.isEmpty
                    ? "Episode alerts verified: all followed shows checked; next scan in \(Int(next / 60)) minute(s)."
                    : "Episode alerts verified: \(report.hits.count) alert(s) queued; next scan in \(Int(next / 60)) minute(s)."
            }
            return next
        }

        let retry = state.consecutiveFailureCount <= 3
            ? NewEpisodeAlertsManager.retryDelaySeconds(consecutiveFailureCount: state.consecutiveFailureCount)
            : selectedInterval
        if store.playbackURL == nil && store.selectedTab == .settings {
            store.status = "Episode alert scan incomplete: \(report.scanOutcome). Retrying in \(Int(retry)) seconds."
        }
        return retry
    }

    @MainActor
    private func verifyNewEpisodeScanner() {
        guard !store.vodExclusivePlaybackActive, store.playbackURL == nil else { return }
        guard !newEpisodeScannerVerificationRunning else { return }
        newEpisodeScannerVerificationRunning = true
        newEpisodeScannerVerificationReport = nil
        newEpisodeScannerVerificationTask?.cancel()
        newEpisodeScannerVerificationTask = Task {
            if realEpisodeAlertScanRunning {
                var report = NewEpisodeAlertScanReport()
                applyNewEpisodeScannerScheduleFields(to: &report)
                report.scanAlreadyRunning = true
                newEpisodeScannerVerificationReport = report
                newEpisodeScannerVerificationRunning = false
                return
            }
            var report = await store.runFollowedEpisodeAlertScanReport(reason: "developer verification")
            applyNewEpisodeScannerScheduleFields(to: &report)
            let beforeDisplayed = displayedNewEpisodeAlertsThisCycle
            enqueueNewEpisodeAlerts(report.hits, resetCycleCount: true)
            report.alertDisplayed = displayedNewEpisodeAlertsThisCycle > beforeDisplayed
            report.displayedThisCycleCount = displayedNewEpisodeAlertsThisCycle
            report.remainingQueueCount = queuedNewEpisodeAlerts.count
            guard !Task.isCancelled, !store.vodExclusivePlaybackActive else { return }
            newEpisodeScannerVerificationReport = report
            newEpisodeScannerVerificationRunning = false
            newEpisodeScannerVerificationTask = nil
        }
    }

    private func applyNewEpisodeScannerScheduleFields(to report: inout NewEpisodeAlertScanReport) {
        NewEpisodeAlertsManager.decorateScanReport(
            &report,
            periodicScannerEnabled: followAlertsEnabled && followNewEpisodesEnabled && scenePhase == .active && !membershipLocked,
            scanIntervalSeconds: newEpisodeAlertScanIntervalSeconds,
            selectedScanFrequency: newEpisodeAlertScanFrequency,
            selectedScanFrequencyRawValue: newEpisodeAlertScanFrequencyMinutesRaw,
            activeHeartbeatIntervalSeconds: activeNewEpisodeHeartbeatIntervalSeconds,
            heartbeatTaskActive: newEpisodeHeartbeatTaskActive && newEpisodeHeartbeatTask != nil,
            heartbeatGeneration: newEpisodeHeartbeatGeneration,
            lastHeartbeatFiredAt: lastNewEpisodeHeartbeatFiredAt,
            nextHeartbeatScanAt: nextNewEpisodeHeartbeatScanAt,
            lastScanReason: lastNewEpisodeScanReason,
            duplicateHeartbeatPreventedCount: duplicateNewEpisodeHeartbeatPreventedCount,
            alertStyleDisplayName: newEpisodeAlertStyle.displayName,
            bannerSideDisplayName: newEpisodeAlertBannerSide.displayName,
            alertThemeDisplayName: newEpisodeAlertTheme.displayName,
            bannerDurationSeconds: newEpisodeAlertBannerDuration.seconds,
            lastRealScanAt: lastRealEpisodeAlertScanAt,
            scanAlreadyRunning: realEpisodeAlertScanRunning,
            displayedThisCycleCount: displayedNewEpisodeAlertsThisCycle,
            remainingQueueCount: queuedNewEpisodeAlerts.count
        )
    }

    @MainActor
    private func completeOneMinuteTestModeIfNeeded(afterScheduledScanReason reason: String) {
        guard newEpisodeAlertScanFrequency == .oneMinuteTest else { return }
        // The one-minute mode completes only after a conclusive scan. Metadata failures
        // remain in test mode and use the reliability retry policy instead of silently
        // returning to the five-minute default without proving the scanner worked.
        lastNewEpisodeScanReason = "1 minute test completed (\(reason))"
        newEpisodeAlertScanFrequencyMinutesRaw = NewEpisodeAlertScanFrequency.five.rawValue
    }

    @MainActor
    private func restorePersistedEpisodeAlertsIfNeeded() {
        guard !didRestorePersistedEpisodeAlerts else { return }
        didRestorePersistedEpisodeAlerts = true
        queuedNewEpisodeAlerts = NewEpisodeAlertsManager.loadPendingAlerts()
        presentNextQueuedNewEpisodeAlertIfPossible(delaySeconds: 0)
    }

    @MainActor
    private func persistEpisodeAlertDeliveryState() {
        var pending = queuedNewEpisodeAlerts
        if let active = activeNewEpisodeAlert,
           !confirmedPresentedEpisodeAlertIDs.contains(active.id),
           !active.alertKey.hasPrefix("developerEpisodeAlertTest::") {
            pending.insert(active, at: 0)
        }
        NewEpisodeAlertsManager.savePendingAlerts(pending)
    }

    @MainActor
    private func confirmEpisodeAlertPresentation(_ alert: NewEpisodeAlertHit) {
        guard !confirmedPresentedEpisodeAlertIDs.contains(alert.id) else { return }
        confirmedPresentedEpisodeAlertIDs.insert(alert.id)
        // Remove first, then advance duplicate progress. A crash between these operations
        // can repeat an alert, but it cannot permanently lose one that never rendered.
        NewEpisodeAlertsManager.removePendingAlert(id: alert.id)
        store.markEpisodeAlertPresented(alert)
    }

    @MainActor
    private func enqueueNewEpisodeAlerts(_ hits: [NewEpisodeAlertHit], resetCycleCount: Bool) {
        guard !hits.isEmpty else { return }
        if resetCycleCount { displayedNewEpisodeAlertsThisCycle = 0 }
        let activeID = activeNewEpisodeAlert?.id
        let merged = NewEpisodeAlertsManager.mergePendingAlerts(hits)
        var queuedIDs = Set<String>()
        queuedNewEpisodeAlerts = merged.filter { hit in
            guard hit.id != activeID else { return false }
            return queuedIDs.insert(hit.id).inserted
        }
        persistEpisodeAlertDeliveryState()
        presentNextQueuedNewEpisodeAlertIfPossible(delaySeconds: 0)
    }

    @MainActor
    private func presentNextQueuedNewEpisodeAlertIfPossible(delaySeconds: UInt64 = 4) {
        guard activeNewEpisodeAlert == nil, !membershipLocked else { return }
        guard episodeAlertPresentationAllowedOnCurrentSurface else { return }
        guard !queuedNewEpisodeAlerts.isEmpty else { return }
        nextQueuedNewEpisodeAlertTask?.cancel()
        if delaySeconds == 0 {
            let next = queuedNewEpisodeAlerts.removeFirst()
            activeNewEpisodeAlert = next
            displayedNewEpisodeAlertsThisCycle += 1
            persistEpisodeAlertDeliveryState()
            prepareAlertPresentation(for: next)
            return
        }
        nextQueuedNewEpisodeAlertTask = Task { @MainActor in
            do {
                try await Task.sleep(nanoseconds: delaySeconds * 1_000_000_000)
            } catch {
                return
            }
            guard activeNewEpisodeAlert == nil, !membershipLocked, episodeAlertPresentationAllowedOnCurrentSurface, !queuedNewEpisodeAlerts.isEmpty else { return }
            let next = queuedNewEpisodeAlerts.removeFirst()
            activeNewEpisodeAlert = next
            displayedNewEpisodeAlertsThisCycle += 1
            persistEpisodeAlertDeliveryState()
            prepareAlertPresentation(for: next)
        }
    }

    @MainActor
    private func dismissRealEpisodeAlert(consume: Bool) {
        guard let alert = activeNewEpisodeAlert else { return }
        activeNewEpisodeAlertDismissTask?.cancel()
        NewEpisodeAlertsManager.removePendingAlert(id: alert.id)
        if consume {
            store.markEpisodeAlertConsumed(alert)
        } else if !confirmedPresentedEpisodeAlertIDs.contains(alert.id) {
            store.markEpisodeAlertPresented(alert)
        }
        confirmedPresentedEpisodeAlertIDs.remove(alert.id)
        withAnimation(.spring(response: 0.42, dampingFraction: 0.88)) {
            activeNewEpisodeAlert = nil
        }
        activeNewEpisodeAlertFocus = 0
        persistEpisodeAlertDeliveryState()
        presentNextQueuedNewEpisodeAlertIfPossible(delaySeconds: 4)
    }

    private func routeRealEpisodeAlert(_ direction: SignalMoveDirection) {
        switch direction {
        case .left:
            activeNewEpisodeAlertFocus = max(0, activeNewEpisodeAlertFocus - 1)
        case .right:
            activeNewEpisodeAlertFocus = min(2, activeNewEpisodeAlertFocus + 1)
        case .up, .down:
            break
        default:
            break
        }
    }

    private func activateRealEpisodeAlert() {
        guard let alert = activeNewEpisodeAlert else { return }
        switch activeNewEpisodeAlertFocus {
        case 0:
            activeNewEpisodeAlertDismissTask?.cancel()
            NewEpisodeAlertsManager.removePendingAlert(id: alert.id)
            store.markEpisodeAlertConsumed(alert)
            confirmedPresentedEpisodeAlertIDs.remove(alert.id)
            pendingEpisodeAlertOpenIntent = alert
            withAnimation(.spring(response: 0.42, dampingFraction: 0.88)) {
                activeNewEpisodeAlert = nil
            }
            activeNewEpisodeAlertFocus = 0
            persistEpisodeAlertDeliveryState()
            if store.playbackURL == nil && !store.vodExclusivePlaybackActive {
                store.openDetail(alert.show)
            }
            presentNextQueuedNewEpisodeAlertIfPossible(delaySeconds: 4)
        case 1:
            dismissRealEpisodeAlert(consume: false)
        default:
            dismissRealEpisodeAlert(consume: true)
        }
    }

    private func triggerDeveloperNewEpisodeAlert() {
        let alert = NewEpisodeAlertsManager.makeDeveloperAlert()
        activeNewEpisodeAlert = alert
        activeNewEpisodeAlertFocus = 0
        prepareAlertPresentation(for: alert)
    }

    private var newEpisodeAlertScanFrequency: NewEpisodeAlertScanFrequency {
        NewEpisodeAlertScanFrequency(rawValue: newEpisodeAlertScanFrequencyMinutesRaw) ?? .five
    }

    private var newEpisodeAlertStyle: NewEpisodeAlertStyle {
        NewEpisodeAlertStyle(rawValue: newEpisodeAlertStyleRaw) ?? .banner
    }

    private var newEpisodeAlertBannerSide: NewEpisodeAlertBannerSide {
        NewEpisodeAlertBannerSide(rawValue: newEpisodeAlertBannerSideRaw) ?? .topRight
    }

    private var newEpisodeAlertTheme: NewEpisodeAlertTheme {
        NewEpisodeAlertTheme(rawValue: newEpisodeAlertThemeRaw) ?? .glass
    }

    private func prepareAlertPresentation(for alert: NewEpisodeAlertHit) {
        activeNewEpisodeAlertFocus = 0
        activeNewEpisodeAlertDismissTask?.cancel()
        switch effectiveNewEpisodeAlertStyle {
        case .banner:
            activeNewEpisodeAlertFocused = false
            schedulePassiveEpisodeAlertDismiss(for: alert)
        case .interactivePopup:
            DispatchQueue.main.async { activeNewEpisodeAlertFocused = true }
        }
    }

    private func schedulePassiveEpisodeAlertDismiss(for alert: NewEpisodeAlertHit) {
        activeNewEpisodeAlertDismissTask?.cancel()
        let durationSeconds = max(10, newEpisodeAlertBannerDuration.seconds)
        activeNewEpisodeAlertDismissTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: UInt64(durationSeconds) * 1_000_000_000)
            guard activeNewEpisodeAlert?.id == alert.id else { return }
            dismissRealEpisodeAlert(consume: false)
        }
    }
}


enum NewEpisodeAlertScanFrequency: String, CaseIterable, Identifiable {
    case oneMinuteTest = "1"
    case five = "5"
    case ten = "10"
    case thirty = "30"

    var id: String { rawValue }
    var minutes: Int { Int(rawValue) ?? 10 }
    var displayName: String {
        switch self {
        case .oneMinuteTest: return "1 Minute Test Mode"
        case .five: return "5 Minutes"
        case .ten: return "10 Minutes"
        case .thirty: return "30 Minutes"
        }
    }
    var isTestingMode: Bool { self == .oneMinuteTest }
    var warningText: String? {
        isTestingMode ? "Testing only. Frequent scans may increase API usage, background activity, and duplicate-alert debugging complexity. Not recommended for normal use." : nil
    }
}

typealias EpisodeAlertInterval = NewEpisodeAlertScanFrequency

func episodeAlertIntervalSeconds(for setting: EpisodeAlertInterval) -> TimeInterval {
    switch setting {
    case .oneMinuteTest: return 60
    case .five: return 300
    case .ten: return 600
    case .thirty: return 1800
    }
}

enum NewEpisodeAlertBannerDuration: String, CaseIterable, Identifiable {
    case ten = "10"
    case fifteen = "15"
    case thirty = "30"

    var id: String { rawValue }
    var seconds: Int { Int(rawValue) ?? 15 }
    var displayName: String {
        switch self {
        case .ten: return "10 Seconds"
        case .fifteen: return "15 Seconds"
        case .thirty: return "30 Seconds"
        }
    }
}


// vBRDC118: one edge contract for root and in-player Episode Alerts.
// 18 pt reads as edge-attached on tvOS while avoiding overscan/clipping.
private let newEpisodeAlertScreenEdgeInset: CGFloat = 18

enum NewEpisodeAlertPresentationScope: String, CaseIterable, Identifiable {
    case mainAndVOD
    case mainOnly

    var id: String { rawValue }
    var displayName: String {
        switch self {
        case .mainAndVOD: return "Main UI + VOD + Live TV"
        case .mainOnly: return "Main UI Only"
        }
    }
}

enum NewEpisodeAlertStyle: String, CaseIterable, Identifiable {
    case banner
    case interactivePopup

    var id: String { rawValue }
    var displayName: String {
        switch self {
        case .banner: return "Banner"
        case .interactivePopup: return "Interactive Popup"
        }
    }
}

enum NewEpisodeAlertBannerSide: RawRepresentable, CaseIterable, Identifiable {
    case topRight
    case topLeft
    case bottomRight
    case bottomLeft

    var id: String { rawValue }
    init?(rawValue: String) {
        switch rawValue {
        case "topRight", "right": self = .topRight
        case "topLeft", "left": self = .topLeft
        case "bottomRight": self = .bottomRight
        case "bottomLeft": self = .bottomLeft
        default: return nil
        }
    }
    var rawValue: String {
        switch self {
        case .topRight: return "topRight"
        case .topLeft: return "topLeft"
        case .bottomRight: return "bottomRight"
        case .bottomLeft: return "bottomLeft"
        }
    }
    var displayName: String {
        switch self {
        case .topRight: return "Top Right"
        case .topLeft: return "Top Left"
        case .bottomRight: return "Bottom Right"
        case .bottomLeft: return "Bottom Left"
        }
    }
    var alignment: Alignment {
        switch self {
        case .topRight: return .topTrailing
        case .topLeft: return .topLeading
        case .bottomRight: return .bottomTrailing
        case .bottomLeft: return .bottomLeading
        }
    }
    var transitionEdge: Edge {
        switch self {
        case .topRight, .bottomRight: return .trailing
        case .topLeft, .bottomLeft: return .leading
        }
    }
    var horizontalEdgeSet: Edge.Set {
        switch self {
        case .topRight, .bottomRight: return .trailing
        case .topLeft, .bottomLeft: return .leading
        }
    }
    var verticalEdgeSet: Edge.Set {
        switch self {
        case .topRight, .topLeft: return .top
        case .bottomRight, .bottomLeft: return .bottom
        }
    }
    var isBottom: Bool {
        switch self {
        case .bottomRight, .bottomLeft: return true
        case .topRight, .topLeft: return false
        }
    }
}

enum NewEpisodeAlertTheme: String, CaseIterable, Identifiable {
    case glass
    case solidDark
    case neonEdge
    case minimal

    var id: String { rawValue }
    var displayName: String {
        switch self {
        case .glass: return "Glass"
        case .solidDark: return "Solid Dark"
        case .neonEdge: return "Neon Edge"
        case .minimal: return "Minimal"
        }
    }

    var cardOpacity: Double {
        switch self {
        case .glass: return 0.84
        case .solidDark: return 0.95
        case .neonEdge: return 0.88
        case .minimal: return 0.92
        }
    }

    var borderColor: Color {
        switch self {
        case .glass: return Color.white.opacity(0.16)
        case .solidDark: return Color.white.opacity(0.10)
        case .neonEdge: return Color.cyan.opacity(0.48)
        case .minimal: return Color.white.opacity(0.08)
        }
    }

    var accentColor: Color {
        switch self {
        case .glass: return Color.orange
        case .solidDark: return Color.white
        case .neonEdge: return Color.cyan
        case .minimal: return Color.white.opacity(0.82)
        }
    }

    var shadowColor: Color {
        switch self {
        case .glass: return Color.orange.opacity(0.12)
        case .solidDark: return Color.black.opacity(0.12)
        case .neonEdge: return Color.cyan.opacity(0.18)
        case .minimal: return Color.clear
        }
    }
}

