private struct LiveTVCBSStreamProfile {
    let finalURL: URL
    let profileActive: Bool
    let hasCBSMetadataSignal: Bool
    let hasChannelsTimingRisk: Bool
    let hlsRewriteSucceeded: Bool
    let originalURLType: String
    let rewrittenURLType: String
    let finalURLType: String
    let debugLabel: String
}

private enum LiveTVCBSChannelsDVRProfile {
    static func profile(for channel: LiveTVChannel, routeLabel: String) -> LiveTVCBSStreamProfile? {
        guard let originalURL = URL(string: channel.streamURL), !channel.streamURL.isEmpty else { return nil }
        let originalType = urlType(for: originalURL)
        let metadataHaystack = [
            channel.name,
            channel.logo,
            channel.tvgID,
            channel.source,
            channel.number,
            routeLabel
        ].joined(separator: " ").lowercased()
        let urlHaystack = [
            channel.streamURL
        ].joined(separator: " ").lowercased()
        let haystack = metadataHaystack + " " + urlHaystack
        let hasCBSMetadataSignal =
            metadataHaystack.contains("cbs") ||
            metadataHaystack.contains("paramount") ||
            metadataHaystack.contains("wcbs") ||
            metadataHaystack.contains("kcbs") ||
            metadataHaystack.contains("wbbm") ||
            metadataHaystack.contains("wkyc") ||
            haystack.contains("cbs") ||
            haystack.contains("paramount") ||
            haystack.contains("wcbs") ||
            haystack.contains("kcbs") ||
            haystack.contains("wbbm") ||
            haystack.contains("wkyc")
        let hasChannelsTimingRisk =
            haystack.contains("/devices/") ||
            haystack.contains("channels.m3u") ||
            haystack.contains("stream.mpg") ||
            haystack.contains("format=ts") ||
            haystack.contains("codec=copy") ||
            haystack.contains("channels dvr") ||
            haystack.contains("tve") ||
            haystack.contains("verizon")
        let profileActive = hasCBSMetadataSignal && hasChannelsTimingRisk
        guard profileActive else { return nil }
        let hlsRewriteURL = hlsURL(from: originalURL)
        let rewrittenURL = hlsRewriteURL ?? nonCopyURL(from: originalURL) ?? originalURL
        let hlsRewriteSucceeded = hlsRewriteURL != nil
        let rewrittenType = rewrittenURL == originalURL ? "fallback original" : urlType(for: rewrittenURL)
        let finalType = urlType(for: rewrittenURL)
        return LiveTVCBSStreamProfile(
            finalURL: rewrittenURL,
            profileActive: true,
            hasCBSMetadataSignal: hasCBSMetadataSignal,
            hasChannelsTimingRisk: hasChannelsTimingRisk,
            hlsRewriteSucceeded: hlsRewriteSucceeded,
            originalURLType: originalType,
            rewrittenURLType: rewrittenType,
            finalURLType: finalType,
            debugLabel: "CBS metadata signal: \(hasCBSMetadataSignal) • Channels timing-risk signal: \(hasChannelsTimingRisk) • CBS profile active: true • hlsURL rewrite succeeded: \(hlsRewriteSucceeded) • original URL type: \(originalType) • rewritten URL type: \(rewrittenType) • final URL type: \(finalType)"
        )
    }

    static func profile(for url: URL, channelName: String, logo: String, tvgID: String, source: String, number: String, routeLabel: String) -> LiveTVCBSStreamProfile? {
        let channel = LiveTVChannel(id: 0, logo: logo, number: number, name: channelName, category: "", now: "", next: "", description: "", accent: .gray, streamURL: url.absoluteString, tvgID: tvgID, source: source)
        return profile(for: channel, routeLabel: routeLabel)
    }

    private static func hlsURL(from url: URL) -> URL? {
        guard var components = URLComponents(url: url, resolvingAgainstBaseURL: false) else { return nil }
        let lowerPath = components.path.lowercased()
        guard lowerPath.contains("/devices/"), lowerPath.contains("/channels/"), lowerPath.hasSuffix("/stream.mpg") else { return nil }
        components.query = nil
        components.percentEncodedQuery = nil
        components.path = String(components.path.dropLast("/stream.mpg".count)) + "/stream.m3u8"
        return components.url
    }

    private static func nonCopyURL(from url: URL) -> URL? {
        guard var components = URLComponents(url: url, resolvingAgainstBaseURL: false) else { return nil }
        components.queryItems = components.queryItems?.filter { item in
            let name = item.name.lowercased()
            let value = (item.value ?? "").lowercased()
            if name == "codec", value == "copy" { return false }
            if name == "format", value == "ts" { return false }
            return true
        }
        if components.queryItems?.isEmpty == true { components.queryItems = nil }
        return components.url
    }

    static func urlType(for url: URL) -> String {
        let value = url.absoluteString.lowercased()
        if value.contains("/devices/") && value.contains("/stream.m3u8") { return "Channels DVR HLS stream.m3u8" }
        if value.contains("/devices/") && value.contains("/stream.mpg") && value.contains("codec=copy") { return "Channels DVR MPEG-TS copy stream.mpg" }
        if value.contains("/devices/") && value.contains("/stream.mpg") { return "Channels DVR stream.mpg non-copy" }
        if value.contains("format=ts") || value.hasSuffix(".ts") || value.contains(".mpg") { return "MPEG-TS/remux" }
        if value.contains(".m3u8") || value.contains("/hls/") { return "HLS" }
        if value.contains("/live/") { return "Xtream live" }
        return "Direct URL"
    }
}


