            verificationRow("heartbeat scheduler enabled", report.periodicScannerEnabled ? "true" : "false")
            verificationRow("periodic scanner enabled", report.periodicScannerEnabled ? "true" : "false")
            verificationRow("scan interval minutes", "\(report.scanIntervalMinutes)")
            verificationRow("last scan time", report.lastScanTime)
            verificationRow("next scan estimate", report.nextScanEstimate)
            verificationRow("scan already running", report.scanAlreadyRunning ? "true" : "false")
            verificationRow("followed keys count", "\(report.followedKeysCount)")
            verificationRow("followed shows matched in loaded rows", "\(report.followedShowsMatchedInLoadedRows)")
            verificationRow("shows checked", "\(report.showsChecked)")
            verificationRow("metadata fetch attempted", report.metadataFetchAttempted ? "true" : "false")
            verificationRow("followed snapshot count", "\(report.followedSnapshotCount)")
            verificationRow("metadata fetch success count", "\(report.metadataFetchSuccessCount)")
            verificationRow("metadata fetch failure count", "\(report.metadataFetchFailureCount)")
            verificationRow("scan completed successfully", report.scanCompletedSuccessfully ? "true" : "false")
            verificationRow("scan partial", report.scanWasPartial ? "true" : "false")
            verificationRow("scan outcome", report.scanOutcome)
            verificationRow("scheduler consecutive failures", "\(report.scheduleConsecutiveFailureCount)")
            verificationRow("persistent delivery queue count", "\(report.persistentQueueCount)")
            verificationRow("episodes fetched count", "\(report.episodesFetchedCount)")
            verificationRow("newest raw date string seen", report.newestRawDateStringSeen)
            verificationRow("newest parsed date", report.newestParsedDate)
            verificationRow("missing/empty date count", "\(report.missingDateCount)")
            verificationRow("parse success count", "\(report.dateParseSuccessCount)")
            verificationRow("parse failed count", "\(report.dateParseFailedCount)")
            verificationRow("newest eligible episode date", report.newestEligibleEpisodeDate)
            verificationRow("recent episode detected", report.recentEpisodeDetected ? "true" : "false")
            verificationRow("eligible but consumed count", "\(report.eligibleButConsumedCount)")
            verificationRow("suppressed duplicate count", "\(report.suppressedDuplicateCount)")
            verificationRow("suppressed same episode count", "\(report.suppressedSameEpisodeCount)")
            verificationRow("already alerted count", "\(report.alreadyAlertedCount)")
            verificationRow("newest detected episode key", report.newestDetectedEpisodeKey)
            verificationRow("last alerted episode key for show", report.lastAlertedEpisodeKeyForShow)
            verificationRow("eligible hits found", "\(report.hits.count)")
            verificationRow("alert queued count", "\(report.alertQueuedCount)")
            verificationRow("displayed this cycle count", "\(report.displayedThisCycleCount)")
            verificationRow("remaining queue count", "\(report.remainingQueueCount)")
            verificationRow("returned alert hits", "\(report.returnedAlertHits)")
            verificationRow("alert displayed", report.alertDisplayed ? "true" : "false")
            if !report.hitSourceSummaries.isEmpty {
                verificationRow("source/catalog/provider used", report.hitSourceSummaries.prefix(3).joined(separator: " | "))
            }
        }
        .font(.system(size: 15, weight: .bold, design: .monospaced))
        .foregroundStyle(.white)
        .padding(16)
        .frame(width: 610, alignment: .leading)
        .background(RoundedRectangle(cornerRadius: 18, style: .continuous).fill(Color.black.opacity(0.82)))
        .overlay(RoundedRectangle(cornerRadius: 18, style: .continuous).stroke(Color.orange.opacity(0.58), lineWidth: 1.3))
        .shadow(color: .black.opacity(0.55), radius: 24, y: 10)
    }

    private func verificationRow(_ title: String, _ value: String) -> some View {
        HStack(alignment: .firstTextBaseline, spacing: 10) {
            Text(title)
                .foregroundStyle(.white.opacity(0.62))
            Spacer(minLength: 12)
            Text(value)
                .foregroundStyle(.white)
                .multilineTextAlignment(.trailing)
        }
    }
}


