private enum TopMenuVisualFamily {
    case classicRail
    case segmented
    case floatingTiles
    case iconDock
    case minimalLine
    case marquee
    case ribbon
    case circleDock
    case monochromeBlocks
    case posterTabs
    // v1156: genuinely different professional navigation compositions. These are
    // geometry families, not recolors of an existing tab treatment.
    case liquidIsland
    case studioChrome
    case broadcastDeck
    case modernPills
}

// vBRDC165: user-adjustable global top-menu size. The renderer keeps each theme's
// own proportions and only scales the completed navigation composition, so changing size
// cannot flatten or substitute a theme. Medium exactly preserves the vBRDC164 geometry.
private enum TopMenuSizePreset {
    static let names = ["Extra Small", "Small", "Medium", "Large", "Extra Large"]

    static func normalized(_ raw: String) -> String {
        names.contains(raw) ? raw : "Medium"
    }

    static func next(after raw: String) -> String {
        let current = normalized(raw)
        guard let index = names.firstIndex(of: current) else { return "Medium" }
        return names[(index + 1) % names.count]
    }

    static func scale(_ raw: String) -> CGFloat {
        switch normalized(raw) {
        case "Extra Small": return 0.56
        case "Small": return 0.64
        case "Large": return 0.82
        case "Extra Large": return 0.94
        default: return 0.72
        }
    }
}

private enum TopMenuThemeStyle: String, CaseIterable, Identifiable {
    case classic = "Classic"
    case transparentBlackGlass = "Transparent Black Glass"
    case darkerGlass = "Darker Glass"
    case lighterGlass = "Lighter Glass"
    case minimal = "Minimal / No Background"
    case artworkBlend = "Artwork Blend Mode"
    case auroraGlass = "Aurora Glass"
    case sapphireGlass = "Sapphire Glass"
    case emeraldGlass = "Emerald Glass"
    case rubyNoir = "Ruby Noir"
    case sunsetGlass = "Sunset Glass"
    case purpleNebula = "Purple Nebula"
    case monochrome = "Monochrome"
    case copperCinema = "Copper Cinema"
    case iconDock = "Icon Dock"
    case floatingTiles = "Floating Tiles"
    case cinemaMarquee = "Cinema Marquee"
    case studioRibbon = "Studio Ribbon"
    case segmentedControl = "Segmented Control"
    case compactIcons = "Compact Icons"
    case neonLine = "Neon Line"
    case posterTabs = "Poster Tabs"
    case liquidGlassPro = "Liquid Glass Pro"
    case crystalNavigation = "Crystal Navigation"
    case obsidianGlass = "Obsidian Glass"
    case studioChrome = "Studio Chrome"
    case graphiteStudio = "Graphite Studio"
    case executiveMinimal = "Executive Minimal"
    case broadcastDeck = "Broadcast Deck"
    case networkConsole = "Network Console"
    case modernCapsules = "Modern Capsules"
    case cinemaCapsules = "Cinema Capsules"

    var id: String { rawValue }
    static let implementedNames = Self.allCases.map(\.rawValue)

    static func resolve(_ raw: String) -> TopMenuThemeStyle {
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)

        // vBRDC149: theme identity is exact-first.  The old broad substring resolver was
        // useful for legacy names, but it also made unrelated presets collapse into the
        // same family when a saved value happened to contain a generic word such as
        // "glass", "minimal", or "graphite".  Resolve every current picker value by its
        // canonical rawValue before consulting aliases so selecting a theme always renders
        // that exact theme and survives relaunch/backup restore unchanged.
        if let exact = Self.allCases.first(where: {
            $0.rawValue.compare(trimmed, options: [.caseInsensitive, .diacriticInsensitive]) == .orderedSame
        }) {
            return exact
        }

        let key = trimmed.lowercased()
        let aliases: [String: TopMenuThemeStyle] = [
            "liquid glass": .liquidGlassPro,
            "liquid nav": .liquidGlassPro,
            "crystal nav": .crystalNavigation,
            "obsidian": .obsidianGlass,
            "chrome": .studioChrome,
            "graphite": .graphiteStudio,
            "executive": .executiveMinimal,
            "broadcast": .broadcastDeck,
            "network": .networkConsole,
            "modern pills": .modernCapsules,
            "cinema pills": .cinemaCapsules,
            "black glass": .transparentBlackGlass,
            "dark glass": .darkerGlass,
            "frosted glass": .lighterGlass,
            "artwork blend": .artworkBlend
        ]
        if let alias = aliases[key] { return alias }

        // Legacy migration only.  Keep this ordered from most-specific to least-specific;
        // it must never run for one of the canonical names above.
        if key.contains("icon dock") { return .iconDock }
        if key.contains("floating tile") { return .floatingTiles }
        if key.contains("cinema marquee") { return .cinemaMarquee }
        if key.contains("studio ribbon") { return .studioRibbon }
        if key.contains("segmented control") { return .segmentedControl }
        if key.contains("compact icon") { return .compactIcons }
        if key.contains("neon line") { return .neonLine }
        if key.contains("poster tab") { return .posterTabs }
        if key.contains("liquid glass") { return .liquidGlassPro }
        if key.contains("crystal") { return .crystalNavigation }
        if key.contains("obsidian") { return .obsidianGlass }
        if key.contains("studio chrome") { return .studioChrome }
        if key.contains("graphite studio") { return .graphiteStudio }
        if key.contains("executive") { return .executiveMinimal }
        if key.contains("broadcast deck") { return .broadcastDeck }
        if key.contains("network console") { return .networkConsole }
        if key.contains("modern capsule") || key.contains("modern pill") { return .modernCapsules }
        if key.contains("cinema capsule") || key.contains("cinema pill") { return .cinemaCapsules }
        if key.contains("aurora") { return .auroraGlass }
        if key.contains("sapphire") { return .sapphireGlass }
        if key.contains("emerald") { return .emeraldGlass }
        if key.contains("ruby") || key.contains("red noir") { return .rubyNoir }
        if key.contains("sunset") { return .sunsetGlass }
        if key.contains("nebula") { return .purpleNebula }
        if key.contains("monochrome") { return .monochrome }
        if key.contains("copper") { return .copperCinema }
        if key.contains("transparent") || key.contains("black glass") { return .transparentBlackGlass }
        if key.contains("darker") || key.contains("dark pill") || key.contains("oled") || key.contains("midnight") || key.contains("carbon") { return .darkerGlass }
        if key.contains("lighter") || key.contains("frosted") || key.contains("vision") || key.contains("platinum") || key.contains("apple glass") { return .lighterGlass }
        if key.contains("minimal") || key.contains("no background") || key.contains("soft minimal") { return .minimal }
        if key.contains("artwork") || key.contains("blend") || key.contains("ambient") || key.contains("dynamic") { return .artworkBlend }
        return .classic
    }

    var family: TopMenuVisualFamily {
        switch self {
        case .classic: return .classicRail
        case .transparentBlackGlass, .auroraGlass, .segmentedControl: return .segmented
        case .darkerGlass, .sunsetGlass, .floatingTiles: return .floatingTiles
        case .lighterGlass, .sapphireGlass, .iconDock: return .iconDock
        case .minimal, .emeraldGlass, .neonLine: return .minimalLine
        case .rubyNoir, .copperCinema, .cinemaMarquee: return .marquee
        case .artworkBlend, .studioRibbon: return .ribbon
        case .purpleNebula, .compactIcons: return .circleDock
        case .monochrome: return .monochromeBlocks
        case .posterTabs: return .posterTabs
        case .liquidGlassPro, .crystalNavigation, .obsidianGlass: return .liquidIsland
        case .studioChrome, .graphiteStudio, .executiveMinimal: return .studioChrome
        case .broadcastDeck, .networkConsole: return .broadcastDeck
        case .modernCapsules, .cinemaCapsules: return .modernPills
        }
    }

    var usesRail: Bool {
        switch family {
        case .floatingTiles, .minimalLine, .circleDock, .posterTabs, .broadcastDeck, .modernPills: return false
        default: return true
        }
    }

    var spacing: CGFloat {
        switch family {
        case .classicRail: return 10
        case .segmented: return 4
        case .floatingTiles: return 7
        case .iconDock: return 10
        // v1152: restore the original v1130 compact letters-only menu spacing.
        // The v1151 minimal underline was flexible inside the HStack and made the
        // navigation consume nearly the full screen width, colliding with Search.
        case .minimalLine: return 42
        case .marquee: return 12
        case .ribbon: return 5
        case .circleDock: return 10
        case .monochromeBlocks: return 2
        case .posterTabs: return 6
        case .liquidIsland: return 4
        case .studioChrome: return 0
        case .broadcastDeck: return 5
        case .modernPills: return 5
        }
    }

    var cornerRadius: CGFloat {
        switch family {
        case .segmented, .iconDock, .circleDock: return 34
        case .marquee, .monochromeBlocks, .ribbon: return 8
        case .classicRail: return 28
        case .liquidIsland: return 26
        case .studioChrome: return 8
        case .broadcastDeck: return 12
        case .modernPills: return 26
        default: return 22
        }
    }

    func accent(defaultAccent: Color) -> Color {
        switch self {
        case .lighterGlass: return Color(red: 0.72, green: 0.90, blue: 1.0)
        case .artworkBlend, .sunsetGlass, .studioRibbon: return Color(red: 1.0, green: 0.48, blue: 0.18)
        case .auroraGlass: return Color(red: 0.26, green: 0.94, blue: 0.78)
        case .sapphireGlass: return Color(red: 0.20, green: 0.58, blue: 1.0)
        case .emeraldGlass: return Color(red: 0.10, green: 0.82, blue: 0.52)
        case .rubyNoir, .cinemaMarquee: return Color(red: 0.95, green: 0.10, blue: 0.22)
        case .purpleNebula: return Color(red: 0.72, green: 0.34, blue: 1.0)
        case .monochrome: return Color.white
        case .copperCinema: return Color(red: 0.88, green: 0.49, blue: 0.24)
        case .neonLine: return Color(red: 0.18, green: 0.95, blue: 1.0)
        case .liquidGlassPro, .crystalNavigation: return Color(red: 0.54, green: 0.84, blue: 1.0)
        case .obsidianGlass, .graphiteStudio, .executiveMinimal: return Color(red: 0.72, green: 0.78, blue: 0.88)
        case .studioChrome: return Color(red: 0.28, green: 0.78, blue: 1.0)
        case .broadcastDeck, .networkConsole: return Color(red: 0.18, green: 0.78, blue: 1.0)
        case .modernCapsules: return Color(red: 0.36, green: 0.86, blue: 1.0)
        case .cinemaCapsules: return Color(red: 1.0, green: 0.58, blue: 0.20)
        default: return defaultAccent
        }
    }

    var railFill: AnyShapeStyle {
        switch self {
        case .transparentBlackGlass: return AnyShapeStyle(Material.ultraThin)
        case .darkerGlass: return AnyShapeStyle(Color.black.opacity(0.84))
        case .lighterGlass: return AnyShapeStyle(Material.thin)
        case .minimal, .emeraldGlass, .neonLine: return AnyShapeStyle(Color.clear)
        case .artworkBlend, .studioRibbon: return AnyShapeStyle(LinearGradient(colors: [Color.black.opacity(0.76), Color.orange.opacity(0.22), Color.indigo.opacity(0.18)], startPoint: .leading, endPoint: .trailing))
        case .auroraGlass: return AnyShapeStyle(LinearGradient(colors: [Color.black.opacity(0.70), Color.cyan.opacity(0.24), Color.green.opacity(0.16), Color.purple.opacity(0.12)], startPoint: .leading, endPoint: .trailing))
        case .sapphireGlass: return AnyShapeStyle(LinearGradient(colors: [Color.white.opacity(0.14), Color.blue.opacity(0.22), Color.black.opacity(0.54)], startPoint: .topLeading, endPoint: .bottomTrailing))
        case .rubyNoir, .cinemaMarquee: return AnyShapeStyle(LinearGradient(colors: [Color.black.opacity(0.94), Color.red.opacity(0.16), Color.black.opacity(0.94)], startPoint: .leading, endPoint: .trailing))
        case .sunsetGlass: return AnyShapeStyle(Color.black.opacity(0.72))
        case .purpleNebula: return AnyShapeStyle(Color.clear)
        case .monochrome: return AnyShapeStyle(Color.black.opacity(0.92))
        case .copperCinema: return AnyShapeStyle(LinearGradient(colors: [Color.black.opacity(0.94), Color(red: 0.48, green: 0.22, blue: 0.08).opacity(0.34), Color.black.opacity(0.94)], startPoint: .leading, endPoint: .trailing))
        case .classic, .segmentedControl, .iconDock: return AnyShapeStyle(Color.black.opacity(0.58))
        case .floatingTiles, .compactIcons, .posterTabs, .broadcastDeck, .networkConsole, .modernCapsules, .cinemaCapsules: return AnyShapeStyle(Color.clear)
        case .liquidGlassPro: return AnyShapeStyle(Material.ultraThin)
        case .crystalNavigation: return AnyShapeStyle(LinearGradient(colors: [Color.white.opacity(0.12), Color.cyan.opacity(0.10), Color.black.opacity(0.42)], startPoint: .topLeading, endPoint: .bottomTrailing))
        case .obsidianGlass: return AnyShapeStyle(LinearGradient(colors: [Color.white.opacity(0.055), Color.black.opacity(0.90), Color.blue.opacity(0.055)], startPoint: .top, endPoint: .bottom))
        case .studioChrome: return AnyShapeStyle(LinearGradient(colors: [Color.black.opacity(0.90), Color.white.opacity(0.075), Color.black.opacity(0.90)], startPoint: .top, endPoint: .bottom))
        case .graphiteStudio, .executiveMinimal: return AnyShapeStyle(Color.black.opacity(0.84))
        }
    }

    func railStroke(accent: Color) -> Color {
        switch family {
        case .marquee: return accent.opacity(0.62)
        case .monochromeBlocks: return Color.white.opacity(0.34)
        case .ribbon: return accent.opacity(0.38)
        case .iconDock, .segmented: return Color.white.opacity(0.18)
        case .liquidIsland: return Color.white.opacity(0.20)
        case .studioChrome: return accent.opacity(0.26)
        case .broadcastDeck, .modernPills: return Color.clear
        default: return Color.white.opacity(0.12)
        }
    }

    func selectedFill(accent: Color) -> Color {
        switch family {
        case .classicRail, .segmented, .floatingTiles, .ribbon: return accent.opacity(0.90)
        case .iconDock, .circleDock: return accent.opacity(0.95)
        case .monochromeBlocks: return Color.white
        case .posterTabs: return accent.opacity(0.78)
        case .liquidIsland: return Color.white.opacity(0.92)
        case .studioChrome: return accent.opacity(0.14)
        case .broadcastDeck: return Color.black.opacity(0.76)
        case .modernPills: return accent.opacity(0.88)
        case .minimalLine, .marquee: return Color.clear
        }
    }

    var selectedTextColor: Color {
        switch family {
        case .monochromeBlocks, .classicRail, .segmented, .floatingTiles, .ribbon, .liquidIsland, .modernPills:
            return .black
        default:
            return .white
        }
    }

    var prefersUppercase: Bool {
        switch family {
        case .marquee, .ribbon, .monochromeBlocks, .posterTabs, .studioChrome, .broadcastDeck: return true
        default: return false
        }
    }
}

private struct TopMenuTabVisual: View {
    let tab: AppTab
    let theme: TopMenuThemeStyle
    let fontPreset: String
    let accent: Color
    let isFocused: Bool
    let isSelected: Bool

    private var label: String {
        let raw = tab.rawValue == "Shows" ? "TV Shows" : tab.rawValue
        return theme.prefersUppercase ? raw.uppercased() : raw
    }

    private var icon: String {
        switch tab {
        case .home: return "house.fill"
        case .movies: return "film.fill"
        case .shows: return "tv.fill"
        case .sports: return "sportscourt.fill"
        case .favorites: return "heart.fill"
        case .live: return "dot.radiowaves.left.and.right"
        case .membership: return "person.crop.circle.badge.checkmark"
        case .settings: return "gearshape.fill"
        }
    }

    private var contextLabel: String {
        switch tab {
        case .home: return "DISCOVER"
        case .movies: return "FILMS"
        case .shows: return "SERIES"
        case .sports: return "LIVE SPORTS"
        case .favorites: return "SAVED"
        case .live: return "CHANNELS"
        case .membership: return "ACCOUNT"
        case .settings: return "SYSTEM"
        }
    }

    private var selectedFill: Color { theme.selectedFill(accent: accent) }
    private var normalText: Color { isSelected ? .white : .white.opacity(0.64) }
    private var activeText: Color { isFocused ? theme.selectedTextColor : normalText }
    private var navFont: Font {
        let size: CGFloat
        switch theme.family {
        case .iconDock, .circleDock:
            size = 15
        case .minimalLine:
            // v1152: exact v1130 letters-only menu text size. Keep the selected
            // font family/color, but restore the original compact geometry.
            size = 25
        case .liquidIsland:
            size = 17
        case .studioChrome:
            size = 16
        case .broadcastDeck:
            size = 15
        case .modernPills:
            size = 16
        case .marquee, .ribbon, .posterTabs, .monochromeBlocks:
            size = 18
        default:
            size = 20
        }
        return PopupTypography.font(fontPreset, size: size, weight: isFocused || isSelected ? .bold : .medium)
    }

    @ViewBuilder
    var body: some View {
        switch theme.family {
        case .classicRail:
            VStack(spacing: 6) {
                Text(label).font(navFont).tracking(PopupTypography.kerning(fontPreset)).foregroundStyle(activeText)
                    .padding(.horizontal, 15).padding(.vertical, 7)
                    .background(RoundedRectangle(cornerRadius: 16, style: .continuous).fill(isFocused ? selectedFill : Color.clear))
                Capsule().fill(isSelected ? accent : Color.clear).frame(width: 52, height: 4)
            }
        case .segmented:
            HStack(spacing: 8) {
                Image(systemName: icon).font(.system(size: 15, weight: .bold))
                Text(label).font(navFont).tracking(PopupTypography.kerning(fontPreset))
            }
            .foregroundStyle(activeText)
            .padding(.horizontal, 13).padding(.vertical, 8)
            .background(Capsule().fill(isFocused ? selectedFill : (isSelected ? Color.white.opacity(0.10) : Color.clear)))
            .overlay(Capsule().stroke(isFocused ? accent.opacity(0.80) : Color.clear, lineWidth: 1))
        case .floatingTiles:
            HStack(spacing: 9) {
                Image(systemName: icon).font(.system(size: 16, weight: .black))
                Text(label).font(navFont).tracking(PopupTypography.kerning(fontPreset))
            }
            .foregroundStyle(isFocused ? theme.selectedTextColor : .white.opacity(isSelected ? 0.96 : 0.72))
            .padding(.horizontal, 18).padding(.vertical, 12)
            .background(RoundedRectangle(cornerRadius: 13, style: .continuous).fill(isFocused ? selectedFill : Color.black.opacity(0.58)))
            .overlay(RoundedRectangle(cornerRadius: 13, style: .continuous).stroke(isSelected ? accent.opacity(0.58) : Color.white.opacity(0.10), lineWidth: 1))
            .shadow(color: isFocused ? accent.opacity(0.36) : .black.opacity(0.36), radius: isFocused ? 14 : 7, y: 5)
        case .iconDock:
            VStack(spacing: 4) {
                ZStack {
                    Circle().fill(isFocused ? selectedFill : (isSelected ? accent.opacity(0.22) : Color.white.opacity(0.08)))
                    Image(systemName: icon).font(.system(size: 20, weight: .black)).foregroundStyle(isFocused ? theme.selectedTextColor : .white)
                }
                .frame(width: 40, height: 40)
                Text(label).font(navFont).tracking(PopupTypography.kerning(fontPreset) * 0.6).foregroundStyle(.white.opacity(isSelected ? 1 : 0.68)).lineLimit(1)
            }
            .frame(minWidth: 64)
        case .minimalLine:
            VStack(spacing: 7) {
                Text(label)
                    .font(navFont)
                    .tracking(PopupTypography.kerning(fontPreset) + 0.20)
                    .foregroundStyle(isFocused ? accent : (isSelected ? .white : .white.opacity(0.62)))
                    .padding(.horizontal, isFocused ? 22 : 12)
                    .padding(.vertical, isFocused ? 9 : 7)
                // v1152: v1130 used a fixed 54/64-point underline. v1151 changed
                // this to an unconstrained Rectangle, which flexed to fill the HStack
                // and stretched the entire menu across the screen. Keep it intrinsic.
                Capsule()
                    .fill(isFocused || isSelected ? accent : Color.clear)
                    .frame(width: tab == .settings ? 64 : 54, height: isFocused ? 4 : 3)
                    .shadow(color: isSelected ? accent.opacity(0.56) : .clear, radius: 8)
            }
        case .marquee:
            VStack(spacing: 5) {
                Rectangle().fill(isFocused ? accent : Color.white.opacity(isSelected ? 0.28 : 0.08)).frame(height: 1)
                Text(label).font(navFont).tracking(PopupTypography.kerning(fontPreset) + 1.1)
                    .foregroundStyle(isFocused ? accent : .white.opacity(isSelected ? 1 : 0.68))
                Rectangle().fill(isFocused ? accent : Color.white.opacity(isSelected ? 0.28 : 0.08)).frame(height: 1)
            }
            .padding(.horizontal, 8).padding(.vertical, 5)
        case .ribbon:
            HStack(spacing: 9) {
                Rectangle().fill(isFocused || isSelected ? accent : Color.white.opacity(0.16)).frame(width: 3, height: 27)
                Image(systemName: icon).font(.system(size: 14, weight: .black))
                Text(label).font(navFont).tracking(PopupTypography.kerning(fontPreset) + 0.45)
            }
            .foregroundStyle(isFocused ? theme.selectedTextColor : .white.opacity(isSelected ? 0.98 : 0.68))
            .padding(.horizontal, 11).padding(.vertical, 7)
            .background(RoundedRectangle(cornerRadius: 6).fill(isFocused ? selectedFill : Color.clear))
        case .circleDock:
            VStack(spacing: 5) {
                ZStack {
                    Circle().fill(isFocused ? selectedFill : Color.black.opacity(0.62))
                    Circle().stroke(isSelected ? accent.opacity(0.86) : Color.white.opacity(0.12), lineWidth: isSelected ? 2 : 1)
                    Image(systemName: icon).font(.system(size: 19, weight: .black)).foregroundStyle(isFocused ? theme.selectedTextColor : .white)
                }.frame(width: 42, height: 42)
                Text(label).font(navFont).foregroundStyle(.white.opacity(isSelected ? 1 : 0.62)).lineLimit(1)
            }.frame(minWidth: 66)
        case .monochromeBlocks:
            Text(label).font(navFont).tracking(PopupTypography.kerning(fontPreset) + 0.55)
                .foregroundStyle(isFocused ? Color.black : .white.opacity(isSelected ? 1 : 0.65))
                .padding(.horizontal, 14).padding(.vertical, 8)
                .background(Rectangle().fill(isFocused ? Color.white : (isSelected ? Color.white.opacity(0.12) : Color.clear)))
                .overlay(Rectangle().stroke(Color.white.opacity(isSelected ? 0.48 : 0.12), lineWidth: 1))
        case .posterTabs:
            VStack(alignment: .leading, spacing: 3) {
                HStack(spacing: 7) {
                    Image(systemName: icon).font(.system(size: 13, weight: .black))
                    Text(label).font(navFont).tracking(PopupTypography.kerning(fontPreset) + 0.45).lineLimit(1)
                }
                Text(isSelected ? "NOW VIEWING" : "BROWSE")
                    .font(.system(size: 8, weight: .black, design: .rounded)).tracking(1.2)
                    .foregroundStyle(isSelected ? accent : .white.opacity(0.34))
            }
            .foregroundStyle(isFocused ? Color.black : .white.opacity(isSelected ? 1 : 0.72))
            .padding(.horizontal, 11).padding(.vertical, 7)
            .frame(minWidth: 92, alignment: .leading)
            .background(RoundedRectangle(cornerRadius: 10).fill(isFocused ? selectedFill : Color.black.opacity(0.56)))
            .overlay(RoundedRectangle(cornerRadius: 10).stroke(isSelected ? accent.opacity(0.62) : Color.white.opacity(0.10), lineWidth: 1))

        case .liquidIsland:
            HStack(spacing: 9) {
                ZStack {
                    Circle()
                        .fill(isFocused ? accent.opacity(0.18) : Color.white.opacity(isSelected ? 0.10 : 0.045))
                    Image(systemName: icon)
                        .font(.system(size: 15, weight: .bold))
                        .foregroundStyle(isFocused ? Color.black.opacity(0.82) : (isSelected ? accent : Color.white.opacity(0.76)))
                }
                .frame(width: 26, height: 26)
                Text(label)
                    .font(navFont)
                    .tracking(PopupTypography.kerning(fontPreset) * 0.55)
                    .lineLimit(1)
                if isSelected && !isFocused {
                    Circle().fill(accent).frame(width: 5, height: 5)
                }
            }
            .foregroundStyle(isFocused ? Color.black : Color.white.opacity(isSelected ? 1.0 : 0.68))
            .padding(.horizontal, 10)
            .padding(.vertical, 6)
            .background(
                RoundedRectangle(cornerRadius: 16, style: .continuous)
                    .fill(isFocused ? selectedFill : (isSelected ? Color.white.opacity(0.10) : Color.clear))
            )
            .overlay(
                RoundedRectangle(cornerRadius: 12, style: .continuous)
                    .stroke(isFocused ? Color.white.opacity(0.82) : (isSelected ? accent.opacity(0.42) : Color.clear), lineWidth: 1)
            )
            .shadow(color: isFocused ? Color.white.opacity(0.18) : .clear, radius: 10, y: 3)

        case .studioChrome:
            VStack(spacing: 5) {
                Rectangle()
                    .fill(isFocused ? accent : (isSelected ? accent.opacity(0.56) : Color.white.opacity(0.12)))
                    .frame(height: isFocused ? 3 : 1)
                HStack(spacing: 7) {
                    Image(systemName: icon)
                        .font(.system(size: 13, weight: .bold))
                        .foregroundStyle(isFocused || isSelected ? accent : Color.white.opacity(0.48))
                    Text(label)
                        .font(navFont)
                        .tracking(PopupTypography.kerning(fontPreset) + 0.75)
                        .lineLimit(1)
                }
                .foregroundStyle(.white.opacity(isFocused ? 1.0 : (isSelected ? 0.92 : 0.60)))
                Rectangle()
                    .fill(Color.white.opacity(isFocused ? 0.20 : 0.06))
                    .frame(height: 1)
            }
            .padding(.horizontal, 11)
            .padding(.vertical, 6)
            .background(Rectangle().fill(isFocused ? selectedFill : Color.clear))

        case .broadcastDeck:
            VStack(alignment: .leading, spacing: 3) {
                HStack(spacing: 6) {
                    Image(systemName: icon).font(.system(size: 11, weight: .black))
                    Text(contextLabel)
                        .font(.system(size: 8, weight: .black, design: .rounded))
                        .tracking(1.15)
                }
                .foregroundStyle(isFocused || isSelected ? accent : Color.white.opacity(0.34))
                Text(label)
                    .font(navFont)
                    .tracking(PopupTypography.kerning(fontPreset) + 0.30)
                    .lineLimit(1)
                    .foregroundStyle(.white.opacity(isFocused ? 1.0 : (isSelected ? 0.92 : 0.62)))
            }
            .padding(.horizontal, 10)
            .padding(.vertical, 6)
            .frame(minWidth: 90, alignment: .leading)
            .background(RoundedRectangle(cornerRadius: 9, style: .continuous).fill(isFocused ? Color.black.opacity(0.82) : Color.black.opacity(0.42)))
            .overlay(alignment: .leading) {
                RoundedRectangle(cornerRadius: 2).fill(isFocused || isSelected ? accent : Color.clear).frame(width: 3).padding(.vertical, 7)
            }
            .overlay(RoundedRectangle(cornerRadius: 9).stroke(isFocused ? accent.opacity(0.52) : Color.white.opacity(0.08), lineWidth: 1))

        case .modernPills:
            HStack(spacing: 8) {
                if isFocused || isSelected {
                    Image(systemName: icon).font(.system(size: 13, weight: .black))
                }
                Text(label)
                    .font(navFont)
                    .tracking(PopupTypography.kerning(fontPreset) * 0.65)
                    .lineLimit(1)
                if isSelected && !isFocused {
                    Circle().fill(accent).frame(width: 5, height: 5)
                }
            }
            .foregroundStyle(isFocused ? Color.black : Color.white.opacity(isSelected ? 1.0 : 0.64))
            .padding(.horizontal, 12)
            .padding(.vertical, 7)
            .background(Capsule().fill(isFocused ? selectedFill : (isSelected ? accent.opacity(0.12) : Color.white.opacity(0.045))))
            .overlay(Capsule().stroke(isFocused ? Color.white.opacity(0.88) : (isSelected ? accent.opacity(0.44) : Color.white.opacity(0.07)), lineWidth: 1))
        }
    }
}

private struct UnityPersistentTopNavigationHost: View {
    let store: CatalogStore
    @EnvironmentObject private var unityCore: UnityAppCore
    let visible: Bool
    let interactive: Bool

    var body: some View {
        TopMenuBar(store: store, shellVisible: visible)
            .opacity(visible ? 1 : 0)
            .disabled(!interactive)
            .allowsHitTesting(interactive)
            .accessibilityHidden(!visible)
            .onChange(of: visible) { _, isVisible in
                if !isVisible {
                    unityCore.setTopNavigationActive(false, origin: store.selectedTab, reason: "shell hidden")
                }
            }
    }
}

struct TopMenuBar: View {
    // vBRDC327: command handlers read the current app-scoped store synchronously,
    // but unrelated CatalogStore publications no longer rebuild the persistent top bar.
    let store: CatalogStore
    @EnvironmentObject var unityCore: UnityAppCore
    let shellVisible: Bool
    private let unityAnimations = UnityAnimationCoordinator.shared
    @AppStorage("membershipActive") private var membershipActive: Bool = false
    @AppStorage("membershipTrialExpiresAt") private var membershipTrialExpiresAt: String = ""
    @AppStorage("membershipEntitlementStatus") private var membershipEntitlementStatus: String = ProductionEntitlementStatus.unknown.rawValue
    @AppStorage("showOwnerLogin") private var showOwnerLogin: Bool = false
    @State private var membershipSecretTapCount: Int = 0
    @State private var lastMembershipSecretTapAt: Date = .distantPast
    @State private var mirrorTopMenuAutoHideTask: Task<Void, Never>? = nil
    @FocusState private var focusedTab: AppTab?
    @FocusState private var searchFocused: Bool
    // vBRDC149: capture where the top menu was entered from.  The persistent Live TV
    // root can remain visible while focus moves across Home/Movies/Shows labels, so the
    // highlighted label is not a reliable source of navigation context.
    @State private var topMenuEntryOriginTab: AppTab? = nil
    @State private var lastTopMenuDownCommandAt: TimeInterval = 0
    @AppStorage("topMenuThemePreset") private var topMenuThemePreset: String = "Classic"
    @AppStorage("topMenuAccentColor") private var topMenuAccentColor: String = "Orange"
    @AppStorage("topMenuFontPreset") private var topMenuFontPreset: String = "SF Rounded"
    @AppStorage("topMenuSizePresetV1") private var topMenuSizePreset: String = "Medium"
    @AppStorage("homeGridThemePreset") private var homeGridThemePreset: String = "Classic Glow"
    @AppStorage("topLeftDebridChannelsLogoEnabledV1") private var topLeftDebridChannelsLogoEnabled: Bool = true
    @AppStorage("signalChromeLogoSizeV346") private var signalChromeLogoSize: String = "Small"
    @AppStorage("liveTVDashboardStyleV348") private var liveTVDashboardStyle: String = "Golden"
    @AppStorage("liveTVPreviewMirrorShowTopMenuV350") private var mirrorShowTopMenu: Bool = false

    private var isPreviewMirrorLive: Bool {
        store.selectedTab == .live && SignalLiveTVDashboardStyle.normalized(liveTVDashboardStyle) == "Preview Mirror"
    }

    private var isPreviewMirrorChromeHidden: Bool {
        isPreviewMirrorLive && !mirrorShowTopMenu && !unityCore.mirrorTopMenuRevealed
    }

    private var topMenuThemeStyle: TopMenuThemeStyle { TopMenuThemeStyle.resolve(topMenuThemePreset) }

    private var previewMirrorTopMenuY: CGFloat { 34 }
    private var previewMirrorTopMenuXRatio: CGFloat { 0.485 }

    private var previewMirrorTopMenuSearchButton: some View {
        Image(systemName: "magnifyingglass")
            .font(.system(size: 15, weight: .semibold))
            .foregroundStyle(searchFocused ? topMenuSelectedAccentBase : Color.white.opacity(0.78))
            .frame(width: 28, height: 28)
            .contentShape(Circle())
            .focusable(true)
            .focused($searchFocused)
            .signalVisionFocusEffectPolicy()
            .modifier(TransparentTVFocusVisual())
            .signalMoveCommand { direction in
                if direction == .down { handleTopMenuDownCommand() }
            }
            .onTapGesture {
                store.searchActive = true
                store.status = "Search opened. Results include loaded Stremio/Cinemeta/service rows and configured catalog rows."
            }
            .clipShape(Circle())
            .compositingGroup()
            .accessibilityAddTraits(.isButton)
            .accessibilityLabel("Search")
            .background(
                GeometryReader { proxy in
                    Color.clear.preference(
                        key: SearchMenuIconFramePreferenceKey.self,
                        value: proxy.frame(in: .global)
                    )
                }
                .allowsHitTesting(false)
            )
    }

    private var topMenuUsesRail: Bool {
        topMenuThemeStyle.usesRail
    }

    private var topMenuSpacing: CGFloat {
        topMenuThemeStyle.spacing
    }

    private var topMenuRailCorner: CGFloat {
        topMenuThemeStyle.cornerRadius
    }

    // vBRDC165: size is independent from theme/font/accent. Medium is the exact
    // vBRDC164 scale; larger/smaller choices affect every theme consistently.
    private var topMenuCompactVisualScale: CGFloat {
        TopMenuSizePreset.scale(topMenuSizePreset)
    }

    private var topMenuAccentBase: Color {
        let key = topMenuThemePreset.lowercased()
        let fallback = key.contains("sapphire") || key.contains("blue") ? Color(red: 0.20, green: 0.58, blue: 1.0) : Color.orange
        return topMenuThemeStyle.accent(defaultAccent: fallback)
    }

    private var topMenuSelectedAccentBase: Color {
        TopMenuAccentColorSystem.color(for: topMenuAccentColor, themeAccent: topMenuAccentBase)
    }

    private var topMenuAccentShadow: Color { topMenuSelectedAccentBase.opacity(0.56) }

    private var topMenuRailFill: Color {
        Color.clear
    }

    private var topMenuRailStroke: Color {
        topMenuThemeStyle.railStroke(accent: topMenuSelectedAccentBase)
    }

    private func topMenuTextColor(isFocused: Bool, isSelected: Bool) -> Color {
        if isFocused { return topMenuThemeStyle.selectedTextColor }
        return isSelected ? Color.white : Color.white.opacity(0.62)
    }

    private func topMenuItemFill(isFocused: Bool, isSelected: Bool) -> Color {
        if isFocused { return topMenuThemeStyle.selectedFill(accent: topMenuSelectedAccentBase) }
        if isSelected && topMenuThemeStyle != .minimal { return Color.white.opacity(topMenuThemeStyle == .lighterGlass ? 0.16 : 0.08) }
        return Color.clear
    }

    private func topMenuItemGlow(isFocused: Bool, isSelected: Bool) -> Color {
        isFocused ? topMenuAccentBase.opacity(0.30) : (isSelected ? topMenuSelectedAccentBase.opacity(0.14) : .clear)
    }

    private func topMenuUnderlineColor(isSelected: Bool) -> Color { isSelected ? topMenuSelectedAccentBase : Color.clear }

    private var topMenuMembershipLocked: Bool {
        MembershipEntitlementManager.isLocked(
            active: membershipActive,
            entitlementStatusRaw: membershipEntitlementStatus,
            trialExpiresAt: membershipTrialExpiresAt,
            now: Date()
        )
    }

    private var visibleTabs: [AppTab] {
        // vBRDC226: entitlement lock owns the entire top-navigation surface. Do not infer
        // lock state only from a locally-present expiry date; backend locked/expired/unknown
        // states must also collapse navigation to Membership so no stale Live TV/catalog
        // focus path can bypass the paywall.
        if topMenuMembershipLocked { return [.membership] }
        return AppTab.allCases.filter { !(membershipActive && $0 == .membership) }
    }

    private func handleTopMenuDownCommand() {
        // vBRDC226 membership isolation: while entitlement is locked, DOWN may only enter
        // Membership. Never route through the generic Live TV/catalog return corridor.
        if topMenuMembershipLocked {
            store.topMenuSelectionHoldTab = nil
            store.catalogRowsPresented = false
            store.topMenuFocusLocked = false
            store.liveQuickPanelOpen = false
            searchFocused = false
            topMenuEntryOriginTab = .membership
            if store.selectedTab != .membership {
                unityCore.select(.membership, store: store, reason: "membership-only top-menu Down")
            }
            focusedTab = nil
            store.contentFocusToken &+= 1
            return
        }

        // The focused tab receives this directly in vBRDC149, with the outer menu retained
        // as a search/fallback receiver.  Suppress a duplicate parent delivery from the same
        // Siri Remote event so one DOWN can never execute two surface handoffs.
        let now = ProcessInfo.processInfo.systemUptime
        guard now - lastTopMenuDownCommandAt > 0.08 else { return }
        lastTopMenuDownCommandAt = now

        let origin = topMenuEntryOriginTab ?? store.selectedTab
        let enteredFromSettings = origin == .settings
        let settingsDestination = focusedTab ?? .settings

        if origin == .favorites {
            // vBRDC154: Favorites is a dedicated surface just like Settings, but its
            // UP -> top-menu -> DOWN corridor must return to the Favorites card rail.
            // vBRDC149's generic non-Settings branch forced every such DOWN to Live TV,
            // which made Favorites appear to jump back to Home/Live TV instead of
            // re-entering its own cards. Keep the selected tab intact and hand focus
            // explicitly back to the Favorites surface.
            store.topMenuSelectionHoldTab = nil
            store.catalogRowsPresented = false
            store.topMenuFocusLocked = false
            store.liveQuickPanelOpen = false
            focusedTab = nil
            searchFocused = false
            topMenuEntryOriginTab = nil
            store.contentFocusToken &+= 1
            return
        }

        if enteredFromSettings {
            let destination = settingsDestination
            store.topMenuSelectionHoldTab = nil
            store.topMenuFocusLocked = false
            store.liveQuickPanelOpen = false
            focusedTab = nil
            searchFocused = false
            topMenuEntryOriginTab = nil

            if store.selectedTab != destination {
                if store.selectedDetail != nil { store.selectedDetail = nil }
                if !store.detailBackStack.isEmpty { store.detailBackStack.removeAll() }
                unityCore.select(destination, store: store, reason: "top-menu Down from Settings")
            }

            if destination == .live {
                store.catalogRowsPresented = false
                Task { @MainActor in
                    await Task.yield()
                    guard store.selectedTab == .live, store.playbackURL == nil else { return }
                    store.liveTVMenuFocusEntryToken &+= 1
                }
            } else if UnitySurfaceSystem.catalogBranchActive(for: destination) {
                store.catalogRowsPresented = true
                Task { @MainActor in
                    await Task.yield()
                    guard store.selectedTab == destination, store.playbackURL == nil else { return }
                    store.contentFocusToken &+= 1
                }
            } else {
                store.catalogRowsPresented = false
                store.contentFocusToken &+= 1
            }
        } else {
            let leavingSports = store.selectedTab == .sports
            if leavingSports {
                store.clearSportsPresentationStateForNavigation(reason: "Top menu Down → Live TV")
            }
            store.topMenuSelectionHoldTab = nil
            store.catalogRowsPresented = false
            store.topMenuFocusLocked = false
            store.liveQuickPanelOpen = false
            focusedTab = nil
            searchFocused = false
            topMenuEntryOriginTab = nil

            if store.selectedTab != .live {
                unityCore.select(.live, store: store, reason: "top-menu Down to Live TV")
                Task { @MainActor in
                    await Task.yield()
                    guard store.selectedTab == .live,
                          store.playbackURL == nil else { return }
                    store.liveTVMenuFocusEntryToken &+= 1
                }
            } else {
                store.liveTVMenuFocusEntryToken &+= 1
            }
        }
    }

    private func scheduleMirrorTopMenuAutoHideIfNeeded() {
        mirrorTopMenuAutoHideTask?.cancel()
        mirrorTopMenuAutoHideTask = nil
        guard isPreviewMirrorLive,
              !mirrorShowTopMenu,
              unityCore.mirrorTopMenuRevealed else { return }
        mirrorTopMenuAutoHideTask = Task { @MainActor in
            do {
                try await Task.sleep(nanoseconds: 15_000_000_000)
            } catch {
                return
            }
            guard !Task.isCancelled,
                  isPreviewMirrorLive,
                  !mirrorShowTopMenu,
                  unityCore.mirrorTopMenuRevealed else { return }
            focusedTab = nil
            searchFocused = false
            topMenuEntryOriginTab = nil
            unityCore.setTopNavigationActive(false, origin: .live, reason: "Mirror 15-second inactivity")
            unityCore.hideMirrorTopMenu()
            store.contentFocusToken &+= 1
        }
    }

    // Build 17: isolate the original Unity chrome's nested SwiftUI builders.
    // These helpers preserve appearance, focus handlers and all tap actions.
    private func topMenuTab(_ tab: AppTab) -> some View {
                        TopMenuTabVisual(
                            tab: tab,
                            theme: topMenuThemeStyle,
                            fontPreset: topMenuFontPreset,
                            accent: topMenuSelectedAccentBase,
                            isFocused: focusedTab == tab,
                            isSelected: store.selectedTab == tab && (focusedTab == nil || focusedTab == tab)
                        )
                        .contentShape(Rectangle())
                        // vBRDC296: focus movement must stay on the native tvOS focus clock.
                        // Preserve the exact themed appearance without stacking a second
                        // SwiftUI scale animation on every remote move.
                        .scaleEffect(focusedTab == tab ? (topMenuThemeStyle.family == .minimalLine ? 1.018 : 1.030) : 1.0)
                        .focusable(true)
                        .focused($focusedTab, equals: tab)
                        .signalVisionFocusEffectPolicy()
                        .modifier(TransparentTVFocusVisual())
                        .signalMoveCommand { direction in
                            if direction == .down { handleTopMenuDownCommand() }
                        }
                        .onTapGesture {
                            if tab == .membership {
                                let now = Date()
                                if now.timeIntervalSince(lastMembershipSecretTapAt) > 4 {
                                    membershipSecretTapCount = 0
                                }
                                lastMembershipSecretTapAt = now
                                membershipSecretTapCount += 1
                                if membershipSecretTapCount >= 7 {
                                    showOwnerLogin = true
                                    membershipSecretTapCount = 0
                                }
                            } else {
                                membershipSecretTapCount = 0
                            }
                            // vBRDC081: never wrap a whole heavy surface swap in one SwiftUI
                            // animation transaction. UNITY owns the cross-surface handoff; only
                            // lightweight local focus visuals animate independently.
                            let leavingSports = store.selectedTab == .sports && tab != .sports
                            if leavingSports {
                                store.clearSportsPresentationStateForNavigation(reason: "Top menu → \(tab.rawValue)")
                            } else {
                                if store.selectedDetail != nil { store.selectedDetail = nil }
                                if !store.detailBackStack.isEmpty { store.detailBackStack.removeAll() }
                            }
                            // vBRDC129: top-menu selection and content focus are separate.
                            // The selected tab remains the visible navigation selection. Home,
                            // Movies and TV Shows enter their normal catalog rows immediately;
                            // Live TV intentionally remains on its selected top-menu item until
                            // the user presses Down into the already-mounted native grid.
                            let wasAlreadySelected = store.selectedTab == tab
                            unityCore.select(tab, store: store, reason: "top-menu selection")
                            topMenuEntryOriginTab = tab
                            if UnitySurfaceSystem.catalogBranchActive(for: tab) {
                                store.topMenuSelectionHoldTab = nil
                                store.catalogRowsPresented = true
                            } else {
                                store.catalogRowsPresented = false
                                store.topMenuSelectionHoldTab = tab == .live ? .live : nil
                            }
                            searchFocused = false

                            if UnitySurfaceSystem.catalogBranchActive(for: tab) {
                                // When selecting a different catalog tab, RootView emits the
                                // normal handoff focus token after the branch is mounted. When
                                // selecting the already-active catalog tab from the top menu,
                                // there is no selectedTab change, so explicitly re-enter rows.
                                focusedTab = nil
                                if wasAlreadySelected {
                                    store.topMenuFocusLocked = false
                                    store.contentFocusToken &+= 1
                                }
                            } else if tab == .live {
                                focusedTab = .live
                            } else {
                                // Dedicated/Sports surfaces keep their pre-vBRDC128 behavior:
                                // selecting the tab lets that surface own its normal focus path.
                                focusedTab = nil
                            }

                            if tab == .sports {
                                store.liveQuickPanelOpen = false
                                store.topMenuFocusLocked = false
                            }
                        }
    }

    private func topMenuRail(_ geo: GeometryProxy) -> some View {
                HStack(spacing: topMenuSpacing) {
                    ForEach(visibleTabs) { tab in
                        topMenuTab(tab)
                    }
                    if isPreviewMirrorLive && !topMenuMembershipLocked {
                        previewMirrorTopMenuSearchButton
                    }
                }
                .padding(.horizontal, topMenuUsesRail ? (topMenuThemeStyle.family == .marquee ? 14 : (topMenuThemeStyle.family == .studioChrome ? 6 : 10)) : 0)
                .padding(.vertical, topMenuUsesRail ? (topMenuThemeStyle.family == .iconDock ? 5 : (topMenuThemeStyle.family == .studioChrome ? 4 : 7)) : 0)
                .background(
                    Group {
                        if topMenuUsesRail {
                            RoundedRectangle(cornerRadius: topMenuRailCorner, style: .continuous)
                                .fill(topMenuThemeStyle.railFill)
                                .overlay(RoundedRectangle(cornerRadius: topMenuRailCorner, style: .continuous).stroke(topMenuRailStroke, lineWidth: 1))
                                .shadow(color: topMenuAccentShadow.opacity(topMenuThemeStyle.family == .ribbon || topMenuThemeStyle.family == .marquee ? 0.48 : (topMenuThemeStyle.family == .liquidIsland ? 0.16 : 0.28)), radius: topMenuThemeStyle.family == .ribbon ? 22 : (topMenuThemeStyle.family == .liquidIsland ? 8 : 12), y: 6)
                                .shadow(color: .black.opacity(topMenuThemeStyle.family == .iconDock ? 0.26 : (topMenuThemeStyle.family == .liquidIsland ? 0.30 : 0.48)), radius: 18, y: 8)
                        }
                    }
                )
                // vBRDC149: a theme change gets a fresh navigation subtree.  tvOS may
                // otherwise retain the focused child identity across an @AppStorage update,
                // leaving geometry/background modifiers from the previous family attached to
                // the new label until another focus transition.  The ID is presentation-only.
                .id("top-menu-theme|\(topMenuThemeStyle.rawValue)|\(topMenuFontPreset)|\(topMenuAccentColor)|\(TopMenuSizePreset.normalized(topMenuSizePreset))")
                .scaleEffect(topMenuCompactVisualScale, anchor: .center)
                .position(x: isPreviewMirrorLive ? geo.size.width * previewMirrorTopMenuXRatio : geo.size.width * 0.46, y: isPreviewMirrorLive ? previewMirrorTopMenuY : (topMenuThemeStyle.family == .iconDock ? 54 : 58))
                .signalVisionFocusSection()
    }

    private func topMenuChrome(_ geo: GeometryProxy) -> some View {
            ZStack(alignment: .topLeading) {
                // v572: global app wordmark lives in the absolute top-left app chrome; native transparent top menu keeps stable focus position.
                Rectangle()
                    .fill(Color.clear)
                    .frame(height: 96)
                    .ignoresSafeArea(edges: .top)

                // Mirror renders one Signal wordmark in its own header; never duplicate
                // the global app wordmark, including after the top menu is revealed.
                if topLeftDebridChannelsLogoEnabled && !isPreviewMirrorLive {
                    DebridChannelsChromeWordmark()
                        .position(x: 20 + SignalChromeLogoSize.width(signalChromeLogoSize) / 2, y: 24)
                        .zIndex(2)
                }

                topMenuRail(geo)

                if !topMenuMembershipLocked {
                    if !isPreviewMirrorLive {
                        HStack(spacing: 28) {
                            Image(systemName: "magnifyingglass")
                                .font(.system(size: 20, weight: .semibold))
                                .foregroundStyle(searchFocused ? topMenuSelectedAccentBase : Color.white.opacity(0.78))
                                .frame(width: 48, height: 48)
                                .background(Circle().fill(Color.clear))
                                .contentShape(Circle())
                                .focusable(true)
                                .focused($searchFocused)
                                .onTapGesture {
                                    store.searchActive = true
                                    store.status = "Search opened. Results include loaded Stremio/Cinemeta/service rows and configured catalog rows."
                                }
                                .clipShape(Circle())
                                .compositingGroup()
                                .accessibilityAddTraits(.isButton)
                                .background(
                                    GeometryReader { proxy in
                                        Color.clear.preference(
                                            key: SearchMenuIconFramePreferenceKey.self,
                                            value: proxy.frame(in: .global)
                                        )
                                    }
                                    .allowsHitTesting(false)
                                )

                            LiveClockText(fontSize: 18)
                        }
                        .position(x: geo.size.width - max(150, geo.size.width * 0.078), y: 58)
                    }
                }
            }
            .frame(width: geo.size.width, height: 100, alignment: .top)
            // vBRDC350: Mirror defaults to its clean dashboard chrome. Hidden global
            // navigation cannot steal focus; the second Up from the top row requests the
            // existing top-navigation focus session and reveals the menu. The optional
            // persistent mode keeps it up but positions search/time/menu ABOVE the header.
            .opacity(isPreviewMirrorChromeHidden ? 0 : 1)
            .disabled(isPreviewMirrorChromeHidden)
            .allowsHitTesting(!isPreviewMirrorChromeHidden)
    }

    var body: some View {
        GeometryReader { geo in
            topMenuChrome(geo)
        }
        .frame(height: 122)
        .background(Color.clear.ignoresSafeArea(edges: .top))
        .zIndex(6000)
        .signalVisionFocusSection()
        .signalMoveCommand { direction in
            if isPreviewMirrorLive { unityCore.touchMirrorTopMenu() }
            if NavigationFocusAuditManager.shared.topMenuShouldYieldToContent(direction: direction) {
                handleTopMenuDownCommand()
            }
        }
        .onAppear { scheduleMirrorTopMenuAutoHideIfNeeded() }
        .onChange(of: unityCore.mirrorTopMenuActivityRevision) { _, _ in
            scheduleMirrorTopMenuAutoHideIfNeeded()
        }
        .onChange(of: unityCore.mirrorTopMenuRevealed) { _, _ in
            scheduleMirrorTopMenuAutoHideIfNeeded()
        }
        .onChange(of: mirrorShowTopMenu) { _, _ in
            scheduleMirrorTopMenuAutoHideIfNeeded()
        }
        .onChange(of: unityCore.topNavigationFocusRequest) { _, _ in
            guard shellVisible else { return }
            if isPreviewMirrorLive { unityCore.revealMirrorTopMenu() }
            // vBRDC182: legacy callers still increment CatalogStore.menuFocusToken, but the
            // persistent shell receives one UNITY focus request rather than every screen
            // directly reaching into TopMenuBar state.
            let requestedOrigin: AppTab = topMenuMembershipLocked ? .membership : unityCore.activeTab
            topMenuEntryOriginTab = requestedOrigin
            store.topMenuFocusLocked = false
            // vBRDC235: selection and focus are intentionally separate. When Live TV
            // climbs into the persistent bar, enter at the first logical chip (Home)
            // instead of snapping focus back to the already-selected Live TV tab.
            focusedTab = topMenuMembershipLocked ? .membership : (requestedOrigin == .live ? .home : requestedOrigin)
            searchFocused = false
        }
        .onChange(of: focusedTab) { newTab in
            if newTab != nil && isPreviewMirrorLive { unityCore.touchMirrorTopMenu() }
            if newTab != nil {
                if topMenuEntryOriginTab == nil { topMenuEntryOriginTab = store.selectedTab }
                unityAnimations.registerNavigationActivity(source: "top-menu")
                unityCore.setTopNavigationActive(true, origin: store.selectedTab, reason: "tab focus entered")
            } else if !searchFocused {
                unityCore.setTopNavigationActive(false, origin: store.selectedTab, reason: "tab focus exited")
            }
            // v716: restore v702 top-menu reachability.  The quick-panel row handler owns
            // Up/Down movement while the row has focus; the menu must not be globally blocked
            // after the quick panel has been opened.  This removes the sticky focus trap that
            // prevented returning to Home/Movies/TV Shows from the top bar.
            if newTab != nil {
                store.topMenuFocusLocked = false
            }
        }
        .onChange(of: searchFocused) { focused in
            if focused && isPreviewMirrorLive { unityCore.touchMirrorTopMenu() }
            if focused {
                unityAnimations.registerNavigationActivity(source: "top-menu-search")
                unityCore.setTopNavigationActive(true, origin: store.selectedTab, reason: "search focus entered")
            } else if focusedTab == nil {
                unityCore.setTopNavigationActive(false, origin: store.selectedTab, reason: "search focus exited")
            }
        }
        .onChange(of: store.selectedTab) { _, tab in
            if tab != .live { unityCore.hideMirrorTopMenu() }
        }
        .onChange(of: shellVisible) { _, visible in
            if !visible {
                mirrorTopMenuAutoHideTask?.cancel()
                mirrorTopMenuAutoHideTask = nil
                unityCore.hideMirrorTopMenu()
                focusedTab = nil
                searchFocused = false
                topMenuEntryOriginTab = nil
                unityCore.setTopNavigationActive(false, origin: store.selectedTab, reason: "persistent shell hidden")
            }
        }
        .onDisappear {
            mirrorTopMenuAutoHideTask?.cancel()
            mirrorTopMenuAutoHideTask = nil
        }
    }
}

struct GlobalSearchScreen: View {
    @EnvironmentObject var store: CatalogStore
    @EnvironmentObject var unityCore: UnityAppCore
    private let unityAnimations = UnityAnimationCoordinator.shared
    @Environment(\.scenePhase) private var scenePhase
    // vBRDC327: one persistent Live TV/EPG/Gracenote owner app-wide.
    @ObservedObject var liveModel: LiveTVSourceModel
    @AppStorage("tmdbApiKey") private var tmdbApiKey: String = ""
    // v1083: Search owns its results and presentation state. Keep the query alive while a
    // Search-origin detail or VOD session temporarily covers the Search screen, so closing
    // either returns to the same Search results instead of revealing Home/main catalogs.
    @SceneStorage("globalSearchQuery") private var query: String = ""
    @SceneStorage("globalSearchFocusedMediaID") private var rememberedFocusedMediaID: String = ""
    // v1010 Phase 4B: one cancellation token/task owns the complete unified search.
    // Local official matches are published immediately; remote providers share one debounce.
    @State private var unifiedResults: [MediaItem] = []
    @State private var unifiedSearchToken: Int = 0
    @State private var isSearchingUnified: Bool = false
    @StateObject private var searchAsyncRuntime = SearchAsyncTaskRuntime()
    private var unifiedSearchTask: Task<Void, Never>? {
            get { searchAsyncRuntime.unifiedSearchTask }
            nonmutating set { searchAsyncRuntime.unifiedSearchTask = newValue }
        }
    private var detailHydrationTask: Task<Void, Never>? {
            get { searchAsyncRuntime.detailHydrationTask }
            nonmutating set { searchAsyncRuntime.detailHydrationTask = newValue }
        }
    // vBRDC084: prewarm the compact Production information for visible Search results
    // so opening a Search-origin Media Information popup can publish the full strip
    // immediately from the session cache instead of starting from an empty panel.
    private var productionPrefetchTask: Task<Void, Never>? {
            get { searchAsyncRuntime.productionPrefetchTask }
            nonmutating set { searchAsyncRuntime.productionPrefetchTask = newValue }
        }
    private var focusSettledPrefetchTask: Task<Void, Never>? {
            get { searchAsyncRuntime.focusSettledPrefetchTask }
            nonmutating set { searchAsyncRuntime.focusSettledPrefetchTask = newValue }
        }
    @FocusState private var focusedID: String?
    @FocusState private var focusedChannelID: Int?

    private var mergedMediaResults: [MediaItem] {
        guard query.trimmingCharacters(in: .whitespacesAndNewlines).count >= 2 else { return [] }
        return unifiedResults
    }

    private var liveResults: [LiveTVChannel] {
        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard trimmed.count >= 2 else { return [] }
        let channels = liveModel.channels
        return Array(channels.filter { channel in
            [channel.number, channel.name, channel.category, channel.source, channel.now, channel.next]
                .joined(separator: " ")
                .lowercased()
                .contains(trimmed)
        }.prefix(80))
    }

    var body: some View {
        ZStack(alignment: .topLeading) {
            UnitySurfaceBackdrop()
            LinearGradient(colors: [.black.opacity(0.58), .black.opacity(0.30), .black.opacity(0.64)], startPoint: .top, endPoint: .bottom).ignoresSafeArea()

            VStack(alignment: .leading, spacing: 22) {
                Spacer().frame(height: 116)
                HStack(alignment: .lastTextBaseline, spacing: 18) {
                    Text("Search")
                        .font(.system(size: 58, weight: .black, design: .rounded))
                        .foregroundStyle(.white)
                    Text("All Catalogs Search")
                        .font(.system(size: 13, weight: .heavy, design: .rounded))
                        .foregroundStyle(unityCore.palette.accent.opacity(0.82))
                }

                TextField("Search movies and shows…", text: $query)
                    .font(.system(size: 31, weight: .semibold, design: .rounded))
                    .foregroundStyle(.white)
                    .padding(.horizontal, 28)
                    .frame(width: 1240, height: 74)
                    .background(RoundedRectangle(cornerRadius: 18).fill(Color.white.opacity(0.10)))
                    .overlay(RoundedRectangle(cornerRadius: 18).stroke(Color.white.opacity(0.16), lineWidth: 1))
                    .onChange(of: query) { _ in
                        scheduleUnifiedSearch()
                    }

                if query.trimmingCharacters(in: .whitespacesAndNewlines).count < 2 {
                    Text("Type to search movies and shows.")
                        .font(.system(size: 22, weight: .semibold, design: .rounded))
                        .foregroundStyle(.white.opacity(0.56))
                        .padding(.top, 12)
                } else if isSearchingUnified && mergedMediaResults.isEmpty {
                    HStack(spacing: 12) {
                        ProgressView()
                        Text("Searching movies and shows…")
                            .font(.system(size: 20, weight: .semibold, design: .rounded))
                            .foregroundStyle(.white.opacity(0.62))
                    }
                    .padding(.top, 12)
                }

                ScrollView(.vertical, showsIndicators: false) {
                    VStack(alignment: .leading, spacing: 30) {
                        if false && !liveResults.isEmpty {
                            Text("Live TV Channels")
                                .font(.system(size: 25, weight: .black, design: .rounded))
                                .foregroundStyle(.white.opacity(0.92))
                            LazyVGrid(columns: Array(repeating: GridItem(.fixed(330), spacing: 34), count: 4), spacing: 34) {
                                ForEach(liveResults) { channel in
                                    SearchLiveChannelCard(channel: channel, isFocused: focusedChannelID == channel.id)
                                        .contentShape(Rectangle())
                                        .focusable(true)
                                        .focused($focusedChannelID, equals: channel.id)
                                        .onTapGesture {
                                            store.searchActive = false
                                            store.selectedTab = .live
                                        }
                                        .accessibilityAddTraits(.isButton)
                                }
                            }
                        }

                        if !mergedMediaResults.isEmpty {
                            Text("Search Results")
                                .font(.system(size: 25, weight: .black, design: .rounded))
                                .foregroundStyle(.white.opacity(0.92))
                            LazyVGrid(columns: Array(repeating: GridItem(.fixed(408), spacing: 46), count: 4), spacing: 58) {
                                ForEach(mergedMediaResults) { item in
                                    SearchResultCard(item: item, isFocused: focusedID == item.id)
                                        .contentShape(RoundedRectangle(cornerRadius: focusedID == item.id ? 26 : 20, style: .continuous))
                                        .focusable(true)
                                        .focused($focusedID, equals: item.id)
                                        .onTapGesture {
                                            // v503: Search result selection must open the popup immediately.
                                            // Do not block the UI on trailer prewarm, addon scans, TMDB external-id lookup,
                                            // or any resolver metadata hydration. Open the lightweight TMDB/Cinemeta card now,
                                            // then quietly upgrade the selected detail if richer resolver metadata arrives.
                                            let selectedSearchID = item.id
                                            let selectedSearchIdentity = store.canonicalCatalogIdentityKey(for: item)
                                            // v1083: Keep Search mounted beneath its own media popup. Previously this
                                            // set searchActive=false, which exposed the selected Home/main tab and made
                                            // Search results appear to leave the Search section.
                                            rememberedFocusedMediaID = item.id
                                            store.openDetail(item, pushCurrent: false, origin: .search)
                                            detailHydrationTask?.cancel()
                                            detailHydrationTask = VODExclusiveWorkRegistry.start {
                                                let hydrated = await store.searchHydratedDetailItem(for: item, query: query, tmdbApiKey: tmdbApiKey)
                                                guard !Task.isCancelled, !VODExclusivePlaybackGate.isActive else { return }
                                                await MainActor.run {
                                                    guard let currentDetail = store.selectedDetail,
                                                          currentDetail.id == selectedSearchID
                                                            || store.canonicalCatalogIdentityKey(for: currentDetail) == selectedSearchIdentity else { return }
                                                    // vBRDC159: artwork-only hydration is still a real update. The
                                                    // old gate ignored a newly resolved clearlogo whenever id/poster/
                                                    // backdrop stayed unchanged, which is exactly the Search/Favorites
                                                    // VOD logo regression. Merge every materially enriched result.
                                                    if hydrated != currentDetail {
                                                        // Keep the already-visible TMDB popup metadata/credits/artwork. Hydration is only
                                                        // supposed to improve resolver identity for Search Links; it must not blank the
                                                        // movie information, cast, or poster after the popup has opened.
                                                        let preserved = MediaItem(
                                                            // v623: keep the visible search detail identity stable.
                                                            // Resolver hydration can swap TMDB -> IMDb/Cinemeta ids,
                                                            // but changing selectedDetail.id while the Details Stage is open
                                                            // resets the panel and can auto-dismiss Source Intelligence.
                                                            id: currentDetail.id,
                                                            tmdbId: currentDetail.tmdbId ?? hydrated.tmdbId,
                                                            imdbId: currentDetail.imdbId ?? hydrated.imdbId,
                                                            tvdbId: currentDetail.tvdbId ?? hydrated.tvdbId,
                                                            title: currentDetail.title.isEmpty ? hydrated.title : currentDetail.title,
                                                            year: currentDetail.year.isEmpty ? hydrated.year : currentDetail.year,
                                                            type: currentDetail.type.isEmpty ? hydrated.type : currentDetail.type,
                                                            catalog: hydrated.catalog,
                                                            description: currentDetail.description.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? hydrated.description : currentDetail.description,
                                                            genres: currentDetail.genres.isEmpty ? hydrated.genres : currentDetail.genres,
                                                            rating: currentDetail.rating.isEmpty ? hydrated.rating : currentDetail.rating,
                                                            posterURL: currentDetail.posterURL ?? hydrated.posterURL,
                                                            landscapeURL: currentDetail.landscapeURL ?? hydrated.landscapeURL,
                                                            logoURL: currentDetail.logoURL ?? hydrated.logoURL,
                                                            previewURL: currentDetail.previewURL ?? hydrated.previewURL,
                                                            addonName: hydrated.addonName ?? currentDetail.addonName,
                                                            addonIconURL: hydrated.addonIconURL ?? currentDetail.addonIconURL,
                                                            seasonNumber: currentDetail.seasonNumber ?? hydrated.seasonNumber,
                                                            episodeNumber: currentDetail.episodeNumber ?? hydrated.episodeNumber,
                                                            cast: currentDetail.cast.isEmpty ? hydrated.cast : currentDetail.cast,
                                                            directors: currentDetail.directors.isEmpty ? hydrated.directors : currentDetail.directors,
                                                            castMembers: currentDetail.castMembers.isEmpty ? hydrated.castMembers : currentDetail.castMembers,
                                                            airDateString: currentDetail.airDateString ?? hydrated.airDateString,
                                                            episodeDateStrings: currentDetail.episodeDateStrings.isEmpty ? hydrated.episodeDateStrings : currentDetail.episodeDateStrings,
                                                            // vBRDC066: Search detail hydration must never erase a franchise shelf that
                                                            // TMDB already attached to the visible media profile.
                                                            franchiseItems: currentDetail.franchiseItems.isEmpty ? hydrated.franchiseItems : currentDetail.franchiseItems
                                                        )
                                                        store.selectedDetail = preserved
                                                    }
                                                }
                                            }
                                        }
                                        .accessibilityElement(children: .combine)
                                        .accessibilityAddTraits(.isButton)
                                }
                            }
                        }
                    }
                    .padding(.bottom, 140)
                }
                .frame(maxHeight: 690)
            }
            .padding(.leading, 86)
        }
        .onAppear {
            // vBRDC066: Search is allowed to outlive a Search-origin detail/player. If an
            // interrupted VOD dismissal left the process-wide exclusivity gate stale, clear
            // it before Search schedules any work so the spinner can never be owned by a
            // no-op VODExclusiveWorkRegistry task.
            store.recoverCatalogInteractivity(reason: "Search appeared")
            // v499: Search must open instantly. Use retained/cached Live TV data here;
            // do not trigger a source/guide network refresh from the Search screen.
            liveModel.loadCachedOrDemo()
            restoreSearchResultFocus(in: mergedMediaResults)
            if query.trimmingCharacters(in: .whitespacesAndNewlines).count >= 2 {
                scheduleUnifiedSearch()
            }
        }
        .onChange(of: focusedID) { focusedResultID in
            if let focusedResultID, !focusedResultID.isEmpty {
                unityAnimations.registerNavigationActivity(source: "search-results")
                // vBRDC158: do not write SceneStorage for every fly-by focus step. The
                // selected result is committed after focus settles (and immediately on Select).
                scheduleSearchProductionPrefetch(in: mergedMediaResults, prioritizedID: focusedResultID)
            }
        }
        .onChange(of: focusedChannelID) { focusedChannelID in
            if focusedChannelID != nil { unityAnimations.registerNavigationActivity(source: "search-live") }
        }
        .onChange(of: store.selectedDetail?.id) { selectedDetailID in
            // The Search screen remains mounted below a Search-owned detail. Reassert the
            // exact result only after the popup closes so tvOS cannot fall through to Home.
            guard selectedDetailID == nil, store.searchActive else { return }
            Task { @MainActor in
                await Task.yield()
                restoreSearchResultFocus(in: mergedMediaResults)
            }
        }
        .onChange(of: store.playbackURL?.absoluteString) { activePlaybackURL in
            // vBRDC066 regression guard: returning from a movie launched by Search does not
            // necessarily remount GlobalSearchScreen. Reconcile the VOD gate on the actual
            // playback->nil edge, then restart the existing query after one render turn.
            guard activePlaybackURL == nil, store.searchActive else { return }
            Task { @MainActor in
                await Task.yield()
                store.recoverCatalogInteractivity(reason: "Search returned from playback")
                isSearchingUnified = false
                if query.trimmingCharacters(in: .whitespacesAndNewlines).count >= 2 {
                    scheduleUnifiedSearch()
                }
            }
        }
        .onChange(of: scenePhase) { phase in
            if phase == .active {
                if query.trimmingCharacters(in: .whitespacesAndNewlines).count >= 2 {
                    scheduleUnifiedSearch()
                }
            } else {
                unifiedSearchToken &+= 1
                unifiedSearchTask?.cancel()
                unifiedSearchTask = nil
                detailHydrationTask?.cancel()
                detailHydrationTask = nil
                productionPrefetchTask?.cancel()
                productionPrefetchTask = nil
                focusSettledPrefetchTask?.cancel()
                focusSettledPrefetchTask = nil
                isSearchingUnified = false
            }
        }
        .onDisappear {
            unifiedSearchToken &+= 1
            unifiedSearchTask?.cancel()
            unifiedSearchTask = nil
            detailHydrationTask?.cancel()
            detailHydrationTask = nil
            productionPrefetchTask?.cancel()
            productionPrefetchTask = nil
            focusSettledPrefetchTask?.cancel()
            focusSettledPrefetchTask = nil
            isSearchingUnified = false
        }
        .signalVisionExitCommand {
            // Explicitly leaving Search starts clean next time. Closing a detail or returning
            // from playback does not run this path, so the current query/results stay owned
            // by Search for that complete interaction.
            query = ""
            rememberedFocusedMediaID = ""
            unifiedResults = []
            focusedID = nil
            store.searchActive = false
        }
    }

    private func restoreSearchResultFocus(in results: [MediaItem]) {
        guard !results.isEmpty else {
            focusedID = nil
            return
        }
        if !rememberedFocusedMediaID.isEmpty,
           results.contains(where: { $0.id == rememberedFocusedMediaID }) {
            focusedID = rememberedFocusedMediaID
        } else {
            focusedID = results.first?.id
            rememberedFocusedMediaID = results.first?.id ?? ""
        }
    }

    private func scheduleSearchProductionPrefetch(in results: [MediaItem], prioritizedID: String?) {
        focusSettledPrefetchTask?.cancel()
        guard !results.isEmpty else { return }
        let expectedID = prioritizedID
        focusSettledPrefetchTask = Task { @MainActor in
            // vBRDC158: vertical Search scrolling must never launch/cancel metadata work for
            // every fly-by card. Only prewarm after focus has actually settled.
            try? await Task.sleep(nanoseconds: 360_000_000)
            guard !Task.isCancelled, focusedID == expectedID else { return }
            if let expectedID, !expectedID.isEmpty { rememberedFocusedMediaID = expectedID }
            guard await UnityFrameRuntime.shared.waitUntilPermitted(.backgroundPrefetch, maxWait: 1.0) else { return }
            guard !Task.isCancelled, focusedID == expectedID else { return }
            prewarmSearchProductionDetails(in: results, prioritizedID: expectedID)
            focusSettledPrefetchTask = nil
        }
    }

    private func prewarmSearchProductionDetails(in results: [MediaItem], prioritizedID: String?) {
        let key = tmdbApiKey.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !key.isEmpty, !results.isEmpty, !VODExclusivePlaybackGate.isActive else { return }

        // UNITY performance rule: prewarm only the result that currently owns focus.
        // Loading production records for every visible card would trade one latency issue
        // for background network/JSON churn while the user is trying to navigate Search.
        let candidate = prioritizedID.flatMap { wanted in results.first(where: { $0.id == wanted }) } ?? results.first
        guard let candidate else { return }

        productionPrefetchTask?.cancel()
        productionPrefetchTask = VODExclusiveWorkRegistry.start {
            guard !Task.isCancelled, !VODExclusivePlaybackGate.isActive else { return }
            _ = await PopupHeaderDetailsService.shared.details(for: candidate, apiKey: key)
        }
    }

    private func scheduleUnifiedSearch() {
        unifiedSearchToken += 1
        let token = unifiedSearchToken
        let currentQuery = query.trimmingCharacters(in: .whitespacesAndNewlines)
        let key = tmdbApiKey
        unifiedSearchTask?.cancel()

        guard currentQuery.count >= 2 else {
            unifiedResults = []
            isSearchingUnified = false
            focusedID = nil
            return
        }

        // Publish the flattened built-in/local index before any debounce or network wait.
        unifiedResults = store.unifiedSearchImmediateResults(for: currentQuery)
        restoreSearchResultFocus(in: unifiedResults)
        scheduleSearchProductionPrefetch(in: unifiedResults, prioritizedID: focusedID)

        // vBRDC066: never show a network-search spinner if the process-wide VOD gate would
        // reject the task. The retained local results remain usable and the playback->nil
        // observer above restarts the remote search when the player actually releases.
        guard !VODExclusivePlaybackGate.isActive else {
            isSearchingUnified = false
            unifiedSearchTask = nil
            return
        }
        isSearchingUnified = true

        unifiedSearchTask = VODExclusiveWorkRegistry.start {
            defer {
                if token == unifiedSearchToken { isSearchingUnified = false }
            }
            try? await Task.sleep(nanoseconds: 250_000_000)
            guard !Task.isCancelled, token == unifiedSearchToken, !VODExclusivePlaybackGate.isActive else { return }
            let results = await store.unifiedSearchResults(for: currentQuery, tmdbApiKey: key)
            guard !Task.isCancelled, token == unifiedSearchToken, !VODExclusivePlaybackGate.isActive else { return }
            unifiedResults = results
            restoreSearchResultFocus(in: results)
            scheduleSearchProductionPrefetch(in: results, prioritizedID: focusedID)
        }
    }
}

struct AddonSearchStatusStrip: View {
    let statuses: [AddonSearchProviderStatus]

    var body: some View {
        ScrollView(.horizontal, showsIndicators: false) {
            HStack(spacing: 8) {
                ForEach(statuses.prefix(12)) { status in
                    HStack(spacing: 7) {
                        if status.state == .loading {
                            ProgressView()
                                .scaleEffect(0.55)
                        } else {
                            Circle()
                                .fill(tint(for: status.state).opacity(0.9))
                                .frame(width: 7, height: 7)
                        }
                        Text(status.provider)
                            .font(.system(size: 11, weight: .black, design: .rounded))
                            .foregroundStyle(.white.opacity(0.78))
                            .lineLimit(1)
                        Text(status.state.rawValue)
                            .font(.system(size: 10, weight: .heavy, design: .rounded))
                            .foregroundStyle(tint(for: status.state).opacity(0.90))
                        if status.resultCount > 0 {
                            Text("\(status.resultCount)")
                                .font(.system(size: 10, weight: .black, design: .rounded))
                                .foregroundStyle(.black.opacity(0.82))
                                .padding(.horizontal, 5)
                                .padding(.vertical, 2)
                                .background(Capsule().fill(tint(for: status.state).opacity(0.90)))
                        }
                    }
                    .padding(.horizontal, 10)
                    .padding(.vertical, 6)
                    .background(Capsule().fill(Color.white.opacity(0.075)))
                    .overlay(Capsule().stroke(tint(for: status.state).opacity(0.22), lineWidth: 1))
                }
            }
        }
    }

    private func tint(for state: AddonSearchProviderState) -> Color {
        switch state {
        case .loading: return .cyan
        case .results: return .green
        case .noResults: return .white
        case .timedOut: return .orange
        case .failed: return .red
        }
    }
}

struct SearchResultCard: View {
    let item: MediaItem
    let isFocused: Bool
    @AppStorage("homeGridThemePreset") private var homeGridThemePreset: String = "Classic Glow"

    // v621: Search cards must never expand beyond the grid slot; focus uses glow/ring only.
    private var cardWidth: CGFloat { 360 }
    private var cardHeight: CGFloat { 202 }
    private var cornerRadius: CGFloat { isFocused ? 24 : 20 }

    var body: some View {
        VStack(alignment: .leading, spacing: 12) {
            ZStack(alignment: .bottomLeading) {
                ZStack {
                    Color.black.opacity(0.34)
                    RemoteImageFit(url: item.landscapeURL ?? item.posterURL, mode: .fit, maxPixelSize: 768)
                        .padding(2)
                }
                    .frame(width: cardWidth, height: cardHeight)
                    .clipped()
                    .clipShape(RoundedRectangle(cornerRadius: cornerRadius, style: .continuous))
                HomeGridThemeOverlay(theme: homeGridThemePreset, focused: isFocused)
                    .clipShape(RoundedRectangle(cornerRadius: cornerRadius, style: .continuous))
                    .overlay(
                        LinearGradient(
                            colors: [.clear, .black.opacity(isFocused ? 0.52 : 0.30)],
                            startPoint: .center,
                            endPoint: .bottom
                        )
                        .clipShape(RoundedRectangle(cornerRadius: cornerRadius, style: .continuous))
                    )
                    .overlay(
                        UnityCatalogCardChrome(item: item, focused: isFocused, cornerRadius: cornerRadius)
                    )
                    .shadow(color: isFocused ? UnityMediaVisualAccent.accent(for: item).opacity(0.30) : .clear, radius: isFocused ? 20 : 0)

                if let resume = PlaybackResumeCacheManager.shared.resumeEntry(for: item) {
                    ContinueWatchingBadge(entry: resume, compact: !isFocused)
                        .padding(12)
                        .frame(width: cardWidth, height: cardHeight, alignment: .topTrailing)
                }

                if isFocused {
                    VStack(alignment: .leading, spacing: 4) {
                        Text(item.title)
                            .font(.system(size: 25, weight: .black, design: .rounded))
                            .foregroundStyle(.white)
                            .lineLimit(1)
                        Text("\(item.year) • \(item.catalog)")
                            .font(.system(size: 15, weight: .heavy, design: .rounded))
                            .foregroundStyle(.white.opacity(0.82))
                            .lineLimit(1)
                    }
                    .padding(.horizontal, 16)
                    .padding(.bottom, 13)
                    .frame(width: cardWidth, alignment: .leading)
                }
            }
            .frame(width: cardWidth, height: cardHeight)

            if !isFocused {
                Text(item.title)
                    .font(.system(size: 23, weight: .bold, design: .rounded))
                    .foregroundStyle(.white)
                    .lineLimit(1)
                Text("\(item.year) • \(item.catalog)")
                    .font(.system(size: 15, weight: .semibold, design: .rounded))
                    .foregroundStyle(.white.opacity(0.54))
                    .lineLimit(1)
            }
        }
        .frame(width: cardWidth, alignment: .leading)
        .scaleEffect(1.0)
        .offset(y: 0)
        .shadow(color: isFocused ? .black.opacity(0.84) : .black.opacity(0.38), radius: isFocused ? 26 : 10, y: isFocused ? 18 : 6)
        .modifier(FocusedSidewaysCardEffect(isFocused: isFocused))
    }
}

struct SearchLiveChannelCard: View {
    let channel: LiveTVChannel
    let isFocused: Bool

    var body: some View {
        HStack(spacing: 14) {
            ZStack {
                RoundedRectangle(cornerRadius: 16).fill(Color.black.opacity(0.24))
                if let url = PremiumArtworkURL.url(channel.iconURL), !channel.iconURL.isEmpty {
                    AsyncImage(url: url) { phase in
                        switch phase {
                        case .success(let image): image.resizable().scaledToFit().padding(10)
                        default: Text(channel.logo).font(.system(size: 25, weight: .black)).foregroundStyle(.white)
                        }
                    }
                } else {
                    Text(channel.logo).font(.system(size: 25, weight: .black)).foregroundStyle(.white)
                }
            }
            .frame(width: 74, height: 58)
            VStack(alignment: .leading, spacing: 5) {
                Text(channel.name).font(.system(size: 17, weight: .black, design: .rounded)).foregroundStyle(.white).lineLimit(1)
                Text("\(channel.number) • \(channel.source)").font(.system(size: 14, weight: .heavy)).foregroundStyle(.white.opacity(0.62)).lineLimit(1)
                Text(channel.now).font(.system(size: 14, weight: .semibold)).foregroundStyle(.white.opacity(0.48)).lineLimit(1)
            }
        }
        .padding(14)
        .frame(width: 278, height: 94, alignment: .leading)
        .background(RoundedRectangle(cornerRadius: 18).fill(isFocused ? Color.white.opacity(0.16) : Color.white.opacity(0.07)))
        .overlay(RoundedRectangle(cornerRadius: 18).stroke(isFocused ? Color.cyan.opacity(0.65) : Color.white.opacity(0.10), lineWidth: isFocused ? 2 : 1))
        .scaleEffect(isFocused ? 1.07 : 1.0)
        .offset(y: isFocused ? -7 : 0)
        .shadow(color: .black.opacity(isFocused ? 0.78 : 0.32), radius: isFocused ? 24 : 10, y: isFocused ? 18 : 6)
        .animation(.spring(response: 0.24, dampingFraction: 0.76), value: isFocused)
    }
}



// MARK: - v220 Grid Overlay Catalog Shelves

// vBRDC216: The main Home/Movies/Shows catalog now uses the exact same fixed-slot
// vertical row presentation path as the catalog browser mounted over VOD/Live TV playback.
// Row identity/focus swaps are atomic with animations disabled; there is no added root offset,
// opacity glide, second row tree, crossfade, or delayed compositor movement. This is intentional:
// the playback catalog's stable, instant Up/Down behavior is the reference implementation.
struct GridOSCatalogOverlay: View {
    @EnvironmentObject var store: CatalogStore
    @EnvironmentObject var unityCore: UnityAppCore
    @Environment(\.scenePhase) private var scenePhase
    @Environment(\.accessibilityReduceMotion) private var accessibilityReduceMotion
    private let unityAnimations = UnityAnimationCoordinator.shared
    @AppStorage("gridLockedMode") private var gridLockedMode: Bool = false
    @AppStorage("liveTVGridThemePreset") private var liveTVGridThemePreset: String = "Classic Dark"
    @AppStorage("catalogRowScrollingAnimationPreset") private var catalogRowScrollingAnimationPreset: String = UnityCatalogRowMotionStyle.defaultName
    @AppStorage("appCanvasExpandedV1") private var appCanvasExpanded: Bool = false
    @AppStorage("tmdbApiKey") private var heroTMDBApiKey: String = ""
    let filter: String?
    let surfaceHandoffActive: Bool
    // vBRDC184: the same production catalog shell can be opened over an active Live TV
    // or VOD session. This mode changes only lifecycle/focus gating; rows, card renderers,
    // filters, provider order, selection memory, and Media Information remain shared.
    var playbackBrowseMode: Bool = false
    var onPlaybackBrowseClose: (() -> Void)? = nil
    // vBRDC309: the main catalog shell may retain its SwiftUI state while another app
    // surface owns the screen, but its heavyweight hero/card/image subtree must not stay
    // mounted at opacity 0. That hidden subtree was still decoding/publishing artwork and
    // reacting to catalog revisions behind Settings, Live TV and Guide.
    var presentationActive: Bool = true

    private var playbackBrowseCatalogWorkAllowed: Bool {
        playbackBrowseMode || (store.playbackURL == nil && !VODExclusivePlaybackGate.isActive)
    }

    private var playbackBrowseBranchActive: Bool {
        playbackBrowseMode || UnitySurfaceSystem.catalogBranchActive(for: store.selectedTab)
    }

    private var playbackBrowseRowsPresented: Bool {
        playbackBrowseMode || store.catalogRowsPresented
    }
    @FocusState private var focusedRow: Int?
    // vBRDC109: retain visual focus independently of tvOS FocusState for exactly the
    // cross-surface handoff window. This prevents the focused card's 390x220 geometry,
    // -6 resting offset, sideways effect and glow from changing while the surface fades.
    @State private var surfaceHandoffVisualFocusPinned: Bool = false
    @StateObject private var catalogAsyncRuntime = CatalogOverlayAsyncTaskRuntime()
    private var surfaceHandoffVisualFocusReleaseTask: Task<Void, Never>? {
            get { catalogAsyncRuntime.surfaceHandoffVisualFocusReleaseTask }
            nonmutating set { catalogAsyncRuntime.surfaceHandoffVisualFocusReleaseTask = newValue }
        }
    @State private var selectedIndices: [String: Int] = [:]
    @State private var activeRowIndex: Int = 0
    @State private var rowTransitionDirection: Int = 1
    // vBRDC216: main and playback-browse catalogs share the same atomic vertical row swap.
    // This generation only owns delayed decorative-work resumption; it does not drive motion.
    @State private var verticalCatalogNavigationGeneration: UInt64 = 0
    // vBRDC214: main Home/Movies/Shows used to start hero metadata, preview resolution,
    // and large artwork work on the same frame as every vertical row move. Playback-browse
    // catalogs skip that work and are visibly smoother. Hold decorative work until navigation
    // settles so the main catalog uses the same frame-budget behavior.
    @State private var verticalCatalogNavigationSettling: Bool = false
    // vBRDC218: the first user video exposed the real main-screen defect: during an Up/Down
    // row rebind tvOS briefly released FocusState, so FixedSlotFocusedCatalogCard changed from
    // its focused 390x220/-6 geometry to the 82% unfocused geometry and then sprang back.
    // Playback browsing has no competing top-navigation focus graph, so it does not show that
    // drop. Pin only the visual focus geometry for the main catalog until the destination row
    // owns FocusState; row data/focus still commit instantly in the same transaction.
    @State private var verticalRowVisualFocusPinned: Bool = false
    private var verticalNavigationSettleTask: Task<Void, Never>? {
        get { catalogAsyncRuntime.verticalNavigationSettleTask }
        nonmutating set { catalogAsyncRuntime.verticalNavigationSettleTask = newValue }
    }
    private var verticalFocusPinReleaseTask: Task<Void, Never>? {
        get { catalogAsyncRuntime.verticalFocusPinReleaseTask }
        nonmutating set { catalogAsyncRuntime.verticalFocusPinReleaseTask = newValue }
    }
    private var visibleArtworkHydrationTask: Task<Void, Never>? {
        get { catalogAsyncRuntime.visibleArtworkHydrationTask }
        nonmutating set { catalogAsyncRuntime.visibleArtworkHydrationTask = newValue }
    }
    private var quickPanelFocusRecoveryTask: Task<Void, Never>? {
            get { catalogAsyncRuntime.quickPanelFocusRecoveryTask }
            nonmutating set { catalogAsyncRuntime.quickPanelFocusRecoveryTask = newValue }
        }
    // Phase 0: normal vertical row entry owns a separate mount-aware focus task.
    // Exact popup/playback restoration continues through quickPanelFocusRecoveryTask.
    private var rowEntryFocusTask: Task<Void, Never>? {
            get { catalogAsyncRuntime.rowEntryFocusTask }
            nonmutating set { catalogAsyncRuntime.rowEntryFocusTask = newValue }
        }
    @State private var rowEntryFocusGeneration: UInt64 = 0
    // v1173: user navigation owns focus immediately. Any delayed row-entry/detail-restore
    // work must yield as soon as the user moves again, otherwise a stale async pass can
    // snap the fixed catalog slot back to an earlier row/card.
    @State private var lastCatalogNavigationAt: Date = .distantPast
    private var deferredRowsRebuildTask: Task<Void, Never>? {
            get { catalogAsyncRuntime.deferredRowsRebuildTask }
            nonmutating set { catalogAsyncRuntime.deferredRowsRebuildTask = newValue }
        }
    // vBRDC099: mounted catalog rows get one bounded readiness repair task so blank
    // Home/Movies/Shows shelves self-heal without requiring a focus/scroll event.
    private var catalogReadinessRecoveryTask: Task<Void, Never>? {
            get { catalogAsyncRuntime.catalogReadinessRecoveryTask }
            nonmutating set { catalogAsyncRuntime.catalogReadinessRecoveryTask = newValue }
        }
    @AppStorage("focusedCardPreviewsEnabled") private var focusedCardPreviewsEnabled: Bool = false
    @State private var focusedCardPreviewURL: URL? = nil
    @State private var focusedCardPreviewKey: String? = nil
    // vBRDC107: request ownership is media-identity based, not focus-motion based.
    // Opening Media Profile or moving among its controls must not cancel/restart the
    // same card's pending/active preview. Only a different catalog item or a real
    // exclusive playback owner tears it down.
    @State private var focusedCardPreviewRequestedKey: String? = nil
    // vBRDC116: one focused media identity gets one bounded preview session. Once its
    // 35-second preview ends, incidental Media Profile/focus publications must not restart
    // the same trailer until the user actually moves to a different catalog identity.
    @State private var focusedCardPreviewCompletedKey: String? = nil
    private var focusedCardPreviewTask: Task<Void, Never>? {
            get { catalogAsyncRuntime.focusedCardPreviewTask }
            nonmutating set { catalogAsyncRuntime.focusedCardPreviewTask = newValue }
        }
    @State private var focusedCardPreviewGeneration: UInt64 = 0
    @State private var focusedHeroMetadata: CatalogHeroMetadataSnapshot? = nil
    @State private var focusedHeroMetadataKey: String? = nil
    private var focusedHeroMetadataTask: Task<Void, Never>? {
            get { catalogAsyncRuntime.focusedHeroMetadataTask }
            nonmutating set { catalogAsyncRuntime.focusedHeroMetadataTask = newValue }
        }
    // v1061: keep the exact selected title pinned while tvOS restores the catalog focus
    // after Details closes. The anchor is released only after the visible rail resolves the
    // same canonical media identity, preventing a one-frame previous/first-row logo flash.
    private var detailHeroReleaseTask: Task<Void, Never>? {
            get { catalogAsyncRuntime.detailHeroReleaseTask }
            nonmutating set { catalogAsyncRuntime.detailHeroReleaseTask = newValue }
        }
    // v1059: transform/filter the 70+ catalog rows only when the store publishes a real
    // row revision. Focus movement now reads this stable snapshot instead of rebuilding
    // every row and item array on each Siri Remote event.
    @State private var renderedRows: [MediaRow] = []

    // v1085: focus movement can recompute hero labels many times per second. Reuse
    // immutable formatters instead of allocating ICU formatters on every card move.
    private static let catalogHeroInputDateFormatter: DateFormatter = {
        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.calendar = Calendar(identifier: .gregorian)
        formatter.dateFormat = "yyyy-MM-dd"
        return formatter
    }()

    private static let catalogHeroOutputDateFormatter: DateFormatter = {
        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.calendar = Calendar(identifier: .gregorian)
        formatter.dateFormat = "MMM d, yyyy"
        return formatter
    }()

    private var rows: [MediaRow] { renderedRows }

    // vBRDC201: playback browse already carries an explicit destination filter. The main
    // persistent catalog shell must instead bind directly to UNITY's *active* catalog tab.
    // Using the retained render-tab identity here can lag one transaction behind because
    // that shell deliberately stays mounted under Live TV. That stale identity was capable
    // of projecting Movies while TV Shows was selected (and vice versa).
    private var effectiveCatalogFilter: String? {
        if playbackBrowseMode { return filter }
        switch unityCore.activeTab {
        case .movies: return "movie"
        case .shows: return "series"
        case .home: return nil
        default: return filter
        }
    }

    private func projectedRows(from source: [MediaRow]) -> [MediaRow] {
        func normalizedKind(_ item: MediaItem) -> String {
            let raw = item.type.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            if item.seasonNumber != nil || item.episodeNumber != nil || raw == "series" || raw == "show" || raw == "tv" || raw == "episode" || raw.contains("series") || raw.contains("show") {
                return "series"
            }
            if raw == "movie" || raw == "film" || raw.contains("movie") { return "movie" }
            return raw
        }

        func strongItemKind(_ item: MediaItem) -> String? {
            let identity = item.id.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            if identity.contains("tmdb:movie:") || identity.hasPrefix("trakt-movie-") || identity.hasPrefix("trakt-cloud-movie-") { return "movie" }
            if identity.contains("tmdb:tv:") || identity.contains("tmdb:show:") || identity.hasPrefix("trakt-show-") || identity.hasPrefix("trakt-cloud-show-") { return "series" }
            return nil
        }

        func declaredRowKind(_ row: MediaRow) -> String? {
            // vBRDC199: explicit user-facing shelf names are the strongest last-mile hint
            // for stale v198 cache rows whose batch `type` was swapped. This is intentionally
            // limited to unambiguous Movie/Show wording; generic genre/network rows fall back
            // to stable row identity instead of title guessing.
            let title = row.title.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            let saysMovie = title.contains("movie") || title.contains("film")
            let saysShow = title.contains("tv show") || title.contains("shows") || title.contains("series")
            if saysMovie != saysShow { return saysMovie ? "movie" : "series" }

            let id = row.id.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            if id.hasPrefix("trakt-movie-") || id.hasPrefix("movie-") { return "movie" }
            if id.hasPrefix("trakt-show-") || id.hasPrefix("series-") || id.hasPrefix("show-") || id.hasPrefix("tv-") { return "series" }
            return nil
        }

        if let filter = effectiveCatalogFilter {
            return source.compactMap { row in
                let rowKind = declaredRowKind(row)
                guard rowKind == nil || rowKind == filter else { return nil }

                let items = row.items.compactMap { original -> MediaItem? in
                    // A canonical ID is allowed to veto stale row/type metadata. This prevents
                    // a known TMDB movie from entering TV Shows even if an old batch snapshot
                    // incorrectly labelled the entire payload as series (and vice versa).
                    if let strong = strongItemKind(original), strong != filter { return nil }
                    if rowKind == nil, normalizedKind(original) != filter { return nil }

                    var item = original
                    if let rowKind {
                        item.type = rowKind
                        if rowKind == "movie" {
                            item.seasonNumber = nil
                            item.episodeNumber = nil
                        }
                    }
                    return item
                }
                guard !items.isEmpty else { return nil }
                return MediaRow(id: row.id + "-slot-overlay-" + filter, title: row.title, items: items, presentation: row.presentation)
            }
        }
        // vBRDC195: Trakt account shelves live specifically in Movies and TV Shows.
        // Keep Home uncluttered rather than duplicating every movie/show Trakt row there.
        return source
            .filter { $0.presentation?.rowKind != "trakt" }
            .map { MediaRow(id: $0.id + "-slot-overlay", title: $0.title, items: $0.items, presentation: $0.presentation) }
    }

    private func rebuildRenderedRows(reason: String) {
        // v1173: capture the exact visible row/card before applying a provider revision.
        // Catalog providers can insert/reorder/replace rows asynchronously; preserving only
        // the numeric row/index lets the visible shelf jump to unrelated content.
        let previousRows = renderedRows
        let previousActiveRowID: String? = previousRows.indices.contains(activeRowIndex) ? previousRows[activeRowIndex].id : nil
        let previousFocusedRowID: String? = {
            guard let focusedRow, previousRows.indices.contains(focusedRow) else { return nil }
            return previousRows[focusedRow].id
        }()
        let previousActiveItem: MediaItem? = {
            guard previousRows.indices.contains(activeRowIndex) else { return nil }
            let row = previousRows[activeRowIndex]
            guard !row.items.isEmpty else { return nil }
            let index = min(max(selectedIndices[row.id, default: 0], 0), row.items.count - 1)
            return row.items[index]
        }()

        let updated = projectedRows(from: store.rows)

        // vBRDC099: provider/catalog refresh is not allowed to replace a healthy mounted
        // shelf with an empty intermediate publication. Keep the last visible snapshot while
        // the CatalogStore completeness contract says recovery is still in progress; the next
        // real row revision swaps the repaired data in place.
        if updated.isEmpty, !previousRows.isEmpty, store.catalogCompletenessNeedsRecovery {
            print("[CatalogReadiness][vBRDC099] retained visible rows during transient empty revision reason=\(reason)")
            return
        }

        // vBRDC119: a store notification may be unrelated to the actual projected catalog
        // payload (or may normalize to the same rows). Avoid touching @State/focus maps when
        // the retained rail snapshot is already exactly correct.
        guard updated != previousRows else { return }

        renderedRows = updated
        let validIDs = Set(updated.map(\.id))
        selectedIndices = selectedIndices.filter { validIDs.contains($0.key) }
        for row in updated where selectedIndices[row.id] == nil { selectedIndices[row.id] = 0 }

        if updated.isEmpty {
            activeRowIndex = 0
            focusedRow = nil
        } else {
            // When the previous snapshot was empty, explicitly give row zero ownership.
            if previousRows.isEmpty {
                activeRowIndex = 0
                selectedIndices[updated[0].id] = 0
                focusedRow = 0
            } else if let previousActiveRowID, let preservedIndex = updated.firstIndex(where: { $0.id == previousActiveRowID }) {
                activeRowIndex = preservedIndex
                let preservedRow = updated[preservedIndex]
                if let previousActiveItem,
                   let itemIndex = preservedRow.items.firstIndex(where: { store.catalogItemsShareCanonicalIdentity($0, previousActiveItem) }) {
                    selectedIndices[preservedRow.id] = itemIndex
                } else if !preservedRow.items.isEmpty {
                    selectedIndices[preservedRow.id] = min(max(selectedIndices[preservedRow.id, default: 0], 0), preservedRow.items.count - 1)
                }
            } else {
                activeRowIndex = min(max(activeRowIndex, 0), updated.count - 1)
            }

            if !previousRows.isEmpty {
                if let previousFocusedRowID, let preservedFocusedIndex = updated.firstIndex(where: { $0.id == previousFocusedRowID }) {
                    focusedRow = preservedFocusedIndex
                } else if focusedRow != nil {
                    focusedRow = activeRowIndex
                }
            }
        }
        if !playbackBrowseMode && store.topMenuSelectionHoldTab == store.selectedTab {
            // vBRDC128: data may publish behind the selected top-menu tab, but publication
            // is never permission to move focus into that row. Down clears the hold first.
            focusedRow = nil
        }
        print("[CatalogScroll][v1173] snapshot reason=\(reason) rows=\(updated.count) active=\(activeRowIndex)")
        scheduleVisibleCatalogArtworkHydration(reason: "snapshot \(reason)")
    }

    @MainActor
    private func prepareCatalogOverlayForPresentation(reason: String) {
        catalogReadinessRecoveryTask?.cancel()
        catalogReadinessRecoveryTask = nil

        // vBRDC101: a healthy catalog entry only needs to project the already-resident rows.
        // Do not run the vBRDC099 emergency mounted-blank sweep during a normal UNITY open;
        // every visible RemoteImageFit owner naturally requests its image on mount.
        if store.rows.isEmpty || store.catalogCompletenessNeedsRecovery {
            forceVisibleCatalogReadiness(reason: reason)
        } else {
            rebuildRenderedRows(reason: reason)
        }
    }

    @MainActor
    private func forceVisibleCatalogReadiness(reason: String) {
        let restored = store.forceVisibleCatalogReadiness(reason: reason)
        rebuildRenderedRows(reason: restored ? "\(reason) durable restore" : reason)
        PremiumArtworkRehydrationCoordinator.shared.force(reason: reason)

        catalogReadinessRecoveryTask?.cancel()
        catalogReadinessRecoveryTask = nil

        // Always schedule one post-mount image pass. The immediate call above can happen
        // before LazyHStack has created every returning RemoteImageFit owner. Healthy cards
        // are untouched; only mounted blank owners restart, so this is a bounded self-heal
        // rather than continuous background work.
        catalogReadinessRecoveryTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: 300_000_000)
            guard !Task.isCancelled,
                  scenePhase == .active,
                  playbackBrowseCatalogWorkAllowed,
                  store.selectedDetail == nil else { return }
            PremiumArtworkRehydrationCoordinator.shared.force(reason: "\(reason) post-mount image pass")

            if renderedRows.isEmpty || store.catalogCompletenessNeedsRecovery {
                _ = store.forceVisibleCatalogReadiness(reason: "\(reason) delayed durable restore")
                rebuildRenderedRows(reason: "\(reason) delayed visible rebuild")
                PremiumArtworkRehydrationCoordinator.shared.force(reason: "\(reason) delayed image retry")
                if renderedRows.isEmpty || store.catalogCompletenessNeedsRecovery {
                    await store.ensureDebridChannelsCatalogCompleteness(reason: "visible catalog readiness \(reason)")
                    guard !Task.isCancelled, playbackBrowseCatalogWorkAllowed else { return }
                    rebuildRenderedRows(reason: "\(reason) completeness repair")
                    PremiumArtworkRehydrationCoordinator.shared.force(reason: "\(reason) completeness artwork")
                }
            }
            catalogReadinessRecoveryTask = nil
        }
    }

    private func scheduleRenderedRowsRebuild(reason: String) {
        deferredRowsRebuildTask?.cancel()
        let frameRuntime = UnityFrameRuntime.shared
        if frameRuntime.permits(.interactiveMetadata), Date().timeIntervalSince(lastCatalogNavigationAt) >= 0.12 {
            rebuildRenderedRows(reason: reason)
            return
        }
        deferredRowsRebuildTask = Task { @MainActor in
            // vBRDC102: row/model publication no longer owns a separate 480-500 ms clock.
            // It waits for the exact navigation/transition owner used by every theme.
            guard await frameRuntime.waitUntilPermittedDurably(.interactiveMetadata) else {
                deferredRowsRebuildTask = nil
                return
            }
            guard !Task.isCancelled,
                  scenePhase == .active,
                  store.selectedDetail == nil,
                  playbackBrowseCatalogWorkAllowed else { return }
            // One run-loop beat prevents a model batch and focus-settle publication sharing
            // the same transaction after the runtime opens the metadata lane.
            await Task.yield()
            guard !Task.isCancelled, frameRuntime.permits(.interactiveMetadata) else { return }
            rebuildRenderedRows(reason: reason)
            deferredRowsRebuildTask = nil
        }
    }

    // vBRDC314 re-core: visible and near-visible poster bytes are hydrated deliberately,
    // independent of Lazy/Focus remount behavior. This mirrors Nuvio's stable catalog approach:
    // focus should reveal already-cached poster bytes, not be the event that starts loading them.
    private func scheduleVisibleCatalogArtworkHydration(reason: String) {
        visibleArtworkHydrationTask?.cancel()
        visibleArtworkHydrationTask = nil
        guard playbackBrowseMode || presentationActive, !rows.isEmpty else { return }

        let active = min(max(activeRowIndex, 0), rows.count - 1)
        var urls: [URL] = []
        // vBRDC332: the previous corridor looked ONLY downward. Fast UP scrolling
        // arrived at rows whose first posters had never been byte-prefetched. Prioritize
        // the active row, then adjacent rows in both directions, without allocating
        // decodes or changing the visible row/card rendering contract.
        let corridor: [(offset: Int, lookAhead: Int)] = [
            (0, 10), (-1, 5), (1, 5), (-2, 2), (2, 2)
        ]
        for (offset, lookAhead) in corridor {
            let rowIndex = active + offset
            guard rows.indices.contains(rowIndex) else { continue }
            let row = rows[rowIndex]
            guard !row.items.isEmpty else { continue }
            let selected = min(max(selectedIndices[row.id, default: 0], 0), row.items.count - 1)
            let lowerItem = max(0, selected - (offset == 0 ? 2 : 0))
            let upperItem = min(row.items.count - 1, selected + lookAhead)
            for itemIndex in lowerItem...upperItem {
                let item = row.items[itemIndex]
                if let url = PremiumArtworkURL.url(item.posterURL ?? item.landscapeURL) { urls.append(url) }
            }
        }
        var seen = Set<URL>()
        let unique = urls.filter { seen.insert($0).inserted }
        guard !unique.isEmpty else { return }

        visibleArtworkHydrationTask = Task { @MainActor in
            // vBRDC334: do not impose an artificial 90 ms blank-poster floor. Network and
            // ImageIO work are already off-main and decode-gated; yield one actor turn only.
            await Task.yield()
            guard !Task.isCancelled,
                  playbackBrowseMode || presentationActive,
                  scenePhase == .active,
                  store.selectedDetail == nil else { return }
            let warmURLs = Array(unique.prefix(24))
            PremiumRemoteImageLoader.prefetch(warmURLs, keeping: Set(unique.prefix(18)))
            // vBRDC334: byte-only prefetch was not enough. A card mounting after prefetch still
            // had to perform disk lookup + WebP/ImageIO decode before it could paint. Warm the
            // exact 384px rail bucket for the nearest corridor so those cards can synchronously
            // hit the decoded NSCache when SwiftUI mounts them. The global decode gate keeps
            // this work bounded and off MainActor.
            for url in warmURLs.prefix(12) {
                PremiumRemoteImageLoader.prewarm(url, maxPixelSize: 384)
            }
            // vBRDC333: navigation is read-only. Missing artwork is repaired by the
            // catalog backend/background refresh, never by the D-pad critical path.
            // Mutating catalog rows while focus is moving was able to rebind the rail.
            visibleArtworkHydrationTask = nil
            print("[CatalogHydration][vBRDC333] queued=\(min(unique.count, 24)) keep=\(min(unique.count, 14)) reason=\(reason)")
        }
    }

    // vBRDC086: the shared catalog hero must never consume an anchor owned by the
    // dedicated Favorites rail. This UI-side gate is intentionally redundant with the
    // CatalogStore cleanup so even a same-frame tab transition cannot paint stale Favorite
    // title/artwork before the lifecycle handoff callback runs.
    private var catalogMayUseDetailPresentationAnchor: Bool {
        guard store.detailPresentationAnchorItem != nil else { return false }
        guard store.detailPresentationOrigin != .favorites,
              store.quickPanelRestoreSection != "favoritesCatalog",
              store.quickPanelRestoreRowID != "catalog-favorites-quick-panel" else { return false }
        return true
    }

    private var rowFocusedBackdropItem: MediaItem? {
        guard !rows.isEmpty else { return nil }
        let rowIndex = min(max(focusedRow ?? 0, 0), rows.count - 1)
        let row = rows[rowIndex]
        guard !row.items.isEmpty else { return nil }
        let selected = min(max(selectedIndices[row.id, default: 0], 0), row.items.count - 1)
        return row.items[selected]
    }

    private var focusedBackdropItem: MediaItem? {
        // v1061: selectedDetail can be nil for one run-loop while a new popup mounts and
        // immediately after Back while tvOS restores focus. The store-owned presentation
        // anchor spans both gaps, so the hero never falls through to a stale row/first card.
        if let selectedDetail = store.selectedDetail, store.detailPresentationOrigin != .favorites { return selectedDetail }
        if catalogMayUseDetailPresentationAnchor, let anchor = store.detailPresentationAnchorItem { return anchor }
        return rowFocusedBackdropItem
    }

    private var focusedBackdropRowID: String {
        guard !rows.isEmpty else { return "none" }
        let rowIndex = min(max(focusedRow ?? 0, 0), rows.count - 1)
        return rows[rowIndex].id
    }

    private var focusedBackdropURL: String? {
        // vBRDC040: during a catalog-origin Details presentation, keep the exact row
        // artwork visible until a separate premium detail backdrop resolves. Metadata
        // hydration is free to enrich selectedDetail, but it may not silently replace
        // the row image and collapse the intended two-stage artwork handoff.
        if store.detailPresentationOrigin == .catalog,
           catalogMayUseDetailPresentationAnchor {
            // vBRDC044: keep the decoded premium detail frame pinned through Back/focus
            // restoration. Dropping to the row URL in the same render turn as popup removal
            // recreated the very visible two-image flash on physical Apple TV.
            if let premium = store.detailPremiumBackdropURL?.trimmingCharacters(in: .whitespacesAndNewlines), !premium.isEmpty {
                return premium
            }
            if let anchor = store.detailPresentationAnchorItem {
                return CatalogArtworkCacheManager.preferredBackdropURL(for: anchor)
            }
        }
        guard let item = focusedBackdropItem else { return nil }
        return CatalogArtworkCacheManager.preferredBackdropURL(for: item)
    }

    // vBRDC021: detail hydration can replace the row shell with the same title carrying a
    // richer/original-resolution backdrop. Keep the artwork host keyed to the originating
    // catalog identity so that URL-quality upgrades reuse the same loader/view instead of
    // tearing it down and exposing a black/placeholder frame.
    private var focusedBackdropStableIdentity: String {
        let identityItem: MediaItem?
        if store.selectedDetail != nil, store.detailPresentationOrigin == .catalog {
            // The store intentionally enriches detailPresentationAnchorItem in place, so
            // use the still-pinned originating row card as the immutable visual identity.
            identityItem = rowFocusedBackdropItem ?? store.detailPresentationAnchorItem
        } else {
            identityItem = focusedBackdropItem
        }
        guard let identityItem else { return "none" }
        let canonical = store.canonicalCatalogIdentityKey(for: identityItem)
        return canonical.isEmpty ? identityItem.id : canonical
    }

    private var focusedBackdropKey: String {
        guard let item = focusedBackdropItem else { return "none" }
        let canonical = store.canonicalCatalogIdentityKey(for: item)
        let identity = canonical.isEmpty ? item.id : canonical
        // v1061: row focus may briefly remap while the popup owns focus. Key hero state by
        // the actual media identity/artwork, not by the transient row index, so opening and
        // closing Details cannot replace the same hero with a stale row-scoped instance.
        return "\(identity)|\(focusedBackdropURL ?? "none")"
    }

    // v1065: focused-card preview ownership is deliberately separate from the hydrated
    // detail hero. Opening Details may replace selectedDetail with richer artwork/metadata,
    // but the preview must remain the exact AVPlayer instance that began on the row card.
    private var focusedCardPreviewItem: MediaItem? {
        if store.selectedDetail != nil, store.detailPresentationOrigin == .catalog {
            if let anchor = store.detailPresentationAnchorItem { return anchor }
            return rowFocusedBackdropItem
        }
        return rowFocusedBackdropItem
    }

    private var focusedCardPreviewIdentityKey: String {
        guard let item = focusedCardPreviewItem else { return "none" }
        let canonical = store.canonicalCatalogIdentityKey(for: item)
        let identity = canonical.isEmpty ? item.id : canonical
        let rowID: String
        if store.selectedDetail != nil,
           store.detailPresentationOrigin == .catalog,
           let restoreRowID = store.quickPanelRestoreRowID,
           !restoreRowID.isEmpty {
            // v1066: quickPanelRestoreRowID is optional. Bind the exact originating row
            // before using it so preview ownership remains stable and the project compiles.
            rowID = restoreRowID
        } else {
            rowID = focusedBackdropRowID
        }
        return "\(rowID)|\(identity)"
    }

    private var focusedThemedLogoURL: String? {
        guard let item = focusedBackdropItem else { return nil }
        if let direct = CatalogArtworkCacheManager.themedLogoURL(for: item) { return direct }
        // vBRDC203: Resume and Trakt Continue Watching can be synthesized from playback
        // identity before their normal catalog card exists. The focused hero metadata call
        // already resolves TMDB identity; reuse the logo appended to that same request so
        // these account rows get the exact same themed-title treatment as ordinary rows.
        guard focusedHeroMetadataKey == focusedBackdropKey else { return nil }
        return focusedHeroMetadata?.logoURL
    }

    private var activeRowPresentation: CatalogRowPresentation? {
        guard !rows.isEmpty else { return nil }
        let rowIndex = min(max(activeRowIndex, 0), rows.count - 1)
        return rows[rowIndex].presentation
    }

    private var activeProviderBrandTitle: String {
        guard !rows.isEmpty else { return "Debrid Channels" }
        let rowIndex = min(max(activeRowIndex, 0), rows.count - 1)
        let row = rows[rowIndex]
        let themedName = row.presentation?.rowKind == "trakt"
            ? row.title.trimmingCharacters(in: .whitespacesAndNewlines)
            : (row.presentation?.shortName?.trimmingCharacters(in: .whitespacesAndNewlines) ?? "")
        let rowTitle = row.title.trimmingCharacters(in: .whitespacesAndNewlines)
        let catalog = focusedBackdropItem?.catalog.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let preferred = themedName.isEmpty ? rowTitle : themedName
        return providerBrandTitle(preferred.isEmpty || isGenericCatalogTitle(preferred) ? catalog : preferred)
    }

    private func isGenericCatalogTitle(_ value: String) -> Bool {
        let key = value.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        return key == "streaming catalogs" || key == "movies" || key == "movie" || key == "tv shows" || key == "shows" || key == "series"
    }

    private func providerBrandTitle(_ value: String) -> String {
        let clean = value.trimmingCharacters(in: .whitespacesAndNewlines)
        let key = clean.lowercased()
        if key.contains("prime") || key.contains("amazon") { return "Prime Video" }
        if key.contains("disney") { return "Disney+" }
        if key.contains("netflix") { return "Netflix" }
        if key.contains("hulu") { return "Hulu" }
        if key.contains("max") || key.contains("hbo") { return "Max" }
        if key.contains("apple") { return "Apple TV+" }
        if key.contains("paramount") { return "Paramount+" }
        if key.contains("peacock") { return "Peacock" }
        if key.contains("starz") { return "STARZ" }
        if key.contains("cinemeta") { return "Cinemeta" }
        if key.contains("tmdb") { return "TMDB" }
        return clean.isEmpty ? "Debrid Channels" : clean
    }

    private var catalogArtworkTheme: CatalogArtworkCacheManager.ThemeFlags {
        CatalogArtworkCacheManager.themeFlags(for: liveTVGridThemePreset)
    }

    private var useArtworkGridBackground: Bool { catalogArtworkTheme.usesArtworkBackground }

    private var useArtwork2: Bool { catalogArtworkTheme.usesArtwork2 }

    private var useArtwork3Hero: Bool { catalogArtworkTheme.usesArtwork3Hero }

    private var useArtwork4Hero2: Bool { catalogArtworkTheme.usesArtwork4Hero2 }

    private var useArtwork5Floating: Bool { catalogArtworkTheme.usesArtwork5Floating }

    // v822: Pure Black keeps its black background, but now shares the clean themed-logo hero treatment.
    private var usePureBlackCatalogLogo: Bool { liveTVGridThemePreset.lowercased().contains("pure black") }

    private var useArtworkHeroDepthLayer: Bool { catalogArtworkTheme.usesHeroDepthLayer }

    private var useFloatingQuickPanel: Bool { catalogArtworkTheme.usesFloatingQuickPanel }

    private var useArtworkTransparentPanel: Bool { catalogArtworkTheme.usesTransparentPanel }

    private var rowTransitionInsertionEdge: Edge {
        rowTransitionDirection >= 0 ? .bottom : .top
    }

    private var rowTransitionRemovalEdge: Edge {
        rowTransitionDirection >= 0 ? .top : .bottom
    }

    private var artworkBackdropOpacity: Double { catalogArtworkTheme.backdropOpacity }

    private var artworkBackdropSaturation: Double { catalogArtworkTheme.backdropSaturation }

    private var artworkBackdropContrast: Double { catalogArtworkTheme.backdropContrast }

    var body: some View {
        Group {
            if playbackBrowseMode || presentationActive {
                GeometryReader { geo in
                    catalogOverlayContent(geo: geo)
                }
                .allowsHitTesting(true)
                .signalVisionExitCommand { closeOverlay() }
            } else {
                // Keep GridOSCatalogOverlay itself alive so row/focus memory survives, but
                // unmount hero, cards, previews and RemoteImageFit owners while covered.
                Color.clear
                    .allowsHitTesting(false)
                    .onAppear {
                        stopFocusedCardPreview()
                        cancelFocusedHeroMetadataLoad(clearVisibleMetadata: false)
                        catalogReadinessRecoveryTask?.cancel()
                        catalogReadinessRecoveryTask = nil
                        deferredRowsRebuildTask?.cancel()
                        deferredRowsRebuildTask = nil
                        PremiumRemoteImageLoader.cancelIdlePrewarmsForNavigation()
                    }
            }
        }
        .onChange(of: presentationActive) { active in
            guard !playbackBrowseMode else { return }
            if active {
                rebuildRenderedRows(reason: "catalog presentation activated")
                if renderedRows.isEmpty || store.catalogCompletenessNeedsRecovery {
                    prepareCatalogOverlayForPresentation(reason: "catalog presentation activated")
                }
                scheduleQuickPanelFocusRestore(reason: "catalog presentation activated")
            } else {
                stopFocusedCardPreview()
                cancelFocusedHeroMetadataLoad(clearVisibleMetadata: false)
                catalogReadinessRecoveryTask?.cancel()
                catalogReadinessRecoveryTask = nil
                deferredRowsRebuildTask?.cancel()
                deferredRowsRebuildTask = nil
                quickPanelFocusRecoveryTask?.cancel()
                quickPanelFocusRecoveryTask = nil
                rowEntryFocusTask?.cancel()
                rowEntryFocusTask = nil
                PremiumRemoteImageLoader.cancelIdlePrewarmsForNavigation()
            }
        }
    }

    @ViewBuilder
    private func catalogOverlayContent(geo: GeometryProxy) -> some View {
        ZStack(alignment: .bottomLeading) {
            catalogArtworkBackground
            artworkHeroLogo(geo: geo)
            catalogQuickPanel(geo: geo)
        }
        .signalVisionFocusSection()
        .overlay(alignment: .leading) {
            if !playbackBrowseMode, store.playbackURL == nil,
               store.selectedDetail == nil, playbackBrowseRowsPresented {
                SignalVisionCatalogArrows(availableSize: geo.size)
                    .padding(.leading, 8)
                    .offset(y: 80)
            }
        }
        // vBRDC103: the focused persistent rail is the single owner of D-pad navigation.
        // The old parent handler could participate in the same move command as the rail,
        // duplicating selection/focus work at the root of the catalog overlay.
        .onAppear {
            if surfaceHandoffActive {
                beginCatalogSurfaceVisualFocusPin()
            }
            // vBRDC104: this surface is persistent. If catalog data already exists, prime
            // the hidden snapshot once. Do not trigger emergency/network readiness merely
            // because the hidden shell was mounted behind Live TV.
            if playbackBrowseBranchActive {
                prepareCatalogOverlayForPresentation(reason: playbackBrowseMode ? "playback unity catalog appear" : "persistent catalog shell appear")
                scheduleQuickPanelFocusRestore(reason: "appear")
                logFocusedArtworkProvider(reason: "appear")
                if !playbackBrowseMode {
                    scheduleFocusedCardPreview(reason: "appear")
                    scheduleFocusedHeroMetadata(reason: "appear")
                }
            } else if !store.rows.isEmpty {
                rebuildRenderedRows(reason: "persistent hidden shell prime")
            }
        }
        .onChange(of: surfaceHandoffActive) { active in
            if active {
                beginCatalogSurfaceVisualFocusPin()
            } else {
                finishCatalogSurfaceVisualFocusPin()
            }
        }
        .onChange(of: unityCore.activeTab) { tab in
            if playbackBrowseMode {
                if renderedRows.isEmpty || store.catalogCompletenessNeedsRecovery {
                    prepareCatalogOverlayForPresentation(reason: "playback unity catalog active-tab update")
                }
                scheduleQuickPanelFocusRestore(reason: "playback browse active")
            } else if UnitySurfaceSystem.catalogBranchActive(for: tab), store.catalogRowsPresented {
                // vBRDC201: the main shell is persistent, so a tab switch is a projection
                // boundary even when the underlying store rows did not change. Rebuild now
                // from effectiveCatalogFilter instead of waiting for a retained render-tab
                // parameter or a provider revision to happen to wake the shell.
                rebuildRenderedRows(reason: "main catalog active-tab boundary")
                if renderedRows.isEmpty || store.catalogCompletenessNeedsRecovery {
                    prepareCatalogOverlayForPresentation(reason: "persistent catalog branch activated")
                }
                scheduleQuickPanelFocusRestore(reason: "branch activated")
                scheduleFocusedCardPreview(reason: "branch activated")
                scheduleFocusedHeroMetadata(reason: "branch activated")
            } else {
                // Hidden persistent catalog pixels are retained, but decoder/network work is not.
                stopFocusedCardPreview()
                cancelFocusedHeroMetadataLoad(clearVisibleMetadata: false)
            }
        }
        .onChange(of: filter) { _ in
            // Re-project only while visible. A hidden shell will rebuild atomically on its
            // presentationActive edge, avoiding large array/filter work behind other tabs.
            guard playbackBrowseMode || presentationActive else { return }
            rebuildRenderedRows(reason: "persistent catalog filter changed")
        }
        .onChange(of: store.contentFocusToken) { _ in
            guard playbackBrowseRowsPresented,
                  playbackBrowseBranchActive else { return }
            if renderedRows.isEmpty || store.catalogCompletenessNeedsRecovery {
                forceVisibleCatalogReadiness(reason: "content focus recovery")
            }
            scheduleQuickPanelFocusRestore(reason: "restore")
            logFocusedArtworkProvider(reason: "restore")
            if !playbackBrowseMode { scheduleFocusedHeroMetadata(reason: "restore") }
        }
        .onChange(of: scenePhase) { phase in
            if phase == .active {
                guard playbackBrowseMode || presentationActive else { return }
                if renderedRows.isEmpty || store.catalogCompletenessNeedsRecovery {
                    forceVisibleCatalogReadiness(reason: "catalog scene active")
                }
                scheduleQuickPanelFocusRestore(reason: "scene active")
                if !playbackBrowseMode {
                    scheduleFocusedCardPreview(reason: "scene active")
                    scheduleFocusedHeroMetadata(reason: "scene active")
                }
            } else {
                quickPanelFocusRecoveryTask?.cancel()
                quickPanelFocusRecoveryTask = nil
                rowEntryFocusTask?.cancel()
                rowEntryFocusTask = nil
                deferredRowsRebuildTask?.cancel()
                deferredRowsRebuildTask = nil
                surfaceHandoffVisualFocusReleaseTask?.cancel()
                surfaceHandoffVisualFocusReleaseTask = nil
                surfaceHandoffVisualFocusPinned = false
                verticalFocusPinReleaseTask?.cancel()
                verticalFocusPinReleaseTask = nil
                verticalRowVisualFocusPinned = false
                stopFocusedCardPreview()
                SignalCatalogPreviewPlayerPool.shared.releaseAll()
                cancelFocusedHeroMetadataLoad(clearVisibleMetadata: false)
            }
        }
        .onChange(of: store.catalogRowsRevision) { _ in
            // vBRDC309: a covered persistent shell stores the new revision in CatalogStore
            // but does not copy/rebuild its large row snapshot until it becomes visible.
            guard playbackBrowseMode || presentationActive else { return }
            scheduleRenderedRowsRebuild(reason: "store revision")
            if !playbackBrowseMode {
                scheduleFocusedCardPreview(reason: "rows")
                scheduleFocusedHeroMetadata(reason: "rows")
            }
        }
        .onChange(of: focusedBackdropKey) { _ in
            if !playbackBrowseMode && presentationActive && !verticalCatalogNavigationSettling {
                scheduleFocusedCardPreview(reason: "focus")
                scheduleFocusedHeroMetadata(reason: "focus")
            }
        }
        .onChange(of: heroTMDBApiKey) { _ in
            scheduleFocusedHeroMetadata(reason: "TMDB key")
        }
        .onChange(of: focusedCardPreviewsEnabled) { enabled in
            if enabled {
                scheduleFocusedCardPreview(reason: "setting enabled")
            } else {
                stopFocusedCardPreview()
            }
        }
        .onChange(of: store.selectedDetail?.id) { selectedID in
            detailHeroReleaseTask?.cancel()
            detailHeroReleaseTask = nil
            if selectedID == nil {
                // Restore the row/index synchronously before any hero fallback can render.
                _ = restoreQuickPanelFocusIfPossible()
                scheduleQuickPanelFocusRestore(reason: "detail closed")
                scheduleDetailHeroAnchorRelease()
                scheduleFocusedCardPreview(reason: "detail closed")
                scheduleFocusedHeroMetadata(reason: "detail closed")
            } else if let detail = store.selectedDetail,
                      store.detailPresentationOrigin == .catalog,
                      let rowItem = rowFocusedBackdropItem,
                      store.catalogItemsShareCanonicalIdentity(detail, rowItem) {
                // v1063: the exact focused-card preview remains alive beneath the connected
                // media-information popup. Do not restart an already-playing preview when the
                // popup takes focus; only resolve one when the selected card had not started yet.
                if focusedCardPreviewURL == nil || focusedCardPreviewKey != focusedCardPreviewIdentityKey {
                    scheduleFocusedCardPreview(reason: "detail opened")
                }
                cancelFocusedHeroMetadataLoad(clearVisibleMetadata: false)
            } else {
                // Search-owned details and any identity mismatch must not leave a stale catalog
                // preview running behind the popup.
                stopFocusedCardPreview()
                cancelFocusedHeroMetadataLoad(clearVisibleMetadata: false)
            }
        }
        .onChange(of: store.searchActive) { searchActive in
            if searchActive {
                stopFocusedCardPreview()
                cancelFocusedHeroMetadataLoad(clearVisibleMetadata: false)
            } else {
                scheduleFocusedCardPreview(reason: "search closed")
                scheduleFocusedHeroMetadata(reason: "search closed")
            }
        }
        // v1014: the catalog overlay intentionally remains rendered behind playback, so
        // onDisappear is not a reliable teardown point. Release the isolated preview player
        // before any movie, episode, trailer, or Live TV session claims the decoder/render lane.
        .onChange(of: store.vodExclusivePlaybackActive) { active in
            if active {
                stopFocusedCardPreview()
                cancelFocusedHeroMetadataLoad(clearVisibleMetadata: false)
            } else {
                scheduleFocusedHeroMetadata(reason: "playback gate closed")
            }
        }
        .onChange(of: store.playbackURL) { playbackURL in
            if playbackBrowseMode {
                // The playback browser intentionally survives source changes. Decorative
                // card previews/hero enrichment stay suspended so the decoder keeps priority.
                stopFocusedCardPreview()
                cancelFocusedHeroMetadataLoad(clearVisibleMetadata: false)
                if renderedRows.isEmpty || store.catalogCompletenessNeedsRecovery {
                    prepareCatalogOverlayForPresentation(reason: "playback unity source changed")
                }
            } else if playbackURL != nil {
                stopFocusedCardPreview()
                cancelFocusedHeroMetadataLoad(clearVisibleMetadata: false)
            } else {
                forceVisibleCatalogReadiness(reason: "catalog playback closed")
                scheduleFocusedCardPreview(reason: "playback closed")
                scheduleFocusedHeroMetadata(reason: "playback closed")
            }
        }
        .onChange(of: unityCore.trailerExclusiveActive) { _, active in
            if active {
                stopFocusedCardPreview()
                cancelFocusedHeroMetadataLoad(clearVisibleMetadata: false)
            } else {
                scheduleFocusedCardPreview(reason: "trailer closed")
                scheduleFocusedHeroMetadata(reason: "trailer closed")
            }
        }
        .onChange(of: unityCore.memoryPressureRevision) { _, _ in
            stopFocusedCardPreview()
            cancelFocusedHeroMetadataLoad(clearVisibleMetadata: true)
        }
        .onDisappear {
            catalogReadinessRecoveryTask?.cancel()
            catalogReadinessRecoveryTask = nil
            quickPanelFocusRecoveryTask?.cancel()
            quickPanelFocusRecoveryTask = nil
            rowEntryFocusTask?.cancel()
            rowEntryFocusTask = nil
            deferredRowsRebuildTask?.cancel()
            deferredRowsRebuildTask = nil
            visibleArtworkHydrationTask?.cancel()
            visibleArtworkHydrationTask = nil
            detailHeroReleaseTask?.cancel()
            detailHeroReleaseTask = nil
            if store.selectedDetail == nil, let restored = rowFocusedBackdropItem {
                store.releaseDetailPresentationAnchorAfterCatalogRestore(matching: restored)
            }
            stopFocusedCardPreview()
            cancelFocusedHeroMetadataLoad(clearVisibleMetadata: true)
        }
        .onChange(of: activeRowIndex) { _ in
            logFocusedArtworkProvider(reason: "row")
            scheduleVisibleCatalogArtworkHydration(reason: "active row")
        }
        .onChange(of: focusedBackdropItem) { _ in
            logFocusedArtworkProvider(reason: "item")
        }
    }

    private var catalogArtworkBackground: some View {
        ZStack {
            catalogArtworkBaseLayer
            if useArtwork3Hero {
                artwork3PureBlackPolishOverlay
            }
            if useArtworkGridBackground && !useArtwork3Hero, let item = focusedBackdropItem, let artworkURL = focusedBackdropURL {
                // vBRDC023: row focus can transiently remap while Details takes focus.
                // Key only by the originating media identity so that remap cannot destroy
                // the loader during the high-resolution artwork handoff.
                let scopedItemID = focusedBackdropStableIdentity
                mainArtworkBackground(itemID: scopedItemID, url: artworkURL)
                artworkDepthLayers(itemID: scopedItemID, url: artworkURL)
            }
            if let item = focusedBackdropItem {
                // vBRDC066 Unity visual overhaul: a cheap deterministic title aura ties the
                // hero, cards, and compact media-information glass together. This is a pair
                // of static gradients only; no extra artwork decode or shader loop is added.
                UnityCatalogHeroAura(item: item, intensity: useArtwork3Hero ? 0.58 : 0.82)
            }
        }
        // v1085: keep the backdrop host stable across focus changes. Individual image
        // identities still transition correctly, but the full-screen gradient/depth
        // hierarchy is no longer destroyed and rebuilt for every Siri Remote move.
        .ignoresSafeArea()
        .contentShape(Rectangle())
        // Unity seam: artwork is a transient skin over the persistent Live TV root.
        // A short opacity transition lets Back reveal that root without a hard scene cut.
        .transition(.opacity)
    }

    private var artwork3PureBlackPolishOverlay: some View {
        ZStack {
            // v825: Artwork Hero 3 now uses only the real Live TV screen behind the catalog panel.
            // This layer does not draw channels, snapshots, placeholders, startup samples, or movie artwork;
            // it only darkens/protects the Pure Black grid already rendered underneath.
            Color.black.opacity(0.18)
            LinearGradient(
                colors: [
                    Color.black.opacity(0.96),
                    Color.black.opacity(0.72),
                    Color.black.opacity(0.36),
                    Color.black.opacity(0.12)
                ],
                startPoint: .leading,
                endPoint: .trailing
            )
            LinearGradient(
                colors: [
                    Color.black.opacity(0.26),
                    Color.black.opacity(0.04),
                    Color.black.opacity(0.30)
                ],
                startPoint: .top,
                endPoint: .bottom
            )
        }
        .allowsHitTesting(false)
    }

    private var catalogArtworkBaseLayer: some View {
        let topOpacity: Double = {
            if useArtwork4Hero2 { return 0.96 }
            if useArtwork3Hero { return 0.72 }
            if useArtwork5Floating { return 0.22 }
            if useArtwork2 { return 0.12 }
            if useArtworkGridBackground { return 0.56 }
            return 0.44
        }()
        let bottomOpacity: Double = {
            if useArtwork4Hero2 { return 0.98 }
            if useArtwork3Hero { return 0.80 }
            if useArtwork5Floating { return 0.24 }
            if useArtwork2 { return 0.10 }
            if useArtworkGridBackground { return 0.60 }
            return 0.40
        }()
        return LinearGradient(
            colors: [
                Color.black.opacity(topOpacity),
                Color(red: 0.025, green: 0.028, blue: 0.035).opacity(bottomOpacity)
            ],
            startPoint: .topLeading,
            endPoint: .bottomTrailing
        )
    }

    private func mainArtworkBackground(itemID: String, url artworkURL: String) -> some View {
        RemoteImageFit(
            url: artworkURL,
            mode: .fill,
            maxPixelSize: playbackBrowseMode ? 1600 : 2048,
            preservePreviousOnURLChange: true,
            publishDuringSurfaceHandoff: true,
            publishDuringPlayback: playbackBrowseMode,
            forceVisiblePlaybackPublication: playbackBrowseMode,
            deferHeavyLoadDuringNavigation: true
        )
            // vBRDC125: never hold a previous title's hero pixels after focus identity changes.
            // The new owner can still reuse its own warm 1280px card decode provisionally and
            // upgrade to 4K in place, preserving continuity without cross-title ghosting.
            .id("catalog-hero-background-\(itemID)")
            .opacity(artworkBackdropOpacity)
            .saturation(artworkBackdropSaturation)
            .contrast(artworkBackdropContrast)
            .transition(.identity)
            // vBRDC044: the retained-frame path must stay atomic in both directions.
            // While a catalog detail anchor is pinned, URL quality changes never carry an
            // implicit opacity animation; the decoded frame remains visible until its ready
            // replacement swaps in directly. Normal row-to-row focus keeps the polish timing.
            .animation(store.detailPresentationAnchorItem == nil ? .easeInOut(duration: 0.26) : nil, value: "\(itemID)|\(artworkURL)")
            .overlay(mainArtworkSideGradient)
            .overlay(mainArtworkVerticalGradient)
    }

    private var mainArtworkSideGradient: some View {
        LinearGradient(
            colors: useArtwork2
                ? [
                    Color.black.opacity(0.20),
                    Color.black.opacity(0.04),
                    Color.black.opacity(0.02),
                    Color.black.opacity(0.16)
                ]
                : (useArtwork4Hero2 || useArtwork5Floating)
                ? [
                    Color.black.opacity(useArtwork5Floating ? 0.10 : 0.16),
                    Color.black.opacity(useArtwork5Floating ? 0.035 : 0.06),
                    Color.black.opacity(0.02),
                    Color.black.opacity(useArtwork5Floating ? 0.06 : 0.10)
                ]
                : [
                    Color.black.opacity(0.78),
                    Color.black.opacity(0.56),
                    Color.black.opacity(0.38),
                    Color.black.opacity(0.64)
                ],
            startPoint: .leading,
            endPoint: .trailing
        )
    }

    private var mainArtworkVerticalGradient: some View {
        LinearGradient(
            colors: useArtwork2
                ? [Color.black.opacity(0.18), Color.black.opacity(0.01), Color.black.opacity(0.20)]
                : (useArtwork4Hero2 || useArtwork5Floating)
                ? [Color.black.opacity(useArtwork5Floating ? 0.08 : 0.12), Color.black.opacity(0.015), Color.black.opacity(useArtwork5Floating ? 0.12 : 0.18)]
                : [Color.black.opacity(0.70), Color.black.opacity(0.12), Color.black.opacity(0.82)],
            startPoint: .top,
            endPoint: .bottom
        )
    }

    @ViewBuilder
    private func artworkDepthLayers(itemID: String, url artworkURL: String) -> some View {
        if useArtwork3Hero || useArtwork5Floating {
            // v1085 performance pass: the previous hero effect decoded/composited up to
            // four additional full-screen copies of the same artwork on every focus
            // move. One restrained depth pass preserves the premium lift while removing
            // the micro-depth/subject-pop/object-cut overdraw from the scroll path.
            RemoteImageFit(
                url: artworkURL,
                mode: .fill,
                maxPixelSize: playbackBrowseMode ? 1600 : 2048,
                preservePreviousOnURLChange: true,
                publishDuringSurfaceHandoff: true,
                publishDuringPlayback: playbackBrowseMode,
                forceVisiblePlaybackPublication: playbackBrowseMode,
                deferHeavyLoadDuringNavigation: true
            )
                // vBRDC125: the decorative depth copy follows the exact same identity rule
                // as the primary hero so an outgoing title cannot remain blended over the
                // incoming title while the high-resolution replacement is decoding.
                .id("catalog-hero-depth-\(itemID)")
                .blur(radius: useArtwork5Floating ? 0.45 : 0.85)
                .opacity(useArtwork5Floating ? 0.13 : 0.105)
                .saturation(useArtwork5Floating ? 1.16 : 1.10)
                .contrast(useArtwork5Floating ? 1.20 : 1.18)
                .blendMode(.screen)
                .allowsHitTesting(false)
                .transition(.identity)
                .animation(store.detailPresentationAnchorItem == nil ? .easeInOut(duration: 0.24) : nil, value: "\(itemID)|\(artworkURL)")
                .overlay(
                    LinearGradient(
                        colors: [Color.black.opacity(0.30), Color.clear, Color.black.opacity(0.42)],
                        startPoint: .leading,
                        endPoint: .trailing
                    )
                )
        }
    }

    private func catalogHeroRuntimeLabel(_ minutes: Int, isTV: Bool) -> String {
        guard minutes > 0 else { return "" }
        let value: String
        if minutes >= 60 {
            let remainder = minutes % 60
            value = remainder == 0 ? "\(minutes / 60)H" : "\(minutes / 60)H \(remainder)M"
        } else {
            value = "\(minutes)M"
        }
        return isTV ? "\(value) EPISODES" : value
    }

    private func catalogHeroTypeLabel(_ item: MediaItem) -> String {
        let normalized = item.type.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        if normalized.contains("series") || normalized.contains("show") || normalized == "tv" { return "TV SERIES" }
        if normalized.contains("movie") || normalized.contains("film") { return "MOVIE" }
        let clean = item.type.trimmingCharacters(in: .whitespacesAndNewlines)
        return clean.isEmpty ? "FEATURE" : clean.uppercased()
    }

    private func catalogHeroReleaseDateLabel(_ value: String) -> String {
        let clean = value.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !clean.isEmpty else { return "" }
        guard let date = Self.catalogHeroInputDateFormatter.date(from: String(clean.prefix(10))) else {
            return String(clean.filter(\.isNumber).prefix(4))
        }
        return Self.catalogHeroOutputDateFormatter.string(from: date).uppercased()
    }

    private func catalogHeroBudgetLabel(_ amount: Int) -> String {
        guard amount > 0 else { return "" }
        let value: String
        if amount >= 1_000_000_000 {
            value = String(format: "$%.1fB", Double(amount) / 1_000_000_000.0)
                .replacingOccurrences(of: ".0B", with: "B")
        } else if amount >= 1_000_000 {
            value = String(format: "$%.1fM", Double(amount) / 1_000_000.0)
                .replacingOccurrences(of: ".0M", with: "M")
        } else if amount >= 1_000 {
            value = String(format: "$%.0fK", Double(amount) / 1_000.0)
        } else {
            value = "$\(amount)"
        }
        return "BUDGET \(value)"
    }

    private func catalogHeroRatingLabel(for item: MediaItem) -> String? {
        let clean = item.rating.replacingOccurrences(of: ",", with: ".")
        let numeric = clean.filter { "0123456789.".contains($0) }
        guard let value = Double(numeric), value > 0, value <= 10 else { return nil }
        return String(format: "%.1f", value)
    }

    private func catalogHeroCertificationLabel(for item: MediaItem, metadata: CatalogHeroMetadataSnapshot?) -> String? {
        let fetched = metadata?.certification?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        if !fetched.isEmpty { return fetched.uppercased() }
        let clean = item.rating.trimmingCharacters(in: .whitespacesAndNewlines).uppercased()
        let certifications = ["NC-17", "PG-13", "TV-MA", "TV-14", "TV-PG", "TV-G", "TV-Y7", "TV-Y", "R", "PG", "G"]
        return certifications.first(where: { clean == $0 })
    }

    private func catalogHeroMetadataValues(for item: MediaItem) -> [String] {
        let currentMetadata = focusedHeroMetadataKey == focusedBackdropKey ? focusedHeroMetadata : nil
        let normalizedType = item.type.lowercased()
        let isTV = normalizedType.contains("series") || normalizedType.contains("show") || normalizedType == "tv"
        var values: [String] = []

        let releaseDate = catalogHeroReleaseDateLabel(currentMetadata?.releaseDate ?? "")
        let localYear = String(item.year.filter(\.isNumber).prefix(4))
        let year = localYear.isEmpty ? (currentMetadata?.releaseYear ?? "") : localYear
        if !releaseDate.isEmpty {
            values.append(releaseDate)
        } else if !year.isEmpty {
            values.append(year)
        }

        if let runtime = currentMetadata?.runtimeMinutes, runtime > 0 {
            values.append(catalogHeroRuntimeLabel(runtime, isTV: isTV))
        }

        values.append(catalogHeroTypeLabel(item))

        let localGenres = item.genres
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
        let genres = localGenres.isEmpty ? (currentMetadata?.genres ?? []) : localGenres
        let genreLabel = genres.prefix(2).joined(separator: " / ").uppercased()
        if !genreLabel.isEmpty { values.append(genreLabel) }

        var seen = Set<String>()
        return values.filter { seen.insert($0).inserted }
    }

    private func catalogHeroSecondaryMetadataValues(for item: MediaItem) -> [String] {
        let currentMetadata = focusedHeroMetadataKey == focusedBackdropKey ? focusedHeroMetadata : nil
        let normalizedType = item.type.lowercased()
        let isTV = normalizedType.contains("series") || normalizedType.contains("show") || normalizedType == "tv"
        var values: [String] = []

        if isTV, let seasons = currentMetadata?.seasonCount, seasons > 0 {
            values.append(seasons == 1 ? "1 SEASON" : "\(seasons) SEASONS")
        }
        if !isTV, let budget = currentMetadata?.budget, budget > 0 {
            values.append(catalogHeroBudgetLabel(budget))
        }
        return values
    }

    private func catalogHeroDescription(for item: MediaItem) -> String {
        let placeholder = "no description available yet."
        let local = item.description.trimmingCharacters(in: .whitespacesAndNewlines)
        let metadata = focusedHeroMetadataKey == focusedBackdropKey
            ? focusedHeroMetadata?.overview?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
            : ""
        let candidates = [local, metadata].filter {
            !$0.isEmpty && $0.lowercased() != placeholder
        }
        return candidates.max(by: { $0.count < $1.count }) ?? ""
    }

    private func catalogHeroDescriptionFontSize(_ description: String, compact: Bool) -> CGFloat {
        switch description.count {
        case 0...260: return compact ? 19 : 21
        case 261...520: return compact ? 17.5 : 19
        case 521...780: return compact ? 16.5 : 18
        default: return compact ? 15.5 : 17
        }
    }

    @ViewBuilder
    private func artworkHeroLogo(geo: GeometryProxy) -> some View {
        if (useArtwork3Hero || useArtwork4Hero2 || usePureBlackCatalogLogo), let item = focusedBackdropItem {
            let usesCompactHero = useArtwork3Hero || usePureBlackCatalogLogo
            let informationWidth = min(
                max(geo.size.width * (usesCompactHero ? 0.34 : 0.37), usesCompactHero ? 520 : 560),
                usesCompactHero ? 660 : 720
            )
            let logoWidth = min(informationWidth * 0.76, usesCompactHero ? 500 : 545)
            let logoHeight = min(
                max(geo.size.height * (usesCompactHero ? 0.13 : 0.15), usesCompactHero ? 96 : 108),
                usesCompactHero ? 158 : 178
            )
            let informationCenterX = min(
                max(geo.size.width * (usesCompactHero ? 0.235 : 0.255), usesCompactHero ? 320 : 350),
                usesCompactHero ? 455 : 500
            )
            let descriptionWidth = min(
                max(informationWidth, geo.size.width * (usesCompactHero ? 0.42 : 0.46)),
                min(usesCompactHero ? 840 : 920, max(informationWidth, (informationCenterX * 2) - 72))
            )
            // v1054: lift the hero logo/metadata/synopsis slightly to preserve a clean
            // connector corridor above the focused poster rail.
            let informationCenterY = min(
                max(geo.size.height * (usesCompactHero ? 0.335 : 0.375), usesCompactHero ? 245 : 270),
                geo.size.height * (usesCompactHero ? 0.45 : 0.50)
            ) - 26
            let metadataValues = catalogHeroMetadataValues(for: item)
            let secondaryMetadataValues = catalogHeroSecondaryMetadataValues(for: item)
            let currentMetadata = focusedHeroMetadataKey == focusedBackdropKey ? focusedHeroMetadata : nil
            let certification = catalogHeroCertificationLabel(for: item, metadata: currentMetadata)
            let rating = catalogHeroRatingLabel(for: item)
            let hasSecondaryMetadata = !secondaryMetadataValues.isEmpty || certification != nil || rating != nil
            let hasMetadata = !metadataValues.isEmpty || hasSecondaryMetadata
            let metadataHeight: CGFloat = hasMetadata ? (hasSecondaryMetadata ? 55 : 30) : 0
            let description = catalogHeroDescription(for: item)
            let hasDescription = !description.isEmpty
            let logoMetadataSpacing: CGFloat = hasMetadata ? 12 : 0
            let metadataDescriptionSpacing: CGFloat = hasDescription ? (hasMetadata ? 14 : 15) : 0
            let descriptionFontSize = catalogHeroDescriptionFontSize(description, compact: usesCompactHero)

            VStack(alignment: .center, spacing: 0) {
                Artwork4HeroLogoLayer(item: item, logoURL: focusedThemedLogoURL, publishDuringPlayback: playbackBrowseMode)
                    .frame(width: logoWidth, height: logoHeight, alignment: .center)

                if hasMetadata {
                    CatalogHeroMetadataRibbon(
                        values: metadataValues,
                        secondaryValues: secondaryMetadataValues,
                        certification: certification,
                        rating: rating,
                        compact: usesCompactHero
                    )
                    .frame(width: informationWidth, height: metadataHeight)
                    .padding(.top, logoMetadataSpacing)
                }

                if hasDescription {
                    Text(description)
                        .font(.system(size: descriptionFontSize, weight: .regular, design: .serif))
                        .tracking(0.12)
                        .foregroundStyle(Color.white.opacity(0.92))
                        .lineSpacing(5.5)
                        .multilineTextAlignment(.leading)
                        .fixedSize(horizontal: false, vertical: true)
                        .frame(width: descriptionWidth, alignment: .topLeading)
                        .padding(.top, metadataDescriptionSpacing)
                        .shadow(color: .black.opacity(0.88), radius: 6, x: 0, y: 2)
                }
            }
            .frame(width: descriptionWidth, alignment: .top)
            // Anchor the hero by its logo instead of the total text height. This keeps the
            // large themed logo in the same place while allowing the complete synopsis to
            // expand naturally beneath the metadata ribbon without a line limit.
            .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
            .padding(.leading, informationCenterX - (descriptionWidth / 2))
            .padding(.top, informationCenterY - (logoHeight / 2))
            // Never crossfade identities during the popup handoff. Normal DPAD browsing
            // keeps its polish, but opening/closing Details swaps the exact pinned hero in a
            // transaction with no old-logo overlap.
            .transition(store.detailPresentationAnchorItem == nil ? .opacity : .identity)
            .animation(store.detailPresentationAnchorItem == nil ? .easeInOut(duration: 0.20) : nil, value: focusedThemedLogoURL ?? item.title)
            .animation(store.detailPresentationAnchorItem == nil ? .easeInOut(duration: 0.16) : nil, value: metadataValues)
            .animation(store.detailPresentationAnchorItem == nil ? .easeInOut(duration: 0.16) : nil, value: description)
            .transaction { transaction in
                if store.detailPresentationAnchorItem != nil { transaction.disablesAnimations = true }
            }
            .allowsHitTesting(false)
        }
    }

    private func catalogQuickPanel(geo: GeometryProxy) -> some View {
        VStack(alignment: .leading, spacing: 8) {
            overlayHeader
            activeCatalogRowPager(geo: geo)
        }
        .padding(.leading, appCanvasExpanded ? 44 : 34)
        .padding(.trailing, appCanvasExpanded ? 40 : 34)
        .padding(.top, 8)
        .padding(.bottom, 2)
        .frame(width: geo.size.width, alignment: .bottomLeading)
        .background(Color.clear)
        // vBRDC216: no main-only vertical transform here. Keeping this tree geometrically
        // fixed makes main-catalog Up/Down identical to playback-browse catalog Up/Down.
        .transition(.asymmetric(insertion: .move(edge: .bottom).combined(with: .opacity), removal: .move(edge: .bottom).combined(with: .opacity)))
    }

    @ViewBuilder
    private func activeCatalogRowPager(geo: GeometryProxy) -> some View {
        let visibleRowIndex = min(max(activeRowIndex, 0), max(rows.count - 1, 0))
        if !rows.isEmpty {
            let row = rows[visibleRowIndex]
            // v748: keep the v702/v711 grounded quick-panel feel.  The focused rail
            // stays near the bottom while preserving the next-row provider mark below it.
            // v716: restore v702 rail geometry.  Do not re-size the poster row from a
            // compressed pager calculation; v702 used a stable bottom quick-panel rail with
            // a 390x220 focused landscape card, 218pt card rail, and the row title directly
            // above the cards.  Keep the new one-row-only behavior, but preserve v702 math.
            let panelHeight = min(geo.size.height * 0.265, 258)
            let contextSpacing: CGFloat = 0
            let cardHeight: CGFloat = 220
            let cardWidth: CGFloat = 390
            let railHeight: CGFloat = 246
            let cardBottomInset: CGFloat = -14
            VStack(alignment: .leading, spacing: contextSpacing) {
                catalogRail(row: row, visibleRowIndex: visibleRowIndex, cardWidth: cardWidth, cardHeight: cardHeight, railHeight: railHeight, cardBottomInset: cardBottomInset)
                nextRowTitle(after: visibleRowIndex)
            }
            .frame(height: panelHeight, alignment: .bottomLeading)
        }
    }

    private func catalogRail(row: MediaRow, visibleRowIndex: Int, cardWidth: CGFloat, cardHeight: CGFloat, railHeight: CGFloat, cardBottomInset: CGFloat) -> some View {
        ZStack(alignment: .topLeading) {
            GridOSFixedSlotCatalogRail(
                row: row,
                rowIndex: visibleRowIndex,
                maxRowIndex: max(rows.count - 1, 0),
                cardWidth: cardWidth,
                cardHeight: cardHeight,
                railHeight: railHeight,
                cardBottomInset: cardBottomInset,
                focusedRow: $focusedRow,
                selectedIndex: Binding(
                    get: { selectedIndices[row.id, default: 0] },
                    set: { selectedIndices[row.id] = $0 }
                ),
                focusedPreviewURL: focusedCardPreviewKey == focusedCardPreviewIdentityKey ? focusedCardPreviewURL : nil,
                focusedPreviewKey: focusedCardPreviewKey,
                onFocusedPreviewFinished: { previewKey in
                    finishFocusedCardPreview(key: previewKey)
                },
                onRowMove: { delta in
                    moveQuickPanelRow(delta)
                },
                onNavigationActivity: { direction in
                    registerCatalogNavigation(direction)
                },
                surfaceVisualFocusPinned: surfaceHandoffVisualFocusPinned || surfaceHandoffActive || verticalRowVisualFocusPinned,
                // vBRDC218: verticalRowVisualFocusPinned prevents the main screen's persistent
                // top-navigation focus graph from shrinking/dropping the card for one frame
                // during Up/Down. Playback-browse keeps its existing native behavior.
                // vBRDC131: never flatten the outgoing catalog merely to move focus.
                // Root disables the whole branch only after its reverse compositor motion.
                allowsFocus: true,
                allowsLazyRefresh: false,
                playbackBrowseMode: playbackBrowseMode
            )
            // vBRDC103/vBRDC125: keep this rail instance alive as rows change. The row/index
            // remain data inputs, preserving focus and the fixed-slot renderer across vertical
            // navigation. Image owners inside those slots are now media-identity scoped so
            // persistence cannot leak the outgoing row's decoded artwork into the incoming row.
            // v715: row changes must be a clean swap. Do not animate the outgoing/incoming
            // catalog row because it creates the ugly previous-row ghost glimpse during Up/Down.
            .transition(.identity)
        }
        .frame(height: railHeight, alignment: .topLeading)
        .animation(nil, value: activeRowIndex)
    }

    @ViewBuilder
    private func nextRowTitle(after visibleRowIndex: Int) -> some View {
        if visibleRowIndex + 1 < rows.count {
            ProviderBrandMark(
                title: providerBrandTitle(
                    rows[visibleRowIndex + 1].presentation?.rowKind == "trakt"
                        ? rows[visibleRowIndex + 1].title
                        : (rows[visibleRowIndex + 1].presentation?.shortName ?? rows[visibleRowIndex + 1].title)
                ),
                compact: true,
                presentation: rows[visibleRowIndex + 1].presentation
            )
                .padding(.leading, 4)
                .padding(.top, 2)
        }
    }

    private func registerCatalogNavigation(_ direction: SignalMoveDirection) {
        lastCatalogNavigationAt = Date()
        // A detail-artwork warmup is speculative until Media Information actually mounts.
        // Do not let a 2048 decode from the card the user just left steal CPU/memory from
        // the next row transition.
        PremiumRemoteImageLoader.cancelIdlePrewarmsForNavigation()
        let settleWindow: TimeInterval
        switch direction {
        case .left, .right:
            settleWindow = UnityCatalogRowMotionStyle.frameBudgetSettleDuration(for: catalogRowScrollingAnimationPreset)
        case .up, .down:
            // vBRDC216: the visible row swap is immediate, matching playback-browse. Keep
            // only a short non-visual settling window so hero/trailer work cannot steal the
            // frame in which the destination row is rebound.
            settleWindow = 0.16
        @unknown default:
            settleWindow = 0.24
        }
        unityAnimations.registerNavigationActivity(source: "catalog", settleAfter: settleWindow)

        // A real user move supersedes all delayed focus ownership from row entry and
        // popup/playback restoration. Leaving those tasks alive is what produced the
        // intermittent snap-back after entering a row or immediately scrolling after Back.
        rowEntryFocusTask?.cancel()
        rowEntryFocusTask = nil
        rowEntryFocusGeneration &+= 1
        quickPanelFocusRecoveryTask?.cancel()
        quickPanelFocusRecoveryTask = nil

        if store.selectedDetail == nil, let restored = rowFocusedBackdropItem {
            store.releaseDetailPresentationAnchorAfterCatalogRestore(matching: restored)
        }
    }

    private func handleQuickPanelMove(_ direction: SignalMoveDirection) {
        guard !rows.isEmpty else { return }
        registerCatalogNavigation(direction)
        if focusedRow == nil {
            focusedRow = min(max(activeRowIndex, 0), rows.count - 1)
        }
        let currentRowIndex = min(max(activeRowIndex, 0), rows.count - 1)
        let row = rows[currentRowIndex]
        let currentItemIndex = min(max(selectedIndices[row.id, default: 0], 0), max(row.items.count - 1, 0))
        switch direction {
        case .left:
            selectedIndices[row.id] = max(currentItemIndex - 1, 0)
            if focusedRow != currentRowIndex { focusedRow = currentRowIndex }
        case .right:
            selectedIndices[row.id] = min(currentItemIndex + 1, max(row.items.count - 1, 0))
            if focusedRow != currentRowIndex { focusedRow = currentRowIndex }
        case .up:
            moveQuickPanelRow(-1)
        case .down:
            moveQuickPanelRow(1)
        @unknown default:
            break
        }
    }

    @MainActor
    private func beginCatalogSurfaceVisualFocusPin() {
        surfaceHandoffVisualFocusReleaseTask?.cancel()
        surfaceHandoffVisualFocusReleaseTask = nil
        // vBRDC131: reverse catalog dismissal keeps the exact focused card geometry
        // through the final visible frame. Focus is handed to the top menu only after
        // Root has driven branch opacity/offset to zero.
        var transaction = Transaction()
        transaction.disablesAnimations = true
        withTransaction(transaction) {
            surfaceHandoffVisualFocusPinned = !rows.isEmpty
            if !rows.isEmpty {
                focusedRow = min(max(activeRowIndex, 0), rows.count - 1)
            }
        }
    }

    @MainActor
    private func finishCatalogSurfaceVisualFocusPin() {
        surfaceHandoffVisualFocusReleaseTask?.cancel()
        // First guarantee real FocusState is already sitting on the exact visible row. Keep
        // the visual pin for one additional render turn, then release it without animation.
        var transaction = Transaction()
        transaction.disablesAnimations = true
        withTransaction(transaction) {
            if !playbackBrowseMode && store.topMenuSelectionHoldTab == store.selectedTab {
                focusedRow = nil
            } else if !rows.isEmpty, playbackBrowseBranchActive {
                focusedRow = min(max(activeRowIndex, 0), rows.count - 1)
            }
        }
        surfaceHandoffVisualFocusReleaseTask = Task { @MainActor in
            await Task.yield()
            guard !Task.isCancelled else { return }
            var release = Transaction()
            release.disablesAnimations = true
            withTransaction(release) { surfaceHandoffVisualFocusPinned = false }
            surfaceHandoffVisualFocusReleaseTask = nil
        }
    }

    private func moveQuickPanelRow(_ delta: Int) {
        guard !rows.isEmpty else { return }
        let next = min(max(activeRowIndex + delta, 0), rows.count - 1)
        guard next != activeRowIndex else {
            // v790: production focus audit. While the Movies/Shows/Streaming quick panel
            // owns focus, boundary UP/DOWN presses are intentionally consumed here instead
            // of leaking focus to the top menu. The top menu remains reachable after the
            // quick panel/overlay releases ownership.
            if NavigationFocusAuditManager.shared.catalogQuickPanelConsumesBoundaryMove() {
                if focusedRow != activeRowIndex { focusedRow = activeRowIndex }
            }
            return
        }

        let row = rows[next]
        if !playbackBrowseMode {
            // vBRDC218 playback-focus parity: v216 copied the playback row-data transaction,
            // but the main screen still performed extra observable work *before* that swap.
            // In the user's first video this made the focused 390x220 card briefly become its
            // 82% unfocused shape and drop to y=0 before returning. Do not publish the legacy
            // topMenuFocusLocked mutation here, and do not create an intermediate render.
            // Cancel speculative work as part of the same animation-disabled transaction.
            verticalNavigationSettleTask?.cancel()
            verticalFocusPinReleaseTask?.cancel()
        }

        // The visible row replacement is exactly one atomic fixed-slot rebind. Main-only
        // focus pinning is included in this same transaction, so there is never a frame where
        // the old row has lost focus geometry or the new row is rendered unfocused.
        var transaction = Transaction()
        transaction.disablesAnimations = true
        withTransaction(transaction) {
            rowTransitionDirection = delta
            selectedIndices[row.id] = 0
            if !playbackBrowseMode {
                verticalCatalogNavigationSettling = true
                verticalCatalogNavigationGeneration &+= 1
                verticalRowVisualFocusPinned = true
                stopFocusedCardPreview()
                cancelFocusedHeroMetadataLoad(clearVisibleMetadata: false)
            }
            activeRowIndex = next
            focusedRow = next
        }

        let navigationGeneration = verticalCatalogNavigationGeneration
        scheduleFirstCardRowEntryFocus(rowIndex: next, rowID: row.id)

        if !playbackBrowseMode {
            // Keep the geometry pin for one focus-graph handoff turn only. The destination
            // row is already on screen; after one yield we let tvOS own focus without chasing it.
            verticalFocusPinReleaseTask = Task { @MainActor in
                // The playback overlay has no persistent top-menu focus graph, while the main
                // shell does. Reassert at most once, then release the visual pin.
                await Task.yield()
                guard !Task.isCancelled,
                      navigationGeneration == verticalCatalogNavigationGeneration,
                      activeRowIndex == next else { return }
                // Nuvio-style focus settle: one destination ownership commit, then stop.
                // Do not chase tvOS focus with repeated frame-timed writes.
                if focusedRow != next {
                    var focus = Transaction()
                    focus.disablesAnimations = true
                    withTransaction(focus) { focusedRow = next }
                }
                var release = Transaction()
                release.disablesAnimations = true
                withTransaction(release) { verticalRowVisualFocusPinned = false }
                verticalFocusPinReleaseTask = nil
            }

            verticalNavigationSettleTask = Task { @MainActor in
                try? await Task.sleep(nanoseconds: 160_000_000)
                guard !Task.isCancelled,
                      navigationGeneration == verticalCatalogNavigationGeneration,
                      activeRowIndex == next else { return }
                verticalCatalogNavigationSettling = false
                scheduleFocusedCardPreview(reason: "vertical row settled")
                scheduleFocusedHeroMetadata(reason: "vertical row settled")
                verticalNavigationSettleTask = nil
            }
        }
    }

    private func scheduleFirstCardRowEntryFocus(rowIndex: Int, rowID: String) {
        rowEntryFocusTask?.cancel()
        rowEntryFocusGeneration &+= 1
        let generation = rowEntryFocusGeneration
        rowEntryFocusTask = Task { @MainActor in
            // vBRDC103: the rail is persistent now, so row entry no longer needs three
            // delayed focus assertions at 0/55/150 ms. One render turn is enough to bind
            // the stable focusable shell to the new row without late snap-back work.
            await Task.yield()
            guard !Task.isCancelled,
                  rowEntryFocusGeneration == generation,
                  scenePhase == .active,
                  store.selectedDetail == nil,
                  playbackBrowseCatalogWorkAllowed,
                  rows.indices.contains(rowIndex),
                  activeRowIndex == rowIndex,
                  rows[rowIndex].id == rowID else { return }
            if focusedRow != rowIndex { focusedRow = rowIndex }
            rowEntryFocusTask = nil
            #if DEBUG
            print("[CatalogFocus][vBRDC103] persistent row entry row=\(rowIndex) id=\(rowID)")
            #endif
        }
    }

    private func scheduleQuickPanelFocusRestore(reason: String) {
        guard !rows.isEmpty else { return }
        if !playbackBrowseRowsPresented || (!playbackBrowseMode && store.topMenuSelectionHoldTab == store.selectedTab) {
            quickPanelFocusRecoveryTask?.cancel()
            quickPanelFocusRecoveryTask = nil
            return
        }
        quickPanelFocusRecoveryTask?.cancel()
        quickPanelFocusRecoveryTask = Task { @MainActor in
            // vBRDC104: ordinary persistent-surface entry needs one render-turn bind only.
            // Keep the older bounded retries solely for true lifecycle/detail recovery where
            // tvOS may be rebuilding a focus graph after another full-screen owner.
            let lower = reason.lowercased()
            let needsRecoveryRetries = lower.contains("detail") || lower.contains("playback") || lower.contains("scene active")
            let delays: [UInt64] = needsRecoveryRetries ? [0, 80_000_000, 220_000_000] : [0]
            for delay in delays {
                if delay > 0 { try? await Task.sleep(nanoseconds: delay) }
                guard !Task.isCancelled,
                      scenePhase == .active,
                      playbackBrowseCatalogWorkAllowed else { return }
                if delay == 0 { await Task.yield() }
                _ = restoreQuickPanelFocusIfPossible()
                focusedRow = min(max(activeRowIndex, 0), max(rows.count - 1, 0))
            }
            #if DEBUG
            print("[CatalogFocus][vBRDC104] restored row=\(focusedRow ?? -1) reason=\(reason) retries=\(delays.count)")
            #endif
            quickPanelFocusRecoveryTask = nil
        }
    }

    @discardableResult
    private func restoreQuickPanelFocusIfPossible() -> Bool {
        guard !rows.isEmpty,
              playbackBrowseRowsPresented,
              playbackBrowseMode || store.topMenuSelectionHoldTab != store.selectedTab else { return false }

        // v1061: restore the exact originating row before doing any global ID search. The
        // same movie/show can appear in many catalogs; searching all rows first could select
        // its first occurrence and briefly display the wrong row/logo when Details closes.
        if let restoreRowID = store.quickPanelRestoreRowID,
           let rowIndex = rows.firstIndex(where: { $0.id == restoreRowID }) {
            let row = rows[rowIndex]
            let restoredItemIndex: Int? = {
                if let restoreID = store.quickPanelRestoreItemID,
                   let index = row.items.firstIndex(where: { $0.id == restoreID }) { return index }
                if let restoreItem = store.quickPanelRestoreIdentityItem,
                   let index = row.items.firstIndex(where: { store.catalogItemsShareCanonicalIdentity($0, restoreItem) }) { return index }
                if let restoreKey = store.quickPanelRestoreCanonicalKey,
                   let index = row.items.firstIndex(where: { store.canonicalCatalogIdentityKey(for: $0) == restoreKey }) { return index }
                guard !row.items.isEmpty else { return nil }
                return min(max(store.quickPanelRestoreItemIndex, 0), row.items.count - 1)
            }()
            if let restoredItemIndex {
                selectedIndices[row.id] = restoredItemIndex
                activeRowIndex = rowIndex
                focusedRow = rowIndex
                return true
            }
        }

        // Provider refreshes can remove or rename the original row. Fall back globally by
        // raw ID, then canonical identity, while still preserving the exact selected item.
        if let restoreID = store.quickPanelRestoreItemID {
            for (rowIndex, row) in rows.enumerated() {
                if let itemIndex = row.items.firstIndex(where: { $0.id == restoreID }) {
                    selectedIndices[row.id] = itemIndex
                    activeRowIndex = rowIndex
                    focusedRow = rowIndex
                    return true
                }
            }
        }
        if let restoreItem = store.quickPanelRestoreIdentityItem {
            for (rowIndex, row) in rows.enumerated() {
                if let itemIndex = row.items.firstIndex(where: {
                    store.catalogItemsShareCanonicalIdentity($0, restoreItem)
                }) {
                    selectedIndices[row.id] = itemIndex
                    activeRowIndex = rowIndex
                    focusedRow = rowIndex
                    return true
                }
            }
        } else if let restoreKey = store.quickPanelRestoreCanonicalKey {
            for (rowIndex, row) in rows.enumerated() {
                if let itemIndex = row.items.firstIndex(where: {
                    store.canonicalCatalogIdentityKey(for: $0) == restoreKey
                }) {
                    selectedIndices[row.id] = itemIndex
                    activeRowIndex = rowIndex
                    focusedRow = rowIndex
                    return true
                }
            }
        }
        if focusedRow == nil { activeRowIndex = 0; focusedRow = 0; return true }
        return false
    }

    private func scheduleDetailHeroAnchorRelease() {
        guard store.selectedDetail == nil, store.detailPresentationAnchorItem != nil else { return }
        detailHeroReleaseTask?.cancel()
        detailHeroReleaseTask = Task { @MainActor in
            // Give FocusState and the fixed-slot rail multiple render turns to settle. The
            // pinned hero remains visible during every retry and is released only when the
            // current row item is canonically identical, making the release a no-op visually.
            let delays: [UInt64] = [70_000_000, 150_000_000, 300_000_000, 520_000_000]
            for delay in delays {
                try? await Task.sleep(nanoseconds: delay)
                guard !Task.isCancelled,
                      scenePhase == .active,
                      store.selectedDetail == nil,
                      playbackBrowseCatalogWorkAllowed else { return }
                _ = restoreQuickPanelFocusIfPossible()
                guard let restored = rowFocusedBackdropItem,
                      let anchor = store.detailPresentationAnchorItem,
                      store.catalogItemsShareCanonicalIdentity(restored, anchor) else { continue }
                store.releaseDetailPresentationAnchorAfterCatalogRestore(matching: restored)
                detailHeroReleaseTask = nil
                return
            }
            // Keep the anchor rather than exposing the wrong title if focus could not be
            // verified. A later content/focus token will retry restoration safely.
            detailHeroReleaseTask = nil
        }
    }

    private func stopFocusedCardPreview() {
        // vBRDC107: teardown is reserved for a real ownership change (different catalog
        // item, trailer/full playback, leaving the catalog, setting off, scene/memory exit).
        // Ordinary focus movement inside the same title no longer reaches this function.
        guard focusedCardPreviewTask != nil
                || focusedCardPreviewURL != nil
                || focusedCardPreviewKey != nil
                || focusedCardPreviewRequestedKey != nil else { return }
        focusedCardPreviewGeneration &+= 1
        focusedCardPreviewTask?.cancel()
        focusedCardPreviewTask = nil
        focusedCardPreviewURL = nil
        focusedCardPreviewKey = nil
        focusedCardPreviewRequestedKey = nil
    }

    private func focusedCardPreviewPresentationAllowed(for item: MediaItem) -> Bool {
        guard let detail = store.selectedDetail else { return true }
        guard store.detailPresentationOrigin == .catalog else { return false }

        // vBRDC136: Media Information legitimately takes tvOS FocusState away from the
        // catalog rail. `focusedRow` can therefore become nil while the popup owns focus;
        // deriving preview ownership from rowFocusedBackdropItem at that moment falls back
        // to row 0 and can falsely classify the exact playing preview as stale. The
        // originating card identity is captured before openDetail and is the durable owner
        // for the whole connected-popup lifetime. Popup focus/navigation must never tear
        // down that AVPlayer unless the media identity actually changes.
        guard let originItem = store.quickPanelRestoreIdentityItem
                ?? store.detailPresentationAnchorItem
                ?? rowFocusedBackdropItem else { return false }
        let detailMatchesOrigin = detail.id == originItem.id
            || store.catalogItemsShareCanonicalIdentity(detail, originItem)
        let previewMatchesOrigin = item.id == originItem.id
            || store.catalogItemsShareCanonicalIdentity(item, originItem)
        return detailMatchesOrigin && previewMatchesOrigin
    }

    private func scheduleFocusedCardPreview(reason: String) {
        guard let item = focusedCardPreviewItem else {
            stopFocusedCardPreview()
            return
        }
        let requestedKey = focusedCardPreviewIdentityKey

        // vBRDC116: do not replay the same completed 35-second preview because the
        // connected Media Profile opened/closed or another same-title UI publication fired.
        // A genuine card/row identity change clears the completion owner below.
        if let completedKey = focusedCardPreviewCompletedKey {
            if completedKey == requestedKey { return }
            focusedCardPreviewCompletedKey = nil
        }

        // vBRDC107: once this exact media identity owns an active preview, UI motion
        // inside the connected Media Profile is irrelevant. Do not consult the ambient
        // UNITY lane here: surface/focus transitions may yield decorative animation, but
        // they must not pause or dismantle an already-playing preview.
        if focusedCardPreviewKey == requestedKey,
           focusedCardPreviewURL != nil,
           focusedCardPreviewPresentationAllowed(for: item),
           store.playbackURL == nil,
           !VODExclusivePlaybackGate.isActive,
           !AuxiliaryVideoPlaybackCoordinator.shared.isAuxiliaryPlaybackSuppressed() {
            focusedCardPreviewTask?.cancel()
            focusedCardPreviewTask = nil
            focusedCardPreviewRequestedKey = requestedKey
            return
        }

        // The same card may still be inside its settle/resolve task when Media Profile
        // opens or focus moves between Play / Trailer / Find Links / Cast. Preserve that
        // request rather than resetting its dwell clock. A different row/card changes the
        // identity key and falls through to the normal replacement path below.
        if focusedCardPreviewRequestedKey == requestedKey,
           focusedCardPreviewTask != nil,
           focusedCardPreviewPresentationAllowed(for: item),
           store.playbackURL == nil,
           !VODExclusivePlaybackGate.isActive,
           !AuxiliaryVideoPlaybackCoordinator.shared.isAuxiliaryPlaybackSuppressed() {
            return
        }

        stopFocusedCardPreview()
        guard focusedCardPreviewsEnabled,
              scenePhase == .active,
              focusedCardPreviewPresentationAllowed(for: item),
              !store.searchActive,
              store.playbackURL == nil,
              !VODExclusivePlaybackGate.isActive,
              !AuxiliaryVideoPlaybackCoordinator.shared.isAuxiliaryPlaybackSuppressed() else { return }

        focusedCardPreviewRequestedKey = requestedKey
        let generation = focusedCardPreviewGeneration
        focusedCardPreviewTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: 2_500_000_000)
            guard !Task.isCancelled,
                  generation == focusedCardPreviewGeneration,
                  requestedKey == focusedCardPreviewIdentityKey,
                  requestedKey == focusedCardPreviewRequestedKey,
                  focusedCardPreviewsEnabled,
                  scenePhase == .active,
                  focusedCardPreviewPresentationAllowed(for: item),
                  !store.searchActive,
                  store.playbackURL == nil,
                  !VODExclusivePlaybackGate.isActive,
                  !AuxiliaryVideoPlaybackCoordinator.shared.isAuxiliaryPlaybackSuppressed(),
                  !UnityFrameRuntime.shared.snapshot.navigationActive else { return }

            // vBRDC293: the resolver is not allowed to compete with an active Siri Remote
            // navigation frame. The next settled-focus publication can arm it again.
            // vBRDC107: resolving the same card's preview is allowed to complete while
            // Media Profile focus moves. Identity/lifecycle gates above are sufficient to
            // prevent stale publication; row navigation changes requestedKey and cancels it.
            guard let resolvedURL = await store.resolveFocusedCardPreviewURL(for: item) else {
                if generation == focusedCardPreviewGeneration {
                    focusedCardPreviewTask = nil
                }
                return
            }
            guard !Task.isCancelled,
                  generation == focusedCardPreviewGeneration,
                  requestedKey == focusedCardPreviewIdentityKey,
                  requestedKey == focusedCardPreviewRequestedKey,
                  focusedCardPreviewPresentationAllowed(for: item),
                  !store.searchActive,
                  store.playbackURL == nil,
                  !VODExclusivePlaybackGate.isActive,
                  !AuxiliaryVideoPlaybackCoordinator.shared.isAuxiliaryPlaybackSuppressed() else { return }

            focusedCardPreviewKey = requestedKey
            focusedCardPreviewURL = resolvedURL
            focusedCardPreviewTask = nil
            print("[FocusedCardPreview][vBRDC107] ready reason=\(reason) title=\"\(item.title)\" qualityCap=720p muted=true duration=35s ownership=media-identity")
        }
    }

    private func finishFocusedCardPreview(key: String) {
        guard focusedCardPreviewKey == key else { return }
        // vBRDC116: completion belongs to the current media identity. Clear the player
        // immediately so the card fades back to artwork, but remember the key so incidental
        // same-title UI events cannot schedule another preview until focus truly changes.
        focusedCardPreviewCompletedKey = key
        stopFocusedCardPreview()
        print("[FocusedCardPreview][vBRDC116] completed cap=35s key=\(key)")
    }

    private func cancelFocusedHeroMetadataLoad(clearVisibleMetadata: Bool) {
        focusedHeroMetadataTask?.cancel()
        focusedHeroMetadataTask = nil
        if clearVisibleMetadata {
            focusedHeroMetadata = nil
            focusedHeroMetadataKey = nil
        }
    }

    private func scheduleFocusedHeroMetadata(reason: String) {
        cancelFocusedHeroMetadataLoad(clearVisibleMetadata: false)
        guard scenePhase == .active,
              store.selectedDetail == nil,
              !store.searchActive,
              store.playbackURL == nil,
              !VODExclusivePlaybackGate.isActive,
              let item = focusedBackdropItem else { return }

        let requestedKey = focusedBackdropKey
        // v1059: keep the previous cache entry parked under its old key until the new
        // request settles. Because rendering already compares keys, stale metadata is never
        // shown, and rapid DPAD movement no longer performs two extra state writes per card.

        let apiKey = heroTMDBApiKey.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !apiKey.isEmpty else { return }

        focusedHeroMetadataTask = Task { @MainActor in
            // vBRDC102: metadata uses the same idle lane as catalog publication/Gracenote.
            // The old fixed 850 ms timer could still fire inside a slow row-motion preset.
            try? await Task.sleep(nanoseconds: 350_000_000)
            guard await UnityFrameRuntime.shared.waitUntilPermitted(.interactiveMetadata, maxWait: 1.60) else { return }
            guard !Task.isCancelled,
                  requestedKey == focusedBackdropKey,
                  scenePhase == .active,
                  store.selectedDetail == nil,
                  !store.searchActive,
                  store.playbackURL == nil,
                  !VODExclusivePlaybackGate.isActive else { return }

            let snapshot = await CatalogHeroMetadataCache.shared.metadata(
                itemID: item.id,
                tmdbID: item.tmdbId,
                imdbID: item.imdbId,
                title: item.title,
                year: item.year,
                type: item.type,
                apiKey: apiKey
            )

            guard !Task.isCancelled,
                  requestedKey == focusedBackdropKey,
                  scenePhase == .active,
                  store.playbackURL == nil,
                  !VODExclusivePlaybackGate.isActive else { return }
            guard await UnityFrameRuntime.shared.waitUntilPermittedDurably(.interactiveMetadata) else { return }
            guard requestedKey == focusedBackdropKey, UnityFrameRuntime.shared.permits(.interactiveMetadata) else { return }

            focusedHeroMetadata = snapshot
            focusedHeroMetadataKey = requestedKey
            focusedHeroMetadataTask = nil
            if let logoURL = snapshot?.logoURL,
               let rowKind = activeRowPresentation?.rowKind?.lowercased(),
               rowKind == "resume" || rowKind == "trakt" {
                PlaybackResumeCacheManager.shared.backfillThemedLogo(for: item, logoURL: logoURL)
            }
            if let runtime = snapshot?.runtimeMinutes {
                print("[CatalogHeroMetadata][v1020] ready reason=\(reason) title=\"\(item.title)\" runtime=\(runtime)m")
            }
        }
    }

    private func logFocusedArtworkProvider(reason: String) {
        // v1059: provider logging was synchronous console I/O on every horizontal DPAD
        // move. Keep the diagnostic in debug builds without taxing release scrolling.
        #if DEBUG
        guard let item = focusedBackdropItem else { return }
        let provider = CatalogArtworkCacheManager.providerName(for: item.landscapeURL ?? item.posterURL, item: item)
        print("Artwork Provider Selected: \(provider) | reason=\(reason) | title=\"\(item.title)\" | catalog=\"\(item.catalog)\" | id=\"\(item.id)\"")
        #endif
    }

    private var overlayHeader: some View {
        HStack(alignment: .lastTextBaseline, spacing: 12) {
            ProviderBrandMark(title: activeProviderBrandTitle, compact: false, presentation: activeRowPresentation)
                .frame(height: 32, alignment: .leading)
            Spacer(minLength: 0)
        }
        .padding(.horizontal, 8)
        .padding(.bottom, 42)
    }

    private func closeOverlay() {
        if playbackBrowseMode {
            store.selectedDetail = nil
            onPlaybackBrowseClose?()
            return
        }

        if NavigationFocusAuditManager.shared.shouldReleaseTopMenuLockWhenClosingOverlay() {
            store.topMenuFocusLocked = false
        }

        // vBRDC131: Back/Menu dismisses the *catalog presentation* using the same UNITY
        // branch scalar that opened it. selectedTab intentionally does not change, so the
        // current Home / Movies / TV Shows item remains selected in the top menu. Do not
        // clear FocusState or make the rail non-focusable here; Root pins the focused card
        // through the reverse motion and requests top-menu focus only after opacity is zero.
        quickPanelFocusRecoveryTask?.cancel()
        quickPanelFocusRecoveryTask = nil
        rowEntryFocusTask?.cancel()
        rowEntryFocusTask = nil
        rowEntryFocusGeneration &+= 1
        detailHeroReleaseTask?.cancel()
        detailHeroReleaseTask = nil
        verticalFocusPinReleaseTask?.cancel()
        verticalFocusPinReleaseTask = nil
        verticalRowVisualFocusPinned = false

        store.selectedDetail = nil
        store.topMenuSelectionHoldTab = store.selectedTab
        store.topMenuFocusLocked = false
        store.catalogRowsPresented = false
    }

}


struct CatalogHeroMetadataRibbon: View {
    let values: [String]
    let secondaryValues: [String]
    let certification: String?
    let rating: String?
    let compact: Bool

    var body: some View {
        VStack(spacing: compact ? 6 : 7) {
            metadataLine(values)
                .frame(maxWidth: .infinity)

            if !secondaryValues.isEmpty || certification != nil || rating != nil {
                HStack(spacing: compact ? 10 : 12) {
                    metadataLine(secondaryValues)

                    if let certification, !certification.isEmpty {
                        Text(certification)
                            .font(.system(size: compact ? 11 : 12, weight: .bold, design: .serif))
                            .tracking(0.55)
                            .foregroundStyle(Color.white.opacity(0.88))
                            .padding(.horizontal, compact ? 7 : 8)
                            .frame(height: compact ? 21 : 23)
                            .overlay(
                                RoundedRectangle(cornerRadius: 4, style: .continuous)
                                    .stroke(Color.white.opacity(0.48), lineWidth: 1)
                            )
                    }

                    if let rating, !rating.isEmpty {
                        HStack(spacing: 5) {
                            Image(systemName: "star.fill")
                                .font(.system(size: compact ? 9 : 10, weight: .black))
                            Text(rating)
                                .font(.system(size: compact ? 12 : 13, weight: .black, design: .rounded))
                                .monospacedDigit()
                        }
                        .foregroundStyle(Color.black.opacity(0.92))
                        .padding(.horizontal, compact ? 8 : 9)
                        .frame(height: compact ? 22 : 24)
                        .background(
                            RoundedRectangle(cornerRadius: 5, style: .continuous)
                                .fill(
                                    LinearGradient(
                                        colors: [Color.orange.opacity(0.98), Color.yellow.opacity(0.94)],
                                        startPoint: .leading,
                                        endPoint: .trailing
                                    )
                                )
                        )
                        .shadow(color: Color.orange.opacity(0.24), radius: 7, x: 0, y: 2)
                    }
                }
                .frame(maxWidth: .infinity, minHeight: compact ? 22 : 24)
            }
        }
        .minimumScaleFactor(0.72)
        .frame(maxWidth: .infinity)
        .shadow(color: .black.opacity(0.78), radius: 5, x: 0, y: 2)
        .accessibilityElement(children: .combine)
    }

    @ViewBuilder
    private func metadataLine(_ lineValues: [String]) -> some View {
        HStack(spacing: compact ? 10 : 12) {
            ForEach(Array(lineValues.enumerated()), id: \.offset) { index, value in
                if index > 0 {
                    Text("•")
                        .font(.system(size: compact ? 11 : 12, weight: .medium, design: .serif))
                        .foregroundStyle(Color.white.opacity(0.40))
                }
                Text(value)
                    .font(.system(size: compact ? 13 : 14, weight: .semibold, design: .serif))
                    .tracking(1.05)
                    .foregroundStyle(Color.white.opacity(0.90))
                    .lineLimit(1)
            }
        }
        .frame(minHeight: compact ? 24 : 26)
    }
}

struct Artwork4HeroLogoLayer: View {
    let item: MediaItem
    let logoURL: String?
    var publishDuringPlayback: Bool = false

    private var fallbackTitle: String {
        item.title.trimmingCharacters(in: .whitespacesAndNewlines).uppercased()
    }

    var body: some View {
        Group {
            if let logoURL, !logoURL.isEmpty {
                RemoteImageFit(
                    url: logoURL,
                    mode: .fit,
                    showPlaceholder: false,
                    maxPixelSize: 1280,
                    // vBRDC187: active-playback catalog navigation is identity-strict.
                    // Never keep the previous title logo visible while the replacement
                    // is waiting for the playback artwork lane. Normal catalog browsing
                    // retains the established seamless same-view behavior.
                    preservePreviousOnURLChange: !publishDuringPlayback,
                    publishDuringSurfaceHandoff: true,
                    publishDuringPlayback: publishDuringPlayback,
                    forceVisiblePlaybackPublication: publishDuringPlayback
                )
                    .id("catalog-hero-logo-\(item.id)-\(logoURL)")
                    .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .leading)
            } else {
                Text(fallbackTitle)
                    .font(.system(size: 56, weight: .black, design: .rounded))
                    .foregroundStyle(.white)
                    .lineLimit(2)
                    .minimumScaleFactor(0.42)
                    .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .leading)
                    .shadow(color: .black.opacity(0.38), radius: 3, x: 0, y: 2)
            }
        }
        .accessibilityLabel(fallbackTitle)
    }
}


private func dcFavoriteCleanToken(_ value: String) -> String {
    value.lowercased()
        .replacingOccurrences(of: #"[^a-z0-9]+"#, with: "-", options: .regularExpression)
        .trimmingCharacters(in: CharacterSet(charactersIn: "-"))
}

func mediaFavoriteKey(_ item: MediaItem) -> String {
    // v829: catalog-agnostic favorite key. Some Stremio/TMDB/provider catalog items use
    // different row/catalog ids for the same movie/show, so including catalog made favorites
    // disappear from the global Favorites tab. Prefer stable external IDs, then item id,
    // then title/year/type. Keep the :: separator for existing storage parsing.
    let type = dcFavoriteCleanToken(item.type.isEmpty ? "media" : item.type)
    if let imdb = item.imdbId?.trimmingCharacters(in: .whitespacesAndNewlines), !imdb.isEmpty { return "imdb::\(dcFavoriteCleanToken(imdb))::\(type)" }
    if let tmdb = item.tmdbId?.trimmingCharacters(in: .whitespacesAndNewlines), !tmdb.isEmpty { return "tmdb::\(dcFavoriteCleanToken(tmdb))::\(type)" }
    if let tvdb = item.tvdbId?.trimmingCharacters(in: .whitespacesAndNewlines), !tvdb.isEmpty { return "tvdb::\(dcFavoriteCleanToken(tvdb))::\(type)" }
    let cleanID = dcFavoriteCleanToken(item.id)
    if !cleanID.isEmpty { return "id::\(cleanID)::\(type)" }
    let title = dcFavoriteCleanToken(item.title)
    let year = dcFavoriteCleanToken(item.year)
    return "title::\(title)-\(year)::\(type)"
}

private func mediaFavoriteLegacyKey(_ item: MediaItem) -> String {
    "\(item.id)::\(item.catalog)::\(item.type)"
}

private func mediaFavoriteKeys(for item: MediaItem) -> Set<String> {
    [mediaFavoriteKey(item), mediaFavoriteLegacyKey(item)]
}

// v607: New Episode Alerts must not depend on the highlighted/visible season.
// Resolve the next upcoming episode from all fetched metadata first; if no dated
// future/today episode exists, synthesize the next logical episode after the
// highest known season/episode instead of alerting the very last aired episode.
// vBRDC119: episode cards and alert scans are high-frequency metadata paths. Keep
// the exact accepted date/season parsing semantics, but reuse the expensive
// ISO8601/DateFormatter/NSRegularExpression objects instead of reconstructing
// them for every episode in every SwiftUI body evaluation.
private final class DCEpisodeMetadataParser {
    static let shared = DCEpisodeMetadataParser()

    private let lock = NSLock()
    private let isoFractional: ISO8601DateFormatter
    private let isoPlain: ISO8601DateFormatter
    private let dayFormatter: DateFormatter
    private let alternateDateFormatters: [DateFormatter]
    private let displayFormatter: DateFormatter
    private let ymdRegex: NSRegularExpression
    private let seasonEpisodeRegexes: [NSRegularExpression]
    private var formatterTimeZoneIdentifier: String
    private var displayLocaleIdentifier: String

    private init() {
        let timeZone = TimeZone.current
        formatterTimeZoneIdentifier = timeZone.identifier
        displayLocaleIdentifier = Locale.current.identifier

        let fractional = ISO8601DateFormatter()
        fractional.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
        isoFractional = fractional

        let plain = ISO8601DateFormatter()
        plain.formatOptions = [.withInternetDateTime]
        isoPlain = plain

        let day = DateFormatter()
        day.locale = Locale(identifier: "en_US_POSIX")
        day.timeZone = timeZone
        day.dateFormat = "yyyy-MM-dd"
        dayFormatter = day

        alternateDateFormatters = ["yyyy/MM/dd", "MM/dd/yyyy", "M/d/yyyy", "MMM d, yyyy", "MMMM d, yyyy"].map { format in
            let formatter = DateFormatter()
            formatter.locale = Locale(identifier: "en_US_POSIX")
            formatter.timeZone = timeZone
            formatter.dateFormat = format
            return formatter
        }

        let display = DateFormatter()
        display.locale = Locale.current
        display.timeZone = timeZone
        display.dateStyle = .medium
        display.timeStyle = .none
        displayFormatter = display

        ymdRegex = try! NSRegularExpression(pattern: #"\d{4}-\d{2}-\d{2}"#)
        seasonEpisodeRegexes = [
            #"s(\d{1,2})\s*e(\d{1,3})"#,
            #"season\s*(\d{1,2}).{0,18}?episode\s*(\d{1,3})"#,
            #"\b(\d{1,2})x(\d{1,3})\b"#
        ].map { try! NSRegularExpression(pattern: $0) }
    }

    private func refreshFormatterContextIfNeeded() {
        let currentTimeZone = TimeZone.current
        if currentTimeZone.identifier != formatterTimeZoneIdentifier {
            formatterTimeZoneIdentifier = currentTimeZone.identifier
            dayFormatter.timeZone = currentTimeZone
            alternateDateFormatters.forEach { $0.timeZone = currentTimeZone }
            displayFormatter.timeZone = currentTimeZone
        }
        let currentLocale = Locale.current
        if currentLocale.identifier != displayLocaleIdentifier {
            displayLocaleIdentifier = currentLocale.identifier
            displayFormatter.locale = currentLocale
        }
    }

    func alertDate(from rawValues: [String]) -> Date? {
        lock.lock()
        defer { lock.unlock() }
        refreshFormatterContextIfNeeded()
        for raw in rawValues {
            if let date = isoFractional.date(from: raw) ?? isoPlain.date(from: raw) ?? dayFormatter.date(from: raw) {
                return date
            }
            let nsRange = NSRange(raw.startIndex..<raw.endIndex, in: raw)
            if let match = ymdRegex.firstMatch(in: raw, range: nsRange),
               let range = Range(match.range, in: raw),
               let date = dayFormatter.date(from: String(raw[range])) {
                return date
            }
        }
        return nil
    }

    func episodeDate(from rawValues: [String]) -> Date? {
        lock.lock()
        defer { lock.unlock() }
        refreshFormatterContextIfNeeded()
        for raw in rawValues {
            if let exact = isoFractional.date(from: raw) ?? isoPlain.date(from: raw) {
                return exact
            }
            let nsRange = NSRange(raw.startIndex..<raw.endIndex, in: raw)
            if let match = ymdRegex.firstMatch(in: raw, range: nsRange),
               let range = Range(match.range, in: raw),
               let parsed = dayFormatter.date(from: String(raw[range])) {
                return parsed
            }
            for formatter in alternateDateFormatters {
                if let parsed = formatter.date(from: raw) { return parsed }
            }
        }
        return nil
    }

    func displayDate(_ date: Date) -> String {
        lock.lock()
        defer { lock.unlock() }
        refreshFormatterContextIfNeeded()
        return displayFormatter.string(from: date)
    }

    func seasonEpisode(from raw: String) -> (season: Int, episode: Int)? {
        lock.lock()
        defer { lock.unlock() }
        let nsRange = NSRange(raw.startIndex..<raw.endIndex, in: raw)
        for regex in seasonEpisodeRegexes {
            guard let match = regex.firstMatch(in: raw, range: nsRange), match.numberOfRanges >= 3,
                  let seasonRange = Range(match.range(at: 1), in: raw),
                  let episodeRange = Range(match.range(at: 2), in: raw),
                  let season = Int(raw[seasonRange]),
                  let episode = Int(raw[episodeRange]) else { continue }
            return (max(1, season), max(1, episode))
        }
        return nil
    }
}

private func dcAlertDateFromEpisode(_ item: MediaItem) -> Date? {
    let rawValues = [item.airDateString, item.year, item.description]
        .compactMap { $0?.trimmingCharacters(in: .whitespacesAndNewlines) }
        .filter { !$0.isEmpty }
    return DCEpisodeMetadataParser.shared.alertDate(from: rawValues)
}

private struct DCEpisodeDatePresentation {
    let date: Date
    let dateText: String
    let statusText: String
    let combinedText: String
    let isUpcoming: Bool
}

// v1104: episode information must use an actual episode air/release date only.
// Never inspect synopsis text or the device clock as a metadata fallback.
private func dcEpisodeDatePresentation(_ item: MediaItem, now: Date = Date()) -> DCEpisodeDatePresentation? {
    let rawValues = ([item.airDateString] + item.episodeDateStrings.map { Optional($0) })
        .compactMap { $0?.trimmingCharacters(in: .whitespacesAndNewlines) }
        .filter { !$0.isEmpty }
        .uniquedPreservingOrder()

    guard let resolvedDate = DCEpisodeMetadataParser.shared.episodeDate(from: rawValues) else { return nil }

    let calendar = Calendar.current
    let dateDay = calendar.startOfDay(for: resolvedDate)
    let today = calendar.startOfDay(for: now)
    let isUpcoming = dateDay > today
    let isToday = calendar.isDate(dateDay, inSameDayAs: today)
    let dateText = DCEpisodeMetadataParser.shared.displayDate(resolvedDate)
    let statusText = isUpcoming ? "UPCOMING" : (isToday ? "TODAY" : "AIRED")
    return DCEpisodeDatePresentation(
        date: resolvedDate,
        dateText: dateText,
        statusText: statusText,
        combinedText: "\(statusText) • \(dateText)",
        isUpcoming: isUpcoming
    )
}

private func dcParsedSeasonEpisode(_ item: MediaItem) -> (season: Int, episode: Int) {
    if let s = item.seasonNumber, let e = item.episodeNumber { return (max(1, s), max(1, e)) }
    let raw = "\(item.title) \(item.id) \(item.catalog)".lowercased()
    return DCEpisodeMetadataParser.shared.seasonEpisode(from: raw)
        ?? (max(1, item.seasonNumber ?? 1), max(1, item.episodeNumber ?? 1))
}

private func dcNextUpcomingEpisodeAlertItem(parent: MediaItem, episodes: [MediaItem], fallback: MediaItem) -> MediaItem {
    let calendar = Calendar.current
    let startOfToday = calendar.startOfDay(for: Date())
    let dated = episodes.compactMap { ep -> (MediaItem, Date, Int, Int)? in
        guard let date = dcAlertDateFromEpisode(ep) else { return nil }
        let se = dcParsedSeasonEpisode(ep)
        return (ep, date, se.season, se.episode)
    }
    let upcoming = dated
        .filter { calendar.startOfDay(for: $0.1) >= startOfToday }
        .sorted { lhs, rhs in
            if lhs.1 != rhs.1 { return lhs.1 < rhs.1 }
            if lhs.2 != rhs.2 { return lhs.2 < rhs.2 }
            return lhs.3 < rhs.3
        }
    if let next = upcoming.first?.0 { return next }

    let allSE = episodes.map(dcParsedSeasonEpisode)
    let latest = allSE.max { lhs, rhs in
        if lhs.season != rhs.season { return lhs.season < rhs.season }
        return lhs.episode < rhs.episode
    } ?? dcParsedSeasonEpisode(fallback)
    let nextEpisode = max(1, latest.episode + 1)
    return MediaItem(
        id: "\(parent.id.isEmpty ? parent.title : parent.id):next:\(latest.season):\(nextEpisode)",
        title: "\(parent.title) S\(String(format: "%02d", latest.season))E\(String(format: "%02d", nextEpisode))",
        year: fallback.year,
        type: "series",
        catalog: "Season \(latest.season)",
        description: "Next upcoming episode alert. Release date was not exposed by the current catalog metadata, so Debrid Channels selected the next logical episode after the latest known episode.",
        genres: fallback.genres,
        rating: fallback.rating,
        posterURL: parent.posterURL,
        landscapeURL: parent.landscapeURL ?? parent.posterURL,
        logoURL: parent.logoURL,
        previewURL: fallback.previewURL,
        addonName: fallback.addonName,
        addonIconURL: fallback.addonIconURL,
        seasonNumber: latest.season,
        episodeNumber: nextEpisode,
        cast: fallback.cast,
        directors: fallback.directors,
        castMembers: fallback.castMembers,
        airDateString: nil
    )
}

private func favoriteMediaKeySet(_ raw: String) -> Set<String> {
    Set(raw.split(separator: "|").map { String($0).trimmingCharacters(in: .whitespacesAndNewlines) }.filter { $0.contains("::") })
}

// v1128: Search results can exist outside the currently loaded catalog rows. Persist a
// compact MediaItem snapshot beside the existing favorite key so Favorites can reconstruct
// a Search-only title after the Search screen closes or the app relaunches. The existing
// `favoriteMediaIds` key remains authoritative and unchanged.
private let favoriteMediaSnapshotsDefaultsKey = "favoriteMediaSnapshotsV1"
private let favoriteMediaSnapshotsBackupKey = "favoriteMediaSnapshotsV1Base64"
private let favoriteMediaLibraryBackupKey = "favoriteMediaLibraryV2Base64"

// vBRDC159: Protected profile backups must carry a durable Favorites library, not a
// second copy of the full metadata model. This record is intentionally small and stable:
// enough identity/artwork to render a restored favorite immediately, while cast/credits/
// season/franchise payloads stay in the normal metadata caches where they belong.
private struct PortableFavoriteMediaRecord: Codable {
    var canonicalKey: String
    var favoriteKeys: [String]
    var id: String
    var tmdbId: String?
    var imdbId: String?
    var tvdbId: String?
    var title: String
    var year: String
    var type: String
    var catalog: String
    var description: String
    var genres: [String]
    var rating: String
    var posterURL: String?
    var landscapeURL: String?
    var logoURL: String?
    var previewURL: String?
    var addonName: String?
    var addonIconURL: String?

    init(item source: MediaItem, favoriteKeys: Set<String>) {
        let item = compactFavoriteMediaSnapshot(source)
        canonicalKey = mediaFavoriteKey(item)
        self.favoriteKeys = Array(favoriteKeys.union(mediaFavoriteKeys(for: item))).sorted()
        id = item.id
        tmdbId = item.tmdbId
        imdbId = item.imdbId
        tvdbId = item.tvdbId
        title = item.title
        year = item.year
        type = item.type
        catalog = item.catalog
        description = String(item.description.prefix(900))
        genres = Array(item.genres.prefix(6))
        rating = item.rating
        posterURL = item.posterURL
        landscapeURL = item.landscapeURL
        logoURL = item.logoURL
        previewURL = item.previewURL
        addonName = item.addonName
        addonIconURL = item.addonIconURL
    }

    var mediaItem: MediaItem {
        MediaItem(
            id: id,
            tmdbId: tmdbId,
            imdbId: imdbId,
            tvdbId: tvdbId,
            title: title,
            year: year,
            type: type,
            catalog: catalog,
            description: description,
            genres: genres,
            rating: rating,
            posterURL: posterURL,
            landscapeURL: landscapeURL,
            logoURL: logoURL,
            previewURL: previewURL,
            addonName: addonName,
            addonIconURL: addonIconURL
        )
    }
}

private func compactFavoriteMediaSnapshot(_ source: MediaItem) -> MediaItem {
    var compact = source
    // vBRDC158: Favorites backup is a durable library index, not a second metadata cache.
    // Keep everything required to render/reopen the title, but strip high-cardinality fields
    // that made larger restore-code payloads exceed the old 1.5 MB safety ceiling.
    compact.description = String(compact.description.prefix(1400))
    compact.genres = Array(compact.genres.prefix(8))
    compact.cast = []
    compact.directors = []
    compact.castMembers = []
    compact.episodeDateStrings = []
    compact.franchiseItems = []
    return compact
}

private func mergedFavoriteMediaSnapshot(existing: MediaItem?, candidate: MediaItem) -> MediaItem {
    guard let existing else { return compactFavoriteMediaSnapshot(candidate) }
    var merged = candidate
    func missing(_ value: String?) -> Bool {
        value?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ?? true
    }
    if missing(merged.tmdbId) { merged.tmdbId = existing.tmdbId }
    if missing(merged.imdbId) { merged.imdbId = existing.imdbId }
    if missing(merged.tvdbId) { merged.tvdbId = existing.tvdbId }
    if missing(merged.posterURL) { merged.posterURL = existing.posterURL }
    if missing(merged.landscapeURL) { merged.landscapeURL = existing.landscapeURL }
    // Never let an older Search/Favorites shell erase a clearlogo that was already resolved.
    if missing(merged.logoURL) { merged.logoURL = existing.logoURL }
    if missing(merged.previewURL) { merged.previewURL = existing.previewURL }
    if merged.description.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty { merged.description = existing.description }
    if merged.genres.isEmpty { merged.genres = existing.genres }
    if merged.rating.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty { merged.rating = existing.rating }
    if missing(merged.addonName) { merged.addonName = existing.addonName }
    if missing(merged.addonIconURL) { merged.addonIconURL = existing.addonIconURL }
    return compactFavoriteMediaSnapshot(merged)
}

private func favoriteMediaSnapshotsBackupString() -> String {
    let snapshots = favoriteMediaSnapshots()
    guard !snapshots.isEmpty else { return "" }
    let compact = snapshots.mapValues { compactFavoriteMediaSnapshot($0) }
    guard let data = try? JSONEncoder().encode(compact),
          !data.isEmpty,
          data.count <= 1_500_000 else { return "" }
    return data.base64EncodedString()
}

private func favoriteMediaLibraryRecords() -> [PortableFavoriteMediaRecord] {
    let authoritativeKeys = favoriteMediaKeySet(UserDefaults.standard.string(forKey: "favoriteMediaIds") ?? "")
    guard !authoritativeKeys.isEmpty else { return [] }

    let snapshots = favoriteMediaSnapshots()
    var grouped: [(item: MediaItem, aliases: Set<String>)] = []
    grouped.reserveCapacity(min(authoritativeKeys.count, 200))

    for (snapshotKey, stored) in snapshots {
        let itemAliases = mediaFavoriteKeys(for: stored)
        guard authoritativeKeys.contains(snapshotKey) || !authoritativeKeys.isDisjoint(with: itemAliases) else { continue }

        if let index = grouped.firstIndex(where: { favoriteMediaSnapshotIdentityMatches($0.item, stored) }) {
            grouped[index].item = mergedFavoriteMediaSnapshot(existing: grouped[index].item, candidate: stored)
            grouped[index].aliases.insert(snapshotKey)
            grouped[index].aliases.formUnion(authoritativeKeys.intersection(itemAliases))
        } else {
            var aliases = Set<String>()
            aliases.insert(snapshotKey)
            aliases.formUnion(authoritativeKeys.intersection(itemAliases))
            grouped.append((compactFavoriteMediaSnapshot(stored), aliases))
        }
    }

    return grouped.map { entry in
        PortableFavoriteMediaRecord(item: entry.item, favoriteKeys: entry.aliases)
    }.sorted { $0.canonicalKey < $1.canonicalKey }
}

private func favoriteMediaLibraryBackupString() -> String {
    let records = favoriteMediaLibraryRecords()
    guard !records.isEmpty,
          let data = try? JSONEncoder().encode(records),
          !data.isEmpty,
          data.count <= 900_000 else { return "" }
    return data.base64EncodedString()
}

@discardableResult
private func restoreFavoriteMediaLibrary(from encoded: String) -> Bool {
    guard !encoded.isEmpty,
          encoded.utf8.count <= 1_250_000,
          let data = Data(base64Encoded: encoded),
          data.count <= 900_000,
          let records = try? JSONDecoder().decode([PortableFavoriteMediaRecord].self, from: data),
          !records.isEmpty else { return false }

    var snapshots = favoriteMediaSnapshots()
    for record in records.prefix(240) {
        let candidate = compactFavoriteMediaSnapshot(record.mediaItem)
        let matchingKeys = snapshots.compactMap { key, stored in
            favoriteMediaSnapshotIdentityMatches(stored, candidate) ? key : nil
        }
        var strongest: MediaItem? = nil
        for key in matchingKeys {
            if let stored = snapshots[key] {
                strongest = mergedFavoriteMediaSnapshot(existing: strongest, candidate: stored)
            }
        }
        let merged = mergedFavoriteMediaSnapshot(existing: strongest, candidate: candidate)
        for key in matchingKeys { snapshots[key] = merged }
        snapshots[record.canonicalKey] = merged
        snapshots[mediaFavoriteKey(merged)] = merged
        for key in record.favoriteKeys where key.contains("::") { snapshots[key] = merged }
    }

    guard let snapshotData = try? JSONEncoder().encode(snapshots), snapshotData.count <= 1_500_000 else { return false }
    UserDefaults.standard.set(snapshotData, forKey: favoriteMediaSnapshotsDefaultsKey)
    return true
}

private func favoriteMediaSnapshots() -> [String: MediaItem] {
    guard let data = UserDefaults.standard.data(forKey: favoriteMediaSnapshotsDefaultsKey),
          let decoded = try? JSONDecoder().decode([String: MediaItem].self, from: data) else { return [:] }
    return decoded
}

private func favoriteMediaSnapshotIdentityMatches(_ lhs: MediaItem, _ rhs: MediaItem) -> Bool {
    if !mediaFavoriteKeys(for: lhs).isDisjoint(with: mediaFavoriteKeys(for: rhs)) { return true }
    let lhsTitle = dcFavoriteCleanToken(lhs.title)
    let rhsTitle = dcFavoriteCleanToken(rhs.title)
    let lhsType = dcFavoriteCleanToken(lhs.type)
    let rhsType = dcFavoriteCleanToken(rhs.type)
    guard !lhsTitle.isEmpty, lhsTitle == rhsTitle, lhsType == rhsType else { return false }
    let lhsYear = lhs.year.filter(\.isNumber)
    let rhsYear = rhs.year.filter(\.isNumber)
    return lhsYear.isEmpty || rhsYear.isEmpty || lhsYear == rhsYear
}

private final class FavoriteProfileBackupSyncManager {
    static let shared = FavoriteProfileBackupSyncManager()
    private var task: Task<Void, Never>?
    private init() {}

    func scheduleSync() {
        task?.cancel()
        task = Task {
            try? await Task.sleep(nanoseconds: 1_400_000_000)
            guard !Task.isCancelled else { return }
            await syncNow()
        }
    }

    private func syncNow() async {
        let defaults = UserDefaults.standard
        let code = (defaults.string(forKey: "backendProfileBackupCode") ?? "")
            .uppercased().filter { $0.isLetter || $0.isNumber || $0 == "-" }
        guard !code.isEmpty else { return }
        let baseURL = (defaults.string(forKey: "backendBaseURL") ?? "https://api.skylinejay187.it.com")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        guard !baseURL.isEmpty else { return }

        do {
            let restored = try await BackendProfileBackupClient.restore(baseURL: baseURL, code: code)
            guard restored.ok, var profile = restored.profile else { return }
            let ids = defaults.string(forKey: "favoriteMediaIds") ?? ""
            let portableLibrary = favoriteMediaLibraryBackupString()
            let legacySnapshots = portableLibrary.isEmpty ? favoriteMediaSnapshotsBackupString() : ""
            if var settings = profile["settings"] as? [String: Any] {
                settings["favoriteMediaIds"] = ids
                if !portableLibrary.isEmpty {
                    settings[favoriteMediaLibraryBackupKey] = portableLibrary
                    settings.removeValue(forKey: favoriteMediaSnapshotsBackupKey)
                } else {
                    settings[favoriteMediaSnapshotsBackupKey] = legacySnapshots
                    settings.removeValue(forKey: favoriteMediaLibraryBackupKey)
                }
                profile["settings"] = settings
            } else {
                profile["favoriteMediaIds"] = ids
                if !portableLibrary.isEmpty {
                    profile[favoriteMediaLibraryBackupKey] = portableLibrary
                    profile.removeValue(forKey: favoriteMediaSnapshotsBackupKey)
                } else {
                    profile[favoriteMediaSnapshotsBackupKey] = legacySnapshots
                    profile.removeValue(forKey: favoriteMediaLibraryBackupKey)
                }
            }
            let deviceName = defaults.string(forKey: "DebridChannelsDeviceName") ?? "Apple TV"
            let saved = try await BackendProfileBackupClient.save(
                baseURL: baseURL,
                code: code,
                profile: profile,
                deviceName: deviceName,
                appBuild: ReleaseCandidateSecurityManager.releaseIdentity()
            )
            if saved.ok {
                defaults.set(saved.updatedAt ?? Date().friendlyBackupDate, forKey: "backendProfileBackupLastDate")
                defaults.set("Backup library synced automatically.", forKey: "backendProfileBackupLastStatus")
            }
        } catch {
            // Library sync is opportunistic. Never block Favorites or surface a navigation
            // error because the backup backend is temporarily unavailable.
        }
    }
}

private func persistFavoriteMediaSnapshot(_ item: MediaItem) {
    var snapshots = favoriteMediaSnapshots()
    let matchingKeys = snapshots.compactMap { key, stored in
        favoriteMediaSnapshotIdentityMatches(stored, item) ? key : nil
    }
    var strongestExisting: MediaItem? = nil
    for key in matchingKeys {
        if let stored = snapshots[key] {
            strongestExisting = mergedFavoriteMediaSnapshot(existing: strongestExisting, candidate: stored)
        }
    }
    let compact = mergedFavoriteMediaSnapshot(existing: strongestExisting, candidate: item)
    for key in matchingKeys { snapshots[key] = compact }
    snapshots[mediaFavoriteKey(compact)] = compact
    if snapshots.count > 200 {
        for key in snapshots.keys.sorted().prefix(snapshots.count - 200) { snapshots.removeValue(forKey: key) }
    }
    if let data = try? JSONEncoder().encode(snapshots), data.count <= 1_500_000 {
        UserDefaults.standard.set(data, forKey: favoriteMediaSnapshotsDefaultsKey)
    }
    FavoriteProfileBackupSyncManager.shared.scheduleSync()
}

private func removeFavoriteMediaSnapshot(for item: MediaItem) {
    var snapshots = favoriteMediaSnapshots()
    let aliases = mediaFavoriteKeys(for: item)
    let keysToRemove = snapshots.compactMap { key, stored in
        if aliases.contains(key) || favoriteMediaSnapshotIdentityMatches(stored, item) { return key }
        return nil
    }
    for key in keysToRemove { snapshots.removeValue(forKey: key) }
    if let data = try? JSONEncoder().encode(snapshots) {
        UserDefaults.standard.set(data, forKey: favoriteMediaSnapshotsDefaultsKey)
    }
    FavoriteProfileBackupSyncManager.shared.scheduleSync()
}

private func persistedFavoriteMediaItems(matching favoriteKeys: Set<String>) -> [MediaItem] {
    favoriteMediaSnapshots().compactMap { key, item in
        // The dictionary key can be an older pre-hydration canonical identity while the
        // value has since gained a stronger external ID. Honor either representation.
        if favoriteKeys.contains(key) || !favoriteKeys.isDisjoint(with: mediaFavoriteKeys(for: item)) { return item }
        return nil
    }
}

private func isFavoriteMovieOrShow(_ item: MediaItem) -> Bool {
    let type = item.type.lowercased()
    return type.contains("movie") || type.contains("series") || type.contains("show") || type == "tv"
}

struct GridOSFixedSlotCatalogRail: View {
    @EnvironmentObject var store: CatalogStore
    private let unityAnimations = UnityAnimationCoordinator.shared
    @AppStorage("favoriteMediaIds") private var favoriteMediaIdsRaw: String = ""
    @AppStorage("sportsExcludedChannelIds") private var sportsExcludedChannelIdsRaw: String = ""
    @AppStorage("sportsExcludedChannelNames") private var sportsExcludedChannelNamesRaw: String = ""
    let row: MediaRow
    let rowIndex: Int
    var maxRowIndex: Int? = nil
    var cardWidth: CGFloat = 338
    var cardHeight: CGFloat = 190
    var railHeight: CGFloat = 266
    var cardBottomInset: CGFloat = 48
    var focusedRow: FocusState<Int?>.Binding
    @Binding var selectedIndex: Int
    var focusedPreviewURL: URL? = nil
    var focusedPreviewKey: String? = nil
    var onFocusedPreviewFinished: ((String) -> Void)? = nil
    var onRowMove: ((Int) -> Void)? = nil
    var onNavigationActivity: ((SignalMoveDirection) -> Void)? = nil
    // vBRDC109: the root surface owns open/close geometry. While pinned, this rail keeps
    // its selected card at final focused geometry even if tvOS temporarily releases FocusState.
    var surfaceVisualFocusPinned: Bool = false
    // vBRDC130: the persistent catalog rail stays mounted for frame-budget reasons, but
    // Back/Menu can temporarily remove it from the tvOS focus graph while the selected
    // top-menu item takes ownership.
    var allowsFocus: Bool = true
    var allowsLazyRefresh: Bool = true
    var playbackBrowseMode: Bool = false
    var allowsRailAnimations: Bool = true
    // vBRDC163: Favorites opts out of the catalog fan/compression geometry. nil preserves
    // the established Home/Movies/Shows rail exactly; a value produces equal-width previews.
    var fixedPreviewCardWidth: CGFloat? = nil
    @AppStorage("focusedCardPulseAnimationEnabled") private var focusedCardPulseAnimationEnabled: Bool = false
    @AppStorage("connectedMediaPopupArtworkEnabled") private var connectedMediaPopupArtworkEnabled: Bool = false
    @AppStorage("catalogRowScrollingAnimationPreset") private var catalogRowScrollingAnimationPreset: String = UnityCatalogRowMotionStyle.defaultName
    @State private var lastHorizontalMoveDirection: Int = 1
    // vBRDC103: one persistent compositor phase drives all 48 catalog motion presets.
    // Card/image-loader identity stays stable while only this transform animates.
    @State private var persistentRailMotionPhase: CGFloat = 1
    @State private var persistentRailMotionGeneration: UInt64 = 0
    // vBRDC092: Connected Popup Artwork should already be warm before Select is pressed.
    // This cancellable task waits until the row's own motion budget has settled, so a
    // 2048 detail decode never competes with remote navigation or starts for fly-by cards.
    @StateObject private var catalogRailAsyncRuntime = CatalogRailAsyncTaskRuntime()
    private var connectedArtworkPrewarmTask: Task<Void, Never>? {
            get { catalogRailAsyncRuntime.connectedArtworkPrewarmTask }
            nonmutating set { catalogRailAsyncRuntime.connectedArtworkPrewarmTask = newValue }
        }

    private var safeIndex: Int {
        guard !row.items.isEmpty else { return 0 }
        return min(max(selectedIndex, 0), row.items.count - 1)
    }

    private var selectedItem: MediaItem? {
        guard !row.items.isEmpty else { return nil }
        return row.items[safeIndex]
    }

    private var detailKeepsSelectedCardVisuallyFocused: Bool {
        guard let selectedItem else { return false }
        // vBRDC095: keep the originating card visually pinned not only while Media
        // Information is mounted, but through the short catalog-focus handoff after
        // selectedDetail becomes nil. vBRDC092/v094 pinned only against selectedDetail;
        // that created a one-frame false->true focus edge on Back. Because focused-card
        // width/height and the rail layout are focus-dependent, that single edge made the
        // focused card and every trailing poster visibly bounce together. The retained
        // detailPresentationAnchorItem is already released only after exact row/index
        // restoration is verified, so it is the authoritative no-gap identity bridge.
        guard let detailIdentity = store.selectedDetail ?? store.detailPresentationAnchorItem else { return false }
        guard store.quickPanelRestoreRowID == row.id,
              store.quickPanelRestoreItemIndex == safeIndex else { return false }
        if selectedItem.id == detailIdentity.id || store.quickPanelRestoreItemID == selectedItem.id {
            return true
        }
        let selectedKey = store.canonicalCatalogIdentityKey(for: selectedItem)
        let detailKey = store.canonicalCatalogIdentityKey(for: detailIdentity)
        return !selectedKey.isEmpty && selectedKey == detailKey
    }

    private var coordinatedRailAnimations: Bool {
        allowsRailAnimations && unityAnimations.allows(.catalogRowMotion)
    }

    private var coordinatedFocusArrivalAnimation: Bool {
        allowsRailAnimations
            && !surfaceVisualFocusPinned
            && !unityAnimations.surfaceHandoffActive
            && unityAnimations.allows(.catalogFocusArrival)
    }

    private var coordinatedPulseAnimation: Bool {
        // vBRDC092 same-frame isolation: Media Information/Source Intelligence owns the
        // overlay compositor. Freeze the underlying glow pulse immediately when Details
        // mounts, even before Root's UNITY context publication reaches this rail. The
        // preview player is deliberately separate and may remain mounted independently.
        allowsRailAnimations
            && focusedCardPulseAnimationEnabled
            && store.selectedDetail == nil
    }

    private var cardIsVisuallyFocused: Bool {
        surfaceVisualFocusPinned
            || (allowsFocus && focusedRow.wrappedValue == rowIndex)
            || (allowsFocus && detailKeepsSelectedCardVisuallyFocused)
    }

    private var previewSlotCount: Int {
        guard !row.items.isEmpty else { return 0 }
        let firstPreviewIndex = safeIndex + 1
        let remainingCount = max(0, row.items.count - firstPreviewIndex)
        guard remainingCount > 0 else { return 0 }

        // vBRDC103: calculate a fixed number of structural slots. We do not create a new
        // MediaItem array or key child views by media identity on every D-pad press.
        let viewportWidth = max(SignalVisionWindowMetrics.currentWindowBounds.width, 1920)
        let targetWidth = max(0, viewportWidth - cardWidth - 54)

        // vBRDC163 Favorites: equal-width preview cards stop the rail from progressively
        // squeezing every remaining poster into thin vertical strips across the television.
        if let fixedPreviewCardWidth {
            let slotWidth = max(96, fixedPreviewCardWidth) + 14
            return min(remainingCount, max(1, Int(targetWidth / slotWidth)))
        }

        var occupied: CGFloat = 0
        var count = 0
        while count < remainingCount, occupied < targetWidth {
            let width = max(64, 116 - CGFloat(count) * 4.4)
            occupied += width + 14
            count += 1
        }
        return min(remainingCount, count + 2)
    }

    private func previewItem(at depth: Int) -> MediaItem? {
        let itemIndex = safeIndex + 1 + depth
        guard depth >= 0, itemIndex >= 0, itemIndex < row.items.count else { return nil }
        return row.items[itemIndex]
    }

    private func isCatalogFavorite(_ item: MediaItem) -> Bool {
        !favoriteMediaKeySet(favoriteMediaIdsRaw).isDisjoint(with: mediaFavoriteKeys(for: item))
    }

    private func toggleCatalogFavorite(_ item: MediaItem) {
        var keys = favoriteMediaKeySet(favoriteMediaIdsRaw)
        let key = mediaFavoriteKey(item)
        let allKeys = mediaFavoriteKeys(for: item)
        if !keys.isDisjoint(with: allKeys) {
            keys.subtract(allKeys)
            removeFavoriteMediaSnapshot(for: item)
            store.status = "Removed \(item.title) from Favorites."
        } else {
            keys.insert(key)
            persistFavoriteMediaSnapshot(item)
            store.status = "Added \(item.title) to Favorites."
        }
        favoriteMediaIdsRaw = keys.sorted().joined(separator: "|")
    }

    private func favoriteActionTitle(for item: MediaItem) -> String {
        isCatalogFavorite(item) ? "Remove from Favorites" : "Add to Favorites"
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 14) {
            HStack(alignment: .bottom, spacing: 14) {
                if let selectedItem {
                    FixedSlotFocusedCatalogCard(
                        item: selectedItem,
                        focused: cardIsVisuallyFocused,
                        detailPresentationActive: store.selectedDetail != nil || store.detailPresentationAnchorItem != nil,
                        animateFocusArrival: coordinatedFocusArrivalAnimation,
                        animateFocusGeometry: !surfaceVisualFocusPinned,
                        animateSlowPulse: coordinatedPulseAnimation,
                        cardWidth: cardWidth,
                        cardHeight: cardHeight,
                        rowID: row.id,
                        // v1063: preserve the exact focused-card preview under its own
                        // connected popup. cardIsVisuallyFocused is identity-pinned to the
                        // originating row/index, so no neighboring or previous card can play.
                        previewURL: cardIsVisuallyFocused ? focusedPreviewURL : nil,
                        previewKey: focusedPreviewKey,
                        onPreviewFinished: onFocusedPreviewFinished,
                        publishDuringPlayback: playbackBrowseMode
                    )
                    .equatable()
                }

                // vBRDC103/vBRDC125: preview views remain structural depth slots
                // (0,1,2...) so the rail/compositor does not churn on every D-pad press.
                // vBRDC125 scopes only each RemoteImageFit owner to media identity, so the
                // persistent slot can never display another title's retained pixels.
                ForEach(0..<previewSlotCount, id: \.self) { depth in
                    if let item = previewItem(at: depth) {
                        FixedSlotPreviewCatalogCard(
                            item: item,
                            depth: depth,
                            maxCardHeight: cardHeight,
                            rowID: row.id,
                            fixedCardWidth: fixedPreviewCardWidth,
                            publishDuringPlayback: playbackBrowseMode
                        )
                    }
                }

                Spacer(minLength: 0)
            }
            .modifier(
                UnityCatalogPersistentRailMotionModifier(
                    transform: coordinatedRailAnimations
                        ? UnityCatalogRowMotionStyle.persistentArrivalTransform(
                            for: catalogRowScrollingAnimationPreset,
                            direction: lastHorizontalMoveDirection
                        )
                        : .identity,
                    phase: persistentRailMotionPhase
                )
            )
            .frame(height: max(218, cardHeight + cardBottomInset), alignment: .bottomLeading)
            // vBRDC088: report the fixed catalog slot, not the animated card itself. The
            // focused card intentionally bounces and can pulse forever; measuring inside that
            // transformed subtree caused its global CGRect preference to republish during the
            // animation and invalidate RootView. This invisible overlay matches the card's
            // resting slot/offset without participating in layout or changing any pixels.
            .overlay(alignment: .bottomLeading) {
                if cardIsVisuallyFocused {
                    Color.clear
                        .frame(width: cardWidth, height: cardHeight)
                        .offset(y: -6)
                        .background(
                            GeometryReader { proxy in
                                Color.clear.preference(
                                    key: FocusedCatalogCardFramePreferenceKey.self,
                                    value: proxy.frame(in: .global)
                                )
                            }
                            .allowsHitTesting(false)
                        )
                        .allowsHitTesting(false)
                }
            }
            .contentShape(Rectangle())
            .focusable(allowsFocus)
            .focused(focusedRow, equals: rowIndex)
            .modifier(TransparentTVFocusVisual())
            .onTapGesture { openSelected() }
            .signalVisionPlayPauseCommand { openSelected() }
            .contextMenu {
                if let selectedItem, selectedItem.type == "movie" || selectedItem.type == "series" {
                    Button(favoriteActionTitle(for: selectedItem)) { toggleCatalogFavorite(selectedItem) }
                }
            }
            .signalMoveCommand { direction in
                handleMove(direction)
            }
            .onReceive(NotificationCenter.default.publisher(for: SignalVisionRemoteEvent.catalogDirection)) { note in
                guard allowsFocus, !row.items.isEmpty,
                      store.selectedDetail == nil,
                      let direction = note.object as? SignalMoveDirection else { return }
                handleMove(direction)
            }
            .onAppear {
                if allowsLazyRefresh {
                    store.requestLazyCatalogRowRefresh(row: row, selectedItem: selectedItem, reason: "row appear")
                }
                scheduleConnectedArtworkPrewarm(reason: "row appear")
            }
            .onChange(of: selectedIndex) { _ in
                // vBRDC327 Phase 5: ordinary D-pad movement is not a catalog-repair event.
                // Only ask the repair lane for work when the newly focused identity actually
                // has no usable artwork. This removes cancel/recreate debounce-task churn from
                // every horizontal focus step without changing a single visible catalog pixel.
                if allowsLazyRefresh, let item = selectedItem {
                    let poster = item.posterURL?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
                    let landscape = item.landscapeURL?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
                    if poster.isEmpty && landscape.isEmpty {
                        store.requestLazyCatalogRowRefresh(row: row, selectedItem: item, reason: "focused item missing artwork")
                    }
                }
                scheduleConnectedArtworkPrewarm(reason: "selection changed")
            }
            .onChange(of: cardIsVisuallyFocused) { isFocused in
                if isFocused {
                    scheduleConnectedArtworkPrewarm(reason: "row focused")
                } else {
                    connectedArtworkPrewarmTask?.cancel()
                    connectedArtworkPrewarmTask = nil
                }
            }
            .onChange(of: connectedMediaPopupArtworkEnabled) { enabled in
                if enabled {
                    scheduleConnectedArtworkPrewarm(reason: "setting enabled")
                } else {
                    connectedArtworkPrewarmTask?.cancel()
                    connectedArtworkPrewarmTask = nil
                }
            }
            .onDisappear {
                connectedArtworkPrewarmTask?.cancel()
                connectedArtworkPrewarmTask = nil
            }
            // vBRDC103: horizontal motion is explicitly driven by persistentRailMotionPhase.
            // Do not attach an implicit animation to selectedIndex; that would animate every
            // descendant data mutation and recreate the old "whole rail is doing work" hitch.
            .animation(coordinatedRailAnimations && !surfaceVisualFocusPinned ? .easeOut(duration: 0.18) : nil, value: cardIsVisuallyFocused)
        }
        .frame(height: railHeight, alignment: .topLeading)
    }

    @MainActor
    private func scheduleConnectedArtworkPrewarm(reason: String) {
        connectedArtworkPrewarmTask?.cancel()
        connectedArtworkPrewarmTask = nil
        guard !playbackBrowseMode,
              connectedMediaPopupArtworkEnabled,
              row.id != "catalog-favorites-quick-panel",
              cardIsVisuallyFocused,
              store.selectedDetail == nil,
              let selectedItem,
              let artworkURL = PremiumArtworkURL.url(selectedItem.landscapeURL ?? selectedItem.posterURL) else { return }

        let settle = UnityCatalogRowMotionStyle.frameBudgetSettleDuration(for: catalogRowScrollingAnimationPreset)
        let expectedItemID = selectedItem.id
        connectedArtworkPrewarmTask = Task { @MainActor in
            // Let row motion finish plus the coordinator's short post-navigation recovery
            // beat. A user who presses Select sooner is still covered by openSelected(),
            // which joins this same in-flight key without a duplicate request.
            let delay = UInt64(max(0.12, min(0.28, settle * 0.45)) * 1_000_000_000)
            try? await Task.sleep(nanoseconds: delay)
            guard await UnityFrameRuntime.shared.waitUntilPermitted(.backgroundPrefetch, maxWait: 1.40) else { return }
            guard !Task.isCancelled,
                  connectedMediaPopupArtworkEnabled,
                  cardIsVisuallyFocused,
                  store.selectedDetail == nil,
                  self.selectedItem?.id == expectedItemID else { return }
            PremiumRemoteImageLoader.prewarm(
                artworkURL,
                maxPixelSize: 2048,
                cacheDomain: .persistent
            )
            connectedArtworkPrewarmTask = nil
            print("[ConnectedPopupArtwork][vBRDC092] idle prewarm item=\(expectedItemID) reason=\(reason)")
        }
    }

    private func handleMove(_ direction: SignalMoveDirection) {
        onNavigationActivity?(direction)
        switch direction {
        case .left:
            commitPersistentHorizontalMove(to: selectedIndex - 1, direction: -1)
        case .right:
            commitPersistentHorizontalMove(to: selectedIndex + 1, direction: 1)
        case .up:
            if let onRowMove { onRowMove(-1) } else { focusedRow.wrappedValue = max(rowIndex - 1, 0) }
        case .down:
            if let onRowMove { onRowMove(1) } else { focusedRow.wrappedValue = min(rowIndex + 1, maxRowIndex ?? rowIndex + 1) }
        @unknown default:
            break
        }
    }

    private func commitPersistentHorizontalMove(to requestedIndex: Int, direction: Int) {
        guard !row.items.isEmpty else { return }
        let nextIndex = min(max(requestedIndex, 0), row.items.count - 1)
        guard nextIndex != selectedIndex else {
            if focusedRow.wrappedValue != rowIndex { focusedRow.wrappedValue = rowIndex }
            return
        }

        persistentRailMotionGeneration &+= 1
        let generation = persistentRailMotionGeneration
        var dataTransaction = Transaction()
        dataTransaction.disablesAnimations = true
        withTransaction(dataTransaction) {
            lastHorizontalMoveDirection = direction
            persistentRailMotionPhase = 0
            selectedIndex = nextIndex
            if focusedRow.wrappedValue != rowIndex { focusedRow.wrappedValue = rowIndex }
        }

        guard coordinatedRailAnimations,
              let motionAnimation = UnityCatalogRowMotionStyle.animation(for: catalogRowScrollingAnimationPreset) else {
            var settleTransaction = Transaction()
            settleTransaction.disablesAnimations = true
            withTransaction(settleTransaction) { persistentRailMotionPhase = 1 }
            return
        }

        // Start the compositor-only arrival on the next run-loop turn, after SwiftUI has
        // rebound the persistent card slots to their new MediaItem inputs.
        DispatchQueue.main.async {
            guard generation == persistentRailMotionGeneration else { return }
            withAnimation(motionAnimation) {
                persistentRailMotionPhase = 1
            }
        }
    }

    private func openSelected() {
        guard let selectedItem else { return }
        if row.id == "sports-remove-channel" && selectedItem.type == "sports-remove" {
            removeSelectedSportsChannel(selectedItem)
            return
        }
        // v1149: Sports uses this shared catalog rail for both informational cards and
        // real live-channel MediaItems. A live channel must never enter the VOD Details
        // Stage/Source Intelligence path. Select and Play/Pause tune the stream directly;
        // only non-live Sports/VOD-style cards continue through Media Information.
        if selectedItem.type.lowercased() == "live" {
            let raw = selectedItem.previewURL?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
            guard !raw.isEmpty, let url = URL(string: raw) else {
                store.status = "\(selectedItem.title) has no playable live stream URL."
                return
            }
            store.startPlayback(
                item: selectedItem,
                url: url,
                alternates: [],
                subtitles: [],
                label: "Sports direct live channel: \(selectedItem.title) • bypass VOD Media Information"
            )
            return
        }
        // v709: remember the exact quick-panel source before opening Details Stage.
        // Back restore uses this to bypass the top menu and land on the same card.
        // vBRDC086: Favorites receives its own restore owner instead of impersonating the
        // shared streaming catalog. That makes it impossible for a Favorite card identity
        // to qualify for Home/Movies/Shows hero-anchor retention.
        let isFavoritesRail = row.id == "catalog-favorites-quick-panel"
        store.quickPanelRestoreSection = isFavoritesRail ? "favoritesCatalog" : "streamingCatalog"
        store.quickPanelRestoreItemID = selectedItem.id
        store.quickPanelRestoreCanonicalKey = store.canonicalCatalogIdentityKey(for: selectedItem)
        store.quickPanelRestoreIdentityItem = selectedItem
        store.quickPanelRestoreRowID = row.id
        store.quickPanelRestoreRowIndex = rowIndex
        store.quickPanelRestoreItemIndex = safeIndex
        store.quickPanelRestoreFocusedCardID = "\(row.id)#\(safeIndex)#\(selectedItem.id)"
        let presentationOrigin: DetailPresentationOrigin? = isFavoritesRail ? .favorites : nil
        // vBRDC092: Connected Popup Artwork uses a 2048 display bucket. Warm that exact
        // bucket before mounting Media Information; if it is still decoding, the popup
        // joins the same in-flight request and immediately reuses the focused card's
        // already-decoded lower bucket as its provisional frame.
        if !playbackBrowseMode, !isFavoritesRail, connectedMediaPopupArtworkEnabled {
            PremiumRemoteImageLoader.prewarm(
                PremiumArtworkURL.url(selectedItem.landscapeURL ?? selectedItem.posterURL),
                maxPixelSize: 2048,
                cacheDomain: .persistent
            )
        }
        store.openDetail(selectedItem, pushCurrent: false, origin: presentationOrigin)
    }

    private func removeSelectedSportsChannel(_ item: MediaItem) {
        if let id = firstInteger(after: "sports-live-", in: item.id) {
            var ids = Set(sportsExcludedChannelIdsRaw.split(separator: ",").compactMap { Int($0.trimmingCharacters(in: .whitespacesAndNewlines)) })
            ids.insert(id)
            sportsExcludedChannelIdsRaw = ids.sorted().map(String.init).joined(separator: ",")
        }
        let normalized = item.title.trimmingCharacters(in: .whitespacesAndNewlines).lowercased().replacingOccurrences(of: "|", with: " ")
        if !normalized.isEmpty {
            var names = Set(sportsExcludedChannelNamesRaw.split(separator: "|").map { String($0).trimmingCharacters(in: .whitespacesAndNewlines) }.filter { !$0.isEmpty })
            names.insert(normalized)
            sportsExcludedChannelNamesRaw = names.sorted().joined(separator: "|")
        }
        store.status = "Removed \(item.title) from Sports. Live TV is unchanged."
        selectedIndex = max(0, min(selectedIndex, row.items.count - 1))
    }

    private func firstInteger(after marker: String, in value: String) -> Int? {
        guard let range = value.range(of: marker) else { return nil }
        let rest = value[range.upperBound...]
        let digits = rest.prefix { $0.isNumber }
        return Int(String(digits))
    }
}

struct StremioAddonSourceBadge: View {
    let item: MediaItem
    var compact: Bool = false

    private var label: String {
        let raw = (item.addonName ?? item.catalog).trimmingCharacters(in: .whitespacesAndNewlines)
        return raw.isEmpty ? "Stremio" : raw
    }

    private var initials: String {
        let parts = label.split(separator: " ").prefix(2)
        let text = parts.compactMap { $0.first }.map(String.init).joined().uppercased()
        return text.isEmpty ? "S" : text
    }

    var body: some View {
        HStack(spacing: compact ? 6 : 8) {
            ZStack {
                Circle().fill(Color.black.opacity(0.36))
                if let icon = item.addonIconURL, !icon.isEmpty {
                    RemoteImageFit(url: icon, mode: .fit)
                        .clipShape(Circle())
                } else {
                    Text(initials)
                        .font(.system(size: compact ? 10 : 12, weight: .black, design: .rounded))
                        .foregroundStyle(.white.opacity(0.92))
                }
            }
            .frame(width: compact ? 22 : 28, height: compact ? 22 : 28)

            if !compact {
                Text(label)
                    .font(.system(size: 13, weight: .black, design: .rounded))
                    .foregroundStyle(.white.opacity(0.90))
                    .lineLimit(1)
                    .frame(maxWidth: 145, alignment: .leading)
            }
        }
        .padding(.horizontal, compact ? 7 : 10)
        .padding(.vertical, compact ? 5 : 7)
        .background(Capsule().fill(Color.black.opacity(0.58)))
        .overlay(Capsule().stroke(Color.white.opacity(0.18), lineWidth: 1))
        .shadow(color: .black.opacity(0.40), radius: 8, y: 3)
        .allowsHitTesting(false)
    }
}

private struct SearchMenuIconFramePreferenceKey: PreferenceKey {
    static var defaultValue: CGRect = .zero

    static func reduce(value: inout CGRect, nextValue: () -> CGRect) {
        let candidate = nextValue()
        if candidate.width > 20, candidate.height > 20 { value = candidate }
    }
}

private struct FocusedCatalogCardFramePreferenceKey: PreferenceKey {
    static var defaultValue: CGRect = .zero

    static func reduce(value: inout CGRect, nextValue: () -> CGRect) {
        let candidate = nextValue()
        if candidate.width > 40, candidate.height > 40 { value = candidate }
    }
}

struct FixedSlotFocusedCatalogCard: View, Equatable {
    // vBRDC327: Equatable poster leaf receives the one detail-presentation bit it needs;
    // it no longer subscribes to every CatalogStore publication.
    // vBRDC327: read UNITY policy synchronously; do not subscribe every visible poster
    // to process-wide navigation revisions. Focus props already invalidate the two cards
    // whose visual state actually changes.
    private let unityAnimations = UnityAnimationCoordinator.shared
    let item: MediaItem
    let focused: Bool
    let detailPresentationActive: Bool

    // vBRDC329: only skip an update if *all* externally supplied render and
    // preview inputs agree. The old equality ignored previews, layout and
    // playback publication, leaving a persistent slot with stale children.
    // The callback is owned by previewKey/previewURL (its playback identity).
    static func == (lhs: Self, rhs: Self) -> Bool {
        lhs.item.id == rhs.item.id &&
        lhs.item.posterURL == rhs.item.posterURL &&
        lhs.item.landscapeURL == rhs.item.landscapeURL &&
        lhs.item.logoURL == rhs.item.logoURL &&
        lhs.item.title == rhs.item.title &&
        lhs.item.catalog == rhs.item.catalog &&
        lhs.focused == rhs.focused &&
        lhs.detailPresentationActive == rhs.detailPresentationActive &&
        lhs.animateFocusArrival == rhs.animateFocusArrival &&
        lhs.animateFocusGeometry == rhs.animateFocusGeometry &&
        lhs.animateSlowPulse == rhs.animateSlowPulse &&
        lhs.cardWidth == rhs.cardWidth &&
        lhs.cardHeight == rhs.cardHeight &&
        lhs.rowID == rhs.rowID &&
        lhs.previewURL == rhs.previewURL &&
        lhs.previewKey == rhs.previewKey &&
        lhs.publishDuringPlayback == rhs.publishDuringPlayback
    }
    // v1092 Phase 0 correction: Search keeps the focused landscape card in its
    // sideways/perspective presentation while the card springs downward on arrival.
    // Catalog rails keep one fixed focused slot, so replay only that vertical arrival
    // motion whenever a new item enters the slot; never reset the card to straight.
    var animateFocusArrival: Bool = true
    // vBRDC109: cross-surface open/close applies final focused geometry while hidden.
    // Do not run the card's own 0.36s focus spring during that compositor transaction.
    var animateFocusGeometry: Bool = true
    var animateSlowPulse: Bool = true
    var cardWidth: CGFloat = 338
    var cardHeight: CGFloat = 190
    var rowID: String = ""
    var previewURL: URL? = nil
    var previewKey: String? = nil
    var onPreviewFinished: ((String) -> Void)? = nil
    var publishDuringPlayback: Bool = false
    @AppStorage("homeGridThemePreset") private var homeGridThemePreset: String = "Classic Glow"
    @State private var inlinePreviewIsPlaying: Bool = false
    @State private var focusArrivalVerticalOffset: CGFloat = 0
    @State private var focusArrivalGeneration: UInt64 = 0
    // vBRDC092: the old breathing scale pulse is replaced by a compositor-only glow
    // pulse. It never changes card geometry, scale, connector measurements or row layout.
    @State private var slowGlowBright: Bool = false

    // vBRDC333: focus is compositor/chrome state only. The measured card slot never
    // changes dimensions when tvOS transfers focus or when artwork publishes.
    private var currentWidth: CGFloat { cardWidth }
    private var currentHeight: CGFloat { cardHeight }
    private var coordinatedPulseEnabled: Bool { animateSlowPulse && unityAnimations.allows(.catalogPulse) }
    var body: some View {
        ZStack(alignment: .bottomLeading) {
            ZStack {
                Color.black.opacity(0.38)
                RemoteImageFit(
                    url: item.landscapeURL ?? item.posterURL,
                    mode: .fill,
                    maxPixelSize: 1024,
                    preservePreviousOnURLChange: true,
                    publishDuringSurfaceHandoff: true,
                    publishDuringPlayback: publishDuringPlayback,
                    forceVisiblePlaybackPublication: publishDuringPlayback
                )
                    // vBRDC125: the fixed focused slot survives horizontal and vertical row
                    // navigation, but its decoded pixels must not survive a media-identity
                    // change. Key only the image owner (not the card/compositor structure) so
                    // same-title URL upgrades still retain their frame while a different title
                    // gets a fresh loader and can never show the previous focused artwork.
                    .id("catalog-focused-artwork-\(rowID)-\(item.id)")
                    .frame(width: currentWidth, height: currentHeight)
                // vBRDC107: an active preview belongs to this media identity, not to the
                // current UNITY ambient-motion permission. Row motion can still delay a
                // preview before it starts; once active, opening Media Profile and moving
                // among its controls must not hide/dismantle it.
                if focused, let previewURL, let previewKey {
                    FocusedCardPreviewSurface(
                        url: previewURL,
                        onPlaybackStarted: {
                            inlinePreviewIsPlaying = true
                        },
                        onPlaybackStopped: {
                            inlinePreviewIsPlaying = false
                        },
                        onFinished: {
                            inlinePreviewIsPlaying = false
                            onPreviewFinished?(previewKey)
                        }
                    )
                    .id("focused-card-inline-preview-\(previewKey)-\(previewURL.absoluteString)")
                    .frame(width: currentWidth, height: currentHeight)
                    // v1074: when the one-shot preview naturally ends, fade back to artwork
                    // but keep the paused, audio-deselected AVPlayerItem mounted until focus
                    // actually changes. This avoids an AVFoundation teardown in the middle of
                    // an independently playing built-in trailer.
                    .opacity(inlinePreviewIsPlaying ? 1.0 : 0.0)
                    .animation(.easeInOut(duration: 0.22), value: inlinePreviewIsPlaying)
                    .allowsHitTesting(false)
                    .transition(.opacity.animation(.easeInOut(duration: 0.22)))
                }
                HomeGridThemeOverlay(theme: homeGridThemePreset, focused: focused)
            }
            .frame(width: currentWidth, height: currentHeight)
            .clipShape(RoundedRectangle(cornerRadius: focused ? 28 : 22, style: .continuous))

            LinearGradient(colors: [.clear, .black.opacity(0.84)], startPoint: .center, endPoint: .bottom)
                .clipShape(RoundedRectangle(cornerRadius: focused ? 28 : 22, style: .continuous))

            UnityCatalogCardChrome(item: item, focused: focused, cornerRadius: focused ? 28 : 22)

            // vBRDC067: focused-card preview video is self-explanatory. Keep the preview
            // visually clean and remove the old PREVIEW popcorn badge/status ornament.

            if !inlinePreviewIsPlaying {
                VStack(alignment: .leading, spacing: 7) {
                    CardThemedLogo(
                        item: item,
                        focused: focused,
                        publishDuringPlayback: publishDuringPlayback
                    )
                    .frame(width: focused ? 278 : 230, height: focused ? 42 : 34, alignment: .leading)
                }
                .padding(18)
                .transition(.opacity.animation(.easeInOut(duration: 0.16)))
            }
        }
        .frame(width: currentWidth, height: currentHeight)
        .onAppear {
            replaySearchStyleFocusArrival()
            updateSlowFocusedPulse(isFocused: focused)
        }
        .onChange(of: item.id) { _ in
            // Horizontal row motion already owns the selected-item transition. Starting a
            // second vertical arrival after the new item lands is the universal end-jump
            // that affected every row-motion preset. Keep the fixed slot at rest.
            var transaction = Transaction()
            transaction.disablesAnimations = true
            withTransaction(transaction) { focusArrivalVerticalOffset = 0 }
            updateSlowFocusedPulse(isFocused: focused)
        }
        .onChange(of: previewURL?.absoluteString) { newValue in
            if newValue == nil { inlinePreviewIsPlaying = false }
        }
        .onChange(of: focused) { isFocused in
            if !isFocused {
                inlinePreviewIsPlaying = false
                focusArrivalGeneration &+= 1
                focusArrivalVerticalOffset = 0
            } else {
                replaySearchStyleFocusArrival()
            }
            updateSlowFocusedPulse(isFocused: isFocused)
        }
        .onChange(of: animateSlowPulse) { enabled in
            updateSlowFocusedPulse(isFocused: focused && enabled && unityAnimations.allows(.catalogPulse))
        }
        .onChange(of: coordinatedPulseEnabled) { allowed in
            updateSlowFocusedPulse(isFocused: focused && allowed)
        }
        .overlay {
            ZStack {
                RoundedRectangle(cornerRadius: focused ? 28 : 22, style: .continuous)
                    .stroke(HomeGridThemeStyle.accent(for: homeGridThemePreset).opacity(focused ? 0.18 : 0.0), lineWidth: focused ? 5 : 0)
                    .blur(radius: focused ? 5 : 0)

                if focused && coordinatedPulseEnabled {
                    // vBRDC095: make the pulse unmistakably a glow rather than another
                    // focus border. Two compositor-only halos breathe together on the same
                    // slow 5.7s cycle; neither changes frame, scale, offset or row geometry.
                    RoundedRectangle(cornerRadius: 30, style: .continuous)
                        .stroke(HomeGridThemeStyle.accent(for: homeGridThemePreset).opacity(0.74), lineWidth: 10)
                        .blur(radius: 22)
                        .opacity(slowGlowBright ? 0.92 : 0.14)

                    RoundedRectangle(cornerRadius: 28, style: .continuous)
                        .stroke(HomeGridThemeStyle.accent(for: homeGridThemePreset).opacity(0.88), lineWidth: 4)
                        .blur(radius: 8)
                        .opacity(slowGlowBright ? 1.0 : 0.24)
                }
            }
            .allowsHitTesting(false)
        }
        // Keep the original focused resting position and sideways presentation. The glow
        // pulse is opacity-only and therefore never moves/scales this measured slot.
        .offset(y: 0)
        .shadow(color: HomeGridThemeStyle.accent(for: homeGridThemePreset).opacity(focused ? HomeGridThemeStyle.focusGlowOpacity(for: homeGridThemePreset) : 0.02), radius: focused ? min(18, HomeGridThemeStyle.focusGlowRadius(for: homeGridThemePreset)) : 6, y: focused ? 4 : 1)
        .shadow(color: .black.opacity(focused ? HomeGridThemeStyle.blackShadowOpacity(for: homeGridThemePreset) : 0.46), radius: focused ? 22 : 14, y: focused ? 12 : 7)
        .modifier(FocusedSidewaysCardEffect(isFocused: focused))
        .animation(nil, value: focused)
    }

    private func updateSlowFocusedPulse(isFocused: Bool) {
        var reset = Transaction()
        reset.disablesAnimations = true
        withTransaction(reset) {
            slowGlowBright = false
        }
        guard isFocused, coordinatedPulseEnabled else { return }
        DispatchQueue.main.async {
            guard focused else { return }
            withAnimation(.easeInOut(duration: 2.85).repeatForever(autoreverses: true)) {
                slowGlowBright = true
            }
        }
    }

    private func replaySearchStyleFocusArrival() {
        // vBRDC333: catalog focus arrival must never alter measured vertical geometry.
        focusArrivalGeneration &+= 1
        var transaction = Transaction()
        transaction.disablesAnimations = true
        withTransaction(transaction) { focusArrivalVerticalOffset = 0 }
    }

    private func startSearchStyleFocusArrivalSpring(generation: UInt64) {
        var transaction = Transaction()
        transaction.disablesAnimations = true
        withTransaction(transaction) { focusArrivalVerticalOffset = 0 }
    }
}


struct FixedSlotPreviewCatalogCard: View {
    let item: MediaItem
    let depth: Int
    // v714: keep the parameter for caller compatibility, but restore the v702 rail geometry.
    // The newer max-height math made the trailing posters too tiny/ugly compared with the
    // working "In The Grey" row.  v702 used width-first poster math so the row fans out
    // across the screen while the focused card keeps the correct 390x220 landscape slot.
    var maxCardHeight: CGFloat = 190
    var rowID: String = ""
    var fixedCardWidth: CGFloat? = nil
    var publishDuringPlayback: Bool = false
    @AppStorage("homeGridThemePreset") private var homeGridThemePreset: String = "Classic Glow"

    private var usesFixedGeometry: Bool { fixedCardWidth != nil }
    private var cardWidth: CGFloat {
        if let fixedCardWidth { return max(96, fixedCardWidth) }
        return max(64, 116 - CGFloat(depth) * 4.4)
    }
    private var cardHeight: CGFloat { cardWidth * 1.48 }
    private var opacity: Double {
        usesFixedGeometry ? max(0.70, 0.94 - Double(depth) * 0.028) : max(0.36, 0.90 - Double(depth) * 0.045)
    }
    private var cardCornerRadius: CGFloat {
        usesFixedGeometry ? 18 : max(9, 16 - CGFloat(depth) * 0.45)
    }
    var body: some View {
        VStack(alignment: .leading, spacing: 6) {
            ZStack(alignment: .bottomLeading) {
                Color.black.opacity(0.34)
                RemoteImageFit(
                    url: item.posterURL,
                    mode: .fill,
                    maxPixelSize: 384,
                    preservePreviousOnURLChange: true,
                    publishDuringSurfaceHandoff: depth < 3,
                    publishDuringPlayback: publishDuringPlayback,
                    forceVisiblePlaybackPublication: publishDuringPlayback
                )
                    // vBRDC125: depth slots stay structurally persistent for cheap motion,
                    // but each media identity owns its own image loader. This removes the
                    // old slot-retention behavior where several advancing cards could briefly
                    // display the posters they had on the previous D-pad frame (duplicate art).
                    .id("catalog-preview-artwork-\(rowID)-\(depth)-\(item.id)")
                    .frame(width: cardWidth, height: cardHeight)
                if depth < 4 {
                    HomeGridThemeOverlay(theme: homeGridThemePreset, focused: depth == 0)
                        .opacity(depth == 0 ? 0.92 : max(0.16, 0.42 - Double(depth) * 0.07))
                }
                UnityCatalogCardChrome(
                    item: item,
                    focused: depth == 0,
                    cornerRadius: cardCornerRadius,
                    compact: true
                )
                .opacity(depth < 5 ? max(0.24, 0.78 - Double(depth) * 0.11) : 0.0)
            }
            .frame(width: cardWidth, height: cardHeight)
            .clipShape(RoundedRectangle(cornerRadius: cardCornerRadius, style: .continuous))
            EmptyView()
        }
        .opacity(opacity)
        // v1085: only near cards receive the expensive accent bloom. Deep cards
        // retain a light grounding shadow without dozens of large live blur layers.
        .shadow(
            color: HomeGridThemeStyle.accent(for: homeGridThemePreset).opacity(
                depth == 0 ? HomeGridThemeStyle.focusGlowOpacity(for: homeGridThemePreset) * 0.55 : (depth == 1 ? 0.012 : 0.0)
            ),
            radius: depth == 0 ? 18 : (depth == 1 ? 5 : 0),
            y: depth == 0 ? 5 : 2
        )
        .shadow(color: .black.opacity(depth < 4 ? 0.46 : 0.28), radius: depth < 4 ? 10 : 5, y: depth < 4 ? 5 : 3)
        .brightness(depth == 0 ? 0.012 : -0.016)
        .saturation(depth == 0 ? 1.02 : 0.92)
    }
}




struct MovieInfoComicBubbleShape: Shape {
    func path(in rect: CGRect) -> Path {
        // v596: restore a professional premium information-card silhouette.
        // The movie/show info panel is no longer a cartoon speech bubble; the
        // selected poster connection is handled by a separate soft glass bridge.
        let radius = min(rect.height * 0.055, 34)
        return RoundedRectangle(cornerRadius: radius, style: .continuous).path(in: rect)
    }
}

struct PosterGlassConnectorShape: Shape {
    func path(in rect: CGRect) -> Path {
        var path = Path()
        // v596: subtle angled bridge from the focused bottom poster/card into the popup.
        // This gives the effect that the info panel grows out of the selected card
        // without using a large comic tail or halftone texture.
        path.move(to: CGPoint(x: rect.minX + rect.width * 0.05, y: rect.maxY))
        path.addQuadCurve(
            to: CGPoint(x: rect.maxX * 0.96, y: rect.minY + rect.height * 0.16),
            control: CGPoint(x: rect.minX + rect.width * 0.44, y: rect.maxY - rect.height * 0.04)
        )
        path.addLine(to: CGPoint(x: rect.maxX, y: rect.minY + rect.height * 0.36))
        path.addQuadCurve(
            to: CGPoint(x: rect.minX + rect.width * 0.20, y: rect.maxY),
            control: CGPoint(x: rect.minX + rect.width * 0.47, y: rect.maxY - rect.height * 0.18)
        )
        path.closeSubpath()
        return path
    }
}

struct MediaInfoPopup: View {
    @EnvironmentObject var store: CatalogStore
    // vBRDC327: Media Information owns its own focus state. Subscribing the whole popup
    // to UNITY's navigation start/settle/recovery revisions rebuilt Play/Trailer/Find Links
    // while the user was moving between those same controls.
    private let unityAnimations = UnityAnimationCoordinator.shared
    let item: MediaItem
    let sourceCardFrame: CGRect
    let connectorOrigin: DetailPresentationOrigin
    @Binding var pendingEpisodeAlertOpenIntent: NewEpisodeAlertHit?
    // vBRDC184: Media Information can be intentionally opened over an active player from
    // the shared playback catalog. The default remains false for every existing surface.
    var playbackBrowseMode: Bool = false

    private var playbackBrowseWorkAllowed: Bool {
        playbackBrowseMode || !VODExclusivePlaybackGate.isActive
    }
    @FocusState private var focused: Bool
    @State private var focus: DetailPage.DetailNode = .play
    @State private var trailerPopup = false
    @State private var trailerURL: URL? = nil
    @State private var trailerResolving = false
    @State private var trailerAuxiliarySuppressionID: UUID? = nil
    @State private var isFindingLinks = false
    @State private var isLoadingEpisodes = false
    @State private var episodeItems: [MediaItem] = []
    @State private var episodesVisible = false
    @State private var episodeWindowStart: Int = 0
    @State private var selectedSeasonNumber: Int = 1
    @State private var seasonDropdownOpen = false
    @State private var linkWindowStart: Int = 0
    @State private var sourcePanelVisible = false
    @State private var sourcePanelLastFocusedIndex: Int = 0
    @StateObject private var mediaInfoAsyncRuntime = MediaInfoAsyncTaskRuntime()
    private var sourceResolveTask: Task<Void, Never>? {
            get { mediaInfoAsyncRuntime.sourceResolveTask }
            nonmutating set { mediaInfoAsyncRuntime.sourceResolveTask = newValue }
        }
    @State private var sourceOpeningProvider: String? = nil
    // v1069: Source Intelligence now lives inside the lower half of the media popup.
    // Selecting a result opens only a compact centered confirmation card; the source
    // resolver, ranking, provider filtering, five-link paging, and playback handoff stay unchanged.
    @State private var sourceConfirmationIndex: Int? = nil
    // v567: when a season episode is selected, Source Intelligence searches that exact
    // episode id instead of falling back to the parent season/show id.
    @State private var sourceSearchItem: MediaItem? = nil
    @State private var demoEpisodeAlertVisible: Bool = false
    @State private var demoEpisodeAlertFocus: Int = 0
    @State private var demoEpisodeAlertItem: MediaItem? = nil
    @State private var relatedWindowStart: Int = 0
    @State private var lastActionAt: TimeInterval = 0
    // vBRDC197: Debrid Channels Favorites and Trakt Watchlist are intentionally
    // independent visible actions. The Trakt state is mirrored locally only after
    // the connected account confirms the mutation.
    @State private var traktWatchlisted: Bool = false
    @State private var traktWatchlistBusy: Bool = false
    @AppStorage("popupFontPreset") private var popupFontPreset: String = "SF Rounded"
    @AppStorage("connectedMediaPopupArtworkEnabled") private var connectedMediaPopupArtworkEnabled: Bool = false
    @AppStorage("mediaInfoConnectorLineEnabledV1") private var mediaInfoConnectorLineEnabled: Bool = true
    @AppStorage("advisoryDisplayEnabled") private var advisoryDisplayEnabled: Bool = true
    @AppStorage("tmdbApiKey") private var popupTMDBApiKey: String = ""
    @AppStorage("externalMoviesInfuseDefault") private var popupExternalMoviesInfuseDefault: Bool = false
    @AppStorage("externalMoviesVLCDefault") private var popupExternalMoviesVLCDefault: Bool = false
    @AppStorage("externalMoviesSenPlayerDefault") private var popupExternalMoviesSenPlayerDefault: Bool = false
    @AppStorage("externalShowsInfuseDefault") private var popupExternalShowsInfuseDefault: Bool = false
    @AppStorage("externalShowsVLCDefault") private var popupExternalShowsVLCDefault: Bool = false
    @AppStorage("externalShowsSenPlayerDefault") private var popupExternalShowsSenPlayerDefault: Bool = false
    @AppStorage("favoriteMediaIds") private var favoriteMediaIdsRaw: String = ""
    @AppStorage("followedShowIds") private var followedShowIdsRaw: String = ""
    @AppStorage("vBRDC019SeriesEpisodeHintShown") private var seriesEpisodeHintShown: Bool = false
    @State private var seriesEpisodeHintVisible: Bool = false
    private var seriesEpisodeHintTask: Task<Void, Never>? {
            get { mediaInfoAsyncRuntime.seriesEpisodeHintTask }
            nonmutating set { mediaInfoAsyncRuntime.seriesEpisodeHintTask = newValue }
        }
    @State private var popupHeaderDetails: PopupHeaderDetails? = nil
    @State private var rottenTomatoesScoreText: String = "N/A"
    private var rottenTomatoesTask: Task<Void, Never>? {
            get { mediaInfoAsyncRuntime.rottenTomatoesTask }
            nonmutating set { mediaInfoAsyncRuntime.rottenTomatoesTask = newValue }
        }
    private var episodePreloadTask: Task<Void, Never>? {
            get { mediaInfoAsyncRuntime.episodePreloadTask }
            nonmutating set { mediaInfoAsyncRuntime.episodePreloadTask = newValue }
        }
    private var popupHeaderDetailsTask: Task<Void, Never>? {
            get { mediaInfoAsyncRuntime.popupHeaderDetailsTask }
            nonmutating set { mediaInfoAsyncRuntime.popupHeaderDetailsTask = newValue }
        }
    private var detailActionTask: Task<Void, Never>? {
            get { mediaInfoAsyncRuntime.detailActionTask }
            nonmutating set { mediaInfoAsyncRuntime.detailActionTask = newValue }
        }
    // v617: prevent Details Stage from showing a naked full-bright artwork frame before
    // the cinematic dim/gradient stack is ready. The backdrop fades in only after the
    // stage is mounted behind a black pre-dim layer.
    @State private var stageBackdropVisible: Bool = false
    // vBRDC108: Media Profile presentation is one compositor transaction. The connector
    // remains decorative, but it no longer serializes the panel presentation behind its draw.
    // Close uses a matched 0.20s panel/connector handoff so no animation is destroyed halfway.
    @State private var connectorLineVisible: Bool = false
    private var connectorLineFadeTask: Task<Void, Never>? {
            get { mediaInfoAsyncRuntime.connectorLineFadeTask }
            nonmutating set { mediaInfoAsyncRuntime.connectorLineFadeTask = newValue }
        }
    private let connectorTravelDuration: Double = 0.20
    private let connectorRetractionDuration: Double = 1.18
    private let connectorCloseRetractionDuration: Double = 0.20
    private let detailStageTransitionDuration: Double = 0.20
    private let connectorTravelNanoseconds: UInt64 = 200_000_000
    private let connectorHoldNanoseconds: UInt64 = 7_000_000_000
    // vBRDC092: popup identity is already revision+media exact, so the old delayed
    // one-frame artwork guard is removed. It guaranteed a transparent/black frame before
    // Connected Popup Artwork appeared. Back owns a short reverse handoff task instead.
    private var detailDismissTask: Task<Void, Never>? {
            get { mediaInfoAsyncRuntime.detailDismissTask }
            nonmutating set { mediaInfoAsyncRuntime.detailDismissTask = newValue }
        }
    @State private var isDismissingDetail: Bool = false

    private let sourceIntelligencePageSize = 5

    private func synchronizeUnitySourceAnimationActivity(reason: String) {
        let opening = sourceOpeningProvider != nil || (isFindingLinks && !sourcePanelVisible)
        let searching = isFindingLinks && sourcePanelVisible && !opening
        unityAnimations.setSourceIntelligence(searching: searching, opening: opening)
        print("[UNITY Animation][Source Intelligence] sync reason=\(reason) searching=\(searching) opening=\(opening)")
    }

    private var detailArtworkReady: Bool { true }

    private var connectedPopupArtworkURL: String? {
        [item.landscapeURL, item.posterURL]
            .compactMap { value -> String? in
                guard let value else { return nil }
                let clean = value.trimmingCharacters(in: .whitespacesAndNewlines)
                return clean.isEmpty ? nil : clean
            }
            .first
    }

    // vBRDC087 single-artwork-owner invariant: Search already owns its cinematic
    // full-screen selected-title backdrop, and Favorites keeps its selected-title
    // backdrop mounted behind the local popup. The optional Connected Popup Artwork
    // layer is therefore catalog-only. This prevents the same title artwork from being
    // decoded/composited a second time inside Search/Favorites Media Information.
    private var connectedPopupArtworkLayerAllowed: Bool {
        connectedMediaPopupArtworkEnabled && connectorOrigin == .catalog
    }

    // v1051: Keep the optional artwork layer geometrically identical to the popup.
    // A fixed canvas plus one continuous mask prevents aspect-ratio negotiation in a
    // SwiftUI background from stretching, overflowing, or leaving the image outside
    // the connected panel during its scale/offset animation.
    private let connectedPopupCanvasSize = CGSize(width: 860, height: 858)
    private let connectedPopupCornerRadius: CGFloat = 34

    private var relatedItems: [MediaItem] {
        let allRows = store.rows
        let all = allRows.flatMap { $0.items }
        let sameGenre = all.filter { $0.id != item.id && (!$0.genres.isEmpty && !Set($0.genres).isDisjoint(with: Set(item.genres))) }
        let fallback = all.filter { $0.id != item.id }
        return Array((sameGenre.isEmpty ? fallback : sameGenre).prefix(14))
    }

    private var isSeriesItem: Bool {
        let lower = item.type.lowercased()
        return lower.contains("series") || lower.contains("show")
    }

    private var seasonNumbers: [Int] {
        let values = Set(episodeItems.compactMap { s in let n = s.seasonNumber ?? 1; return n > 0 ? n : nil })
        return values.isEmpty ? [selectedSeasonNumber] : values.sorted()
    }

    private var selectedSeasonIndex: Int {
        seasonNumbers.firstIndex(of: selectedSeasonNumber) ?? 0
    }

    private var connectedSeasonScrollTargetIndex: Int {
        if case .season(let index) = focus { return index }
        return selectedSeasonIndex
    }

    private var filteredEpisodeItems: [MediaItem] {
        episodeItems.filter {
            let season = $0.seasonNumber ?? 1
            return season > 0 && season == selectedSeasonNumber
        }
    }

    private let connectedPopupEpisodePageSize = 3

    private var visibleEpisodeItems: [MediaItem] {
        // v1049: the connected popup now presents three episode cards. Keep the
        // navigation window identical to the visible geometry so every focused
        // episode remains on-screen while moving through the complete season.
        Array(filteredEpisodeItems.dropFirst(episodeWindowStart).prefix(connectedPopupEpisodePageSize))
    }

    private var visibleLinks: [StreamLink] {
        // v523: keep source chips contained inside popup bounds; use arrows for paging.
        Array(activeSourceLinks.dropFirst(linkWindowStart).prefix(sourceIntelligencePageSize))
    }

    private var activeSourceLinks: [StreamLink] {
        let selection = store.selectedSourceProvider.trimmingCharacters(in: .whitespacesAndNewlines)
        let filtered: [StreamLink]
        if selection.isEmpty || selection == "All Providers" {
            filtered = store.streamLinks
        } else {
            filtered = store.streamLinks.filter { sourceProviderMatches(selection: selection, link: $0) }
        }
        return PerTitlePlaybackMemoryManager.shared.prioritizedLinks(for: sourceSearchItem ?? item, links: filtered)
    }

    private var sourceProviderOptions: [String] {
        var options = ["All Providers"]
        let groupInS = NuvioPluginPreferences.groupProvidersByRepository()

        for link in store.streamLinks {
            let label: String
            if groupInS, link.providerService?.caseInsensitiveCompare("In-S") == .orderedSame {
                label = NuvioPluginPreferences.repositoryName(forProviderName: link.source) ?? link.providerDisplay
            } else {
                label = link.providerDisplay
            }
            let clean = label.trimmingCharacters(in: .whitespacesAndNewlines)
            let isInS = link.providerService?.caseInsensitiveCompare("In-S") == .orderedSame
            if !clean.isEmpty, (isKnownSourceProvider(clean) || isInS), !options.contains(where: { $0.caseInsensitiveCompare(clean) == .orderedSame }) {
                options.append(clean)
            }
        }

        for status in store.sourceProviderStatuses {
            var label = status.provider.trimmingCharacters(in: .whitespacesAndNewlines)
            if groupInS, let repository = NuvioPluginPreferences.repositoryName(forProviderName: label) { label = repository }
            let isInS = NuvioPluginPreferences.repositoryName(forProviderName: status.provider) != nil
            if !label.isEmpty, (isKnownSourceProvider(label) || isInS), !options.contains(where: { $0.caseInsensitiveCompare(label) == .orderedSame }) {
                options.append(label)
            }
        }
        return options
    }

    private var focusedSourceProviderIndex: Int? {
        if case .sourceProvider(let index) = focus { return index }
        return nil
    }

    private func sourceProviderCanonical(_ value: String) -> String {
        value.lowercased()
            .replacingOccurrences(of: " ", with: "")
            .replacingOccurrences(of: "-", with: "")
            .replacingOccurrences(of: "_", with: "")
    }

    private func isKnownSourceProvider(_ value: String) -> Bool {
        let canonical = sourceProviderCanonical(value)
        if ["mediafusion", "torrentio", "comet", "debrido", "debridio", "torbox", "realdebrid", "alldebrid", "premiumize", "debridlink", "easydebrid", "debrider", "febbox", "showbox"].contains(where: { canonical.contains($0) }) {
            return true
        }
        if NuvioPluginPreferences.enabledRepositoryNames().contains(where: { sourceProviderCanonical($0) == canonical }) { return true }
        return NuvioPluginPreferences.enabledProviderNames().contains { sourceProviderCanonical($0) == canonical || canonical.contains(sourceProviderCanonical($0)) }
    }

    private func sourceProviderMatches(selection: String, link: StreamLink) -> Bool {
        let cleanSelection = selection.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !cleanSelection.isEmpty, cleanSelection != "All Providers" else { return true }
        if NuvioPluginPreferences.groupProvidersByRepository(),
           link.providerService?.caseInsensitiveCompare("In-S") == .orderedSame,
           NuvioPluginPreferences.providerBelongsToRepository(providerName: link.source, repositoryName: cleanSelection) {
            return true
        }
        let provider = link.providerDisplay
        let providerKey = sourceProviderCanonical(provider)
        let selectionKey = sourceProviderCanonical(cleanSelection)
        if cleanSelection == "Other detected providers" { return !isKnownSourceProvider(provider) }
        return providerKey.contains(selectionKey)
    }

    private func selectSourceProvider(_ provider: String) {
        // v764 stability pass: provider chips are a filter over the links already returned by
        // the active Source Intelligence scan. Do not fire a second provider search here; it
        // clears the good results, makes MediaFusion look broken, and can re-enter shared state
        // while the overlay is focused.
        let clean = provider.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? "All Providers" : provider
        store.selectedSourceProvider = clean
        PerTitlePlaybackMemoryManager.shared.rememberProvider(clean, for: sourceSearchItem ?? item)
        linkWindowStart = 0
        sourcePanelLastFocusedIndex = 0
        sourcePanelVisible = true
        isFindingLinks = false
        let providerIndex = sourceProviderOptions.firstIndex { $0.caseInsensitiveCompare(clean) == .orderedSame } ?? 0
        focus = activeSourceLinks.isEmpty ? .sourceProvider(providerIndex) : .stream(0)
    }

    // vBRDC084: Search keeps the visible detail id stable while resolver hydration
    // can add TMDB/IMDb/TVDB identities a moment later. Production metadata must react
    // to that identity improvement even though `item.id` intentionally does not change.
    private var popupProductionHydrationIdentity: String {
        [item.tmdbId ?? "", item.imdbId ?? "", item.tvdbId ?? ""]
            .joined(separator: "|")
            .lowercased()
    }

    private var visibleRelatedItems: [MediaItem] {
        // v524: bottom poster rail removed from the popup. Keep a small, stable sample
        // only for Media DNA counts/cards so the popup stays clean and contained.
        Array(relatedItems.prefix(11))
    }

    private var visibleMovieFranchiseItems: [MediaItem] {
        // v616: Explore the Franchise is collection-only. Do not populate it
        // from same-genre/related fallback movies.
        Array(item.franchiseItems.dropFirst(relatedWindowStart).prefix(5))
    }

    private var focusedFranchiseIndex: Int? {
        if case .related(let index) = focus { return index }
        return nil
    }

    var body: some View {
        ZStack(alignment: .top) {
            popupDimLayer
            // v1088: only Home/Movies/Shows catalog details draw the focused-card
            // connector. Search and Favorites open directly; Favorites stays centered
            // over its existing poster background and never draws the line.
            if connectorOrigin == .catalog && mediaInfoConnectorLineEnabled && !playbackBrowseMode {
                FocusedCardToMediaPopupConnector(
                    sourceFrame: sourceCardFrame,
                    visible: connectorLineVisible,
                    animationDuration: connectorTravelDuration,
                    retractionDuration: isDismissingDetail ? connectorCloseRetractionDuration : connectorRetractionDuration
                )
                .zIndex(1)
            }
            popupPanelLayer
                .zIndex(2)
            sourcePanelLayer
            demoEpisodeAlertLayer
            popupTrailerLayer
        }
        .signalVisionFocusSection()
        .focusable(true)
        .focused($focused)
        .onAppear {
            synchronizeUnitySourceAnimationActivity(reason: "detail appear")
            // vBRDC157: Search/Favorites details can hydrate richer logo/artwork after the
            // favorite identity was first saved. Refresh the compact favorite snapshot as
            // soon as Media Information mounts so that richer presentation survives later
            // Favorites visits and the next profile backup.
            persistFavoriteSnapshotIfNeeded(item)
            refreshTraktWatchlistState()
            focused = true
            focus = .play
            trailerPopup = false
            trailerURL = nil
            trailerResolving = false
            sourcePanelVisible = false
            sourceConfirmationIndex = nil
            sourceSearchItem = nil
            demoEpisodeAlertVisible = false
            demoEpisodeAlertFocus = 0
            demoEpisodeAlertItem = nil
            popupHeaderDetails = nil
            refreshTraktWatchlistState()
            resetAndLoadRottenTomatoesScore()
            connectorLineFadeTask?.cancel()
            connectorLineFadeTask = nil
            connectorLineVisible = false
            // Build 33: explicitly present Media Information on visionOS before any connector
            // decision is made. This removes the compositor dependency where the invisible
            // connector layer was accidentally the only thing forcing the popup pixels to draw.
            #if os(visionOS)
            var mediaInfoTransaction = Transaction()
            mediaInfoTransaction.disablesAnimations = true
            withTransaction(mediaInfoTransaction) { stageBackdropVisible = true }
            #else
            stageBackdropVisible = false
            #endif
            isDismissingDetail = false
            detailDismissTask?.cancel()
            detailDismissTask = nil
            loadPopupHeaderDetails()
            if isSeriesItem {
                preloadEpisodesForHeroPopup()
                showSeriesEpisodeHintIfNeeded()
            }
            openPendingEpisodeAlertIntentIfNeeded()
            let detailID = item.id
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.025) {
                guard playbackBrowseWorkAllowed else { return }
                guard store.selectedDetail?.id == detailID else { return }
                presentPremiumConnector(for: detailID)
            }
            // v1059: keep detail popup instant. Built-in trailer resolving waits until the user asks for Trailer.
        }
        .onChange(of: item) { updated in
            // vBRDC157: detail hydration is in-place, so id can remain unchanged while
            // TMDB/Cinemeta supplies the missing clearlogo/poster/backdrop. Persist the
            // enriched favorite object instead of waiting for an unfavorite/refavorite.
            persistFavoriteSnapshotIfNeeded(updated)
            refreshTraktWatchlistState()
        }
        .onChange(of: item.id) { _ in
            sourceResolveTask?.cancel()
            episodePreloadTask?.cancel()
            popupHeaderDetailsTask?.cancel()
            rottenTomatoesTask?.cancel()
            detailActionTask?.cancel()
            seriesEpisodeHintTask?.cancel()
            seriesEpisodeHintTask = nil
            seriesEpisodeHintVisible = false
            endTrailerExclusivePlayback(trailerAuxiliarySuppressionID)
            trailerAuxiliarySuppressionID = nil
            trailerPopup = false
            trailerURL = nil
            trailerResolving = false
            sourcePanelVisible = false
            sourceConfirmationIndex = nil
            sourceSearchItem = nil
            demoEpisodeAlertVisible = false
            demoEpisodeAlertFocus = 0
            demoEpisodeAlertItem = nil
            popupHeaderDetails = nil
            refreshTraktWatchlistState()
            resetAndLoadRottenTomatoesScore()
            connectorLineFadeTask?.cancel()
            connectorLineFadeTask = nil
            connectorLineVisible = false
            // Build 33: explicitly present Media Information on visionOS before any connector
            // decision is made. This removes the compositor dependency where the invisible
            // connector layer was accidentally the only thing forcing the popup pixels to draw.
            #if os(visionOS)
            var mediaInfoTransaction = Transaction()
            mediaInfoTransaction.disablesAnimations = true
            withTransaction(mediaInfoTransaction) { stageBackdropVisible = true }
            #else
            stageBackdropVisible = false
            #endif
            isDismissingDetail = false
            detailDismissTask?.cancel()
            detailDismissTask = nil
            loadPopupHeaderDetails()
            if isSeriesItem {
                preloadEpisodesForHeroPopup()
                showSeriesEpisodeHintIfNeeded()
            }
            openPendingEpisodeAlertIntentIfNeeded()
            let detailID = item.id
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.025) {
                guard playbackBrowseWorkAllowed else { return }
                guard store.selectedDetail?.id == detailID else { return }
                presentPremiumConnector(for: detailID)
            }
        }
        .onChange(of: popupProductionHydrationIdentity) { _ in
            // Search resolver hydration preserves the popup's visual id on purpose. If it
            // supplies a stronger external identity, immediately retry the compact Production
            // strip against the exact ID instead of leaving the earlier partial/title lookup.
            popupHeaderDetailsTask?.cancel()
            popupHeaderDetailsTask = nil
            if let cached = PopupHeaderDetailsService.shared.cached(for: item) {
                popupHeaderDetails = cached
            } else {
                loadPopupHeaderDetails()
            }
        }
        .onChange(of: isFindingLinks) { _ in
            synchronizeUnitySourceAnimationActivity(reason: "finding links")
        }
        .onChange(of: store.streamLinks.count) { count in
            // vBRDC212: results are interactive on first arrival; do not make the user wait
            // for every slow addon to finish before focus can enter the first playable row.
            guard count > 0, sourcePanelVisible, isFindingLinks else { return }
            if case .sourceProvider = focus {
                linkWindowStart = 0
                sourcePanelLastFocusedIndex = 0
                focus = .stream(0)
            }
        }
        .onChange(of: sourcePanelVisible) { _ in
            synchronizeUnitySourceAnimationActivity(reason: "source panel")
        }
        .onChange(of: sourceOpeningProvider) { _ in
            synchronizeUnitySourceAnimationActivity(reason: "source opening")
            if sourceOpeningProvider != nil {
                var transaction = Transaction()
                transaction.disablesAnimations = true
                withTransaction(transaction) { connectorLineVisible = false }
            }
        }
        .onChange(of: focused) { value in
            if !value && store.selectedDetail?.id == item.id && (playbackBrowseMode || store.playbackURL == nil) {
                DispatchQueue.main.async {
                    guard playbackBrowseWorkAllowed else { return }
                    focused = true
                }
            }
        }
        .onChange(of: store.playbackURL) { value in
            if value != nil {
                sourceConfirmationIndex = nil
                // v888: playback should not dismiss Source Intelligence. Keep the link panel
                // mounted behind the player so exiting a movie/show returns directly to the
                // same searchable links instead of falling back to catalog rows.
                sourceResolveTask?.cancel()
                episodePreloadTask?.cancel()
                popupHeaderDetailsTask?.cancel()
                rottenTomatoesTask?.cancel()
                detailActionTask?.cancel()
                store.cancelCurrentStreamSearch(reason: "Playback started; Source Intelligence network work stopped for VOD Exclusive Mode.", publishState: false)
                sourceOpeningProvider = nil
                isFindingLinks = false
                if !activeSourceLinks.isEmpty {
                    sourcePanelVisible = true
                    let safeIndex = min(max(sourcePanelLastFocusedIndex, 0), max(activeSourceLinks.count - 1, 0))
                    sourcePanelLastFocusedIndex = safeIndex
                    linkWindowStart = min(linkWindowStart, max(0, activeSourceLinks.count - sourceIntelligencePageSize))
                    focus = .stream(safeIndex)
                }
            } else if !activeSourceLinks.isEmpty || sourceOpeningProvider != nil || sourcePanelVisible {
                // v888: when playback closes, restore Source Intelligence as the active detail
                // focus target. This prevents focus from being stranded on the catalog rows and
                // lets the user immediately pick another source link.
                sourceOpeningProvider = nil
                isFindingLinks = false
                sourcePanelVisible = true
                let safeIndex = min(max(sourcePanelLastFocusedIndex, 0), max(activeSourceLinks.count - 1, 0))
                sourcePanelLastFocusedIndex = safeIndex
                linkWindowStart = min(linkWindowStart, max(0, activeSourceLinks.count - sourceIntelligencePageSize))
                focus = activeSourceLinks.isEmpty ? .findLinks : .stream(safeIndex)
                focused = true
            }
        }
        .onDisappear {
            detailDismissTask?.cancel()
            detailDismissTask = nil
            unityAnimations.setSourceIntelligence(searching: false, opening: false)
            connectorLineFadeTask?.cancel()
            connectorLineFadeTask = nil
            connectorLineVisible = false
            sourceResolveTask?.cancel()
            episodePreloadTask?.cancel()
            popupHeaderDetailsTask?.cancel()
            rottenTomatoesTask?.cancel()
            detailActionTask?.cancel()
            seriesEpisodeHintTask?.cancel()
            seriesEpisodeHintTask = nil
            seriesEpisodeHintVisible = false
            endTrailerExclusivePlayback(trailerAuxiliarySuppressionID)
            trailerAuxiliarySuppressionID = nil
            if store.playbackURL != nil {
                store.cancelCurrentStreamSearch(reason: "Details Stage unmounted for VOD Exclusive Mode.", publishState: false)
            }
        }
        .onTapGesture { activateDebounced() }
        .signalVisionPlayPauseCommand { activateDebounced() }
        .signalVisionExitCommand {
            if sourceConfirmationIndex != nil {
                sourceConfirmationIndex = nil
                focused = true
            } else if sourceOpeningProvider != nil {
                sourceOpeningProvider = nil
                sourcePanelVisible = false
                isFindingLinks = false
                focus = .findLinks
                store.status = "Opening stream cancelled."
            } else if trailerPopup {
                trailerPopup = false
                trailerURL = nil
                endTrailerExclusivePlayback(trailerAuxiliarySuppressionID)
                trailerAuxiliarySuppressionID = nil
                focused = true
            } else if sourcePanelVisible || isFindingLinks {
                sourceResolveTask?.cancel()
                store.cancelCurrentStreamSearch(reason: "Source Intelligence closed.")
                sourcePanelVisible = false
                sourceConfirmationIndex = nil
                sourceOpeningProvider = nil
                isFindingLinks = false
                linkWindowStart = 0
                focus = .findLinks
                focused = true
            } else if demoEpisodeAlertVisible {
                demoEpisodeAlertVisible = false
                focus = .follow
            } else {
                dismissDetailSmoothly()
            }
        }
        .signalMoveCommand { direction in
            guard !isDismissingDetail else { return }
            route(direction)
        }
    }

    @MainActor
    private func dismissDetailSmoothly() {
        guard !isDismissingDetail else { return }
        isDismissingDetail = true
        let closingID = item.id

        connectorLineFadeTask?.cancel()
        connectorLineFadeTask = nil
        connectorLineVisible = false

        // Restore the exact catalog FocusState while the opaque/glass popup still covers
        // it. This converts Back from a popup-removal/focus jump into one continuous handoff.
        if connectorOrigin == .catalog {
            store.prepareCatalogDetailDismissalFocusHandoff()
        }

        let animated = unityAnimations.allows(.detailTransition)
        if animated {
            withAnimation(.timingCurve(0.20, 0.86, 0.28, 1.0, duration: detailStageTransitionDuration)) {
                stageBackdropVisible = false
            }
        } else {
            var transaction = Transaction()
            transaction.disablesAnimations = true
            withTransaction(transaction) { stageBackdropVisible = false }
        }

        detailDismissTask?.cancel()
        detailDismissTask = Task { @MainActor in
            if animated {
                // One matched compositor handoff. Do not destroy a 1.18s connector
                // retraction 320ms into its path as the previous implementation did.
                try? await Task.sleep(nanoseconds: UInt64((detailStageTransitionDuration + 0.02) * 1_000_000_000))
            } else {
                await Task.yield()
            }
            guard !Task.isCancelled,
                  (playbackBrowseMode || store.playbackURL == nil),
                  store.selectedDetail?.id == closingID else { return }
            store.closeDetail()
            detailDismissTask = nil
        }
    }

    @MainActor
    private func presentPremiumConnector(for detailID: String) {
        connectorLineFadeTask?.cancel()
        connectorLineFadeTask = nil
        #if os(visionOS)
        // Build 31 hard separation: this function owns ONLY the decorative connector.
        // It cannot mutate Media Information panel presentation state on visionOS.
        guard mediaInfoConnectorLineEnabled,
              connectorOrigin == .catalog,
              !playbackBrowseMode,
              unityAnimations.allows(.detailConnector) else {
            connectorLineVisible = false
            return
        }
        connectorLineVisible = true
        connectorLineFadeTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: connectorTravelNanoseconds + connectorHoldNanoseconds)
            guard !Task.isCancelled,
                  store.selectedDetail?.id == detailID,
                  item.id == detailID else { return }
            // Only the line retracts. Media Information stays presented until Back/Play.
            connectorLineVisible = false
            connectorLineFadeTask = nil
        }
        return
        #else

        guard unityAnimations.allows(.detailConnector) else {
            var transaction = Transaction()
            transaction.disablesAnimations = true
            withTransaction(transaction) {
                connectorLineVisible = false
                stageBackdropVisible = true
            }
            return
        }

        // v1088: Search and Favorites do not use a connector. Reveal their
        // presentation immediately and leave connector state disabled for the visit.
        if playbackBrowseMode || connectorOrigin == .search || connectorOrigin == .favorites || !mediaInfoConnectorLineEnabled {
            var searchTransaction = Transaction()
            searchTransaction.disablesAnimations = true
            withTransaction(searchTransaction) {
                connectorLineVisible = false
                stageBackdropVisible = true
            }
            return
        }

        // Reset both stages without animation so every selected title visibly travels
        // from its focused poster into a newly presented information panel.
        var resetTransaction = Transaction()
        resetTransaction.disablesAnimations = true
        withTransaction(resetTransaction) {
            connectorLineVisible = false
            stageBackdropVisible = false
        }

        DispatchQueue.main.async {
            guard playbackBrowseWorkAllowed,
                  store.selectedDetail?.id == detailID,
                  item.id == detailID else { return }
            // vBRDC108: connector and panel start on the same render turn. The old
            // connector-first 200-260ms wait made every Details open feel like two
            // animations chained together and exposed a visible half-settled catalog frame.
            connectorLineVisible = true
            stageBackdropVisible = true
        }

        connectorLineFadeTask = Task { @MainActor in
            // Hold timing starts after the connector finishes drawing, but panel visibility
            // is independent and already moving in the same compositor transaction.
            try? await Task.sleep(nanoseconds: connectorTravelNanoseconds)
            guard !Task.isCancelled,
                  playbackBrowseWorkAllowed,
                  store.selectedDetail?.id == detailID,
                  item.id == detailID else { return }

            // Keep the complete connector on screen for seven seconds, then retract it.
            try? await Task.sleep(nanoseconds: connectorHoldNanoseconds)
            guard !Task.isCancelled,
                  playbackBrowseWorkAllowed,
                  store.selectedDetail?.id == detailID,
                  item.id == detailID else { return }
            connectorLineVisible = false
            connectorLineFadeTask = nil
        }
        #endif
    }

    @ViewBuilder
    private var popupDimLayer: some View {
        if connectorOrigin == .search {
            // vBRDC020: Search-owned details now have their own cinematic presentation.
            // Search remains mounted underneath for exact return, but the selected title's
            // artwork always owns the full-screen backdrop here even when the optional
            // catalog Connected Popup Artwork setting is Off. This is intentionally scoped
            // to Search so Home/Movies/Shows/Favorites/Live TV presentation stays untouched.
            ZStack {
                Color.black

                if detailArtworkReady, let backdropURL = connectedPopupArtworkURL {
                    RemoteImageFit(url: backdropURL, mode: .fill, showPlaceholder: false)
                        .id("vBRDC020-search-cinematic-backdrop-\(item.id)-\(backdropURL)")
                        .scaleEffect(1.035)
                        .saturation(1.10)
                        .contrast(1.10)
                        .brightness(-0.015)
                        .opacity(0.68)
                } else {
                    LinearGradient(
                        colors: [
                            Color.black,
                            Color(red: 0.025, green: 0.065, blue: 0.11),
                            Color.black,
                            Color(red: 0.10, green: 0.035, blue: 0.018).opacity(0.65)
                        ],
                        startPoint: .topLeading,
                        endPoint: .bottomTrailing
                    )
                }

                // Keep faces/artwork readable while carving a dark premium lane behind the
                // centered Media Profile card instead of reducing the entire screen to black.
                LinearGradient(
                    colors: [
                        Color.black.opacity(0.74),
                        Color.black.opacity(0.22),
                        Color.black.opacity(0.14),
                        Color.black.opacity(0.60)
                    ],
                    startPoint: .leading,
                    endPoint: .trailing
                )

                LinearGradient(
                    colors: [
                        Color.black.opacity(0.34),
                        Color.clear,
                        Color.black.opacity(0.18),
                        Color.black.opacity(0.88)
                    ],
                    startPoint: .top,
                    endPoint: .bottom
                )

                // Brand-light ambience adds depth without tinting the actual poster/backdrop.
                RadialGradient(
                    colors: [Color.cyan.opacity(0.16), Color.cyan.opacity(0.035), Color.clear],
                    center: .topLeading,
                    startRadius: 30,
                    endRadius: 820
                )
                .blendMode(.screen)

                RadialGradient(
                    colors: [Color.orange.opacity(0.12), Color.orange.opacity(0.025), Color.clear],
                    center: .bottomTrailing,
                    startRadius: 20,
                    endRadius: 760
                )
                .blendMode(.screen)

                // A restrained diagonal sheen keeps the full-screen search stage from reading
                // like a static wallpaper while remaining completely non-interactive/focus-free.
                LinearGradient(
                    colors: [Color.white.opacity(0.028), Color.clear, Color.white.opacity(0.012), Color.clear],
                    startPoint: .topLeading,
                    endPoint: .bottomTrailing
                )
            }
            .compositingGroup()
            .ignoresSafeArea()
            .allowsHitTesting(false)
            .accessibilityIdentifier("VBRDC020SearchCinematicMediaInformationStage")
        } else if connectorOrigin == .favorites {
            // v1088: keep the selected Favorites backdrop/poster clearly visible. A
            // restrained neutral veil separates the centered popup without replacing
            // the Favorites screen or making it read like a new destination.
            Color.black.opacity(0.16)
                .ignoresSafeArea()
                .allowsHitTesting(false)
                .accessibilityIdentifier("V1088FavoritesLocalPopupBackdrop")
        } else {
            // Catalog-origin details remain transparent over the active rows/Live TV grid.
            Color.clear
                .ignoresSafeArea()
                .allowsHitTesting(false)
        }
    }

    private var mediaInfoPanelPresented: Bool {
        #if os(visionOS)
        // Build 33: selectedDetail owns the lifetime of Media Information on visionOS.
        // Do NOT gate the panel on stageBackdropVisible or connectorLineVisible. The headset
        // proved the old separate visual layer could become invisible while hit testing stayed
        // alive. Only an explicit detail dismissal may hide this panel now.
        return !isDismissingDetail
        #else
        return stageBackdropVisible
        #endif
    }

    private var popupPanelLayer: some View {
        let centeredPresentation = connectorOrigin == .favorites || connectorOrigin == .search
        return ZStack(alignment: centeredPresentation ? .center : .topTrailing) {
            popupPanelContent
                .frame(width: connectedPopupCanvasSize.width, height: connectedPopupCanvasSize.height, alignment: .topLeading)
                .background(popupPanelBackground)
                // v1061: only the glass treatment dissolves into the lower poster rail.
                // Popup content remains fully legible while the tint/blur/outline lose their
                // rectangular bottom edge and appear to break naturally into the cards.
                .background(popupPanelDissolvingShadow)
                // v1051: The content and the exact-size artwork canvas share one mask.
                // This is a true aspect-fill crop inside 860×858, never a stretched
                // background proposal and never an image outside the popup silhouette.
                .clipShape(RoundedRectangle(cornerRadius: connectedPopupCornerRadius, style: .continuous))
                .overlay(popupPanelBorder.allowsHitTesting(false))
                // vBRDC108: do not animate a full-size mask over the complete 860x858
                // glass/artwork subtree. That forces repeated off-screen re-rasterization
                // during the same frames that catalog focus is being handed off. A small
                // direct transform stays on the compositor and keeps the exact panel pixels.
                .scaleEffect(x: mediaInfoPanelPresented ? 1.0 : 0.975, y: 1.0, anchor: .leading)
                .offset(
                    x: centeredPresentation ? (mediaInfoPanelPresented ? 0 : -6) : (mediaInfoPanelPresented ? -48 : -42),
                    y: centeredPresentation ? 0 : 126
                )
                .opacity(mediaInfoPanelPresented ? 1.0 : 0.0)
        }
        .frame(width: 1920, height: 1080, alignment: centeredPresentation ? .center : .topTrailing)
        #if os(visionOS)
        .background(Color.black.opacity(0.001))
        .compositingGroup()
        #endif
        .animation(
            unityAnimations.allows(.detailTransition)
                ? .timingCurve(0.20, 0.86, 0.28, 1.0, duration: detailStageTransitionDuration)
                : nil,
            value: mediaInfoPanelPresented
        )
        .animation(unityAnimations.allows(.detailTransition) ? .easeInOut(duration: 0.18) : nil, value: connectedPopupArtworkLayerAllowed)
        .accessibilityIdentifier("V1049ConnectedPopupArtworkContained")
    }

    @ViewBuilder
    private var popupPanelBackground: some View {
        // v1060: the connected panel has no opaque canvas. Live TV and catalog artwork
        // remain visible through the full popup silhouette; only a faint edge sheen is
        // retained so text groups still read as one premium surface.
        ZStack {
            #if os(visionOS)
            // Build 32: the Media Information surface must remain visually composited even
            // when the connector line is disabled/retracted. This foundation is independent
            // of connectorLineVisible and fixes the previous invisible-but-hit-testable panel.
            RoundedRectangle(cornerRadius: connectedPopupCornerRadius, style: .continuous)
                .fill(Color.black.opacity(0.82))
                .overlay(
                    RoundedRectangle(cornerRadius: connectedPopupCornerRadius, style: .continuous)
                        .stroke(Color.white.opacity(0.16), lineWidth: 1.5)
                )
            #else
            Color.clear
            #endif

            if connectedPopupArtworkLayerAllowed, detailArtworkReady, let backdropURL = connectedPopupArtworkURL {
                RemoteImageFit(
                    url: backdropURL,
                    mode: .fill,
                    showPlaceholder: false,
                    maxPixelSize: 2048,
                    preservePreviousOnURLChange: true
                )
                    // Keep this loader stable if metadata hydration upgrades the URL for the
                    // same title. The ready replacement swaps directly over the retained frame.
                    .id("connected-popup-detail-artwork-vBRDC092-\(item.id)")
                    .frame(width: connectedPopupCanvasSize.width, height: connectedPopupCanvasSize.height)
                    .clipped()
                    .saturation(0.92)
                    .contrast(1.08)
                    .opacity(0.34)
                    .overlay(
                        LinearGradient(
                            colors: [
                                Color.black.opacity(0.38),
                                Color.black.opacity(0.16),
                                Color.black.opacity(0.34)
                            ],
                            startPoint: .topLeading,
                            endPoint: .bottomTrailing
                        )
                    )
            }

            LinearGradient(
                colors: [
                    Color.white.opacity(0.022),
                    Color.cyan.opacity(0.010),
                    Color.clear,
                    Color.orange.opacity(0.010)
                ],
                startPoint: .topLeading,
                endPoint: .bottomTrailing
            )

            RadialGradient(
                colors: [Color.cyan.opacity(0.018), Color.clear],
                center: .topLeading,
                startRadius: 0,
                endRadius: 470
            )

            UnityCatalogHeroAura(item: item, intensity: 0.62)
        }
        .frame(width: connectedPopupCanvasSize.width, height: connectedPopupCanvasSize.height)
        .clipShape(RoundedRectangle(cornerRadius: connectedPopupCornerRadius, style: .continuous))
        .mask(popupGlassDissolveMask)
        .allowsHitTesting(false)
    }

    private var popupGlassDissolveMask: some View {
        LinearGradient(
            stops: [
                .init(color: .white, location: 0.00),
                .init(color: .white, location: 0.69),
                .init(color: .white.opacity(0.92), location: 0.76),
                .init(color: .white.opacity(0.58), location: 0.84),
                .init(color: .white.opacity(0.18), location: 0.93),
                .init(color: .clear, location: 1.00)
            ],
            startPoint: .top,
            endPoint: .bottom
        )
        .frame(width: connectedPopupCanvasSize.width, height: connectedPopupCanvasSize.height)
    }

    private var popupPanelDissolvingShadow: some View {
        RoundedRectangle(cornerRadius: connectedPopupCornerRadius, style: .continuous)
            .fill(Color.black.opacity(0.16))
            .blur(radius: 18)
            .offset(x: -4, y: 8)
            .mask(popupGlassDissolveMask)
            .allowsHitTesting(false)
    }

    @ViewBuilder
    private var popupPanelBorder: some View {
        ZStack(alignment: .topLeading) {
            RoundedRectangle(cornerRadius: connectedPopupCornerRadius, style: .continuous)
                .stroke(
                    LinearGradient(
                        colors: playbackBrowseMode
                            ? [Color.cyan.opacity(0.72), Color.indigo.opacity(0.56), Color.white.opacity(0.12), Color.cyan.opacity(0.34)]
                            : [Color.white.opacity(0.34), Color.cyan.opacity(0.20), Color.white.opacity(0.065), Color.orange.opacity(0.22)],
                        startPoint: .topLeading,
                        endPoint: .bottomTrailing
                    ),
                    lineWidth: 1.25
                )
                .mask(popupGlassDissolveMask)
        }
        .frame(width: connectedPopupCanvasSize.width, height: connectedPopupCanvasSize.height)
    }

    private var popupPanelContent: some View {
        VStack(alignment: .leading, spacing: 12) {
            ConnectedMediaInformationTopBar(item: item, details: popupHeaderDetails, publishDuringPlayback: playbackBrowseMode)

            Rectangle()
                .fill(LinearGradient(colors: [Color.orange.opacity(0.58), Color.white.opacity(0.20), Color.cyan.opacity(0.54), Color.clear], startPoint: .leading, endPoint: .trailing))
                .frame(height: 1.25)

            popupActionRow
                .frame(maxWidth: .infinity, alignment: .leading)

            if sourcePanelVisible {
                // v1069: Find Links never leaves the media-information popup. The complete
                // Source Intelligence experience occupies the lower half beneath the action
                // chips, with a separate glass fade so it dissolves before reaching row cards.
                SourceIntelligenceEmbeddedLowerPanel(
                    item: sourceSearchItem ?? item,
                    focus: focus,
                    visibleLinks: visibleLinks,
                    allLinks: activeSourceLinks,
                    linkWindowStart: linkWindowStart,
                    totalLinkCount: activeSourceLinks.count,
                    isScanning: isFindingLinks,
                    batchStatus: store.sourceIntelligenceBatchStatus,
                    selectedProvider: store.selectedSourceProvider,
                    providerOptions: sourceProviderOptions,
                    providerStatuses: store.sourceProviderStatuses,
                    focusedProviderIndex: focusedSourceProviderIndex,
                    onSelectProvider: selectSourceProvider
                )
                .frame(width: 808, height: 522, alignment: .topLeading)
                .transition(.opacity.combined(with: .move(edge: .bottom)))
                .accessibilityIdentifier("V1069EmbeddedLowerSourceIntelligence")
            } else {
                popupUtilityRow

                if advisoryDisplayEnabled {
                    ConnectedPopupAdvisoryStrip(item: item, details: popupHeaderDetails)
                }

                ConnectedPopupCastRow(item: item, publishDuringPlayback: playbackBrowseMode)
                    .frame(height: isSeriesItem ? 88 : 136, alignment: .topLeading)

                // vBRDC066: restore real TMDB franchise/collection metadata to the CURRENT
                // compact connected media-information panel. The ribbon has a fixed 66pt
                // footprint; its focused shelf expands upward as an overlay, so the catalog
                // cards underneath never move and the old full-screen Details page stays gone.
                if !visibleMovieFranchiseItems.isEmpty {
                    UnityCompactFranchiseRibbon(
                        item: item,
                        visibleItems: visibleMovieFranchiseItems,
                        totalCount: item.franchiseItems.count,
                        baseIndex: relatedWindowStart,
                        focusedIndex: focusedFranchiseIndex
                    )
                    .frame(width: 808, height: 66, alignment: .leading)
                    .zIndex(focusedFranchiseIndex == nil ? 2 : 40)
                }

                if isSeriesItem {
                    connectedSeriesEpisodesSection
                }
            }

            Spacer(minLength: 0)
        }
        .padding(.horizontal, 26)
        .padding(.vertical, 22)
        .contentShape(RoundedRectangle(cornerRadius: connectedPopupCornerRadius, style: .continuous))
        .overlay(alignment: .topTrailing) {
            if isSeriesItem && seriesEpisodeHintVisible && !sourcePanelVisible {
                HStack(spacing: 9) {
                    Image(systemName: "arrow.down.circle.fill")
                        .font(.system(size: 17, weight: .black))
                        .foregroundStyle(Color.cyan.opacity(0.96))
                    Text("Tip: Scroll down, choose a season, then select the episode you want for links.")
                        .font(.system(size: 12, weight: .bold, design: .rounded))
                        .foregroundStyle(.white.opacity(0.94))
                        .lineLimit(2)
                }
                .padding(.horizontal, 14)
                .padding(.vertical, 10)
                .frame(width: 390, alignment: .leading)
                .background(
                    RoundedRectangle(cornerRadius: 14, style: .continuous)
                        .fill(Color.black.opacity(0.82))
                        .overlay(RoundedRectangle(cornerRadius: 14, style: .continuous).stroke(Color.cyan.opacity(0.34), lineWidth: 1))
                )
                .padding(.top, 112)
                .padding(.trailing, 22)
                .allowsHitTesting(false)
                .transition(.opacity.combined(with: .scale(scale: 0.98)))
            }
        }
        .animation(unityAnimations.allows(.sourceIntelligenceMotion) ? .spring(response: 0.30, dampingFraction: 0.91) : nil, value: sourcePanelVisible)
        .animation(.easeOut(duration: 0.20), value: seriesEpisodeHintVisible)
    }

    private func showSeriesEpisodeHintIfNeeded() {
        seriesEpisodeHintTask?.cancel()
        guard isSeriesItem, !seriesEpisodeHintShown else {
            seriesEpisodeHintVisible = false
            return
        }
        seriesEpisodeHintShown = true
        withAnimation(.easeOut(duration: 0.20)) {
            seriesEpisodeHintVisible = true
        }
        seriesEpisodeHintTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: 30_000_000_000)
            guard !Task.isCancelled else { return }
            withAnimation(.easeOut(duration: 0.18)) {
                seriesEpisodeHintVisible = false
            }
            seriesEpisodeHintTask = nil
        }
    }

