    private var isCatalogFavorite: Bool {
        !favoriteMediaKeySet(favoriteMediaIdsRaw).isDisjoint(with: mediaFavoriteKeys(for: item))
    }

    private var isFollowingShow: Bool {
        !followedShowKeySet.isDisjoint(with: followShowKeyAliases)
    }

    private var followedShowKeySet: Set<String> {
        Set(followedShowIdsRaw.split(separator: "|").map(String.init).filter { !$0.isEmpty })
    }

    private var safeFollowShowKey: String {
        mediaFavoriteKey(item)
            .replacingOccurrences(of: "|", with: "_")
            .replacingOccurrences(of: "\n", with: " ")
    }

    private var followShowKeyAliases: Set<String> {
        let legacy = mediaFavoriteLegacyKey(item)
            .replacingOccurrences(of: "|", with: "_")
            .replacingOccurrences(of: "\n", with: " ")
        return [safeFollowShowKey, legacy]
    }

    private var verifiedEpisodeHint: String? {
        guard isSeriesItem else { return nil }
        if isFollowingShow { return "Verified episode alerts enabled" }
        return popupHeaderDetails?.status?.lowercased() == "returning series" ? "Follow for verified episode alerts" : nil
    }

    private func persistFavoriteSnapshotIfNeeded(_ candidate: MediaItem) {
        let keys = favoriteMediaKeySet(favoriteMediaIdsRaw)
        guard !keys.isDisjoint(with: mediaFavoriteKeys(for: candidate)) else { return }
        persistFavoriteMediaSnapshot(candidate)
    }

    private func togglePopupFavorite() {
        var keys = favoriteMediaKeySet(favoriteMediaIdsRaw)
        let key = mediaFavoriteKey(item)
        let allKeys = mediaFavoriteKeys(for: item)
        if !keys.isDisjoint(with: allKeys) {
            keys.subtract(allKeys)
            removeFavoriteMediaSnapshot(for: item)
            store.status = "Removed from Favorites"
        } else {
            keys.insert(key)
            persistFavoriteMediaSnapshot(item)
            store.status = "Added to Favorites"
        }
        favoriteMediaIdsRaw = keys.sorted().joined(separator: "|")
    }

    private func refreshTraktWatchlistState() {
        guard TraktSyncManager.shared.isConnected else {
            traktWatchlisted = false
            traktWatchlistBusy = false
            return
        }
        traktWatchlisted = TraktCatalogService.shared.personalStatus(for: item).inWatchlist
    }

    private func toggleTraktWatchlist() {
        guard TraktSyncManager.shared.isConnected else {
            store.status = "Connect Trakt in Settings first."
            return
        }
        guard !traktWatchlistBusy else { return }
        let target = !traktWatchlisted
        traktWatchlistBusy = true
        store.status = target ? "Adding to Trakt Watchlist…" : "Removing from Trakt Watchlist…"
        Task {
            do {
                try await TraktSyncManager.shared.setWatchlist(item: item, add: target)
                await MainActor.run {
                    traktWatchlisted = target
                    traktWatchlistBusy = false
                    store.status = target ? "Added to Trakt Watchlist" : "Removed from Trakt Watchlist"
                    // Publish the button/account state now; network shelves refresh behind it.
                    store.refreshPlaybackDerivedCatalogRows()
                    store.refreshTraktCatalogRowsIfNeeded(force: true, userInitiated: true)
                }
            } catch {
                await MainActor.run {
                    traktWatchlistBusy = false
                    refreshTraktWatchlistState()
                    store.status = "Trakt Watchlist: \(error.localizedDescription)"
                }
            }
        }
    }

    private func toggleFollowShow() {
        var keys = followedShowKeySet
        let key = safeFollowShowKey
        if !keys.isDisjoint(with: followShowKeyAliases) {
            keys.subtract(followShowKeyAliases)
            store.forgetFollowedShow(item)
            store.status = "Show follow removed"
        } else {
            keys.insert(key)
            store.rememberFollowedShow(item)
            store.status = "Following show for verified episode alerts"
        }
        followedShowIdsRaw = keys.sorted().joined(separator: "|")
    }

    private var popupMetadataLine: some View {
        // v511: The popup already shows year/type/genre in the header and premium chips; source search is now compact icon-only.
        // Use this prime real estate for critic-style score cards instead of repeating metadata.
        HStack(spacing: 12) {
            if tomatoScoreText != "N/A" {
                CriticScorePill(title: "RT", value: tomatoScoreText, icon: "seal.fill", tint: .red)
            }
            CriticScorePill(title: "CRITICS", value: criticScoreText, icon: "quote.bubble.fill", tint: .yellow)
            CriticScorePill(title: "AUDIENCE", value: audienceScoreText, icon: "person.2.fill", tint: .orange)
        }
        .frame(height: 36, alignment: .leading)
    }

    private var numericRating: Double {
        let cleaned = item.rating.replacingOccurrences(of: ",", with: ".")
        return Double(cleaned.filter { "0123456789.".contains($0) }) ?? 0
    }

    private var normalizedScorePercent: Int {
        let rating = numericRating
        guard rating > 0 else { return 0 }
        if rating <= 10 { return Int((rating * 10).rounded()) }
        if rating <= 100 { return Int(rating.rounded()) }
        return 0
    }

    private var tomatoScoreText: String {
        rottenTomatoesScoreText
    }

    private var criticScoreText: String {
        let rating = numericRating
        if rating > 0 && rating <= 10 { return String(format: "%.1f/10", rating) }
        let score = normalizedScorePercent
        return score > 0 ? "\(score)%" : "N/A"
    }

    private var audienceScoreText: String {
        let score = normalizedScorePercent
        guard score > 0 else { return "N/A" }
        // Audience is displayed as a companion score until a true external audience feed is wired.
        return "\(min(99, max(1, score + 3)))%"
    }

    private var popupIMDbID: String? {
        let explicit = item.imdbId?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        if !explicit.isEmpty { return explicit.lowercased() }
        let rawText = ([item.id, item.previewURL ?? "", item.posterURL ?? "", item.landscapeURL ?? "", item.description] + item.genres).joined(separator: " ")
        guard let range = rawText.range(of: #"tt\d{5,}"#, options: [.regularExpression, .caseInsensitive]) else { return nil }
        return String(rawText[range]).lowercased()
    }

    private func resetAndLoadRottenTomatoesScore() {
        rottenTomatoesTask?.cancel()
        rottenTomatoesScoreText = "N/A"
        let currentID = item.id
        let imdbID = popupIMDbID
        let title = item.title
        let year = item.year
        let tmdbID = item.tmdbId
        let itemID = item.id
        let type = item.type
        rottenTomatoesTask = VODExclusiveWorkRegistry.start(allowDuringExclusivePlayback: playbackBrowseMode) {
            let score = await RottenTomatoesScoreCache.fetchScore(imdbID: imdbID, title: title, year: year, tmdbID: tmdbID, itemID: itemID, type: type)
            guard !Task.isCancelled, playbackBrowseWorkAllowed else { return }
            await MainActor.run {
                guard item.id == currentID, playbackBrowseWorkAllowed else { return }
                rottenTomatoesScoreText = score ?? "N/A"
            }
        }
    }



