struct DynamicInformationBar: View {
    let item: MediaItem
    let tomatoScore: String
    let criticScore: String
    let audienceScore: String
    @State private var page: Int = 0

    private var entries: [(String, String, String, Color)] {
        var result: [(String, String, String, Color)] = []
        if tomatoScore != "—" && tomatoScore != "N/A" { result.append(("TOMATO", "Tomato score \(tomatoScore)", "seal.fill", .white)) }
        if criticScore != "—" && criticScore != "N/A" { result.append(("CRITICS", "Critics \(criticScore)", "quote.bubble.fill", .white)) }
        if audienceScore != "—" && audienceScore != "N/A" { result.append(("AUDIENCE", "Audience \(audienceScore)", "person.2.fill", .white)) }
        if !item.catalog.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            result.append(("SOURCE", item.catalog, "sparkles.tv.fill", .white))
        }
        if let director = item.directors.first, !director.isEmpty {
            result.append(("DIRECTED BY", director, "person.crop.rectangle.stack.fill", .white))
        } else if let cast = item.castMembers.first?.name, !cast.isEmpty {
            result.append(("CAST SPOTLIGHT", cast, "person.crop.circle.fill", .white))
        }
        if let firstGenre = item.genres.first, !firstGenre.isEmpty {
            result.append(("MOOD", "\(firstGenre.uppercased()) • Premium metadata ready", "wand.and.stars", .white))
        }
        return result
    }

    private var current: (String, String, String, Color) {
        let all = entries
        guard !all.isEmpty else { return ("INFO", "Metadata ready", "info.circle.fill", .white) }
        return all[page % all.count]
    }

    var body: some View {
        let item = current
        HStack(spacing: 10) {
            Image(systemName: item.2)
                .font(.system(size: 15, weight: .black))
                .foregroundStyle(.white.opacity(0.76))
                .frame(width: 22)
            Text(item.0)
                .font(.system(size: 10, weight: .black, design: .rounded))
                .kerning(0.8)
                .foregroundStyle(.white.opacity(0.56))
                .lineLimit(1)
            Text(item.1)
                .font(.system(size: 14, weight: .black, design: .rounded))
                .foregroundStyle(.white.opacity(0.92))
                .lineLimit(1)
            Spacer(minLength: 0)
            EmptyView()
        }
        .padding(.horizontal, 12)
        .background(RoundedRectangle(cornerRadius: 14, style: .continuous).fill(Color.black.opacity(0.34)))
        .overlay(RoundedRectangle(cornerRadius: 14, style: .continuous).stroke(Color.white.opacity(0.10), lineWidth: 0.8))
        .animation(.easeInOut(duration: 0.28), value: page)
        .onReceive(Timer.publish(every: 5.8, on: .main, in: .common).autoconnect()) { _ in
            let count = max(entries.count, 1)
            page = (page + 1) % count
        }
    }
}

