    }

    private func openSourceIntelligenceForEpisode(_ selectedEpisode: MediaItem, emptyFocus: DetailPage.DetailNode) {
        var episode = selectedEpisode
        // v1062: preserve the exact episode identity and let CatalogStore hydrate
        // episode/season/series credits in priority order. Copying the parent cast here
        // made anthology episodes display the wrong actors before hydration completed.
        episode.castMembers = []
        episode.cast = []
        episode.directors = []
        func nonEmpty(_ value: String?) -> String? {
            let clean = value?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
            return clean.isEmpty ? nil : clean
        }
        let episodeStill = [episode.landscapeURL, episode.previewURL, episode.posterURL]
            .compactMap(nonEmpty)
            .first
        let fallbackArt = episodeStill ?? nonEmpty(item.posterURL) ?? nonEmpty(item.landscapeURL)
        if nonEmpty(episode.posterURL) == nil { episode.posterURL = fallbackArt }
        if nonEmpty(episode.landscapeURL) == nil { episode.landscapeURL = episodeStill ?? fallbackArt }
        if nonEmpty(episode.previewURL) == nil { episode.previewURL = episodeStill ?? fallbackArt }
        sourceSearchItem = episode
        store.selectedSourceProvider = "All Providers"
        sourcePanelVisible = true
        linkWindowStart = 0
        sourcePanelLastFocusedIndex = 0
        focus = activeSourceLinks.isEmpty ? emptyFocus : .stream(0)
        sourceResolveTask?.cancel()
        store.cancelCurrentStreamSearch(reason: "Episode changed; previous provider resolve cancelled.")
        sourceResolveTask = VODExclusiveWorkRegistry.start(allowDuringExclusivePlayback: playbackBrowseMode) {
            isFindingLinks = true
            _ = await store.findStreamsForcePopulated(for: episode, providerFilter: store.selectedSourceProvider)
            guard !Task.isCancelled, sourceSearchItem?.id == episode.id else { return }
            guard !Task.isCancelled, sourceSearchItem?.id == episode.id else { return }
            isFindingLinks = false
            linkWindowStart = 0
            sourcePanelLastFocusedIndex = min(sourcePanelLastFocusedIndex, max(activeSourceLinks.count - 1, 0))
            if !activeSourceLinks.isEmpty { focus = .stream(min(sourcePanelLastFocusedIndex, activeSourceLinks.count - 1)) }
        }
    }

    private func routeDemoEpisodeAlert(_ direction: SignalMoveDirection) {
        switch direction {
        case .left:
            demoEpisodeAlertFocus = max(0, demoEpisodeAlertFocus - 1)
        case .right:
            demoEpisodeAlertFocus = min(3, demoEpisodeAlertFocus + 1)
        case .up, .down:
            break
        default:
            break
        }
    }

    private func activateDemoEpisodeAlert() {
        switch demoEpisodeAlertFocus {
        case 0:
            let episode = demoEpisodeAlertItem ?? makeDemoEpisodeAlertItem()
            demoEpisodeAlertVisible = false
            detailActionTask?.cancel()
            detailActionTask = VODExclusiveWorkRegistry.start(allowDuringExclusivePlayback: playbackBrowseMode) {
                isFindingLinks = true
                await store.playFirstDirectStream(for: episode)
                if playbackBrowseWorkAllowed { isFindingLinks = false }
            }
        case 1:
            runDemoAlertFindLinks()
        case 2:
            demoEpisodeAlertVisible = false
            focus = .testAlert
        default:
            demoEpisodeAlertVisible = false
            focus = .testAlert
            store.status = "Test alert marked seen"
        }
    }

