    private func loadPopupHeaderDetails() {
        let key = popupTMDBApiKey.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !key.isEmpty else { return }
        if let cached = PopupHeaderDetailsService.shared.cached(for: item) {
            popupHeaderDetails = cached
            return
        }
        let currentID = item.id
        popupHeaderDetailsTask?.cancel()
        popupHeaderDetailsTask = VODExclusiveWorkRegistry.start(allowDuringExclusivePlayback: playbackBrowseMode) {
            guard let details = await PopupHeaderDetailsService.shared.details(for: item, apiKey: key) else { return }
            guard !Task.isCancelled, playbackBrowseWorkAllowed, item.id == currentID else { return }
            popupHeaderDetails = details
        }
    }

    private func fetchPopupHeaderDetails(apiKey key: String) async -> PopupHeaderDetails? {
        struct FoundItem: Decodable { let id: Int? }
        struct FindResponse: Decodable { let movie_results: [FoundItem]?; let tv_results: [FoundItem]? }
        struct SearchItem: Decodable { let id: Int? }
        struct SearchResponse: Decodable { let results: [SearchItem]? }
        struct Company: Decodable { let name: String? }
        struct Network: Decodable { let name: String? }
        struct MovieReleaseDate: Decodable { let certification: String? }
        struct MovieReleaseRegion: Decodable { let iso_3166_1: String?; let release_dates: [MovieReleaseDate]? }
        struct MovieReleaseDates: Decodable { let results: [MovieReleaseRegion]? }
        struct TVContentRating: Decodable { let iso_3166_1: String?; let rating: String? }
        struct TVContentRatings: Decodable { let results: [TVContentRating]? }
        struct MovieDetail: Decodable { let budget: Int?; let revenue: Int?; let runtime: Int?; let production_companies: [Company]?; let release_dates: MovieReleaseDates? }
        struct TVDetail: Decodable { let episode_run_time: [Int]?; let number_of_seasons: Int?; let number_of_episodes: Int?; let status: String?; let networks: [Network]?; let content_ratings: TVContentRatings? }

        func fetch<T: Decodable>(_ type: T.Type, from url: URL) async -> T? {
            do {
                let (data, response) = try await URLSession.shared.data(from: url)
                if let http = response as? HTTPURLResponse, !(200..<300).contains(http.statusCode) { return nil }
                return try JSONDecoder().decode(T.self, from: data)
            } catch { return nil }
        }

        let normalizedType = item.type.lowercased()
        let isTV = normalizedType.contains("series") || normalizedType.contains("show") || normalizedType.contains("tv")
        let parts = item.id.split(separator: ":").map(String.init)
        var detailKind: String? = nil
        var detailID: String? = nil

        if parts.count >= 3, parts[0].lowercased() == "tmdb" {
            detailKind = (parts[1].lowercased() == "tv" || isTV) ? "tv" : "movie"
            detailID = parts[2]
        } else {
            let imdbID: String? = {
                if item.id.lowercased().hasPrefix("tt") { return item.id }
                if let match = item.id.range(of: #"tt\d{6,}"#, options: .regularExpression) { return String(item.id[match]) }
                return nil
            }()
            if let imdbID, let encoded = imdbID.addingPercentEncoding(withAllowedCharacters: .urlPathAllowed),
               let findURL = URL(string: "https://api.themoviedb.org/3/find/\(encoded)?api_key=\(key)&external_source=imdb_id&language=en-US"),
               let found = await fetch(FindResponse.self, from: findURL) {
                if let movieID = found.movie_results?.compactMap({ $0.id }).first { detailKind = "movie"; detailID = String(movieID) }
                else if let tvID = found.tv_results?.compactMap({ $0.id }).first { detailKind = "tv"; detailID = String(tvID) }
            }
        }

        // v483: If catalog/Cinemeta items do not carry a TMDB or IMDb id, use title+year search
        // so budget/revenue/runtime/studio can still appear when the user has a TMDB key.
        if detailKind == nil {
            let query = item.title.trimmingCharacters(in: .whitespacesAndNewlines)
            if !query.isEmpty, let encodedQuery = query.addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed) {
                let searchKind = isTV ? "tv" : "movie"
                let cleanYear = item.year.trimmingCharacters(in: .whitespacesAndNewlines)
                let yearParam = isTV ? "first_air_date_year" : "year"
                let yearSuffix = cleanYear.isEmpty ? "" : "&\(yearParam)=\(cleanYear)"
                if let searchURL = URL(string: "https://api.themoviedb.org/3/search/\(searchKind)?api_key=\(key)&query=\(encodedQuery)\(yearSuffix)"),
                   let search = await fetch(SearchResponse.self, from: searchURL),
                   let foundID = search.results?.compactMap({ $0.id }).first {
                    detailKind = searchKind
                    detailID = String(foundID)
                }
            }
        }

        guard let detailKind, let detailID, let url = URL(string: "https://api.themoviedb.org/3/\(detailKind)/\(detailID)?api_key=\(key)&append_to_response=release_dates,content_ratings") else { return nil }
        if detailKind == "movie", let detail = await fetch(MovieDetail.self, from: url) {
            let regions = detail.release_dates?.results ?? []
            let preferredRegion = regions.first(where: { $0.iso_3166_1?.uppercased() == "US" }) ?? regions.first
            let certification = preferredRegion?.release_dates?.compactMap { $0.certification?.trimmingCharacters(in: .whitespacesAndNewlines) }.first(where: { !$0.isEmpty })
            return PopupHeaderDetails(
                budget: detail.budget,
                revenue: detail.revenue,
                runtimeMinutes: detail.runtime,
                studio: detail.production_companies?.compactMap { $0.name?.trimmingCharacters(in: .whitespacesAndNewlines) }.first(where: { !$0.isEmpty }),
                seasons: nil,
                episodes: nil,
                status: nil,
                network: nil,
                certification: certification
            )
        }
        if detailKind == "tv", let detail = await fetch(TVDetail.self, from: url) {
            let ratings = detail.content_ratings?.results ?? []
            let preferred = ratings.first(where: { $0.iso_3166_1?.uppercased() == "US" }) ?? ratings.first
            let certification = preferred?.rating?.trimmingCharacters(in: .whitespacesAndNewlines)
            return PopupHeaderDetails(
                budget: nil,
                revenue: nil,
                runtimeMinutes: detail.episode_run_time?.first(where: { $0 > 0 }),
                studio: nil,
                seasons: detail.number_of_seasons,
                episodes: detail.number_of_episodes,
                status: detail.status,
                network: detail.networks?.compactMap { $0.name?.trimmingCharacters(in: .whitespacesAndNewlines) }.first(where: { !$0.isEmpty }),
                certification: certification
            )
        }
        return nil
    }


    private func pageSourceLinks(_ deltaPages: Int) {
        guard !activeSourceLinks.isEmpty else { linkWindowStart = 0; return }
        let pageSize = sourceIntelligencePageSize
        let maxStart = max(0, ((activeSourceLinks.count - 1) / pageSize) * pageSize)
        let newStart = min(max(linkWindowStart + (deltaPages * pageSize), 0), maxStart)
        linkWindowStart = newStart
        focus = .stream(newStart)
    }
    private func routeSourceIntelligencePanel(_ direction: SignalMoveDirection) {
        guard sourceOpeningProvider == nil else { return }
        if case .sourceProvider(let index) = focus {
            switch direction {
            case .left:
                focus = .sourceProvider(max(0, index - 1))
            case .right:
                focus = .sourceProvider(min(sourceProviderOptions.count - 1, index + 1))
            case .down:
                focus = activeSourceLinks.isEmpty ? .sourceProvider(index) : .stream(linkWindowStart)
            default:
                break
            }
            return
        }
        guard !activeSourceLinks.isEmpty else {
            focus = .sourceProvider(sourceProviderOptions.firstIndex(of: store.selectedSourceProvider) ?? 0)
            linkWindowStart = 0
            return
        }
        let firstVisible = linkWindowStart
        let lastVisible = min(linkWindowStart + visibleLinks.count - 1, activeSourceLinks.count - 1)
        let currentIndex: Int
        if case .stream(let index) = focus, index >= firstVisible, index <= lastVisible {
            currentIndex = index
        } else {
            currentIndex = min(max(sourcePanelLastFocusedIndex, firstVisible), lastVisible)
            focus = .stream(currentIndex)
        }

        switch direction {
        case .up:
            if currentIndex == firstVisible {
                focus = .sourceProvider(sourceProviderOptions.firstIndex(of: store.selectedSourceProvider) ?? 0)
            } else {
                let next = max(firstVisible, currentIndex - 1)
                sourcePanelLastFocusedIndex = next
                focus = .stream(next)
            }
        case .down:
            let next = min(lastVisible, currentIndex + 1)
            sourcePanelLastFocusedIndex = next
            focus = .stream(next)
        case .left:
            pageSourceLinks(-1)
            sourcePanelLastFocusedIndex = linkWindowStart
        case .right:
            pageSourceLinks(1)
            sourcePanelLastFocusedIndex = linkWindowStart
        default:
            break
        }
    }

    private func routeSourceConfirmation(_ direction: SignalMoveDirection) {
        // v1081: one confirmation action only. Directional input intentionally does
        // nothing; Menu/Back dismisses and restores the exact selected link.
    }

    private func route(_ direction: SignalMoveDirection) {
        UnityAnimationCoordinator.shared.registerNavigationActivity(source: "media-info", settleAfter: 0.20)
        if sourceConfirmationIndex != nil {
            routeSourceConfirmation(direction)
            return
        }
        if demoEpisodeAlertVisible {
            routeDemoEpisodeAlert(direction)
            return
        }
        if sourcePanelVisible {
            routeSourceIntelligencePanel(direction)
            return
        }
        switch direction {
        case .up:
            switch focus {
            case .play, .trailer, .findLinks, .episodes, .close: break
            case .favorite, .traktWatchlist, .follow, .testAlert: focus = .play
            case .season: focus = isSeriesItem ? .favorite : .play
            case .episode: focus = isSeriesItem ? .season(selectedSeasonIndex) : .play
            case .searchLinks, .stream, .sourceProvider: focus = .play
            case .related: focus = .favorite
            }
        case .down:
            switch focus {
            case .play, .trailer, .findLinks, .episodes, .close: focus = .favorite
            case .favorite, .traktWatchlist, .follow, .testAlert:
                if !visibleMovieFranchiseItems.isEmpty {
                    ensureRelatedVisible(0)
                    focus = .related(0)
                } else if isSeriesItem {
                    focus = .season(selectedSeasonIndex)
                } else {
                    focus = activeSourceLinks.isEmpty ? .findLinks : .stream(linkWindowStart)
                }
            case .searchLinks:
                if !activeSourceLinks.isEmpty { focus = .stream(linkWindowStart) }
            case .sourceProvider(let index):
                focus = activeSourceLinks.isEmpty ? .sourceProvider(index) : .stream(linkWindowStart)
            case .stream(let index):
                let previous = max(0, index - 1)
                focus = .stream(previous)
                ensureLinkVisible(previous)
            case .season:
                focus = filteredEpisodeItems.isEmpty ? .episodes : .episode(0)
            case .episode:
                // v524: bottom related poster rail removed; stay on the episode row.
                break
            case .related:
                if isSeriesItem { focus = .season(selectedSeasonIndex) }
            }
        case .left:
            switch focus {
            case .play: break
            case .favorite: break
            case .traktWatchlist: focus = .favorite
            case .follow: focus = TraktSyncManager.shared.isConnected ? .traktWatchlist : .favorite
            case .testAlert: focus = .follow
            case .trailer: focus = .play
                        case .findLinks: focus = .trailer
            case .episodes: focus = .findLinks
            case .close: focus = isSeriesItem ? .trailer : .findLinks
            case .searchLinks: focus = .findLinks
            case .season(let index):
                let prev = max(0, index - 1)
                selectedSeasonNumber = seasonNumbers[prev]
                episodeWindowStart = 0
                focus = .season(prev)
            case .stream:
                pageSourceLinks(-1)
            case .sourceProvider(let index):
                focus = .sourceProvider(max(0, index - 1))
            case .episode(let index):
                if index <= 0 { focus = .season(selectedSeasonIndex) } else { let previous = index - 1; focus = .episode(previous); ensureEpisodeVisible(previous) }
            case .related(let index):
                let previous = max(0, index - 1)
                focus = .related(previous)
                ensureRelatedVisible(previous)
            }
        case .right:
            switch focus {
            case .play: focus = .trailer
            case .favorite:
                focus = TraktSyncManager.shared.isConnected ? .traktWatchlist : (isSeriesItem ? .follow : .favorite)
            case .traktWatchlist:
                focus = isSeriesItem ? .follow : .traktWatchlist
            case .follow: break
            case .testAlert: break
            case .trailer: focus = isSeriesItem ? .trailer : .findLinks
                        case .findLinks: break
            case .episodes: break
            case .close: focus = episodesVisible ? .season(selectedSeasonIndex) : (activeSourceLinks.isEmpty ? .findLinks : .stream(linkWindowStart))
            case .season(let index):
                let next = min(max(seasonNumbers.count - 1, 0), index + 1)
                selectedSeasonNumber = seasonNumbers[next]
                episodeWindowStart = 0
                focus = .season(next)
            case .searchLinks:
                if !activeSourceLinks.isEmpty { ensureLinkVisible(linkWindowStart); focus = .stream(linkWindowStart) }
            case .stream:
                pageSourceLinks(1)
            case .sourceProvider(let index):
                focus = .sourceProvider(min(sourceProviderOptions.count - 1, index + 1))
            case .episode(let index):
                let next = min(max(filteredEpisodeItems.count - 1, 0), index + 1)
                focus = .episode(next)
                ensureEpisodeVisible(next)
            case .related(let index):
                let next = min(max(item.franchiseItems.count - 1, 0), index + 1)
                focus = .related(next)
                ensureRelatedVisible(next)
            }
        default: break
        }
    }

    private func ensureRelatedVisible(_ absoluteIndex: Int) {
        let franchiseSource = item.franchiseItems
        guard !franchiseSource.isEmpty else { relatedWindowStart = 0; return }
        let clamped = min(max(absoluteIndex, 0), franchiseSource.count - 1)
        if clamped < relatedWindowStart {
            relatedWindowStart = clamped
        } else if clamped >= relatedWindowStart + 5 {
            relatedWindowStart = max(0, clamped - 4)
        }
    }

    private func playTrailerUsingSelectedMode() {
        // v1059: Built-in Trailer is the only trailer surface. It never launches an external app,
        // and playback begins only after the resolver verifies a complete muxed audio/video asset.
        detailActionTask?.cancel()
        detailActionTask = VODExclusiveWorkRegistry.start(allowDuringExclusivePlayback: playbackBrowseMode) {
            let requestedID = item.id
            await MainActor.run {
                trailerPopup = false
                trailerURL = nil
                trailerResolving = true
                store.cancelFocusedCardPreviewDiskStage()
                if trailerAuxiliarySuppressionID == nil {
                    trailerAuxiliarySuppressionID = beginTrailerExclusivePlayback(reason: "full trailer resolve")
                }
                store.lastStreamMessage = "Loading trailer for \(item.title)…"
            }
            if let url = await store.resolvePlayableTrailerURL(for: item) {
                // vBRDC015: retain the vBRDC014 focused-preview suppression for the entire
                // full-trailer resolve/playback session. Full trailer owns the decoder lane.
                await MainActor.run {
                    guard requestedID == item.id else {
                        endTrailerExclusivePlayback(trailerAuxiliarySuppressionID)
                        trailerAuxiliarySuppressionID = nil
                        return
                    }
                    trailerResolving = false
                    trailerURL = url
                    trailerPopup = true
                }
            } else {
                await MainActor.run {
                    trailerResolving = false
                    endTrailerExclusivePlayback(trailerAuxiliarySuppressionID)
                    trailerAuxiliarySuppressionID = nil
                    store.status = "No complete built-in trailer is ready yet."
                }
            }
        }
    }


    private func ensureLinkVisible(_ absoluteIndex: Int) {
        guard !activeSourceLinks.isEmpty else { linkWindowStart = 0; return }
        let clamped = min(max(absoluteIndex, 0), activeSourceLinks.count - 1)
        if clamped < linkWindowStart {
            linkWindowStart = clamped
        } else if clamped >= linkWindowStart + sourceIntelligencePageSize {
            linkWindowStart = max(0, clamped - sourceIntelligencePageSize + 1)
        }
    }

    private func ensureEpisodeVisible(_ absoluteIndex: Int) {
        guard !filteredEpisodeItems.isEmpty else { episodeWindowStart = 0; return }
        let clamped = min(max(absoluteIndex, 0), filteredEpisodeItems.count - 1)
        if clamped < episodeWindowStart {
            episodeWindowStart = clamped
        } else if clamped >= episodeWindowStart + connectedPopupEpisodePageSize {
            episodeWindowStart = max(0, clamped - connectedPopupEpisodePageSize + 1)
        }
    }

    // v1154: Source Intelligence is allowed to hydrate a movie to a stronger resolver
    // identity for link discovery, but selecting a different source must not create a new
    // playback/resume identity. Movies therefore launch from the original Media Information
    // item and only inherit non-identity artwork/credit metadata from the resolver item.
    // Exact TV episodes still launch from the selected episode item so S/E identity is kept.
    private func sourceSelectedPlaybackItem() -> MediaItem {
        // vBRDC159: Source Intelligence must launch from the *presentation-restored* Media
        // Information object, not the original lightweight Search/Favorites shell captured
        // when the popup first mounted. This preserves a clearlogo learned moments later by
        // TMDB/Cinemeta all the way into full-screen VOD without changing resume identity.
        let presentationBase = store.presentationArtworkRestoredItem(from: item)
        guard let resolved = sourceSearchItem else { return presentationBase }
        let lower = resolved.type.lowercased()
        let isEpisode = resolved.seasonNumber != nil
            || resolved.episodeNumber != nil
            || lower.contains("episode")
        if isEpisode { return store.presentationArtworkRestoredItem(from: resolved) }

        var anchored = presentationBase
        if anchored.posterURL?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ?? true { anchored.posterURL = resolved.posterURL }
        if anchored.landscapeURL?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ?? true { anchored.landscapeURL = resolved.landscapeURL }
        if anchored.logoURL?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ?? true { anchored.logoURL = resolved.logoURL }
        if anchored.cast.isEmpty { anchored.cast = resolved.cast }
        if anchored.directors.isEmpty { anchored.directors = resolved.directors }
        if anchored.castMembers.isEmpty { anchored.castMembers = resolved.castMembers }
        return store.presentationArtworkRestoredItem(from: anchored)
    }

    private func launchConfirmedSource(at index: Int) {
        guard sourceOpeningProvider == nil else { return }
        guard activeSourceLinks.indices.contains(index) else { return }
        sourcePanelLastFocusedIndex = index
        ensureLinkVisible(index)
        let link = activeSourceLinks[index]
            if link.isDirectPlayable, let url = CatalogStore.makePlayableURL(from: link.url) {
                store.cancelCurrentStreamSearch(reason: "Source selected; background resolving stopped.")
                var playbackItem = sourceSelectedPlaybackItem()
                // v884: when launching a TV episode, keep playback metadata for the selected
                // episode, but force the VOD overlay artwork card to use the parent show's
                // main portrait poster. This prevents episode landscape stills from appearing
                // in the poster slot during series playback.
                if sourceSearchItem != nil,
                   (playbackItem.seasonNumber != nil || playbackItem.episodeNumber != nil || playbackItem.type.lowercased().contains("episode")) {
                    if let showPoster = item.posterURL?.trimmingCharacters(in: .whitespacesAndNewlines), !showPoster.isEmpty {
                        playbackItem.posterURL = showPoster
                    }
                    if (playbackItem.logoURL?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ?? true),
                       let showLogo = item.logoURL?.trimmingCharacters(in: .whitespacesAndNewlines), !showLogo.isEmpty {
                        playbackItem.logoURL = showLogo
                    }
                }
                let sourceSummary = store.preparedPlaybackTrackSummary(for: url)
                    ?? (SourceMediaTrackProbeCache.cachedSummary(for: link) ?? SourceLinkMetadataParser.summary(for: link, didProbe: true)).merged(with: SourceLinkMetadataParser.summary(for: link, didProbe: true))
                if let externalTarget = popupDefaultExternalTarget(for: playbackItem) {
                    sourceOpeningProvider = link.providerDisplay
                    isFindingLinks = true
                    store.lastStreamMessage = "Opening \(playbackItem.title) in \(externalTarget.rawValue)…"
                    store.status = "Opening \(playbackItem.title) in \(externalTarget.rawValue)…"
                    guard let externalStreamURL = MediaFlowProxyRouter.playbackURLIfAllowed(for: url, kind: .vod, upstreamHeaders: link.requestHeaders.playbackHTTPHeaderDictionary) else {
                        store.status = "MediaFlow Proxy is enabled but the selected source could not be routed through the configured home proxy."
                        store.lastStreamMessage = store.status
                        isFindingLinks = false
                        sourceOpeningProvider = nil
                        return
                    }
                    ExternalPlayerLauncher.open(externalTarget, streamURL: externalStreamURL, title: playbackItem.title, subtitles: store.subtitleURLs(from: link).map(\.absoluteString)) { message in
                        store.status = message
                        store.lastStreamMessage = message
                        isFindingLinks = false
                        sourceOpeningProvider = nil
                    }
                } else {
                    if sourceSummary.dolbyVisionProfile == "5" {
                        sourceOpeningProvider = nil
                        isFindingLinks = false
                        store.lastStreamMessage = "This Dolby Vision Profile 5 source may not render correctly with the internal player. Try another source."
                        store.status = store.lastStreamMessage
                        return
                    }
                    sourceOpeningProvider = link.providerDisplay
                    isFindingLinks = true
                    store.lastStreamMessage = "Opening Stream… \(link.providerDisplay)"
                    store.status = "Opening Stream… \(link.providerDisplay)"
                    // vBRDC233 Nuvio-style zero-delay handoff: do not intentionally render an
                    // intermediate 550 ms "Opening Stream" state. The ReadyPlaybackSource was
                    // already built while links were visible, so route to the player now.
                    guard playbackBrowseWorkAllowed else { return }
                    guard sourceOpeningProvider != nil else { return }
                    sourceResolveTask?.cancel()
                    store.cancelCurrentStreamSearch(reason: "Selected source is opening; Source Intelligence results stay open for return.", publishState: false)
                    sourcePanelVisible = true
                    focus = .stream(sourcePanelLastFocusedIndex)
                    store.startPlayback(
                        item: playbackItem,
                        url: url,
                        label: "Opening selected stream: \(link.vodLinkPrimaryLine) • \(link.vodLinkDetailLine). Adaptive fallback is armed across all direct playable links.",
                        sourceTrackSummary: sourceSummary
                    )
                    // Persist source affinity only after the playback route is published so
                    // UserDefaults/disk bookkeeping can never hold frame #1 behind the link tap.
                    DispatchQueue.main.async {
                        PerTitlePlaybackMemoryManager.shared.rememberSource(link, for: playbackItem)
                        LastPlaybackLinkCacheManager.shared.save(item: playbackItem, link: link, url: url)
                    }
                }
            } else if link.isTorBoxUsenetCandidate || link.infoHash?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false {
                let isTorBoxUsenet = link.isTorBoxUsenetCandidate
                sourceOpeningProvider = link.providerDisplay
                isFindingLinks = true
                store.lastStreamMessage = isTorBoxUsenet ? "Preparing selected TorBox Usenet source…" : "Resolving selected debrid stream…"
                store.status = store.lastStreamMessage
                VODExclusiveWorkRegistry.start(allowDuringExclusivePlayback: playbackBrowseMode) {
                    guard let url = await store.resolvePlayableURL(for: link) else {
                        sourceOpeningProvider = nil
                        isFindingLinks = false
                        if isTorBoxUsenet {
                            if !store.status.localizedCaseInsensitiveContains("torbox") {
                                store.status = "TorBox could not prepare this Usenet source. Try another source or check TorBox Downloads."
                            }
                        } else {
                            store.status = "This debrid link could not be resolved. Try another source."
                        }
                        return
                    }
                    var playbackItem = sourceSelectedPlaybackItem()
                    if sourceSearchItem != nil,
                       (playbackItem.seasonNumber != nil || playbackItem.episodeNumber != nil || playbackItem.type.lowercased().contains("episode")) {
                        if let showPoster = item.posterURL?.trimmingCharacters(in: .whitespacesAndNewlines), !showPoster.isEmpty { playbackItem.posterURL = showPoster }
                        if (playbackItem.logoURL?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ?? true),
                           let showLogo = item.logoURL?.trimmingCharacters(in: .whitespacesAndNewlines), !showLogo.isEmpty { playbackItem.logoURL = showLogo }
                    }
                    sourceResolveTask?.cancel()
                    store.cancelCurrentStreamSearch(reason: "Selected source is opening; Source Intelligence results stay open for return.", publishState: false)
                    sourcePanelVisible = true
                    focus = .stream(sourcePanelLastFocusedIndex)
                    PerTitlePlaybackMemoryManager.shared.rememberSource(link, for: playbackItem)
                    store.startPlayback(item: playbackItem, url: url, alternates: store.playableURLs(from: activeSourceLinks, selected: link), subtitles: store.subtitleURLs(from: link), headers: link.requestHeaders.playbackHTTPHeaderDictionary, fallbackHeaders: store.playbackHeaderMap(from: activeSourceLinks), label: isTorBoxUsenet ? "Opening selected TorBox Usenet stream: \(link.vodLinkPrimaryLine) • \(link.vodLinkDetailLine)." : "Opening selected debrid stream: \(link.vodLinkPrimaryLine) • \(link.vodLinkDetailLine).", sourceTrackSummary: SourceLinkMetadataParser.summary(for: link, didProbe: true), adaptiveCacheHint: link.sourceIntelligenceAdaptiveCacheHint)
                    isFindingLinks = false
                    sourceOpeningProvider = nil
                }
            } else {
                sourceOpeningProvider = nil
                store.status = "This link is not direct-playable yet. A resolver service is needed for magnet/infoHash/debrid-only links."
            }
    }

    private func activateDebounced() {
        let now = Date().timeIntervalSinceReferenceDate
        guard sourceOpeningProvider == nil else { return }
        guard now - lastActionAt > 0.36 else { return }
        lastActionAt = now
        activate()
    }

    private func activate() {
        if let index = sourceConfirmationIndex {
            // vBRDC021: Source Details must be completely removed before the opening
            // progress card appears. Disable the confirmation-card removal animation for
            // this Play Source handoff so its dark/shadowed rectangle cannot linger for a
            // transition frame behind “Opening Stream…”. The selected source state is kept.
            var transaction = Transaction(animation: nil)
            transaction.disablesAnimations = true
            withTransaction(transaction) {
                sourceConfirmationIndex = nil
            }
            DispatchQueue.main.async {
                launchConfirmedSource(at: index)
            }
            return
        }
        if demoEpisodeAlertVisible {
            activateDemoEpisodeAlert()
            return
        }
        switch focus {
        case .play:
            detailActionTask?.cancel()
            detailActionTask = VODExclusiveWorkRegistry.start(allowDuringExclusivePlayback: playbackBrowseMode) {
                isFindingLinks = true
                await store.playFirstDirectStream(for: item)
                if playbackBrowseWorkAllowed { isFindingLinks = false }
            }
        case .trailer:
            playTrailerUsingSelectedMode()
        case .findLinks, .searchLinks:
            sourceSearchItem = item
            store.selectedSourceProvider = "All Providers"
            sourcePanelVisible = true
            isFindingLinks = true
            linkWindowStart = 0
            sourcePanelLastFocusedIndex = 0
            focus = .sourceProvider(sourceProviderOptions.firstIndex(of: store.selectedSourceProvider) ?? 0)
            sourceResolveTask?.cancel()
            store.cancelCurrentStreamSearch(reason: "New source search started; previous provider resolve cancelled.")
            sourceResolveTask = VODExclusiveWorkRegistry.start(allowDuringExclusivePlayback: playbackBrowseMode) {
                // vBRDC212: race providers immediately with the identity already on screen.
                // Metadata hydration runs beside that race instead of in front of it. If the
                // exact identity has links, cancel the resolver. If it has none, the stronger
                // identity is usually already waiting and can start fallback providers at once.
                let resolverTask = Task { @MainActor in
                    await store.resolverReadyStreamItem(for: item, tmdbApiKey: popupTMDBApiKey, publishStatus: false)
                }
                let fastResult = await store.findStreamsForcePopulated(
                    for: item,
                    fallbackItem: nil,
                    providerFilter: store.selectedSourceProvider
                )
                guard !Task.isCancelled else {
                    resolverTask.cancel()
                    return
                }
                if fastResult.isEmpty {
                    let resolverItem = await resolverTask.value
                    guard !Task.isCancelled, sourceSearchItem?.id == item.id || sourceSearchItem?.id == resolverItem.id else { return }
                    sourceSearchItem = resolverItem
                    if resolverItem != item {
                        _ = await store.findStreamsForcePopulated(
                            for: resolverItem,
                            fallbackItem: item,
                            providerFilter: store.selectedSourceProvider
                        )
                    }
                } else {
                    resolverTask.cancel()
                }
                guard !Task.isCancelled else { return }
                isFindingLinks = false
                linkWindowStart = 0
                sourcePanelLastFocusedIndex = 0
                sourcePanelVisible = true
                if !activeSourceLinks.isEmpty { focus = .stream(0) }
            }
        case .episodes:
            VODExclusiveWorkRegistry.start(allowDuringExclusivePlayback: playbackBrowseMode) {
                isLoadingEpisodes = true
                if episodeItems.isEmpty {
                    episodeItems = await store.fetchSeriesEpisodes(for: item)
                }
                isLoadingEpisodes = false
                episodesVisible = true
                selectedSeasonNumber = seasonNumbers.first ?? 1
                seasonDropdownOpen = true
                episodeWindowStart = 0
                focus = episodeItems.isEmpty ? .episodes : .season(selectedSeasonIndex)
            }
        case .close:
            store.closeDetail()
        case .favorite:
            togglePopupFavorite()
        case .traktWatchlist:
            toggleTraktWatchlist()
        case .follow:
            if isSeriesItem { toggleFollowShow() }
        case .testAlert:
            break
        case .stream(let index):
            guard sourceOpeningProvider == nil else { return }
            guard activeSourceLinks.indices.contains(index) else { return }
            sourcePanelLastFocusedIndex = index
            ensureLinkVisible(index)
            sourceConfirmationIndex = index
        case .sourceProvider(let index):
            guard sourceProviderOptions.indices.contains(index) else { return }
            selectSourceProvider(sourceProviderOptions[index])
        case .season(let index):
            guard seasonNumbers.indices.contains(index) else { return }
            selectedSeasonNumber = seasonNumbers[index]
            seasonDropdownOpen = true
            episodeWindowStart = 0
            focus = filteredEpisodeItems.isEmpty ? .season(index) : .episode(0)
        case .episode(let index):
            guard filteredEpisodeItems.indices.contains(index) else { return }
            openSourceIntelligenceForEpisode(filteredEpisodeItems[index], emptyFocus: .episode(index))
        case .related(let index):
            guard item.franchiseItems.indices.contains(index) else { return }
            store.openDetail(item.franchiseItems[index], pushCurrent: true)
        }
    }
}

struct DetailPage: View {
    @EnvironmentObject var store: CatalogStore
    let item: MediaItem
    @FocusState private var canvasFocused: Bool
    @State private var focus: DetailNode = .play
    @State private var trailerPopup = false
    @State private var trailerURL: URL? = nil
    @State private var trailerResolving = false
    @State private var trailerAuxiliarySuppressionID: UUID? = nil
    @State private var isFindingLinks = false
    @State private var isLoadingEpisodes = false
    @State private var episodeItems: [MediaItem] = []
    @State private var episodesVisible = false
    @State private var episodeWindowStart: Int = 0
    @State private var selectedSeasonNumber: Int = 1
    @State private var seasonDropdownOpen = false
    @State private var lastRemoteActionAt: TimeInterval = 0
    @State private var linkWindowStart: Int = 0
    @State private var sourcePanelVisible = false
    @State private var sourcePanelLastFocusedIndex: Int = 0
    @StateObject private var detailPageAsyncRuntime = DetailPageAsyncTaskRuntime()
    private var sourceResolveTask: Task<Void, Never>? {
            get { detailPageAsyncRuntime.sourceResolveTask }
            nonmutating set { detailPageAsyncRuntime.sourceResolveTask = newValue }
        }
    private var detailActionTask: Task<Void, Never>? {
            get { detailPageAsyncRuntime.detailActionTask }
            nonmutating set { detailPageAsyncRuntime.detailActionTask = newValue }
        }
    @State private var sourceSearchItem: MediaItem? = nil
    @State private var demoEpisodeAlertVisible: Bool = false
    @State private var demoEpisodeAlertFocus: Int = 0
    @State private var demoEpisodeAlertItem: MediaItem? = nil
    @AppStorage("popupFontPreset") private var popupFontPreset: String = "SF Rounded"
    @AppStorage("tmdbApiKey") private var popupTMDBApiKey: String = ""
    @State private var popupHeaderDetails: PopupHeaderDetails? = nil
    // v617: prevent Details Stage from showing a naked full-bright artwork frame before
    // the cinematic dim/gradient stack is ready. The backdrop fades in only after the
    // stage is mounted behind a black pre-dim layer.
    @State private var stageBackdropVisible: Bool = false

    private let sourceIntelligencePageSize = 5

    enum DetailNode: Hashable {
        case play, trailer, findLinks, episodes, close, searchLinks, favorite, traktWatchlist, follow, testAlert
        case sourceProvider(Int)
        case stream(Int)
        case season(Int)
        case episode(Int)
        case related(Int)
    }

    var relatedItems: [MediaItem] {
        let allRows = store.rows
        let all = allRows.flatMap { $0.items }
        let sameGenre = all.filter { $0.id != item.id && (!$0.genres.isEmpty && !Set($0.genres).isDisjoint(with: Set(item.genres))) }
        let fallback = all.filter { $0.id != item.id }
        return Array((sameGenre.isEmpty ? fallback : sameGenre).prefix(8))
    }

    let maxVisibleStreamLinks = 5
    let maxVisibleEpisodes = 6

    private var isSeriesItem: Bool {
        let lower = item.type.lowercased()
        return lower.contains("series") || lower.contains("show")
    }

    var seasonNumbers: [Int] {
        let values = Set(episodeItems.compactMap { s in let n = s.seasonNumber ?? 1; return n > 0 ? n : nil })
        return values.isEmpty ? [selectedSeasonNumber] : values.sorted()
    }

    var selectedSeasonIndex: Int {
        seasonNumbers.firstIndex(of: selectedSeasonNumber) ?? 0
    }

    var filteredEpisodeItems: [MediaItem] {
        episodeItems.filter {
            let season = $0.seasonNumber ?? 1
            return season > 0 && season == selectedSeasonNumber
        }
    }

    var visibleEpisodeItems: [MediaItem] {
        Array(filteredEpisodeItems.dropFirst(episodeWindowStart).prefix(maxVisibleEpisodes))
    }

    var visibleLinks: [StreamLink] {
        Array(store.streamLinks.dropFirst(linkWindowStart).prefix(maxVisibleStreamLinks))
    }

    var body: some View {
        ZStack(alignment: .topLeading) {
            DetailBackdropArtwork(item: item)
                .ignoresSafeArea()
                .overlay(Color.black.opacity(0.28))
                .overlay(LinearGradient(colors: [.black.opacity(0.78), .black.opacity(0.20), .black.opacity(0.62)], startPoint: .leading, endPoint: .trailing))
                .overlay(LinearGradient(colors: [.clear, .black.opacity(0.78)], startPoint: .top, endPoint: .bottom))

            VStack(alignment: .leading, spacing: 24) {
                Spacer().frame(height: 250)

                // v251: detail page keeps themed artwork logos static; popup removed fallback text logos/pulse.
                HeroLogoText(item: item)
                    .frame(width: 780, height: 132, alignment: .leading)
                    .padding(.leading, 84)

                HStack(spacing: 30) {
                    Text(item.genres.first?.uppercased() ?? item.type.uppercased())
                    Text(item.year)
                    Text(item.type.uppercased())
                    Text("152min")
                    Text("🍅 80%")
                    Text("🍿 82%")
                    Text("★ \(item.rating)")
                }
                .font(.system(size: 28, weight: .bold))
                .foregroundStyle(.white.opacity(0.86))
                .padding(.leading, 84)

                HStack(spacing: 22) {
                    ManualDetailButton(title: "PLAY", icon: "play.fill", selected: focus == .play)
                    ManualDetailButton(title: trailerResolving ? "LOADING" : "TRAILER", icon: "film.fill", selected: focus == .trailer, blackBlueGlow: true)
                            ManualDetailButton(title: isFindingLinks ? "FINDING" : "FIND LINKS", icon: "link", selected: focus == .findLinks, blackBlueGlow: true)
                    if isSeriesItem {
                        ManualDetailButton(title: isLoadingEpisodes ? "LOADING" : "EPISODES", icon: "list.bullet.rectangle", selected: focus == .episodes)
                    }
                }
                .padding(.leading, 84)

                Text(streamStatusText(store.lastStreamMessage))
                    .font(.system(size: 20, weight: .semibold))
                    .foregroundStyle(.white.opacity(0.72))
                    .padding(.leading, 84)
                    .frame(width: 980, alignment: .leading)

                if episodesVisible {
                    ManualEpisodesRow(focus: focus, visibleEpisodes: visibleEpisodeItems, episodeWindowStart: episodeWindowStart, totalEpisodeCount: filteredEpisodeItems.count, seasonNumbers: seasonNumbers, selectedSeasonNumber: selectedSeasonNumber, seasonDropdownOpen: seasonDropdownOpen)
                        .padding(.leading, 84)
                }

                ManualStreamLinksRow(focus: focus, visibleLinks: visibleLinks, linkWindowStart: linkWindowStart, totalLinkCount: store.streamLinks.count)
                    .padding(.leading, 84)

                Spacer()

                VStack(alignment: .leading, spacing: 12) {
                    ManualRelatedRow(focus: focus, relatedItems: relatedItems, compact: true)
                }
                .foregroundStyle(.white)
                .padding(.leading, 84)
                .padding(.bottom, 46)
            }

            VStack(alignment: .leading, spacing: 14) {
                Text(item.description)
                    .font(.system(size: 16, weight: .semibold))
                    .lineLimit(nil)
                    .fixedSize(horizontal: false, vertical: true)
                    .foregroundStyle(Color.orange.opacity(0.98))
                CastCreditsSummary(item: item, compact: false)
            }
            .font(.system(size: 14, weight: .medium))
            .foregroundStyle(.white.opacity(0.80))
            .padding(16)
            .frame(width: 430, alignment: .leading)
            .frame(minHeight: 248, alignment: .leading)
            .background(.ultraThinMaterial.opacity(0.46), in: RoundedRectangle(cornerRadius: 24))
            .overlay(RoundedRectangle(cornerRadius: 24).stroke(.white.opacity(0.14), lineWidth: 1))
            // v160: mathematically pinned beside the stream-link arrow area, moved a half-inch right from v159.
            .position(x: 1238, y: 622)

            if trailerPopup, let trailerURL {
                TrailerPopup(url: trailerURL, audioURL: store.resolvedTrailerAudioURL, requestHeaders: store.resolvedTrailerHTTPHeaders, sessionKey: "\(item.id)|\(item.title)|\(trailerURL.absoluteString)") {
                    trailerPopup = false
                    self.trailerURL = nil
                    endTrailerExclusivePlayback(trailerAuxiliarySuppressionID)
                    trailerAuxiliarySuppressionID = nil
                    canvasFocused = true
                }
                .zIndex(10)
            }
        }
        .focusable(true)
        .focused($canvasFocused)
        .onAppear {
            canvasFocused = true
            focus = .play
            trailerPopup = false
            trailerURL = nil
            trailerResolving = false
        }
        .onChange(of: item.id) { _ in
            endTrailerExclusivePlayback(trailerAuxiliarySuppressionID)
            trailerAuxiliarySuppressionID = nil
            trailerPopup = false
            trailerURL = nil
            trailerResolving = false
        }
        .onTapGesture { activateFocusedNodeDebounced() }
        .signalVisionPlayPauseCommand { activateFocusedNodeDebounced() }
        .signalMoveCommand { direction in
            route(direction)
        }
        .task(id: item.id) {
            // v503: keep Details/Search popup instant. Trailer resolving starts only
            // when the built-in Trailer action is selected.
            trailerPopup = false
            trailerURL = nil
        }
        .onDisappear {
            sourceResolveTask?.cancel()
            detailActionTask?.cancel()
            endTrailerExclusivePlayback(trailerAuxiliarySuppressionID)
            trailerAuxiliarySuppressionID = nil
            if store.playbackURL != nil {
                store.cancelCurrentStreamSearch(reason: "Legacy Details unmounted for VOD Exclusive Mode.", publishState: false)
            }
        }
        .signalVisionExitCommand {
            if trailerPopup {
                trailerPopup = false
                trailerURL = nil
                endTrailerExclusivePlayback(trailerAuxiliarySuppressionID)
                trailerAuxiliarySuppressionID = nil
            } else {
                store.closeDetail()
            }
        }
    }


    private func makeDemoEpisodeAlertItem() -> MediaItem {
        let season = selectedSeasonNumber <= 0 ? 1 : selectedSeasonNumber
        let episodeNumber = 1
        let baseID = item.id.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? item.title : item.id
        return MediaItem(
            id: "\(baseID):\(season):\(episodeNumber)",
            tmdbId: item.tmdbId,
            imdbId: item.imdbId,
            tvdbId: item.tvdbId,
            title: "\(item.title) S\(String(format: "%02d", season))E\(String(format: "%02d", episodeNumber))",
            year: item.year,
            type: "series",
            catalog: item.catalog,
            description: "Demo verified new-episode alert. This uses the same popup, focus buttons, and Source Intelligence path that a real new episode alert will use.",
            genres: item.genres,
            rating: item.rating,
            posterURL: item.posterURL,
            landscapeURL: item.landscapeURL,
            logoURL: item.logoURL,
            previewURL: item.previewURL,
            addonName: item.addonName,
            addonIconURL: item.addonIconURL,
            seasonNumber: season,
            episodeNumber: episodeNumber,
            cast: [],
            directors: [],
            castMembers: []
        )
    }

    private func showTestNewEpisodeAlert() {
        VODExclusiveWorkRegistry.start {
            if episodeItems.isEmpty {
                await MainActor.run { isLoadingEpisodes = true }
                let fetched = await store.fetchSeriesEpisodes(for: item)
                await MainActor.run {
                    episodeItems = fetched
                    isLoadingEpisodes = false
                }
            }
            await MainActor.run {
                let preferred = dcNextUpcomingEpisodeAlertItem(parent: item, episodes: episodeItems, fallback: makeDemoEpisodeAlertItem())
                demoEpisodeAlertItem = preferred
                demoEpisodeAlertFocus = 0
                demoEpisodeAlertVisible = true
                sourcePanelVisible = false
                store.status = "Showing test new-episode alert for \(preferred.title)"
            }
        }
    }

    private func runDemoAlertFindLinks() {
        let episode = demoEpisodeAlertItem ?? makeDemoEpisodeAlertItem()
        demoEpisodeAlertVisible = false
        sourceSearchItem = episode
        store.selectedSourceProvider = "All Providers"
        sourcePanelVisible = true
        linkWindowStart = 0
        sourcePanelLastFocusedIndex = 0
        focus = .testAlert
        sourceResolveTask?.cancel()
        store.cancelCurrentStreamSearch(reason: "Episode changed; previous provider resolve cancelled.")
        sourceResolveTask = VODExclusiveWorkRegistry.start {
            isFindingLinks = true
            _ = await store.findStreams(for: episode)
            guard !Task.isCancelled, sourceSearchItem?.id == episode.id else { return }
            isFindingLinks = false
            linkWindowStart = 0
            sourcePanelLastFocusedIndex = 0
            if !store.streamLinks.isEmpty { focus = .stream(0) }
        }
    }

    private func routeDemoEpisodeAlert(_ direction: SignalMoveDirection) {
        switch direction {
        case .left:
            demoEpisodeAlertFocus = max(0, demoEpisodeAlertFocus - 1)
        case .right:
            demoEpisodeAlertFocus = min(3, demoEpisodeAlertFocus + 1)
        case .up, .down:
            break
        default:
            break
        }
    }

    private func activateDemoEpisodeAlert() {
        switch demoEpisodeAlertFocus {
        case 0:
            let episode = demoEpisodeAlertItem ?? makeDemoEpisodeAlertItem()
            demoEpisodeAlertVisible = false
            detailActionTask?.cancel()
            detailActionTask = VODExclusiveWorkRegistry.start {
                isFindingLinks = true
                await store.playFirstDirectStream(for: episode)
                if !VODExclusivePlaybackGate.isActive { isFindingLinks = false }
            }
        case 1:
            runDemoAlertFindLinks()
        case 2:
            demoEpisodeAlertVisible = false
            focus = .testAlert
        default:
            demoEpisodeAlertVisible = false
            focus = .testAlert
            store.status = "Test alert marked seen"
        }
    }

    private func loadPopupHeaderDetails() {
        let key = popupTMDBApiKey.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !key.isEmpty else { return }
        if let cached = PopupHeaderDetailsService.shared.cached(for: item) {
            popupHeaderDetails = cached
            return
        }
        let currentID = item.id
        VODExclusiveWorkRegistry.start {
            if let details = await PopupHeaderDetailsService.shared.details(for: item, apiKey: key), item.id == currentID {
                popupHeaderDetails = details
            }
        }
    }

    private func fetchPopupHeaderDetails(apiKey key: String) async -> PopupHeaderDetails? {
        struct FoundItem: Decodable { let id: Int? }
        struct FindResponse: Decodable { let movie_results: [FoundItem]?; let tv_results: [FoundItem]? }
        struct SearchItem: Decodable { let id: Int? }
        struct SearchResponse: Decodable { let results: [SearchItem]? }
        struct Company: Decodable { let name: String? }
        struct Network: Decodable { let name: String? }
        struct MovieReleaseDate: Decodable { let certification: String? }
        struct MovieReleaseRegion: Decodable { let iso_3166_1: String?; let release_dates: [MovieReleaseDate]? }
        struct MovieReleaseDates: Decodable { let results: [MovieReleaseRegion]? }
        struct TVContentRating: Decodable { let iso_3166_1: String?; let rating: String? }
        struct TVContentRatings: Decodable { let results: [TVContentRating]? }
        struct MovieDetail: Decodable { let budget: Int?; let revenue: Int?; let runtime: Int?; let production_companies: [Company]?; let release_dates: MovieReleaseDates? }
        struct TVDetail: Decodable { let episode_run_time: [Int]?; let number_of_seasons: Int?; let number_of_episodes: Int?; let status: String?; let networks: [Network]?; let content_ratings: TVContentRatings? }

        func fetch<T: Decodable>(_ type: T.Type, from url: URL) async -> T? {
            do {
                let (data, response) = try await URLSession.shared.data(from: url)
                if let http = response as? HTTPURLResponse, !(200..<300).contains(http.statusCode) { return nil }
                return try JSONDecoder().decode(T.self, from: data)
            } catch { return nil }
        }

        let normalizedType = item.type.lowercased()
        let isTV = normalizedType.contains("series") || normalizedType.contains("show") || normalizedType.contains("tv")
        let parts = item.id.split(separator: ":").map(String.init)
        var detailKind: String? = nil
        var detailID: String? = nil

        if parts.count >= 3, parts[0].lowercased() == "tmdb" {
            detailKind = (parts[1].lowercased() == "tv" || isTV) ? "tv" : "movie"
            detailID = parts[2]
        } else {
            let imdbID: String? = {
                if item.id.lowercased().hasPrefix("tt") { return item.id }
                if let match = item.id.range(of: #"tt\d{6,}"#, options: .regularExpression) { return String(item.id[match]) }
                return nil
            }()
            if let imdbID, let encoded = imdbID.addingPercentEncoding(withAllowedCharacters: .urlPathAllowed),
               let findURL = URL(string: "https://api.themoviedb.org/3/find/\(encoded)?api_key=\(key)&external_source=imdb_id"),
               let found = await fetch(FindResponse.self, from: findURL) {
                if let movieID = found.movie_results?.compactMap({ $0.id }).first { detailKind = "movie"; detailID = String(movieID) }
                else if let tvID = found.tv_results?.compactMap({ $0.id }).first { detailKind = "tv"; detailID = String(tvID) }
            }
        }

        // v483: If catalog/Cinemeta items do not carry a TMDB or IMDb id, use title+year search
        // so budget/revenue/runtime/studio can still appear when the user has a TMDB key.
        if detailKind == nil {
            let query = item.title.trimmingCharacters(in: .whitespacesAndNewlines)
            if !query.isEmpty, let encodedQuery = query.addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed) {
                let searchKind = isTV ? "tv" : "movie"
                let cleanYear = item.year.trimmingCharacters(in: .whitespacesAndNewlines)
                let yearParam = isTV ? "first_air_date_year" : "year"
                let yearSuffix = cleanYear.isEmpty ? "" : "&\(yearParam)=\(cleanYear)"
                if let searchURL = URL(string: "https://api.themoviedb.org/3/search/\(searchKind)?api_key=\(key)&query=\(encodedQuery)\(yearSuffix)"),
                   let search = await fetch(SearchResponse.self, from: searchURL),
                   let foundID = search.results?.compactMap({ $0.id }).first {
                    detailKind = searchKind
                    detailID = String(foundID)
                }
            }
        }

        guard let detailKind, let detailID, let url = URL(string: "https://api.themoviedb.org/3/\(detailKind)/\(detailID)?api_key=\(key)&append_to_response=release_dates,content_ratings") else { return nil }
        if detailKind == "movie", let detail = await fetch(MovieDetail.self, from: url) {
            let regions = detail.release_dates?.results ?? []
            let preferredRegion = regions.first(where: { $0.iso_3166_1?.uppercased() == "US" }) ?? regions.first
            let certification = preferredRegion?.release_dates?.compactMap { $0.certification?.trimmingCharacters(in: .whitespacesAndNewlines) }.first(where: { !$0.isEmpty })
            return PopupHeaderDetails(
                budget: detail.budget,
                revenue: detail.revenue,
                runtimeMinutes: detail.runtime,
                studio: detail.production_companies?.compactMap { $0.name?.trimmingCharacters(in: .whitespacesAndNewlines) }.first(where: { !$0.isEmpty }),
                seasons: nil,
                episodes: nil,
                status: nil,
                network: nil,
                certification: certification
            )
        }
        if detailKind == "tv", let detail = await fetch(TVDetail.self, from: url) {
            let ratings = detail.content_ratings?.results ?? []
            let preferred = ratings.first(where: { $0.iso_3166_1?.uppercased() == "US" }) ?? ratings.first
            let certification = preferred?.rating?.trimmingCharacters(in: .whitespacesAndNewlines)
            return PopupHeaderDetails(
                budget: nil,
                revenue: nil,
                runtimeMinutes: detail.episode_run_time?.first(where: { $0 > 0 }),
                studio: nil,
                seasons: detail.number_of_seasons,
                episodes: detail.number_of_episodes,
                status: detail.status,
                network: detail.networks?.compactMap { $0.name?.trimmingCharacters(in: .whitespacesAndNewlines) }.first(where: { !$0.isEmpty }),
                certification: certification
            )
        }
        return nil
    }


    private func pageSourceLinks(_ deltaPages: Int) {
        guard !store.streamLinks.isEmpty else { linkWindowStart = 0; return }
        let pageSize = sourceIntelligencePageSize
        let maxStart = max(0, ((store.streamLinks.count - 1) / pageSize) * pageSize)
        let newStart = min(max(linkWindowStart + (deltaPages * pageSize), 0), maxStart)
        linkWindowStart = newStart
        focus = .stream(newStart)
    }
    private func route(_ direction: SignalMoveDirection) {
        UnityAnimationCoordinator.shared.registerNavigationActivity(source: "detail", settleAfter: 0.20)
        switch direction {
        case .up:
            switch focus {
            case .play, .trailer, .findLinks, .episodes, .close:
                canvasFocused = true
            case .favorite, .traktWatchlist, .follow, .testAlert:
                focus = .play
            case .searchLinks, .sourceProvider, .stream, .season, .episode:
                focus = .play
            case .related:
                focus = store.streamLinks.isEmpty ? .searchLinks : .stream(linkWindowStart)
            }
        case .down:
            switch focus {
            case .play, .trailer, .findLinks, .episodes, .close:
                focus = .searchLinks
            case .favorite, .traktWatchlist, .follow, .testAlert:
                focus = .searchLinks
            case .searchLinks:
                if !store.streamLinks.isEmpty { focus = .stream(linkWindowStart) }
            case .sourceProvider:
                focus = store.streamLinks.isEmpty ? .searchLinks : .stream(linkWindowStart)
            case .stream:
                pageSourceLinks(1)
            case .season:
                focus = filteredEpisodeItems.isEmpty ? .searchLinks : .episode(0)
            case .episode:
                focus = .related(0)
            case .related:
                break
            }
        case .left:
            switch focus {
            case .play: break
            case .favorite: focus = .play
            case .traktWatchlist: focus = .favorite
            case .follow: focus = .favorite
            case .testAlert: focus = isSeriesItem ? .follow : .favorite
            case .trailer: focus = .play
                        case .findLinks: focus = .trailer
            case .episodes: focus = .findLinks
            case .close: focus = isSeriesItem ? .trailer : .findLinks
            case .searchLinks: focus = .close
            case .season(let index):
                let prev = max(0, index - 1)
                selectedSeasonNumber = seasonNumbers[prev]
                episodeWindowStart = 0
                focus = .season(prev)
            case .stream:
                pageSourceLinks(-1)
            case .sourceProvider:
                focus = .searchLinks
            case .episode(let index):
                if index <= 0 { focus = .episodes } else {
                    let previous = index - 1
                    focus = .episode(previous)
                    ensureEpisodeVisible(previous)
                }
            case .related(let index): focus = .related(max(0, index - 1))
            }
        case .right:
            switch focus {
            case .play: focus = .trailer
            case .favorite: focus = .follow
            case .traktWatchlist: focus = .favorite
            case .follow: focus = .testAlert
            case .testAlert: focus = .trailer
            case .trailer: focus = isSeriesItem ? .trailer : .findLinks
                        case .findLinks: break
            case .episodes: break
            case .close: focus = episodesVisible ? .season(selectedSeasonIndex) : .searchLinks
            case .season(let index):
                let next = min(max(seasonNumbers.count - 1, 0), index + 1)
                selectedSeasonNumber = seasonNumbers[next]
                episodeWindowStart = 0
                focus = .season(next)
            case .searchLinks:
                if !store.streamLinks.isEmpty {
                    ensureLinkVisible(linkWindowStart)
                    focus = .stream(linkWindowStart)
                }
            case .sourceProvider:
                focus = .searchLinks
            case .stream:
                pageSourceLinks(1)
            case .episode(let index):
                let next = min(max(filteredEpisodeItems.count - 1, 0), index + 1)
                focus = .episode(next)
                ensureEpisodeVisible(next)
            case .related(let index): focus = .related(min(max(relatedItems.count - 1, 0), index + 1))
            }
        default:
            break
        }
    }

    private func playTrailerUsingSelectedMode() {
        // v1059: Built-in Trailer is the only trailer surface. It never launches an external app,
        // and playback begins only after the resolver verifies a complete muxed audio/video asset.
        VODExclusiveWorkRegistry.start {
            let requestedID = item.id
            await MainActor.run {
                trailerPopup = false
                trailerURL = nil
                trailerResolving = true
                store.cancelFocusedCardPreviewDiskStage()
                if trailerAuxiliarySuppressionID == nil {
                    trailerAuxiliarySuppressionID = beginTrailerExclusivePlayback(reason: "full trailer resolve")
                }
                store.lastStreamMessage = "Loading trailer for \(item.title)…"
            }
            if let url = await store.resolvePlayableTrailerURL(for: item) {
                // vBRDC015: retain the vBRDC014 rule: full trailer owns the decoder lane; preview stays suppressed.
                await MainActor.run {
                    guard requestedID == item.id else {
                        endTrailerExclusivePlayback(trailerAuxiliarySuppressionID)
                        trailerAuxiliarySuppressionID = nil
                        return
                    }
                    trailerResolving = false
                    trailerURL = url
                    trailerPopup = true
                }
            } else {
                await MainActor.run {
                    trailerResolving = false
                    endTrailerExclusivePlayback(trailerAuxiliarySuppressionID)
                    trailerAuxiliarySuppressionID = nil
                    store.status = "No complete built-in trailer is ready yet."
                }
            }
        }
    }


    private func ensureLinkVisible(_ absoluteIndex: Int) {
        guard !store.streamLinks.isEmpty else { linkWindowStart = 0; return }
        let clamped = min(max(absoluteIndex, 0), store.streamLinks.count - 1)
        if clamped < linkWindowStart {
            linkWindowStart = clamped
        } else if clamped >= linkWindowStart + maxVisibleStreamLinks {
            linkWindowStart = max(0, clamped - maxVisibleStreamLinks + 1)
        }
    }

    private func ensureEpisodeVisible(_ absoluteIndex: Int) {
        guard !filteredEpisodeItems.isEmpty else { episodeWindowStart = 0; return }
        let clamped = min(max(absoluteIndex, 0), filteredEpisodeItems.count - 1)
        if clamped < episodeWindowStart {
            episodeWindowStart = clamped
        } else if clamped >= episodeWindowStart + maxVisibleEpisodes {
            episodeWindowStart = max(0, clamped - maxVisibleEpisodes + 1)
        }
    }

    private func activateFocusedNodeDebounced() {
        let now = Date().timeIntervalSinceReferenceDate
        guard now - lastRemoteActionAt > 0.38 else { return }
        lastRemoteActionAt = now
        activateFocusedNode()
    }

    private func activateFocusedNode() {
        switch focus {
        case .play:
            VODExclusiveWorkRegistry.start {
                isFindingLinks = true
                await store.playFirstDirectStream(for: item)
                isFindingLinks = false
            }
        case .trailer:
            playTrailerUsingSelectedMode()
        case .findLinks, .searchLinks:
            VODExclusiveWorkRegistry.start {
                episodesVisible = false
                store.selectedSourceProvider = "All Providers"
                isFindingLinks = true
                _ = await store.findStreamsForcePopulated(for: item, providerFilter: "All Providers")
                isFindingLinks = false
                linkWindowStart = 0
                focus = store.streamLinks.isEmpty ? .searchLinks : .stream(0)
            }
        case .episodes:
            VODExclusiveWorkRegistry.start {
                isLoadingEpisodes = true
                if episodeItems.isEmpty { episodeItems = await store.fetchSeriesEpisodes(for: item) }
                isLoadingEpisodes = false
                episodesVisible = true
                selectedSeasonNumber = seasonNumbers.first ?? 1
                seasonDropdownOpen = true
                episodeWindowStart = 0
                focus = episodeItems.isEmpty ? .episodes : .season(selectedSeasonIndex)
            }
        case .close:
            store.closeDetail()
        case .favorite, .traktWatchlist, .follow, .testAlert:
            break
        case .sourceProvider:
            break
        case .stream(let index):
            guard store.streamLinks.indices.contains(index) else { return }
            ensureLinkVisible(index)
            let link = store.streamLinks[index]
            if link.isDirectPlayable, let url = CatalogStore.makePlayableURL(from: link.url) {
                let sourceSummary = store.preparedPlaybackTrackSummary(for: url)
                    ?? (SourceMediaTrackProbeCache.cachedSummary(for: link) ?? SourceLinkMetadataParser.summary(for: link, didProbe: true)).merged(with: SourceLinkMetadataParser.summary(for: link, didProbe: true))
                if sourceSummary.dolbyVisionProfile == "5" {
                    store.status = "This Dolby Vision Profile 5 source may not render correctly with the internal player. Try another source."
                    return
                }
                store.startPlayback(item: item, url: url, label: "Opening selected stream: \(link.vodLinkPrimaryLine) • \(link.vodLinkDetailLine). Adaptive fallback is armed across all direct playable links.", sourceTrackSummary: sourceSummary)
                DispatchQueue.main.async {
                    PerTitlePlaybackMemoryManager.shared.rememberSource(link, for: item)
                    LastPlaybackLinkCacheManager.shared.save(item: item, link: link, url: url)
                }
            } else if link.isTorBoxUsenetCandidate || link.infoHash?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false {
                let isTorBoxUsenet = link.isTorBoxUsenetCandidate
                isFindingLinks = true
                store.status = isTorBoxUsenet ? "Preparing selected TorBox Usenet source…" : "Resolving selected debrid stream…"
                VODExclusiveWorkRegistry.start {
                    guard let url = await store.resolvePlayableURL(for: link) else {
                        isFindingLinks = false
                        if isTorBoxUsenet {
                            if !store.status.localizedCaseInsensitiveContains("torbox") {
                                store.status = "TorBox could not prepare this Usenet source. Try another source or check TorBox Downloads."
                            }
                        } else {
                            store.status = "This debrid link could not be resolved. Try another source."
                        }
                        return
                    }
                    PerTitlePlaybackMemoryManager.shared.rememberSource(link, for: item)
                    store.startPlayback(item: item, url: url, alternates: store.playableURLs(from: store.streamLinks, selected: link), subtitles: store.subtitleURLs(from: link), headers: link.requestHeaders.playbackHTTPHeaderDictionary, fallbackHeaders: store.playbackHeaderMap(from: store.streamLinks), label: isTorBoxUsenet ? "Opening selected TorBox Usenet stream: \(link.vodLinkPrimaryLine) • \(link.vodLinkDetailLine)." : "Opening selected debrid stream: \(link.vodLinkPrimaryLine) • \(link.vodLinkDetailLine).", sourceTrackSummary: SourceLinkMetadataParser.summary(for: link, didProbe: true), adaptiveCacheHint: link.sourceIntelligenceAdaptiveCacheHint)
                    isFindingLinks = false
                }
            } else {
                store.status = "This link is not direct-playable yet. A resolver service is needed for magnet/infoHash/debrid-only links."
            }
        case .season(let index):
            guard seasonNumbers.indices.contains(index) else { return }
            selectedSeasonNumber = seasonNumbers[index]
            seasonDropdownOpen = true
            episodeWindowStart = 0
            focus = filteredEpisodeItems.isEmpty ? .season(index) : .episode(0)
        case .episode(let index):
            guard filteredEpisodeItems.indices.contains(index) else { return }
            var episode = filteredEpisodeItems[index]
            // v1062: preserve the exact episode identity and let CatalogStore hydrate
            // episode/season/series credits in priority order. Copying the parent cast here
            // made anthology episodes display the wrong actors before hydration completed.
            episode.castMembers = []
            episode.cast = []
            episode.directors = []
            store.openDetail(episode, pushCurrent: true)
        case .related(let index):
            guard relatedItems.indices.contains(index) else { return }
            store.openDetail(relatedItems[index], pushCurrent: true)
        }
    }
}


struct PopupPremiumStatusChips: View {
    let item: MediaItem
    let isSeries: Bool
    let isFavorite: Bool
    let isFollowing: Bool
    let hasVerifiedEpisodeHint: Bool

    private var chips: [(String, String, Color)] {
        var values: [(String, String, Color)] = []
        if isFavorite { values.append(("FAVORITE", "star.fill", .yellow)) }
        if isSeries && isFollowing { values.append(("FOLLOWING", "bell.badge.fill", .cyan)) }
        if hasVerifiedEpisodeHint { values.append(("VERIFIED ALERTS", "checkmark.seal.fill", .green)) }
        if !item.rating.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty { values.append(("RATED \(item.rating)", "star.circle.fill", .orange)) }
        if isSeries { values.append(("EPISODE WATCH", "calendar.badge.clock", .purple)) }
        values.append(("PREMIUM INFO", "sparkles", .cyan))
        return Array(values.prefix(5))
    }

    var body: some View {
        HStack(spacing: 9) {
            ForEach(Array(chips.enumerated()), id: \.offset) { _, chip in
                HStack(spacing: 6) {
                    Image(systemName: chip.1)
                        .font(.system(size: 11, weight: .black))
                    Text(chip.0)
                        .font(.system(size: 10, weight: .black, design: .rounded))
                        .kerning(0.75)
                }
                .foregroundStyle(Color.white.opacity(0.92))
                .padding(.horizontal, 10)
                .padding(.vertical, 7)
                .background(LinearGradient(colors: [chip.2.opacity(0.22), Color.black.opacity(0.34)], startPoint: .topLeading, endPoint: .bottomTrailing), in: Capsule())
                .overlay(Capsule().stroke(chip.2.opacity(0.26), lineWidth: 1))
                .shadow(color: chip.2.opacity(0.12), radius: 10, y: 3)
            }
            Spacer(minLength: 0)
        }
    }
}

