struct ManualDetailButton: View {
    let title: String
    var icon: String? = nil
    let selected: Bool
    var blackBlueGlow: Bool = false

    private var isPrimary: Bool { title == "PLAY" || title == "CONTINUE" }
    private var buttonWidth: CGFloat {
        if isPrimary { return 170 }
        if title == "CLOSE" { return 132 }
        return 150
    }
    private var buttonHeight: CGFloat { isPrimary ? 70 : 64 }
    private var horizontalPadding: CGFloat { isPrimary ? 28 : 22 }
    private var selectedScale: CGFloat { selected ? 1.055 : 1.0 }
    private var strokeWidth: CGFloat { blackBlueGlow ? (selected ? 1.35 : 0.85) : 0 }
    private var shadowRadius: CGFloat { selected ? 20 : (blackBlueGlow ? 13 : 8) }
    private var shadowOffset: CGFloat { selected ? 5 : 3 }

    var body: some View {
        ManualDetailButtonVisual(
            title: title,
            icon: icon,
            isPrimary: isPrimary,
            selected: selected,
            blackBlueGlow: blackBlueGlow,
            buttonWidth: buttonWidth,
            buttonHeight: buttonHeight,
            horizontalPadding: horizontalPadding
        )
        .equatable()
    }

    private var foregroundColor: Color {
        if selected && isPrimary { return .black }
        return Color.white.opacity(selected ? 1.0 : 0.94)
    }

    private var shadowColor: Color {
        if blackBlueGlow {
            return Color(red: 0.16, green: 0.52, blue: 0.92).opacity(selected ? 0.46 : 0.22)
        }
        if !selected { return Color.black.opacity(0.22) }
        return isPrimary ? Color.cyan.opacity(0.52) : Color.white.opacity(0.16)
    }

    private var buttonBorder: some View {
        Capsule()
            .stroke(buttonStroke, lineWidth: strokeWidth)
    }

    private var buttonGloss: some View {
        Capsule()
            .fill(Color.white.opacity(selected ? 0.25 : 0.10))
            .frame(height: 21)
            .padding(.horizontal, 12)
            .padding(.top, 5)
            .allowsHitTesting(false)
    }

    private var buttonFill: LinearGradient {
        if selected && isPrimary {
            return LinearGradient(colors: [Color.cyan.opacity(0.98), Color.white.opacity(0.94)], startPoint: .topLeading, endPoint: .bottomTrailing)
        }
        if blackBlueGlow {
            return LinearGradient(
                colors: selected
                    ? [Color.black.opacity(0.92), Color(red: 0.045, green: 0.16, blue: 0.31).opacity(0.96)]
                    : [Color.black.opacity(0.78), Color(red: 0.035, green: 0.12, blue: 0.24).opacity(0.72)],
                startPoint: .topLeading,
                endPoint: .bottomTrailing
            )
        }
        if selected {
            return LinearGradient(colors: [Color.white.opacity(0.25), Color.white.opacity(0.10)], startPoint: .topLeading, endPoint: .bottomTrailing)
        }
        return LinearGradient(colors: [Color.white.opacity(0.13), Color.black.opacity(0.22)], startPoint: .topLeading, endPoint: .bottomTrailing)
    }

    private var buttonStroke: Color {
        if selected && isPrimary { return Color.white.opacity(0.88) }
        if blackBlueGlow { return Color(red: 0.24, green: 0.66, blue: 1.0).opacity(selected ? 0.70 : 0.32) }
        if selected { return Color.cyan.opacity(0.55) }
        return Color.white.opacity(0.14)
    }
}

private struct ManualDetailButtonVisual: View, Equatable {
    let title: String
    let icon: String?
    let isPrimary: Bool
    let selected: Bool
    let blackBlueGlow: Bool
    let buttonWidth: CGFloat
    let buttonHeight: CGFloat
    let horizontalPadding: CGFloat

    static func == (lhs: Self, rhs: Self) -> Bool {
        lhs.title == rhs.title && lhs.icon == rhs.icon && lhs.isPrimary == rhs.isPrimary &&
        lhs.selected == rhs.selected && lhs.blackBlueGlow == rhs.blackBlueGlow &&
        lhs.buttonWidth == rhs.buttonWidth && lhs.buttonHeight == rhs.buttonHeight &&
        lhs.horizontalPadding == rhs.horizontalPadding
    }

    var body: some View {
        ManualDetailButtonContent(title: title, icon: icon, isPrimary: isPrimary)
            .foregroundStyle(foregroundColor)
            .padding(.horizontal, horizontalPadding)
            .frame(minWidth: buttonWidth)
            .frame(height: buttonHeight)
            .background(buttonFill, in: Capsule())
            .overlay(Capsule().stroke(buttonStroke, lineWidth: strokeWidth))
            .scaleEffect(selected ? 1.055 : 1.0)
            .shadow(color: shadowColor, radius: selected ? 20 : (blackBlueGlow ? 13 : 8), y: selected ? 5 : 3)
            .animation(.spring(response: 0.22, dampingFraction: 0.82), value: selected)
    }

    private var foregroundColor: Color {
        if selected && isPrimary { return .black }
        return Color.white.opacity(selected ? 1.0 : 0.94)
    }
    private var strokeWidth: CGFloat { blackBlueGlow ? (selected ? 1.35 : 0.85) : 0 }
    private var shadowColor: Color {
        if blackBlueGlow { return Color(red: 0.16, green: 0.52, blue: 0.92).opacity(selected ? 0.46 : 0.22) }
        if !selected { return Color.black.opacity(0.22) }
        return isPrimary ? Color.cyan.opacity(0.52) : Color.white.opacity(0.16)
    }
    private var buttonFill: LinearGradient {
        if selected && isPrimary {
            return LinearGradient(colors: [Color.cyan.opacity(0.98), Color.white.opacity(0.94)], startPoint: .topLeading, endPoint: .bottomTrailing)
        }
        if blackBlueGlow {
            return LinearGradient(colors: selected
                ? [Color.black.opacity(0.92), Color(red: 0.045, green: 0.16, blue: 0.31).opacity(0.96)]
                : [Color.black.opacity(0.78), Color(red: 0.035, green: 0.12, blue: 0.24).opacity(0.72)],
                startPoint: .topLeading, endPoint: .bottomTrailing)
        }
        if selected { return LinearGradient(colors: [Color.white.opacity(0.25), Color.white.opacity(0.10)], startPoint: .topLeading, endPoint: .bottomTrailing) }
        return LinearGradient(colors: [Color.white.opacity(0.13), Color.black.opacity(0.22)], startPoint: .topLeading, endPoint: .bottomTrailing)
    }
    private var buttonStroke: Color {
        if selected && isPrimary { return Color.white.opacity(0.88) }
        if blackBlueGlow { return Color(red: 0.24, green: 0.66, blue: 1.0).opacity(selected ? 0.70 : 0.32) }
        if selected { return Color.cyan.opacity(0.55) }
        return Color.white.opacity(0.14)
    }
}

