        if !item.castMembers.isEmpty { return Array(item.castMembers.prefix(maxMembers)) }
        return Array(item.cast.prefix(maxMembers)).map { CastMember(name: $0, role: nil, imageURL: nil) }
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 12) {
            if !displayMembers.isEmpty {
                Text("CREDITS")
                    .font(.system(size: 18, weight: .black, design: .rounded))
                    .kerning(1.2)
                    .foregroundStyle(.white.opacity(0.78))
                HStack(alignment: .top, spacing: 34) {
                    ForEach(displayMembers) { member in
                        // v1144: Media Information cast is intentionally presentation-only.
                        // Cast Explorer is a VOD playback feature and owns its own focusable
                        // cast surface; popup cast cards must never enter the tvOS focus graph.
                        MovieCastShowcaseCard(member: member)
                    }
                }
            }
        }
    }
}

struct MovieCastShowcaseCard: View {
    let member: CastMember
    var selected: Bool = false

    private var initials: String {
        let parts = member.name.split(separator: " ")
        let letters = parts.prefix(2).compactMap { $0.first }.map(String.init).joined()
        return letters.isEmpty ? "?" : letters.uppercased()
    }

    var body: some View {
        VStack(spacing: 9) {
            ZStack {
                if let imageURL = member.imageURL, !imageURL.isEmpty {
                    RemoteImageFit(url: imageURL, mode: .fill)
                } else {
                    Circle()
                        .fill(LinearGradient(colors: [Color.white.opacity(0.22), Color.cyan.opacity(0.16), Color.orange.opacity(0.14)], startPoint: .topLeading, endPoint: .bottomTrailing))
                    Text(initials)
                        .font(.system(size: 24, weight: .black, design: .rounded))
                        .foregroundStyle(.white.opacity(0.92))
                }
            }
            .frame(width: 104, height: 104)
            .clipShape(Circle())
            .overlay(Circle().stroke(selected ? Color.orange.opacity(0.95) : Color.white.opacity(0.28), lineWidth: selected ? 3 : 1.2))
            .scaleEffect(selected ? 1.07 : 1.0)
            .shadow(color: selected ? Color.orange.opacity(0.24) : Color.black.opacity(0.36), radius: selected ? 18 : 14, y: 7)

            VStack(spacing: 2) {
                Text(member.name)
                    .font(.system(size: 19, weight: .bold, design: .rounded))
                    .foregroundStyle(.white.opacity(0.95))
                    .lineLimit(1)
                    .minimumScaleFactor(0.58)
                if let role = member.role, !role.isEmpty {
                    Text(role)
                        .font(.system(size: 14, weight: .semibold, design: .rounded))
                        .foregroundStyle(.white.opacity(0.60))
                        .lineLimit(1)
                        .minimumScaleFactor(0.52)
                }
            }
            .frame(width: 150)
        }
        .frame(width: 152, height: 138, alignment: .top)
        .accessibilityElement(children: .combine)
        .accessibilityLabel([member.name, member.role].compactMap { $0 }.filter { !$0.isEmpty }.joined(separator: ", "))
        .accessibilityHint(selected ? "Press Select to open Cast Explorer" : "")
    }
}

