struct MovieFranchiseStageCard: View {
    let item: MediaItem
    let selected: Bool

    var body: some View {
        ZStack(alignment: .bottomLeading) {
            RemoteImageFit(url: item.landscapeURL ?? item.posterURL, mode: .fill)
                .saturation(1.08)
                .contrast(1.04)
                .overlay(Color.black.opacity(0.38))
                .overlay(
                    LinearGradient(colors: [Color.black.opacity(0.18), Color.black.opacity(0.42)], startPoint: .top, endPoint: .bottom)
                )
            // v618: franchise cards are logo-only. No year, no rating, no text title.
            Group {
                if let logoURL = item.logoURL, !logoURL.isEmpty {
                    RemoteImageFit(url: logoURL, mode: .fit)
                        .frame(width: 205, height: 70, alignment: .center)
                } else {
                    // Last-resort fallback only when TMDB has no logo image for the title.
                    // Kept inside the card but styled like a logo rather than metadata.
                    Text(item.title.uppercased())
                        .font(.system(size: 24, weight: .black, design: .rounded))
                        .multilineTextAlignment(.center)
                        .foregroundStyle(.white.opacity(0.94))
                        .minimumScaleFactor(0.45)
                        .lineLimit(2)
                        .frame(width: 205, height: 70, alignment: .center)
                }
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .center)
            .padding(.horizontal, 18)
        }
        .frame(width: 260, height: 132)
        .clipShape(RoundedRectangle(cornerRadius: 18, style: .continuous))
        .overlay(
            RoundedRectangle(cornerRadius: 18, style: .continuous)
                .stroke(selected ? Color(red: 0.42, green: 0.84, blue: 1.0).opacity(0.98) : Color.white.opacity(0.10), lineWidth: selected ? 3 : 1)
        )
        .overlay(
            RoundedRectangle(cornerRadius: 24, style: .continuous)
                .stroke(Color(red: 0.42, green: 0.84, blue: 1.0).opacity(selected ? 0.40 : 0.0), lineWidth: selected ? 7 : 0)
                .blur(radius: selected ? 7 : 0)
        )
        .scaleEffect(selected ? 1.045 : 1.0)
        .shadow(color: Color(red: 0.42, green: 0.84, blue: 1.0).opacity(selected ? 0.30 : 0.0), radius: selected ? 20 : 0, y: selected ? 7 : 0)
        .modifier(SafeCardScrollMotion(isFocused: selected, intensity: 0.55))
    }
}

