struct CompactHeroCastCard: View {
    let member: CastMember
    var compact: Bool = false
    var selected: Bool = false
    var publishDuringPlayback: Bool = false

    private var initials: String {
        let parts = member.name.split(separator: " ")
        let letters = parts.prefix(2).compactMap { $0.first }.map(String.init).joined()
        return letters.isEmpty ? "?" : letters.uppercased()
    }

    private var avatarSize: CGFloat { compact ? 42 : 52 }
    private var cardWidth: CGFloat { compact ? 162 : 198 }
    private var cardHeight: CGFloat { compact ? 56 : 68 }
    private var cardCornerRadius: CGFloat { compact ? 16 : 18 }
    private var textWidth: CGFloat { compact ? 98 : 122 }
    private var horizontalPadding: CGFloat { compact ? 8 : 10 }
    private var contentSpacing: CGFloat { compact ? 7 : 8 }

    private var accessibilityText: String {
        [member.name, member.role]
            .compactMap { $0 }
            .filter { !$0.isEmpty }
            .joined(separator: ", ")
    }

    @ViewBuilder
    private var avatarContent: some View {
        if let imageURL = member.imageURL, !imageURL.isEmpty {
            RemoteImageFit(
                url: imageURL,
                mode: .fill,
                maxPixelSize: 512,
                publishDuringPlayback: publishDuringPlayback,
                forceVisiblePlaybackPublication: publishDuringPlayback
            )
        } else {
            Circle()
                .fill(
                    LinearGradient(
                        colors: [
                            Color.white.opacity(0.18),
                            Color.cyan.opacity(0.16),
                            Color.orange.opacity(0.12)
                        ],
                        startPoint: .topLeading,
                        endPoint: .bottomTrailing
                    )
                )
            Text(initials)
                .font(.system(size: compact ? 12 : 14, weight: .black, design: .rounded))
                .foregroundStyle(.white.opacity(0.88))
        }
    }

    private var avatarView: some View {
        ZStack {
            avatarContent
        }
        .frame(width: avatarSize, height: avatarSize)
        .clipShape(Circle())
        .overlay(Circle().stroke(Color.white.opacity(0.20), lineWidth: 1))
    }

    @ViewBuilder
    private var roleView: some View {
        if let role = member.role, !role.isEmpty {
            Text(role)
                .font(.system(size: compact ? 10 : 11, weight: .semibold, design: .rounded))
                .foregroundStyle(.white.opacity(0.52))
                .lineLimit(1)
                .minimumScaleFactor(0.62)
        }
    }

    private var textView: some View {
        VStack(alignment: .leading, spacing: 1) {
            Text(member.name)
                .font(.system(size: compact ? 12 : 14, weight: .black, design: .rounded))
                .foregroundStyle(.white.opacity(0.94))
                .lineLimit(1)
                .minimumScaleFactor(0.62)
            roleView
        }
        .frame(width: textWidth, alignment: .leading)
    }

    private var cardContent: some View {
        HStack(spacing: contentSpacing) {
            avatarView
            textView
        }
        .padding(.horizontal, horizontalPadding)
        .frame(width: cardWidth, height: cardHeight, alignment: .leading)
    }

    private var cardBackground: some View {
        RoundedRectangle(cornerRadius: cardCornerRadius, style: .continuous)
            .fill(Color.black.opacity(0.34))
    }

    private var cardBorder: some View {
        RoundedRectangle(cornerRadius: cardCornerRadius, style: .continuous)
            .stroke(
                selected ? Color.orange.opacity(0.95) : Color.white.opacity(0.10),
                lineWidth: selected ? 2.5 : 1
            )
    }

    var body: some View {
        cardContent
            .background(cardBackground)
            .overlay(cardBorder)
            .scaleEffect(selected ? 1.045 : 1.0)
            .shadow(
                color: selected ? Color.orange.opacity(0.18) : Color.clear,
                radius: 12,
                y: 4
            )
            .accessibilityElement(children: .combine)
            .accessibilityLabel(accessibilityText)
            .accessibilityHint(selected ? "Press Select to open Cast Explorer" : "")
    }
}

struct ManualEpisodesRow: View {
    let focus: DetailPage.DetailNode
    let visibleEpisodes: [MediaItem]
    let episodeWindowStart: Int
    let totalEpisodeCount: Int
    let seasonNumbers: [Int]
    let selectedSeasonNumber: Int
    let seasonDropdownOpen: Bool

    private var seasonScrollTargetIndex: Int {
        if case .season(let index) = focus { return index }
        return seasonNumbers.firstIndex(of: selectedSeasonNumber) ?? 0
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 7) {
            manualSeasonHeader
            manualSeasonScrollStrip
            manualEpisodeCards
        }
        .foregroundStyle(.white)
    }

    private var manualSeasonHeader: some View {
        HStack(alignment: .center, spacing: 12) {
                Text("SEASONS")
                    .font(.system(size: 14, weight: .black, design: .rounded))
                    .kerning(1.2)
                    .foregroundStyle(.white.opacity(0.58))
                if totalEpisodeCount > 0 {
                    Text("EPISODES \(episodeWindowStart + 1)-\(min(episodeWindowStart + visibleEpisodes.count, totalEpisodeCount)) OF \(totalEpisodeCount)")
                        .font(.system(size: 12, weight: .black, design: .rounded))
                        .kerning(0.9)
                        .foregroundStyle(.white.opacity(0.42))
                }
            }

    }

    private func manualSeasonChip(index: Int, season: Int) -> some View {
        let selected: Bool = selectedSeasonNumber == season
        let focusedSeason: Bool = focus == .season(index)
        let highlighted: Bool = selected || focusedSeason
        let fill: Color = highlighted ? Color.white.opacity(0.92) : Color.black.opacity(0.38)
        let border: Color = focusedSeason ? Color.cyan.opacity(0.98) : Color.white.opacity(0.12)
        return Text("Season \(season)")
            .font(.system(size: 15, weight: .black, design: .rounded))
            .foregroundStyle(highlighted ? Color.black : Color.white.opacity(0.88))
            .padding(.horizontal, 16)
            .frame(height: 34)
            .background(RoundedRectangle(cornerRadius: 13, style: .continuous).fill(fill))
            .overlay(RoundedRectangle(cornerRadius: 13, style: .continuous).stroke(border, lineWidth: focusedSeason ? 2.5 : 1))
            .id(index)
    }

    private var manualSeasonStripContent: some View {
        ScrollView(.horizontal, showsIndicators: false) {
            HStack(spacing: 9) {
                ForEach(Array(seasonNumbers.enumerated()), id: \.element) { index, season in
                    manualSeasonChip(index: index, season: season)
                }
            }
        }
    }

    private var manualSeasonScrollStrip: some View {
            ScrollViewReader { proxy in
                manualSeasonStripContent
                .onAppear {
                    proxy.scrollTo(seasonScrollTargetIndex, anchor: .center)
                }
                .onChange(of: seasonScrollTargetIndex) { target in
                    DispatchQueue.main.async {
                        proxy.scrollTo(target, anchor: .center)
                    }
                }
            }
            .frame(maxWidth: 1120, alignment: .leading)

    }

    private var manualEpisodeCards: some View {
            HStack(spacing: 12) {
                if visibleEpisodes.isEmpty {
                    HStack(spacing: 12) {
                        ProgressView()
                            .scaleEffect(0.82)
                        Text("Loading episode previews and season metadata…")
                            .font(.system(size: 18, weight: .bold, design: .rounded))
                            .foregroundStyle(.white.opacity(0.70))
                    }
                    .frame(width: 620, height: 158, alignment: .center)
                    .background(RoundedRectangle(cornerRadius: 18, style: .continuous).fill(Color.black.opacity(0.34)))
                    .overlay(RoundedRectangle(cornerRadius: 18, style: .continuous).stroke(Color.white.opacity(0.12), lineWidth: 1))
                } else {
                    ForEach(Array(visibleEpisodes.enumerated()), id: \.element.id) { offset, episode in
                        let absolute = episodeWindowStart + offset
                        let selected = focus == .episode(absolute)
                        HeroEpisodePreviewCard(episode: episode, absoluteIndex: absolute, selected: selected)
                    }
                }
            }
    }
}

struct HeroEpisodePreviewCard: View {
    let episode: MediaItem
    let absoluteIndex: Int
    let selected: Bool
    let cardWidth: CGFloat

    init(episode: MediaItem, absoluteIndex: Int, selected: Bool, cardWidth: CGFloat = 264) {
        self.episode = episode
        self.absoluteIndex = absoluteIndex
        self.selected = selected
        self.cardWidth = cardWidth
    }

    private var mediaWidth: CGFloat { max(180, cardWidth - 20) }
    private var textWidth: CGFloat { max(160, cardWidth - 40) }

    private var code: String {
        "S\(episode.seasonNumber ?? 1)E\(episode.episodeNumber ?? absoluteIndex + 1)"
    }

    private var image: String? {
        if let preview = episode.previewURL, !preview.isEmpty { return preview }
        if let landscape = episode.landscapeURL, !landscape.isEmpty { return landscape }
        return episode.posterURL
    }

    private var titleText: String {
        let cleaned = episode.title.replacingOccurrences(of: "  ", with: " ").trimmingCharacters(in: .whitespacesAndNewlines)
        return cleaned.isEmpty ? code : cleaned
    }

    private var detailText: String {
        let cleaned = episode.description.trimmingCharacters(in: .whitespacesAndNewlines)
        return cleaned.isEmpty ? "Episode metadata ready" : cleaned
    }

    private var episodeDate: DCEpisodeDatePresentation? {
        dcEpisodeDatePresentation(episode)
    }


    private var resumeEntry: PlaybackResumeEntry? {
        PlaybackResumeCacheManager.shared.resumeEntry(for: episode)
    }

    private var thumbnail: some View {
        ZStack {
            RemoteImageFit(
                url: image,
                mode: .fill,
                maxPixelSize: 768,
                publishDuringPlayback: true,
                forceVisiblePlaybackPublication: true
            )
                .frame(width: mediaWidth, height: 122)
                .clipped()
            LinearGradient(colors: [Color.clear, Color.black.opacity(0.86)], startPoint: .top, endPoint: .bottom)

            if let resume = resumeEntry, resume.duration > 0 {
                HStack(spacing: 5) {
                    Image(systemName: "play.fill")
                        .font(.system(size: 8, weight: .black))
                    Text("\(resume.dcRemainingText.uppercased()) LEFT")
                        .font(.system(size: 9, weight: .black, design: .rounded))
                        .kerning(0.35)
                }
                .foregroundStyle(.white.opacity(0.96))
                .padding(.horizontal, 8)
                .frame(height: 24)
                .background(Capsule().fill(Color.cyan.opacity(0.82)))
                .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
                .padding(8)
            }

            VStack(spacing: 0) {
                Spacer(minLength: 0)

                HStack(spacing: 6) {
                    Text(code)
                        .font(.system(size: 14, weight: .black, design: .rounded))
                        .foregroundStyle(.white)

                    if let episodeDate {
                        Text("•")
                            .font(.system(size: 10, weight: .black, design: .rounded))
                            .foregroundStyle(.white.opacity(0.58))

                        Text("\(episodeDate.statusText.uppercased()) \(episodeDate.dateText.uppercased())")
                            .font(.system(size: 8.5, weight: .black, design: .rounded))
                            .foregroundStyle(episodeDate.isUpcoming ? Color.orange : Color.white.opacity(0.90))
                            .lineLimit(1)
                            .minimumScaleFactor(0.64)
                    }

                    Spacer(minLength: 0)
                }
                .padding(.horizontal, 9)
                .frame(maxWidth: .infinity, minHeight: 26, alignment: .leading)
                .background(
                    Capsule()
                        .fill(Color.black.opacity(0.62))
                )
                .overlay(
                    Capsule()
                        .stroke(episodeDate?.isUpcoming == true ? Color.orange.opacity(0.78) : Color.white.opacity(0.14), lineWidth: 1)
                )
            }
            .padding(8)
        }
        .frame(width: mediaWidth, height: 122)
        .clipShape(RoundedRectangle(cornerRadius: 18, style: .continuous))
    }

    private var textBlock: some View {
        VStack(alignment: .leading, spacing: 4) {
            Text(titleText)
                .font(.system(size: 14, weight: .black, design: .rounded))
                .foregroundStyle(.white.opacity(0.94))
                .lineLimit(1)
                .frame(width: textWidth, alignment: .leading)
            Text(detailText)
                .font(.system(size: 11, weight: .semibold, design: .rounded))
                .foregroundStyle(.white.opacity(0.56))
                .lineLimit(2)
                .frame(width: textWidth, height: 30, alignment: .topLeading)
        }
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 7) {
            thumbnail
            textBlock
        }
        .padding(10)
        .frame(width: cardWidth, height: 202, alignment: .topLeading)
        .background(cardBackground)
        .overlay(cardStroke)
        .shadow(color: selected ? Color.cyan.opacity(0.36) : Color.black.opacity(0.20), radius: selected ? 20 : 8, y: selected ? 7 : 3)
        .scaleEffect(selected ? 1.035 : 1.0)
        .animation(.easeOut(duration: 0.16), value: selected)
    }

    private var cardBackground: some View {
        RoundedRectangle(cornerRadius: 24, style: .continuous)
            .fill(selected ? Color.cyan.opacity(0.20) : Color.black.opacity(0.38))
    }

    private var cardStroke: some View {
        RoundedRectangle(cornerRadius: 24, style: .continuous)
            .stroke(selected ? Color.cyan.opacity(0.98) : Color.white.opacity(0.12), lineWidth: selected ? 3 : 1)
    }
}


extension StreamLink {
    var vodLinkPrimaryLine: String {
        let provider = source.trimmingCharacters(in: .whitespacesAndNewlines)
        let qualityText = quality.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? "Unknown" : quality
        if provider.isEmpty { return qualityText }
        return "\(qualityText) • \(provider)"
    }

    var vodLinkDetailLine: String {
        var parts: [String] = []
        if !size.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty { parts.append(size) }
        parts.append(contentsOf: vodFeatureTags)
        if !subtitleURLs.isEmpty { parts.append("Subs \(subtitleURLs.count)") }
        if let warning = vodLanguageWarning { parts.insert(warning, at: 0) }
        if parts.isEmpty { return "No technical metadata from provider" }
        return parts.prefix(7).joined(separator: " • ")
    }

    var vodLanguageWarning: String? {
        let h = " \(title) \(quality) \(source) ".lowercased()
        let englishHit = [" english", " eng", ".eng", "-eng", " en ", "[en", " en-", "truehd", "atmos"].contains { h.contains($0) }
        let nonEnglishSignals = [" spanish", " latino", " castellano", " spa", ".spa", " french", " fra", " german", " deu", " italian", " ita", " portuguese", " por", " polish", " pl ", " pldub", " russian", " rus", " hindi", " korean", " japanese", " jpn"]
        if !englishHit && nonEnglishSignals.contains(where: { h.contains($0) }) { return "⚠ Language check" }
        if h.contains("multi") || h.contains("dual") { return "Multi Audio" }
        return nil
    }

    private var vodFeatureTags: [String] {
        let haystack = "\(title) \(quality) \(source)".lowercased()
        var tags: [String] = []
        func add(_ value: String) { if !tags.contains(value) { tags.append(value) } }

        if haystack.contains("dolby vision") || haystack.contains("dovi") || haystack.contains(" dv ") || haystack.contains(".dv.") || haystack.contains("-dv-") { add("DV") }
        if haystack.contains("hdr10+") || haystack.contains("hdr10plus") { add("HDR10+") }
        else if haystack.contains("hdr10") || haystack.contains(" hdr ") || haystack.contains(".hdr.") || haystack.contains("-hdr-") { add("HDR") }
        if haystack.contains("hlg") { add("HLG") }
        if haystack.contains("av1") { add("AV1") }
        if haystack.contains("hevc") || haystack.contains("h.265") || haystack.contains("x265") { add("HEVC") }
        if haystack.contains("h.264") || haystack.contains("x264") || haystack.contains("avc") { add("H.264") }
        if haystack.contains("atmos") { add("Atmos") }
        if haystack.contains("truehd") || haystack.contains("true hd") { add("TrueHD") }
        if haystack.contains("dts-hd") || haystack.contains("dtshd") { add("DTS-HD") }
        else if haystack.contains(" dts ") || haystack.contains(".dts.") || haystack.contains("-dts-") { add("DTS") }
        if haystack.contains("ddp") || haystack.contains("eac3") || haystack.contains("e-ac3") || haystack.contains("dolby digital plus") { add("DD+") }
        else if haystack.contains(" ac3") || haystack.contains(".ac3") || haystack.contains("-ac3") { add("AC3") }
        if haystack.contains(" aac") || haystack.contains(".aac") || haystack.contains("-aac") { add("AAC") }

        let languagePatterns: [(String, [String])] = [
            ("English", [" english", " eng", ".eng", "-eng", " en ", "[en"]),
            ("Spanish", [" spanish", " spa", ".spa", "-spa", " es ", " latino"]),
            ("French", [" french", " fre", " fra", ".fre", ".fra", " fr "]),
            ("Japanese", [" japanese", " jpn", ".jpn", " ja "]),
            ("Korean", [" korean", " kor", ".kor", " ko "]),
            ("German", [" german", " ger", " deu", ".ger", ".deu", " de "]),
            ("Italian", [" italian", " ita", ".ita", " it "]),
            ("Portuguese", [" portuguese", " por", ".por", " pt "]),
            ("Polish", [" polish", " pldub", " pl ", ".pl."])
        ]
        for (name, patterns) in languagePatterns where patterns.contains(where: { haystack.contains($0) }) { add(name) }

        if haystack.contains("remux") { add("REMUX") }
        if haystack.contains("web-dl") || haystack.contains("webdl") { add("WEB-DL") }
        if haystack.contains("bluray") || haystack.contains("blu-ray") { add("BluRay") }
        return Array(tags.prefix(6))
    }
}


extension StreamLink {
    var intelligenceHaystack: String {
        [title, quality, size, source, url ?? ""].joined(separator: " ").lowercased()
    }

    var detectedResolution: String {
        let h = intelligenceHaystack
        if h.contains("2160") || h.contains("4k") { return "4K" }
        if h.contains("1440") { return "1440p" }
        if h.contains("1080") { return "1080p" }
        if h.contains("720") { return "720p" }
        if !quality.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty { return quality }
        return "Quality Unknown"
    }

    var detectedCodec: String? {
        let h = intelligenceHaystack
        if h.contains("av1") { return "AV1" }
        if h.contains("hevc") || h.contains("h.265") || h.contains("h265") || h.contains("x265") { return "HEVC / H.265" }
        if h.contains("h.264") || h.contains("h264") || h.contains("x264") || h.contains("avc") { return "H.264 / AVC" }
        if h.contains("mpeg2") { return "MPEG-2" }
        return nil
    }

    var detectedDolbyVisionProfile: String? {
        let h = intelligenceHaystack
        if h.contains("profile 5") || h.contains("profile5") || h.contains("dv5") || h.contains("dv p5") || h.contains("dovi p5") || h.contains("dvhe.05") || h.contains("dvh1.05") { return "5" }
        if h.contains("profile 7") || h.contains("profile7") || h.contains("dv7") || h.contains("dv p7") || h.contains("dovi p7") || h.contains("dvhe.07") || h.contains("dvh1.07") { return "7" }
        if h.contains("profile 8") || h.contains("profile8") || h.contains("dv8") || h.contains("dv p8") || h.contains("dovi p8") || h.contains("dvhe.08") || h.contains("dvh1.08") { return "8" }
        return nil
    }

    var detectedHDR: String? {
        let h = intelligenceHaystack
        if let profile = detectedDolbyVisionProfile {
            if profile == "8" { return "Dolby Vision Profile 8 / HDR compatible" }
            return "Dolby Vision Profile \(profile)"
        }
        if h.contains("dolby vision") || h.contains(" dovi ") || h.contains(".dovi.") || h.contains(" dv ") || h.contains(".dv.") || h.contains("-dv-") { return "Dolby Vision" }
        if h.contains("hdr10+") || h.contains("hdr10plus") { return "HDR10+" }
        if h.contains("hdr10") { return "HDR10" }
        if h.contains(" hdr ") || h.contains(".hdr.") || h.contains("-hdr-") { return "HDR" }
        if h.contains("sdr") { return "SDR" }
        return nil
    }

    var detectedAudio: String? {
        let h = intelligenceHaystack
        if h.contains("truehd") { return h.contains("atmos") ? "TrueHD Atmos" : "TrueHD" }
        if h.contains("atmos") { return "Atmos" }
        if h.contains("dts-hd") { return "DTS-HD" }
        if h.contains("dts") { return "DTS" }
        if h.contains("ddp5.1") { return "DD+ 5.1" }
        if h.contains("ddp") || h.contains("eac3") || h.contains("e-ac3") || h.contains("dd+") { return "DD+" }
        if h.contains("ac3") { return "AC3" }
        if h.contains("5.1") { return "5.1" }
        if h.contains("aac") { return "AAC" }
        if h.contains("stereo") || h.contains("2.0") { return "Stereo" }
        return nil
    }

    var detectedLanguage: String? {
        let h = intelligenceHaystack
        let englishTokens = ["[en", " en ", " english", "eng", "multi", "dual audio"]
        if englishTokens.contains(where: { h.contains($0) }) { return "English" }
        if h.contains("pldub") || h.contains(" polish") || h.contains("[pl") || h.contains(" lektor") { return "Polish" }
        if h.contains(" latino") || h.contains(" spanish") || h.contains("[es") || h.contains(" esp") { return "Spanish" }
        if h.contains(" german") || h.contains("[de") { return "German" }
        if h.contains(" french") || h.contains("[fr") { return "French" }
        if h.contains(" italian") || h.contains("[it") { return "Italian" }
        if h.contains(" portuguese") || h.contains("[pt") { return "Portuguese" }
        if h.contains(" ukrainian") || h.contains(" ukr") || h.contains("[uk") { return "Ukrainian" }
        if h.contains(" chinese") || h.contains(" zho") || h.contains(" chi") || h.contains("[zh") { return "Chinese" }
        if h.contains(" japanese") || h.contains("[ja") { return "Japanese" }
        if h.contains(" korean") || h.contains("[ko") { return "Korean" }
        if h.contains(" hindi") || h.contains("[hi") { return "Hindi" }
        return nil
    }

    var dolbyVisionPlaybackWarning: String? {
        detectedDolbyVisionProfile == "5" ? "DV Profile 5 may require compatible playback" : nil
    }

    var sourceWarning: String? {
        guard let lang = detectedLanguage else { return nil }
        if lang != "English" && lang != "Multi" { return "Check audio: \(lang)" }
        return nil
    }

    var matchLabel: String {
        if let warning = sourceWarning { return warning }
        if detectedLanguage == "English" { return "English detected" }
        if isDirectPlayable { return "Direct playable" }
        return "Resolve needed"
    }

    var hasSubtitleInfo: Bool { !subtitleURLs.isEmpty || intelligenceHaystack.contains("sub") || intelligenceHaystack.contains("subs") }
    var subtitleLabel: String { hasSubtitleInfo ? "Subtitles available" : "Subtitle info unknown" }

    var providerDisplay: String {
        let clean = source.trimmingCharacters(in: .whitespacesAndNewlines)
        let base = clean.isEmpty ? "Unknown Provider" : clean
        let service = providerService?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        guard !service.isEmpty else { return base }
        let baseKey = SourceIntelligenceManager.providerCanonical(base)
        let serviceKey = SourceIntelligenceManager.providerCanonical(service)
        return baseKey.contains(serviceKey) ? base : "\(base) • \(service)"
    }
}

struct RealMediaTrackOption: Identifiable, Hashable {
    var id: String
    var optionIndex: Int
    var label: String
    var languageName: String
    var codecOrFormat: String?
    var isDefault: Bool
    var isForced: Bool
    var isSDH: Bool
}

struct RealMediaTrackSummary: Hashable {
    var audio: [RealMediaTrackOption]
    var subtitles: [RealMediaTrackOption]
    var didProbe: Bool
    var resolution: String? = nil
    var container: String? = nil
    var videoCodec: String? = nil
    var hdrType: String? = nil
    var dolbyVisionProfile: String? = nil
    var sourceWarning: String? = nil

    static let unavailable = RealMediaTrackSummary(audio: [], subtitles: [], didProbe: true)

    var audioLanguagesText: String {
        let values = audio.map(\.languageName).filter { !$0.isEmpty }
        return values.isEmpty ? "Audio: Unknown" : "Audio: " + values.uniquedPreservingOrder().joined(separator: ", ")
    }

    var subtitleLanguagesText: String {
        let values = subtitles.map(\.languageName).filter { !$0.isEmpty }
        return values.isEmpty ? "Subtitles: None detected" : "Subtitles: " + values.uniquedPreservingOrder().joined(separator: ", ")
    }

    var audioCodecText: String? {
        audio.compactMap(\.codecOrFormat).filter { !$0.isEmpty }.uniquedPreservingOrder().first
    }

    var subtitleFormatText: String? {
        subtitles.compactMap(\.codecOrFormat).filter { !$0.isEmpty }.uniquedPreservingOrder().first
    }

    var subtitleMarkersText: String? {
        let markers = subtitles.flatMap { option -> [String] in
            var values: [String] = []
            if option.isDefault { values.append("Default") }
            if option.isForced { values.append("Forced") }
            if option.isSDH { values.append("SDH") }
            return values
        }.uniquedPreservingOrder()
        return markers.isEmpty ? nil : markers.joined(separator: ", ")
    }

    func merged(with fallback: RealMediaTrackSummary) -> RealMediaTrackSummary {
        RealMediaTrackSummary(
            audio: audio.isEmpty ? fallback.audio : audio,
            subtitles: subtitles.isEmpty ? fallback.subtitles : subtitles,
            didProbe: didProbe,
            resolution: resolution ?? fallback.resolution,
            container: container ?? fallback.container,
            videoCodec: videoCodec ?? fallback.videoCodec,
            hdrType: hdrType ?? fallback.hdrType,
            dolbyVisionProfile: dolbyVisionProfile ?? fallback.dolbyVisionProfile,
            sourceWarning: sourceWarning ?? fallback.sourceWarning
        )
    }
}

enum SourceLinkMetadataParser {
    static func summary(for link: StreamLink, didProbe: Bool = false) -> RealMediaTrackSummary {
        let audioCodec = link.detectedAudio
        let language = link.detectedLanguage
        let audio: [RealMediaTrackOption]
        if let language {
            audio = [
                RealMediaTrackOption(
                    id: "filename-audio-\(language)",
                    optionIndex: 0,
                    label: [language, audioCodec].compactMap { $0 }.joined(separator: " • "),
                    languageName: language,
                    codecOrFormat: audioCodec,
                    isDefault: true,
                    isForced: false,
                    isSDH: false
                )
            ]
        } else {
            audio = []
        }
        return RealMediaTrackSummary(
            audio: audio,
            subtitles: subtitleOptions(for: link),
            didProbe: didProbe,
            resolution: link.detectedResolution == "Quality Unknown" ? nil : link.detectedResolution,
            container: detectedContainer(for: link),
            videoCodec: link.detectedCodec,
            hdrType: link.detectedHDR,
            dolbyVisionProfile: link.detectedDolbyVisionProfile,
            sourceWarning: link.dolbyVisionPlaybackWarning ?? link.sourceWarning
        )
    }

    private static func detectedContainer(for link: StreamLink) -> String? {
        let h = link.intelligenceHaystack
        if h.contains(".mkv") || h.contains(" matroska") { return "MKV" }
        if h.contains(".mp4") { return "MP4" }
        if h.contains(".m3u8") || h.contains(" hls") { return "HLS" }
        if h.contains(".ts") || h.contains(" mpeg-ts") { return "MPEG-TS" }
        if h.contains(".avi") { return "AVI" }
        return nil
    }

    private static func subtitleOptions(for link: StreamLink) -> [RealMediaTrackOption] {
        let explicit = link.subtitleURLs.enumerated().map { index, value in
            let language = MediaTrackLanguageNormalizer.displayName(code: nil, fallback: value)
            let lower = value.lowercased()
            return RealMediaTrackOption(
                id: "filename-subtitle-\(index)-\(language)",
                optionIndex: index,
                label: "External • \(language)",
                languageName: language,
                codecOrFormat: subtitleFormat(from: lower),
                isDefault: false,
                isForced: lower.contains("forced"),
                isSDH: lower.contains("sdh")
            )
        }
        if !explicit.isEmpty { return explicit }
        let h = link.intelligenceHaystack
        guard h.contains(" sub") || h.contains(".sub") || h.contains("subs") || h.contains("srt") || h.contains("vtt") else { return [] }
        let language = link.detectedLanguage ?? "Unknown"
        return [RealMediaTrackOption(id: "filename-subtitle-\(language)", optionIndex: 0, label: "\(language) subtitles", languageName: language, codecOrFormat: subtitleFormat(from: h), isDefault: false, isForced: h.contains("forced"), isSDH: h.contains("sdh"))]
    }

    private static func subtitleFormat(from lower: String) -> String? {
        if lower.contains("srt") { return "SRT" }
        if lower.contains("vtt") { return "VTT" }
        if lower.contains("ass") { return "ASS" }
        if lower.contains("pgs") { return "PGS" }
        return nil
    }
}

extension Array where Element == String {
    func uniquedPreservingOrder() -> [String] {
        var seen = Set<String>()
        return filter { seen.insert($0).inserted }
    }
}

enum MediaTrackLanguageNormalizer {
    static func displayName(code raw: String?, fallback: String? = nil) -> String {
        let cleaned = (raw ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let lowered = cleaned.lowercased()
        let primary = lowered.components(separatedBy: CharacterSet(charactersIn: "-_")).first ?? lowered
        switch primary {
        case "eng", "en": return "English"
        case "spa", "es": return "Spanish"
        case "fre", "fra", "fr": return "French"
        case "ger", "deu", "de": return "German"
        case "jpn", "ja": return "Japanese"
        case "kor", "ko": return "Korean"
        case "chi", "zho", "zh": return "Chinese"
        case "por", "pt": return "Portuguese"
        case "ita", "it": return "Italian"
        default:
            if let fallback {
                let trimmedFallback = fallback.trimmingCharacters(in: .whitespacesAndNewlines)
                let lowerFallback = trimmedFallback.lowercased()
                if lowerFallback.contains("english") { return "English" }
                if lowerFallback.contains("spanish") { return "Spanish" }
                if lowerFallback.contains("french") { return "French" }
                if lowerFallback.contains("german") { return "German" }
                if lowerFallback.contains("japanese") { return "Japanese" }
                if lowerFallback.contains("korean") { return "Korean" }
                if lowerFallback.contains("chinese") { return "Chinese" }
                if lowerFallback.contains("portuguese") { return "Portuguese" }
                if lowerFallback.contains("italian") { return "Italian" }
            }
            return cleaned.isEmpty ? "Unknown" : cleaned.uppercased()
        }
    }

    static func conciseLabel(for option: RealMediaTrackOption) -> String {
        var label = option.languageName.isEmpty ? "Unknown" : option.languageName
        if option.isForced { label += " Forced" }
        if option.isSDH { label += " SDH" }
        if let codec = option.codecOrFormat, !codec.isEmpty { label += " • \(codec)" }
        if option.isDefault { label += " • Default" }
        return label
    }
}

@MainActor
final class SourceMediaTrackProbeCache: ObservableObject {
    private static var sessionSummaries: [String: RealMediaTrackSummary] = [:]
    private static var sessionSummaryOrder: [String] = []
    private static var sessionInFlight = Set<String>()
    private static let maxSessionSummaries = 96
    private static let maxConcurrentProbes = 3
    @Published private var summaries: [String: RealMediaTrackSummary] = [:]
    @Published private var inFlightKeys = Set<String>()
    private var pendingLinks: [StreamLink] = []
    private var activeProbeCount = 0

    func summary(for link: StreamLink) -> RealMediaTrackSummary? {
        guard let key = key(for: link) else { return nil }
        return summaries[key] ?? Self.sessionSummaries[key]
    }

    func isChecking(_ link: StreamLink) -> Bool {
        guard let key = key(for: link) else { return false }
        return inFlightKeys.contains(key) || Self.sessionInFlight.contains(key) || pendingLinks.contains { self.key(for: $0) == key }
    }

    func probeLinks(_ links: [StreamLink]) {
        // v764 crash isolation: do not run AVURLAsset probes from the Source Intelligence panel.
        // The earlier playback crash came from real media probing; the panel can still show
        // English/cache/codec/source badges from addon Source Intelligence metadata safely.
        for link in links {
            guard let key = key(for: link), summaries[key] == nil, Self.sessionSummaries[key] == nil else { continue }
            let fallback = SourceLinkMetadataParser.summary(for: link, didProbe: false)
            Self.rememberSessionSummary(fallback, for: key)
            summaries[key] = fallback
        }
        pendingLinks.removeAll()
        inFlightKeys.removeAll()
        Self.sessionInFlight.removeAll()
        activeProbeCount = 0
    }

    private func key(for link: StreamLink) -> String? {
        guard link.isDirectPlayable, let url = CatalogStore.makePlayableURL(from: link.url) else { return nil }
        return [link.providerDisplay, link.quality, link.title, "\(link.fileIndex ?? -1)", url.absoluteString].joined(separator: "|").lowercased()
    }

    static func cachedSummary(for link: StreamLink) -> RealMediaTrackSummary? {
        let urlText = CatalogStore.makePlayableURL(from: link.url)?.absoluteString ?? link.url ?? ""
        let key = [link.providerDisplay, link.quality, link.title, "\(link.fileIndex ?? -1)", urlText].joined(separator: "|").lowercased()
        return sessionSummaries[key]
    }

    private static func rememberSessionSummary(_ summary: RealMediaTrackSummary, for key: String) {
        sessionSummaries[key] = summary
        sessionSummaryOrder.removeAll { $0 == key }
        sessionSummaryOrder.append(key)
        while sessionSummaryOrder.count > maxSessionSummaries {
            let evicted = sessionSummaryOrder.removeFirst()
            sessionSummaries.removeValue(forKey: evicted)
        }
    }

    static func handleReleaseStabilityMemoryPressure() {
        sessionSummaries.removeAll(keepingCapacity: false)
        sessionSummaryOrder.removeAll(keepingCapacity: false)
        sessionInFlight.removeAll(keepingCapacity: false)
    }

    static var releaseStabilityCachedSummaryCount: Int { sessionSummaries.count }

    private func drainProbeQueue() {
        while activeProbeCount < Self.maxConcurrentProbes, !pendingLinks.isEmpty {
            let link = pendingLinks.removeFirst()
            guard let key = key(for: link),
                  summaries[key] == nil,
                  Self.sessionSummaries[key] == nil,
                  !Self.sessionInFlight.contains(key),
                  let url = CatalogStore.makePlayableURL(from: link.url) else { continue }
            activeProbeCount += 1
            inFlightKeys.insert(key)
            Self.sessionInFlight.insert(key)
            VODExclusiveWorkRegistry.start {
                let summary = await Self.probe(url: url, fallback: SourceLinkMetadataParser.summary(for: link, didProbe: true))
                await MainActor.run {
                    Self.rememberSessionSummary(summary, for: key)
                    self.summaries[key] = summary
                    self.inFlightKeys.remove(key)
                    Self.sessionInFlight.remove(key)
                    self.activeProbeCount = max(0, self.activeProbeCount - 1)
                    self.drainProbeQueue()
                }
            }
        }
    }

    nonisolated private static func probe(url: URL, fallback: RealMediaTrackSummary) async -> RealMediaTrackSummary {
        let asset = AVURLAsset(url: url, options: ["AVURLAssetHTTPHeaderFieldsKey": [
            "User-Agent": "DebridChannels-tvOS/669 SourceTrackProbe",
            "Accept": "video/*,audio/*,application/vnd.apple.mpegurl,application/x-mpegURL,application/octet-stream,*/*;q=0.8",
            "Accept-Encoding": "identity",
            "Range": "bytes=0-"
        ]])
        do {
            _ = try await asset.load(.availableMediaCharacteristicsWithMediaSelectionOptions)
            var audio: [RealMediaTrackOption] = []
            var subtitles: [RealMediaTrackOption] = []
            if let group = try await asset.loadMediaSelectionGroup(for: .audible) {
                audio = Self.trackOptions(from: group, kind: "Audio")
            }
            if let group = try await asset.loadMediaSelectionGroup(for: .legible) {
                subtitles = Self.trackOptions(from: group, kind: "Subtitle")
            }
            return RealMediaTrackSummary(audio: audio, subtitles: subtitles, didProbe: true).merged(with: fallback)
        } catch {
            return fallback
        }
    }

    nonisolated static func trackOptions(from group: AVMediaSelectionGroup, kind: String) -> [RealMediaTrackOption] {
        var seen = Set<String>()
        return group.options.enumerated().compactMap { index, option in
            let display = option.displayName.trimmingCharacters(in: .whitespacesAndNewlines)
            let code = option.extendedLanguageTag ?? option.locale?.identifier
            let language = MediaTrackLanguageNormalizer.displayName(code: code, fallback: display)
            let format = option.mediaSubTypes.map { "\($0)" }.joined(separator: "/")
            let isForced = option.hasMediaCharacteristic(.containsOnlyForcedSubtitles)
            let isSDH = option.hasMediaCharacteristic(.transcribesSpokenDialogForAccessibility) || option.hasMediaCharacteristic(.describesMusicAndSoundForAccessibility)
            let isDefault = group.defaultOption == option
            var label = language
            if kind == "Subtitle", isForced { label += " Forced" }
            if kind == "Subtitle", isSDH { label += " SDH" }
            if !format.isEmpty { label += " • \(format)" }
            if isDefault { label += " • Default" }
            if label.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty { label = "\(kind) Track \(index + 1)" }
            let identity = "\(kind)|\(label)"
            guard seen.insert(identity).inserted else { return nil }
            return RealMediaTrackOption(
                id: "\(kind.lowercased())-\(index)-\(label)",
                optionIndex: index,
                label: label,
                languageName: language,
                codecOrFormat: format.isEmpty ? nil : format,
                isDefault: isDefault,
                isForced: isForced,
                isSDH: isSDH
            )
        }
    }
}


