// MARK: - v1063 Source Intelligence satellite presentation

private struct SourceIntelligenceSatelliteConnectorCurve: Shape {
    var progress: CGFloat

    var animatableData: CGFloat {
        get { progress }
        set { progress = newValue }
    }

    func path(in rect: CGRect) -> Path {
        var full = Path()
        // Fixed 1920×1080 media-stage geometry: the short connector begins under the
        // Find Links chip and lands at the top edge of the attached satellite panel.
        let start = CGPoint(x: 1518, y: 378)
        let end = CGPoint(x: 1510, y: 515)
        full.move(to: start)
        full.addCurve(
            to: end,
            control1: CGPoint(x: 1560, y: 414),
            control2: CGPoint(x: 1468, y: 477)
        )
        return full.trimmedPath(from: 0, to: min(max(progress, 0), 1))
    }
}

struct SourceIntelligenceSatelliteConnector: View {
    @State private var progress: CGFloat = 0

    var body: some View {
        ZStack {
            SourceIntelligenceSatelliteConnectorCurve(progress: progress)
                .stroke(Color.cyan.opacity(0.18), style: StrokeStyle(lineWidth: 13, lineCap: .round, lineJoin: .round))
                .blur(radius: 8)

            SourceIntelligenceSatelliteConnectorCurve(progress: progress)
                .stroke(
                    LinearGradient(
                        colors: [Color.white.opacity(0.92), Color.cyan.opacity(0.92), Color.white.opacity(0.72)],
                        startPoint: .top,
                        endPoint: .bottom
                    ),
                    style: StrokeStyle(lineWidth: 2.6, lineCap: .round, lineJoin: .round)
                )

            Circle()
                .fill(Color.white.opacity(0.96))
                .frame(width: 8, height: 8)
                .overlay(Circle().stroke(Color.cyan.opacity(0.90), lineWidth: 2))
                .shadow(color: Color.cyan.opacity(0.55), radius: 8)
                .position(x: 1518, y: 378)

            Circle()
                .fill(Color.white.opacity(progress > 0.98 ? 0.96 : 0.0))
                .frame(width: 9, height: 9)
                .overlay(Circle().stroke(Color.cyan.opacity(progress > 0.98 ? 0.92 : 0.0), lineWidth: 2))
                .shadow(color: Color.cyan.opacity(progress > 0.98 ? 0.55 : 0.0), radius: 8)
                .position(x: 1510, y: 515)
        }
        .frame(width: 1920, height: 1080, alignment: .topLeading)
        .onAppear {
            progress = 0
            withAnimation(.easeOut(duration: 0.22)) { progress = 1 }
        }
    }
}

struct SourceIntelligenceSatellitePanel: View {
    let item: MediaItem
    let focus: DetailPage.DetailNode
    let visibleLinks: [StreamLink]
    let allLinks: [StreamLink]
    let linkWindowStart: Int
    let totalLinkCount: Int
    let pageSize: Int
    let isScanning: Bool
    let batchStatus: String
    let openingProvider: String?
    let selectedProvider: String
    let providerOptions: [String]
    let providerStatuses: [SourceProviderRequestStatus]
    let focusedProviderIndex: Int?
    let onSelectProvider: (String) -> Void

    @StateObject private var trackProbe = SourceMediaTrackProbeCache()
    @State private var revealed = false

    private var selectedAbsoluteIndex: Int? {
        if case .stream(let index) = focus { return index }
        return visibleLinks.isEmpty ? nil : linkWindowStart
    }

    private var selectedLink: StreamLink? {
        guard let index = selectedAbsoluteIndex, allLinks.indices.contains(index) else {
            return visibleLinks.first
        }
        return allLinks[index]
    }

    private var rangeText: String {
        guard totalLinkCount > 0 else { return "No sources" }
        let first = min(linkWindowStart + 1, totalLinkCount)
        let last = min(linkWindowStart + visibleLinks.count, totalLinkCount)
        return "\(first)–\(last) of \(totalLinkCount)"
    }

    private var currentPage: Int {
        guard totalLinkCount > 0 else { return 0 }
        return (linkWindowStart / max(pageSize, 1)) + 1
    }

    private var pageCount: Int {
        guard totalLinkCount > 0 else { return 0 }
        return Int(ceil(Double(totalLinkCount) / Double(max(pageSize, 1))))
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            satelliteHeader
            satelliteProviderPicker

            if visibleLinks.isEmpty {
                satelliteEmptyState
            } else if let recommended = visibleLinks.first {
                VStack(alignment: .leading, spacing: 7) {
                    SourceIntelligenceSatelliteRecommendedCard(
                        item: item,
                        link: recommended,
                        absoluteIndex: linkWindowStart,
                        selected: focus == .stream(linkWindowStart),
                        trackSummary: trackProbe.summary(for: recommended),
                        isGlobalRecommendation: linkWindowStart == 0
                    )

                    if visibleLinks.count > 1 {
                        HStack(spacing: 8) {
                            Text(linkWindowStart == 0 ? "OTHER RANKED LINKS" : "MORE RANKED LINKS")
                                .font(.system(size: 9, weight: .black, design: .rounded))
                                .kerning(0.45)
                                .foregroundStyle(.white.opacity(0.48))
                            Rectangle().fill(Color.white.opacity(0.10)).frame(height: 1)
                        }

                        VStack(spacing: 6) {
                            ForEach(Array(visibleLinks.enumerated().dropFirst()), id: \.element.id) { offset, link in
                                let absoluteIndex = linkWindowStart + offset
                                SourceIntelligenceSatelliteLinkRow(
                                    link: link,
                                    absoluteIndex: absoluteIndex,
                                    selected: focus == .stream(absoluteIndex),
                                    trackSummary: trackProbe.summary(for: link)
                                )
                            }
                        }
                    }
                }
            }

            Spacer(minLength: 0)
            satelliteFooter
        }
        .padding(.horizontal, 18)
        .padding(.vertical, 16)
        .frame(width: 700, height: 500, alignment: .topLeading)
        .background(satelliteGlass)
        .clipShape(RoundedRectangle(cornerRadius: 28, style: .continuous))
        .overlay(
            RoundedRectangle(cornerRadius: 28, style: .continuous)
                .stroke(
                    LinearGradient(
                        colors: [Color.white.opacity(0.40), Color.cyan.opacity(0.34), Color.white.opacity(0.10)],
                        startPoint: .topLeading,
                        endPoint: .bottomTrailing
                    ),
                    lineWidth: 1.25
                )
        )
        .overlay {
            if let openingProvider {
                SourceIntelligenceSatelliteOpeningOverlay(provider: openingProvider, link: selectedLink)
            }
        }
        .shadow(color: .black.opacity(0.52), radius: 28, y: 16)
        .shadow(color: .cyan.opacity(0.12), radius: 20)
        .scaleEffect(x: revealed ? 1.0 : 0.985, y: revealed ? 1.0 : 0.04, anchor: .top)
        .opacity(revealed ? 1.0 : 0.0)
        .onAppear {
            trackProbe.probeLinks(allLinks)
            revealed = false
            withAnimation(.spring(response: 0.30, dampingFraction: 0.90)) { revealed = true }
        }
        .onChange(of: allLinks.map(\.id)) { _ in trackProbe.probeLinks(allLinks) }
        .accessibilityIdentifier("V1063SourceIntelligenceSatellitePanel")
    }

    private var satelliteHeader: some View {
        HStack(spacing: 11) {
            ZStack {
                Circle().fill(Color.cyan.opacity(0.17)).frame(width: 40, height: 40)
                Image(systemName: "sparkles.rectangle.stack.fill")
                    .font(.system(size: 20, weight: .black))
                    .foregroundStyle(LinearGradient(colors: [.white, .cyan], startPoint: .top, endPoint: .bottom))
            }

            VStack(alignment: .leading, spacing: 2) {
                Text("SOURCE INTELLIGENCE")
                    .font(.system(size: 20, weight: .black, design: .rounded))
                    .kerning(0.5)
                    .foregroundStyle(.white.opacity(0.96))
                Text(batchStatus.isEmpty ? (isScanning ? "Resolving ranked sources…" : "Ranked links for \(item.title)") : batchStatus)
                    .font(.system(size: 11, weight: .bold, design: .rounded))
                    .foregroundStyle(.white.opacity(0.58))
                    .lineLimit(1)
            }

            Spacer(minLength: 0)

            VStack(alignment: .trailing, spacing: 2) {
                Text(rangeText)
                    .font(.system(size: 12, weight: .black, design: .rounded))
                    .foregroundStyle(.white.opacity(0.78))
                if pageCount > 0 {
                    Text("PAGE \(currentPage) / \(pageCount)")
                        .font(.system(size: 10, weight: .black, design: .rounded))
                        .foregroundStyle(Color.cyan.opacity(0.76))
                }
            }
        }
        .frame(height: 46)
    }

    private var satelliteProviderPicker: some View {
        ScrollView(.horizontal, showsIndicators: false) {
            HStack(spacing: 7) {
                ForEach(Array(providerOptions.enumerated()), id: \.offset) { index, provider in
                    SourceProviderPickerChip(
                        provider: provider,
                        selected: provider == selectedProvider,
                        focused: focusedProviderIndex == index,
                        status: providerStatus(for: provider)
                    )
                    .contentShape(Capsule())
                    .onTapGesture { onSelectProvider(provider) }
                }
            }
            .padding(.vertical, 1)
        }
        .frame(width: 664, height: 42, alignment: .leading)
    }

    private var satelliteEmptyState: some View {
        VStack(spacing: 12) {
            if isScanning { ProgressView().scaleEffect(1.0) }
            Image(systemName: isScanning ? "antenna.radiowaves.left.and.right" : "link.badge.plus")
                .font(.system(size: 34, weight: .light))
                .foregroundStyle(Color.cyan.opacity(0.82))
            Text(isScanning ? "Finding playable links…" : "No links found yet")
                .font(.system(size: 18, weight: .black, design: .rounded))
                .foregroundStyle(.white.opacity(0.88))
            Text(selectedProvider == "All Providers" ? "Provider results appear here without leaving the media popup." : "Try All Providers or another source provider.")
                .font(.system(size: 12, weight: .semibold, design: .rounded))
                .foregroundStyle(.white.opacity(0.52))
                .multilineTextAlignment(.center)
        }
        .frame(maxWidth: .infinity, minHeight: 280)
    }

    private var satelliteFooter: some View {
        HStack(spacing: 9) {
            Image(systemName: "arrow.up.arrow.down.circle.fill")
                .font(.system(size: 14, weight: .black))
                .foregroundStyle(Color.cyan.opacity(0.86))
            Text("UP / DOWN LINKS")
                .font(.system(size: 10, weight: .black, design: .rounded))
                .foregroundStyle(.white.opacity(0.62))

            Divider().frame(height: 14).overlay(Color.white.opacity(0.14))

            Image(systemName: "arrow.left.arrow.right.circle.fill")
                .font(.system(size: 14, weight: .black))
                .foregroundStyle(Color.cyan.opacity(0.86))
            Text("LEFT / RIGHT PAGES")
                .font(.system(size: 10, weight: .black, design: .rounded))
                .foregroundStyle(.white.opacity(0.62))

            Spacer(minLength: 0)

            Text("BACK CLOSES PANEL")
                .font(.system(size: 9, weight: .black, design: .rounded))
                .foregroundStyle(.white.opacity(0.38))
        }
        .padding(.horizontal, 12)
        .frame(height: 30)
        .background(RoundedRectangle(cornerRadius: 15, style: .continuous).fill(Color.black.opacity(0.18)))
        .overlay(RoundedRectangle(cornerRadius: 15, style: .continuous).stroke(Color.white.opacity(0.08), lineWidth: 1))
    }

    private var satelliteGlass: some View {
        ZStack {
            // Approximately 75% transparent overall. Darker local link rows provide
            // text contrast while the catalog/Live TV stage remains visible through it.
            RoundedRectangle(cornerRadius: 28, style: .continuous)
                .fill(.ultraThinMaterial)
                .opacity(0.30)
            RoundedRectangle(cornerRadius: 28, style: .continuous)
                .fill(Color.black.opacity(0.20))
            RoundedRectangle(cornerRadius: 28, style: .continuous)
                .fill(
                    LinearGradient(
                        colors: [Color.cyan.opacity(0.055), Color.clear, Color.white.opacity(0.025)],
                        startPoint: .topLeading,
                        endPoint: .bottomTrailing
                    )
                )
        }
    }

    private func providerStatus(for provider: String) -> SourceProviderRequestStatus? {
        guard provider != "All Providers" else { return nil }
        return providerStatuses.first {
            $0.provider.caseInsensitiveCompare(provider) == .orderedSame ||
            $0.provider.lowercased().contains(provider.lowercased())
        }
    }
}


struct SourceIntelligenceSatelliteRecommendedCard: View {
    let item: MediaItem
    let link: StreamLink
    let absoluteIndex: Int
    let selected: Bool
    let trackSummary: RealMediaTrackSummary?
    let isGlobalRecommendation: Bool

    private var summary: RealMediaTrackSummary {
        let parsed = SourceLinkMetadataParser.summary(for: link)
        return (trackSummary ?? parsed).merged(with: parsed)
    }

    private var accent: Color {
        if link.sourceWarning != nil { return .orange }
        if link.sourceIntelligenceIsCached { return .green }
        return link.isDirectPlayable ? .cyan : .orange
    }

    private var sizeText: String {
        let gb = link.sourceIntelligenceSizeGB
        if gb.isFinite, gb < Double.greatestFiniteMagnitude {
            return String(format: gb >= 10 ? "%.0f GB" : "%.1f GB", gb)
        }
        let clean = link.size.trimmingCharacters(in: .whitespacesAndNewlines)
        return clean.isEmpty ? "SIZE UNKNOWN" : clean
    }

    private var qualityText: String {
        let value = summary.resolution ?? link.detectedResolution
        return value.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? "QUALITY UNKNOWN" : value
    }

    private var audioText: String {
        if let value = summary.audioCodecText, !value.isEmpty { return value }
        if let value = link.detectedAudio, !value.isEmpty { return value }
        return "AUDIO UNKNOWN"
    }

    private var confidenceText: String {
        var score = 52
        if link.sourceIntelligenceIsCached { score += 20 }
        if link.sourceIntelligenceIsEnglish { score += 12 }
        if link.sourceIntelligenceResolutionRank == 0 { score += 8 }
        if link.isDirectPlayable { score += 6 }
        if link.sourceWarning != nil { score -= 18 }
        return "\(min(max(score, 1), 99))% MATCH"
    }

    var body: some View {
        HStack(spacing: 13) {
            ZStack {
                RoundedRectangle(cornerRadius: 14, style: .continuous)
                    .fill(accent.opacity(selected ? 0.27 : 0.14))
                VStack(spacing: 2) {
                    Image(systemName: isGlobalRecommendation ? "crown.fill" : "chart.line.uptrend.xyaxis")
                        .font(.system(size: 17, weight: .black))
                    Text("#\(absoluteIndex + 1)")
                        .font(.system(size: 10, weight: .black, design: .rounded))
                }
                .foregroundStyle(.white.opacity(0.94))
            }
            .frame(width: 54, height: 72)

            VStack(alignment: .leading, spacing: 5) {
                HStack(spacing: 7) {
                    Text(isGlobalRecommendation ? "TOP RECOMMENDED LINK" : "BEST ON THIS PAGE")
                        .font(.system(size: 10, weight: .black, design: .rounded))
                        .kerning(0.55)
                        .foregroundStyle(accent.opacity(0.95))
                    SourceMiniPill(title: confidenceText, tint: accent)
                }

                Text(link.vodLinkPrimaryLine)
                    .font(.system(size: 16, weight: .black, design: .rounded))
                    .foregroundStyle(.white.opacity(0.98))
                    .lineLimit(1)

                HStack(spacing: 6) {
                    SourceSatelliteMiniPill(text: qualityText, tint: .cyan)
                    if let hdr = summary.hdrType ?? link.detectedHDR { SourceSatelliteMiniPill(text: hdr, tint: .purple) }
                    if link.sourceIntelligenceIsCached { SourceSatelliteMiniPill(text: "CACHED", tint: .green) }
                    SourceSatelliteMiniPill(text: link.sourceIntelligenceLanguageLabel, tint: link.sourceIntelligenceIsEnglish ? .green : .orange)
                    SourceSatelliteMiniPill(text: audioText, tint: .blue)
                }
            }

            Spacer(minLength: 0)

            VStack(alignment: .trailing, spacing: 5) {
                Text(sizeText)
                    .font(.system(size: 12, weight: .black, design: .rounded))
                    .foregroundStyle(.white.opacity(0.84))
                Text(link.providerDisplay.uppercased())
                    .font(.system(size: 9, weight: .black, design: .rounded))
                    .foregroundStyle(.white.opacity(0.48))
                    .lineLimit(1)
                Image(systemName: selected ? "play.circle.fill" : "chevron.right.circle.fill")
                    .font(.system(size: 20, weight: .bold))
                    .foregroundStyle(accent.opacity(selected ? 1.0 : 0.52))
            }
        }
        .padding(.horizontal, 13)
        .frame(height: 100)
        .background(
            RoundedRectangle(cornerRadius: 19, style: .continuous)
                .fill(selected ? accent.opacity(0.23) : Color.black.opacity(0.23))
        )
        .overlay(
            RoundedRectangle(cornerRadius: 19, style: .continuous)
                .stroke(selected ? Color.white.opacity(0.90) : accent.opacity(0.28), lineWidth: selected ? 2 : 1)
        )
        .shadow(color: selected ? accent.opacity(0.28) : .clear, radius: 14)
        .scaleEffect(selected ? 1.008 : 1.0)
        .animation(.easeOut(duration: 0.14), value: selected)
        .accessibilityLabel("Top recommended source \(absoluteIndex + 1), \(link.vodLinkPrimaryLine)")
    }
}

struct SourceIntelligenceSatelliteLinkRow: View {
    let link: StreamLink
    let absoluteIndex: Int
    let selected: Bool
    let trackSummary: RealMediaTrackSummary?

    private var accent: Color {
        if link.sourceWarning != nil { return .orange }
        if link.sourceIntelligenceIsCached { return .green }
        return link.isDirectPlayable ? .cyan : .orange
    }

    private var sizeText: String {
        let gb = link.sourceIntelligenceSizeGB
        if gb.isFinite, gb < Double.greatestFiniteMagnitude {
            return String(format: gb >= 10 ? "%.0f GB" : "%.1f GB", gb)
        }
        let clean = link.size.trimmingCharacters(in: .whitespacesAndNewlines)
        return clean.isEmpty ? "SIZE ?" : clean
    }

    private var audioText: String? {
        if let audio = link.detectedAudio?.trimmingCharacters(in: .whitespacesAndNewlines), !audio.isEmpty { return audio }
        if let codec = trackSummary?.audioCodecText, !codec.isEmpty { return codec }
        return nil
    }

