            satelliteMetadata



            Spacer(minLength: 0)

            VStack(alignment: .trailing, spacing: 3) {
                Text(sizeText)
                    .font(.system(size: 11, weight: .black, design: .rounded))
                    .foregroundStyle(.white.opacity(0.76))
                Text(link.isDirectPlayable ? "DIRECT" : "RESOLVE")
                    .font(.system(size: 9, weight: .black, design: .rounded))
                    .foregroundStyle(accent.opacity(0.94))
            }
        }
    }

    private var satelliteFill: Color {
        selected ? accent.opacity(0.24) : Color.black.opacity(0.19)
    }

    private var satelliteStroke: Color {
        selected ? Color.white.opacity(0.88) : Color.white.opacity(0.075)
