        )
    }

    var body: some View {
        satelliteBase
            .overlay(
                RoundedRectangle(cornerRadius: 16, style: .continuous)
                    .stroke(satelliteStroke, lineWidth: selected ? 2 : 1)
            )
            .shadow(color: selected ? accent.opacity(0.24) : Color.clear, radius: 12)
            .scaleEffect(selected ? 1.012 : 1.0)
            .animation(.easeOut(duration: 0.14), value: selected)
            .accessibilityLabel("Source \(absoluteIndex + 1), \(link.vodLinkPrimaryLine)")
