struct SourceIntelligenceSatelliteOpeningOverlay: View {
    let provider: String
    let link: StreamLink?

    var body: some View {
        ZStack {
            RoundedRectangle(cornerRadius: 28, style: .continuous)
                .fill(Color.black.opacity(0.70))

            VStack(spacing: 13) {
                ProgressView().scaleEffect(1.10)
                Text("OPENING STREAM")
                    .font(.system(size: 20, weight: .black, design: .rounded))
                    .foregroundStyle(.white)
                Text(openingText)
                    .font(.system(size: 12, weight: .bold, design: .rounded))
                    .foregroundStyle(.white.opacity(0.62))
                    .lineLimit(2)
                    .multilineTextAlignment(.center)
            }
            .padding(24)
            .background(RoundedRectangle(cornerRadius: 20, style: .continuous).fill(Color.black.opacity(0.46)))
            .overlay(RoundedRectangle(cornerRadius: 20, style: .continuous).stroke(Color.cyan.opacity(0.28), lineWidth: 1))
        }
    }

    private var openingText: String {
        var parts = [provider.trimmingCharacters(in: .whitespacesAndNewlines)]
        if let quality = link?.detectedResolution, !quality.isEmpty, quality != "Quality Unknown" { parts.append(quality) }
        return parts.filter { !$0.isEmpty }.joined(separator: " • ")
    }
}


// MARK: - v1072 Embedded Source Intelligence neutral chrome
// Presentation only: the resolver, ranking, provider filtering, paging, selection,
// and playback handoff remain owned by MediaInfoPopup/CatalogStore.
struct SourceIntelligenceEmbeddedLowerPanel: View {
    let item: MediaItem
    let focus: DetailPage.DetailNode
    let visibleLinks: [StreamLink]
    let allLinks: [StreamLink]
    let linkWindowStart: Int
    let totalLinkCount: Int
    let isScanning: Bool
    let batchStatus: String
    let selectedProvider: String
    let providerOptions: [String]
    let providerStatuses: [SourceProviderRequestStatus]
    let focusedProviderIndex: Int?
    let onSelectProvider: (String) -> Void

    private let panelWidth: CGFloat = 808
    private let contentWidth: CGFloat = 780

    private var resumeEntry: PlaybackResumeEntry? {
        PlaybackResumeCacheManager.shared.resumeEntry(for: item)
    }

    private var rangeText: String {
        guard totalLinkCount > 0 else { return "0 sources" }
        let first = min(linkWindowStart + 1, totalLinkCount)
        let last = min(linkWindowStart + visibleLinks.count, totalLinkCount)
        return "\(first)–\(last) of \(totalLinkCount)"
    }

    private var pageText: String {
        guard totalLinkCount > 0 else { return "PAGE 1" }
        let current = (linkWindowStart / 5) + 1
        let total = max(1, Int(ceil(Double(totalLinkCount) / 5.0)))
        return "PAGE \(current) / \(total)"
    }

