struct EmbeddedSourceProviderStrip: View {
    let options: [String]
    let selectedProvider: String
    let focusedIndex: Int?
    let statuses: [SourceProviderRequestStatus]
    let onSelect: (String) -> Void

    var body: some View {
        ScrollView(.horizontal, showsIndicators: false) {
            HStack(spacing: 7) {
                ForEach(Array(options.enumerated()), id: \.offset) { index, provider in
                    providerChip(index: index, provider: provider)
                }
            }
            .padding(.horizontal, 1)
        }
    }

    private func providerChip(index: Int, provider: String) -> some View {
                    let status = providerStatus(provider)
                    let focused = focusedIndex == index
                    let selected = provider.caseInsensitiveCompare(selectedProvider) == .orderedSame
                    return HStack(spacing: 6) {
                        if status?.state == .searching {
                            ProgressView().scaleEffect(0.50)
                        } else {
                            Circle()
                                .fill(providerTint(status).opacity(0.92))
                                .frame(width: 7, height: 7)
                        }
                        Text(provider)
                            .font(.system(size: 10, weight: .black, design: .rounded))
                            .foregroundStyle(.white.opacity(0.88))
                            .lineLimit(1)
                        if let count = status?.linkCount, count > 0 {
                            Text("\(count)")
                                .font(.system(size: 9, weight: .black, design: .rounded))
                                .foregroundStyle(.black.opacity(0.82))
                                .padding(.horizontal, 5)
                                .padding(.vertical, 1)
                                .background(Capsule().fill(providerTint(status).opacity(0.92)))
                        }
                    }
                    .padding(.horizontal, 10)
                    .frame(height: 30)
                    .background(Capsule().fill(selected ? providerTint(status).opacity(0.22) : Color.white.opacity(0.045)))
                    .overlay(Capsule().stroke(focused ? Color.white.opacity(0.92) : (selected ? providerTint(status).opacity(0.58) : Color.white.opacity(0.09)), lineWidth: focused ? 1.8 : 1))
                    .scaleEffect(focused ? 1.035 : 1.0)
                    .contentShape(Capsule())
                    .onTapGesture { onSelect(provider) }
    }

    private func providerStatus(_ provider: String) -> SourceProviderRequestStatus? {
        guard provider != "All Providers" else { return nil }
        return statuses.first {
            $0.provider.caseInsensitiveCompare(provider) == .orderedSame ||
            $0.provider.lowercased().contains(provider.lowercased())
        }
    }

    private func providerTint(_ status: SourceProviderRequestStatus?) -> Color {
        switch status?.state {
        case .returnedLinks: return Color(red: 0.46, green: 0.74, blue: 1.0)
        case .searching: return .cyan
        case .failed, .timeout: return .orange
        case .noLinks: return .gray
        case nil: return Color.white.opacity(0.72)
        }
    }
}

struct EmbeddedBestSourceCard: View {
    let item: MediaItem
    let link: StreamLink
    let rank: Int
    let selected: Bool

    private var summary: RealMediaTrackSummary { SourceLinkMetadataParser.summary(for: link) }
    private var confidence: Int {
        var score = 74
        if link.sourceIntelligenceIsCached { score += 10 }
        if link.sourceIntelligenceIsEnglish { score += 6 }
        if link.detectedResolution.lowercased().contains("4k") || link.detectedResolution.lowercased().contains("2160") { score += 5 }
        if link.matchLabel.lowercased().contains("exact") { score += 4 }
        return min(99, score)
    }

    var body: some View {
        HStack(spacing: 13) {
            VStack(spacing: 2) {
                Image(systemName: "crown.fill")
                    .font(.system(size: 19, weight: .black))
                    .foregroundStyle(LinearGradient(colors: [.white, Color.green], startPoint: .top, endPoint: .bottom))
                Text("#\(rank)")
                    .font(.system(size: 12, weight: .black, design: .rounded))
                    .foregroundStyle(.white.opacity(0.72))
            }
            .frame(width: 48, height: 76)
            .background(RoundedRectangle(cornerRadius: 16, style: .continuous).fill(Color.green.opacity(0.16)))

            VStack(alignment: .leading, spacing: 7) {
                HStack(spacing: 8) {
                    Text("TOP RECOMMENDED LINK")
                        .font(.system(size: 11, weight: .black, design: .rounded))
                        .kerning(0.8)
                        .foregroundStyle(Color.green.opacity(0.96))
                    Text("\(confidence)% MATCH")
                        .font(.system(size: 10, weight: .black, design: .rounded))
                        .foregroundStyle(.black.opacity(0.82))
                        .padding(.horizontal, 7)
                        .padding(.vertical, 3)
                        .background(Capsule().fill(Color.green.opacity(0.92)))
                }

                Text(link.title)
                    .font(.system(size: 15, weight: .black, design: .rounded))
                    .foregroundStyle(.white.opacity(0.96))
                    .lineLimit(1)
                    .truncationMode(.middle)

                HStack(spacing: 6) {
                    EmbeddedSourcePill(text: link.sourceIntelligenceCacheLabel.uppercased(), tint: link.sourceIntelligenceIsCached ? .green : .orange)
                    EmbeddedSourcePill(text: link.detectedResolution, tint: Color(red: 0.52, green: 0.78, blue: 1.0))
                    EmbeddedSourcePill(text: link.sourceIntelligenceLanguageLabel, tint: link.sourceIntelligenceIsEnglish ? .cyan : .gray)
                    if let hdr = summary.hdrType ?? link.detectedHDR { EmbeddedSourcePill(text: hdr, tint: .purple) }
                    if !link.size.isEmpty { EmbeddedSourcePill(text: link.size, tint: .white) }
                }
                .lineLimit(1)
            }

            Spacer(minLength: 8)

            VStack(alignment: .trailing, spacing: 7) {
                Text(link.providerDisplay.uppercased())
                    .font(.system(size: 10, weight: .black, design: .rounded))
                    .foregroundStyle(.white.opacity(0.55))
                    .lineLimit(1)
                Image(systemName: selected ? "checkmark.circle.fill" : "chevron.right.circle.fill")
                    .font(.system(size: 27, weight: .black))
                    .foregroundStyle(selected ? Color.green : Color.white.opacity(0.28))
            }
        }
        .padding(.horizontal, 14)
        .frame(width: 780, height: 108)
        .background {
            ZStack {
                RoundedRectangle(cornerRadius: 22, style: .continuous)
                    .fill(Color.black.opacity(0.24))
                RoundedRectangle(cornerRadius: 22, style: .continuous)
                    .fill(LinearGradient(colors: [Color.green.opacity(selected ? 0.22 : 0.13), Color.teal.opacity(0.05), .clear], startPoint: .leading, endPoint: .trailing))
            }
        }
        .overlay(RoundedRectangle(cornerRadius: 22, style: .continuous).stroke(selected ? Color.green.opacity(0.92) : Color.green.opacity(0.30), lineWidth: selected ? 2 : 1))
        .shadow(color: selected ? Color.green.opacity(0.20) : .clear, radius: 16, y: 6)
        .scaleEffect(selected ? 1.012 : 1.0)
    }
}

