// v1068: Centered transparent Source Intelligence presentation.
struct SourceIntelligenceFullOverlay: View {
    let item: MediaItem
    let focus: DetailPage.DetailNode
    let visibleLinks: [StreamLink]
    let allLinks: [StreamLink]
    let linkWindowStart: Int
    let totalLinkCount: Int
    let isScanning: Bool
    let batchStatus: String
    let openingProvider: String?
    let selectedProvider: String
    let providerOptions: [String]
    let providerStatuses: [SourceProviderRequestStatus]
    let focusedProviderIndex: Int?
    let onSelectProvider: (String) -> Void
    @StateObject private var trackProbe = SourceMediaTrackProbeCache()

    private var selectedAbsoluteIndex: Int? {
        if case .stream(let index) = focus { return index }
        return visibleLinks.isEmpty ? nil : linkWindowStart
    }

    private var selectedLink: StreamLink? {
        guard let index = selectedAbsoluteIndex else { return visibleLinks.first }
        let local = index - linkWindowStart
        guard visibleLinks.indices.contains(local) else { return visibleLinks.first }
        return visibleLinks[local]
    }

    private var rangeText: String {
        guard totalLinkCount > 0 else { return "No sources yet" }
        let first = min(linkWindowStart + 1, totalLinkCount)
        let last = min(linkWindowStart + visibleLinks.count, totalLinkCount)
        return "\(first)-\(last) of \(totalLinkCount)"
    }

    private var visibleSecondaryLinks: [(offset: Int, element: StreamLink)] {
        Array(Array(visibleLinks.enumerated()).dropFirst())
    }

    private var lowestKnownGB: Double? {
        let values = allLinks.map(\.sourceIntelligenceSizeGB).filter { $0.isFinite && $0 < Double.greatestFiniteMagnitude }
        return values.min()
    }

    private func isLowestKnownSize(_ link: StreamLink) -> Bool {
        guard let lowestKnownGB else { return false }
        let size = link.sourceIntelligenceSizeGB
        guard size.isFinite && size < Double.greatestFiniteMagnitude else { return false }
        return abs(size - lowestKnownGB) < 0.05
    }

