struct SourceProviderStatusStrip: View {
    let statuses: [SourceProviderRequestStatus]
    let selectedProvider: String

    private var visibleStatuses: [SourceProviderRequestStatus] {
        if selectedProvider == "All Providers" {
            // vBRDC051: TorBox Usenet is an additive provider and is normally appended
            // after the first several addon statuses. Pin it into the five visible pills
            // so a real-account test can always see returned links, zero results, or the
            // exact TorBox API error instead of silently hiding the diagnostic.
            if let usenet = statuses.first(where: { $0.provider.caseInsensitiveCompare("TorBox Usenet") == .orderedSame }) {
                let others = statuses.filter { $0.id != usenet.id }
                return [usenet] + Array(others.prefix(4))
            }
            return Array(statuses.prefix(5))
        }
        return statuses.filter { $0.provider.caseInsensitiveCompare(selectedProvider) == .orderedSame || $0.provider.lowercased().contains(selectedProvider.lowercased()) }.prefix(5).map { $0 }
    }

    var body: some View {
        HStack(spacing: 8) {
            if visibleStatuses.isEmpty {
                SourceProviderStatusPill(title: "Provider status will appear here", tint: .white)
            } else {
                ForEach(visibleStatuses) { status in
                    SourceProviderStatusPill(title: "\(status.provider): \(status.message)", tint: tint(for: status.state))
                }
            }
            Spacer(minLength: 0)
        }
        .frame(maxWidth: .infinity, minHeight: 30, maxHeight: 30, alignment: .leading)
    }

    private func tint(for state: SourceProviderRequestState) -> Color {
        switch state {
        case .searching: return .cyan
        case .returnedLinks: return .green
        case .noLinks: return .white
        case .failed, .timeout: return .orange
        }
    }
}

