enum SourceVisualRules {
    static func isExactMatch(item: MediaItem, link: StreamLink) -> Bool {
        let lower = link.sourceIntelligenceHaystack
        if let season = item.seasonNumber, let episode = item.episodeNumber {
            let s = String(format: "%02d", season)
            let e = String(format: "%02d", episode)
            return lower.range(of: "\\bs0?\(season)[ ._-]*e0?\(episode)\\b", options: .regularExpression) != nil ||
                lower.contains("s\(s)e\(e)") ||
                lower.contains("\(season)x\(e)") ||
                lower.contains("season \(season) episode \(episode)")
        }
        let title = item.title.lowercased().replacingOccurrences(of: #"[^a-z0-9]+"#, with: " ", options: .regularExpression).trimmingCharacters(in: .whitespacesAndNewlines)
        return title.count >= 3 && lower.replacingOccurrences(of: #"[^a-z0-9]+"#, with: " ", options: .regularExpression).contains(title)
    }

    static func confidenceScore(item: MediaItem, link: StreamLink, summary: RealMediaTrackSummary, isLowestGB: Bool) -> Int {
        var score = 42
        if isExactMatch(item: item, link: link) { score += 22 }
        if link.sourceIntelligenceIsCached { score += 16 }
        if link.sourceIntelligenceIsEnglish { score += 10 }
        if link.sourceIntelligenceResolutionRank == 0 { score += 6 }
        if isLowestGB { score += 4 }
        if link.isDirectPlayable { score += 6 }
        if summary.sourceWarning != nil { score -= 10 }
        return min(99, max(35, score))
    }
}

