            Text("\(index)")
                .font(.system(size: 18, weight: .black, design: .rounded))
                .foregroundStyle(.white.opacity(0.72))
                .frame(width: 34, height: 34)
                .background(Circle().fill(accent.opacity(selected ? 0.24 : 0.10)))

            VStack(alignment: .leading, spacing: 7) {
                Text(link.title)
                    .font(.system(size: 17, weight: .black, design: .rounded))
                    .foregroundStyle(.white.opacity(0.95))
                    .lineLimit(1)
                    .truncationMode(.tail)

                HStack(spacing: 8) {
                    if isExactMatch { SourceMiniPill(title: item.seasonNumber == nil ? "Exact Movie" : "Exact Episode", tint: .green) }
                    if link.sourceIntelligenceIsCached { SourceMiniPill(title: "Cached", tint: .green) }
                    SourceMiniPill(title: displaySummary.resolution ?? link.detectedResolution, tint: .orange)
                    SourceMiniPill(title: link.sourceIntelligenceLanguageLabel, tint: link.sourceIntelligenceIsEnglish ? .green : .cyan)
                    if isLowestGB { SourceMiniPill(title: "Lowest GB", tint: .white) }
                    if let codec = displaySummary.videoCodec ?? link.detectedCodec { SourceMiniPill(title: codec, tint: .blue) }
                    if !link.size.isEmpty { SourceMiniPill(title: link.size, tint: .white) }
                }
                .lineLimit(1)
                .clipped()
            }
            Spacer(minLength: 0)
            VStack(alignment: .trailing, spacing: 7) {
                SourceConfidenceMeter(score: confidence, accent: accent)
                    .frame(width: 160)
                Text(link.providerDisplay)
                    .font(.system(size: 12, weight: .black, design: .rounded))
                    .foregroundStyle(.white.opacity(0.50))
                    .lineLimit(1)
            }
            Image(systemName: selected ? "play.circle.fill" : "chevron.right.circle")
                .font(.system(size: 27, weight: .bold))
                .foregroundStyle(accent.opacity(selected ? 0.98 : 0.38))
        }
        .padding(.horizontal, 16)
        .frame(width: 1348, height: 60, alignment: .leading)
        .background(
            ZStack {
                RoundedRectangle(cornerRadius: 20, style: .continuous)
                    .fill(Color.black.opacity(selected ? 0.76 : 0.66))
                RoundedRectangle(cornerRadius: 20, style: .continuous)
                    .fill(selected ? accent.opacity(0.13) : Color.white.opacity(0.030))
                RoundedRectangle(cornerRadius: 20, style: .continuous)
                    .fill(LinearGradient(colors: [.white.opacity(selected ? 0.08 : 0.032), .clear], startPoint: .topLeading, endPoint: .bottomTrailing))
            }
        )
        .overlay(RoundedRectangle(cornerRadius: 20, style: .continuous).stroke(selected ? accent.opacity(0.84) : Color.white.opacity(0.10), lineWidth: selected ? 1.9 : 1.0))
        .shadow(color: selected ? accent.opacity(0.30) : .clear, radius: 18, y: 8)
    }
}

struct SourceIntelligenceDetailPanel: View {
    let item: MediaItem
    let link: StreamLink?
    let totalLinkCount: Int
    let trackSummary: RealMediaTrackSummary?
    let isCheckingTracks: Bool

    private var displaySummary: RealMediaTrackSummary? {
        guard let link else { return nil }
        return (trackSummary ?? SourceLinkMetadataParser.summary(for: link)).merged(with: SourceLinkMetadataParser.summary(for: link))
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 14) {
            HStack(spacing: 12) {
                let detailArt = (item.landscapeURL?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false) ? item.landscapeURL : item.posterURL
                if let poster = detailArt, !poster.isEmpty {
                    RemoteImageFit(url: poster, mode: .fit)
                        .frame(width: 132, height: 82)
                        .background(RoundedRectangle(cornerRadius: 16, style: .continuous).fill(Color.black.opacity(0.42)))
                        .clipShape(RoundedRectangle(cornerRadius: 16, style: .continuous))
                }
                VStack(alignment: .leading, spacing: 5) {
                    Text(item.title)
                        .font(.system(size: 25, weight: .black, design: .rounded))
                        .foregroundStyle(.white.opacity(0.96))
                        .lineLimit(2)
                    Text("\(totalLinkCount) source\(totalLinkCount == 1 ? "" : "s") found")
                        .font(.system(size: 14, weight: .bold, design: .rounded))
                        .foregroundStyle(.white.opacity(0.55))
                }
            }

            Divider().overlay(Color.white.opacity(0.14))

            if let link {
                let summary = displaySummary ?? SourceLinkMetadataParser.summary(for: link)
                SourceDetailLine(label: "Quality", value: summary.resolution ?? link.detectedResolution, tint: .orange)
                SourceDetailLine(label: "Audio", value: isCheckingTracks ? "checking tracks..." : summary.audioLanguagesText.replacingOccurrences(of: "Audio: ", with: ""), tint: .cyan)
                SourceDetailLine(label: "Audio Codec", value: summary.audioCodecText ?? link.detectedAudio ?? "Unknown", tint: .cyan)
                SourceDetailLine(label: "Subtitles", value: isCheckingTracks ? "checking tracks..." : summary.subtitleLanguagesText.replacingOccurrences(of: "Subtitles: ", with: ""), tint: .purple)
                SourceDetailLine(label: "Sub Format", value: summary.subtitleFormatText ?? "Unknown", tint: .purple)
                SourceDetailLine(label: "Sub Flags", value: summary.subtitleMarkersText ?? "None", tint: .orange)
                SourceDetailLine(label: "Codec", value: summary.videoCodec ?? link.detectedCodec ?? "Unknown", tint: .blue)
                SourceDetailLine(label: "HDR", value: summary.hdrType ?? link.detectedHDR ?? "Unknown", tint: .purple)
                if let warning = summary.sourceWarning {
                    SourceDetailLine(label: "Warning", value: warning, tint: .orange)
                }
                SourceDetailLine(label: "Size", value: link.size.isEmpty ? "Unknown" : link.size, tint: .white)
                SourceDetailLine(label: "Cache", value: link.sourceIntelligenceCacheLabel, tint: link.sourceIntelligenceIsCached ? .green : .orange)
                SourceDetailLine(label: "Provider", value: link.providerDisplay, tint: .blue)
                SourceDetailLine(label: "Safety", value: summary.sourceWarning ?? link.matchLabel, tint: summary.sourceWarning == nil ? .green : .orange)

                Text("Press SELECT to play. UP/DOWN stays on visible links. LEFT/RIGHT changes pages. MENU/BACK closes Source Intelligence.")
                    .font(.system(size: 11, weight: .semibold, design: .rounded))
                    .foregroundStyle(.white.opacity(0.48))
                    .padding(.top, 8)
            } else {
                Text("No selected source yet. Press Find Links and wait for addon results.")
                    .font(.system(size: 17, weight: .bold, design: .rounded))
                    .foregroundStyle(.white.opacity(0.62))
            }
            Spacer(minLength: 0)
        }
        .padding(18)
        .background(RoundedRectangle(cornerRadius: 26, style: .continuous).fill(Color.black.opacity(0.35)))
        .overlay(RoundedRectangle(cornerRadius: 26, style: .continuous).stroke(Color.white.opacity(0.12), lineWidth: 1))
    }
}

struct SourceOpeningStreamOverlay: View {
    let provider: String
    let link: StreamLink?
    @State private var stageIndex = 0

    private let stages = [
        "Resolving source…",
        "Checking media…",
        "Preparing playback…",
        "Launching internal player…"
    ]

    private var currentStage: String {
        stages[min(stageIndex, stages.count - 1)]
    }

    var body: some View {
        ZStack {
            Color.black.opacity(0.56)
                .clipShape(RoundedRectangle(cornerRadius: 34, style: .continuous))
            VStack(spacing: 16) {
                ProgressView()
                    .scaleEffect(1.35)
                Text("Opening Stream…")
                    .font(.system(size: 30, weight: .black, design: .rounded))
                    .foregroundStyle(.white)
                Text(openingDetailText)
                    .font(.system(size: 17, weight: .bold, design: .rounded))
                    .foregroundStyle(.white.opacity(0.64))
                    .lineLimit(2)
                    .multilineTextAlignment(.center)
                HStack(spacing: 9) {
                    ForEach(Array(stages.enumerated()), id: \.offset) { index, stage in
                        HStack(spacing: 6) {
                            Circle()
                                .fill(index <= stageIndex ? Color.cyan.opacity(0.95) : Color.white.opacity(0.18))
                                .frame(width: 7, height: 7)
                            Text(index == stageIndex ? currentStage : stage)
                                .font(.system(size: 11, weight: .black, design: .rounded))
                                .foregroundStyle(index <= stageIndex ? .white.opacity(0.86) : .white.opacity(0.38))
                                .lineLimit(1)
                        }
                    }
                }
            }
            .padding(34)
            .background(RoundedRectangle(cornerRadius: 24, style: .continuous).fill(Color.black.opacity(0.72)))
            .overlay(RoundedRectangle(cornerRadius: 24, style: .continuous).stroke(Color.white.opacity(0.16), lineWidth: 1))
        }
        .allowsHitTesting(true)
        .onAppear { advanceStages() }
    }

    private var openingDetailText: String {
        var parts: [String] = []
        let providerText = provider.trimmingCharacters(in: .whitespacesAndNewlines)
        if !providerText.isEmpty { parts.append(providerText) }
        if let quality = link?.detectedResolution, !quality.isEmpty, quality != "Quality Unknown" { parts.append(quality) }
        if let title = link?.title.trimmingCharacters(in: .whitespacesAndNewlines), !title.isEmpty { parts.append(title) }
        return parts.isEmpty ? "Preparing internal player" : parts.prefix(3).joined(separator: " • ")
    }

    private func advanceStages() {
        VODExclusiveWorkRegistry.start {
            for index in 1..<stages.count {
                try? await Task.sleep(nanoseconds: 700_000_000)
                await MainActor.run { stageIndex = index }
            }
        }
    }
}

