struct PopupHeaderDetails: Hashable {
    var budget: Int? = nil
    var revenue: Int? = nil
    var runtimeMinutes: Int? = nil
    var studio: String? = nil
    var seasons: Int? = nil
    var episodes: Int? = nil
    var status: String? = nil
    var network: String? = nil
    var certification: String? = nil
}

/// vBRDC084: Search-origin details should not open with a half-empty Production
/// information strip while the same TMDB request is rebuilt from zero. This small
/// session cache is identity-exact and is prewarmed by Global Search for the visible
/// result set. It stores metadata only; artwork/player/provider state is untouched.
private final class PopupHeaderDetailsService {
    static let shared = PopupHeaderDetailsService()

    private let lock = NSLock()
    private var cache: [String: PopupHeaderDetails] = [:]
    private var cacheOrder: [String] = []
    private let maximumEntries = 80

    private init() {}

    func cached(for item: MediaItem) -> PopupHeaderDetails? {
        let key = cacheKey(for: item)
        lock.lock(); defer { lock.unlock() }
        return cache[key]
    }

    func details(for item: MediaItem, apiKey rawKey: String) async -> PopupHeaderDetails? {
        if let cached = cached(for: item) { return cached }
        let apiKey = rawKey.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !apiKey.isEmpty else { return nil }
        guard let fetched = await fetch(item: item, apiKey: apiKey) else { return nil }
        let key = cacheKey(for: item)
        lock.lock()
        cache[key] = fetched
        cacheOrder.removeAll { $0 == key }
        cacheOrder.append(key)
        while cacheOrder.count > maximumEntries {
            let old = cacheOrder.removeFirst()
            cache[old] = nil
        }
        lock.unlock()
        return fetched
    }

    private func cacheKey(for item: MediaItem) -> String {
        let type = item.type.lowercased()
        if let tmdb = item.tmdbId?.trimmingCharacters(in: .whitespacesAndNewlines), !tmdb.isEmpty {
            return "tmdb|\(type)|\(tmdb)"
        }
        if let imdb = item.imdbId?.trimmingCharacters(in: .whitespacesAndNewlines), !imdb.isEmpty {
            return "imdb|\(type)|\(imdb.lowercased())"
        }
        if let tvdb = item.tvdbId?.trimmingCharacters(in: .whitespacesAndNewlines), !tvdb.isEmpty {
            return "tvdb|\(type)|\(tvdb)"
        }
        let rawID = item.id.lowercased()
        if let match = rawID.range(of: #"tmdb[:_/|-]?(?:movie|tv|show|series)?[:_/|-]?(\d+)"#, options: .regularExpression) {
            let fragment = String(rawID[match])
            if let digits = fragment.range(of: #"\d+"#, options: .regularExpression) {
                return "tmdb|\(type)|\(fragment[digits])"
            }
        }
        if let imdb = rawID.range(of: #"tt\d{6,}"#, options: .regularExpression) {
            return "imdb|\(type)|\(String(rawID[imdb]))"
        }
        return "raw|\(type)|\(rawID)|\(item.year)|\(item.title.lowercased())"
    }

    private func fetch(item: MediaItem, apiKey key: String) async -> PopupHeaderDetails? {
        struct FoundItem: Decodable { let id: Int? }
        struct FindResponse: Decodable { let movie_results: [FoundItem]?; let tv_results: [FoundItem]? }
        struct SearchItem: Decodable { let id: Int? }
        struct SearchResponse: Decodable { let results: [SearchItem]? }
        struct Company: Decodable { let name: String? }
        struct Network: Decodable { let name: String? }
        struct MovieReleaseDate: Decodable { let certification: String? }
        struct MovieReleaseRegion: Decodable { let iso_3166_1: String?; let release_dates: [MovieReleaseDate]? }
        struct MovieReleaseDates: Decodable { let results: [MovieReleaseRegion]? }
        struct TVContentRating: Decodable { let iso_3166_1: String?; let rating: String? }
        struct TVContentRatings: Decodable { let results: [TVContentRating]? }
        struct MovieDetail: Decodable { let budget: Int?; let revenue: Int?; let runtime: Int?; let production_companies: [Company]?; let release_dates: MovieReleaseDates? }
        struct TVDetail: Decodable { let episode_run_time: [Int]?; let number_of_seasons: Int?; let number_of_episodes: Int?; let status: String?; let networks: [Network]?; let content_ratings: TVContentRatings? }

        func request<T: Decodable>(_ type: T.Type, from url: URL) async -> T? {
            do {
                let (data, response) = try await URLSession.shared.data(from: url)
                guard !Task.isCancelled else { return nil }
                if let http = response as? HTTPURLResponse, !(200..<300).contains(http.statusCode) { return nil }
                return try JSONDecoder().decode(T.self, from: data)
            } catch { return nil }
        }

        let normalizedType = item.type.lowercased()
        let isTV = normalizedType.contains("series") || normalizedType.contains("show") || normalizedType.contains("tv")
        let parts = item.id.split(separator: ":").map(String.init)
        var detailKind: String? = nil
        var detailID: String? = nil

        if let tmdbValue = item.tmdbId,
           let tmdbRange = tmdbValue.range(of: #"\d+"#, options: .regularExpression) {
            detailKind = isTV ? "tv" : "movie"
            detailID = String(tmdbValue[tmdbRange])
        } else if parts.count >= 3, parts[0].lowercased() == "tmdb" {
            detailKind = (parts[1].lowercased() == "tv" || isTV) ? "tv" : "movie"
            detailID = parts[2]
        } else {
            let imdbID: String? = {
                if let imdbValue = item.imdbId,
                   let explicit = imdbValue.range(of: #"tt\d{6,}"#, options: [.regularExpression, .caseInsensitive]) {
                    return String(imdbValue[explicit]).lowercased()
                }
                if item.id.lowercased().hasPrefix("tt") { return item.id.lowercased() }
                if let match = item.id.range(of: #"tt\d{6,}"#, options: [.regularExpression, .caseInsensitive]) { return String(item.id[match]).lowercased() }
                return nil
            }()
            if let imdbID,
               let encoded = imdbID.addingPercentEncoding(withAllowedCharacters: .urlPathAllowed),
               let findURL = URL(string: "https://api.themoviedb.org/3/find/\(encoded)?api_key=\(key)&external_source=imdb_id&language=en-US"),
               let found = await request(FindResponse.self, from: findURL) {
                if let movieID = found.movie_results?.compactMap({ $0.id }).first { detailKind = "movie"; detailID = String(movieID) }
                else if let tvID = found.tv_results?.compactMap({ $0.id }).first { detailKind = "tv"; detailID = String(tvID) }
            }
        }

        if detailKind == nil {
            let query = item.title.trimmingCharacters(in: .whitespacesAndNewlines)
            if !query.isEmpty, let encodedQuery = query.addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed) {
                let searchKind = isTV ? "tv" : "movie"
                let cleanYear = item.year.trimmingCharacters(in: .whitespacesAndNewlines)
                let yearParam = isTV ? "first_air_date_year" : "year"
                let yearSuffix = cleanYear.isEmpty ? "" : "&\(yearParam)=\(cleanYear)"
                if let searchURL = URL(string: "https://api.themoviedb.org/3/search/\(searchKind)?api_key=\(key)&query=\(encodedQuery)\(yearSuffix)"),
                   let search = await request(SearchResponse.self, from: searchURL),
                   let foundID = search.results?.compactMap({ $0.id }).first {
                    detailKind = searchKind
                    detailID = String(foundID)
                }
            }
        }

        guard !Task.isCancelled,
              let detailKind, let detailID,
              let url = URL(string: "https://api.themoviedb.org/3/\(detailKind)/\(detailID)?api_key=\(key)&append_to_response=release_dates,content_ratings") else { return nil }

        if detailKind == "movie", let detail = await request(MovieDetail.self, from: url) {
            let regions = detail.release_dates?.results ?? []
            let preferredRegion = regions.first(where: { $0.iso_3166_1?.uppercased() == "US" }) ?? regions.first
            let certification = preferredRegion?.release_dates?.compactMap { $0.certification?.trimmingCharacters(in: .whitespacesAndNewlines) }.first(where: { !$0.isEmpty })
            return PopupHeaderDetails(
                budget: detail.budget,
                revenue: detail.revenue,
                runtimeMinutes: detail.runtime,
                studio: detail.production_companies?.compactMap { $0.name?.trimmingCharacters(in: .whitespacesAndNewlines) }.first(where: { !$0.isEmpty }),
                certification: certification
            )
        }

        if detailKind == "tv", let detail = await request(TVDetail.self, from: url) {
            let ratings = detail.content_ratings?.results ?? []
            let preferred = ratings.first(where: { $0.iso_3166_1?.uppercased() == "US" }) ?? ratings.first
            return PopupHeaderDetails(
                runtimeMinutes: detail.episode_run_time?.first(where: { $0 > 0 }),
                seasons: detail.number_of_seasons,
                episodes: detail.number_of_episodes,
                status: detail.status,
                network: detail.networks?.compactMap { $0.name?.trimmingCharacters(in: .whitespacesAndNewlines) }.first(where: { !$0.isEmpty }),
                certification: preferred?.rating?.trimmingCharacters(in: .whitespacesAndNewlines)
            )
        }
        return nil
    }
}


private enum ConnectedMediaPopupDockGeometry {
    // Fixed 1920×1080 connected-stage geometry. The catalog connector docks into the
    // bottom of the popup's illuminated left spine; Search docks into the same spine top.
    static let panelLeft: CGFloat = 1012
    static let accentX: CGFloat = 1013
    static let accentTopY: CGFloat = 168
    static let accentBottomY: CGFloat = 515
    static let accentLocalTop: CGFloat = 42
    static let accentHeight: CGFloat = accentBottomY - accentTopY
}

private struct ConnectedMediaPopupCurve: Shape {
    let start: CGPoint
    let end: CGPoint

    func path(in rect: CGRect) -> Path {
        var path = Path()
        let horizontal = max(180, end.x - start.x)
        // v1060: restore the original connected-popup cubic proportions from v1053.
        // The only geometry correction is the elevated poster anchor/end corridor, which
        // preserves the classic sweep without crossing the next card or hero information.
        let firstControl = CGPoint(x: start.x + horizontal * 0.34, y: start.y - 28)
        let secondControl = CGPoint(x: end.x - horizontal * 0.22, y: end.y + 26)
        path.move(to: start)
        path.addCurve(to: end, control1: firstControl, control2: secondControl)
        return path
    }
}

private struct SearchIconToMediaPopupCurve: Shape {
    let start: CGPoint
    let end: CGPoint

    func path(in rect: CGRect) -> Path {
        var path = Path()
        path.move(to: start)
        // Leave the top-menu Search icon downward first, then sweep left into the
        // popup's illuminated top edge. This keeps the curve below the menu labels
        // and makes Search—not a stale home-row card—the unmistakable origin.
        let firstControl = CGPoint(x: start.x - 18, y: start.y + 112)
        let secondControl = CGPoint(x: end.x + 205, y: end.y - 26)
        path.addCurve(to: end, control1: firstControl, control2: secondControl)
        return path
    }
}

private struct SearchIconToMediaPopupConnector: View {
    let sourceFrame: CGRect
    let visible: Bool
    let animationDuration: Double
    @State private var drawProgress: CGFloat = 0

    private var startPoint: CGPoint {
        guard sourceFrame.width > 20, sourceFrame.height > 20 else {
            return CGPoint(x: 1770, y: 82)
        }
        return CGPoint(
            x: min(max(sourceFrame.midX, 1240), 1840),
            y: min(max(sourceFrame.maxY - 2, 54), 132)
        )
    }

    private var endPoint: CGPoint {
        CGPoint(x: ConnectedMediaPopupDockGeometry.accentX, y: ConnectedMediaPopupDockGeometry.accentTopY)
    }

    var body: some View {
        let curve = SearchIconToMediaPopupCurve(start: startPoint, end: endPoint)

        ZStack {
            // Match the accepted original connected-popup illumination exactly; only
            // the route/origin changes for Search-owned details.
            curve
                .trim(from: 0, to: drawProgress)
                .stroke(
                    LinearGradient(
                        colors: [
                            Color(red: 0.32, green: 0.82, blue: 1.0).opacity(0.95),
                            Color.white.opacity(0.72),
                            Color.orange.opacity(0.22)
                        ],
                        startPoint: .leading,
                        endPoint: .trailing
                    ),
                    style: StrokeStyle(lineWidth: 4.5, lineCap: .round, lineJoin: .round)
                )
                .shadow(color: Color(red: 0.28, green: 0.76, blue: 1.0).opacity(0.70), radius: 12)

            curve
                .trim(from: 0, to: drawProgress)
                .stroke(Color.white.opacity(0.22), style: StrokeStyle(lineWidth: 10, lineCap: .round))
                .blur(radius: 8)

            Circle()
                .fill(Color.white.opacity(drawProgress > 0.01 ? 0.94 : 0))
                .frame(width: 12, height: 12)
                .shadow(color: Color.cyan.opacity(0.95), radius: 12)
                .scaleEffect(drawProgress > 0.01 ? 1 : 0.2)
                .position(startPoint)

            Circle()
                .fill(Color.orange.opacity(drawProgress > 0.985 ? 0.58 : 0))
                .frame(width: 9, height: 9)
                .shadow(color: Color.orange.opacity(0.72), radius: 10)
                .scaleEffect(drawProgress > 0.985 ? 1 : 0.2)
                .position(endPoint)
        }
        .frame(width: 1920, height: 1080)
        .onAppear { setConnectorVisibility(visible, resetOpening: visible) }
        .onChange(of: visible) { isVisible in
            setConnectorVisibility(isVisible, resetOpening: isVisible)
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
        .accessibilityIdentifier("V1062SearchIconToMediaPopupConnector")
    }

    private func setConnectorVisibility(_ isVisible: Bool, resetOpening: Bool) {
        if isVisible {
            if resetOpening {
                var transaction = Transaction()
                transaction.disablesAnimations = true
                withTransaction(transaction) { drawProgress = 0 }
            }
            DispatchQueue.main.async {
                withAnimation(.timingCurve(0.20, 0.86, 0.28, 1.0, duration: animationDuration)) { drawProgress = 1 }
            }
        } else {
            // Search details retract back into the Search icon along the identical curve,
            // matching the accepted poster-origin connector behavior.
            withAnimation(.timingCurve(0.20, 0.86, 0.28, 1.0, duration: animationDuration)) { drawProgress = 0 }
        }
    }
}

private struct FocusedCardToMediaPopupConnector: View {
    let sourceFrame: CGRect
    let visible: Bool
    let animationDuration: Double
    let retractionDuration: Double
    @State private var drawProgress: CGFloat = 0

    private var startPoint: CGPoint {
        guard sourceFrame.width > 40, sourceFrame.height > 40 else {
            return CGPoint(x: 340, y: 720)
        }
        return CGPoint(
            x: min(max(sourceFrame.maxX - 6, 180), 880),
            // Originate from the focused poster itself, but high enough that the glow
            // clears the next poster before beginning the original upward sweep.
            y: min(max(sourceFrame.minY + 14, 210), 820)
        )
    }

    // v1063: dock exactly into the bottom of the popup's illuminated left spine. The
    // connector and the accent are now one continuous visual path rather than two nearby
    // elements that only appear loosely aligned.
    private var endPoint: CGPoint {
        CGPoint(x: ConnectedMediaPopupDockGeometry.accentX, y: ConnectedMediaPopupDockGeometry.accentBottomY)
    }

    var body: some View {
        let curve = ConnectedMediaPopupCurve(start: startPoint, end: endPoint)

        ZStack {
            // Exact original v1053 illuminated line treatment.
            curve
                .trim(from: 0, to: drawProgress)
                .stroke(
                    LinearGradient(
                        colors: [
                            Color(red: 0.32, green: 0.82, blue: 1.0).opacity(0.95),
                            Color.white.opacity(0.72),
                            Color.orange.opacity(0.22)
                        ],
                        startPoint: .leading,
                        endPoint: .trailing
                    ),
                    style: StrokeStyle(lineWidth: 4.5, lineCap: .round, lineJoin: .round)
                )
                .shadow(color: Color(red: 0.28, green: 0.76, blue: 1.0).opacity(0.70), radius: 12)

            curve
                .trim(from: 0, to: drawProgress)
                .stroke(Color.white.opacity(0.22), style: StrokeStyle(lineWidth: 10, lineCap: .round))
                .blur(radius: 8)

            Circle()
                .fill(Color.white.opacity(drawProgress > 0.01 ? 0.94 : 0))
                .frame(width: 12, height: 12)
                .shadow(color: Color.cyan.opacity(0.95), radius: 12)
                .scaleEffect(drawProgress > 0.01 ? 1 : 0.2)
                .position(startPoint)

            Circle()
                .fill(Color.orange.opacity(drawProgress > 0.985 ? 0.58 : 0))
                .frame(width: 9, height: 9)
                .shadow(color: Color.orange.opacity(0.72), radius: 10)
                .scaleEffect(drawProgress > 0.985 ? 1 : 0.2)
                .position(endPoint)
        }
        .frame(width: 1920, height: 1080)
        .onAppear { setConnectorVisibility(visible, resetOpening: visible) }
        .onChange(of: visible) { isVisible in
            setConnectorVisibility(isVisible, resetOpening: isVisible)
        }
        .onChange(of: retractionDuration) { _ in
            // If Back is pressed while the decorative seven-second auto-retraction is
            // already in flight, immediately converge to the close-duration contract.
            // This prevents the parent from ever removing a connector mid-animation.
            if !visible { setConnectorVisibility(false, resetOpening: false) }
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
        .accessibilityIdentifier("V1063FocusedPreviewConnectorDockedToPopupSpine")
    }

    private func setConnectorVisibility(_ isVisible: Bool, resetOpening: Bool) {
        if isVisible {
            if resetOpening {
                var transaction = Transaction()
                transaction.disablesAnimations = true
                withTransaction(transaction) { drawProgress = 0 }
            }
            DispatchQueue.main.async {
                withAnimation(.timingCurve(0.20, 0.86, 0.28, 1.0, duration: animationDuration)) { drawProgress = 1 }
            }
        } else {
            // v1073: reverse the identical trim path at a slower, cinematic pace. The
            // line visibly flows back into the originating card instead of snapping away.
            withAnimation(.timingCurve(0.46, 0.02, 0.20, 1.0, duration: retractionDuration)) {
                drawProgress = 0
            }
        }
    }
}

