private struct ConnectedMediaInformationTopBar: View {
    @EnvironmentObject private var store: CatalogStore
    let item: MediaItem
    let details: PopupHeaderDetails?
    var publishDuringPlayback: Bool = false
    @State private var verifiedEpisodeItem: MediaItem? = nil

    private var isSeries: Bool {
        let value = item.type.lowercased()
        return value.contains("series") || value.contains("show") || value.contains("tv") || value.contains("episode") || item.seasonNumber != nil || item.episodeNumber != nil
    }

    private var isEpisode: Bool { item.seasonNumber != nil || item.episodeNumber != nil || item.type.lowercased().contains("episode") }
    private var episodeDate: DCEpisodeDatePresentation? { isEpisode ? verifiedEpisodeItem.flatMap { dcEpisodeDatePresentation($0) } : nil }
    private var episodeHydrationKey: String {
        "\(item.id)|\(item.seasonNumber ?? 0)|\(item.episodeNumber ?? 0)|\(item.airDateString ?? "")"
    }

    private var yearText: String {
        let clean = item.year.trimmingCharacters(in: .whitespacesAndNewlines)
        return clean.isEmpty ? "Unknown" : clean
    }

    private var ratingText: String {
        let clean = item.rating.trimmingCharacters(in: .whitespacesAndNewlines)
        return clean.isEmpty || clean == "0" || clean == "0.0" ? "Not rated" : clean
    }

    private var runtimeText: String {
        guard let minutes = details?.runtimeMinutes, minutes > 0 else { return isSeries ? "Series" : "Pending" }
        return minutes >= 60 ? "\(minutes / 60)h \(minutes % 60)m" : "\(minutes)m"
    }

    private func moneyText(_ amount: Int?) -> String {
        guard let amount, amount > 0 else { return "Not reported" }
        if amount >= 1_000_000_000 { return String(format: "$%.1fB", Double(amount) / 1_000_000_000) }
        if amount >= 1_000_000 { return String(format: "$%.1fM", Double(amount) / 1_000_000) }
        if amount >= 1_000 { return String(format: "$%.0fK", Double(amount) / 1_000) }
        return "$\(amount)"
    }

    private var primaryProductionLabel: String { isEpisode ? "Season" : (isSeries ? "Seasons" : "Budget") }
    private var primaryProductionValue: String {
        if isEpisode, let season = item.seasonNumber { return "\(season)" }
        if isSeries, let seasons = details?.seasons, seasons > 0 { return "\(seasons)" }
        return moneyText(details?.budget)
    }
    private var secondaryProductionLabel: String { isEpisode ? "Episode" : (isSeries ? "Episodes" : "Revenue") }
    private var secondaryProductionValue: String {
        if isEpisode, let episode = item.episodeNumber { return "\(episode)" }
        if isSeries, let episodes = details?.episodes, episodes > 0 { return "\(episodes)" }
        return moneyText(details?.revenue)
    }
    private var companyText: String {
        let candidate = isSeries ? (details?.network ?? details?.studio) : (details?.studio ?? details?.network)
        let clean = candidate?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        return clean.isEmpty ? "Production pending" : clean
    }
    private var directorText: String {
        let clean = item.directors.first?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        return clean.isEmpty ? "Credits loading" : clean
    }
    private var genreText: String {
        let text = item.genres.prefix(3).joined(separator: " • ")
        return text.isEmpty ? (isSeries ? "Series" : "Movie") : text
    }

    var body: some View {
        HStack(alignment: .top, spacing: 20) {
            ZStack(alignment: .bottomLeading) {
                RoundedRectangle(cornerRadius: 19, style: .continuous)
                    .fill(Color.black.opacity(0.48))
                RemoteImageFit(
                    url: item.posterURL,
                    mode: .fill,
                    maxPixelSize: 768,
                    publishDuringPlayback: publishDuringPlayback,
                    forceVisiblePlaybackPublication: publishDuringPlayback
                )
                    .id("connected-popup-poster-v1059-\(item.id)-\(item.posterURL ?? "placeholder")")
                LinearGradient(colors: [Color.clear, Color.black.opacity(0.72)], startPoint: .center, endPoint: .bottom)
                Text(isSeries ? "SERIES" : "FEATURE")
                    .font(.custom("AvenirNext-DemiBold", size: 9))
                    .kerning(1.7)
                    .foregroundStyle(.white.opacity(0.88))
                    .padding(.horizontal, 10)
                    .padding(.vertical, 7)
            }
            .frame(width: 142, height: 210)
            .clipShape(RoundedRectangle(cornerRadius: 19, style: .continuous))
            .overlay(RoundedRectangle(cornerRadius: 19, style: .continuous).stroke(LinearGradient(colors: [Color.white.opacity(0.30), Color.cyan.opacity(0.15), Color.orange.opacity(0.20)], startPoint: .topLeading, endPoint: .bottomTrailing), lineWidth: 1.2))
            .shadow(color: .black.opacity(0.62), radius: 18, y: 11)

            VStack(alignment: .leading, spacing: 9) {
                HStack(alignment: .firstTextBaseline) {
                    VStack(alignment: .leading, spacing: 3) {
                        Text("SIGNAL  /  MEDIA PROFILE")
                            .font(.custom("AvenirNext-DemiBold", size: 9.5))
                            .kerning(1.7)
                            .foregroundStyle(Color.cyan.opacity(0.68))
                        Group {
                            if let logoURL = item.logoURL?.trimmingCharacters(in: .whitespacesAndNewlines), !logoURL.isEmpty {
                                // vBRDC031: Media Information uses the exact same resolved
                                // themed title artwork as the focused card/hero.
                                RemoteImageFit(
                                    url: logoURL,
                                    mode: .fit,
                                    showPlaceholder: false,
                                    maxPixelSize: 1024,
                                    publishDuringPlayback: publishDuringPlayback,
                                    forceVisiblePlaybackPublication: publishDuringPlayback
                                )
                                    .frame(width: 330, height: 48, alignment: .leading)
                                    .shadow(color: .black.opacity(0.50), radius: 5, y: 3)
                            } else {
                                Text(item.title)
                                    .font(.custom("AvenirNext-DemiBold", size: 27))
                                    .tracking(-0.35)
                                    .foregroundStyle(LinearGradient(colors: [.white, .white], startPoint: .leading, endPoint: .trailing))
                                    .lineLimit(1)
                                    .minimumScaleFactor(0.62)
                            }
                        }
                        .frame(height: 48, alignment: .leading)
                    }
                    Spacer(minLength: 10)
                    if let certification = details?.certification, !certification.isEmpty {
                        Text(certification)
                            .font(.custom("AvenirNext-DemiBold", size: 12))
                            .foregroundStyle(.white.opacity(0.94))
                            .padding(.horizontal, 10)
                            .frame(height: 29)
                            .background(Capsule().fill(Color.orange.opacity(0.19)))
                            .overlay(Capsule().stroke(Color.orange.opacity(0.52), lineWidth: 1))
                    }
                }

                HStack(spacing: 8) {
                    ConnectedMediaInformationMetric(
                        icon: isEpisode ? "calendar.badge.clock" : "calendar",
                        label: isEpisode ? (episodeDate?.isUpcoming == true ? "Release Date" : "Air Date") : "Year",
                        value: episodeDate?.combinedText ?? yearText,
                        tint: episodeDate?.isUpcoming == true ? .orange : .cyan
                    )
                    ConnectedMediaInformationMetric(icon: "star.fill", label: "Rating", value: ratingText, tint: .yellow)
                    ConnectedMediaInformationMetric(icon: "clock", label: "Runtime", value: runtimeText, tint: .white)
                }

                HStack(spacing: 8) {
                    ConnectedMediaInformationMetric(icon: isSeries ? "rectangle.stack" : "banknote", label: primaryProductionLabel, value: primaryProductionValue, tint: .orange)
                    ConnectedMediaInformationMetric(icon: isSeries ? "play.square.stack" : "chart.line.uptrend.xyaxis", label: secondaryProductionLabel, value: secondaryProductionValue, tint: .green)
                    ConnectedMediaInformationMetric(icon: "building.2", label: isSeries ? "Network" : "Studio", value: companyText, tint: .purple)
                }

                HStack(spacing: 16) {
                    Label(directorText, systemImage: "person.text.rectangle")
                    Label(genreText, systemImage: "theatermasks")
                }
                .font(.custom("AvenirNext-Medium", size: 12.5))
                .foregroundStyle(.white.opacity(0.65))
                .lineLimit(1)
            }
            .frame(maxWidth: .infinity, alignment: .leading)
        }
        .frame(height: 212, alignment: .topLeading)
        .task(id: episodeHydrationKey) {
            guard isEpisode else {
                verifiedEpisodeItem = nil
                return
            }
            let enriched = await store.exactEpisodeMetadataForPresentation(item)
            guard !Task.isCancelled else { return }
            verifiedEpisodeItem = enriched
        }
    }
}

private struct ConnectedPopupAdvisoryStrip: View {
    let item: MediaItem
    let details: PopupHeaderDetails?

    private var certification: String? {
        let fromDetails = details?.certification?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        if !fromDetails.isEmpty { return fromDetails.uppercased() }
        let clean = item.rating.trimmingCharacters(in: .whitespacesAndNewlines).uppercased()
        let knownRatings = Set(["NC-17", "PG-13", "TV-MA", "TV-14", "TV-PG", "TV-G", "TV-Y7", "TV-Y", "R", "PG", "G"])
        return knownRatings.contains(clean) ? clean : nil
    }

    private var guidance: String {
        switch certification {
        case "G", "TV-G", "TV-Y": return "General audiences"
        case "PG", "TV-PG", "TV-Y7": return "Parental guidance suggested"
        case "PG-13", "TV-14": return "Parents strongly cautioned"
        case "R", "TV-MA": return "Mature audiences"
        case "NC-17": return "Adults only"
        case .some: return "Official viewer certification"
        case .none: return "Advisory unavailable from the current metadata provider"
        }
    }

    var body: some View {
        HStack(spacing: 12) {
            ZStack {
                RoundedRectangle(cornerRadius: 11, style: .continuous)
                    .fill(Color.orange.opacity(0.14))
                Image(systemName: "exclamationmark.shield.fill")
                    .font(.system(size: 16, weight: .bold))
                    .foregroundStyle(Color.orange.opacity(0.96))
            }
            .frame(width: 36, height: 36)

            VStack(alignment: .leading, spacing: 2) {
                Text("CONTENT ADVISORY")
                    .font(.custom("AvenirNext-DemiBold", size: 9))
                    .kerning(1.35)
                    .foregroundStyle(.white.opacity(0.48))
                Text(guidance)
                    .font(.custom("AvenirNext-Medium", size: 13))
                    .foregroundStyle(.white.opacity(0.86))
                    .lineLimit(1)
            }

            Spacer(minLength: 8)

            Text(certification ?? "NOT RATED")
                .font(.custom("AvenirNext-DemiBold", size: 11.5))
                .kerning(0.35)
                .foregroundStyle(.white.opacity(certification == nil ? 0.58 : 0.96))
                .padding(.horizontal, 12)
                .frame(height: 29)
                .background(Capsule().fill(certification == nil ? Color.white.opacity(0.055) : Color.orange.opacity(0.15)))
                .overlay(Capsule().stroke(certification == nil ? Color.white.opacity(0.10) : Color.orange.opacity(0.38), lineWidth: 1))
        }
        .padding(.horizontal, 12)
        .frame(width: 790, height: 48, alignment: .leading)
        .background(
            RoundedRectangle(cornerRadius: 15, style: .continuous)
                .fill(Color.white.opacity(0.045))
        )
        .overlay(
            RoundedRectangle(cornerRadius: 15, style: .continuous)
                .stroke(
                    LinearGradient(
                        colors: [Color.orange.opacity(0.24), Color.white.opacity(0.07), Color.clear],
                        startPoint: .leading,
                        endPoint: .trailing
                    ),
                    lineWidth: 0.9
                )
        )
        .accessibilityIdentifier("V1059ConnectedPopupAdvisory")
    }
}

private struct ConnectedPopupCastRow: View {
    let item: MediaItem
    var publishDuringPlayback: Bool = false

    private var isSeries: Bool {
        let value = item.type.lowercased()
        return value.contains("series") || value.contains("show") || value.contains("tv") || item.seasonNumber != nil
    }

    private func normalizedMember(_ source: CastMember) -> CastMember? {
        let name = source.name.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !name.isEmpty else { return nil }
        var member = source
        member.name = name
        if let rawValue = member.imageURL?.trimmingCharacters(in: .whitespacesAndNewlines), !rawValue.isEmpty,
           let url = URL(string: rawValue),
           let scheme = url.scheme?.lowercased(),
           scheme == "http" || scheme == "https" {
            let lower = rawValue.lowercased()
            if ["placeholder", "silhouette", "no-image", "no_image", "noimage", "default-avatar", "default_profile"].contains(where: lower.contains) {
                member.imageURL = nil
            } else {
                member.imageURL = rawValue
            }
        } else {
            member.imageURL = nil
        }
        return member
    }

    private var members: [CastMember] {
        let limit = isSeries ? 4 : 6
        let sourceMembers: [CastMember] = item.castMembers.isEmpty
            ? item.cast.map { CastMember(name: $0, role: nil, imageURL: nil) }
            : item.castMembers
        return Array(sourceMembers.compactMap(normalizedMember).prefix(limit))
    }

    var body: some View {
        VStack(alignment: .leading, spacing: isSeries ? 9 : 10) {
            Label(isSeries ? "CAST" : "CREDITS", systemImage: isSeries ? "person.3.fill" : "person.3.sequence.fill")
                .font(.system(size: 13, weight: .bold, design: .default))
                .kerning(1.1)
                .foregroundStyle(.white.opacity(0.70))

            if members.isEmpty {
                CastCreditsSummary(item: item)
            } else if isSeries {
                HStack(spacing: 10) {
                    ForEach(members) { member in
                        CompactHeroCastCard(member: member, compact: true, publishDuringPlayback: publishDuringPlayback)
                    }
                }
                .accessibilityIdentifier("V1052SeriesCompactCastRow")
            } else {
                HStack(alignment: .top, spacing: 10) {
                    ForEach(members) { member in
                        CastFaceCard(member: member, premium: true, publishDuringPlayback: publishDuringPlayback)
                    }
                }
                .frame(maxWidth: .infinity, alignment: .leading)
                .accessibilityIdentifier("V1052MovieCircularCreditsRow")
            }
        }
    }
}

struct PopupFontPreset: Identifiable, Hashable {
    let id: String
    let title: String
    let category: String
}

struct PopupTypography {
    static let presets: [PopupFontPreset] = [
