    static func font(_ preset: String, size: CGFloat, weight: Font.Weight) -> Font {
        switch preset {
        case "SF Rounded", "Soft Rounded", "Classic TV", "Glass UI", "Comfort Rounded", "Arcade": return .system(size: size, weight: weight, design: .rounded)
        case "SF Serif", "Editorial", "Magazine", "Luxury Serif": return .system(size: size, weight: weight, design: .serif)
        case "SF Mono", "Digital HUD", "Courier", "Terminal": return .system(size: size, weight: weight, design: .monospaced)
        case "Avenir Next": return .custom("Avenir Next", size: size).weight(weight)
        case "Avenir": return .custom("Avenir", size: size).weight(weight)
        case "Helvetica Neue", "Minimal Sans", "Studio": return .custom("Helvetica Neue", size: size).weight(weight)
        case "Futura", "Blockbuster", "Trailer Title": return .custom("Futura", size: size).weight(weight)
        case "Gill Sans", "Broadcast": return .custom("Gill Sans", size: size).weight(weight)
        case "Optima", "Prestige": return .custom("Optima", size: size).weight(weight)
        case "Palatino", "Film Archive": return .custom("Palatino", size: size).weight(weight)
        case "Georgia": return .custom("Georgia", size: size).weight(weight)
        case "Baskerville", "Noir": return .custom("Baskerville", size: size).weight(weight)
        case "Didot", "Cinematic": return .custom("Didot", size: size).weight(weight)
        case "American Typewriter", "Broadcast Typewriter": return .custom("American Typewriter", size: size).weight(weight)
        case "Avenir Condensed", "Headline Condensed": return .custom("Avenir Next Condensed", size: size).weight(weight)
        case "Copperplate", "Cinema Copperplate": return .custom("Copperplate", size: size).weight(weight)
        case "Menlo": return .custom("Menlo", size: size).weight(weight)
        case "Trebuchet": return .custom("Trebuchet MS", size: size).weight(weight)
        case "Hoefler": return .custom("Hoefler Text", size: size).weight(weight)
        case "Marker": return .custom("Marker Felt", size: size).weight(weight)
        case "Chalkboard": return .custom("Chalkboard SE", size: size).weight(weight)
        case "Times Classic": return .custom("Times New Roman", size: size).weight(weight)
        case "Large Readability", "High Contrast": return .system(size: size + 1.5, weight: .bold, design: .rounded)
        case "Compact UI", "Ultra Clean": return .system(size: max(10, size - 1.0), weight: weight, design: .default)
        case "Thin Modern", "Apple TV Clean", "Midnight Sans": return .system(size: size, weight: .medium, design: .default)
        case "Apple TV Bold": return .system(size: size, weight: .bold, design: .rounded)
        case "Sports Network": return .custom("Avenir Next Condensed", size: size).weight(.bold)
        case "Newsroom": return .custom("Helvetica Neue", size: size).weight(.bold)
        case "Cinema Wide": return .custom("Copperplate", size: size).weight(weight)
        case "Future Display": return .system(size: size, weight: .semibold, design: .rounded)
        case "Retro Broadcast": return .custom("American Typewriter", size: size).weight(.semibold)
        case "Cyber", "Neo Tech", "Space Station", "Synthwave": return .custom("Avenir Next Condensed", size: size).weight(weight)
        case "VHS", "Retro Cinema": return .custom("American Typewriter", size: size).weight(weight)
        case "Pro Display", "Glass Display": return .system(size: size, weight: weight, design: .rounded)
        case "Studio Sans", "Executive Sans", "Modern Grotesk": return .custom("Avenir Next", size: size).weight(weight)
        case "Network Condensed": return .custom("Avenir Next Condensed", size: size).weight(.bold)
        case "Cinema Editorial": return .custom("Baskerville", size: size).weight(weight)
        case "Gallery Serif": return .custom("Didot", size: size).weight(weight)
        default: return .system(size: size, weight: weight, design: .default)
        }
    }

    static func kerning(_ preset: String) -> CGFloat {
        switch preset {
        case "Cinematic", "Trailer Title", "Blockbuster", "Noir", "Prestige", "Cinema Wide", "Copperplate", "Cinema Copperplate": return 1.35
        case "Digital HUD", "Cyber", "Neo Tech", "Space Station", "Terminal", "Future Display", "Menlo": return 1.0
        case "Sports Network", "Newsroom", "Apple TV Bold", "Avenir Condensed", "Headline Condensed": return 0.45
        case "Retro Broadcast", "Arcade", "American Typewriter", "Broadcast Typewriter", "Marker", "Chalkboard": return 0.95
        case "Compact UI", "Ultra Clean", "Midnight Sans": return 0.25
        case "Pro Display", "Glass Display", "Studio Sans", "Executive Sans", "Modern Grotesk": return 0.34
        case "Network Condensed": return 0.50
        case "Cinema Editorial", "Gallery Serif": return 0.85
        default: return 0.55
        }
    }

    static func descriptionLineSpacing(_ preset: String) -> CGFloat {
        switch preset {
        case "Large Readability", "High Contrast", "Editorial", "Magazine": return 7
        case "Compact UI": return 4
        default: return 5
        }
    }
}

// v481: Larger second-style cinematic details header. The hidden top menu space becomes
// a true hero banner: clearer backdrop, large artwork logo, and an integrated metadata row.
struct PopupExtendedMetadataHeader: View {
    let item: MediaItem
    let details: PopupHeaderDetails?
    // v1073: portrait, centered layout, and solid readability treatment are now
    // locked presentation decisions rather than user-facing legacy settings.
    private let showMediaInfoPortraitPoster: Bool = true
    private let topBarMediaInfoLayout: String = "Center"
    private let mediaInfoTopBarTransparency: String = "Solid"
    @AppStorage("advisoryDisplayEnabled") private var advisoryDisplayEnabled: Bool = true
    @State private var advisorVisible: Bool = false
    @State private var advisorFactIndex: Int = 0
    @State private var advisorOMDbFacts: [String] = []
    @StateObject private var popupMetadataAsyncRuntime = PopupMetadataAsyncTaskRuntime()
    private var advisorDismissTask: Task<Void, Never>? {
            get { popupMetadataAsyncRuntime.advisorDismissTask }
            nonmutating set { popupMetadataAsyncRuntime.advisorDismissTask = newValue }
        }
    private var advisorOMDbTask: Task<Void, Never>? {
            get { popupMetadataAsyncRuntime.advisorOMDbTask }
            nonmutating set { popupMetadataAsyncRuntime.advisorOMDbTask = newValue }
        }

    private var isShow: Bool {
        let lower = item.type.lowercased()
        return lower.contains("show") || lower.contains("series") || lower.contains("tv")
    }

    private var sourceLabel: String {
        if let value = details?.studio?.trimmingCharacters(in: .whitespacesAndNewlines), !value.isEmpty { return value }
        if let value = details?.network?.trimmingCharacters(in: .whitespacesAndNewlines), !value.isEmpty { return value }
        if let value = item.addonName?.trimmingCharacters(in: .whitespacesAndNewlines), !value.isEmpty { return value }
        return item.catalog.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private var firstGenre: String { item.genres.first?.trimmingCharacters(in: .whitespacesAndNewlines) ?? "" }

    private var ratingValue: String {
        let trimmed = item.rating.trimmingCharacters(in: .whitespacesAndNewlines)
        if trimmed.isEmpty || trimmed == "—" || trimmed == "0" || trimmed == "0.0" { return "" }
        return trimmed
    }

    private func moneyLabel(_ value: Int?) -> String {
        guard let value, value > 0 else { return "" }
        let amount = Double(value)
        if amount >= 1_000_000_000 { return String(format: "$%.1fB", amount / 1_000_000_000) }
        if amount >= 1_000_000 { return String(format: "$%.0fM", amount / 1_000_000) }
        return "$\(value)"
    }

    private func runtimeLabel(_ minutes: Int?) -> String {
        guard let minutes, minutes > 0 else { return "" }
        if minutes >= 60 { return "\(minutes / 60)h \(minutes % 60)m" }
        return "\(minutes)m"
    }

    private var metricPairs: [(String, String)] {
        let base: [(String, String)]
        if isShow {
            base = [
                ("SEASONS", details?.seasons.map(String.init) ?? ""),
                ("EPISODES", details?.episodes.map(String.init) ?? ""),
                ("STATUS", details?.status ?? ""),
                ("NETWORK", sourceLabel),
                ("RATING", ratingValue),
                ("GENRE", firstGenre)
            ]
        } else {
            base = [
                ("BUDGET", moneyLabel(details?.budget)),
                ("REVENUE", moneyLabel(details?.revenue)),
                ("RUNTIME", runtimeLabel(details?.runtimeMinutes)),
                ("RELEASE", item.year),
                ("STUDIO", sourceLabel),
                ("RATING", ratingValue),
                ("GENRE", firstGenre)
            ]
        }
        return base.filter { !$0.1.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
    }

    private var advisorFacts: [String] {
        // v814 correction: the top-right advisory pill is intentionally basic.
        // Show only the user-facing warning facts: Rated R/TV-MA/etc and content
        // descriptors such as Nudity, Sexual content, Adult scenes, Gore, or Scary scenes.
        // Do not rotate through Certification/MPAA/Region duplicates.
        var facts: [String] = []
        let dynamicAdvisory = dynamicCertificationAndDescriptors()
        let certification = !dynamicAdvisory.certification.isEmpty ? dynamicAdvisory.certification : (isCertificationRating(ratingValue) ? ratingValue : "")
        if !certification.isEmpty {
            facts.append("Rated \(certification)")
        }

        let advisoryTags = item.genres
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { isAdvisoryTag($0) }
            .map { normalizedAdvisoryLabel($0) }
            .filter { !$0.isEmpty }
            .uniquedPreservingOrder()

        let descriptorLabels = (advisoryTags + dynamicAdvisory.descriptors)
            .uniquedPreservingOrder()
            .filter { !$0.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }

        facts.append(contentsOf: descriptorLabels.prefix(5).map { "Content Descriptor: \($0)" })
        return facts.uniquedPreservingOrder().prefix(6).map { $0 }
    }

    private var advisorySelectionToken: String {
        // v808 compile-safe advisory token: keep the same dynamic inputs, but avoid
        // one large optional-heavy array expression that can overwhelm Swift type checking.
        var parts: [String] = []
        parts.append(item.id)
        parts.append(item.title)
        parts.append(item.year)
        parts.append(item.type)
        parts.append(item.rating)
        parts.append(item.description)
        parts.append(item.catalog)
        parts.append(item.addonName ?? "")
        parts.append(item.genres.joined(separator: "|"))
        parts.append(details?.studio ?? "")
        parts.append(details?.network ?? "")
        parts.append(details?.status ?? "")
        if let runtime = details?.runtimeMinutes {
            parts.append(String(runtime))
        } else {
            parts.append("")
        }
        return parts.joined(separator: "::")
    }

    private var visibleAdvisorFacts: [String] {
        let currentFacts = advisorFacts
        guard !currentFacts.isEmpty else { return [] }
        let index = advisorFactIndex % currentFacts.count
        let next = currentFacts[(index + 1) % currentFacts.count]
        return currentFacts.count > 1 ? [currentFacts[index], next] : [currentFacts[index]]
    }

    private var advisorIsWarning: Bool {
        let upperRating = ratingValue.uppercased()
        return upperRating.contains("R") || upperRating.contains("TV-MA") || upperRating.contains("NC-17")
    }

    private var topBarAlignment: Alignment {
        switch topBarMediaInfoLayout {
        case "Left": return .leading
        default: return .center
        }
    }

    private var topBarHorizontalPadding: CGFloat {
        topBarMediaInfoLayout == "Left" ? 104 : 0
    }

    // v799: controls only the black/glass background layer of the top media information bar.
    // It intentionally does not move or restyle poster, chips, advisory, hero artwork, details, buttons, or credits.
    private var topBarBackgroundOpacityScale: Double {
        switch mediaInfoTopBarTransparency {
        case "Medium": return 0.5
        case "Clear": return 0.0
        default: return 1.0
        }
    }

    @ViewBuilder
    private var mediaInfoContent: some View {
        HStack(alignment: .center, spacing: 22) {
            if showMediaInfoPortraitPoster {
                HeaderPosterArtwork(item: item)
                    .frame(width: 90, height: 120, alignment: .center)
                    .padding(.top, 24)
            }

            HStack(spacing: 10) {
                ForEach(Array(metricPairs.prefix(isShow ? 5 : 6).enumerated()), id: \.offset) { _, pair in
                    HeaderMetricChip(title: pair.0, value: pair.1)
                }
            }
        }
        .padding(.leading, topBarHorizontalPadding)
    }

    var body: some View {
        ZStack(alignment: .bottomLeading) {
            ZStack {
                Rectangle()
                    .fill(Color.black.opacity(0.72 * topBarBackgroundOpacityScale))
                LinearGradient(
                    colors: [Color.black.opacity(0.94 * topBarBackgroundOpacityScale), Color.black.opacity(0.72 * topBarBackgroundOpacityScale), Color.black.opacity(0.50 * topBarBackgroundOpacityScale), Color.black.opacity(0.36 * topBarBackgroundOpacityScale)],
                    startPoint: .leading,
                    endPoint: .trailing
                )
                LinearGradient(
                    colors: [Color.white.opacity(0.045 * topBarBackgroundOpacityScale), Color.clear, Color.black.opacity(0.38 * topBarBackgroundOpacityScale)],
                    startPoint: .top,
                    endPoint: .bottom
                )
            }
            .frame(width: 1920, height: 158)

            mediaInfoContent
            .padding(.bottom, 18)
            .frame(width: 1920, alignment: topBarAlignment)

            if advisoryDisplayEnabled && !advisorFacts.isEmpty {
                AdvisorAlertBanner(facts: visibleAdvisorFacts, isWarning: advisorIsWarning)
                    .id("advisor-banner-\(advisorySelectionToken)")
                    .padding(.trailing, 72)
                    .padding(.bottom, 64)
                    .frame(width: 1920, alignment: .trailing)
                    .transition(.asymmetric(insertion: .move(edge: .trailing).combined(with: .opacity), removal: .opacity))
                    .zIndex(4)
            }

            Rectangle()
                .fill(LinearGradient(colors: [Color.clear, Color.white.opacity(0.08 * topBarBackgroundOpacityScale), Color.clear], startPoint: .leading, endPoint: .trailing))
                .frame(height: 1)
        }
        // v801: no second independent black layer; this background follows the same top-bar transparency setting.
        .background(Color.black.opacity(0.56 * topBarBackgroundOpacityScale))
        .id("media-info-top-bar-\(advisorySelectionToken)-\(mediaInfoTopBarTransparency)")
        .accessibilityHidden(true)
        .onAppear {
            resetAdvisorForCurrentSelection(clearOMDb: true)
        }
        .task(id: advisorySelectionToken) {
            await MainActor.run { resetAdvisorForCurrentSelection(clearOMDb: true) }
        }
        .onChange(of: advisorySelectionToken) { _, _ in
            resetAdvisorForCurrentSelection(clearOMDb: true)
        }
        .onChange(of: advisoryDisplayEnabled) { enabled in
            if enabled {
                loadOptionalOMDbFactsIfNeeded()
                showAdvisorBannerIfNeeded()
            } else {
                advisorDismissTask?.cancel()
                withAnimation(.easeOut(duration: 0.22)) { advisorVisible = false }
            }
        }
        .onDisappear {
            advisorDismissTask?.cancel()
            advisorOMDbTask?.cancel()
        }
        .onReceive(Timer.publish(every: 5.0, on: .main, in: .common).autoconnect()) { _ in
            guard advisorVisible, advisorFacts.count > 1 else { return }
            withAnimation(.easeInOut(duration: 0.22)) {
                advisorFactIndex = (advisorFactIndex + 1) % advisorFacts.count
            }
        }
    }

    private func resetAdvisorForCurrentSelection(clearOMDb: Bool) {
        advisorFactIndex = 0
        if clearOMDb { advisorOMDbFacts = [] }
        advisorOMDbTask?.cancel()
        loadOptionalOMDbFactsIfNeeded()
        showAdvisorBannerIfNeeded()
    }

    private func dynamicCertificationAndDescriptors() -> (certification: String, descriptors: [String], regionRating: String?) {
        // v813: rebuild from the current item identity every focus change.
        let rawValues = ([item.rating, item.description, item.catalog, item.addonName ?? ""] + item.genres + advisorOMDbFacts)
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
        let joined = rawValues.joined(separator: " • ")
        let upper = joined.uppercased()
        let certifications = ["NC-17", "PG-13", "TV-MA", "TV-14", "TV-PG", "TV-G", "TV-Y7", "TV-Y", "R", "PG", "G"]
        let certification = certifications.first { cert in
            upper.range(of: "(^|[^A-Z0-9])" + NSRegularExpression.escapedPattern(for: cert) + "([^A-Z0-9]|$)", options: .regularExpression) != nil
        } ?? ""

        var descriptors: [String] = []
        let descriptorMap: [(String, String)] = [
            ("strong violence", "Strong violence"), ("violence", "Violence"), ("violent", "Violence"), ("gore", "Gore"), ("bloody", "Bloody violence"),
            ("strong language", "Strong language"), ("language", "Language"), ("profanity", "Language"), ("crude", "Crude language"),
            ("graphic nudity", "Graphic nudity"), ("brief nudity", "Brief nudity"), ("nudity", "Nudity"), ("nude", "Nudity"),
            ("adult scenes", "Adult scenes"), ("sex scenes", "Sexual scenes"), ("sexual content", "Sexual content"), ("sexuality", "Sexual content"), ("sexual", "Sexual content"), ("erotic", "Sexual content"), ("explicit", "Explicit content"),
            ("drug use", "Drug use"), ("drug", "Drug use"), ("smoking", "Smoking"), ("alcohol", "Alcohol"),
            ("mature", "Mature themes"), ("adult", "Adult themes"),
            ("frightening", "Frightening scenes"), ("scary", "Scary scenes"), ("horror", "Scary scenes"), ("intense", "Intense scenes")
        ]
        let lower = joined.lowercased()
        for (needle, label) in descriptorMap where lower.contains(needle) { descriptors.append(label) }
        if ["R", "NC-17", "TV-MA"].contains(certification) {
            descriptors.append(certification == "R" ? "Mature/adult content" : "Adult content")
        } else if certification == "TV-14" {
            descriptors.append("Parental guidance suggested")
        }
        let regionPatterns = [
            "US: \(certification)", "USA: \(certification)", "United States: \(certification)",
            "UK: \(certification)", "GB: \(certification)", "CA: \(certification)", "AU: \(certification)"
        ]
        let regionRating = certification.isEmpty ? nil : regionPatterns.first { joined.localizedCaseInsensitiveContains($0) }
        return (certification, descriptors.uniquedPreservingOrder().prefix(4).map { $0 }, regionRating)
    }

    private func showAdvisorBannerIfNeeded() {
        advisorDismissTask?.cancel()
        guard advisoryDisplayEnabled, !advisorFacts.isEmpty else {
            advisorVisible = false
            return
        }
        advisorFactIndex = 0
        withAnimation(.spring(response: 0.42, dampingFraction: 0.86)) { advisorVisible = true }
        // v688: advisory remains visible while the top media info bar is visible.
    }

    private func isCertificationRating(_ value: String) -> Bool {
        let upper = value.trimmingCharacters(in: .whitespacesAndNewlines).uppercased()
        return ["G", "PG", "PG-13", "R", "NC-17", "TV-Y", "TV-Y7", "TV-G", "TV-PG", "TV-14", "TV-MA"].contains(upper)
    }

    private func normalizedAdvisoryLabel(_ tag: String) -> String {
        let lower = tag.lowercased()
        if lower.contains("graphic nudity") { return "Graphic nudity" }
        if lower.contains("brief nudity") { return "Brief nudity" }
        if lower.contains("nudity") || lower.contains("nude") { return "Nudity" }
        if lower.contains("adult scenes") { return "Adult scenes" }
        if lower.contains("sex scenes") { return "Sexual scenes" }
        if lower.contains("sexual") || lower.contains("sex") || lower.contains("erotic") { return "Sexual content" }
        if lower.contains("explicit") { return "Explicit content" }
        if lower.contains("strong violence") { return "Strong violence" }
        if lower.contains("violence") || lower.contains("violent") { return "Violence" }
        if lower.contains("gore") || lower.contains("bloody") { return "Gore" }
        if lower.contains("strong language") { return "Strong language" }
        if lower.contains("language") || lower.contains("profanity") { return "Language" }
        if lower.contains("drug") { return "Drug use" }
        if lower.contains("scary") || lower.contains("frightening") || lower.contains("horror") { return "Scary scenes" }
        if lower.contains("adult") || lower.contains("mature") { return "Adult content" }
        return tag.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private func isAdvisoryTag(_ tag: String) -> Bool {
        let lower = tag.lowercased()
        return lower.contains("violence") || lower.contains("language") || lower.contains("adult") || lower.contains("nudity") || lower.contains("nude") || lower.contains("sex") || lower.contains("sexual") || lower.contains("erotic") || lower.contains("explicit") || lower.contains("mature") || lower.contains("advisory") || lower.contains("drug") || lower.contains("gore")
    }

    private func isSourceOrQualityTag(_ tag: String) -> Bool {
        let lower = tag.lowercased()
        return lower.contains("1080") || lower.contains("2160") || lower.contains("720") || lower.contains("4k") || lower.contains("hdr") || lower.contains("web-dl") || lower.contains("bluray") || lower.contains("remux") || lower.contains("cache")
    }

    private func qualityFacts() -> [String] {
        let rawText = ([item.title, item.description, item.catalog, item.addonName ?? ""] + item.genres).joined(separator: " ")
        let lower = rawText.lowercased()
        var facts: [String] = []
        if lower.contains("2160p") || lower.contains("4k") { facts.append("4K source note") }
        else if lower.contains("1080p") { facts.append("1080p source note") }
        else if lower.contains("720p") { facts.append("720p source note") }
        if lower.contains("hdr") { facts.append("HDR source note") }
        if lower.contains("dolby vision") || lower.contains(" dv ") { facts.append("Dolby Vision source note") }
        if lower.contains("atmos") { facts.append("Atmos source note") }
        if lower.contains("cached") || lower.contains("cache") { facts.append("Cached source note") }
        return facts
    }

    private func resumeFact() -> String? {
        guard let resume = PlaybackResumeCacheManager.shared.resumeEntry(for: item) else { return nil }
        guard resume.duration > resume.seconds else { return "Resume available" }
        let remaining = max(0, resume.duration - resume.seconds)
        if remaining >= 3600 {
            return "Resume \(Int(remaining / 3600))h \(Int((remaining.truncatingRemainder(dividingBy: 3600)) / 60))m left"
        }
        return "Resume \(max(1, Int(remaining / 60)))m left"
    }

    private var advisorIMDbID: String? {
        if let direct = item.imdbId?.trimmingCharacters(in: .whitespacesAndNewlines), !direct.isEmpty {
            return direct.lowercased()
        }
        let rawText = ([item.id, item.previewURL ?? "", item.posterURL ?? "", item.landscapeURL ?? "", item.description] + item.genres).joined(separator: " ")
        guard let range = rawText.range(of: #"tt\d{5,}"#, options: [.regularExpression, .caseInsensitive]) else { return nil }
        return String(rawText[range]).lowercased()
    }

    private var advisorOMDbLookupKey: String {
        if let imdbID = advisorIMDbID { return "i:\(imdbID)" }
        let cleanTitle = item.title.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let cleanYear = item.year.trimmingCharacters(in: .whitespacesAndNewlines)
        return "t:\(cleanTitle)|y:\(cleanYear)|type:\(isShow ? "series" : "movie")"
    }

    private func loadOptionalOMDbFactsIfNeeded() {
        guard advisoryDisplayEnabled else { return }
        guard advisorOMDbFacts.isEmpty else { return }
        let configuredOMDbKey = ["omdbApiKey", "OMDB_API_KEY", "omdb_api_key", "rottenTomatoesOMDbApiKey"]
            .compactMap { UserDefaults.standard.string(forKey: $0)?.trimmingCharacters(in: .whitespacesAndNewlines) }
            .first(where: { !$0.isEmpty }) ?? ""
        let environmentOMDbKey = ProcessInfo.processInfo.environment["OMDB_API_KEY"]?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let omdbKey = configuredOMDbKey.isEmpty ? environmentOMDbKey : configuredOMDbKey
        let configuredTMDBKey = UserDefaults.standard.string(forKey: "tmdbApiKey")?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let environmentTMDBKey = ProcessInfo.processInfo.environment["TMDB_API_KEY"]?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let tmdbKey = configuredTMDBKey.isEmpty ? environmentTMDBKey : configuredTMDBKey
        guard !omdbKey.isEmpty || !tmdbKey.isEmpty else { return }
        let lookupKey = advisorOMDbLookupKey
        let combinedKey = "combined:\(lookupKey)"
        if let cached = AdvisoryOMDbFactCache.facts(for: combinedKey) {
            advisorOMDbFacts = cached
            return
        }
        advisorOMDbTask?.cancel()
        let imdbID = advisorIMDbID
        let tmdbID = item.tmdbId
        let itemID = item.id
        let title = item.title
        let year = item.year
        let type = isShow ? "series" : "movie"
        advisorOMDbTask = VODExclusiveWorkRegistry.start {
            var facts: [String] = []
            if !omdbKey.isEmpty {
                facts.append(contentsOf: await AdvisoryOMDbFactCache.fetchFacts(lookupKey: "omdb:\(lookupKey)", imdbID: imdbID, tmdbID: tmdbID, itemID: itemID, title: title, year: year, type: type, apiKey: omdbKey))
            }
            if !tmdbKey.isEmpty {
                facts.append(contentsOf: await AdvisoryTMDBFactCache.fetchFacts(lookupKey: "tmdb:\(lookupKey)", tmdbID: tmdbID, itemID: itemID, type: type, apiKey: tmdbKey))
            }
            facts = facts.uniquedPreservingOrder()
            AdvisoryOMDbFactCache.storeFacts(facts, for: combinedKey)
            await MainActor.run {
                guard self.advisorOMDbLookupKey == lookupKey else { return }
                self.advisorOMDbFacts = facts
                if self.advisoryDisplayEnabled, !facts.isEmpty {
                    self.showAdvisorBannerIfNeeded()
                }
            }
        }
    }
}

enum OMDbIMDbResolver {
    static func resolve(explicitIMDb: String?, tmdbID: String?, itemID: String, type: String) async -> String? {
        if let direct = cleanIMDb(explicitIMDb) { return direct }
        if let embedded = embeddedIMDbID(in: [itemID, tmdbID ?? "", type].joined(separator: " ")) { return embedded }
        guard let tmdb = cleanTMDBID(tmdbID) ?? parsedTMDBID(from: itemID) else { return nil }
        let tmdbKind = type.lowercased().contains("series") || type.lowercased().contains("show") || type.lowercased() == "tv" ? "tv" : "movie"
        let key = UserDefaults.standard.string(forKey: "tmdbApiKey")?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        guard !key.isEmpty else {
            print("[OMDb RT] Missing TMDB key for IMDb external-id resolution.")
            return nil
        }
        guard let url = URL(string: "https://api.themoviedb.org/3/\(tmdbKind)/\(tmdb)/external_ids?api_key=\(key)") else { return nil }
        do {
            var request = URLRequest(url: url, timeoutInterval: 10)
            request.setValue("application/json", forHTTPHeaderField: "Accept")
            request.setValue("DebridChannels-tvOS/746 OMDbIMDbResolver", forHTTPHeaderField: "User-Agent")
            let (data, response) = try await URLSession.shared.data(for: request)
            if let http = response as? HTTPURLResponse, !(200..<300).contains(http.statusCode) {
                print("[OMDb RT] TMDB external-id request failed HTTP \(http.statusCode).")
                return nil
            }
            guard let json = try JSONSerialization.jsonObject(with: data) as? [String: Any] else { return nil }
            return cleanIMDb(json["imdb_id"] as? String)
        } catch {
            print("[OMDb RT] TMDB external-id request error: \(error.localizedDescription)")
            return nil
        }
    }

    private static func cleanIMDb(_ value: String?) -> String? {
        let clean = value?.trimmingCharacters(in: .whitespacesAndNewlines).lowercased() ?? ""
        return clean.hasPrefix("tt") ? clean : nil
    }

    private static func embeddedIMDbID(in value: String) -> String? {
        guard let range = value.range(of: #"tt\d{5,}"#, options: [.regularExpression, .caseInsensitive]) else { return nil }
        return String(value[range]).lowercased()
    }

    private static func cleanTMDBID(_ value: String?) -> String? {
        let clean = value?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        return clean.isEmpty ? nil : clean
    }

    private static func parsedTMDBID(from itemID: String) -> String? {
        let parts = itemID.split(separator: ":").map(String.init)
        guard parts.count >= 3, parts[0].lowercased() == "tmdb" else { return nil }
        let clean = parts[2].trimmingCharacters(in: .whitespacesAndNewlines)
        return clean.isEmpty ? nil : clean
    }
}

enum AdvisoryOMDbFactCache {
    private static var cachedFacts: [String: [String]] = [:]
    private static var cacheOrder: [String] = []
    private static let cacheLimit = 96

    static func facts(for lookupKey: String) -> [String]? {
        cachedFacts[lookupKey]
    }

    static func storeFacts(_ facts: [String], for lookupKey: String) {
        cachedFacts[lookupKey] = facts
        cacheOrder.removeAll { $0 == lookupKey }
        cacheOrder.append(lookupKey)
        while cacheOrder.count > cacheLimit {
            cachedFacts.removeValue(forKey: cacheOrder.removeFirst())
        }
    }

    static func handleReleaseStabilityMemoryPressure() {
        cachedFacts.removeAll(keepingCapacity: false)
        cacheOrder.removeAll(keepingCapacity: false)
    }

    static func fetchFacts(lookupKey: String, imdbID: String?, tmdbID: String?, itemID: String, title: String, year: String, type: String, apiKey: String) async -> [String] {
        if let cached = cachedFacts[lookupKey] { return cached }
        guard var components = URLComponents(string: "https://www.omdbapi.com/") else { return [] }
        var queryItems = [URLQueryItem(name: "apikey", value: apiKey), URLQueryItem(name: "tomatoes", value: "true")]
        let resolvedIMDb = await OMDbIMDbResolver.resolve(explicitIMDb: imdbID, tmdbID: tmdbID, itemID: itemID, type: type)
        if let resolvedIMDb, !resolvedIMDb.isEmpty {
            queryItems.append(URLQueryItem(name: "i", value: resolvedIMDb))
        } else {
            print("[OMDb RT] Missing IMDb ID for advisory lookup: \(title)")
            queryItems.append(URLQueryItem(name: "t", value: title))
            let digits = year.filter { $0.isNumber }
            if digits.count >= 4 { queryItems.append(URLQueryItem(name: "y", value: String(digits.prefix(4)))) }
            queryItems.append(URLQueryItem(name: "type", value: type == "series" ? "series" : "movie"))
        }
        components.queryItems = queryItems
        guard let url = components.url else { return [] }
        do {
            let (data, response) = try await URLSession.shared.data(from: url)
            if let http = response as? HTTPURLResponse, !(200..<300).contains(http.statusCode) {
                print("[OMDb RT] Advisory request failed HTTP \(http.statusCode): \(title)")
                storeFacts([], for: lookupKey)
                return []
            }
            guard let json = try JSONSerialization.jsonObject(with: data) as? [String: Any] else { return [] }
            var facts: [String] = []
            if let ratings = json["Ratings"] as? [[String: Any]] {
                for rating in ratings {
                    guard let source = clean(rating["Source"] as? String), source == "Rotten Tomatoes" else { continue }
                    guard let value = clean(rating["Value"] as? String), value.lowercased() != "n/a" else { continue }
                    facts.append("RT \(value)")
                    break
                }
            }
            if !facts.contains(where: { $0.hasPrefix("RT ") }) {
                print("[OMDb RT] No Rotten Tomatoes rating found for advisory: \(title)")
            }
            if let rated = clean(json["Rated"] as? String), rated.uppercased() != "NOT RATED" { facts.append("Rated \(rated)") }
            if let runtime = clean(json["Runtime"] as? String), runtime.lowercased() != "n/a" { facts.append("Runtime \(runtime)") }
            if let imdbRating = clean(json["imdbRating"] as? String), imdbRating.lowercased() != "n/a" { facts.append("IMDb \(imdbRating)") }
            let uniqueFacts = facts.uniquedPreservingOrder()
            storeFacts(uniqueFacts, for: lookupKey)
            return uniqueFacts
        } catch {
            print("[OMDb RT] Advisory request error for \(title): \(error.localizedDescription)")
            storeFacts([], for: lookupKey)
            return []
        }
    }

    private static func clean(_ value: String?) -> String? {
        let trimmed = value?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        return trimmed.isEmpty ? nil : trimmed
    }
}

enum AdvisoryTMDBFactCache {
    private static var cachedFacts: [String: [String]] = [:]
    private static var cacheOrder: [String] = []
    private static let cacheLimit = 96

    private static func storeFacts(_ facts: [String], for lookupKey: String) {
        cachedFacts[lookupKey] = facts
        cacheOrder.removeAll { $0 == lookupKey }
        cacheOrder.append(lookupKey)
        while cacheOrder.count > cacheLimit {
            cachedFacts.removeValue(forKey: cacheOrder.removeFirst())
        }
    }

    static func handleReleaseStabilityMemoryPressure() {
        cachedFacts.removeAll(keepingCapacity: false)
        cacheOrder.removeAll(keepingCapacity: false)
    }

    static func fetchFacts(lookupKey: String, tmdbID: String?, itemID: String, type: String, apiKey: String) async -> [String] {
        if let cached = cachedFacts[lookupKey] { return cached }
        guard let tmdb = cleanTMDBID(tmdbID) ?? parsedTMDBID(from: itemID) else {
            storeFacts([], for: lookupKey)
            return []
        }
        let isSeries = type.lowercased().contains("series") || type.lowercased().contains("show") || type.lowercased() == "tv"
        let path = isSeries ? "tv/\(tmdb)/content_ratings" : "movie/\(tmdb)/release_dates"
        guard let url = URL(string: "https://api.themoviedb.org/3/\(path)?api_key=\(apiKey)") else { return [] }
        do {
            var request = URLRequest(url: url, timeoutInterval: 12)
            request.setValue("application/json", forHTTPHeaderField: "Accept")
            request.setValue("DebridChannels-tvOS-v813-Advisory", forHTTPHeaderField: "User-Agent")
            let (data, response) = try await URLSession.shared.data(for: request)
            if let http = response as? HTTPURLResponse, !(200..<300).contains(http.statusCode) {
                storeFacts([], for: lookupKey)
                return []
            }
            guard let json = try JSONSerialization.jsonObject(with: data) as? [String: Any],
                  let results = json["results"] as? [[String: Any]] else {
                storeFacts([], for: lookupKey)
                return []
            }
            var facts: [String] = []
            let preferredCountries = ["US", "GB", "CA", "AU"]
            for country in preferredCountries {
                guard let entry = results.first(where: { (($0["iso_3166_1"] as? String) ?? "").uppercased() == country }) else { continue }
                if isSeries {
                    if let rating = clean(entry["rating"] as? String) {
                        facts.append("\(country): \(rating)")
                        facts.append("Rated \(rating)")
                        break
                    }
                } else if let releases = entry["release_dates"] as? [[String: Any]] {
                    for release in releases {
                        if let certification = clean(release["certification"] as? String) {
                            facts.append("\(country): \(certification)")
                            facts.append("Rated \(certification)")
                            if let note = clean(release["note"] as? String) { facts.append(note) }
                            break
                        }
                    }
                    if !facts.isEmpty { break }
                }
            }
            let unique = facts.uniquedPreservingOrder()
            storeFacts(unique, for: lookupKey)
            return unique
        } catch {
            storeFacts([], for: lookupKey)
            return []
        }
    }

    private static func clean(_ value: String?) -> String? {
        let trimmed = value?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        return trimmed.isEmpty ? nil : trimmed
    }

    private static func cleanTMDBID(_ value: String?) -> String? {
        let clean = value?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        return clean.isEmpty ? nil : clean
    }

    private static func parsedTMDBID(from itemID: String) -> String? {
        let parts = itemID.split(separator: ":").map(String.init)
        if parts.count >= 3, parts[0].lowercased() == "tmdb" {
            let clean = parts[2].trimmingCharacters(in: .whitespacesAndNewlines)
            return clean.isEmpty ? nil : clean
        }
        guard let range = itemID.range(of: #"\d{2,}"#, options: .regularExpression) else { return nil }
        return String(itemID[range])
    }
}

enum RottenTomatoesScoreCache {
    private static var cachedScores: [String: String] = [:]
    private static var cacheOrder: [String] = []
    private static let cacheLimit = 96

    private static func storeScore(_ score: String, for key: String) {
        cachedScores[key] = score
        cacheOrder.removeAll { $0 == key }
        cacheOrder.append(key)
        while cacheOrder.count > cacheLimit {
            cachedScores.removeValue(forKey: cacheOrder.removeFirst())
        }
    }

    static func handleReleaseStabilityMemoryPressure() {
        cachedScores.removeAll(keepingCapacity: false)
        cacheOrder.removeAll(keepingCapacity: false)
    }

    static func fetchScore(imdbID: String?, title: String, year: String, tmdbID: String? = nil, itemID: String = "", type: String = "") async -> String? {
        let cleanTitle = title.trimmingCharacters(in: .whitespacesAndNewlines)
        let cleanYear = String(year.filter { $0.isNumber }.prefix(4))
        let resolvedIMDb = await OMDbIMDbResolver.resolve(explicitIMDb: imdbID, tmdbID: tmdbID, itemID: itemID, type: type)
        let key = (resolvedIMDb?.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()).flatMap { $0.isEmpty ? nil : $0 }
            ?? "\(cleanTitle.lowercased())|\(cleanYear)"
        if let cached = cachedScores[key] { return cached == "N/A" ? nil : cached }
        guard let apiKey = apiKey() else {
            print("[OMDb RT] Missing API key for media-info lookup: \(title)")
            storeScore("N/A", for: key)
            return nil
        }
        guard var components = URLComponents(string: "https://www.omdbapi.com/") else {
            storeScore("N/A", for: key)
            return nil
        }
        var queryItems = [
            URLQueryItem(name: "apikey", value: apiKey),
            URLQueryItem(name: "tomatoes", value: "true")
        ]
        if let resolvedIMDb, !resolvedIMDb.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            queryItems.append(URLQueryItem(name: "i", value: resolvedIMDb.trimmingCharacters(in: .whitespacesAndNewlines)))
        } else {
            print("[OMDb RT] Missing IMDb ID for media-info lookup, falling back to title/year: \(title)")
            guard !cleanTitle.isEmpty else {
                storeScore("N/A", for: key)
                return nil
            }
            queryItems.append(URLQueryItem(name: "t", value: cleanTitle))
            if !cleanYear.isEmpty { queryItems.append(URLQueryItem(name: "y", value: cleanYear)) }
        }
        components.queryItems = queryItems
        guard let url = components.url else {
            storeScore("N/A", for: key)
            return nil
        }
        let firstScore = await requestRottenTomatoesScore(url: url)
        if let firstScore {
            storeScore(firstScore, for: key)
            return firstScore
        }

        // v730: OMDb sometimes fails an IMDb-id lookup for catalog-provided IDs or omits
        // the Rotten Tomatoes row on the id response. When the user entered an OMDb key,
        // always retry by title/year before showing pending/blank in the advisory.
        if resolvedIMDb != nil, !cleanTitle.isEmpty {
            var fallback = URLComponents(string: "https://www.omdbapi.com/")!
            var fallbackItems = [
                URLQueryItem(name: "apikey", value: apiKey),
                URLQueryItem(name: "tomatoes", value: "true"),
                URLQueryItem(name: "t", value: cleanTitle)
            ]
            if !cleanYear.isEmpty { fallbackItems.append(URLQueryItem(name: "y", value: cleanYear)) }
            fallback.queryItems = fallbackItems
            if let fallbackURL = fallback.url, let fallbackScore = await requestRottenTomatoesScore(url: fallbackURL) {
                storeScore(fallbackScore, for: key)
                return fallbackScore
            }
        }

        print("[OMDb RT] No RT rating found for media-info: \(title)")
        storeScore("N/A", for: key)
        return nil
    }

    private static func requestRottenTomatoesScore(url: URL) async -> String? {
        do {
            let (data, response) = try await URLSession.shared.data(from: url)
            if let http = response as? HTTPURLResponse, !(200..<300).contains(http.statusCode) {
                print("[OMDb RT] Request failed HTTP \(http.statusCode)")
                return nil
            }
            guard let json = try JSONSerialization.jsonObject(with: data) as? [String: Any] else { return nil }
            if let response = (json["Response"] as? String)?.lowercased(), response == "false" {
                print("[OMDb RT] OMDb response false: \((json["Error"] as? String) ?? "unknown")")
                return nil
            }
            guard let ratings = json["Ratings"] as? [[String: Any]] else { return nil }
            return ratings.compactMap { rating -> String? in
                let source = (rating["Source"] as? String)?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
                guard source == "Rotten Tomatoes" else { return nil }
                let value = (rating["Value"] as? String)?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
                return value.isEmpty || value.lowercased() == "n/a" ? nil : value
            }.first
        } catch {
            print("[OMDb RT] Request error: \(error.localizedDescription)")
            return nil
        }
    }

    private static func apiKey() -> String? {
        let defaultsValue = ["omdbApiKey", "OMDB_API_KEY", "omdb_api_key", "rottenTomatoesOMDbApiKey"]
            .compactMap { UserDefaults.standard.string(forKey: $0)?.trimmingCharacters(in: .whitespacesAndNewlines) }
            .first(where: { !$0.isEmpty }) ?? ""
        if !defaultsValue.isEmpty { return defaultsValue }
        let envValue = ProcessInfo.processInfo.environment["OMDB_API_KEY"]?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        return envValue.isEmpty ? nil : envValue
    }
}

enum TopBarAdvisorSession {
    private static var shownItemIDs = Set<String>()
    private static var shownItemOrder: [String] = []
    private static let shownItemLimit = 128

    static func hasShown(_ id: String) -> Bool {
        shownItemIDs.contains(id)
    }

    static func markShown(_ id: String) {
        guard shownItemIDs.insert(id).inserted else { return }
        shownItemOrder.append(id)
        while shownItemOrder.count > shownItemLimit {
            shownItemIDs.remove(shownItemOrder.removeFirst())
        }
    }

    static func handleReleaseStabilityMemoryPressure() {
        shownItemIDs.removeAll(keepingCapacity: false)
        shownItemOrder.removeAll(keepingCapacity: false)
    }
}


struct HeaderPosterArtwork: View {
    let item: MediaItem

    private var posterURL: String? {
        let preferred = item.posterURL?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        if !preferred.isEmpty { return preferred }
        let fallback = item.landscapeURL?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        return fallback.isEmpty ? nil : fallback
    }

    var body: some View {
        ZStack {
            if let url = posterURL {
                RemoteImageFit(url: url, mode: .fit)
                    // v720: key top media-info poster to this exact media item and URL.
                    .id("header-poster-\(item.id)-\(url)")
                    .padding(2)
                    .clipShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
            } else {
                RoundedRectangle(cornerRadius: 14, style: .continuous)
                    .fill(Color.white.opacity(0.06))
                Image(systemName: "photo.on.rectangle.angled")
                    .font(.system(size: 34, weight: .black))
                    .foregroundStyle(.white.opacity(0.44))
            }

            if let resume = PlaybackResumeCacheManager.shared.resumeEntry(for: item) {
                HeaderPosterResumeOverlay(entry: resume)
                    .padding(5)
                    .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .bottom)
            }
        }
        .shadow(color: .black.opacity(0.46), radius: 10, y: 5)
        .accessibilityLabel("Poster artwork")
    }
}


struct HeaderPosterResumeOverlay: View {
    let entry: PlaybackResumeEntry

    private var progress: Double {
        guard entry.duration > 0 else { return 0 }
        return min(0.98, max(0.02, entry.seconds / entry.duration))
    }

    private var remainingText: String {
        guard entry.duration > entry.seconds else { return "Continue" }
        let remaining = max(0, entry.duration - entry.seconds)
        if remaining >= 3600 {
            return "\(Int(remaining / 3600))h \(Int((remaining.truncatingRemainder(dividingBy: 3600)) / 60))m left"
        }
        return "\(max(1, Int(remaining / 60)))m left"
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 4) {
            Text(remainingText.uppercased())
                .font(.system(size: 8, weight: .black, design: .rounded))
                .kerning(0.45)
                .foregroundStyle(.white.opacity(0.96))
                .lineLimit(1)
                .minimumScaleFactor(0.72)
            GeometryReader { geo in
                ZStack(alignment: .leading) {
                    Capsule().fill(Color.white.opacity(0.22))
                    Capsule().fill(Color.white.opacity(0.92))
                        .frame(width: max(5, geo.size.width * progress))
                }
            }
            .frame(height: 4)
        }
        .padding(.horizontal, 7)
        .padding(.vertical, 6)
        .background(RoundedRectangle(cornerRadius: 10, style: .continuous).fill(Color.black.opacity(0.68)))
        .shadow(color: Color.black.opacity(0.20), radius: 6, y: 2)
    }
}

struct AdvisorAlertBanner: View {
    let facts: [String]
    let isWarning: Bool

    private func iconName(for fact: String) -> String {
        let lower = fact.lowercased()
        if lower.contains("rotten") { return "tomato.fill" }
        if lower.contains("imdb") || lower.contains("tmdb") || lower.contains("rating") { return "star.circle.fill" }
        if lower.contains("rated") || lower.contains("content") || lower.contains("advisory") { return "exclamationmark.shield.fill" }
        if lower.contains("runtime") { return "clock.fill" }
        if lower.contains("network") || lower.contains("source") { return "antenna.radiowaves.left.and.right" }
        if lower.contains("resume") { return "play.circle.fill" }
        if lower.contains("hdr") || lower.contains("4k") || lower.contains("1080") { return "sparkles.tv.fill" }
        return "info.circle.fill"
    }

    private func tint(for fact: String) -> Color {
        let lower = fact.lowercased()
        if lower.contains("rotten") { return .red.opacity(0.95) }
        if lower.contains("imdb") || lower.contains("tmdb") || lower.contains("rating") { return .yellow.opacity(0.95) }
        if lower.contains("rated") || lower.contains("content") || lower.contains("advisory") { return .white.opacity(0.78) }
        if lower.contains("network") || lower.contains("source") { return .white.opacity(0.78) }
        if lower.contains("resume") { return .white.opacity(0.78) }
        return .cyan.opacity(0.95)
    }

    var body: some View {
        HStack(spacing: 10) {
            VStack(alignment: .leading, spacing: 5) {
                ForEach(Array(facts.prefix(2).enumerated()), id: \.offset) { _, fact in
                    HStack(spacing: 8) {
                        Image(systemName: iconName(for: fact))
                            .font(.system(size: 14, weight: .black))
                            .foregroundStyle(tint(for: fact))
                            .frame(width: 18)
                        Text(fact)
                            .font(.system(size: 14, weight: .heavy, design: .rounded))
                            .foregroundStyle(.white.opacity(0.96))
                            .lineLimit(1)
                            .minimumScaleFactor(0.68)
                    }
                }
            }
            Spacer(minLength: 0)
        }
        .padding(.horizontal, 14)
        .frame(width: 430, alignment: .leading)
        .frame(minHeight: 58, alignment: .leading)
        .background(.ultraThinMaterial, in: RoundedRectangle(cornerRadius: 17, style: .continuous))
        .background(
            LinearGradient(
                colors: [Color.black.opacity(0.74), Color.black.opacity(0.50), Color.white.opacity(0.10)],
                startPoint: .topLeading,
                endPoint: .bottomTrailing
            ),
            in: RoundedRectangle(cornerRadius: 17, style: .continuous)
        )
        .overlay(RoundedRectangle(cornerRadius: 17, style: .continuous).stroke(Color.white.opacity(0.15), lineWidth: 1))
        .shadow(color: Color.black.opacity(0.38), radius: 16, y: 7)
        .allowsHitTesting(false)
        .focusable(false)
        .accessibilityHidden(true)
    }
}

