struct TopBarMediaInfoTicker: View {
    let items: [String]
    @State private var index: Int = 0
    @State private var ticks: Int = 0
    @State private var visible: Bool = true

    private var activeText: String {
        guard !items.isEmpty else { return "" }
        return items[index % items.count]
    }

    var body: some View {
        Group {
            if visible && !items.isEmpty {
                HStack(spacing: 12) {
                    Text("MEDIA INFO")
                        .font(.system(size: 10, weight: .black, design: .rounded))
                        .tracking(1.2)
                        .foregroundStyle(Color.orange.opacity(0.90))
                    Text(activeText)
                        .font(.system(size: 19, weight: .black, design: .rounded))
                        .foregroundStyle(.white.opacity(0.96))
                        .lineLimit(1)
                        .minimumScaleFactor(0.72)
                        .id(activeText)
                        .transition(.opacity)
                    Spacer(minLength: 0)
                }
                .padding(.horizontal, 18)
                .frame(width: 1180, height: 46, alignment: .leading)
                .background(RoundedRectangle(cornerRadius: 14, style: .continuous).fill(Color.black.opacity(0.34)))
                .overlay(RoundedRectangle(cornerRadius: 14, style: .continuous).stroke(Color.white.opacity(0.12), lineWidth: 1))
            } else {
                Color.clear.frame(width: 1180, height: 46)
            }
        }
        .allowsHitTesting(false)
        .focusable(false)
        .accessibilityHidden(true)
        .onAppear {
            index = 0
            ticks = 0
            visible = !items.isEmpty
        }
        // vBRDC134: this ticker is a finite presentation, not a permanent heartbeat.
        // The old autoconnected Timer kept waking the MainActor every 2.6 seconds after
        // the ticker had already hidden. A view-owned task exits as soon as the sequence
        // finishes and is cancelled automatically when the surface unmounts.
        .task(id: items.joined(separator: "|")) {
            guard visible, !items.isEmpty else { return }
            while !Task.isCancelled, visible {
                try? await Task.sleep(nanoseconds: 2_600_000_000)
                guard !Task.isCancelled, visible, !items.isEmpty else { return }
                ticks += 1
                if ticks >= max(1, items.count) {
                    withAnimation(.easeOut(duration: 0.24)) { visible = false }
                    return
                } else if items.count > 1 {
                    withAnimation(.easeInOut(duration: 0.26)) { index = (index + 1) % items.count }
                }
            }
        }
    }
}

