struct CastFaceCard: View {
    let member: CastMember
    var premium: Bool = false
    var compactTheater: Bool = false
    var publishDuringPlayback: Bool = false
    @AppStorage("popupFontPreset") private var popupFontPreset: String = "SF Rounded"

    private var initials: String {
        let parts = member.name.split(separator: " ")
        let letters = parts.prefix(2).compactMap { $0.first }.map(String.init).joined()
        return letters.isEmpty ? "?" : letters.uppercased()
    }

    var body: some View {
        VStack(spacing: 5) {
            ZStack {
                if let imageURL = member.imageURL, !imageURL.isEmpty {
                    RemoteImageFit(
                        url: imageURL,
                        mode: .fill,
                        maxPixelSize: 512,
                        publishDuringPlayback: publishDuringPlayback,
                        forceVisiblePlaybackPublication: publishDuringPlayback
                    )
                } else {
                    Circle()
                        .fill(LinearGradient(colors: [Color.white.opacity(0.22), Color.orange.opacity(0.22)], startPoint: .topLeading, endPoint: .bottomTrailing))
                    Text(initials)
                        .font(.system(size: 19, weight: .black, design: .rounded))
                        .foregroundStyle(.white.opacity(0.88))
                }
            }
            .frame(width: compactTheater ? 58 : (premium ? 78 : 64), height: compactTheater ? 58 : (premium ? 78 : 64))
            .clipShape(Circle())
            .overlay(Circle().stroke(Color.white.opacity(premium ? 0.24 : 0.18), lineWidth: premium ? 1.4 : 1))
            .shadow(color: .black.opacity(0.35), radius: premium ? 12 : 8, y: 4)
            .shadow(color: Color.orange.opacity(premium ? 0.14 : 0.0), radius: premium ? 16 : 0)

            Text(member.name)
                .font(PopupTypography.font(popupFontPreset, size: compactTheater ? 11 : (premium ? 13 : 12), weight: .black))
                .foregroundStyle(.white.opacity(0.96))
                .lineLimit(1)
                .minimumScaleFactor(0.72)
                .frame(width: compactTheater ? 78 : (premium ? 116 : 86))

            if let role = member.role, !role.isEmpty {
                Text(role)
                    .font(PopupTypography.font(popupFontPreset, size: compactTheater ? 9 : (premium ? 10 : 10), weight: .semibold))
                    .foregroundStyle(.white.opacity(0.64))
                    .lineLimit(1)
                    .minimumScaleFactor(0.72)
                    .frame(width: compactTheater ? 78 : (premium ? 116 : 86))
            }
        }
        .frame(width: compactTheater ? 80 : (premium ? 118 : 88))
