struct QRCodeImage: View {
    let text: String
    private let context = CIContext()
    private let filter = CIFilter.qrCodeGenerator()

    var body: some View {
        if let image = makeQRImage() {
            Image(uiImage: image)
                .interpolation(.none)
                .resizable()
                .scaledToFit()
                .padding(22)
        } else {
            Text("QR unavailable")
                .font(.system(size: 26, weight: .black, design: .rounded))
                .foregroundStyle(.black)
        }
    }

    private func makeQRImage() -> UIImage? {
        filter.message = Data(text.utf8)
        filter.correctionLevel = "M"
        guard let output = filter.outputImage else { return nil }
        let scaled = output.transformed(by: CGAffineTransform(scaleX: 12, y: 12))
        guard let cgImage = context.createCGImage(scaled, from: scaled.extent) else { return nil }
        return UIImage(cgImage: cgImage)
    }
}

struct TrailerPopup: View {
    let url: URL
    let audioURL: URL?
    let requestHeaders: [String: String]
    let sessionKey: String
    let close: () -> Void

    @State private var trailerMuted: Bool = false
    @State private var trailerControlsVisible: Bool = true
    @StateObject private var trailerAsyncRuntime = TrailerAsyncTaskRuntime()
    private var hideControlsTask: Task<Void, Never>? {
            get { trailerAsyncRuntime.hideControlsTask }
            nonmutating set { trailerAsyncRuntime.hideControlsTask = newValue }
        }
    private var dismissTask: Task<Void, Never>? {
            get { trailerAsyncRuntime.dismissTask }
            nonmutating set { trailerAsyncRuntime.dismissTask = newValue }
        }
    @State private var popupVisible: Bool = false
    @State private var lightSweepActive: Bool = false
    @State private var isClosing: Bool = false
    @FocusState private var focusedAction: TrailerPopupAction?
    @AppStorage("trailerEngineMode") private var trailerEngineMode: String = "auto"

    private enum TrailerPopupAction: Hashable {
        case mute
        case close
    }

    private var selectedTrailerEngine: TrailerEngineSelection {
        TrailerEngineSelection(rawValue: trailerEngineMode.lowercased()) ?? .auto
    }

    var body: some View {
        ZStack {
            Color.black
                .opacity(popupVisible && !isClosing ? 0.86 : 0.0)
                .ignoresSafeArea()
                .animation(.easeOut(duration: 0.22), value: popupVisible)
                .animation(.easeIn(duration: 0.16), value: isClosing)

            ZStack {
                trailerBackgroundGlow
                VStack(spacing: 18) {
                    trailerVideoCard
                    if trailerControlsVisible { trailerActionRow.transition(.opacity.combined(with: .move(edge: .bottom))) }
                }
            }
            .signalVisionFocusSection()
            .scaleEffect(popupVisible && !isClosing ? 1.0 : 0.92)
            .opacity(popupVisible && !isClosing ? 1.0 : 0.0)
            .blur(radius: popupVisible && !isClosing ? 0 : 8)
            .animation(.spring(response: 0.34, dampingFraction: 0.82), value: popupVisible)
            .animation(.easeIn(duration: 0.16), value: isClosing)
        }
        .onAppear {
            prepareTrailerPopupEntrance()
        }
        .onChange(of: url.absoluteString) { _ in prepareTrailerPopupEntrance() }
        .signalMoveCommand { direction in
            revealTrailerControls()
            switch direction {
            case .left:
                focusedAction = .mute
            case .right:
                focusedAction = .close
            default:
                break
            }
        }
        .onTapGesture { revealTrailerControls(); activateFocusedTrailerAction() }
        .signalVisionPlayPauseCommand { revealTrailerControls(); activateFocusedTrailerAction() }
        .signalVisionExitCommand( dismissTrailerPopup)
        .onDisappear {
            hideControlsTask?.cancel()
            dismissTask?.cancel()
        }
    }

    private var trailerBackgroundGlow: some View {
        ZStack {
            RoundedRectangle(cornerRadius: 46, style: .continuous)
                .fill(
                    RadialGradient(
                        colors: [Color(red: 0.12, green: 0.28, blue: 0.58).opacity(popupVisible && !isClosing ? 0.34 : 0.0), Color.clear],
                        center: .center,
                        startRadius: 120,
                        endRadius: 900
                    )
                )
                .frame(width: 1660, height: 820)
                .blur(radius: 34)
            RoundedRectangle(cornerRadius: 46, style: .continuous)
                .stroke(Color.white.opacity(popupVisible && !isClosing ? 0.10 : 0.0), lineWidth: 1)
                .frame(width: 1588, height: 748)
        }
        .allowsHitTesting(false)
    }

    private var trailerVideoCard: some View {
        ZStack {
            RoundedRectangle(cornerRadius: 28, style: .continuous)
                .fill(Color.black.opacity(0.96))
            TrailerPlayableSurface(url: url, audioURL: audioURL, requestHeaders: requestHeaders, muted: trailerMuted, sessionKey: sessionKey, engine: selectedTrailerEngine)
                .id(sessionKey + "|" + url.absoluteString + "|audio=\(audioURL?.absoluteString ?? "none")|engine=\(selectedTrailerEngine.rawValue)")
                .padding(2)
            trailerCinemaSweep
                .clipShape(RoundedRectangle(cornerRadius: 28, style: .continuous))
        }
        .frame(width: 1540, height: 720)
        // vBRDC306: do not rasterize/composite the live trailer video into an intermediate
        // SwiftUI surface; let AVPlayerLayer present frames directly at display cadence.
        .clipShape(RoundedRectangle(cornerRadius: 28, style: .continuous))
        .contentShape(RoundedRectangle(cornerRadius: 28, style: .continuous))
        .overlay(trailerGlassStroke.clipShape(RoundedRectangle(cornerRadius: 28, style: .continuous)))
        .shadow(color: Color.black.opacity(0.70), radius: popupVisible ? 42 : 0, x: 0, y: 18)
        .shadow(color: Color(red: 0.42, green: 0.38, blue: 0.62).opacity(0.18), radius: popupVisible ? 34 : 0, x: 0, y: 0)
    }

    private var trailerGlassStroke: some View {
        RoundedRectangle(cornerRadius: 28, style: .continuous)
            .stroke(
                LinearGradient(
                    colors: [Color.white.opacity(0.24), Color(red: 0.42, green: 0.38, blue: 0.62).opacity(0.24), Color.white.opacity(0.08)],
                    startPoint: .topLeading,
                    endPoint: .bottomTrailing
                ),
                lineWidth: 1.4
            )
    }

    private var trailerCinemaSweep: some View {
        GeometryReader { proxy in
            LinearGradient(
                colors: [Color.clear, Color.white.opacity(0.16), Color.clear],
                startPoint: .top,
                endPoint: .bottom
            )
            .frame(width: 260, height: proxy.size.height * 1.5)
            .rotationEffect(.degrees(18))
            .offset(x: lightSweepActive ? proxy.size.width + 220 : -360, y: -proxy.size.height * 0.22)
            .opacity(lightSweepActive ? 0.0 : 1.0)
            .animation(.easeOut(duration: 0.95).delay(0.12), value: lightSweepActive)
        }
        .allowsHitTesting(false)
    }

    private var trailerActionRow: some View {
        HStack(spacing: 18) {
            Button(action: { revealTrailerControls(); trailerMuted.toggle() }) {
                Text(trailerMuted ? "Unmute" : "Mute")
                    .font(.system(size: 24, weight: .bold))
                    .padding(.horizontal, 34)
                    .padding(.vertical, 14)
            }
            .buttonStyle(.borderedProminent)
            .focused($focusedAction, equals: .mute)
            .focusable(true)

            Button(action: dismissTrailerPopup) {
                Text("Close Trailer")
                    .font(.system(size: 24, weight: .bold))
                    .padding(.horizontal, 34)
                    .padding(.vertical, 14)
            }
            .buttonStyle(.borderedProminent)
            .focused($focusedAction, equals: .close)
            .focusable(true)
        }
        .signalVisionFocusSection()
        .opacity(popupVisible && !isClosing ? 1.0 : 0.0)
    }

    private func prepareTrailerPopupEntrance() {
        dismissTask?.cancel()
        trailerMuted = false
        trailerControlsVisible = true
        focusedAction = .close
        isClosing = false
        lightSweepActive = false
        popupVisible = false
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.03) {
            withAnimation(.spring(response: 0.34, dampingFraction: 0.82)) { popupVisible = true }
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.08) { lightSweepActive = true }
        }
        scheduleTrailerControlHide()
    }

    private func activateFocusedTrailerAction() {
        switch focusedAction ?? .close {
        case .mute: trailerMuted.toggle(); scheduleTrailerControlHide()
        case .close: dismissTrailerPopup()
        }
    }

    private func dismissTrailerPopup() {
        hideControlsTask?.cancel()
        dismissTask?.cancel()
        withAnimation(.easeIn(duration: 0.16)) {
            isClosing = true
            trailerControlsVisible = false
        }
        dismissTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: 170_000_000)
            close()
        }
    }

    private func revealTrailerControls() {
        withAnimation(.easeOut(duration: 0.18)) { trailerControlsVisible = true }
        if focusedAction == nil { focusedAction = .close }
        scheduleTrailerControlHide()
    }

    private func scheduleTrailerControlHide() {
        hideControlsTask?.cancel()
        hideControlsTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: 5_000_000_000)
            withAnimation(.easeOut(duration: 0.22)) { trailerControlsVisible = false }
        }
    }
}

enum TrailerEngineSelection: String {
    case auto
    case aether
    case avplayer
    case ksplayer
}

struct TrailerPlayableSurface: View {
    let url: URL
    let audioURL: URL?
    let requestHeaders: [String: String]
    let muted: Bool
    let sessionKey: String
    let engine: TrailerEngineSelection

    @ViewBuilder
    var body: some View {
        // vBRDC268: trailers can explicitly use Aether, AVPlayer, or KSPlayer.
        // Auto intentionally preserves the proven KS trailer lane; Aether is opt-in until
        // physical-Apple-TV trailer testing proves it is the better automatic default.
        if audioURL != nil {
            #if canImport(KSPlayer)
            PlaybackKitKSPlayerHost(
                url: url,
                shouldPlay: true,
                seekSerial: 0,
                seekSeconds: 0,
                seekIsAbsolute: false,
                reloadToken: 0,
                startTimeSeconds: 0,
                externalAudioURL: audioURL,
                externalAudioOffsetMS: 0,
                externalAudioHTTPHeaders: requestHeaders,
                muteAudio: muted,
                contentMode: .scaleAspectFill,
                routeHint: "trailer-popup-adaptive|\(sessionKey)",
                httpHeaders: requestHeaders
            )
            #else
            MissingInternalEngineSurface(message: "This 1080p trailer uses separate video/audio and requires the built-in KSPlayer fallback.")
            #endif
        } else {
        switch engine {
        case .aether:
            // vBRDC279: set AetherEngine's own AVLayerVideoGravity instead of trying to
            // scale the UIKit host from SwiftUI. Aether owns the AVPlayerLayer / sample
            // buffer display layer, so resizeAspectFill must be applied inside the engine.
            PlaybackKitAetherHost(
                url: url,
                shouldPlay: true,
                playAssertionSerial: 1,
                seekSerial: 0,
                seekSeconds: 0,
                seekIsAbsolute: false,
                reloadToken: 0,
                startTimeSeconds: 0,
                isLiveStream: false,
                httpHeaders: requestHeaders.merging([
                    "Accept": "application/vnd.apple.mpegurl,application/x-mpegURL,video/mp4,video/*,*/*"
                ]) { current, _ in current },
                enableDisplayMatch: true,
                videoGravityRaw: "resizeAspectFill"
            )
            .background(Color.black)
            .clipped()

        case .avplayer:
            TrailerAVPlayerSurface(url: url, requestHeaders: requestHeaders, muted: muted, sessionKey: sessionKey)

        case .auto:
            // vBRDC306: mirror NuvioTV's smooth full-screen trailer strategy: a muxed
            // trailer goes straight through a dedicated AVPlayerLayer instead of carrying
            // the full VOD engine stack. Split YouTube video/audio still uses KSPlayer above.
            TrailerAVPlayerSurface(
                url: url,
                requestHeaders: requestHeaders,
                muted: muted,
                sessionKey: sessionKey
            )

        case .ksplayer:
            #if canImport(KSPlayer)
            PlaybackKitKSPlayerHost(
                url: url,
                shouldPlay: true,
                seekSerial: 0,
                seekSeconds: 0,
                seekIsAbsolute: false,
                reloadToken: 0,
                startTimeSeconds: 0,
                externalAudioURL: audioURL,
                externalAudioOffsetMS: 0,
                externalAudioHTTPHeaders: requestHeaders,
                muteAudio: muted,
                contentMode: .scaleAspectFill,
                routeHint: "trailer-popup|\(sessionKey)",
                httpHeaders: requestHeaders
            )
            #else
            MissingInternalEngineSurface(message: "KSPlayer/FFmpeg/Metal was not compiled into this IPA. Choose Aether or AVPlayer for trailer playback.")
            #endif
        }
        }
    }
}

struct TrailerAVPlayerSurface: UIViewRepresentable {
    let url: URL
    let requestHeaders: [String: String]
    let muted: Bool
    let sessionKey: String

    final class NullLayerAction: NSObject, CAAction {
        func run(forKey event: String, object anObject: Any, arguments dict: [AnyHashable : Any]?) {}
    }

    final class PlayerLayerView: UIView {
        override static var layerClass: AnyClass { AVPlayerLayer.self }
        var playerLayer: AVPlayerLayer { layer as! AVPlayerLayer }

        override init(frame: CGRect) {
            super.init(frame: frame)
            configureLayerForSmoothTrailers()
        }

        required init?(coder: NSCoder) {
            super.init(coder: coder)
            configureLayerForSmoothTrailers()
        }

        private func configureLayerForSmoothTrailers() {
            backgroundColor = .black
            isOpaque = true
            isUserInteractionEnabled = false
            layer.isOpaque = true
            layer.drawsAsynchronously = true
            playerLayer.isOpaque = true
            playerLayer.drawsAsynchronously = true
            playerLayer.backgroundColor = UIColor.black.cgColor
            playerLayer.videoGravity = .resizeAspectFill
            playerLayer.contentsScale = SignalVisionWindowMetrics.contentScale
            layer.contentsScale = SignalVisionWindowMetrics.contentScale
            let nullAction = NullLayerAction()
            playerLayer.actions = [
                "position": nullAction,
                "bounds": nullAction,
                "opacity": nullAction,
                "contents": nullAction,
                "sublayers": nullAction,
                "onOrderIn": nullAction,
                "onOrderOut": nullAction
            ]
        }

        override func layoutSubviews() {
            CATransaction.begin()
            CATransaction.setDisableActions(true)
            super.layoutSubviews()
            playerLayer.frame = bounds
            CATransaction.commit()
        }
    }

    final class Coordinator {
        var player: AVPlayer?
        var item: AVPlayerItem?
        var currentURL: URL?
        var currentSessionKey: String?
        var endObserver: NSObjectProtocol?
        var statusObserver: NSKeyValueObservation?
        var timeControlObserver: NSKeyValueObservation?
        var rateObserver: NSKeyValueObservation?
        var hasIssuedInitialPlay = false

        deinit { teardown() }

        func teardown() {
            if let endObserver = endObserver { NotificationCenter.default.removeObserver(endObserver) }
            endObserver = nil
            statusObserver = nil
            timeControlObserver = nil
            rateObserver = nil
            player?.pause()
            player?.replaceCurrentItem(with: nil)
            player = nil
            item = nil
            currentURL = nil
            currentSessionKey = nil
            hasIssuedInitialPlay = false
        }

        func configure(url: URL, requestHeaders: [String: String], muted: Bool, sessionKey: String, view: PlayerLayerView) {
            CATransaction.begin()
            CATransaction.setDisableActions(true)
            view.playerLayer.videoGravity = .resizeAspectFill
            view.playerLayer.backgroundColor = UIColor.black.cgColor
            view.playerLayer.contentsScale = SignalVisionWindowMetrics.contentScale
            view.layer.contentsScale = SignalVisionWindowMetrics.contentScale
            CATransaction.commit()

            if currentURL != url || currentSessionKey != sessionKey || player == nil {
                teardown()
                currentURL = url
                currentSessionKey = sessionKey

                let asset = AVURLAsset(url: url, options: [
                    AVURLAssetPreferPreciseDurationAndTimingKey: false,
                    "AVURLAssetHTTPHeaderFieldsKey": requestHeaders.merging([
                        "Accept": "application/vnd.apple.mpegurl,application/x-mpegURL,video/mp4,video/*,*/*"
                    ]) { current, _ in current }
                ])
                let loadedItem = AVPlayerItem(asset: asset)
                loadedItem.preferredForwardBufferDuration = 6.0
                loadedItem.canUseNetworkResourcesForLiveStreamingWhilePaused = true
                loadedItem.seekingWaitsForVideoCompositionRendering = false
                loadedItem.audioTimePitchAlgorithm = .timeDomain
                loadedItem.preferredPeakBitRate = 0
                if #available(tvOS 11.0, *) {
                    loadedItem.preferredMaximumResolution = CGSize(width: 3840, height: 2160)
                }

                let builtPlayer = AVPlayer(playerItem: loadedItem)
                builtPlayer.automaticallyWaitsToMinimizeStalling = true
                #if os(tvOS)
                builtPlayer.preventsDisplaySleepDuringVideoPlayback = true
                #endif
                builtPlayer.actionAtItemEnd = .none
                builtPlayer.isMuted = muted
                builtPlayer.volume = muted ? 0.0 : 1.0

                player = builtPlayer
                item = loadedItem

                CATransaction.begin()
                CATransaction.setDisableActions(true)
                view.playerLayer.player = builtPlayer
                view.playerLayer.videoGravity = .resizeAspectFill
                view.playerLayer.frame = view.bounds
                CATransaction.commit()

                installObservers(player: builtPlayer, item: loadedItem)
                startPlaybackIfNeeded(force: true)
            } else {
                player?.isMuted = muted
                player?.volume = muted ? 0.0 : 1.0
            }
        }

        func installObservers(player: AVPlayer, item: AVPlayerItem) {
            statusObserver = item.observe(\.status, options: [.new, .initial]) { [weak self] item, _ in
                guard item.status == .readyToPlay else { return }
                DispatchQueue.main.async {
                    guard let self = self else { return }
                    self.startPlaybackIfNeeded()
                }
            }
            timeControlObserver = player.observe(\.timeControlStatus, options: [.new]) { [weak self] player, _ in
                guard player.timeControlStatus == .paused else { return }
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.35) { self?.resumeIfUnexpectedlyPaused() }
            }
            rateObserver = player.observe(\.rate, options: [.new]) { [weak self] player, _ in
                guard player.rate == 0 else { return }
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.45) { self?.resumeIfUnexpectedlyPaused() }
            }
            endObserver = NotificationCenter.default.addObserver(
                forName: .AVPlayerItemDidPlayToEndTime,
                object: item,
                queue: .main
            ) { [weak self] _ in
                // v595: Trailer popup must not auto-loop. Earlier builds restarted here,
                // which looked like half-trailer stops/replays when HLS or the item reached end.
                self?.hasIssuedInitialPlay = false
                self?.player?.pause()
            }
        }

        func startPlaybackIfNeeded(force: Bool = false) {
            guard let player = player, let item = item else { return }
            guard item.status != .failed else { return }
            if !force && hasIssuedInitialPlay && player.rate > 0 { return }
            hasIssuedInitialPlay = true
            if #available(tvOS 10.0, *) { player.playImmediately(atRate: 1.0) }
            else { player.play() }
        }

        func resumeIfUnexpectedlyPaused() {
            guard let player = player, let item = item else { return }
            guard item.status != .failed else { return }
            guard hasIssuedInitialPlay, player.rate == 0 else { return }
            // v595: Do not treat normal end-of-trailer as a stall. AVPlayer may briefly report
            // paused/rate=0 at the end; restarting there caused repeat/loop behavior.
            let current = CMTimeGetSeconds(player.currentTime())
            let duration = CMTimeGetSeconds(item.duration)
            if current.isFinite, duration.isFinite, duration > 1.0, current >= max(0, duration - 1.0) {
                hasIssuedInitialPlay = false
                return
            }
            player.play()
        }
    }

    func makeCoordinator() -> Coordinator { Coordinator() }

    func makeUIView(context: Context) -> PlayerLayerView {
        let view = PlayerLayerView()
        view.backgroundColor = .black
        view.isOpaque = true
        view.isUserInteractionEnabled = false
        return view
    }

    func updateUIView(_ view: PlayerLayerView, context: Context) {
        context.coordinator.configure(url: url, requestHeaders: requestHeaders, muted: muted, sessionKey: sessionKey, view: view)
    }

    static func dismantleUIView(_ view: PlayerLayerView, coordinator: Coordinator) {
        coordinator.teardown()
        view.playerLayer.player = nil
    }
}




struct RasterizedOverlayModifier: ViewModifier {
    var active: Bool

    func body(content: Content) -> some View {
        content.background(RasterizationHost(active: active).allowsHitTesting(false))
    }
}

struct RasterizationHost: UIViewRepresentable {
    var active: Bool

    func makeUIView(context: Context) -> UIView {
        let view = UIView(frame: .zero)
        view.isUserInteractionEnabled = false
        view.backgroundColor = .clear
        return view
    }

    func updateUIView(_ view: UIView, context: Context) {
        view.layer.shouldRasterize = active
        view.layer.rasterizationScale = SignalVisionWindowMetrics.contentScale
        view.layer.drawsAsynchronously = active
    }
}

private enum AlternateAudioHandoffState: String, Hashable {
    case idle
    case switching
    case active
    case restoring
    case failed
}

enum VODOverlayThemePreset: String, CaseIterable, Hashable, Identifiable {
    case original = "Original"
    case pro = "Pro"
    case cinema = "Cinema"
    case mediaCenter = "Media Center"
    case studio = "Studio"
    case minimal = "Minimal"
    case noir = "Noir"
    case prestige = "Prestige"

    var id: String { rawValue }

    var displayName: String { rawValue }

    var icon: String {
        switch self {
        case .original: return "sparkles.tv"
        case .pro: return "rectangle.3.group.bubble.left.fill"
        case .cinema: return "film.stack.fill"
        case .mediaCenter: return "play.rectangle.on.rectangle.fill"
        case .studio: return "slider.horizontal.3"
        case .minimal: return "minus.rectangle"
        case .noir: return "circle.lefthalf.filled"
        case .prestige: return "crown.fill"
        }
    }

    var subtitle: String {
        switch self {
        case .original: return "The exact current Debrid Channels VOD overlay."
        case .pro: return "Floating technical HUD islands: metadata left, telemetry right, detached timeline and controls."
        case .cinema: return "Open theatrical composition with editorial metadata, a premiere line, and detached controls over picture."
        case .mediaCenter: return "Kodi-inspired side OSD: structured information column with a separate playback rail and no bottom slab."
        case .studio: return "Broadcast split HUD with a metadata monitor, telemetry module, and independent control console."
        case .minimal: return "Nearly chrome-free: metadata, facts, timeline, and controls float directly over the movie."
        case .noir: return "Monochrome editorial split with a separate telemetry card and independent hairline controls."
        case .prestige: return "Luxury theater cards with warm-metal borders, separate telemetry plaque, and detached control row."
        }
    }

    var accent: Color {
        switch self {
        case .original: return .orange
        case .pro: return Color(red: 0.36, green: 0.78, blue: 1.0)
        case .cinema: return Color(red: 0.96, green: 0.55, blue: 0.20)
        case .mediaCenter: return Color(red: 0.10, green: 0.66, blue: 0.96)
        case .studio: return Color(red: 0.26, green: 0.86, blue: 0.79)
        case .minimal: return .white
        case .noir: return Color.white.opacity(0.90)
        case .prestige: return Color(red: 0.92, green: 0.73, blue: 0.34)
        }
    }
}

struct VODOverlayThemePreview: View {
    let theme: VODOverlayThemePreset

    var body: some View {
        HStack(spacing: 14) {
            previewGraphic
                .frame(width: 250, height: 126)
                .clipped()
                .shadow(color: theme == .minimal ? .clear : .black.opacity(0.42), radius: 12, y: 7)

            VStack(alignment: .leading, spacing: 5) {
                HStack(spacing: 8) {
                    Image(systemName: theme.icon)
                        .foregroundStyle(theme.accent)
                    Text(theme.displayName)
                        .font(.system(size: 18, weight: .black, design: theme == .cinema || theme == .prestige ? .serif : .rounded))
                        .foregroundStyle(.white)
                }
                Text(theme.subtitle)
                    .font(.system(size: 13, weight: .semibold, design: .rounded))
                    .foregroundStyle(.white.opacity(0.62))
                    .lineLimit(3)
            }
            Spacer(minLength: 0)
        }
        .padding(14)
        .frame(maxWidth: 900, alignment: .leading)
        .background(RoundedRectangle(cornerRadius: 18, style: .continuous).fill(Color.white.opacity(0.035)))
        .overlay(RoundedRectangle(cornerRadius: 18, style: .continuous).stroke(theme.accent.opacity(0.18), lineWidth: 1))
    }

    @ViewBuilder
    private var previewGraphic: some View {
        switch theme {
        case .original:
            originalPreview
        case .pro:
            ZStack {
                previewVideoBackground
                HStack(alignment: .bottom, spacing: 8) {
                    previewPanel(width: 142, height: 72, radius: 14, opacity: 0.58) { previewMetadataLines }
                    previewPanel(width: 70, height: 54, radius: 11, opacity: 0.54) { previewTelemetryGrid }
                }
                .offset(y: 8)
                VStack { Spacer(); previewTimeline(width: 180); previewControls(count: 4) }
                    .padding(.bottom, 8)
            }
        case .cinema:
            ZStack(alignment: .bottomLeading) {
                previewVideoBackground
                VStack(alignment: .leading, spacing: 5) {
                    previewMetadataLines
                    Rectangle().fill(theme.accent.opacity(0.8)).frame(width: 128, height: 1)
                    previewTimeline(width: 172)
                    previewControls(count: 5)
                }
                .padding(12)
            }
        case .mediaCenter:
            ZStack(alignment: .bottomLeading) {
                previewVideoBackground
                HStack(spacing: 0) {
                    Rectangle().fill(theme.accent).frame(width: 3)
                    VStack(alignment: .leading, spacing: 6) {
                        previewMetadataLines
                        previewTelemetryGrid
                    }
                    .padding(8)
                }
                .frame(width: 154, height: 100)
                .background(Color.black.opacity(0.66))
                VStack { Spacer(); previewTimeline(width: 132); previewControls(count: 4) }
                    .padding(.leading, 8)
                    .padding(.bottom, 6)
            }
        case .studio:
            ZStack {
                previewVideoBackground
                HStack(alignment: .bottom, spacing: 8) {
                    previewPanel(width: 145, height: 78, radius: 10, opacity: 0.52) { previewMetadataLines }
                    VStack(spacing: 6) {
                        previewPanel(width: 66, height: 38, radius: 8, opacity: 0.48) { previewTelemetryGrid }
                        previewPanel(width: 66, height: 28, radius: 8, opacity: 0.40) { previewControls(count: 3) }
                    }
                }
                .offset(y: 4)
                VStack { Spacer(); previewTimeline(width: 192) }.padding(.bottom, 7)
            }
        case .minimal:
            ZStack(alignment: .bottomLeading) {
                previewVideoBackground
                VStack(alignment: .leading, spacing: 5) {
                    previewMetadataLines
                    previewTelemetryGrid.opacity(0.65)
                    previewTimeline(width: 182)
                    previewControls(count: 4)
                }
                .padding(12)
            }
        case .noir:
            ZStack {
                previewVideoBackground.grayscale(1)
                HStack(alignment: .bottom, spacing: 10) {
                    VStack(alignment: .leading, spacing: 6) {
                        Rectangle().fill(Color.white.opacity(0.8)).frame(width: 50, height: 1)
                        previewMetadataLines.grayscale(1)
                    }
                    previewPanel(width: 68, height: 55, radius: 0, opacity: 0.48) { previewTelemetryGrid.grayscale(1) }
                }
                .offset(y: 4)
                VStack { Spacer(); previewTimeline(width: 176).grayscale(1); previewControls(count: 4).grayscale(1) }
                    .padding(.bottom, 8)
            }
        case .prestige:
            ZStack {
                previewVideoBackground
                HStack(alignment: .bottom, spacing: 8) {
                    previewPanel(width: 142, height: 74, radius: 16, opacity: 0.62) { previewMetadataLines }
                    previewPanel(width: 70, height: 54, radius: 13, opacity: 0.54) { previewTelemetryGrid }
                }
                .overlay(alignment: .bottom) {
                    Rectangle().fill(theme.accent.opacity(0.7)).frame(width: 120, height: 1).offset(y: 10)
                }
                VStack { Spacer(); previewTimeline(width: 178); previewControls(count: 5) }
                    .padding(.bottom, 8)
            }
        }
    }

    private var originalPreview: some View {
        ZStack(alignment: .bottomLeading) {
            RoundedRectangle(cornerRadius: 15, style: .continuous)
                .fill(Color.black.opacity(0.62))
            VStack(alignment: .leading, spacing: 7) {
                HStack(spacing: 8) {
                    RoundedRectangle(cornerRadius: 5, style: .continuous)
                        .fill(Color.white.opacity(0.18))
                        .frame(width: 34, height: 48)
                    previewMetadataLines
                }
                previewTimeline(width: 194)
                previewControls(count: 4)
            }
            .padding(12)
        }
        .overlay(RoundedRectangle(cornerRadius: 15, style: .continuous).stroke(Color.orange.opacity(0.16), lineWidth: 1))
    }

    private var previewVideoBackground: some View {
        ZStack {
            LinearGradient(colors: [Color.black, Color(red: 0.07, green: 0.08, blue: 0.10)], startPoint: .topLeading, endPoint: .bottomTrailing)
            RadialGradient(colors: [theme.accent.opacity(0.10), .clear], center: .topTrailing, startRadius: 5, endRadius: 210)
        }
    }

    private var previewMetadataLines: some View {
        VStack(alignment: .leading, spacing: 5) {
            Capsule().fill(Color.white.opacity(0.88)).frame(width: 92, height: 7)
            Capsule().fill(Color.white.opacity(0.30)).frame(width: 126, height: 5)
            Capsule().fill(theme.accent.opacity(0.70)).frame(width: 66, height: 4)
        }
    }

    private var previewTelemetryGrid: some View {
        VStack(alignment: .leading, spacing: 4) {
            HStack(spacing: 4) {
                Capsule().fill(Color.white.opacity(0.34)).frame(width: 28, height: 4)
                Capsule().fill(theme.accent.opacity(0.54)).frame(width: 22, height: 4)
            }
            HStack(spacing: 4) {
                Capsule().fill(Color.white.opacity(0.22)).frame(width: 24, height: 4)
                Capsule().fill(Color.white.opacity(0.28)).frame(width: 30, height: 4)
            }
        }
    }

    private func previewPanel<PanelContent: View>(width: CGFloat, height: CGFloat, radius: CGFloat, opacity: Double, @ViewBuilder content: () -> PanelContent) -> some View {
        content()
            .padding(7)
            .frame(width: width, height: height, alignment: .leading)
            .background(RoundedRectangle(cornerRadius: radius, style: .continuous).fill(Color.black.opacity(opacity)))
            .overlay(RoundedRectangle(cornerRadius: radius, style: .continuous).stroke(theme.accent.opacity(0.24), lineWidth: 1))
    }

    private func previewTimeline(width: CGFloat) -> some View {
        ZStack(alignment: .leading) {
            Capsule().fill(Color.white.opacity(0.18)).frame(width: width, height: 2)
            Capsule().fill(theme.accent.opacity(0.80)).frame(width: width * 0.42, height: 2)
            Circle().fill(Color.white).frame(width: 6, height: 6).offset(x: width * 0.42 - 3)
        }
        .frame(width: width, height: 6)
    }

    private func previewControls(count: Int) -> some View {
        HStack(spacing: 5) {
            ForEach(0..<count, id: \.self) { index in
                Circle()
                    .fill(index == 0 ? theme.accent.opacity(0.82) : Color.white.opacity(0.15))
                    .frame(width: 12, height: 12)
            }
        }
    }
}

struct VODOverlayThemeBackdrop: View {
    let theme: VODOverlayThemePreset

    private var bottomBlackOpacity: Double {
        switch theme {
        case .original: return 0.0
        case .minimal: return 0.26
        case .cinema: return 0.34
        case .noir: return 0.38
        case .prestige: return 0.36
        case .pro, .mediaCenter, .studio: return 0.32
        }
    }

    private var accentOpacity: Double {
        switch theme {
        case .original, .minimal, .noir: return 0.0
        case .cinema, .prestige: return 0.055
        default: return 0.045
        }
    }

    var body: some View {
        ZStack(alignment: .bottom) {
            // v1160: keep the movie visible. Non-Original themes use only a restrained
            // lower-screen readability fade instead of the v1157 near-opaque full-screen veil.
            LinearGradient(
                colors: [Color.clear, Color.clear, Color.black.opacity(bottomBlackOpacity)],
                startPoint: .top,
                endPoint: .bottom
            )
            if accentOpacity > 0 {
                RadialGradient(
                    colors: [theme.accent.opacity(accentOpacity), Color.clear],
                    center: .bottomTrailing,
                    startRadius: 10,
                    endRadius: 760
                )
            }
        }
        .allowsHitTesting(false)
    }
}

struct VODOverlayThemeShell<Content: View>: View {
    let theme: VODOverlayThemePreset
    let shelfExpanded: Bool
    let controlsVisible: Bool
    let interactionEnabled: Bool
    let disabled: Bool
    let rasterActive: Bool
    let isPlaying: Bool
    let content: Content

    init(
        theme: VODOverlayThemePreset,
        shelfExpanded: Bool,
        controlsVisible: Bool,
        interactionEnabled: Bool,
        disabled: Bool,
        rasterActive: Bool,
        isPlaying: Bool,
        @ViewBuilder content: () -> Content
    ) {
        self.theme = theme
        self.shelfExpanded = shelfExpanded
        self.controlsVisible = controlsVisible
        self.interactionEnabled = interactionEnabled
        self.disabled = disabled
        self.rasterActive = rasterActive
        self.isPlaying = isPlaying
        self.content = content()
    }

    var body: some View {
        themedSurface
            .foregroundStyle(.white)
            .opacity(controlsVisible ? 1.0 : 0.0)
            .allowsHitTesting(interactionEnabled)
            .disabled(disabled)
            .signalVisionFocusSection()
            .contentShape(Rectangle())
            .zIndex(25)
            .modifier(RasterizedOverlayModifier(active: rasterActive))
            .animation(isPlaying ? nil : .easeInOut(duration: 0.18), value: controlsVisible)
            .animation(.spring(response: 0.30, dampingFraction: 0.88), value: shelfExpanded)
    }

    // v1169: Non-Original themes no longer share a universal bottom-deck surface.
    // This wrapper now owns only common visibility/focus/raster behavior; each theme
    // composes its own independent geometry inside VODPlayerScreen. Original remains
    // on its untouched production path and never enters this shell.
    @ViewBuilder private var themedSurface: some View {
        content
    }
}

enum VODFeaturedCastPresentationMode: String, CaseIterable, Hashable {
    case off
    case compactOverlay
    case fullPoster

    var displayName: String {
        switch self {
        case .off: return "Off"
        case .compactOverlay: return "Cast Banner"
        case .fullPoster: return "Full Poster"
        }
    }

    var next: VODFeaturedCastPresentationMode {
        switch self {
        case .off: return .compactOverlay
        case .compactOverlay: return .fullPoster
        case .fullPoster: return .off
        }
    }
}

// vBRDC184: Playback UNITY uses the exact same production catalog rows while the
// current Live TV channel or VOD title keeps playing underneath. These destinations
// only choose the existing Home / Movies / TV Shows filter; no catalog is duplicated.
private enum PlaybackUnityCatalogDestination: String, CaseIterable, Hashable {
    case home
    case movies
    case shows

    var title: String {
        switch self {
        case .home: return "Home"
        case .movies: return "Movies"
        case .shows: return "TV Shows"
        }
    }

    var icon: String {
        switch self {
        case .home: return "house.fill"
        case .movies: return "film.fill"
        case .shows: return "tv.fill"
        }
    }

    var catalogFilter: String? {
        switch self {
        case .home: return nil
        case .movies: return "movie"
        case .shows: return "series"
        }
    }
}

struct VODPlayerScreen: View {
    @EnvironmentObject var store: CatalogStore
    @Environment(\.scenePhase) private var scenePhase
    let item: MediaItem
    let url: URL
    // Immutable identity allocated by CatalogStore before this launch is published.
    let playbackPresentationID: UUID
    // vBRDC021: the existing root Episode Alert delivery state is injected into the
    // player presentation. No second scanner, timer, or polling system is created.
    let episodeAlert: NewEpisodeAlertHit?
    let episodeAlertSide: NewEpisodeAlertBannerSide
    let episodeAlertTheme: NewEpisodeAlertTheme
    let onEpisodeAlertPresented: (NewEpisodeAlertHit) -> Void

    @State private var player: AVPlayer? = nil
    @State private var controlsVisible = true
    @State private var visionPlaybackExitHovered = false
    // vBRDC184: one shared in-player catalog state powers both Live TV and VOD.
    // Video is intentionally not paused when this surface opens.
    @State private var playbackUnityCatalogDestination: PlaybackUnityCatalogDestination? = nil
    @State private var playbackBrowseEpisodeAlertOpenIntent: NewEpisodeAlertHit? = nil
    @State private var isPlaying = true
    @State private var isLoading = true
    @State private var isFirstFrameReady = false
    // vBRDC296: KSPlayer has a longer native surface/bootstrap path than Aether. Keep a
    // deterministic loading cover up until KS reports its first real frame instead of
    // allowing intermediate handoff state to expose a black screen.
    @State private var ksLoadingCoverActive = false
    // Phase 6 distinguishes a genuine player first frame from the older bounded
    // loading-cover safety release. Once real playback progress is confirmed,
    // automatic source switching is permanently disabled for this presentation.
    @State private var hasStableFirstFramePlayback = false
    @State private var errorText: String? = nil
    @State private var retryText: String? = nil
    @State private var currentSeconds: Double = 0
    @State private var durationSeconds: Double = 0
    // vBRDC062: actual KSPlayer playable endpoint. This is intentionally separate from
    // the playback clock so the VOD scrubber can show the reserve growing in real time
    // while first-frame playback starts immediately.
    @State private var bufferedPlaybackSeconds: Double = 0
    @State private var metadataRuntimeSeconds: Double = 0
    @State private var metadataRuntimeLabel: String = ""
    @State private var playbackMetadataItem: MediaItem? = nil
    @State private var pendingPlaybackMetadataItem: MediaItem? = nil
    @StateObject private var vodAsyncRuntime = VODPlayerAsyncTaskRuntime()
    private var playbackMetadataTask: Task<Void, Never>? {
            get { vodAsyncRuntime.playbackMetadataTask }
            nonmutating set { vodAsyncRuntime.playbackMetadataTask = newValue }
        }
    // v1104: these live at the player level so hiding/unmounting VOD chrome does
    // not restart Featured Cast or lose the loaded review score.
    @State private var featuredCastSpotlightIndex: Int = 0
    // v1136 Phase 14: the one-time full-poster title hold belongs to the playback
    // presentation, not the transient overlay view. Once claimed it can never restart
    // because the VOD chrome hid/remounted while the four-second window was running.
    @State private var featuredCastInitialHoldClaimed: Bool = false
    @State private var featuredCastFocusRequestToken: UInt64 = 0
    // vBRDC119: manual LEFT/RIGHT Cast browsing is a standard VOD overlay interaction.
    // The token resets only the existing seven-second visible rotation clock after a manual
    // move; it does not create a second timer or alter hidden/offscreen Cast behavior.
    @State private var featuredCastManualNavigationToken: UInt64 = 0
    @State private var castExplorerShouldResumePlayback: Bool = false
    // v1108: player-owned Production & Ratings artwork position survives VOD
    // overlay hide/show. The rotating panel receives this as a binding.
    @State private var vodProductionArtworkIndex: Int = 0
        @State private var vodRottenTomatoesScore: String? = nil
    private var vodReviewTask: Task<Void, Never>? {
            get { vodAsyncRuntime.vodReviewTask }
            nonmutating set { vodAsyncRuntime.vodReviewTask = newValue }
        }
    // v1111: review lookups are decorative and must never share the source-opening window.
    // This identity prevents duplicate OMDb/TMDB retries during one playback presentation.
    @State private var vodReviewResolvedItemID: String? = nil
    @State private var vodProductionMetadata: VODProductionMetadataSnapshot = .empty
    @State private var vodProductionMetadataItemID: String? = nil
    // vBRDC200: metadata may finish while playback chrome is hidden, but the completion
    // is held privately until visible UI actually needs it.
    @State private var pendingVODProductionMetadata: VODProductionMetadataSnapshot? = nil
    @State private var pendingVODProductionMetadataItemID: String? = nil
    private var vodProductionMetadataTask: Task<Void, Never>? {
            get { vodAsyncRuntime.vodProductionMetadataTask }
            nonmutating set { vodAsyncRuntime.vodProductionMetadataTask = newValue }
        }
    // v1134 Phase 13: Cast Explorer is user-invoked only. No person lookup starts merely
    // because a cast portrait is present, and all work is cancelled when the explorer closes.
    @State private var castExplorerMember: CastMember? = nil
    @State private var castExplorerSnapshot: CastExplorerSnapshot? = nil
    @State private var castExplorerLoading: Bool = false
    @State private var castExplorerError: String? = nil
    private var castExplorerTask: Task<Void, Never>? {
            get { vodAsyncRuntime.castExplorerTask }
            nonmutating set { vodAsyncRuntime.castExplorerTask = newValue }
        }
    // vBRDC041: one-time VOD Cast Explorer onboarding. The hint is presentation-only,
    // remains visible for 30 seconds on the first successful VOD startup, then never
    // reappears unless the viewer explicitly replays first-time setup from Settings.
    @State private var vodCastExplorerOnboardingVisible: Bool = false
    private var vodCastExplorerOnboardingTask: Task<Void, Never>? {
            get { vodAsyncRuntime.vodCastExplorerOnboardingTask }
            nonmutating set { vodAsyncRuntime.vodCastExplorerOnboardingTask = newValue }
        }
    // Phase 15: full-screen episode browsing and cross-title playback switching remain
    // presentation-owned. The current playback stays paused until a newly selected title
    // actually publishes a different playback presentation.
    @State private var vodEpisodeBrowserVisible: Bool = false
    @State private var vodEpisodeBrowserItems: [MediaItem] = []
    @State private var vodEpisodeBrowserLoading: Bool = false
    @State private var vodEpisodeBrowserError: String? = nil
    private var vodEpisodeBrowserTask: Task<Void, Never>? {
            get { vodAsyncRuntime.vodEpisodeBrowserTask }
            nonmutating set { vodAsyncRuntime.vodEpisodeBrowserTask = newValue }
        }
    @State private var vodEpisodeBrowserShouldResumePlayback: Bool = false
    @State private var vodEpisodeBrowserSeriesTitle: String = ""
    @State private var pendingVODSwitchItem: MediaItem? = nil
    @State private var pendingVODSwitchContext: String = ""
    @State private var pendingVODSwitchError: String? = nil
    @State private var pendingVODSwitchInProgress: Bool = false
    @State private var pendingVODSwitchSources: [StreamLink] = []
    @State private var pendingVODSwitchResolvedItem: MediaItem? = nil
    @State private var pendingVODSwitchSourcePickerVisible: Bool = false
    private var pendingVODSwitchTask: Task<Void, Never>? {
            get { vodAsyncRuntime.pendingVODSwitchTask }
            nonmutating set { vodAsyncRuntime.pendingVODSwitchTask = newValue }
        }
    private var runtimeLookupTask: Task<Void, Never>? {
            get { vodAsyncRuntime.runtimeLookupTask }
            nonmutating set { vodAsyncRuntime.runtimeLookupTask = newValue }
        }
    private var timelineMetadataRecoveryTask: Task<Void, Never>? {
            get { vodAsyncRuntime.timelineMetadataRecoveryTask }
            nonmutating set { vodAsyncRuntime.timelineMetadataRecoveryTask = newValue }
        }
    @State private var hasRecoveredSeekableMetadata: Bool = false
    @AppStorage("vodVideoFitModeV1") private var vodVideoFitModeRaw: String = DebridVideoFitMode.fit.rawValue

    private var vodVideoFitMode: DebridVideoFitMode {
        DebridVideoFitMode(rawValue: vodVideoFitModeRaw) ?? .fit
    }
    private var timeObserver: Any? {
            get { vodAsyncRuntime.timeObserver }
            nonmutating set { vodAsyncRuntime.timeObserver = newValue }
        }
    private var statusObserver: NSKeyValueObservation? {
            get { vodAsyncRuntime.statusObserver }
            nonmutating set { vodAsyncRuntime.statusObserver = newValue }
        }
    private var hideTask: Task<Void, Never>? {
            get { vodAsyncRuntime.hideTask }
            nonmutating set { vodAsyncRuntime.hideTask = newValue }
        }
    private var endObserver: NSObjectProtocol? {
            get { vodAsyncRuntime.endObserver }
            nonmutating set { vodAsyncRuntime.endObserver = newValue }
        }
    private var renderWatchdogTask: Task<Void, Never>? {
            get { vodAsyncRuntime.renderWatchdogTask }
            nonmutating set { vodAsyncRuntime.renderWatchdogTask = newValue }
        }
    private var nativePrepareTask: Task<Void, Never>? {
            get { vodAsyncRuntime.nativePrepareTask }
            nonmutating set { vodAsyncRuntime.nativePrepareTask = newValue }
        }
    @State private var activePanel: PlayerPanel? = nil
    @State private var playbackNotice: String = ""
    @State private var lastPlayerActionAt: TimeInterval = 0
    @State private var lastPlayerMoveAt: TimeInterval = 0
    @State private var forceVLCSurface = false
    @State private var forceKSPlayerSurface = false
    @State private var forceAetherSurface = false
    @State private var avRetryAttemptedForCurrentURL = false
    @State private var nativeProfileText: String = ""
    // Phase 1: snapshot-only diagnostics. This value changes only when the hidden
    // Playback Health panel is opened or manually refreshed, so playback does not
    // continuously invalidate the full VOD overlay.
    @State private var playbackHealthSnapshot: PlaybackHealthSnapshot = .empty
    @State private var alternateAudioDiagnosticsSnapshot: AlternateAudioBridgeDiagnosticsSnapshot = .empty
    @State private var vlcSeekSerial = 0
    @State private var vlcSeekSeconds: Double = 0
    @State private var ksSeekSerial = 0
    @State private var ksSeekSeconds: Double = 0
    @State private var ksSeekIsAbsolute = false
    // vBRDC085: an explicit KS play assertion is separate from the Boolean play state.
    // Automatic resume can confirm while `isPlaying` is already true, so assigning true
    // again does not produce a SwiftUI update. This serial guarantees the active KS layer
    // receives a fresh Play command after a confirmed resume without recreating the surface.
    @State private var ksPlayAssertionSerial = 0
    @State private var vlcSurfaceToken: Int = 0
    @State private var ksSurfaceToken: Int = 0
    @State private var ksStartTimeSeconds: Double = 0
    @State private var resumeEntry: PlaybackResumeEntry? = nil
    @State private var didAttemptAutomaticResume = false
    @State private var pendingAutomaticResumeSeconds: Double? = nil
    private var automaticResumeTask: Task<Void, Never>? {
            get { vodAsyncRuntime.automaticResumeTask }
            nonmutating set { vodAsyncRuntime.automaticResumeTask = newValue }
        }
    @State private var didApplyAutomaticResumeSeek = false
    // vBRDC073: automatic resume is player-clock confirmed. A seek request is not success;
    // keep retry metadata until the authoritative decoder clock reaches the saved target.
    @State private var automaticResumeSeekAttempts = 0
    @State private var automaticResumeLastSeekRequestAt: Date = .distantPast
    // vBRDC085: protects the short decoder-flush window after resume confirmation from
    // a transient KSPlayer `finish(nil)` callback being mistaken for a real movie ending.
    @State private var automaticResumeConfirmedAt: Date? = nil
    // v1150: while an automatic resume jump is still landing, never let the temporary
    // startup 0:00 clock overwrite the last known-good durable resume checkpoint.
    @State private var resumePersistenceFloorSeconds: Double = 0
    @State private var lastResumeSaveAt: Date = .distantPast
    @FocusState private var focusedControl: PlayerControl?
    @FocusState private var playerCanvasFocused: Bool
    @AppStorage("vodPlaybackDiagnosticsEnabled") private var vodPlaybackDiagnosticsEnabled: Bool = false
    // v1109: a single three-state selector avoids conflicting cast toggles. When
