    private var livePlayerOverrideStorageKey: String {
        "liveTVPlayerOverride::\(livePlayerStableChannelKey)"
    }

    private var livePlayerStableChannelKey: String {
        let payload = store.playbackLinkLabel.components(separatedBy: ": ").last ?? store.playbackLinkLabel
        let parts = payload.components(separatedBy: " • ").map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
        let name = (parts.first ?? item.title).ifEmpty(item.title)
        let tvgID = parts.count > 2 ? parts[2] : ""
        let source = parts.count > 4 ? parts[4] : item.catalog
        let number = parts.count > 5 ? parts[5] : ""
        let identity = tvgID.isEmpty || tvgID.lowercased() == "unknown" ? "\(number)::\(name)" : tvgID
        return "\(source)::\(identity)"
            .lowercased()
            .replacingOccurrences(of: "|", with: "_")
            .replacingOccurrences(of: "\n", with: " ")
    }

    private var livePlayerOverride: String {
        get { UserDefaults.standard.string(forKey: livePlayerOverrideStorageKey) ?? "auto" }
        nonmutating set {
            if newValue == "auto" {
                UserDefaults.standard.removeObject(forKey: livePlayerOverrideStorageKey)
            } else {
                UserDefaults.standard.set(newValue, forKey: livePlayerOverrideStorageKey)
            }
        }
    }

    private var liveTimingDebugInfo: LiveTimingDebugInfo? {
        guard isLivePlayback else { return nil }
        let lowerURL = url.absoluteString.lowercased()
        let lowerRouteHint = store.playbackLinkLabel.lowercased()
        let timingRiskHaystack = lowerURL + " " + lowerRouteHint
        let hasCBSMetadataSignal =
            timingRiskHaystack.contains("cbs") ||
            timingRiskHaystack.contains("paramount") ||
            timingRiskHaystack.contains("wcbs") ||
            timingRiskHaystack.contains("kcbs") ||
            timingRiskHaystack.contains("wbbm") ||
            timingRiskHaystack.contains("wkyc")
        let hasLiveRemuxTimingSignal =
            timingRiskHaystack.contains("/devices/") ||
            timingRiskHaystack.contains("channels.m3u") ||
            timingRiskHaystack.contains("/hls/") ||
            timingRiskHaystack.contains("/dvr/") ||
            timingRiskHaystack.contains("format=ts") ||
            timingRiskHaystack.contains(".m3u8") ||
            timingRiskHaystack.contains(".mpg") ||
            timingRiskHaystack.contains("tve") ||
            timingRiskHaystack.contains("channels dvr") ||
            timingRiskHaystack.contains("verizon") ||
            timingRiskHaystack.contains("live tv direct stream") ||
            timingRiskHaystack.contains("ks live tv route")
        let timingRiskActive = hasCBSMetadataSignal && hasLiveRemuxTimingSignal
        guard hasCBSMetadataSignal || timingRiskActive else { return nil }
        let diagnostics = currentPlaybackDiagnostics()
        let cbsProfileActive = liveTimingCBSProfileField(named: "CBS profile active")
        let hlsRewriteSucceeded = liveTimingCBSProfileField(named: "hlsURL rewrite succeeded")
        let originalURLType = liveTimingCBSProfileField(named: "original URL type")
        let finalURLType = liveTimingCBSProfileField(named: "final URL type")
        return LiveTimingDebugInfo(
            timingRiskActive: timingRiskActive,
            channelName: item.title.ifEmpty("Unknown"),
            tvgID: liveTimingDebugTVGID,
            source: item.catalog.ifEmpty("Unknown"),
            streamURLType: liveTimingDebugURLType(for: url),
            cbsMetadataSignal: liveTimingCBSProfileField(named: "CBS metadata signal", fallback: "\(hasCBSMetadataSignal)"),
            channelsTimingRiskSignal: liveTimingCBSProfileField(named: "Channels timing-risk signal", fallback: "\(hasLiveRemuxTimingSignal)"),
            cbsProfileActive: cbsProfileActive == "unavailable" ? "false" : cbsProfileActive,
            hlsRewriteSucceeded: hlsRewriteSucceeded == "unavailable" ? "false" : hlsRewriteSucceeded,
            cbsOriginalURLType: originalURLType == "unavailable" ? LiveTVCBSChannelsDVRProfile.urlType(for: url) : originalURLType,
            cbsFinalURLType: finalURLType == "unavailable" ? LiveTVCBSChannelsDVRProfile.urlType(for: url) : finalURLType,
            backend: activeEngineName,
            profile: timingRiskActive
                ? "buffer=8 max=12 analyze=3000000 probe=1048576 sync=ext fflags=+genpts flags=<empty> cache=1500 max_delay=700000"
                : "buffer=0 max=3 analyze=100000 probe=16384 sync=audio fflags=nobuffer flags=low_delay cache=0 max_delay=100000",
            videoCodec: diagnostics.videoCodec.ifEmpty("unavailable"),
            audioCodec: diagnostics.audioCodec.ifEmpty("unavailable"),
            audioChannels: diagnostics.audioChannels.ifEmpty("unavailable"),
            sampleRate: diagnostics.sampleRate.ifEmpty("unavailable"),
            scanType: diagnostics.scanType.ifEmpty("unavailable"),
            avDrift: liveTimingDebugDriftText(diagnostics.avDrift),
            cbsProfileDebugLine: liveTimingCBSProfileDebugLine(finalURL: url, backend: activeEngineName)
        )
    }

    private func liveTimingCBSProfileDebugLine(finalURL: URL, backend: String) -> String {
        let label = store.playbackLinkLabel
        guard let range = label.range(of: "CBS metadata signal:") ?? label.range(of: "CBS profile active:") else {
            return "CBS metadata signal: unavailable • Channels timing-risk signal: unavailable • CBS profile active: false • hlsURL rewrite succeeded: false • original URL type: unavailable • rewritten URL type: unavailable • final URL type: \(LiveTVCBSChannelsDVRProfile.urlType(for: finalURL)) • player route used: \(backend)"
        }
        return "\(label[range.lowerBound...]) • player route used: \(backend)"
    }

    private func liveTimingCBSProfileField(named name: String) -> String {
        liveTimingCBSProfileField(named: name, fallback: "unavailable")
    }

    private func liveTimingCBSProfileField(named name: String, fallback: String) -> String {
        let prefix = "\(name): "
        guard let range = store.playbackLinkLabel.range(of: prefix) else { return fallback }
        let tail = store.playbackLinkLabel[range.upperBound...]
        return String(tail).components(separatedBy: " • ").first?.trimmingCharacters(in: .whitespacesAndNewlines) ?? fallback
    }

    private func liveTimingDebugDriftText(_ raw: String) -> String {
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        if trimmed.isEmpty || trimmed.lowercased() == "measuring" { return "unavailable" }
        return trimmed
    }

    private var liveTimingDebugTVGID: String {
        let payload = store.playbackLinkLabel.components(separatedBy: ": ").last ?? store.playbackLinkLabel
        let parts = payload.components(separatedBy: " • ").map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
        guard parts.count > 2, !parts[2].isEmpty else { return "Unknown" }
        return parts[2]
    }

    private func liveTimingDebugURLType(for url: URL) -> String {
        let value = url.absoluteString.lowercased()
        if value.contains("/devices/") && value.contains("/stream.mpg") { return "Channels DVR stream.mpg MPEG-TS" }
        if value.contains("format=ts") || value.hasSuffix(".ts") || value.contains(".mpg") { return "MPEG-TS/remux" }
        if value.contains(".m3u8") || value.contains("/hls/") { return "HLS" }
        if value.contains("/live/") { return "Xtream live" }
        return "Direct URL"
    }

    private var overlayItem: MediaItem {
        // vBRDC158: playback metadata may arrive in several waves. Always merge the
        // current wave through CatalogStore's durable artwork memory so a Search/Favorites
        // clearlogo cannot blink out when a later cast/credits object is published.
        store.presentationArtworkRestoredItem(from: playbackMetadataItem ?? item)
    }

    private var vodCommunityScoreText: String? {
        let clean = overlayItem.rating
            .replacingOccurrences(of: "★", with: "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        guard !clean.isEmpty, clean.lowercased() != "n/a", clean != "0", clean != "0.0" else { return nil }
        return clean
    }

    private func loadVODReviewScore(
        for sourceItem: MediaItem,
        delayNanoseconds: UInt64 = 0,
        force: Bool = false
    ) {
        guard !isLivePlayback, isFirstFrameReady, controlsVisible, activePanel == nil else { return }
        let sourceID = sourceItem.id
        if !force, vodReviewResolvedItemID == sourceID { return }
        vodReviewTask?.cancel()
        vodReviewTask = nil
        vodRottenTomatoesScore = nil

        let presentationID = playbackPresentationID
        let imdbID = sourceItem.imdbId?.trimmingCharacters(in: .whitespacesAndNewlines)
        let title = sourceItem.title
        let year = sourceItem.year
        let tmdbID = sourceItem.tmdbId
        let type = sourceItem.type
        vodReviewTask = Task(priority: .background) {
            if delayNanoseconds > 0 {
                try? await Task.sleep(nanoseconds: delayNanoseconds)
            }
            guard !Task.isCancelled else { return }
            let stillStable = await MainActor.run {
                isFirstFrameReady
                    && controlsVisible
                    && activePanel == nil
                    && store.playbackPresentationID == presentationID
                    && overlayItem.id == sourceID
            }
            guard stillStable else { return }
            let score = await RottenTomatoesScoreCache.fetchScore(
                imdbID: imdbID,
                title: title,
                year: year,
                tmdbID: tmdbID,
                itemID: sourceID,
                type: type
            )
            guard !Task.isCancelled else { return }
            await MainActor.run {
                guard controlsVisible, activePanel == nil,
                      store.playbackPresentationID == presentationID, overlayItem.id == sourceID else { return }
                vodRottenTomatoesScore = score
                vodReviewResolvedItemID = sourceID
                vodReviewTask = nil
            }
        }
    }


    private var vodSupplementalInfoPanelEnabled: Bool {
        !isLivePlayback && (vodProductionRatingsPanelEnabled || vodSpotlightHubPanelEnabled)
    }

    private func loadVODProductionMetadata(
        for sourceItem: MediaItem,
        delayNanoseconds: UInt64 = 0,
        force: Bool = false
    ) {
        // vBRDC162: overlay hydration is single-flight. Repeated first-frame, overlay-open,
        // and metadata-enrichment signals used to cancel/restart the same Production request,
        // which could leave the first visible overlay empty until it was closed and reopened.
        guard vodSupplementalInfoPanelEnabled,
              isFirstFrameReady else { return }

        let sourceID = sourceItem.id
        if !force,
           (vodProductionMetadataItemID == sourceID && vodProductionMetadata.hasUsefulContent)
            || (pendingVODProductionMetadataItemID == sourceID && pendingVODProductionMetadata?.hasUsefulContent == true) {
            return
        }
        if !force, vodProductionMetadataTask != nil { return }
        if force {
            vodProductionMetadataTask?.cancel()
            vodProductionMetadataTask = nil
        }

        // vBRDC085: Production information is session metadata, not a pause-only action.
        // Fetch it once after first frame on a background-priority task so the panel is
        // already complete whenever the overlay is opened. Review/runtime enrichment can
        // remain pause-time work; Production must never depend on the Play/Pause button.
        let presentationID = playbackPresentationID
        let key = vodTMDBApiKey
        vodAsyncRuntime.vodProductionMetadataGeneration &+= 1
        let requestGeneration = vodAsyncRuntime.vodProductionMetadataGeneration
        vodProductionMetadataTask = Task(priority: .background) { @MainActor in
            defer {
                if vodAsyncRuntime.vodProductionMetadataGeneration == requestGeneration {
                    vodProductionMetadataTask = nil
                }
            }
            if delayNanoseconds > 0 {
                try? await Task.sleep(nanoseconds: delayNanoseconds)
            }
            guard !Task.isCancelled,
                  vodAsyncRuntime.vodProductionMetadataGeneration == requestGeneration,
                  isFirstFrameReady,
                  store.playbackPresentationID == presentationID,
                  overlayItem.id == sourceID,
                  vodSupplementalInfoPanelEnabled else { return }

            let snapshot = await VODProductionMetadataService.fetch(
                itemID: sourceItem.id,
                tmdbID: sourceItem.tmdbId,
                imdbID: sourceItem.imdbId,
                title: sourceItem.title,
                year: sourceItem.year,
                type: sourceItem.type,
                seasonNumber: sourceItem.seasonNumber,
                episodeNumber: sourceItem.episodeNumber,
                apiKey: key,
                includeSpotlight: vodSpotlightHubPanelEnabled
            )
            guard !Task.isCancelled,
                  vodAsyncRuntime.vodProductionMetadataGeneration == requestGeneration,
                  isFirstFrameReady,
                  vodSupplementalInfoPanelEnabled,
                  store.playbackPresentationID == presentationID,
                  overlayItem.id == sourceID else { return }
            if controlsVisible || activePanel != nil {
                vodProductionMetadata = snapshot
                vodProductionMetadataItemID = sourceID
                pendingVODProductionMetadata = nil
                pendingVODProductionMetadataItemID = nil
            } else {
                // Do not publish into SwiftUI while a movie/show owns the full frame budget.
                pendingVODProductionMetadata = snapshot
                pendingVODProductionMetadataItemID = sourceID
            }
        }
    }

    private func commitPendingVODProductionMetadataIfVisible() {
        guard controlsVisible || activePanel != nil,
              let pending = pendingVODProductionMetadata,
              let sourceID = pendingVODProductionMetadataItemID,
              sourceID == overlayItem.id,
              store.playbackPresentationID == playbackPresentationID else { return }
        pendingVODProductionMetadata = nil
        pendingVODProductionMetadataItemID = nil
        vodProductionMetadata = pending
        vodProductionMetadataItemID = sourceID
    }

    private func showVODCastExplorerOnboardingIfNeeded() {
        guard !isLivePlayback,
              !vodCastExplorerOnboardingSeen,
              vodFeaturedCastPresentationMode != .off else { return }
        let hasCast = !overlayItem.castMembers.isEmpty || !overlayItem.cast.isEmpty
        guard hasCast else { return }
        // Mark as seen as soon as the successful VOD presentation actually displays it.
        // This prevents a force-close during the 30-second window from replaying it forever.
        vodCastExplorerOnboardingSeen = true
        vodCastExplorerOnboardingTask?.cancel()
        hideTask?.cancel()
        vodCastExplorerOnboardingVisible = true
        withAnimation(.easeInOut(duration: 0.18)) { controlsVisible = true }

        vodCastExplorerOnboardingTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: 30_000_000_000)
            guard !Task.isCancelled else { return }
            withAnimation(.easeInOut(duration: 0.24)) {
                vodCastExplorerOnboardingVisible = false
            }
            vodCastExplorerOnboardingTask = nil
            scheduleOverlayAutoHideIfAllowed()
        }
    }

    private func cancelVODCastExplorerOnboarding() {
        vodCastExplorerOnboardingTask?.cancel()
        vodCastExplorerOnboardingTask = nil
        vodCastExplorerOnboardingVisible = false
    }

    private func openCastExplorer(_ member: CastMember) {
        guard !isLivePlayback, isFirstFrameReady, controlsVisible else { return }
        // vBRDC122: Cast Explorer becomes the visible playback surface. Retire any
        // pre-existing VOD chrome auto-hide owner before its artwork requests begin.
        hideTask?.cancel()
        hideTask = nil
        castExplorerShouldResumePlayback = isPlaying
        if isPlaying { togglePlay() }
        castExplorerTask?.cancel()
        castExplorerTask = nil
        castExplorerMember = member
        castExplorerSnapshot = nil
        castExplorerError = nil
        castExplorerLoading = true
        vodControlShelfHideTask?.cancel()
        vodControlShelfHideTask = nil
        vodOverlayLockedForRemoteNavigation = true
        vodReviewTask?.cancel()
        vodReviewTask = nil
        vodProductionMetadataTask?.cancel()
        vodProductionMetadataTask = nil

        let ownerPresentationID = playbackPresentationID
        let ownerItem = overlayItem
        let apiKey = vodTMDBApiKey
        let memberID = member.id
        castExplorerTask = Task(priority: .userInitiated) {
            let snapshot = await CastExplorerRepository.shared.snapshot(
                for: member,
                currentItem: ownerItem,
                tmdbAPIKey: apiKey
            )
            guard !Task.isCancelled else { return }
            await MainActor.run {
                guard store.playbackPresentationID == ownerPresentationID,
                      castExplorerMember?.id == memberID else { return }
                castExplorerSnapshot = snapshot
                castExplorerLoading = false
                castExplorerTask = nil
                if snapshot == nil {
                    castExplorerError = apiKey.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                        ? "Add your TMDB API key for film and TV credits. Open Wikidata facts will appear when an exact person match is available."
                        : "No verified person details were available for this cast member."
                }
            }
        }
    }

    private func closeCastExplorer() {
        let shouldResumePlayback = castExplorerShouldResumePlayback
        castExplorerShouldResumePlayback = false
        castExplorerTask?.cancel()
        castExplorerTask = nil
        castExplorerMember = nil
        castExplorerSnapshot = nil
        castExplorerLoading = false
        castExplorerError = nil
        PremiumRemoteImageLoader.releaseDecodedArtworkForHiddenVODOverlay()
        vodOverlayLockedForRemoteNavigation = controlsVisible
        if controlsVisible && isFirstFrameReady && activePanel == nil {
            loadVODReviewScore(for: overlayItem, delayNanoseconds: 180_000_000)
            if vodSupplementalInfoPanelEnabled {
                loadVODProductionMetadata(for: overlayItem, delayNanoseconds: 260_000_000)
            }
        }
        if shouldResumePlayback && !isPlaying { togglePlay() }
    }

    private func handleCastExplorerCreditSelected(_ credit: CastExplorerCredit) {
        let target = credit.mediaItem
        if target.id == item.id {
            playbackNotice = "This title is already playing."
            store.status = playbackNotice
            return
        }
        requestVODPlaybackSwitch(
            to: target,
            context: "Selected from \(castExplorerMember?.name ?? "Cast Explorer") credits"
        )
    }

    private func phase15SeriesBrowserTitle(_ source: MediaItem) -> String {
        var value = source.title.trimmingCharacters(in: .whitespacesAndNewlines)
        for pattern in [
            #"\s+[sS]\d{1,2}[eE]\d{1,3}.*$"#,
            #"\s+[sS]eason\s*\d{1,2}.*$"#,
            #"\s+\d{1,2}x\d{1,3}.*$"#
        ] {
            value = value.replacingOccurrences(of: pattern, with: "", options: .regularExpression)
        }
        let clean = value.trimmingCharacters(in: .whitespacesAndNewlines)
        return clean.isEmpty ? source.title : clean
    }

    private func openVODEpisodeBrowser() {
        guard !isLivePlayback, isSeriesPlayback else {
            playbackNotice = "Full episode search is available for TV series playback."
            store.status = playbackNotice
            return
        }
        activePanel = nil
        selectedPanelOption = nil
        focusedPanelOption = nil
        vodEpisodeBrowserShouldResumePlayback = isPlaying
        if isPlaying { togglePlay() }
        vodEpisodeBrowserVisible = true
        vodEpisodeBrowserSeriesTitle = phase15SeriesBrowserTitle(overlayItem)
        vodEpisodeBrowserItems = []
        vodEpisodeBrowserError = nil
        vodEpisodeBrowserLoading = true
        vodOverlayLockedForRemoteNavigation = true
        vodEpisodeBrowserTask?.cancel()

        let ownerPresentationID = playbackPresentationID
        let ownerURL = url
        let ownerItem = item
        vodEpisodeBrowserTask = Task(priority: .userInitiated) {
            let episodes = await store.fetchSeriesEpisodes(for: ownerItem, publishStatus: false)
            guard !Task.isCancelled else { return }
            await MainActor.run {
                guard store.playbackPresentationID == ownerPresentationID,
                      store.playbackURL == ownerURL,
                      vodEpisodeBrowserVisible else { return }
                vodEpisodeBrowserItems = episodes
                vodEpisodeBrowserLoading = false
                vodEpisodeBrowserTask = nil
                if episodes.isEmpty {
                    vodEpisodeBrowserError = "No verified complete episode inventory was returned from the series metadata fallbacks. Try again after confirming network access."
                }
            }
        }
