    private func closeVODEpisodeBrowser() {
        let shouldResumePlayback = vodEpisodeBrowserShouldResumePlayback
        vodEpisodeBrowserShouldResumePlayback = false
        vodEpisodeBrowserTask?.cancel()
        vodEpisodeBrowserTask = nil
        vodEpisodeBrowserVisible = false
        vodEpisodeBrowserSeriesTitle = ""
        vodEpisodeBrowserItems = []
        vodEpisodeBrowserLoading = false
        vodEpisodeBrowserError = nil
        vodOverlayLockedForRemoteNavigation = controlsVisible
        if shouldResumePlayback && !isPlaying { togglePlay() }
        if controlsVisible { seedVODOverlayFocusIfNeeded() }
    }

    private func requestVODEpisodeSwitch(_ episode: MediaItem) {
        if episode.id == item.id {
            playbackNotice = "That episode is already playing."
            store.status = playbackNotice
            return
        }
        let code = "S\(episode.seasonNumber ?? 1)E\(episode.episodeNumber ?? 1)"
        requestVODPlaybackSwitch(to: episode, context: "Full Episode Browser • \(code)")
    }

    private func requestVODPlaybackSwitch(to target: MediaItem, context: String) {
        guard !isLivePlayback else { return }
        pendingVODSwitchTask?.cancel()
        pendingVODSwitchTask = nil
        pendingVODSwitchItem = target
        pendingVODSwitchContext = context
        pendingVODSwitchError = nil
        pendingVODSwitchInProgress = false
        pendingVODSwitchSources = []
        pendingVODSwitchResolvedItem = nil
        pendingVODSwitchSourcePickerVisible = false
        if isPlaying { togglePlay() }
        vodOverlayLockedForRemoteNavigation = true
    }

    private func cancelPendingVODPlaybackSwitch() {
        guard !pendingVODSwitchInProgress else { return }
        pendingVODSwitchTask?.cancel()
        pendingVODSwitchTask = nil
        pendingVODSwitchItem = nil
        pendingVODSwitchContext = ""
        pendingVODSwitchError = nil
        pendingVODSwitchSources = []
        pendingVODSwitchResolvedItem = nil
        pendingVODSwitchSourcePickerVisible = false
        if castExplorerMember == nil && !vodEpisodeBrowserVisible {
            vodOverlayLockedForRemoteNavigation = controlsVisible
        }
    }

    private func confirmPendingVODPlaybackSwitch() {
        guard let target = pendingVODSwitchItem,
              !pendingVODSwitchInProgress else { return }
        pendingVODSwitchInProgress = true
        pendingVODSwitchError = nil
        pendingVODSwitchSources = []
        pendingVODSwitchResolvedItem = nil
        pendingVODSwitchSourcePickerVisible = false
        let ownerPresentationID = playbackPresentationID
        let ownerURL = url
        let targetID = target.id
        store.status = "Preparing Source Intelligence for \(target.title)…"

        pendingVODSwitchTask = Task { @MainActor in
            let playbackTarget: MediaItem
            if target.catalog == "Cast Explorer" {
                playbackTarget = await store.resolverReadyStreamItem(
                    for: target,
                    tmdbApiKey: vodTMDBApiKey,
                    publishStatus: false
                )
            } else {
                playbackTarget = target
            }
            guard !Task.isCancelled,
                  store.playbackPresentationID == ownerPresentationID,
                  store.playbackURL == ownerURL,
                  pendingVODSwitchItem?.id == targetID else { return }

            let lowerType = playbackTarget.type.lowercased()
            let isSeriesRoot = playbackTarget.seasonNumber == nil
                && playbackTarget.episodeNumber == nil
                && (lowerType.contains("series") || lowerType.contains("show") || lowerType == "tv")

            // Cast Explorer TV credits represent the series itself, not an arbitrary
            // episode. Resolve the complete real episode list first so the user chooses
            // an exact episode before Source Intelligence searches playable links.
            if isSeriesRoot {
                let episodes = await store.fetchSeriesEpisodes(for: playbackTarget, publishStatus: false)
                guard !Task.isCancelled,
                      store.playbackPresentationID == ownerPresentationID,
                      store.playbackURL == ownerURL,
                      pendingVODSwitchItem?.id == targetID else { return }
                guard !episodes.isEmpty else {
                    pendingVODSwitchInProgress = false
                    pendingVODSwitchTask = nil
                    pendingVODSwitchError = "No complete episode list was available for \(playbackTarget.title). Your current playback remains paused and unchanged."
                    return
                }

                // Transfer pause ownership from Cast Explorer into the episode browser;
                // do not resume the current title between the two full-screen stages.
                let shouldResume = castExplorerShouldResumePlayback || vodEpisodeBrowserShouldResumePlayback
                castExplorerShouldResumePlayback = false
                castExplorerTask?.cancel()
                castExplorerTask = nil
                castExplorerMember = nil
                castExplorerSnapshot = nil
                castExplorerLoading = false
                castExplorerError = nil
                vodEpisodeBrowserShouldResumePlayback = shouldResume
                vodEpisodeBrowserSeriesTitle = playbackTarget.title
                vodEpisodeBrowserItems = episodes
                vodEpisodeBrowserLoading = false
                vodEpisodeBrowserError = nil
                vodEpisodeBrowserVisible = true
                pendingVODSwitchItem = nil
                pendingVODSwitchContext = ""
                pendingVODSwitchInProgress = false
                pendingVODSwitchTask = nil
                store.status = "Loaded \(episodes.count) episode(s) for \(playbackTarget.title). Choose an episode to open Source Intelligence."
                return
            }

            let sources = await store.phase15PreparedSwitchSources(for: playbackTarget)
            guard !Task.isCancelled,
                  store.playbackPresentationID == ownerPresentationID,
                  store.playbackURL == ownerURL,
                  pendingVODSwitchItem?.id == targetID else { return }
            guard !sources.isEmpty else {
                pendingVODSwitchInProgress = false
                pendingVODSwitchTask = nil
                let statusText = store.status.trimmingCharacters(in: .whitespacesAndNewlines)
                pendingVODSwitchError = statusText.isEmpty
                    ? "No direct playable sources were found. Your current playback remains paused and unchanged."
                    : "No direct playable sources: \(statusText)"
                return
            }

            pendingVODSwitchResolvedItem = playbackTarget
            pendingVODSwitchSources = sources
            pendingVODSwitchSourcePickerVisible = true
            pendingVODSwitchInProgress = false
            pendingVODSwitchTask = nil
            store.status = "Source Intelligence: \(sources.count) ranked source(s) ready for \(playbackTarget.title)."
        }
    }

    private func selectPendingVODSwitchSource(_ source: StreamLink) {
        guard let target = pendingVODSwitchResolvedItem ?? pendingVODSwitchItem,
              pendingVODSwitchSourcePickerVisible,
              !pendingVODSwitchInProgress else { return }
        pendingVODSwitchInProgress = true
        pendingVODSwitchError = nil
        let ownerPresentationID = playbackPresentationID
        let ownerURL = url
        let targetID = pendingVODSwitchItem?.id
        let ranked = pendingVODSwitchSources

        pendingVODSwitchTask?.cancel()
        pendingVODSwitchTask = Task { @MainActor in
            let opened = await store.playPhase15SelectedDirectStream(
                for: target,
                selected: source,
                rankedLinks: ranked
            )
            guard !Task.isCancelled else { return }
            if opened, store.playbackPresentationID != ownerPresentationID {
                pendingVODSwitchItem = nil
                pendingVODSwitchContext = ""
                pendingVODSwitchError = nil
                pendingVODSwitchSources = []
                pendingVODSwitchResolvedItem = nil
                pendingVODSwitchSourcePickerVisible = false
                pendingVODSwitchInProgress = false
                pendingVODSwitchTask = nil
                return
            }
            guard store.playbackPresentationID == ownerPresentationID,
                  store.playbackURL == ownerURL,
                  pendingVODSwitchItem?.id == targetID else { return }
            pendingVODSwitchInProgress = false
            pendingVODSwitchTask = nil
            let statusText = store.status.trimmingCharacters(in: .whitespacesAndNewlines)
            pendingVODSwitchError = statusText.isEmpty
                ? "That source could not be opened. Choose another ranked source."
                : statusText
        }
    }

    private func applyVODAudioAmplification(_ preset: Phase15AudioAmplificationPreset) {
        guard !isLivePlayback else { return }

        // v1141: audio gain is a live FFmpeg-filter update on the existing KSPNUVIO
        // options object. Never change the URL, playback session, KS surface token,
        // seek serial, first-frame gate, timestamp, or play/pause state merely to alter
        // amplification. This keeps picture and A/V clocks completely continuous.
        vodAudioAmplificationDB = preset.rawValue

        if forceKSPlayerSurface {
            playbackNotice = preset == .off
                ? "Volume Amplification: Off"
                : "Volume Amplification: \(preset.displayName) • applied live"
            store.status = "\(playbackNotice). Playback continues on the existing KSPlayer session; no reload or seek was issued."
            showControlsWithoutChangingFocus()
            return
        }

        if forceAetherSurface, preset != .off {
            // Aether 6.81 exposes transport/track/display control but no public >1.0 audio
            // gain stage, and its native route ultimately hands audio to AVPlayer. Keep the
            // user's timestamp, show the real loading handoff, and move only this session to
            // KSPlayer where the existing FFmpeg volume filter can apply +3/+6/+9/+12 dB.
            let handoffSeconds = captureCurrentVODEngineHandoffPosition()
            playbackNotice = "Volume Amplification: \(preset.displayName) • enabling gain stage…"
            store.status = "\(playbackNotice) Playback position will be preserved."
            switchToKSPlayerEngine(
                manual: false,
                fallbackReason: "Volume amplification requires the KSPlayer FFmpeg gain stage.",
                startAt: handoffSeconds
            )
            return
        }

        playbackNotice = preset == .off
            ? "Volume Amplification: Off"
            : "Volume Amplification: \(preset.displayName) saved • KSPlayer gain stage required"
        store.status = "\(playbackNotice)."
        showControlsWithoutChangingFocus()
    }

    private var authoritativePlaybackSnapshot: PlaybackSnapshot? {
        guard !isLivePlayback,
              (forceAetherSurface || forceKSPlayerSurface),
              let session = PlaybackController.shared.activeSession,
              session.id == playbackPresentationID,
              session.request.url == url else { return nil }
        return session.clock.snapshot
    }

    private var authoritativeCurrentSeconds: Double {
        if let snapshot = authoritativePlaybackSnapshot, snapshot.elapsed.isFinite {
            return max(0, snapshot.elapsed)
        }
        return max(0, currentSeconds)
    }

    /// Player engines can publish coarse/irregular clock samples. Keep the displayed
    /// timeline monotonic between explicit seeks so labels/progress do not visibly jump
    /// ahead by several seconds and then settle back. Engine clocks remain authoritative
    /// for EOF, resume, Trakt and seek decisions; this helper is presentation-only.
    private func stablePresentedPlaybackSecond(_ raw: Double) -> Double {
        guard raw.isFinite else { return lastStablePresentedPlaybackSecond }
        let now = ProcessInfo.processInfo.systemUptime
        if isSeekingInPlayer || isScrubbingTimeline || lastStablePresentedPlaybackUptime == 0 {
            lastStablePresentedPlaybackSecond = max(0, raw)
            lastStablePresentedPlaybackUptime = now
            return lastStablePresentedPlaybackSecond
        }
        let dt = max(0, now - lastStablePresentedPlaybackUptime)
        let expectedAdvance = isPlaying ? dt : 0
        let maxForward = max(1.25, expectedAdvance + 1.25)
        let current = lastStablePresentedPlaybackSecond
        let candidate: Double
        if raw > current + maxForward {
            candidate = current + maxForward
        } else if raw < current - 1.0 && isPlaying {
            candidate = current
        } else {
            candidate = raw
        }
        lastStablePresentedPlaybackSecond = max(0, candidate)
        lastStablePresentedPlaybackUptime = now
        return lastStablePresentedPlaybackSecond
    }

    private var resolvedDurationSeconds: Double {
        let snapshotDuration = authoritativePlaybackSnapshot?.duration ?? 0
        if snapshotDuration.isFinite && snapshotDuration > 1 { return snapshotDuration }
        let playerDuration = durationSeconds.isFinite ? durationSeconds : 0
        if playerDuration > 1 { return playerDuration }
        let savedDuration = resumeEntry?.duration ?? 0
        if savedDuration.isFinite && savedDuration > 1 { return savedDuration }
        let metadataDuration = metadataRuntimeSeconds.isFinite ? metadataRuntimeSeconds : 0
        if metadataDuration > 1 { return metadataDuration }
        return 0
    }

    private var progress: Double {
        let total = resolvedDurationSeconds
        guard total > 0 else { return 0 }
        return min(max(authoritativeCurrentSeconds / total, 0), 1)
    }

    private var remainingSeconds: Double {
        let total = resolvedDurationSeconds
        guard total > 0 else { return 0 }
        return max(total - authoritativeCurrentSeconds, 0)
    }

    private var progressPercentText: String {
        guard resolvedDurationSeconds > 0 else { return "0%" }
        return "\(Int((progress * 100).rounded()))%"
    }

    private var isLivePlayback: Bool {
        item.type.lowercased() == "live" || store.playbackLinkLabel.localizedCaseInsensitiveContains("Live TV")
    }

    private var mediaFlowRouteKind: MediaFlowProxyRouteKind {
        isLivePlayback ? .liveTV : .vod
    }

    private var livePlaybackHTTPHeaders: [String: String] {
        // vBRDC259: preserve every provider-supplied IPTV header exactly, then fill only
        // missing names (case-insensitive) with the same lean request profile that the
        // proven KSPlayer live path uses. v257's broad Accept + forced identity encoding
        // made Aether a different HTTP client from the path that successfully opens these
        // channels. Do not overwrite Referer/Authorization/STB User-Agent values.
        var headers = store.playbackHTTPHeaders
        func containsHeader(_ name: String) -> Bool {
            headers.keys.contains { $0.caseInsensitiveCompare(name) == .orderedSame }
        }
        if !containsHeader("User-Agent") {
            headers["User-Agent"] = "DebridChannels-tvOS/158 KSPlayer"
        }
        if !containsHeader("Accept") {
            headers["Accept"] = "*/*"
        }
        if !containsHeader("Connection") {
            headers["Connection"] = "keep-alive"
        }
        return headers
    }

    private func mediaFlowPlaybackURL(_ sourceURL: URL) -> URL? {
        MediaFlowProxyRouter.playbackURLIfAllowed(
            for: sourceURL,
            kind: mediaFlowRouteKind,
            upstreamHeaders: isLivePlayback ? livePlaybackHTTPHeaders : store.playbackHTTPHeaders
        )
    }

    private var enginePlaybackHTTPHeaders: [String: String] {
        let upstream = isLivePlayback ? livePlaybackHTTPHeaders : store.playbackHTTPHeaders
        return MediaFlowProxyRouter.playerRequestHeaders(
            for: mediaFlowRouteKind,
            upstreamHeaders: upstream
        )
    }

    private var isSeriesPlayback: Bool {
        let type = item.type.lowercased()
        if item.seasonNumber != nil || item.episodeNumber != nil { return true }
        if type.contains("series") || type.contains("show") || type == "tv" || type == "episode" { return true }
        if store.playbackLinkLabel.localizedCaseInsensitiveContains("S0") || store.playbackLinkLabel.localizedCaseInsensitiveContains("Episode") { return true }
        return false
    }


    private var vodOverlayDescriptionText: String {
        let trimmed = overlayItem.description.trimmingCharacters(in: .whitespacesAndNewlines)
        if !trimmed.isEmpty && trimmed.lowercased() != "no description available yet." { return trimmed }
        let genres = overlayItem.genres.filter { !$0.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }.prefix(3).joined(separator: ", ")
        if !genres.isEmpty { return "Metadata is still loading from the selected catalog. Genre: \(genres)." }
        return "Metadata is still loading from the selected catalog. Playback will continue while Debrid Channels refreshes artwork and description data."
    }

    private var activePlaybackURL: URL? {
        guard !isDismissingPlayer else { return nil }
        return preparedPlaybackURL ?? url
    }


    private var sourceQualityLabel: String {
        let label = store.playbackLinkLabel.lowercased()
        if label.contains("4k") || label.contains("2160") { return "4K Direct" }
        if label.contains("1080") { return "HD Direct" }
        if label.contains("cached") || label.contains("debrid") { return "Cache Ready" }
        return "Direct Play"
    }


    private var vodStatusPercentLabel: String {
        guard resolvedDurationSeconds > 0 else { return "0%" }
        // v1145: while the timeline is being preview-scrubbed, the visible playback
        // facts must follow the preview position rather than the last committed player clock.
        return "\(Int(max(0, min(100, (scrubDisplaySeconds / resolvedDurationSeconds) * 100))))%"
    }

    private var vodRemainingLabel: String {
        guard resolvedDurationSeconds > 0 else { return "--:--" }
        // v1145: show the time remaining at the preview target immediately on LEFT/RIGHT.
        return formatTime(max(0, resolvedDurationSeconds - scrubDisplaySeconds))
    }

    private var vodCacheStatusChipLabel: String {
        isLivePlayback ? "Live" : "Direct Stream"
    }

    private var vodSourceInfoChipLabel: String {
        if let summary = store.playbackSourceTrackSummary {
            let parts = [summary.resolution, summary.videoCodec, summary.container, summary.hdrType]
                .compactMap { $0?.trimmingCharacters(in: .whitespacesAndNewlines) }
                .filter { !$0.isEmpty && $0.lowercased() != "unknown" }
                .uniquedPreservingOrder()
            if !parts.isEmpty { return parts.prefix(5).joined(separator: " • ") }
        }
        let label = store.playbackLinkLabel.trimmingCharacters(in: .whitespacesAndNewlines)
        if label.isEmpty { return sourceQualityLabel }
        let parts = label.components(separatedBy: "•").map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }.filter { !$0.isEmpty }
        return parts.suffix(4).joined(separator: " • ").ifEmpty(sourceQualityLabel)
    }

    private var loadingMessage: String {
        isLivePlayback ? "Loading Stream..." : "Preparing Playback..."
    }

    private func playbackSurfaceLayer(_ activePlaybackURL: URL?) -> AnyView {
        guard let activePlaybackURL else {
            return AnyView(Color.black.ignoresSafeArea())
        }
        guard let enginePlaybackURL = mediaFlowPlaybackURL(activePlaybackURL) else {
            // vBRDC016 fail-closed invariant: when MediaFlow is enabled but not fully
            // configured, never leak playback through the Apple TV's direct public IP.
            return AnyView(Color.black.ignoresSafeArea())
        }

        // Phase 4: closures are bound to the exact source generation that created this
        // render surface. A stopped outgoing layer may drain callbacks after the new
        // bridge/original layer is already active, so URL + reload-token ownership is
        // checked before any clock, track, or failure state is published.
        let ownedKSSurfaceToken = ksSurfaceToken
        let ownedPlaybackURL = activePlaybackURL

        let surface = AnyView(
            UniversalVideoSurface(
                url: enginePlaybackURL,
                avPlayer: player,
                videoFitMode: isLivePlayback ? .fit : vodVideoFitMode,
                forceVLC: forceVLCSurface,
                routeHint: [store.playbackLinkLabel, store.playbackAdaptiveCacheHint, vodSourceInfoChipLabel].filter { !$0.isEmpty }.joined(separator: " | "),
                vlcShouldPlay: isPlaying,
                vlcSeekSerial: vlcSeekSerial,
                vlcSeekSeconds: vlcSeekSeconds,
                vlcSurfaceToken: vlcSurfaceToken,
                ksShouldPlay: isPlaying,
                ksPlayAssertionSerial: ksPlayAssertionSerial,
                ksSeekSerial: ksSeekSerial,
                ksSeekSeconds: ksSeekSeconds,
                ksReloadToken: ksSurfaceToken,
                ksStartTimeSeconds: ksStartTimeSeconds,
                ksSeekIsAbsolute: ksSeekIsAbsolute,
                preferAetherEngine: forceAetherSurface && localAlternateAudioURL == nil,
                preferKSPlayer: forceKSPlayerSurface || (forceAetherSurface && localAlternateAudioURL != nil),
                preferAVFoundation: !usingInternalNonAVEngine,
                isLiveStream: isLivePlayback,
                playbackSessionID: isLivePlayback ? nil : playbackPresentationID,
                httpHeaders: enginePlaybackHTTPHeaders,
                // vBRDC160: the original video URL remains the primary player forever.
                // A selected alternate copy is opened as an audio-only local KSPlayer layer.
                externalAudioURL: isLivePlayback ? nil : localAlternateAudioURL,
                externalAudioOffsetMS: isLivePlayback ? 0 : store.alternateAudioSyncOffsetMS,
                externalAudioTrackIndex: isLivePlayback ? nil : localAlternateAudioTrackIndex,
                externalAudioHTTPHeaders: isLivePlayback ? [:] : localAlternateAudioHTTPHeaders,
                onKSExternalAudioReady: {
                    guard !isLivePlayback,
                          store.playbackPresentationID == playbackPresentationID,
                          store.playbackURL == url,
                          ownedKSSurfaceToken == ksSurfaceToken,
                          localAlternateAudioURL != nil else { return }
                    alternateAudioHandoffRecoveryTask?.cancel()
                    alternateAudioHandoffRecoveryTask = nil
                    alternateAudioHandoffState = .active
                    selectedAudioMode = "Alternate English"
                    playbackNotice = "Alternate English audio active • local sync \(store.alternateAudioSyncOffsetMS)ms"
                    store.status = playbackNotice
                    showControlsWithoutChangingFocus()
                },
                onKSExternalAudioFailure: { message in
                    guard !isLivePlayback,
                          store.playbackPresentationID == playbackPresentationID,
                          store.playbackURL == url,
                          ownedKSSurfaceToken == ksSurfaceToken,
                          localAlternateAudioURL != nil else { return }
                    store.recordAlternateAudioFailure("Local Alternate Audio failed: \(message)")
                    alternateAudioHandoffState = .failed
                    if !tryNextAlternateAudioCandidateAfterFailure(message: message) {
                        restoreOriginalAudio(
                            reason: "Alternate Audio failed (\(message)) — original audio restored.",
                            clearSelection: false
                        )
                    }
                },
                // v1073: display matching remains a VOD-only PlaybackKit behavior.
                // The retired Live TV display-match setting is no longer consulted.
                enableDisplayMatch: (forceAetherSurface || forceKSPlayerSurface) && !isLivePlayback,
                displayMatchIsLive: isLivePlayback,
                hardwareAcceleration: .auto,
                ksSelectedAudioTrackIndex: ksSelectedAudioTrackIndex,
                ksSelectedSubtitleTrackIndex: ksSelectedSubtitleTrackIndex,
                ksSelectedExternalSubtitleURL: ksSelectedExternalSubtitleURL,
                ksSubtitleDelayMS: subtitleDelayMS,
                ksTrackSelectionSerial: ksTrackSelectionSerial,
                ksAudioGainDB: isLivePlayback ? 0 : vodAudioAmplificationPreset.rawValue,
                aetherSelectedAudioTrackID: aetherSelectedAudioTrackID,
                aetherSelectedSubtitleTrackID: aetherSelectedSubtitleTrackID,
                aetherTrackSelectionSerial: aetherTrackSelectionSerial,
                onPlaybackTimeUpdate: { current, total in
                    guard store.playbackPresentationID == playbackPresentationID,
                          store.playbackURL == url,
                          ownedKSSurfaceToken == ksSurfaceToken,
                          self.activePlaybackURL == ownedPlaybackURL else { return }
                    handleAlternateAudioPlaybackClock(
                        current: current,
                        total: total,
                        surfaceToken: ownedKSSurfaceToken,
                        sourceURL: ownedPlaybackURL
                    )
                    if isLivePlayback {
                        // KSPlayer historically has no explicit ready-for-display callback, so its
                        // authoritative clock remains the release signal. Aether DOES expose
                        // hasFirstFrameReadyForDisplay and must use that signal exclusively: its
                        // clock/session can advance while AVPlayer is still black or waiting.
                        if !forceAetherSurface && !isFirstFrameReady {
                            markFirstFrameReady(engine: "Live TV", reason: "KSPlayer clock callback")
                        }
                        return
                    }
                    // vBRDC073: a real KSPlayer callback proves the active surface exists.
                    // Use that callback to issue/confirm the in-place automatic resume seek;
                    // never recreate the surface just to resume.
                    reconcileAutomaticResumePlaybackClock(current: current)
                    // v996: PlaybackKit's session clock is the sole VOD timeline authority.
                    // The overlay receives throttled snapshots from OverlayBridge instead of
                    // mutating a second local clock directly from decoder callbacks.
                    PlaybackController.shared.ingestClock(
                        sessionID: playbackPresentationID,
                        elapsed: current.isFinite ? max(0, current) : 0,
                        duration: total.isFinite ? max(0, total) : 0,
                        isPlaying: isPlaying
                    )
                    // vBRDC135: keep the invisible Bluetooth/Now Playing owner current from
                    // the authoritative decoder clock even while VOD chrome is hidden. The
                    // coordinator publishes to MPNowPlayingInfoCenter only on state changes or
                    // ~5-second elapsed deltas, so this adds no SwiftUI clock lane.
                    BluetoothVODMediaButtonCoordinator.shared.updateNowPlaying(
                        sessionID: playbackPresentationID,
                        title: item.title,
                        duration: total,
                        elapsed: current,
                        isPlaying: isPlaying
                    )
                    // v1150 durable resume: KSPlayer is the production VOD engine, so its
                    // real decoder clock must checkpoint progress during playback instead of
                    // relying on VOD-screen teardown. saveResumePositionIfNeeded keeps the
                    // existing 5-second throttle and protects a pending resume target from
                    // being replaced by the temporary startup clock.
                    saveResumePositionIfNeeded()
                    if current.isFinite, current > 0.01 {
                        markStableFirstFrameReady(engine: "Playback", reason: "authoritative player clock")
                    }
                },
                onAetherFirstFrameReady: {
                    guard forceAetherSurface,
                          store.playbackPresentationID == playbackPresentationID,
                          store.playbackURL == url,
                          ownedKSSurfaceToken == ksSurfaceToken,
                          self.activePlaybackURL == ownedPlaybackURL else { return }
                    markStableFirstFrameReady(engine: "AetherEngine", reason: "renderer ready-for-display callback")
                    // vBRDC267: Aether can produce a valid first frame before an early
                    // startup clock sample drives the shared resume reconciler. Reconcile
                    // once at the authoritative renderer-ready edge so a saved checkpoint
                    // cannot silently be skipped just because the initial decoder clock was
                    // late. The shared seek serial still owns the seek and remains bounded.
                    if !isLivePlayback,
                       let target = pendingAutomaticResumeSeconds,
                       target >= 8,
                       authoritativeCurrentSeconds + 4 < target {
                        requestAutomaticResumeSeek(target, minimumInterval: 0.25)
                    }
                },
                onAetherBufferingChanged: { buffering in
                    guard forceAetherSurface,
                          store.playbackPresentationID == playbackPresentationID,
                          store.playbackURL == url,
                          ownedKSSurfaceToken == ksSurfaceToken,
                          self.activePlaybackURL == ownedPlaybackURL else { return }
                    // Live TV does not own the VOD PlaybackKit session clock. Publishing its
                    // transient buffer state into a non-owned VOD session creates needless
                    // MainActor/session churn while channel playback is starting.
                    if !isLivePlayback {
                        PlaybackController.shared.setBuffering(buffering, sessionID: playbackPresentationID)
                    }
                },
                onAetherPlaybackFailure: { message in
                    guard forceAetherSurface,
                          store.playbackPresentationID == playbackPresentationID,
                          store.playbackURL == url,
                          ownedKSSurfaceToken == ksSurfaceToken,
                          self.activePlaybackURL == ownedPlaybackURL else { return }
                    let resumeAt = isLivePlayback ? nil : authoritativeCurrentSeconds
                    playbackNotice = "AetherEngine compatibility fallback → KSPlayer"
                    store.status = "AetherEngine could not continue this source; handing the same source to KSPlayer."
                    switchToKSPlayerEngine(manual: false, fallbackReason: "AetherEngine: \(message)", startAt: resumeAt)
                },
                onAetherPlaybackEnded: {
                    guard forceAetherSurface,
                          store.playbackPresentationID == playbackPresentationID,
                          store.playbackURL == url,
                          ownedKSSurfaceToken == ksSurfaceToken,
                          self.activePlaybackURL == ownedPlaybackURL,
                          !isLivePlayback else { return }
                    if isSeriesPlayback {
                        // vBRDC280: Aether EOF must enter the same decoder-safe Up Next lane
                        // even if SwiftUI's isPlaying value was already false before the
                        // completion callback. Calling the scheduler directly makes the
                        // transition independent of an onChange edge while preserving the
                        // 300 ms decoder-settle window inside schedulePostEOFUpNextWork().
                        handleNaturalEpisodeEnd(reason: "AetherEngine natural completion")
                        isPlaying = false
                        schedulePostEOFUpNextWork()
                    } else {
                        isPlaying = false
                        TraktSyncManager.shared.markCompleted(item: item, duration: resolvedDurationSeconds)
                        PlaybackResumeCacheManager.shared.clear(for: item)
                        controlsVisible = true
                        focusedControl = .playPause
                    }
                },
                onAetherRouteChanged: { route in
                    guard forceAetherSurface,
                          store.playbackPresentationID == playbackPresentationID,
                          store.playbackURL == url,
                          ownedKSSurfaceToken == ksSurfaceToken,
                          self.activePlaybackURL == ownedPlaybackURL else { return }
                    if isLivePlayback {
                        store.status = "Aether Live TV • \(route)"
                    }
                },
                onAetherTracksDiscovered: { audio, subtitles in
                    guard forceAetherSurface,
                          store.playbackPresentationID == playbackPresentationID,
                          store.playbackURL == url,
                          ownedKSSurfaceToken == ksSurfaceToken,
                          self.activePlaybackURL == ownedPlaybackURL else { return }
                    updateAetherEmbeddedTracks(audio: audio, subtitles: subtitles)
                },
                onAetherSubtitleTextChanged: { text in
                    guard forceAetherSurface,
                          store.playbackPresentationID == playbackPresentationID,
                          store.playbackURL == url,
                          ownedKSSurfaceToken == ksSurfaceToken,
                          self.activePlaybackURL == ownedPlaybackURL else { return }
                    aetherSubtitleText = text
                },
                onKSBufferUpdate: { playable, total in
                    guard !isLivePlayback,
                          store.playbackPresentationID == playbackPresentationID,
                          store.playbackURL == url,
                          ownedKSSurfaceToken == ksSurfaceToken,
                          self.activePlaybackURL == ownedPlaybackURL else { return }
                    // vBRDC200 Playback Priority: keep a raw, non-published playable endpoint
                    // for buffer-aware Up Next scheduling even while chrome is hidden. Only the
                    // visible scrubber mirrors this value into SwiftUI state.
                    let current = authoritativeCurrentSeconds
                    let safePlayable = playable.isFinite ? max(current, playable) : current
                    let safeTotal = total.isFinite ? max(0, total) : resolvedDurationSeconds
                    let normalizedPlayable = safeTotal > 0
                        ? min(max(0, safePlayable), safeTotal)
                        : max(0, safePlayable)
                    vodAsyncRuntime.latestBufferedPlaybackSeconds = normalizedPlayable
                    guard controlsVisible || activePanel != nil || isScrubbingTimeline || isSeekingInPlayer else { return }
                    bufferedPlaybackSeconds = normalizedPlayable
                },
                onKSTracksDiscovered: { audio, subtitles in
                    guard store.playbackPresentationID == playbackPresentationID,
                          store.playbackURL == url,
                          ownedKSSurfaceToken == ksSurfaceToken,
                          self.activePlaybackURL == ownedPlaybackURL else { return }
                    updateKSEmbeddedTracks(audio: audio, subtitles: subtitles)
                },
                onKSPlaybackFailure: { message in
                    guard store.playbackPresentationID == playbackPresentationID,
                          store.playbackURL == url,
                          ownedKSSurfaceToken == ksSurfaceToken,
                          self.activePlaybackURL == ownedPlaybackURL else { return }
                    if handleAlternateAudioPlaybackFailure(
                        message: message,
                        surfaceToken: ownedKSSurfaceToken,
                        sourceURL: ownedPlaybackURL
                    ) { return }
                    if attemptAutomaticSourceFailover(message: message, failedURL: ownedPlaybackURL) { return }
                    publishPlaybackFailureWithoutFailover(message, engine: "KSPlayer")
                },
                onKSPlaybackEnded: {
                    guard store.playbackPresentationID == playbackPresentationID,
                          store.playbackURL == url,
                          ownedKSSurfaceToken == ksSurfaceToken,
                          self.activePlaybackURL == ownedPlaybackURL,
                          !isLivePlayback else { return }

                    // vBRDC085: KSPNUVIO can emit a transient finish(nil) while its
                    // decoder is flushing an automatic-resume seek. On physical Apple TV
                    // that callback was flipping `isPlaying` false after the correct saved
                    // position had already landed, which is why Find Links required a second
                    // Siri Remote Play press. Only suppress that callback inside the short
                    // confirmed-resume window and only when the clock is not genuinely near EOF.
                    if isPlaying,
                       let confirmedAt = automaticResumeConfirmedAt,
                       Date().timeIntervalSince(confirmedAt) < 8.0 {
                        let elapsed = authoritativeCurrentSeconds
                        let total = resolvedDurationSeconds
                        let nearNaturalEnd = total > 20 && elapsed >= max(0, total - max(8, min(20, total * 0.01)))
                        if !nearNaturalEnd {
                            isPlaying = true
                            ksPlayAssertionSerial &+= 1
                            store.status = "Automatic resume decoder flush completed; playback continuing."
                            return
                        }
                    }

                    if isSeriesPlayback {
                        // vBRDC206: classify natural EOF before changing isPlaying. Otherwise
                        // the generic pause observer performs durable resume/Trakt/catalog work
                        // while Up Next is simultaneously resolving/starting the next decoder.
                        handleNaturalEpisodeEnd(reason: "KSPlayer natural completion")
                        isPlaying = false
                    } else {
                        isPlaying = false
                        TraktSyncManager.shared.markCompleted(item: item, duration: resolvedDurationSeconds)
                        PlaybackResumeCacheManager.shared.clear(for: item)
                        controlsVisible = true
                        focusedControl = .playPause
                    }
                },
                onKSChaptersDiscovered: (!isLivePlayback && isSeriesPlayback) ? { chapters in
                    handleLocalIntroChapters(chapters, presentationID: playbackPresentationID)
                } : nil,
                onKSAudioFingerprintSample: (!isLivePlayback && isSeriesPlayback) ? { sample in
                    handleLocalAudioFingerprint(sample, presentationID: playbackPresentationID)
                } : nil
            )
        )

        return AnyView(
            surface
                .overlay(alignment: .bottom) {
                    if forceAetherSurface, !aetherSubtitleText.isEmpty {
                        Text(aetherSubtitleText)
                            .font(.system(size: 38, weight: .semibold, design: .rounded))
                            .multilineTextAlignment(.center)
                            .foregroundStyle(.white)
                            .shadow(color: .black.opacity(0.95), radius: 4, x: 0, y: 2)
                            .padding(.horizontal, 48)
                            .padding(.vertical, 12)
                            .background(.black.opacity(0.48), in: RoundedRectangle(cornerRadius: 12, style: .continuous))
                            .padding(.bottom, controlsVisible || activePanel != nil ? 176 : 72)
                            .allowsHitTesting(false)
                    }
                }
                .ignoresSafeArea()
                .opacity(isFirstFrameReady ? 1.0 : 0.0)
                .zIndex(0)
                .animation(.easeInOut(duration: 0.28), value: isFirstFrameReady)
                .allowsHitTesting(!(controlsVisible || activePanel != nil || isLoading || errorText != nil))
                .disabled(controlsVisible || activePanel != nil || isLoading || errorText != nil)
                .focusable(false)
        )
    }


    @ViewBuilder
    private var vodStatusChipRow: some View {
        // v1041: Apple TV-style, borderless playback facts. The old capsule/pill
        // shelf made every piece of information look equally heavy and also made
        // the Year/Rating redesign difficult to distinguish on-device. Keep the
        // exact timeline and control positions, but present status as an editorial
        // information rail with SF Symbols and system typography.
        HStack(alignment: .center, spacing: 15) {
            V1041InlinePlaybackFact(
                icon: "clock.arrow.circlepath",
                label: isScrubbingTimeline ? "SCRUB TO" : "POSITION",
                value: "\(formatTime(scrubDisplaySeconds)) / \(resolvedDurationSeconds > 0 ? formatTime(resolvedDurationSeconds) : "--:--")",
                theme: vodOverlayThemePreset
            )
            V1041PlaybackFactSeparator()
            V1041InlinePlaybackFact(icon: "timer", label: "REMAINING", value: vodRemainingLabel, theme: vodOverlayThemePreset)
            V1041PlaybackFactSeparator()
            V1041InlinePlaybackFact(icon: "chart.line.uptrend.xyaxis", label: "PROGRESS", value: vodStatusPercentLabel, theme: vodOverlayThemePreset)
            V1041PlaybackFactSeparator()
            V1041InlinePlaybackFact(icon: "externaldrive", label: "CACHE", value: vodCacheStatusChipLabel, theme: vodOverlayThemePreset)
            V1041PlaybackFactSeparator()
            V1041InlinePlaybackFact(icon: "4k.tv", label: "SOURCE", value: vodSourceInfoChipLabel, maxWidth: 310, theme: vodOverlayThemePreset)
            V1041PlaybackFactSeparator()
            V1052CurrentTimePlaybackFact(theme: vodOverlayThemePreset)
            Spacer(minLength: 4)
        }
        .frame(maxWidth: 1220, alignment: .leading)
        .padding(.leading, 262)
        .padding(.trailing, 86)
        .padding(.top, 1)
        .padding(.bottom, -2)
    }

    @ViewBuilder
    private var vodOverlayHeroInfoBlock: some View {
        if isLivePlayback {
            HStack(alignment: .bottom, spacing: 18) {
                VStack(alignment: .leading, spacing: 12) {
                    LivePlaybackLogoOnly(item: overlayItem)
                        .frame(width: 360, height: 64, alignment: .leading)
                    Text(vodOverlayDescriptionText)
                        .font(.system(size: 22, weight: .semibold, design: .rounded))
                        .lineSpacing(4)
                        .lineLimit(2)
                        .foregroundStyle(.white.opacity(0.76))
                }
                Spacer(minLength: 12)
            }
        } else {
            V1041AppleTVMediaInformationStage(
                item: overlayItem,
                descriptionText: vodOverlayDescriptionText,
                overlayTheme: vodOverlayThemePreset,
                castWallAwake: controlsVisible && activePanel == nil && castExplorerMember == nil && !vodEpisodeBrowserVisible && pendingVODSwitchItem == nil,
                episodeDateVerified: playbackMetadataItem != nil,
                castSpotlightIndex: $featuredCastSpotlightIndex,
                castInitialHoldClaimed: $featuredCastInitialHoldClaimed,
                castFocusRequestToken: featuredCastFocusRequestToken,
                castManualNavigationToken: featuredCastManualNavigationToken,
                castFocusActive: focusedZone == .cast,
                onCastFocusChanged: { focused in
                    if focused { focusedZone = .cast; focusedControl = nil }
                },
                productionArtworkIndex: $vodProductionArtworkIndex,
                rottenTomatoesScore: vodRottenTomatoesScore,
                communityScore: vodCommunityScoreText,
                featuredCastPresentationMode: vodFeaturedCastPresentationMode,
                portraitPosterThemedLogoEnabled: vodPortraitPosterThemedLogoEnabled,
                productionRatingsPanelEnabled: vodProductionRatingsPanelEnabled && !vodSpotlightHubPanelEnabled,
                spotlightHubPanelEnabled: vodSpotlightHubPanelEnabled,
                productionRatingsThemedLogoEnabled: vodProductionRatingsThemedLogoEnabled,
                playbackReady: isFirstFrameReady,
                productionMetadata: vodProductionMetadata,
                playbackRuntimeMinutes: resolvedDurationSeconds > 60 ? Int(resolvedDurationSeconds / 60) : nil,
                onCastSelected: openCastExplorer
            )
                .padding(.bottom, 10)
        }
    }

    private var vodTimelineControlRow: some View {
        // Keep the scrubber's visual confirmation latched for the entire scrub session.
        // tvOS can briefly clear/reassign FocusState while LEFT/RIGHT events are routed,
        // even though this screen still owns timeline scrubbing. Using isScrubbingTimeline
        // prevents the enlarged dot/halo from flashing once and disappearing mid-scrub.
        let isTimelineFocused = controlsVisible && vodControlShelfExpanded && activePanel == nil && !isLivePlayback &&
            (focusedZone == .timeline || focusedControl == .timeline || isScrubbingTimeline)
        // v886: exact mock-up thin rail. Keep the v884 position, width, white scrubber dot,
        // focus behavior, and every other VOD overlay element unchanged.
        let barHeight: CGFloat = 3
        let canFocusTimeline = activePanel == nil && controlsVisible && vodControlShelfExpanded && !isLivePlayback

        return HStack(alignment: .center, spacing: 18) {
            // v1145: preserve the exact v881 rail geometry, but expose the selected
            // target time while the scrubber owns focus. The label follows preview state
            // immediately; SELECT is only the commit action, not the first visible update.
            Group {
                if isTimelineFocused {
                    Text(formatTime(scrubDisplaySeconds))
                        .font(.system(size: 18, weight: .bold, design: .rounded))
                        .monospacedDigit()
                        .foregroundStyle(.white.opacity(0.96))
                } else {
                    Color.clear.frame(height: 1)
                }
            }
            .frame(width: 86, alignment: .trailing)

            vodTimelineProgressBar(isTimelineFocused: isTimelineFocused, barHeight: barHeight)

            Group {
                if isTimelineFocused {
                    Text(resolvedDurationSeconds > 0 ? formatTime(resolvedDurationSeconds) : "--:--")
                        .font(.system(size: 18, weight: .semibold, design: .rounded))
                        .monospacedDigit()
                        .foregroundStyle(.white.opacity(0.72))
                } else {
                    Color.clear.frame(height: 1)
                }
            }
            .frame(width: 96, alignment: .leading)
        }
        .frame(maxWidth: .infinity, alignment: .leading)
        .foregroundStyle(.white.opacity(0.92))
        .padding(.vertical, 6)
        .background(Color.clear)
        .focusable(canFocusTimeline)
        .focused($focusedControl, equals: .timeline)
        .onTapGesture { commitTimelineScrubOrToggleFocus() }
    }

    private func vodTimelineProgressBar(isTimelineFocused: Bool, barHeight: CGFloat) -> some View {
        PlayerProgressBar(
            progress: scrubDisplayProgress,
            focused: isTimelineFocused,
            previewProgress: scrubPreviewProgress,
            bufferedProgress: bufferedPlaybackProgress
        )
        .frame(width: 1135, height: 18)
    }

    private var vodControlDescriptors: [VODControlDescriptor] {
        var controls: [VODControlDescriptor] = []
        if !isLivePlayback {
            // vBRDC263: resume remains automatic and durable; use the redundant Resume slot
            // for the explicit AetherEngine / KSPlayer selector instead.
            controls.append(.init(control: .playerEngine, title: "Player Engine  \(activeEngineName)"))
            controls.append(.init(control: .restart, title: "Restart  0:00"))
        }
        controls.append(.init(control: .playPause, title: isPlaying ? "Pause" : "Play"))
        controls.append(.init(control: .back10, title: "Back 30  30"))
        controls.append(.init(control: .forward10, title: "Forward 60  60"))
        controls.append(.init(control: .catalogHome, title: "Home"))
        controls.append(.init(control: .catalogMovies, title: "Movies"))
        controls.append(.init(control: .catalogShows, title: "TV Shows"))
        controls.append(.init(control: .audio, title: "Audio  \(selectedAudioMode.isEmpty ? "Default" : selectedAudioMode)"))
        controls.append(.init(control: .subtitles, title: "Subtitles  \(selectedSubtitleMode)"))
        if !isLivePlayback {
            controls.append(.init(control: .zoom, title: "Video Fit  \(vodVideoFitMode.chipLabel)"))
        }
        if isSeriesPlayback {
            controls.append(.init(control: .episodes, title: "Episodes"))
        }
        controls.append(.init(control: .externalPlayer, title: "External Player"))
        controls.append(.init(control: .settings, title: "Settings"))
        return controls
    }

    // vBRDC189: the VOD control rail never scrolls.  Every available chip receives one
    // mathematically equal slot across the fixed safe-width shelf, so tvOS focus movement
    // changes only the selected chip scale/glow and can no longer pan the entire row.
    private var vodControlChipScroller: some View {
        GeometryReader { chipGeo in
            let descriptors = vodControlDescriptors
            let count = max(1, descriptors.count)
            let horizontalInset: CGFloat = 18
            let usableWidth = max(1, chipGeo.size.width - (horizontalInset * 2))
            let slotWidth = usableWidth / CGFloat(count)

            HStack(spacing: 0) {
                ForEach(descriptors) { descriptor in
                    PlayerControlButton(title: descriptor.title, focus: descriptor.control, focused: $focusedControl) {
                        focusedControl = descriptor.control
                        activateFocusedPlayerControl()
                    }
                    .id(descriptor.control)
                    .frame(width: slotWidth, height: 116, alignment: .center)
                }
            }
            .padding(.horizontal, horizontalInset)
            .frame(width: chipGeo.size.width, height: chipGeo.size.height, alignment: .center)
            .background {
                if vodControlsDockStyle == "visible" {
                    RoundedRectangle(cornerRadius: 42, style: .continuous)
                        .fill(
                            LinearGradient(
                                colors: [Color.white.opacity(0.085), Color.black.opacity(0.90), Color.black.opacity(0.97)],
                                startPoint: .top,
                                endPoint: .bottom
                            )
                        )
                }
            }
            .overlay {
                if vodControlsDockStyle == "visible" {
                    RoundedRectangle(cornerRadius: 42, style: .continuous)
                        .stroke(Color.white.opacity(0.10), lineWidth: 1)
                }
            }
            .shadow(
                color: vodControlsDockStyle == "visible" ? .black.opacity(0.48) : .clear,
                radius: vodControlsDockStyle == "visible" ? 24 : 0,
                y: vodControlsDockStyle == "visible" ? 10 : 0
            )
        }
        .frame(maxWidth: 1800, minHeight: 124, maxHeight: 124, alignment: .center)
        .frame(maxWidth: .infinity, alignment: .center)
        .padding(.horizontal, 38)
        .signalVisionFocusSection()
        .modifier(VODFocusBoundaryModifier())
        .contentShape(Rectangle())
    }

    private var vodControlDrawerHandle: some View {
        let isFocused = focusedControl == .controlDrawer
        return VStack(spacing: 4) {
            ZStack {
                Capsule()
                    .fill(
                        LinearGradient(
                            colors: isFocused
                                ? [Color.white.opacity(0.24), Color.white.opacity(0.10), Color.black.opacity(0.72)]
                                : [Color.white.opacity(0.10), Color.black.opacity(0.60)],
                            startPoint: .top,
                            endPoint: .bottom
                        )
                    )
                Capsule()
                    .stroke(isFocused ? Color.white.opacity(0.94) : Color.white.opacity(0.22), lineWidth: isFocused ? 2 : 1)
                Image(systemName: vodControlShelfExpanded ? "chevron.down" : "chevron.up")
                    .font(.system(size: 21, weight: .black))
                    .foregroundStyle(.white.opacity(isFocused ? 1.0 : 0.88))
            }
            .frame(width: 86, height: 42)
            .scaleEffect(isFocused ? 1.08 : 1.0)
            .shadow(color: isFocused ? Color.white.opacity(0.24) : Color.black.opacity(0.36), radius: isFocused ? 15 : 8, y: 5)

            Text(vodControlShelfExpanded ? "HIDE CONTROLS" : "CONTROLS")
                .font(.system(size: 10, weight: .black, design: .rounded))
                .kerning(1.2)
                .foregroundStyle(.white.opacity(isFocused ? 0.92 : 0.52))
        }
        .frame(width: 150, height: 62)
        .contentShape(Rectangle())
        .focusable(true)
        .focused($focusedControl, equals: .controlDrawer)
        .onTapGesture { toggleVODControlShelf() }
        .accessibilityAddTraits(.isButton)
        .accessibilityLabel(vodControlShelfExpanded ? "Hide VOD controls" : "Show VOD controls")
    }

    @ViewBuilder
    private var vodControlDrawerLayer: some View {
        if isLivePlayback {
            vodControlChipScroller
        } else if vodControlShelfExpanded {
            VStack(spacing: 0) {
                vodControlDrawerHandle
                    .padding(.bottom, -4)
                vodControlChipScroller
            }
            .transition(.move(edge: .bottom).combined(with: .opacity))
        } else {
            vodControlDrawerHandle
                .frame(maxWidth: .infinity, alignment: .center)
                .transition(.opacity.combined(with: .scale(scale: 0.94, anchor: .bottom)))
        }
    }

    private var liveOverlayCurrentChannel: LiveTVChannel? {
        currentLiveQuickGuideChannel ?? liveQuickGuideSelectedChannel
    }

    private var liveOverlayCurrentProgram: LiveProgram? {
        guard let channel = liveOverlayCurrentChannel else { return nil }
        return liveQuickGuideModel.currentProgram(for: channel) ?? liveQuickGuideModel.programs(for: channel).first
    }

    private var liveOverlayNextProgram: LiveProgram? {
        guard let channel = liveOverlayCurrentChannel else { return nil }
        return liveQuickGuideModel.nextProgram(for: channel, after: liveOverlayCurrentProgram)
    }

    private var liveTVControlChipRow: some View {
        HStack(spacing: 12) {
            LiveTVOverlayControlChip(
                title: usesBottomLiveTVQuickGuide ? "Bottom Quick Guide" : "Top Quick Guide",
                icon: usesBottomLiveTVQuickGuide ? "rectangle.bottomthird.inset.filled" : "rectangle.topthird.inset.filled",
                focus: .quickGuide,
                focused: $focusedControl
            ) { activateFocusedPlayerControl() }
            LiveTVOverlayControlChip(title: isPlaying ? "Pause" : "Play", icon: isPlaying ? "pause.fill" : "play.fill", focus: .playPause, focused: $focusedControl) { activateFocusedPlayerControl() }
            LiveTVOverlayControlChip(title: "Home", icon: "house.fill", focus: .catalogHome, focused: $focusedControl) { activateFocusedPlayerControl() }
            LiveTVOverlayControlChip(title: "Movies", icon: "film.fill", focus: .catalogMovies, focused: $focusedControl) { activateFocusedPlayerControl() }
            LiveTVOverlayControlChip(title: "TV Shows", icon: "tv.fill", focus: .catalogShows, focused: $focusedControl) { activateFocusedPlayerControl() }
            LiveTVOverlayControlChip(title: "Audio", icon: "waveform", focus: .audio, focused: $focusedControl) { activateFocusedPlayerControl() }
            LiveTVOverlayControlChip(title: "Subtitles", icon: "captions.bubble", focus: .subtitles, focused: $focusedControl) { activateFocusedPlayerControl() }
            LiveTVOverlayControlChip(title: "Settings", icon: "gearshape", focus: .settings, focused: $focusedControl) { activateFocusedPlayerControl() }
            LiveTVOverlayControlChip(title: "Close", icon: "xmark", focus: .close, focused: $focusedControl) { activateFocusedPlayerControl() }
        }
        .signalVisionFocusSection()
    }

    private var liveTVBottomChromeLayer: some View {
        let channel = liveOverlayCurrentChannel
        let program = liveOverlayCurrentProgram
        let nextProgram = liveOverlayNextProgram
        return VStack(alignment: .leading, spacing: 10) {
            HStack(alignment: .center, spacing: 15) {
                ZStack {
                    RoundedRectangle(cornerRadius: 15, style: .continuous)
                        .fill(Color.black.opacity(0.46))
                    if let artwork = program?.imageURL, PremiumArtworkURL.url(artwork) != nil, !artwork.isEmpty {
                        LiveTVProgramArtworkFrame(imageURL: artwork, cornerRadius: 15, fallbackText: channel?.logo ?? "TV")
                    } else if let artwork = channel?.iconURL, let artworkURL = PremiumArtworkURL.url(artwork), !artwork.isEmpty {
                        LiveTVBoundedFitArtwork(
                            url: artworkURL,
                            fallbackText: channel?.logo ?? "TV",
                            maxPixelSize: 384,
                            contentPadding: 8,
                            fallbackFont: .system(size: 22, weight: .black),
                            allowDuringFullScreenPlayback: true
                        )
                    } else {
                        Text(channel?.logo ?? "TV").font(.system(size: 22, weight: .black))
                    }
                }
                .frame(width: 138, height: 92)
                .overlay(RoundedRectangle(cornerRadius: 15, style: .continuous).stroke(Color.white.opacity(0.13), lineWidth: 1))

                VStack(alignment: .leading, spacing: 4) {
                    Text(program?.title.ifEmpty(item.title) ?? item.title)
                        .font(.custom("Avenir Next", fixedSize: 31).weight(.heavy))
                        .lineLimit(1)
                    Text((program?.description).flatMap { $0.isEmpty ? nil : $0 } ?? item.description)
                        .font(.custom("Avenir Next", fixedSize: 18).weight(.medium))
                        .foregroundStyle(.white.opacity(0.74))
                        .lineLimit(2)
                    HStack(spacing: 8) {
                        Text([channel?.number, channel?.name, channel?.source].compactMap { $0 }.filter { !$0.isEmpty }.joined(separator: " • "))
                        if let nextProgram {
                            Text("NEXT  \(nextProgram.startText.ifEmpty("Soon"))  \(nextProgram.title)")
                                .foregroundStyle(.white.opacity(0.54))
                                .lineLimit(1)
                        }
                    }
                    .font(.custom("Avenir Next Condensed", fixedSize: 15).weight(.bold))
                    .foregroundStyle(.white.opacity(0.64))
                }
                Spacer(minLength: 12)
                if let nextProgram {
                    LiveTVNextProgramPreview(program: nextProgram, compact: false)
                        .frame(width: 330)
                }
                VStack(alignment: .trailing, spacing: 4) {
                    LiveTVProgramTimelineText(program: program, compact: false)
                    TimelineView(.periodic(from: Date(), by: 1.0)) { context in
                        Text(context.date.formatted(date: .omitted, time: .shortened))
                    }
                    .font(.custom("Avenir Next", fixedSize: 15).weight(.semibold))
                    .foregroundStyle(.white.opacity(0.60))
                }
            }

            LiveTVProgramProgressBar(program: program)

            liveTVControlChipRow
        }
        .padding(.horizontal, 30)
        .padding(.vertical, 22)
        .frame(maxWidth: 1520, minHeight: 245, alignment: .leading)
        .background(
            RoundedRectangle(cornerRadius: 26, style: .continuous)
                .fill(Color.black.opacity(0.76))
                .overlay(RoundedRectangle(cornerRadius: 26, style: .continuous).stroke(Color.white.opacity(0.13), lineWidth: 1))
        )
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .bottom)
        // v1171: Larger information surface inspired by modern Live TV OSDs.
        // Keep it centered with safe symmetric margins on the 1920-wide tvOS canvas.
        .padding(.horizontal, 42)
        .padding(.bottom, 42)
        .opacity(controlsVisible ? 1 : 0)
        .allowsHitTesting(controlsVisible && activePanel == nil)
        .disabled(activePanel != nil)
        .zIndex(25)
        .transition(.move(edge: .bottom).combined(with: .opacity))
    }

    @ViewBuilder
    private var vodBottomChromeLayer: some View {
        // v1171: Original is the only production VOD overlay. This bypasses every
        // retired skin path while preserving the exact approved overlay implementation.
        vodOriginalBottomChromeLayer
    }

    // v1157: Original is intentionally the exact v1156 production VOD overlay.
    // All new themes wrap/recompose the same information and controls without changing
    // playback engines, focus routing, scrubber behavior, track menus, or source state.
    // vBRDC186 runtime containment: erase heavyweight content islands before composing
    // the final chrome. The vBRDC185 device IPS showed Swift generic-metadata recursion
    // / stack exhaustion in this getter, not a playback-engine failure.
    private var vodOriginalHeroStatusSection: AnyView {
        AnyView(
            VStack(alignment: .leading, spacing: 7) {
                vodOverlayHeroInfoBlock
                vodStatusChipRow
            }
        )
    }

    private var vodOriginalTimelineSection: AnyView { AnyView(vodTimelineControlRow) }
    private var vodOriginalDrawerSection: AnyView { AnyView(vodControlDrawerLayer) }

    private var vodOriginalBottomChromeLayer: some View {
        VStack(alignment: .leading, spacing: vodControlShelfExpanded || isLivePlayback ? 10 : 6) {
            vodOriginalHeroStatusSection
            vodOriginalTimelineSection
            vodOriginalDrawerSection
        }
        .foregroundStyle(.white)
        .padding(.horizontal, 28)
        .padding(.bottom, vodControlShelfExpanded || isLivePlayback ? 8 : 2)
        .frame(maxWidth: .infinity, alignment: .center)
        .scaleEffect(x: 1.0, y: 0.88, anchor: .bottom)
        .opacity(controlsVisible ? 1.0 : 0.0)
        .allowsHitTesting(controlsVisible && activePanel == nil)
        .disabled(activePanel != nil)
        .signalVisionFocusSection()
        .contentShape(Rectangle())
        .zIndex(25)
        .modifier(RasterizedOverlayModifier(active: controlsVisible || activePanel != nil || isScrubbingTimeline || isSeekingInPlayer))
        .animation(isPlaying ? nil : .easeInOut(duration: 0.22), value: controlsVisible)
        .animation(.spring(response: 0.34, dampingFraction: 0.86), value: vodControlShelfExpanded)
    }

    private var vodThemedBottomChromeLayer: some View {
        VODOverlayThemeShell(
            theme: vodOverlayThemePreset,
            shelfExpanded: vodControlShelfExpanded,
            controlsVisible: controlsVisible,
            interactionEnabled: controlsVisible && activePanel == nil,
            disabled: activePanel != nil,
            rasterActive: controlsVisible || activePanel != nil || isScrubbingTimeline || isSeekingInPlayer,
            isPlaying: isPlaying
        ) {
            vodThemedBottomChromeContent
                .frame(maxWidth: .infinity, maxHeight: .infinity)
        }
    }

