                V1041InlinePlaybackFact(icon: "4k.tv", label: "SOURCE", value: vodSourceInfoChipLabel, maxWidth: 230, theme: vodOverlayThemePreset)
                V1052CurrentTimePlaybackFact(theme: vodOverlayThemePreset)
            }
        }
    }

    private func vodThemePanel<PanelContent: View>(
        cornerRadius: CGFloat,
        fill: Color,
        stroke: Color,
        @ViewBuilder content: () -> PanelContent
    ) -> some View {
        content()
            .padding(16)
            .background(
                RoundedRectangle(cornerRadius: cornerRadius, style: .continuous)
                    .fill(fill)
            )
            .overlay(
                RoundedRectangle(cornerRadius: cornerRadius, style: .continuous)
                    .stroke(stroke, lineWidth: 1)
            )
    }

