    private var skipIntroProgress: Double {
        guard let marker = detectedIntroMarker else { return 0 }
        let duration = max(1, marker.durationSeconds)
        let remaining = max(0, marker.endSeconds - authoritativeCurrentSeconds)
        return min(1, max(0, remaining / duration))
    }

