    private func handleBluetoothVODMediaCommand(_ notification: Notification) {
        guard let owner = notification.userInfo?["sessionID"] as? UUID,
              owner == playbackPresentationID,
              let rawCommand = notification.userInfo?["command"] as? String,
              let command = BluetoothVODMediaCommand(rawValue: rawCommand) else { return }

        // vBRDC138: MPRemoteCommandCenter already has its own 180 ms duplicate-event
        // suppression in BluetoothVODMediaButtonCoordinator. Do not send a legitimate
        // headset transport command through playerAction's 440 ms UI debounce, which is
        // intended only for rapid Siri-remote/chip actions and can otherwise discard the
        // first Bluetooth Pause/Play after another player interaction.
        guard castExplorerMember == nil,
              !vodEpisodeBrowserVisible,
              pendingVODSwitchItem == nil else { return }

        switch command {
        case .toggle:
            togglePlay()
        case .play:
            if !isPlaying { togglePlay() }
        case .pause:
            if isPlaying { togglePlay() }
        }
    }

