    private var playerVisualTree: some View {
        ZStack(alignment: .bottom) {
            playbackSurfaceLayer(activePlaybackURL)

            // vBRDC192: mount the existing passive Episode Alert banner inside the same
            // presentation stack as KSPlayer/AVPlayer for both VOD and Live TV. The
            // alert stays non-focusable, non-pausing, and independent of player clocks.
            if let episodeAlert {
                RootNewEpisodeAlertBanner(
                    showTitle: episodeAlert.show.title,
                    showPosterURL: episodeAlert.show.posterURL ?? "",
                    episode: episodeAlert.episode,
                    side: episodeAlertSide,
                    theme: episodeAlertTheme
                )
                .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: episodeAlertSide.alignment)
                .padding(episodeAlertSide.verticalEdgeSet, newEpisodeAlertScreenEdgeInset)
                .padding(episodeAlertSide.horizontalEdgeSet, newEpisodeAlertScreenEdgeInset)
                .allowsHitTesting(false)
                .id("vod-episode-alert-\(episodeAlert.id)")
                .onAppear { onEpisodeAlertPresented(episodeAlert) }
                .transition(.move(edge: episodeAlertSide.transitionEdge).combined(with: .opacity))
                .zIndex(120)
            }

            // v1028: VOD needs a lightweight focus owner while its chrome is hidden.
            // v1027 removed the focusable bottom-chrome parent to keep scrubber focus stable,
            // but that also left normal VOD playback with no focus destination after auto-hide.
            // Without a destination, tvOS stops delivering move/select commands and the overlay
            // cannot be reopened. This transparent canvas exists only while VOD controls are hidden;
            // once the chrome appears, the real timeline/buttons regain focus ownership.
            if !isLivePlayback && activePanel == nil && !controlsVisible && playbackUnityCatalogDestination == nil {
                Color.black.opacity(0.001)
                    .ignoresSafeArea()
                    .contentShape(Rectangle())
                    .focusable(true)
                    .focused($playerCanvasFocused)
                    .allowsHitTesting(true)
                    .zIndex(5)
                    .onAppear {
                        DispatchQueue.main.async {
                            guard !self.isLivePlayback,
                                  self.activePanel == nil,
                                  !self.controlsVisible else { return }
                            self.playerCanvasFocused = true
                        }
                    }
            }

            // v977: Live TV keeps the v976 full-screen focus owner; controls hide immediately, so it needs a persistent
            // focus owner after the heavy grid is removed from the root render tree.
            // Without this host, tvOS has no focusable destination and drops remote
            // focus as soon as a channel opens. The transparent canvas owns focus only
            // while Live TV chrome/panels are hidden; Quick Guide input continues to be
            // routed by the parent player view without retaining the Live TV grid.
            if isLivePlayback {
                Color.black.opacity(0.001)
                    .ignoresSafeArea()
                    .contentShape(Rectangle())
                    .focusable(activePanel == nil && !controlsVisible && playbackUnityCatalogDestination == nil)
                    .focused($playerCanvasFocused)
                    .allowsHitTesting(activePanel == nil && !controlsVisible && playbackUnityCatalogDestination == nil)
                    .zIndex(5)

                LiveTVSelectHoldMonitor(
                    minimumDuration: 0.62,
                    isEnabled: liveQuickGuideVisible && !liveQuickGuideChannelActionsVisible,
                    onRecognized: {
                        guard let selected = liveQuickGuideSelectedChannel else { return }
                        liveQuickGuideSuppressSelectUntil = Date().addingTimeInterval(1.0)
                        presentLiveQuickGuideChannelActions(for: selected)
                    },
                    onEnded: {}
                )
                .frame(width: 1, height: 1)
                .opacity(0.001)
                .allowsHitTesting(false)
                .zIndex(6)
            }

            if (isLoading || !isFirstFrameReady || ksLoadingCoverActive) && errorText == nil {
                ZStack {
                    VODLoadingBackdrop(item: overlayItem, message: retryText ?? loadingMessage)
                }
                .opacity((isFirstFrameReady && !ksLoadingCoverActive) ? 0.0 : 1.0)
                .animation(.easeInOut(duration: 0.20), value: isFirstFrameReady && !ksLoadingCoverActive)
                // vBRDC306: engine handoff/loading must cover the outgoing frozen frame
                // and any option drawer while KSPlayer is constructing its first frame.
                .zIndex(80)
            }

            if let errorText {
                ApplePlayerErrorCard(message: errorText) { requestPlayerDismissal() }
                    .zIndex(40)
            }

            if let playerCompatibilityToast {
                Text(playerCompatibilityToast)
                    .font(.system(size: 22, weight: .black, design: .rounded))
                    .foregroundStyle(.white)
                    .padding(.horizontal, 24)
                    .padding(.vertical, 12)
                    .background(Capsule().fill(Color.black.opacity(0.70)))
                    .overlay(Capsule().stroke(Color.white.opacity(0.18), lineWidth: 1))
                    .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .top)
                    .padding(.top, 74)
                    .allowsHitTesting(false)
                    .zIndex(41)
            }

            if !isLivePlayback, let automaticSourceFailoverToast {
                HStack(spacing: 12) {
                    Image(systemName: "arrow.triangle.2.circlepath")
                        .font(.system(size: 18, weight: .black))
                        .foregroundStyle(.orange)
                    Text(automaticSourceFailoverToast)
                        .font(.system(size: 19, weight: .black, design: .rounded))
                        .foregroundStyle(.white)
                        .lineLimit(1)
                }
                .padding(.horizontal, 22)
                .padding(.vertical, 13)
                .background(Capsule().fill(Color.black.opacity(0.84)))
                .overlay(Capsule().stroke(Color.orange.opacity(0.46), lineWidth: 1))
                .shadow(color: .black.opacity(0.50), radius: 16, y: 8)
                .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .top)
                .padding(.top, 72)
                .allowsHitTesting(false)
                .accessibilityLabel(automaticSourceFailoverToast)
                .zIndex(43)
                .transition(.move(edge: .top).combined(with: .opacity))
            }

            if vodCastExplorerOnboardingVisible,
               !isLivePlayback,
               controlsVisible,
               activePanel == nil,
               castExplorerMember == nil,
               !vodEpisodeBrowserVisible,
               pendingVODSwitchItem == nil {
                VODCastExplorerOnboardingTip()
                    .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
                    .padding(.top, 76)
                    .padding(.leading, 70)
                    .allowsHitTesting(false)
                    .zIndex(45)
                    .transition(.move(edge: .top).combined(with: .opacity))
            }

            if let castExplorerMember, !isLivePlayback {
                V1134CastExplorerOverlay(
                    member: castExplorerMember,
                    snapshot: castExplorerSnapshot,
                    isLoading: castExplorerLoading,
                    errorMessage: castExplorerError,
                    onCreditSelected: handleCastExplorerCreditSelected,
                    onClose: closeCastExplorer
                )
                .frame(maxWidth: .infinity, maxHeight: .infinity)
                .disabled(pendingVODSwitchItem != nil)
                .zIndex(70)
                .transition(.opacity.combined(with: .scale(scale: 0.985)))
            }

            if vodEpisodeBrowserVisible, !isLivePlayback {
                Phase15VODEpisodeBrowserOverlay(
                    seriesTitle: vodEpisodeBrowserSeriesTitle.ifEmpty(overlayItem.title),
                    currentItemID: item.id,
                    episodes: vodEpisodeBrowserItems,
                    isLoading: vodEpisodeBrowserLoading,
                    errorMessage: vodEpisodeBrowserError,
                    onEpisodeSelected: requestVODEpisodeSwitch,
                    onClose: closeVODEpisodeBrowser
                )
                .frame(maxWidth: .infinity, maxHeight: .infinity)
                .disabled(pendingVODSwitchItem != nil)
                .zIndex(72)
                .transition(.opacity.combined(with: .scale(scale: 0.985)))
            }

            if let pendingVODSwitchItem, !isLivePlayback {
                if pendingVODSwitchSourcePickerVisible {
                    Phase15VODSourcePickerOverlay(
                        target: pendingVODSwitchResolvedItem ?? pendingVODSwitchItem,
                        sources: pendingVODSwitchSources,
                        isWorking: pendingVODSwitchInProgress,
                        errorMessage: pendingVODSwitchError,
                        onCancel: cancelPendingVODPlaybackSwitch,
                        onSelect: selectPendingVODSwitchSource
                    )
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                    .zIndex(96)
                    .transition(.opacity.combined(with: .scale(scale: 0.97)))
                } else {
                    Phase15VODSwitchConfirmationOverlay(
                        currentTitle: overlayItem.title,
                        target: pendingVODSwitchItem,
                        contextLabel: pendingVODSwitchContext,
                        isWorking: pendingVODSwitchInProgress,
                        errorMessage: pendingVODSwitchError,
                        onCancel: cancelPendingVODPlaybackSwitch,
                        onConfirm: confirmPendingVODPlaybackSwitch
                    )
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                    .zIndex(95)
                    .transition(.opacity.combined(with: .scale(scale: 0.97)))
                }
            }

            if let seekFeedbackSeconds, !isLivePlayback {
                VODSeekFeedbackBadge(seconds: seekFeedbackSeconds)
                    .frame(
                        maxWidth: .infinity,
                        maxHeight: .infinity,
                        alignment: seekFeedbackSeconds < 0 ? .leading : .trailing
                    )
                    .padding(.horizontal, 116)
                    .allowsHitTesting(false)
                    .zIndex(42)
                    .transition(
                        .opacity.combined(
                            with: .scale(
                                scale: 0.88,
                                anchor: seekFeedbackSeconds < 0 ? .leading : .trailing
                            )
                        )
                    )
            }

            if let debugInfo = liveTimingDebugInfo {
                LiveTimingDebugOverlay(info: debugInfo)
                    .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
                    .padding(.top, 52)
                    .padding(.leading, 52)
                    .allowsHitTesting(false)
                    .zIndex(18)
            }

            if isLivePlayback && liveQuickGuideVisible {
                livePlaybackQuickGuideOverlay
                    .zIndex(35)
                    .transition(.move(edge: .top).combined(with: .opacity))
            }

            if isLivePlayback,
               liveQuickGuideChannelActionsVisible,
               let selected = liveQuickGuideSelectedChannel {
                liveQuickGuideChannelActionOverlay(channel: selected)
                    .zIndex(50)
                    .transition(.opacity.combined(with: .scale(scale: 0.98)))
            }

            if shouldShowLiveQuickGuideTip {
                liveQuickGuideTip
                    .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .bottom)
                    .padding(.bottom, 92)
                    .allowsHitTesting(false)
                    .zIndex(34)
                    .transition(.opacity.combined(with: .scale(scale: 0.98)))
            }

            if !isLivePlayback && skipIntroVisible {
                skipIntroOverlay
                    .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .bottomTrailing)
                    .padding(.trailing, 64)
                    .padding(.bottom, controlsVisible ? 236 : 76)
                    .allowsHitTesting(false)
                    .zIndex(47)
                    .transition(.move(edge: .trailing).combined(with: .opacity))
            }

            if !isLivePlayback && upNextVisible {
                upNextEpisodeOverlay
                    .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .bottomTrailing)
                    .padding(.trailing, 62)
                    .padding(.bottom, controlsVisible ? 238 : 72)
                    .zIndex(46)
                    .transition(.move(edge: .trailing).combined(with: .opacity))
            }

            // v619: Live TV diagnostics are isolated to Live TV debugging only. VOD playback is now
            // stable with display matching, so CBS/Fox timing work needs channel-level visibility without
            // touching the VOD pipeline.
            if isLivePlayback && vodPlaybackDiagnosticsEnabled {
                DebridPlaybackDiagnosticsPanel(diagnostics: currentPlaybackDiagnostics(), isLive: true)
                    .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topTrailing)
                    .padding(.top, 42)
                    .padding(.trailing, 54)
                    .zIndex(12)
                    .transition(.opacity)
            }

            // v151: diagnostics are useful, but keeping a diagnostic panel alive over every playing
            // frame adds SwiftUI/compositing work exactly where cadence is most sensitive. Show it while
            // paused/loading/settings are open, not during normal hidden-controls playback.
            if !isLivePlayback && vodPlaybackDiagnosticsEnabled && (!isPlaying || activePanel == .settings || isLoading || errorText != nil) {
                DebridPlaybackDiagnosticsPanel(diagnostics: currentPlaybackDiagnostics(), isLive: false)
                    .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topTrailing)
                    .padding(.top, 42)
                    .padding(.trailing, 54)
                    .zIndex(12)
                    .transition(.opacity)
            }

            if controlsVisible || activePanel != nil {
                if isLivePlayback {
                    LinearGradient(
                        colors: [Color.clear, Color.black.opacity(0.14), Color.black.opacity(0.72)],
                        startPoint: .top,
                        endPoint: .bottom
                    )
                    .ignoresSafeArea()
                    .allowsHitTesting(false)
                } else {
                    if vodOverlayThemePreset == .original {
                        AppleVODChromeBackground()
                            .ignoresSafeArea()
                            .opacity(isPlaying ? 0.18 : 1.0)
                            .allowsHitTesting(false)

                        if activeEngineName != "AetherEngine" {
                            TheaterAmbientArtworkGlow(item: overlayItem)
                                .ignoresSafeArea()
                                .opacity(isPlaying ? 0.34 : 0.46)
                                .allowsHitTesting(false)
                                .zIndex(2)
                        }
                    } else {
                        VODOverlayThemeBackdrop(theme: vodOverlayThemePreset)
                            .ignoresSafeArea()
                            .opacity(isPlaying ? 0.86 : 1.0)
                            .allowsHitTesting(false)

                        if activeEngineName != "AetherEngine" {
                            TheaterAmbientArtworkGlow(item: overlayItem)
                                .ignoresSafeArea()
                                .saturation(vodOverlayThemePreset == .noir ? 0 : 1)
                                .opacity(vodOverlayThemePreset == .minimal ? (isPlaying ? 0.12 : 0.18) : (isPlaying ? 0.16 : 0.24))
                                .allowsHitTesting(false)
                                .zIndex(2)
                        }
                    }
                }
            }

            if let activePanel {
                // v269: panel shield blocks remote/tap leakage to the bottom VOD bar while
                // the option panel is open. The bottom bar remains visible, but is silenced.
                Color.black.opacity(0.001)
                    .ignoresSafeArea()
                    .contentShape(Rectangle())
                    .allowsHitTesting(true)
                    .zIndex(34)

                DebridPlayerPanel(
                    title: panelTitle(activePanel),
                    detail: panelDetail(activePanel),
                    focusedOption: selectedPanelOption ?? focusedPanelOption
                ) {
                    panelOptions(activePanel)
                    PanelOptionChip(title: "Close Panel", selected: (selectedPanelOption ?? focusedPanelOption) == .closePanel, focus: .closePanel, focused: $focusedPanelOption) {
                        focusedPanelOption = .closePanel
                        selectedPanelOption = .closePanel
                        activateFocusedPanelOption()
                    }
                }
                .signalVisionFocusSection()
                .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .trailing)
                .padding(.trailing, 72)
                .padding(.bottom, 170)
                .zIndex(35)
                .onAppear { seedPanelFocus(activePanel) }
            }

            // vBRDC184 compile containment: keep the full shared catalog/detail graph
            // behind one opaque subview so playerVisualTree does not inherit its generic depth.
            playbackUnityCatalogLayer

            // v1085: opacity alone kept the complete VOD chrome, cast timers,
            // artwork views, materials, and shadows alive while controls were hidden.
            // The lightweight player canvas already owns hidden-state focus, so mount
            // the heavy chrome only when it can actually be seen or interacted with.
            if playbackUnityCatalogDestination == nil && (controlsVisible || activePanel != nil || isScrubbingTimeline || isSeekingInPlayer) {
                if isLivePlayback {
                    liveTVBottomChromeLayer
                } else {
                    vodBottomChromeLayer
                        .transition(isPlaying ? .identity : .opacity)
                }
            }
        }
        .contentShape(Rectangle())
        .signalVisionFocusSection()
    }

    // vBRDC113 compile containment: keep the VOD player modifier graph split into
    // opaque stages so Xcode never has to infer the full playback surface, lifecycle,
    // observation, remote-command, and exit-command chain as one generic expression.
    // This is a compiler-only structural boundary; runtime modifier order is preserved.
    private var playerLifecycleTree: some View {
        playerVisualTree
        .onAppear {
            if !isLivePlayback {
                // vBRDC192: hard-normalize restored preferences so the shared right-side
                // Media Information feature slot can never have two active owners.
                if vodProductionRatingsPanelEnabled && vodSpotlightHubPanelEnabled {
                    vodProductionRatingsPanelEnabled = false
                }
                restorePerTitlePlaybackMemory()
                playbackOverlayBridge.connect(to: PlaybackController.shared.snapshots)
                playbackOverlayBridge.setOverlayVisible(controlsVisible || activePanel != nil)
                // PlaybackKit's clock and KSPlayer both begin at zero. v1145 primed
                // KSOptions.startPlayTime with the saved position, but PlaybackKit's KS
                // coordinator also pre-seeded its published clock with that same value.
                // That could falsely "confirm" resume even when the decoder actually
                // started at 0. v1146 waits for a genuine advancing KS clock, then seeks.
                let session = PlaybackController.shared.play(
                    PlaybackRequest(id: playbackPresentationID, url: url, title: item.title, kind: .vod, startTime: 0)
                )
                // Phase 5: passive render-host lifecycle markers only. The existing
                // SwiftUI/KSPlayer surface remains the sole render path in this build.
                PlaybackController.shared.attachRenderHost(sessionID: session.id)
                PlaybackController.shared.activateRenderHost(sessionID: session.id)
                PlaybackController.shared.setOverlayVisible(controlsVisible || activePanel != nil, sessionID: session.id)
                PlaybackController.shared.setLoading(isLoading, sessionID: session.id)
                PlaybackController.shared.setFirstFrameReady(isFirstFrameReady, sessionID: session.id)
            }
            setupPlayer()
            #if os(visionOS)
            if !isLivePlayback {
                SignalVisionPlaybackHandoff.shared.begin(
                    sessionID: playbackPresentationID,
                    engineName: activeEngineName,
                    avPlayer: player
                )
                SignalVisionPlaybackHandoff.shared.updateClock(
                    elapsed: authoritativeCurrentSeconds,
                    duration: resolvedDurationSeconds,
                    isPlaying: isPlaying,
                    force: true
                )
            }
            #endif
            if !isLivePlayback {
                BluetoothVODMediaButtonCoordinator.shared.claimVODSession(
                    playbackPresentationID,
                    title: item.title,
                    duration: resolvedDurationSeconds,
                    elapsed: authoritativeCurrentSeconds,
                    isPlaying: isPlaying
                )
                publishVODSystemNowPlayingMetadata()
            }
            // v1111 startup isolation: review/production/artwork work begins only after
            // KSPlayer has produced a confirmed first frame. Nothing decorative runs here.
            if isLivePlayback {
                LiveTVMemoryAuditManager.shared.markPlayerPresented()
                // vBRDC305: setupPlayer() owns the one startup Quick Guide snapshot load.
                // Do not synchronously republish the ObservableObject a second time while
                // SwiftUI is still evaluating VODPlayerScreen.onAppear.
                publishLiveTVSystemNowPlaying(claim: true)
                scheduleLiveQuickGuideBoundaryRefresh(reason: "playback appear")
                controlsVisible = false
                focusedControl = nil
                playerCanvasFocused = false
                claimLiveTVPlayerCanvasFocus(reason: "player appeared")
                scheduleLiveQuickGuideTipIfNeeded()
            } else {
                configureInitialVODControlShelfState()
                forceControlsVisibleForNavigation()
                seedVODOverlayFocusIfNeeded()
            }
        }
        .onDisappear {
            let internalVODHandoff = isInternalVODPlaybackHandoff
            if playbackUnityCatalogDestination != nil || store.playbackUnityBrowseActive {
                store.selectedDetail = nil
                store.setPlaybackUnityBrowseActive(false, reason: "player surface disappeared")
                playbackUnityCatalogDestination = nil
            }
            // vBRDC138: do not release Bluetooth/Now Playing ownership from SwiftUI
            // disappearance. The authoritative CatalogStore playback session owns that
            // lifetime so transient/remounted VOD surfaces cannot tear down headset
            // controls underneath an otherwise-active movie/show.
            seekFeedbackTask?.cancel()
            seekFeedbackTask = nil
            timelineScrubAutoSeekTask?.cancel()
            timelineScrubAutoSeekTask = nil
            vodControlShelfHideTask?.cancel()
            vodControlShelfHideTask = nil
            seekFeedbackSeconds = nil
            playerDismissalTask?.cancel()
            playerDismissalTask = nil
            livePlayerFocusTask?.cancel()
            livePlayerFocusTask = nil
            vodReviewTask?.cancel()
            vodReviewTask = nil
            vodReviewResolvedItemID = nil
            vodProductionMetadataTask?.cancel()
            vodProductionMetadataTask = nil
            castExplorerTask?.cancel()
            castExplorerTask = nil
            cancelVODCastExplorerOnboarding()
            castExplorerMember = nil
            castExplorerSnapshot = nil
            castExplorerLoading = false
            castExplorerError = nil
            vodEpisodeBrowserTask?.cancel()
            vodEpisodeBrowserTask = nil
            vodEpisodeBrowserVisible = false
            vodEpisodeBrowserItems = []
            vodEpisodeBrowserLoading = false
            vodEpisodeBrowserError = nil
            pendingVODSwitchTask?.cancel()
            pendingVODSwitchTask = nil
            pendingVODSwitchItem = nil
            pendingVODSwitchInProgress = false
            pendingVODSwitchError = nil
            pendingVODSwitchSources = []
            pendingVODSwitchResolvedItem = nil
            pendingVODSwitchSourcePickerVisible = false
            upNextPreparationTask?.cancel()
            upNextPreparationTask = nil
            upNextSourcePreparationTask?.cancel()
            upNextSourcePreparationTask = nil
            upNextCountdownTask?.cancel()
            upNextCountdownTask = nil
            upNextWatchdogTask?.cancel()
            upNextWatchdogTask = nil
            upNextDecorationTask?.cancel()
            upNextDecorationTask = nil
            pendingVODProductionMetadata = nil
            pendingVODProductionMetadataItemID = nil
            // Persist only the tiny local fingerprint session before the VOD surface is torn down.
            // No audio/video bytes or source credentials are written by this engine.
            if !isLivePlayback, isSeriesPlayback {
                // LocalIntroDetectionEngine only snapshots/removes the tiny session here;
                // JSON encoding + atomic persistence already run on its private utility queue.
                LocalIntroDetectionEngine.shared.finishSession(item: item, presentationID: playbackPresentationID)
            }
            skipIntroCountdownTask?.cancel()
            skipIntroCountdownTask = nil
            introSegmentLookupTask?.cancel()
            introSegmentLookupTask = nil
            introSegmentLookupDurationBucket = nil
            skipIntroVisible = false
            detectedIntroMarker = nil
            alternateAudioDiscoveryTask?.cancel()
            alternateAudioDiscoveryTask = nil
            alternateAudioBridgeTask?.cancel()
            alternateAudioBridgeTask = nil
            isPreparingAlternateAudioBridge = false
            localAlternateAudioURL = nil
            localAlternateAudioTrackIndex = nil
            localAlternateAudioHTTPHeaders = [:]
            store.cancelAlternateAudioBridgeSession(
                pendingAlternateAudioBridgeUUID,
                presentationID: playbackPresentationID,
                reason: "Playback closed — pending Alternate Audio bridge released."
            )
            store.cancelAlternateAudioBridgeSession(
                activeAlternateAudioBridgeUUID,
                presentationID: playbackPresentationID,
                reason: "Playback closed — active Alternate Audio bridge released."
            )
            store.cancelAlternateAudioBridgeSession(
                retiringAlternateAudioBridgeUUID,
                presentationID: playbackPresentationID,
                reason: "Playback closed — retired Alternate Audio bridge released."
            )
            pendingAlternateAudioBridgeUUID = nil
            activeAlternateAudioBridgeUUID = nil
            retiringAlternateAudioBridgeUUID = nil
            store.cancelAllAlternateAudioWork(
                presentationID: playbackPresentationID,
                additionalBridgeUUID: store.preparedAlternateAudioBridge?.id,
                clearPrepared: true,
                reason: "Playback closed — Alternate Audio backend work cancelled."
            )
            alternateAudioHandoffRecoveryTask?.cancel()
            alternateAudioHandoffRecoveryTask = nil
            if !isLivePlayback,
               (alternateAudioHandoffID != nil || store.experimentalPlaybackHandoffID != nil) {
                store.clearSessionOwnedExperimentalPlaybackHandoff(
                    alternateAudioHandoffID,
                    presentationID: playbackPresentationID,
                    reason: "Playback closed — experimental audio handoff released."
                )
                alternateAudioHandoffID = nil
                alternateAudioHandoffState = .idle
            }
            playerCanvasFocused = false
            if isLivePlayback {
                teardownPlayer()
                teardownLiveTVTransientState()
                LiveTVMemoryAuditManager.shared.markPlayerTeardown()
            } else if !orderedPlayerTeardownCompleted {
                // vBRDC200: a replacement VOD presentation already owns decoder startup.
                // The outgoing SwiftUI surface must perform only local cleanup in that case;
                // durable resume/Trakt/catalog exit work belongs to a real player dismissal.
                teardownPlayer(forInternalHandoff: internalVODHandoff)
                stopOwnedPlaybackKitSession(reason: internalVODHandoff ? "stale VOD handoff surface disappeared" : "screen disappeared")
            }
            #if os(visionOS)
            SignalVisionPlaybackHandoff.shared.end(sessionID: playbackPresentationID)
            #endif
        }
    }

    private var playerInputTree: AnyView {
        AnyView(
        playerLifecycleTree
        .onChange(of: scenePhase) { phase in
            guard !isLivePlayback else { return }
            if phase == .active {
                // vBRDC327: app-switcher return is a resume edge, not a decoder rebuild.
                // Restore MediaRemote/audio ownership and pulse the existing internal engine.
                BluetoothVODMediaButtonCoordinator.shared.reassertActiveVODOwnership(reason: "VOD scene active")
                if (forceAetherSurface || forceKSPlayerSurface), isPlaying {
                    ksPlayAssertionSerial &+= 1
                } else if !usingInternalNonAVEngine, isPlaying {
                    player?.play()
                }
                return
            }
            // v1150: force a durable checkpoint before tvOS can suspend/terminate the app.
            // This is the missing process-lifecycle edge that allowed a visible timeline to
            // disappear after swiping the app away.
            saveResumePositionIfNeeded(force: true, durable: true)
            // vBRDC193: mirror the same lifecycle edge to Trakt as a pause checkpoint.
            // Local persistence above remains authoritative/offline; Trakt is only the
            // cross-device synchronization layer.
            TraktSyncManager.shared.playbackStateChanged(
                item: item,
                seconds: authoritativeCurrentSeconds,
                duration: resolvedDurationSeconds,
                isPlaying: false
            )
            // vBRDC327: never block the MainActor with a synchronous persistence flush or
            // rebuild catalog shelves just because Control Center/app switcher covered video.
            // The durable checkpoint above already queues persistence. Catalog-derived rows
            // recover on real playback dismissal, not transient scene inactivity.
            cancelAlternateAudioForLifecycle(reason: "App backgrounded — Alternate Audio work cancelled and original audio restored.")
        }
        .onChange(of: store.playbackPresentationID) { newPresentationID in
            guard !isLivePlayback, newPresentationID != playbackPresentationID else { return }
            cancelAlternateAudioForLifecycle(reason: "Playback source or episode changed — stale Alternate Audio work cancelled.")
        }
        #if os(visionOS)
        .onChange(of: currentSeconds) { _ in
            SignalVisionPlaybackHandoff.shared.updateClock(elapsed: authoritativeCurrentSeconds, duration: resolvedDurationSeconds, isPlaying: isPlaying)
        }
        .onChange(of: durationSeconds) { _ in
            SignalVisionPlaybackHandoff.shared.updateClock(elapsed: authoritativeCurrentSeconds, duration: resolvedDurationSeconds, isPlaying: isPlaying, force: true)
        }
        .onChange(of: isPlaying) { _ in
            SignalVisionPlaybackHandoff.shared.updateClock(elapsed: authoritativeCurrentSeconds, duration: resolvedDurationSeconds, isPlaying: isPlaying, force: true)
        }
        .onChange(of: forceAetherSurface) { _ in
            SignalVisionPlaybackHandoff.shared.updateEngine(activeEngineName, avPlayer: player)
        }
        .onChange(of: forceKSPlayerSurface) { _ in
            SignalVisionPlaybackHandoff.shared.updateEngine(activeEngineName, avPlayer: player)
        }
        .onReceive(NotificationCenter.default.publisher(for: SignalVisionPlaybackHandoff.commandNotification)) { note in
            guard !isLivePlayback,
                  store.playbackPresentationID == playbackPresentationID,
                  let raw = note.object as? String,
                  let command = SignalVisionPlaybackHandoff.Command(rawValue: raw) else { return }
            switch command {
            case .togglePlayPause:
                handlePlayerPlayPausePress()
            case .rewind:
                seekRelative(-30)
            case .fastForward:
                seekRelative(60)
            case .audio:
                if forceAetherSurface || forceKSPlayerSurface, !realAudioTrackLabels.isEmpty {
                    let next = ((selectedRealAudioTrackIndex ?? -1) + 1) % realAudioTrackLabels.count
                    selectRealAudioTrack(next)
                } else {
                    cycleMedia(groupCharacteristic: .audible, label: "audio")
                }
            case .subtitles:
                if forceAetherSurface || forceKSPlayerSurface, !realSubtitleTrackLabels.isEmpty {
                    let next = ((selectedRealSubtitleTrackIndex ?? -1) + 1) % realSubtitleTrackLabels.count
                    selectRealSubtitleTrack(next)
                } else {
                    cycleMedia(groupCharacteristic: .legible, label: "subtitle")
                }
            case .productionRatings:
                vodProductionRatingsPanelEnabled.toggle()
                if vodProductionRatingsPanelEnabled { vodSpotlightHubPanelEnabled = false }
            case .spotlightHub:
                vodSpotlightHubPanelEnabled.toggle()
                if vodSpotlightHubPanelEnabled { vodProductionRatingsPanelEnabled = false }
            case .exitPlayback:
                requestPlayerDismissal()
            case .exitTheater:
                break
            }
        }
        #endif
        .signalMoveCommand { direction in
            routePlayerMove(direction)
        }
        .onTapGesture {
            handlePlayerSelectPress()
        }
        .signalVisionPlayPauseCommand {
            if BluetoothVODMediaButtonCoordinator.shared.shouldSuppressSwiftUIPlayPause() { return }
            handlePlayerPlayPausePress()
        }
        .onReceive(NotificationCenter.default.publisher(for: .debridBluetoothVODMediaCommand)) { notification in
            handleBluetoothVODMediaCommand(notification)
        }
        )
    }

    private var playerOverlayStateTree: AnyView {
        AnyView(
        playerInputTree
        .onChange(of: controlsVisible) { visible in
            if visible, let pending = pendingPlaybackMetadataItem {
                pendingPlaybackMetadataItem = nil
                applyPlaybackMetadata(pending)
            }
            if visible {
                commitPendingVODProductionMetadataIfVisible()
            }
            if !isLivePlayback {
                playbackOverlayBridge.setOverlayVisible(visible || activePanel != nil)
                PlaybackController.shared.setOverlayVisible(visible || activePanel != nil, sessionID: playbackPresentationID)
                if visible && activePanel == nil && isFirstFrameReady {
                    startPlaybackMetadataHydration(delayNanoseconds: 0)
                    // vBRDC085: Production is no longer pause-gated. Review lookup remains
                    // pause-time work, but Production may complete in the background while
                    // video continues so opening the overlay never requires Play/Pause.
                    if !isPlaying {
                        loadVODReviewScore(for: overlayItem, delayNanoseconds: 180_000_000)
                    }
                    if vodSupplementalInfoPanelEnabled {
                        loadVODProductionMetadata(for: overlayItem, delayNanoseconds: 120_000_000)
                    }
                } else if !visible {
                    vodReviewTask?.cancel()
                    vodReviewTask = nil
                    // Do not cancel the one bounded Production fetch merely because chrome
                    // auto-hid; the completed snapshot will be ready on the next reveal.
                    // vBRDC122: Cast Explorer / Episode Browser / source-switch surfaces are
                    // independently visible VOD UI. Hidden base chrome must not cancel their
                    // in-flight foreground artwork while those surfaces remain mounted.
                    if castExplorerMember == nil && !vodEpisodeBrowserVisible && pendingVODSwitchItem == nil {
                        PremiumRemoteImageLoader.releaseDecodedArtworkForHiddenVODOverlay()
                    }
                }
            }
            if visible {
                if !isLivePlayback {
                    if vodControlShelfMode == "always" {
                        setVODControlShelfExpanded(true, moveFocus: false)
                    } else if vodControlShelfMode == "hidden" {
                        setVODControlShelfExpanded(false, moveFocus: false)
                    }
                }
                livePlayerFocusTask?.cancel()
                livePlayerFocusTask = nil
                playerCanvasFocused = false
                dismissLiveQuickGuideTip()
                seedVODOverlayFocusIfNeeded()
            } else {
                if !isLivePlayback {
                    vodControlShelfHideTask?.cancel()
                    vodControlShelfHideTask = nil
                    // v1051: A hidden overlay owns no timeline focus or preview state.
                    // Directional presses are routed as direct skip commands instead.
                    focusedZone = .video
                    focusedControl = nil
                    scrubPreviewSeconds = nil
                    isScrubbingTimeline = false
                    hasAdjustedTimelineScrub = false
                }
                if isLivePlayback {
                    claimLiveTVPlayerCanvasFocus(reason: "controls hidden")
                }
                scheduleLiveQuickGuideTipIfNeeded()
            }
        }
        .onChange(of: isPlaying) { playing in
            if isLivePlayback {
                // vBRDC210: Live TV pause/resume is also system media state. Keep
                // Home Assistant/MediaRemote and Bluetooth transport ownership aligned
                // with the real player instead of permanently advertising rate 1.0.
                DebridNowPlayingManager.shared.updateLivePlaybackState(playbackPresentationID, isPlaying: playing)
                return
            }
            // vBRDC209: natural episode completion is not a user pause. The completion
            // callback only latches EOF; all bookkeeping and Up Next work waits until the
            // decoder-safe post-EOF lane. Even the forced MediaRemote/Now Playing state
            // publication is deferred so the decoder's final render turn stays uncontested.
            if !playing, vodAsyncRuntime.naturalEpisodeTransitionActive {
                schedulePostEOFUpNextWork()
                return
            }
            BluetoothVODMediaButtonCoordinator.shared.updateNowPlaying(
                sessionID: playbackPresentationID,
                title: item.title,
                duration: resolvedDurationSeconds,
                elapsed: authoritativeCurrentSeconds,
                isPlaying: playing,
                force: true
            )
            if playing {
                // vBRDC209: a provider/metadata task may have been started while the user
                // was paused near EOF. Resuming playback immediately revokes that privilege.
                // Cancel every Up Next worker so none can return to CatalogStore/MainActor
                // and publish while the current decoder is rendering again.
                upNextPreparationTask?.cancel()
                upNextPreparationTask = nil
                upNextSourcePreparationTask?.cancel()
                upNextSourcePreparationTask = nil
                upNextDecorationTask?.cancel()
                upNextDecorationTask = nil
                upNextPostEOFTask?.cancel()
                upNextPostEOFTask = nil
                upNextCountdownTask?.cancel()
                upNextCountdownTask = nil
                upNextVisible = false
                upNextAutoAdvanceArmed = false
                upNextFocusedAction = nil
                if upNextPreparation?.sourceReady != true {
                    upNextSourcePreparationAttemptCount = 0
                    vodAsyncRuntime.upNextSourceRetryNotBeforeUptime = 0
                }
                vodAsyncRuntime.naturalEpisodeTransitionActive = false
                vodAsyncRuntime.naturalEpisodeEndReason = ""
            }
            // vBRDC193: publish an immediate Trakt start/pause edge only when playback
            // state actually changes. The five-second decoder resume clock remains local,
            // so Trakt never becomes a second high-frequency playback clock.
            TraktSyncManager.shared.playbackStateChanged(
                item: item,
                seconds: authoritativeCurrentSeconds,
                duration: resolvedDurationSeconds,
                isPlaying: playing
            )
            if playing {
                // Active playback owns the machine. Cancel decorative network work that may
                // have been started while paused; existing cached values remain on screen.
                vodReviewTask?.cancel()
                vodReviewTask = nil
                // vBRDC085: Production metadata remains allowed to finish in background
                // during active playback. It is one bounded session fetch and must not be
                // tied to pausing the movie.
                runtimeLookupTask?.cancel()
                runtimeLookupTask = nil
                // vBRDC162: metadata hydration is bounded foreground-overlay state and is
                // intentionally allowed to finish after first frame while video keeps playing.
                // Cancelling it here was a direct cause of missing logos/cast on first reveal.
            } else if isFirstFrameReady {
                // vBRDC196: pause is a durable resume edge. Commit it before any optional
                // enrichment so relaunch and Continue Watching update immediately.
                saveResumePositionIfNeeded(force: true, durable: true)
                PlaybackResumeCacheManager.shared.flushSynchronously()
                store.refreshPlaybackDerivedCatalogRows()
                // Paused playback is the safe enrichment window.
                startPlaybackMetadataHydration()
                if resolvedDurationSeconds <= 1 {
                    startRuntimeMetadataLookupIfNeeded(delayNanoseconds: 150_000_000)
                }
                if controlsVisible && activePanel == nil {
                    loadVODReviewScore(for: overlayItem, delayNanoseconds: 180_000_000)
                    if vodSupplementalInfoPanelEnabled {
                        loadVODProductionMetadata(for: overlayItem, delayNanoseconds: 260_000_000)
                    }
                }
            }
        }
        .onChange(of: activePanel) { panel in
            if panel != nil {
                commitPendingVODProductionMetadataIfVisible()
            }
            if !isLivePlayback {
                playbackOverlayBridge.setOverlayVisible(controlsVisible || panel != nil)
                PlaybackController.shared.setOverlayVisible(controlsVisible || panel != nil, sessionID: playbackPresentationID)
            }
            if let panel {
                if !isLivePlayback {
                    vodControlShelfHideTask?.cancel()
                    vodControlShelfHideTask = nil
                    vodReviewTask?.cancel()
                    vodReviewTask = nil
                    // Production fetch is session-scoped and may finish behind a settings
                    // panel; no player/overlay focus state is coupled to the request.
                }
                livePlayerFocusTask?.cancel()
                livePlayerFocusTask = nil
                playerCanvasFocused = false
                dismissLiveQuickGuideTip()
                vodOverlayLockedForRemoteNavigation = true
                seedPanelFocus(panel)
            } else {
                focusedPanelOption = nil
                selectedPanelOption = nil
                vodOverlayLockedForRemoteNavigation = controlsVisible
                if isLivePlayback && !controlsVisible {
                    claimLiveTVPlayerCanvasFocus(reason: "panel closed")
                } else if !isLivePlayback && vodControlShelfExpanded {
                    scheduleVODControlShelfAutoHide()
                }
                scheduleLiveQuickGuideTipIfNeeded()
                if !isLivePlayback && controlsVisible && isFirstFrameReady {
                    if !isPlaying {
                        loadVODReviewScore(for: overlayItem, delayNanoseconds: 180_000_000)
                    }
                    if vodSupplementalInfoPanelEnabled {
                        loadVODProductionMetadata(for: overlayItem, delayNanoseconds: 120_000_000)
                    }
                }
            }
        }
        )
    }

    private var playerPlaybackStateTree: AnyView {
        AnyView(
        playerOverlayStateTree
        .onChange(of: isLoading) { loading in
            if !isLivePlayback { PlaybackController.shared.setLoading(loading, sessionID: playbackPresentationID) }
            if !loading { scheduleLiveQuickGuideTipIfNeeded() }
        }
        .onChange(of: isFirstFrameReady) { ready in
            if !isLivePlayback { PlaybackController.shared.setFirstFrameReady(ready, sessionID: playbackPresentationID) }
            if ready {
                scheduleLiveQuickGuideTipIfNeeded()
                if isLivePlayback {
                    // vBRDC210: the Live TV decoder/audio renderer may establish its own
                    // audio route after the pre-mount claim. Reassert MediaRemote ownership
                    // on the first real frame just like VOD so Bluetooth and Home Assistant
                    // see the session after the engine has fully initialized.
                    BluetoothVODMediaButtonCoordinator.shared.reassertActiveVODOwnership(reason: "Live TV first frame")
                    publishLiveTVSystemNowPlaying(claim: false)
                }
                if !isLivePlayback {
                    // vBRDC121: the concrete KS/AV playback surface can finish audio setup
                    // after the parent VOD view's initial claim. Reassert once on first frame
                    // so Bluetooth media buttons remain owned by this VOD presentation.
                    BluetoothVODMediaButtonCoordinator.shared.reassertActiveVODOwnership(reason: "VOD first frame")
                    publishVODSystemNowPlayingMetadata()
                    // vBRDC206: a completed previous episode may have deferred the expensive
                    // Trakt cloud-resume GET pair. Only release that work after the incoming
                    // episode has a stable decoder, never during the EOF/source handoff.
                    TraktSyncManager.shared.flushDeferredProgressRefreshAfterPlaybackStabilizes()
                    showVODCastExplorerOnboardingIfNeeded()
                    // v1085: first-frame presentation wins over TMDB/Stremio/credits work.
                    // Begin enrichment only after the decoder is visibly established.
                    // vBRDC076 Playback Priority: the detail screen already supplied the
                    // playback identity/artwork needed for the overlay. Remote enrichment is
                    // deferred until pause so active video owns CPU, network and compositor
                    // headroom after first frame.
                    // vBRDC162: title logo/cast identity are foreground overlay data, not
                    // pause-only decoration. Start one bounded enrichment after first frame so
                    // the first overlay reveal is complete even if playback never pauses.
                    startPlaybackMetadataHydration(delayNanoseconds: 350_000_000)
                    if !isPlaying {
                        startRuntimeMetadataLookupIfNeeded(delayNanoseconds: 1_100_000_000)
                    }
                    // vBRDC085: start the compact Production snapshot automatically after
                    // stable first frame even while the movie is playing. The fetch runs at
                    // background priority and publishes once; heavy review/runtime hydration
                    // remains pause-only to preserve vBRDC076 playback priority.
                    if vodSupplementalInfoPanelEnabled {
                        loadVODProductionMetadata(for: overlayItem, delayNanoseconds: 900_000_000)
                    }
                    if controlsVisible && activePanel == nil && !isPlaying {
                        loadVODReviewScore(for: overlayItem, delayNanoseconds: 400_000_000)
                    }
                }
            }
        }
        .onChange(of: hasStableFirstFramePlayback) { stable in
            if stable {
                // vBRDC076 Playback Priority: do not fan out next-episode metadata/network
                // work immediately after first frame. The watchdog will begin that bounded
                // preparation only inside the final six minutes, when it is actually useful.
                startUpNextWatchdogIfNeeded()
                startLocalIntroDetectionIfNeeded()
            }
        }
        .onChange(of: ksSurfaceToken) { _ in
            // A new KS generation must never inherit the outgoing source's buffer ghost.
            // Start the reserve at the current playhead; the new engine will immediately
            // extend it as its own playableTime callbacks arrive.
            if !isLivePlayback {
                let current = authoritativeCurrentSeconds
                vodAsyncRuntime.latestBufferedPlaybackSeconds = current
                bufferedPlaybackSeconds = current
            }
        }
        )
    }

    private var playerTimelineStateTree: AnyView {
        AnyView(
        playerPlaybackStateTree
        .onChange(of: currentSeconds) { _ in
            if !isLivePlayback {
                BluetoothVODMediaButtonCoordinator.shared.updateNowPlaying(
                    sessionID: playbackPresentationID,
                    title: item.title,
                    duration: resolvedDurationSeconds,
                    elapsed: authoritativeCurrentSeconds,
                    isPlaying: isPlaying
                )
            }
            if !isLivePlayback && isSeriesPlayback && detectedIntroMarker?.chapterIndex == nil && !skipIntroConsumed {
                // vBRDC048: the initial request can happen before the player exposes its exact
                // runtime. The duration-bucket guard makes this effectively free on normal ticks,
                // but permits one release-aware refresh as soon as the true duration arrives.
                startAppSideIntroSegmentLookupIfNeeded()
            }
            evaluateSkipIntroPresentation()
            // vBRDC200: Up Next has one timing owner: startUpNextWatchdogIfNeeded().
            // Do not repeat provider prep/presentation decisions on every overlay clock publish.
        }
        .onChange(of: playbackOverlayBridge.snapshot) { snapshot in
            applyPlaybackSnapshot(snapshot)
        }
        .onChange(of: store.experimentalPlaybackHandoffID) { handoffID in
            guard !isLivePlayback,
                  handoffID == nil,
                  (alternateAudioHandoffState == .switching || alternateAudioHandoffState == .active),
                  activePlaybackURL != url else { return }
            restoreOriginalAudio(
                reason: "Experimental playback rollback requested — original audio restored.",
                clearSelection: false
            )
        }
        .onChange(of: liveQuickGuideVisible) { visible in
            if visible {
                dismissLiveQuickGuideTip()
                scheduleLiveQuickGuideAutoDismiss()
                clearLiveTVDoubleBackExitArm()
            } else {
                dismissLiveQuickGuideChannelActions(rescheduleAutoDismiss: false)
                cancelLiveQuickGuideAutoDismiss()
                scheduleLiveQuickGuideTipIfNeeded()
            }
            if isLivePlayback && !controlsVisible && activePanel == nil {
                claimLiveTVPlayerCanvasFocus(reason: visible ? "quick guide opened" : "quick guide closed")
            }
        }
        .onChange(of: playerCanvasFocused) { focused in
            guard isLivePlayback else { return }
            print("[LiveTVFocus][v978] player canvas focus=\(focused)")
        }
        )
    }

    private var playerCommandTree: AnyView {
        AnyView(
        playerTimelineStateTree
        .onChange(of: focusedControl) { newFocus in
            guard let newFocus else { return }
            focusedZone = zone(for: newFocus)
            if drawerActionControlOrder.contains(newFocus) { lastKnownControlFocus = newFocus }
            if !isLivePlayback && vodControlShelfExpanded {
                scheduleVODControlShelfAutoHide()
            }
            forceControlsVisibleForNavigation(lockOverlay: true)
        }
        .signalVisionExitCommand {
            cancelLiveQuickGuideTip()
            if playbackUnityCatalogDestination != nil {
                // MediaInfoPopup owns Back while details / Source Intelligence has focus.
                // Once detail is closed, Back returns directly to the still-playing video.
                if store.selectedDetail == nil { closePlaybackUnityCatalog() }
                return
            }
            if pendingVODSwitchItem != nil {
                cancelPendingVODPlaybackSwitch()
            } else if vodEpisodeBrowserVisible {
                closeVODEpisodeBrowser()
            } else if castExplorerMember != nil {
                closeCastExplorer()
            } else if upNextVisible {
                cancelUpNextCountdown()
            } else if isLivePlayback && liveQuickGuideChannelActionsVisible {
                dismissLiveQuickGuideChannelActions()
            } else if isLivePlayback && liveQuickGuideVisible {
                dismissLiveQuickGuide(reason: "Back")
            } else if activePanel != nil {
                activePanel = nil
                selectedPanelOption = nil
                focusedPanelOption = nil
                forceControlsVisibleForNavigation()
            } else if !isLivePlayback && controlsVisible && vodControlShelfExpanded && vodControlShelfMode != "always" {
                setVODControlShelfExpanded(false, moveFocus: true)
            } else if controlsVisible {
                controlsVisible = false
                activePanel = nil
                scrubPreviewSeconds = nil
                isScrubbingTimeline = false
                hasAdjustedTimelineScrub = false
                if isLivePlayback && liveTVPlaybackDoubleBackExitEnabled {
                    armLiveTVDoubleBackExit()
                }
            } else if isLivePlayback {
                handleLiveTVPlaybackBackExitRequest()
            } else {
                requestPlayerDismissal()
            }
        }
        )
    }

    private func publishVODSystemNowPlayingMetadata() {
        guard !isLivePlayback else { return }
        let source = playbackMetadataItem ?? item
        let rawTitle = source.title.trimmingCharacters(in: .whitespacesAndNewlines)
        let isEpisode = source.seasonNumber != nil || source.episodeNumber != nil
        let seriesTitle: String? = {
            guard isEpisode else { return nil }
            let stripped = rawTitle.replacingOccurrences(
                of: #"\s+[sS]\d{1,2}[eE]\d{1,3}.*$"#,
                with: "",
                options: .regularExpression
            ).trimmingCharacters(in: .whitespacesAndNewlines)
            return stripped.isEmpty ? nil : stripped
        }()
        let episodeTitle: String = {
            guard isEpisode else { return rawTitle }
            let stripped = rawTitle.replacingOccurrences(
                of: #"^.*?\s+[sS]\d{1,2}[eE]\d{1,3}\s*[•:\-–—]*\s*"#,
                with: "",
                options: .regularExpression
            ).trimmingCharacters(in: .whitespacesAndNewlines)
            return stripped.isEmpty ? rawTitle : stripped
        }()
        let episodeLabel: String? = {
            guard let season = source.seasonNumber, let episode = source.episodeNumber else { return nil }
            return String(format: "S%02dE%02d", season, episode)
        }()
        let movieAlbum: String? = {
            let year = source.year.trimmingCharacters(in: .whitespacesAndNewlines)
            return year.isEmpty ? "Movie • Debrid Channels" : "Movie • \(year)"
        }()
        let externalID = source.tmdbId.map { "tmdb:\(isEpisode ? "tv" : "movie"):\($0)" }
            ?? source.imdbId.map { "imdb:\($0)" }
            ?? source.id

        // Keep startup/decoder priority: title/state publish immediately; artwork begins only
        // after the real player has delivered its first frame.
        let artworkURL = isFirstFrameReady ? DebridNowPlayingArtworkURL.url(source.landscapeURL ?? source.posterURL) : nil
        DebridNowPlayingManager.shared.enrichVODSession(
            playbackPresentationID,
            title: isEpisode ? episodeTitle : rawTitle,
            artist: isEpisode ? seriesTitle : "Debrid Channels",
            albumTitle: isEpisode ? episodeLabel : movieAlbum,
            externalContentID: externalID,
            assetURL: activePlaybackURL,
            contentKind: isEpisode ? .tvShow : .movie,
            artworkURL: artworkURL
        )
    }

    private func publishLiveTVSystemNowPlaying(claim: Bool) {
        guard isLivePlayback else { return }
        let channel = currentLiveQuickGuideChannel ?? liveQuickGuideSelectedChannel
        let program = channel.flatMap { liveQuickGuideModel.currentProgram(for: $0) }
        let now = Date()
        let title = program?.title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false
            ? (program?.title ?? item.title)
            : ((channel?.now.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false ? channel?.now : nil) ?? item.title)
        let channelName = channel?.name ?? item.title
        let subtitle = [channel?.number, "Live TV", channel?.category]
            .compactMap { value -> String? in
                guard let value else { return nil }
                let clean = value.trimmingCharacters(in: .whitespacesAndNewlines)
                return clean.isEmpty ? nil : clean
            }
            .joined(separator: " • ")
        let duration: Double
        let elapsed: Double
        if let start = program?.startDate, let end = program?.endDate, end > start {
            duration = end.timeIntervalSince(start)
            elapsed = min(max(0, now.timeIntervalSince(start)), duration)
        } else {
            duration = 0
            elapsed = 0
        }
        let externalID = channel.map { "live:\($0.id):\(program?.id ?? 0)" } ?? "live:\(item.id)"
        let artworkURL = isFirstFrameReady
            ? DebridNowPlayingArtworkURL.url(program?.imageURL ?? channel?.iconURL ?? item.landscapeURL ?? item.posterURL)
            : nil
        if claim {
            BluetoothVODMediaButtonCoordinator.shared.claimLiveControlSession(
                playbackPresentationID,
                title: channelName
            )
            DebridNowPlayingManager.shared.claimLiveSession(
                playbackPresentationID,
                title: title,
                channelName: channelName,
                subtitle: subtitle.isEmpty ? nil : subtitle,
                duration: duration,
                elapsed: elapsed,
                externalContentID: externalID,
                assetURL: activePlaybackURL,
                artworkURL: artworkURL
            )
        } else {
            DebridNowPlayingManager.shared.updateLiveSession(
                playbackPresentationID,
                title: title,
                channelName: channelName,
                subtitle: subtitle.isEmpty ? nil : subtitle,
                duration: duration,
                elapsed: elapsed,
                externalContentID: externalID,
                assetURL: activePlaybackURL,
                artworkURL: artworkURL
            )
        }
    }

    var body: some View {
        playerCommandTree
            .overlay(alignment: .topTrailing) {
                Button {
                    requestPlayerDismissal()
                } label: {
                    Image(systemName: "xmark")
                        .font(.system(size: 19, weight: .bold))
                        .frame(width: 48, height: 48)
                }
                .buttonStyle(.bordered)
                .hoverEffect(.highlight)
                .opacity(visionPlaybackExitHovered ? 1.0 : 0.76)
                .onHover { visionPlaybackExitHovered = $0 }
                .accessibilityLabel("Exit playback")
                .padding(.top, 12)
                .padding(.trailing, 24)
            }
    }


    private func startUpNextPreparationIfNeeded() {
        guard !isLivePlayback,
              isSeriesPlayback,
              upNextPreparationTask == nil,
              upNextPreparation == nil,
              !upNextDismissed else { return }

        let ownerPresentationID = playbackPresentationID
        let ownerURL = url
        upNextPreparationTask = Task { @MainActor in
            // vBRDC209: this task is forbidden while the current episode is playing.
            // At natural EOF the decoder-settle lane has already elapsed, so resolve the
            // next episode identity immediately. A user-paused preparation keeps the
            // historical courtesy delay.
            if !upNextNaturalEndPending {
                try? await Task.sleep(nanoseconds: isPlaying ? 350_000_000 : 1_100_000_000)
            }
            guard !Task.isCancelled,
                  store.playbackPresentationID == ownerPresentationID,
                  store.playbackURL == ownerURL else {
                upNextPreparationTask = nil
                return
            }

            let episodes = await store.fetchSeriesEpisodes(for: item, publishStatus: false)
            guard !Task.isCancelled,
                  store.playbackPresentationID == ownerPresentationID,
                  store.playbackURL == ownerURL else {
                upNextPreparationTask = nil
                return
            }
            guard let next = nextEpisode(after: item, from: episodes) else {
                upNextPreparationTask = nil
                if upNextNaturalEndPending {
                    upNextNaturalEndPending = false
                    controlsVisible = true
                    focusedControl = .playPause
                    TraktSyncManager.shared.flushDeferredProgressRefreshAfterPlaybackStabilizes()
                    store.status = "Episode completed • no next episode is currently available."
                }
                return
            }

            let enriched = await store.playbackMetadata(for: next)
            guard !Task.isCancelled,
                  store.playbackPresentationID == ownerPresentationID,
                  store.playbackURL == ownerURL else {
                upNextPreparationTask = nil
                return
            }

            // Publish identity only. Provider/source preparation remains watchdog-owned and
            // decorative next-episode work is forbidden while the current decoder is active.
            upNextMetadataItem = enriched
            upNextPreparation = UpNextEpisodePreparation(
                episode: enriched,
                rankedLinks: [],
                primaryURL: nil,
                primaryAvailability: nil,
                alternateURLs: [],
                subtitleURLs: []
            )
            upNextAlternateAudioReadiness = alternateAudioMasterEnabled ? "Deferred until playback" : "Off"
            upNextPreparationTask = nil
            // vBRDC206: the outgoing episode performs no decorative next-episode
            // metadata/intro work at EOF. The incoming episode owns that enrichment after
            // first frame; EOF is reserved for source readiness and presentation only.
            evaluateUpNextPresentation(forceAtEnd: upNextNaturalEndPending)
            if !isPlaying {
                prepareUpNextSourcesIfNeeded(force: upNextNaturalEndPending)
            }
        }
    }

    private func prefetchUpNextIntroAfterCurrentEpisodeEndsIfNeeded() {
        guard upNextNaturalEndPending,
              let target = upNextMetadataItem ?? upNextPreparation?.episode else { return }
        Task(priority: .utility) {
            await AppSideIntroSegmentService.shared.prefetch(for: target)
        }
    }

    private func loadUpNextDecorationAfterCurrentEpisodeEndsIfNeeded() {
        guard upNextNaturalEndPending,
              upNextDecorationTask == nil,
              !upNextProductionMetadata.hasUsefulContent,
              let target = upNextMetadataItem ?? upNextPreparation?.episode else { return }
        let ownerPresentationID = playbackPresentationID
        let ownerURL = url
        upNextDecorationTask = Task(priority: .background) { @MainActor in
            let snapshot = await VODProductionMetadataService.fetch(
                itemID: target.id,
                tmdbID: target.tmdbId,
                imdbID: target.imdbId,
                title: upNextSeriesTitle(from: target.title),
                year: target.year,
                type: target.type,
                seasonNumber: target.seasonNumber,
                episodeNumber: target.episodeNumber,
                apiKey: vodTMDBApiKey
            )
            guard !Task.isCancelled,
                  store.playbackPresentationID == ownerPresentationID,
                  store.playbackURL == ownerURL else { return }
            upNextProductionMetadata = snapshot
            upNextDecorationTask = nil
        }
    }

    private func prepareUpNextSourcesIfNeeded(force: Bool = false) {
        guard !isLivePlayback,
              isSeriesPlayback,
              !upNextDismissed,
              !upNextPlaybackStarting,
              upNextSourcePreparationTask == nil,
              upNextPreparation?.sourceReady != true,
              let target = upNextMetadataItem ?? upNextPreparation?.episode else { return }

        let retryUptime = ProcessInfo.processInfo.systemUptime
        if force {
            guard upNextSourcePreparationAttemptCount < 3,
                  retryUptime >= vodAsyncRuntime.upNextSourceRetryNotBeforeUptime else { return }
        } else {
            let total = resolvedDurationSeconds
            let now = authoritativeCurrentSeconds
            guard total.isFinite, total > 120, now.isFinite, now >= 0 else { return }
            let remaining = max(0, total - now)
            // vBRDC209: this branch can run only while playback is already paused/stopped.
            // The old buffer-aware prewarming still allowed Xtream/Stremio/Nuvio parsing
            // to return to CatalogStore's MainActor during the current episode and could
            // starve the video/compositor while audio continued. Active playback is now a
            // hard boundary rather than a soft buffer heuristic.
            if upNextSourcePreparationAttemptCount == 0 {
                guard remaining <= 210 else { return }
                if forceKSPlayerSurface {
                    let bufferedEndpoint = max(vodAsyncRuntime.latestBufferedPlaybackSeconds, bufferedPlaybackSeconds)
                    let bufferedHeadroom = max(0, bufferedEndpoint - now)
                    // vBRDC206: never spend the current episode's last reserve on provider
                    // discovery. If headroom is weak, wait for EOF where force=true runs
                    // after the decoder has finished instead of risking a fast-scene hitch.
                    guard bufferedHeadroom >= 24 else { return }
                }
            } else if upNextSourcePreparationAttemptCount == 1 {
                guard remaining <= 75 else { return }
                if forceKSPlayerSurface {
                    let bufferedEndpoint = max(vodAsyncRuntime.latestBufferedPlaybackSeconds, bufferedPlaybackSeconds)
                    let bufferedHeadroom = max(0, bufferedEndpoint - now)
                    guard bufferedHeadroom >= 12 else { return }
                }
            } else {
                return
            }
        }

        upNextSourcePreparationAttemptCount += 1
        let ownerPresentationID = playbackPresentationID
        let ownerURL = url
        upNextSourcePreparationTask = Task { @MainActor in
            let preparation = await store.prepareUpNextEpisodeSources(for: target)
            guard !Task.isCancelled,
                  !isPlaying,
                  store.playbackPresentationID == ownerPresentationID,
                  store.playbackURL == ownerURL else {
                upNextSourcePreparationTask = nil
                return
            }

            upNextPreparation = preparation
            upNextSourcePreparationTask = nil
            if preparation.sourceReady {
                vodAsyncRuntime.upNextSourceRetryNotBeforeUptime = 0
            } else {
                // 2s, 4s, then 8s minimum spacing. The old 500 ms watchdog could
                // immediately relaunch a full provider fan-out after an EOF miss.
                let delay: Double
                switch upNextSourcePreparationAttemptCount {
                case ...1: delay = 2
                case 2: delay = 4
                default: delay = 8
                }
                vodAsyncRuntime.upNextSourceRetryNotBeforeUptime = ProcessInfo.processInfo.systemUptime + delay
            }
            upNextAlternateAudioReadiness = alternateAudioMasterEnabled
                ? (preparation.sourceReady ? "Available after episode starts" : "No prepared source")
                : "Off"

            evaluateUpNextPresentation(forceAtEnd: upNextNaturalEndPending)
            if upNextVisible, preparation.sourceReady { upNextFocusedAction = .play }
            armUpNextAutoAdvanceIfNeeded(forceAtEnd: upNextNaturalEndPending)
            // vBRDC200: Alternate Audio discovery is intentionally deferred to the incoming
            // episode. It is informational here and must not spend network/CPU during current VOD.
        }
    }

    private func nextEpisode(after current: MediaItem, from episodes: [MediaItem]) -> MediaItem? {
        guard let currentSeason = current.seasonNumber,
              let currentEpisode = current.episodeNumber else { return nil }
        return episodes
            .filter { ($0.seasonNumber ?? 0) > 0 && ($0.episodeNumber ?? 0) > 0 }
            .sorted { lhs, rhs in
                let left = (lhs.seasonNumber ?? 0, lhs.episodeNumber ?? 0)
                let right = (rhs.seasonNumber ?? 0, rhs.episodeNumber ?? 0)
                return left.0 == right.0 ? left.1 < right.1 : left.0 < right.0
            }
            .first { episode in
                let season = episode.seasonNumber ?? 0
                let number = episode.episodeNumber ?? 0
                return season > currentSeason || (season == currentSeason && number > currentEpisode)
            }
    }

    private func evaluateUpNextPresentation(forceAtEnd: Bool = false) {
        guard !isLivePlayback,
              isSeriesPlayback,
              !isPlaying,
              !upNextDismissed,
              !upNextVisible,
              upNextPreparation != nil,
              pendingVODSwitchItem == nil else { return }

        if forceAtEnd {
            // Natural EOF is authoritative and must not wait for another Siri Remote event.
            // Retire ordinary VOD chrome that could otherwise keep the Up Next surface gated.
            activePanel = nil
            castExplorerMember = nil
            vodEpisodeBrowserVisible = false
            controlsVisible = false
            focusedControl = nil
            focusedPanelOption = nil
        } else {
            guard activePanel == nil,
                  castExplorerMember == nil,
                  !vodEpisodeBrowserVisible else { return }
        }

        let total = resolvedDurationSeconds
        let now = authoritativeCurrentSeconds
        guard now.isFinite, now >= 0 else { return }
        if !forceAtEnd {
            guard total.isFinite, total > 120 else { return }
            let remaining = max(0, total - now)
            // App-side clock authority: surface Up Next about 75–120 seconds before EOF.
            let threshold = min(120.0, max(75.0, total * 0.10))
            guard remaining <= threshold else { return }
        }

        upNextVisible = true
        upNextCountdownSeconds = 15
        upNextAutoAdvanceArmed = false
        controlsVisible = false
        focusedControl = nil
        focusedPanelOption = nil
        playerCanvasFocused = false
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.10) {
            upNextFocusedAction = upNextPreparation?.sourceReady == true ? .play : .cancel
        }
        armUpNextAutoAdvanceIfNeeded(forceAtEnd: forceAtEnd)
    }

    private func armUpNextAutoAdvanceIfNeeded(forceAtEnd: Bool = false) {
        guard !isPlaying,
              upNextVisible,
              !upNextAutoAdvanceArmed,
              upNextPreparation?.sourceReady == true else { return }
        let total = resolvedDurationSeconds
        let now = authoritativeCurrentSeconds
        let remaining = total > 0 ? max(0, total - now) : 0
        guard forceAtEnd || remaining <= 15 else { return }
        upNextAutoAdvanceArmed = true
        // Natural completion is now fully serviced by the app. Clear the pending EOF
        // latch only after a playable next source exists and the countdown is armed.
        if forceAtEnd { upNextNaturalEndPending = false }
        if forceAtEnd || remaining <= 0.5 {
            upNextCountdownSeconds = 15
        } else {
            upNextCountdownSeconds = max(1, min(15, Int(ceil(remaining))))
        }
        startUpNextCountdown()
    }

    private func startUpNextWatchdogIfNeeded() {
        guard !isLivePlayback,
              isSeriesPlayback,
              upNextWatchdogTask == nil else { return }
        let ownerPresentationID = playbackPresentationID
        let ownerURL = url
        upNextWatchdogTask = Task { @MainActor in
            while !Task.isCancelled,
                  store.playbackPresentationID == ownerPresentationID,
                  store.playbackURL == ownerURL {
                evaluateSkipIntroPresentation()

                let now = authoritativeCurrentSeconds
                let total = resolvedDurationSeconds
                let remaining = total > 0 ? max(0, total - now) : Double.greatestFiniteMagnitude

                // vBRDC209: current video is the absolute resource owner. CatalogStore is
                // @MainActor and the full Up Next resolver performs provider JSON decoding,
                // ranking and preflights there after its network awaits. None of that is
                // permitted while the outgoing episode is actively decoding/rendering.
                // Resolve only next-episode identity near the end while the current decoder
                // is still playing. This is lightweight metadata work and lets both AetherEngine
                // and KSPlayer show Up Next before EOF. Provider/source preparation remains
                // decoder-safe and runs only after pause/EOF.
                if upNextPreparation == nil, !upNextDismissed, (upNextNaturalEndPending || remaining <= 180) {
                    startUpNextPreparationIfNeeded()
                }
                if !isPlaying {
                    prepareUpNextSourcesIfNeeded(force: upNextNaturalEndPending)
                    evaluateUpNextPresentation(forceAtEnd: upNextNaturalEndPending)
                    armUpNextAutoAdvanceIfNeeded(forceAtEnd: upNextNaturalEndPending)
                } else if remaining <= 120 {
                    evaluateUpNextPresentation(forceAtEnd: false)
                }

                // Third app-side EOF authority. KSPlayer/AVPlayer completion callbacks remain
                // primary, but a stream that never emits a clean completion event is treated
                // as ended only when the local clock is effectively at EOF. vBRDC206 shrinks the
                // old ~1.25s early trigger so Trakt/source work never starts over the final frames.
                if total.isFinite, total > 30,
                   now.isFinite, now > 5,
                   remaining <= 1.50,
                   !upNextNaturalEndPending,
                   !upNextDismissed,
                   !upNextPlaybackStarting {
                    handleNaturalEpisodeEnd(reason: "Apple TV playback clock reached episode end")
                    // Some container/decoder combinations never emit a clean ended callback.
                    // Marking the UI clock stopped here does not pause/seek the decoder; it
                    // only opens the post-EOF lane after the 300 ms settle delay below.
                    if isPlaying { isPlaying = false }
                }

                let introNeedsPrecision = detectedIntroMarker.map { !skipIntroConsumed && now < $0.endSeconds + 1 } ?? false
                let sleepSeconds: Double
                if introNeedsPrecision || remaining <= 150 {
                    sleepSeconds = 0.50
                } else if remaining <= 360 {
                    sleepSeconds = 2.0
                } else {
                    sleepSeconds = 8.0
                }
                try? await Task.sleep(nanoseconds: UInt64(sleepSeconds * 1_000_000_000))
            }
            upNextWatchdogTask = nil
        }
    }

    private func handleNaturalEpisodeEnd(reason: String) {
        guard !isLivePlayback,
              isSeriesPlayback,
              !upNextPlaybackStarting,
              !vodAsyncRuntime.naturalEpisodeTransitionActive else { return }

        // vBRDC209: the completion callback itself is a zero-work latch. In particular,
        // do NOT send Trakt, flush/clear resume state, fetch episode metadata, resolve
        // providers, decode Up Next artwork, or mutate catalog shelves while KSPlayer/
        // AVPlayer may still be flushing its final video frame. Audio can continue from
        // its queue while the video/compositor is starved, which produced the reported
        // frozen/glitching picture at episode end.
        vodAsyncRuntime.naturalEpisodeTransitionActive = true
        vodAsyncRuntime.naturalEpisodeEndReason = reason
        upNextNaturalEndPending = true
        // The watchdog has finished its only remaining job once EOF is latched. Cancel it
        // now so it cannot wake during the decoder-settle window and accidentally bypass
        // the post-EOF owner by starting metadata/provider work on its next iteration.
        upNextWatchdogTask?.cancel()
        upNextWatchdogTask = nil
        store.status = "Episode completion detected; preserving the final video frame before Up Next."
    }

    private func schedulePostEOFUpNextWork() {
        guard !isLivePlayback,
              isSeriesPlayback,
              vodAsyncRuntime.naturalEpisodeTransitionActive,
              !isPlaying,
              upNextPostEOFTask == nil else { return }

        let ownerPresentationID = playbackPresentationID
        let ownerURL = url
        upNextPostEOFTask = Task { @MainActor in
            // Let the outgoing video renderer/decoder complete its flush before any
            // provider/catalog/UI work is allowed to claim MainActor or compositor time.
            try? await Task.sleep(nanoseconds: 300_000_000)
            guard !Task.isCancelled,
                  store.playbackPresentationID == ownerPresentationID,
                  store.playbackURL == ownerURL,
                  vodAsyncRuntime.naturalEpisodeTransitionActive,
                  !isPlaying else {
                upNextPostEOFTask = nil
                return
            }

            let reason = vodAsyncRuntime.naturalEpisodeEndReason
            // Now that the renderer has had its settle window, publish the stopped state
            // to MediaRemote/Home Assistant. This used to happen in the decoder callback
            // turn and is intentionally part of the post-EOF lane now.
            BluetoothVODMediaButtonCoordinator.shared.updateNowPlaying(
                sessionID: playbackPresentationID,
                title: item.title,
                duration: resolvedDurationSeconds,
                elapsed: authoritativeCurrentSeconds,
                isPlaying: false,
                force: true
            )
            // Completion bookkeeping is intentionally after decoder settle. These remain
            // once-per-episode because naturalEpisodeTransitionActive rejects duplicates.
            TraktSyncManager.shared.markCompleted(
                item: item,
                duration: resolvedDurationSeconds,
                deferProgressRefresh: true
            )
            PlaybackResumeCacheManager.shared.clear(for: item)
            LocalIntroDetectionEngine.shared.finishSession(item: item, presentationID: playbackPresentationID)

            if upNextDismissed {
                upNextNaturalEndPending = false
                controlsVisible = true
                focusedControl = .playPause
                vodAsyncRuntime.naturalEpisodeTransitionActive = false
                TraktSyncManager.shared.flushDeferredProgressRefreshAfterPlaybackStabilizes()
                store.status = "Episode completed; Up Next was dismissed for this episode (\(reason))."
                upNextPostEOFTask = nil
                return
            }

            // From this point onward the current decoder is stopped. It is now safe for
            // CatalogStore's @MainActor provider resolver and Up Next UI to do work.
            if upNextPreparation == nil {
                startUpNextPreparationIfNeeded()
            } else {
                prepareUpNextSourcesIfNeeded(force: true)
                evaluateUpNextPresentation(forceAtEnd: true)
                armUpNextAutoAdvanceIfNeeded(forceAtEnd: true)
            }
            store.status = "Up Next resolving after decoder-safe episode completion (\(reason))."
            upNextPostEOFTask = nil
        }
    }

    private func startLocalIntroDetectionIfNeeded() {
        guard !isLivePlayback,
              isSeriesPlayback,
              !skipIntroConsumed else { return }

        // vBRDC045: resolve a known episode opening from public timestamp metadata in
        // parallel with the existing local detector. A late 5-minute intro can therefore
        // be armed from the episode identity instead of waiting for 12 seconds of audio.
        startAppSideIntroSegmentLookupIfNeeded()

        if let marker = LocalIntroDetectionEngine.shared.currentMarker(
            item: item,
            presentationID: playbackPresentationID
        ) {
            acceptLocalIntroMarker(marker, presentationID: playbackPresentationID)
            return
        }

        // KSPlayer publishes chapters continuously through its local player callback.
        // If AVPlayer is active instead, read its local timed chapter metadata directly.
        if !forceAetherSurface && !forceKSPlayerSurface && !forceVLCSurface {
            publishLocalAVPlayerChaptersIfAvailable()
        }
    }

    private func startAppSideIntroSegmentLookupIfNeeded() {
        guard introSegmentLookupTask == nil,
              !isLivePlayback,
              isSeriesPlayback,
              !skipIntroConsumed,
              item.seasonNumber != nil,
              item.episodeNumber != nil else { return }

        let ownerPresentationID = playbackPresentationID
        let ownerURL = url
        let lookupItem = item
        let duration = resolvedDurationSeconds.isFinite && resolvedDurationSeconds > 0
            ? resolvedDurationSeconds
            : nil
        let durationBucket = duration.map { Int(($0 / 5.0).rounded()) * 5 } ?? 0
        guard introSegmentLookupDurationBucket != durationBucket else { return }
        introSegmentLookupDurationBucket = durationBucket

        introSegmentLookupTask = Task { @MainActor in
            let marker = await AppSideIntroSegmentService.shared.marker(
                for: lookupItem,
                durationSeconds: duration
            )
            guard !Task.isCancelled,
                  store.playbackPresentationID == ownerPresentationID,
                  store.playbackURL == ownerURL else { return }
            introSegmentLookupTask = nil
            if let marker {
                acceptLocalIntroMarker(marker, presentationID: ownerPresentationID)
            }
        }
    }

    private func handleLocalIntroChapters(_ chapters: [PlaybackChapterMarker], presentationID: UUID) {
        guard presentationID == playbackPresentationID,
              !isLivePlayback,
              isSeriesPlayback,
              !skipIntroConsumed else { return }
        if let marker = LocalIntroDetectionEngine.shared.registerChapters(
            chapters,
            item: item,
            presentationID: presentationID
        ) {
            acceptLocalIntroMarker(marker, presentationID: presentationID)
        }
    }

    private func handleLocalAudioFingerprint(_ sample: PlaybackAudioFingerprintSample, presentationID: UUID) {
        guard let marker = LocalIntroDetectionEngine.shared.ingestFingerprint(
            sample,
            item: item,
            presentationID: presentationID
        ) else { return }
        // Decoded audio arrives off MainActor. The detector itself is lock-protected;
        // only the tiny marker result crosses back to SwiftUI's main presentation state.
        DispatchQueue.main.async {
            acceptLocalIntroMarker(marker, presentationID: presentationID)
        }
    }

    @MainActor
    private func acceptLocalIntroMarker(_ marker: VODIntroMarker, presentationID: UUID) {
        guard presentationID == playbackPresentationID,
              store.playbackPresentationID == presentationID,
              store.playbackURL == url,
              !isLivePlayback,
              isSeriesPlayback,
              !skipIntroConsumed,
              marker.isStorySafe else { return }
        // Exact-file chapter > community episode authorities > learned local audio. A trusted
        // episode marker is also fed back into the tiny local learner so one known episode can
        // teach later database gaps. The following episode still requires a real audio match.
        if marker.authorityRank >= 425 {
            LocalIntroDetectionEngine.shared.registerTrustedEpisodeMarker(
                marker,
                item: item,
                presentationID: presentationID
            )
        }
        if let current = detectedIntroMarker {
            let sameProviderRefinement = marker.authorityRank == current.authorityRank &&
                marker.provider?.lowercased() == current.provider?.lowercased() &&
                marker != current
            if marker.authorityRank > current.authorityRank || sameProviderRefinement {
                // A duration-aware refresh from the same provider is allowed to refine the
                // startup no-duration result. Exact embedded chapters still outrank everything.
                detectedIntroMarker = marker
            }
        } else {
            detectedIntroMarker = marker
        }
        evaluateSkipIntroPresentation()
    }

    private func publishLocalAVPlayerChaptersIfAvailable() {
        guard let asset = player?.currentItem?.asset else { return }
        let preferred = Array(Set(Locale.preferredLanguages + ["en", "und"]))
        Task { @MainActor in
            guard let groups = try? await asset.loadChapterMetadataGroups(bestMatchingPreferredLanguages: preferred) else { return }
            let chapters: [PlaybackChapterMarker] = groups.compactMap { group in
            let start = group.timeRange.start.seconds
            let duration = group.timeRange.duration.seconds
            guard start.isFinite, duration.isFinite, duration > 0 else { return nil }
            let title = group.items.compactMap { item -> String? in
                if item.commonKey?.rawValue == AVMetadataKey.commonKeyTitle.rawValue,
                   let value = item.stringValue?.trimmingCharacters(in: .whitespacesAndNewlines),
                   !value.isEmpty { return value }
                return nil
            }.first ?? ""
            guard !title.isEmpty else { return nil }
            return PlaybackChapterMarker(startSeconds: max(0, start), endSeconds: start + duration, title: title)
        }
            guard !chapters.isEmpty, player?.currentItem?.asset === asset else { return }
            handleLocalIntroChapters(chapters, presentationID: playbackPresentationID)
        }
    }

    private func evaluateSkipIntroPresentation() {
        guard !isLivePlayback,
              isSeriesPlayback,
              isFirstFrameReady,
              !isLoading,
              !skipIntroConsumed,
              !upNextVisible,
              activePanel == nil,
              castExplorerMember == nil,
              !vodEpisodeBrowserVisible,
              pendingVODSwitchItem == nil,
              let marker = detectedIntroMarker,
              marker.isStorySafe else { return }
        let now = authoritativeCurrentSeconds
        guard now.isFinite else { return }

        if now >= marker.endSeconds - 0.75 {
            dismissSkipIntroPrompt(consumed: true)
            return
        }
        // A 1.5s lead lets the chip appear as the named chapter begins without ever
        // seeking on its own. Only Select performs the skip.
        guard now >= max(0, marker.startSeconds - 1.5), now < marker.endSeconds - 0.75 else { return }
        guard !skipIntroVisible else { return }

        skipIntroVisible = true
        skipIntroCountdownSeconds = max(1, Int(ceil(marker.endSeconds - now)))
        startSkipIntroCountdown()
    }

    private func startSkipIntroCountdown() {
        skipIntroCountdownTask?.cancel()
        skipIntroCountdownTask = Task { @MainActor in
            while !Task.isCancelled, skipIntroVisible {
                guard let marker = detectedIntroMarker else {
                    dismissSkipIntroPrompt(consumed: false)
                    return
                }
                let now = authoritativeCurrentSeconds
                if now >= marker.endSeconds - 0.75 {
                    dismissSkipIntroPrompt(consumed: true)
                    return
                }
                // If the user scrubbed back before the verified opening, hide without
                // consuming it. The ordinary playback clock will present it again on re-entry.
                if now < max(0, marker.startSeconds - 2.5) {
                    dismissSkipIntroPrompt(consumed: false)
                    return
                }
                skipIntroCountdownSeconds = max(1, Int(ceil(marker.endSeconds - now)))
                try? await Task.sleep(nanoseconds: 500_000_000)
            }
        }
    }

    private func dismissSkipIntroPrompt(consumed: Bool) {
        skipIntroCountdownTask?.cancel()
        skipIntroCountdownTask = nil
        skipIntroVisible = false
        if consumed { skipIntroConsumed = true }
    }

    private func performSkipIntro() {
        guard skipIntroVisible,
              let marker = detectedIntroMarker,
              marker.isStorySafe else { return }
        let now = authoritativeCurrentSeconds
        guard now < marker.endSeconds - 0.25 else {
            dismissSkipIntroPrompt(consumed: true)
            return
        }
        let target = min(marker.endSeconds + 0.20, max(marker.endSeconds, resolvedDurationSeconds - 0.5))
        let delta = max(0, target - now)
        dismissSkipIntroPrompt(consumed: true)
        seekAbsolute(target, directionSeconds: delta, revealControls: false, precise: true)
        store.status = "Skipped verified intro ‘\(marker.title)’; story playback resumes at \(formatTime(target))."
    }

    private func startUpNextCountdown() {
        upNextCountdownTask?.cancel()
        upNextCountdownTask = Task { @MainActor in
            while !Task.isCancelled, upNextVisible, upNextCountdownSeconds > 0 {
                try? await Task.sleep(nanoseconds: 1_000_000_000)
                guard !Task.isCancelled, upNextVisible else { return }
                upNextCountdownSeconds -= 1
            }
            guard !Task.isCancelled,
                  upNextVisible,
                  upNextCountdownSeconds <= 0 else { return }
            playPreparedUpNextEpisode()
        }
    }

    private func cancelUpNextCountdown() {
        upNextCountdownTask?.cancel()
        upNextCountdownTask = nil
        upNextVisible = false
        upNextAutoAdvanceArmed = false
        upNextDismissed = true
        upNextFocusedAction = nil
        playerCanvasFocused = false
        showControlsWithoutChangingFocus()
        seedVODOverlayFocusIfNeeded()
        store.status = "Up Next countdown cancelled for this episode."
    }

    private func playPreparedUpNextEpisode() {
        guard !upNextPlaybackStarting,
              let preparation = upNextPreparation,
              let primaryURL = preparation.primaryURL else { return }
        upNextPlaybackStarting = true
        upNextCountdownTask?.cancel()
        upNextCountdownTask = nil
        upNextVisible = false
        upNextAutoAdvanceArmed = false
        upNextFocusedAction = nil
        // vBRDC206: once a playable next source is committed, retire every outgoing
        // Up Next owner before CatalogStore publishes the replacement presentation.
        upNextWatchdogTask?.cancel()
        upNextWatchdogTask = nil
        upNextPreparationTask?.cancel()
        upNextPreparationTask = nil
        upNextSourcePreparationTask?.cancel()
        upNextSourcePreparationTask = nil
        upNextDecorationTask?.cancel()
        upNextDecorationTask = nil
        PlaybackResumeCacheManager.shared.clear(for: item)

        let rememberedLink = preparation.rankedLinks.first(where: { link in
            CatalogStore.makePlayableURL(from: link.url) == primaryURL
        }) ?? preparation.rankedLinks.first
        if let primaryLink = rememberedLink {
            PerTitlePlaybackMemoryManager.shared.rememberSource(primaryLink, for: preparation.episode)
            LastPlaybackLinkCacheManager.shared.save(item: preparation.episode, link: primaryLink, url: primaryURL)
        }

        store.startPlayback(
            item: preparation.episode,
            url: primaryURL,
            alternates: preparation.alternateURLs,
            subtitles: preparation.subtitleURLs,
            headers: rememberedLink?.requestHeaders.playbackHTTPHeaderDictionary ?? [:],
            fallbackHeaders: store.playbackHeaderMap(from: preparation.rankedLinks),
            label: "Up Next • \(compactEpisodeLabel(preparation.episode)) • \(preparation.providerLabel) • \(preparation.qualityLabel) • \(preparation.readinessLabel.lowercased())",
            adaptiveCacheHint: rememberedLink?.sourceIntelligenceAdaptiveCacheHint ?? ""
        )
    }

    private func routeUpNextMove(_ direction: SignalMoveDirection) {
        switch direction {
        case .left:
            if upNextPreparation?.sourceReady == true { upNextFocusedAction = .play }
        case .right:
            upNextFocusedAction = .cancel
        case .up, .down:
            break
        default:
            break
        }
    }

    private func compactEpisodeLabel(_ episode: MediaItem) -> String? {
        guard let season = episode.seasonNumber, let number = episode.episodeNumber else { return nil }
        return "S\(season)E\(number)"
    }

    private func upNextDisplayTitle(for episode: MediaItem) -> String {
        var title = episode.title
        let parent = upNextSeriesTitle(from: item.title)
        if !parent.isEmpty, title.lowercased().hasPrefix(parent.lowercased()) {
            title = String(title.dropFirst(parent.count))
        }
        title = title.replacingOccurrences(of: #"^\s*[•:\-–—]*\s*"#, with: "", options: .regularExpression)
        title = title.replacingOccurrences(of: #"^S\d{1,2}E\d{1,3}\s*"#, with: "", options: [.regularExpression, .caseInsensitive])
        let clean = title.trimmingCharacters(in: .whitespacesAndNewlines)
        return clean.isEmpty ? (compactEpisodeLabel(episode) ?? "Next Episode") : clean
    }

    private func upNextSeriesTitle(from raw: String) -> String {
        raw.replacingOccurrences(of: #"\s+[sS]\d{1,2}[eE]\d{1,3}.*$"#, with: "", options: .regularExpression)
            .replacingOccurrences(of: #"\s+\d{1,2}x\d{1,3}.*$"#, with: "", options: .regularExpression)
            .trimmingCharacters(in: .whitespacesAndNewlines)
    }

    @MainActor
    private func stopOwnedPlaybackKitSession(reason: String) {
        playbackOverlayBridge.disconnect()
        guard PlaybackController.shared.ownsSession(playbackPresentationID) else {
            print("[PlaybackKit][v1054] ignored stale VOD teardown reason=\(reason) session=\(playbackPresentationID)")
            return
        }
        PlaybackController.shared.beginPresentationDismissal(sessionID: playbackPresentationID)
        PlaybackController.shared.suspendRenderHost(sessionID: playbackPresentationID)
        PlaybackController.shared.detachRenderHost(sessionID: playbackPresentationID)
        PlaybackController.shared.stop(sessionID: playbackPresentationID)
    }

    /// v992 ordered dismissal: stop the session-owned render host while the player
    /// screen still owns the hierarchy, then publish playbackURL=nil only after KSPlayer
    /// teardown has completed a render turn. This prevents player destruction, catalog
    /// remounting, artwork decoding, and focus restoration from colliding on MainActor.
    private func requestPlayerDismissal() {
        guard !isDismissingPlayer else { return }
        isDismissingPlayer = true
        isPlaying = false
        controlsVisible = false
        activePanel = nil
        focusedControl = nil
        focusedPanelOption = nil

        playerDismissalTask?.cancel()

        // vBRDC078: finish all synchronous player/session teardown while VOD still owns
        // the hierarchy. Previously onDisappear repeated teardownPlayer() after the grid
        // had already begun remounting, including a second synchronous resume-cache flush.
        // That could leave a visible catalog with no responsive focus owner.
        teardownPlayer()
        if !isLivePlayback {
            stopOwnedPlaybackKitSession(reason: "player dismissal requested")
        }
        orderedPlayerTeardownCompleted = true

        playerDismissalTask = Task { @MainActor in
            await Task.yield()
            try? await Task.sleep(nanoseconds: 140_000_000)
            guard !Task.isCancelled else { return }
            // Clear the task before publishing playbackURL=nil so onDisappear cannot
            // cancel the task that is currently performing the close/remount handoff.
            playerDismissalTask = nil
            store.closePlayer(expectedPresentationID: playbackPresentationID, expectedURL: url)
        }
    }

    private func claimLiveTVPlayerCanvasFocus(reason: String) {
        guard isLivePlayback, activePanel == nil, !controlsVisible else { return }
        livePlayerFocusTask?.cancel()
        livePlayerFocusTask = Task { @MainActor in
            // Clear stale grid/chrome focus bindings first, then claim focus only after
            // the full-screen player has completed a render turn. A short second turn
            // makes the handoff deterministic across loading and first-frame changes.
            focusedControl = nil
            focusedPanelOption = nil
            playerCanvasFocused = false
            await Task.yield()
            try? await Task.sleep(nanoseconds: 45_000_000)
            guard !Task.isCancelled,
                  isLivePlayback,
                  activePanel == nil,
                  !controlsVisible,
                  store.playbackPresentationID == playbackPresentationID,
                  store.playbackURL == url else { return }
            playerCanvasFocused = true
            await Task.yield()
            try? await Task.sleep(nanoseconds: 75_000_000)
            guard !Task.isCancelled,
                  isLivePlayback,
                  activePanel == nil,
                  !controlsVisible,
                  store.playbackPresentationID == playbackPresentationID,
                  store.playbackURL == url else { return }
            if !playerCanvasFocused {
                playerCanvasFocused = true
            }
            print("[LiveTVFocus][v978] claimed player canvas reason=\(reason)")
            livePlayerFocusTask = nil
        }
    }

    private var shouldShowLiveQuickGuideTip: Bool {
        isLivePlayback &&
        liveQuickGuideTipVisible &&
        !controlsVisible &&
        activePanel == nil &&
        !liveQuickGuideVisible &&
        !isLoading &&
        isFirstFrameReady &&
        errorText == nil
    }

