    private func scheduleLiveQuickGuideTipIfNeeded() {
        guard isLivePlayback, !liveQuickGuideTipShown, !controlsVisible, activePanel == nil, !liveQuickGuideVisible, !isLoading, isFirstFrameReady, errorText == nil else { return }
        liveQuickGuideTipTask?.cancel()
        liveQuickGuideTipTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: 900_000_000)
            guard !Task.isCancelled, isLivePlayback, !liveQuickGuideTipShown, !controlsVisible, activePanel == nil, !liveQuickGuideVisible, !isLoading, isFirstFrameReady, errorText == nil else { return }
            withAnimation(.easeOut(duration: 0.20)) {
                liveQuickGuideTipVisible = true
            }
            liveQuickGuideTipShown = true
            try? await Task.sleep(nanoseconds: 30_000_000_000)
            guard !Task.isCancelled else { return }
            withAnimation(.easeOut(duration: 0.18)) {
                liveQuickGuideTipVisible = false
            }
        }
    }

    private func dismissLiveQuickGuideTip() {
        liveQuickGuideTipTask?.cancel()
        liveQuickGuideTipTask = nil
        if liveQuickGuideTipVisible {
            withAnimation(.easeOut(duration: 0.14)) {
                liveQuickGuideTipVisible = false
            }
        }
        if isLivePlayback {
            liveQuickGuideTipShown = true
        }
    }

    private func cancelLiveQuickGuideTip() {
        liveQuickGuideTipTask?.cancel()
        liveQuickGuideTipTask = nil
        liveQuickGuideTipVisible = false
    }

    private func configureInitialVODControlShelfState() {
        guard !isLivePlayback else { return }
        switch vodControlShelfMode {
        case "always":
            vodControlShelfExpanded = true
        case "remember":
            vodControlShelfExpanded = vodControlShelfLastExpanded
        default:
            vodControlShelfExpanded = false
        }
        if vodControlShelfExpanded {
            scheduleVODControlShelfAutoHide()
        }
    }

    private func toggleVODControlShelf() {
        guard !isLivePlayback else { return }
        setVODControlShelfExpanded(!vodControlShelfExpanded, moveFocus: true)
    }

    private func setVODControlShelfExpanded(_ expanded: Bool, moveFocus: Bool) {
        guard !isLivePlayback else { return }
        let resolvedExpanded = vodControlShelfMode == "always" ? true : expanded
        vodControlShelfHideTask?.cancel()
        vodControlShelfHideTask = nil
        withAnimation(.spring(response: 0.34, dampingFraction: 0.86)) {
            vodControlShelfExpanded = resolvedExpanded
        }
        if vodControlShelfMode == "remember" {
            vodControlShelfLastExpanded = resolvedExpanded
        }
        if moveFocus {
            if resolvedExpanded {
                // v1047: Opening the drawer is a focus transition, not a seek action.
                // Any untouched timeline snapshot is discarded without calling seekAbsolute.
                if !hasAdjustedTimelineScrub {
                    scrubPreviewSeconds = nil
                    isScrubbingTimeline = false
                    hasAdjustedTimelineScrub = false
                }
                focusedZone = .chips
                let target = drawerActionControlOrder.contains(lastKnownControlFocus) ? lastKnownControlFocus : .playPause
                focusedControl = target
            } else {
                // v1051: Collapsed controls park focus on the chevron. The timeline is
                // visible as information but cannot highlight or scrub until expanded.
                focusedZone = .chips
                focusedControl = .controlDrawer
                scrubPreviewSeconds = nil
                isScrubbingTimeline = false
                hasAdjustedTimelineScrub = false
            }
        }
        if resolvedExpanded {
            scheduleVODControlShelfAutoHide()
        }
    }

    private func scheduleVODControlShelfAutoHide() {
        guard !isLivePlayback,
              vodControlShelfExpanded,
              activePanel == nil,
              controlsVisible,
              vodControlShelfMode != "always",
              vodControlShelfAutoHideSeconds > 0 else { return }
        vodControlShelfHideTask?.cancel()
        let delay = UInt64(vodControlShelfAutoHideSeconds) * 1_000_000_000
        vodControlShelfHideTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: delay)
            guard !Task.isCancelled,
                  !isLivePlayback,
                  vodControlShelfExpanded,
                  activePanel == nil,
                  controlsVisible else { return }
            setVODControlShelfExpanded(false, moveFocus: true)
        }
    }

    private func ensureVODChipsFocused(lockOverlay: Bool = true) {
        if lockOverlay { vodOverlayLockedForRemoteNavigation = true }
        forceControlsVisibleForNavigation(lockOverlay: lockOverlay)
        if isLivePlayback {
            if focusedControl == nil || !chipControlOrder.contains(focusedControl!) {
                if !drawerActionControlOrder.contains(lastKnownControlFocus) { lastKnownControlFocus = .playPause }
                focusedZone = .chips
                focusedControl = lastKnownControlFocus
            }
            didSeedVODOverlayFocus = true
            return
        }
        if isScrubbingTimeline {
            focusedZone = .timeline
            focusedControl = .timeline
        } else if vodControlShelfExpanded {
            focusedZone = .chips
            focusedControl = drawerActionControlOrder.contains(lastKnownControlFocus) ? lastKnownControlFocus : .playPause
            scheduleVODControlShelfAutoHide()
        } else {
            focusedZone = .chips
            focusedControl = .controlDrawer
            scrubPreviewSeconds = nil
            isScrubbingTimeline = false
            hasAdjustedTimelineScrub = false
        }
        didSeedVODOverlayFocus = true
    }

    private var primaryControlOrder: [PlayerControl] {
        if isLivePlayback { return [.quickGuide, .playPause, .catalogHome, .catalogMovies, .catalogShows] }
        // vBRDC264: the visible first VOD chip is Player Engine. Keeping the retired .resume
        // focus target here made tvOS focus/activation disagree with the rendered chip and
        // could invoke forceResumeFromSavedPosition(), which looked like an unexplained rewind.
        return [.playerEngine, .restart, .playPause, .back10, .forward10, .catalogHome, .catalogMovies, .catalogShows]
    }

    private var secondaryControlOrder: [PlayerControl] {
        if isLivePlayback { return [.audio, .subtitles, .settings, .close] }
        var controls: [PlayerControl] = [.audio, .subtitles, .zoom]
        if isSeriesPlayback { controls.append(.episodes) }
        controls += [.externalPlayer, .settings]
        return controls
    }

    private var drawerActionControlOrder: [PlayerControl] {
        primaryControlOrder + secondaryControlOrder
    }

    private var chipControlOrder: [PlayerControl] {
        if isLivePlayback { return drawerActionControlOrder }
        if vodControlShelfExpanded { return [.controlDrawer] + drawerActionControlOrder }
        return [.controlDrawer]
    }

    private var allOverlayControlOrder: [PlayerControl] {
        chipControlOrder + [.timeline]
    }

    private func zone(for control: PlayerControl) -> PlayerFocusZone {
        if control == .timeline { return .timeline }
        if chipControlOrder.contains(control) { return .chips }
        return .video
    }

    private func handlePlayerSelectPress() {
        if playbackUnityCatalogDestination != nil { return }
        if pendingVODSwitchItem != nil || vodEpisodeBrowserVisible || castExplorerMember != nil { return }
        if skipIntroVisible {
            performSkipIntro()
            return
        }
        if isLivePlayback && liveQuickGuideChannelActionsVisible { return }
        if isLivePlayback && Date() < liveQuickGuideSuppressSelectUntil { return }
        if upNextVisible {
            let fallbackAction: UpNextAction = upNextPreparation?.sourceReady == true ? .play : .cancel
            switch upNextFocusedAction ?? fallbackAction {
            case .play: playPreparedUpNextEpisode()
            case .cancel: cancelUpNextCountdown()
            }
            return
        }
        if isLivePlayback && liveQuickGuideVisible { playLiveQuickGuideSelection(); return }
        if activePanel != nil { activateFocusedPanelOption(); return }
        if !controlsVisible { ensureVODChipsFocused(lockOverlay: true); return }
        if focusedControl == .controlDrawer {
            toggleVODControlShelf()
            return
        }
        if focusedZone == .timeline || isScrubbingTimeline {
            playerAction { commitTimelineScrubOrToggleFocus() }
            return
        }
        if focusedZone == .video {
            playerAction { togglePlay() }
            return
        }
        if focusedZone == .cast {
            // The focused cast surface owns Select and opens Cast Explorer itself.
            // Do not let the parent VOD canvas steal focus back to the chip scroller.
            return
        }
        ensureVODChipsFocused(lockOverlay: true)
        activateFocusedPlayerControl()
    }

    private func handlePlayerPlayPausePress() {
        if playbackUnityCatalogDestination != nil { return }
        if isLivePlayback && liveQuickGuideChannelActionsVisible { return }
        if isLivePlayback && Date() < liveQuickGuideSuppressSelectUntil { return }
        // Phase 14: Cast Explorer owns playback pause state. Siri Remote Play/Pause
        // cannot resume or toggle the underlying movie until the explorer closes.
        guard castExplorerMember == nil,
              !vodEpisodeBrowserVisible,
              pendingVODSwitchItem == nil else { return }
        playerAction { togglePlay() }
    }

    private let liveQuickGuideBaseCategories = ["All", "My Favorites", "HD", "Favorites", "Sports", "Drama", "News", "Kids"]

    private var liveQuickGuideAllChannels: [LiveTVChannel] {
        let loaded = liveQuickGuideModel.channels.isEmpty ? [] : liveQuickGuideModel.channels
        return loaded.isEmpty ? LiveTVScreen.sampleChannels : loaded
    }

    private var liveQuickGuideFavoriteChannelIDs: Set<Int> {
        Set(liveQuickGuideFavoriteChannelIdsRaw
            .split(separator: ",")
            .compactMap { Int($0.trimmingCharacters(in: .whitespacesAndNewlines)) })
    }

    private var liveQuickGuideSportsManualChannelIDs: Set<Int> {
        Set(liveQuickGuideSportsManualChannelIdsRaw
            .split(separator: ",")
            .compactMap { Int($0.trimmingCharacters(in: .whitespacesAndNewlines)) })
    }

    private var liveQuickGuideCategories: [String] {
        var output = liveQuickGuideBaseCategories
        for category in liveQuickGuideAllChannels.map(\.category) {
            let trimmed = category.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !trimmed.isEmpty, trimmed != "Movies", !output.contains(trimmed) else { continue }
            output.append(trimmed)
        }
        return output
    }

    private func liveQuickGuideChannels(for category: String) -> [LiveTVChannel] {
        let channels = liveQuickGuideAllChannels
        switch category {
        case "All":
            return channels
        case "My Favorites":
            return channels.filter { liveQuickGuideFavoriteChannelIDs.contains($0.id) }
        case "HD":
            return channels.filter {
                $0.category == "HD" || (Int($0.number) ?? 0) >= 6000 || $0.name.localizedCaseInsensitiveContains("HD")
            }
        default:
            return channels.filter { $0.category == category }
        }
    }

    private var liveQuickGuideChannels: [LiveTVChannel] {
        let validCategory = liveQuickGuideCategories.contains(liveQuickGuideCategory) ? liveQuickGuideCategory : "All"
        return liveQuickGuideChannels(for: validCategory)
    }

    private var currentLiveQuickGuideChannel: LiveTVChannel? {
        liveQuickGuideAllChannels.first(where: { $0.name == item.title || "live-\($0.id)-\($0.streamURL.hashValue)" == item.id })
    }

    private var liveQuickGuideCategoryWindow: [String] {
        let categories = liveQuickGuideCategories
        guard !categories.isEmpty else { return ["All"] }
        let currentIndex = categories.firstIndex(of: liveQuickGuideCategory) ?? 0
        if categories.count <= 3 { return categories }
        let previous = (currentIndex - 1 + categories.count) % categories.count
        let next = (currentIndex + 1) % categories.count
        return [categories[previous], categories[currentIndex], categories[next]]
    }

    private struct LiveQuickGuideCategoryChip: View {
        let category: String
        let selected: Bool
        let compact: Bool

        private var fontSize: CGFloat {
            if selected { return compact ? 14 : 16 }
