    private func syncLiveQuickGuideIndexToCurrentChannel() {
        liveQuickGuideModel.loadPlaybackQuickGuideSnapshot()
        liveQuickGuideModel.refreshPlaybackQuickGuideSnapshot()
        if !liveQuickGuideCategories.contains(liveQuickGuideCategory) {
            liveQuickGuideCategory = "All"
        }
        let channels = liveQuickGuideChannels
        if let idx = channels.firstIndex(where: { $0.name == item.title || "live-\($0.id)-\($0.streamURL.hashValue)" == item.id }) {
            liveQuickGuideIndex = idx
        } else if liveQuickGuideIndex >= channels.count {
            liveQuickGuideIndex = max(0, channels.count - 1)
        }
    }

    private func moveLiveQuickGuide(_ delta: Int) {
        let channels = liveQuickGuideChannels
        guard !channels.isEmpty else { return }
        liveQuickGuideIndex = min(max(liveQuickGuideIndex + delta, 0), channels.count - 1)
    }

    private func moveLiveQuickGuideCategory(_ delta: Int) {
        let categories = liveQuickGuideCategories
        guard !categories.isEmpty else { return }
        let current = categories.firstIndex(of: liveQuickGuideCategory) ?? 0
        let next = (current + delta + categories.count) % categories.count
        liveQuickGuideCategory = categories[next]
        let filtered = liveQuickGuideChannels(for: liveQuickGuideCategory)
        if let currentChannel = currentLiveQuickGuideChannel,
           let idx = filtered.firstIndex(where: { $0.id == currentChannel.id }) {
            liveQuickGuideIndex = idx
        } else {
            liveQuickGuideIndex = 0
        }
        liveQuickGuideModel.refreshPlaybackQuickGuideSnapshot()
        scheduleLiveQuickGuideBoundaryRefresh(reason: "Quick Guide category changed")
    }

    private func isLiveQuickGuideFavorite(_ channel: LiveTVChannel) -> Bool {
        liveQuickGuideFavoriteChannelIDs.contains(channel.id)
    }

    private func liveQuickGuideFavoriteActionTitle(for channel: LiveTVChannel) -> String {
        isLiveQuickGuideFavorite(channel) ? "Remove from My Favorites" : "Add to My Favorites"
    }

    private func toggleLiveQuickGuideFavorite(_ channel: LiveTVChannel) {
        var ids = liveQuickGuideFavoriteChannelIDs
        if ids.contains(channel.id) {
            ids.remove(channel.id)
        } else {
            ids.insert(channel.id)
        }
        liveQuickGuideFavoriteChannelIdsRaw = ids.sorted().map(String.init).joined(separator: ",")
        if liveQuickGuideCategory == "My Favorites", liveQuickGuideChannels(for: "My Favorites").isEmpty {
            liveQuickGuideCategory = "All"
            syncLiveQuickGuideIndexToCurrentChannel()
        } else {
            liveQuickGuideIndex = min(liveQuickGuideIndex, max(0, liveQuickGuideChannels.count - 1))
        }
    }

    private func isLiveQuickGuideManualSportsChannel(_ channel: LiveTVChannel) -> Bool {
        liveQuickGuideSportsManualChannelIDs.contains(channel.id)
    }

    private func liveQuickGuideSportsActionTitle(for channel: LiveTVChannel) -> String {
        isLiveQuickGuideManualSportsChannel(channel) ? "Remove from Sports" : "Add to Sports"
    }

    private func toggleLiveQuickGuideManualSportsChannel(_ channel: LiveTVChannel) {
        var ids = liveQuickGuideSportsManualChannelIDs
        if ids.contains(channel.id) {
            ids.remove(channel.id)
            store.status = "Removed \(channel.name) from Sports Hub."
        } else {
            ids.insert(channel.id)
            store.status = "Added \(channel.name) to Sports Hub."
        }
        liveQuickGuideSportsManualChannelIdsRaw = ids.sorted().map(String.init).joined(separator: ",")
    }

    private func presentLiveQuickGuideChannelActions(for channel: LiveTVChannel) {
        guard liveQuickGuideVisible else { return }
        if let index = liveQuickGuideChannels.firstIndex(where: { $0.id == channel.id }) {
            liveQuickGuideIndex = index
        }
        liveQuickGuideChannelActionPresentedAt = Date()
        cancelLiveQuickGuideAutoDismiss()
        withAnimation(.easeOut(duration: 0.16)) {
            liveQuickGuideChannelActionsVisible = true
        }
        DispatchQueue.main.async {
            liveQuickGuideChannelActionFocus = .favorite
        }
    }

    private func dismissLiveQuickGuideChannelActions(rescheduleAutoDismiss: Bool = true) {
        liveQuickGuideChannelActionFocus = nil
        if liveQuickGuideChannelActionsVisible {
            withAnimation(.easeOut(duration: 0.14)) {
                liveQuickGuideChannelActionsVisible = false
            }
        }
        if rescheduleAutoDismiss && liveQuickGuideVisible {
            scheduleLiveQuickGuideAutoDismiss()
        }
    }

