    private func liveQuickGuideChannelActionButton(
        title: String,
        systemImage: String,
        focus: LiveQuickGuideChannelActionFocus,
        action: @escaping () -> Void
    ) -> some View {
        let selected = liveQuickGuideChannelActionFocus == focus
        let chipShape = RoundedRectangle(cornerRadius: 18, style: .continuous)
        let foregroundColor: Color = selected ? .black : .white.opacity(0.92)
        let fillColor: Color = selected ? .white : .white.opacity(0.08)
        let strokeColor: Color = selected ? .white.opacity(0.96) : .white.opacity(0.12)
        let strokeWidth: CGFloat = selected ? 2 : 1
        let focusScale: CGFloat = selected ? 1.012 : 1.0

        // vBRDC023 compile correction: type-erase the visual-only portion of this
        // tiny two-button Quick Guide action row so Xcode does not have to solve
        // the entire SwiftUI modifier graph as one generic expression. Focus,
        // command handling, timing guards, appearance, and behavior are unchanged.
        let row = AnyView(
            HStack(spacing: 15) {
                Image(systemName: systemImage)
                    .font(.system(size: 21, weight: .bold))
                    .frame(width: 28)
                Text(title)
                    .font(.system(size: 23, weight: .bold, design: .rounded))
                    .lineLimit(1)
                Spacer(minLength: 0)
            }
        )

        let styledRow = AnyView(
            row
                .foregroundStyle(foregroundColor)
                .padding(.horizontal, 20)
                .frame(height: 64)
                .background(chipShape.fill(fillColor))
                .overlay(chipShape.stroke(strokeColor, lineWidth: strokeWidth))
                .contentShape(chipShape)
                .clipShape(chipShape)
                .compositingGroup()
        )

        return styledRow
            .focusable(true)
            .focused($liveQuickGuideChannelActionFocus, equals: focus)
            .signalVisionFocusEffectPolicy()
            .scaleEffect(focusScale)
            .animation(.easeOut(duration: 0.12), value: selected)
            .onTapGesture {
                guard Date().timeIntervalSince(liveQuickGuideChannelActionPresentedAt) >= 0.38 else { return }
                liveQuickGuideSuppressSelectUntil = Date().addingTimeInterval(0.8)
                action()
            }
            .signalVisionPlayPauseCommand {
                guard Date().timeIntervalSince(liveQuickGuideChannelActionPresentedAt) >= 0.38 else { return }
                liveQuickGuideSuppressSelectUntil = Date().addingTimeInterval(0.8)
                action()
            }
    }

    private func playLiveQuickGuideSelection() {
        guard let channel = liveQuickGuideSelectedChannel, let originalURL = URL(string: channel.streamURL), !channel.streamURL.isEmpty else { return }
        dismissLiveQuickGuideChannelActions(rescheduleAutoDismiss: false)
        // Rebind this channel to the persistent process-wide guide before the new
        // playback generation is published. The departing player is not allowed to
        // erase the shared snapshot used by the incoming channel session.
        liveQuickGuideModel.refreshPlaybackQuickGuideSnapshot(activeChannelID: channel.id)
        let routeLabel = "Live TV direct stream: \(channel.name) • \(channel.logo) • \(channel.tvgID) • \(channel.source) • \(channel.number) • quick guide selection"
        let cbsProfile = LiveTVCBSChannelsDVRProfile.profile(for: channel, routeLabel: routeLabel) ?? LiveTVCBSChannelsDVRProfile.profile(for: originalURL, channelName: channel.name, logo: channel.logo, tvgID: channel.tvgID, source: channel.source, number: channel.number, routeLabel: routeLabel)
        liveQuickGuideVisible = false
        store.startPlayback(
            item: MediaItem(id: "live-\(channel.id)-\(channel.streamURL.hashValue)", title: channel.name, year: "Live", type: "live", catalog: channel.source, description: channel.description, genres: [channel.category, channel.source], rating: "", posterURL: channel.iconURL, landscapeURL: nil, logoURL: nil, previewURL: nil),
            url: cbsProfile?.finalURL ?? originalURL,
            alternates: [],
            subtitles: [],
            label: cbsProfile.map { routeLabel + " • \($0.debugLabel)" } ?? routeLabel
        )
    }

    private func cancelLiveQuickGuideAutoDismiss() {
        liveQuickGuideAutoDismissTask?.cancel()
        liveQuickGuideAutoDismissTask = nil
    }

    private func scheduleLiveQuickGuideAutoDismiss() {
        guard isLivePlayback, liveQuickGuideVisible, !liveQuickGuideChannelActionsVisible else {
            cancelLiveQuickGuideAutoDismiss()
            return
        }
        cancelLiveQuickGuideAutoDismiss()
        let ownerPresentationID = playbackPresentationID
        let ownerURL = url
        liveQuickGuideAutoDismissTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: 10_000_000_000)
            guard !Task.isCancelled,
                  store.playbackPresentationID == ownerPresentationID,
                  store.playbackURL == ownerURL,
                  liveQuickGuideVisible else { return }
            dismissLiveQuickGuide(reason: "10-second inactivity")
        }
    }

    private func dismissLiveQuickGuide(reason: String) {
        dismissLiveQuickGuideChannelActions(rescheduleAutoDismiss: false)
        cancelLiveQuickGuideAutoDismiss()
        guard liveQuickGuideVisible else { return }
        withAnimation(.easeOut(duration: 0.18)) { liveQuickGuideVisible = false }
        print("[LiveTVQuickGuide][v1168] closed reason=\(reason)")
    }

    private func clearLiveTVDoubleBackExitArm() {
        livePlaybackExitBackTask?.cancel()
        livePlaybackExitBackTask = nil
        livePlaybackExitBackArmed = false
    }

    private func armLiveTVDoubleBackExit() {
        clearLiveTVDoubleBackExitArm()
        livePlaybackExitBackArmed = true
        playbackNotice = "Press Back again to exit Live TV"
        livePlaybackExitBackTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: 2_000_000_000)
            guard !Task.isCancelled else { return }
            livePlaybackExitBackArmed = false
            livePlaybackExitBackTask = nil
            if playbackNotice == "Press Back again to exit Live TV" {
                playbackNotice = ""
            }
        }
    }

    private func handleLiveTVPlaybackBackExitRequest() {
        guard isLivePlayback else {
            requestPlayerDismissal()
            return
        }
        guard liveTVPlaybackDoubleBackExitEnabled else {
            requestPlayerDismissal()
            return
        }
        if livePlaybackExitBackArmed {
            clearLiveTVDoubleBackExitArm()
            requestPlayerDismissal()
            return
        }
        armLiveTVDoubleBackExit()
    }

    private func scheduleLiveQuickGuideBoundaryRefresh(reason: String) {
        guard isLivePlayback else { return }
        liveQuickGuideRefreshTask?.cancel()
        liveQuickGuideRefreshTask = nil

        let now = Date()
        let channel = currentLiveQuickGuideChannel ?? liveQuickGuideSelectedChannel
        let program = channel.flatMap { liveQuickGuideModel.currentProgram(for: $0) }
        guard let boundary = program?.endDate, boundary > now else { return }

        let delay = max(0.20, boundary.timeIntervalSince(now) + 0.12)
        let expectedPresentationID = store.playbackPresentationID
        liveQuickGuideRefreshTask = Task { @MainActor in
            do {
                try await Task.sleep(nanoseconds: UInt64(delay * 1_000_000_000))
            } catch { return }
            guard !Task.isCancelled,
                  store.playbackPresentationID == expectedPresentationID,
                  store.playbackURL == url else { return }

            // Rebind once at the actual programme boundary. This replaces the old 5-second
            // MainActor loop that rebuilt channel matching/current-next state while video
            // was decoding even when Quick Guide was closed.
            let targetChannelID = liveQuickGuideVisible
                ? (liveQuickGuideSelectedChannel?.id ?? currentLiveQuickGuideChannel?.id)
                : currentLiveQuickGuideChannel?.id
            liveQuickGuideModel.refreshPlaybackQuickGuideSnapshot(activeChannelID: targetChannelID)
            publishLiveTVSystemNowPlaying(claim: false)
            liveQuickGuideRefreshTask = nil
            scheduleLiveQuickGuideBoundaryRefresh(reason: "program boundary")
        }
    }

    private func seedVODOverlayFocusIfNeeded() {
        guard controlsVisible else { return }
        guard !didSeedVODOverlayFocus || focusedControl == nil else { return }
        didSeedVODOverlayFocus = true
        if isScrubbingTimeline {
            focusedZone = .timeline
            focusedControl = .timeline
        } else if !isLivePlayback && !vodControlShelfExpanded {
            focusedZone = .chips
            focusedControl = .controlDrawer
            scrubPreviewSeconds = nil
            isScrubbingTimeline = false
            hasAdjustedTimelineScrub = false
        } else if focusedControl == nil || !allOverlayControlOrder.contains(focusedControl!) {
            if !drawerActionControlOrder.contains(lastKnownControlFocus) { lastKnownControlFocus = .playPause }
            focusedZone = .chips
            focusedControl = drawerActionControlOrder.contains(lastKnownControlFocus) ? lastKnownControlFocus : .playPause
        } else if let focusedControl {
            focusedZone = zone(for: focusedControl)
        }
    }


    @MainActor
    private func openPlaybackUnityCatalog(_ destination: PlaybackUnityCatalogDestination) {
        guard playbackUnityCatalogDestination == nil else {
            playbackUnityCatalogDestination = destination
            return
        }

        // The video/audio session is deliberately untouched. We only transfer focus from
        // player chrome to the existing catalog and open a narrowly-scoped interaction lane.
        activePanel = nil
        selectedPanelOption = nil
        focusedPanelOption = nil
        liveQuickGuideVisible = false
        liveQuickGuideChannelActionsVisible = false
        cancelLiveQuickGuideAutoDismiss()
        controlsVisible = false
        playerCanvasFocused = false
        focusedControl = nil
        store.selectedDetail = nil
        store.setPlaybackUnityBrowseActive(true, reason: "\(isLivePlayback ? "Live TV" : "VOD") -> \(destination.title)")
        playbackUnityCatalogDestination = destination
    }

    @MainActor
    private func closePlaybackUnityCatalog() {
        guard playbackUnityCatalogDestination != nil || store.playbackUnityBrowseActive else { return }
        store.cancelCurrentStreamSearch(reason: "Playback UNITY browser closed.", publishState: false)
        store.selectedDetail = nil
        playbackUnityCatalogDestination = nil
        store.setPlaybackUnityBrowseActive(false, reason: "returned to active playback")

        if isLivePlayback {
            controlsVisible = false
            focusedControl = nil
            claimLiveTVPlayerCanvasFocus(reason: "playback UNITY browser closed")
        } else {
            controlsVisible = true
            vodOverlayLockedForRemoteNavigation = true
            if vodControlShelfMode == "hidden" {
                focusedZone = .chips
                focusedControl = .controlDrawer
            } else {
                setVODControlShelfExpanded(true, moveFocus: false)
                focusedZone = .chips
                focusedControl = .catalogHome
            }
        }
    }

    private func activateFocusedPlayerControl() {
        if activePanel != nil {
            activateFocusedPanelOption()
            return
        }
        lastKnownControlFocus = focusedControl ?? lastKnownControlFocus
        switch focusedControl ?? lastKnownControlFocus {
        case .controlDrawer: toggleVODControlShelf()
        case .quickGuide:
            syncLiveQuickGuideIndexToCurrentChannel()
            withAnimation(.easeOut(duration: 0.18)) { liveQuickGuideVisible = true }
        case .resume: playerAction { forceResumeFromSavedPosition() }
        case .restart: playerAction { seekAbsolute(0, directionSeconds: -authoritativeCurrentSeconds, revealControls: true, markAutomaticResume: false, precise: false) }
        case .timeline: playerAction { commitTimelineScrubOrToggleFocus() }
        case .back10: playerAction { seekRelative(-30) }
        case .playPause: playerAction { togglePlay() }
        case .forward10: playerAction { seekRelative(60) }
        case .catalogHome: openPlaybackUnityCatalog(.home)
        case .catalogMovies: openPlaybackUnityCatalog(.movies)
        case .catalogShows: openPlaybackUnityCatalog(.shows)
        case .ksplayer: playerAction { switchToKSPlayerEngine(manual: true) }
        case .avplayer: playerAction { switchToAVPlayerEngine(manual: true) }
        case .internalVLC: playerAction { switchToVLCEngine(manual: true) }
        case .playerEngine:
            // Opening/focusing the engine selector is a UI-only operation. Never seek,
            // checkpoint, recreate, or pause a player until a different engine is chosen.
            activePanel = .engine
            seedPanelFocus(.engine)
            forceControlsVisibleForNavigation()
        case .audio: playerAction { activePanel = .audio; seedPanelFocus(.audio); forceControlsVisibleForNavigation() }
        case .findAudio: playerAction { findAlternateAudio() }
        case .subtitles: playerAction { activePanel = .subtitles; seedPanelFocus(.subtitles); forceControlsVisibleForNavigation() }
        case .episodes: playerAction { activePanel = .episodes; seedPanelFocus(.episodes); store.status = "Episode selector is wired into the Apple-style VOD overlay and ready for series episode rows."; forceControlsVisibleForNavigation() }
        case .zoom: playerAction { activePanel = .videoFit; seedPanelFocus(.videoFit); forceControlsVisibleForNavigation() }
        case .settings: playerAction { activePanel = .settings; seedPanelFocus(.settings); forceControlsVisibleForNavigation() }
        case .infuse: playerAction { openExternal(.infuse) }
        case .vlc: playerAction { openExternal(.vlc) }
        case .senplayer: playerAction { openExternal(.senPlayer) }
        case .externalPlayer: playerAction { activePanel = .external; seedPanelFocus(.external); forceControlsVisibleForNavigation() }
        case .close: playerAction { requestPlayerDismissal() }
        }
    }

    private func playerAction(_ action: () -> Void) {
        let now = Date().timeIntervalSinceReferenceDate
        guard now - lastPlayerActionAt > 0.44 else { return }
        lastPlayerActionAt = now
        action()
    }

    // v1051: Timeline preview creation is intentionally unavailable while the
    // overlay is hidden or the drawer is collapsed. Hidden Left/Right commands
    // perform direct relative seeks; preview scrubbing exists only when expanded.

    private func claimVODTimelineFocusAfterDrawerMount() {
        guard !isLivePlayback else { return }
        // Remove Featured Cast from the native focus graph immediately, then claim the
        // timeline one run-loop turn after the expanded shelf is mounted. Assigning the
        // FocusState in the same transaction that creates the scrubber lets tvOS ignore
        // the request and geometrically fall back to the poster/cast surface.
        focusedZone = .timeline
        focusedControl = nil
        DispatchQueue.main.async {
            guard !isLivePlayback,
                  controlsVisible,
                  vodControlShelfExpanded,
                  activePanel == nil,
                  pendingVODSwitchItem == nil,
                  !vodEpisodeBrowserVisible,
                  castExplorerMember == nil else { return }
            focusedZone = .timeline
            focusedControl = .timeline
        }
    }

    private func revealVODControlDrawerWithoutSeeking() {
        guard !isLivePlayback else { return }
        // Discard every passive preview snapshot before changing focus. No call to
        // seekAbsolute or commitTimelineScrubIfNeeded is permitted on this path.
        scrubPreviewSeconds = nil
        isScrubbingTimeline = false
        hasAdjustedTimelineScrub = false
        vodOverlayLockedForRemoteNavigation = true
        forceControlsVisibleForNavigation(lockOverlay: true)
        setVODControlShelfExpanded(true, moveFocus: false)
        // v1141: the first UP/DOWN that reveals VOD controls lands on the scrubber.
        // Featured Cast cannot geometrically steal this transition.
        claimVODTimelineFocusAfterDrawerMount()
    }

    private func routePlayerMove(_ direction: SignalMoveDirection) {
        if playbackUnityCatalogDestination != nil { return }
        if isLivePlayback && liveQuickGuideChannelActionsVisible {
            switch direction {
            case .up, .left: liveQuickGuideChannelActionFocus = .favorite
            case .down, .right: liveQuickGuideChannelActionFocus = .sports
            default: break
            }
            return
        }
        // Cast Explorer owns native tvOS focus while open. Do not route its DPAD events
        // into seeking, playback controls, Quick Guide, or the VOD panel router.
        if pendingVODSwitchItem != nil || vodEpisodeBrowserVisible || castExplorerMember != nil { return }
        if upNextVisible {
            routeUpNextMove(direction)
            return
        }
        if activePanel == nil,
           controlsVisible,
           focusedZone == .chips,
           (direction == .left || direction == .right),
           (isLivePlayback || vodControlShelfExpanded) {
            return
        }
        let now = Date().timeIntervalSinceReferenceDate
        let moveDebounce: TimeInterval = activePanel != nil ? 0.42 : ((focusedZone == .chips && !isLivePlayback) ? 0.34 : ((focusedZone == .timeline && !isLivePlayback) ? 0.18 : (isLivePlayback ? 0.34 : 0.32)))
        guard now - lastPlayerMoveAt > moveDebounce else { return }
        lastPlayerMoveAt = now

        if let panel = activePanel {
            routePanelMove(direction, panel: panel)
            return
        }

        if liveQuickGuideVisible {
            switch direction {
            case .left: moveLiveQuickGuide(-1)
            case .right: moveLiveQuickGuide(1)
            case .up: moveLiveQuickGuideCategory(-1)
            case .down: moveLiveQuickGuideCategory(1)
            default: break
            }
            scheduleLiveQuickGuideAutoDismiss()
            return
        }

        if !controlsVisible {
            if isLivePlayback, direction == .up || direction == .down {
                dismissLiveQuickGuideTip()
                syncLiveQuickGuideIndexToCurrentChannel()
                withAnimation(.easeOut(duration: 0.18)) { liveQuickGuideVisible = true }
            } else if !isLivePlayback {
                switch direction {
                // v1051 three-state input contract:
                // overlay hidden → direct skip, Δt = -30/+60 and overlay remains hidden;
                // drawer collapsed → no scrub focus;
                // drawer expanded → preview/commit timeline scrubbing.
                case .left: seekRelative(-30, revealControls: false)
                case .right: seekRelative(60, revealControls: false)
                case .up, .down: revealVODControlDrawerWithoutSeeking()
                default: break
                }
            }
            return
        }

        vodOverlayLockedForRemoteNavigation = true
        showControlsWithoutChangingFocus()
        switch focusedZone {
        case .cast:
            switch direction {
            case .down:
                focusedZone = .timeline
                focusedControl = .timeline
                scrubPreviewSeconds = nil
                isScrubbingTimeline = false
                hasAdjustedTimelineScrub = false
            case .up:
                featuredCastFocusRequestToken &+= 1
            case .left:
                moveFeaturedCast(by: -1)
            case .right:
                moveFeaturedCast(by: 1)
            default: break
            }
        case .video:
            switch direction {
            case .left: seekRelative(-30)
            case .right: seekRelative(60)
            case .down:
                focusedZone = .timeline
                focusedControl = .timeline
                scrubPreviewSeconds = nil
                isScrubbingTimeline = false
                hasAdjustedTimelineScrub = false
            case .up:
                focusedZone = .video
                focusedControl = nil
            default: break
            }
        case .timeline:
            // Defensive gate: timeline movement exists only while the control shelf is
            // expanded. A stale FocusState can never create a deferred hidden seek.
            guard isLivePlayback || vodControlShelfExpanded else {
                focusedZone = .chips
                focusedControl = .controlDrawer
                scrubPreviewSeconds = nil
                isScrubbingTimeline = false
                hasAdjustedTimelineScrub = false
                return
            }
            switch direction {
            case .left: scrubTimelineAndSeek(by: -30)
            case .right: scrubTimelineAndSeek(by: 60)
            case .up:
                if hasAdjustedTimelineScrub {
                    commitTimelineScrubIfNeeded()
                } else {
                    scrubPreviewSeconds = nil
                    isScrubbingTimeline = false
                    hasAdjustedTimelineScrub = false
                }
                if !isLivePlayback && !vodControlShelfExpanded {
                    revealVODControlDrawerWithoutSeeking()
                } else if !isLivePlayback, vodFeaturedCastPresentationMode != .off {
                    focusedZone = .cast
                    focusedControl = nil
                    featuredCastFocusRequestToken &+= 1
                } else {
                    focusedZone = .video
                    focusedControl = nil
                }
            case .down:
                commitTimelineScrubIfNeeded()
                focusedZone = .chips
                if !isLivePlayback && !vodControlShelfExpanded {
                    focusedControl = .controlDrawer
                } else {
                    focusedControl = drawerActionControlOrder.contains(lastKnownControlFocus) ? lastKnownControlFocus : .playPause
                }
            default: break
            }
        case .chips:
            switch direction {
            case .left, .right:
                // With the drawer collapsed, the chevron is the sole focus target and
                // directional movement cannot manipulate the timeline. When expanded,
                // tvOS handles horizontal chip-to-chip focus before this route.
                break
            case .up:
                if !isLivePlayback && !vodControlShelfExpanded {
                    setVODControlShelfExpanded(true, moveFocus: false)
                }
                scrubPreviewSeconds = nil
                isScrubbingTimeline = false
                hasAdjustedTimelineScrub = false
                claimVODTimelineFocusAfterDrawerMount()
            case .down:
                if !isLivePlayback && vodControlShelfExpanded && vodControlShelfMode != "always" {
                    setVODControlShelfExpanded(false, moveFocus: true)
                }
            default: break
            }
        }
    }

    private var manuallyNavigableFeaturedCast: [CastMember] {
        let source: [CastMember]
        if !overlayItem.castMembers.isEmpty {
            source = overlayItem.castMembers
        } else {
            source = overlayItem.cast
                .filter { !$0.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
                .map { CastMember(name: $0, role: nil, imageURL: nil) }
        }
        return source.filter { member in
            let raw = member.imageURL?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
            guard let url = URL(string: raw), let scheme = url.scheme?.lowercased() else { return false }
            return scheme == "http" || scheme == "https"
        }
    }

    private func moveFeaturedCast(by delta: Int) {
        let members = manuallyNavigableFeaturedCast
        guard focusedZone == .cast, members.count > 1, delta != 0 else { return }
        let current = max(featuredCastSpotlightIndex, 0) % members.count
        let next = (current + delta % members.count + members.count) % members.count
        guard next != current else { return }

        withAnimation(.easeInOut(duration: 0.30)) {
            featuredCastSpotlightIndex = next
        }
        // Restart the existing visible-only seven-second rotation hold from the newly
        // selected member so auto-rotation cannot immediately override a manual choice.
        featuredCastManualNavigationToken &+= 1
    }

    private func moveChipFocus(in order: [PlayerControl], direction: SignalMoveDirection, fallback: PlayerControl) {
        guard !order.isEmpty else { return }
        let current = focusedControl.flatMap { order.contains($0) ? $0 : nil } ?? fallback
        let idx = order.firstIndex(of: current) ?? 0
        let nextIndex = direction == .left ? (idx - 1 + order.count) % order.count : (idx + 1) % order.count
        focusedControl = order[nextIndex]
        lastKnownControlFocus = focusedControl ?? lastKnownControlFocus
        scrubPreviewSeconds = nil
        isScrubbingTimeline = false
        hasAdjustedTimelineScrub = false
    }

    private func moveControlFocusVertically(up: Bool) {
        if up {
            focusedZone = .timeline
            focusedControl = .timeline
            scrubPreviewSeconds = nil
            isScrubbingTimeline = false
            hasAdjustedTimelineScrub = false
        } else if !isLivePlayback && vodControlShelfExpanded && vodControlShelfMode != "always" {
            setVODControlShelfExpanded(false, moveFocus: true)
        } else {
            focusedZone = .chips
            if focusedControl == nil || !chipControlOrder.contains(focusedControl!) {
                focusedControl = !isLivePlayback && !vodControlShelfExpanded
                    ? .controlDrawer
                    : (drawerActionControlOrder.contains(lastKnownControlFocus) ? lastKnownControlFocus : .playPause)
            }
        }
    }

    private func panelOptionsList(_ panel: PlayerPanel) -> [PlayerPanelOption] {
        switch panel {
        case .audio:
            let realAudioOptions = realAudioTrackLabels.indices.map { PlayerPanelOption.audioTrack($0) }
            let embedded = realAudioOptions.isEmpty ? [.audioNext] : realAudioOptions
            guard alternateAudioMasterEnabled else { return embedded + [.alternateAudioToggle, .closePanel] }
            return embedded + [.alternateAudioToggle, .findAlternateAudio] + store.alternateAudioSources.indices.map { PlayerPanelOption.alternateAudio($0) } + [.alternateAudioPrepareBridge, .alternateAudioMinus250, .alternateAudioPlus250, .alternateAudioReset, .alternateAudioRestoreOriginal, .alternateAudioClear, .closePanel]
        case .subtitles:
            let realSubtitleOptions = realSubtitleTrackLabels.indices.map { PlayerPanelOption.subtitleTrack($0) }
            return [.subtitlesOff] + realSubtitleOptions + [.subtitleDelayMinus250, .subtitleDelayPlus250, .subtitleDelayReset, .closePanel]
        case .episodes: return [.episodesOpen, .closePanel]
        case .engine: return [.engineAether, .engineKSPlayer, .engineAVPlayer, .closePanel]
        case .external: return [.externalInfuse, .externalVLC, .externalSenPlayer, .closePanel]
        case .videoFit: return DebridVideoFitMode.allCases.map { .videoFit($0) } + [.closePanel]
        case .settings:
            var opts: [PlayerPanelOption] = [.frameRateInfo]
            if isLivePlayback {
                opts += [.liveGuideModeTop, .liveGuideModeBottom, .liveDoubleBackExitToggle, .livePlayerAuto, .livePlayerKS, .livePlayerAV, .livePlayerVLC, .liveReloadStream, .liveResyncStream, .liveClearBuffer, .liveStreamDiagnostics]
            } else {
                opts += [.playbackHealthOpen, .audioAmplificationCycle, .featuredCastPosterTakeoverToggle, .portraitPosterThemedLogoToggle, .productionRatingsPanelToggle, .spotlightHubPanelToggle, .productionRatingsThemedLogoToggle]
            }
            opts += [.settingsDiagnostics, .alternateAudioToggle]
            if alternateAudioMasterEnabled { opts += [.settingsFindAudio] }
            opts += [.settingsInfuse, .settingsVLC, .settingsSenPlayer, .closePanel]
            return opts
        case .health:
            return [.playbackHealthRefresh, .playbackHealthRetryBridge, .playbackHealthTryAnotherAudio, .playbackHealthRestoreOriginal, .closePanel]
        }
    }

    private func seedPanelFocus(_ panel: PlayerPanel) {
        let first: PlayerPanelOption? = panel == .videoFit ? .videoFit(vodVideoFitMode) : panelOptionsList(panel).first
        selectedPanelOption = first
        focusedPanelOption = first
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.05) {
            selectedPanelOption = first
            focusedPanelOption = first
        }
    }

    private func routePanelMove(_ direction: SignalMoveDirection, panel: PlayerPanel) {
        let options = panelOptionsList(panel)
        guard !options.isEmpty else { return }
        let current = selectedPanelOption ?? focusedPanelOption ?? options[0]
        let idx = options.firstIndex(of: current) ?? 0
        let next: PlayerPanelOption
        switch direction {
        case .up:
            next = options[max(0, idx - 1)]
        case .down:
            next = options[min(options.count - 1, idx + 1)]
        case .left, .right:
            // While a chip submenu is open, UP/DOWN moves inside that submenu only.
            // LEFT/RIGHT are reserved for the bottom VOD chip rail before a submenu opens.
            return
        default:
            return
        }
        selectedPanelOption = next
        focusedPanelOption = next
    }

    private func activateFocusedPanelOption() {
        guard let panel = activePanel else { return }
        let option = selectedPanelOption ?? focusedPanelOption ?? panelOptionsList(panel).first
        switch option {
        case .audioAuto:
            selectedAudioMode = "Auto"
            saveTrackPreference("audio", value: "Auto")
            selectAudioOverlayOption("Auto / English preferred")
        case .audioEnglish:
            selectedAudioMode = "English"
            saveTrackPreference("audio", value: "English")
            selectAudioOverlayOption("English")
        case .audioOriginal:
            selectedAudioMode = "Original"
            saveTrackPreference("audio", value: "Original")
            selectAudioOverlayOption("Original")
        case .audioNext:
            selectedAudioMode = "Next"; cycleMedia(groupCharacteristic: .audible, label: "audio")
        case .audioTrack(let index):
            selectRealAudioTrack(index)
        case .alternateAudioToggle:
            setAlternateAudioEnabled(!alternateAudioMasterEnabled)
        case .findAlternateAudio:
            findAlternateAudio()
        case .alternateAudio(let index):
            guard store.alternateAudioSources.indices.contains(index) else { return }
            let source = store.alternateAudioSources[index]
            // vBRDC162 Universal Alternate Audio: old bridge-era timing classifications are
            // advisory only. The on-device KSME decoder can open any resolved copy and select
            // its English/untagged audio independently while the original video stays mounted.
            selectedAlternateAudioIndex = index
            selectedAudioMode = "Alt candidate"
            store.selectAlternateAudioSource(source, for: item)
            applyAlternateAudioSelection()
            showControlsWithoutChangingFocus()
        case .alternateAudioPrepareBridge:
            useSelectedAlternateAudioLocally()
        case .alternateAudioMinus250:
            store.adjustAlternateAudioSyncOffset(for: item, source: store.selectedAlternateAudioSource, deltaMS: -250)
            playbackNotice = localAlternateAudioURL != nil ? "Alternate Audio sync \(store.alternateAudioSyncOffsetMS)ms • applied live" : "Alternate Audio sync \(store.alternateAudioSyncOffsetMS)ms"
            showControlsWithoutChangingFocus()
        case .alternateAudioPlus250:
            store.adjustAlternateAudioSyncOffset(for: item, source: store.selectedAlternateAudioSource, deltaMS: 250)
            playbackNotice = localAlternateAudioURL != nil ? "Alternate Audio sync \(store.alternateAudioSyncOffsetMS)ms • applied live" : "Alternate Audio sync \(store.alternateAudioSyncOffsetMS)ms"
            showControlsWithoutChangingFocus()
        case .alternateAudioReset:
            store.resetAlternateAudioSyncOffset(for: item, source: store.selectedAlternateAudioSource)
            playbackNotice = localAlternateAudioURL != nil ? "Alternate Audio sync reset • applied live" : "Alternate Audio sync reset"
            showControlsWithoutChangingFocus()
        case .alternateAudioRestoreOriginal:
            restoreOriginalAudio(reason: "Original embedded audio restored.", clearSelection: false)
            showControlsWithoutChangingFocus()
        case .alternateAudioClear:
            restoreOriginalAudio(reason: "Alternate Audio cleared — original audio restored.", clearSelection: true)
            selectedAlternateAudioIndex = nil
            showControlsWithoutChangingFocus()
        case .subtitlesOff:
            selectedSubtitleMode = "Off"
            saveTrackPreference("subtitle", value: "Off")
            selectSubtitleOverlayOption("Off")
        case .subtitlesEnglish:
            selectedSubtitleMode = "English"
            saveTrackPreference("subtitle", value: "English")
            selectSubtitleOverlayOption("English")
        case .subtitlesAuto:
            selectedSubtitleMode = "Auto"
            saveTrackPreference("subtitle", value: "Auto")
            selectSubtitleOverlayOption("Auto")
        case .subtitlesNext:
            selectedSubtitleMode = "Next"
            cycleMedia(groupCharacteristic: .legible, label: "subtitle")
        case .subtitleTrack(let index):
            selectRealSubtitleTrack(index)
        case .subtitleDelayMinus250:
            adjustSubtitleDelay(by: -250)
        case .subtitleDelayPlus250:
            adjustSubtitleDelay(by: 250)
        case .subtitleDelayReset:
            setSubtitleDelay(0)
        case .episodesOpen:
            openVODEpisodeBrowser()
        case .engineAether:
            activePanel = nil
            selectedPanelOption = nil
            focusedPanelOption = nil
            if forceAetherSurface {
                playbackNotice = "AetherEngine is already active."
                store.status = playbackNotice
                forceControlsVisibleForNavigation()
            } else {
                switchToAetherEngine(manual: true)
            }
        case .engineAVPlayer:
            activePanel = nil
            selectedPanelOption = nil
            focusedPanelOption = nil
            switchToAVPlayerEngine(manual: true)
        case .engineKSPlayer:
            activePanel = nil
            selectedPanelOption = nil
            focusedPanelOption = nil
            if forceKSPlayerSurface {
                playbackNotice = "KSPlayer is already active."
                store.status = playbackNotice
                forceControlsVisibleForNavigation()
            } else {
                switchToKSPlayerEngine(manual: true)
            }
        case .externalInfuse:
            activePanel = nil
            selectedPanelOption = nil
            focusedPanelOption = nil
            openExternal(.infuse)
        case .externalVLC:
            activePanel = nil
            selectedPanelOption = nil
            focusedPanelOption = nil
            openExternal(.vlc)
        case .externalSenPlayer:
            activePanel = nil
            selectedPanelOption = nil
            focusedPanelOption = nil
            openExternal(.senPlayer)
        case .videoFit(let mode):
            applyVideoFitMode(mode)
        case .frameRateInfo:
            store.status = "Frame-rate matching remains controlled by tvOS/player output; playback is not restarted."
        case .liveReloadStream:
            reloadCurrentLiveStream(reason: "Manual reload chip")
        case .liveResyncStream:
            resyncCurrentLiveStream()
        case .liveClearBuffer:
            clearLiveBufferAndHoldOffset()
        case .liveStreamDiagnostics:
            vodPlaybackDiagnosticsEnabled = true
            playbackNotice = "Stream diagnostics • \(remuxStreamModeLabel) • URL: \(url.absoluteString.prefix(80))"
            store.status = "Stream diagnostics enabled. Source mode: \(remuxStreamModeLabel). If CBS/TVE drifts, use Resync or Reload Stream."
            showControlsWithoutChangingFocus()
        case .livePlayerAuto:
            livePlayerOverride = "auto"
            livePlayerFallbackReason = ""
            store.status = "Live TV player override cleared for this channel. Reopening with Auto..."
            setupPlayer()
            showControlsWithoutChangingFocus()
        case .livePlayerKS:
            switchToKSPlayerEngine(manual: true)
        case .livePlayerAV:
            switchToAVPlayerEngine(manual: true)
        case .livePlayerVLC:
            switchToVLCEngine(manual: true)
        case .liveGuideModeTop:
            liveTVPlaybackGuideModeRaw = "top"
            store.status = "Live TV Guide button will open Top Quick Guide over playback."
            showControlsWithoutChangingFocus()
        case .liveGuideModeBottom:
            liveTVPlaybackGuideModeRaw = "bottom"
            store.status = "Live TV Guide button will open Bottom Quick Guide over playback."
            showControlsWithoutChangingFocus()
        case .liveDoubleBackExitToggle:
            liveTVPlaybackDoubleBackExitEnabled.toggle()
            clearLiveTVDoubleBackExitArm()
            store.status = liveTVPlaybackDoubleBackExitEnabled
                ? "Live TV exit protection enabled — press Back twice on the uncovered playback screen to exit."
                : "Live TV exit protection disabled — one Back exits when no overlay or controls are open."
            showControlsWithoutChangingFocus()
        case .settingsDiagnostics:
            vodPlaybackDiagnosticsEnabled.toggle()
            store.status = vodPlaybackDiagnosticsEnabled ? "Playback diagnostics enabled in Settings." : "Playback diagnostics hidden by default."
            showControlsWithoutChangingFocus()
        case .featuredCastPosterTakeoverToggle:
            let nextMode = vodFeaturedCastPresentationMode.next
            vodFeaturedCastPresentationModeRaw = nextMode.rawValue
            legacyVODFeaturedCastPosterTakeoverEnabled = nextMode == .fullPoster
            switch nextMode {
            case .off:
                store.status = "Featured Cast Presentation is Off. The original movie/show poster remains untouched."
            case .compactOverlay:
                store.status = "Featured Cast Presentation keeps the original poster full size and shows a small cast banner underneath with name and role."
            case .fullPoster:
                store.status = "Featured Cast Presentation uses the full poster area after the title poster appears briefly."
            }
            showControlsWithoutChangingFocus()
        case .portraitPosterThemedLogoToggle:
            vodPortraitPosterThemedLogoEnabled.toggle()
            store.status = vodPortraitPosterThemedLogoEnabled
                ? "Poster Themed Logo is On. Title artwork appears over the portrait poster."
                : "Poster Themed Logo is Off. The portrait poster remains clean."
            showControlsWithoutChangingFocus()
        case .productionRatingsPanelToggle:
            let enabling = !vodProductionRatingsPanelEnabled || vodSpotlightHubPanelEnabled
            vodProductionRatingsPanelEnabled = enabling
            if enabling {
                // vBRDC192: the right-side Media Information feature slot has one owner.
                // Production & Ratings and Spotlight Hub are single-owner alternatives.
                vodSpotlightHubPanelEnabled = false
                if isFirstFrameReady {
                    loadVODProductionMetadata(for: overlayItem, delayNanoseconds: 180_000_000, force: true)
                    store.status = "Media Info Feature: Production & Ratings."
                } else {
                    store.status = "Media Info Feature: Production & Ratings will load after playback is established."
                }
            } else {
                vodProductionMetadataTask?.cancel()
                vodProductionMetadataTask = nil
                store.status = "Media Info Feature is Off."
            }
            showControlsWithoutChangingFocus()
        case .spotlightHubPanelToggle:
            let enabling = !vodSpotlightHubPanelEnabled || vodProductionRatingsPanelEnabled
            vodSpotlightHubPanelEnabled = enabling
            if enabling {
                // Mutually exclusive with Production & Ratings by construction.
                vodProductionRatingsPanelEnabled = false
                if isFirstFrameReady {
                    loadVODProductionMetadata(for: overlayItem, delayNanoseconds: 120_000_000, force: true)
                    store.status = "Media Info Feature: Spotlight Hub. Trakt activity, personal title state, related titles, watch providers, and community highlights load when available."
                } else {
                    store.status = "Media Info Feature: Spotlight Hub will load after playback is established."
                }
            } else {
                vodProductionMetadataTask?.cancel()
                vodProductionMetadataTask = nil
                store.status = "Media Info Feature is Off."
            }
            showControlsWithoutChangingFocus()
        case .productionRatingsThemedLogoToggle:
            vodProductionRatingsThemedLogoEnabled.toggle()
            store.status = vodProductionRatingsThemedLogoEnabled
                ? "Production & Ratings Themed Logo is On. Title artwork appears in the Production & Ratings banner whenever that feature is selected."
                : "Production & Ratings Themed Logo is Off. Production artwork remains unobstructed."
            showControlsWithoutChangingFocus()
        case .audioAmplificationCycle:
            applyVODAudioAmplification(vodAudioAmplificationPreset.next)
        case .playbackHealthOpen:
            guard !isLivePlayback else { return }
            capturePlaybackHealthSnapshot()
            refreshAlternateAudioDiagnosticsSnapshot()
            activePanel = .health
            seedPanelFocus(.health)
            forceControlsVisibleForNavigation()
        case .playbackHealthRefresh:
            capturePlaybackHealthSnapshot()
            refreshAlternateAudioDiagnosticsSnapshot()
            store.status = "Playback Health snapshot refreshed without enabling a continuous overlay monitor."
            showControlsWithoutChangingFocus()
        case .playbackHealthRetryBridge:
            useSelectedAlternateAudioLocally()
        case .playbackHealthTryAnotherAudio:
            tryAnotherAlternateAudioCandidate()
        case .playbackHealthRestoreOriginal:
            restoreOriginalAudio(reason: "Original embedded audio restored from Playback Health.", clearSelection: false)
            refreshAlternateAudioDiagnosticsSnapshot()
            showControlsWithoutChangingFocus()
        case .settingsFindAudio:
            findAlternateAudio()
        case .settingsInfuse:
            openExternal(.infuse)
        case .settingsVLC:
            openExternal(.vlc)
        case .settingsSenPlayer:
            openExternal(.senPlayer)
        case .closePanel, .none:
            selectedPanelOption = nil
            focusedPanelOption = nil
            activePanel = nil
            showControlsWithoutChangingFocus()
        }
    }

