    private func panelTitle(_ panel: PlayerPanel) -> String {
        switch panel {
        case .audio: return "Audio Tracks"
        case .subtitles: return "Subtitles"
        case .episodes: return "Episodes"
        case .engine: return "Player Engine"
        case .external: return "External Player"
        case .videoFit: return "Video Fit & Aspect Ratio"
        case .settings: return "Playback Settings"
        case .health: return "Playback Health"
        }
    }

    private func panelDetail(_ panel: PlayerPanel) -> String {
        switch panel {
        case .audio:
            return "Find English Audio publishes every resolved copy immediately, then optionally enriches track labels/indexes with ffprobe. Legacy identity/timing classifications are diagnostics only and never block local audio selection."
        case .subtitles:
            return "Stremio subtitle URLs are captured for the overlay parser path. Subtitles default off and can be enabled from the Debrid overlay when supported by the active engine."
        case .episodes:
            return "Open the full-screen episode browser to search every loaded episode by SxEy, title, description, or air date, filter real seasons, and confirm before switching playback."
        case .engine:
            return "KSPlayer is the production VOD engine. AVPlayer remains available only as an explicit native compatibility choice."
        case .external:
            return "External players remain one-select launch targets. Internal AVPlayer and KSPlayer state is preserved by resume/progress saving."
        case .videoFit:
            return "Change only the picture geometry while playback stays mounted: source fit, fill, crop/zoom, stretch, zoom levels, and standard TV/cinema aspect-ratio overrides."
        case .settings:
            return "Engines: \(activeEngineName) is active. KSPlayer is the VOD default, with AVPlayer available as a manual native compatibility choice. Direct streaming is active. Current profile: \(nativeProfileText.isEmpty ? "pending" : nativeProfileText)."
        case .health:
            return "A low-overhead, point-in-time snapshot of the active VOD session. It refreshes only when this panel opens or Refresh Snapshot is selected."
        }
    }


    private var isLikelyChannelsDVRRemuxStream: Bool {
        let lowerURL = url.absoluteString.lowercased()
        let lowerLabel = store.playbackLinkLabel.lowercased()
        return lowerURL.contains("/devices/") || lowerURL.contains("channels.m3u") || lowerURL.contains("/hls/") || lowerURL.contains("/dvr/") || lowerLabel.contains("channels dvr") || lowerLabel.contains("tve") || lowerLabel.contains("verizon")
    }

    private var isLikelyCBSAffiliateStream: Bool {
        let haystack = "\(item.title) \(item.catalog) \(item.description) \(store.playbackLinkLabel) \(url.absoluteString)".lowercased()
        return haystack.contains("cbs") || haystack.contains("paramount") || haystack.contains("wkyc") || haystack.contains("wbbm") || haystack.contains("wcbs") || haystack.contains("kcbs")
    }

    private var remuxStreamModeLabel: String {
        if isLikelyCBSAffiliateStream && isLikelyChannelsDVRRemuxStream { return "CBS/TVE remux timing guard" }
        if isLikelyCBSAffiliateStream { return "CBS affiliate timing guard" }
        return isLikelyChannelsDVRRemuxStream ? "Remuxed HLS / Channels DVR M3U" : "Standard stream"
    }

    private func reloadCurrentLiveStream(reason: String = "Manual reload") {
        guard isLivePlayback else {
            store.status = "Reload Stream is available for Live TV only."
            return
        }
        retryText = "Reloading live stream…"
        playbackNotice = "\(reason) • flushing live buffer • \(remuxStreamModeLabel)"
        store.status = "Live TV reload: \(reason). Re-opening the current stream without changing channel."
        vlcSurfaceToken += 1
        setupPlayer()
        showControlsWithoutChangingFocus()
    }

    private func resyncCurrentLiveStream() {
        guard isLivePlayback else {
            store.status = "Resync is available for Live TV only."
            return
        }
        playbackNotice = "A/V resync requested • \(remuxStreamModeLabel)"
        store.status = "A/V resync: flushing and re-opening this live stream. Use this for TVE ad-break drift or stale video with newer audio."
        vlcSurfaceToken += 1
        setupPlayer()
        showControlsWithoutChangingFocus()
    }

    private func clearLiveBufferAndHoldOffset() {
        guard isLivePlayback else {
            store.status = "Clear Buffer is available for Live TV only."
            return
        }
        playbackNotice = "Live buffer cleared • using safer remux/live-edge offset • \(remuxStreamModeLabel)"
        store.status = "Live buffer cleared. Remuxed Channels DVR M3U streams should sit a few segments behind live edge for fewer CBS/TVE ad-sync glitches."
        vlcSurfaceToken += 1
        setupPlayer()
        showControlsWithoutChangingFocus()
    }

    private func refreshAlternateAudioDiagnosticsSnapshot() {
        let source = store.selectedAlternateAudioSource
        let bridge = store.preparedAlternateAudioBridge
        alternateAudioDiagnosticsSnapshot = AlternateAudioBridgeDiagnosticsSnapshot(
            preparationStage: bridge?.preparationStage ?? store.alternateAudioBridgeState.rawValue.capitalized,
            preparationPercentage: bridge?.preparationPercentage ?? (store.alternateAudioBridgeState == .preparing ? 35 : store.alternateAudioBridgeState == .ready ? 90 : 0),
            originalVideoSource: bridge?.originalVideoSource ?? "Current playback source",
            alternateAudioSource: bridge?.alternateAudioSource ?? source?.title ?? "Not selected",
            selectedStreamIndex: bridge.map { String($0.selectedStreamIndex) } ?? source?.audioTrackIndex.map(String.init) ?? "Not selected",
            matchClassification: bridge?.classification ?? source?.matchClassification ?? "Not classified",
            offset: "\(bridge?.offsetMS ?? store.alternateAudioSyncOffsetMS)ms",
            driftCorrection: bridge?.driftCorrection ?? ((source?.matchClassification == AlternateAudioMatchClassification.driftCorrectable.rawValue) ? "Audio drift correction enabled" : "Not required"),
            streamModes: bridge.map { "Video \($0.videoMode) • Audio \($0.audioMode)" } ?? "Video stream-copy • audio pending",
            candidateRejectionReason: bridge?.rejectionReason ?? source?.rejectionReason ?? "None",
            bridgeStatus: store.alternateAudioBridgeMessage
        )
        guard let bridge else { return }
        let bridgeID = bridge.id
        let backend = UserDefaults.standard.string(forKey: "backendBaseURL") ?? "https://api.skylinejay187.it.com"
        Task(priority: .utility) {
            guard let remote = await AlternateAudioDiagnosticsClient.fetch(backendBaseURL: backend, bridgeUUID: bridgeID) else { return }
            await MainActor.run {
                guard store.preparedAlternateAudioBridge?.id == bridgeID else { return }
                alternateAudioDiagnosticsSnapshot = remote
            }
        }
    }

    private func alternateAudioCandidateKey(_ source: AlternateAudioSource) -> String {
        "\(source.url)#\(source.audioTrackIndex ?? -1)"
    }

    @MainActor
    private func tryNextAlternateAudioCandidateAfterFailure(message: String) -> Bool {
        let candidates = Array(store.alternateAudioSources.enumerated())
        guard let next = candidates.first(where: {
            !alternateAudioAttemptedCandidateKeys.contains(alternateAudioCandidateKey($0.element))
        }) else {
            return false
        }
        selectedAlternateAudioIndex = next.offset
        selectedAudioMode = "Alt candidate"
        store.selectAlternateAudioSource(next.element, for: item)
        store.status = "Alternate Audio: trying another resolved copy after \(message)"
        useSelectedAlternateAudioLocally(resetAttemptCycle: false)
        return true
    }

    private func tryAnotherAlternateAudioCandidate() {
        guard !store.alternateAudioSources.isEmpty else {
            store.status = "No alternate audio candidates are available. Run Find English Audio first."
            return
        }
        let candidates = Array(store.alternateAudioSources.enumerated())
        guard !candidates.isEmpty else {
            store.status = "No alternate audio candidate is available."
            return
        }
        let currentURL = store.selectedAlternateAudioSource?.url
        let currentPosition = candidates.firstIndex { $0.element.url == currentURL } ?? -1
        let next = candidates[(currentPosition + 1) % candidates.count]
        selectedAlternateAudioIndex = next.offset
        selectedAudioMode = "Alt candidate"
        store.selectAlternateAudioSource(next.element, for: item)
        useSelectedAlternateAudioLocally(resetAttemptCycle: true)
    }

    private func capturePlaybackHealthSnapshot() {
        let diagnostics = currentPlaybackDiagnostics()
        let sourceSummary = store.playbackSourceTrackSummary
        let filename = activePlaybackURL?.lastPathComponent.removingPercentEncoding?.ifEmpty("Unknown file") ?? "Unknown file"
        let provider = item.catalog.trimmingCharacters(in: .whitespacesAndNewlines).ifEmpty("Unknown provider")
        let hdr = sourceSummary?.hdrType?.trimmingCharacters(in: .whitespacesAndNewlines)
        let alternateStatus: String = {
            if let bridge = store.preparedAlternateAudioBridge {
                let handoff = alternateAudioHandoffState.rawValue.capitalized
                let source = activePlaybackURL == bridge.hlsURL ? "bridge active" : "bridge prepared"
                return "Bridge \(store.alternateAudioBridgeState.rawValue) • \(bridge.diagnosticSummary) • handoff \(handoff) • \(source)"
            }
            if let selected = store.selectedAlternateAudioSource {
                let localState = localAlternateAudioURL == nil ? "selected" : "local audio \(alternateAudioHandoffState.rawValue)"
                return "Discovery candidate • \(selected.displayTitle) • \(store.alternateAudioSyncOffsetMS) ms • \(localState) • primary video unchanged"
            }
            return "\(store.alternateAudioDiscoveryState.rawValue.capitalized) • \(store.alternateAudioDiscoveryMessage)"
        }()
        let handoffStatus: String = {
            if let failover = store.automaticSourceFailoverContext(for: playbackPresentationID) {
                return "Automatic startup failover • \(failover.attempt)/\(failover.availableFallbacks) • waiting for stable first frame"
            }
            if let handoff = store.experimentalPlaybackHandoffID { return "Experimental active • \(handoff.uuidString.prefix(8))" }
            if store.playbackPresentationID == playbackPresentationID { return "Stable source owned by current session" }
            return "Stale presentation rejected"
        }()
        let trailerStatus: String = {
            let signature = "\(url.absoluteString) \(store.playbackLinkLabel)".lowercased()
            guard signature.contains("trailer") || signature.contains("remux-cache") else { return "Not a trailer session" }
            return isLoading ? "v1073 eager resolver lane • filling" : "v1073 eager resolver lane • playing"
        }()
        let embeddedAudioLabel: String = {
            guard let index = selectedRealAudioTrackIndex, realAudioTrackLabels.indices.contains(index) else { return "Default" }
            return realAudioTrackLabels[index]
        }()
        let bufferedDurationText: String = {
            guard let range = player?.currentItem?.loadedTimeRanges.first?.timeRangeValue else {
                return isLoading ? "Filling / startup" : "Engine-managed"
            }
            let bufferedEnd = CMTimeGetSeconds(CMTimeRangeGetEnd(range))
            guard bufferedEnd.isFinite else { return "Engine-managed" }
            return String(format: "%.1f s ahead", max(0, bufferedEnd - authoritativeCurrentSeconds))
        }()
        let frameHealthText: String = {
            guard let event = player?.currentItem?.accessLog()?.events.last else { return diagnostics.droppedFrames }
            return "\(event.numberOfDroppedVideoFrames) dropped • \(event.numberOfStalls) stalls"
        }()
        playbackHealthSnapshot = PlaybackHealthSnapshot(
            sessionUUID: playbackPresentationID.uuidString,
            presentationGeneration: "KS surface \(ksSurfaceToken) • VLC surface \(vlcSurfaceToken)",
            sourceProviderAndFilename: "\(provider) • \(filename)",
            videoCodec: sourceSummary?.videoCodec?.ifEmpty(diagnostics.videoCodec) ?? diagnostics.videoCodec,
            audioCodec: sourceSummary?.audioCodecText?.ifEmpty(diagnostics.audioCodec) ?? diagnostics.audioCodec,
            resolution: sourceSummary?.resolution?.ifEmpty(sourceQualityLabel) ?? sourceQualityLabel,
            hdrState: (hdr?.isEmpty == false ? hdr! : (UniversalCodecSupport.profile(for: url, hint: store.playbackLinkLabel).isLikelyHDR ? "HDR/Dolby Vision hint" : "SDR/undetected")),
            frameRate: diagnostics.fps,
            hardwareDecoder: "\(diagnostics.activeDecoder) • \(diagnostics.hwDecode)",
            bufferDuration: bufferedDurationText,
            droppedAndDelayedFrames: frameHealthText,
            audioVideoClockDifference: diagnostics.avDrift,
            currentAudioTrack: selectedAudioMode.ifEmpty(embeddedAudioLabel),
            currentSubtitleTrack: selectedSubtitleMode.ifEmpty("Off"),
            firstFrameStatus: isFirstFrameReady ? "Ready" : (isLoading ? "Waiting" : "Not confirmed"),
            sourceHandoffStatus: handoffStatus,
            alternateAudioStatus: alternateStatus,
            trailerResolverStatus: trailerStatus,
            capturedAt: Date().formatted(date: .omitted, time: .shortened)
        )
    }

    private func currentPlaybackDiagnostics() -> DebridPlaybackDiagnostics {
        let profile = UniversalCodecSupport.profile(for: url, hint: store.playbackLinkLabel)
        let engine = activeEngineName
        let isPlaybackKitKSPlayer = engine.lowercased().contains("ksplayer")
        let hardwareSetting: DebridHardwareAccelerationSetting = isPlaybackKitKSPlayer ? .forceOn : .auto
        var diag = DebridPlaybackDiagnosticsFactory.make(engine: engine, profile: profile, controlsVisible: controlsVisible, isPlaying: isPlaying, hardwareAcceleration: hardwareSetting)
        if isPlaybackKitKSPlayer {
            diag.hardwareAccelerationSetting = "PlaybackKit / VideoToolbox"
        }
        if isLoading {
            diag.fps = "Loading"
            diag.droppedFrames = "Pending"
        }
        if !playbackNotice.isEmpty {
            diag.notes = isLivePlayback ? "\(playbackNotice) • Source mode: \(remuxStreamModeLabel) • Channel: \(item.title)" : playbackNotice
        } else if isLivePlayback {
            diag.notes = "Source mode: \(remuxStreamModeLabel) • Channel: \(item.title)"
        }
        if isLivePlayback && isLikelyCBSAffiliateStream {
            diag.avDrift = forceVLCSurface ? "Estimating CBS/VLC PCR delta" : "Estimating CBS PTS/PCR delta"
        }
        if isLivePlayback {
            let timingRiskHaystack = url.absoluteString.lowercased() + " " + store.playbackLinkLabel.lowercased()
            let hasCBSMetadataSignal = timingRiskHaystack.contains("cbs") || timingRiskHaystack.contains("paramount") || timingRiskHaystack.contains("wcbs") || timingRiskHaystack.contains("kcbs") || timingRiskHaystack.contains("wbbm") || timingRiskHaystack.contains("wkyc")
            let hasLiveRemuxTimingSignal = timingRiskHaystack.contains("/devices/") || timingRiskHaystack.contains("channels.m3u") || timingRiskHaystack.contains("/hls/") || timingRiskHaystack.contains("/dvr/") || timingRiskHaystack.contains("format=ts") || timingRiskHaystack.contains(".m3u8") || timingRiskHaystack.contains(".mpg") || timingRiskHaystack.contains("tve") || timingRiskHaystack.contains("channels dvr") || timingRiskHaystack.contains("verizon") || timingRiskHaystack.contains("live tv direct stream") || timingRiskHaystack.contains("ks live tv route")
            let cbsProfileActive = liveTimingCBSProfileField(named: "CBS profile active")
            let hlsRewriteSucceeded = liveTimingCBSProfileField(named: "hlsURL rewrite succeeded")
            let originalURLType = liveTimingCBSProfileField(named: "original URL type")
            let finalURLType = liveTimingCBSProfileField(named: "final URL type")
            diag.selectedPlayerOverride = livePlayerOverride.uppercased()
            diag.effectivePlayerEngine = activeEngineName
            diag.forceVLCSurface = forceVLCSurface ? "true" : "false"
            diag.forceKSPlayerSurface = forceKSPlayerSurface ? "true" : "false"
            diag.finalPlaybackURLType = finalURLType == "unavailable" ? LiveTVCBSChannelsDVRProfile.urlType(for: url) : finalURLType
            diag.cbsMetadataSignal = liveTimingCBSProfileField(named: "CBS metadata signal", fallback: "\(hasCBSMetadataSignal)")
            diag.channelsTimingRiskSignal = liveTimingCBSProfileField(named: "Channels timing-risk signal", fallback: "\(hasLiveRemuxTimingSignal)")
            diag.cbsProfileActive = cbsProfileActive == "unavailable" ? "false" : cbsProfileActive
            diag.hlsRewriteSucceeded = hlsRewriteSucceeded == "unavailable" ? "false" : hlsRewriteSucceeded
            diag.cbsOriginalURLType = originalURLType == "unavailable" ? LiveTVCBSChannelsDVRProfile.urlType(for: url) : originalURLType
            diag.cbsFinalURLType = finalURLType == "unavailable" ? LiveTVCBSChannelsDVRProfile.urlType(for: url) : finalURLType
            diag.fallbackReason = livePlayerFallbackReason.isEmpty ? "None" : livePlayerFallbackReason
        } else {
            diag.fallbackReason = vodEngineFallbackReason
            let compatibilityHint = [store.playbackLinkLabel, vodSourceInfoChipLabel].filter { !$0.isEmpty }.joined(separator: " | ")
            let compatibility = PlaybackCodecCompatibilityProfile.infer(url: activePlaybackURL ?? url, routeHint: compatibilityHint)
            let compatibilityNote = "Phase 11: \(compatibility.diagnosticLabel)"
            diag.notes = diag.notes.isEmpty ? compatibilityNote : "\(diag.notes) • \(compatibilityNote)"
        }
        return diag
    }

    private func setAlternateAudioEnabled(_ enabled: Bool) {
        alternateAudioMasterEnabled = enabled
        StableFeatureGateManager.setEnabled(enabled, for: .alternateAudioMaster)
        StableFeatureGateManager.setEnabled(enabled, for: .alternateAudioDiscovery)
        StableFeatureGateManager.setEnabled(enabled, for: .alternateAudioBridge)
        StableFeatureGateManager.setEnabled(enabled, for: .alternateAudioHandoff)

        if enabled {
            store.status = "Alternate Audio is On. Scans run only when you select Find English Audio."
            playbackNotice = "Alternate Audio On • idle until manually scanned"
        } else {
            cancelAlternateAudioForLifecycle(reason: "Alternate Audio turned Off — all backend work cancelled and original audio restored.")
            selectedAlternateAudioIndex = nil
            store.alternateAudioSources = []
            store.selectAlternateAudioSource(nil, for: item)
        }
        activePanel = .audio
        seedPanelFocus(.audio)
        showControlsWithoutChangingFocus()
    }

    private func cancelAlternateAudioForLifecycle(reason: String) {
        alternateAudioDiscoveryTask?.cancel()
        alternateAudioDiscoveryTask = nil
        alternateAudioBridgeTask?.cancel()
        alternateAudioBridgeTask = nil
        isFindingAlternateAudio = false
        isPreparingAlternateAudioBridge = false
        let preparedBridgeUUID = store.preparedAlternateAudioBridge?.id
        store.cancelAlternateAudioBridgeSession(pendingAlternateAudioBridgeUUID, presentationID: playbackPresentationID, reason: reason)
        store.cancelAlternateAudioBridgeSession(activeAlternateAudioBridgeUUID, presentationID: playbackPresentationID, reason: reason)
        store.cancelAlternateAudioBridgeSession(retiringAlternateAudioBridgeUUID, presentationID: playbackPresentationID, reason: reason)
        pendingAlternateAudioBridgeUUID = nil
        activeAlternateAudioBridgeUUID = nil
        retiringAlternateAudioBridgeUUID = nil
        store.cancelAllAlternateAudioWork(
            presentationID: playbackPresentationID,
            additionalBridgeUUID: preparedBridgeUUID,
            clearPrepared: true,
            reason: reason
        )
        if alternateAudioHandoffState == .switching || alternateAudioHandoffState == .active || localAlternateAudioURL != nil || activePlaybackURL != url {
            restoreOriginalAudio(reason: reason, clearSelection: false)
        } else {
            playbackNotice = reason
            store.status = reason
        }
    }

    private func findAlternateAudio() {
        guard !isLivePlayback else {
            store.status = "Alternate audio search is for Movies/Shows only. Live TV keeps the channel stream audio."
            return
        }
        if alternateAudioHandoffState == .switching || alternateAudioHandoffState == .active || localAlternateAudioURL != nil || activePlaybackURL != url {
            restoreOriginalAudio(
                reason: "Original audio restored before scanning for another Alternate Audio source.",
                clearSelection: false
            )
        }
        alternateAudioDiscoveryTask?.cancel()
        store.cancelAlternateAudioDiscovery()
        alternateAudioBridgeTask?.cancel()
        alternateAudioBridgeTask = nil
        isPreparingAlternateAudioBridge = false
        store.cancelAlternateAudioBridgePreparation(clearPrepared: true)
        guard alternateAudioMasterEnabled,
              StableFeatureGateManager.isEnabled(.alternateAudioDiscovery) else {
            store.status = "Alternate Audio is Off. Turn it On before scanning."
            showControlsWithoutChangingFocus()
            return
        }
        isFindingAlternateAudio = true
        activePanel = .audio
        forceControlsVisibleForNavigation()
        let ownedPresentationID = playbackPresentationID
        alternateAudioDiscoveryTask = Task { @MainActor in
            let candidates = await store.discoverAlternateAudioSources(for: item, currentURL: url, preferredLanguage: "English")
            guard !Task.isCancelled, ownedPresentationID == playbackPresentationID else { return }
            isFindingAlternateAudio = false
            if let remembered = store.selectedAlternateAudioSource,
               let rememberedIndex = candidates.firstIndex(where: {
                   $0.url == remembered.url && $0.audioTrackIndex == remembered.audioTrackIndex
               }) {
                selectedAlternateAudioIndex = rememberedIndex
                selectedAudioMode = "Alt candidate"
                selectedPanelOption = .alternateAudio(rememberedIndex)
            } else if let first = candidates.first {
                selectedAlternateAudioIndex = 0
                selectedAudioMode = "Alt candidate"
                store.selectAlternateAudioSource(first, for: item)
                selectedPanelOption = .alternateAudio(0)
            } else {
                selectedPanelOption = .findAlternateAudio
            }
            focusedPanelOption = selectedPanelOption
            alternateAudioDiscoveryTask = nil
        }
    }

    private func useSelectedAlternateAudioLocally(resetAttemptCycle: Bool = true) {
        guard !isLivePlayback else {
            store.status = "Alternate Audio is available for Movies/Shows only."
            return
        }
        guard alternateAudioMasterEnabled,
              StableFeatureGateManager.isEnabled(.alternateAudioDiscovery) else {
            store.status = "Alternate Audio is Off. Turn it On before using another audio track."
            return
        }
        guard let source = store.selectedAlternateAudioSource,
              let rawURL = URL(string: source.url) else {
            store.status = "Select an alternate audio copy first."
            showControlsWithoutChangingFocus()
            return
        }

        if resetAttemptCycle {
            alternateAudioAttemptedCandidateKeys.removeAll(keepingCapacity: true)
        }
        alternateAudioAttemptedCandidateKeys.insert(alternateAudioCandidateKey(source))

        let upstreamHeaders = source.requestHeaders.playbackHTTPHeaderDictionary
        guard let engineURL = MediaFlowProxyRouter.playbackURLIfAllowed(
            for: rawURL,
            kind: .vod,
            upstreamHeaders: upstreamHeaders
        ) else {
            store.status = MediaFlowProxyRouter.configurationError(kind: .vod) ?? "Alternate Audio source could not be opened."
            showControlsWithoutChangingFocus()
            return
        }
        let engineHeaders = MediaFlowProxyRouter.playerRequestHeaders(for: .vod, upstreamHeaders: upstreamHeaders)

        if resetAttemptCycle && (
            alternateAudioHandoffState == .idle
            || alternateAudioHandoffState == .failed
            || alternateAudioHandoffState == .restoring
        ) {
            alternateAudioSavedAudioTrackIndex = ksSelectedAudioTrackIndex
            alternateAudioSavedAudioMode = selectedAudioMode
        }

        // Local dual-source audio requires KSPNUVIO/FFmpeg. If this presentation began on
        // AVFoundation, move the same primary URL to KS once at the current position; after
        // that, Alternate Audio never replaces or remuxes the primary video source.
        if !forceKSPlayerSurface {
            let resumeSeconds = max(0, authoritativeCurrentSeconds)
            player?.pause()
            if let timeObserver, let player { player.removeTimeObserver(timeObserver) }
            timeObserver = nil
            statusObserver?.invalidate()
            statusObserver = nil
            nativePrepareTask?.cancel()
            nativePrepareTask = nil
            player = nil
            forceAetherSurface = false
            forceVLCSurface = false
            forceKSPlayerSurface = true
            selectedPlaybackMode = "KS Direct + Local Alternate Audio"
            ksStartTimeSeconds = resumeSeconds
            ksSeekSeconds = resumeSeconds
            ksSeekIsAbsolute = true
            ksSurfaceToken &+= 1
        }

        // Clean up any obsolete server-side bridge from older builds, but never create one.
        alternateAudioBridgeTask?.cancel()
        alternateAudioBridgeTask = nil
        isPreparingAlternateAudioBridge = false
        store.cancelAlternateAudioBridgePreparation(clearPrepared: true, reason: "vBRDC160 local Alternate Audio supersedes backend bridge")
        for bridgeUUID in [activeAlternateAudioBridgeUUID, pendingAlternateAudioBridgeUUID, retiringAlternateAudioBridgeUUID].compactMap({ $0 }) {
            store.cancelAlternateAudioBridgeSession(bridgeUUID, presentationID: playbackPresentationID, reason: "Local Alternate Audio active — obsolete backend bridge released")
        }
        activeAlternateAudioBridgeUUID = nil
        pendingAlternateAudioBridgeUUID = nil
        retiringAlternateAudioBridgeUUID = nil
        alternateAudioHandoffID = nil
        preparedPlaybackURL = nil

        alternateAudioHandoffGeneration &+= 1
        let generation = alternateAudioHandoffGeneration
        alternateAudioHandoffState = .switching
        localAlternateAudioTrackIndex = source.audioTrackIndex
        localAlternateAudioHTTPHeaders = engineHeaders
        localAlternateAudioURL = engineURL
        selectedAudioMode = "Alternate loading"
        playbackNotice = "Starting \(source.audioLanguage?.ifEmpty("English") ?? "English") audio locally • video unchanged"
        store.status = "Opening selected audio stream on Apple TV • \(source.displayTitle)"

        alternateAudioHandoffRecoveryTask?.cancel()
        alternateAudioHandoffRecoveryTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: 15_000_000_000)
            guard !Task.isCancelled,
                  generation == alternateAudioHandoffGeneration,
                  alternateAudioHandoffState == .switching,
                  localAlternateAudioURL == engineURL else { return }
            let message = "Local Alternate Audio did not become ready within 15 seconds."
            store.recordAlternateAudioFailure(message)
            alternateAudioHandoffState = .failed
            if !tryNextAlternateAudioCandidateAfterFailure(message: message) {
                restoreOriginalAudio(
                    reason: "Alternate Audio did not become ready — original audio restored.",
                    clearSelection: false
                )
            }
        }
        showControlsWithoutChangingFocus()
    }

    private func prepareAlternateAudioBridge(applyWhenReady: Bool) {
        guard !isLivePlayback else {
            store.status = "Alternate Audio Bridge is available for Movies/Shows only."
            return
        }
        guard store.selectedAlternateAudioSource != nil else {
            store.status = "Select an alternate audio copy before preparing legacy bridge diagnostics."
            showControlsWithoutChangingFocus()
            return
        }

        if applyWhenReady,
           let prepared = store.preparedAlternateAudioBridge,
           prepared.originalSourceURL == url,
           prepared.offsetMS == store.alternateAudioSyncOffsetMS,
           prepared.expiresAt.map({ $0.timeIntervalSinceNow > 15 }) ?? true {
            activatePreparedAlternateAudioBridge(prepared)
            return
        }

        guard alternateAudioMasterEnabled,
              StableFeatureGateManager.isEnabled(.alternateAudioBridge) else {
            store.status = "Alternate Audio is Off. Turn it On before preparing a bridge."
            showControlsWithoutChangingFocus()
            return
        }
        alternateAudioBridgeTask?.cancel()
        store.cancelAlternateAudioBridgePreparation(clearPrepared: true, reason: "Rebuilding Alternate Audio bridge")
        isPreparingAlternateAudioBridge = true
        activePanel = .audio
        forceControlsVisibleForNavigation()
        let ownedPresentationID = playbackPresentationID
        alternateAudioBridgeTask = Task { @MainActor in
            let prepared = await store.prepareAlternateAudioBridge(for: item, currentURL: url)
            guard !Task.isCancelled,
                  store.playbackPresentationID == ownedPresentationID,
                  store.playbackURL == url else { return }
            isPreparingAlternateAudioBridge = false
            selectedPanelOption = .alternateAudioPrepareBridge
            focusedPanelOption = .alternateAudioPrepareBridge
            alternateAudioBridgeTask = nil
            guard let prepared else {
                playbackNotice = "Alternate Audio bridge preparation failed • current playback preserved"
                showControlsWithoutChangingFocus()
                return
            }
            if applyWhenReady {
                activatePreparedAlternateAudioBridge(prepared)
            } else {
                playbackNotice = "Alternate Audio bridge prepared • ready to apply"
                showControlsWithoutChangingFocus()
            }
        }
    }

    private func activatePreparedAlternateAudioBridge(_ bridge: AlternateAudioBridgeSession) {
        guard !isLivePlayback,
              bridge.originalSourceURL == url,
              store.playbackPresentationID == playbackPresentationID,
              store.playbackURL == url else {
            playbackNotice = "Alternate Audio bridge rejected • source ownership changed"
            store.recordAlternateAudioFailure(playbackNotice)
            return
        }
        if let expiresAt = bridge.expiresAt, expiresAt.timeIntervalSinceNow <= 10 {
            playbackNotice = "Alternate Audio bridge expired • prepare it again"
            store.status = playbackNotice
            store.recordAlternateAudioFailure(playbackNotice)
            return
        }

        guard alternateAudioMasterEnabled,
              StableFeatureGateManager.isEnabled(.alternateAudioHandoff) else {
            playbackNotice = "Alternate Audio is Off • original playback preserved"
            store.cancelAlternateAudioBridgePreparation(clearPrepared: true, reason: "Alternate Audio disabled before handoff")
            return
        }

        let resumeSeconds = max(0, authoritativeCurrentSeconds)
        let resumePlayback = isPlaying
        if alternateAudioHandoffState == .idle || alternateAudioHandoffState == .failed || alternateAudioHandoffState == .restoring {
            alternateAudioSavedAudioTrackIndex = ksSelectedAudioTrackIndex
            alternateAudioSavedAudioMode = selectedAudioMode
        }

        // Phase 4 is explicitly KSPlayer-owned. If the user temporarily selected another
        // internal engine, convert the existing presentation in place instead of creating
        // a second root player screen or changing the stable CatalogStore playback URL.
        if !forceKSPlayerSurface {
            player?.pause()
            if let timeObserver, let player { player.removeTimeObserver(timeObserver) }
            timeObserver = nil
            statusObserver?.invalidate()
            statusObserver = nil
            nativePrepareTask?.cancel()
            nativePrepareTask = nil
            player = nil
            forceAetherSurface = false
            forceVLCSurface = false
            forceKSPlayerSurface = true
            selectedPlaybackMode = "KS Direct + Alternate Audio"
        }

        retiringAlternateAudioBridgeUUID = activeAlternateAudioBridgeUUID
        pendingAlternateAudioBridgeUUID = bridge.id
        alternateAudioHandoffGeneration &+= 1
        let generation = alternateAudioHandoffGeneration
        guard let handoffID = store.beginSessionOwnedExperimentalPlaybackHandoff(
            to: bridge.hlsURL,
            feature: .alternateAudioHandoff,
            presentationID: playbackPresentationID,
            reason: "Switching to synchronized Alternate Audio bridge…"
        ) else {
            playbackNotice = "Alternate Audio handoff rejected • original playback preserved"
            store.recordAlternateAudioFailure(playbackNotice)
            return
        }

        alternateAudioHandoffID = handoffID
        alternateAudioHandoffState = .switching
        alternateAudioExpectedResumeSeconds = resumeSeconds
        alternateAudioDidIssueResumeCorrection = false
        selectedAudioMode = "Alternate English"
        ksSelectedAudioTrackIndex = nil
        // Subtitle selection state is intentionally retained. External subtitles reattach
        // to the new HLS source, and an embedded index is re-applied when present.
        ksTrackSelectionSerial &+= 1
        currentSeconds = resumeSeconds
        ksStartTimeSeconds = resumeSeconds
        ksSeekSeconds = resumeSeconds
        ksSeekIsAbsolute = true
        preparedPlaybackURL = bridge.hlsURL
        ksSurfaceToken &+= 1
        isPlaying = resumePlayback
        resetFirstFrameGate(message: "Switching to synchronized English audio…")
        playbackNotice = "Alternate Audio switching • preserving \(formatTime(resumeSeconds)) • \(bridge.classification)"
        store.status = playbackNotice
        startPlayerClock()

        alternateAudioHandoffRecoveryTask?.cancel()
        alternateAudioHandoffRecoveryTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: 18_000_000_000)
            guard !Task.isCancelled,
                  generation == alternateAudioHandoffGeneration,
                  alternateAudioHandoffState == .switching,
                  store.sessionOwnedExperimentalPlaybackHandoffIsCurrent(
                    handoffID,
                    presentationID: playbackPresentationID,
                    experimentalURL: bridge.hlsURL
                  ) else { return }
            store.recordAlternateAudioFailure("Alternate Audio handoff did not reach a stable first frame; original audio restored.")
            restoreOriginalAudio(
                reason: "Alternate Audio did not reach a stable first frame — original audio restored.",
                clearSelection: false
            )
        }
        showControlsWithoutChangingFocus()
    }

    private func handleAlternateAudioPlaybackClock(
        current: Double,
        total _: Double,
        surfaceToken: Int,
        sourceURL: URL
    ) {
        guard !isLivePlayback,
              surfaceToken == ksSurfaceToken,
              sourceURL == activePlaybackURL else { return }

        if alternateAudioHandoffState == .restoring, sourceURL == url {
            alternateAudioHandoffRecoveryTask?.cancel()
            alternateAudioHandoffRecoveryTask = nil
            alternateAudioHandoffState = .idle
            alternateAudioHandoffID = nil
            selectedAudioMode = alternateAudioSavedAudioMode
            playbackNotice = "Original audio active • position preserved"
            return
        }

        guard (alternateAudioHandoffState == .switching || alternateAudioHandoffState == .active),
              sourceURL != url,
              let handoffID = alternateAudioHandoffID,
              store.sessionOwnedExperimentalPlaybackHandoffIsCurrent(
                handoffID,
                presentationID: playbackPresentationID,
                experimentalURL: sourceURL
              ) else { return }

        if alternateAudioHandoffState == .switching,
           !alternateAudioDidIssueResumeCorrection,
           alternateAudioExpectedResumeSeconds >= 8,
           current.isFinite,
           abs(current - alternateAudioExpectedResumeSeconds) > 3.0 {
            alternateAudioDidIssueResumeCorrection = true
            ksSeekSeconds = alternateAudioExpectedResumeSeconds
            ksSeekIsAbsolute = true
            ksSeekSerial &+= 1
            playbackNotice = "Alternate Audio aligned to \(formatTime(alternateAudioExpectedResumeSeconds))"
            return
        }

        guard current.isFinite, current > 0.01 else { return }
        if alternateAudioHandoffState == .switching {
            alternateAudioHandoffState = .active
            let newlyActiveBridgeUUID = pendingAlternateAudioBridgeUUID
            pendingAlternateAudioBridgeUUID = nil
            activeAlternateAudioBridgeUUID = newlyActiveBridgeUUID
            if let retired = retiringAlternateAudioBridgeUUID, retired != newlyActiveBridgeUUID {
                store.cancelAlternateAudioBridgeSession(
                    retired,
                    presentationID: playbackPresentationID,
                    reason: "Replacement Alternate Audio bridge reached stable playback — retired bridge released."
                )
            }
            retiringAlternateAudioBridgeUUID = nil
            alternateAudioHandoffRecoveryTask?.cancel()
            alternateAudioHandoffRecoveryTask = nil
            store.completeSessionOwnedExperimentalPlaybackHandoff(
                handoffID,
                presentationID: playbackPresentationID,
                reason: "Alternate Audio active • synchronized bridge • \(store.alternateAudioSyncOffsetMS)ms"
            )
            playbackNotice = "Alternate English audio active • \(store.alternateAudioSyncOffsetMS)ms"
        }
    }

    @discardableResult
    private func handleAlternateAudioPlaybackFailure(
        message: String,
        surfaceToken: Int,
        sourceURL: URL
    ) -> Bool {
        guard !isLivePlayback,
              surfaceToken == ksSurfaceToken,
              sourceURL == activePlaybackURL,
              sourceURL != url,
              (alternateAudioHandoffState == .switching || alternateAudioHandoffState == .active) else { return false }
        alternateAudioHandoffState = .failed
        Phase13RolloutManager.recordUnrecoverablePlaybackFailure("Alternate Audio failed: \(message)")
        restoreOriginalAudio(
            reason: "Alternate Audio failed (\(message)) — original audio restored.",
            clearSelection: false
        )
        return true
    }

    private func restoreOriginalAudio(reason: String, clearSelection: Bool) {
        guard !isLivePlayback else { return }
        let hasLocalAlternateAudio = localAlternateAudioURL != nil
        let hasLegacyBridgeSource = activePlaybackURL != nil && activePlaybackURL != url
        guard hasLocalAlternateAudio || hasLegacyBridgeSource ||
              alternateAudioHandoffState == .switching ||
              alternateAudioHandoffState == .active ||
              alternateAudioHandoffState == .failed else {
            if clearSelection {
                selectedAlternateAudioIndex = nil
                selectedAudioMode = "Auto"
                store.selectAlternateAudioSource(nil, for: item)
                store.cancelAlternateAudioBridgePreparation(clearPrepared: true)
            }
            playbackNotice = "Original audio is already active"
            store.status = playbackNotice
            return
        }

        alternateAudioHandoffGeneration &+= 1
        alternateAudioHandoffRecoveryTask?.cancel()
        alternateAudioHandoffRecoveryTask = nil
        alternateAudioHandoffState = .restoring
        localAlternateAudioURL = nil
        localAlternateAudioTrackIndex = nil
        localAlternateAudioHTTPHeaders = [:]
        preparedPlaybackURL = nil

        let ownedHandoffID = alternateAudioHandoffID
        alternateAudioHandoffID = nil
        let bridgesToRelease = Set([activeAlternateAudioBridgeUUID, pendingAlternateAudioBridgeUUID, retiringAlternateAudioBridgeUUID].compactMap { $0 })
        activeAlternateAudioBridgeUUID = nil
        pendingAlternateAudioBridgeUUID = nil
        retiringAlternateAudioBridgeUUID = nil
        store.clearSessionOwnedExperimentalPlaybackHandoff(
            store.experimentalPlaybackHandoffID == ownedHandoffID ? ownedHandoffID : nil,
            presentationID: playbackPresentationID,
            reason: reason
        )
        store.cancelAlternateAudioBridgePreparation(clearPrepared: true, reason: reason)
        for bridgeUUID in bridgesToRelease {
            store.cancelAlternateAudioBridgeSession(bridgeUUID, presentationID: playbackPresentationID, reason: reason)
        }

        // Removing externalAudioURL makes the existing KS surface stop the hidden audio-only
        // layer and unmute its already-decoding original audio. No video URL replacement,
        // player recreation, or seek is required.
        alternateAudioHandoffState = .idle
        if clearSelection {
            selectedAlternateAudioIndex = nil
            selectedAudioMode = "Auto"
            alternateAudioSavedAudioMode = "Auto"
            alternateAudioSavedAudioTrackIndex = nil
            store.selectAlternateAudioSource(nil, for: item)
        } else {
            selectedAudioMode = alternateAudioSavedAudioMode
        }
        playbackNotice = reason
        store.status = reason
        showControlsWithoutChangingFocus()
    }

    private func applyAlternateAudioSelection() {
        if let source = store.selectedAlternateAudioSource {
            playbackNotice = "Alternate Audio copy saved • \(source.matchClassification) • local English auto-select ready"
            store.status = "Saved \(source.displayTitle). Use This Audio keeps the current video playing and locally selects English audio from this copy."
        } else {
            playbackNotice = "Alternate Audio candidate cleared"
            store.status = "Alternate Audio candidate cleared. Original audio remains active."
        }
        showControlsWithoutChangingFocus()
    }

    private func automaticFailoverResumeTarget() -> Double {
        AutomaticSourceFailoverPolicy.normalizedResumeSeconds(
            authoritativeCurrentSeconds,
            pendingAutomaticResumeSeconds,
            resumeEntry?.seconds
        )
    }

    private func shouldRetrySameSourceBeforeFailover(_ message: String) -> Bool {
        guard startupSameSourceRetryCount < 1, !hasStableFirstFramePlayback else { return false }
        let lower = message.lowercased()
        if lower.contains("unsupported")
            || lower.contains("codec")
            || lower.contains("no video")
            || lower.contains("format")
            || lower.contains("adaptive source grace period") {
            return false
        }
        return lower.contains("timeout")
            || lower.contains("timed out")
            || lower.contains("network")
            || lower.contains("connection")
            || lower.contains("http")
            || lower.contains("server")
            || lower.contains("eof")
            || lower.contains("read")
            || lower.contains("resource")
    }

    @discardableResult
    private func attemptAutomaticSourceFailover(message: String, failedURL: URL) -> Bool {
        guard !isLivePlayback,
              failedURL == url,
              activePlaybackURL == failedURL,
              !hasStableFirstFramePlayback,
              alternateAudioHandoffState == .idle,
              store.experimentalPlaybackHandoffID == nil else { return false }

        // vBRDC171: cold debrid/network starts occasionally report a transient read error
        // before the exact same URL succeeds on the next open. Retry that selected URL once
        // in-place before abandoning the user's chosen link for the ranked fallback list.
        if shouldRetrySameSourceBeforeFailover(message) {
            startupSameSourceRetryCount += 1
            startupSameSourceRetryTask?.cancel()
            retryText = "Retrying selected link once…"
            playbackNotice = "Selected source had a transient startup error • retrying same link"
            errorText = nil
            isLoading = true
            startupSameSourceRetryTask = Task { @MainActor in
                try? await Task.sleep(nanoseconds: 1_200_000_000)
                guard !Task.isCancelled,
                      store.playbackPresentationID == playbackPresentationID,
                      store.playbackURL == url,
                      activePlaybackURL == failedURL,
                      !hasStableFirstFramePlayback else { return }
                setupPlayer()
                startupSameSourceRetryTask = nil
            }
            return true
        }

        let resumeTarget = automaticFailoverResumeTarget()
        saveResumePositionIfNeeded(force: true)
        guard let context = store.beginAutomaticSourceFailover(
            after: failedURL,
            resumeSeconds: resumeTarget,
            failureReason: message,
            hasStableFirstFrame: hasStableFirstFramePlayback
        ) else { return false }

        automaticSourceFailoverWatchdogTask?.cancel()
        automaticSourceFailoverWatchdogTask = nil
        retryText = AutomaticSourceFailoverContext.notice
        playbackNotice = "\(AutomaticSourceFailoverContext.notice) • \(context.attempt)/\(context.availableFallbacks)"
        errorText = nil
        isLoading = true
        return true
    }

    private func publishPlaybackFailureWithoutFailover(_ message: String, engine: String) {
        isLoading = false
        store.cancelPlaybackLaunchTransition(presentationID: playbackPresentationID)
        forceControlsVisibleForNavigation()
        let stableSuffix = hasStableFirstFramePlayback
            ? " Automatic switching is disabled after stable playback begins."
            : " No additional compatible ranked links remain."
        errorText = message + "\n\nEngine: \(engine)." + stableSuffix
        store.status = "Playback failure on \(engine): \(message)" + stableSuffix
    }

    private var automaticSourceStartupGraceSeconds: Double {
        let hint = [store.playbackAdaptiveCacheHint, store.playbackLinkLabel, vodSourceInfoChipLabel]
            .joined(separator: " ")
            .lowercased()
        let uncached = hint.contains("cache-health=uncached")
            || hint.contains(" uncached")
            || hint.contains("[uncached]")
        let seeders: Int? = {
            guard let range = hint.range(of: #"seeders[=: ]+([0-9]+)"#, options: .regularExpression) else { return nil }
            return Int(hint[range].filter(\.isNumber))
        }()
        if uncached {
            if let seeders, seeders <= 10 { return 42 }
            if let seeders, seeders <= 25 { return 36 }
            return 30
        }
        if hint.contains("remux") || hint.contains("2160") || hint.contains("4k") || hint.contains("uhd") {
            return 25
        }
        return 21
    }

    private func armAutomaticSourceFailoverWatchdog() {
        automaticSourceFailoverWatchdogTask?.cancel()
        automaticSourceFailoverWatchdogTask = nil
        guard !isLivePlayback,
              activePlaybackURL == url,
              store.experimentalPlaybackHandoffID == nil,
              let index = store.playbackFallbackURLs.firstIndex(of: url),
              store.playbackFallbackURLs.indices.contains(index + 1) else { return }

        let startupGrace = automaticSourceStartupGraceSeconds
        automaticSourceFailoverWatchdogTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: UInt64(startupGrace * 1_000_000_000))
            guard !Task.isCancelled,
                  store.playbackPresentationID == playbackPresentationID,
                  store.playbackURL == url,
                  activePlaybackURL == url,
                  !hasStableFirstFramePlayback,
                  errorText == nil else { return }

            if bufferedPlaybackSeconds > 0.35 {
                try? await Task.sleep(nanoseconds: 9_000_000_000)
                guard !Task.isCancelled,
                      store.playbackPresentationID == playbackPresentationID,
                      store.playbackURL == url,
                      activePlaybackURL == url,
                      !hasStableFirstFramePlayback,
                      errorText == nil else { return }
            }
            _ = attemptAutomaticSourceFailover(
                message: "Startup did not reach a stable first frame after the adaptive source grace period.",
                failedURL: url
            )
        }
    }

    private func markStableFirstFrameReady(engine: String, reason: String) {
        automaticSourceFailoverWatchdogTask?.cancel()
        automaticSourceFailoverWatchdogTask = nil
        aetherCompatibilityWatchdogTask?.cancel()
        aetherCompatibilityWatchdogTask = nil
        if !hasStableFirstFramePlayback {
            hasStableFirstFramePlayback = true
            store.completeAutomaticSourceFailover(presentationID: playbackPresentationID)
        }
        markFirstFrameReady(engine: engine, reason: reason)
    }

    private func markFirstFrameReady(engine: String, reason: String) {
        guard store.playbackPresentationID == playbackPresentationID,
              store.playbackURL == url else { return }
        guard !isFirstFrameReady else { return }
        PlaybackLaunchBenchmark.shared.mark(sessionID: playbackPresentationID, "first frame accepted by player screen")
        isFirstFrameReady = true
        isLoading = false
        ksLoadingCoverActive = false
        retryText = nil
        playbackNotice = playbackNotice.isEmpty ? "\(engine) first frame ready." : playbackNotice
        store.status = "\(engine): first frame ready (\(reason))."
        store.completePlaybackLaunchTransition(presentationID: playbackPresentationID)
        forceControlsVisibleForNavigation(lockOverlay: false)
        scheduleAutoHide()
    }

    private func resetFirstFrameGate(message: String? = nil) {
        firstFrameProbeTask?.cancel()
        firstFrameProbeTask = nil
        isFirstFrameReady = false
        isLoading = true
        vodBootstrapDeadline = Date().addingTimeInterval(isLivePlayback ? 1.8 : 2.8)
        retryText = message ?? loadingMessage
    }

    private func startAVFirstFrameProbe(output: AVPlayerItemVideoOutput, player av: AVPlayer, label: String) {
        firstFrameProbeTask?.cancel()
        firstFrameProbeTask = Task { @MainActor in
            while !Task.isCancelled {
                let itemTime = output.itemTime(forHostTime: CACurrentMediaTime())
                if output.hasNewPixelBuffer(forItemTime: itemTime) {
                    markStableFirstFrameReady(engine: label, reason: "first rendered pixel buffer")
                    return
                }
                if av.status == .failed || av.currentItem?.status == .failed { return }
                retryText = "Buffering Video..."
                try? await Task.sleep(nanoseconds: 80_000_000)
            }
        }
    }

    private func normalizeStoredVODEngineIfNeeded() {
        if UserDefaults.standard.object(forKey: "vodInternalPlayerEngine") == nil {
            vodInternalPlayerEngine = "aether"
        }
        let normalized = vodInternalPlayerEngine.lowercased()
        if normalized != "aether" && normalized != "ksplayer" {
            vodInternalPlayerEngine = "aether"
            store.status = "Legacy VOD engine preference removed. VOD default restored to AetherEngine."
        }
        // vBRDC294: never rewrite an explicit stored KSPlayer preference. Previous migration
        // code could run inside a newly-created player surface after Settings had already saved
        // KSPlayer, which made the VOD default appear not to stick. Mark the legacy migration
        // complete without changing a valid user selection.
        if !aetherPrimaryDefaultMigrationV1 {
            aetherPrimaryDefaultMigrationV1 = true
        }
    }

    private func normalizedLiveTVEnginePreference() -> String {
        liveTVInternalPlayerEngine.lowercased() == "ksplayer" ? "ksplayer" : "aether"
    }

    /// vBRDC264: engine handoff state is deliberately separate from durable resume state.
    /// A manual Aether <-> KS transition captures the live decoder clock first, persists it,
    /// then clears only engine-local retry/seek state. It must never re-arm an older resume
    /// checkpoint during the handoff because that makes the new engine jump backwards.
    private func captureCurrentVODEngineHandoffPosition() -> Double {
        guard !isLivePlayback else { return 0 }
        let local = currentSeconds.isFinite ? max(0, currentSeconds) : 0
        let position = max(local, authoritativeCurrentSeconds)
        guard position.isFinite else { return 0 }
        if position >= 8 {
            // Current-session handoff is intentionally separate from durable startup resume.
            // The normal checkpoint writer owns persistence; do not block the main thread on
            // a synchronous disk write just because the user changes engines.
            resumePersistenceFloorSeconds = max(resumePersistenceFloorSeconds, position)
        }
        return position
    }

    private func clearTransientPlaybackStateForManualEngineSwitch(preserving handoffSeconds: Double) {
        guard !isLivePlayback else {
            ksStartTimeSeconds = 0
            ksSeekSeconds = 0
            ksSeekIsAbsolute = false
            vlcSeekSeconds = 0
            return
        }
        automaticResumeTask?.cancel()
        automaticResumeTask = nil
        startupSameSourceRetryTask?.cancel()
        startupSameSourceRetryTask = nil
        firstFrameProbeTask?.cancel()
        firstFrameProbeTask = nil

        // Manual engine switching is not a new playback session. Do not call
        // applyAutomaticResumeIfAvailable() here: the current session position is newer than
        // the durable startup checkpoint and is the only valid handoff target.
        pendingAutomaticResumeSeconds = nil
        didApplyAutomaticResumeSeek = false
        didAttemptAutomaticResume = true
        automaticResumeSeekAttempts = 0
        automaticResumeLastSeekRequestAt = .distantPast
        automaticResumeConfirmedAt = nil
        ksStartTimeSeconds = 0
        ksSeekSeconds = 0
        ksSeekIsAbsolute = false
        vlcSeekSeconds = 0
        if handoffSeconds.isFinite, handoffSeconds > 0 {
            currentSeconds = handoffSeconds
            resumePersistenceFloorSeconds = max(resumePersistenceFloorSeconds, handoffSeconds)
        }
    }

    private func preferredCompatibilityFallbackEngine() -> PlayerEngine? {
        if UniversalCodecSupport.ksPlayerCompiledIn {
            return .ksplayer
        }
        return nil
    }

    private func setupPlayer() {
        PlaybackLaunchBenchmark.shared.mark(sessionID: playbackPresentationID, "AetherEngine screen bootstrap")
        // vBRDC235: AetherEngine is the primary VOD/Live TV renderer. KSPlayer remains
        // the first compatibility fallback and AVPlayer remains a manual/native route.
        normalizeStoredVODEngineIfNeeded()
        let mediaFlowConfigurationError = MediaFlowProxyRouter.configurationError(kind: mediaFlowRouteKind)
        nativePrepareTask?.cancel()
        startupLoadingTask?.cancel()
        firstFrameProbeTask?.cancel()
        automaticResumeTask?.cancel()
        startupSameSourceRetryTask?.cancel()
        startupSameSourceRetryTask = nil
        timelineScrubAutoSeekTask?.cancel()
        timelineScrubAutoSeekTask = nil
        renderWatchdogTask?.cancel()
        statusObserver?.invalidate()
        if let endObserver { NotificationCenter.default.removeObserver(endObserver) }
        endObserver = nil
        if let timeObserver, let player { player.removeTimeObserver(timeObserver) }
        timeObserver = nil
        player?.pause()
        player = nil

        forceVLCSurface = false
        forceKSPlayerSurface = false
        forceAetherSurface = false
        livePlayerFallbackReason = ""
        vodEngineFallbackReason = "None"
        avToKSFallbackAttempted = false
        playerCompatibilityToast = nil
        avRetryAttemptedForCurrentURL = false
        if let mediaFlowError = mediaFlowConfigurationError {
            isPlaying = false
            isLoading = false
            isFirstFrameReady = false
            errorText = mediaFlowError
            retryText = "MediaFlow configuration required"
            playbackNotice = "MediaFlow Proxy blocked direct playback"
            store.status = mediaFlowError
            forceControlsVisibleForNavigation()
            return
        }
        let selectedSourceOpening = !isLivePlayback && store.playbackLinkLabel.localizedCaseInsensitiveContains("Opening selected")
        resetFirstFrameGate(message: selectedSourceOpening ? "Opening Stream…" : (isLivePlayback ? "Opening Stream…" : "Preparing Playback..."))
        errorText = nil
        retryText = "Preparing player…"
        focusedControl = .playPause
        focusedZone = .chips
        preparedPlaybackURL = nil
        localAlternateAudioURL = nil
        localAlternateAudioTrackIndex = nil
        localAlternateAudioHTTPHeaders = [:]
        alternateAudioHandoffRecoveryTask?.cancel()
        alternateAudioHandoffRecoveryTask = nil
        alternateAudioHandoffID = nil
        alternateAudioHandoffState = .idle
        alternateAudioHandoffGeneration &+= 1
        alternateAudioExpectedResumeSeconds = 0
        alternateAudioDidIssueResumeCorrection = false
        alternateAudioSavedAudioTrackIndex = nil
        alternateAudioSavedAudioMode = "Auto"
        // v1016: resetFirstFrameGate has already armed the bounded startup deadline
        // (1.8 s for Live TV, 2.8 s for VOD). Do not erase it here. This is the fallback
        // that releases the current loading screen if KSPlayer's first clock callback is late.
        pendingAutomaticResumeSeconds = nil
        didApplyAutomaticResumeSeek = false
        // vBRDC266: every fresh playback/source setup must re-arm the shared durable
        // resume lookup for both Aether and KS. Engine handoffs do not call setupPlayer.
        didAttemptAutomaticResume = false
        automaticResumeSeekAttempts = 0
        automaticResumeLastSeekRequestAt = .distantPast
        automaticResumeConfirmedAt = nil
        ksPlayAssertionSerial = 0
        ksStartTimeSeconds = 0
        vlcSeekSeconds = 0
        ksSeekSeconds = 0
        ksSeekIsAbsolute = false
        let profile = UniversalCodecSupport.profile(for: url, hint: store.playbackLinkLabel)
        realAudioTracks = []
        realSubtitleTracks = []
        realAudioTrackLabels = []
        realSubtitleTrackLabels = []
        selectedRealAudioTrackIndex = nil
        selectedRealSubtitleTrackIndex = nil
        ksSelectedAudioTrackIndex = nil
        ksSelectedSubtitleTrackIndex = nil
        ksSelectedExternalSubtitleURL = nil
        selectedAudioMode = "Detecting"
        selectedSubtitleMode = "Off"
        if !isLivePlayback { seedSourceIntelligenceTrackMetadata() }
        // v764 emergency stability: skip startup AVURLAsset real-track probing. Crash logs showed SIGTRAP in loadRealMediaTrackMetadata(from:) on playback start.
        // Track labels fall back to Source Intelligence/player-reported metadata without blocking playback.
        // if !isLivePlayback { loadRealMediaTrackMetadata(from: url) }
        if isLivePlayback {
                preparedPlaybackURL = url
            currentSeconds = 0
            durationSeconds = 0
            hasRecoveredSeekableMetadata = false
            retryText = "Starting Live TV…"
        } else {
            // Always reset the visible VOD clock on a fresh stream. Resume must be an actual
            // player seek, not a leftover progress label from the previous playback session.
            currentSeconds = 0
            durationSeconds = 0
            hasRecoveredSeekableMetadata = false
            applyAutomaticResumeIfAvailable()
            let resumeStartupText = retryText
            // v965: the temporary 5GB/10GB/Unlimited proxy cache has been
            // removed. VOD always opens the selected hosted source directly.
            preparedPlaybackURL = url
            if resumeStartupText == nil || resumeStartupText == "Preparing player…" {
                retryText = "Opening direct stream…"
            }
            if store.automaticSourceFailoverContext(for: playbackPresentationID) == nil {
                store.status = "VOD direct stream: temporary proxy cache removed."
            }
        }
        nativeProfileText = profile.diagnostic
        if metadataRuntimeSeconds <= 0 { metadataRuntimeSeconds = runtimeSeconds(for: item) }
        currentSeconds = max(currentSeconds, 0)
        startPlayerClock()
        // v1085: timeline recovery stays player-owned, but network metadata waits until
        // the first frame so JSON decoding/state publication cannot compete with startup.
        startTimelineMetadataRecoveryMonitor()

        if isLivePlayback {
            // v347: Live TV full playback now uses KSPlayer as the default route.
            // The guide preview also uses KSPlayer, but it is suppressed before opening full playback
            // so the preview surface cannot create double audio.
            DispatchQueue.main.async {
                guard isLivePlayback else { return }
                liveQuickGuideModel.loadPlaybackQuickGuideSnapshot()
            }
            controlsVisible = false
            liveQuickGuideVisible = false
        }

        if !isLivePlayback, let externalTarget = defaultExternalTargetForCurrentItem() {
            isLoading = true
            isFirstFrameReady = false
            forceControlsVisibleForNavigation()
            playbackNotice = "Opening in \(externalTarget.rawValue) by default from Settings."
            store.status = "External player default enabled for \(item.type): opening \(item.title) in \(externalTarget.rawValue)."
            guard let externalStreamURL = mediaFlowPlaybackURL(url) else {
                errorText = "MediaFlow Proxy is enabled but the playback URL could not be wrapped."
                store.status = errorText ?? "MediaFlow Proxy routing failed."
                return
            }
            ExternalPlayerLauncher.open(externalTarget, streamURL: externalStreamURL, title: item.title, subtitles: store.playbackSubtitleURLs.map(\.absoluteString)) { message in
                store.status = message
            }
            return
        }

        if !isLivePlayback {
            armAutomaticSourceFailoverWatchdog()
        }

        if isLivePlayback {
            let legacyOverride = livePlayerOverride.lowercased()
            if legacyOverride == "avplayer" || legacyOverride == "vlc" {
                livePlayerOverride = "auto"
            }
            let selectedLiveEngine = legacyOverride == "ksplayer" ? "ksplayer" : normalizedLiveTVEnginePreference()
            if selectedLiveEngine == "ksplayer" {
                retryText = "Opening Stream…"
                switchToKSPlayerEngine(manual: false)
                return
            }
            // vBRDC257 stabilization: Live TV must enter Aether through the same complete
            // engine-transition path as VOD/manual engine switching. v256 set the surface flags
            // directly here, bypassing reset/startup/watchdog/session cleanup owned by
            // switchToAetherEngine(). That left Live TV with a partially initialized Aether
            // session and made failures look like a permanent loading screen. Keep Aether first,
            // but use the real transition path so first-frame/failure recovery is deterministic.
            retryText = "Opening Stream…"
            switchToAetherEngine(manual: false)
            controlsVisible = false
            liveQuickGuideVisible = false
            playbackNotice = "Player: AetherEngine • KSPlayer compatibility fallback armed • quick guide available with UP/DOWN • \(profile.diagnostic)"
            store.status = "Opening Live TV with AetherEngine."
            return
        }

        if vodInternalPlayerEngine.lowercased().contains("ks") {
            switchToKSPlayerEngine(manual: false)
        } else {
            forceAetherSurface = true
            forceKSPlayerSurface = false
            forceVLCSurface = false
            isPlaying = true
            ksSurfaceToken += 1
            armStartupLoadingGate(engine: "AetherEngine")
            scheduleAutomaticResumeAfterSurfaceStart()
            playbackNotice = "AetherEngine primary VOD • KSPlayer compatibility fallback armed • \(profile.diagnostic)"
            store.status = "VOD playback: AetherEngine primary."
        }

    }


    private func startNativeLivePlaybackDirect(url: URL, profile: NativePlaybackProfile) {
        nativePrepareTask?.cancel()
        guard let networkURL = MediaFlowProxyRouter.playbackURLIfAllowed(for: url, kind: .liveTV) else {
            publishPlaybackFailureWithoutFailover("MediaFlow Proxy is enabled but Live TV could not be routed through the configured home proxy.", engine: "MediaFlow")
            return
        }
        let headers: [String: String] = [
            "User-Agent": "DebridChannels-tvOS/1.0 LiveTV",
            "Accept": "application/vnd.apple.mpegurl,application/x-mpegURL,video/*,application/octet-stream,*/*;q=0.8",
            "Accept-Encoding": "identity",
            "Connection": "keep-alive"
        ]
        let asset = AVURLAsset(url: networkURL, options: ["AVURLAssetHTTPHeaderFieldsKey": headers])
        let item = AVPlayerItem(asset: asset)
        let videoOutput = AVPlayerItemVideoOutput(pixelBufferAttributes: [
            kCVPixelBufferPixelFormatTypeKey as String: Int(kCVPixelFormatType_32BGRA)
        ] as [String: Any])
        item.add(videoOutput)
        item.preferredForwardBufferDuration = profile.isHLS ? 8 : 15
        let av = AVPlayer(playerItem: item)
        av.automaticallyWaitsToMinimizeStalling = true
        #if os(tvOS)
                av.preventsDisplaySleepDuringVideoPlayback = true
                #endif
        player = av
        preparedPlaybackURL = url
        isLoading = true
        isFirstFrameReady = false
        errorText = nil
        attachNativePlayerObservers(item: item, player: av)
        startAVFirstFrameProbe(output: videoOutput, player: av, label: "AVPlayer Live TV")
        av.play()
    }

    private func prepareNativeAssetAndStart(url: URL, profile: NativePlaybackProfile) {
        guard let networkURL = MediaFlowProxyRouter.playbackURLIfAllowed(for: url, kind: mediaFlowRouteKind, upstreamHeaders: isLivePlayback ? [:] : store.playbackHTTPHeaders) else {
            publishPlaybackFailureWithoutFailover("MediaFlow Proxy is enabled but the stream could not be routed through the configured home proxy.", engine: "MediaFlow")
            return
        }
        var headers: [String: String] = [
            "User-Agent": "DebridChannels-tvOS/1.0 KSPlayer/VLC",
            "Accept": "video/mp4,video/quicktime,application/vnd.apple.mpegurl,application/x-mpegURL,video/*,application/octet-stream,*/*;q=0.8",
            "Accept-Encoding": "identity",
            "Connection": "keep-alive",
            "Range": "bytes=0-"
        ]
        // vBRDC089: AVPlayer is a manual compatibility path, but protected plugin/FebBox
        // sources must still carry the provider's request context when the user selects it.
        // Range remains player-owned so a provider cannot pin every segmented request to a
        // stale byte range.
        for (name, value) in MediaFlowProxyRouter.playerRequestHeaders(for: mediaFlowRouteKind, upstreamHeaders: store.playbackHTTPHeaders) {
            let lower = name.lowercased()
            guard !["host", "content-length", "transfer-encoding", "range", "content-range"].contains(lower) else { continue }
            if let existing = headers.keys.first(where: { $0.caseInsensitiveCompare(name) == .orderedSame }) {
                headers.removeValue(forKey: existing)
            }
            headers[name] = value
        }
        let options: [String: Any] = ["AVURLAssetHTTPHeaderFieldsKey": headers]
        let asset = AVURLAsset(url: networkURL, options: options)

        nativePrepareTask = Task { @MainActor in
            do {
                // Load the real AVFoundation properties before making the visible player.
                // If these fail, AVPlayer would usually become audio-only/black or stutter.
                let playable = try await asset.load(.isPlayable)
                let tracks = try await asset.load(.tracks)
                let duration = try? await asset.load(.duration)
                let mediaCharacteristics = try? await asset.load(.availableMediaCharacteristicsWithMediaSelectionOptions)
                let videoTracks = tracks.filter { $0.mediaType == .video }
                let audioTracks = tracks.filter { $0.mediaType == .audio }

                guard !Task.isCancelled,
                      store.playbackPresentationID == playbackPresentationID,
                      store.playbackURL == url else { return }
                guard playable else {
                    handleNativePreparationFailure("AVPlayer rejected this asset as not playable before render.")
                    return
                }
                if videoTracks.isEmpty && !profile.isAppleContainer && !profile.isNativeDolbyVisionPreferred {
                    let audioCount = audioTracks.count
                    handleNativePreparationFailure("AVPlayer only exposed audio tracks (\(audioCount)) and no video track before render for \(profile.diagnostic).")
                    return
                }

                let itemAsset = AVPlayerItem(asset: asset)
                let videoOutput = AVPlayerItemVideoOutput(pixelBufferAttributes: [
                    kCVPixelBufferPixelFormatTypeKey as String: Int(kCVPixelFormatType_32BGRA)
                ] as [String: Any])
                itemAsset.add(videoOutput)
                itemAsset.preferredForwardBufferDuration = profile.isHLS ? 60 : 180
                itemAsset.canUseNetworkResourcesForLiveStreamingWhilePaused = true
                itemAsset.preferredPeakBitRate = 0
                itemAsset.preferredMaximumResolution = CGSize(width: 4096, height: 2160)
                itemAsset.seekingWaitsForVideoCompositionRendering = false

                let av = AVPlayer(playerItem: itemAsset)
                av.appliesMediaSelectionCriteriaAutomatically = true
                av.automaticallyWaitsToMinimizeStalling = true
                #if os(tvOS)
                av.preventsDisplaySleepDuringVideoPlayback = true
                #endif
                #if os(tvOS)
                av.allowsExternalPlayback = false
                #endif

                player = av
                #if os(visionOS)
                SignalVisionPlaybackHandoff.shared.updateEngine(activeEngineName, avPlayer: av)
                #endif
                let durationText = duration.map { CMTimeGetSeconds($0).isFinite ? "duration \(Int(CMTimeGetSeconds($0)))s" : "duration live/unknown" } ?? "duration pending"
                let characteristicsText = mediaCharacteristics?.map { $0.rawValue }.joined(separator: ",") ?? "characteristics pending"
                playbackNotice = "AVPlayer ready • \(profile.diagnostic) • \(videoTracks.count) video track(s) • no bitrate cap • 4K/DV native path."
                store.status = "AVPlayer validation passed: \(videoTracks.count) video track(s), \(audioTracks.count) audio track(s), \(durationText), \(characteristicsText). Starting hardware playback path."
                attachNativePlayerObservers(item: itemAsset, player: av)
                startAVFirstFrameProbe(output: videoOutput, player: av, label: "AVPlayer VOD")
                // v688: wait for readyToPlay before starting AVPlayer so tvOS Match Content
                // handshakes once for the final validated item instead of during preparation.
                isPlaying = true
            } catch {
                guard !Task.isCancelled else { return }
                handleNativePreparationFailure("AVPlayer asset preparation failed for \(profile.diagnostic): \(error.localizedDescription)")
            }
        }
    }

    private func handleNativePreparationFailure(_ message: String) {
        if !usingInternalNonAVEngine {
            if isLivePlayback {
                retryText = "AVPlayer rejected this Live TV stream; falling back to KSPlayer…"
                errorText = nil
                store.status = "AVPlayer preparation failed: \(message). Falling back to KSPlayer."
                switchToKSPlayerEngine(manual: false)
            } else {
                let profile = UniversalCodecSupport.profile(for: url, hint: store.playbackLinkLabel)
                if shouldAutoFallbackFromAVPlayer(message: message, profile: profile) {
                    fallbackFromAVPlayer(reason: "AVPlayer unsupported container/codec")
                    return
                }
                if attemptAutomaticSourceFailover(message: message, failedURL: url) { return }
                isLoading = false
                forceControlsVisibleForNavigation()
                retryText = "AVPlayer could not use this stream; fallback engines are available."
                errorText = message + "\n\nVOD defaults to KSPlayer. AVPlayer remains the manual native compatibility choice; use external Infuse if needed."
                store.status = "AVPlayer VOD preparation failed: \(message)"
            }
            return
        }
        isLoading = false
        forceControlsVisibleForNavigation()
        store.status = message
        #if canImport(TVVLCKit)
        if UniversalCodecSupport.vlcCompiledIn {
            retryText = "AVPlayer could not use this stream; fallback engines are available."
            errorText = message + "\n\nVOD defaults to KSPlayer. AVPlayer remains the manual native compatibility choice; use external Infuse if needed."
        } else {
            errorText = message + "\n\nVOD defaults to KSPlayer. AVPlayer remains the manual native compatibility choice; use external Infuse if needed."
        }
        #else
        errorText = message + "\n\nVOD defaults to KSPlayer. AVPlayer remains the manual native compatibility choice; use external Infuse if needed."
        #endif
    }

    private func shouldAutoFallbackFromAVPlayer(message: String, profile: NativePlaybackProfile) -> Bool {
        guard !isLivePlayback, !avToKSFallbackAttempted else { return false }
        if profile.isMatroskaOrUnsupportedContainer || profile.isLikelyUnsupportedAudioOnlyRisk || profile.requiresVLCForContainer { return true }
        let lower = (message + " " + profile.normalizedHint).lowercased()
        return lower.contains("unsupported") ||
            lower.contains("not playable") ||
            lower.contains("mkv") ||
            lower.contains("matroska") ||
            lower.contains("codec") ||
            lower.contains("audio-only") ||
            lower.contains("no video")
    }

    private func fallbackFromAVPlayer(reason: String) {
        guard !avToKSFallbackAttempted else { return }
        avToKSFallbackAttempted = true
        vodEngineFallbackReason = reason
        let resumeTarget = max(currentSeconds, pendingAutomaticResumeSeconds ?? 0)
        playerCompatibilityToast = "Switching player for compatibility..."
        DispatchQueue.main.asyncAfter(deadline: .now() + 2.4) {
            if playerCompatibilityToast == "Switching player for compatibility..." { playerCompatibilityToast = nil }
        }
        retryText = "Switching player for compatibility..."
        errorText = nil
        store.status = "VOD fallback: \(reason). Preserving stream URL and resuming at \(formatTime(resumeTarget))."
        switch preferredCompatibilityFallbackEngine() {
        case .ksplayer:
            switchToKSPlayerEngine(manual: false, fallbackReason: reason, startAt: resumeTarget >= 8 ? resumeTarget : nil)
        default:
            isLoading = false
            forceControlsVisibleForNavigation()
            errorText = "AVPlayer could not play this stream and no internal compatibility fallback is compiled into this IPA."
        }
    }

    private func attachNativePlayerObservers(item itemAsset: AVPlayerItem, player av: AVPlayer) {
        statusObserver = itemAsset.observe(\.status, options: [.new, .initial]) { observedItem, _ in
            DispatchQueue.main.async {
                guard store.playbackPresentationID == playbackPresentationID,
                      store.playbackURL == url else { return }
                switch observedItem.status {
                case .readyToPlay:
                    let readyDuration = CMTimeGetSeconds(observedItem.duration)
                    if readyDuration.isFinite && readyDuration > 1 {
                        if abs(durationSeconds - readyDuration) > 0.05 { durationSeconds = readyDuration }
                        hasRecoveredSeekableMetadata = true
                    }
                    let dimensions = observedItem.presentationSize
                    let event = observedItem.accessLog()?.events.last
                    let bitrateText = event.map { "observed \(Int($0.observedBitrate))bps / indicated \(Int($0.indicatedBitrate))bps" } ?? "bitrate pending"
                    let sizeText = dimensions.width > 8 ? "\(Int(dimensions.width))×\(Int(dimensions.height))" : "video size pending"
                    playbackNotice = "\(activeEngineName) playing • \(nativeProfileText) • \(sizeText) • \(bitrateText)"
                    store.status = "Playback route: \(activeEngineName); \(nativeProfileText); video size \(sizeText); \(bitrateText); selected \(store.playbackLinkLabel)"
                    applyEnglishDefaultsForAVPlayerIfAvailable(observedItem)
                    av.play()
                    if !isPlaying { isPlaying = true }
                    startRenderWatchdog(for: observedItem, player: av)
                    scheduleAutoHide()
                case .failed:
                    let message = observedItem.error?.localizedDescription ?? "The selected stream could not be played."
                    if isLivePlayback && !forceAetherSurface && !forceKSPlayerSurface && !forceVLCSurface {
                        retryText = "AVPlayer stopped on this Live TV stream; falling back to KSPlayer…"
                        errorText = nil
                        store.status = "AVPlayer Live TV failed: \(message). Falling back to KSPlayer without closing playback."
                        switchToKSPlayerEngine(manual: false)
                        return
                    }
                    if !isLivePlayback && !usingInternalNonAVEngine {
                        let profile = UniversalCodecSupport.profile(for: url, hint: store.playbackLinkLabel)
                        if shouldAutoFallbackFromAVPlayer(message: message, profile: profile) {
                            fallbackFromAVPlayer(reason: "AVPlayer unsupported container/codec")
                            return
                        }
                    }
                    if attemptAutomaticSourceFailover(message: message, failedURL: url) { return }
                    publishPlaybackFailureWithoutFailover(message, engine: activeEngineName)
                default:
                    break
                }
            }
        }

        timeObserver = av.addPeriodicTimeObserver(forInterval: CMTime(seconds: 0.25, preferredTimescale: 600), queue: .main) { time in
            guard store.playbackPresentationID == playbackPresentationID,
                  store.playbackURL == url else { return }
            if !forceVLCSurface {
                currentSeconds = CMTimeGetSeconds(time).isFinite ? CMTimeGetSeconds(time) : 0
                saveResumePositionIfNeeded()
            }
                if let duration = av.currentItem?.duration {
                let seconds = CMTimeGetSeconds(duration)
                if seconds.isFinite && seconds > 1 {
                    if abs(durationSeconds - seconds) > 0.05 { durationSeconds = seconds }
                    hasRecoveredSeekableMetadata = true
                }
            }
            if !forceVLCSurface {
                // vBRDC206: AVPlayer's `.waitingToPlayAtSpecifiedRate` is buffering, not
                // a user pause. Treating every non-playing state as Pause used to trigger
                // durable resume/Trakt/catalog work during network stalls and near EOF.
                switch av.timeControlStatus {
                case .playing:
                    if !isPlaying { isPlaying = true }
                case .paused:
                    if isSeriesPlayback {
                        let total = resolvedDurationSeconds
                        let elapsed = authoritativeCurrentSeconds
                        if total.isFinite, total > 30, elapsed.isFinite, elapsed >= max(0, total - 0.20) {
                            handleNaturalEpisodeEnd(reason: "AVPlayer paused at natural completion")
                        }
                    }
                    if isPlaying { isPlaying = false }
                case .waitingToPlayAtSpecifiedRate:
                    break
                @unknown default:
                    break
                }
            }
        }

        endObserver = NotificationCenter.default.addObserver(forName: .AVPlayerItemDidPlayToEndTime, object: itemAsset, queue: .main) { _ in
            guard store.playbackPresentationID == playbackPresentationID,
                  store.playbackURL == url else { return }
            if !isLivePlayback, !isSeriesPlayback {
                TraktSyncManager.shared.markCompleted(item: item, duration: resolvedDurationSeconds)
                PlaybackResumeCacheManager.shared.clear(for: item)
                isPlaying = false
            } else if isSeriesPlayback {
                handleNaturalEpisodeEnd(reason: "AVPlayer natural completion")
                isPlaying = false
            }
            if !isSeriesPlayback {
                controlsVisible = true
                focusedControl = .playPause
            }
        }

        if !store.playbackSubtitleURLs.isEmpty {
            store.status = "Captured \(store.playbackSubtitleURLs.count) external subtitle URL(s) from the selected Stremio stream."
        }
    }

    private func applyEnglishDefaultsForAVPlayerIfAvailable(_ itemAsset: AVPlayerItem) {
        guard !usingInternalNonAVEngine else { return }
        Task { @MainActor in
            if let audible = try? await itemAsset.asset.loadMediaSelectionGroup(for: .audible) {
                if let english = audible.options.first(where: { Self.mediaOptionLooksEnglish($0) }) {
                    itemAsset.select(english, in: audible)
                    selectedAudioMode = "English"
                }
            }
            if let legible = try? await itemAsset.asset.loadMediaSelectionGroup(for: .legible) {
                if let english = legible.options.first(where: { Self.mediaOptionLooksEnglish($0) }) {
                    itemAsset.select(english, in: legible)
                    selectedSubtitleMode = "English"
                } else {
                    itemAsset.select(nil, in: legible)
                    selectedSubtitleMode = "Off"
                }
            }
        }
    }

    private static func mediaOptionLooksEnglish(_ option: AVMediaSelectionOption) -> Bool {
        let haystack = [option.displayName, option.locale?.identifier ?? "", option.extendedLanguageTag ?? ""]
            .joined(separator: " ")
            .lowercased()
        return haystack.contains("english") || haystack.contains(" eng") || haystack == "en" || haystack.contains(" en-")
    }


    private func teardownLiveTVTransientState() {
        guard isLivePlayback else { return }
        timelineMetadataRecoveryTask?.cancel()
        timelineMetadataRecoveryTask = nil
        automaticResumeTask?.cancel()
        automaticResumeTask = nil
        liveQuickGuideTipTask?.cancel()
        liveQuickGuideTipTask = nil
        liveQuickGuideRefreshTask?.cancel()
        liveQuickGuideRefreshTask = nil
        cancelLiveQuickGuideAutoDismiss()
        clearLiveTVDoubleBackExitArm()
        hideTask?.cancel()
        hideTask = nil
        renderWatchdogTask?.cancel()
        renderWatchdogTask = nil
        statusObserver = nil
        timeObserver = nil
        liveQuickGuideVisible = false
        // A Quick Guide channel switch creates the incoming playback generation before
        // the old screen disappears. Only a real dismissal may clear the shared compact
        // guide; stale/departing generations release their local model only.
        let shouldClearSharedQuickGuide = isDismissingPlayer || store.playbackURL == nil
        liveQuickGuideModel.releasePlaybackQuickGuideSnapshot(clearShared: shouldClearSharedQuickGuide)
        PremiumRemoteImageLoader.cancelObsoletePrefetches(keeping: [])
    }

    private var isInternalVODPlaybackHandoff: Bool {
        guard !isLivePlayback,
              !isDismissingPlayer,
              store.vodExclusivePlaybackActive,
              let incomingURL = store.playbackURL else { return false }
        return store.playbackPresentationID != playbackPresentationID || incomingURL != url
    }

    private func teardownPlayer(forInternalHandoff internalHandoff: Bool = false) {
        timelineScrubAutoSeekTask?.cancel()
        timelineScrubAutoSeekTask = nil
        if !isLivePlayback && !internalHandoff {
            TraktSyncManager.shared.playbackStateChanged(
                item: item,
                seconds: authoritativeCurrentSeconds,
                duration: resolvedDurationSeconds,
                isPlaying: false
            )
            saveResumePositionIfNeeded(force: true, durable: true)
            PlaybackResumeCacheManager.shared.flushSynchronously()
        } else if internalHandoff {
            // Automatic failover checkpoints asynchronously before publishing its new
            // presentation; natural EOF clears completion state before Next Episode.
            // Never synchronously flush disk or publish catalog/Trakt work here.
            print("[VODHandoff][vBRDC200] lightweight outgoing teardown session=\(playbackPresentationID)")
        }
        // Playback-derived shelves recover once CatalogStore actually ends the VOD-exclusive
        // gate. Rebuilding them here duplicates work and can collide with replacement decoder startup.
        hideTask?.cancel()
        nativePrepareTask?.cancel()
        nativePrepareTask = nil
        renderWatchdogTask?.cancel()
        startupLoadingTask?.cancel()
        startupLoadingTask = nil
        automaticSourceFailoverWatchdogTask?.cancel()
        automaticSourceFailoverWatchdogTask = nil
        aetherCompatibilityWatchdogTask?.cancel()
        aetherCompatibilityWatchdogTask = nil
        automaticSourceFailoverToastTask?.cancel()
        automaticSourceFailoverToastTask = nil
        automaticSourceFailoverToast = nil
        firstFrameProbeTask?.cancel()
        firstFrameProbeTask = nil
        runtimeLookupTask?.cancel()
        runtimeLookupTask = nil
        playbackMetadataTask?.cancel()
        playbackMetadataTask = nil
        pendingPlaybackMetadataItem = nil
        timelineMetadataRecoveryTask?.cancel()
        timelineMetadataRecoveryTask = nil
        playbackClockTask?.cancel()
        playbackClockTask = nil
        if let timeObserver, let player { player.removeTimeObserver(timeObserver) }
        statusObserver?.invalidate()
        if let endObserver { NotificationCenter.default.removeObserver(endObserver) }
        endObserver = nil
        player?.pause()
        player = nil
        isFirstFrameReady = false
        preparedPlaybackURL = nil
        localAlternateAudioURL = nil
        localAlternateAudioTrackIndex = nil
        localAlternateAudioHTTPHeaders = [:]
        alternateAudioHandoffRecoveryTask?.cancel()
        alternateAudioHandoffRecoveryTask = nil
        alternateAudioHandoffID = nil
        alternateAudioHandoffState = .idle
        alternateAudioHandoffGeneration &+= 1
        alternateAudioExpectedResumeSeconds = 0
        alternateAudioDidIssueResumeCorrection = false
        alternateAudioSavedAudioTrackIndex = nil
        alternateAudioSavedAudioMode = "Auto"
        vodBootstrapDeadline = nil
        pendingAutomaticResumeSeconds = nil
        didApplyAutomaticResumeSeek = false
        automaticResumeConfirmedAt = nil
        resumePersistenceFloorSeconds = 0
        vodAsyncRuntime.latestBufferedPlaybackSeconds = 0
        pendingVODProductionMetadata = nil
        pendingVODProductionMetadataItemID = nil
    }


    private func presentAutomaticSourceFailoverToast(_ context: AutomaticSourceFailoverContext) {
        automaticSourceFailoverToastTask?.cancel()
        automaticSourceFailoverToast = "\(AutomaticSourceFailoverContext.notice) • ranked source \(context.attempt) of \(context.availableFallbacks)"
        let owner = playbackPresentationID
        automaticSourceFailoverToastTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: 3_200_000_000)
            guard !Task.isCancelled, playbackPresentationID == owner else { return }
            withAnimation(.easeOut(duration: 0.18)) { automaticSourceFailoverToast = nil }
            automaticSourceFailoverToastTask = nil
        }
    }

    private func applyAutomaticResumeIfAvailable() {
        guard !isLivePlayback, !didAttemptAutomaticResume else { return }
        didAttemptAutomaticResume = true
        let failoverContext = store.automaticSourceFailoverContext(for: playbackPresentationID)
        let saved = PlaybackResumeCacheManager.shared.resumeEntry(for: item)
        resumeEntry = saved
        let target = AutomaticSourceFailoverPolicy.normalizedResumeSeconds(
            failoverContext?.resumeSeconds,
            saved?.seconds
        )

        if let failoverContext {
            retryText = AutomaticSourceFailoverContext.notice
            playbackNotice = "\(AutomaticSourceFailoverContext.notice) • ranked attempt \(failoverContext.attempt)/\(failoverContext.availableFallbacks)"
            store.status = playbackNotice
            presentAutomaticSourceFailoverToast(failoverContext)
        }

        guard target >= 8 else { return }
        pendingAutomaticResumeSeconds = target
        didApplyAutomaticResumeSeek = false
        automaticResumeSeekAttempts = 0
        automaticResumeLastSeekRequestAt = .distantPast
        resumePersistenceFloorSeconds = target
        // vBRDC266: seed the shared internal-player surface with the durable checkpoint.
        // Both Aether and KSPlayer own an explicit startTimeSeconds path; using it makes
        // resume deterministic even when an engine does not publish an early 0:00 clock
        // callback soon enough for the retry seek lane. The retry lane remains as backup.
        ksStartTimeSeconds = target
        ksSeekIsAbsolute = true
        vlcSeekSeconds = target
        ksSeekSeconds = target
        if failoverContext != nil {
            retryText = "\(AutomaticSourceFailoverContext.notice)… resume queued for \(formatTime(target))"
            playbackNotice = "Automatic source recovery • resume queued at \(formatTime(target))"
            store.status = playbackNotice
        } else {
            retryText = "Opening stream… automatic resume queued for \(formatTime(target))…"
            playbackNotice = "Automatic resume queued at \(formatTime(target)). Backup chip stays available until the player confirms the jump."
            store.status = "Resume playback: \(item.title) will jump to \(formatTime(target)) after the player surface is ready."
        }
    }

    private func scheduleAutomaticResumeAfterSurfaceStart() {
        guard !isLivePlayback, let target = pendingAutomaticResumeSeconds, target >= 8, !didApplyAutomaticResumeSeek else { return }
        automaticResumeTask?.cancel()
        automaticResumeTask = Task { @MainActor in
            // KSPlayer resume is driven by its real decoder clock callback below. AVPlayer
            // does not use that callback, so poll only until its item becomes seek-ready.
            for delay in [0.35, 0.70, 1.10, 1.60, 2.20, 3.00] {
                do { try await Task.sleep(nanoseconds: UInt64(delay * 1_000_000_000)) }
                catch { return }
                guard !Task.isCancelled else { return }
                guard store.playbackPresentationID == playbackPresentationID,
                      store.playbackURL == url else { return }
                guard errorText == nil else { continue }
                guard pendingAutomaticResumeSeconds == target, !didApplyAutomaticResumeSeek else { return }

                if forceAetherSurface || forceKSPlayerSurface {
                    // Aether/KS decoder callbacks call reconcileAutomaticResumePlaybackClock.
                    // Do not pre-seed seekSerial before the surface exists because makeUIView
                    // can absorb that serial as its initial value without performing the seek.
                    continue
                }
                if forceVLCSurface {
                    requestAutomaticResumeSeek(target, minimumInterval: 1.20)
                    continue
                }
                if player?.currentItem?.status == .readyToPlay {
                    requestAutomaticResumeSeek(target, minimumInterval: 1.20)
                }
            }
            if pendingAutomaticResumeSeconds == target, !didApplyAutomaticResumeSeek {
                retryText = "Playback started • waiting for the player to confirm resume at \(formatTime(target))…"
                playbackNotice = "Automatic resume remains armed at \(formatTime(target)); the saved checkpoint is protected."
            }
        }
    }

    private func requestAutomaticResumeSeek(_ target: Double, minimumInterval: TimeInterval = 0.85) {
        guard !isLivePlayback, pendingAutomaticResumeSeconds == target, target >= 8, !didApplyAutomaticResumeSeek else { return }
        let now = Date()
        if automaticResumeSeekAttempts > 0, now.timeIntervalSince(automaticResumeLastSeekRequestAt) < minimumInterval { return }
        guard automaticResumeSeekAttempts < 6 else {
            playbackNotice = "Automatic resume is still armed at \(formatTime(target)). Use Resume if this source ignores seek commands."
            return
        }
        automaticResumeSeekAttempts += 1
        automaticResumeLastSeekRequestAt = now
        seekAbsolute(target, directionSeconds: 0, revealControls: false, markAutomaticResume: true, precise: true)
        retryText = "Applying saved position \(formatTime(target))…"
        store.status = "Automatic resume seek requested (attempt \(automaticResumeSeekAttempts))."
    }

    private func reconcileAutomaticResumePlaybackClock(current: Double) {
        guard !isLivePlayback, current.isFinite,
              let target = pendingAutomaticResumeSeconds, target >= 8, !didApplyAutomaticResumeSeek else { return }

        // Allow a small decoder/keyframe tolerance. A value beyond the target is also a
        // successful resume (for example a stream that lands on the next decodable frame).
        if current + 4 >= target {
            confirmAutomaticResume(target: target, confirmedSeconds: current)
            return
        }

        // Any real KS clock callback means the surface is mounted and its Coordinator can
        // observe a changed seekSerial. This avoids vBRDC072's reload/startPlayTime race.
        requestAutomaticResumeSeek(target)
    }

    private func confirmAutomaticResume(target: Double, confirmedSeconds: Double) {
        guard pendingAutomaticResumeSeconds == target, !didApplyAutomaticResumeSeek else { return }
        didApplyAutomaticResumeSeek = true
        pendingAutomaticResumeSeconds = nil
        resumePersistenceFloorSeconds = 0
        automaticResumeTask?.cancel()
        automaticResumeTask = nil

        // vBRDC077: automatic resume is a complete startup action, not just a seek.
        // KSPNUVIO pauses its player while applying an in-place seek. Some sources can
        // land on the saved decoder clock after that pause without automatically resuming
        // presentation. Reassert the UI-owned play state after the clock confirms the
        // target so reopening a movie/episode always continues playing without a second
        // Siri Remote Play press. The KS surface separately guards its post-seek play
        // assertion with currentShouldPlay, so a real user pause still wins.
        isPlaying = true
        automaticResumeConfirmedAt = Date()
        liveQuickGuideVisible = false
        scheduleAutoHide()
        if forceAetherSurface || forceKSPlayerSurface {
            // `isPlaying` is normally already true here, so assigning true again cannot
            // drive updateUIView. The serial is the authoritative post-resume Play pulse.
            ksPlayAssertionSerial &+= 1
        } else if !forceVLCSurface {
            player?.play()
        }

        let landed = confirmedSeconds.isFinite && confirmedSeconds > 0 ? confirmedSeconds : target
        retryText = "Resumed from \(formatTime(landed)); cache still warming…"
        playbackNotice = "Automatic resume confirmed at \(formatTime(landed)) • playback continuing automatically • cache-ahead remains active."
        store.status = "Automatic resume confirmed and playing: \(formatTime(landed))."
    }

    private func forceResumeFromSavedPosition() {
        guard let saved = resumeEntry else { return }
        seekAbsolute(saved.seconds, directionSeconds: 0, revealControls: true, markAutomaticResume: true, precise: true)
        didApplyAutomaticResumeSeek = true
        pendingAutomaticResumeSeconds = nil
        isPlaying = true
        automaticResumeConfirmedAt = Date()
        if forceAetherSurface || forceKSPlayerSurface { ksPlayAssertionSerial &+= 1 }
        liveQuickGuideVisible = false
        playbackNotice = "Manual resume applied at \(formatTime(saved.seconds))."
        store.status = "Manual resume backup: jumped to \(formatTime(saved.seconds))."
    }

    private func saveResumePositionIfNeeded(force: Bool = false, durable: Bool = false) {
        guard !isLivePlayback else { return }
        // Ordinary checkpoints still require exact playback ownership. A final durable
        // teardown/background checkpoint may arrive after ordered dismissal has already
        // cleared the store owner; allow only that bounded final save through.
        guard durable || (
            store.playbackPresentationID == playbackPresentationID &&
            store.playbackURL == url
        ) else { return }
        let elapsed = authoritativeCurrentSeconds
        guard elapsed.isFinite, elapsed >= 8 else { return }

        // v1150: issuing the v1130 resume-only KSPlayer reload briefly creates a new surface
        // whose first callbacks can report 0:00 before startPlayTime/seek lands. Preserve the
        // previous durable checkpoint until the real decoder clock reaches the queued target.
        if resumePersistenceFloorSeconds >= 8 {
            if elapsed + 4 < resumePersistenceFloorSeconds { return }
            resumePersistenceFloorSeconds = 0
        }

        if !force, Date().timeIntervalSince(lastResumeSaveAt) < 5 { return }
        lastResumeSaveAt = Date()
        // vBRDC209: a periodic resume checkpoint is never allowed to declare playback
        // complete. The old >=95% branch called Trakt stop + cloud playback refresh and
        // cleared Resume every five seconds through the final minutes of an episode. That
        // overlapped Up Next and could starve the video/compositor while audio continued.
        // Completion is now owned exclusively by the actual player EOF callback/fallback.
        PlaybackResumeCacheManager.shared.saveProgress(
            item: item,
            seconds: elapsed,
            duration: resolvedDurationSeconds,
            synchronously: durable
        )
    }

    private func defaultExternalTargetForCurrentItem() -> ExternalPlaybackTarget? {
        let lower = item.type.lowercased()
        let isShow = lower.contains("series") || lower.contains("show") || item.seasonNumber != nil || item.episodeNumber != nil
        if isShow {
            if externalShowsInfuseDefault { return .infuse }
            if externalShowsVLCDefault { return .vlc }
            if externalShowsSenPlayerDefault { return .senPlayer }
        } else {
            if externalMoviesInfuseDefault { return .infuse }
            if externalMoviesVLCDefault { return .vlc }
            if externalMoviesSenPlayerDefault { return .senPlayer }
        }
        return nil
    }

    private func openExternal(_ target: ExternalPlaybackTarget) {
        player?.pause()
        isPlaying = false
        forceControlsVisibleForNavigation()
        guard let externalStreamURL = mediaFlowPlaybackURL(url) else {
            store.status = "MediaFlow Proxy is enabled but the playback URL could not be wrapped."
            return
        }
        ExternalPlayerLauncher.open(target, streamURL: externalStreamURL, title: item.title, subtitles: store.playbackSubtitleURLs.map(\.absoluteString)) { message in
            store.status = message
        }
    }

    private func switchToAetherEngine(manual: Bool) {
        if manual, forceAetherSurface {
            playbackNotice = "AetherEngine is already active."
            store.status = playbackNotice
            forceControlsVisibleForNavigation()
            return
        }

        // Fresh startup keeps the proven automatic-resume pipeline. A manual engine handoff
        // instead captures the *current session clock* before touching any transient state.
        let handoffSeconds = manual ? captureCurrentVODEngineHandoffPosition() : 0
        let startupResumeSeconds = pendingAutomaticResumeSeconds ?? 0
        let resumeSeconds = isLivePlayback ? 0 : (manual ? handoffSeconds : max(startupResumeSeconds, max(0, authoritativeCurrentSeconds)))
        if manual { clearTransientPlaybackStateForManualEngineSwitch(preserving: handoffSeconds) }

        aetherCompatibilityWatchdogTask?.cancel()
        aetherCompatibilityWatchdogTask = nil
        if forceKSPlayerSurface {
            // vBRDC267: KSPlayer is session-retained and will intentionally ignore a normal
            // SwiftUI dismantle while the PlaybackSession is active. Explicitly release the
            // outgoing KS decoder/audio graph before mounting Aether so there can never be
            // two active audio owners after KS -> Aether. The PlaybackSession/clock survives.
            PlaybackController.shared.releaseRenderSurfaceForEngineHandoff(sessionID: playbackPresentationID)
        }
        player?.pause()
        if let timeObserver, let player { player.removeTimeObserver(timeObserver) }
        timeObserver = nil
        statusObserver?.invalidate()
        statusObserver = nil
        nativePrepareTask?.cancel()
        player = nil
        if !isLivePlayback && manual { vodInternalPlayerEngine = "aether" }
        if isLivePlayback && manual {
            liveTVInternalPlayerEngine = "aether"
            livePlayerOverride = "auto"
        }
        forceAetherSurface = true
        forceKSPlayerSurface = false
        forceVLCSurface = false
        ksLoadingCoverActive = false
        isPlaying = true
        resetFirstFrameGate(message: manual && !isLivePlayback ? "Switching to AetherEngine…" : "Preparing AetherEngine...")
        errorText = nil
        selectedPlaybackMode = isLivePlayback ? "AetherEngine Live TV" : "AetherEngine"

        if manual && !isLivePlayback {
            // PlaybackKitAetherHost applies startTimeSeconds during its initial load, so one
            // deterministic handoff position is enough; do not re-arm the old durable resume.
            currentSeconds = resumeSeconds
            ksStartTimeSeconds = resumeSeconds
            ksSeekIsAbsolute = true
            ksSeekSeconds = resumeSeconds
        } else {
            // Preserve the accepted v259 startup behavior. Automatic resume remains owned by
            // applyAutomaticResumeIfAvailable()/reconcileAutomaticResumePlaybackClock().
            ksStartTimeSeconds = resumeSeconds
            ksSeekIsAbsolute = true
            ksSeekSeconds = resumeSeconds
        }
        ksSurfaceToken &+= 1
        startPlayerClock()
        armStartupLoadingGate(engine: isLivePlayback ? "AetherEngine Live TV" : "AetherEngine")
        if !manual && !isLivePlayback { scheduleAutomaticResumeAfterSurfaceStart() }

        let routeHint = [store.playbackLinkLabel, store.playbackAdaptiveCacheHint, vodSourceInfoChipLabel]
            .filter { !$0.isEmpty }.joined(separator: " | ")
        let compatibility = AetherPlaybackCompatibilityPolicy.infer(
            url: activePlaybackURL ?? url,
            routeHint: routeHint,
            isLive: isLivePlayback
        )
        let ownedPresentationID = playbackPresentationID
        let ownedURL = url
        let ownedSurfaceToken = ksSurfaceToken
        aetherCompatibilityWatchdogTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: UInt64(compatibility.startupGraceSeconds * 1_000_000_000))
            guard !Task.isCancelled,
                  store.playbackPresentationID == ownedPresentationID,
                  store.playbackURL == ownedURL,
                  forceAetherSurface,
                  ksSurfaceToken == ownedSurfaceToken,
                  !isFirstFrameReady,
                  errorText == nil else { return }
            let resumeAt = isLivePlayback ? nil : authoritativeCurrentSeconds
            playbackNotice = "AetherEngine startup recovery → KSPlayer"
            store.status = "\(compatibility.diagnosticLabel) • no first frame; handing the same source to KSPlayer."
            switchToKSPlayerEngine(manual: false, fallbackReason: compatibility.diagnosticLabel, startAt: resumeAt)
        }

        playbackNotice = manual ? "AetherEngine selected • continuing at \(formatTime(resumeSeconds))." : "AetherEngine primary playback active."
        store.status = compatibility.isHighRisk ? "\(playbackNotice) • \(compatibility.diagnosticLabel)" : playbackNotice
        if isLivePlayback && !manual {
            controlsVisible = false
        } else {
            forceControlsVisibleForNavigation()
        }
    }

    private func switchToAVPlayerEngine(manual: Bool) {
        if forceKSPlayerSurface {
            PlaybackController.shared.releaseRenderSurfaceForEngineHandoff(sessionID: playbackPresentationID)
        }
        if !isLivePlayback, player != nil, preparedPlaybackURL == url, !usingInternalNonAVEngine {
            if manual { vodInternalPlayerEngine = "avplayer" }
            selectedPlaybackMode = "AVPlayer"
            store.status = "AVPlayer already active; no player restart needed."
            forceControlsVisibleForNavigation()
            return
        }
        if isLivePlayback {
            if manual { livePlayerOverride = "avplayer" }
        } else if manual {
            vodInternalPlayerEngine = "avplayer"
            vodEngineFallbackReason = "None"
            avToKSFallbackAttempted = false
        }
        forceAetherSurface = false
        forceKSPlayerSurface = false
        forceVLCSurface = false
        ksLoadingCoverActive = false
        isPlaying = true
        resetFirstFrameGate(message: "Opening with AVPlayer...")
        errorText = nil
        selectedPlaybackMode = isLivePlayback ? "AVPlayer Live TV" : "AVPlayer VOD"
        let profile = UniversalCodecSupport.profile(for: url, hint: store.playbackLinkLabel)
        nativeProfileText = profile.diagnostic
        if isLivePlayback {
            startNativeLivePlaybackDirect(url: url, profile: profile)
            armStartupLoadingGate(engine: "AVPlayer Live TV")
            playbackNotice = manual ? "Player: AVPlayer • saved for this Live TV channel." : "Player: AVPlayer"
            livePlayerFallbackReason = ""
        } else {
            print("[VOD ENGINE] selected=AVPlayer instantiated=AVPlayer diagnostics=AVPlayer")
            prepareNativeAssetAndStart(url: activePlaybackURL ?? url, profile: profile)
            armStartupLoadingGate(engine: "AVPlayer VOD")
            scheduleAutomaticResumeAfterSurfaceStart()
            playbackNotice = manual ? "AVPlayer VOD selected manually." : "AVPlayer VOD selected from saved preference • tvOS Match Frame Rate/Dynamic Range path."
        }
        store.status = playbackNotice
        forceControlsVisibleForNavigation()
    }

    private func switchToKSPlayerEngine(manual: Bool, fallbackReason: String? = nil, startAt startSeconds: Double? = nil) {
        if manual, forceKSPlayerSurface {
            playbackNotice = "KSPlayer is already active."
            store.status = playbackNotice
            forceControlsVisibleForNavigation()
            return
        }
        let handoffSeconds = manual ? captureCurrentVODEngineHandoffPosition() : 0
        // vBRDC266: fresh KS startup consumes the durable resume target directly. Manual
        // engine handoff still uses only the live decoder clock captured above.
        let requestedStartSeconds: Double? = manual ? handoffSeconds : (startSeconds ?? pendingAutomaticResumeSeconds)
        aetherCompatibilityWatchdogTask?.cancel()
        aetherCompatibilityWatchdogTask = nil
        if manual { clearTransientPlaybackStateForManualEngineSwitch(preserving: handoffSeconds) }
        player?.pause()
        if let timeObserver, let player { player.removeTimeObserver(timeObserver) }
        timeObserver = nil
        statusObserver?.invalidate()
        statusObserver = nil
        nativePrepareTask?.cancel()
        player = nil
        if isLivePlayback && manual {
            liveTVInternalPlayerEngine = "ksplayer"
            livePlayerOverride = "auto"
        }
        if !isLivePlayback && manual { vodInternalPlayerEngine = "ksplayer" }
        forceAetherSurface = false
        forceVLCSurface = false
        forceKSPlayerSurface = true
        // vBRDC306: immediately hand visual ownership to the loading cover. Leaving the
        // engine panel mounted above the outgoing renderer made a manual KSPlayer switch
        // look like the previous video frame had frozen.
        activePanel = nil
        selectedPanelOption = nil
        focusedPanelOption = nil
        controlsVisible = false
        ksLoadingCoverActive = true
        ksSelectedAudioTrackIndex = selectedRealAudioTrackIndex.flatMap { index in
            realAudioTracks.indices.contains(index) ? realAudioTracks[index].optionIndex : index
        }
        applyKSSubtitleSelection(at: selectedRealSubtitleTrackIndex)
        ksTrackSelectionSerial += 1
        isPlaying = true
        let selectedSourceOpening = !isLivePlayback && store.playbackLinkLabel.localizedCaseInsensitiveContains("Opening selected")
        resetFirstFrameGate(message: selectedSourceOpening || isLivePlayback ? "Opening Stream…" : "Opening with KSPlayer…")
        errorText = nil
        selectedPlaybackMode = isLivePlayback ? "KSPlayer" : "KS Direct"
        if isLivePlayback { livePlayerFallbackReason = "" }
        if let fallbackReason, !isLivePlayback { vodEngineFallbackReason = fallbackReason }
        ksSurfaceToken &+= 1
        if let requestedStartSeconds, !isLivePlayback, requestedStartSeconds.isFinite, requestedStartSeconds > 0 {
            currentSeconds = requestedStartSeconds
            ksStartTimeSeconds = requestedStartSeconds
            ksSeekIsAbsolute = true
            ksSeekSeconds = requestedStartSeconds
            // The new KS surface consumes startTimeSeconds directly. Bump the serial as a
            // bounded backup for an already-mounted coordinator, without reusing old resume state.
            ksSeekSerial &+= 1
        }
        #if canImport(KSPlayer)
        playbackNotice = isLivePlayback ? (manual ? "Player: KSPlayer • saved as the Live TV default." : "Player: KSPlayer") : (selectedSourceOpening ? "Opening Stream…" : (fallbackReason != nil ? "KSPlayer compatibility fallback active." : (manual ? "KSPlayer selected manually for this stream." : "KSPlayer selected as internal fallback engine.")))
        startPlayerClock()
        armStartupLoadingGate(engine: isLivePlayback ? "KSPlayer Live TV" : "KSPlayer")
        if !manual && !isLivePlayback { scheduleAutomaticResumeAfterSurfaceStart() }
        store.status = playbackNotice
        #else
        if fallbackReason != nil && !isLivePlayback {
            isPlaying = false
            isLoading = false
            ksLoadingCoverActive = false
            forceKSPlayerSurface = false
            playbackNotice = "KSPlayer is not compiled into this IPA."
            errorText = "AVPlayer could not play this container/codec, and KSPlayer is not compiled into this IPA."
            store.status = playbackNotice
        } else {
            playbackNotice = "KSPlayer is not compiled into this IPA. Staying on VLC Internal fallback."
            store.status = playbackNotice
            switchToVLCEngine(manual: false)
        }
        #endif
    }



    private func switchToVLCEngine(manual: Bool) {
        #if canImport(TVVLCKit)
        if forceKSPlayerSurface {
            PlaybackController.shared.releaseRenderSurfaceForEngineHandoff(sessionID: playbackPresentationID)
        }
        player?.pause()
        if let timeObserver, let player { player.removeTimeObserver(timeObserver) }
        timeObserver = nil
        player = nil
        nativePrepareTask?.cancel()
        statusObserver?.invalidate()
        statusObserver = nil
        if isLivePlayback {
            if manual { livePlayerOverride = "vlc" }
            livePlayerFallbackReason = ""
        }
        forceAetherSurface = false
        forceKSPlayerSurface = false
        forceVLCSurface = true
        ksLoadingCoverActive = false
        vlcSurfaceToken += 1
        isPlaying = true
        resetFirstFrameGate(message: "Preparing Playback...")
        errorText = nil
        selectedPlaybackMode = isLivePlayback ? "VLC" : "VLC Internal"
        playbackNotice = isLivePlayback ? (manual ? "Player: VLC • saved for this Live TV channel." : "Player: VLC") : (manual ? "VLC Internal selected manually for this stream." : "Switched to VLC Internal fallback.")
        startPlayerClock()
        armStartupLoadingGate(engine: isLivePlayback ? "VLC Live TV" : "VLC")
        store.status = isLivePlayback ? "\(playbackNotice) • final URL type: \(liveTimingDebugURLType(for: url))" : playbackNotice
        #else
        playbackNotice = "VLC engine unavailable in this build"
        store.status = playbackNotice
        if isLivePlayback {
            errorText = "VLC engine unavailable in this build"
            livePlayerFallbackReason = "TVVLCKit missing/not compiled"
            DispatchQueue.main.asyncAfter(deadline: .now() + 2.0) {
                guard errorText == "VLC engine unavailable in this build" else { return }
                livePlayerOverride = "auto"
                switchToKSPlayerEngine(manual: false)
            }
        }
        #endif
    }

    private func togglePlay() {
        if forceAetherSurface || forceKSPlayerSurface || forceVLCSurface {
            isPlaying.toggle()
            liveQuickGuideVisible = false
            if isPlaying {
                forceControlsVisibleForNavigation(lockOverlay: false)
                scheduleAutoHide()
                store.status = "Playback resumed; auto-hide timer restored."
            } else {
                forceControlsVisible()
                store.status = "Playback paused; controls remain visible."
            }
            return
        }
        guard let player else { return }
        if player.timeControlStatus == .playing {
            player.pause()
            isPlaying = false
            forceControlsVisible()
        } else {
            player.play()
            isPlaying = true
            forceControlsVisibleForNavigation(lockOverlay: false)
            scheduleAutoHide()
        }
    }


    private var scrubDisplaySeconds: Double {
        scrubPreviewSeconds ?? authoritativeCurrentSeconds
    }

    private var scrubDisplayProgress: Double {
        guard resolvedDurationSeconds > 0 else { return progress }
        return max(0, min(1, scrubDisplaySeconds / resolvedDurationSeconds))
    }

    private var scrubPreviewProgress: Double? {
        guard scrubPreviewSeconds != nil else { return nil }
        return scrubDisplayProgress
    }

    private var bufferedPlaybackProgress: Double? {
        guard !isLivePlayback, resolvedDurationSeconds > 0 else { return nil }
        let endpoint = max(bufferedPlaybackSeconds, authoritativeCurrentSeconds)
        return max(0, min(1, endpoint / resolvedDurationSeconds))
    }

    private func scrubTimelineAndSeek(by seconds: Double) {
        guard vodControlShelfExpanded else {
            timelineScrubAutoSeekTask?.cancel()
            timelineScrubAutoSeekTask = nil
            scrubPreviewSeconds = nil
            isScrubbingTimeline = false
            hasAdjustedTimelineScrub = false
            focusedZone = .chips
            focusedControl = .controlDrawer
            return
        }
        guard !isLivePlayback else {
            rejectSeekForNonSeekableStream()
            return
        }
        let duration = max(resolvedDurationSeconds, 1)
        let base = scrubPreviewSeconds ?? authoritativeCurrentSeconds
        let target = max(0, min(duration, base + seconds))

        // v1146: LEFT/RIGHT changes the visible target immediately, then automatically
        // seeks after a tiny debounce. The debounce lets tvOS finish its directional-focus
        // transaction first (avoiding the old v1020 focus drop) while removing v1145's
        // separate second-step commit requirement.
        scrubPreviewSeconds = target
        isScrubbingTimeline = true
        hasAdjustedTimelineScrub = true
        focusedZone = .timeline
        focusedControl = .timeline
        didSeedVODOverlayFocus = true
        vodOverlayLockedForRemoteNavigation = true
        showControlsWithoutChangingFocus()
        presentSeekFeedback(seconds)

        timelineScrubAutoSeekTask?.cancel()
        let owner = playbackPresentationID
        timelineScrubAutoSeekTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: 140_000_000)
            guard !Task.isCancelled,
                  store.playbackPresentationID == owner,
                  store.playbackURL == url,
                  controlsVisible,
                  activePanel == nil,
                  focusedZone == .timeline,
                  scrubPreviewSeconds == target else { return }
            let previous = authoritativeCurrentSeconds
            seekAbsolute(
                target,
                directionSeconds: target - previous,
                revealControls: true,
                markAutomaticResume: false,
                precise: false
            )
            hasAdjustedTimelineScrub = false
            focusedZone = .timeline
            focusedControl = .timeline
            didSeedVODOverlayFocus = true
            store.status = "Timeline seek applied at \(formatTime(target))."
            DispatchQueue.main.async {
                guard self.controlsVisible,
                      self.activePanel == nil,
                      self.focusedZone == .timeline else { return }
                self.focusedControl = .timeline
            }
            timelineScrubAutoSeekTask = nil
        }
        store.status = seconds < 0
            ? "Timeline: seeking back 30 seconds to \(formatTime(target))."
            : "Timeline: seeking forward 60 seconds to \(formatTime(target))."
    }

    private func commitTimelineScrubOrToggleFocus() {
        guard !isLivePlayback else {
            rejectSeekForNonSeekableStream()
            togglePlay()
            return
        }

        // LEFT/RIGHT now auto-commits. If Select arrives during the 90 ms debounce,
        // apply that already-visible target immediately; otherwise Select simply keeps
        // timeline focus and never becomes a required second confirmation step.
        if hasAdjustedTimelineScrub, let target = scrubPreviewSeconds {
            timelineScrubAutoSeekTask?.cancel()
            timelineScrubAutoSeekTask = nil
            let previous = authoritativeCurrentSeconds
            seekAbsolute(target, directionSeconds: target - previous, revealControls: true, markAutomaticResume: false, precise: false)
            hasAdjustedTimelineScrub = false
            isScrubbingTimeline = true
            focusedZone = .timeline
            focusedControl = .timeline
            didSeedVODOverlayFocus = true
            store.status = "Timeline seek applied at \(formatTime(target))."
        } else {
            scrubPreviewSeconds = authoritativeCurrentSeconds
            isScrubbingTimeline = true
            hasAdjustedTimelineScrub = false
            focusedZone = .timeline
            focusedControl = .timeline
            lastKnownControlFocus = .timeline
            forceControlsVisibleForNavigation(lockOverlay: true)
            store.status = "Timeline selected. Press LEFT/RIGHT to seek immediately."
        }
    }

    private func commitTimelineScrubIfNeeded() {
        timelineScrubAutoSeekTask?.cancel()
        timelineScrubAutoSeekTask = nil
        guard !isLivePlayback,
              isScrubbingTimeline,
              hasAdjustedTimelineScrub,
              let target = scrubPreviewSeconds else {
            // No pending directional target means the previous LEFT/RIGHT seek already
            // committed automatically. Leaving the timeline only clears its visual latch.
            scrubPreviewSeconds = nil
            isScrubbingTimeline = false
            hasAdjustedTimelineScrub = false
            return
        }
        seekAbsolute(target, directionSeconds: target - authoritativeCurrentSeconds, revealControls: true, markAutomaticResume: false, precise: false)
        scrubPreviewSeconds = nil
        isScrubbingTimeline = false
        hasAdjustedTimelineScrub = false
    }

    private func seekRelative(_ seconds: Double, revealControls: Bool = true) {
        guard canSeekCurrentPlayback else {
            rejectSeekForNonSeekableStream()
            if revealControls { forceControlsVisibleForNavigation(lockOverlay: true) }
            return
        }
        let upperBound = resolvedDurationSeconds > 0 ? resolvedDurationSeconds : Double.greatestFiniteMagnitude
        let target = max(0, min(upperBound, authoritativeCurrentSeconds + seconds))
        presentSeekFeedback(seconds)
        seekAbsolute(target, directionSeconds: seconds, revealControls: revealControls, precise: false)
    }

    private func presentSeekFeedback(_ seconds: Double) {
        guard !isLivePlayback, abs(seconds) >= 0.5 else { return }
        let displayedSeconds = seconds < 0 ? -30 : 60
        seekFeedbackTask?.cancel()
        withAnimation(.spring(response: 0.24, dampingFraction: 0.78)) {
            seekFeedbackSeconds = displayedSeconds
        }
        seekFeedbackTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: 1_050_000_000)
            guard !Task.isCancelled else { return }
            withAnimation(.easeOut(duration: 0.18)) {
                seekFeedbackSeconds = nil
            }
            seekFeedbackTask = nil
        }
    }

    private func seekAbsolute(_ targetSeconds: Double, directionSeconds: Double = 0, revealControls: Bool = true, markAutomaticResume: Bool = false, precise: Bool = false) {
        guard canSeekCurrentPlayback || markAutomaticResume else {
            rejectSeekForNonSeekableStream()
            if revealControls { forceControlsVisibleForNavigation(lockOverlay: true) }
            return
        }
        let upperBound = resolvedDurationSeconds > 0 ? resolvedDurationSeconds : Double.greatestFiniteMagnitude
        let target = max(0, min(upperBound, targetSeconds))
        let relativeDelta = target - authoritativeCurrentSeconds
        currentSeconds = target
        if markAutomaticResume {
            lastResumeSaveAt = .distantPast
        }
        saveResumePosition(force: true)

        if forceAetherSurface || forceKSPlayerSurface {
            isSeekingInPlayer = true
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.70) { isSeekingInPlayer = false }
            // vBRDC073: automatic resume now uses the same in-place absolute seek path as
            // normal seeking. Recreating KSPlayer here could absorb/lose the resume command
            // during surface setup and caused vBRDC072 to start at 0:00 while claiming success.
            ksStartTimeSeconds = 0
            ksSeekIsAbsolute = true
            ksSeekSeconds = target
            ksSeekSerial &+= 1
            isPlaying = true
            store.status = markAutomaticResume ? "Resume seek requested: \(formatTime(target))." : "KSPlayer seek requested: \(formatTime(target))."
            if revealControls { forceControlsVisibleForNavigation(lockOverlay: true) }
            return
        }


        if forceVLCSurface {
            ksSeekIsAbsolute = false
            vlcSeekSeconds = abs(directionSeconds) > 0.01 ? directionSeconds : relativeDelta
            vlcSeekSerial &+= 1
            store.status = directionSeconds < 0 ? "Rewind 30 seconds." : "Fast-forward 60 seconds."
            if revealControls { forceControlsVisibleForNavigation() }
            return
        }

        guard let player else { return }
        let time = CMTime(seconds: target, preferredTimescale: 600)
        let tolerance = precise ? CMTime.zero : CMTime(seconds: 0.50, preferredTimescale: 600)
        isSeekingInPlayer = true
        player.currentItem?.seekingWaitsForVideoCompositionRendering = false
        player.currentItem?.cancelPendingSeeks()
        player.seek(to: time, toleranceBefore: tolerance, toleranceAfter: tolerance) { finished in
            DispatchQueue.main.async {
                self.isSeekingInPlayer = false
                guard finished else { return }
                self.currentSeconds = target
                if self.isPlaying { player.play() }
                if markAutomaticResume, self.pendingAutomaticResumeSeconds == target {
                    self.confirmAutomaticResume(target: target, confirmedSeconds: target)
                } else {
                    self.store.status = markAutomaticResume ? "Resumed at \(self.formatTime(target))." : "Seeked to \(self.formatTime(target))."
                }
                if revealControls { self.forceControlsVisibleForNavigation(lockOverlay: true) }
            }
        }
        if revealControls { showControlsWithoutChangingFocus() }
    }

    private func startTimelineMetadataRecoveryMonitor() {
        timelineMetadataRecoveryTask?.cancel()
        hasRecoveredSeekableMetadata = resolvedDurationSeconds > 1
        guard !isLivePlayback else { return }
        timelineMetadataRecoveryTask = Task { @MainActor in
            var ticks = 0
            while !Task.isCancelled && ticks < 120 {
                guard store.playbackPresentationID == playbackPresentationID,
                      store.playbackURL == url else { return }
                ticks += 1
                if let currentItem = player?.currentItem {
                    let duration = CMTimeGetSeconds(currentItem.duration)
                    if duration.isFinite && duration > 1 {
                        durationSeconds = duration
                        hasRecoveredSeekableMetadata = true
                    }
                    let seekable = currentItem.seekableTimeRanges
                    if !seekable.isEmpty {
                        hasRecoveredSeekableMetadata = true
                        if durationSeconds <= 1, let range = seekable.last?.timeRangeValue {
                            let start = CMTimeGetSeconds(range.start)
                            let length = CMTimeGetSeconds(range.duration)
                            let end = start + length
                            if end.isFinite && end > 1 { durationSeconds = max(durationSeconds, end) }
                        }
                    }
                    let loaded = currentItem.loadedTimeRanges
                    if durationSeconds <= 1, let range = loaded.last?.timeRangeValue {
                        let end = CMTimeGetSeconds(range.start) + CMTimeGetSeconds(range.duration)
                        if end.isFinite && end > currentSeconds + 30 { durationSeconds = max(durationSeconds, end) }
                    }
                    if currentItem.status == .readyToPlay && currentSeconds > 0.25 { hasRecoveredSeekableMetadata = true }
                } else if forceAetherSurface || forceKSPlayerSurface || forceVLCSurface {
                    hasRecoveredSeekableMetadata = true
                }
                if resolvedDurationSeconds > 1 && hasRecoveredSeekableMetadata && ticks > 6 {
                    store.status = "Timeline metadata recovered; seeking is available."
                    return
                }
                try? await Task.sleep(nanoseconds: 500_000_000)
            }
        }
    }

    private var canSeekCurrentPlayback: Bool {
        if isLivePlayback { return resolvedDurationSeconds.isFinite && resolvedDurationSeconds > 1 }
        if resolvedDurationSeconds.isFinite && resolvedDurationSeconds > 1 { return true }
        if hasRecoveredSeekableMetadata { return true }
        if forceAetherSurface || forceKSPlayerSurface || forceVLCSurface { return true }
        if let item = player?.currentItem, item.status == .readyToPlay { return true }
        return player != nil && isFirstFrameReady
    }

    private func rejectSeekForNonSeekableStream() {
        let reason = isLivePlayback ? "live stream has no fixed duration" : "duration is unavailable"
        print("[Playback] seek rejected: \(reason)")
        store.status = "Seek unavailable: stream is not seekable."
    }

    private func applyVideoFitMode(_ mode: DebridVideoFitMode) {
        vodVideoFitModeRaw = mode.rawValue
        playbackNotice = "Video Fit • \(mode.displayName)"
        store.status = "Video Fit changed to \(mode.displayName) without restarting playback."
        showControlsWithoutChangingFocus()
    }


    private func cleanTrackLabel(_ value: String, fallback: String) -> String {
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        if trimmed.isEmpty || trimmed.lowercased() == "unknown" { return fallback }
        return trimmed
    }

    private var vodTrackPreferenceKey: String {
        "DebridChannels.v669.trackPrefs.\(PlaybackResumeCacheManager.shared.playbackKey(for: item))"
    }

    private func savedTrackPreference(_ key: String) -> String? {
        if let remembered = PerTitlePlaybackMemoryManager.shared.trackPreference(key, for: item) {
            return remembered
        }
        return UserDefaults.standard.dictionary(forKey: vodTrackPreferenceKey)?[key] as? String
    }

    private func saveTrackPreference(_ key: String, value: String) {
        PerTitlePlaybackMemoryManager.shared.rememberTrackPreference(key, value: value, for: item)
        // Keep the legacy exact-title dictionary during the staged rollout so rollback
        // builds retain the user's most recent explicit choice.
        var prefs = UserDefaults.standard.dictionary(forKey: vodTrackPreferenceKey) ?? [:]
        prefs[key] = value
        UserDefaults.standard.set(prefs, forKey: vodTrackPreferenceKey)
    }

    private func preferredTrackIndex(preference: String, tracks: [RealMediaTrackOption], labels: [String], subtitle: Bool) -> Int? {
        let clean = preference.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !clean.isEmpty, clean.caseInsensitiveCompare("Off") != .orderedSame else { return nil }
        if let exact = labels.firstIndex(where: { $0.caseInsensitiveCompare(clean) == .orderedSame }) { return exact }
        let lower = clean.lowercased()
        if lower == "original" { return tracks.firstIndex(where: { $0.isDefault }) ?? tracks.indices.first }
        if lower == "auto" || lower == "english" {
            if let english = tracks.firstIndex(where: { option in
                let haystack = (option.label + " " + option.languageName).lowercased()
                return haystack.contains("english") || haystack.contains(" eng") || haystack == "eng" || haystack.contains(" en ")
            }) { return english }
            return subtitle ? nil : (tracks.firstIndex(where: { $0.isDefault }) ?? tracks.indices.first)
        }
        let words = lower.split(whereSeparator: { !$0.isLetter }).filter { $0.count >= 2 }
        return labels.indices.first(where: { index in
            let haystack = (labels[index] + " " + tracks[index].label + " " + tracks[index].languageName).lowercased()
            return words.contains(where: { haystack.contains($0) })
        })
    }

    private func restorePerTitlePlaybackMemory() {
        subtitleDelayMS = PerTitlePlaybackMemoryManager.shared.subtitleDelayMS(for: item)
    }

    private func setSubtitleDelay(_ value: Int) {
        subtitleDelayMS = min(max(value, -10_000), 10_000)
        PerTitlePlaybackMemoryManager.shared.rememberSubtitleDelayMS(subtitleDelayMS, for: item)
        ksTrackSelectionSerial += 1
        store.status = subtitleDelayMS == 0 ? "Subtitle delay reset." : "Subtitle delay set to \(subtitleDelayMS)ms."
        showControlsWithoutChangingFocus()
    }

    private func adjustSubtitleDelay(by delta: Int) {
        setSubtitleDelay(subtitleDelayMS + delta)
    }

    private func externalSubtitleTrackOptions() -> [RealMediaTrackOption] {
        store.playbackSubtitleURLs.enumerated().map { index, url in
            let last = url.lastPathComponent.removingPercentEncoding ?? url.lastPathComponent
            let cleaned = last.trimmingCharacters(in: .whitespacesAndNewlines)
            return RealMediaTrackOption(
                id: "external-subtitle-\(index)-\(cleaned)",
                optionIndex: index,
                label: cleaned.isEmpty ? "External Subtitle \(index + 1)" : "External • \(cleaned)",
                languageName: MediaTrackLanguageNormalizer.displayName(code: nil, fallback: cleaned),
                codecOrFormat: url.pathExtension.isEmpty ? nil : url.pathExtension.uppercased(),
                isDefault: false,
                isForced: cleaned.lowercased().contains("forced"),
                isSDH: cleaned.lowercased().contains("sdh")
            )
        }
    }

    private func applyKSSubtitleSelection(at combinedIndex: Int?) {
        guard let combinedIndex,
              realSubtitleTracks.indices.contains(combinedIndex) else {
            ksSelectedSubtitleTrackIndex = nil
            ksSelectedExternalSubtitleURL = nil
            return
        }

        let option = realSubtitleTracks[combinedIndex]
        if option.id.hasPrefix("external-subtitle-"),
           store.playbackSubtitleURLs.indices.contains(option.optionIndex) {
            ksSelectedSubtitleTrackIndex = nil
            ksSelectedExternalSubtitleURL = store.playbackSubtitleURLs[option.optionIndex]
        } else {
            ksSelectedExternalSubtitleURL = nil
            ksSelectedSubtitleTrackIndex = option.optionIndex
        }
    }

    private func loadRealMediaTrackMetadata(from mediaURL: URL) {
        let expectedPresentationID = playbackPresentationID
        let expectedPlaybackURL = url
        let asset = AVURLAsset(url: mediaURL, options: ["AVURLAssetHTTPHeaderFieldsKey": [
            "User-Agent": "DebridChannels-tvOS/669 RealTrackProbe",
            "Accept": "video/*,audio/*,application/vnd.apple.mpegurl,application/x-mpegURL,application/octet-stream,*/*;q=0.8",
            "Accept-Encoding": "identity",
            "Range": "bytes=0-"
        ]])
        let externalSubtitleTracks = externalSubtitleTrackOptions()
        Task {
            var audioTracks: [RealMediaTrackOption] = []
            var subtitleTracks: [RealMediaTrackOption] = []
            do {
                _ = try await asset.load(.availableMediaCharacteristicsWithMediaSelectionOptions)
                if let group = try await asset.loadMediaSelectionGroup(for: .audible) {
                    audioTracks = SourceMediaTrackProbeCache.trackOptions(from: group, kind: "Audio")
                }
                if let group = try await asset.loadMediaSelectionGroup(for: .legible) {
                    subtitleTracks = SourceMediaTrackProbeCache.trackOptions(from: group, kind: "Subtitle")
                }
            } catch {
                print("[VOD Tracks] AVAsset track probe failed: \(error.localizedDescription)")
            }
            subtitleTracks.append(contentsOf: externalSubtitleTracks)

            await MainActor.run {
                guard store.playbackPresentationID == expectedPresentationID,
                      store.playbackURL == expectedPlaybackURL else { return }
                realAudioTracks = audioTracks
                realSubtitleTracks = subtitleTracks
                realAudioTrackLabels = audioTracks.map { MediaTrackLanguageNormalizer.conciseLabel(for: $0) }
                realSubtitleTrackLabels = subtitleTracks.map { MediaTrackLanguageNormalizer.conciseLabel(for: $0) }

                if let savedAudio = savedTrackPreference("audio"),
                   let savedIndex = preferredTrackIndex(preference: savedAudio, tracks: audioTracks, labels: realAudioTrackLabels, subtitle: false) {
                    selectedRealAudioTrackIndex = savedIndex
                    selectedAudioMode = realAudioTrackLabels[savedIndex]
                } else if let englishIndex = audioTracks.firstIndex(where: { $0.languageName.lowercased().contains("english") || $0.label.lowercased().contains("english") || $0.label.lowercased().contains(" eng") }) {
                    selectedRealAudioTrackIndex = englishIndex
                    selectedAudioMode = realAudioTrackLabels[englishIndex]
                    if !usingInternalNonAVEngine,
                       let currentItem = player?.currentItem {
                        let optionIndex = audioTracks[englishIndex].optionIndex
                        Task { @MainActor in
                            guard let group = try? await currentItem.asset.loadMediaSelectionGroup(for: .audible),
                                  group.options.indices.contains(optionIndex),
                                  player?.currentItem === currentItem else { return }
                            currentItem.select(group.options[optionIndex], in: group)
                        }
                    }
                } else if let defaultIndex = audioTracks.firstIndex(where: { $0.isDefault }) ?? (audioTracks.isEmpty ? nil : 0) {
                    selectedRealAudioTrackIndex = defaultIndex
                    selectedAudioMode = realAudioTrackLabels[defaultIndex]
                } else {
                    selectedRealAudioTrackIndex = nil
                    selectedAudioMode = "Unknown"
                }

                if savedTrackPreference("subtitle") == "Off" {
                    selectedRealSubtitleTrackIndex = nil
                    selectedSubtitleMode = "Off"
                    if forceKSPlayerSurface {
                        applyKSSubtitleSelection(at: nil)
                        ksTrackSelectionSerial += 1
                    }
                } else if let savedSubtitle = savedTrackPreference("subtitle"),
                          let savedIndex = preferredTrackIndex(preference: savedSubtitle, tracks: subtitleTracks, labels: realSubtitleTrackLabels, subtitle: true) {
                    selectedRealSubtitleTrackIndex = savedIndex
                    selectedSubtitleMode = realSubtitleTrackLabels[savedIndex]
                    if forceKSPlayerSurface {
                        applyKSSubtitleSelection(at: savedIndex)
                        ksTrackSelectionSerial += 1
                    }
                } else {
                    selectedRealSubtitleTrackIndex = nil
                    selectedSubtitleMode = "Off"
                }
            }
        }
    }

    private func updateAetherEmbeddedTracks(audio: [[String: Any]], subtitles: [[String: Any]]) {
        guard forceAetherSurface else { return }

        func map(_ raw: [[String: Any]], kind: String) -> [RealMediaTrackOption] {
            raw.enumerated().compactMap { offset, entry in
                let id = (entry["id"] as? NSNumber)?.intValue ?? (entry["id"] as? Int) ?? -1
                guard id >= 0 else { return nil }
                let label = (entry["label"] as? String)?.trimmingCharacters(in: .whitespacesAndNewlines)
                let language = (entry["language"] as? String)?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
                let codec = (entry["codec"] as? String)?.trimmingCharacters(in: .whitespacesAndNewlines)
                return RealMediaTrackOption(
                    id: "aether-\(kind.lowercased())-\(id)",
                    optionIndex: id,
                    label: (label?.isEmpty == false ? label! : "\(kind) \(offset + 1)"),
                    languageName: MediaTrackLanguageNormalizer.displayName(code: language.isEmpty ? nil : language, fallback: label ?? kind),
                    codecOrFormat: codec?.isEmpty == false ? codec : nil,
                    isDefault: entry["isDefault"] as? Bool ?? false,
                    isForced: entry["isForced"] as? Bool ?? false,
                    isSDH: entry["isSDH"] as? Bool ?? false
                )
            }
        }

        let mappedAudio = map(audio, kind: "Audio")
        let mappedSubtitles = map(subtitles, kind: "Subtitle")
        if !mappedAudio.isEmpty {
            realAudioTracks = mappedAudio
            realAudioTrackLabels = mappedAudio.map { MediaTrackLanguageNormalizer.conciseLabel(for: $0) }
        }
        realSubtitleTracks = mappedSubtitles
        realSubtitleTrackLabels = mappedSubtitles.map { MediaTrackLanguageNormalizer.conciseLabel(for: $0) }

        if let savedAudio = savedTrackPreference("audio"),
           let savedIndex = preferredTrackIndex(preference: savedAudio, tracks: realAudioTracks, labels: realAudioTrackLabels, subtitle: false) {
            selectedRealAudioTrackIndex = savedIndex
            selectedAudioMode = realAudioTrackLabels[savedIndex]
            aetherSelectedAudioTrackID = realAudioTracks[savedIndex].optionIndex
            aetherTrackSelectionSerial += 1
        } else if selectedRealAudioTrackIndex == nil,
                  let englishIndex = realAudioTracks.firstIndex(where: { ($0.label + " " + $0.languageName).lowercased().contains("english") }) {
            selectedRealAudioTrackIndex = englishIndex
            selectedAudioMode = realAudioTrackLabels[englishIndex]
        }

        if savedTrackPreference("subtitle") == "Off" {
            selectedRealSubtitleTrackIndex = nil
            selectedSubtitleMode = "Off"
            aetherSelectedSubtitleTrackID = nil
            aetherSubtitleText = ""
            aetherTrackSelectionSerial += 1
        } else if let savedSubtitle = savedTrackPreference("subtitle"),
                  let savedIndex = preferredTrackIndex(preference: savedSubtitle, tracks: realSubtitleTracks, labels: realSubtitleTrackLabels, subtitle: true) {
            selectedRealSubtitleTrackIndex = savedIndex
            selectedSubtitleMode = realSubtitleTrackLabels[savedIndex]
            aetherSelectedSubtitleTrackID = realSubtitleTracks[savedIndex].optionIndex
            aetherTrackSelectionSerial += 1
        }
        store.status = "AetherEngine exposed real tracks: \(realAudioTrackLabels.count) audio / \(realSubtitleTrackLabels.count) subtitle."
    }

    private func updateKSEmbeddedTracks(audio: [RealMediaTrackOption], subtitles: [RealMediaTrackOption]) {
        guard forceKSPlayerSurface else { return }

        if !audio.isEmpty {
            realAudioTracks = audio
            realAudioTrackLabels = audio.map { MediaTrackLanguageNormalizer.conciseLabel(for: $0) }
        }

        // Embedded KSPlayer tracks and captured external subtitle files share one menu,
        // but retain separate engine identities. Embedded options keep their KS track index;
        // external options keep their URL index and are parsed by PlaybackKit's subtitle bridge.
        let mergedSubtitles = subtitles + externalSubtitleTrackOptions()
        realSubtitleTracks = mergedSubtitles
        realSubtitleTrackLabels = mergedSubtitles.map { MediaTrackLanguageNormalizer.conciseLabel(for: $0) }

        if let savedAudio = savedTrackPreference("audio"),
           let savedIndex = preferredTrackIndex(preference: savedAudio, tracks: realAudioTracks, labels: realAudioTrackLabels, subtitle: false) {
            selectedRealAudioTrackIndex = savedIndex
            selectedAudioMode = realAudioTrackLabels[savedIndex]
            ksSelectedAudioTrackIndex = realAudioTracks[savedIndex].optionIndex
            ksTrackSelectionSerial += 1
        } else if selectedRealAudioTrackIndex == nil,
                  let englishIndex = realAudioTracks.firstIndex(where: { option in
                      let h = (option.label + " " + option.languageName).lowercased()
                      return h.contains("english") || h.contains(" eng") || h == "eng" || h.contains(" en ")
                  }) {
            selectedRealAudioTrackIndex = englishIndex
            selectedAudioMode = realAudioTrackLabels[englishIndex]
            ksSelectedAudioTrackIndex = realAudioTracks[englishIndex].optionIndex
            ksTrackSelectionSerial += 1
        }

        if savedTrackPreference("subtitle") == "Off" {
            selectedRealSubtitleTrackIndex = nil
            selectedSubtitleMode = "Off"
            applyKSSubtitleSelection(at: nil)
            ksTrackSelectionSerial += 1
        } else if let savedSubtitle = savedTrackPreference("subtitle"),
                  let savedIndex = preferredTrackIndex(preference: savedSubtitle, tracks: realSubtitleTracks, labels: realSubtitleTrackLabels, subtitle: true) {
            selectedRealSubtitleTrackIndex = savedIndex
            selectedSubtitleMode = realSubtitleTrackLabels[savedIndex]
            applyKSSubtitleSelection(at: savedIndex)
            ksTrackSelectionSerial += 1
        } else {
            selectedRealSubtitleTrackIndex = nil
            selectedSubtitleMode = "Off"
            applyKSSubtitleSelection(at: nil)
            ksTrackSelectionSerial += 1
        }

        store.status = "KSPlayer exposed real tracks: \(realAudioTrackLabels.count) audio / \(subtitles.count) embedded subtitle / \(store.playbackSubtitleURLs.count) external subtitle."
    }

    private func seedSourceIntelligenceTrackMetadata() {
        guard let summary = store.playbackSourceTrackSummary else { return }
        realAudioTracks = summary.audio
        realSubtitleTracks = summary.subtitles + externalSubtitleTrackOptions()
        realAudioTrackLabels = summary.audio.map { MediaTrackLanguageNormalizer.conciseLabel(for: $0) }
        realSubtitleTrackLabels = realSubtitleTracks.map { MediaTrackLanguageNormalizer.conciseLabel(for: $0) }
        if let firstAudio = realAudioTrackLabels.first {
            selectedRealAudioTrackIndex = 0
            selectedAudioMode = firstAudio
        }
        selectedSubtitleMode = "Off"
        selectedRealSubtitleTrackIndex = nil
    }

    private func selectRealAudioTrack(_ index: Int) {
        guard realAudioTrackLabels.indices.contains(index) else { return }
        selectedRealAudioTrackIndex = index
        selectedAudioMode = realAudioTrackLabels[index]
        saveTrackPreference("audio", value: realAudioTrackLabels[index])
        if forceAetherSurface {
            aetherSelectedAudioTrackID = realAudioTracks.indices.contains(index) ? realAudioTracks[index].optionIndex : index
            aetherTrackSelectionSerial += 1
            store.status = "Selected AetherEngine audio track: \(realAudioTrackLabels[index])."
        } else if forceKSPlayerSurface {
            ksSelectedAudioTrackIndex = realAudioTracks.indices.contains(index) ? realAudioTracks[index].optionIndex : index
            ksTrackSelectionSerial += 1
            store.status = "Selected KSPlayer audio track: \(realAudioTrackLabels[index])."
        } else if !usingInternalNonAVEngine,
                  let currentItem = player?.currentItem,
                  realAudioTracks.indices.contains(index) {
            let optionIndex = realAudioTracks[index].optionIndex
            Task { @MainActor in
                guard let group = try? await currentItem.asset.loadMediaSelectionGroup(for: .audible),
                      group.options.indices.contains(optionIndex),
                      player?.currentItem === currentItem else { return }
                currentItem.select(group.options[optionIndex], in: group)
            }
            store.status = "Selected real audio track: \(realAudioTrackLabels[index])."
        } else {
            store.status = "Real audio track detected: \(realAudioTrackLabels[index]). Track switching depends on the active internal engine exposing that file track."
        }
        showControlsWithoutChangingFocus()
    }

    private func selectRealSubtitleTrack(_ index: Int) {
        guard realSubtitleTrackLabels.indices.contains(index) else { return }
        selectedRealSubtitleTrackIndex = index
        selectedSubtitleMode = realSubtitleTrackLabels[index]
        saveTrackPreference("subtitle", value: realSubtitleTrackLabels[index])
        if forceAetherSurface {
            aetherSelectedSubtitleTrackID = realSubtitleTracks.indices.contains(index) ? realSubtitleTracks[index].optionIndex : index
            aetherTrackSelectionSerial += 1
            store.status = "Selected AetherEngine subtitle track: \(realSubtitleTrackLabels[index])."
        } else if forceKSPlayerSurface {
            applyKSSubtitleSelection(at: index)
            ksTrackSelectionSerial += 1
            let sourceKind = realSubtitleTracks[index].id.hasPrefix("external-subtitle-") ? "external" : "embedded"
            store.status = "Selected KSPlayer \(sourceKind) subtitle track: \(realSubtitleTrackLabels[index])."
        } else if !usingInternalNonAVEngine,
                  let currentItem = player?.currentItem,
                  realSubtitleTracks.indices.contains(index) {
            let optionIndex = realSubtitleTracks[index].optionIndex
            Task { @MainActor in
                guard let group = try? await currentItem.asset.loadMediaSelectionGroup(for: .legible),
                      group.options.indices.contains(optionIndex),
                      player?.currentItem === currentItem else { return }
                currentItem.select(group.options[optionIndex], in: group)
            }
            store.status = "Selected real subtitle track: \(realSubtitleTrackLabels[index])."
        } else {
            store.status = "Real subtitle track selected: \(realSubtitleTrackLabels[index]). External/embedded subtitle rendering depends on the active playback engine."
        }
        showControlsWithoutChangingFocus()
    }

    private func selectAudioOverlayOption(_ option: String) {
        activePanel = .audio
        if forceAetherSurface || forceKSPlayerSurface || forceVLCSurface {
            store.status = "Audio option set to \(option). The active internal engine keeps the stream playing while it applies track preferences."
            showControls()
            return
        }
        cycleMedia(groupCharacteristic: .audible, label: "audio")
    }

    private func selectSubtitleOverlayOption(_ option: String) {
        activePanel = .subtitles
        if option == "Off" {
            selectedRealSubtitleTrackIndex = nil
            selectedSubtitleMode = "Off"
            saveTrackPreference("subtitle", value: "Off")
            if forceAetherSurface {
                aetherSelectedSubtitleTrackID = nil
                aetherSubtitleText = ""
                aetherTrackSelectionSerial += 1
            } else if forceKSPlayerSurface {
                applyKSSubtitleSelection(at: nil)
                ksTrackSelectionSerial += 1
            }
            if let item = player?.currentItem {
                Task { @MainActor in
                    guard let group = try? await item.asset.loadMediaSelectionGroup(for: .legible),
                          player?.currentItem === item else { return }
                    item.select(nil, in: group)
                }
            }
            store.status = "Subtitles are Off. No fake subtitle label is shown."
            showControls()
            return
        }
        if forceAetherSurface || forceKSPlayerSurface || forceVLCSurface {
            store.status = "Subtitle option set to \(option). The active internal engine will use the matching embedded/external track when available."
            showControls()
            return
        }
        cycleMedia(groupCharacteristic: .legible, label: "subtitle")
    }

    private func cycleMedia(groupCharacteristic: AVMediaCharacteristic, label: String) {
        guard !usingInternalNonAVEngine else {
            store.status = "\(label.capitalized) default is set by the active internal engine: real audio/subtitle tracks are listed from the active file when exposed; subtitles default off."
            showControls()
            return
        }
        guard let item = player?.currentItem else {
            store.status = "No alternate \(label) tracks were found in this stream."
            showControls()
            return
        }
        Task { @MainActor in
            guard let group = try? await item.asset.loadMediaSelectionGroup(for: groupCharacteristic),
                  player?.currentItem === item else {
                store.status = "No alternate \(label) tracks were found in this stream."
                showControls()
                return
            }
        let options = group.options
        guard !options.isEmpty else {
            store.status = "No alternate \(label) tracks were found in this stream."
            showControls()
            return
        }
        let current = item.currentMediaSelection.selectedMediaOption(in: group)
        let nextIndex: Int
        if let current, let idx = options.firstIndex(of: current) {
            nextIndex = (idx + 1) % options.count
        } else {
            nextIndex = 0
        }
        item.select(options[nextIndex], in: group)
        let displayName = options[nextIndex].displayName
        if label == "audio" {
            selectedAudioMode = displayName
            saveTrackPreference("audio", value: displayName)
        } else {
            selectedSubtitleMode = displayName
            saveTrackPreference("subtitle", value: displayName)
        }
        store.status = "Selected \(label): \(displayName)"
        showControls()
        }
    }

    private func startRenderWatchdog(for item: AVPlayerItem, player: AVPlayer) {
        renderWatchdogTask?.cancel()
        renderWatchdogTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: 5_000_000_000)
            guard store.playbackPresentationID == playbackPresentationID,
                  store.playbackURL == url,
                  errorText == nil, !usingInternalNonAVEngine else { return }
            let size = item.presentationSize
            let hasVideo = size.width > 8 && size.height > 8
            let likelyPlaying = player.timeControlStatus == .playing || player.rate > 0
            if !hasVideo && likelyPlaying {
                let message = "AVPlayer could not render video for this stream."
                if attemptAutomaticSourceFailover(message: message, failedURL: url) { return }
                publishPlaybackFailureWithoutFailover(message, engine: "AVPlayer")
            }
        }
    }



    private func forceControlsVisible() {
        hideTask?.cancel()
        vodOverlayLockedForRemoteNavigation = true
        withAnimation(.easeInOut(duration: 0.18)) { controlsVisible = true }
    }








    private func forceControlsVisibleForNavigation(lockOverlay: Bool = true) {
        hideTask?.cancel()
        if lockOverlay { vodOverlayLockedForRemoteNavigation = true }
        withAnimation(.easeInOut(duration: 0.16)) { controlsVisible = true }
        if focusedControl == nil { DispatchQueue.main.async { focusedControl = lastKnownControlFocus } }
        scheduleOverlayAutoHideIfAllowed()
    }

    private func showControlsWithoutChangingFocus() {
        hideTask?.cancel()
        withAnimation(.easeInOut(duration: 0.12)) { controlsVisible = true }
        scheduleOverlayAutoHideIfAllowed(delaySeconds: 15)
    }

    private func showControls() {
        hideTask?.cancel()
        // vBRDC076 Playback Priority: active video never shares a full-screen opacity
        // animation transaction with the VOD chrome. Paused playback can retain polish.
        if isPlaying {
            controlsVisible = true
        } else {
            withAnimation(.easeInOut(duration: 0.18)) { controlsVisible = true }
        }
        scheduleAutoHide()
    }

    private func scheduleAutoHide() {
        hideTask?.cancel()
        vodOverlayLockedForRemoteNavigation = false
        scheduleOverlayAutoHideIfAllowed(delaySeconds: 15)
    }

    private func scheduleOverlayAutoHideIfAllowed(delaySeconds: UInt64 = 15) {
        hideTask?.cancel()
        guard !vodCastExplorerOnboardingVisible, activePanel == nil, castExplorerMember == nil, !vodEpisodeBrowserVisible, pendingVODSwitchItem == nil, errorText == nil, !isLoading, isPlaying else { return }
        hideTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: delaySeconds * 1_000_000_000)
            guard !Task.isCancelled else { return }
            guard !vodCastExplorerOnboardingVisible, activePanel == nil, castExplorerMember == nil, !vodEpisodeBrowserVisible, pendingVODSwitchItem == nil, errorText == nil, !isLoading, isPlaying else { return }
            vodOverlayLockedForRemoteNavigation = false
            // v1144: remove the active-playback overlay atomically. Animating the entire
            // chrome tree out competes with the video compositor and, combined with Phase
            // 15 artwork teardown, could present as a one-frame playback hitch.
            controlsVisible = false
        }
    }


    private func resumeStorageKey() -> String {
        let identity = [item.type, item.catalog, item.year, item.title, item.id]
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines).lowercased() }
            .joined(separator: "|")
        let safe = identity.addingPercentEncoding(withAllowedCharacters: .alphanumerics) ?? String(abs(identity.hashValue))
        return "vod.resume.seconds.\(safe)"
    }

    private func saveResumePosition(force: Bool = false) {
        saveResumePositionIfNeeded(force: force)
    }

    private func startPlaybackMetadataHydration(delayNanoseconds: UInt64 = 350_000_000, force: Bool = false) {
        guard !isLivePlayback, isFirstFrameReady else { return }
        // vBRDC162: one player-owned enrichment flight per presentation. Overlay open/close,
        // play/pause and first-frame callbacks may all request hydration, but none may starve
        // another request by repeatedly cancelling it. A generation token prevents a stale
        // cancelled task from clearing or blocking the newer owner.
        if !force, playbackMetadataTask != nil { return }
        if force {
            playbackMetadataTask?.cancel()
            playbackMetadataTask = nil
        }
        vodAsyncRuntime.playbackMetadataGeneration &+= 1
        let requestGeneration = vodAsyncRuntime.playbackMetadataGeneration
        playbackMetadataTask = Task { @MainActor in
            defer {
                if vodAsyncRuntime.playbackMetadataGeneration == requestGeneration {
                    playbackMetadataTask = nil
                }
            }
            if delayNanoseconds > 0 {
                try? await Task.sleep(nanoseconds: delayNanoseconds)
            }
            guard !Task.isCancelled,
                  vodAsyncRuntime.playbackMetadataGeneration == requestGeneration,
                  isFirstFrameReady,
                  store.playbackPresentationID == playbackPresentationID,
                  store.playbackURL == url else { return }
            var enriched = item

            // v996: metadata providers can still be warming up when a direct VOD URL opens.
            // Use one bounded retry for incomplete results instead of permanently keeping a
            // placeholder overlay. This remains player-owned work and never remounts rows.
            for attempt in 0..<3 {
                enriched = await store.playbackMetadata(for: enriched)
                guard !Task.isCancelled,
                      vodAsyncRuntime.playbackMetadataGeneration == requestGeneration,
                      store.playbackPresentationID == playbackPresentationID,
                      store.playbackURL == url else { return }
                if playbackMetadataIsPresentationReady(enriched) || attempt == 2 { break }
                let delay: UInt64 = attempt == 0 ? 1_200_000_000 : 2_400_000_000
                try? await Task.sleep(nanoseconds: delay)
            }

            guard !Task.isCancelled,
                  vodAsyncRuntime.playbackMetadataGeneration == requestGeneration,
                  store.playbackPresentationID == playbackPresentationID,
                  store.playbackURL == url else { return }
            if isFirstFrameReady && !controlsVisible && activePanel == nil {
                // One metadata publication should never invalidate hidden playback chrome.
                // Hold it in memory and publish when the user next opens the overlay.
                pendingPlaybackMetadataItem = enriched
            } else {
                applyPlaybackMetadata(enriched)
            }
        }
    }

    private func playbackMetadataIsPresentationReady(_ value: MediaItem) -> Bool {
        let description = value.description.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let hasDescription = !description.isEmpty
            && !description.contains("no description")
            && !description.contains("metadata is still loading")
        let hasArtwork = !(value.landscapeURL?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ?? true)
            || !(value.posterURL?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ?? true)
        let hasCast = !value.castMembers.isEmpty || !value.cast.isEmpty
        return hasDescription && hasArtwork && hasCast
    }

    private func applyPlaybackMetadata(_ enriched: MediaItem) {
        let stable = store.presentationArtworkRestoredItem(from: enriched)
        guard stable != playbackMetadataItem else { return }
        playbackMetadataItem = stable
        publishVODSystemNowPlayingMetadata()
        // vBRDC158: if VOD itself is the first place a Search/Favorites title resolves its
        // clearlogo, upgrade the durable favorite snapshot immediately. The snapshot merge
        // never lets a later no-logo shell erase richer artwork.
        let favoriteKeys = favoriteMediaKeySet(UserDefaults.standard.string(forKey: "favoriteMediaIds") ?? "")
        if !favoriteKeys.isDisjoint(with: mediaFavoriteKeys(for: stable)) {
            persistFavoriteMediaSnapshot(stable)
        }
        if isFirstFrameReady { showVODCastExplorerOnboardingIfNeeded() }
        if let current = store.playbackItem,
           current.id == item.id || !mediaFavoriteKeys(for: current).isDisjoint(with: mediaFavoriteKeys(for: stable)) {
            store.playbackItem = stable
        }
        if vodSupplementalInfoPanelEnabled, isFirstFrameReady {
            // vBRDC162: Search/Favorites shells may receive TMDB/IMDb identity only after
            // playback begins. Re-run the single-flight Production fetch with the enriched
            // item immediately instead of waiting for an overlay close/reopen cycle.
            loadVODProductionMetadata(for: stable, delayNanoseconds: 120_000_000, force: !vodProductionMetadata.hasUsefulContent)
        }
        if !isPlaying {
            loadVODReviewScore(for: stable, delayNanoseconds: 500_000_000)
            if resolvedDurationSeconds <= 1 {
                startRuntimeMetadataLookupIfNeeded(force: true)
            }
        }
    }

    private func applyPlaybackSnapshot(_ snapshot: PlaybackSnapshot) {
        guard !isLivePlayback,
              forceKSPlayerSurface,
              snapshot.sessionID == playbackPresentationID,
              store.playbackPresentationID == playbackPresentationID,
              store.playbackURL == url else { return }
        if snapshot.duration.isFinite, snapshot.duration > 1 {
            if abs(durationSeconds - snapshot.duration) > 0.05 { durationSeconds = snapshot.duration }
            hasRecoveredSeekableMetadata = true
        }
        if snapshot.elapsed.isFinite, snapshot.elapsed >= 0, !isSeekingInPlayer, !isScrubbingTimeline {
            currentSeconds = snapshot.duration > 1 ? min(snapshot.elapsed, snapshot.duration) : snapshot.elapsed
        }
        if snapshot.elapsed > 0.01 {
            markStableFirstFrameReady(engine: "Playback", reason: "authoritative player clock")
        }
    }

    private func runtimeSeconds(for item: MediaItem) -> Double {
        // Preserve the last confirmed duration from resume history when a direct file has
        // not published duration yet. This is exact for the previously played source and
        // is replaced immediately when PlaybackKit reports the active file duration.
        if let saved = PlaybackResumeCacheManager.shared.resumeEntry(for: item), saved.duration > 1 {
            return saved.duration
        }
        return 0
    }

    private func startRuntimeMetadataLookupIfNeeded(force: Bool = false, delayNanoseconds: UInt64 = 0) {
        guard !isLivePlayback else { return }
        guard force || resolvedDurationSeconds <= 1 else { return }
        runtimeLookupTask?.cancel()
        runtimeLookupTask = Task { @MainActor in
            if delayNanoseconds > 0 {
                try? await Task.sleep(nanoseconds: delayNanoseconds)
                guard !Task.isCancelled,
                      isFirstFrameReady,
                      store.playbackPresentationID == playbackPresentationID,
                      store.playbackURL == url else { return }
            }
            let tmdbSeconds = await fetchRuntimeSecondsFromTMDB()
            let resolved: Double?
            let resolvedLabel: String
            if let tmdbSeconds {
                resolved = tmdbSeconds
                resolvedLabel = "TMDB runtime"
            } else {
                resolved = await fetchRuntimeSecondsFromOMDB()
                resolvedLabel = "OMDb runtime"
            }
            guard !Task.isCancelled,
                  store.playbackPresentationID == playbackPresentationID,
                  store.playbackURL == url else { return }
            if let seconds = resolved, seconds.isFinite, seconds > 1 {
                metadataRuntimeSeconds = seconds
                metadataRuntimeLabel = resolvedLabel
            }
            runtimeLookupTask = nil
        }
    }

    private func fetchRuntimeSecondsFromTMDB() async -> Double? {
        let key = vodTMDBApiKey.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !key.isEmpty else { return nil }

        struct MovieDetail: Decodable { let runtime: Int? }
        struct TVDetail: Decodable { let episode_run_time: [Int]? }
        struct EpisodeDetail: Decodable { let runtime: Int? }
        struct FindResponse: Decodable {
            struct FoundItem: Decodable { let id: Int? }
            let movie_results: [FoundItem]?
            let tv_results: [FoundItem]?
        }
        struct SearchResponse: Decodable {
            struct FoundItem: Decodable { let id: Int? }
            let results: [FoundItem]
        }

        func fetch<T: Decodable>(_ type: T.Type, from url: URL) async -> T? {
            do {
                var request = URLRequest(url: url, timeoutInterval: 8)
                request.setValue("application/json", forHTTPHeaderField: "Accept")
                request.setValue("DebridChannels-tvOS/525 RuntimeMetadata", forHTTPHeaderField: "User-Agent")
                let (data, response) = try await URLSession.shared.data(for: request)
                if let http = response as? HTTPURLResponse, !(200...299).contains(http.statusCode) { return nil }
                return try JSONDecoder().decode(T.self, from: data)
            } catch {
                return nil
            }
        }

        let metadataItem = overlayItem
        let series = metadataItem.seasonNumber != nil || metadataItem.episodeNumber != nil || {
            let lower = metadataItem.type.lowercased()
            return lower.contains("series") || lower.contains("show") || lower == "tv" || lower.contains("episode")
        }()

        var tmdbID = metadataItem.tmdbId?.trimmingCharacters(in: .whitespacesAndNewlines)
        let parts = metadataItem.id.split(separator: ":").map(String.init)
        if tmdbID?.isEmpty != false, parts.count >= 3, parts[0].lowercased() == "tmdb" {
            tmdbID = parts[2]
        }

        let imdbID: String? = {
            if let explicit = metadataItem.imdbId?.trimmingCharacters(in: .whitespacesAndNewlines), explicit.lowercased().hasPrefix("tt") { return explicit }
            if metadataItem.id.lowercased().hasPrefix("tt") { return String(metadataItem.id.split(separator: ":").first ?? Substring(metadataItem.id)) }
            if let match = metadataItem.id.range(of: #"tt\d{6,}"#, options: .regularExpression) { return String(metadataItem.id[match]) }
            return nil
        }()

        if tmdbID?.isEmpty != false, let imdbID,
           let encoded = imdbID.addingPercentEncoding(withAllowedCharacters: .urlPathAllowed),
           let findURL = URL(string: "https://api.themoviedb.org/3/find/\(encoded)?api_key=\(key)&external_source=imdb_id"),
           let found = await fetch(FindResponse.self, from: findURL) {
            tmdbID = series
                ? found.tv_results?.compactMap(\.id).first.map(String.init)
                : found.movie_results?.compactMap(\.id).first.map(String.init)
        }

        if tmdbID?.isEmpty != false {
            let query = metadataItem.title.trimmingCharacters(in: .whitespacesAndNewlines)
            if query.count >= 2,
               let encoded = query.addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed) {
                let yearDigits = metadataItem.year.filter(\.isNumber)
                let endpoint = series ? "tv" : "movie"
                let yearName = series ? "first_air_date_year" : "year"
                let yearQuery = yearDigits.isEmpty ? "" : "&\(yearName)=\(yearDigits)"
                if let searchURL = URL(string: "https://api.themoviedb.org/3/search/\(endpoint)?api_key=\(key)&query=\(encoded)&include_adult=false&language=en-US\(yearQuery)"),
                   let found = await fetch(SearchResponse.self, from: searchURL) {
                    tmdbID = found.results.compactMap(\.id).first.map(String.init)
                }
            }
        }

        guard let tmdbID, !tmdbID.isEmpty else { return nil }
        if !series,
           let detailURL = URL(string: "https://api.themoviedb.org/3/movie/\(tmdbID)?api_key=\(key)&language=en-US"),
           let detail = await fetch(MovieDetail.self, from: detailURL),
           let minutes = detail.runtime, minutes > 0 {
            return Double(minutes) * 60
        }

        if series,
           let season = metadataItem.seasonNumber,
           let episode = metadataItem.episodeNumber,
           let episodeURL = URL(string: "https://api.themoviedb.org/3/tv/\(tmdbID)/season/\(season)/episode/\(episode)?api_key=\(key)&language=en-US"),
           let detail = await fetch(EpisodeDetail.self, from: episodeURL),
           let minutes = detail.runtime, minutes > 0 {
            return Double(minutes) * 60
        }

        if series,
           let detailURL = URL(string: "https://api.themoviedb.org/3/tv/\(tmdbID)?api_key=\(key)&language=en-US"),
           let detail = await fetch(TVDetail.self, from: detailURL),
           let minutes = detail.episode_run_time?.first(where: { $0 > 0 }) {
            return Double(minutes) * 60
        }
        return nil
    }

    private func fetchRuntimeSecondsFromOMDB() async -> Double? {
        let key = vodOMDBApiKey.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !key.isEmpty else { return nil }

        struct OMDbDetail: Decodable {
            let runtime: String?
            enum CodingKeys: String, CodingKey { case runtime = "Runtime" }
        }

        let metadataItem = overlayItem
        var components = URLComponents(string: "https://www.omdbapi.com/")
        var queryItems = [URLQueryItem(name: "apikey", value: key)]
        let imdbID: String? = {
            if let explicit = metadataItem.imdbId?.trimmingCharacters(in: .whitespacesAndNewlines), explicit.lowercased().hasPrefix("tt") { return explicit }
            if let match = metadataItem.id.range(of: #"tt\d{6,}"#, options: .regularExpression) { return String(metadataItem.id[match]) }
            return nil
        }()
        if let imdbID {
            queryItems.append(URLQueryItem(name: "i", value: imdbID))
        } else {
            queryItems.append(URLQueryItem(name: "t", value: metadataItem.title))
            let year = metadataItem.year.filter(\.isNumber)
            if !year.isEmpty { queryItems.append(URLQueryItem(name: "y", value: year)) }
        }
        if let season = metadataItem.seasonNumber, let episode = metadataItem.episodeNumber {
            queryItems.append(URLQueryItem(name: "Season", value: String(season)))
            queryItems.append(URLQueryItem(name: "Episode", value: String(episode)))
        }
        components?.queryItems = queryItems
        guard let requestURL = components?.url else { return nil }

        do {
            var request = URLRequest(url: requestURL, timeoutInterval: 8)
            request.setValue("application/json", forHTTPHeaderField: "Accept")
            request.setValue("DebridChannels-tvOS/525 RuntimeMetadata", forHTTPHeaderField: "User-Agent")
            let (data, response) = try await URLSession.shared.data(for: request)
            if let http = response as? HTTPURLResponse, !(200...299).contains(http.statusCode) { return nil }
            let runtime = try JSONDecoder().decode(OMDbDetail.self, from: data).runtime ?? ""
            return parseRuntimeSeconds(runtime)
        } catch {
            return nil
        }
    }

    private func parseRuntimeSeconds(_ value: String) -> Double? {
        let lower = value.lowercased()
        var minutes = 0
        if let hourRange = lower.range(of: #"\d+\s*h"#, options: .regularExpression) {
            minutes += (Int(lower[hourRange].filter(\.isNumber)) ?? 0) * 60
        }
        if let minuteRange = lower.range(of: #"\d+\s*min"#, options: .regularExpression) {
            minutes += Int(lower[minuteRange].filter(\.isNumber)) ?? 0
        } else if minutes == 0, let first = lower.split(whereSeparator: { !$0.isNumber }).first, let rawMinutes = Int(first) {
            minutes = rawMinutes
        }
        return minutes > 0 ? Double(minutes) * 60 : nil
    }

    private func armStartupLoadingGate(engine _: String) {
        startupLoadingTask?.cancel()
        startupLoadingTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: 300_000_000)
            guard !Task.isCancelled,
                  errorText == nil,
                  !isFirstFrameReady else { return }
            // v1085: one state publication is enough. The former 300 ms loop kept
            // invalidating startup chrome throughout decoder initialization.
            let message = isLivePlayback ? "Loading stream…" : "Preparing video…"
            if retryText != message { retryText = message }
        }
    }

    private func startPlayerClock() {
        playbackClockTask?.cancel()
        playbackClockTask = Task { @MainActor in
            while !Task.isCancelled {
                // v833: keep the v831 KSPlayer buffering/cache-ahead profile, but stop
                // driving visible SwiftUI playback chrome once per second while controls are
                // hidden. The player renders smoothly on its own; the app only needs periodic
                // bookkeeping for resume/progress until the overlay is shown again.
                let hiddenSteadyPlayback = !controlsVisible && activePanel == nil && isFirstFrameReady && errorText == nil && !isSeekingInPlayer && !isScrubbingTimeline
                let tickSeconds: Double = hiddenSteadyPlayback ? 5.0 : 1.0
                try? await Task.sleep(nanoseconds: UInt64(tickSeconds * 1_000_000_000))
                guard store.playbackPresentationID == playbackPresentationID,
                      store.playbackURL == url else { return }
                guard isPlaying, errorText == nil else { continue }
                guard forceAetherSurface || forceKSPlayerSurface || forceVLCSurface else { continue }

                // v996: never manufacture a visible KSPlayer timestamp. The authoritative
                // clock arrives from PlaybackKit. A bounded first-frame safety deadline can
                // release the loading cover, but it does not advance current time.
                if forceAetherSurface || forceKSPlayerSurface {
                    if !isFirstFrameReady,
                       let deadline = vodBootstrapDeadline,
                       Date() >= deadline {
                        markFirstFrameReady(engine: "Playback", reason: "startup safety deadline")
                    }
                    // KSPlayer owns the real timeline through PlaybackKit callbacks. Once
                    // startup is resolved this helper has no bookkeeping role, so stop its
                    // periodic MainActor wakeups for the rest of the movie/episode.
                    if isFirstFrameReady || errorText != nil { return }
                    continue
                }

                let total = resolvedDurationSeconds
                if total > 0 { currentSeconds = min(total, currentSeconds + tickSeconds) } else { currentSeconds += tickSeconds }
                if !isFirstFrameReady, currentSeconds > 0.25 {
                    markFirstFrameReady(engine: "Playback", reason: "playback clock advanced")
                }
                saveResumePositionIfNeeded()
                // vBRDC209: periodic clock bookkeeping never owns completion. True EOF
                // callbacks/fallbacks are the only place that may stop-scrobble or clear
                // Resume, preventing repeated final-minutes completion work on any engine.
            }
        }
    }

    private func formatTime(_ seconds: Double) -> String {
        guard seconds.isFinite, seconds > 0 else { return "0:00" }
        let total = Int(seconds)
        let h = total / 3600
        let m = (total % 3600) / 60
        let s = total % 60
        return h > 0 ? String(format: "%d:%02d:%02d", h, m, s) : String(format: "%d:%02d", m, s)
    }
}


struct PlaybackHealthSnapshot: Equatable {
    var sessionUUID: String
    var presentationGeneration: String
    var sourceProviderAndFilename: String
    var videoCodec: String
    var audioCodec: String
    var resolution: String
    var hdrState: String
    var frameRate: String
    var hardwareDecoder: String
    var bufferDuration: String
    var droppedAndDelayedFrames: String
    var audioVideoClockDifference: String
    var currentAudioTrack: String
    var currentSubtitleTrack: String
    var firstFrameStatus: String
    var sourceHandoffStatus: String
    var alternateAudioStatus: String
    var trailerResolverStatus: String
    var capturedAt: String

    static let empty = PlaybackHealthSnapshot(
        sessionUUID: "Not captured", presentationGeneration: "Not captured", sourceProviderAndFilename: "Not captured",
        videoCodec: "Not captured", audioCodec: "Not captured", resolution: "Not captured", hdrState: "Not captured",
        frameRate: "Not captured", hardwareDecoder: "Not captured", bufferDuration: "Not captured",
        droppedAndDelayedFrames: "Not captured", audioVideoClockDifference: "Not captured",
        currentAudioTrack: "Not captured", currentSubtitleTrack: "Not captured", firstFrameStatus: "Not captured",
        sourceHandoffStatus: "Not captured", alternateAudioStatus: "Not captured", trailerResolverStatus: "Not captured",
        capturedAt: "Not captured"
    )
}

struct PlaybackHealthSnapshotPanel: View {
