    var body: some View {
        VStack(alignment: .leading, spacing: 6) {
            healthRow("Session UUID", snapshot.sessionUUID)
            healthRow("Presentation", snapshot.presentationGeneration)
            healthRow("Source", snapshot.sourceProviderAndFilename)
            healthRow("Video", snapshot.videoCodec)
            healthRow("Audio", snapshot.audioCodec)
            healthRow("Resolution", snapshot.resolution)
            healthRow("HDR / Dolby Vision", snapshot.hdrState)
            healthRow("Frame Rate", snapshot.frameRate)
            healthRow("Hardware Decoder", snapshot.hardwareDecoder)
            healthRow("Buffer", snapshot.bufferDuration)
            healthRow("Dropped / Delayed", snapshot.droppedAndDelayedFrames)
            healthRow("A/V Clock", snapshot.audioVideoClockDifference)
            healthRow("Audio Track", snapshot.currentAudioTrack)
            healthRow("Subtitle Track", snapshot.currentSubtitleTrack)
            healthRow("First Frame", snapshot.firstFrameStatus)
            healthRow("Source Handoff", snapshot.sourceHandoffStatus)
            healthRow("Alternate Audio", snapshot.alternateAudioStatus)
            healthRow("Bridge Stage", "\(bridge.preparationStage) • \(bridge.preparationPercentage)%")
            healthRow("Original Video", bridge.originalVideoSource)
            healthRow("Alternate Source", bridge.alternateAudioSource)
            healthRow("Audio Stream", bridge.selectedStreamIndex)
            healthRow("Match", bridge.matchClassification)
            healthRow("Offset", bridge.offset)
            healthRow("Drift", bridge.driftCorrection)
            healthRow("Stream Modes", bridge.streamModes)
            healthRow("Rejected Because", bridge.candidateRejectionReason)
            healthRow("Trailer Resolver", snapshot.trailerResolverStatus)
            if !failureHistory.isEmpty {
                Text("RECENT FAILED HANDOFFS")
                    .font(.system(size: 11, weight: .black, design: .rounded))
                    .foregroundStyle(.white.opacity(0.44))
                    .padding(.top, 4)
                ForEach(Array(failureHistory.prefix(3).enumerated()), id: \.offset) { _, row in
                    Text(row)
                        .font(.system(size: 11, weight: .semibold, design: .rounded))
                        .foregroundStyle(.white.opacity(0.62))
                        .lineLimit(1)
                }
            }
            Text("Privacy-safe report • source credentials and signed URLs are never shown")
                .font(.system(size: 10, weight: .bold, design: .rounded))
                .foregroundStyle(.white.opacity(0.40))
            Text("Captured \(snapshot.capturedAt) • snapshot only")
