        .overlay(RoundedRectangle(cornerRadius: 18, style: .continuous).stroke(Color.white.opacity(0.10), lineWidth: 1))
    }

    private func healthRow(_ title: String, _ value: String) -> some View {
        HStack(alignment: .firstTextBaseline, spacing: 10) {
            Text(title.uppercased())
                .font(.system(size: 11, weight: .black, design: .rounded))
                .foregroundStyle(.white.opacity(0.44))
                .frame(width: 132, alignment: .leading)
            Text(value)
                .font(.system(size: 13, weight: .bold, design: .rounded))
                .foregroundStyle(.white.opacity(0.88))
                .lineLimit(1)
                .minimumScaleFactor(0.72)
        }
    }
}

struct LiveTVOverlayControlChip: View {
    let title: String
    let icon: String
    let focus: VODPlayerScreen.PlayerControl
    var focused: FocusState<VODPlayerScreen.PlayerControl?>.Binding
    let action: () -> Void

    private var selected: Bool { focused.wrappedValue == focus }

    var body: some View {
        controlButton
    }

    private var controlButton: some View {
        Button(action: activate) { controlLabel }
            .buttonStyle(.plain)
            .foregroundStyle(controlForeground)
            .padding(.horizontal, 15)
            .frame(height: 38)
            .background(controlBackground)
            .overlay(controlBorder)
            .scaleEffect(selected ? 1.04 : 1.0)
            .contentShape(Capsule())
            .focusable(true)
            .focused(focused, equals: focus)
            .onHover(perform: handleHover)
            .hoverEffect(.highlight)
            .accessibilityAddTraits(.isButton)
            .accessibilityLabel(title)
    }

    private var controlLabel: some View {
        HStack(spacing: 8) {
            Image(systemName: icon)
                .font(.system(size: 14, weight: .bold))
            Text(title)
                .font(.system(size: 14, weight: .bold, design: .rounded))
        }
    }

    private var controlForeground: Color {
        .white.opacity(selected ? 1.0 : 0.76)
    }

    private var controlBackground: some View {
        Capsule().fill(selected ? Color.white.opacity(0.16) : Color.white.opacity(0.055))
    }

    private var controlBorder: some View {
        Capsule().stroke(
            selected ? Color.white.opacity(0.72) : Color.white.opacity(0.10),
            lineWidth: selected ? 1.4 : 1
        )
    }

    private func activate() {
        focused.wrappedValue = focus
        action()
    }

    private func handleHover(_ hovering: Bool) {
        if hovering { focused.wrappedValue = focus }
    }
}

