// v1041: the production VOD information stage used by VODPlayerScreen.
// This is deliberately named and wired at the active call site so the physical
// Apple TV cannot silently fall back to one of the earlier experimental stages.
// Display-only: playback engines, seeking, clocks, trailers and source selection
// remain untouched.
struct V1041AppleTVMediaInformationStage: View {
    let item: MediaItem
    let descriptionText: String
    let overlayTheme: VODOverlayThemePreset
    let castWallAwake: Bool
    let episodeDateVerified: Bool
    @Binding var castSpotlightIndex: Int
    @Binding var castInitialHoldClaimed: Bool
    let castFocusRequestToken: UInt64
    let castManualNavigationToken: UInt64
    let castFocusActive: Bool
    let onCastFocusChanged: (Bool) -> Void
    @Binding var productionArtworkIndex: Int
    let rottenTomatoesScore: String?
    let communityScore: String?
    let featuredCastPresentationMode: VODFeaturedCastPresentationMode
    let portraitPosterThemedLogoEnabled: Bool
    let productionRatingsPanelEnabled: Bool
    let spotlightHubPanelEnabled: Bool
    let productionRatingsThemedLogoEnabled: Bool
    let playbackReady: Bool
    let productionMetadata: VODProductionMetadataSnapshot
    let playbackRuntimeMinutes: Int?
    let onCastSelected: (CastMember) -> Void

    private var cast: [CastMember] {
        let rich = item.castMembers.filter { !$0.name.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
        if !rich.isEmpty { return rich }
        return item.cast
            .filter { !$0.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
            .map { CastMember(name: $0, role: nil, imageURL: nil) }
    }

    private var isSeries: Bool {
        let type = item.type.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        return item.seasonNumber != nil || item.episodeNumber != nil || type.contains("episode") || type.contains("series") || type.contains("show") || type == "tv"
    }

    private var mediaTypeLabel: String { isSeries ? "SERIES" : "MOVIE" }
    private var mediaTypeIcon: String { isSeries ? "rectangle.stack.fill" : "film.fill" }

    private var episodeLabel: String? {
        guard let season = item.seasonNumber else { return nil }
        if let episode = item.episodeNumber { return "S\(season) E\(episode)" }
        return "SEASON \(season)"
    }

    private var episodeDate: DCEpisodeDatePresentation? {
        guard episodeDateVerified, isSeries, item.seasonNumber != nil || item.episodeNumber != nil else { return nil }
        return dcEpisodeDatePresentation(item)
    }

    private var cleanYear: String? {
        let value = item.year.trimmingCharacters(in: .whitespacesAndNewlines)
        guard value.range(of: #"^(19|20)\d{2}$"#, options: .regularExpression) != nil else { return nil }
        return value
    }

    private var cleanRating: String? {
        let value = item.rating
            .replacingOccurrences(of: "★", with: "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        guard !value.isEmpty, value.lowercased() != "n/a", value != "0", value != "0.0" else { return nil }
        return value
    }

    private var genreLine: String {
        item.genres
            .prefix(4)
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
            .uniquedPreservingOrder()
            .joined(separator: "  •  ")
    }

    private var directorLine: String? {
        let names = item.directors
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
            .prefix(2)
        guard !names.isEmpty else { return nil }
        return names.joined(separator: "  •  ")
    }

    private var accent: Color {
        if overlayTheme != .original { return overlayTheme.accent }
        let haystack = ([item.title, item.type] + item.genres).joined(separator: " ").lowercased()
        if haystack.contains("horror") || haystack.contains("thriller") { return .red }
        if haystack.contains("animation") || haystack.contains("family") { return .purple }
        if haystack.contains("science fiction") || haystack.contains("sci-fi") { return .cyan }
        if haystack.contains("action") || haystack.contains("adventure") { return .blue }
        if haystack.contains("romance") { return .pink }
        if haystack.contains("comedy") { return .yellow }
        if haystack.contains("documentary") { return .mint }
        return .orange
    }

    var body: some View {
        ZStack(alignment: .bottomTrailing) {
            HStack(alignment: .bottom, spacing: 28) {
                V1111FeaturedCastPosterCard(
                    item: item,
                    members: cast,
                    awake: castWallAwake,
                    mode: featuredCastPresentationMode,
                    playbackReady: playbackReady,
                    themedLogoEnabled: portraitPosterThemedLogoEnabled,
                    spotlightIndex: $castSpotlightIndex,
                    initialHoldClaimed: $castInitialHoldClaimed,
                    focusRequestToken: castFocusRequestToken,
                    manualNavigationToken: castManualNavigationToken,
                    focusActive: castFocusActive,
                    onFocusChanged: onCastFocusChanged,
                    onCastSelected: onCastSelected
                )
                .frame(
                    width: 138,
                    height: featuredCastPresentationMode == .compactOverlay ? 271 : 207,
                    alignment: .bottom
                )
                .padding(.bottom, 1)

                VStack(alignment: .leading, spacing: 8) {
                    V1041NowPlayingHeader(icon: mediaTypeIcon, text: mediaTypeLabel, accent: accent, theme: overlayTheme)

                    HeroLogoText(item: item)
                        .frame(width: 620, height: 60, alignment: .leading)
                        .fixedSize(horizontal: false, vertical: true)

                    HStack(alignment: .center, spacing: 12) {
                        if let episodeDate {
                            V1041BorderlessMediaFact(
                                icon: "calendar.badge.clock",
                                value: episodeDate.combinedText,
                                tint: episodeDate.isUpcoming ? .orange : .white,
                                theme: overlayTheme
                            )
                        } else if let cleanYear {
                            V1041BorderlessMediaFact(icon: "calendar", value: cleanYear, tint: .white, theme: overlayTheme)
                        }
                        if let cleanRating {
                            V1041BorderlessMediaFact(icon: "star.fill", value: cleanRating, tint: .yellow, theme: overlayTheme)
                        }
                        V1104ReviewScoresCluster(
                            rottenTomatoesScore: rottenTomatoesScore,
                            communityScore: communityScore
                        )
                        if let episodeLabel {
                            V1041BorderlessMediaFact(icon: "rectangle.stack.fill", value: episodeLabel, tint: accent, theme: overlayTheme)
                        }
                        if !genreLine.isEmpty {
                            V1041BorderlessMediaFact(icon: "tag.fill", value: genreLine, tint: accent, maximumWidth: 310, theme: overlayTheme)
                        }
                    }
                    .frame(maxWidth: 1000, alignment: .leading)

                    V1041AppleTVSynopsis(text: descriptionText, accent: accent, theme: overlayTheme)
                        .frame(maxWidth: 850, alignment: .leading)

                    if let directorLine {
                        HStack(spacing: 8) {
                            Image(systemName: "megaphone.fill")
                                .font(.system(size: 11, weight: .semibold))
                                .foregroundStyle(accent.opacity(0.90))
                            Text("DIRECTED BY")
                                .font(.system(size: 10, weight: .semibold, design: .default))
                                .tracking(1.7)
                                .foregroundStyle(.white.opacity(0.46))
                            Text(directorLine)
                                .font(.system(size: 13, weight: .semibold, design: .default))
                                .foregroundStyle(.white.opacity(0.78))
                                .lineLimit(1)
                        }
                    }
                }
                .frame(maxWidth: .infinity, alignment: .leading)

                Spacer(minLength: (productionRatingsPanelEnabled || spotlightHubPanelEnabled) && playbackReady ? 492 : 20)
            }
            .frame(maxWidth: .infinity, alignment: .bottomLeading)
            .padding(.leading, 104)
            .padding(.trailing, 100)

            if productionRatingsPanelEnabled && playbackReady {
                V1108ProductionRatingsPanel(
                    item: item,
                    metadata: productionMetadata,
                    rottenTomatoesScore: rottenTomatoesScore,
                    communityScore: communityScore,
                    playbackRuntimeMinutes: playbackRuntimeMinutes,
                    awake: castWallAwake,
                    themedLogoEnabled: productionRatingsThemedLogoEnabled,
                    artworkIndex: $productionArtworkIndex
                )
                .frame(width: 390, alignment: .bottomTrailing)
                .padding(.trailing, 96)
                .padding(.bottom, -8)
                .transition(.opacity)
                .accessibilityIdentifier("V1108ProductionRatingsPanel")
            } else if spotlightHubPanelEnabled && playbackReady {
                VBRDC193SpotlightHubPanel(
                    item: item,
                    metadata: productionMetadata
                )
                .frame(width: 480, alignment: .bottomTrailing)
                .padding(.trailing, 96)
                .padding(.bottom, -8)
                .transition(.opacity)
                .accessibilityIdentifier("VBRDC193SpotlightHubPanel")
            }
        }
        .frame(
            maxWidth: .infinity,
            minHeight: featuredCastPresentationMode == .compactOverlay ? 272 : 204,
            alignment: .bottomLeading
        )
        .padding(.top, 6)
        .padding(.bottom, 0)
        .accessibilityIdentifier("V1041AppleTVMediaInformationStage")
    }
}

