struct V1134CastExplorerOverlay: View {
    let member: CastMember
    let snapshot: CastExplorerSnapshot?
    let isLoading: Bool
    let errorMessage: String?
    let onCreditSelected: (CastExplorerCredit) -> Void
    let onClose: () -> Void

    @State private var profileScrollRequest: UInt64 = 0

    var body: some View {
        ZStack {
            Color.black.opacity(0.86).ignoresSafeArea()

            LinearGradient(
                colors: [Color.black.opacity(0.28), Color.orange.opacity(0.055), Color.black.opacity(0.44)],
                startPoint: .topLeading,
                endPoint: .bottomTrailing
            )
            .ignoresSafeArea()

            VStack(spacing: 18) {
                VStack(alignment: .leading, spacing: 4) {
                    Text("CAST EXPLORER")
                        .font(.system(size: 13, weight: .black, design: .rounded))
                        .tracking(2.0)
                        .foregroundStyle(Color.orange.opacity(0.96))
                    Text(snapshot?.name ?? member.name)
                        .font(.system(size: 38, weight: .black, design: .rounded))
                        .foregroundStyle(.white)
                        .lineLimit(1)
                    Text("Person details load only when you open this screen. Press Back to return to playback.")
                        .font(.system(size: 14, weight: .semibold, design: .rounded))
                        .foregroundStyle(.white.opacity(0.50))
                }
                .frame(maxWidth: .infinity, alignment: .leading)

                ScrollViewReader { profileProxy in
                    ScrollView(.vertical, showsIndicators: false) {
                        VStack(alignment: .leading, spacing: 24) {
                        if isLoading {
                            HStack(spacing: 14) {
                                ProgressView()
                                VStack(alignment: .leading, spacing: 4) {
                                    Text("Loading verified cast information…")
                                        .font(.system(size: 22, weight: .black, design: .rounded))
                                    Text("Film/TV credits use your TMDB key; open structured facts use Wikidata when an exact match is verified.")
                                        .font(.system(size: 15, weight: .semibold, design: .rounded))
                                        .foregroundStyle(.white.opacity(0.56))
                                }
                            }
                            .padding(26)
                            .frame(maxWidth: .infinity, alignment: .leading)
                            .background(RoundedRectangle(cornerRadius: 24, style: .continuous).fill(Color.white.opacity(0.055)))
                        } else if let snapshot {
                            personHeader(snapshot)
                                .id("V1134CastExplorerProfile")

                            if !snapshot.knownFor.isEmpty {
                                creditSection(title: "KNOWN FOR", credits: snapshot.knownFor)
                            }
                            if !snapshot.movies.isEmpty {
                                creditSection(title: "MOVIES", credits: snapshot.movies)
                            }
                            if !snapshot.shows.isEmpty {
                                creditSection(title: "TV SHOWS", credits: snapshot.shows)
                            }
                            if !snapshot.upcoming.isEmpty {
                                creditSection(title: "UPCOMING", credits: snapshot.upcoming)
                            }
                        } else {
                            VStack(alignment: .leading, spacing: 10) {
                                Image(systemName: "person.crop.circle.badge.questionmark")
                                    .font(.system(size: 40, weight: .semibold))
                                    .foregroundStyle(.orange.opacity(0.86))
                                Text("Cast information unavailable")
                                    .font(.system(size: 25, weight: .black, design: .rounded))
                                Text(errorMessage ?? "No verified person data was returned.")
                                    .font(.system(size: 16, weight: .semibold, design: .rounded))
                                    .foregroundStyle(.white.opacity(0.58))
                                    .lineSpacing(3)
                            }
                            .padding(28)
                            .frame(maxWidth: .infinity, alignment: .leading)
                            .background(RoundedRectangle(cornerRadius: 24, style: .continuous).fill(Color.white.opacity(0.055)))
                        }
                        }
                        .padding(.bottom, 42)
                    }
                    .onChange(of: profileScrollRequest) { _, _ in
                        withAnimation(.easeOut(duration: 0.18)) {
                            profileProxy.scrollTo("V1134CastExplorerProfile", anchor: .top)
                        }
                    }
                }
            }
            .padding(.horizontal, 74)
            .padding(.top, 54)
            .padding(.bottom, 30)
        }
        .foregroundStyle(.white)
        .signalVisionExitCommand( onClose)
        .accessibilityElement(children: .contain)
        .accessibilityIdentifier("V1134CastExplorerOverlay")
    }

    @ViewBuilder
    private func personHeader(_ snapshot: CastExplorerSnapshot) -> some View {
        HStack(alignment: .top, spacing: 26) {
            ZStack {
                RoundedRectangle(cornerRadius: 26, style: .continuous)
                    .fill(Color.white.opacity(0.055))
                if let profile = snapshot.profileURL, !profile.isEmpty {
                    RemoteImageFit(url: profile, mode: .fill, showPlaceholder: false, maxPixelSize: 768, publishDuringPlayback: true, forceVisiblePlaybackPublication: true)
                } else if let fallback = member.imageURL, !fallback.isEmpty {
                    RemoteImageFit(url: fallback, mode: .fill, showPlaceholder: false, maxPixelSize: 768, publishDuringPlayback: true, forceVisiblePlaybackPublication: true)
                } else {
                    Image(systemName: "person.crop.rectangle")
                        .font(.system(size: 62, weight: .medium))
                        .foregroundStyle(.white.opacity(0.35))
                }
            }
            .frame(width: 214, height: 286)
            .clipShape(RoundedRectangle(cornerRadius: 26, style: .continuous))
            .overlay(RoundedRectangle(cornerRadius: 26, style: .continuous).stroke(Color.white.opacity(0.16), lineWidth: 1))

            VStack(alignment: .leading, spacing: 15) {
                HStack(spacing: 10) {
                    if let department = clean(snapshot.knownForDepartment) {
                        V1134CastFactChip(icon: "person.text.rectangle", title: "KNOWN FOR", value: department)
                    }
                    if let popularity = snapshot.tmdbPopularity {
                        V1134CastFactChip(icon: "chart.line.uptrend.xyaxis", title: "TMDB POPULARITY", value: String(format: "%.1f", popularity))
                    }
                    if let netWorth = snapshot.reportedNetWorthUSD {
                        V1134CastFactChip(
                            icon: "dollarsign.circle.fill",
                            title: "REPORTED NET WORTH",
                            value: formatUSD(netWorth) + (snapshot.netWorthAsOf.map { " • \($0)" } ?? "")
                        )
                    }
                }

                HStack(spacing: 10) {
                    if let birthday = clean(snapshot.birthday) {
                        V1134CastFactChip(icon: "birthday.cake.fill", title: "BORN", value: birthday + ageSuffix(birthday))
                    }
                    if let place = clean(snapshot.placeOfBirth) {
                        V1134CastFactChip(icon: "mappin.and.ellipse", title: "BIRTHPLACE", value: place)
                    }
                }

                if let biography = clean(snapshot.biography) {
                    Text(biography)
                        .font(.system(size: 17, weight: .semibold, design: .rounded))
                        .foregroundStyle(.white.opacity(0.72))
                        .lineLimit(8)
                        .lineSpacing(4)
                        .frame(maxWidth: 1020, alignment: .leading)
                }

                if !snapshot.occupations.isEmpty {
                    detailLine(icon: "briefcase.fill", label: "Occupation", values: snapshot.occupations)
                }
                if !snapshot.citizenships.isEmpty {
                    detailLine(icon: "globe.americas.fill", label: "Citizenship", values: snapshot.citizenships)
                }
                if !snapshot.education.isEmpty {
                    detailLine(icon: "graduationcap.fill", label: "Education", values: snapshot.education)
                }
                if !snapshot.awards.isEmpty {
                    detailLine(icon: "trophy.fill", label: "Awards", values: snapshot.awards)
                }
                if !snapshot.spouses.isEmpty {
                    detailLine(icon: "heart.fill", label: "Spouse", values: snapshot.spouses)
                } else if !snapshot.partners.isEmpty {
                    detailLine(icon: "heart.circle.fill", label: "Publicly documented partner", values: snapshot.partners)
                }
                if !snapshot.children.isEmpty {
                    detailLine(icon: "figure.2.and.child.holdinghands", label: "Children", values: snapshot.children)
                }
                if !snapshot.parents.isEmpty {
                    detailLine(icon: "person.2.fill", label: "Parents", values: snapshot.parents)
                }
                if !snapshot.siblings.isEmpty {
                    detailLine(icon: "person.3.fill", label: "Siblings", values: snapshot.siblings)
                }

                HStack(spacing: 8) {
                    if snapshot.wikidataID != nil {
                        Label("Open facts: Wikidata", systemImage: "checkmark.seal.fill")
                    }
                    if snapshot.personID != nil {
                        Label("Credits: TMDB", systemImage: "film.stack.fill")
                    }
                    if snapshot.reportedNetWorthUSD != nil {
                        Text("Net worth is shown only when Wikidata reports a USD value; Debrid Channels does not estimate it.")
                    }
                }
                .font(.system(size: 11, weight: .bold, design: .rounded))
                .foregroundStyle(.white.opacity(0.42))
            }
            Spacer(minLength: 0)
        }
        .padding(22)
        .background(RoundedRectangle(cornerRadius: 28, style: .continuous).fill(Color.black.opacity(0.32)))
        .overlay(RoundedRectangle(cornerRadius: 28, style: .continuous).stroke(Color.white.opacity(0.10), lineWidth: 1))
    }

    private func detailLine(icon: String, label: String, values: [String]) -> some View {
        HStack(alignment: .top, spacing: 8) {
            Image(systemName: icon)
                .font(.system(size: 12, weight: .bold))
                .foregroundStyle(.orange.opacity(0.90))
                .frame(width: 18)
            Text(label.uppercased())
                .font(.system(size: 10, weight: .black, design: .rounded))
                .tracking(1.0)
                .foregroundStyle(.white.opacity(0.42))
            Text(values.prefix(12).joined(separator: " • "))
                .font(.system(size: 13, weight: .semibold, design: .rounded))
                .foregroundStyle(.white.opacity(0.72))
                .lineLimit(2)
        }
    }

    @ViewBuilder
    private func creditSection(title: String, credits: [CastExplorerCredit]) -> some View {
        VStack(alignment: .leading, spacing: 12) {
            Text(title)
                .font(.system(size: 13, weight: .black, design: .rounded))
                .tracking(1.8)
                .foregroundStyle(.white.opacity(0.82))
            ScrollView(.horizontal, showsIndicators: false) {
                LazyHStack(spacing: 16) {
                    ForEach(credits) { credit in
                        V1134CastCreditCard(credit: credit) {
                            onCreditSelected(credit)
                        }
                    }
                }
                .padding(.vertical, 10)
            }
            .scrollClipDisabled(true)
            .signalVisionFocusSection()
            .signalMoveCommand { direction in
                guard direction == .up else { return }
                // Keep the person profile reachable without adding a redundant Search or
                // Close control. Back/Menu remains the single exit action for this overlay.
                profileScrollRequest &+= 1
            }
        }
    }

    private func clean(_ value: String?) -> String? {
        guard let value else { return nil }
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? nil : trimmed
    }

    private func formatUSD(_ value: Double) -> String {
        if value >= 1_000_000_000 { return String(format: "$%.1fB", value / 1_000_000_000) }
        if value >= 1_000_000 { return String(format: "$%.1fM", value / 1_000_000) }
        if value >= 1_000 { return String(format: "$%.0fK", value / 1_000) }
        return String(format: "$%.0f", value)
    }

    private func ageSuffix(_ birthday: String) -> String {
        let formatter = DateFormatter()
        formatter.calendar = Calendar(identifier: .gregorian)
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.timeZone = TimeZone(secondsFromGMT: 0)
        formatter.dateFormat = "yyyy-MM-dd"
        guard let date = formatter.date(from: birthday) else { return "" }
        let age = Calendar(identifier: .gregorian).dateComponents([.year], from: date, to: Date()).year ?? 0
        return age > 0 ? " • age \(age)" : ""
    }
}

