struct V1134CastCreditCard: View {
    let credit: CastExplorerCredit
    let onSelect: () -> Void
    @FocusState private var focused: Bool

    private var focusFill: Color {
        focused ? Color.white.opacity(0.085) : Color.black.opacity(0.26)
    }

    private var focusStroke: Color {
        focused ? Color.orange.opacity(0.90) : Color.clear
    }

    private var accessibilityText: String {
        var parts = [credit.title, credit.mediaType == "movie" ? "movie" : "TV show"]
        if let year = credit.year, !year.isEmpty { parts.append(year) }
        return parts.joined(separator: ", ")
    }

    var body: some View {
        accessibleCard
    }

    // Type erasure is deliberate here. The physical-test correction added custom
    // focus, animation, accessibility and styling to the same card. Xcode's SwiftUI
    // type checker can otherwise spend minutes expanding one enormous generic type.
    // Staging the card keeps the exact UI/behavior while bounding compiler work.
    private var visualCard: AnyView {
        AnyView(
            V1143CastCreditCardContent(credit: credit, focused: focused)
                .padding(8)
                .background(V1143CastCreditCardBackground(fill: focusFill))
                .overlay(V1143CastCreditCardBorder(stroke: focusStroke, focused: focused))
                .scaleEffect(focused ? 1.055 : 1.0)
                .shadow(color: focused ? Color.orange.opacity(0.16) : .clear, radius: 14, y: 5)
        )
    }

    private var focusCard: AnyView {
        AnyView(
            visualCard
                .focusable(true)
                .signalVisionFocusEffectPolicy()
                .focused($focused)
                .onTapGesture(perform: onSelect)
                .animation(.easeOut(duration: 0.15), value: focused)
        )
    }

    private var accessibleCard: AnyView {
        AnyView(
            focusCard
                .accessibilityElement(children: .combine)
                .accessibilityAddTraits(.isButton)
                .accessibilityLabel(accessibilityText)
                .accessibilityHint("Open this title")
        )
    }
}

