struct V1111FeaturedCastPosterCard: View {
    let item: MediaItem
    let members: [CastMember]
    let awake: Bool
    let mode: VODFeaturedCastPresentationMode
    let playbackReady: Bool
    let themedLogoEnabled: Bool
    @Binding var spotlightIndex: Int
    @Binding var initialHoldClaimed: Bool
    let focusRequestToken: UInt64
    let manualNavigationToken: UInt64
    let focusActive: Bool
    let onFocusChanged: (Bool) -> Void
    let onCastSelected: (CastMember) -> Void

    @State private var showingOriginalPoster = true
    // vBRDC106: the visible identity follows the bitmap that actually made it to screen,
    // not merely the requested rotation index. This keeps portrait, name, role and Select
    // action atomic while preservePreviousOnURLChange is holding the outgoing portrait.
    @State private var displayedCastMemberID: String? = nil
    // vBRDC119: arrows are a transient discoverability hint only. They appear inside
    // the active cast portrait when Cast first receives focus, then fade away.
    @State private var castNavigationHintVisible: Bool = false
    @State private var castNavigationHintToken: UInt64 = 0
    @FocusState private var castExplorerFocused: Bool
    private let posterHeight: CGFloat = 207
    private let compactBannerHeight: CGFloat = 58

    private var imageMembers: [CastMember] {
        members.filter { member in
            let raw = member.imageURL?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
            guard let url = URL(string: raw), let scheme = url.scheme?.lowercased() else { return false }
            return scheme == "http" || scheme == "https"
        }
    }

    private var normalizedIndex: Int {
        guard !imageMembers.isEmpty else { return 0 }
        let positive = max(spotlightIndex, 0)
        return positive % imageMembers.count
    }

    private var currentMember: CastMember? {
        guard imageMembers.indices.contains(normalizedIndex) else { return nil }
        return imageMembers[normalizedIndex]
    }

    private var displayedMember: CastMember? {
        if let displayedCastMemberID,
           let committed = imageMembers.first(where: { $0.id == displayedCastMemberID }) {
            return committed
        }
        return currentMember
    }

    private var canPresentCast: Bool {
        playbackReady && awake && mode != .off && currentMember != nil
    }

    private var shouldShowFullPosterCast: Bool {
        canPresentCast && mode == .fullPoster && !showingOriginalPoster
    }

    private var isCastSelectable: Bool {
        guard canPresentCast else { return false }
        // The full-poster surface remains a valid focus destination during its brief
        // title-poster hold. A real UP navigation can therefore claim the Cast Wall
        // immediately instead of leaving tvOS hunting through a scroll container.
        return mode == .compactOverlay || mode == .fullPoster
    }

    var body: some View {
        decoratedPresentation
    }

    // v1140 Phase 15 compile correction:
    // Keep the exact v1139 Cast Explorer behavior, but split the large SwiftUI generic
    // expression into smaller typed stages. Xcode's Release compiler timed out while
    // type-checking the previous single modifier chain.
    private var presentationLayout: some View {
        VStack(spacing: mode == .compactOverlay ? 6 : 0) {
            posterSurface
                .frame(maxWidth: .infinity)
                .frame(height: posterHeight)

            if mode == .compactOverlay {
                compactBannerSurface
                    .frame(maxWidth: .infinity)
                    .frame(height: compactBannerHeight)
            }
        }
    }

    private var taskManagedPresentation: some View {
        presentationLayout
            .task(id: revealTaskID) {
                await runRevealTask()
            }
            .task(id: rotationTaskID) {
                await runRotationTask()
            }
            .task(id: castNavigationHintToken) {
                await runCastNavigationHintTask()
            }
            .onChange(of: imageMembers.count) { _, count in
                normalizeSpotlightIndex(for: count)
                if count <= 1 { castNavigationHintVisible = false }
                if let displayedCastMemberID,
                   !imageMembers.contains(where: { $0.id == displayedCastMemberID }) {
                    self.displayedCastMemberID = nil
                }
            }
    }

    private var focusManagedPresentation: some View {
        taskManagedPresentation
            // Phase 14 corrective: the Cast Wall is not a candidate in the native focus
            // graph unless the parent VOD router explicitly owns the Cast zone. This prevents
            // tvOS geometry from skipping the timeline scrubber and jumping straight to Cast.
            .focusable(isCastSelectable && focusActive)
            .focused($castExplorerFocused)
            .onChange(of: focusActive) { _, active in
                handleFocusActiveChange(active)
            }
            .onChange(of: focusRequestToken) { _, _ in
                handleFocusRequest()
            }
            .onChange(of: castExplorerFocused) { _, focused in
                handleCastExplorerFocusChange(focused)
            }
            .onTapGesture {
                handleCastSelection()
            }
    }

    private var decoratedPresentation: some View {
        focusManagedPresentation
            .scaleEffect(castExplorerFocused ? 1.035 : 1.0)
            .overlay(castFocusOutline)
            .shadow(color: castExplorerFocused ? Color.orange.opacity(0.20) : .clear, radius: 16)
            .animation(.easeOut(duration: 0.16), value: castExplorerFocused)
            .accessibilityElement(children: .combine)
            .accessibilityLabel(accessibilityText)
            .accessibilityHint(isCastSelectable ? "Press Left or Right to browse cast. Press Select to open Cast Explorer." : "")
            .accessibilityIdentifier("V1111FeaturedCastPosterPresentation")
    }

    private var castFocusOutline: some View {
        RoundedRectangle(cornerRadius: 22, style: .continuous)
            .stroke(castExplorerFocused ? Color.orange.opacity(0.90) : Color.clear, lineWidth: 2)
            .padding(-4)
    }

    private var revealTaskID: String {
        "reveal|\(item.id)|\(mode.rawValue)|\(awake)|\(playbackReady)"
    }

    private var imageMemberRotationSignature: String {
        // vBRDC123: the rotation owner follows the actual cast identities/URLs, not only
        // the array count. Metadata enrichment can replace members without changing count;
        // restarting from the new signature prevents a long-lived task from capturing a
        // stale cast snapshot and guarantees the seven-second cycle follows current data.
        imageMembers
            .map { "\($0.id)|\($0.imageURL ?? "")" }
            .joined(separator: ";")
    }

    private var rotationTaskID: String {
        "rotate|\(item.id)|\(mode.rawValue)|\(awake)|\(playbackReady)|\(imageMemberRotationSignature)|manual:\(manualNavigationToken)"
    }

    @MainActor
    private func runRevealTask() async {
        guard playbackReady, mode == .fullPoster, awake, !imageMembers.isEmpty else { return }
        if initialHoldClaimed {
            showingOriginalPoster = false
            return
        }

        // Claim the presentation-wide hold before sleeping. If the overlay hides or
        // remounts during this window, a later view cannot restart another four seconds.
        initialHoldClaimed = true
        showingOriginalPoster = true
        try? await Task.sleep(nanoseconds: 4_000_000_000)
        guard !Task.isCancelled, mode == .fullPoster, awake else { return }
        withAnimation(.easeInOut(duration: 0.70)) {
            showingOriginalPoster = false
        }
    }

    @MainActor
    private func runRotationTask() async {
        guard playbackReady, awake, mode != .off, imageMembers.count > 1 else { return }
        while !Task.isCancelled {
            try? await Task.sleep(nanoseconds: 7_000_000_000)
            guard !Task.isCancelled,
                  playbackReady,
                  awake,
                  mode != .off,
                  imageMembers.count > 1
            else {
                return
            }

            if mode == .fullPoster && showingOriginalPoster {
                continue
            }

            withAnimation(.easeInOut(duration: 0.55)) {
                spotlightIndex = (normalizedIndex + 1) % imageMembers.count
            }
        }
    }

    @MainActor
    private func runCastNavigationHintTask() async {
        guard castNavigationHintVisible, imageMembers.count > 1 else { return }
        try? await Task.sleep(nanoseconds: 2_200_000_000)
        guard !Task.isCancelled else { return }
        withAnimation(.easeOut(duration: 0.22)) {
            castNavigationHintVisible = false
        }
    }

    private func showCastNavigationHintIfNeeded() {
        guard imageMembers.count > 1 else {
            castNavigationHintVisible = false
            return
        }
        castNavigationHintToken &+= 1
        withAnimation(.easeOut(duration: 0.14)) {
            castNavigationHintVisible = true
        }
    }

    private func normalizeSpotlightIndex(for count: Int) {
        guard count > 0 else {
            spotlightIndex = 0
            return
        }
        spotlightIndex = max(spotlightIndex, 0) % count
    }

    private func handleFocusActiveChange(_ active: Bool) {
        if !active, castExplorerFocused {
            castExplorerFocused = false
        }
    }

    private func handleFocusRequest() {
        guard isCastSelectable, focusActive else { return }
        if mode == .fullPoster && showingOriginalPoster {
            withAnimation(.easeInOut(duration: 0.30)) {
                showingOriginalPoster = false
            }
        }
        castExplorerFocused = true
    }

    private func handleCastExplorerFocusChange(_ focused: Bool) {
        if focused, mode == .fullPoster, showingOriginalPoster {
            withAnimation(.easeInOut(duration: 0.30)) {
                showingOriginalPoster = false
            }
        }
        if focused {
            showCastNavigationHintIfNeeded()
        } else {
            castNavigationHintVisible = false
        }
        onFocusChanged(focused)
    }

    private func handleCastSelection() {
        guard isCastSelectable, focusActive, let member = displayedMember ?? currentMember else { return }
        onCastSelected(member)
    }

    private var posterSurface: some View {
        ZStack(alignment: .bottomLeading) {
            RoundedRectangle(cornerRadius: 20, style: .continuous)
                .fill(Color.black.opacity(0.42))

            RemoteImageFit(url: item.posterURL, mode: .fit, maxPixelSize: 1024, publishDuringPlayback: true)
                .frame(maxWidth: .infinity, maxHeight: .infinity)
                .opacity(shouldShowFullPosterCast ? 0 : 1)

            if playbackReady, let member = currentMember, let imageURL = member.imageURL {
                fullPosterCast(member: member, imageURL: imageURL)
                    .opacity(shouldShowFullPosterCast ? 1 : 0)
            }

            if themedLogoEnabled,
               !shouldShowFullPosterCast,
               let logoURL = item.logoURL?.trimmingCharacters(in: .whitespacesAndNewlines),
               !logoURL.isEmpty {
                VStack {
                    Spacer(minLength: 0)
                    RemoteImageFit(
                        url: logoURL,
                        mode: .fit,
                        showPlaceholder: false,
                        maxPixelSize: 640,
                        publishDuringPlayback: true,
                        forceVisiblePlaybackPublication: true
                    )
                        .frame(maxWidth: 112, maxHeight: 38, alignment: .leading)
                        .shadow(color: .black.opacity(0.76), radius: 5, y: 2)
                }
                .padding(.horizontal, 10)
                .padding(.bottom, 10)
                .allowsHitTesting(false)
                .accessibilityLabel("Poster title artwork")
            }

            if canPresentCast && mode == .fullPoster && showingOriginalPoster {
                Text("FEATURED CAST")
                    .font(.system(size: 8, weight: .black, design: .rounded))
                    .tracking(1.0)
                    .foregroundStyle(.white.opacity(0.70))
                    .padding(.horizontal, 8)
                    .padding(.vertical, 5)
                    .background(Capsule().fill(Color.black.opacity(0.54)))
                    .padding(8)
                    .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topTrailing)
            }

            if mode == .fullPoster {
                fullPosterCastNavigationHint
            }
        }
        .clipShape(RoundedRectangle(cornerRadius: 20, style: .continuous))
        .overlay(RoundedRectangle(cornerRadius: 20, style: .continuous).stroke(Color.white.opacity(0.18), lineWidth: 1))
        .shadow(color: .black.opacity(0.60), radius: 22, y: 12)
        .animation(.easeInOut(duration: 0.70), value: shouldShowFullPosterCast)
    }

    @ViewBuilder
    private var compactBannerSurface: some View {
        if let member = currentMember, let imageURL = member.imageURL, canPresentCast {
            HStack(spacing: 8) {
                // vBRDC100: keep the last decoded cast portrait alive while the next
                // member image is fetched/decoded. Identity changes only with the title,
                // never with the rotating member, so a rotation cannot expose a blank frame.
                ZStack {
                    RemoteImageFit(
                        url: imageURL,
                        mode: .fill,
                        showPlaceholder: false,
                        maxPixelSize: 512,
                        preservePreviousOnURLChange: true,
                        publishDuringPlayback: true,
                        // vBRDC123: Featured Cast is foreground playback UI. The seven-second
                        // index may advance while the retained outgoing bitmap remains visible;
                        // use the bounded must-paint contract so the new actor cannot sit
                        // indefinitely behind the durable frame gate.
                        forceVisiblePlaybackPublication: true,
                        onDisplayedURLChange: { displayedURL in
                            commitDisplayedCastMember(member, requestedURL: imageURL, displayedURL: displayedURL)
                        }
                    )
                    compactCastNavigationHint
                }
                .id("vBRDC100-featured-cast-compact-\(item.id)")
                .frame(width: 44, height: 48)
                .clipShape(RoundedRectangle(cornerRadius: 9, style: .continuous))
                .overlay(
                    RoundedRectangle(cornerRadius: 9, style: .continuous)
                        .stroke(Color.white.opacity(0.24), lineWidth: 0.8)
                )

                VStack(alignment: .leading, spacing: 1) {
                    Text(visibleIdentity(for: member).name)
                        .font(.system(size: 9, weight: .black, design: .rounded))
                        .foregroundStyle(.white)
                        .lineLimit(2)
                        .minimumScaleFactor(0.66)
                    Text((visibleIdentity(for: member).role ?? "Featured Cast").ifEmpty("Featured Cast"))
                        .font(.system(size: 7, weight: .bold, design: .rounded))
                        .foregroundStyle(.white.opacity(0.68))
                        .lineLimit(2)
                        .minimumScaleFactor(0.62)
                }
                Spacer(minLength: 0)
            }
            .padding(.horizontal, 7)
            .padding(.vertical, 5)
            .background(
                RoundedRectangle(cornerRadius: 13, style: .continuous)
                    .fill(Color.black.opacity(0.52))
                    .overlay(
                        LinearGradient(
                            colors: [Color.white.opacity(0.05), Color.clear, Color.orange.opacity(0.05)],
                            startPoint: .topLeading,
                            endPoint: .bottomTrailing
                        )
                        .clipShape(RoundedRectangle(cornerRadius: 13, style: .continuous))
                    )
            )
            .overlay(
                RoundedRectangle(cornerRadius: 13, style: .continuous)
                    .stroke(Color.white.opacity(0.15), lineWidth: 1)
            )
            .transition(.opacity)
        } else {
            Color.clear
        }
    }

    @ViewBuilder
    private var fullPosterCastNavigationHint: some View {
        if castExplorerFocused && castNavigationHintVisible && imageMembers.count > 1 {
            HStack {
                castNavigationChevron("chevron.left", compact: false)
                Spacer(minLength: 0)
                castNavigationChevron("chevron.right", compact: false)
            }
            .padding(.horizontal, 7)
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .transition(.opacity)
            .allowsHitTesting(false)
            .accessibilityHidden(true)
        }
    }

    @ViewBuilder
    private var compactCastNavigationHint: some View {
        if castExplorerFocused && castNavigationHintVisible && imageMembers.count > 1 {
            HStack(spacing: 0) {
                castNavigationChevron("chevron.left", compact: true)
                Spacer(minLength: 0)
                castNavigationChevron("chevron.right", compact: true)
            }
            .padding(.horizontal, 2)
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .transition(.opacity)
            .allowsHitTesting(false)
            .accessibilityHidden(true)
        }
    }

    private func castNavigationChevron(_ systemName: String, compact: Bool) -> some View {
        Image(systemName: systemName)
            .font(.system(size: compact ? 6 : 10, weight: .black, design: .rounded))
            .foregroundStyle(.white.opacity(0.96))
            .frame(width: compact ? 12 : 22, height: compact ? 12 : 22)
            .background(Circle().fill(Color.black.opacity(0.58)))
            .overlay(Circle().stroke(Color.white.opacity(0.22), lineWidth: 0.7))
            .shadow(color: .black.opacity(0.34), radius: compact ? 2 : 4)
    }

    @ViewBuilder
    private func fullPosterCast(member: CastMember, imageURL: String) -> some View {
        ZStack(alignment: .bottomLeading) {
            // vBRDC100: same retained-frame handoff as Compact Cast. The current actor
            // remains visible until the replacement bitmap is ready, then swaps in place.
            RemoteImageFit(
                url: imageURL,
                mode: .fill,
                showPlaceholder: false,
                maxPixelSize: 1024,
                preservePreviousOnURLChange: true,
                publishDuringPlayback: true,
                // vBRDC123: full-poster Featured Cast uses the same foreground publication
                // contract as Compact Cast so each scheduled actor becomes visible promptly.
                forceVisiblePlaybackPublication: true,
                onDisplayedURLChange: { displayedURL in
                    commitDisplayedCastMember(member, requestedURL: imageURL, displayedURL: displayedURL)
                }
            )
                .id("vBRDC100-featured-cast-full-\(item.id)")
                .frame(maxWidth: .infinity, maxHeight: .infinity)
                .clipped()

            LinearGradient(
                colors: [Color.clear, Color.black.opacity(0.10), Color.black.opacity(0.90)],
                startPoint: .top,
                endPoint: .bottom
            )

            VStack(alignment: .leading, spacing: 2) {
                Text(visibleIdentity(for: member).name)
                    .font(.system(size: 13, weight: .black, design: .rounded))
                    .foregroundStyle(.white)
                    .lineLimit(2)
                    .minimumScaleFactor(0.68)
                Text((visibleIdentity(for: member).role ?? "Featured Cast").ifEmpty("Featured Cast"))
                    .font(.system(size: 10, weight: .bold, design: .rounded))
                    .foregroundStyle(.white.opacity(0.72))
                    .lineLimit(2)
                    .minimumScaleFactor(0.64)
            }
            .padding(.horizontal, 10)
            .padding(.bottom, 9)
        }
    }

    private func commitDisplayedCastMember(_ member: CastMember, requestedURL: String, displayedURL: URL?) {
        guard let requested = PremiumArtworkURL.url(requestedURL), displayedURL == requested else { return }
        if displayedCastMemberID != member.id {
            displayedCastMemberID = member.id
        }
    }

    private func visibleIdentity(for requested: CastMember) -> CastMember {
        displayedMember ?? requested
    }

    private var accessibilityText: String {
        switch mode {
        case .off:
            return "Movie or show poster"
        case .compactOverlay:
            return "Movie or show poster with featured cast banner for \(displayedMember?.name ?? currentMember?.name ?? "")"
        case .fullPoster:
            return shouldShowFullPosterCast ? "Featured cast \(displayedMember?.name ?? currentMember?.name ?? "")" : "Movie or show poster"
        }
    }
}

private struct VBRDC193SpotlightHubPanel: View {
    let item: MediaItem
    let metadata: VODProductionMetadataSnapshot

    @EnvironmentObject private var store: CatalogStore
    @AppStorage("tmdbApiKey") private var tmdbApiKey: String = ""
    @State private var traktStats: TraktTitleStats? = nil
    @State private var traktStatsLoading: Bool = false
    @State private var traktRelatedItems: [MediaItem] = []

    private var providers: [VODWatchProvider] {
        Array(metadata.watchProviders.prefix(5))
    }

    private var cloudResume: TraktCloudResumePoint? {
        TraktSyncManager.shared.cloudResumePoint(for: item)
    }

    private var personalStatus: TraktPersonalTitleStatus {
        TraktCatalogService.shared.personalStatus(for: item)
    }

    private var hasAnything: Bool {
        traktStats != nil || cloudResume != nil || !traktRelatedItems.isEmpty || personalStatus.inWatchlist || personalStatus.isFavorite || personalStatus.recentlyWatched || !providers.isEmpty || metadata.reviewHighlight != nil
    }

    var body: some View {
        spotlightHubContent
            .padding(.horizontal, 11)
            .padding(.vertical, 10)
            .background(spotlightHubBackground)
            .overlay(spotlightHubBorder)
            .accessibilityElement(children: .combine)
            .accessibilityLabel("Spotlight Hub for \(item.title)")
            .task(id: item.id) {
                await loadSpotlightHub()
            }
    }

    @ViewBuilder
    private var spotlightHubContent: some View {
        VStack(alignment: .leading, spacing: 8) {
            spotlightHubHeader
            traktPulseSection

            if TraktSyncManager.shared.isConnected {
                yourTraktSection
            }

            if !traktRelatedItems.isEmpty {
                relatedOnTraktStrip
            }

            if !providers.isEmpty {
                watchProviderStrip
            }

            if traktRelatedItems.isEmpty, let review = metadata.reviewHighlight {
                reviewCard(review)
            } else if !hasAnything {
                emptyState
            }

            if !providers.isEmpty {
                availabilityAttribution
            }
        }
    }

    private var spotlightHubHeader: some View {
        HStack(spacing: 7) {
            Image(systemName: "waveform.path.ecg.rectangle.fill")
                .font(.system(size: 10, weight: .bold))
                .foregroundStyle(.cyan.opacity(0.98))
            Text("SPOTLIGHT HUB")
                .font(.system(size: 9, weight: .black, design: .rounded))
                .tracking(1.25)
                .foregroundStyle(.white.opacity(0.82))
            Spacer(minLength: 8)
            Text("TRAKT PULSE • WATCH • COMMUNITY")
                .font(.system(size: 6.5, weight: .black, design: .rounded))
                .tracking(0.55)
                .foregroundStyle(.white.opacity(0.36))
        }
    }

    private var availabilityAttribution: some View {
        HStack(spacing: 4) {
            Text("Availability by")
            Text("JustWatch").fontWeight(.bold)
            Text("via TMDB")
        }
