    @MainActor
    private func loadSpotlightHub() async {
        TraktSyncManager.shared.refreshPlaybackProgressIfNeeded(force: false)
        guard !traktStatsLoading else { return }

        traktStatsLoading = true
        defer { traktStatsLoading = false }

        let baseItems = store.rows
            .filter { $0.presentation?.providerName?.caseInsensitiveCompare("Trakt") != .orderedSame }
            .flatMap(\.items)

        async let statsTask = TraktSyncManager.shared.publicStats(for: item)
        async let relatedTask = TraktCatalogService.shared.relatedItems(
            for: item,
            existingItems: baseItems,
            tmdbApiKey: tmdbApiKey
        )

        let (stats, related) = await (statsTask, relatedTask)
        guard !Task.isCancelled else { return }

        traktStats = stats
        traktRelatedItems = related

        // The Spotlight validator returns String?, while the shared poster prefetcher
        // takes [URL]. Normalize explicitly at this boundary to retain the validated
        // artwork and themed-logo URLs without asking Swift to infer incompatible types.
        let spotlightURLs: [URL] = related.prefix(4).flatMap { relatedItem -> [URL] in
            let artwork = validURL(relatedItem.landscapeURL ?? relatedItem.posterURL)
                .flatMap { URL(string: $0) }
            let logo = validURL(relatedItem.logoURL)
                .flatMap { URL(string: $0) }
            return [artwork, logo].compactMap { $0 }
        }
        // Spotlight must not replace the main catalog's single global byte-prefetch
        // queue; its own mounted artwork loads normally, with just two bounded warmups.
        for url in spotlightURLs.prefix(2) {
            PremiumRemoteImageLoader.prewarm(url, maxPixelSize: 768)
        }
    }

