    private func compactCount(_ value: Int) -> String {
        if value >= 1_000_000 { return String(format: "%.1fM", Double(value) / 1_000_000.0) }
        if value >= 1_000 { return String(format: "%.1fK", Double(value) / 1_000.0) }
        return "\(value)"
    }

    private func relativeSyncText(_ date: Date) -> String {
        let seconds = max(0, Date().timeIntervalSince(date))
        if seconds < 90 { return "synced just now" }
        if seconds < 3600 { return "synced \(Int(seconds / 60))m ago" }
        if seconds < 86_400 { return "synced \(Int(seconds / 3600))h ago" }
        return "synced \(Int(seconds / 86_400))d ago"
    }

    private func cleanReviewText(_ value: String) -> String {
        value
            .replacingOccurrences(of: #"https?://\S+|www\.\S+"#, with: "", options: [.regularExpression, .caseInsensitive])
            .replacingOccurrences(of: #"\s+"#, with: " ", options: .regularExpression)
            .trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private func validURL(_ value: String?) -> String? {
        let text = value?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let lower = text.lowercased()
        guard lower.hasPrefix("https://") || lower.hasPrefix("http://") else { return nil }
        guard !lower.contains("placeholder"), !lower.contains("missing"), !lower.contains("default") else { return nil }
        return text
    }
}

private struct V1106ProductionFact: Identifiable {
    let id: String
    let icon: String
    let label: String
    let value: String
    let tint: Color
}

struct V1108ProductionRatingsPanel: View {
    let item: MediaItem
    let metadata: VODProductionMetadataSnapshot
    let rottenTomatoesScore: String?
    let communityScore: String?
    let playbackRuntimeMinutes: Int?
    let awake: Bool
    let themedLogoEnabled: Bool
    @Binding var artworkIndex: Int

    private var knownCertification: String? {
        if let certification = clean(metadata.certification) { return certification }
        let value = item.rating.trimmingCharacters(in: .whitespacesAndNewlines).uppercased()
        let known = Set(["G", "PG", "PG-13", "R", "NC-17", "TV-Y", "TV-Y7", "TV-G", "TV-PG", "TV-14", "TV-MA"])
        return known.contains(value) ? value : nil
    }

    private var advisory: String? {
        let matches = item.genres.compactMap { raw -> String? in
            let lower = raw.lowercased()
            if lower.contains("violence") || lower.contains("gore") { return "Violence" }
            if lower.contains("language") || lower.contains("explicit") { return "Language" }
            if lower.contains("drug") { return "Drug use" }
            if lower.contains("nudity") || lower.contains("sexual") || lower.contains("adult") { return "Mature content" }
            return nil
        }.uniquedPreservingOrder()
        if !matches.isEmpty { return matches.prefix(2).joined(separator: " • ") }
        if ["R", "NC-17", "TV-MA"].contains(knownCertification ?? "") { return "Mature audiences" }
        if ["PG-13", "TV-14"].contains(knownCertification ?? "") { return "Parents cautioned" }
        return nil
    }

    private var isTelevisionTitle: Bool {
        let lower = item.type.lowercased()
        return item.seasonNumber != nil
            || item.episodeNumber != nil
            || lower.contains("series")
            || lower.contains("show")
            || lower.contains("episode")
            || lower == "tv"
    }

    private var facts: [V1106ProductionFact] {
        var output: [V1106ProductionFact] = []

        // v1112: keep the panel compact, but prioritize genuinely useful title facts.
        // Movie budget/box office can no longer be pushed out by decorative rows.
        if let rating = knownCertification {
            output.append(.init(id: "rating", icon: "checkmark.shield.fill", label: "RATING", value: rating, tint: .orange))
        }
        if let advisory {
            output.append(.init(id: "advisory", icon: "exclamationmark.triangle.fill", label: "ADVISORY", value: advisory, tint: .red))
        }
        if let budget = metadata.budget {
            output.append(.init(id: "budget", icon: "banknote.fill", label: "BUDGET", value: money(budget), tint: .mint))
        }
        if let revenue = metadata.revenue {
            output.append(.init(id: "revenue", icon: "chart.line.uptrend.xyaxis", label: "BOX OFFICE", value: money(revenue), tint: .green))
        }
        if let runtime = metadata.runtimeMinutes ?? playbackRuntimeMinutes, runtime > 0 {
            output.append(.init(id: "runtime", icon: "clock.fill", label: "RUNTIME", value: "\(runtime) min", tint: .cyan))
        }
        if let releaseDate = clean(metadata.releaseDate) {
            output.append(.init(
                id: "releaseDate",
                icon: "calendar.badge.clock",
                label: isTelevisionTitle ? "FIRST AIRED" : "RELEASED",
                value: releaseDate,
                tint: .teal
            ))
        }
        if let status = clean(metadata.status) {
            output.append(.init(id: "status", icon: "dot.radiowaves.left.and.right", label: "STATUS", value: status, tint: .blue))
        }
        if isTelevisionTitle, let companyLine {
            output.append(.init(id: "company", icon: "building.2.fill", label: "NETWORK / STUDIO", value: companyLine, tint: .orange))
        }
        if let critic = clean(rottenTomatoesScore) {
            output.append(.init(id: "critic", icon: "🍅", label: "CRITICS", value: critic, tint: .red))
        }
        if let community = clean(communityScore) {
            output.append(.init(id: "community", icon: "🍿", label: "IMDB", value: community, tint: .yellow))
        }
        if let countries = joined(metadata.countries) {
            output.append(.init(id: "country", icon: "globe.americas.fill", label: "COUNTRY", value: countries, tint: .purple))
        }
        if let languages = joined(metadata.languages) {
            output.append(.init(id: "language", icon: "captions.bubble.fill", label: "LANGUAGE", value: languages, tint: .indigo))
        }
        return Array(output.prefix(8))
    }

    private var allCompanies: [VODProductionCompany] {
        var seen = Set<String>()
        return (metadata.networks + metadata.studios).filter { company in
            let normalizedName = company.name
                .trimmingCharacters(in: .whitespacesAndNewlines)
                .lowercased()
            let normalizedLogo = (company.logoURL ?? "")
                .trimmingCharacters(in: .whitespacesAndNewlines)
                .lowercased()
            let key = !normalizedName.isEmpty ? normalizedName : normalizedLogo
            guard !key.isEmpty else { return false }
            return seen.insert(key).inserted
        }
    }

    private var primaryCompany: VODProductionCompany? {
        allCompanies.first(where: { clean($0.logoURL) != nil }) ?? allCompanies.first
    }

    private var companyLine: String? {
        let names = allCompanies.map(\.name).uniquedPreservingOrder()
        return names.isEmpty ? nil : names.prefix(2).joined(separator: " • ")
    }

    private var artworkURLs: [String] {
        var seen = Set<String>()
        let editorialBackdrops = metadata.landscapeArtworkURLs
            .compactMap { validatedArtworkURL($0) }
            .filter { seen.insert($0.lowercased()).inserted }

        // The metadata service supplies language-neutral backdrops first so countdown and
        // “coming tomorrow” promotional banners are not rotated into this panel.
        if !editorialBackdrops.isEmpty {
            return editorialBackdrops
        }

        // Preserve one known title image only as a last-resort fallback when no vetted
        // backdrop/fanart is available.
        if let fallback = validatedArtworkURL(item.landscapeURL) {
            return [fallback]
        }
        return []
    }

    private var titleLogoURL: String? {
        validatedLogoURL(item.logoURL) ?? validatedLogoURL(metadata.titleLogoURL)
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 7) {
            V1111ProductionArtworkHeader(
                artworkURLs: artworkURLs,
                artworkAspectRatios: metadata.landscapeArtworkAspectRatios,
                titleLogoURL: themedLogoEnabled ? titleLogoURL : nil,
                companyLogoURL: primaryCompany.flatMap { clean($0.logoURL) },
                companyName: companyLine,
                awake: awake,
                artworkIndex: $artworkIndex
            )
            // vBRDC100: reset retained artwork only when the actual media title changes;
            // ordinary 7-second artwork rotation keeps the same loader/state owner.
            .id("vBRDC100-production-header-\(item.id)")

            Rectangle()
                .fill(LinearGradient(colors: [.orange.opacity(0.44), .white.opacity(0.07), .clear], startPoint: .leading, endPoint: .trailing))
                .frame(height: 1)

            LazyVGrid(columns: [GridItem(.flexible(), spacing: 8), GridItem(.flexible(), spacing: 8)], alignment: .leading, spacing: 5) {
                ForEach(facts) { fact in
                    HStack(alignment: .top, spacing: 7) {
                        if fact.icon.count <= 2 {
                            Text(fact.icon).font(.system(size: 12))
                        } else {
                            Image(systemName: fact.icon)
                                .font(.system(size: 10, weight: .bold))
                                .foregroundStyle(fact.tint.opacity(0.92))
                        }
                        VStack(alignment: .leading, spacing: 1) {
                            Text(fact.label)
                                .font(.system(size: 7, weight: .black, design: .rounded))
                                .tracking(0.6)
                                .foregroundStyle(.white.opacity(0.40))
                            Text(fact.value)
                                .font(.system(size: 9, weight: .black, design: .rounded))
                                .foregroundStyle(.white.opacity(0.90))
                                .lineLimit(1)
                                .minimumScaleFactor(0.62)
                        }
                    }
                    .frame(maxWidth: .infinity, alignment: .leading)
                }
            }
        }
        .padding(.horizontal, 11)
        .padding(.vertical, 9)
        .background(
            RoundedRectangle(cornerRadius: 24, style: .continuous)
                .fill(Color.black.opacity(0.20))
                .overlay(
                    LinearGradient(
                        colors: [Color.white.opacity(0.035), Color.clear, Color.black.opacity(0.08)],
                        startPoint: .topLeading,
                        endPoint: .bottomTrailing
                    )
                    .clipShape(RoundedRectangle(cornerRadius: 24, style: .continuous))
                )
        )
        .overlay(RoundedRectangle(cornerRadius: 24, style: .continuous).stroke(Color.white.opacity(0.11), lineWidth: 1))
    }

    private func validatedArtworkURL(_ value: String?) -> String? {
        let text = value?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let lower = text.lowercased()
        guard (lower.hasPrefix("https://") || lower.hasPrefix("http://")),
              !lower.contains("placeholder"),
              !lower.contains("default"),
              !lower.contains("missing") else { return nil }
        return text
    }

    private func validatedLogoURL(_ value: String?) -> String? {
        validatedArtworkURL(value)
    }

    private func clean(_ value: String?) -> String? {
        let text = value?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        guard !text.isEmpty, text.uppercased() != "N/A", text != "—", text != "0", text != "0.0" else { return nil }
        return text
    }

    private func joined(_ values: [String]) -> String? {
        let cleanValues = values.map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }.filter { !$0.isEmpty }
        return cleanValues.isEmpty ? nil : cleanValues.prefix(2).joined(separator: " • ")
    }

    private func money(_ value: Int) -> String {
        let amount = Double(value)
        if amount >= 1_000_000_000 { return String(format: "$%.1fB", amount / 1_000_000_000) }
        if amount >= 1_000_000 { return String(format: "$%.1fM", amount / 1_000_000) }
        if amount >= 1_000 { return String(format: "$%.0fK", amount / 1_000) }
        return "$\(value)"
    }
}

private struct V1111ProductionArtworkHeader: View {
    let artworkURLs: [String]
    let artworkAspectRatios: [String: Double]
    let titleLogoURL: String?
    let companyLogoURL: String?
    let companyName: String?
    let awake: Bool
    @Binding var artworkIndex: Int

    private var safeIndex: Int {
        guard !artworkURLs.isEmpty else { return 0 }
        return min(max(artworkIndex, 0), artworkURLs.count - 1)
    }

    private var currentArtworkURL: String? {
        guard artworkURLs.indices.contains(safeIndex) else { return nil }
        return artworkURLs[safeIndex]
    }

    private var rotationTaskID: String {
        // vBRDC106: the task exists only while this visible overlay header is mounted.
        // Hidden chrome unmounts the header, cancelling the task, so no 7-second cycling
        // or artwork requests run in the background.
        "vBRDC106-production-rotation|\(awake)|\(artworkURLs.count)|\(artworkURLs.joined(separator: "|"))"
    }

    @MainActor
    private func runVisibleRotationTask() async {
        guard awake, artworkURLs.count > 1 else { return }
        while !Task.isCancelled {
            try? await Task.sleep(nanoseconds: 7_000_000_000)
            guard !Task.isCancelled, awake, artworkURLs.count > 1 else { return }
            withAnimation(.easeInOut(duration: 0.80)) {
                artworkIndex = (safeIndex + 1) % artworkURLs.count
            }
        }
    }

    private var bannerHeight: CGFloat {
        // v1112: keep a true banner-sized header. Artwork remains fully visible via
        // aspect-fit inside this fixed canvas instead of making the whole panel grow.
        138
    }

    var body: some View {
        ZStack(alignment: .bottomLeading) {
            RoundedRectangle(cornerRadius: 14, style: .continuous)
                .fill(Color.black.opacity(0.48))

            if let currentArtworkURL {
                // v1112: the fixed banner canvas keeps the panel compact while
                // aspect-fit preserves the complete official artwork without cropping.
                // vBRDC100: do not key this view by each rotating URL. Reusing one loader
                // lets preservePreviousOnURLChange hold the old bitmap until the new one is ready.
                RemoteImageFit(
                    url: currentArtworkURL,
                    mode: .fit,
                    showPlaceholder: false,
                    maxPixelSize: 1280,
                    preservePreviousOnURLChange: true,
                    publishDuringPlayback: true,
                    forceVisiblePlaybackPublication: true
                )
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
            } else {
                LinearGradient(
                    colors: [Color.white.opacity(0.04), Color.black.opacity(0.24)],
                    startPoint: .topLeading,
                    endPoint: .bottomTrailing
                )
            }

            LinearGradient(
                colors: [Color.clear, Color.black.opacity(0.04), Color.black.opacity(0.64)],
                startPoint: .top,
                endPoint: .bottom
            )

            VStack(alignment: .leading, spacing: 0) {
                // v1117: keep the rotating production artwork unobstructed. The
                // section label was decorative and covered valid banner content.
                Spacer(minLength: 0)

                HStack(alignment: .bottom, spacing: 10) {
                    if let titleLogoURL {
                        RemoteImageFit(
                            url: titleLogoURL,
                            mode: .fit,
                            showPlaceholder: false,
                            maxPixelSize: 640,
                            publishDuringPlayback: true,
                            forceVisiblePlaybackPublication: true
                        )
                            .frame(width: 142, height: 33, alignment: .leading)
                            .shadow(color: .black.opacity(0.75), radius: 5, y: 2)
                            .accessibilityLabel("Title logo")
                    }

                    Spacer(minLength: 0)

                    if let companyLogoURL {
                        RemoteImageFit(url: companyLogoURL, mode: .fit, showPlaceholder: false, maxPixelSize: 384, publishDuringPlayback: true, forceVisiblePlaybackPublication: true)
                            .frame(width: 64, height: 20, alignment: .trailing)
                            .accessibilityLabel(companyName ?? "Production company")
                    } else if let companyName {
                        Text(companyName)
                            .font(.system(size: 8, weight: .bold, design: .rounded))
                            .foregroundStyle(.white.opacity(0.64))
                            .lineLimit(1)
                            .minimumScaleFactor(0.68)
                            .frame(maxWidth: 104, alignment: .trailing)
                    }
                }
            }
            .padding(9)
        }
        .frame(maxWidth: .infinity)
        .frame(height: bannerHeight)
        .clipShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
        .overlay(RoundedRectangle(cornerRadius: 14, style: .continuous).stroke(Color.white.opacity(0.14), lineWidth: 1))
        .animation(.easeInOut(duration: 0.80), value: safeIndex)
        .task(id: rotationTaskID) {
            await runVisibleRotationTask()
        }
        .onChange(of: artworkURLs.count) { _, newCount in
            guard newCount > 0 else {
                artworkIndex = 0
                return
            }
            if artworkIndex >= newCount || artworkIndex < 0 {
                artworkIndex = 0
            }
        }
        .accessibilityElement(children: .combine)
        .accessibilityLabel("Production artwork \(safeIndex + 1) of \(max(artworkURLs.count, 1))")
        .accessibilityIdentifier("V1112ProductionArtworkHeader")
    }
}

