                .font(.system(size: theme == .mediaCenter ? 12 : 11, weight: theme == .mediaCenter ? .bold : .semibold, design: headerDesign))
                .tracking(tracking)
                .foregroundStyle(.white.opacity(theme == .original ? 0.66 : (theme == .minimal ? 0.52 : 0.70)))
            Rectangle()
                .fill(LinearGradient(colors: [accent.opacity(theme == .noir ? 0.55 : 0.92), accent.opacity(0.18), .clear], startPoint: .leading, endPoint: .trailing))
