        .shadow(color: .black.opacity(0.42), radius: 22, y: 10)
        .shadow(color: accent.opacity(0.18), radius: 22, y: 2)
        .animation(.easeInOut(duration: 0.42), value: safeIndex)
        .accessibilityIdentifier("V1052PremiumFeaturedCast")
        .onReceive(timer) { _ in
            guard members.count > 1 else { return }
            withAnimation(.easeInOut(duration: 0.42)) {
                spotlightIndex = (safeIndex + 1) % members.count
            }
        }
    }
}

