struct V1097VerifiedCastProfileImage: View {
    let memberID: String
    let rawURL: String?
    let onUnavailable: (String) -> Void
    @StateObject private var loader = PremiumRemoteImageLoader()
    @State private var reportedUnavailable = false

    private var resolvedURL: URL? { PremiumArtworkURL.url(rawURL) }

    var body: some View {
        Group {
            if let resolvedURL,
               loader.imageURL == resolvedURL,
               let image = loader.image {
                Image(uiImage: image)
                    .resizable()
                    .aspectRatio(contentMode: .fill)
            } else {
                Color.clear
            }
        }
        .onAppear { loadImage() }
        .onChange(of: rawURL) { _ in loadImage() }
        .onChange(of: loader.failed) { failed in
            guard failed else { return }
            reportUnavailableOnce()
        }
        .onDisappear { loader.cancel() }
    }

    private func loadImage() {
        reportedUnavailable = false
        guard let resolvedURL else {
            reportUnavailableOnce()
            return
        }
        loader.load(resolvedURL)
    }

    private func reportUnavailableOnce() {
        guard !reportedUnavailable else { return }
        reportedUnavailable = true
        onUnavailable(memberID)
    }
}

struct V841DynamicCastWall: View {
    let members: [CastMember]
    @Binding var spotlightIndex: Int
    private let timer = Timer.publish(every: 6, on: .main, in: .common).autoconnect()

    private var normalizedSpotlightIndex: Int {
        guard !members.isEmpty else { return 0 }
        return spotlightIndex % members.count
    }

    private var current: CastMember? {
        guard !members.isEmpty else { return nil }
        return members[normalizedSpotlightIndex]
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 10) {
            HStack(spacing: 8) {
                Image(systemName: "sparkles.rectangle.stack.fill")
                    .font(.system(size: 16, weight: .black))
                    .foregroundStyle(.white.opacity(0.84))
                Text("FEATURED CAST")
                    .font(.system(size: 12, weight: .black, design: .rounded))
                    .kerning(1.7)
                Spacer()
                if !members.isEmpty {
                    Text("\(normalizedSpotlightIndex + 1) / \(members.count)")
                        .font(.system(size: 12, weight: .black, design: .rounded))
                        .foregroundStyle(.white.opacity(0.60))
                }
            }
            .foregroundStyle(.white.opacity(0.94))

            if let member = current {
                HStack(alignment: .center, spacing: 14) {
                    ZStack {
                        RoundedRectangle(cornerRadius: 18, style: .continuous)
                            .fill(Color.white.opacity(0.055))
                        if let url = member.imageURL, !url.isEmpty {
                            RemoteImageFit(url: url, mode: .fill, showPlaceholder: false)
                                .padding(0)
                        } else {
                            Image(systemName: "person.crop.rectangle")
                                .font(.system(size: 42, weight: .medium))
                                .foregroundStyle(.white.opacity(0.38))
                        }
                    }
                    .frame(width: 88, height: 112)
                    .clipShape(RoundedRectangle(cornerRadius: 18, style: .continuous))
                    .overlay(
                        RoundedRectangle(cornerRadius: 18, style: .continuous)
                            .stroke(Color.white.opacity(0.24), lineWidth: 1)
                    )
                    .shadow(color: Color.white.opacity(0.10), radius: 14, y: 0)

                    VStack(alignment: .leading, spacing: 7) {
                        Text(member.name)
                            .font(.system(size: 19, weight: .black, design: .rounded))
                            .foregroundStyle(.white)
                            .lineLimit(2)
                            .minimumScaleFactor(0.66)
                            .fixedSize(horizontal: false, vertical: true)
                        Text((member.role ?? "Featured Cast").ifEmpty("Featured Cast"))
                            .font(.system(size: 14, weight: .bold, design: .rounded))
                            .foregroundStyle(.white.opacity(0.68))
                            .lineLimit(2)
                            .minimumScaleFactor(0.66)
                            .fixedSize(horizontal: false, vertical: true)
                        HStack(spacing: 5) {
                            ForEach(0..<min(members.count, 8), id: \.self) { dot in
                                Circle()
                                    .fill(dot == normalizedSpotlightIndex ? Color.white.opacity(0.92) : Color.white.opacity(0.20))
                                    .frame(width: dot == spotlightIndex % max(members.count, 1) ? 9 : 5, height: 5)
                            }
                        }
                        .padding(.top, 2)
                    }
                    Spacer(minLength: 0)
                }
                .transition(.opacity.combined(with: .scale(scale: 0.98)))
            } else {
                Text("Cast information will appear when available")
                    .font(.system(size: 17, weight: .semibold, design: .rounded))
                    .foregroundStyle(.white.opacity(0.55))
                    .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .center)
            }
        }
        .padding(.horizontal, 18)
        .padding(.vertical, 15)
        .background(
            ZStack {
                RoundedRectangle(cornerRadius: 30, style: .continuous)
                    .fill(Color.black.opacity(0.08))
                RoundedRectangle(cornerRadius: 30, style: .continuous)
                    .fill(
                        LinearGradient(
                            colors: [
                                Color.white.opacity(0.050),
                                Color.clear,
                                Color.black.opacity(0.035)
                            ],
                            startPoint: .topLeading,
                            endPoint: .bottomTrailing
                        )
                    )
            }
        )
        .clipShape(RoundedRectangle(cornerRadius: 30, style: .continuous))
        .overlay(
            RoundedRectangle(cornerRadius: 30, style: .continuous)
                .stroke(LinearGradient(colors: [Color.white.opacity(0.28), Color.white.opacity(0.06), Color.white.opacity(0.16)], startPoint: .topLeading, endPoint: .bottomTrailing), lineWidth: 1)
        )
        .overlay(
            RoundedRectangle(cornerRadius: 24, style: .continuous)
                .stroke(Color.white.opacity(0.055), lineWidth: 1)
                .padding(7)
        )
        .shadow(color: .black.opacity(0.30), radius: 24, y: 12)
        .shadow(color: .white.opacity(0.16), radius: 22, y: 0)
        .onReceive(timer) { _ in
            guard members.count > 1 else { return }
            withAnimation(.easeInOut(duration: 0.35)) { spotlightIndex = (normalizedSpotlightIndex + 1) % members.count }
        }
    }
}

