struct VODTheaterModeStrip: View {
    let item: MediaItem
    let engine: String
    let cacheLabel: String
    let resumeEntry: PlaybackResumeEntry?
    let isPlaying: Bool

    private var headline: String {
        if let resumeEntry, resumeEntry.seconds >= 8 { return "THEATER MODE  •  RESUME READY" }
        return isPlaying ? "THEATER MODE  •  NOW PLAYING" : "THEATER MODE  •  PAUSED"
    }

    private var subline: String {
        var parts: [String] = []
        if !item.year.isEmpty { parts.append(item.year) }
        if let first = item.genres.first, !first.isEmpty { parts.append(first) }
        parts.append(engine)
        if !cacheLabel.isEmpty { parts.append(cacheLabel) }
        return parts.prefix(4).joined(separator: "  •  ")
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 6) {
            Text(headline)
                .font(.system(size: 16, weight: .black, design: .rounded))
                .kerning(1.4)
                .foregroundStyle(LinearGradient(colors: [.orange, .yellow.opacity(0.92)], startPoint: .leading, endPoint: .trailing))
            Text(item.title)
                .font(.system(size: 32, weight: .black, design: .rounded))
                .foregroundStyle(.white.opacity(0.97))
                .lineLimit(1)
                .minimumScaleFactor(0.70)
            Text(subline)
                .font(.system(size: 18, weight: .bold, design: .rounded))
                .foregroundStyle(.white.opacity(0.70))
                .lineLimit(1)
        }
        .padding(.horizontal, 18)
        .padding(.vertical, 13)
        .background(RoundedRectangle(cornerRadius: 18, style: .continuous).fill(Color.black.opacity(0.34)))
        .overlay(RoundedRectangle(cornerRadius: 18, style: .continuous).stroke(Color.orange.opacity(0.18), lineWidth: 1))
        .shadow(color: .orange.opacity(0.16), radius: 22, y: 6)
    }
}

struct VODTheaterCharacterSpotlightPanel: View {
    let item: MediaItem
    let interactionToken: TimeInterval
    @State private var failedCastMemberIDs: Set<String> = []

    private var isLivePlaybackItem: Bool {
        item.type.lowercased() == "live"
    }

    private var isLikelySportsProgram: Bool {
        let haystack = ([item.title, item.description] + item.genres).joined(separator: " ").lowercased()
        return ["nfl", "nba", "mlb", "nhl", "soccer", "football", "basketball", "baseball", "hockey", "ufc", "boxing", "tennis", "golf", "vs", " at "].contains { haystack.contains($0) }
    }


    private var liveSmartProgramLine: String {
        let desc = item.description.trimmingCharacters(in: .whitespacesAndNewlines)
        if !desc.isEmpty && !desc.lowercased().contains("tvmaze") && !desc.lowercased().contains("smart program details load") {
            return desc
        }
        let fields = ([item.year, item.rating] + item.genres).map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }.filter { !$0.isEmpty }
        if !fields.isEmpty { return fields.prefix(4).joined(separator: " • ") }
        return isLikelySportsProgram ? "Waiting for verified sports matchup metadata from EPG/public feeds." : "No verified EPG details were matched for this channel yet."
    }

    private var liveSmartProgramBadge: String {
        let desc = item.description.trimmingCharacters(in: .whitespacesAndNewlines)
        if !desc.isEmpty && !desc.lowercased().contains("tvmaze") { return "EPG metadata attached" }
        return isLikelySportsProgram ? "Waiting for verified sports feed" : "Waiting for verified EPG"
    }

    private var members: [CastMember] {
        Array(item.castMembers.filter { member in
            let raw = member.imageURL?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
            guard !member.name.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
                  !failedCastMemberIDs.contains(member.id),
                  let url = URL(string: raw),
                  let scheme = url.scheme?.lowercased(),
                  scheme == "http" || scheme == "https" else { return false }
            let lower = raw.lowercased()
            return !["placeholder", "silhouette", "no-image", "no_image", "noimage", "default-avatar", "default_profile"].contains(where: lower.contains)
        }.prefix(30))
    }

    private var glassWidth: CGFloat {
        if isLivePlaybackItem { return 410 }
        if members.isEmpty { return 340 }
        // v1070: compact featured-cast panel while retaining complete actor and character names.
        return 430
    }

    @ViewBuilder
    var body: some View {
        if isLivePlaybackItem || !members.isEmpty {
            VStack(alignment: .leading, spacing: 12) {
            HStack(spacing: 8) {
                Image(systemName: isLivePlaybackItem ? (isLikelySportsProgram ? "sportscourt.fill" : "sparkles.tv.fill") : "person.3.fill")
                    .font(.system(size: 15, weight: .black))
                    .foregroundStyle(Color.orange.opacity(0.95))
                Text(isLivePlaybackItem ? (isLikelySportsProgram ? "LIVE MATCH" : "PROGRAM INFO") : "FEATURED CAST")
                    .font(.system(size: 12, weight: .black, design: .rounded))
                    .kerning(1.1)
                    .foregroundStyle(.white.opacity(0.90))
            }
            if isLivePlaybackItem {
                VStack(alignment: .leading, spacing: 6) {
                    Text(liveSmartProgramLine)
                        .font(.system(size: 16, weight: .semibold, design: .rounded))
                        .foregroundStyle(.white.opacity(0.62))
                        .lineLimit(3)
                    Text(liveSmartProgramBadge)
                        .font(.system(size: 12, weight: .black, design: .rounded))
                        .kerning(0.8)
                        .foregroundStyle(.orange.opacity(0.90))
                }
            } else if members.isEmpty {
                Text("Cast will appear when metadata finishes loading.")
                    .font(.system(size: 16, weight: .semibold, design: .rounded))
                    .foregroundStyle(.white.opacity(0.58))
                    .lineLimit(3)
            } else {
                VODCharacterSpotlight(
                    members: members,
                    interactionToken: interactionToken,
                    onImageUnavailable: { memberID in failedCastMemberIDs.insert(memberID) }
                )
            }
        }
        .padding(.horizontal, 13)
        .padding(.vertical, 11)
        .frame(width: glassWidth, alignment: .leading)
        .scaleEffect(1.0, anchor: .topLeading)
        .background(
            ZStack {
                RoundedRectangle(cornerRadius: 24, style: .continuous)
                    .fill(Color.black.opacity(0.34))
                LinearGradient(
                    colors: [Color.white.opacity(0.055), Color.clear, Color.black.opacity(0.12)],
                    startPoint: .topLeading,
                    endPoint: .bottomTrailing
                )
                .clipShape(RoundedRectangle(cornerRadius: 24, style: .continuous))
            }
        )
        .overlay(RoundedRectangle(cornerRadius: 24, style: .continuous).stroke(Color.white.opacity(0.12), lineWidth: 1))
        .shadow(color: .black.opacity(0.34), radius: 20, y: 9)
        }
    }
}


struct VODCharacterSpotlight: View {
    let members: [CastMember]
    let interactionToken: TimeInterval
    let onImageUnavailable: (String) -> Void
    @State private var spotlightIndex: Int = 0
    @State private var lastInteractionAt: Date = Date.distantPast
    private let rotationTimer = Timer.publish(every: 8, on: .main, in: .common).autoconnect()

    private var safeMembers: [CastMember] { members }
    private var spotlight: CastMember? {
        guard !safeMembers.isEmpty else { return nil }
        return safeMembers[min(spotlightIndex, safeMembers.count - 1)]
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 12) {
            if let spotlight {
                HStack(alignment: .center, spacing: 14) {
                    V1097VerifiedCastProfileImage(
                        memberID: spotlight.id,
                        rawURL: spotlight.imageURL,
                        onUnavailable: onImageUnavailable
                    )
                        .id(spotlight.id)
                        .transition(.opacity)
                        .padding(5)
                        .frame(width: 68, height: 102)
                        .background(
                            RoundedRectangle(cornerRadius: 20, style: .continuous)
                                .fill(LinearGradient(
                                    colors: [Color.white.opacity(0.10), Color.black.opacity(0.24)],
                                    startPoint: .topLeading,
                                    endPoint: .bottomTrailing
                                ))
                        )
                        .clipShape(RoundedRectangle(cornerRadius: 20, style: .continuous))
                        .overlay(RoundedRectangle(cornerRadius: 20, style: .continuous).stroke(Color.orange.opacity(0.35), lineWidth: 1))
                        .shadow(color: .orange.opacity(0.14), radius: 16, y: 7)
                        .animation(.easeInOut(duration: 0.40), value: spotlightIndex)

                    VStack(alignment: .leading, spacing: 6) {
                        HStack(spacing: 6) {
                            Image(systemName: "sparkles")
                                .font(.system(size: 11, weight: .black))
                            Text("CHARACTER SPOTLIGHT")
                                .font(.system(size: 10, weight: .black, design: .rounded))
                                .kerning(1.1)
                        }
                        .foregroundStyle(.orange.opacity(0.96))

                        Text((spotlight.role ?? "Featured Cast").ifEmpty("Featured Cast"))
                            .font(.system(size: 18, weight: .black, design: .rounded))
                            .foregroundStyle(.white.opacity(0.96))
                            .lineLimit(2)
                            .minimumScaleFactor(0.68)
                            .fixedSize(horizontal: false, vertical: true)

                        Text(spotlight.name)
                            .font(.system(size: 14, weight: .bold, design: .rounded))
                            .foregroundStyle(.white.opacity(0.70))
                            .lineLimit(2)
                            .minimumScaleFactor(0.68)
                            .fixedSize(horizontal: false, vertical: true)
                    }
                    .frame(maxWidth: 280, alignment: .leading)
                }

                ScrollViewReader { proxy in
                    ScrollView(.horizontal, showsIndicators: false) {
                        LazyHStack(spacing: 8) {
                            ForEach(Array(safeMembers.enumerated()), id: \.element.id) { index, member in
                                VStack(spacing: 5) {
                                    V1097VerifiedCastProfileImage(
                                        memberID: member.id,
                                        rawURL: member.imageURL,
                                        onUnavailable: onImageUnavailable
                                    )
                                        .frame(width: 46, height: 62)
                                        .padding(3)
                                        .background(RoundedRectangle(cornerRadius: 14, style: .continuous).fill(Color.white.opacity(index == spotlightIndex ? 0.13 : 0.06)))
                                        .clipShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
                                        .overlay(RoundedRectangle(cornerRadius: 14, style: .continuous).stroke(index == spotlightIndex ? Color.orange.opacity(0.70) : Color.white.opacity(0.12), lineWidth: 1))
                                    Text(member.name.components(separatedBy: " ").first ?? member.name)
                                        .font(.system(size: 9, weight: .bold, design: .rounded))
                                        .foregroundStyle(.white.opacity(index == spotlightIndex ? 0.88 : 0.54))
                                        .lineLimit(1)
                                        .frame(width: 54)
                                }
                                .id(index)
                            }
                        }
                        .padding(.vertical, 2)
                    }
                    .frame(height: 84)
                    .onChange(of: spotlightIndex) { _, next in
                        withAnimation(.easeOut(duration: 0.25)) {
                            proxy.scrollTo(next, anchor: .center)
                        }
                    }
                }
            }
        }
        .frame(minHeight: 196, alignment: .leading)
        .signalMoveCommand { _ in
            lastInteractionAt = Date()
        }
        .onTapGesture { lastInteractionAt = Date() }
        .onReceive(rotationTimer) { _ in
            guard safeMembers.count > 1 else { return }
            guard Date().timeIntervalSince(lastInteractionAt) >= 8 else { return }
            withAnimation(.easeInOut(duration: 0.45)) {
                spotlightIndex = (spotlightIndex + 1) % safeMembers.count
            }
        }
        .onChange(of: members) { _, _ in spotlightIndex = 0 }
    }
}

