struct VideoSurface: UIViewRepresentable {
    let player: AVPlayer?
    let videoGravity: AVLayerVideoGravity

    final class PlayerLayerView: UIView {
        override static var layerClass: AnyClass { AVPlayerLayer.self }
        var playerLayer: AVPlayerLayer { layer as! AVPlayerLayer }
    }

    func makeUIView(context: Context) -> PlayerLayerView {
        let view = PlayerLayerView()
        view.backgroundColor = .black
        view.isUserInteractionEnabled = false
        view.playerLayer.videoGravity = videoGravity
        view.playerLayer.player = player
        return view
    }

    func updateUIView(_ view: PlayerLayerView, context: Context) {
        view.playerLayer.player = player
        view.playerLayer.videoGravity = videoGravity
    }
}

struct DebridPlayerPanel<Content: View>: View {
    let title: String
    let detail: String
    var focusedOption: VODPlayerScreen.PlayerPanelOption? = nil
    @ViewBuilder let content: () -> Content

    var body: some View {
        VStack(alignment: .leading, spacing: 14) {
            Text(title)
                .font(.system(size: 28, weight: .black, design: .rounded))
            ScrollViewReader { proxy in
                ScrollView(.vertical, showsIndicators: false) {
                    VStack(alignment: .leading, spacing: 10) {
                        content()
                    }
                    .padding(.vertical, 4)
                }
                .frame(maxHeight: 360)
                .onAppear {
                    if let focusedOption {
                        DispatchQueue.main.asyncAfter(deadline: .now() + 0.05) {
                            withAnimation(.easeOut(duration: 0.12)) {
                                proxy.scrollTo(focusedOption, anchor: .center)
                            }
                        }
                    }
                }
                // vBRDC103: panel options are real focusable controls. Keep the one
                // initial restore scroll above, then let tvOS own interactive focus scrolling
                // instead of issuing another proxy animation for every option change.
            }
        }
        .foregroundStyle(.white)
        .padding(22)
        .frame(width: 500, alignment: .leading)
        .background(.ultraThinMaterial.opacity(0.88), in: RoundedRectangle(cornerRadius: 22))
        .overlay(RoundedRectangle(cornerRadius: 22).stroke(Color.white.opacity(0.18), lineWidth: 1))
        .shadow(color: .black.opacity(0.50), radius: 22)
        .signalVisionFocusSection()
    }
}

