struct PlayerProgressBar: View {
    let progress: Double
    var focused: Bool = false
    var previewProgress: Double? = nil
    var bufferedProgress: Double? = nil

    private let focusBlue = Color(red: 0.20, green: 0.55, blue: 0.98)

    var body: some View {
        GeometryReader { proxy in
            let clamped = min(max(progress, 0), 1)
            let preview = previewProgress.map { min(max($0, 0), 1) }
            let buffered = bufferedProgress.map { min(max($0, clamped), 1) }
            let thumbProgress = preview ?? clamped
            let thumbDiameter: CGFloat = focused ? 30 : 18
            let visualThumbDiameter: CGFloat = focused ? 44 : thumbDiameter
            let visualThumbRadius = visualThumbDiameter / 2

            ZStack(alignment: .leading) {
                Capsule()
                    .fill(Color.black.opacity(focused ? 0.70 : 0.52))
                    .frame(height: focused ? 5 : 3)
                Capsule()
                    .fill(Color.white.opacity(focused ? 0.14 : 0.06))
                    .frame(height: focused ? 5 : 3)
                // vBRDC062 buffer ghost: this translucent rail ends at KSPNUVIO's actual
                // playableTime. It grows independently while playback continues, so the
                // viewer can see exactly how much interruption protection is available.
                if let buffered, buffered > clamped + 0.0005 {
                    Capsule()
                        .fill(focusBlue.opacity(focused ? 0.34 : 0.22))
                        .frame(width: proxy.size.width * buffered, height: focused ? 5 : 3)

                    Circle()
                        .fill(Color.white.opacity(focused ? 0.52 : 0.38))
                        .frame(width: focused ? 10 : 8, height: focused ? 10 : 8)
                        .overlay(
                            Circle()
                                .stroke(focusBlue.opacity(focused ? 0.72 : 0.50), lineWidth: 1)
                        )
                        .shadow(color: focusBlue.opacity(focused ? 0.45 : 0.24), radius: focused ? 6 : 3)
                        .offset(x: max(0, min(proxy.size.width - (focused ? 10 : 8), proxy.size.width * buffered - (focused ? 5 : 4))))
                        .accessibilityHidden(true)
                }

                // Keep the original blue played-progress treatment, but make the rail
                // slightly brighter and thicker while the timeline owns focus.
                Capsule()
                    .fill(focusBlue.opacity(focused ? 1.0 : 0.94))
                    .frame(width: proxy.size.width * clamped, height: focused ? 5 : 3)

                if let preview {
                    Capsule()
                        .fill(Color.white.opacity(focused ? 0.48 : 0.34))
                        .frame(width: proxy.size.width * preview, height: focused ? 5 : 3)
                }

                ZStack {
                    if focused {
                        Circle()
                            .fill(focusBlue.opacity(0.30))
                            .frame(width: 44, height: 44)
                            .overlay(
                                Circle()
                                    .stroke(Color.white.opacity(0.72), lineWidth: 2)
                            )
                            .shadow(color: focusBlue.opacity(0.88), radius: 18)
                    }

                    Circle()
                        .fill(Color.white)
                        .frame(width: thumbDiameter, height: thumbDiameter)
                        .overlay(
                            Circle()
                                .stroke(focused ? focusBlue.opacity(0.95) : Color.clear, lineWidth: 3)
                        )
                        .shadow(
                            color: focused ? Color.white.opacity(0.88) : Color.white.opacity(0.34),
                            radius: focused ? 14 : 6
                        )
                }
                .offset(x: max(0, min(proxy.size.width - visualThumbDiameter, proxy.size.width * thumbProgress - visualThumbRadius)))
                .accessibilityLabel(Text(focused ? "Scrubber focused. Press left or right to seek immediately." : "Playback position"))
            }
            // vBRDC063: bufferedProgress is live engine telemetry, not decorative motion.
            // Drawing each new endpoint directly avoids a continuous Core Animation transaction
            // competing with matched-cadence video presentation while the VOD overlay is visible.
            .animation(.easeOut(duration: 0.08), value: previewProgress)
            .animation(.spring(response: 0.24, dampingFraction: 0.78), value: focused)
        }
    }
}


