struct PlayerControlButton: View {
    let title: String
    let focus: VODPlayerScreen.PlayerControl
    var focused: FocusState<VODPlayerScreen.PlayerControl?>.Binding
    let action: () -> Void
    @AppStorage("vodOverlayThemePresetV1") private var vodOverlayThemePresetRaw: String = VODOverlayThemePreset.original.rawValue

    private var selected: Bool { focused.wrappedValue == focus }
    private var theme: VODOverlayThemePreset { .original }
    private var primaryTitle: String { title.components(separatedBy: "  ").first ?? title }
    private var secondaryTitle: String {
        let parts = title.components(separatedBy: "  ")
        if parts.count > 1 { return parts.dropFirst().joined(separator: "  ") }
        if focus == .back10 { return "30 sec" }
        if focus == .forward10 { return "60 sec" }
        return ""
    }

    private var iconName: String {
        switch focus {
        case .controlDrawer: return "chevron.up"
        case .quickGuide: return "rectangle.grid.1x2"
        case .resume: return "play.fill"
        case .restart: return "backward.end.fill"
        case .timeline: return "timeline.selection"
        case .back10: return "gobackward.30"
        case .playPause: return title.lowercased().contains("pause") ? "pause.fill" : "play.fill"
        case .forward10: return "goforward.60"
        case .catalogHome: return "house.fill"
        case .catalogMovies: return "film.fill"
        case .catalogShows: return "tv.fill"
        case .ksplayer: return "play.tv.fill"
        case .internalVLC: return "cone.fill"
        case .avplayer: return "airplayvideo"
        case .playerEngine: return "arrow.triangle.2.circlepath"
        case .audio: return "waveform"
        case .findAudio: return "music.note.list"
        case .subtitles: return "captions.bubble.fill"
        case .episodes: return "list.bullet.rectangle"
        case .zoom: return "arrow.up.left.and.arrow.down.right"
        case .settings: return "gearshape.fill"
        case .infuse: return "sparkles.tv.fill"
        case .vlc: return "play.rectangle.fill"
        case .senplayer: return "rectangle.on.rectangle"
        case .externalPlayer: return "rectangle.portrait.and.arrow.right"
        case .close: return "xmark"
        }
    }

    private var labelDesign: Font.Design {
        switch theme {
        case .cinema, .noir, .prestige: return .serif
        case .pro, .studio: return .rounded
        default: return .rounded
        }
    }

    @ViewBuilder
    var body: some View {
        if theme == .original {
            originalBody
        } else {
            themedBody
        }
    }

    private var originalBody: some View {
        // Exact v1156 production control geometry for the Original theme.
        VStack(spacing: 7) {
            ZStack {
                Circle()
                    .fill(
                        LinearGradient(
                            colors: selected
                                ? [Color.white.opacity(0.22), Color.white.opacity(0.09), Color.black.opacity(0.86)]
                                : [Color.white.opacity(0.10), Color.white.opacity(0.035), Color.black.opacity(0.72)],
                            startPoint: .topLeading,
                            endPoint: .bottomTrailing
                        )
                    )
                Circle()
                    .stroke(selected ? Color.white.opacity(0.96) : Color.white.opacity(0.20), lineWidth: selected ? 2.2 : 1)
                if selected {
                    Circle()
                        .stroke(Color.white.opacity(0.22), lineWidth: 1)
                        .padding(4)
                }
                Image(systemName: iconName)
                    .font(.system(size: 24, weight: .bold))
                    .symbolRenderingMode(.monochrome)
                    .foregroundStyle(.white.opacity(selected ? 1.0 : 0.90))
            }
            .frame(width: 62, height: 62)
            .scaleEffect(selected ? 1.07 : 1.0)
            .shadow(color: selected ? Color.white.opacity(0.34) : .clear, radius: selected ? 18 : 0)
            .shadow(color: .black.opacity(0.48), radius: 9, y: 5)

            VStack(spacing: 1) {
                Text(primaryTitle)
                    .font(.system(size: 13, weight: .bold, design: .rounded))
                    .foregroundStyle(.white.opacity(0.96))
                    .lineLimit(1)
                    .minimumScaleFactor(0.72)
                if !secondaryTitle.isEmpty {
                    Text(secondaryTitle)
                        .font(.system(size: 10, weight: .medium, design: .rounded))
                        .foregroundStyle(.white.opacity(0.52))
                        .lineLimit(1)
                        .minimumScaleFactor(0.68)
                }
            }
            .frame(height: 29, alignment: .top)
        }
        .frame(width: 102, height: 104, alignment: .top)
        .contentShape(Rectangle())
        .focusable(true)
        .focused(focused, equals: focus)
        .onTapGesture(perform: action)
        .onHover { if $0 { focused.wrappedValue = focus } }
        .hoverEffect(.highlight)
        .accessibilityAddTraits(.isButton)
        .accessibilityLabel(title)
    }

    private var themedBody: some View {
        VStack(spacing: theme == .minimal ? 3 : 4) {
            controlArtwork
                .frame(width: theme == .mediaCenter ? 62 : 58, height: theme == .mediaCenter ? 50 : 58)
                .scaleEffect(selected ? (theme == .minimal ? 1.03 : 1.06) : 1.0)
                .shadow(color: selected ? theme.accent.opacity(0.18) : .clear, radius: selected ? 12 : 0)
                .shadow(color: .black.opacity(theme == .minimal ? 0.12 : 0.34), radius: 6, y: 3)

            VStack(spacing: 0) {
                Text(primaryTitle)
                    .font(.system(size: theme == .mediaCenter ? 10 : 11, weight: theme == .minimal ? .semibold : .bold, design: labelDesign))
                    .foregroundStyle(.white.opacity(theme == .minimal ? 0.80 : 0.94))
                    .lineLimit(1)
                    .minimumScaleFactor(0.68)
                if !secondaryTitle.isEmpty {
                    Text(secondaryTitle)
                        .font(.system(size: 9, weight: .medium, design: labelDesign))
                        .foregroundStyle(.white.opacity(theme == .minimal ? 0.36 : 0.48))
                        .lineLimit(1)
                        .minimumScaleFactor(0.64)
                }
            }
            .frame(height: 23, alignment: .top)
        }
        .frame(width: theme == .mediaCenter ? 96 : 90, height: 86, alignment: .top)
        .contentShape(Rectangle())
        .focusable(true)
        .focused(focused, equals: focus)
        .onTapGesture(perform: action)
        .onHover { if $0 { focused.wrappedValue = focus } }
        .hoverEffect(.highlight)
        .accessibilityAddTraits(.isButton)
        .accessibilityLabel(title)
    }

    @ViewBuilder
    private var controlArtwork: some View {
        switch theme {
        case .original:
            ZStack {
                Circle()
                    .fill(
                        LinearGradient(
                            colors: selected
                                ? [Color.white.opacity(0.22), Color.white.opacity(0.09), Color.black.opacity(0.86)]
                                : [Color.white.opacity(0.10), Color.white.opacity(0.035), Color.black.opacity(0.72)],
                            startPoint: .topLeading,
                            endPoint: .bottomTrailing
                        )
                    )
                Circle()
                    .stroke(selected ? Color.white.opacity(0.96) : Color.white.opacity(0.20), lineWidth: selected ? 2.2 : 1)
                if selected {
                    Circle()
                        .stroke(Color.white.opacity(0.22), lineWidth: 1)
                        .padding(4)
                }
                Image(systemName: iconName)
                    .font(.system(size: 24, weight: .bold))
                    .symbolRenderingMode(.monochrome)
                    .foregroundStyle(.white.opacity(selected ? 1.0 : 0.90))
            }
            .frame(width: 68, height: 68)
            .shadow(color: selected ? Color.white.opacity(0.34) : .clear, radius: selected ? 18 : 0)

        case .pro:
            ZStack {
                RoundedRectangle(cornerRadius: 14, style: .continuous)
                    .fill(LinearGradient(colors: [Color.white.opacity(selected ? 0.14 : 0.055), Color.black.opacity(0.34)], startPoint: .topLeading, endPoint: .bottomTrailing))
                RoundedRectangle(cornerRadius: 14, style: .continuous)
                    .stroke(selected ? theme.accent.opacity(0.96) : Color.white.opacity(0.15), lineWidth: selected ? 2 : 1)
                Image(systemName: iconName)
                    .font(.system(size: 21, weight: .bold))
                    .foregroundStyle(selected ? theme.accent : Color.white.opacity(0.86))
            }

        case .cinema:
            ZStack {
                Circle().fill(Color.black.opacity(0.26))
                Circle().stroke(selected ? theme.accent.opacity(0.92) : Color.white.opacity(0.18), lineWidth: selected ? 1.8 : 1)
                Image(systemName: iconName)
                    .font(.system(size: 21, weight: .semibold))
                    .foregroundStyle(selected ? theme.accent : Color.white.opacity(0.88))
            }

        case .mediaCenter:
            ZStack {
                RoundedRectangle(cornerRadius: 7, style: .continuous)
                    .fill(selected ? theme.accent.opacity(0.72) : Color.black.opacity(0.28))
                RoundedRectangle(cornerRadius: 8, style: .continuous)
                    .stroke(selected ? Color.white.opacity(0.80) : Color.white.opacity(0.12), lineWidth: 1)
                HStack(spacing: 7) {
                    Image(systemName: iconName)
                        .font(.system(size: 19, weight: .bold))
                    if selected {
                        Rectangle().fill(Color.white.opacity(0.72)).frame(width: 1, height: 28)
                    }
                }
                .foregroundStyle(selected ? Color.black.opacity(0.78) : Color.white.opacity(0.88))
            }
            .frame(width: 62, height: 46)

        case .studio:
            ZStack {
                RoundedRectangle(cornerRadius: 12, style: .continuous)
                    .fill(LinearGradient(colors: [theme.accent.opacity(selected ? 0.16 : 0.055), Color.black.opacity(0.34)], startPoint: .top, endPoint: .bottom))
                RoundedRectangle(cornerRadius: 12, style: .continuous)
                    .stroke(selected ? theme.accent.opacity(0.88) : Color.white.opacity(0.13), lineWidth: selected ? 1.7 : 1)
                VStack(spacing: 4) {
                    Image(systemName: iconName)
                        .font(.system(size: 20, weight: .bold))
                    Capsule().fill(selected ? theme.accent : Color.white.opacity(0.18)).frame(width: 24, height: 2)
                }
                .foregroundStyle(.white.opacity(0.92))
            }

        case .minimal:
            VStack(spacing: 8) {
                Image(systemName: iconName)
                    .font(.system(size: 23, weight: selected ? .bold : .medium))
                    .foregroundStyle(.white.opacity(selected ? 1.0 : 0.72))
                Capsule()
                    .fill(selected ? Color.white.opacity(0.94) : Color.white.opacity(0.12))
                    .frame(width: selected ? 36 : 18, height: 2)
            }

        case .noir:
            ZStack {
                RoundedRectangle(cornerRadius: 8, style: .continuous)
                    .fill(selected ? Color.white.opacity(0.90) : Color.black.opacity(0.26))
                RoundedRectangle(cornerRadius: 8, style: .continuous)
                    .stroke(Color.white.opacity(selected ? 0.88 : 0.28), lineWidth: 1)
                Image(systemName: iconName)
                    .font(.system(size: 20, weight: .semibold))
                    .foregroundStyle(selected ? Color.black.opacity(0.90) : Color.white.opacity(0.88))
            }

        case .prestige:
            ZStack {
                RoundedRectangle(cornerRadius: 18, style: .continuous).fill(LinearGradient(colors: [Color(red: 0.12, green: 0.075, blue: 0.025).opacity(0.58), Color.black.opacity(0.34)], startPoint: .topLeading, endPoint: .bottomTrailing))
                RoundedRectangle(cornerRadius: 18, style: .continuous).stroke(selected ? theme.accent.opacity(0.88) : theme.accent.opacity(0.28), lineWidth: selected ? 1.7 : 1)
                if selected { RoundedRectangle(cornerRadius: 14, style: .continuous).stroke(Color.white.opacity(0.13), lineWidth: 1).padding(4) }
                Image(systemName: iconName)
                    .font(.system(size: 20, weight: .bold))
                    .foregroundStyle(selected ? theme.accent : Color.white.opacity(0.88))
            }
        }
    }
}


private extension Date {
    var iso8601String: String { ISO8601DateFormatter().string(from: self) }
    var friendlyBackupDate: String {
        let formatter = DateFormatter()
        formatter.dateStyle = .medium
        formatter.timeStyle = .short
        return formatter.string(from: self)
    }
}

private struct GuideStartupPreferenceCard: View {
    let isOn: Bool
    let action: () -> Void
    @FocusState private var isFocused: Bool

    var body: some View {
        Button(action: action) {
            HStack(spacing: 16) {
                RoundedRectangle(cornerRadius: 16, style: .continuous)
                    .fill(isOn ? Color.cyan.opacity(0.88) : Color.white.opacity(0.12))
                    .frame(width: 86, height: 44)
                    .overlay(alignment: isOn ? .trailing : .leading) {
                        Circle().fill(Color.white).frame(width: 34, height: 34).padding(5)
                    }
                VStack(alignment: .leading, spacing: 4) {
                    Text("Launch App in Guide: \(isOn ? "On" : "Off")")
                        .font(.system(size: 19, weight: .black, design: .rounded))
                        .foregroundStyle(.white)
                    Text("On a fresh launch, open the existing full Live TV guide instead of the channel grid.")
                        .font(.system(size: 14, weight: .semibold, design: .rounded))
                        .foregroundStyle(.white.opacity(0.62))
                        .lineLimit(2)
                }
                Spacer()
            }
            .padding(14)
            .frame(width: 560)
            .background(RoundedRectangle(cornerRadius: 14, style: .continuous).fill(isFocused ? Color.cyan.opacity(0.12) : Color.white.opacity(0.07)))
            .overlay(RoundedRectangle(cornerRadius: 14, style: .continuous).stroke(isFocused ? Color.cyan.opacity(0.95) : Color.white.opacity(0.12), lineWidth: isFocused ? 3 : 1))
        }
        .buttonStyle(.plain)
        .focused($isFocused)
        .modifier(SettingsRoundedFocusVisual(cornerRadius: 14))
    }
}

private struct GuideStartupConfirmationOverlay: View {
    let dismiss: () -> Void
    @FocusState private var okFocused: Bool

    var body: some View {
        ZStack {
            Color.black.opacity(0.58).ignoresSafeArea()
            VStack(spacing: 20) {
                Image(systemName: "rectangle.grid.1x2.fill")
                    .font(.system(size: 46, weight: .semibold))
                    .foregroundStyle(Color.cyan)
                Text("Guide startup enabled")
                    .font(.system(size: 34, weight: .black, design: .rounded))
                    .foregroundStyle(.white)
                Text("From now on, Debrid Channels will launch with the Live TV guide open. Close and reopen the app for this change to take effect.")
                    .font(.system(size: 19, weight: .semibold, design: .rounded))
                    .foregroundStyle(.white.opacity(0.78))
                    .multilineTextAlignment(.center)
                    .frame(width: 620)
                Button(action: dismiss) {
                    Text("OK")
                        .font(.system(size: 20, weight: .black, design: .rounded))
                        .foregroundStyle(.black)
                        .padding(.horizontal, 46)
                        .padding(.vertical, 14)
                        .background(Capsule().fill(Color.white))
                }
                .buttonStyle(.plain)
                .focused($okFocused)
                .modifier(SettingsRoundedFocusVisual(cornerRadius: 24))
            }
            .padding(.horizontal, 54)
            .padding(.vertical, 42)
            .background(.ultraThinMaterial, in: RoundedRectangle(cornerRadius: 28, style: .continuous))
            .overlay(RoundedRectangle(cornerRadius: 28, style: .continuous).stroke(Color.cyan.opacity(0.45), lineWidth: 1.5))
            .shadow(color: Color.black.opacity(0.72), radius: 34, y: 18)
        }
        .onAppear { DispatchQueue.main.asyncAfter(deadline: .now() + 0.12) { okFocused = true } }
        .signalVisionExitCommand( dismiss)
    }
}

