    var body: some View {
        ZStack {
            SettingsControlCenterBackdrop().equatable().ignoresSafeArea()
            settingsScroll
                .disabled(showGuideStartupConfirmation)
                .allowsHitTesting(!showGuideStartupConfirmation)
            if showGuideStartupConfirmation {
                GuideStartupConfirmationOverlay {
                    showGuideStartupConfirmation = false
                    focused = .liveDvr
                }
                .zIndex(9000)
            }
        }
        .onAppear {
            DebridCredentialBridge.migrateLegacyOverridesIfNeeded()
            _ = TraktSyncManager.shared.restorePersistedConnectionIfNeeded()
            traktStatusText = TraktSyncManager.shared.lastStatus
            if TraktSyncManager.shared.isConnected {
                Task {
                    _ = await TraktSyncManager.shared.refreshConnectedAccountIdentityIfNeeded(
                        force: TraktSyncManager.shared.connectedAccountName.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                    )
                    await MainActor.run { traktStatusText = TraktSyncManager.shared.lastStatus }
                }
            }
            if mediaFlowAPIPassword.isEmpty {
                mediaFlowAPIPassword = MediaFlowCredentialStore.readPassword()
            }
            if febBoxCookieDraft.isEmpty {
                febBoxCookieDraft = BackupStreamingCredentialStore.readFebBoxCookie()
            }
            nuvioRepositories = NuvioPluginPreferences.repositories()
            let normalizedWallpaperPreset = DynamicMainGridWallpaperStyle.normalized(dynamicMainGridWallpaperPreset)
            if normalizedWallpaperPreset != dynamicMainGridWallpaperPreset {
                dynamicMainGridWallpaperPreset = normalizedWallpaperPreset
            }
            // vBRDC332: connection verification is intentionally manual. The previous
            // automatic provider/network fan-out published Settings state while tvOS was
            // resolving focus and scrolling, which could make the vertical panel stall.
            // Cached health remains visible; Verify Connections performs a fresh check.
            if store.onboardingTourActive {
                focused = nil
            } else {
                focused = .category(selectedSettingsCategory ?? .general)
            }
        }
        .onChange(of: store.contentFocusToken) { _ in
            // vBRDC148: Settings is a dedicated surface, so when the global menu yields
            // back to Settings, explicitly restore the selected category card instead of
            // relying on tvOS to infer focus across the overlay boundary.
            guard unityCore.isRuntimeOwner(.settings),
                  !store.onboardingTourActive,
                  !showGuideStartupConfirmation else { return }
            focused = .category(selectedSettingsCategory ?? .general)
        }
        .signalVisionExitCommand {
            if showGuideStartupConfirmation {
                showGuideStartupConfirmation = false
                focused = .liveDvr
            } else if selectedSettingsCategory != nil {
                selectedSettingsCategory = nil
                focused = .category(.general)
            } else {
                store.menuFocusToken += 1
            }
        }
        .fullScreenCover(isPresented: $liveTVThemeConfirmationOpen) {
            SignalLiveTVThemeConfirmationScreen(candidate: $liveTVThemeCandidate, effectCandidate: $liveTVEffectCandidate, sizeCandidate: $liveTVSizeCandidate, typographyCandidate: $liveTVTypographyCandidate, selectedTypography: $signalLiveTVCardTypography, selectedTheme: $signalLiveTVCardTheme, selectedEffect: $signalLiveTVCardEffect, selectedSize: $signalLiveTVCardSize, isPresented: $liveTVThemeConfirmationOpen)
        }
        .onChange(of: liveTVThemeConfirmationOpen) { isOpen in
            if !isOpen { focused = .liveCardThemePreview }
        }
        .fullScreenCover(isPresented: $showAllInOneCatalogCustomizer) {
            AllInOneCatalogCustomizationScreen()
                .environmentObject(store)
        }
        .sheet(item: $selectedNuvioSettingsTarget) { target in
            NuvioPluginSettingsEditor(backendBaseURL: backendBaseURL, target: target)
        }
        .onChange(of: mediaFlowProxyURL) { _ in
            invalidateMediaFlowVerification()
        }
        .onChange(of: mediaFlowPublicIP) { _ in
            invalidateMediaFlowVerification()
        }
        .onChange(of: mediaFlowAPIPassword) { value in
            let previousPassword = MediaFlowCredentialStore.readPassword()
            _ = MediaFlowCredentialStore.savePassword(value)
            if value.trimmingCharacters(in: .whitespacesAndNewlines) != previousPassword.trimmingCharacters(in: .whitespacesAndNewlines) {
                invalidateMediaFlowVerification()
            }
        }
        // v182: Let the tvOS focus engine own Settings DPAD movement. The prior
        // manual routeSettings() handler fought the native ScrollView/TextField focus
        // movement, causing one Siri Remote click to jump two controls.
    }

    // vBRDC349: Settings always uses the wider 1080p canvas geometry shown in the
    // expanded reference layout. This is a Settings-only visual choice: never write
    // appCanvasExpandedV1, which still controls Live TV and the other app surfaces.
