    /// vBRDC303: Settings uses pure native tvOS horizontal focus movement.
    /// Do not programmatically scroll-to-center on every focus change: that repositions the
    /// focus graph during the same Siri Remote gesture and can create a visible double-hop.
    private var categoryCardsRow: some View {
        ScrollView(.horizontal, showsIndicators: false) {
            HStack(spacing: 14) {
                ForEach(SettingsCategory.allCases, id: \.self) { category in
                    let isFocusable = settingsCategoryIsFocusable(category)
                    SettingsCategoryCard(
                        category: category,
                        selected: selectedSettingsCategory == category,
                        focused: focused == .category(category)
                    ) {
                        selectedSettingsCategory = category
                        focused = firstFocus(in: category)
                    }
                    .equatable()
                    .id(category)
                    .focusable(true)
                    .disabled(!isFocusable)
                    .focused($focused, equals: .category(category))
                    .signalMoveCommand { direction in
                        if direction == .down {
                            selectedSettingsCategory = category
                            focused = firstFocus(in: category)
                        }
                    }
                }
            }
            .padding(.horizontal, 8)
            .padding(.vertical, 8)
        }
        .frame(width: 1810, height: 128, alignment: .leading)
        .clipped()
        .onChange(of: focused) { _, nextFocus in
            guard case let .category(category)? = nextFocus else { return }
            if selectedSettingsCategory != category {
                selectedSettingsCategory = category
            }
        }
    }

    private func settingsCategoryIsFocusable(_ category: SettingsCategory) -> Bool {
        guard let focused else { return true }
        if case .category = focused { return true }
        return selectedSettingsCategory == category
    }

    @ViewBuilder
    private var settingsCategoryPanel: some View {
        if let category = selectedSettingsCategory {
            SettingsSectionCard(title: category.rawValue, subtitle: category.subtitle, systemImage: category.icon) {
                ScrollView(.vertical, showsIndicators: true) {
                    categoryContent(category)
                        .padding(.trailing, 12)
                        .padding(.bottom, 48)
                }
                .frame(width: 1710, height: 670, alignment: .topLeading)
            }
            .frame(width: 1770, alignment: .topLeading)
        } else {
            VStack(alignment: .leading, spacing: 12) {
                Text("Select a settings category")
                    .font(.system(size: 32, weight: .black, design: .rounded))
                    .foregroundStyle(.white)
                Text("Move left and right to browse categories. The highlighted category opens automatically; press Down to enter its controls.")
                    .font(.system(size: 19, weight: .semibold, design: .rounded))
                    .foregroundStyle(.white.opacity(0.62))
            }
            .padding(34)
            .frame(width: 1770, height: 260, alignment: .topLeading)
            .background(RoundedRectangle(cornerRadius: 28, style: .continuous).fill(Color.black.opacity(0.26)))
            .overlay(RoundedRectangle(cornerRadius: 28, style: .continuous).stroke(Color.white.opacity(0.10), lineWidth: 1))
        }
    }

