        switch category {
        case .general:
            VStack(alignment: .leading, spacing: 18) {
                resetOnboardingSection
                aboutCard
            }
        case .appearance:
            appearanceSettingsSection
        case .liveTV:
            liveTVSourcesSection
        case .streamingCatalogs:
            VStack(alignment: .leading, spacing: 18) {
                allInOneCatalogToggleSection
                builtInAddonManagerSection
                stremioHeader
                manifestInput
                manifestButtons
                savedManifestList
            }
        case .mediaFlowProxy:
            mediaFlowProxySettingsSection
        case .backupStreaming:
            backupStreamingSettingsSection
        case .catalogHealth:
            catalogHealthSettingsSection
        case .vodPlayer:
            VStack(alignment: .leading, spacing: 18) {
                vodInternalPlayerSection
                traktSyncSettingsSection
                trailerSettingsSection
                externalPlayerDefaultsSection
            }
        case .sourceIntelligence:
            sourceIntelligenceSettingsSection
        case .newEpisodeAlerts:
            followCenterSettingsSection
        case .sports:
            sportsSourcesSettingsSection
        case .backupRestore:
            backendProfileBackupSection
        }
    }

    private func firstFocus(in category: SettingsCategory) -> SettingsFocus {
        switch category {
        case .general: return .restoreStableUIDefaults
        case .appearance: return .popupFontToggle
        case .liveTV: return .liveDvr
        case .streamingCatalogs: return .allInOneCatalogToggle
        case .mediaFlowProxy: return .mediaFlowEnabled
        case .backupStreaming: return .nuvioRepositoryURL
        case .catalogHealth: return .loadAll
        case .vodPlayer: return .vodEngineAether
        case .sourceIntelligence: return .sourceLinks25
        case .newEpisodeAlerts: return .alertScopeMainAndVOD
        case .sports: return .sportsXtreamFull
        case .backupRestore: return .backupCode
        }
    }


    private var mediaFlowEnabledBinding: Binding<Bool> {
        Binding(
            get: { mediaFlowProxyEnabled },
            set: { enabled in
                mediaFlowProxyEnabled = enabled
                _ = MediaFlowCredentialStore.savePassword(mediaFlowAPIPassword)
                MediaFlowConnectionMonitor.shared.markConfigurationChanged()

                if enabled {
                    MediaFlowConnectionMonitor.shared.refresh(
                        reason: "MediaFlow enabled",
                        showBanner: true,
                        allowFreshReuse: false
                    )
                    store.status = "MediaFlow Proxy enabled globally. Debrid Channels will verify the home proxy automatically and fail closed instead of exposing the device IP."
                } else {
                    store.status = "MediaFlow Proxy disabled. Playback uses the normal direct route."
                }
            }
        )
    }

    private var mediaFlowWebBrowserBinding: Binding<Bool> {
        Binding(
            get: { mediaFlowWebBrowserPlayback },
            set: { mediaFlowWebBrowserPlayback = $0 }
        )
    }

