    private func clearMediaFlowCredentials() {
        mediaFlowProxyEnabled = false
        mediaFlowProxyURL = ""
        mediaFlowPublicIP = ""
        mediaFlowLastDetectedIP = ""
        mediaFlowLastStatus = "Not tested"
        mediaFlowLastTestDate = "Never"
        mediaFlowLastVerified = false
        mediaFlowAPIPassword = ""
        _ = MediaFlowCredentialStore.savePassword("")
        MediaFlowConnectionMonitor.shared.markConfigurationChanged()
        store.status = "MediaFlow Proxy credentials cleared."
    }

    private func invalidateMediaFlowVerification() {
        guard !mediaFlowTestBusy else { return }
        mediaFlowLastVerified = false
        mediaFlowLastStatus = "Configuration changed • automatic verification pending"
        MediaFlowConnectionMonitor.shared.markConfigurationChanged()
    }

    private func testMediaFlowConnection() {
        guard !mediaFlowTestBusy else { return }
        _ = MediaFlowCredentialStore.savePassword(mediaFlowAPIPassword)
        mediaFlowTestBusy = true
        mediaFlowLastStatus = "Testing…"
        let proxyURL = mediaFlowProxyURL
        let password = mediaFlowAPIPassword
        let expectedIP = mediaFlowPublicIP
        Task {
            let result = await MediaFlowProxyRouter.testConnection(
                proxyURLString: proxyURL,
                apiPassword: password,
                expectedPublicIP: expectedIP
            )
            await MainActor.run {
                mediaFlowTestBusy = false
                mediaFlowLastDetectedIP = result.detectedIP
                mediaFlowLastStatus = result.status
                mediaFlowLastVerified = result.success
                let formatter = DateFormatter()
                formatter.dateStyle = .medium
                formatter.timeStyle = .short
                mediaFlowLastTestDate = formatter.string(from: Date())
                MediaFlowConnectionMonitor.shared.applyManualTestResult(result)
                store.status = result.success
                    ? "MediaFlow verified • streaming as \(result.detectedIP) • \(result.securitySummary)"
                    : result.status
            }
        }
    }

