    private func nuvioRepositoryCard(_ repository: NuvioPluginRepositoryConfiguration) -> some View {
        VStack(alignment: .leading, spacing: 12) {
            HStack(alignment: .top, spacing: 14) {
                VStack(alignment: .leading, spacing: 4) {
                    Text(repository.name.isEmpty ? "In-S Repository" : repository.name)
                        .font(.system(size: 21, weight: .black, design: .rounded))
                        .foregroundStyle(.white)
                    Text("v\(repository.version.isEmpty ? "?" : repository.version) • \(repository.enabledProviderIDs.count)/\(repository.providers.count) enabled")
                        .font(.system(size: 12, weight: .bold, design: .rounded))
                        .foregroundStyle(.cyan.opacity(0.78))
                    Text(repository.repositoryURL)
                        .font(.system(size: 11, weight: .medium, design: .monospaced))
                        .foregroundStyle(.white.opacity(0.42))
                        .lineLimit(1)
                }
                Spacer()
                Button(nuvioRepositoryBusyURL == repository.repositoryURL ? "Refreshing…" : "Refresh") {
                    refreshNuvioRepository(repository)
                }
                .buttonStyle(.bordered)
                .disabled(nuvioRepositoryBusyURL != nil)
                Button("Remove") {
                    NuvioPluginPreferences.remove(repositoryURL: repository.repositoryURL)
                    reloadNuvioRepositories(message: "Removed \(repository.name).")
                    invalidateStreamsForNuvioChange()
                }
                .buttonStyle(.bordered)
            }

            ForEach(repository.providers) { provider in
                let serverBridgeAdvisory = provider.disabledPlatforms.contains { value in
                    let key = value.lowercased()
                    return key == "ios" || key == "tvos"
                }
                HStack(spacing: 12) {
                    Toggle(isOn: Binding(
                        get: { repository.enabledProviderIDs.contains(provider.id) },
                        set: { enabled in
                            NuvioPluginPreferences.setProviderEnabled(repositoryURL: repository.repositoryURL, providerID: provider.id, enabled: enabled)
                            reloadNuvioRepositories(message: "\(provider.name) \(enabled ? "enabled" : "disabled").")
                            invalidateStreamsForNuvioChange()
                        }
                    )) {
                        VStack(alignment: .leading, spacing: 3) {
                            HStack(spacing: 7) {
                                Text(provider.name)
                                    .font(.system(size: 16, weight: .black, design: .rounded))
                                    .foregroundStyle(.white)
                                if provider.limited {
                                    Text("LIMITED")
                                        .font(.system(size: 9, weight: .black, design: .rounded))
                                        .padding(.horizontal, 6).padding(.vertical, 3)
                                        .background(Capsule().fill(Color.orange.opacity(0.18)))
                                        .foregroundStyle(.orange)
                                }
                                if serverBridgeAdvisory {
                                    Text("SERVER BRIDGE")
                                        .font(.system(size: 9, weight: .black, design: .rounded))
                                        .padding(.horizontal, 6).padding(.vertical, 3)
                                        .background(Capsule().fill(Color.cyan.opacity(0.16)))
                                        .foregroundStyle(.cyan.opacity(0.9))
                                }
                            }
                            Text(provider.description.isEmpty ? provider.formats.joined(separator: " • ") : provider.description)
                                .font(.system(size: 11.5, weight: .semibold, design: .rounded))
                                .foregroundStyle(.white.opacity(0.50))
                                .lineLimit(2)
                        }
                    }
                    .toggleStyle(.automatic)

                    if provider.hasSettings {
                        Button("Settings") {
                            selectedNuvioSettingsTarget = NuvioPluginSettingsTarget(
                                repositoryURL: repository.repositoryURL,
                                providerID: provider.id,
                                providerName: provider.name
                            )
                        }
                        .buttonStyle(.bordered)
                    }
                }
                .padding(.vertical, 6)
            }
        }
        .padding(14)
        .background(RoundedRectangle(cornerRadius: 16, style: .continuous).fill(Color.black.opacity(0.22)))
        .overlay(RoundedRectangle(cornerRadius: 16, style: .continuous).stroke(Color.white.opacity(0.08), lineWidth: 1))
    }

    private func addNuvioRepository() {
        let clean = nuvioRepositoryURLDraft.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !clean.isEmpty, nuvioRepositoryBusyURL == nil else { return }
        nuvioRepositoryBusyURL = "__add__"
        nuvioPluginStatusMessage = "Inspecting repository…"
        let baseURL = backendBaseURL
        Task {
            do {
                let snapshot = try await NuvioPluginClient.inspectRepository(backendBaseURL: baseURL, repositoryURL: clean, force: true)
                await MainActor.run {
                    NuvioPluginPreferences.upsert(snapshot: snapshot)
                    nuvioRepositoryBusyURL = nil
                    reloadNuvioRepositories(message: "Added \(snapshot.name) • \(snapshot.providers.count) providers.")
                    invalidateStreamsForNuvioChange()
                }
            } catch {
                await MainActor.run {
                    nuvioRepositoryBusyURL = nil
                    nuvioPluginStatusMessage = "Repository failed: \(error.localizedDescription)"
                }
            }
        }
    }

    private func refreshNuvioRepository(_ repository: NuvioPluginRepositoryConfiguration) {
        guard nuvioRepositoryBusyURL == nil else { return }
        nuvioRepositoryBusyURL = repository.repositoryURL
        nuvioPluginStatusMessage = "Refreshing \(repository.name)…"
        let baseURL = backendBaseURL
        Task {
            do {
                let snapshot = try await NuvioPluginClient.inspectRepository(backendBaseURL: baseURL, repositoryURL: repository.repositoryURL, force: true)
                await MainActor.run {
                    NuvioPluginPreferences.upsert(snapshot: snapshot)
                    nuvioRepositoryBusyURL = nil
                    reloadNuvioRepositories(message: "Refreshed \(snapshot.name).")
                    invalidateStreamsForNuvioChange()
                }
            } catch {
                await MainActor.run {
                    nuvioRepositoryBusyURL = nil
                    nuvioPluginStatusMessage = "Refresh failed: \(error.localizedDescription)"
                }
            }
        }
    }

    private func reloadNuvioRepositories(message: String? = nil) {
        nuvioRepositories = NuvioPluginPreferences.repositories()
        if let message { nuvioPluginStatusMessage = message }
    }

    private func invalidateStreamsForNuvioChange() {
