    private var backupStreamingRemainingDisplay: String {
        guard backupStreamingRemainingMB >= 0 else { return optionalFebBoxEnabled ? "Verify FebBox cookie to check" : "Off" }
        if backupStreamingRemainingMB >= 1024 { return String(format: "%.1f GB", backupStreamingRemainingMB / 1024.0) }
        return String(format: "%.0f MB", backupStreamingRemainingMB)
    }

    private func verifyFebBoxBackupCookie() {
        guard !backupStreamingVerifyBusy else { return }
        let clean = BackupStreamingCredentialStore.normalizedCookieValue(febBoxCookieDraft)
        guard !clean.isEmpty else {
            backupStreamingLastStatus = "Enter your FebBox ui cookie first"
            backupStreamingRemainingMB = -1
            store.status = backupStreamingLastStatus
            return
        }
        guard BackupStreamingCredentialStore.saveFebBoxCookie(clean) else {
            backupStreamingLastStatus = "Could not save FebBox cookie to Keychain"
            backupStreamingRemainingMB = -1
            store.status = backupStreamingLastStatus
            return
        }
        febBoxCookieDraft = clean
        backupStreamingVerifyBusy = true
        backupStreamingLastStatus = "Verifying FebBox…"
        let baseURL = backendBaseURL
        Task {
            do {
                let result = try await BackupStreamingClient.verifyFebBox(backendBaseURL: baseURL, cookie: clean)
                await MainActor.run {
                    backupStreamingVerifyBusy = false
                    backupStreamingLastStatus = result.message
                    backupStreamingRemainingMB = result.remainingMB ?? -1
                    if result.valid { optionalFebBoxEnabled = true }
                    store.status = result.valid ? "FebBox verified • \(result.remainingDisplay) remaining." : result.message
                }
            } catch {
                await MainActor.run {
                    backupStreamingVerifyBusy = false
                    backupStreamingLastStatus = "FebBox verification service unavailable"
                    backupStreamingRemainingMB = -1
                    store.status = error.localizedDescription
                }
            }
        }
    }

    private func clearFebBoxBackupCookie() {
        _ = BackupStreamingCredentialStore.saveFebBoxCookie("")
        febBoxCookieDraft = ""
        backupStreamingRemainingMB = -1
        optionalFebBoxEnabled = false
        backupStreamingLastStatus = "FebBox cookie cleared • FebBox off"
        store.status = "FebBox cookie removed from this device. In-S and other providers are unchanged."
    }

