    @ViewBuilder
    private func managedTorrentioAccountToggle(service: DebridServiceID, enabled: Binding<Bool>, focus: SettingsFocus) -> some View {
        SettingsButton(
            title: enabled.wrappedValue ? "Remove Torrentio • \(service.displayName)" : "Add Torrentio • \(service.displayName)",
            focus: focus,
            focused: $focused
        ) {
            let removing = enabled.wrappedValue
            enabled.wrappedValue = !removing
            DebridCredentialBridge.setTorrentioEnabled(!removing, for: service)
            let serviceKey = SourceIntelligenceManager.providerCanonical(service.displayName)
            if removing {
                let selectedKey = SourceIntelligenceManager.providerCanonical(store.selectedSourceProvider)
                if selectedKey.contains("torrentio") && selectedKey.contains(serviceKey) {
                    store.selectedSourceProvider = "All Providers"
                }
                store.sourceProviderStatuses.removeAll { status in
                    let key = SourceIntelligenceManager.providerCanonical(status.provider)
                    return key.contains("torrentio") && key.contains(serviceKey)
                }
                store.streamLinks.removeAll { link in
                    let providerKey = SourceIntelligenceManager.providerCanonical(link.providerDisplay + " " + link.source)
                    let bridgedService = SourceIntelligenceManager.providerCanonical(link.providerService ?? "")
                    return providerKey.contains("torrentio") && (bridgedService == serviceKey || providerKey.contains(serviceKey))
                }
                store.status = "Torrentio • \(service.displayName) removed. The \(service.displayName) credential was kept."
                if service == .torBox {
                    store.status += " Native TorBox Usenet remains independent."
                }
            } else {
                if DebridCredentialBridge.credential(for: service) == nil {
                    store.status = "Torrentio • \(service.displayName) enabled. Add the \(service.displayName) credential to activate it."
                } else {
                    store.status = "Torrentio • \(service.displayName) enabled independently."
                }
            }
        }
    }

    @ViewBuilder
    private func managedConnectionStatusRow(_ health: ConnectedServiceHealth) -> some View {
        let tint: Color = {
            switch health.state {
            case .connected: return .green
            case .partial: return .orange
            case .failed: return .red
            case .notConfigured: return .white
            }
        }()
        VStack(alignment: .leading, spacing: 5) {
            HStack(spacing: 8) {
                Circle().fill(tint.opacity(0.92)).frame(width: 8, height: 8)
                Text(health.name)
                    .font(.system(size: 15, weight: .black, design: .rounded))
                    .foregroundStyle(.white)
                Text(health.headline)
                    .font(.system(size: 12, weight: .bold, design: .rounded))
                    .foregroundStyle(tint.opacity(0.92))
            }
            ForEach(Array(health.details.prefix(6)), id: \.self) { detail in
                Text(detail)
                    .font(.system(size: 11, weight: .semibold, design: .rounded))
                    .foregroundStyle(.white.opacity(0.55))
                    .lineLimit(2)
            }
        }
        .padding(10)
        .frame(width: settingsColumnWidth, alignment: .leading)
        .background(RoundedRectangle(cornerRadius: 12).fill(tint.opacity(0.06)))
        .overlay(RoundedRectangle(cornerRadius: 12).stroke(tint.opacity(0.18), lineWidth: 1))
    }

    private func verifyManagedConnections(userInitiated: Bool) {
        guard !connectedServicesHealthBusy else { return }
        connectedServicesHealthBusy = true
        if userInitiated { store.status = "Checking connected services and saved addons…" }
        Task {
            let health = await ConnectedServicesHealthClient.verifyAll()
            await MainActor.run {
                connectedServicesHealth = health
                connectedServicesHealthBusy = false
                let connected = health.filter { $0.state == .connected }.map(\.name)
                let partial = health.filter { $0.state == .partial }.map(\.name)
                if userInitiated {
                    if !connected.isEmpty {
                        store.status = "Connected: \(connected.joined(separator: ", "))\(partial.isEmpty ? "" : " • Partial: \(partial.joined(separator: ", "))")"
                    } else if !partial.isEmpty {
                        store.status = "Partially connected: \(partial.joined(separator: ", "))"
                    } else {
                        store.status = "No configured service passed verification. See Connection Status for details."
                    }
                }
            }
        }
    }

