    private func beginTraktDeviceLinkFromSettings() {
        guard !traktBusy else { return }
        guard TraktSyncManager.shared.isConfigured else {
            traktStatusText = "Debrid Channels Trakt app configuration is unavailable."
            return
        }
        traktLinkTask?.cancel()
        traktBusy = true
        traktStatusText = "Requesting Trakt device code…"
        traktLinkTask = Task {
            do {
                let code = try await TraktSyncManager.shared.beginDeviceLink()
                await MainActor.run {
                    traktDeviceLinkCode = code
                    traktStatusText = "Waiting for approval at \(code.verificationURL)"
                }
                let account = try await TraktSyncManager.shared.pollDeviceAuthorization(code)
                await MainActor.run {
                    traktDeviceLinkCode = nil
                    traktBusy = false
                    traktStatusText = "Connected as \(account) • resume progress synchronized."
                    store.refreshPlaybackDerivedCatalogRows()
                    store.refreshTraktCatalogRowsIfNeeded(force: true, userInitiated: true, playbackAlreadySynchronized: true)
                    store.status = traktStatusText
                }
            } catch is CancellationError {
                await MainActor.run { traktBusy = false }
            } catch {
                await MainActor.run {
                    traktDeviceLinkCode = nil
                    traktBusy = false
                    traktStatusText = error.localizedDescription
                    store.status = "Trakt: \(error.localizedDescription)"
                }
            }
        }
    }

