    private func cleanBackupCode(_ value: String) -> String {
        value.uppercased().filter { $0.isLetter || $0.isNumber || $0 == "-" }
    }

    private func runBackendProfileBackup() {
        guard !backendProfileBackupBusy else { return }
        backendProfileBackupBusy = true
        backendProfileBackupMessage = "Saving and verifying backup…"
        let code = cleanBackupCode(backendProfileBackupCode)
        let payload = currentBackendProfilePayload()
        let deviceName = UserDefaults.standard.string(forKey: "DebridChannelsDeviceName") ?? "Apple TV"
        let appBuild = ReleaseCandidateSecurityManager.releaseIdentity()

        VODExclusiveWorkRegistry.start {
            do {
                let payloadData = try JSONSerialization.data(withJSONObject: payload, options: [.sortedKeys])
                let saved = try await BackendProfileBackupClient.save(
                    baseURL: backendBaseURL,
                    code: code,
                    profile: payload,
                    deviceName: deviceName,
                    appBuild: appBuild
                )
                let newCode = cleanBackupCode(saved.code ?? code)
                guard saved.ok, !newCode.isEmpty else {
                    let message = saved.message ?? "The backend did not return a usable backup code."
                    await MainActor.run {
                        backendProfileBackupBusy = false
                        backendProfileBackupPayloadSize = formattedByteCount(payloadData.count)
                        backendProfileBackupLastStatus = "Backup failed: \(message)"
                        backendProfileBackupMessage = backendProfileBackupLastStatus
                    }
                    return
                }

                var verification = "Saved"
                do {
                    let restored = try await BackendProfileBackupClient.restore(baseURL: backendBaseURL, code: newCode)
                    if restored.ok, let profile = restored.profile {
                        let result = verifyBackendProfileRoundTrip(expected: payload, restored: profile)
                        if result.mismatchCount == 0, result.expectedCount > 0 {
                            verification = "Saved and fully verified \(result.expectedCount) settings"
                        } else {
                            verification = "Saved, but verification found \(result.mismatchCount) missing or changed setting(s)"
                        }
                    } else {
                        verification = "Saved, but verification returned no profile"
                    }
                } catch {
                    verification = "Saved, but verification failed: \(error.localizedDescription)"
                }

                await MainActor.run {
                    backendProfileBackupBusy = false
                    backendProfileBackupCode = newCode
                    backendProfileBackupPayloadSize = formattedByteCount(payloadData.count)
                    backendProfileBackupLastDate = saved.updatedAt ?? Date().friendlyBackupDate
                    backendProfileBackupLastStatus = "\(verification). Full Live TV and Source Intelligence configuration is included."
                    backendProfileBackupMessage = backendProfileBackupLastStatus
                }
            } catch {
                await MainActor.run {
                    backendProfileBackupBusy = false
                    backendProfileBackupLastStatus = "Backup failed: \(error.localizedDescription)"
                    backendProfileBackupMessage = backendProfileBackupLastStatus
                }
            }
        }
    }

    private func runBackendProfileRestore() {
        guard !backendProfileBackupBusy else { return }
        let code = cleanBackupCode(backendProfileBackupCode)
        guard !code.isEmpty else {
            backendProfileBackupMessage = "Enter a backup code first."
            backendProfileBackupLastStatus = backendProfileBackupMessage
            return
        }

        backendProfileBackupBusy = true
        backendProfileBackupMessage = "Downloading and validating backup…"
        VODExclusiveWorkRegistry.start {
            do {
                let restored = try await BackendProfileBackupClient.restore(baseURL: backendBaseURL, code: code)
                guard restored.ok, let profile = restored.profile else {
                    let message = restored.message ?? "No backend backup was found for that code."
                    await MainActor.run {
                        backendProfileBackupBusy = false
                        backendProfileBackupLastStatus = message
                        backendProfileBackupMessage = message
                    }
                    return
                }

                let appliedCount = await MainActor.run { () -> Int in
                    let count = applyBackendProfilePayload(profile)
                    backendProfileBackupCode = cleanBackupCode(restored.code ?? code)
                    backendProfileBackupPayloadSize = formattedByteCount(restored.payloadByteCount)
                    backendProfileBackupLastDate = restored.updatedAt ?? Date().friendlyBackupDate
                    if count > 0 {
                        backendProfileBackupLastStatus = "Restored \(count) profile settings, including Live TV sources and provider keys. Refreshing catalogs and Trakt resume now."
                    } else {
                        backendProfileBackupLastStatus = "The backup was downloaded, but it contained no compatible settings for this build."
                    }
                    backendProfileBackupMessage = backendProfileBackupLastStatus
                    return count
                }

                var traktRestoreDetail = ""
                if appliedCount > 0 {
                    // vBRDC211: restore codes never copy OAuth tokens, but Keychain survives
                    // normal reinstall/update paths on the same Apple TV. Recover that link and
                    // issue exactly ONE authoritative playback-progress resync as part of this
                    // restore transaction so Continue Playing • Trakt is correct immediately.
                    let recoveredPersistedTrakt = TraktSyncManager.shared.restorePersistedConnectionIfNeeded()
                    if recoveredPersistedTrakt && TraktSyncManager.shared.isEnabled {
                        let resynced = await TraktSyncManager.shared.manualResyncFromSettings()
                        let syncedStatus = TraktSyncManager.shared.lastStatus
                        await MainActor.run {
                            store.refreshPlaybackDerivedCatalogRows(scheduleAccountRefresh: false)
                            store.hydrateResumeArtworkOnColdLaunchIfNeeded(force: true)
                            if resynced {
                                // The playback snapshot was just refreshed above. Explicitly
                                // prevent the Trakt catalog fetch from issuing it a second time.
                                store.refreshTraktCatalogRowsIfNeeded(
                                    force: true,
                                    userInitiated: true,
                                    playbackAlreadySynchronized: true
                                )
                            }
                            traktStatusText = syncedStatus
                            store.status = syncedStatus
                        }
                        traktRestoreDetail = resynced
                            ? " Trakt was restored from Keychain and resynced once automatically."
                            : " Trakt link was restored, but resume resync failed: \(syncedStatus)"
                    } else if recoveredPersistedTrakt {
                        await MainActor.run {
                            traktStatusText = "Trakt Resume Sync is Off"
                            store.refreshPlaybackDerivedCatalogRows(scheduleAccountRefresh: false)
                        }
                        traktRestoreDetail = " Trakt is linked, but Resume Sync is Off, so no automatic network resync was requested."
                    } else {
                        traktRestoreDetail = " No saved Trakt Keychain link was available; reconnect Trakt once on this Apple TV to enable cloud resume."
                    }
                }

                await MainActor.run {
                    backendProfileBackupBusy = false
                    backendProfileBackupLastStatus += traktRestoreDetail
                    backendProfileBackupMessage = backendProfileBackupLastStatus
                }
            } catch {
                await MainActor.run {
                    backendProfileBackupBusy = false
                    backendProfileBackupLastStatus = "Restore failed: \(error.localizedDescription)"
                    backendProfileBackupMessage = backendProfileBackupLastStatus
                }
            }
        }
    }

    private func runBackendProfileClear() {
        guard !backendProfileBackupBusy else { return }
        let code = cleanBackupCode(backendProfileBackupCode)
        guard !code.isEmpty else {
            backendProfileBackupMessage = "Enter a backup code first."
            backendProfileBackupLastStatus = backendProfileBackupMessage
            return
        }

        backendProfileBackupBusy = true
        backendProfileBackupMessage = "Deleting backend copy…"
        VODExclusiveWorkRegistry.start {
            do {
                let cleared = try await BackendProfileBackupClient.clear(baseURL: backendBaseURL, code: code)
                await MainActor.run {
                    backendProfileBackupBusy = false
                    if cleared.ok {
                        backendProfileBackupLastDate = "Never"
                        backendProfileBackupPayloadSize = "0 bytes"
                        backendProfileBackupLastStatus = "Backend backup cleared. Local settings were not changed."
                    } else {
                        backendProfileBackupLastStatus = cleared.message ?? "Backend clear failed."
                    }
                    backendProfileBackupMessage = backendProfileBackupLastStatus
                }
            } catch {
                await MainActor.run {
                    backendProfileBackupBusy = false
                    backendProfileBackupLastStatus = "Clear failed: \(error.localizedDescription)"
                    backendProfileBackupMessage = backendProfileBackupLastStatus
                }
            }
        }
    }

    private func formattedByteCount(_ count: Int) -> String {
        ByteCountFormatter.string(fromByteCount: Int64(count), countStyle: .file)
    }

    private func verifyBackendProfileRoundTrip(expected: [String: Any], restored: [String: Any]) -> (expectedCount: Int, mismatchCount: Int) {
        let expectedRaw = (expected["settings"] as? [String: Any]) ?? expected
        let restoredRaw = (restored["settings"] as? [String: Any]) ?? restored
        let expectedSettings = ReleaseCandidateSecurityManager.sanitizedRestoredSettings(expectedRaw)
        let restoredSettings = ReleaseCandidateSecurityManager.sanitizedRestoredSettings(restoredRaw)
        let expectedVault = ReleaseCandidateSecurityManager.sanitizedCredentialVault((expected["credentialVault"] as? [String: Any]) ?? [:])
        let restoredVault = ReleaseCandidateSecurityManager.sanitizedCredentialVault((restored["credentialVault"] as? [String: Any]) ?? [:])
        var mismatches = 0
        for (key, expectedValue) in expectedSettings {
            guard let restoredValue = restoredSettings[key],
                  canonicalBackupValue(expectedValue) == canonicalBackupValue(restoredValue) else {
                mismatches += 1
                continue
            }
        }
        for (key, expectedValue) in expectedVault where restoredVault[key] != expectedValue {
            mismatches += 1
        }
        return (expectedSettings.count + expectedVault.count, mismatches)
    }

    private func canonicalBackupValue(_ value: Any) -> Data? {
        guard JSONSerialization.isValidJSONObject(["value": value]) else { return nil }
        return try? JSONSerialization.data(withJSONObject: ["value": value], options: [.sortedKeys])
    }

    private func currentBackendProfilePayload() -> [String: Any] {
        let backupManifestURLs = ReleaseCandidateSecurityManager.cloudBackupManifestURLs(store.manifestURLs)
        let requestedPrimary = ReleaseCandidateSecurityManager.cloudBackupManifestURLs([manifestURL]).first
        let primaryManifest = requestedPrimary.flatMap { requested in
            backupManifestURLs.first(where: { $0.caseInsensitiveCompare(requested) == .orderedSame })
        } ?? backupManifestURLs.first ?? "https://v3-cinemeta.strem.io/manifest.json"
        let defaults = UserDefaults.standard
        let favoritePortableLibraryBackup = favoriteMediaLibraryBackupString()
        let favoriteLegacySnapshotBackup = favoritePortableLibraryBackup.isEmpty ? favoriteMediaSnapshotsBackupString() : ""
        let credentialVault = ReleaseCandidateSecurityManager.sanitizedCredentialVault([
            "febBoxCookie": BackupStreamingCredentialStore.readFebBoxCookie(),
            "mediaFlowAPIPassword": MediaFlowCredentialStore.readPassword(),
            "nuvioPluginBackupBlob": NuvioPluginPreferences.exportBackupBlob()
        ])
        let settings: [String: Any] = [
            // Catalogs and add-ons
