    @discardableResult
    private func applyBackendProfilePayload(_ payload: [String: Any]) -> Int {
        let rawSettings = (payload["settings"] as? [String: Any]) ?? payload
        let settings = ReleaseCandidateSecurityManager.sanitizedRestoredSettings(rawSettings)
        let credentialVault = ReleaseCandidateSecurityManager.sanitizedCredentialVault((payload["credentialVault"] as? [String: Any]) ?? [:])
        guard !settings.isEmpty || !credentialVault.isEmpty else { return 0 }
        let defaults = UserDefaults.standard
        for (key, value) in settings {
            defaults.set(value, forKey: key)
        }
        // vBRDC159: restore the compact portable library first. It survives replacement
        // installs without requiring Search/catalog rows to rediscover the title. Older
        // v157/v158 restore codes still fall back to their validated snapshot dictionary.
        var restoredPortableFavorites = false
        if let encodedLibrary = settings[favoriteMediaLibraryBackupKey] as? String {
            restoredPortableFavorites = restoreFavoriteMediaLibrary(from: encodedLibrary)
        }
        if !restoredPortableFavorites,
           let encodedSnapshots = settings[favoriteMediaSnapshotsBackupKey] as? String,
           !encodedSnapshots.isEmpty,
           encodedSnapshots.utf8.count <= 2_100_000,
           let snapshotData = Data(base64Encoded: encodedSnapshots),
           snapshotData.count <= 1_500_000,
           (try? JSONDecoder().decode([String: MediaItem].self, from: snapshotData)) != nil {
            defaults.set(snapshotData, forKey: favoriteMediaSnapshotsDefaultsKey)
        }
        defaults.removeObject(forKey: favoriteMediaLibraryBackupKey)
        defaults.removeObject(forKey: favoriteMediaSnapshotsBackupKey)
        defaults.set(defaults.integer(forKey: "favoriteMediaRestoreGenerationV1") + 1, forKey: "favoriteMediaRestoreGenerationV1")
        // vBRDC203: UserDefaults.set is immediately visible in-process; forcing a
        // synchronous domain flush here can stall the tvOS UI after large profile restores.
        // vBRDC158: older restore codes can contain favorite IDs without portable snapshots.
        // Rebuild those in the background immediately after restore; Favorites no longer
        // waits for the user to manually search/unfavorite/refavorite a title.
        Task { @MainActor in
            var keys = favoriteMediaKeySet(defaults.string(forKey: "favoriteMediaIds") ?? "")
            var migrated = false

            // Portable/legacy snapshot aliases can already contain enough identity to migrate
            // an old `itemID::catalog::type` key without making a network request.
            for key in Array(keys) {
                if let existing = persistedFavoriteMediaItems(matching: Set([key])).first {
                    let modern = mediaFavoriteKey(existing)
                    if modern != key {
                        keys.remove(key)
                        keys.insert(modern)
                        migrated = true
                    }
                }
            }

            let persisted = persistedFavoriteMediaItems(matching: keys)
            let catalogItems = store.rows.flatMap(\.items)
            let missing = keys.filter { key in
                !persisted.contains(where: { mediaFavoriteKeys(for: $0).contains(key) })
                    && !catalogItems.contains(where: { mediaFavoriteKeys(for: $0).contains(key) })
            }.sorted()
            var recovered = 0
            for key in missing.prefix(64) {
                guard let item = await store.rehydrateFavoriteMediaItem(fromFavoriteKey: key), isFavoriteMovieOrShow(item) else { continue }
                persistFavoriteMediaSnapshot(item)
                let modern = mediaFavoriteKey(item)
                if modern != key {
                    keys.remove(key)
                    keys.insert(modern)
                    migrated = true
                }
                recovered += 1
                await Task.yield()
            }
            if migrated {
                defaults.set(keys.sorted().joined(separator: "|"), forKey: "favoriteMediaIds")
            }
            if recovered > 0 || migrated {
                defaults.set(defaults.integer(forKey: "favoriteMediaRestoreGenerationV1") + 1, forKey: "favoriteMediaRestoreGenerationV1")
                // vBRDC203: UserDefaults.set is immediately visible in-process; forcing a
                // synchronous domain flush here can stall the tvOS UI after large profile restores.
                FavoriteProfileBackupSyncManager.shared.scheduleSync()
            }
        }
        let payloadManifests = ((payload["streamingCatalogs"] as? [String: Any])?["manifestURLs"] as? [String]) ?? ((payload["stremioAddons"] as? [String: Any])?["manifestURLs"] as? [String])
        let restoredManifests = ReleaseCandidateSecurityManager.cloudBackupManifestURLs((settings["stremioManifestURLs"] as? [String]) ?? payloadManifests ?? [])
        let restoredAllInOne = settings["allInOneCatalogsEnabled"] as? Bool ?? allInOneCatalogsEnabled
        allInOneCatalogsEnabled = restoredAllInOne
        let cleanedRestoredManifests = restoredManifests.map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }.filter { !$0.isEmpty }
        store.reconcileCatalogsAfterRestore(restoredManifests: cleanedRestoredManifests, allInOneEnabled: restoredAllInOne)
        manifestURL = store.manifestURLs.first ?? (settings["stremioManifestURL"] as? String ?? manifestURL)
        liveChannelsDvrBaseURL = settings["liveChannelsDvrBaseURL"] as? String ?? liveChannelsDvrBaseURL
        liveHDHomeRunManualURL = settings["liveHDHomeRunManualURL"] as? String ?? liveHDHomeRunManualURL
        liveHDHomeRunManualGuideURL = settings["liveHDHomeRunManualGuideURL"] as? String ?? liveHDHomeRunManualGuideURL
        liveM3UURL = settings["liveM3UURL"] as? String ?? liveM3UURL
        liveXMLTVURL = settings["liveXMLTVURL"] as? String ?? liveXMLTVURL
        liveXtreamServer = settings["liveXtreamServer"] as? String ?? liveXtreamServer
        liveXtreamUsername = settings["liveXtreamUsername"] as? String ?? liveXtreamUsername
        liveXtreamPassword = settings["liveXtreamPassword"] as? String ?? liveXtreamPassword
        liveXtreamAccounts = settings["liveXtreamAccounts"] as? String ?? liveXtreamAccounts
        sportsAssignedGroupsRaw = settings["sportsAssignedGroups"] as? String ?? sportsAssignedGroupsRaw
        liveXtreamLoginStatus = settings["liveXtreamLoginStatus"] as? String ?? liveXtreamLoginStatus
        sportsXtreamImportMode = settings["sportsXtreamImportMode"] as? String ?? sportsXtreamImportMode
        sportsFavoriteTeams = settings["sportsFavoriteTeams"] as? String ?? sportsFavoriteTeams
        sportsCustomSourcesJSON = settings["sportsCustomSourcesJSON"] as? String ?? sportsCustomSourcesJSON
        sportsScoreTickerEnabled = settings["sportsScoreTickerEnabled"] as? Bool ?? sportsScoreTickerEnabled
        moviesShowsReleaseTickerEnabled = settings["moviesShowsReleaseTickerEnabled"] as? Bool ?? moviesShowsReleaseTickerEnabled
        backendBaseURL = settings["backendBaseURL"] as? String ?? backendBaseURL
        tmdbApiKey = settings["tmdbApiKey"] as? String ?? tmdbApiKey
        omdbApiKey = settings["omdbApiKey"] as? String ?? omdbApiKey
        fanartTvApiKey = settings["fanartTvApiKey"] as? String ?? fanartTvApiKey
        tvdbApiToken = settings["tvdbApiToken"] as? String ?? tvdbApiToken
        torBoxApiKey = settings["torBoxApiKey"] as? String
            ?? settings["torrentioTorBoxApiKey"] as? String
            ?? torBoxApiKey
        torBoxUsenetBridgeManifestURL = settings["torBoxUsenetBridgeManifestURLV1"] as? String ?? torBoxUsenetBridgeManifestURL
        realDebridApiKey = settings["realDebridApiKey"] as? String
            ?? settings["torrentioRealDebridApiKey"] as? String
            ?? realDebridApiKey
        premiumizeApiKey = settings["premiumizeApiKey"] as? String ?? premiumizeApiKey
        allDebridApiKey = settings["allDebridApiKey"] as? String ?? allDebridApiKey
        debridLinkApiKey = settings["debridLinkApiKey"] as? String ?? debridLinkApiKey
