        putioClientID = settings["putioClientID"] as? String ?? putioClientID
        putioToken = settings["putioToken"] as? String ?? putioToken
        DebridCredentialBridge.migrateLegacyOverridesIfNeeded(defaults: defaults)
        managedTorrentioRealDebridEnabled = settings["managedTorrentioEnabled.realdebrid.v1"] as? Bool ?? UserDefaults.standard.bool(forKey: DebridServiceID.realDebrid.torrentioEnabledKey)
        managedTorrentioTorBoxEnabled = settings["managedTorrentioEnabled.torbox.v1"] as? Bool ?? UserDefaults.standard.bool(forKey: DebridServiceID.torBox.torrentioEnabledKey)
        managedTorrentioPremiumizeEnabled = settings["managedTorrentioEnabled.premiumize.v1"] as? Bool ?? UserDefaults.standard.bool(forKey: DebridServiceID.premiumize.torrentioEnabledKey)
        managedTorrentioAllDebridEnabled = settings["managedTorrentioEnabled.alldebrid.v1"] as? Bool ?? UserDefaults.standard.bool(forKey: DebridServiceID.allDebrid.torrentioEnabledKey)
        managedTorrentioDebridLinkEnabled = settings["managedTorrentioEnabled.debridlink.v1"] as? Bool ?? UserDefaults.standard.bool(forKey: DebridServiceID.debridLink.torrentioEnabledKey)
        managedTorrentioEasyDebridEnabled = settings["managedTorrentioEnabled.easydebrid.v1"] as? Bool ?? UserDefaults.standard.bool(forKey: DebridServiceID.easyDebrid.torrentioEnabledKey)
        managedTorrentioOffcloudEnabled = settings["managedTorrentioEnabled.offcloud.v1"] as? Bool ?? UserDefaults.standard.bool(forKey: DebridServiceID.offcloud.torrentioEnabledKey)
        managedTorrentioPutioEnabled = settings["managedTorrentioEnabled.putio.v1"] as? Bool ?? UserDefaults.standard.bool(forKey: DebridServiceID.putio.torrentioEnabledKey)
        builtInAddonCachedOnly = settings["builtInAddonCachedOnly"] as? Bool ?? builtInAddonCachedOnly
        builtInAddonExcludeCam = settings["builtInAddonExcludeCam"] as? Bool ?? builtInAddonExcludeCam
        sourceIntelligenceMaximumLinks = SettingsStateFocusManager.normalizedSourceLinkLimit(settings["sourceIntelligenceMaximumLinks"], fallback: sourceIntelligenceMaximumLinks)
        optionalFebBoxEnabled = settings["optionalFebBoxEnabledV1"] as? Bool ?? optionalFebBoxEnabled
        if let grouped = settings["nuvioPluginGroupProvidersByRepository.v1"] as? Bool {
            NuvioPluginPreferences.setGroupProvidersByRepository(grouped)
            groupInSProvidersByRepository = grouped
        }
        mediaFlowProxyEnabled = settings["mediaFlowProxyEnabledV1"] as? Bool ?? mediaFlowProxyEnabled
        mediaFlowProxyURL = settings["mediaFlowProxyURLV1"] as? String ?? mediaFlowProxyURL
        mediaFlowPublicIP = settings["mediaFlowProxyPublicIPV1"] as? String ?? mediaFlowPublicIP
        mediaFlowWebBrowserPlayback = settings["mediaFlowWebBrowserPlaybackV1"] as? Bool ?? mediaFlowWebBrowserPlayback
        debridNowShowingServerURL = settings["debridNowShowingServerURLV1"] as? String ?? debridNowShowingServerURL
        debridNowShowingPushToken = settings["debridNowShowingPushTokenV1"] as? String ?? debridNowShowingPushToken
        externalMoviesInfuseDefault = settings["externalMoviesInfuseDefault"] as? Bool ?? externalMoviesInfuseDefault
        externalMoviesVLCDefault = settings["externalMoviesVLCDefault"] as? Bool ?? externalMoviesVLCDefault
        externalMoviesSenPlayerDefault = settings["externalMoviesSenPlayerDefault"] as? Bool ?? externalMoviesSenPlayerDefault
        externalShowsInfuseDefault = settings["externalShowsInfuseDefault"] as? Bool ?? externalShowsInfuseDefault
        externalShowsVLCDefault = settings["externalShowsVLCDefault"] as? Bool ?? externalShowsVLCDefault
        externalShowsSenPlayerDefault = settings["externalShowsSenPlayerDefault"] as? Bool ?? externalShowsSenPlayerDefault
        liveTVUseAVPlayerDefault = settings["liveTVUseAVPlayerDefault"] as? Bool ?? liveTVUseAVPlayerDefault
        liveTVInternalPlayerEngine = settings["liveTVInternalPlayerEngineV1"] as? String ?? liveTVInternalPlayerEngine
        if liveTVInternalPlayerEngine != "aether" && liveTVInternalPlayerEngine != "ksplayer" { liveTVInternalPlayerEngine = "aether" }
        liveTVMatchDisplayEnabled = settings["liveTVMatchDisplayEnabled"] as? Bool ?? liveTVMatchDisplayEnabled
