        }
        vodControlShelfMode = settings["vodControlShelfMode"] as? String ?? vodControlShelfMode
        let restoredShelfAutoHide = (settings["vodControlShelfAutoHideSeconds"] as? NSNumber)?.intValue
            ?? Int(settings["vodControlShelfAutoHideSeconds"] as? String ?? "")
            ?? vodControlShelfAutoHideSeconds
        vodControlShelfAutoHideSeconds = [0, 5, 10, 15].contains(restoredShelfAutoHide) ? restoredShelfAutoHide : vodControlShelfAutoHideSeconds
        vodControlShelfLastExpanded = settings["vodControlShelfLastExpanded"] as? Bool ?? vodControlShelfLastExpanded
        focusedCardPreviewsEnabled = settings["focusedCardPreviewsEnabled"] as? Bool ?? focusedCardPreviewsEnabled
