        mediaInfoTopBarTransparency = settings["mediaInfoTopBarTransparency"] as? String ?? mediaInfoTopBarTransparency
        showMediaInfoPortraitPoster = settings["showMediaInfoPortraitPoster"] as? Bool ?? showMediaInfoPortraitPoster
        connectedMediaPopupArtworkEnabled = settings["connectedMediaPopupArtworkEnabled"] as? Bool ?? connectedMediaPopupArtworkEnabled
        mediaInfoConnectorLineEnabled = settings["mediaInfoConnectorLineEnabledV1"] as? Bool ?? mediaInfoConnectorLineEnabled
        topLeftDebridChannelsLogoEnabled = settings["topLeftDebridChannelsLogoEnabledV1"] as? Bool ?? topLeftDebridChannelsLogoEnabled
        signalChromeLogoSize = SignalChromeLogoSize.normalized(settings["signalChromeLogoSizeV346"] as? String ?? signalChromeLogoSize)
        advisoryDisplayEnabled = settings["advisoryDisplayEnabled"] as? Bool ?? advisoryDisplayEnabled
        homeGridThemePreset = settings["homeGridThemePreset"] as? String ?? homeGridThemePreset
        liveTVGridThemePreset = settings["liveTVGridThemePreset"] as? String ?? liveTVGridThemePreset
        followAlertsEnabled = settings["followAlertsEnabled"] as? Bool ?? followAlertsEnabled
        followNewEpisodesEnabled = settings["followNewEpisodesEnabled"] as? Bool ?? followNewEpisodesEnabled
        followSportsAlertsEnabled = settings["followSportsAlertsEnabled"] as? Bool ?? followSportsAlertsEnabled
        followPPVAlertsEnabled = settings["followPPVAlertsEnabled"] as? Bool ?? followPPVAlertsEnabled
        followVerifiedOnly = settings["followVerifiedOnly"] as? Bool ?? followVerifiedOnly
        newEpisodeAlertScanFrequencyMinutes = settings["newEpisodeAlertScanFrequencyMinutes"] as? String ?? newEpisodeAlertScanFrequencyMinutes
        newEpisodeAlertStyle = settings["newEpisodeAlertStyle"] as? String ?? newEpisodeAlertStyle
        newEpisodeAlertBannerSide = settings["newEpisodeAlertBannerSide"] as? String ?? newEpisodeAlertBannerSide
        newEpisodeAlertTheme = settings["newEpisodeAlertTheme"] as? String ?? newEpisodeAlertTheme
        newEpisodeAlertBannerDurationSeconds = settings["newEpisodeAlertBannerDurationSeconds"] as? String ?? newEpisodeAlertBannerDurationSeconds
        newEpisodeAlertPresentationScope = settings["newEpisodeAlertPresentationScopeV1"] as? String ?? newEpisodeAlertPresentationScope

        var restoredCredentialCount = 0
        if let cookie = credentialVault["febBoxCookie"], BackupStreamingCredentialStore.saveFebBoxCookie(cookie) {
            febBoxCookieDraft = cookie
            restoredCredentialCount += 1
        }
        if let password = credentialVault["mediaFlowAPIPassword"], MediaFlowCredentialStore.savePassword(password) {
            mediaFlowAPIPassword = password
            restoredCredentialCount += 1
        }
        if let blob = credentialVault["nuvioPluginBackupBlob"] {
            restoredCredentialCount += NuvioPluginPreferences.restoreBackupBlob(blob)
            nuvioRepositories = NuvioPluginPreferences.repositories()
        }
        return settings.count + restoredCredentialCount
    }

    private var resetOnboardingSection: some View {
        VStack(alignment: .leading, spacing: 12) {
            Text("Stable Protection")
                .font(.system(size: 22, weight: .black))
                .foregroundStyle(Color.cyan)
            Text("Restore the verified stable presentation defaults or immediately disable experimental playback. Accounts, favorites, watch progress, providers, Live TV sources, and episode alerts are preserved.")
