    private func restoreStableUIDefaults() {
        Phase13RolloutManager.setEmergencyKillSwitch(false)
        let changed = StableFeatureGateManager.restoreStableUIDefaults()

        // Assign through AppStorage as well as UserDefaults so the visible Settings screen
        // updates immediately without requiring an app relaunch.
        gridLockedMode = false
        popupFontPreset = "SF Rounded"
        topMenuThemePreset = "Classic"
        topMenuAccentColor = "Orange"
        topMenuFontPreset = "SF Rounded"
        topMenuSizePreset = "Medium"
        appCanvasExpanded = false
        homeGridThemePreset = "Classic Glow"
        focusedCardPreviewsEnabled = false
        focusedCardPulseAnimationEnabled = false
        catalogRowScrollingAnimationPreset = UnityCatalogRowMotionStyle.defaultName
        mainGridBackgroundPreset = "Midnight Graphite"
        dynamicMainGridWallpaperEnabled = false
        dynamicMainGridWallpaperPreset = "Cinematic Smoke"
        dynamicMainGridWallpaperCustomEnabled = false
        dynamicMainGridWallpaperCustomURL = ""
        visualPerformanceMode = "Compatibility"
        liveTVGridThemePreset = "Classic Dark"
        liveTVGridProgramProgressEnabled = true
        liveTVGridFocusPreviewEnabled = true
        liveTVGridFocusPreviewDuration = "15 Seconds"
        liveTVGridFocusPreviewStyle = "Standard"
        liveTVGridDimOthersDuringPreview = true
        liveTVGridFocusRingColor = "White"
        liveTVGridFocusRingMotion = "Classic Glow"
        liveTVCardArtworkStyle = "frosted"
        liveTVAnimatedHeaderLogoEnabled = true
        liveTVAnimatedHeaderLogoStyle = "Signal TV"
        liveTVChannelNumberPosition = "Top Right"
        liveTVGridLayoutStyle = "Current"
        liveTVDashboardStyle = "Golden"
        mirrorShowTopMenu = false
        signalLiveTVCardTheme = "Original UNITY"
        signalLiveTVCardEffect = "Dual Inward"
        signalLiveTVCardSize = "Standard"
        signalLiveTVCardTypography = "UNITY Original"
        signalChromeLogoSize = "Small"
        launchAppInGuide = false
        showMediaInfoPortraitPoster = true
        connectedMediaPopupArtworkEnabled = false
        topBarMediaInfoLayout = "Center"
        mediaInfoTopBarTransparency = "Solid"
        advisoryDisplayEnabled = true
        vodInternalPlayerEngine = "aether"
        vodControlsDockStyle = "visible"
        vodOverlayThemePresetRaw = VODOverlayThemePreset.original.rawValue
        vodControlShelfMode = "hidden"
        vodControlShelfAutoHideSeconds = 5
        vodControlShelfLastExpanded = false
        trailerEngineMode = "auto"

        store.recoverCatalogInteractivity(reason: "stable UI defaults restored")
        store.status = "Stable UI defaults restored (\(changed) setting changes). Accounts, favorites, progress, providers, Live TV, and episode alerts were preserved."
    }

    private var installedAppReleaseID: String {
        let raw = Bundle.main.object(forInfoDictionaryKey: "DebridChannelsReleaseID") as? String
        return (raw?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false) ? raw! : "Unknown"
    }

    private var installedAppVersion: String {
        let raw = Bundle.main.object(forInfoDictionaryKey: "CFBundleShortVersionString") as? String
        return (raw?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false) ? raw! : "Unknown"
    }

    private var installedAppBuild: String {
        let raw = Bundle.main.object(forInfoDictionaryKey: "CFBundleVersion") as? String
        return (raw?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false) ? raw! : "Unknown"
    }

    private var installedAppCodeName: String {
        let raw = Bundle.main.object(forInfoDictionaryKey: "DebridChannelsCodeName") as? String
        return (raw?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false) ? raw! : UnitySurfaceSystem.displayCodeName
    }

