    private var catalogHealthSettingsSection: some View {
        let snapshot = store.catalogHealthSnapshot
        return LazyVStack(alignment: .leading, spacing: 18) {
            catalogHealthOverview(snapshot)
            sharedArtworkBackendHealthCard
            catalogHealthActions(snapshot)
            catalogHealthProviderList(snapshot)
