    private func catalogHealthOverview(_ snapshot: CatalogHealthSnapshot) -> some View {
        let loadedTint: Color = snapshot.loadedRows >= snapshot.expectedRows && snapshot.expectedRows > 0 ? .green : .orange
        let backendTint: Color = store.sharedArtworkCacheReachable ? .green : .red
        let cacheGB = Double(store.sharedArtworkCacheBytes) / 1_073_741_824.0
        return HStack(spacing: 12) {
            catalogHealthStat(title: "Catalog Rows", value: "\(snapshot.loadedRows)/\(snapshot.expectedRows)", icon: "rectangle.stack.fill", tint: loadedTint)
            catalogHealthStat(title: "Server Artwork", value: store.sharedArtworkCacheFiles.formatted(), icon: "externaldrive.fill", tint: .cyan)
            catalogHealthStat(title: "Cache Size", value: String(format: "%.1f GB", cacheGB), icon: "internaldrive.fill", tint: .purple)
            catalogHealthStat(title: "Backend", value: store.sharedArtworkCacheReachable ? "READY" : "OFFLINE", icon: "server.rack", tint: backendTint)
        }
        .frame(width: 1190, alignment: .leading)
    }

    private var sharedArtworkBackendHealthCard: some View {
