    @ViewBuilder
    private func catalogHealthProviderFailures(_ snapshot: CatalogHealthSnapshot) -> some View {
        if !snapshot.failedProviders.isEmpty || !snapshot.timedOutProviders.isEmpty {
            let failureCount = snapshot.failedProviders.count + snapshot.timedOutProviders.count
            let timedOut = snapshot.timedOutProviders.map { "Timed out: \($0.name)" }
            let failed = snapshot.failedProviders.map { "Failed: \($0.name)" }
            VStack(alignment: .leading, spacing: 8) {
                catalogHealthSectionTitle("Provider Failures", count: failureCount, icon: "wifi.exclamationmark")
                Text((timedOut + failed).joined(separator: "  •  "))
                    .font(.system(size: 14, weight: .semibold, design: .rounded))
                    .foregroundStyle(Color.red.opacity(0.84))
                    .frame(width: 1190, alignment: .leading)
            }
        }
    }

    @ViewBuilder
