    private func catalogHealthDateText(_ date: Date?) -> String {
        guard let date else { return "No successful refresh recorded yet" }
        let formatter = DateFormatter()
        formatter.dateStyle = .medium
        formatter.timeStyle = .short
        return formatter.string(from: date)
    }

    private func catalogHealthColor(_ state: CatalogProviderHealthState) -> Color {
        switch state {
        case .loaded: return .green
        case .checking: return .orange
        case .cached, .streamOnly: return .cyan
        case .noRows: return .yellow
        case .timedOut, .failed: return .red
        }
    }

