            liveTextField("TMDB API key", text: $tmdbApiKey, focus: .tmdbKey)
            liveTextField("OMDb API key for Rotten Tomatoes", text: $omdbApiKey, focus: .omdbKey)
            liveTextField("Fanart.tv API key", text: $fanartTvApiKey, focus: .fanartKey)
            liveTextField("TVDB API bearer token", text: $tvdbApiToken, focus: .tvdbToken)
            SettingsButton(title: "Save Artwork Keys", focus: .saveArtworkKeys, focused: $focused) {
                VODExclusiveWorkRegistry.start { await saveArtworkKeysToBackend() }
            }
            Text("Keys are saved securely and used to improve artwork throughout Debrid Channels.")
                .font(.system(size: 15, weight: .semibold))
                .foregroundStyle(.white.opacity(0.58))
                .frame(width: settingsColumnWidth, alignment: .leading)
        }
        .padding(.top, 10)
    }

    private func saveArtworkKeysToBackend() async {
        let base = backendBaseURL.trimmingCharacters(in: .whitespacesAndNewlines).trimmingCharacters(in: CharacterSet(charactersIn: "/"))
        guard !base.isEmpty, let url = URL(string: base + "/api/artwork/provider-keys") else {
            await MainActor.run { store.status = "Artwork key save failed: connection is not ready." }
            return
        }
        let body: [String: String] = [
            "tmdbApiKey": tmdbApiKey,
            "omdbApiKey": omdbApiKey,
            "fanartTvApiKey": fanartTvApiKey,
            "tvdbApiToken": tvdbApiToken
        ]
        do {
            var request = URLRequest(url: url)
            request.httpMethod = "POST"
            request.setValue("application/json", forHTTPHeaderField: "Content-Type")
            request.httpBody = try JSONSerialization.data(withJSONObject: body, options: [])
            let (_, response) = try await URLSession.shared.data(for: request)
            let code = (response as? HTTPURLResponse)?.statusCode ?? 0
            await MainActor.run {
                store.status = (200..<300).contains(code) ? "Artwork provider keys saved." : "Artwork key save failed with HTTP \(code)."
            }
        } catch {
            await MainActor.run { store.status = "Artwork key save failed: \(error.localizedDescription)" }
        }
    }

    private var buildStatusSection: some View { EmptyView() }

    private var quickNavigationCard: some View { EmptyView() }

    private var isXtreamFieldFocused: Bool {
        focused == .liveXtreamServer || focused == .liveXtreamUsername || focused == .liveXtreamPassword
    }


}

private struct NuvioPluginSettingsEditor: View {
    @Environment(\.dismiss) private var dismiss
    let backendBaseURL: String
    let target: NuvioPluginSettingsTarget

    @State private var fields: [NuvioPluginSettingField] = []
    @State private var values: [String: NuvioSettingValue] = [:]
    @State private var status: String = "Loading plugin settings…"
    @State private var loading: Bool = true

    var body: some View {
        ZStack {
            LinearGradient(
                colors: [Color.black, Color(red: 0.025, green: 0.035, blue: 0.055)],
                startPoint: .topLeading,
                endPoint: .bottomTrailing
            )
            .ignoresSafeArea()

            VStack(alignment: .leading, spacing: 20) {
                HStack(alignment: .top) {
                    VStack(alignment: .leading, spacing: 6) {
                        Text(target.providerName)
                            .font(.system(size: 42, weight: .black, design: .rounded))
                            .foregroundStyle(.white)
                        Text("🔌 In-S Settings")
                            .font(.system(size: 16, weight: .black, design: .rounded))
                            .tracking(1.0)
                            .foregroundStyle(.cyan.opacity(0.82))
                    }
                    Spacer()
                    Button("Close") {
                        persistSettingsIfLoaded()
                        dismiss()
                    }
                        .buttonStyle(.bordered)
                }

                if loading {
                    HStack(spacing: 12) {
                        ProgressView()
                        Text(status)
                            .font(.system(size: 17, weight: .semibold, design: .rounded))
                            .foregroundStyle(.white.opacity(0.68))
                    }
                    Spacer()
                } else if fields.isEmpty {
                    Text(status.isEmpty ? "This provider does not expose configurable settings." : status)
                        .font(.system(size: 18, weight: .semibold, design: .rounded))
                        .foregroundStyle(.white.opacity(0.66))
                    Spacer()
                } else {
                    ScrollView(.vertical, showsIndicators: true) {
                        VStack(alignment: .leading, spacing: 16) {
                            ForEach(fields) { field in
                                settingField(field)
                            }
                        }
                        .padding(.trailing, 16)
                    }

                    HStack(spacing: 14) {
                        Button("Save Settings") {
                            persistSettingsIfLoaded()
                            status = "Settings saved. New source searches will use them."
                        }
                        .buttonStyle(.borderedProminent)

                        Text(status)
                            .font(.system(size: 13, weight: .bold, design: .rounded))
                            .foregroundStyle(.white.opacity(0.58))
                    }
                }
            }
            .padding(64)
            .frame(maxWidth: 1540, maxHeight: 900, alignment: .topLeading)
        }
        .task { await loadSettings() }
        .onDisappear { persistSettingsIfLoaded() }
    }

    @ViewBuilder
    private func settingField(_ field: NuvioPluginSettingField) -> some View {
        switch field.type.lowercased() {
        case "header":
            Text(field.label)
                .font(.system(size: 24, weight: .black, design: .rounded))
                .foregroundStyle(.white)
                .padding(.top, 8)
        case "info":
            VStack(alignment: .leading, spacing: 4) {
                Text(field.label)
                    .font(.system(size: 15, weight: .bold, design: .rounded))
                    .foregroundStyle(.white.opacity(0.84))
                if let description = field.description, !description.isEmpty {
                    Text(description)
                        .font(.system(size: 13, weight: .semibold, design: .rounded))
                        .foregroundStyle(.white.opacity(0.50))
                }
            }
        case "toggle":
            if let key = field.key {
                Toggle(isOn: Binding(
                    get: { values[key]?.boolValue ?? field.defaultValue?.boolValue ?? false },
                    set: { values[key] = .bool($0) }
                )) {
                    fieldLabel(field)
                }
                .toggleStyle(.automatic)
            }
        case "select":
            if let key = field.key {
                VStack(alignment: .leading, spacing: 9) {
                    fieldLabel(field)
                    HStack(spacing: 10) {
                        ForEach(field.options) { option in
                            let selected = (values[key]?.stringValue ?? field.defaultValue?.stringValue ?? "") == option.value
                            Button(option.label) { values[key] = .string(option.value) }
                                .buttonStyle(.bordered)
                                .tint(selected ? Color.cyan : Color.white.opacity(0.18))
                        }
                    }
                }
            }
        case "text":
            if let key = field.key {
                VStack(alignment: .leading, spacing: 8) {
                    fieldLabel(field)
                    if field.isPassword {
                        SecureField(field.placeholder ?? field.label, text: stringBinding(key: key, fallback: field.defaultValue?.stringValue ?? ""))
                            .textFieldStyle(.plain)
                            .padding(14)
                            .background(RoundedRectangle(cornerRadius: 12).fill(Color.white.opacity(0.08)))
                    } else {
                        TextField(field.placeholder ?? field.label, text: stringBinding(key: key, fallback: field.defaultValue?.stringValue ?? ""))
                            .textFieldStyle(.plain)
                            .padding(14)
                            .background(RoundedRectangle(cornerRadius: 12).fill(Color.white.opacity(0.08)))
                    }
                }
            }
        default:
            EmptyView()
        }
    }

    private func fieldLabel(_ field: NuvioPluginSettingField) -> some View {
        VStack(alignment: .leading, spacing: 3) {
            Text(field.label)
                .font(.system(size: 16, weight: .black, design: .rounded))
                .foregroundStyle(.white)
            if let description = field.description, !description.isEmpty {
                Text(description)
                    .font(.system(size: 12, weight: .semibold, design: .rounded))
                    .foregroundStyle(.white.opacity(0.48))
            }
        }
    }

    private func stringBinding(key: String, fallback: String) -> Binding<String> {
        Binding(
            get: { values[key]?.stringValue ?? fallback },
            set: { values[key] = .string($0) }
        )
    }


    private func persistSettingsIfLoaded() {
        guard !loading, !fields.isEmpty else { return }
        NuvioPluginPreferences.saveSettings(
            repositoryURL: target.repositoryURL,
            providerID: target.providerID,
            fields: fields,
            values: values
        )
    }

    private func loadSettings() async {
        do {
            let loaded = try await NuvioPluginClient.providerSettings(
                backendBaseURL: backendBaseURL,
                repositoryURL: target.repositoryURL,
                providerID: target.providerID
            )
            guard !Task.isCancelled else { return }
            let loadedValues = NuvioPluginPreferences.settingValues(
                repositoryURL: target.repositoryURL,
                providerID: target.providerID,
                fields: loaded
            )
            await MainActor.run {
                fields = loaded
                values = loadedValues
                loading = false
                status = loaded.isEmpty ? "No configurable settings." : ""
            }
        } catch {
            await MainActor.run {
                fields = []
                loading = false
                status = "Could not load settings: \(error.localizedDescription)"
            }
        }
    }
}

struct AllInOneCatalogCustomizationScreen: View {
    private enum CustomizationFocus: Hashable {
        case visibility(String)
        case moveTop(String)
        case moveUp(String)
        case moveDown(String)
        case apply
        case reset
        case cancel
    }

    @EnvironmentObject private var store: CatalogStore
    @Environment(\.dismiss) private var dismiss
    @State private var draftRows: [BuiltInCatalogRowDescriptor] = []
    @State private var officialDefaultRows: [BuiltInCatalogRowDescriptor] = []
    @State private var hiddenRowIDs: Set<String> = []
    @State private var hasLoadedDraft = false
    @State private var hasChanges = false
    @FocusState private var focusedControl: CustomizationFocus?

    var body: some View {
        ZStack {
            StaticAppBackground().ignoresSafeArea()
            VStack(alignment: .leading, spacing: 22) {
                header
                if draftRows.isEmpty {
                    loadingState
                } else {
                    rowList
                    footerControls
                }
            }
            .frame(width: 1740, height: 960, alignment: .topLeading)
            .padding(.top, 64)
        }
        .onAppear { loadDraftIfAvailable(force: true) }
        .onChange(of: store.builtInCatalogRowDescriptors) { _ in
            if !hasLoadedDraft { loadDraftIfAvailable(force: true) }
        }
        .signalVisionExitCommand { dismiss() }
    }

    private var header: some View {
        VStack(alignment: .leading, spacing: 8) {
            Text("Customize All-in-One Catalogs")
                .font(.system(size: 52, weight: .black, design: .rounded))
                .foregroundStyle(.white)
            Text("Built-in, Continue Watching, and Trakt row controls. Apply reorders cached rows immediately; no full network reload is required.")
                .font(.system(size: 18, weight: .semibold, design: .rounded))
                .foregroundStyle(.white.opacity(0.62))
            if !draftRows.isEmpty {
                Text("\(draftRows.count - hiddenRowIDs.count) visible of \(draftRows.count) customizable rows")
                    .font(.system(size: 16, weight: .bold, design: .rounded))
                    .foregroundStyle(.orange.opacity(0.92))
            }
        }
    }

    private var loadingState: some View {
        VStack(alignment: .leading, spacing: 18) {
            Text("Built-in rows are still loading")
                .font(.system(size: 30, weight: .black, design: .rounded))
                .foregroundStyle(.white)
            Text("The customization list appears after the normal All-in-One manifest refresh supplies its row IDs and official order.")
                .font(.system(size: 18, weight: .semibold, design: .rounded))
                .foregroundStyle(.white.opacity(0.62))
                .frame(width: 980, alignment: .leading)
            Button("Close") { dismiss() }
                .buttonStyle(.borderedProminent)
        }
        .padding(30)
        .frame(width: 1200, alignment: .leading)
        .background(RoundedRectangle(cornerRadius: 24, style: .continuous).fill(Color.black.opacity(0.34)))
        .overlay(RoundedRectangle(cornerRadius: 24, style: .continuous).stroke(Color.white.opacity(0.12), lineWidth: 1))
    }

    private var rowList: some View {
        ScrollView(.vertical, showsIndicators: true) {
            LazyVStack(spacing: 10) {
                ForEach(Array(draftRows.enumerated()), id: \.element.id) { index, row in
                    catalogRow(row, index: index)
                }
            }
            .padding(.trailing, 18)
            .padding(.bottom, 18)
        }
        .frame(width: 1700, height: 680, alignment: .topLeading)
    }

    private func catalogRow(_ row: BuiltInCatalogRowDescriptor, index: Int) -> some View {
        let isHidden = hiddenRowIDs.contains(row.id)
        return HStack(spacing: 16) {
            Text("\(index + 1)")
                .font(.system(size: 17, weight: .black, design: .monospaced))
                .foregroundStyle(.white.opacity(0.46))
                .frame(width: 48, alignment: .trailing)
            Text(row.title)
                .font(.system(size: 23, weight: .bold, design: .rounded))
                .foregroundStyle(isHidden ? Color.white.opacity(0.42) : Color.white)
                .lineLimit(1)
                .frame(maxWidth: .infinity, alignment: .leading)
            Button(isHidden ? "Off" : "On") {
                if isHidden {
                    hiddenRowIDs.remove(row.id)
                } else {
                    hiddenRowIDs.insert(row.id)
                }
                hasChanges = true
            }
            .buttonStyle(.bordered)
            .focused($focusedControl, equals: .visibility(row.id))
            .signalMoveCommand { direction in
                routeCustomizationMove(direction, from: .visibility(row.id), rowIndex: index)
            }
            Button("Move to Top") { moveRowToTop(from: index) }
                .buttonStyle(.bordered)
                .disabled(index == 0)
                .focused($focusedControl, equals: .moveTop(row.id))
                .signalMoveCommand { direction in
                    routeCustomizationMove(direction, from: .moveTop(row.id), rowIndex: index)
                }
            Button("Move Up") { moveRow(from: index, offset: -1) }
                .buttonStyle(.bordered)
                .disabled(index == 0)
                .focused($focusedControl, equals: .moveUp(row.id))
                .signalMoveCommand { direction in
                    routeCustomizationMove(direction, from: .moveUp(row.id), rowIndex: index)
                }
            Button("Move Down") { moveRow(from: index, offset: 1) }
                .buttonStyle(.bordered)
                .disabled(index >= draftRows.count - 1)
                .focused($focusedControl, equals: .moveDown(row.id))
                .signalMoveCommand { direction in
                    routeCustomizationMove(direction, from: .moveDown(row.id), rowIndex: index)
                }
        }
        .padding(.horizontal, 20)
        .frame(width: 1660, height: 72)
        .background(RoundedRectangle(cornerRadius: 16, style: .continuous).fill(Color.white.opacity(isHidden ? 0.035 : 0.07)))
        .overlay(RoundedRectangle(cornerRadius: 16, style: .continuous).stroke(Color.white.opacity(0.10), lineWidth: 1))
    }

    private var footerControls: some View {
        HStack(spacing: 16) {
            Button("Apply Changes") {
                store.commitBuiltInCatalogCustomization(
                    hiddenRowIDs: hiddenRowIDs,
                    orderedRowIDs: draftRows.map(\.id)
                )
                dismiss()
            }
            .buttonStyle(.borderedProminent)
            .disabled(!hasChanges)
            .focused($focusedControl, equals: .apply)
            .signalMoveCommand { direction in
                routeFooterMove(direction, from: .apply)
            }

            Button("Reset Default Order") {
                draftRows = officialDefaultRows
                hasChanges = true
            }
            .buttonStyle(.bordered)
            .focused($focusedControl, equals: .reset)
            .signalMoveCommand { direction in
                routeFooterMove(direction, from: .reset)
            }

            Button("Cancel") { dismiss() }
                .buttonStyle(.bordered)
                .focused($focusedControl, equals: .cancel)
                .signalMoveCommand { direction in
                    routeFooterMove(direction, from: .cancel)
                }
        }
    }

    private func loadDraftIfAvailable(force: Bool) {
        guard force || !hasLoadedDraft else { return }
        let snapshot = store.builtInCatalogCustomizationSnapshot()
        guard !snapshot.rows.isEmpty else { return }
        draftRows = snapshot.rows
        officialDefaultRows = store.catalogCustomizationDefaultRows()
        hiddenRowIDs = snapshot.hiddenRowIDs
        hasLoadedDraft = true
        hasChanges = false
        if focusedControl == nil, let first = draftRows.first {
            DispatchQueue.main.async {
                self.focusedControl = .visibility(first.id)
            }
        }
    }

    private func routeCustomizationMove(
        _ direction: SignalMoveDirection,
        from control: CustomizationFocus,
        rowIndex: Int
    ) {
        UnityAnimationCoordinator.shared.registerNavigationActivity(source: "settings-catalog-customization", settleAfter: 0.18)
        guard draftRows.indices.contains(rowIndex) else { return }
        let row = draftRows[rowIndex]
        let isFirst = rowIndex == 0
        let isLast = rowIndex == draftRows.count - 1

        switch direction {
        case .left:
            switch control {
            case .visibility:
                // Required shortcut: LEFT from the first On/Off chip enters the
                // footer action section. After edits, Apply Changes is the target.
                if isFirst { focusedControl = hasChanges ? .apply : .reset }
            case .moveTop:
                focusedControl = .visibility(row.id)
            case .moveUp:
                focusedControl = indexCanMoveUp(rowIndex) ? .moveTop(row.id) : .visibility(row.id)
            case .moveDown:
                focusedControl = indexCanMoveUp(rowIndex) ? .moveUp(row.id) : .visibility(row.id)
            default:
                break
            }
        case .right:
            switch control {
            case .visibility:
                focusedControl = indexCanMoveUp(rowIndex) ? .moveTop(row.id) : (indexCanMoveDown(rowIndex) ? .moveDown(row.id) : .visibility(row.id))
            case .moveTop:
                focusedControl = indexCanMoveUp(rowIndex) ? .moveUp(row.id) : .moveTop(row.id)
            case .moveUp:
                focusedControl = indexCanMoveDown(rowIndex) ? .moveDown(row.id) : .moveUp(row.id)
            case .moveDown:
                break
            default:
                break
            }
        case .up:
            guard !isFirst else { return }
            focusSameColumn(as: control, rowIndex: rowIndex - 1)
        case .down:
            if isLast {
                focusedControl = hasChanges ? .apply : .reset
            } else {
                focusSameColumn(as: control, rowIndex: rowIndex + 1)
            }
        default:
            break
        }
    }

    private func routeFooterMove(_ direction: SignalMoveDirection, from control: CustomizationFocus) {
        UnityAnimationCoordinator.shared.registerNavigationActivity(source: "settings-catalog-customization", settleAfter: 0.18)
        switch direction {
        case .left:
            switch control {
            case .apply: focusedControl = .cancel
            case .reset: focusedControl = hasChanges ? .apply : .cancel
            case .cancel: focusedControl = .reset
            default: break
            }
        case .right:
            switch control {
            case .apply: focusedControl = .reset
            case .reset: focusedControl = .cancel
            case .cancel: focusedControl = hasChanges ? .apply : .reset
            default: break
            }
        case .up:
            guard let last = draftRows.last else { return }
            focusedControl = .visibility(last.id)
        default:
            break
        }
    }

    private func focusSameColumn(as control: CustomizationFocus, rowIndex: Int) {
        guard draftRows.indices.contains(rowIndex) else { return }
        let target = draftRows[rowIndex]
        switch control {
        case .visibility:
            focusedControl = .visibility(target.id)
        case .moveTop:
            focusedControl = indexCanMoveUp(rowIndex) ? .moveTop(target.id) : .visibility(target.id)
        case .moveUp:
            focusedControl = indexCanMoveUp(rowIndex) ? .moveUp(target.id) : .visibility(target.id)
        case .moveDown:
            focusedControl = indexCanMoveDown(rowIndex) ? .moveDown(target.id) : (indexCanMoveUp(rowIndex) ? .moveUp(target.id) : .visibility(target.id))
        default:
            focusedControl = .visibility(target.id)
        }
    }

    private func indexCanMoveUp(_ index: Int) -> Bool { index > 0 }
    private func indexCanMoveDown(_ index: Int) -> Bool { index >= 0 && index < draftRows.count - 1 }

    private func moveRowToTop(from index: Int) {
        guard draftRows.indices.contains(index), index > 0 else { return }
        let row = draftRows.remove(at: index)
        draftRows.insert(row, at: 0)
        hasChanges = true
        // The Move to Top control becomes disabled at index zero; keep focus on the
        // same row's enabled On/Off chip instead of handing tvOS a disabled focus target.
        focusedControl = .visibility(row.id)
    }

    private func moveRow(from index: Int, offset: Int) {
        let destination = index + offset
        guard draftRows.indices.contains(index), draftRows.indices.contains(destination) else { return }
        let row = draftRows.remove(at: index)
        draftRows.insert(row, at: destination)
        hasChanges = true
    }
}

struct SettingsControlCenterBackdrop: View, Equatable {
    static func == (lhs: SettingsControlCenterBackdrop, rhs: SettingsControlCenterBackdrop) -> Bool { true }
    // vBRDC334: a decorative Settings canvas must never subscribe to process-wide UNITY state.
    // SettingsScreen remounts it when Settings itself changes; background runtime publications
    // no longer redraw a full-screen Canvas behind active focus movement.
    private let unityCore = UnityAppCore.shared

    static func accent(for title: String) -> Color {
        let key = title.lowercased()
        if key.contains("appearance") { return Color(red: 0.66, green: 0.42, blue: 1.0) }
        if key.contains("live") { return .cyan }
        if key.contains("sport") { return Color(red: 0.30, green: 0.90, blue: 0.72) }
        if key.contains("catalog") { return Color(red: 0.24, green: 0.62, blue: 1.0) }
        if key.contains("player") { return Color(red: 1.0, green: 0.40, blue: 0.28) }
        if key.contains("source") { return Color(red: 0.50, green: 0.68, blue: 1.0) }
        if key.contains("alert") { return Color(red: 1.0, green: 0.76, blue: 0.22) }
        return Color(red: 0.98, green: 0.60, blue: 0.24)
    }

    var body: some View {
        let palette = unityCore.palette
        Canvas(rendersAsynchronously: true) { context, size in
            let bounds = CGRect(origin: .zero, size: size)
            context.fill(Path(bounds), with: .linearGradient(
                Gradient(colors: palette.backgroundGradient),
                startPoint: CGPoint(x: 0, y: 0),
                endPoint: CGPoint(x: size.width, y: size.height)
            ))

            let glows: [(CGPoint, CGFloat, Color, Double)] = [
                (CGPoint(x: size.width * 0.18, y: size.height * 0.14), size.width * 0.34, palette.accent, palette.isPureBlack ? 0.0 : 0.070),
                (CGPoint(x: size.width * 0.78, y: size.height * 0.24), size.width * 0.30, palette.accent, palette.isPureBlack ? 0.0 : 0.040),
                (CGPoint(x: size.width * 0.58, y: size.height * 0.88), size.width * 0.36, Color.white, palette.isPureBlack ? 0.0 : 0.022)
            ]
            for glow in glows {
                context.fill(Path(ellipseIn: CGRect(x: glow.0.x - glow.1 * 0.5, y: glow.0.y - glow.1 * 0.5, width: glow.1, height: glow.1)), with: .radialGradient(
                    Gradient(colors: [glow.2.opacity(glow.3), Color.clear]),
                    center: glow.0,
                    startRadius: 0,
                    endRadius: glow.1 * 0.5
                ))
            }

            let lineColor = Color.white.opacity(0.022)
            for index in 1..<9 {
                let y = size.height * CGFloat(index) / 9.0
                var line = Path(); line.move(to: CGPoint(x: 0, y: y)); line.addLine(to: CGPoint(x: size.width, y: y))
                context.stroke(line, with: .color(lineColor), lineWidth: 1)
            }
        }
        .overlay(
            LinearGradient(colors: [Color.black.opacity(0.02), Color.clear, Color.black.opacity(0.30)], startPoint: .top, endPoint: .bottom)
        )
        .allowsHitTesting(false)
    }
}

struct SettingsCategoryCard: View, Equatable {
    let category: SettingsScreen.SettingsCategory
    let selected: Bool
    let focused: Bool
    let action: () -> Void

    static func == (lhs: SettingsCategoryCard, rhs: SettingsCategoryCard) -> Bool {
        lhs.category == rhs.category && lhs.selected == rhs.selected && lhs.focused == rhs.focused
    }

    private var accent: Color {
        switch category {
        case .general: return Color(red: 0.98, green: 0.60, blue: 0.24)
        case .appearance: return Color(red: 0.66, green: 0.42, blue: 1.0)
        case .liveTV: return Color.cyan
        case .streamingCatalogs: return Color(red: 0.24, green: 0.62, blue: 1.0)
        case .mediaFlowProxy: return Color(red: 0.20, green: 0.82, blue: 0.95)
        case .backupStreaming: return Color(red: 1.0, green: 0.82, blue: 0.10)
        case .catalogHealth: return Color(red: 0.25, green: 0.88, blue: 0.58)
        case .vodPlayer: return Color(red: 1.0, green: 0.40, blue: 0.28)
        case .sourceIntelligence: return Color(red: 0.50, green: 0.68, blue: 1.0)
        case .newEpisodeAlerts: return Color(red: 1.0, green: 0.76, blue: 0.22)
        case .sports: return Color(red: 0.30, green: 0.90, blue: 0.72)
        case .backupRestore: return Color(red: 0.74, green: 0.80, blue: 0.90)
        }
    }

    private var fillColor: Color {
        if focused { return Color.white.opacity(0.92) }
        if selected { return accent.opacity(0.15) }
        return Color.white.opacity(0.052)
    }

    private var strokeColor: Color {
        if focused { return Color.white.opacity(0.96) }
        if selected { return accent.opacity(0.55) }
        return Color.white.opacity(0.085)
    }

    var body: some View {
        HStack(spacing: 12) {
            ZStack {
                RoundedRectangle(cornerRadius: 10, style: .continuous)
                    .fill(focused ? accent.opacity(0.16) : accent.opacity(selected ? 0.17 : 0.10))
                if category == .backupStreaming {
                    Text("🔌")
                        .font(.system(size: 21, weight: .black))
                        .foregroundStyle(focused ? Color.black.opacity(0.80) : accent.opacity(0.96))
                } else {
                    Image(systemName: category.icon)
                        .font(.system(size: 20, weight: .black))
                        .foregroundStyle(focused ? Color.black.opacity(0.80) : accent.opacity(0.96))
                }
            }
            .frame(width: 38, height: 38)
            VStack(alignment: .leading, spacing: 3) {
                Text(category.rawValue)
                    .font(.system(size: 20, weight: .black, design: .rounded))
                    .foregroundStyle(focused ? Color.black.opacity(0.92) : Color.white)
                    .lineLimit(1)
                Text(category.subtitle)
                    .font(.system(size: 11, weight: .bold, design: .rounded))
                    .foregroundStyle(focused ? Color.black.opacity(0.56) : Color.white.opacity(0.46))
                    .lineLimit(1)
            }
            Spacer(minLength: 0)
        }
        .padding(.horizontal, 16)
        .frame(width: 238, height: 86, alignment: .leading)
        .background(RoundedRectangle(cornerRadius: 18, style: .continuous).fill(fillColor))
        .overlay(RoundedRectangle(cornerRadius: 18, style: .continuous).stroke(strokeColor, lineWidth: focused ? 2 : 1))
        .overlay(alignment: .bottomLeading) {
            Capsule().fill(selected || focused ? accent : Color.clear).frame(width: 48, height: 3).padding(.leading, 16).padding(.bottom, 7)
        }
        .clipShape(RoundedRectangle(cornerRadius: 18, style: .continuous))
        .contentShape(RoundedRectangle(cornerRadius: 18, style: .continuous))
        .scaleEffect(focused ? 1.045 : 1.0)
        .shadow(color: focused ? accent.opacity(0.20) : Color.clear, radius: 18, y: 6)
        .onTapGesture(perform: action)
        .signalVisionFocusEffectPolicy()
        .modifier(SettingsRoundedFocusVisual(cornerRadius: 18))
    }
}

