struct PopupFontPickerGrid: View {
    @Binding var selectedPreset: String

    private var columns: [GridItem] {
        [GridItem(.flexible(), spacing: 8), GridItem(.flexible(), spacing: 8)]
    }

    private func select(_ preset: PopupFontPreset) {
        selectedPreset = preset.id
        UserDefaults.standard.set(preset.id, forKey: "popupFontPreset")
    }

    var body: some View {
        LazyVGrid(columns: columns, alignment: .leading, spacing: 8) {
            ForEach(PopupTypography.presets) { preset in
                PopupFontChoiceButton(preset: preset, selected: selectedPreset == preset.id) {
                    select(preset)
                }
            }
        }
        .padding(.top, 4)
    }
}

struct PopupFontChoiceButton: View {
    let preset: PopupFontPreset
    let selected: Bool
    let action: () -> Void
    @FocusState private var focused: Bool

    private var fill: Color {
        if selected { return Color.cyan.opacity(0.95) }
        if focused { return Color.orange.opacity(0.82) }
        return Color.white.opacity(0.085)
    }

    private var stroke: Color {
        if selected { return Color.white.opacity(0.92) }
        if focused { return Color.orange.opacity(0.95) }
        return Color.white.opacity(0.10)
    }

    var body: some View {
        Button(action: action) {
            HStack(spacing: 10) {
                Image(systemName: selected ? "checkmark.circle.fill" : "textformat")
                    .font(.system(size: 15, weight: .black))
                    .frame(width: 20)
                VStack(alignment: .leading, spacing: 2) {
                    Text(preset.title)
                        .font(PopupTypography.font(preset.id, size: 15, weight: .black))
                        .lineLimit(1)
                    Text(preset.category.uppercased())
                        .font(.system(size: 9, weight: .black, design: .rounded))
                        .foregroundStyle((selected || focused) ? Color.black.opacity(0.62) : Color.white.opacity(0.52))
                        .lineLimit(1)
                }
                Spacer(minLength: 0)
            }
            .foregroundStyle((selected || focused) ? Color.black : Color.white)
            .padding(.horizontal, 12)
            .padding(.vertical, 10)
            .frame(height: 56)
            .contentShape(RoundedRectangle(cornerRadius: 14))
            .background(RoundedRectangle(cornerRadius: 14).fill(fill))
            .overlay(RoundedRectangle(cornerRadius: 14).stroke(stroke, lineWidth: (selected || focused) ? 2 : 1))
            .shadow(color: focused ? Color.orange.opacity(0.30) : Color.clear, radius: 14, y: 4)
        }
        .buttonStyle(.plain)
        .focused($focused)
        .modifier(SettingsRoundedFocusVisual(cornerRadius: 14))
        .onTapGesture { action() }
    }
}


struct MainGridBackgroundStyle {
    static let presets = [
        "Midnight Graphite", "Pure Black", "Deep Navy", "Ocean Blue", "Steel Blue",
        "Slate", "Charcoal", "Forest", "Deep Teal", "Emerald Night", "Royal Purple",
        "Plum", "Burgundy", "Deep Red", "Espresso", "Warm Bronze", "Soft Graphite", "Cinema Blue"
    ]

    static func gradientColors(for preset: String) -> [Color] {
        switch preset.lowercased() {
        case let key where key.contains("pure black"):
            return [.black, .black, .black]
        case let key where key.contains("deep navy"):
            return [Color(red: 0.008, green: 0.018, blue: 0.052), Color(red: 0.018, green: 0.050, blue: 0.120), .black]
        case let key where key.contains("ocean"):
            return [Color(red: 0.006, green: 0.030, blue: 0.060), Color(red: 0.010, green: 0.105, blue: 0.160), Color(red: 0.005, green: 0.020, blue: 0.040)]
        case let key where key.contains("steel blue"):
            return [Color(red: 0.025, green: 0.045, blue: 0.070), Color(red: 0.080, green: 0.135, blue: 0.190), Color(red: 0.012, green: 0.022, blue: 0.035)]
        case let key where key == "slate":
            return [Color(red: 0.025, green: 0.032, blue: 0.042), Color(red: 0.095, green: 0.115, blue: 0.140), Color(red: 0.015, green: 0.020, blue: 0.026)]
        case let key where key.contains("charcoal"):
            return [Color(red: 0.020, green: 0.020, blue: 0.023), Color(red: 0.075, green: 0.078, blue: 0.084), Color(red: 0.012, green: 0.012, blue: 0.014)]
        case let key where key == "forest":
            return [Color(red: 0.004, green: 0.028, blue: 0.020), Color(red: 0.018, green: 0.100, blue: 0.070), Color(red: 0.004, green: 0.018, blue: 0.015)]
        case let key where key.contains("deep teal"):
            return [Color(red: 0.004, green: 0.030, blue: 0.035), Color(red: 0.010, green: 0.105, blue: 0.110), Color(red: 0.004, green: 0.020, blue: 0.024)]
        case let key where key.contains("emerald"):
            return [Color(red: 0.004, green: 0.028, blue: 0.020), Color(red: 0.010, green: 0.125, blue: 0.075), Color(red: 0.004, green: 0.018, blue: 0.012)]
        case let key where key.contains("royal purple"):
            return [Color(red: 0.020, green: 0.010, blue: 0.045), Color(red: 0.095, green: 0.035, blue: 0.170), Color(red: 0.012, green: 0.006, blue: 0.026)]
        case let key where key == "plum":
            return [Color(red: 0.030, green: 0.010, blue: 0.032), Color(red: 0.125, green: 0.035, blue: 0.105), Color(red: 0.018, green: 0.006, blue: 0.018)]
        case let key where key.contains("burgundy"):
            return [Color(red: 0.035, green: 0.006, blue: 0.012), Color(red: 0.130, green: 0.025, blue: 0.045), Color(red: 0.020, green: 0.004, blue: 0.008)]
        case let key where key.contains("deep red"):
            return [Color(red: 0.040, green: 0.004, blue: 0.006), Color(red: 0.155, green: 0.020, blue: 0.022), Color(red: 0.022, green: 0.003, blue: 0.004)]
        case let key where key.contains("espresso"):
            return [Color(red: 0.028, green: 0.018, blue: 0.014), Color(red: 0.105, green: 0.060, blue: 0.038), Color(red: 0.018, green: 0.012, blue: 0.010)]
        case let key where key.contains("bronze"):
            return [Color(red: 0.030, green: 0.020, blue: 0.010), Color(red: 0.140, green: 0.078, blue: 0.025), Color(red: 0.020, green: 0.012, blue: 0.006)]
        case let key where key.contains("soft graphite"):
            return [Color(red: 0.028, green: 0.032, blue: 0.040), Color(red: 0.105, green: 0.115, blue: 0.130), Color(red: 0.018, green: 0.020, blue: 0.025)]
        case let key where key.contains("cinema blue"):
            return [Color(red: 0.008, green: 0.018, blue: 0.040), Color(red: 0.025, green: 0.085, blue: 0.165), Color(red: 0.012, green: 0.010, blue: 0.022)]
        default:
            return [Color(red: 0.014, green: 0.017, blue: 0.024), Color(red: 0.050, green: 0.060, blue: 0.078), Color(red: 0.008, green: 0.010, blue: 0.014)]
        }
    }

    static func swatch(for preset: String) -> Color {
        gradientColors(for: preset).dropFirst().first ?? Color.gray
    }
}

struct VisualPerformanceProfile {
    static let modes = ["Compatibility", "Balanced", "High Performance"]

    static func normalized(_ raw: String) -> String {
        modes.first(where: { $0.caseInsensitiveCompare(raw) == .orderedSame }) ?? "Compatibility"
    }

    static func framesPerSecond(for raw: String) -> Double {
        switch normalized(raw) {
        // vBRDC084 UNITY frame budget: preserve the exact visual/detail presets while
        // capping perpetual wallpaper redraw frequency below the tvOS focus compositor.
        // The wallpaper remains continuous and full-resolution; only redundant redraws
        // are reduced so D-pad focus, artwork, Pulse and previews retain priority.
        case "High Performance": return 16.0
        case "Balanced": return 12.0
        default: return 8.0
        }
    }

    static func detailLevel(for raw: String) -> Int {
        switch normalized(raw) {
        case "High Performance": return 3
        case "Balanced": return 2
        default: return 1
        }
    }

    static func accent(for raw: String) -> Color {
        switch normalized(raw) {
        case "High Performance": return .green
        case "Balanced": return .cyan
        default: return .orange
        }
    }

    static func subtitle(for raw: String) -> String {
        switch normalized(raw) {
        case "High Performance":
            return "16 fps full-resolution wallpaper motion with richer Canvas detail. UNITY reserves the remaining compositor budget for focus, previews and artwork, then fully suspends wallpaper work for playback and covered surfaces."
        case "Balanced":
            return "12 fps full-resolution wallpaper motion with moderate Canvas detail. It remains continuously animated while browsing Live TV without competing with the tvOS focus engine."
        default:
            return "Compatibility keeps the lightweight v1152 architecture: 8 fps asynchronous Canvas, conservative detail, and no expensive live blur stacks. Wallpaper now remains continuous while browsing channels and suspends only when Live TV no longer owns the screen."
        }
    }
}

struct DynamicMainGridWallpaperStyle {
    // vBRDC079: curated procedural wallpaper library. The old 48-preset collection had
    // many near-duplicate smoke/projector variants; this list intentionally favors
    // distinct motion families while retaining only the strongest cinema presets.
    static let presets = [
        "Digital Rain",
        "Emerald Code",
        "Cyber Rain",
        "Falling Stars",
        "Deep Galaxy",
        "Warp Space",
        "Cosmic Dust",
        "Aurora",
        "Meteor Shower",
        "Black Hole",
        "Constellations",
        "Nexus Lines",
        "Neon Grid",
        "Data Grid",
        "Electric Storm",
        "Fire Embers",
        "Snowfall",
        "Rain on Glass",
        "Underwater",
        "OLED Particles",
        "Spotlight Smoke",
        "Cinematic Smoke",
        "Cinema Projector",
        "Black Velvet Smoke",
        "OLED Cinema",
        "Midnight Smoke"
    ]

    static func normalized(_ raw: String) -> String {
        if let exact = presets.first(where: { $0.caseInsensitiveCompare(raw) == .orderedSame }) { return exact }
        let key = raw.lowercased()
        if key.contains("starfield") { return "Falling Stars" }
        if key.contains("nebula") || key.contains("cosmic") || key.contains("deep space") { return "Deep Galaxy" }
        if key.contains("matrix") || key.contains("grid") { return "Data Grid" }
        if key.contains("nexus") { return "Nexus Lines" }
        if key.contains("aurora") { return "Aurora" }
        if key.contains("ember") { return "Fire Embers" }
        if key.contains("spotlight") { return "Spotlight Smoke" }
        if key.contains("projector") || key.contains("projection") { return "Cinema Projector" }
        if key.contains("black velvet") { return "Black Velvet Smoke" }
        if key.contains("oled") { return "OLED Cinema" }
        if key.contains("midnight smoke") || key.contains("charcoal") || key.contains("noir") { return "Midnight Smoke" }
        return "Cinematic Smoke"
    }

    static func family(for preset: String) -> String {
        switch normalized(preset) {
        case "Digital Rain", "Emerald Code", "Cyber Rain": return "digitalRain"
        case "Falling Stars": return "fallingStars"
        case "Deep Galaxy": return "galaxy"
        case "Warp Space": return "warp"
        case "Cosmic Dust": return "cosmicDust"
        case "Aurora": return "aurora"
        case "Meteor Shower": return "meteor"
        case "Black Hole": return "blackHole"
        case "Constellations": return "constellation"
        case "Nexus Lines": return "nexusLines"
        case "Neon Grid": return "neonGrid"
        case "Data Grid": return "dataGrid"
        case "Electric Storm": return "electricStorm"
        case "Fire Embers": return "embers"
        case "Snowfall": return "snow"
        case "Rain on Glass": return "rainGlass"
        case "Underwater": return "underwater"
        case "OLED Particles": return "oledParticles"
        case "Spotlight Smoke": return "spotlight"
        case "Cinema Projector": return "projector"
        case "OLED Cinema": return "theater"
        default: return "smoke"
        }
    }

    static func colors(for preset: String) -> [Color] {
        switch normalized(preset) {
        case "Digital Rain": return [Color(red: 0.12, green: 1.00, blue: 0.38), Color(red: 0.02, green: 0.52, blue: 0.20), Color(red: 0.00, green: 0.20, blue: 0.08), .black]
        case "Emerald Code": return [Color(red: 0.28, green: 1.00, blue: 0.58), Color(red: 0.03, green: 0.68, blue: 0.30), Color(red: 0.01, green: 0.24, blue: 0.12), .black]
        case "Cyber Rain": return [.cyan, .purple, Color(red: 0.18, green: 0.36, blue: 1.0), .black]
        case "Falling Stars": return [.white, Color(red: 0.58, green: 0.78, blue: 1.0), .indigo, .black]
        case "Deep Galaxy": return [Color(red: 0.22, green: 0.38, blue: 1.0), .purple, Color(red: 0.86, green: 0.24, blue: 0.72), .black]
        case "Warp Space": return [.white, .cyan, Color(red: 0.30, green: 0.48, blue: 1.0), .black]
        case "Cosmic Dust": return [Color(red: 0.40, green: 0.58, blue: 1.0), .purple, .white, .black]
        case "Aurora": return [.cyan, .green, .purple, Color(red: 0.01, green: 0.04, blue: 0.10)]
        case "Meteor Shower": return [.white, Color(red: 0.46, green: 0.70, blue: 1.0), .orange, .black]
        case "Black Hole": return [.orange, Color(red: 1.0, green: 0.34, blue: 0.10), .purple, .black]
        case "Constellations": return [.white, Color(red: 0.38, green: 0.66, blue: 1.0), .cyan, .black]
        case "Nexus Lines": return [Color(red: 0.16, green: 1.00, blue: 0.28), Color(red: 0.12, green: 0.64, blue: 1.00), Color(red: 1.00, green: 0.16, blue: 0.28), Color(red: 1.00, green: 0.88, blue: 0.16)]
        case "Neon Grid": return [.cyan, .purple, .pink, .black]
        case "Data Grid": return [.cyan, Color(red: 0.10, green: 0.48, blue: 1.0), .white, .black]
        case "Electric Storm": return [Color(red: 0.62, green: 0.78, blue: 1.0), .purple, .white, Color(red: 0.01, green: 0.02, blue: 0.07)]
        case "Fire Embers": return [.orange, .red, .yellow, .black]
        case "Snowfall": return [.white, Color(red: 0.72, green: 0.88, blue: 1.0), .cyan, Color(red: 0.01, green: 0.03, blue: 0.07)]
        case "Rain on Glass": return [Color(red: 0.38, green: 0.68, blue: 1.0), .cyan, .white, Color(red: 0.01, green: 0.03, blue: 0.06)]
        case "Underwater": return [.cyan, Color(red: 0.02, green: 0.30, blue: 0.62), Color(red: 0.02, green: 0.62, blue: 0.58), Color(red: 0.00, green: 0.03, blue: 0.08)]
        case "OLED Particles": return [.white, .cyan, .purple, .black]
        case "Spotlight Smoke": return [.white, Color(red: 0.34, green: 0.48, blue: 0.68), .gray, .black]
        case "Cinema Projector": return [Color(red: 1.00, green: 0.82, blue: 0.55), .white, Color(red: 0.30, green: 0.36, blue: 0.46), .black]
        case "Black Velvet Smoke": return [Color(red: 0.16, green: 0.17, blue: 0.20), Color(red: 0.07, green: 0.08, blue: 0.10), Color(red: 0.23, green: 0.12, blue: 0.08), .black]
        case "OLED Cinema": return [Color(red: 0.10, green: 0.18, blue: 0.28), Color(red: 0.26, green: 0.12, blue: 0.06), Color(red: 0.03, green: 0.04, blue: 0.06), .black]
        case "Midnight Smoke": return [Color(red: 0.08, green: 0.12, blue: 0.20), Color(red: 0.12, green: 0.10, blue: 0.18), Color(red: 0.04, green: 0.06, blue: 0.10), .black]
        default: return [.white, .gray, Color(red: 0.30, green: 0.44, blue: 0.62), .black]
        }
    }
}

private actor DynamicWallpaperAssetCache {
    static let shared = DynamicWallpaperAssetCache()
    // vBRDC083: larger on-disk allowance for genuine UHD animated assets. Decoding remains
    // streaming/single-frame so the cache size does not translate into resident frame memory.
    private let maximumBytes: Int64 = 96 * 1024 * 1024
    private let allowedExtensions = Set(["gif", "webp", "mp4", "mov", "m4v"])

    func cachedAsset(for rawURL: String) async -> URL? {
        let trimmed = rawURL.trimmingCharacters(in: .whitespacesAndNewlines)
        guard let remoteURL = URL(string: trimmed), remoteURL.scheme?.lowercased() == "https" else { return nil }

        let folder = FileManager.default.urls(for: .cachesDirectory, in: .userDomainMask)[0]
            .appendingPathComponent("DebridChannelsDynamicWallpaper", isDirectory: true)
        try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        let key = stableKey(trimmed)
        for ext in allowedExtensions {
            let existing = folder.appendingPathComponent("wallpaper_\(key).\(ext)")
            if let size = fileSize(existing), size > 0, size <= maximumBytes, isUsableAsset(existing) { return existing }
        }

        var request = URLRequest(url: remoteURL, cachePolicy: .reloadRevalidatingCacheData, timeoutInterval: 25)
        request.setValue("DebridChannels/tvOS DynamicWallpaper", forHTTPHeaderField: "User-Agent")
        do {
            let (temporaryURL, response) = try await URLSession.shared.download(for: request)
            guard let http = response as? HTTPURLResponse, (200...299).contains(http.statusCode) else { return nil }
            guard let size = fileSize(temporaryURL), size > 0, size <= maximumBytes else { return nil }
            guard let resolvedExtension = assetExtension(remoteURL: remoteURL, mimeType: response.mimeType),
                  allowedExtensions.contains(resolvedExtension) else { return nil }
            let destination = folder.appendingPathComponent("wallpaper_\(key).\(resolvedExtension)")
            for ext in allowedExtensions where ext != resolvedExtension {
                try? FileManager.default.removeItem(at: folder.appendingPathComponent("wallpaper_\(key).\(ext)"))
            }
            try? FileManager.default.removeItem(at: destination)
            try FileManager.default.moveItem(at: temporaryURL, to: destination)
            guard isUsableAsset(destination) else {
                try? FileManager.default.removeItem(at: destination)
                return nil
            }
            prune(folder: folder, keeping: destination)
            return destination
        } catch {
            return nil
        }
    }

    private func fileSize(_ url: URL) -> Int64? {
        let values = try? url.resourceValues(forKeys: [.fileSizeKey])
        return values?.fileSize.map(Int64.init)
    }

    private func isUsableAsset(_ url: URL) -> Bool {
        let ext = url.pathExtension.lowercased()
        if ext == "gif" || ext == "webp" {
            guard let source = CGImageSourceCreateWithURL(url as CFURL, nil) else { return false }
            return CGImageSourceGetCount(source) > 0
        }
        if ext == "mp4" || ext == "mov" || ext == "m4v" {
            // The file was already accepted by extension/MIME type and size. AVPlayer owns
            // final codec validation; do not synchronously probe media on the Live TV UI path.
            return true
        }
        return false
    }

    private func assetExtension(remoteURL: URL, mimeType: String?) -> String? {
        let ext = remoteURL.pathExtension.lowercased()
        if allowedExtensions.contains(ext) { return ext }
        switch mimeType?.lowercased() {
        case "image/gif": return "gif"
        case "image/webp": return "webp"
        case "video/quicktime": return "mov"
        case "video/x-m4v": return "m4v"
        case "video/mp4": return "mp4"
        default: return nil
        }
    }

    private func stableKey(_ value: String) -> String {
        var hash: UInt64 = 1469598103934665603
        for byte in value.utf8 {
            hash ^= UInt64(byte)
            hash &*= 1099511628211
        }
        return String(hash, radix: 16)
    }

    private func prune(folder: URL, keeping: URL) {
        guard let files = try? FileManager.default.contentsOfDirectory(at: folder, includingPropertiesForKeys: [.contentModificationDateKey], options: [.skipsHiddenFiles]) else { return }
        let extras = files.filter { $0 != keeping }.sorted {
            let lhs = (try? $0.resourceValues(forKeys: [.contentModificationDateKey]).contentModificationDate) ?? .distantPast
            let rhs = (try? $1.resourceValues(forKeys: [.contentModificationDateKey]).contentModificationDate) ?? .distantPast
            return lhs > rhs
        }
        for url in extras.dropFirst(2) { try? FileManager.default.removeItem(at: url) }
    }
}

private struct DynamicWallpaperSurface: View {
    let builtInStyle: String
    let performanceMode: String
    let paused: Bool
    let continuousWhileBrowsing: Bool
    let customEnabled: Bool
    let customURL: String
    @State private var cachedCustomURL: URL? = nil

    var body: some View {
        Group {
            if customEnabled, let cachedCustomURL {
                DynamicWallpaperLocalAssetView(url: cachedCustomURL, performanceMode: performanceMode, paused: paused)
            } else {
                DynamicSmokeWallpaper(style: DynamicMainGridWallpaperStyle.normalized(builtInStyle), performanceMode: performanceMode, paused: paused, continuousWhileBrowsing: continuousWhileBrowsing)
            }
        }
        .task(id: customTaskIdentity) {
            cachedCustomURL = nil
            guard customEnabled, !customURL.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return }
            cachedCustomURL = await DynamicWallpaperAssetCache.shared.cachedAsset(for: customURL)
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }

    private var customTaskIdentity: String { "\(customEnabled)|\(customURL)" }
}

private struct DynamicWallpaperLocalAssetView: View {
    let url: URL
    let performanceMode: String
    let paused: Bool

    var body: some View {
        let ext = url.pathExtension.lowercased()
        Group {
            if ["mp4", "mov", "m4v"].contains(ext) {
                DynamicWallpaperLoopVideoView(url: url, paused: paused)
            } else {
                DynamicWallpaperAnimatedImageView(url: url, performanceMode: performanceMode, paused: paused)
            }
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .clipped()
        .allowsHitTesting(false)
    }
}

private final class DynamicWallpaperLoopPlayerUIView: UIView {
    override class var layerClass: AnyClass { AVPlayerLayer.self }
    private var queuePlayer: AVQueuePlayer?
    private var looper: AVPlayerLooper?
    private var configuredURL: URL?
    private var configuredPaused: Bool? = nil

    private var playerLayer: AVPlayerLayer { layer as! AVPlayerLayer }

    func configure(url: URL, paused: Bool) {
        if configuredURL != url {
            stop()
            configuredURL = url
            let item = AVPlayerItem(url: url)
            let player = AVQueuePlayer()
            player.isMuted = true
            player.actionAtItemEnd = .none
            playerLayer.videoGravity = .resizeAspectFill
            playerLayer.player = player
            queuePlayer = player
            looper = AVPlayerLooper(player: player, templateItem: item)
        }
        // vBRDC091: SwiftUI may update the wallpaper representable for unrelated Live TV
        // state. Do not re-issue AVPlayer play/pause commands unless ownership actually
        // changed; repeated play() calls during focus churn were needless player-thread work.
        if configuredPaused != paused {
            configuredPaused = paused
            if paused { queuePlayer?.pause() } else { queuePlayer?.play() }
        }
    }

    func stop() {
        queuePlayer?.pause()
        queuePlayer?.removeAllItems()
        playerLayer.player = nil
        looper = nil
        queuePlayer = nil
        configuredURL = nil
        configuredPaused = nil
    }
}

private struct DynamicWallpaperLoopVideoView: UIViewRepresentable {
    let url: URL
    let paused: Bool
    func makeUIView(context: Context) -> DynamicWallpaperLoopPlayerUIView { DynamicWallpaperLoopPlayerUIView() }
    func updateUIView(_ uiView: DynamicWallpaperLoopPlayerUIView, context: Context) { uiView.configure(url: url, paused: paused) }
    static func dismantleUIView(_ uiView: DynamicWallpaperLoopPlayerUIView, coordinator: ()) { uiView.stop() }
}

// vBRDC119: event-driven pause gate for streaming GIF/WebP wallpaper. The old
// decoder polled `isPaused` through MainActor every 45 ms while navigation owned the
// frame, waking the UI thread ~22 times/second even though the wallpaper was frozen.
// Continuations preserve the exact current frame/index with zero paused polling.
private final class DynamicWallpaperPauseGate: @unchecked Sendable {
    private let lock = NSLock()
    private var paused = false
    private var stopped = false
    private var waiters: [UUID: CheckedContinuation<Bool, Never>] = [:]

    func restart(paused: Bool) {
        lock.lock()
        let stale = Array(waiters.values)
        waiters.removeAll(keepingCapacity: true)
        stopped = false
        self.paused = paused
        lock.unlock()
        stale.forEach { $0.resume(returning: false) }
    }

    func setPaused(_ paused: Bool) {
        lock.lock()
        self.paused = paused
        let ready = !paused && !stopped ? Array(waiters.values) : []
        if !ready.isEmpty { waiters.removeAll(keepingCapacity: true) }
        lock.unlock()
        ready.forEach { $0.resume(returning: true) }
    }

    func stop() {
        lock.lock()
        stopped = true
        let pending = Array(waiters.values)
        waiters.removeAll(keepingCapacity: false)
        lock.unlock()
        pending.forEach { $0.resume(returning: false) }
    }

    func waitUntilRunning() async -> Bool {
        if Task.isCancelled { return false }
        let id = UUID()
        return await withTaskCancellationHandler(operation: {
            await withCheckedContinuation { continuation in
                lock.lock()
                if Task.isCancelled || stopped {
                    lock.unlock()
                    continuation.resume(returning: false)
                } else if !paused {
                    lock.unlock()
                    continuation.resume(returning: true)
                } else {
                    waiters[id] = continuation
                    lock.unlock()
                }
            }
        }, onCancel: {
            self.cancelWaiter(id)
        })
    }

    private func cancelWaiter(_ id: UUID) {
        lock.lock()
        let waiter = waiters.removeValue(forKey: id)
        lock.unlock()
        waiter?.resume(returning: false)
    }
}

private final class DynamicWallpaperAnimatedUIImageView: UIImageView {
    private var configuredURL: URL?
    private var decodeTask: Task<Void, Never>?
    private var configuredPerformanceMode: String = ""
    private var isPaused: Bool = false
    private var decoderGeneration: UInt64 = 0
    private let pauseGate = DynamicWallpaperPauseGate()

    func configure(url: URL, performanceMode: String, paused: Bool) {
        let normalizedMode = VisualPerformanceProfile.normalized(performanceMode)
        let identityChanged = configuredURL != url || configuredPerformanceMode != normalizedMode
        configuredURL = url
        configuredPerformanceMode = normalizedMode
        isPaused = paused

        if identityChanged {
            decoderGeneration &+= 1
            decodeTask?.cancel()
            decodeTask = nil
            image = nil
            pauseGate.restart(paused: paused)
        } else {
            pauseGate.setPaused(paused)
        }

        // vBRDC091: a navigation yield freezes the currently presented GIF/WebP frame
        // without cancelling the decoder or resetting its frame index. vBRDC090 cancelled
        // and restarted from frame zero on every D-pad burst, which looked like the
        // wallpaper was glitching backward even though the surface itself stayed mounted.
        // The streaming task now sleeps while paused and resumes from the exact same index.
        guard decodeTask == nil else { return }
        startStreamingAnimation(url: url, performanceMode: normalizedMode)
    }

    func stopAndRelease() {
        decoderGeneration &+= 1
        pauseGate.stop()
        decodeTask?.cancel()
        decodeTask = nil
        image = nil
        configuredURL = nil
        configuredPerformanceMode = ""
        isPaused = false
    }

    private func startStreamingAnimation(url: URL, performanceMode: String) {
        // Render to the actual output pixel envelope instead of the old 720/960px thumbnail.
        // On Apple TV 4K this is 3840px on the long edge; on HD hardware it naturally falls
        // back to 1920px. Only ONE decoded frame is retained at a time, keeping UHD GIF/WebP
        // wallpaper isolated from playback memory pressure.
        let screenLongEdge = Int(max(SignalVisionWindowMetrics.currentWindowBounds.width, SignalVisionWindowMetrics.currentWindowBounds.height))
        let nativePixelTarget = min(3840, max(1920, screenLongEdge))
        let maxFPS: Double
        switch performanceMode {
        // vBRDC084: UHD GIF/WebP keeps the native 3840-pixel envelope, but animation
        // cadence is deliberately bounded. Decoding 4K raster frames at 18-24 fps was
        // enough to starve tvOS focus/artwork even though only one frame was retained.
        // Resolution is unchanged; only decode frequency is reduced.
        case "High Performance": maxFPS = 10
        case "Balanced": maxFPS = 8
        default: maxFPS = 6
        }
        let minimumFrameDuration = 1.0 / maxFPS
        decoderGeneration &+= 1
        let generation = decoderGeneration

        decodeTask = Task.detached(priority: .background) { [weak self] in
            // vBRDC329: failed image-source creation and empty/corrupt files must
            // release the task ownership too. Otherwise configure() sees an
            // apparently active task and cannot retry this wallpaper.
            guard let source = CGImageSourceCreateWithURL(url as CFURL, [kCGImageSourceShouldCache: false] as CFDictionary) else {
                await MainActor.run {
                    guard let self, self.configuredURL == url, self.decoderGeneration == generation else { return }
                    self.decodeTask = nil
                }
                return
            }
            let count = CGImageSourceGetCount(source)
            guard count > 0 else {
                await MainActor.run {
                    guard let self, self.configuredURL == url, self.decoderGeneration == generation else { return }
                    self.decodeTask = nil
                }
                return
            }
            let options: [CFString: Any] = [
                kCGImageSourceCreateThumbnailFromImageAlways: true,
                kCGImageSourceThumbnailMaxPixelSize: nativePixelTarget,
                kCGImageSourceCreateThumbnailWithTransform: true,
                kCGImageSourceShouldCache: false,
                kCGImageSourceShouldCacheImmediately: false
            ]
            var index = 0
            while !Task.isCancelled {
                guard let self, await self.pauseGate.waitUntilRunning(), !Task.isCancelled else { break }

                let frame: UIImage? = autoreleasepool {
                    guard let cg = CGImageSourceCreateThumbnailAtIndex(source, index, options as CFDictionary) else { return nil }
                    return UIImage(cgImage: cg)
                }
                guard let frame else { break }

                var frameDuration: TimeInterval = 0.08
                if let props = CGImageSourceCopyPropertiesAtIndex(source, index, nil) as? [CFString: Any],
                   let gif = props[kCGImagePropertyGIFDictionary] as? [CFString: Any] {
                    let unclamped = gif[kCGImagePropertyGIFUnclampedDelayTime] as? Double
                    let clamped = gif[kCGImagePropertyGIFDelayTime] as? Double
                    frameDuration = unclamped ?? clamped ?? 0.08
                }
                frameDuration = max(minimumFrameDuration, max(0.03, frameDuration))

                await MainActor.run {
                    guard self.configuredURL == url, self.decoderGeneration == generation, !self.isPaused else { return }
                    self.image = frame
                }
                if Task.isCancelled || count == 1 { break }
                try? await Task.sleep(nanoseconds: UInt64(frameDuration * 1_000_000_000))
                index = (index + 1) % count
            }
            await MainActor.run {
                guard let self, self.configuredURL == url, self.decoderGeneration == generation else { return }
                self.decodeTask = nil
            }
        }
    }
}

private struct DynamicWallpaperAnimatedImageView: UIViewRepresentable {
    let url: URL
    let performanceMode: String
    let paused: Bool

    func makeUIView(context: Context) -> DynamicWallpaperAnimatedUIImageView {
        let view = DynamicWallpaperAnimatedUIImageView()
        view.contentMode = .scaleAspectFill
        view.clipsToBounds = true
        view.backgroundColor = .black
        return view
    }
    func updateUIView(_ uiView: DynamicWallpaperAnimatedUIImageView, context: Context) {
        uiView.configure(url: url, performanceMode: performanceMode, paused: paused)
    }
    static func dismantleUIView(_ uiView: DynamicWallpaperAnimatedUIImageView, coordinator: ()) { uiView.stopAndRelease() }
}

struct MainGridBackgroundView: View {
    let preset: String
    let dynamicEnabled: Bool
    let dynamicPreset: String

    var body: some View {
        ZStack {
            LinearGradient(
                colors: MainGridBackgroundStyle.gradientColors(for: preset),
                startPoint: .topLeading,
                endPoint: .bottomTrailing
            )
            if dynamicEnabled {
                DynamicSmokeWallpaper(style: DynamicMainGridWallpaperStyle.normalized(dynamicPreset), performanceMode: "Compatibility")
                    .transition(.opacity)
            }
            LinearGradient(
                colors: [Color.black.opacity(0.10), Color.clear, Color.black.opacity(0.30)],
                startPoint: .top,
                endPoint: .bottom
            )
        }
        .clipped()
        .allowsHitTesting(false)
    }
}

struct DynamicSmokeWallpaper: View {
    @ObservedObject private var unityAnimations = UnityAnimationCoordinator.shared
    let style: String
    let performanceMode: String
    let paused: Bool
    let continuousWhileBrowsing: Bool
    @State private var accumulatedPausedDuration: TimeInterval = 0
    @State private var pauseBeganAtReferenceTime: TimeInterval? = nil

    init(style: String, performanceMode: String = "Compatibility", paused: Bool = false, continuousWhileBrowsing: Bool = false) {
        self.style = style
        self.performanceMode = VisualPerformanceProfile.normalized(performanceMode)
        self.paused = paused
        self.continuousWhileBrowsing = continuousWhileBrowsing
    }

    var body: some View {
        let configuredFPS = VisualPerformanceProfile.framesPerSecond(for: performanceMode)
        // Visual Performance may change idle richness, but it must not change focus quality.
        // During a Siri Remote navigation burst keep the wallpaper moving at a low cadence
        // instead of competing with the 60 Hz focus/system compositor.
        let navigationBusy = unityAnimations.navigationBurstActive || unityAnimations.postNavigationVisualRecoveryActive || unityAnimations.surfaceHandoffActive
        // Only the interactive Live TV grid keeps visibly moving through scroll bursts.
        // Cap the compositor updates rather than mounting a second wallpaper player.
        let effectiveFPS = continuousWhileBrowsing
            ? (navigationBusy ? min(20.0, max(18.0, configuredFPS)) : configuredFPS)
            : (navigationBusy ? min(configuredFPS, 6.0) : configuredFPS)
        let detailLevel = navigationBusy && !continuousWhileBrowsing
            ? 1 : VisualPerformanceProfile.detailLevel(for: performanceMode)
        TimelineView(.animation(minimumInterval: 1.0 / effectiveFPS, paused: paused)) { timeline in
            let rawReferenceTime = timeline.date.timeIntervalSinceReferenceDate
            // vBRDC091 phase lock: subtract time spent yielded to Siri Remote navigation.
            // TimelineView used an absolute clock in vBRDC090, so resuming after a freeze
            // jumped the procedural wallpaper forward by the whole pause interval.
            let t = (pauseBeganAtReferenceTime ?? rawReferenceTime) - accumulatedPausedDuration
            let colors = DynamicMainGridWallpaperStyle.colors(for: style)
            Canvas(rendersAsynchronously: true) { context, size in
                renderWallpaper(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel)
            }
            .blendMode(.screen)
            .saturation(1.16)
            .brightness(0.08)
            .contrast(1.08)
            .opacity(detailLevel == 1 ? 0.86 : (detailLevel == 2 ? 0.91 : 0.95))
        }
        .onAppear {
            if paused, pauseBeganAtReferenceTime == nil {
                pauseBeganAtReferenceTime = Date().timeIntervalSinceReferenceDate
            }
        }
        .onChange(of: paused) { _, nowPaused in
            let now = Date().timeIntervalSinceReferenceDate
            if nowPaused {
                if pauseBeganAtReferenceTime == nil { pauseBeganAtReferenceTime = now }
            } else if let began = pauseBeganAtReferenceTime {
                accumulatedPausedDuration += max(0, now - began)
                pauseBeganAtReferenceTime = nil
            }
        }
        .allowsHitTesting(false)
        .accessibilityHidden(true)
    }

    private func renderWallpaper(
        context: inout GraphicsContext,
        size: CGSize,
        t: TimeInterval,
        colors: [Color],
        detailLevel: Int
    ) {
        let family = DynamicMainGridWallpaperStyle.family(for: style)

        switch family {
        case "digitalRain":
            drawDigitalRain(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel)

        case "fallingStars":
            drawFallingStars(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel)

        case "galaxy":
            drawGalaxy(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel)

        case "warp":
            drawWarpSpace(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel)

        case "cosmicDust":
            drawCosmicDust(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel)

        case "aurora":
            drawAurora(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel)

        case "meteor":
            drawStars(context: &context, size: size, t: t, count: detailLevel == 3 ? 64 : 38)
            drawMeteorShower(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel)

        case "blackHole":
            drawBlackHole(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel)

        case "constellation":
            drawConstellations(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel)

        case "nexusLines":
            drawNexusLines(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel)

        case "neonGrid":
            drawPerspectiveGrid(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel, neon: true)

        case "dataGrid":
            drawPerspectiveGrid(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel, neon: false)
            drawDataParticles(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel)

        case "electricStorm":
            drawElectricStorm(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel)

        case "embers":
            drawEmbers(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel)

        case "snow":
            drawSnow(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel)

        case "rainGlass":
            drawRainOnGlass(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel)

        case "underwater":
            drawUnderwater(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel)

        case "oledParticles":
            drawOLEDParticles(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel)

        case "spotlight":
            drawSmokeFields(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel, opacityScale: 1.0)
            drawSpotlight(context: &context, size: size, t: t, color: Color.white, direction: -1, intensity: 0.28)
            drawSpotlight(context: &context, size: size, t: t + 2.2, color: colors[1], direction: 1, intensity: 0.24)
            if detailLevel >= 2 { drawDust(context: &context, size: size, t: t, count: detailLevel == 3 ? 34 : 18) }

        case "projector":
            drawSmokeFields(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel, opacityScale: 0.72)
            drawProjectorBeam(context: &context, size: size, t: t, colors: colors)
            drawDust(context: &context, size: size, t: t, count: detailLevel == 3 ? 42 : (detailLevel == 2 ? 26 : 14))

        case "theater":
            drawSmokeFields(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel, opacityScale: 0.78)
            drawSpotlight(context: &context, size: size, t: t, color: colors[0], direction: -1, intensity: 0.22)
            drawSpotlight(context: &context, size: size, t: t + 1.3, color: colors[1], direction: 1, intensity: 0.20)
            drawMarqueeEdgeGlow(context: &context, size: size, t: t, color: colors[0])

        case "broadcast":
            drawSmokeFields(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel, opacityScale: 0.48)
            drawBroadcastBands(context: &context, size: size, t: t, colors: colors, count: detailLevel == 3 ? 7 : 5)
            drawSignalLines(context: &context, size: size, t: t, color: colors[1], count: detailLevel == 1 ? 3 : 5)

        case "signal":
            drawSignalLines(context: &context, size: size, t: t, color: colors[0], count: detailLevel == 3 ? 9 : (detailLevel == 2 ? 7 : 5))
            drawBroadcastBands(context: &context, size: size, t: t * 0.72, colors: colors, count: detailLevel == 3 ? 6 : 4)
            if detailLevel >= 2 { drawDust(context: &context, size: size, t: t, count: 16) }

        case "newsroom":
            drawStudioPanels(context: &context, size: size, t: t, left: colors[0], right: colors[1], detailLevel: detailLevel)
            drawSignalLines(context: &context, size: size, t: t, color: Color.white, count: 3)

        case "sports":
            drawSmokeFields(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel, opacityScale: 0.55)
            drawSpotlight(context: &context, size: size, t: t * 1.2, color: colors[0], direction: -1, intensity: 0.24)
            drawSpotlight(context: &context, size: size, t: t * 1.2 + 1.7, color: colors[1], direction: 1, intensity: 0.24)
            drawArenaHorizon(context: &context, size: size, t: t, color: Color.white)

        case "studio":
            drawStudioPanels(context: &context, size: size, t: t, left: colors[0], right: colors[1], detailLevel: detailLevel)
            drawSmokeFields(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel, opacityScale: 0.38)

        case "neon":
            drawSmokeFields(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel, opacityScale: 0.82)
            drawNeonSweep(context: &context, size: size, t: t, colors: colors)

        case "starfield":
            drawSmokeFields(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel, opacityScale: 0.42)
            drawStars(context: &context, size: size, t: t, count: detailLevel == 3 ? 54 : (detailLevel == 2 ? 38 : 24))

        case "noir":
            drawSmokeFields(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel, opacityScale: 0.84)
            drawSpotlight(context: &context, size: size, t: t * 0.6, color: Color.white, direction: -1, intensity: 0.14)

        case "curtain":
            drawCurtainGlow(context: &context, size: size, t: t, colors: colors)
            drawSpotlight(context: &context, size: size, t: t * 0.72, color: colors[1], direction: -1, intensity: 0.18)
            drawSpotlight(context: &context, size: size, t: t * 0.72 + 2.0, color: Color.white, direction: 1, intensity: 0.12)
            if detailLevel >= 2 { drawDust(context: &context, size: size, t: t, count: detailLevel == 3 ? 30 : 18) }

        case "film":
            drawSmokeFields(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel, opacityScale: 0.50)
            drawProjectorBeam(context: &context, size: size, t: t, colors: colors)
            drawFilmFrames(context: &context, size: size, t: t, color: colors[0], detailLevel: detailLevel)

        case "matrix":
            drawStudioPanels(context: &context, size: size, t: t, left: colors[0], right: colors[1], detailLevel: detailLevel)
            drawGridLines(context: &context, size: size, t: t, color: colors[0], detailLevel: detailLevel)
            drawSignalLines(context: &context, size: size, t: t * 0.7, color: colors[1], count: detailLevel == 3 ? 5 : 3)

        case "arena":
            drawSmokeFields(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel, opacityScale: 0.42)
            drawSpotlight(context: &context, size: size, t: t, color: colors[0], direction: -1, intensity: 0.20)
            drawSpotlight(context: &context, size: size, t: t + 1.5, color: colors[1], direction: 1, intensity: 0.20)
            drawArenaHorizon(context: &context, size: size, t: t, color: Color.white)
            drawScoreTicks(context: &context, size: size, t: t, color: colors[1], detailLevel: detailLevel)

        case "skyline":
            drawSmokeFields(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel, opacityScale: 0.46)
            drawSkyline(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel)

        case "prism":
            drawSmokeFields(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel, opacityScale: 0.38)
            drawWaveRibbons(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel)

        case "cosmic":
            drawSmokeFields(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel, opacityScale: 0.34)
            drawStars(context: &context, size: size, t: t, count: detailLevel == 3 ? 60 : (detailLevel == 2 ? 42 : 26))
            drawOrbitRings(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel)

        default:
            drawSmokeFields(context: &context, size: size, t: t, colors: colors, detailLevel: detailLevel, opacityScale: 1.0)
        }
    }

    private func unit(_ seed: Double) -> CGFloat {
        CGFloat(abs(sin(seed * 12.9898 + 78.233)).truncatingRemainder(dividingBy: 1.0))
    }

    private func drawNexusLines(context: inout GraphicsContext, size: CGSize, t: TimeInterval, colors: [Color], detailLevel: Int) {
        // Original UNITY rendition of the classic axis-aligned particle-tail idea: luminous
        // red/green/blue/yellow heads travel horizontally and vertically with fading trails.
        // It is procedural Canvas work only—no external wallpaper asset is bundled or copied.
        let count = detailLevel == 3 ? 28 : (detailLevel == 2 ? 20 : 14)
        let palette = colors.isEmpty ? [Color.green, .blue, .red, .yellow] : colors
        for index in 0..<count {
            let seed = Double(index + 1) * 2.417
            let horizontal = index % 2 == 0
            let reverse = index % 4 >= 2
            let speed = 72.0 + Double(index % 7) * 17.0
            let color = palette[index % palette.count]
            let lane = unit(seed * 1.37)
            let tailFraction = CGFloat(0.10 + Double(index % 5) * 0.018)

            if horizontal {
                let travel = Double(size.width * 1.28)
                var phase = CGFloat((t * speed + seed * 131.0).truncatingRemainder(dividingBy: travel)) - size.width * 0.14
                if reverse { phase = size.width - phase }
                let y = max(14, min(size.height - 14, lane * size.height))
                let tail = size.width * tailFraction * (reverse ? 1 : -1)
                let start = CGPoint(x: phase + tail, y: y)
                let head = CGPoint(x: phase, y: y)
                var path = Path(); path.move(to: start); path.addLine(to: head)
                context.stroke(path, with: .color(color.opacity(0.16)), style: StrokeStyle(lineWidth: detailLevel == 3 ? 12 : 9, lineCap: .round))
                context.stroke(path, with: .color(color.opacity(0.78)), style: StrokeStyle(lineWidth: detailLevel == 3 ? 3.5 : 2.8, lineCap: .round))
                let headSize: CGFloat = detailLevel == 3 ? 8 : 6
                let headRect = CGRect(x: head.x - headSize * 0.5, y: head.y - headSize * 0.5, width: headSize, height: headSize)
                context.fill(Path(roundedRect: headRect, cornerRadius: 1.5), with: .color(Color.white.opacity(0.94)))
                context.stroke(Path(roundedRect: headRect.insetBy(dx: -2, dy: -2), cornerRadius: 2), with: .color(color.opacity(0.68)), lineWidth: 2)
            } else {
                let travel = Double(size.height * 1.28)
                var phase = CGFloat((t * speed + seed * 127.0).truncatingRemainder(dividingBy: travel)) - size.height * 0.14
                if reverse { phase = size.height - phase }
                let x = max(14, min(size.width - 14, lane * size.width))
                let tail = size.height * tailFraction * (reverse ? 1 : -1)
                let start = CGPoint(x: x, y: phase + tail)
                let head = CGPoint(x: x, y: phase)
                var path = Path(); path.move(to: start); path.addLine(to: head)
                context.stroke(path, with: .color(color.opacity(0.16)), style: StrokeStyle(lineWidth: detailLevel == 3 ? 12 : 9, lineCap: .round))
                context.stroke(path, with: .color(color.opacity(0.78)), style: StrokeStyle(lineWidth: detailLevel == 3 ? 3.5 : 2.8, lineCap: .round))
                let headSize: CGFloat = detailLevel == 3 ? 8 : 6
                let headRect = CGRect(x: head.x - headSize * 0.5, y: head.y - headSize * 0.5, width: headSize, height: headSize)
                context.fill(Path(roundedRect: headRect, cornerRadius: 1.5), with: .color(Color.white.opacity(0.94)))
                context.stroke(Path(roundedRect: headRect.insetBy(dx: -2, dy: -2), cornerRadius: 2), with: .color(color.opacity(0.68)), lineWidth: 2)
            }
        }
    }

    private func drawDigitalRain(context: inout GraphicsContext, size: CGSize, t: TimeInterval, colors: [Color], detailLevel: Int) {
        let columns = detailLevel == 3 ? 30 : (detailLevel == 2 ? 22 : 15)
        let glyphRows = detailLevel == 3 ? 18 : (detailLevel == 2 ? 14 : 10)
        let glyphs = Array("01<>[]{}:/\\*+DEBRIDCHANNELS")
        for column in 0..<columns {
            let seed = Double(column) * 1.731
            let x = (CGFloat(column) + 0.5) / CGFloat(columns) * size.width
            let speed = 38.0 + Double(column % 7) * 9.0
            let cycle = Double(size.height + CGFloat(glyphRows) * 30)
            let head = CGFloat((t * speed + seed * 113.0).truncatingRemainder(dividingBy: cycle)) - CGFloat(glyphRows) * 30
            var string = ""
            for row in 0..<glyphRows {
                let idx = (column * 11 + row * 7 + Int(t * 0.7)) % glyphs.count
                string.append(glyphs[idx])
                if row < glyphRows - 1 { string.append("\n") }
            }
            let opacity = 0.32 + Double(column % 4) * 0.045
            let text = Text(string)
                .font(.system(size: detailLevel == 1 ? 13 : 15, weight: .semibold, design: .monospaced))
                .foregroundColor(colors[column % min(3, colors.count)].opacity(opacity))
            context.draw(text, at: CGPoint(x: x, y: head), anchor: .top)
            let headRect = CGRect(x: x - 2.0, y: head + CGFloat(glyphRows - 1) * 28, width: 4, height: 18)
            context.fill(Path(roundedRect: headRect, cornerRadius: 2), with: .color(Color.white.opacity(0.72)))
        }
    }

    private func drawFallingStars(context: inout GraphicsContext, size: CGSize, t: TimeInterval, colors: [Color], detailLevel: Int) {
        let count = detailLevel == 3 ? 72 : (detailLevel == 2 ? 48 : 30)
        for index in 0..<count {
            let seed = Double(index) * 2.417
            let x = unit(seed) * size.width
            let speed = 20.0 + Double(index % 8) * 7.0
            let y = CGFloat((t * speed + seed * 79).truncatingRemainder(dividingBy: Double(size.height + 80))) - 40
            let length = CGFloat(8 + index % 5 * 4)
            var tail = Path(); tail.move(to: CGPoint(x: x, y: y - length)); tail.addLine(to: CGPoint(x: x, y: y))
            context.stroke(tail, with: .linearGradient(Gradient(colors: [Color.clear, colors[index % 2].opacity(0.20)]), startPoint: CGPoint(x: x, y: y - length), endPoint: CGPoint(x: x, y: y)), lineWidth: index % 7 == 0 ? 1.8 : 1.0)
            let radius: CGFloat = index % 7 == 0 ? 2.6 : 1.5
            context.fill(Path(ellipseIn: CGRect(x: x-radius, y: y-radius, width: radius*2, height: radius*2)), with: .color(Color.white.opacity(0.24)))
        }
    }

    private func drawGalaxy(context: inout GraphicsContext, size: CGSize, t: TimeInterval, colors: [Color], detailLevel: Int) {
        drawSmokeFields(context: &context, size: size, t: t * 0.28, colors: colors, detailLevel: detailLevel, opacityScale: 0.48)
        drawStars(context: &context, size: size, t: t, count: detailLevel == 3 ? 92 : (detailLevel == 2 ? 64 : 40))
        let center = CGPoint(x: size.width * 0.58, y: size.height * 0.48)
        let rings = detailLevel == 1 ? 3 : 5
        for index in 0..<rings {
            let w = size.width * (0.12 + CGFloat(index) * 0.065)
            let h = size.height * (0.035 + CGFloat(index) * 0.026)
            let drift = CGFloat(sin(t * 0.10 + Double(index))) * 12
            let rect = CGRect(x: center.x-w/2+drift, y: center.y-h/2, width: w, height: h)
            context.stroke(Path(ellipseIn: rect), with: .color(colors[index % 3].opacity(0.07)), lineWidth: 1.2)
        }
    }

    private func drawWarpSpace(context: inout GraphicsContext, size: CGSize, t: TimeInterval, colors: [Color], detailLevel: Int) {
        let center = CGPoint(x: size.width * 0.5, y: size.height * 0.48)
        let count = detailLevel == 3 ? 76 : (detailLevel == 2 ? 52 : 32)
        let phase = CGFloat((t * 0.14).truncatingRemainder(dividingBy: 1.0))
        for index in 0..<count {
            let angle = Double(index) * 2.399
            let base = (unit(Double(index) * 1.31) + phase).truncatingRemainder(dividingBy: 1.0)
            let radial = 0.04 + base * base * 0.96
            let dx = CGFloat(cos(angle)); let dy = CGFloat(sin(angle))
            let end = CGPoint(x: center.x + dx * radial * size.width * 0.78, y: center.y + dy * radial * size.height * 0.92)
            let tailScale = max(0.015, radial * 0.10)
            let start = CGPoint(x: end.x - dx * tailScale * size.width, y: end.y - dy * tailScale * size.height)
            var streak = Path(); streak.move(to: start); streak.addLine(to: end)
            context.stroke(streak, with: .color(colors[index % 3].opacity(0.10 + Double(radial) * 0.16)), lineWidth: index % 9 == 0 ? 2.0 : 1.0)
        }
    }

    private func drawCosmicDust(context: inout GraphicsContext, size: CGSize, t: TimeInterval, colors: [Color], detailLevel: Int) {
        drawSmokeFields(context: &context, size: size, t: t * 0.20, colors: colors, detailLevel: detailLevel, opacityScale: 0.28)
        let count = detailLevel == 3 ? 86 : (detailLevel == 2 ? 58 : 34)
        for index in 0..<count {
            let seed = Double(index) * 3.19
            let x = (unit(seed) + CGFloat((t * (0.002 + Double(index % 4) * 0.001)).truncatingRemainder(dividingBy: 1.0))).truncatingRemainder(dividingBy: 1.0) * size.width
            let y = unit(seed * 1.77) * size.height
            let r = CGFloat(1 + index % 4) * 0.7
            context.fill(Path(ellipseIn: CGRect(x: x-r, y: y-r, width: r*2, height: r*2)), with: .color(colors[index % 3].opacity(index % 9 == 0 ? 0.20 : 0.08)))
        }
    }

    private func drawAurora(context: inout GraphicsContext, size: CGSize, t: TimeInterval, colors: [Color], detailLevel: Int) {
        let ribbons = detailLevel == 3 ? 6 : (detailLevel == 2 ? 5 : 4)
        for ribbon in 0..<ribbons {
            var path = Path()
            let baseY = size.height * (0.16 + CGFloat(ribbon) * 0.09)
            let segments = 24
            path.move(to: CGPoint(x: 0, y: baseY))
            for step in 1...segments {
                let x = size.width * CGFloat(step) / CGFloat(segments)
                let y = baseY + CGFloat(sin(Double(step) * 0.48 + t * 0.28 + Double(ribbon) * 0.9)) * size.height * (0.035 + CGFloat(ribbon) * 0.003)
                path.addLine(to: CGPoint(x: x, y: y))
            }
            context.stroke(path, with: .color(colors[ribbon % 3].opacity(0.08 + Double(ribbon) * 0.012)), lineWidth: CGFloat(12 - min(ribbon, 6)))
        }
    }

    private func drawMeteorShower(context: inout GraphicsContext, size: CGSize, t: TimeInterval, colors: [Color], detailLevel: Int) {
        let count = detailLevel == 3 ? 12 : (detailLevel == 2 ? 8 : 5)
        for index in 0..<count {
            let seed = Double(index) * 9.17
            let cycle = (t * (0.055 + Double(index % 4) * 0.01) + seed).truncatingRemainder(dividingBy: 1.5)
            let x = CGFloat(cycle - 0.25) * size.width
            let y = unit(seed * 1.7) * size.height * 0.72 + CGFloat(cycle) * size.height * 0.15
            let tail: CGFloat = 70 + CGFloat(index % 4) * 22
            var streak = Path(); streak.move(to: CGPoint(x: x-tail, y: y-tail*0.52)); streak.addLine(to: CGPoint(x: x, y: y))
            context.stroke(streak, with: .linearGradient(Gradient(colors: [Color.clear, colors[index % 3].opacity(0.26), Color.white.opacity(0.32)]), startPoint: CGPoint(x: x-tail, y: y-tail*0.52), endPoint: CGPoint(x: x, y: y)), lineWidth: index % 3 == 0 ? 2.2 : 1.3)
        }
    }

    private func drawBlackHole(context: inout GraphicsContext, size: CGSize, t: TimeInterval, colors: [Color], detailLevel: Int) {
        drawStars(context: &context, size: size, t: t, count: detailLevel == 3 ? 72 : 42)
        let center = CGPoint(x: size.width * 0.57, y: size.height * 0.49)
        let rings = detailLevel == 1 ? 5 : 8
        for index in 0..<rings {
            let wobble = CGFloat(sin(t * 0.18 + Double(index))) * 5
            let w = size.width * (0.16 + CGFloat(index) * 0.030)
            let h = size.height * (0.025 + CGFloat(index) * 0.010)
            let rect = CGRect(x: center.x-w/2+wobble, y: center.y-h/2, width: w, height: h)
            context.stroke(Path(ellipseIn: rect), with: .color(colors[index % 3].opacity(0.09 + Double(index) * 0.009)), lineWidth: index % 3 == 0 ? 2.2 : 1.0)
        }
        let hole = CGRect(x: center.x-size.width*0.055, y: center.y-size.height*0.072, width: size.width*0.11, height: size.height*0.144)
        context.fill(Path(ellipseIn: hole), with: .color(Color.black.opacity(0.98)))
    }

    private func drawConstellations(context: inout GraphicsContext, size: CGSize, t: TimeInterval, colors: [Color], detailLevel: Int) {
        let count = detailLevel == 3 ? 34 : (detailLevel == 2 ? 26 : 18)
        var points: [CGPoint] = []
        for index in 0..<count {
            let seed = Double(index) * 4.77
            let p = CGPoint(x: unit(seed) * size.width, y: unit(seed * 1.91) * size.height)
            points.append(p)
            let r: CGFloat = index % 5 == 0 ? 2.5 : 1.5
            let pulse = 0.11 + (sin(t * 0.5 + seed) + 1) * 0.035
            context.fill(Path(ellipseIn: CGRect(x: p.x-r, y: p.y-r, width: r*2, height: r*2)), with: .color(Color.white.opacity(pulse)))
        }
        for index in 1..<points.count where index % 3 != 0 {
            var line = Path(); line.move(to: points[index-1]); line.addLine(to: points[index])
            context.stroke(line, with: .color(colors[1].opacity(0.045)), lineWidth: 0.8)
        }
    }

    private func drawPerspectiveGrid(context: inout GraphicsContext, size: CGSize, t: TimeInterval, colors: [Color], detailLevel: Int, neon: Bool) {
        let horizon = size.height * 0.47
        let verticals = detailLevel == 3 ? 17 : (detailLevel == 2 ? 13 : 9)
        for index in 0...verticals {
            let fraction = CGFloat(index) / CGFloat(verticals)
            let bottomX = fraction * size.width
            let horizonX = size.width * 0.5 + (bottomX - size.width * 0.5) * 0.12
            var line = Path(); line.move(to: CGPoint(x: horizonX, y: horizon)); line.addLine(to: CGPoint(x: bottomX, y: size.height))
            context.stroke(line, with: .color(colors[index % 2].opacity(neon ? 0.12 : 0.065)), lineWidth: neon ? 1.4 : 1.0)
        }
        let rows = detailLevel == 3 ? 12 : (detailLevel == 2 ? 9 : 7)
        let phase = CGFloat((t * 0.18).truncatingRemainder(dividingBy: 1.0))
        for row in 0..<rows {
            let normalized = (CGFloat(row) + phase) / CGFloat(rows)
            let eased = normalized * normalized
            let y = horizon + eased * (size.height - horizon)
            var line = Path(); line.move(to: CGPoint(x: 0, y: y)); line.addLine(to: CGPoint(x: size.width, y: y))
            context.stroke(line, with: .color(colors[(row+1) % 2].opacity(neon ? 0.12 : 0.055)), lineWidth: neon ? 1.3 : 1.0)
        }
    }

    private func drawDataParticles(context: inout GraphicsContext, size: CGSize, t: TimeInterval, colors: [Color], detailLevel: Int) {
        let count = detailLevel == 3 ? 44 : (detailLevel == 2 ? 30 : 18)
        for index in 0..<count {
            let seed = Double(index) * 5.03
            let x = unit(seed) * size.width
            let y = CGFloat((unit(seed * 1.7) + CGFloat((t * 0.035 + seed).truncatingRemainder(dividingBy: 1.0))).truncatingRemainder(dividingBy: 1.0)) * size.height
            let rect = CGRect(x: x, y: y, width: index % 7 == 0 ? 5 : 3, height: index % 7 == 0 ? 5 : 3)
            context.fill(Path(rect), with: .color(colors[index % 3].opacity(0.12)))
        }
    }

    private func drawElectricStorm(context: inout GraphicsContext, size: CGSize, t: TimeInterval, colors: [Color], detailLevel: Int) {
        drawSmokeFields(context: &context, size: size, t: t * 0.20, colors: colors, detailLevel: detailLevel, opacityScale: 0.34)
        let bolts = detailLevel == 3 ? 4 : (detailLevel == 2 ? 3 : 2)
        let flashPhase = Int(t * 1.4)
        for bolt in 0..<bolts {
            let seed = Double(flashPhase * 17 + bolt * 31)
            var path = Path()
            var p = CGPoint(x: unit(seed) * size.width, y: -10)
            path.move(to: p)
            let steps = 7
            for step in 1...steps {
                p = CGPoint(x: p.x + (unit(seed + Double(step) * 2.3) - 0.5) * size.width * 0.10, y: size.height * CGFloat(step) / CGFloat(steps) * 0.72)
                path.addLine(to: p)
            }
            let active = (sin(t * 5.2 + seed) + 1) * 0.5
            context.stroke(path, with: .color(colors[bolt % 3].opacity(0.04 + active * 0.14)), lineWidth: bolt == 0 ? 2.0 : 1.1)
        }
    }

    private func drawEmbers(context: inout GraphicsContext, size: CGSize, t: TimeInterval, colors: [Color], detailLevel: Int) {
        let count = detailLevel == 3 ? 66 : (detailLevel == 2 ? 44 : 28)
        for index in 0..<count {
            let seed = Double(index) * 6.21
            let x = (unit(seed) + CGFloat(sin(t * 0.20 + seed)) * 0.035) * size.width
            let progress = CGFloat((t * (0.025 + Double(index % 5) * 0.006) + seed).truncatingRemainder(dividingBy: 1.0))
            let y = size.height * (1.05 - progress * 1.15)
            let r: CGFloat = index % 8 == 0 ? 3.0 : 1.6
            context.fill(Path(ellipseIn: CGRect(x: x-r, y: y-r, width: r*2, height: r*2)), with: .color(colors[index % 3].opacity(0.10 + Double(index % 4) * 0.035)))
        }
    }

    private func drawSnow(context: inout GraphicsContext, size: CGSize, t: TimeInterval, colors: [Color], detailLevel: Int) {
        let count = detailLevel == 3 ? 78 : (detailLevel == 2 ? 52 : 32)
        for index in 0..<count {
            let seed = Double(index) * 4.13
            let speed = 0.025 + Double(index % 6) * 0.006
            let progress = CGFloat((t * speed + seed).truncatingRemainder(dividingBy: 1.0))
            let x = (unit(seed) + CGFloat(sin(t * 0.25 + seed)) * 0.025) * size.width
            let y = progress * size.height
            let r: CGFloat = CGFloat(1 + index % 4) * 0.8
            context.fill(Path(ellipseIn: CGRect(x: x-r, y: y-r, width: r*2, height: r*2)), with: .color(colors[index % 2].opacity(index % 9 == 0 ? 0.24 : 0.13)))
        }
    }

    private func drawRainOnGlass(context: inout GraphicsContext, size: CGSize, t: TimeInterval, colors: [Color], detailLevel: Int) {
        let count = detailLevel == 3 ? 60 : (detailLevel == 2 ? 42 : 26)
        for index in 0..<count {
            let seed = Double(index) * 3.71
            let x = unit(seed) * size.width
            let speed = 0.11 + Double(index % 5) * 0.018
            let progress = CGFloat((t * speed + seed).truncatingRemainder(dividingBy: 1.0))
            let y = progress * size.height
            let length = CGFloat(18 + index % 6 * 8)
            var drop = Path(); drop.move(to: CGPoint(x: x, y: y-length)); drop.addLine(to: CGPoint(x: x-2, y: y))
            context.stroke(drop, with: .linearGradient(Gradient(colors: [Color.clear, colors[index % 2].opacity(0.14)]), startPoint: CGPoint(x: x, y: y-length), endPoint: CGPoint(x: x, y: y)), lineWidth: index % 7 == 0 ? 1.8 : 1.0)
        }
    }

    private func drawUnderwater(context: inout GraphicsContext, size: CGSize, t: TimeInterval, colors: [Color], detailLevel: Int) {
        drawSmokeFields(context: &context, size: size, t: t * 0.15, colors: colors, detailLevel: detailLevel, opacityScale: 0.22)
        for beam in 0..<4 {
            let x = size.width * (0.12 + CGFloat(beam) * 0.23) + CGFloat(sin(t * 0.12 + Double(beam))) * 28
            var path = Path(); path.move(to: CGPoint(x: x-18, y: -10)); path.addLine(to: CGPoint(x: x+18, y: -10)); path.addLine(to: CGPoint(x: x+size.width*0.08, y: size.height)); path.addLine(to: CGPoint(x: x-size.width*0.08, y: size.height)); path.closeSubpath()
            context.fill(path, with: .linearGradient(Gradient(colors: [colors[0].opacity(0.08), Color.clear]), startPoint: CGPoint(x: x, y: 0), endPoint: CGPoint(x: x, y: size.height)))
        }
        let bubbles = detailLevel == 3 ? 44 : (detailLevel == 2 ? 30 : 18)
        for index in 0..<bubbles {
            let seed = Double(index) * 4.91
            let x = (unit(seed) + CGFloat(sin(t * 0.18 + seed)) * 0.02) * size.width
            let progress = CGFloat((t * (0.018 + Double(index % 5) * 0.004) + seed).truncatingRemainder(dividingBy: 1.0))
            let y = size.height * (1.0-progress)
            let r: CGFloat = CGFloat(2 + index % 5)
            context.stroke(Path(ellipseIn: CGRect(x: x-r, y: y-r, width: r*2, height: r*2)), with: .color(Color.white.opacity(0.08)), lineWidth: 0.8)
        }
    }

    private func drawOLEDParticles(context: inout GraphicsContext, size: CGSize, t: TimeInterval, colors: [Color], detailLevel: Int) {
        let count = detailLevel == 3 ? 42 : (detailLevel == 2 ? 28 : 16)
        for index in 0..<count {
            let seed = Double(index) * 8.31
            let x = (unit(seed) + CGFloat(sin(t * 0.07 + seed)) * 0.05).truncatingRemainder(dividingBy: 1.0) * size.width
            let y = (unit(seed * 1.33) + CGFloat(cos(t * 0.06 + seed)) * 0.04).truncatingRemainder(dividingBy: 1.0) * size.height
            let r: CGFloat = index % 10 == 0 ? 3.2 : 1.4
            let glow = 0.08 + (sin(t * 0.6 + seed) + 1) * 0.035
            context.fill(Path(ellipseIn: CGRect(x: x-r, y: y-r, width: r*2, height: r*2)), with: .color(colors[index % 3].opacity(glow)))
        }
    }

    private func drawSmokeFields(
        context: inout GraphicsContext,
        size: CGSize,
        t: TimeInterval,
        colors: [Color],
        detailLevel: Int,
        opacityScale: Double
    ) {
        drawSmokeBlob(
            context: &context,
            color: colors[0],
            opacityScale: opacityScale,
            rect: smokeRect(
                size: size,
                widthScale: 0.82,
                heightScale: 0.76,
                x: CGFloat(sin(t * 0.090)) * size.width * 0.20 - size.width * 0.18,
                y: CGFloat(cos(t * 0.074)) * size.height * 0.18 - size.height * 0.10
            )
        )
        drawSmokeBlob(
            context: &context,
            color: colors[1],
            opacityScale: opacityScale,
            rect: smokeRect(
                size: size,
                widthScale: 0.74,
                heightScale: 0.69,
                x: CGFloat(cos(t * 0.071)) * size.width * 0.24 + size.width * 0.20,
                y: CGFloat(sin(t * 0.061)) * size.height * 0.20 + size.height * 0.06
            )
        )
        drawSmokeBlob(
            context: &context,
            color: colors[2],
            opacityScale: opacityScale,
            rect: smokeRect(
                size: size,
                widthScale: 0.64,
                heightScale: 0.61,
                x: CGFloat(sin(t * 0.052 + 1.8)) * size.width * 0.28,
                y: CGFloat(cos(t * 0.047 + 0.7)) * size.height * 0.22 + size.height * 0.12
            )
        )
        if detailLevel >= 2 {
            drawSmokeBlob(
                context: &context,
                color: colors[3],
                opacityScale: opacityScale * 0.70,
                rect: smokeRect(
                    size: size,
                    widthScale: 0.52,
                    heightScale: 0.48,
                    x: CGFloat(cos(t * 0.043 + 2.6)) * size.width * 0.30,
                    y: CGFloat(sin(t * 0.039 + 1.1)) * size.height * 0.24 - size.height * 0.05
                )
            )
        }
    }

    private func smokeRect(size: CGSize, widthScale: CGFloat, heightScale: CGFloat, x: CGFloat, y: CGFloat) -> CGRect {
        let width = size.width * widthScale
        let height = size.height * heightScale
        return CGRect(
            x: (size.width - width) * 0.5 + x,
            y: (size.height - height) * 0.5 + y,
            width: width,
            height: height
        )
    }

    private func drawSmokeBlob(context: inout GraphicsContext, color: Color, opacityScale: Double, rect: CGRect) {
        let path = Path(ellipseIn: rect)
        context.fill(
            path,
            with: .radialGradient(
                Gradient(colors: [
                    color.opacity(0.28 * opacityScale),
                    color.opacity(0.12 * opacityScale),
                    color.opacity(0.035 * opacityScale),
                    Color.clear
                ]),
                center: CGPoint(x: rect.midX, y: rect.midY),
                startRadius: 0,
                endRadius: max(rect.width, rect.height) * 0.50
            )
        )
    }

    private func drawSpotlight(
        context: inout GraphicsContext,
        size: CGSize,
        t: TimeInterval,
        color: Color,
        direction: CGFloat,
        intensity: Double
    ) {
        let topX = size.width * (direction < 0 ? 0.22 : 0.78)
        let sweep = CGFloat(sin(t * 0.22)) * size.width * 0.14 * direction
        let bottomX = size.width * 0.5 + sweep
        var path = Path()
        path.move(to: CGPoint(x: topX - 18, y: -20))
        path.addLine(to: CGPoint(x: topX + 18, y: -20))
        path.addLine(to: CGPoint(x: bottomX + size.width * 0.17, y: size.height * 1.04))
        path.addLine(to: CGPoint(x: bottomX - size.width * 0.17, y: size.height * 1.04))
        path.closeSubpath()
        context.fill(
            path,
            with: .linearGradient(
                Gradient(colors: [color.opacity(intensity), color.opacity(intensity * 0.34), Color.clear]),
                startPoint: CGPoint(x: topX, y: 0),
                endPoint: CGPoint(x: bottomX, y: size.height)
            )
        )
    }

    private func drawProjectorBeam(context: inout GraphicsContext, size: CGSize, t: TimeInterval, colors: [Color]) {
        let source = CGPoint(x: size.width * 0.08, y: size.height * 0.24)
        let wobble = CGFloat(sin(t * 0.11)) * size.height * 0.035
        var path = Path()
        path.move(to: source)
        path.addLine(to: CGPoint(x: size.width * 0.96, y: size.height * 0.17 + wobble))
        path.addLine(to: CGPoint(x: size.width * 0.96, y: size.height * 0.82 + wobble))
        path.closeSubpath()
        context.fill(
            path,
            with: .linearGradient(
                Gradient(colors: [colors[0].opacity(0.26), colors[1].opacity(0.10), Color.clear]),
                startPoint: source,
                endPoint: CGPoint(x: size.width, y: size.height * 0.5)
            )
        )
    }

    private func drawBroadcastBands(context: inout GraphicsContext, size: CGSize, t: TimeInterval, colors: [Color], count: Int) {
        for index in 0..<count {
            let fraction = CGFloat(index) / CGFloat(max(1, count - 1))
            let travel = CGFloat(sin(t * 0.18 + Double(index) * 0.70)) * size.width * 0.08
            let x = size.width * (0.05 + fraction * 0.90) + travel
            var band = Path()
            band.move(to: CGPoint(x: x - 90, y: -10))
            band.addLine(to: CGPoint(x: x + 26, y: -10))
            band.addLine(to: CGPoint(x: x + 180, y: size.height + 10))
            band.addLine(to: CGPoint(x: x + 55, y: size.height + 10))
            band.closeSubpath()
            context.fill(
                band,
                with: .linearGradient(
                    Gradient(colors: [Color.clear, colors[index % 3].opacity(0.10), Color.clear]),
                    startPoint: CGPoint(x: x, y: 0),
                    endPoint: CGPoint(x: x + 80, y: size.height)
                )
            )
        }
    }

    private func drawSignalLines(context: inout GraphicsContext, size: CGSize, t: TimeInterval, color: Color, count: Int) {
        for index in 0..<count {
            let base = CGFloat(index + 1) / CGFloat(count + 1)
            let y = size.height * base + CGFloat(sin(t * 0.35 + Double(index))) * 14
            var line = Path()
            line.move(to: CGPoint(x: 0, y: y))
            line.addCurve(
                to: CGPoint(x: size.width, y: y),
                control1: CGPoint(x: size.width * 0.30, y: y - 18 - CGFloat(index * 2)),
                control2: CGPoint(x: size.width * 0.70, y: y + 18 + CGFloat(index * 2))
            )
            context.stroke(line, with: .color(color.opacity(index % 2 == 0 ? 0.13 : 0.075)), lineWidth: index % 2 == 0 ? 2 : 1)
        }
    }

    private func drawStudioPanels(context: inout GraphicsContext, size: CGSize, t: TimeInterval, left: Color, right: Color, detailLevel: Int) {
        let sweep = CGFloat(sin(t * 0.16)) * size.width * 0.08
        var leftPath = Path()
        leftPath.addRect(CGRect(x: -size.width * 0.10 + sweep, y: 0, width: size.width * 0.46, height: size.height))
        context.fill(leftPath, with: .linearGradient(Gradient(colors: [left.opacity(0.18), Color.clear]), startPoint: .zero, endPoint: CGPoint(x: size.width * 0.50, y: 0)))
        var rightPath = Path()
        rightPath.addRect(CGRect(x: size.width * 0.64 - sweep, y: 0, width: size.width * 0.46, height: size.height))
        context.fill(rightPath, with: .linearGradient(Gradient(colors: [Color.clear, right.opacity(0.18)]), startPoint: CGPoint(x: size.width * 0.50, y: 0), endPoint: CGPoint(x: size.width, y: 0)))
        if detailLevel >= 2 {
            drawBroadcastBands(context: &context, size: size, t: t, colors: [left, right, Color.white, Color.clear], count: detailLevel == 3 ? 5 : 3)
        }
    }

    private func drawMarqueeEdgeGlow(context: inout GraphicsContext, size: CGSize, t: TimeInterval, color: Color) {
        let pulse = 0.07 + (sin(t * 0.8) + 1.0) * 0.025
        var top = Path(); top.addRect(CGRect(x: 0, y: 0, width: size.width, height: 44))
        var bottom = Path(); bottom.addRect(CGRect(x: 0, y: size.height - 54, width: size.width, height: 54))
        context.fill(top, with: .linearGradient(Gradient(colors: [color.opacity(pulse), Color.clear]), startPoint: CGPoint(x: size.width * 0.5, y: 0), endPoint: CGPoint(x: size.width * 0.5, y: 70)))
        context.fill(bottom, with: .linearGradient(Gradient(colors: [Color.clear, color.opacity(pulse)]), startPoint: CGPoint(x: size.width * 0.5, y: size.height - 80), endPoint: CGPoint(x: size.width * 0.5, y: size.height)))
    }

    private func drawArenaHorizon(context: inout GraphicsContext, size: CGSize, t: TimeInterval, color: Color) {
        let y = size.height * 0.74
        var line = Path()
        line.move(to: CGPoint(x: 0, y: y))
        line.addLine(to: CGPoint(x: size.width, y: y))
        context.stroke(line, with: .color(color.opacity(0.12 + (sin(t * 0.9) + 1.0) * 0.025)), lineWidth: 2)
    }

    private func drawNeonSweep(context: inout GraphicsContext, size: CGSize, t: TimeInterval, colors: [Color]) {
        let x = (CGFloat(sin(t * 0.21)) * 0.5 + 0.5) * size.width
        var path = Path()
        path.move(to: CGPoint(x: x - 150, y: 0))
        path.addLine(to: CGPoint(x: x + 30, y: 0))
        path.addLine(to: CGPoint(x: x + 210, y: size.height))
        path.addLine(to: CGPoint(x: x + 20, y: size.height))
        path.closeSubpath()
        context.fill(path, with: .linearGradient(Gradient(colors: [Color.clear, colors[0].opacity(0.14), colors[1].opacity(0.10), Color.clear]), startPoint: CGPoint(x: x, y: 0), endPoint: CGPoint(x: x + 80, y: size.height)))
    }

    private func drawCurtainGlow(context: inout GraphicsContext, size: CGSize, t: TimeInterval, colors: [Color]) {
        let breathe = 0.12 + (sin(t * 0.42) + 1.0) * 0.025
        let third = size.width / 3.0
        for index in 0..<4 {
            let x = CGFloat(index) * third - third * 0.35
            var fold = Path()
            fold.addRect(CGRect(x: x, y: 0, width: third * 0.72, height: size.height))
            context.fill(
                fold,
                with: .linearGradient(
                    Gradient(colors: [colors[0].opacity(breathe), Color.clear, colors[0].opacity(breathe * 0.45)]),
                    startPoint: CGPoint(x: x, y: 0),
                    endPoint: CGPoint(x: x + third * 0.72, y: 0)
                )
            )
        }
        drawMarqueeEdgeGlow(context: &context, size: size, t: t, color: colors[1])
    }

    private func drawFilmFrames(context: inout GraphicsContext, size: CGSize, t: TimeInterval, color: Color, detailLevel: Int) {
        let frameCount = detailLevel == 3 ? 11 : (detailLevel == 2 ? 8 : 6)
        let travel = CGFloat((t * 18.0).truncatingRemainder(dividingBy: 96.0))
        let y = size.height * 0.82
        for index in 0..<frameCount {
            let width = size.width / CGFloat(frameCount)
            let x = CGFloat(index) * width - travel
            let rect = CGRect(x: x, y: y, width: width * 0.72, height: 34)
            context.stroke(Path(roundedRect: rect, cornerRadius: 4), with: .color(color.opacity(0.10)), lineWidth: 1)
            let perf = CGRect(x: x + 5, y: y + 5, width: 5, height: 5)
            context.fill(Path(roundedRect: perf, cornerRadius: 1), with: .color(Color.white.opacity(0.10)))
        }
    }

    private func drawGridLines(context: inout GraphicsContext, size: CGSize, t: TimeInterval, color: Color, detailLevel: Int) {
        let columns = detailLevel == 3 ? 12 : (detailLevel == 2 ? 9 : 7)
        let rows = detailLevel == 3 ? 7 : 5
        let xShift = CGFloat(sin(t * 0.12)) * 10
        for index in 1..<columns {
            let x = size.width * CGFloat(index) / CGFloat(columns) + xShift
            var line = Path(); line.move(to: CGPoint(x: x, y: size.height * 0.20)); line.addLine(to: CGPoint(x: x, y: size.height))
            context.stroke(line, with: .color(color.opacity(0.045)), lineWidth: 1)
        }
        for index in 1..<rows {
            let y = size.height * (0.24 + 0.76 * CGFloat(index) / CGFloat(rows))
            var line = Path(); line.move(to: CGPoint(x: 0, y: y)); line.addLine(to: CGPoint(x: size.width, y: y))
            context.stroke(line, with: .color(Color.white.opacity(0.035)), lineWidth: 1)
        }
    }

    private func drawScoreTicks(context: inout GraphicsContext, size: CGSize, t: TimeInterval, color: Color, detailLevel: Int) {
        let count = detailLevel == 3 ? 18 : (detailLevel == 2 ? 12 : 8)
        let y = size.height * 0.76
        let phase = CGFloat((t * 14.0).truncatingRemainder(dividingBy: 64.0))
        for index in 0..<count {
            let x = size.width * CGFloat(index) / CGFloat(max(1, count - 1)) + phase - 32
            var tick = Path(); tick.move(to: CGPoint(x: x, y: y - 8)); tick.addLine(to: CGPoint(x: x, y: y + 8))
            context.stroke(tick, with: .color(color.opacity(0.12)), lineWidth: index % 3 == 0 ? 2 : 1)
        }
    }

    private func drawSkyline(context: inout GraphicsContext, size: CGSize, t: TimeInterval, colors: [Color], detailLevel: Int) {
        let count = detailLevel == 3 ? 22 : (detailLevel == 2 ? 17 : 13)
        let baseline = size.height * 0.84
        for index in 0..<count {
            let width = size.width / CGFloat(count)
            let seed = Double(index) * 1.73
            let height = size.height * (0.06 + CGFloat(sin(seed) * 0.5 + 0.5) * 0.17)
            let rect = CGRect(x: CGFloat(index) * width, y: baseline - height, width: width * 0.72, height: height)
            let pulse = 0.045 + (sin(t * 0.28 + seed) + 1.0) * 0.018
            context.fill(Path(rect), with: .linearGradient(Gradient(colors: [colors[index % 3].opacity(pulse), Color.black.opacity(0.30)]), startPoint: CGPoint(x: rect.midX, y: rect.minY), endPoint: CGPoint(x: rect.midX, y: rect.maxY)))
        }
        var horizon = Path(); horizon.move(to: CGPoint(x: 0, y: baseline)); horizon.addLine(to: CGPoint(x: size.width, y: baseline))
        context.stroke(horizon, with: .color(colors[1].opacity(0.12)), lineWidth: 1)
    }

    private func drawWaveRibbons(context: inout GraphicsContext, size: CGSize, t: TimeInterval, colors: [Color], detailLevel: Int) {
        let count = detailLevel == 3 ? 5 : (detailLevel == 2 ? 4 : 3)
        for index in 0..<count {
            let baseY = size.height * (0.28 + CGFloat(index) * 0.12)
            let amplitude = size.height * (0.035 + CGFloat(index) * 0.008)
            var wave = Path()
            wave.move(to: CGPoint(x: 0, y: baseY))
            let segments = 18
            for step in 1...segments {
                let x = size.width * CGFloat(step) / CGFloat(segments)
                let phase = Double(step) * 0.55 + t * (0.30 + Double(index) * 0.04)
                let y = baseY + CGFloat(sin(phase)) * amplitude
                wave.addLine(to: CGPoint(x: x, y: y))
            }
            context.stroke(wave, with: .color(colors[index % colors.count].opacity(0.10)), lineWidth: CGFloat(1 + index % 2))
        }
    }

    private func drawOrbitRings(context: inout GraphicsContext, size: CGSize, t: TimeInterval, colors: [Color], detailLevel: Int) {
        let count = detailLevel == 3 ? 4 : (detailLevel == 2 ? 3 : 2)
        let center = CGPoint(x: size.width * (0.52 + CGFloat(sin(t * 0.08)) * 0.03), y: size.height * 0.50)
        for index in 0..<count {
            let width = size.width * (0.24 + CGFloat(index) * 0.11)
            let height = size.height * (0.16 + CGFloat(index) * 0.08)
            let rect = CGRect(x: center.x - width * 0.5, y: center.y - height * 0.5, width: width, height: height)
            context.stroke(Path(ellipseIn: rect), with: .color(colors[index % 3].opacity(0.08 + Double(index) * 0.012)), lineWidth: 1)
        }
    }

    private func drawDust(context: inout GraphicsContext, size: CGSize, t: TimeInterval, count: Int) {
        for index in 0..<count {
            let seed = Double(index) * 12.9898
            let fx = CGFloat(sin(seed) * 0.5 + 0.5)
            let baseY = CGFloat(cos(seed * 1.37) * 0.5 + 0.5)
            let drift = CGFloat((t * (3.0 + Double(index % 5))).truncatingRemainder(dividingBy: 120.0)) / 120.0
            let y = (baseY + drift).truncatingRemainder(dividingBy: 1.0) * size.height
            let radius = CGFloat(1 + (index % 3))
            let rect = CGRect(x: fx * size.width, y: y, width: radius, height: radius)
            context.fill(Path(ellipseIn: rect), with: .color(Color.white.opacity(index % 4 == 0 ? 0.19 : 0.10)))
        }
    }

    private func drawStars(context: inout GraphicsContext, size: CGSize, t: TimeInterval, count: Int) {
        for index in 0..<count {
            let seed = Double(index) * 7.913
            let x = CGFloat(sin(seed * 1.11) * 0.5 + 0.5) * size.width
            let y = CGFloat(cos(seed * 1.73) * 0.5 + 0.5) * size.height
            let twinkle = 0.07 + (sin(t * 0.9 + seed) + 1.0) * 0.035
            let radius = CGFloat(index % 5 == 0 ? 2.4 : 1.2)
            context.fill(Path(ellipseIn: CGRect(x: x, y: y, width: radius, height: radius)), with: .color(Color.white.opacity(twinkle)))
        }
    }
}

struct MainGridBackgroundPicker: View {
    @Binding var selectedPreset: String
    @FocusState private var focusedPreset: String?
    private let columns = [GridItem(.flexible(), spacing: 8), GridItem(.flexible(), spacing: 8)]

    var body: some View {
        LazyVGrid(columns: columns, alignment: .leading, spacing: 8) {
            ForEach(MainGridBackgroundStyle.presets, id: \.self) { preset in
                let selected = selectedPreset == preset
                let focused = focusedPreset == preset
                let swatch = MainGridBackgroundStyle.swatch(for: preset)
                Button {
                    selectedPreset = preset
                    UserDefaults.standard.set(preset, forKey: "mainGridBackgroundPreset")
                } label: {
                    HStack(spacing: 10) {
                        RoundedRectangle(cornerRadius: 5, style: .continuous)
                            .fill(swatch)
                            .frame(width: 24, height: 17)
                            .overlay(RoundedRectangle(cornerRadius: 5).stroke(Color.white.opacity(0.52), lineWidth: 1))
                        Text(preset)
                            .font(.system(size: 14, weight: .black, design: .rounded))
                            .lineLimit(1)
                        Spacer(minLength: 0)
                        if selected { Image(systemName: "checkmark.circle.fill").font(.system(size: 14, weight: .black)) }
                    }
                    .foregroundStyle((selected || focused) ? Color.black : Color.white)
                    .padding(.horizontal, 12)
                    .frame(height: 52)
                    .background(RoundedRectangle(cornerRadius: 15, style: .continuous).fill(selected ? swatch.opacity(0.96) : (focused ? Color.orange.opacity(0.82) : Color.white.opacity(0.085))))
                    .overlay(RoundedRectangle(cornerRadius: 15, style: .continuous).stroke((selected || focused) ? Color.white.opacity(0.90) : Color.white.opacity(0.10), lineWidth: (selected || focused) ? 2 : 1))
                }
                .buttonStyle(.plain)
                .focused($focusedPreset, equals: preset)
                .modifier(SettingsRoundedFocusVisual(cornerRadius: 15))
            }
        }
        .padding(.top, 4)
    }
}

struct DynamicMainGridWallpaperPicker: View {
    @Binding var selectedPreset: String
    @FocusState private var focusedPreset: String?
    private let columns = [GridItem(.flexible(), spacing: 8), GridItem(.flexible(), spacing: 8)]

    var body: some View {
        LazyVGrid(columns: columns, alignment: .leading, spacing: 8) {
            ForEach(DynamicMainGridWallpaperStyle.presets, id: \.self) { preset in
                let selected = selectedPreset == preset
                let focused = focusedPreset == preset
                let colors = DynamicMainGridWallpaperStyle.colors(for: preset)
                Button {
                    selectedPreset = preset
                    UserDefaults.standard.set(preset, forKey: "dynamicMainGridWallpaperPreset")
                } label: {
                    HStack(spacing: 10) {
                        Circle()
                            .fill(LinearGradient(colors: Array(colors.prefix(3)), startPoint: .topLeading, endPoint: .bottomTrailing))
                            .frame(width: 20, height: 20)
                            .overlay(Circle().stroke(Color.white.opacity(0.52), lineWidth: 1))
                        Text(preset)
                            .font(.system(size: 14, weight: .black, design: .rounded))
                            .lineLimit(1)
                        Spacer(minLength: 0)
                        if selected { Image(systemName: "checkmark.circle.fill").font(.system(size: 14, weight: .black)) }
                    }
                    .foregroundStyle((selected || focused) ? Color.black : Color.white)
                    .padding(.horizontal, 12)
                    .frame(height: 52)
                    .background(RoundedRectangle(cornerRadius: 15, style: .continuous).fill(selected ? colors[0].opacity(0.90) : (focused ? Color.orange.opacity(0.82) : Color.white.opacity(0.085))))
                    .overlay(RoundedRectangle(cornerRadius: 15, style: .continuous).stroke((selected || focused) ? Color.white.opacity(0.90) : Color.white.opacity(0.10), lineWidth: (selected || focused) ? 2 : 1))
                }
                .buttonStyle(.plain)
