struct HomeGridThemeStyle {
    static let themes = [
        "Classic Glow", "Apple Glass", "Frosted 3D", "Pure Black", "Midnight Blue",
        "Neon Edge", "Carbon OLED", "Crimson Red", "Ruby Glow", "Cinema Gold",
        "Amber Gold", "Bronze Theater", "Emerald Focus", "Royal Purple", "Rose Neon",
        "Ice Blue", "Copper Glow"
    ]

    static func accent(for theme: String) -> Color {
        let key = theme.lowercased()
        if key.contains("crimson") || key.contains("red") { return Color(red: 0.98, green: 0.16, blue: 0.18) }
        if key.contains("ruby") { return Color(red: 0.94, green: 0.10, blue: 0.28) }
        if key.contains("gold") { return Color(red: 1.0, green: 0.72, blue: 0.18) }
        if key.contains("amber") { return Color(red: 1.0, green: 0.56, blue: 0.08) }
        if key.contains("bronze") { return Color(red: 0.78, green: 0.43, blue: 0.20) }
        if key.contains("copper") { return Color(red: 0.90, green: 0.42, blue: 0.18) }
        if key.contains("emerald") || key.contains("green") { return Color(red: 0.14, green: 0.82, blue: 0.48) }
        if key.contains("purple") || key.contains("violet") { return Color(red: 0.60, green: 0.32, blue: 1.0) }
        if key.contains("rose") || key.contains("pink") { return Color(red: 1.0, green: 0.28, blue: 0.56) }
        if key.contains("neon") { return Color.cyan }
        if key.contains("ice") { return Color(red: 0.52, green: 0.88, blue: 1.0) }
        if key.contains("blue") { return Color(red: 0.16, green: 0.58, blue: 1.0) }
        if key.contains("black") || key.contains("carbon") { return Color.white.opacity(0.80) }
        if key.contains("apple") || key.contains("frost") { return Color.white.opacity(0.95) }
        return Color(red: 0.16, green: 0.58, blue: 1.0)
    }

    static func focusGlowOpacity(for theme: String) -> Double {
        let key = theme.lowercased()
        if key.contains("black") { return 0.16 }
        if key.contains("frost") || key.contains("apple") { return 0.26 }
        if key.contains("neon") { return 0.54 }
        return 0.36
    }

    static func focusGlowRadius(for theme: String) -> CGFloat {
        let key = theme.lowercased()
        if key.contains("frost") || key.contains("apple") { return 34 }
        if key.contains("neon") { return 38 }
        return 28
    }

    static func blackShadowOpacity(for theme: String) -> Double {
        let key = theme.lowercased()
        if key.contains("black") || key.contains("carbon") { return 0.92 }
        if key.contains("apple") || key.contains("frost") { return 0.68 }
        return 0.82
    }
}

struct HomeGridThemeOverlay: View {
    let theme: String
    let focused: Bool

    var body: some View {
        let key = theme.lowercased()
        ZStack {
            if key.contains("apple") || key.contains("frost") {
                LinearGradient(colors: [Color.white.opacity(focused ? 0.20 : 0.10), Color.white.opacity(0.035), Color.black.opacity(0.30)], startPoint: .topLeading, endPoint: .bottomTrailing)
                RoundedRectangle(cornerRadius: 24, style: .continuous)
                    .stroke(Color.white.opacity(focused ? 0.30 : 0.12), lineWidth: focused ? 1.6 : 1.0)
                    .blur(radius: key.contains("frost") ? 0.6 : 0.0)
            } else if key.contains("black") || key.contains("carbon") {
                LinearGradient(colors: [Color.black.opacity(0.04), Color.black.opacity(focused ? 0.22 : 0.34)], startPoint: .top, endPoint: .bottom)
            } else if key.contains("crimson") || key.contains("red") || key.contains("ruby") {
                LinearGradient(colors: [HomeGridThemeStyle.accent(for: theme).opacity(focused ? 0.22 : 0.07), Color.black.opacity(0.22)], startPoint: .topLeading, endPoint: .bottomTrailing)
            } else if key.contains("gold") || key.contains("amber") || key.contains("bronze") || key.contains("copper") {
                LinearGradient(colors: [HomeGridThemeStyle.accent(for: theme).opacity(focused ? 0.20 : 0.065), Color.black.opacity(0.20)], startPoint: .topLeading, endPoint: .bottomTrailing)
            } else if key.contains("emerald") || key.contains("green") || key.contains("purple") || key.contains("violet") || key.contains("rose") || key.contains("pink") {
                LinearGradient(colors: [HomeGridThemeStyle.accent(for: theme).opacity(focused ? 0.20 : 0.06), Color.black.opacity(0.20)], startPoint: .topLeading, endPoint: .bottomTrailing)
            } else if key.contains("neon") {
                LinearGradient(colors: [Color.cyan.opacity(focused ? 0.17 : 0.05), Color.purple.opacity(focused ? 0.10 : 0.03), Color.black.opacity(0.18)], startPoint: .topLeading, endPoint: .bottomTrailing)
            } else if key.contains("blue") {
                LinearGradient(colors: [Color.blue.opacity(focused ? 0.18 : 0.06), Color.black.opacity(0.20)], startPoint: .topLeading, endPoint: .bottomTrailing)
            } else {
                Color.clear
            }
        }
        .clipShape(RoundedRectangle(cornerRadius: 24, style: .continuous))
        .allowsHitTesting(false)
    }
}

struct HomeGridThemePicker: View {
