                            .font(.system(size: 15, weight: .black))
                        VStack(alignment: .leading, spacing: 2) {
                            Text(theme)
                                .font(.system(size: 15, weight: .black, design: .rounded))
                                .lineLimit(1)
                            Text(themeSubtitle(theme))
                                .font(.system(size: 10, weight: .heavy, design: .rounded))
                                .foregroundStyle(selectedTheme == theme ? Color.black.opacity(0.62) : Color.white.opacity(0.52))
                                .lineLimit(1)
                        }
                        Spacer(minLength: 0)
                    }
                    .foregroundStyle((selectedTheme == theme || isFocused) ? Color.black : Color.white)
                    .padding(.horizontal, 12)
                    .frame(height: 58)
                    .background(RoundedRectangle(cornerRadius: 15, style: .continuous).fill(selectedTheme == theme ? HomeGridThemeStyle.accent(for: theme).opacity(0.92) : (isFocused ? Color.orange.opacity(0.82) : Color.white.opacity(0.085))))
                    .overlay(RoundedRectangle(cornerRadius: 15, style: .continuous).stroke((selectedTheme == theme || isFocused) ? Color.white.opacity(0.90) : Color.white.opacity(0.10), lineWidth: (selectedTheme == theme || isFocused) ? 2 : 1))
                    .clipShape(RoundedRectangle(cornerRadius: 15, style: .continuous))
                    .contentShape(RoundedRectangle(cornerRadius: 15, style: .continuous))
                }
                .buttonStyle(.plain)
                .focused($focusedTheme, equals: theme)
                .modifier(SettingsRoundedFocusVisual(cornerRadius: 15))
            }
        }
        .padding(.top, 4)
    }

    private func themeSubtitle(_ theme: String) -> String {
        let key = theme.lowercased()
        if key.contains("apple") { return "glass depth" }
        if key.contains("frost") { return "3D frost" }
        if key.contains("black") { return "all black" }
        if key.contains("crimson") || key.contains("red") { return "deep red focus" }
        if key.contains("ruby") { return "ruby highlight" }
        if key.contains("gold") { return "cinema gold" }
        if key.contains("amber") { return "warm amber" }
        if key.contains("bronze") { return "bronze theater" }
        if key.contains("copper") { return "copper edge" }
        if key.contains("emerald") { return "emerald focus" }
        if key.contains("purple") { return "royal purple" }
        if key.contains("rose") { return "rose highlight" }
        if key.contains("ice") { return "cool ice blue" }
        if key.contains("neon") { return "bright edge" }
        if key.contains("carbon") { return "dark pro" }
        return "current style"
    }
}

