private struct SettingsButtonVisual: View, Equatable {
    let title: String
    let isFocused: Bool
    static func == (lhs: Self, rhs: Self) -> Bool { lhs.title == rhs.title && lhs.isFocused == rhs.isFocused }

    var body: some View {
        HStack(spacing: 13) {
            Capsule().fill(isFocused ? Color.cyan : Color.white.opacity(0.22)).frame(width: 4, height: 26)
            Text(title)
                .font(.system(size: 22, weight: isFocused ? .black : .bold, design: .rounded))
                .foregroundStyle(isFocused ? Color.black.opacity(0.88) : Color.white.opacity(0.92))
                .lineLimit(1)
            Spacer(minLength: 8)
            Image(systemName: "chevron.right")
                .font(.system(size: 13, weight: .black))
                .foregroundStyle(isFocused ? Color.black.opacity(0.62) : Color.white.opacity(0.28))
        }
        .padding(.horizontal, 22)
        .frame(minHeight: 60)
        .background(RoundedRectangle(cornerRadius: 17, style: .continuous).fill(isFocused ? Color.white.opacity(0.93) : Color.white.opacity(0.065)))
        .overlay(RoundedRectangle(cornerRadius: 17, style: .continuous).stroke(isFocused ? Color.cyan.opacity(0.88) : Color.white.opacity(0.10), lineWidth: isFocused ? 2 : 1))
        .shadow(color: isFocused ? Color.cyan.opacity(0.16) : Color.clear, radius: 18, y: 8)
        .scaleEffect(isFocused ? 1.025 : 1.0)
    }
}



struct LiveTVChannel: Identifiable, Hashable {
    let id: Int
    let logo: String
    let number: String
    let name: String
    let category: String
    let now: String
    let next: String
    let description: String
    let accent: Color
    var streamURL: String = ""
    var iconURL: String = ""
    var tvgID: String = ""
    var source: String = "Demo"
}

extension LiveTVChannel {
    var bestArtworkURL: String? {
        let cleanIcon = iconURL.trimmingCharacters(in: .whitespacesAndNewlines)
        if cleanIcon.hasPrefix("http://") || cleanIcon.hasPrefix("https://") { return cleanIcon }
        return nil
    }

    var isXtreamSource: Bool {
        source.lowercased().contains("xtream") || streamURL.lowercased().contains("/live/")
    }
}

struct LiveProgram: Identifiable, Hashable, Sendable {
    // vBRDC119: UUID-per-initialization made every guide cell look brand new to SwiftUI on
    // every provider refresh — and even on fallback `programs(for:)` calls created during a
    // normal body evaluation. Stable content identity lets tvOS retain the same program-cell
    // views until the actual schedule row changes instead of destroying/recreating them.
    let id: UInt64
    let title: String
    let width: CGFloat
    let isLive: Bool
    var description: String = ""
    var startText: String = ""
    var endText: String = ""
    var imageURL: String = ""
    // v276: keep real guide timing so the renderer uses current/future listings
    // instead of the first programs in the XMLTV file. This fixes partially
    // populated guide rows after real channels load.
    var startDate: Date? = nil
    var endDate: Date? = nil

    init(
        title: String,
        width: CGFloat,
        isLive: Bool,
        description: String = "",
        startText: String = "",
        endText: String = "",
        imageURL: String = "",
        startDate: Date? = nil,
        endDate: Date? = nil
    ) {
        self.title = title
        self.width = width
        self.isLive = isLive
        self.description = description
        self.startText = startText
        self.endText = endText
        self.imageURL = imageURL
        self.startDate = startDate
        self.endDate = endDate
        self.id = Self.makeStableID(
            title: title,
            width: width,
            startText: startText,
            endText: endText,
            startDate: startDate,
            endDate: endDate
        )
    }

    private static func makeStableID(
        title: String,
        width: CGFloat,
        startText: String,
        endText: String,
        startDate: Date?,
        endDate: Date?
    ) -> UInt64 {
        var hash: UInt64 = 1469598103934665603
        @inline(__always) func mixByte(_ byte: UInt8, into hash: inout UInt64) {
            hash ^= UInt64(byte)
            hash &*= 1099511628211
        }
        func mixString(_ value: String, into hash: inout UInt64) {
            for byte in value.utf8 { mixByte(byte, into: &hash) }
            mixByte(0xff, into: &hash)
        }
        func mixUInt64(_ value: UInt64, into hash: inout UInt64) {
            var value = value
            for _ in 0..<8 {
                mixByte(UInt8(truncatingIfNeeded: value), into: &hash)
                value >>= 8
            }
        }

        // Identity represents the schedule slot, not presentation metadata. Artwork,
        // description enrichment, width correction, and the live/not-live boundary may
        // legitimately change while SwiftUI should keep the same guide cell alive.
        mixString(title, into: &hash)
        if let startDate {
            mixUInt64(startDate.timeIntervalSince1970.bitPattern, into: &hash)
        } else {
            mixString(startText, into: &hash)
        }
        if let endDate {
            mixUInt64(endDate.timeIntervalSince1970.bitPattern, into: &hash)
        } else {
            mixString(endText, into: &hash)
            mixUInt64(Double(width).bitPattern, into: &hash)
        }
        return hash
    }

    func progress(at now: Date) -> CGFloat {
        guard let startDate, let endDate, endDate > startDate else { return 0.5 }
        let duration = endDate.timeIntervalSince(startDate)
        guard duration > 0 else { return 0.5 }
        let elapsed = now.timeIntervalSince(startDate)
        return CGFloat(min(max(elapsed / duration, 0.0), 1.0))
    }

    var liveProgress: CGFloat { progress(at: Date()) }

    func secondsRemaining(at now: Date) -> TimeInterval? {
        guard let endDate else { return nil }
        return max(0, endDate.timeIntervalSince(now))
    }

    func secondsUntilStart(at now: Date) -> TimeInterval? {
        guard let startDate else { return nil }
        return max(0, startDate.timeIntervalSince(now))
    }

    func isAiring(at now: Date) -> Bool {
        guard let startDate, let endDate, endDate > startDate else { return isLive }
        return startDate <= now && now < endDate
    }

    var hasRealTiming: Bool {
        guard let startDate, let endDate else { return false }
        return endDate > startDate
    }
}


private struct XMLTVGuideChannelSnapshot: Sendable {
    let resultKey: String
    let lookupKeys: [String]
}

/// CPU-heavy XMLTV work must never own the tvOS main thread. The parser keeps the vBRDC064
/// matching semantics but runs on a utility executor, caches repeated channel-key normalization,
/// and checks cancellation throughout long provider guides.
private enum LiveTVXMLTVBackgroundParser {
    /// One parser-local immutable toolbox. vBRDC118 had moved XMLTV off MainActor, but the
    /// helper methods still compiled 5-8 regular expressions and allocated DateFormatter
    /// objects for *every programme row*. Large Gracenote/XMLTV feeds can contain hundreds
    /// of thousands of rows, so that hidden utility work still consumed enough CPU/memory
    /// bandwidth to compete with foreground focus animation. Build these helpers once per
    /// parse operation and reuse them for its entire lifetime.
    private final class ParseContext {
        let programmeRegex: NSRegularExpression
        let channelRegex: NSRegularExpression
        let displayNameRegex: NSRegularExpression
        let titleRegex: NSRegularExpression
        let descriptionRegex: NSRegularExpression
        let iconRegex: NSRegularExpression
        let attributeRegexes: [String: NSRegularExpression]
        let digitRegex: NSRegularExpression
        let numberedNameRegex: NSRegularExpression
        let dateFormatters: [DateFormatter]
        let timeFormatter: DateFormatter

        init?() {
            do {
                programmeRegex = try NSRegularExpression(
                    pattern: #"<programme\s+([^>]*)>(.*?)</programme>"#,
                    options: [.caseInsensitive, .dotMatchesLineSeparators]
                )
                channelRegex = try NSRegularExpression(
                    pattern: #"<channel\s+[^>]*id=\"([^\"]+)\"[^>]*>(.*?)</channel>"#,
                    options: [.caseInsensitive, .dotMatchesLineSeparators]
                )
                displayNameRegex = try NSRegularExpression(
                    pattern: #"<display-name[^>]*>(.*?)</display-name>"#,
                    options: [.caseInsensitive, .dotMatchesLineSeparators]
                )
                titleRegex = try NSRegularExpression(
                    pattern: #"<title[^>]*>(.*?)</title>"#,
                    options: [.caseInsensitive, .dotMatchesLineSeparators]
                )
                descriptionRegex = try NSRegularExpression(
                    pattern: #"<desc[^>]*>(.*?)</desc>"#,
                    options: [.caseInsensitive, .dotMatchesLineSeparators]
                )
                iconRegex = try NSRegularExpression(
                    pattern: #"<icon[^>]*src=\"([^\"]+)\"[^>]*/?>"#,
                    options: [.caseInsensitive]
                )
                var attrs: [String: NSRegularExpression] = [:]
                for name in ["channel", "start", "stop"] {
                    attrs[name] = try NSRegularExpression(
                        pattern: "(?:^|\\s)" + NSRegularExpression.escapedPattern(for: name) + "=\\\"([^\\\"]*)\\\"",
                        options: [.caseInsensitive]
                    )
                }
                attributeRegexes = attrs
                digitRegex = try NSRegularExpression(pattern: #"[0-9]{3,}"#)
                numberedNameRegex = try NSRegularExpression(pattern: #"^([0-9]+(?:[.\-_][0-9]+)?)\s+(.+)$"#)
            } catch {
                return nil
            }

            let formats = [
                "yyyy-MM-dd'T'HH:mm:ss.SSSX", "yyyy-MM-dd'T'HH:mm:ssX", "yyyy-MM-dd HH:mm:ss",
                "yyyyMMddHHmmss Z", "yyyyMMddHHmmssZ", "yyyyMMddHHmmss", "yyyyMMddHHmm Z", "yyyyMMddHHmmZ"
            ]
            dateFormatters = formats.map { format in
                let formatter = DateFormatter()
                formatter.locale = Locale(identifier: "en_US_POSIX")
                formatter.timeZone = .current
                formatter.dateFormat = format
                return formatter
            }
            let display = DateFormatter()
            display.locale = .current
            display.timeZone = .current
            display.dateStyle = .none
            display.timeStyle = .short
            timeFormatter = display
        }

        func attribute(_ attrs: String, name: String) -> String {
            guard let regex = attributeRegexes[name] else { return "" }
            let ns = attrs as NSString
            guard let match = regex.firstMatch(in: attrs, range: NSRange(location: 0, length: ns.length)),
                  match.numberOfRanges > 1 else { return "" }
            return LiveTVXMLTVBackgroundParser.decodeXML(ns.substring(with: match.range(at: 1)))
                .trimmingCharacters(in: .whitespacesAndNewlines)
        }

        func tagText(_ body: String, tag: String) -> String {
            let regex: NSRegularExpression
            switch tag {
            case "title": regex = titleRegex
            case "desc": regex = descriptionRegex
            default: return ""
            }
            let ns = body as NSString
            guard let match = regex.firstMatch(in: body, range: NSRange(location: 0, length: ns.length)),
                  match.numberOfRanges > 1 else { return "" }
            return LiveTVXMLTVBackgroundParser.decodeXML(ns.substring(with: match.range(at: 1)))
        }

        func firstIcon(in body: String) -> String {
            let ns = body as NSString
            guard let match = iconRegex.firstMatch(in: body, range: NSRange(location: 0, length: ns.length)),
                  match.numberOfRanges > 1 else { return "" }
            return LiveTVXMLTVBackgroundParser.decodeXML(ns.substring(with: match.range(at: 1)))
        }

        func date(_ raw: String) -> Date? {
            let cleaned = raw.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !cleaned.isEmpty else { return nil }
            if let epoch = Double(cleaned) {
                let seconds = epoch > 100_000_000_000 ? epoch / 1000.0 : epoch
                return Date(timeIntervalSince1970: seconds)
            }
            for formatter in dateFormatters {
                if let date = formatter.date(from: cleaned) { return date }
            }
            return nil
        }

        func timeText(_ date: Date?) -> String {
            guard let date else { return "" }
            return timeFormatter.string(from: date)
        }

        func lookupKeys(_ raw: String) -> [String] {
            let value = LiveTVXMLTVBackgroundParser.decodeXML(raw).trimmingCharacters(in: .whitespacesAndNewlines)
            guard !value.isEmpty else { return [] }
            var keys = Set<String>()
            func add(_ candidate: String) {
                let clean = candidate.trimmingCharacters(in: .whitespacesAndNewlines)
                guard !clean.isEmpty else { return }
                keys.insert(clean.lowercased())
                let normalized = LiveTVXMLTVBackgroundParser.normalizeGuideKey(clean)
                if !normalized.isEmpty { keys.insert(normalized) }
            }
            add(value)
            add(value.replacingOccurrences(of: ".", with: "-"))
            add(value.replacingOccurrences(of: "-", with: "."))
            add(value.replacingOccurrences(of: "_", with: "."))
            add(value.components(separatedBy: ".").first ?? value)
            add(value.components(separatedBy: "-").first ?? value)

            let ns = value as NSString
            if let digitMatch = digitRegex.firstMatch(in: value, range: NSRange(location: 0, length: ns.length)) {
                add(ns.substring(with: digitMatch.range))
            }
            if let match = numberedNameRegex.firstMatch(in: value, range: NSRange(location: 0, length: ns.length)),
               match.numberOfRanges > 2 {
                let first = ns.substring(with: match.range(at: 1))
                let second = ns.substring(with: match.range(at: 2))
                add(first)
                add(first.replacingOccurrences(of: "-", with: "."))
                add(first.replacingOccurrences(of: ".", with: "-"))
                add(second)
            }
            return Array(keys)
        }
    }

    static func parse(
        xml: String,
        channels: [XMLTVGuideChannelSnapshot],
        guideDurationSeconds: Int,
        guideMaxProgramRows: Int
    ) -> [String: [LiveProgram]] {
        guard !Task.isCancelled, !xml.isEmpty, !channels.isEmpty, let context = ParseContext() else { return [:] }

        let channelNames = channelLookupNames(xml, context: context)
        guard !Task.isCancelled else { return [:] }

        // vBRDC119: store each programme once under its real XMLTV channel ID. The old
        // parser appended the same LiveProgram under every normalized alias (often 8-15
        // copies), multiplying guide memory and append/sort work. A reverse alias index
        // preserves the exact lookup semantics without duplicating programme payloads.
        var channelIDsByLookupKey: [String: Set<String>] = [:]
        channelIDsByLookupKey.reserveCapacity(max(64, channelNames.count * 2))
        for (channelID, aliases) in channelNames {
            for key in aliases where !key.isEmpty {
                channelIDsByLookupKey[key, default: []].insert(channelID)
            }
        }

        let ns = xml as NSString
        var programsByChannelID: [String: [LiveProgram]] = [:]
        programsByChannelID.reserveCapacity(max(64, channelNames.count))
        var programmeChannelIDsIndexed = Set<String>()
        let parseNow = Date()

        var parsedCount = 0
        context.programmeRegex.enumerateMatches(
            in: xml,
            options: [],
            range: NSRange(location: 0, length: ns.length)
        ) { match, _, stop in
            if Task.isCancelled || parsedCount >= 1_500_000 {
                stop.pointee = true
                return
            }
            guard let match, match.numberOfRanges > 2 else { return }
            parsedCount += 1
            if parsedCount.isMultiple(of: 256), Task.isCancelled {
                stop.pointee = true
                return
            }

            let attrs = ns.substring(with: match.range(at: 1))
            let body = ns.substring(with: match.range(at: 2))
            let channelID = context.attribute(attrs, name: "channel")
            guard !channelID.isEmpty else { return }

            if programmeChannelIDsIndexed.insert(channelID).inserted {
                // Some providers omit a <channel> declaration. The old parser still matched
                // those programme rows by raw ID, so preserve that fallback in the reverse index.
                for key in context.lookupKeys(channelID) where !key.isEmpty {
                    channelIDsByLookupKey[key, default: []].insert(channelID)
                }
            }

            let startRaw = context.attribute(attrs, name: "start")
            let stopRaw = context.attribute(attrs, name: "stop")
            let title = context.tagText(body, tag: "title").ifEmptyBackground("No information")
            let desc = context.tagText(body, tag: "desc")
            let programIcon = context.firstIcon(in: body)
            let startDate = context.date(startRaw)
            let endDate = context.date(stopRaw)
            let isLive: Bool
            if let startDate, let endDate {
                isLive = startDate <= parseNow && parseNow < endDate
            } else {
                isLive = false
            }
            let minutes: Int
            if let startDate, let endDate, endDate > startDate {
                minutes = max(15, min(240, Int(endDate.timeIntervalSince(startDate) / 60.0)))
            } else {
                minutes = 30
            }
            let width = CGFloat(max(120, min(560, Int((Double(minutes) / 30.0) * 120.0))))
            programsByChannelID[channelID, default: []].append(
                LiveProgram(
                    title: title,
                    width: width,
                    isLive: isLive,
                    description: desc,
                    startText: context.timeText(startDate).ifEmptyBackground(isLive ? "Now" : ""),
                    endText: context.timeText(endDate),
                    imageURL: programIcon,
                    startDate: startDate,
                    endDate: endDate
                )
            )
        }

        guard !Task.isCancelled else { return [:] }
        var resolved: [String: [LiveProgram]] = [:]
        resolved.reserveCapacity(channels.count)
        let now = Date()
        let staleCutoff = now.addingTimeInterval(-10 * 60)
        let guideCutoff = now.addingTimeInterval(TimeInterval(guideDurationSeconds))

        for (index, channel) in channels.enumerated() {
            if index.isMultiple(of: 128), Task.isCancelled { return [:] }

            var matchingChannelIDs: Set<String> = []
            for key in channel.lookupKeys {
                if let ids = channelIDsByLookupKey[key], !ids.isEmpty {
                    matchingChannelIDs.formUnion(ids)
                    // Preserve the previous first-successful-lookup-key behavior.
                    break
                }
            }
            guard !matchingChannelIDs.isEmpty else { continue }

            var found: [LiveProgram] = []
            for channelID in matchingChannelIDs {
                if let rows = programsByChannelID[channelID], !rows.isEmpty {
                    found.append(contentsOf: rows)
                }
            }
            guard !found.isEmpty else { continue }

            let sorted = found.sorted {
                ($0.startDate ?? .distantPast) < ($1.startDate ?? .distantPast)
            }
            let currentAndUpcoming = sorted.filter { program in
                if let end = program.endDate, end < staleCutoff { return false }
                if let start = program.startDate, start > guideCutoff { return false }
                return true
            }
            resolved[channel.resultKey] = Array(
                (currentAndUpcoming.isEmpty ? sorted : currentAndUpcoming).prefix(guideMaxProgramRows)
            )
        }
        return Task.isCancelled ? [:] : resolved
    }

    private static func channelLookupNames(_ xml: String, context: ParseContext) -> [String: Set<String>] {
        var out: [String: Set<String>] = [:]
        let ns = xml as NSString
        var channelCount = 0
        context.channelRegex.enumerateMatches(in: xml, options: [], range: NSRange(location: 0, length: ns.length)) { match, _, stop in
            if Task.isCancelled {
                stop.pointee = true
                return
            }
            guard let match, match.numberOfRanges > 2 else { return }
            channelCount += 1
            if channelCount > 100_000 {
                stop.pointee = true
                return
            }
            let id = decodeXML(ns.substring(with: match.range(at: 1)))
            let body = ns.substring(with: match.range(at: 2))
            var names = Set<String>()
            for key in context.lookupKeys(id) { names.insert(key) }
            let bodyNS = body as NSString
            for nameMatch in context.displayNameRegex.matches(in: body, range: NSRange(location: 0, length: bodyNS.length)) {
                guard nameMatch.numberOfRanges > 1 else { continue }
                let display = decodeXML(bodyNS.substring(with: nameMatch.range(at: 1)))
                for key in context.lookupKeys(display) { names.insert(key) }
                let parts = display.split(maxSplits: 1, whereSeparator: { $0.isWhitespace })
                if let first = parts.first {
                    for key in context.lookupKeys(String(first)) { names.insert(key) }
                }
                if parts.count > 1 {
                    for key in context.lookupKeys(String(parts[1])) { names.insert(key) }
                }
            }
            out[id] = names
        }
        return out
    }

    private static func normalizeGuideKey(_ value: String) -> String {
        var clean = value.lowercased()
        for token in ["fhd", "uhd", "4k", "hd"] {
            clean = clean.replacingOccurrences(of: token, with: "")
        }
        return clean.components(separatedBy: CharacterSet.alphanumerics.inverted).joined()
    }

    private static func decodeXML(_ value: String) -> String {
        value
            .replacingOccurrences(of: "&amp;", with: "&")
            .replacingOccurrences(of: "&lt;", with: "<")
            .replacingOccurrences(of: "&gt;", with: ">")
            .replacingOccurrences(of: "&quot;", with: "\"")
            .replacingOccurrences(of: "&#39;", with: "'")
    }
}

private extension String {
    func ifEmptyBackground(_ replacement: String) -> String { isEmpty ? replacement : self }
}

private enum LiveTVTimelineFormatter {
    static func timeRange(_ program: LiveProgram?) -> String {
        guard let program else { return "LIVE" }
        return [program.startText, program.endText].filter { !$0.isEmpty }.joined(separator: " – ").ifEmpty("LIVE")
    }

    static func remaining(_ program: LiveProgram?, at now: Date) -> String {
        guard let seconds = program?.secondsRemaining(at: now), seconds > 0 else { return "" }
        if seconds < 60 { return "<1m left" }
        let minutes = Int(ceil(seconds / 60.0))
        if minutes < 60 { return "\(minutes)m left" }
        let hours = minutes / 60
        let remainder = minutes % 60
        return remainder == 0 ? "\(hours)h left" : "\(hours)h \(remainder)m left"
    }

    static func startsIn(_ program: LiveProgram?, at now: Date) -> String {
        guard let seconds = program?.secondsUntilStart(at: now) else { return "" }
        if seconds <= 30 { return "Starting now" }
        let minutes = Int(ceil(seconds / 60.0))
        if minutes < 60 { return "in \(minutes)m" }
        let hours = minutes / 60
        let remainder = minutes % 60
        return remainder == 0 ? "in \(hours)h" : "in \(hours)h \(remainder)m"
    }
}

private struct LiveTVProgramTimelineText: View {
    let program: LiveProgram?
    let compact: Bool

    var body: some View {
        TimelineView(.periodic(from: Date(), by: 1.0)) { context in
            let range = LiveTVTimelineFormatter.timeRange(program)
            let remaining = LiveTVTimelineFormatter.remaining(program, at: context.date)
            HStack(spacing: compact ? 7 : 9) {
                Text(range)
                if !remaining.isEmpty {
                    Text("•")
                    Text(remaining)
                        .foregroundStyle(.white.opacity(0.72))
                }
            }
        }
        .font(.custom("Avenir Next Condensed", fixedSize: compact ? 12 : 14).weight(.bold))
        .tracking(0.35)
        .foregroundStyle(.white.opacity(0.86))
        .lineLimit(1)
    }
}

private struct LiveTVProgramProgressBar: View {
    let program: LiveProgram?

    var body: some View {
        TimelineView(.periodic(from: Date(), by: 1.0)) { context in
            GeometryReader { geo in
                let progress = program?.progress(at: context.date) ?? 0
                ZStack(alignment: .leading) {
                    Capsule().fill(Color.white.opacity(0.18)).frame(height: 3)
                    Capsule().fill(Color.white.opacity(0.86))
                        .frame(width: geo.size.width * max(0, min(1, progress)), height: 3)
                }
            }
        }
        .frame(height: 3)
    }
}

// vBRDC001: Quick Guide-only explicit aspect containment renderer.
// The blurred background may crop to fill the existing landscape frame, but the visible
// foreground is sized from the decoded bitmap's real pixel aspect ratio and therefore
// cannot be crop-to-filled by SwiftUI proposals. This renderer is used only by Quick Guide.
// vBRDC002: Quick Guide artwork uses its own bounded/cancellable decode lane.
// Do not feed full-resolution Gracenote bitmaps into the process-wide catalog artwork cache:
// those decodes can finish after the guide closes and compete with video/focus rendering.
// vBRDC004: bound actual ImageIO CPU work as well as network prefetch. vBRDC002 bounded
// cache size but every mounted grid card could still start its own detached decode.
private actor LiveTVArtworkDecodeGate {
    static let shared = LiveTVArtworkDecodeGate(limit: 2)

    private let limit: Int
    private var active: Int = 0
    private var waiterOrder: [UUID] = []
    private var waiters: [UUID: CheckedContinuation<Bool, Never>] = [:]
    // Cancellation can win the tiny race before a suspended continuation is registered.
    // Remember that ID briefly so registration completes immediately instead of joining the
    // ImageIO queue. The set is defensively bounded because waiter IDs are one-shot values.
    private var pendingCancellationIDs: Set<UUID> = []

    init(limit: Int) { self.limit = max(1, limit) }

    func acquire() async -> Bool {
        if Task.isCancelled { return false }
        if active < limit {
            active += 1
            return true
        }

        let id = UUID()
        return await withTaskCancellationHandler(operation: {
            await withCheckedContinuation { continuation in
                if pendingCancellationIDs.remove(id) != nil || Task.isCancelled {
                    continuation.resume(returning: false)
                    return
                }
                waiters[id] = continuation
                waiterOrder.append(id)
            }
        }, onCancel: {
            Task { await self.cancelWaiter(id) }
        })
    }

    private func cancelWaiter(_ id: UUID) {
        if let continuation = waiters.removeValue(forKey: id) {
            waiterOrder.removeAll { $0 == id }
            continuation.resume(returning: false)
            return
        }
        pendingCancellationIDs.insert(id)
        if pendingCancellationIDs.count > 256 {
            pendingCancellationIDs.removeAll(keepingCapacity: true)
        }
    }

    func release() {
        while !waiterOrder.isEmpty {
            let id = waiterOrder.removeFirst()
            guard let continuation = waiters.removeValue(forKey: id) else { continue }
            continuation.resume(returning: true)
            return
        }
        active = max(0, active - 1)
    }
}

/// vBRDC297: Nuvio-style in-flight coalescing for Live TV artwork. Grid, Guide,
/// Quick Guide and focused-program surfaces can request the same station/program image
/// on the same frame. Share one fetch/decode task instead of multiplying URLSession and
/// ImageIO work during remote navigation.
private actor LiveTVArtworkSharedFetchRegistry {
    struct Key: Hashable {
        let url: URL
        let maxPixelSize: Int
        let allowDuringFullScreenPlayback: Bool
    }

    // vBRDC347: A coalesced fetch belongs to its *subscribers*, not to the last
    // URL that requested it. Cancel the worker when its last visible/prefetch owner
    // disappears. The old registry let orphaned image fetches/decodes run for tens
    // of seconds as the user paged through channels, then an older completion
    // could erase the registry handle for a newer same-URL request.
    private struct Entry {
        let token: UUID
        let task: Task<UIImage?, Never>
        var subscribers: Set<UUID>
    }
    private var tasks: [Key: Entry] = [:]

    func image(
        for key: Key,
        operation: @escaping @Sendable () async -> UIImage?
    ) async -> UIImage? {
        guard !Task.isCancelled else { return nil }
        let subscriber = UUID()
        let token: UUID
        let task: Task<UIImage?, Never>
        if var entry = tasks[key] {
            entry.subscribers.insert(subscriber)
            tasks[key] = entry
            token = entry.token
            task = entry.task
        } else {
            token = UUID()
            task = Task(priority: .utility) { await operation() }
            tasks[key] = Entry(token: token, task: task, subscribers: [subscriber])
        }
        let result = await withTaskCancellationHandler(operation: {
            await task.value
        }, onCancel: {
            Task { await self.unsubscribe(key: key, token: token, subscriber: subscriber) }
        })
        unsubscribe(key: key, token: token, subscriber: subscriber)
        return Task.isCancelled ? nil : result
    }

    private func unsubscribe(key: Key, token: UUID, subscriber: UUID) {
        guard var entry = tasks[key], entry.token == token else { return }
        entry.subscribers.remove(subscriber)
        if entry.subscribers.isEmpty {
            entry.task.cancel()
            tasks.removeValue(forKey: key)
        } else {
            tasks[key] = entry
        }
    }

    func cancelAll() {
        for entry in tasks.values { entry.task.cancel() }
        tasks.removeAll()
    }
}

@MainActor
private final class LiveTVBoundedArtworkLoader: ObservableObject {
    @Published private(set) var image: UIImage?
    @Published private(set) var imageURL: URL?
    // vBRDC089: remember real network/decode failures for the lifetime of this
    // mounted artwork owner so a broken Gracenote URL can fall through to the
    // channel icon instead of pinning the Live TV card to a black spinner.
    @Published private(set) var failedURLs: Set<URL> = []

    // Mounted SwiftUI StateObjects retain their current UIImage independently of NSCache.
    // Artwork 3 intentionally keeps LiveTVScreen mounted behind catalog overlays, so a
    // cache purge alone cannot recover that memory. Keep only weak references to loaders
    // so lifecycle/memory-pressure events can release their view-owned bitmap as well.
    private final class WeakBox {
        weak var value: LiveTVBoundedArtworkLoader?
        init(_ value: LiveTVBoundedArtworkLoader) { self.value = value }
    }
    private static var liveLoaders: [WeakBox] = []

    // vBRDC002: Live TV is a high-churn surface. Keep a separate, display-sized decode
    // reservoir instead of retaining provider/TMDB original-resolution bitmaps in every
    // grid/Quick Guide view. The original URL is unchanged; only the in-memory decode is
    // bounded to more than twice the visible card resolution.
    private static let cache: NSCache<NSString, UIImage> = {
        let cache = NSCache<NSString, UIImage>()
        cache.countLimit = 96
        cache.totalCostLimit = 96 * 1024 * 1024
        return cache
    }()
    // vBRDC179: station logos get their own small, long-lived reservoir. Program/Gracenote
    // artwork can churn aggressively while scrolling, but it can no longer evict the network
    // identity bitmaps needed by every card/footer/Guide channel lane.
    private static let logoCache: NSCache<NSString, UIImage> = {
        let cache = NSCache<NSString, UIImage>()
        cache.countLimit = 256
        cache.totalCostLimit = 24 * 1024 * 1024
        return cache
    }()
    // vBRDC099: exact recent Live TV pixels survive full-screen playback in a tiny
    // bounded return reservoir while the main 64 MB high-churn cache is released.
    private static let playbackReturnCache: NSCache<NSString, UIImage> = {
        let cache = NSCache<NSString, UIImage>()
        cache.countLimit = 36
        cache.totalCostLimit = 32 * 1024 * 1024
        return cache
    }()
    private static let imageSession: URLSession = {
        // vBRDC297: Live TV used an ephemeral URLSession, so even correctly cached Grid/Guide
        // artwork was thrown away at process exit. Match the catalog artwork architecture:
        // URLCache is a fast first layer and PersistentArtworkSourceCache is the durable source
        // of truth when CDN/proxy cache headers are weak.
        let configuration = URLSessionConfiguration.default
        configuration.requestCachePolicy = .returnCacheDataElseLoad
        configuration.timeoutIntervalForRequest = 18
        configuration.timeoutIntervalForResource = 28
        configuration.waitsForConnectivity = true
        configuration.httpMaximumConnectionsPerHost = 4
        configuration.urlCache = URLCache(
            memoryCapacity: 32 * 1024 * 1024,
            diskCapacity: 256 * 1024 * 1024,
            diskPath: "DebridChannelsLiveArtwork-v297"
        )
        return URLSession(configuration: configuration)
    }()
    private static let sharedFetchRegistry = LiveTVArtworkSharedFetchRegistry()
    private static var prefetchTasks: [URL: Task<Void, Never>] = [:]
    private static var prefetchTokens: [URL: UUID] = [:]
    static var activeJobCount: Int {
        // Weak boxes do not prolong StateObject lifetimes. Count *actual* owned
        // tasks, so sustained-scroll testing can detect surviving work at idle.
        prefetchTasks.count + liveLoaders.reduce(0) { total, box in
            total + (box.value?.loadTask == nil ? 0 : 1)
        }
    }
    private static let maxPrefetchTasks = 1
    private static var fullScreenPlaybackSuspended = false

    private var loadTask: Task<Void, Never>?
    // vBRDC140: every network/decode attempt has a generation. This lets an older
    // cancelled attempt finish harmlessly without clearing/replacing the handle for a
    // newer request that happens to use the same URL after a lifecycle re-arm.
    private var requestGeneration: UInt64 = 0
    private var requestedCacheKey: NSString?
    private var requestedURL: URL?
    private var requestedMaxPixelSize: Int = 0
    // vBRDC140: channel identity is the Live TV grid's guaranteed first-paint fallback.
    // Its small 384 px bitmap may publish as soon as it is decoded instead of waiting behind
    // a long navigation/surface frame gate. Program/Gracenote artwork still uses the normal
    // frame-budget publication lane.
    private var requestedAllowsImmediatePublication: Bool = false
    // vBRDC009: playback Quick Guide is an active on-screen playback surface, not
    // background grid work. Its dedicated Frosted Edges cards may load while the
    // off-screen Live TV grid remains suspended.
    private var requestedAllowsFullScreenPlayback: Bool = false

    init() {
        Self.liveLoaders.removeAll { $0.value == nil }
        Self.liveLoaders.append(WeakBox(self))
    }

    func load(
        _ url: URL?,
        maxPixelSize: Int,
        allowDuringFullScreenPlayback: Bool = false,
        preserveCurrentImage: Bool = false,
        allowImmediatePublication: Bool = false
    ) {
        guard !Self.fullScreenPlaybackSuspended || allowDuringFullScreenPlayback else {
            suspendPreservingImage()
            return
        }
        guard let url else {
            cancel()
            image = nil
            imageURL = nil
            requestedCacheKey = nil
            return
        }
        let key = Self.cacheKey(url: url, maxPixelSize: maxPixelSize)
        if imageURL == url, requestedCacheKey == key, image != nil { return }

        // vBRDC140 permanent cold-start fix: the force-bootstrap token is a retry signal,
        // not permission to destroy a request that is already fetching/decoding the exact
        // same URL + decode bucket. vBRDC139 could cancel its own slow DNS/TLS request at
        // every reinforcement token, leaving mounted cards generic until a tab round-trip.
        if requestedURL == url, requestedCacheKey == key, loadTask != nil {
            if allowImmediatePublication { requestedAllowsImmediatePublication = true }
            return
        }

        loadTask?.cancel()
        loadTask = nil
        // Grid tiles may remain physically mounted under another UNITY surface. When the
        // next program/source needs a fresh decode, retain the last valid bitmap until the
        // replacement is ready so the shared root never exposes a generic/empty card.
        if !preserveCurrentImage {
            image = nil
            imageURL = nil
        }
        requestedURL = url
        requestedMaxPixelSize = maxPixelSize
        requestedAllowsImmediatePublication = allowImmediatePublication
        requestedAllowsFullScreenPlayback = allowDuringFullScreenPlayback
        requestedCacheKey = key

        let logoRequest = Self.isLogoRequest(maxPixelSize: maxPixelSize, allowImmediatePublication: allowImmediatePublication)
        if logoRequest, let cached = Self.logoCache.object(forKey: key) {
            markURLSuccessful(url)
            imageURL = url
            image = cached
            return
        }
        if let cached = Self.cache.object(forKey: key) {
            markURLSuccessful(url)
            imageURL = url
            image = cached
            return
        }
        if let cached = Self.playbackReturnCache.object(forKey: key) {
            let cost = cached.cgImage.map { $0.bytesPerRow * $0.height } ?? 0
            Self.cache.setObject(cached, forKey: key, cost: cost)
            markURLSuccessful(url)
            imageURL = url
            image = cached
            return
        }

        requestGeneration &+= 1
        let generation = requestGeneration
        loadTask = Task { @MainActor [weak self] in
            guard let self else { return }
            defer {
                // Never let a completed/cancelled task leave a stale non-nil ownership
                // handle. Conversely, an older generation must not clear a newer request.
                if self.requestGeneration == generation { self.loadTask = nil }
            }
            var decoded = await Self.fetchAndDecode(
                url: url,
                maxPixelSize: maxPixelSize,
                allowDuringFullScreenPlayback: allowDuringFullScreenPlayback
            )
            guard !Task.isCancelled, self.requestedCacheKey == key else { return }

            // vBRDC097: a cold tvOS launch can briefly have an interface but no settled
            // DNS/TLS route. A single transient miss must not poison a persistent Live TV
            // tile's failedURLs set until scrolling recreates its StateObject. waitsForConnectivity
            // handles the normal case; this one bounded retry covers a connection that was
            // established while the first request was already unwinding.
            if decoded == nil,
               !Self.fullScreenPlaybackSuspended || allowDuringFullScreenPlayback {
                try? await Task.sleep(nanoseconds: 650_000_000)
                guard !Task.isCancelled, self.requestedCacheKey == key else { return }
                decoded = await Self.fetchAndDecode(
                    url: url,
                    maxPixelSize: maxPixelSize,
                    allowDuringFullScreenPlayback: allowDuringFullScreenPlayback
                )
                guard !Task.isCancelled, self.requestedCacheKey == key else { return }
            }

            // vBRDC140: successful network/decode work is reusable immediately. The old
            // ordering waited for the SwiftUI publication lane *before* inserting into the
            // bounded cache, so a focus move/surface handoff could cancel a fully-decoded
            // bitmap and force the next appearance to download/decode it again.
            if let decoded {
                Self.store(decoded, key: key, logoRequest: logoRequest)
            }

            // Channel logos are the low-cost guaranteed identity fallback and may publish
            // immediately. Also never frame-gate the *first real bitmap* of an otherwise blank
            // visible card: if a provider has no logo but persisted Gracenote art is valid,
            // making that first paint wait behind navigation recreates the cold-start blank-grid
            // failure. Once a fallback bitmap already exists, higher-cost program upgrades still
            // yield to active navigation/surface geometry through the process-wide runtime.
            let needsFirstRealPaint = self.image == nil
            if !self.requestedAllowsImmediatePublication && !needsFirstRealPaint {
                guard await UnityFrameRuntime.shared.waitUntilVisualPublicationPermitted(
                    critical: false,
                    allowDuringPlayback: allowDuringFullScreenPlayback
                ) else { return }
                guard !Task.isCancelled, self.requestedCacheKey == key else { return }
            }

            guard !Task.isCancelled, self.requestedCacheKey == key else { return }
            guard let decoded else {
                // A genuine fetch/decode failure is presentation state: publish it so
                // LiveTVGridTileArtwork immediately advances to its next candidate.
                // Cancellation/suspension exits through the guard above and is never
                // recorded as a broken artwork URL. Grid callers can preserve their last
                // valid image while the fallback candidate begins loading.
                self.markURLFailed(url)
                if !preserveCurrentImage {
                    self.image = nil
                    self.imageURL = nil
                }
                return
            }
            self.markURLSuccessful(url)
            self.imageURL = url
            self.image = decoded
        }
    }

    func resetFailedURLsForAuthoritativeRefresh() {
        // Guide publication is an authoritative new opportunity to resolve artwork. In
        // particular, a first-launch connectivity miss must be retryable without requiring
        // LazyVGrid to destroy/recreate this tile by scrolling it off screen.
        if !failedURLs.isEmpty { failedURLs.removeAll() }
    }

    private func markURLSuccessful(_ url: URL) {
        guard failedURLs.contains(url) else { return }
        failedURLs.remove(url)
    }

    private func markURLFailed(_ url: URL) {
        guard !failedURLs.contains(url) else { return }
        failedURLs.insert(url)
    }

    func suspendPreservingImage() {
        // vBRDC095 UNITY visual continuity: a covered persistent Live TV tile must stop
        // network/decode work without throwing away the exact pixels already visible under
        // Home/Movies/Shows. Clearing image/imageURL here was the reason the persistent root
        // immediately fell back to generic channel-name cards as soon as Catalog took focus.
        loadTask?.cancel()
        loadTask = nil
    }

    func cancel() {
        loadTask?.cancel()
        loadTask = nil
        // StateObject lifetime can outlive a view's visible lifetime inside Lazy grids.
        // The bounded static NSCache is the warm reservoir; do not let an off-screen view
        // hold a second strong UIImage reference indefinitely.
        image = nil
        imageURL = nil
        requestedURL = nil
        requestedMaxPixelSize = 0
        requestedAllowsImmediatePublication = false
        requestedAllowsFullScreenPlayback = false
        requestedCacheKey = nil
    }

    static func prefetch(_ urls: [URL], maxPixelSize: Int, cancelObsolete: Bool = true) {
        guard !fullScreenPlaybackSuspended, !VODExclusivePlaybackGate.isActive else { return }
        let unique = Array(Set(urls)).prefix(12)
        let keep = Set(unique)
        if cancelObsolete { cancelObsoletePrefetches(keeping: keep) }

        for url in unique {
            let key = cacheKey(url: url, maxPixelSize: maxPixelSize)
            let logoRequest = maxPixelSize <= 384
            if (logoRequest && logoCache.object(forKey: key) != nil) || cache.object(forKey: key) != nil || prefetchTasks[url] != nil { continue }
            if prefetchTasks.count >= maxPrefetchTasks { break }

            let token = UUID()
            prefetchTokens[url] = token
            let task = Task { @MainActor in
                let decoded = await fetchAndDecode(url: url, maxPixelSize: maxPixelSize)
                // A cancelled older task must never clear/overwrite its replacement.
                guard prefetchTokens[url] == token else { return }
                prefetchTokens.removeValue(forKey: url)
                prefetchTasks.removeValue(forKey: url)
                guard !Task.isCancelled else { return }
                if let decoded { store(decoded, key: key, logoRequest: logoRequest) }
            }
            prefetchTasks[url] = task
        }
    }

    static func cancelObsoletePrefetches(keeping urls: Set<URL>) {
        let obsolete = prefetchTasks.keys.filter { !urls.contains($0) }
        for url in obsolete {
            prefetchTokens.removeValue(forKey: url)
            prefetchTasks[url]?.cancel()
            prefetchTasks.removeValue(forKey: url)
        }
    }

    private static func snapshotMountedArtworkForReturn(reason: String) {
        // Keep this reservoir rolling instead of clearing it before every snapshot. There are
        // two legitimate playback-entry callers: LiveTVScreen captures before setting
        // playbackURL, then RootView suspends after the hierarchy may already be disappearing.
        // Clearing here let the second caller erase the first good snapshot when it captured
        // zero owners — exactly the kind of return-to-grid blank we are preventing.
        var retained: [WeakBox] = []
        retained.reserveCapacity(liveLoaders.count)
        var captured = 0
        for box in liveLoaders {
            guard let loader = box.value else { continue }
            retained.append(box)
            guard let image = loader.image,
                  let imageURL = loader.imageURL else { continue }
            let pixelSize = loader.requestedMaxPixelSize > 0 ? loader.requestedMaxPixelSize : 768
            let key = cacheKey(url: imageURL, maxPixelSize: pixelSize)
            let cost = image.cgImage.map { $0.bytesPerRow * $0.height } ?? 0
            playbackReturnCache.setObject(image, forKey: key, cost: cost)
            if isLogoRequest(maxPixelSize: pixelSize, allowImmediatePublication: loader.requestedAllowsImmediatePublication) {
                logoCache.setObject(image, forKey: key, cost: cost)
            }
            captured += 1
        }
        liveLoaders = retained
        print("[LiveTVArtwork][vBRDC099] return snapshot captured=\(captured) mounted=\(retained.count) reason=\(reason)")
    }

    static func prepareForFullScreenPlayback(reason: String) {
        snapshotMountedArtworkForReturn(reason: reason)
    }

    static func suspendForCoveredSurface(reason: String) {
        prefetchTokens.removeAll()
        for task in prefetchTasks.values { task.cancel() }
        prefetchTasks.removeAll()
        // Retain current visible pixels, but cancel underlying work that no longer
        // has a Live TV owner. Catalogue artwork uses its separate loader/cache.
        liveLoaders.removeAll { $0.value == nil }
        for box in liveLoaders { box.value?.suspendPreservingImage() }
        Task { await sharedFetchRegistry.cancelAll() }
        #if DEBUG
        print("[LiveTVLifecycle][vBRDC347] suspended owners=\(liveLoaders.count) reason=\(reason)")
        #endif
    }

    static func releaseCacheAndPrefetch(reason: String) {
        prefetchTokens.removeAll()
        for task in prefetchTasks.values { task.cancel() }
        prefetchTasks.removeAll()
        Task { await sharedFetchRegistry.cancelAll() }
        cache.removeAllObjects()
        logoCache.removeAllObjects()
        playbackReturnCache.removeAllObjects()
        print("[LiveTVMemory][vBRDC002] released bounded Live TV cache/prefetch reason=\(reason)")
    }

    static func releaseTransientResources(
        reason: String,
        preserveVisibleRequests: Bool = false,
        preservePlaybackReturnCache: Bool = false
    ) {
        if preservePlaybackReturnCache {
            snapshotMountedArtworkForReturn(reason: "\(reason) pre-release")
        }
        prefetchTokens.removeAll()
        for task in prefetchTasks.values { task.cancel() }
        prefetchTasks.removeAll()
        cache.removeAllObjects()
        if !preservePlaybackReturnCache { playbackReturnCache.removeAllObjects() }

        var retained: [WeakBox] = []
        retained.reserveCapacity(liveLoaders.count)
        for box in liveLoaders {
            guard let loader = box.value else { continue }
            loader.releaseViewOwnedImage(preserveRequest: preserveVisibleRequests)
            retained.append(box)
        }
        liveLoaders = retained
        print("[LiveTVMemory][vBRDC004] released bounded Live TV artwork cache + \(retained.count) mounted bitmap owner(s) preserveRequests=\(preserveVisibleRequests) reason=\(reason)")
    }

    static func beginFullScreenPlaybackSuspension(reason: String) {
        fullScreenPlaybackSuspended = true
        releaseTransientResources(
            reason: reason,
            preserveVisibleRequests: true,
            preservePlaybackReturnCache: true
        )
    }

    static func endFullScreenPlaybackSuspension() {
        fullScreenPlaybackSuspended = false
    }

    static func resumeRetainedRequests() {
        guard !fullScreenPlaybackSuspended else { return }
        liveLoaders.removeAll { $0.value == nil }
        for box in liveLoaders {
            guard let loader = box.value,
                  loader.loadTask == nil,
                  let url = loader.requestedURL,
                  loader.requestedMaxPixelSize > 0,
                  (loader.image == nil || loader.imageURL != url) else { continue }
            // Cancellation/decoder suspension is never evidence that a Gracenote URL is bad.
            // Make the retained request authoritative on return instead of waiting for a new
            // LazyVGrid owner/scroll to clear the tile-local failure ladder.
            loader.resetFailedURLsForAuthoritativeRefresh()
            loader.load(
                url,
                maxPixelSize: loader.requestedMaxPixelSize,
                allowDuringFullScreenPlayback: loader.requestedAllowsFullScreenPlayback,
                preserveCurrentImage: loader.image != nil,
                allowImmediatePublication: loader.requestedAllowsImmediatePublication
            )
        }
    }

    private func releaseViewOwnedImage(preserveRequest: Bool) {
        loadTask?.cancel()
        loadTask = nil
        image = nil
        imageURL = nil
        requestedCacheKey = nil
        if !preserveRequest {
            requestedURL = nil
            requestedMaxPixelSize = 0
            requestedAllowsImmediatePublication = false
            requestedAllowsFullScreenPlayback = false
        }
    }

    private static func normalizedDecodeBudget(_ requested: Int) -> Int {
        // vBRDC297: share common decoded sizes across Grid/Guide/Quick Guide instead of
        // keeping near-duplicate 420/480/512/etc. bitmaps of the same artwork in memory.
        // Keep enough buckets for logos, cards, guide hero art and full-width artwork.
        let value = max(320, requested)
        let buckets = [320, 384, 512, 640, 768, 1024, 1280, 1600, 2048, 2560]
        return buckets.first(where: { $0 >= value }) ?? value
    }

    private static func cacheKey(url: URL, maxPixelSize: Int) -> NSString {
        let bucket = normalizedDecodeBudget(maxPixelSize)
        return "\(url.absoluteString)|\(bucket)" as NSString
    }

    private static func isLogoRequest(maxPixelSize: Int, allowImmediatePublication: Bool) -> Bool {
        allowImmediatePublication && maxPixelSize <= 384
    }

    private static func store(_ image: UIImage, key: NSString, logoRequest: Bool = false) {
        let cost = image.cgImage.map { $0.bytesPerRow * $0.height } ?? 0
        if logoRequest {
            logoCache.setObject(image, forKey: key, cost: cost)
        } else {
            cache.setObject(image, forKey: key, cost: cost)
        }
        playbackReturnCache.setObject(image, forKey: key, cost: cost)
    }

    private static func fetchAndDecode(
        url: URL,
        maxPixelSize: Int,
        allowDuringFullScreenPlayback: Bool = false
    ) async -> UIImage? {
        let bucket = normalizedDecodeBudget(maxPixelSize)
        let key = LiveTVArtworkSharedFetchRegistry.Key(
            url: url,
            maxPixelSize: bucket,
            allowDuringFullScreenPlayback: allowDuringFullScreenPlayback
        )
        return await sharedFetchRegistry.image(for: key) {
            await fetchAndDecodeUnshared(
                url: url,
                maxPixelSize: bucket,
                allowDuringFullScreenPlayback: allowDuringFullScreenPlayback
            )
        }
    }

    private static func fetchAndDecodeUnshared(
        url: URL,
        maxPixelSize: Int,
        allowDuringFullScreenPlayback: Bool
    ) async -> UIImage? {
        guard !Task.isCancelled else { return nil }

        // Disk-first, URL-keyed source bytes. This is shared with normal catalog artwork,
        // so an image already seen anywhere in Signal can become an instant Live TV hit.
        if let data = await PersistentArtworkSourceCache.data(for: url), !data.isEmpty {
            guard !Task.isCancelled else { return nil }
            guard await LiveTVArtworkDecodeGate.shared.acquire() else { return nil }
            let decodeTask = Task.detached(priority: .utility) {
                guard !Task.isCancelled else { return nil as UIImage? }
                return downsampledImage(data: data, maxPixelSize: maxPixelSize)
            }
            let decoded = await withTaskCancellationHandler(operation: {
                await decodeTask.value
            }, onCancel: {
                decodeTask.cancel()
            })
            await LiveTVArtworkDecodeGate.shared.release()
            return Task.isCancelled ? nil : decoded
        }

        do {
            guard !fullScreenPlaybackSuspended || allowDuringFullScreenPlayback else { return nil }
            var request = URLRequest(url: url)
            request.cachePolicy = .returnCacheDataElseLoad
            request.timeoutInterval = 18
            request.setValue("image/avif,image/webp,image/apng,image/*,*/*;q=0.8", forHTTPHeaderField: "Accept")
            request.setValue("DebridChannels-tvOS-LiveArtwork/1.0", forHTTPHeaderField: "User-Agent")
            let (data, response) = try await imageSession.data(for: request)
            guard !Task.isCancelled, (!fullScreenPlaybackSuspended || allowDuringFullScreenPlayback), !data.isEmpty else { return nil }
            if let http = response as? HTTPURLResponse, !(200...299).contains(http.statusCode) { return nil }

            // URLSession.data(for:) returns a non-optional URLResponse. Cache the
            // successful response directly; conditional binding here does not compile.
            imageSession.configuration.urlCache?.storeCachedResponse(
                CachedURLResponse(response: response, data: data, storagePolicy: .allowed),
                for: request
            )
            PersistentArtworkSourceCache.write(data, for: url)

            // Keep the existing Live TV-specific two-decode ceiling. The new shared request
            // registry above additionally prevents duplicate same-image decodes.
            guard await LiveTVArtworkDecodeGate.shared.acquire() else { return nil }
            guard !Task.isCancelled, (!fullScreenPlaybackSuspended || allowDuringFullScreenPlayback) else {
                await LiveTVArtworkDecodeGate.shared.release()
                return nil
            }
            let decodeTask = Task.detached(priority: .utility) {
                guard !Task.isCancelled else { return nil as UIImage? }
                return downsampledImage(data: data, maxPixelSize: maxPixelSize)
            }
            let decoded = await withTaskCancellationHandler(operation: {
                await decodeTask.value
            }, onCancel: {
                decodeTask.cancel()
            })
            await LiveTVArtworkDecodeGate.shared.release()
            guard !Task.isCancelled, (!fullScreenPlaybackSuspended || allowDuringFullScreenPlayback) else { return nil }
            return decoded
        } catch {
            return nil
        }
    }

    nonisolated private static func downsampledImage(data: Data, maxPixelSize: Int) -> UIImage? {
        autoreleasepool {
            guard let source = CGImageSourceCreateWithData(data as CFData, nil) else { return nil }
            let options: [CFString: Any] = [
                kCGImageSourceCreateThumbnailFromImageAlways: true,
                kCGImageSourceCreateThumbnailWithTransform: true,
                kCGImageSourceShouldCacheImmediately: true,
                kCGImageSourceThumbnailMaxPixelSize: max(320, maxPixelSize)
            ]
            guard let cgImage = CGImageSourceCreateThumbnailAtIndex(source, 0, options as CFDictionary) else { return nil }
            return UIImage(cgImage: cgImage, scale: 1.0, orientation: .up)
        }
    }
}

private struct LiveTVQuickGuideContainedArtworkFrame: View {
    let imageURL: String
    let cornerRadius: CGFloat
    var fallbackText: String = "TV"

    @StateObject private var loader = LiveTVBoundedArtworkLoader()

    private var resolvedURL: URL? {
        PremiumArtworkURL.url(imageURL)
    }

    var body: some View {
        GeometryReader { geo in
            ZStack {
                Color.black.opacity(0.90)

                if let image = loader.image, loader.imageURL == resolvedURL {
                    blurredFill(image: image, size: geo.size)
                    containedForeground(image: image, size: geo.size)
                } else {
                    Text(fallbackText)
                        .font(.custom("Avenir Next", fixedSize: 18).weight(.heavy))
                        .foregroundStyle(.white.opacity(0.72))
                }
            }
            .frame(width: geo.size.width, height: geo.size.height)
            .clipped()
        }
        .clipShape(RoundedRectangle(cornerRadius: cornerRadius, style: .continuous))
        // vBRDC009: this view exists only inside the Live TV playback Quick Guide.
        // Allow its visible Gracenote artwork through the playback suspension gate while
        // the hidden Live TV grid and its prefetch/decode corridor remain suspended.
        .onAppear { loader.load(resolvedURL, maxPixelSize: 768, allowDuringFullScreenPlayback: true) }
        .onChange(of: resolvedURL) { newValue in
            loader.load(newValue, maxPixelSize: 768, allowDuringFullScreenPlayback: true)
        }
        .onDisappear { loader.cancel() }
    }

    private func blurredFill(image: UIImage, size: CGSize) -> some View {
        Image(uiImage: image)
            .resizable()
            .interpolation(.high)
            .antialiased(true)
            .scaledToFill()
            .frame(width: size.width, height: size.height)
            .clipped()
            .blur(radius: 12)
            .saturation(1.06)
            .opacity(0.46)
    }

    private func containedForeground(image: UIImage, size: CGSize) -> some View {
        let fitted = Self.aspectFitSize(imageSize: image.size, containerSize: size, inset: 4)
        return Image(uiImage: image)
            .resizable()
            .interpolation(.high)
            .antialiased(true)
            .frame(width: fitted.width, height: fitted.height)
            .shadow(color: .black.opacity(0.34), radius: 4, y: 2)
    }

    private static func aspectFitSize(imageSize: CGSize, containerSize: CGSize, inset: CGFloat) -> CGSize {
        let sourceWidth = max(1, imageSize.width)
        let sourceHeight = max(1, imageSize.height)
        let availableWidth = max(1, containerSize.width - inset * 2)
        let availableHeight = max(1, containerSize.height - inset * 2)
        let scale = min(availableWidth / sourceWidth, availableHeight / sourceHeight)
        return CGSize(width: sourceWidth * scale, height: sourceHeight * scale)
    }
}

// Quick Guide-only UP NEXT presentation. The Live TV playback information box keeps
// using LiveTVNextProgramPreview and is intentionally not routed through this type.
private struct LiveTVQuickGuideNextProgramPreview: View {
    let program: LiveProgram
    let compact: Bool

    var body: some View {
        TimelineView(.periodic(from: Date(), by: 1.0)) { context in
            HStack(spacing: compact ? 9 : 11) {
                nextArtwork(program)
                VStack(alignment: .leading, spacing: 3) {
                    Text("UP NEXT")
                        .font(.custom("Avenir Next Condensed", fixedSize: compact ? 10 : 11).weight(.heavy))
                        .tracking(0.9)
                        .foregroundStyle(Color.orange.opacity(0.90))
                    Text(program.title)
                        .font(.custom("Avenir Next", fixedSize: compact ? 13 : 15).weight(.semibold))
                        .foregroundStyle(.white.opacity(0.94))
                        .lineLimit(1)
                    Text([program.startText, LiveTVTimelineFormatter.startsIn(program, at: context.date)].filter { !$0.isEmpty }.joined(separator: " • "))
                        .font(.custom("Avenir Next Condensed", fixedSize: compact ? 10 : 12).weight(.bold))
                        .foregroundStyle(.white.opacity(0.62))
                        .lineLimit(1)
                }
                Spacer(minLength: 0)
            }
        }
    }

    @ViewBuilder
    private func nextArtwork(_ program: LiveProgram) -> some View {
        if PremiumArtworkURL.url(program.imageURL) != nil, !program.imageURL.isEmpty {
            LiveTVQuickGuideContainedArtworkFrame(
                imageURL: program.imageURL,
                cornerRadius: compact ? 7 : 9,
                fallbackText: "TV"
            )
            .frame(width: compact ? 72 : 92, height: compact ? 44 : 56)
        } else {
            fallbackArtwork
                .frame(width: compact ? 72 : 92, height: compact ? 44 : 56)
        }
    }

    private var fallbackArtwork: some View {
        RoundedRectangle(cornerRadius: compact ? 7 : 9, style: .continuous)
            .fill(Color.white.opacity(0.06))
            .overlay(Image(systemName: "tv").font(.system(size: compact ? 15 : 18, weight: .semibold)).foregroundStyle(.white.opacity(0.38)))
    }
}

private struct LiveTVProgramArtworkFrame: View {
    let imageURL: String
    let cornerRadius: CGFloat
    var fallbackText: String = "TV"

    @StateObject private var loader = LiveTVBoundedArtworkLoader()

    private var resolvedURL: URL? {
        PremiumArtworkURL.url(imageURL)
    }

    var body: some View {
        ZStack {
            Color.black.opacity(0.88)
            if let image = loader.image, loader.imageURL == resolvedURL {
                // v1172: preserve the entire Gracenote/program frame instead of crop-to-fill.
                // A softly enlarged copy fills the container behind the uncropped foreground,
                // so portrait/4:3/landscape provider art all reads as a complete image without
                // introducing empty bars or changing the surrounding Quick Guide geometry.
                Image(uiImage: image)
                    .resizable()
                    .interpolation(.high)
                    .antialiased(true)
                    .scaledToFill()
                    .blur(radius: 13)
                    .saturation(1.03)
                    .opacity(0.34)
                Image(uiImage: image)
                    .resizable()
                    .interpolation(.high)
                    .antialiased(true)
                    .scaledToFit()
                    .padding(2)
            } else {
                Text(fallbackText)
                    .font(.custom("Avenir Next", fixedSize: 18).weight(.heavy))
                    .foregroundStyle(.white.opacity(0.72))
            }
        }
        .clipShape(RoundedRectangle(cornerRadius: cornerRadius, style: .continuous))
        .onAppear { loader.load(resolvedURL, maxPixelSize: 512, allowDuringFullScreenPlayback: true) }
        .onChange(of: resolvedURL) { newValue in
            loader.load(newValue, maxPixelSize: 512, allowDuringFullScreenPlayback: true)
        }
        .onDisappear { loader.cancel() }
    }
}

private struct LiveTVBoundedFitArtwork: View {
