struct CachedLiveProgram: Codable, Sendable {
    var title: String
    var width: Double
    var isLive: Bool
    var description: String
    var startText: String
    var endText: String
    var imageURL: String
    var startTimestamp: Double?
    var endTimestamp: Double?

    init(_ program: LiveProgram) {
        title = program.title
        width = Double(program.width)
        isLive = program.isLive
        description = program.description
        startText = program.startText
        endText = program.endText
        imageURL = program.imageURL
        startTimestamp = program.startDate?.timeIntervalSince1970
        endTimestamp = program.endDate?.timeIntervalSince1970
    }

    var liveProgram: LiveProgram {
        LiveProgram(
            title: title,
            width: CGFloat(width),
            isLive: isLive,
            description: description,
            startText: startText,
            endText: endText,
            imageURL: imageURL,
            startDate: startTimestamp.map { Date(timeIntervalSince1970: $0) },
            endDate: endTimestamp.map { Date(timeIntervalSince1970: $0) }
        )
    }
}

