@MainActor
final class LiveTVSourceModel: ObservableObject {
    @Published var channels: [LiveTVChannel] = LiveTVScreen.sampleChannels {
        didSet { rebuildChannelBrowseIndex() }
    }
    @Published var guidePrograms: [String: [LiveProgram]] = [:] {
        didSet { currentProgramCache.removeAll(keepingCapacity: true) }
    }
    @Published var status: String = "Live TV demo lineup ready. Configure Channels DVR, M3U/XMLTV, or Xtream in Settings, then reopen Live TV."
    @Published var isLoading: Bool = false

    // vBRDC088: channel/category projection is provider-data work, not focus work. The old
    // LiveTVScreen recomputed category names and filtered the complete lineup inside every
    // SwiftUI body pass, so a single remote move could rescan thousands of channels. Build
    // immutable browse indexes only when the provider publishes a new channel array.
    private var channelBrowseIndex: [String: [LiveTVChannel]] = [:]
    private var channelBrowsePositionIndex: [String: [Int: Int]] = [:]
    private var indexedCategoryNames: [String] = []
    private var indexedHDChannels: [LiveTVChannel] = []
    private var indexedHDPositionByID: [Int: Int] = [:]
    private var indexedChannelByID: [Int: LiveTVChannel] = [:]
    private var indexedChannelPositionByID: [Int: Int] = [:]

    init() {
        rebuildChannelBrowseIndex()
    }

    // vBRDC119: @Published sends before assignment, so even assigning byte-for-byte
    // equivalent Live TV state invalidates every observing guide/grid surface. Provider
    // refreshes and native EPG batches can legitimately reproduce the same snapshot.
    // Gate those publications here so unchanged authoritative state remains authoritative
    // without paying a full SwiftUI invalidation + browse-index rebuild.
    @discardableResult
    private func publishChannelsIfChanged(_ next: [LiveTVChannel]) -> Bool {
        guard next != channels else { return false }
        channels = next
        return true
    }

    @discardableResult
    private func publishGuideProgramsIfChanged(_ next: [String: [LiveProgram]]) -> Bool {
        guard next != guidePrograms else { return false }
        guidePrograms = next
        return true
    }

    private func mergeGuideProgramsAtomically(_ incoming: [String: [LiveProgram]]) -> [String: [LiveProgram]] {
        guard !incoming.isEmpty else { return guidePrograms }
        var next = guidePrograms
        next.reserveCapacity(max(next.count, incoming.count))
        for (key, programs) in incoming where !programs.isEmpty {
            if next[key] != programs { next[key] = programs }
        }
        _ = publishGuideProgramsIfChanged(next)
        return next
    }

    private func rebuildChannelBrowseIndex() {
        var groups: [String: [LiveTVChannel]] = [:]
        var groupPositions: [String: [Int: Int]] = [:]
        var categoryNames: [String] = []
        var seenCategories = Set<String>()
        var hdChannels: [LiveTVChannel] = []
        var hdPositions: [Int: Int] = [:]
        var channelByID: [Int: LiveTVChannel] = [:]
        var channelPositionByID: [Int: Int] = [:]
        categoryNames.reserveCapacity(32)
        hdChannels.reserveCapacity(min(channels.count, 256))
        channelByID.reserveCapacity(channels.count)
        channelPositionByID.reserveCapacity(channels.count)

        for (position, channel) in channels.enumerated() {
            channelByID[channel.id] = channel
            channelPositionByID[channel.id] = position
            let category = channel.category.trimmingCharacters(in: .whitespacesAndNewlines)
            if !category.isEmpty {
                let groupPosition = groups[category]?.count ?? 0
                groups[category, default: []].append(channel)
                groupPositions[category, default: [:]][channel.id] = groupPosition
                if seenCategories.insert(category).inserted {
                    categoryNames.append(category)
                }
            }
            if category == "HD" || (Int(channel.number) ?? 0) >= 6000 || channel.name.localizedCaseInsensitiveContains("HD") {
                hdPositions[channel.id] = hdChannels.count
                hdChannels.append(channel)
            }
        }
        channelBrowseIndex = groups
        channelBrowsePositionIndex = groupPositions
        indexedCategoryNames = categoryNames
        indexedHDChannels = hdChannels
        indexedHDPositionByID = hdPositions
        indexedChannelByID = channelByID
        indexedChannelPositionByID = channelPositionByID

        // vBRDC124: provider lineups can be replaced repeatedly during long sessions. Keep
        // per-channel lookup/current-program caches bounded to identities that still exist.
        if !channelMatchingKeyCache.isEmpty {
            channelMatchingKeyCache = channelMatchingKeyCache.filter { channelByID[$0.key] != nil }
        }
        if !currentProgramCache.isEmpty {
            currentProgramCache = currentProgramCache.filter { channelByID[$0.key] != nil }
        }
    }

    func browseCategoryNames() -> [String] {
        indexedCategoryNames
    }

    func browseChannels(inExactCategory category: String) -> [LiveTVChannel] {
        channelBrowseIndex[category] ?? []
    }

    func browseHDChannels() -> [LiveTVChannel] {
        indexedHDChannels
    }

    // vBRDC119: focused Live TV cards ask for their channel and visible position several
    // times per Siri Remote move. Use the provider-built indexes instead of rescanning a
    // 5k–30k channel array during focus geometry.
    func channel(id: Int) -> LiveTVChannel? { indexedChannelByID[id] }

    func browsePosition(of channelID: Int, category: String) -> Int? {
        if category == "All" { return indexedChannelPositionByID[channelID] }
        if category == "HD" { return indexedHDPositionByID[channelID] }
        return channelBrowsePositionIndex[category]?[channelID]
    }

    func browseFavoriteChannels(ids: Set<Int>) -> [LiveTVChannel] {
        ids.compactMap { indexedChannelByID[$0] }
            .sorted {
                indexedChannelPositionByID[$0.id, default: .max]
                    < indexedChannelPositionByID[$1.id, default: .max]
            }
    }

    private static let providerSession: URLSession = {
        let configuration = URLSessionConfiguration.ephemeral
        configuration.requestCachePolicy = .reloadIgnoringLocalCacheData
        configuration.timeoutIntervalForRequest = 75
        configuration.timeoutIntervalForResource = 120
        configuration.waitsForConnectivity = true
        configuration.httpMaximumConnectionsPerHost = 6
        return URLSession(configuration: configuration)
    }()

    private let guideCacheManager = LiveTVGuideCacheManager()
    // v1172: cache normalized guide lookup keys by stable channel identity. The Live TV
    // grid asks for current-program data while focus moves; rebuilding the same Set of
    // normalized tvgID/number/name/logo aliases for every visible tile caused avoidable
    // MainActor work. The fingerprint invalidates naturally when provider metadata changes.
    private var channelMatchingKeyCache: [Int: (fingerprint: String, keys: [String])] = [:]
    // vBRDC124: `currentProgram(for:)` is called while SwiftUI evaluates each visible Live
    // TV card. Cache the resolved row until its real schedule boundary (or provider/channel
    // publication) so a focus move does not rescan up to 96 EPG rows for every mounted card.
    private struct CurrentProgramCacheEntry {
        let channel: LiveTVChannel
        let program: LiveProgram?
        let validUntil: Date
    }
    private var currentProgramCache: [Int: CurrentProgramCacheEntry] = [:]
    private let liveGuideDurationSeconds = 43_200
    private let liveGuideMaxProgramRows = 96
    private static var sessionChannels: [LiveTVChannel] = []
    private static var sessionGuidePrograms: [String: [LiveProgram]] = [:]
    private static var sessionStatus: String = ""
    // v1094 Phase 1 stabilization: full-screen playback retains only current + next
    // program rows per channel, but those rows are rebound to the process-wide guide at
    // program boundaries. This stays lightweight while preventing Gracenote metadata and
    // artwork from disappearing during long playback or a Quick Guide channel handoff.
    private static var playbackQuickGuideChannels: [LiveTVChannel] = []
    private static var playbackQuickGuidePrograms: [Int: [LiveProgram]] = [:]
    private var playbackQuickGuidePrograms: [Int: [LiveProgram]] = [:] {
        didSet {
            if oldValue != playbackQuickGuidePrograms {
                currentProgramCache.removeAll(keepingCapacity: true)
            }
        }
    }

    static func cachedRealAmbientChannels(limit: Int? = nil) -> [LiveTVChannel] {
        let sampleIDs = Set(LiveTVScreen.sampleChannels.map(\.id))
        let boundedLimit = max(1, limit ?? Int.max)

        func realChannels(from source: [LiveTVChannel]) -> [LiveTVChannel] {
            var output: [LiveTVChannel] = []
            output.reserveCapacity(min(source.count, boundedLimit == Int.max ? source.count : boundedLimit))
            for channel in source {
                guard !sampleIDs.contains(channel.id),
                      !channel.streamURL.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
                      channel.source.caseInsensitiveCompare("Demo") != .orderedSame else { continue }
                output.append(channel)
                if output.count >= boundedLimit { break }
            }
            return output
        }

        let realSession = realChannels(from: sessionChannels)
        if !realSession.isEmpty { return realSession }
        let cached = LiveTVGuideCacheManager().loadChannelSnapshots()?.map { $0.uiChannel() } ?? []
        return realChannels(from: cached)
    }

    static func cachedAmbientProgram(for channel: LiveTVChannel) -> LiveProgram? {
        let keys = [
            "\(channel.source)|\(channel.number)|\(channel.name)",
            channel.tvgID,
            channel.number,
            channel.name,
            channel.logo
        ]
        .map { $0.trimmingCharacters(in: .whitespacesAndNewlines).lowercased() }
        .filter { !$0.isEmpty }

        for key in keys {
            if let direct = sessionGuidePrograms[key]?.first { return direct }
        }

        for (storedKey, programs) in sessionGuidePrograms where !programs.isEmpty {
            let key = storedKey.lowercased()
            if keys.contains(where: { key.contains($0) || $0.contains(key) }) {
                return programs.first
            }
        }

        if !channel.now.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            return LiveProgram(title: channel.now, width: 240, isLive: true, description: channel.description, startText: "Now", endText: "")
        }
        return nil
    }

    private var hasLoadedThisAppSession = false
    // v918: only the newest Live TV refresh may publish or persist results.
    // Prevents a slower HDHomeRun/raw-lineup task from replacing a newer Gracenote merge.
    private var refreshGeneration: Int = 0
    // vBRDC203: disk cache decode is explicitly off-MainActor. The task handle coalesces
    // Search/Live/root calls so one process generation never decodes the same huge EPG twice.
    private var persistedStateRestoreTask: Task<Void, Never>? = nil

    private static func largeStateDirectory() -> URL? {
        guard let base = FileManager.default.urls(for: .cachesDirectory, in: .userDomainMask).first else { return nil }
        let dir = base.appendingPathComponent("DebridChannelsLargeState", isDirectory: true)
        try? FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        return dir
    }

    private static func largeStateFile(named name: String) -> URL? {
        largeStateDirectory()?.appendingPathComponent(name)
    }

    private static func removeLargeStateFile(named name: String) {
        guard let url = largeStateFile(named: name) else { return }
        try? FileManager.default.removeItem(at: url)
    }

    private func loadLargeStateData(defaultsKey: String, fileName: String) -> Data? {
        if let url = Self.largeStateFile(named: fileName),
           let data = try? Data(contentsOf: url),
           !data.isEmpty {
            return data
        }
        let data = UserDefaults.standard.data(forKey: defaultsKey)
        if let data, !data.isEmpty {
            if let url = Self.largeStateFile(named: fileName) {
                try? data.write(to: url, options: [.atomic])
            }
            UserDefaults.standard.removeObject(forKey: defaultsKey)
        }
        return data
    }

    private func saveLargeStateData(_ data: Data, defaultsKey: String, fileName: String) {
        guard !data.isEmpty else {
            UserDefaults.standard.removeObject(forKey: defaultsKey)
            Self.removeLargeStateFile(named: fileName)
            return
        }
        if let url = Self.largeStateFile(named: fileName) {
            try? data.write(to: url, options: [.atomic])
        }
        UserDefaults.standard.removeObject(forKey: defaultsKey)
    }

    private var shouldRefreshNow: Bool { guideCacheManager.shouldRefreshNow }

    // vBRDC203: guide health is independent from lineup health and from the 3-hour TTL.
    // A process can retain thousands of valid channels while every cached EPG row has aged
    // out during Apple TV sleep. Treat that as an incomplete guide even though dictionaries
    // are non-empty, otherwise refreshIfNeeded can incorrectly say "already loaded" for hours.
    private func hasCurrentOrUpcomingGuideCoverage(
        _ guide: [String: [LiveProgram]],
        now: Date = Date()
    ) -> Bool {
        guard !guide.isEmpty else { return false }
        let futureCutoff = now.addingTimeInterval(6 * 60 * 60)
        var inspectedChannels = 0
        var healthyChannels = 0
        for programs in guide.values where !programs.isEmpty {
            inspectedChannels += 1
            let healthy = programs.prefix(16).contains { program in
                let title = program.title.trimmingCharacters(in: .whitespacesAndNewlines)
                guard !title.isEmpty else { return false }
                if program.hasRealTiming,
                   let start = program.startDate,
                   let end = program.endDate {
                    return end > now && start < futureCutoff
                }
                // Some provider-native "now" rows do not carry XMLTV dates. Count only an
                // explicitly-live untimed row; ordinary stale untimed text does not satisfy
                // the health gate.
                return program.isLive
            }
            if healthy { healthyChannels += 1 }
            if inspectedChannels >= 128 { break }
        }
        guard inspectedChannels > 0 else { return false }
        let requiredHealthy = min(12, max(1, inspectedChannels / 8))
        return healthyChannels >= requiredHealthy
    }

    private var hasConfiguredLiveTVSource: Bool {
        let defaults = UserDefaults.standard
        let dvrBase = defaults.string(forKey: "liveChannelsDvrBaseURL")?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let hdhrManual = defaults.string(forKey: "liveHDHomeRunManualURL")?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let m3uURLs = Self.parseSourceList(defaults.string(forKey: "liveM3UURL") ?? "")
        let xtreamAccounts = Self.parseXtreamAccounts(
            saved: defaults.string(forKey: "liveXtreamAccounts") ?? "",
            currentServer: defaults.string(forKey: "liveXtreamServer") ?? "",
            currentUser: defaults.string(forKey: "liveXtreamUsername") ?? "",
            currentPass: defaults.string(forKey: "liveXtreamPassword") ?? ""
        )
        // A guide-only XMLTV URL is not a lineup source, so it should not arm an endless
        // recovery loop by itself. Any configured lineup provider does: if it temporarily
        // returns zero channels after sleep/network loss, Force Guide keeps retrying until
        // the provider comes back instead of treating an empty lineup as success.
        return !dvrBase.isEmpty || !hdhrManual.isEmpty || !m3uURLs.isEmpty || !xtreamAccounts.isEmpty
    }

    var guideRecoveryRequired: Bool {
        // Phase 4 / vBRDC327: guide health is evaluated independently from the lineup and
        // independently from the three-hour provider TTL. A healthy cached guide remains
        // visible while recovery runs; an expired/empty guide can no longer masquerade as
        // "loaded" simply because thousands of channels are present.
        // Recovery has to have a real provider to call. This prevents a stale cached lineup
        // from arming a five-minute retry forever after the user intentionally removed every
        // Live TV source, while a configured-but-temporarily-empty provider still retries.
        guard hasConfiguredLiveTVSource else { return false }
        let hasRealLineup = channels.contains {
            !$0.streamURL.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty &&
            $0.source.caseInsensitiveCompare("Demo") != .orderedSame
        }
        guard hasRealLineup else { return true }
        return !hasCurrentOrUpcomingGuideCoverage(guidePrograms)
    }

    func retryIncompleteGuideRecovery() async {
        guard guideRecoveryRequired,
              !VODExclusivePlaybackGate.isActive,
              !Task.isCancelled else { return }
        // Keep the last-known-good visible status and EPG snapshot stable while retrying.
        // Repeated recovery attempts must not invalidate the entire Grid/Guide just to paint
        // "retrying" text.
        // Use the bounded post-sleep publication lane but no blocking spinner: an existing
        // channel grid remains usable while recovery keeps probing in the background.
        await refreshFromConfiguredSources(showLoadingIndicator: false, userInitiatedForce: true)
    }

    func refreshIfNeeded() async {
        guard !VODExclusivePlaybackGate.isActive, !Task.isCancelled else { return }
        await restorePersistedStateBeforeRefreshIfNeeded()

        // vBRDC141: restore the proven v987 cache contract. A complete persisted lineup +
        // guide is immediately authoritative after relaunch and honors the normal refresh TTL.
        // Artwork rehydration is independent from provider/XMLTV refresh, so cold-start logos
        // and Gracenote pixels never need a giant provider reload just to paint the grid.
        guard !hasLoadedThisAppSession || shouldRefreshNow || channels.isEmpty || guideRecoveryRequired else {
            status = "Live TV lineup + current guide kept loaded • \(channels.count) channels • refreshes after 3 hours"
            return
        }

        // A scheduled/TTL refresh runs silently when useful cached UI is already visible.
        // The top-right spinner is reserved for a genuinely blocking first load or an explicit
        // user Force Refresh, so a slow/unreachable configured source cannot look stuck.
        let hasUsableVisualState = !channels.isEmpty && !guidePrograms.isEmpty
        let recoveringIncompleteGuide = guideRecoveryRequired
        await refreshFromConfiguredSources(
            showLoadingIndicator: !hasUsableVisualState,
            userInitiatedForce: recoveringIncompleteGuide
        )
    }

    func forceRefreshGuide() async {
        guard !VODExclusivePlaybackGate.isActive, !Task.isCancelled else { return }
        status = "Force refreshing Live TV guide…"
        guideCacheManager.resetRefreshClock()
        // vBRDC201: explicit Force Guide is authoritative. After a long tvOS idle/sleep,
        // a stale navigation/surface ownership bit must not leave a successfully fetched
        // Gracenote/XMLTV guide waiting forever on the normal courtesy publication lane.
        // Provider generations and the VOD gate still protect against stale/wrong playback
        // publication; only the user-initiated frame-lane wait becomes bounded.
        hasLoadedThisAppSession = false
        await refreshFromConfiguredSources(showLoadingIndicator: true, userInitiatedForce: true)
    }

    func suspendForVODPlayback() {
        refreshGeneration &+= 1
        persistedStateRestoreTask?.cancel()
        persistedStateRestoreTask = nil
        isLoading = false
    }

    // vBRDC081: a secondary/auxiliary Live TV model (Sports) must not publish a stale
    // refresh after its surface has left. The retained process-wide Live TV session remains
    // untouched; only this model generation is invalidated.
    func suspendForSurfaceExit() {
        refreshGeneration &+= 1
        persistedStateRestoreTask?.cancel()
        persistedStateRestoreTask = nil
        isLoading = false
    }

    // Keep current + next Gracenote rows before releasing the grid's heavy guide arrays.
    // The process-wide session guide remains authoritative and is used for in-place boundary
    // refreshes while full-screen playback stays mounted.
    func prepareForFullScreenPlayback() {
        refreshGeneration &+= 1
        isLoading = false
        Self.playbackQuickGuideChannels = channels
        let sourceGuide = !guidePrograms.isEmpty ? guidePrograms : Self.sessionGuidePrograms
        let compact = makePlaybackQuickGuidePrograms(
            channels: channels,
            guide: sourceGuide,
            previous: Self.playbackQuickGuidePrograms,
            activeChannelID: nil,
            now: Date()
        )
        if !compact.isEmpty {
            Self.playbackQuickGuidePrograms = compact
        }
        channels = []
        guidePrograms = [:]
        playbackQuickGuidePrograms = [:]
        status = "Live TV grid state released for full-screen playback"
    }

    func loadPlaybackQuickGuideSnapshot() {
        refreshGeneration &+= 1
        isLoading = false
        let snapshot = !Self.playbackQuickGuideChannels.isEmpty
            ? Self.playbackQuickGuideChannels
            : (!Self.sessionChannels.isEmpty ? Self.sessionChannels : LiveTVScreen.sampleChannels)

        channels = snapshot
        guidePrograms = [:]

        // Never overwrite a still-valid local snapshot with an empty shared dictionary.
        // This protects an incoming channel generation from a departing player's teardown.
        if !Self.playbackQuickGuidePrograms.isEmpty {
            playbackQuickGuidePrograms = Self.playbackQuickGuidePrograms
        } else if playbackQuickGuidePrograms.isEmpty {
            let rebuilt = makePlaybackQuickGuidePrograms(
                channels: snapshot,
                guide: Self.sessionGuidePrograms,
                previous: [:],
                activeChannelID: nil,
                now: Date()
            )
            if !rebuilt.isEmpty {
                playbackQuickGuidePrograms = rebuilt
                Self.playbackQuickGuidePrograms = rebuilt
            }
        }

        refreshPlaybackQuickGuideSnapshot()
        let rowCount = playbackQuickGuidePrograms.values.reduce(0) { $0 + $1.count }
        status = "Persistent Gracenote Quick Guide ready • \(channels.count) channels • \(rowCount) current/next rows"
    }

    /// Rebinds the compact player guide to the full process-wide guide without restarting
    /// playback. Passing an active channel ID limits periodic work to the channel on screen;
    /// opening the Quick Guide refreshes all channels in one atomic publication.
    func refreshPlaybackQuickGuideSnapshot(activeChannelID: Int? = nil) {
        let snapshot = !channels.isEmpty
            ? channels
            : (!Self.playbackQuickGuideChannels.isEmpty ? Self.playbackQuickGuideChannels : Self.sessionChannels)
        guard !snapshot.isEmpty else { return }

        let previous = !playbackQuickGuidePrograms.isEmpty
            ? playbackQuickGuidePrograms
            : Self.playbackQuickGuidePrograms
        let refreshed = makePlaybackQuickGuidePrograms(
            channels: snapshot,
            guide: Self.sessionGuidePrograms,
            previous: previous,
            activeChannelID: activeChannelID,
            now: Date()
        )
        guard !refreshed.isEmpty else { return }

        Self.playbackQuickGuideChannels = snapshot
        Self.playbackQuickGuidePrograms = refreshed
        if refreshed != playbackQuickGuidePrograms {
            playbackQuickGuidePrograms = refreshed
        }
    }

    func releasePlaybackQuickGuideSnapshot(clearShared: Bool = true) {
        refreshGeneration &+= 1
        isLoading = false
        channels = []
        guidePrograms = [:]
        playbackQuickGuidePrograms = [:]
        if clearShared {
            Self.playbackQuickGuideChannels = []
            Self.playbackQuickGuidePrograms = [:]
        }
        status = clearShared
            ? "Live TV player quick-guide state released"
            : "Departing Live TV generation released local Quick Guide state"
    }

    private func makePlaybackQuickGuidePrograms(
        channels: [LiveTVChannel],
        guide: [String: [LiveProgram]],
        previous: [Int: [LiveProgram]],
        activeChannelID: Int?,
        now: Date
    ) -> [Int: [LiveProgram]] {
        var output = activeChannelID == nil ? [:] : previous
        output.reserveCapacity(max(output.count, channels.count))

        for channel in channels where activeChannelID == nil || channel.id == activeChannelID {
            let prior = previous[channel.id] ?? []
            let candidates = playbackGuidePrograms(for: channel, guide: guide)
            let compact = currentAndNextPlaybackPrograms(from: candidates, previous: prior, now: now)
            if !compact.isEmpty {
                output[channel.id] = compact
            } else if !prior.isEmpty {
                // Last-known-good data must remain visible through partial/failed refreshes.
                output[channel.id] = prior
            }
        }
        return output
    }

    private func playbackGuidePrograms(
        for channel: LiveTVChannel,
        guide: [String: [LiveProgram]]
    ) -> [LiveProgram] {
        guard !guide.isEmpty else { return [] }

        let directKeys = [channelKey(channel)]
            + (channel.isXtreamSource ? xtreamGuideLookupKeys(for: channel) : [])
            + channelMatchingKeys(channel)
        for key in directKeys {
            if let direct = guide[key], !direct.isEmpty { return direct }
        }

        // Defensive fallback for older session dictionaries whose key format predates
        // channelKey(_:). This is used only when direct identity lookup failed.
        let identities = [channel.tvgID, channel.number, channel.name, channel.logo]
            .map { normalizeGuideKey($0) }
            .filter { !$0.isEmpty }
        for (storedKey, programs) in guide where !programs.isEmpty {
            let normalizedStored = normalizeGuideKey(storedKey)
            guard !normalizedStored.isEmpty else { continue }
            if identities.contains(where: { normalizedStored.contains($0) || $0.contains(normalizedStored) }) {
                return programs
            }
        }
        return []
    }

    private func currentAndNextPlaybackPrograms(
        from programs: [LiveProgram],
        previous: [LiveProgram],
        now: Date
    ) -> [LiveProgram] {
        guard !programs.isEmpty else { return previous }
        let sorted = programs.sorted {
            ($0.startDate ?? .distantPast) < ($1.startDate ?? .distantPast)
        }

        let currentIndex = sorted.firstIndex { program in
            guard let start = program.startDate, let end = program.endDate else { return false }
            return start <= now && now < end
        }
        let upcomingIndex = sorted.firstIndex { program in
            guard let start = program.startDate else { return false }
            return start > now
        }

        let startIndex: Int
        if let currentIndex {
            startIndex = currentIndex
        } else if let upcomingIndex {
            startIndex = upcomingIndex
        } else if sorted.allSatisfy({ !$0.hasRealTiming }) {
            startIndex = 0
        } else {
            // The provider's current window may have expired while a refresh is unavailable.
            // Keep the previous real Gracenote snapshot instead of showing blank/fallback rows.
            return previous
        }

        let endIndex = min(sorted.count, startIndex + 2)
        return sorted[startIndex..<endIndex].map { candidate in
            playbackProgramRetainingMetadata(candidate, previous: previous)
        }
    }

    private func playbackProgramRetainingMetadata(
        _ candidate: LiveProgram,
        previous: [LiveProgram]
    ) -> LiveProgram {
        guard let prior = previous.first(where: { playbackProgramIdentityMatches($0, candidate) }) else {
            return candidate
        }

        let candidateImage = candidate.imageURL.trimmingCharacters(in: .whitespacesAndNewlines)
        let candidateDescription = candidate.description.trimmingCharacters(in: .whitespacesAndNewlines)
        let candidateStart = candidate.startText.trimmingCharacters(in: .whitespacesAndNewlines)
        let candidateEnd = candidate.endText.trimmingCharacters(in: .whitespacesAndNewlines)
        let priorScore = [prior.imageURL, prior.description, prior.startText, prior.endText]
            .filter { !$0.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }.count
        let candidateScore = [candidateImage, candidateDescription, candidateStart, candidateEnd]
            .filter { !$0.isEmpty }.count

        // Reuse the existing object (and stable UUID) when it already contains at least
        // as much metadata. This prevents the 30-second boundary check from republishing
        // unchanged SwiftUI state.
        if priorScore >= candidateScore { return prior }

        return LiveProgram(
            title: candidate.title,
            width: candidate.width,
            isLive: candidate.isLive,
            description: candidateDescription.ifEmpty(prior.description),
            startText: candidateStart.ifEmpty(prior.startText),
            endText: candidateEnd.ifEmpty(prior.endText),
            imageURL: candidateImage.ifEmpty(prior.imageURL),
            startDate: candidate.startDate ?? prior.startDate,
            endDate: candidate.endDate ?? prior.endDate
        )
    }

    private func playbackProgramIdentityMatches(_ lhs: LiveProgram, _ rhs: LiveProgram) -> Bool {
        guard lhs.title.caseInsensitiveCompare(rhs.title) == .orderedSame else { return false }
        if let lhsStart = lhs.startDate, let rhsStart = rhs.startDate {
            return abs(lhsStart.timeIntervalSince(rhsStart)) < 90
        }
        return lhs.startText == rhs.startText && lhs.endText == rhs.endText
    }

    // v535: when an Xtream account is changed to Sports Only, the previous Full TV disk/session lineup
    // must be invalidated immediately. Otherwise the Live TV grid can visually keep old Xtream channels
    // until the three-hour cache expires, which makes Sports Only look broken.
    static func invalidatePersistedLineupCacheForSourceModeChange() {
        LiveTVGuideCacheManager.clearPersistedCache()
        sessionChannels = []
        sessionGuidePrograms = [:]
        sessionStatus = ""
    }

    nonisolated static func accent(for category: String) -> Color {
        switch category.lowercased() {
        case "sports": return .red
        case "news": return .red
        case "kids": return .orange
        case "movies": return .cyan
        case "hd": return .blue
        case "favorites": return .indigo
        case "comedy": return .mint
        default: return .gray
        }
    }

    private func publishRetainedLiveTVSessionIfAvailable() -> Bool {
        guard !Self.sessionChannels.isEmpty else { return false }
        _ = publishChannelsIfChanged(Self.sessionChannels)
        _ = publishGuideProgramsIfChanged(Self.sessionGuidePrograms)
        hasLoadedThisAppSession = true
        status = Self.sessionStatus.ifEmpty("Live TV session retained • \(channels.count) channels • \(guidePrograms.values.reduce(0) { $0 + $1.count }) guide rows")
        return true
    }

    private func applyPersistedLiveTVSnapshot(_ snapshot: LiveTVPersistedGuideSnapshot) {
        // A provider refresh may have populated the process-wide session while disk decoding
        // was in flight. Never let an older persisted snapshot replace that newer generation.
        if publishRetainedLiveTVSessionIfAvailable() { return }
        _ = publishChannelsIfChanged(snapshot.channels.map { $0.uiChannel() })
        if !snapshot.guide.isEmpty {
            _ = publishGuideProgramsIfChanged(snapshot.guide)
            Self.sessionChannels = channels
            Self.sessionGuidePrograms = snapshot.guide
            Self.sessionStatus = "Cached Live TV lineup and guide artwork restored • \(channels.count) channels"
            hasLoadedThisAppSession = true
            status = Self.sessionStatus
        } else {
            hasLoadedThisAppSession = false
            status = "Cached Live TV lineup shown while guide reloads • \(channels.count) channels"
        }
    }

    func loadCachedOrDemo() {
        // vBRDC203: retained in-process state is still synchronous and effectively free.
        // Cold disk state is restored asynchronously so Search/Live onAppear never JSON-
        // decodes a large persisted guide on MainActor.
        if publishRetainedLiveTVSessionIfAvailable() { return }
        guard persistedStateRestoreTask == nil,
              !VODExclusivePlaybackGate.isActive else { return }
        persistedStateRestoreTask = VODExclusiveWorkRegistry.start {
            let snapshot = await self.guideCacheManager.loadPersistedStateAsync()
            guard !Task.isCancelled, !VODExclusivePlaybackGate.isActive else {
                self.persistedStateRestoreTask = nil
                return
            }
            if let snapshot { self.applyPersistedLiveTVSnapshot(snapshot) }
            self.persistedStateRestoreTask = nil
        }
    }

    private func restorePersistedStateBeforeRefreshIfNeeded() async {
        if publishRetainedLiveTVSessionIfAvailable() { return }
        if persistedStateRestoreTask == nil { loadCachedOrDemo() }
        if let task = persistedStateRestoreTask { await task.value }
        _ = publishRetainedLiveTVSessionIfAvailable()
    }

    private func persistGuidePrograms(_ guide: [String: [LiveProgram]]) {
        guideCacheManager.persistGuidePrograms(guide, maxRows: liveGuideMaxProgramRows)
    }

    // vBRDC152: real provider channels must never be held hostage by Gracenote/XMLTV.
    // On a true cold/demo bootstrap, publish the provider lineup as soon as it arrives and
    // let guide/artwork enrichment continue afterward. This removes the indefinite demo-card
    // + spinner state when a guide endpoint is slow/unreachable while preserving the final
    // authoritative guide publication and normal cached-session behavior.
    private func publishLineupFirstIfNeeded(_ candidates: [LiveTVChannel], generation: Int, reason: String) async {
        guard generation == refreshGeneration,
              !Task.isCancelled,
              !VODExclusivePlaybackGate.isActive else { return }

        let showingOnlyDemoFallback = channels.isEmpty || channels.allSatisfy { $0.source.caseInsensitiveCompare("Demo") == .orderedSame }
        guard showingOnlyDemoFallback else { return }

        let real = dedupe(candidates).filter {
            !$0.streamURL.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty &&
            $0.source.caseInsensitiveCompare("Demo") != .orderedSame
        }
        guard !real.isEmpty else { return }

        // Give active D-pad geometry a short courtesy window, but never let a transient
        // frame-lane ownership bug suppress an already-fetched lineup indefinitely.
        _ = await UnityFrameRuntime.shared.waitUntilPermitted(.interactiveMetadata, maxWait: 0.45)
        guard generation == refreshGeneration,
              !Task.isCancelled,
              !VODExclusivePlaybackGate.isActive else { return }

        let nextChannels = real.sorted {
            channelSortKey($0.number) < channelSortKey($1.number) ||
            (channelSortKey($0.number) == channelSortKey($1.number) && $0.name < $1.name)
        }
        _ = publishChannelsIfChanged(nextChannels)

        // Persist identity immediately, but deliberately do NOT mark the guide refresh clock
        // complete. A relaunch can restore real channel logos/names while the guide retries.
        let persist = nextChannels.map {
            LiveTVLoadedChannel(
                id: $0.id, logo: $0.logo, number: $0.number, name: $0.name,
                category: $0.category, now: $0.now, next: $0.next,
                description: $0.description, streamURL: $0.streamURL,
                iconURL: $0.iconURL, tvgID: $0.tvgID, source: $0.source
            )
        }
        guideCacheManager.persistChannels(persist)
        status = "Live TV channels ready • guide/artwork loading in background • \(nextChannels.count) channels • \(reason)"

        // Once real channels are visible, the full-screen spinner is no longer truthful.
        // Gracenote/XMLTV enrichment continues silently and will republish richer cards later.
        isLoading = false
    }

    private func guideRetainingArtwork(_ guide: [String: [LiveProgram]], previous: [String: [LiveProgram]]) -> [String: [LiveProgram]] {
        guard !guide.isEmpty, !previous.isEmpty else { return guide }
        var merged = guide
        for (key, programs) in guide {
            let prior = previous[key] ?? []
            guard !prior.isEmpty else { continue }
            merged[key] = programs.enumerated().map { index, program in
                guard program.imageURL.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return program }
                let matched = prior.first { $0.title.caseInsensitiveCompare(program.title) == .orderedSame && !$0.imageURL.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
                    ?? (prior.indices.contains(index) ? prior[index] : nil)
                guard let imageURL = matched?.imageURL.trimmingCharacters(in: .whitespacesAndNewlines), !imageURL.isEmpty else { return program }
                return LiveProgram(title: program.title, width: program.width, isLive: program.isLive, description: program.description, startText: program.startText, endText: program.endText, imageURL: imageURL, startDate: program.startDate, endDate: program.endDate)
            }
        }
        return merged
    }

    func refreshFromConfiguredSources(showLoadingIndicator: Bool = true, userInitiatedForce: Bool = false) async {
        guard !VODExclusivePlaybackGate.isActive, !Task.isCancelled else { return }
        refreshGeneration &+= 1
        let generation = refreshGeneration
        isLoading = showLoadingIndicator
        defer {
            if generation == refreshGeneration { isLoading = false }
        }

        func awaitGuidePublicationLane() async -> Bool {
            if userInitiatedForce {
                // Give active focus geometry a short chance to settle, then honor the user's
                // explicit force request even if a stale post-sleep transient owner never
                // publishes another revision. Do not bypass scene/playback/cancellation gates.
                _ = await UnityFrameRuntime.shared.waitUntilPermitted(.interactiveMetadata, maxWait: 0.80)
                return !Task.isCancelled
                    && !VODExclusivePlaybackGate.isActive
                    && UnityFrameRuntime.shared.snapshot.sceneActive
            }
            return await UnityFrameRuntime.shared.waitUntilPermittedDurably(.interactiveMetadata)
        }

        let defaults = UserDefaults.standard
        let dvrBase = defaults.string(forKey: "liveChannelsDvrBaseURL")?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let hdhrManual = defaults.string(forKey: "liveHDHomeRunManualURL")?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let hdhrManualGuide = defaults.string(forKey: "liveHDHomeRunManualGuideURL")?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let m3uURLs = Self.parseSourceList(defaults.string(forKey: "liveM3UURL") ?? "")
        let xmltvURLs = Self.parseSourceList(defaults.string(forKey: "liveXMLTVURL") ?? "")
        let xtreamAccounts = Self.parseXtreamAccounts(
            saved: defaults.string(forKey: "liveXtreamAccounts") ?? "",
            currentServer: defaults.string(forKey: "liveXtreamServer") ?? "",
            currentUser: defaults.string(forKey: "liveXtreamUsername") ?? "",
            currentPass: defaults.string(forKey: "liveXtreamPassword") ?? ""
        )

        var loaded: [LiveTVChannel] = []
        var messages: [String] = []
        var xmlGuide = ""
        let previousGuidePrograms = guidePrograms
        var authoritativeHDHRGuide: [String: [LiveProgram]] = [:]
        let hasXtreamAccounts = !xtreamAccounts.isEmpty
        // v309: keep the currently visible guide on screen while a refresh is in flight.
        // Only replace it after new guide data has successfully parsed.

        // vBRDC153: probe an explicitly configured HDHomeRun first. This prevents a stale
        // Channels DVR address from delaying a valid tuner lineup behind multiple fallback probes.
        if !hdhrManual.isEmpty {
            let hdhr = await loadHDHomeRun(manual: hdhrManual, allowAutoScan: false)
            var hdhrChannels = hdhr.channels
            messages.append(hdhr.message)
            let hdhrLoadedStart = loaded.count
            loaded.append(contentsOf: hdhrChannels)
            await publishLineupFirstIfNeeded(loaded, generation: generation, reason: "HDHomeRun lineup")
            if !hdhrChannels.isEmpty,
               !hdhrManualGuide.isEmpty,
               let hdhrXML = await fetchText(cappedGuideURL(hdhrManualGuide), accept: "application/xml,text/xml,*/*", maxBytes: 512 * 1024 * 1024, timeout: 45, attempts: 1) {
                hdhrChannels = applyXMLTVIcons(hdhrXML, to: hdhrChannels, baseURL: urlBase(hdhrManualGuide))
                let hdhrGuide = await parseXMLTV(hdhrXML, channels: hdhrChannels)
                authoritativeHDHRGuide = guideRetainingArtwork(hdhrGuide, previous: previousGuidePrograms)
                xmlGuide = xmlGuide.isEmpty ? hdhrXML : xmlGuide
                messages.append("HDHomeRun XMLTV/Gracenotes guide matched \(hdhrGuide.count) channel(s)")
                if loaded.count >= hdhrLoadedStart + hdhr.channels.count {
                    loaded.replaceSubrange(hdhrLoadedStart..<(hdhrLoadedStart + hdhr.channels.count), with: hdhrChannels)
                }
            }
        }


        if !dvrBase.isEmpty {
            let result = await loadChannelsDVR(base: dvrBase, allowAutoScan: false)
            loaded.append(contentsOf: result.channels)
            messages.append(result.message)
            await publishLineupFirstIfNeeded(loaded, generation: generation, reason: "Channels DVR lineup")

            // vBRDC153: never let an unavailable/stale DVR source block the next configured
            // lineup by fetching a huge guide after the DVR already returned zero channels.
            // Guide work only belongs to a source that actually produced channel identity.
            if !result.channels.isEmpty {
                let storedDvrBase = UserDefaults.standard.string(forKey: "liveChannelsDvrBaseURL") ?? dvrBase
                let dvrGuideBase = normalizeServerBase(storedDvrBase, defaultPort: 8089)
                if !dvrGuideBase.isEmpty {
                    xmlGuide = await fetchText(
                        "\(dvrGuideBase)/devices/ANY/guide/xmltv?duration=\(liveGuideDurationSeconds)",
                        accept: "application/xml,text/xml,*/*",
                        maxBytes: 512 * 1024 * 1024,
                        timeout: 45,
                        attempts: 1
                    ) ?? xmlGuide
                }
            }
        }

        for (index, m3uURL) in m3uURLs.enumerated() {
            let m3u = await loadM3U(url: m3uURL, source: m3uURLs.count > 1 ? "M3U/XMLTV #\(index + 1)" : "M3U/XMLTV")
            loaded.append(contentsOf: m3u.channels)
            messages.append(m3u.message)
            await publishLineupFirstIfNeeded(loaded, generation: generation, reason: "M3U lineup")
        }

        // vBRDC153: all configured lineups get a chance to publish before any optional
        // standalone XMLTV work. A dead external guide URL must never sit in front of a
        // valid Xtream account and keep the grid on demo channels.
        var xmlGuideFragments: [String] = []
        var xtreamGuideJobs: [(server: String, username: String, password: String, channels: [LiveTVChannel])] = []
        var xtreamGuideSources: [(index: Int, account: XtreamAccount, channels: [LiveTVChannel])] = []
        for (index, account) in xtreamAccounts.enumerated() {
            // v541: production rollback for IPTV routing. Xtream always imports into normal Live TV.
            // Sports-only/Both auto-routing is backlogged because it was hiding channels and confusing cache state.
            let sourceLabel = xtreamAccounts.count > 1 ? "Xtream/IPTV #\(index + 1)" : "Xtream/IPTV"
            let xtream = await loadXtream(server: account.server, username: account.username, password: account.password, sourceName: sourceLabel)
            messages.append(xtream.message)
            if !xtream.channels.isEmpty {
                loaded.append(contentsOf: xtream.channels)
                await publishLineupFirstIfNeeded(loaded, generation: generation, reason: "Xtream lineup")
                xtreamGuideSources.append((index, account, xtream.channels))
                let nonXtreamLoaded = loaded.filter { !$0.source.hasPrefix("Xtream/IPTV") }
                await commitXtreamChannelsInVisibleBatches(xtream.channels, existing: nonXtreamLoaded, messages: messages)
            }
        }

        // If every configured provider returned zero channels, there is no reason to wait
        // on the UNITY publication lane or large guide parsing before releasing the spinner.
        // Surface the provider messages immediately; demo/cached visuals can remain as a
        // non-interactive fallback while the user fixes connectivity/settings.
        guard generation == refreshGeneration, !Task.isCancelled, !VODExclusivePlaybackGate.isActive else { return }
        if dedupe(loaded).isEmpty {
            // vBRDC203: a configured provider returning zero channels is a failed refresh,
            // not a three-hour success. Clear any older success stamp so both automatic
            // recovery and Force Guide remain armed until the lineup actually comes back.
            guideCacheManager.resetRefreshClock()
            status = messages.joined(separator: " • ").ifEmpty("No configured Live TV source returned channels. Demo lineup remains visible • recovery armed.")
            isLoading = false
            return
        }

        // Guide enrichment phase. At this point at least one real lineup has already been
        // published by publishLineupFirstIfNeeded(_:), so none of these network calls can
        // hide real channels behind the loading overlay.
        for (index, xmltvURL) in xmltvURLs.enumerated() {
            if let fragment = await fetchText(
                cappedGuideURL(xmltvURL),
                accept: "application/xml,text/xml,*/*",
                maxBytes: 128 * 1024 * 1024,
                timeout: 35,
                attempts: 1
            ), !fragment.isEmpty {
                xmlGuideFragments.append(fragment)
                messages.append(xmltvURLs.count > 1 ? "XMLTV #\(index + 1) guide loaded" : "XMLTV guide loaded")
            }
        }

        for source in xtreamGuideSources {
            let base = normalizeServerBase(source.account.server, defaultPort: nil)
            let user = urlQueryEncode(source.account.username)
            let pass = urlQueryEncode(source.account.password)
            let xmlURL = "\(base)/xmltv.php?username=\(user)&password=\(pass)"
            if let xtreamXML = await fetchText(
                xmlURL,
                accept: "application/xml,text/xml,*/*",
                maxBytes: 512 * 1024 * 1024,
                timeout: 45,
                attempts: 1
            ), !xtreamXML.isEmpty {
                xmlGuideFragments.append(xtreamXML)
                messages.append(xtreamAccounts.count > 1 ? "Xtream #\(source.index + 1) XMLTV guide loaded" : "Xtream XMLTV guide loaded")
            } else {
                xtreamGuideJobs.append((source.account.server, source.account.username, source.account.password, source.channels))
                messages.append(xtreamAccounts.count > 1 ? "Xtream #\(source.index + 1) XMLTV unavailable • native short EPG will load after channels appear" : "Xtream XMLTV unavailable • native short EPG will load after channels appear")
            }
        }
        if !xmlGuideFragments.isEmpty {
            xmlGuide = xmlGuide.isEmpty ? xmlGuideFragments.joined(separator: "\n") : ([xmlGuide] + xmlGuideFragments).joined(separator: "\n")
        }

        // vBRDC102: provider/network work may finish at any time, but large guide/channel
        // publication waits behind active focus/UNITY geometry. This covers Gracenote,
        // XMLTV and Xtream without changing their data or refresh cadence.
        // vBRDC110: frame timing may defer a successful Live TV bootstrap, but it must
        // never discard it. vBRDC102 used a bounded wait as a destructive guard; if focus/
        // UNITY activity stayed busy for 2 seconds, fully fetched channels + Gracenote/XMLTV
        // were thrown away and the grid remained on its demo/empty state. Keep the courtesy
        // deferral, then commit the newest successful generation regardless of lane timeout.
        guard await awaitGuidePublicationLane() else { return }
        guard generation == refreshGeneration, !Task.isCancelled, !VODExclusivePlaybackGate.isActive else { return }

        var finalized = dedupe(loaded)
        // Build the guide in a local snapshot. The @Published guidePrograms dictionary is
        // swapped only after the runtime re-opens the interactive metadata lane; parsing a
        // large XMLTV/Gracenote payload can no longer trigger a mid-scroll root invalidation.
        var finalizedGuidePrograms = previousGuidePrograms
        let lastKnownGoodGuide = hasCurrentOrUpcomingGuideCoverage(previousGuidePrograms) ? previousGuidePrograms : Self.sessionGuidePrograms
        if !xmlGuide.isEmpty {
            finalized = applyXMLTVIcons(xmlGuide, to: finalized, baseURL: !xmltvURLs.isEmpty ? urlBase(xmltvURLs[0]) : (!dvrBase.isEmpty ? normalizeServerBase(dvrBase, defaultPort: 8089) : ""))
            let parsedGuide = await parseXMLTV(xmlGuide, channels: finalized)
            if !parsedGuide.isEmpty {
                let enriched = guideRetainingArtwork(parsedGuide, previous: previousGuidePrograms)
                // Never downgrade a healthy visible Gracenote/XMLTV snapshot to a partial
                // provider response during sleep/wake or transient backend failure.
                if hasCurrentOrUpcomingGuideCoverage(enriched) || lastKnownGoodGuide.isEmpty {
                    finalizedGuidePrograms = enriched
                } else {
                    finalizedGuidePrograms = lastKnownGoodGuide
                }
            } else if !lastKnownGoodGuide.isEmpty {
                finalizedGuidePrograms = lastKnownGoodGuide
            }
            let guideCount = finalizedGuidePrograms.values.reduce(0) { $0 + $1.count }
            if guideCount > 0 { messages.append("Guide matched \(finalizedGuidePrograms.count) channel(s) / \(guideCount) program(s)") }
        } else if !hasXtreamAccounts && finalizedGuidePrograms.isEmpty && !previousGuidePrograms.isEmpty {
            finalizedGuidePrograms = previousGuidePrograms
        }

        // HDHomeRun/Gracenote is authoritative once it successfully matched.
        // Later raw lineup/cache/fallback work may enrich it, but may not erase it.
        if !authoritativeHDHRGuide.isEmpty {
            for (key, programs) in authoritativeHDHRGuide where !programs.isEmpty {
                let current = finalizedGuidePrograms[key] ?? []
                let currentQuality = current.filter { !$0.title.isEmpty }.count + current.filter { !$0.imageURL.isEmpty }.count
                let hdhrQuality = programs.filter { !$0.title.isEmpty }.count + programs.filter { !$0.imageURL.isEmpty }.count
                if current.isEmpty || hdhrQuality >= currentQuality { finalizedGuidePrograms[key] = programs }
            }
        }

        // A newer refresh started while this one was awaiting network work. Ignore this stale result.
        guard generation == refreshGeneration, !Task.isCancelled, !VODExclusivePlaybackGate.isActive else { return }
        // vBRDC110: same non-destructive rule at the final publication boundary.
        guard await awaitGuidePublicationLane() else { return }
        guard generation == refreshGeneration, !Task.isCancelled, !VODExclusivePlaybackGate.isActive else { return }

        if !finalized.isEmpty {
            let nextChannels = finalized.sorted { channelSortKey($0.number) < channelSortKey($1.number) || (channelSortKey($0.number) == channelSortKey($1.number) && $0.name < $1.name) }
            _ = publishGuideProgramsIfChanged(finalizedGuidePrograms)
            _ = publishChannelsIfChanged(nextChannels)
            let persist = nextChannels.map { LiveTVLoadedChannel(id: $0.id, logo: $0.logo, number: $0.number, name: $0.name, category: $0.category, now: $0.now, next: $0.next, description: $0.description, streamURL: $0.streamURL, iconURL: $0.iconURL, tvgID: $0.tvgID, source: $0.source) }
            guideCacheManager.persistChannels(persist)
            let guideHealthy = hasCurrentOrUpcomingGuideCoverage(finalizedGuidePrograms)
            if guideHealthy {
                guideCacheManager.markRefreshed()
            } else {
                // Never let a successful lineup fetch stamp a three-hour success window over
                // an empty/expired guide. The visible channels stay cached while the recovery
                // loop remains armed until real current/future listings arrive.
                guideCacheManager.resetRefreshClock()
            }
            hasLoadedThisAppSession = true
            let baseStatus = messages.joined(separator: " • ").ifEmpty("Loaded \(nextChannels.count) Live TV channels")
            status = guideHealthy ? baseStatus : baseStatus + " • guide incomplete • recovery armed"
            Self.sessionChannels = nextChannels
            Self.sessionGuidePrograms = finalizedGuidePrograms
            Self.sessionStatus = status
            persistGuidePrograms(finalizedGuidePrograms)
            for job in xtreamGuideJobs {
                VODExclusiveWorkRegistry.start {
                    await self.loadDeferredXtreamShortGuide(
                        server: job.server,
                        username: job.username,
                        password: job.password,
                        channels: job.channels,
                        generation: generation
                    )
                }
            }
        } else {
            status = messages.joined(separator: " • ").ifEmpty("No configured Live TV source returned channels. Demo lineup remains visible.")
        }
    }

    private struct XtreamAccount { let server: String; let username: String; let password: String; let mode: String }

    private static func parseSourceList(_ raw: String) -> [String] {
        raw
            .components(separatedBy: CharacterSet(charactersIn: "\n;"))
            .flatMap { segment in segment.components(separatedBy: ",").map { String($0) } }
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
            .reduce(into: [String]()) { result, item in
                if !result.contains(item) { result.append(item) }
            }
    }

    private static func parseXtreamAccounts(saved: String, currentServer: String, currentUser: String, currentPass: String) -> [XtreamAccount] {
        var accounts: [XtreamAccount] = []
        func add(server: String, user: String, pass: String, mode: String = "Full TV") {
            let s = server.trimmingCharacters(in: .whitespacesAndNewlines)
            let u = user.trimmingCharacters(in: .whitespacesAndNewlines)
            let p = pass.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !s.isEmpty, !u.isEmpty, !p.isEmpty else { return }
            let normalized = normalizeXtreamServerStatic(s)
            if !accounts.contains(where: { $0.server == normalized && $0.username == u }) {
                accounts.append(XtreamAccount(server: normalized, username: u, password: p, mode: mode))
            }
        }
        saved.components(separatedBy: .newlines).forEach { line in
            let parts = line.components(separatedBy: "|")
            if parts.count >= 4 { add(server: parts[0], user: parts[1], pass: parts[2], mode: parts.dropFirst(3).joined(separator: "|")) }
            else if parts.count >= 3 { add(server: parts[0], user: parts[1], pass: parts.dropFirst(2).joined(separator: "|"), mode: "Full TV") }
        }
        add(server: currentServer, user: currentUser, pass: currentPass, mode: "Full TV")
        return accounts
    }


    private static func normalizedXtreamModeStatic(_ raw: String) -> String {
        // v541: auto IPTV sports routing is disabled/backlogged. Keep old saved modes harmless.
        return "Full TV"
    }

    private static func normalizeXtreamServerStatic(_ raw: String) -> String {
        var clean = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        clean = clean.trimmingCharacters(in: CharacterSet(charactersIn: "/"))
        if clean.isEmpty { return clean }
        if !clean.lowercased().hasPrefix("http://") && !clean.lowercased().hasPrefix("https://") { clean = "http://" + clean }
        return clean
    }

    private static func retagChannel(_ channel: LiveTVChannel, source: String) -> LiveTVChannel {
        LiveTVChannel(id: channel.id, logo: channel.logo, number: channel.number, name: channel.name, category: channel.category, now: channel.now, next: channel.next, description: channel.description, accent: channel.accent, streamURL: channel.streamURL, iconURL: channel.iconURL, tvgID: channel.tvgID, source: source)
    }

    private func normalizeServerBase(_ raw: String, defaultPort: Int?) -> String {
        var clean = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        clean = clean.trimmingCharacters(in: CharacterSet(charactersIn: "/"))
        if clean.isEmpty { return clean }
        if !clean.lowercased().hasPrefix("http://") && !clean.lowercased().hasPrefix("https://") {
            clean = "http://" + clean
        }
        guard let defaultPort,
              var components = URLComponents(string: clean),
              components.port == nil,
              let host = components.host,
              !host.isEmpty else { return clean }
        components.port = defaultPort
        return components.string ?? clean
    }

    private func channelsDVRCandidates(rawBase: String, allowAutoScan: Bool) -> [String] {
        let trimmed = rawBase.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return [] }
        return [normalizeServerBase(trimmed, defaultPort: 8089)]
    }

    private func loadChannelsDVR(base rawBase: String, allowAutoScan: Bool = true) async -> (channels: [LiveTVChannel], message: String) {
        let candidates = channelsDVRCandidates(rawBase: rawBase, allowAutoScan: allowAutoScan)
        var bestMessage = allowAutoScan ? "Channels DVR auto-scan found no server" : "Channels DVR not configured"

        for base in candidates {
            // vBRDC153: fastest authoritative probe first. The old loader could spend three
            // full M3U timeouts before even asking the aggregate JSON endpoint. Try canonical
            // M3U, then ANY JSON, and only then the two legacy M3U format variants.
            let primaryM3U = "\(base)/devices/ANY/channels.m3u"
            if let text = await fetchText(
                primaryM3U,
                accept: "audio/x-mpegurl,application/x-mpegURL,text/plain,*/*",
                maxBytes: 6 * 1024 * 1024,
                timeout: 10,
                attempts: 1
            ) {
                let parsed = dedupe(await parseM3U(text, source: "Channels DVR", baseURL: base))
                if !parsed.isEmpty {
                    UserDefaults.standard.set(base, forKey: "liveChannelsDvrBaseURL")
                    return (parsed, "Channels DVR native • \(parsed.count) channel(s) • \(base)")
                }
            }

            // JSON aggregate endpoint is normally much smaller than M3U and is the best
            // second chance when a proxy dislikes playlist framing/content type.
            var jsonChannels: [LiveTVChannel] = []
            if let data = await fetchText(
                "\(base)/devices/ANY/channels",
                accept: "application/json,*/*",
                maxBytes: 4 * 1024 * 1024,
                timeout: 9,
                attempts: 1
            ) {
                jsonChannels = parseDVRChannelsJSON(data, base: base, device: "ANY") ?? []
            }

            if jsonChannels.isEmpty {
                // Older Channels DVR builds sometimes need an explicit format variant.
                for suffix in ["?format=ts&codec=copy", "?format=ts"] {
                    guard !Task.isCancelled else { return ([], "Channels DVR load cancelled") }
                    if let text = await fetchText(
                        primaryM3U + suffix,
                        accept: "audio/x-mpegurl,application/x-mpegURL,text/plain,*/*",
                        maxBytes: 6 * 1024 * 1024,
                        timeout: 8,
                        attempts: 1
                    ) {
                        let parsed = dedupe(await parseM3U(text, source: "Channels DVR", baseURL: base))
                        if !parsed.isEmpty {
                            UserDefaults.standard.set(base, forKey: "liveChannelsDvrBaseURL")
                            return (parsed, "Channels DVR native • \(parsed.count) channel(s) • \(base)")
                        }
                    }
                }

                // Last compatibility lane: enumerate one named device, but stop after the
                // first successful lineup so a stale second device cannot delay publication.
                let devices = await fetchDVRDevices(base: base)
                for device in devices.prefix(2) {
                    guard !Task.isCancelled else { return ([], "Channels DVR load cancelled") }
                    let encDevice = urlEncode(device)
                    if let data = await fetchText(
                        "\(base)/devices/\(encDevice)/channels",
                        accept: "application/json,*/*",
                        maxBytes: 4 * 1024 * 1024,
                        timeout: 8,
                        attempts: 1
                    ) {
                        let list = parseDVRChannelsJSON(data, base: base, device: device) ?? []
                        if !list.isEmpty {
                            jsonChannels.append(contentsOf: list)
                            break
                        }
                    }
                }
            }

            var out = dedupe(jsonChannels)
            if !out.isEmpty {
                let groups = await loadDVRLineupGroups(base: base)
                if !groups.isEmpty {
                    out = out.map { channel -> LiveTVChannel in
                        let extra = groups.first { _, members in
                            members.contains(channel.number.lowercased()) ||
                            members.contains(channel.name.lowercased()) ||
                            (!channel.tvgID.isEmpty && members.contains(channel.tvgID.lowercased()))
                        }?.key
                        guard let extra, !extra.isEmpty else { return channel }
                        return LiveTVChannel(
                            id: channel.id, logo: channel.logo, number: channel.number,
                            name: channel.name, category: normalizeCategory(extra, fallback: channel.category),
                            now: channel.now, next: channel.next, description: channel.description,
                            accent: Self.accent(for: extra), streamURL: channel.streamURL,
                            iconURL: channel.iconURL, tvgID: channel.tvgID, source: channel.source
                        )
                    }
                }
                UserDefaults.standard.set(base, forKey: "liveChannelsDvrBaseURL")
                return (out, "Channels DVR native • \(out.count) channel(s) • \(base)")
            }
            bestMessage = "Channels DVR returned no channels at \(base)"
        }
        return ([], bestMessage)
    }

    private func loadHDHomeRun(manual: String, allowAutoScan: Bool) async -> (channels: [LiveTVChannel], message: String) {
        var messages: [String] = []

        // vBRDC153: manual HDHomeRun input expands to JSON/M3U/XML alternatives. They are
        // fallbacks, not three required downloads. Return immediately on the first non-empty
        // lineup so a missing alternate endpoint cannot hold the grid behind repeated timeouts.
        for url in hdHomeRunManualCandidates(manual) {
            guard !Task.isCancelled else { return ([], "HDHomeRun load cancelled") }
            if url.lowercased().hasSuffix(".m3u") {
                if let text = await fetchText(
                    url,
                    accept: "audio/x-mpegurl,application/x-mpegURL,text/plain,*/*",
                    maxBytes: 8 * 1024 * 1024,
                    timeout: 10,
                    attempts: 1
                ) {
                    let parsed = dedupe(await parseM3U(text, source: "HDHomeRun", baseURL: urlBase(url))).map { ch in
                        LiveTVChannel(id: ch.id, logo: ch.logo, number: ch.number, name: ch.name, category: ch.category.ifEmpty("HDHomeRun"), now: ch.now, next: ch.next, description: ch.description, accent: Self.accent(for: ch.category), streamURL: ch.streamURL, iconURL: ch.iconURL, tvgID: ch.tvgID, source: "HDHomeRun")
                    }
                    messages.append("HDHomeRun manual M3U • \(parsed.count)")
                    if !parsed.isEmpty { return (parsed, "HDHomeRun • \(parsed.count) channel(s) • " + messages.joined(separator: " • ")) }
                }
            } else if url.lowercased().hasSuffix(".xml") {
                if let xml = await fetchText(url, accept: "application/xml,text/xml,*/*", maxBytes: 4 * 1024 * 1024, timeout: 10, attempts: 1) {
                    let parsed = dedupe(parseHDHomeRunXMLLineup(xml, base: urlBase(url)))
                    messages.append("HDHomeRun manual XML • \(parsed.count)")
                    if !parsed.isEmpty { return (parsed, "HDHomeRun • \(parsed.count) channel(s) • " + messages.joined(separator: " • ")) }
                }
            } else {
                if let json = await fetchText(url, accept: "application/json,*/*", maxBytes: 4 * 1024 * 1024, timeout: 10, attempts: 1) {
                    let parsed = dedupe(parseHDHomeRunJSONLineup(json, base: urlBase(url)))
                    messages.append("HDHomeRun manual JSON • \(parsed.count)")
                    if !parsed.isEmpty { return (parsed, "HDHomeRun • \(parsed.count) channel(s) • " + messages.joined(separator: " • ")) }
                }
            }
        }

        if allowAutoScan {
            let devices = await discoverHDHomeRunDevices()
            for device in devices {
                if let json = await fetchText(device.lineupURL, accept: "application/json,*/*", maxBytes: 4 * 1024 * 1024, timeout: 10, attempts: 1) {
                    let parsed = dedupe(parseHDHomeRunJSONLineup(json, base: device.baseURL))
                    messages.append("HDHomeRun auto \(device.name) • \(parsed.count)")
                    if !parsed.isEmpty { return (parsed, "HDHomeRun • \(parsed.count) channel(s) • " + messages.joined(separator: " • ")) }
                }
            }
            if devices.isEmpty { messages.append("HDHomeRun auto-scan found no devices") }
        }
        return ([], messages.joined(separator: " • ").ifEmpty("HDHomeRun off/no channels"))
    }

    private struct HDHomeRunDeviceCandidate { let name: String; let baseURL: String; let lineupURL: String }

    // vBRDC120 compile correction: vBRDC119 moved the high-volume Xtream parser's
    // string helper into its nonisolated worker, but HDHomeRun/Channels DVR still use
    // the same provider-value normalization on the LiveTVSourceModel path. Keep a tiny
    // instance helper here so those provider parsers retain their existing behavior.
    @inline(__always)
    private func stringValue(_ row: [String: Any], keys: [String]) -> String {
        for key in keys {
            guard let value = row[key], !(value is NSNull) else { continue }
            let text = String(describing: value).trimmingCharacters(in: .whitespacesAndNewlines)
            if !text.isEmpty { return text }
        }
        return ""
    }

    // vBRDC120 compile correction: HDHomeRun XML lineup parsing still needs a generic
    // tag reader after the XMLTV-specific parser helpers were isolated in vBRDC119.
    private func tagText(_ body: String, tag: String) -> String {
        let escaped = NSRegularExpression.escapedPattern(for: tag)
        guard let regex = try? NSRegularExpression(
            pattern: "<\\s*" + escaped + "(?:\\s[^>]*)?>(.*?)</\\s*" + escaped + "\\s*>",
            options: [.caseInsensitive, .dotMatchesLineSeparators]
        ) else { return "" }
        let ns = body as NSString
        guard let match = regex.firstMatch(in: body, range: NSRange(location: 0, length: ns.length)),
              match.numberOfRanges > 1 else { return "" }
        return ns.substring(with: match.range(at: 1)).xmlDecoded()
            .trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private func discoverHDHomeRunDevices() async -> [HDHomeRunDeviceCandidate] {
        guard let text = await fetchText("http://my.hdhomerun.com/discover", accept: "application/json,*/*", maxBytes: 512 * 1024),
              let data = text.data(using: .utf8),
              let arr = try? JSONSerialization.jsonObject(with: data) as? [[String: Any]] else { return [] }
        return arr.compactMap { obj in
            let base = stringValue(obj, keys: ["BaseURL", "BaseUrl", "baseURL"]).trimmingCharacters(in: CharacterSet(charactersIn: "/"))
            let lineup = stringValue(obj, keys: ["LineupURL", "LineupUrl", "lineupURL"]).ifEmpty(base.isEmpty ? "" : base + "/lineup.json")
            guard !base.isEmpty, !lineup.isEmpty else { return nil }
            let name = stringValue(obj, keys: ["FriendlyName", "DeviceID", "DeviceId"]).ifEmpty("HDHomeRun")
            return HDHomeRunDeviceCandidate(name: name, baseURL: base, lineupURL: lineup)
        }
    }

    private func hdHomeRunManualCandidates(_ raw: String) -> [String] {
        let tokens = raw.split(whereSeparator: { $0 == "," || $0 == ";" || $0 == "\n" }).map { String($0).trimmingCharacters(in: .whitespacesAndNewlines) }.filter { !$0.isEmpty }
        var out: [String] = []
        for token in tokens {
            var clean = token
            if !clean.lowercased().hasPrefix("http://") && !clean.lowercased().hasPrefix("https://") { clean = "http://" + clean }
            let lower = clean.lowercased()
            if lower.hasSuffix("/lineup.json") || lower.hasSuffix("/lineup.m3u") || lower.hasSuffix("/lineup.xml") {
                out.append(clean)
            } else if lower.hasSuffix("/discover.json") {
                let base = String(clean.dropLast("/discover.json".count)).trimmingCharacters(in: CharacterSet(charactersIn: "/"))
                out += [base + "/lineup.json", base + "/lineup.m3u", base + "/lineup.xml"]
            } else {
                let base = clean.trimmingCharacters(in: CharacterSet(charactersIn: "/"))
                out += [base + "/lineup.json", base + "/lineup.m3u", base + "/lineup.xml"]
            }
        }
        var seen = Set<String>()
        return out.filter { seen.insert($0).inserted }
    }

    private func parseHDHomeRunJSONLineup(_ json: String, base: String) -> [LiveTVChannel] {
        guard let data = json.data(using: .utf8), let arr = try? JSONSerialization.jsonObject(with: data) as? [[String: Any]] else { return [] }
        return arr.enumerated().compactMap { index, obj in
            let number = stringValue(obj, keys: ["GuideNumber", "Guide", "number", "channel"])
            let name = stringValue(obj, keys: ["GuideName", "Name", "name", "CallSign"]).ifEmpty("HDHomeRun \(number.ifEmpty(String(index + 1)))")
            let stream = stringValue(obj, keys: ["URL", "StreamURL", "PlayURL", "url"]).ifEmpty(number.isEmpty ? "" : base.trimmingCharacters(in: CharacterSet(charactersIn: "/")) + "/auto/v" + number)
            guard !stream.isEmpty else { return nil }
            let icon = stringValue(obj, keys: ["ImageURL", "GuideImageURL", "LogoURL", "StationLogo", "IconURL", "logo"])
            return makeChannel(name: name, number: number, url: absoluteStreamURL(stream, base: base), source: "HDHomeRun", category: "HDHomeRun", iconURL: absoluteLogoURL(icon, base: base), tvgID: number)
        }
    }

    private func parseHDHomeRunXMLLineup(_ xml: String, base: String) -> [LiveTVChannel] {
        guard let regex = try? NSRegularExpression(pattern: #"<Program[^>]*>(.*?)</Program>"#, options: [.caseInsensitive, .dotMatchesLineSeparators]) else { return [] }
        let ns = xml as NSString
        return regex.matches(in: xml, range: NSRange(location: 0, length: ns.length)).enumerated().compactMap { index, match in
            let body = ns.substring(with: match.range(at: 1))
            let number = tagText(body, tag: "GuideNumber")
            let name = tagText(body, tag: "GuideName").ifEmpty("HDHomeRun \(number.ifEmpty(String(index + 1)))")
            let stream = tagText(body, tag: "URL").ifEmpty(number.isEmpty ? "" : base.trimmingCharacters(in: CharacterSet(charactersIn: "/")) + "/auto/v" + number)
            let icon = tagText(body, tag: "ImageURL").ifEmpty(tagText(body, tag: "GuideImageURL")).ifEmpty(tagText(body, tag: "LogoURL")).ifEmpty(tagText(body, tag: "IconURL"))
            guard !stream.isEmpty else { return nil }
            return makeChannel(name: name, number: number, url: absoluteStreamURL(stream, base: base), source: "HDHomeRun", category: "HDHomeRun", iconURL: absoluteLogoURL(icon, base: base), tvgID: number)
        }
    }

    private func urlBase(_ raw: String) -> String {
        guard let url = URL(string: raw), let scheme = url.scheme, let host = url.host else { return raw }
        let port = url.port.map { ":\($0)" } ?? ""
        return "\(scheme)://\(host)\(port)"
    }

    private func fetchDVRDevices(base: String) async -> [String] {
        guard let text = await fetchText("\(base)/devices", accept: "application/json,*/*", maxBytes: 512 * 1024, timeout: 10, attempts: 1), let data = text.data(using: .utf8) else { return [] }
        var names: [String] = []
        if let arr = try? JSONSerialization.jsonObject(with: data) as? [[String: Any]] {
            for obj in arr { addDeviceName(from: obj, into: &names) }
        } else if let obj = try? JSONSerialization.jsonObject(with: data) as? [String: Any] {
            if let arr = obj["devices"] as? [[String: Any]] { for item in arr { addDeviceName(from: item, into: &names) } }
            if let arr = obj["Devices"] as? [[String: Any]] { for item in arr { addDeviceName(from: item, into: &names) } }
            addDeviceName(from: obj, into: &names)
        }
        var seen = Set<String>()
        return names.filter { value in
            let clean = value.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !clean.isEmpty && clean.uppercased() != "ANY" else { return false }
            return seen.insert(clean).inserted
        }
    }

    private func addDeviceName(from obj: [String: Any], into names: inout [String]) {
        for key in ["name", "Name", "DeviceID", "DeviceId", "deviceID", "id", "ID"] {
            if let value = obj[key] as? String, !value.isEmpty { names.append(value) }
        }
    }

    private func parseDVRChannelsJSON(_ text: String, base: String, device: String) -> [LiveTVChannel]? {
        guard let data = text.data(using: .utf8) else { return nil }
        let raw: Any?
        if let arr = try? JSONSerialization.jsonObject(with: data) as? [[String: Any]] {
            raw = arr
        } else if let obj = try? JSONSerialization.jsonObject(with: data) as? [String: Any] {
            raw = obj["channels"] as? [[String: Any]] ?? obj["Channels"] as? [[String: Any]]
        } else { raw = nil }
        guard let arr = raw as? [[String: Any]] else { return nil }
        return arr.enumerated().compactMap { idx, obj in
            let number = stringValue(obj, keys: ["GuideNumber", "Number", "number", "channelNumber", "ChannelNumber"])
            let id = stringValue(obj, keys: ["id", "ID", "GuideNumber", "Number", "StationID", "stationID", "TmsId", "tmsId", "GuideID", "guideID"]).ifEmpty(number)
            let name = stringValue(obj, keys: ["GuideName", "Name", "name", "channel"]).ifEmpty("Channel \(number.ifEmpty(id.ifEmpty("\(idx+1)")))")
            let playbackKey = number.ifEmpty(id)
            guard !playbackKey.isEmpty else { return nil }
            let url = "\(base)/devices/\(urlEncode(device))/channels/\(urlEncode(playbackKey))/stream.mpg?format=ts&codec=copy"
            let rawIcon = stringValue(obj, keys: ["ImageURL", "Image", "imageUrl", "LogoURL", "logoUrl", "logo", "tvg-logo", "icon", "Icon", "stationLogo", "StationLogo", "Logo", "PreferredImage", "GracenoteLogo", "gracenoteLogo"])
            var icon = absoluteLogoURL(rawIcon, base: base)
            if icon.isEmpty && !id.isEmpty { icon = "\(base)/images/station/\(urlEncode(id))" }
            let category = inferCategory(name: name, explicit: "Channels DVR")
            return makeChannel(name: name, number: number, url: url, source: "Channels DVR", category: category, iconURL: icon, tvgID: id)
        }
    }

    private func loadDVRLineupGroups(base: String) async -> [String: Set<String>] {
        guard let text = await fetchText("\(base)/dvr/lineups", accept: "application/json,*/*", maxBytes: 2 * 1024 * 1024, timeout: 8, attempts: 1), let data = text.data(using: .utf8) else { return [:] }
        let root = try? JSONSerialization.jsonObject(with: data)
        var entries: [[String: Any]] = []
        if let arr = root as? [[String: Any]] { entries = arr }
        if let obj = root as? [String: Any] {
            entries = (obj["lineups"] as? [[String: Any]]) ?? (obj["Lineups"] as? [[String: Any]]) ?? (obj["items"] as? [[String: Any]]) ?? []
        }
        var result: [String: Set<String>] = [:]
        for obj in entries {
            let name = stringValue(obj, keys: ["name", "Name", "title", "Title", "group", "Group"]).ifEmpty("Channels DVR")
            var members = Set<String>()
            func add(_ any: Any?) {
                if let s = any as? String { members.insert(s.lowercased()) }
                if let n = any as? NSNumber { members.insert(n.stringValue.lowercased()) }
                if let arr = any as? [Any] { arr.forEach { add($0) } }
                if let dict = any as? [String: Any] {
                    for key in ["GuideNumber", "Number", "number", "GuideName", "Name", "name", "id", "ID"] { add(dict[key]) }
                }
            }
            for key in ["channels", "Channels", "members", "Members", "items", "Items"] { add(obj[key]) }
            if !members.isEmpty { result[name] = members }
        }
        return result
    }

    private func loadM3U(url: String, source: String) async -> (channels: [LiveTVChannel], message: String) {
        guard let text = await fetchText(url, accept: "audio/x-mpegurl,application/x-mpegURL,text/plain,*/*", maxBytes: 128 * 1024 * 1024, timeout: 22, attempts: 1) else { return ([], "M3U failed or timed out") }
        let channels = await parseM3U(text, source: source, baseURL: "")
        return (channels, channels.isEmpty ? "M3U returned no channels" : "M3U playlist • \(channels.count) channel(s)")
    }

    private func parseM3U(_ text: String, source: String, baseURL: String) async -> [LiveTVChannel] {
        // vBRDC119: M3U parsing used to run on the @MainActor LiveTVSourceModel and compiled
        // an NSRegularExpression separately for every requested attribute of every channel.
        // Large IPTV lists can contain tens of thousands of entries, so importing one list
        // could monopolize UI execution even though the network request itself was async.
        // Parse value-only drafts on a utility executor using ONE attribute regex per list.
        let drafts = await Task.detached(priority: .utility) {
            Self.parseM3UDrafts(text, source: source, baseURL: baseURL)
        }.value
        guard !Task.isCancelled else { return [] }
        return drafts.map { draft in
            LiveTVChannel(
                id: draft.id,
                logo: draft.logo,
                number: draft.number,
                name: draft.name,
                category: draft.category,
                now: draft.name,
                next: "Guide data loading",
                description: source,
                accent: Self.accent(for: draft.category),
                streamURL: draft.streamURL,
                iconURL: draft.iconURL,
                tvgID: draft.tvgID,
                source: source
            )
        }
    }

    private nonisolated static func parseM3UDrafts(_ text: String, source: String, baseURL: String) -> [M3ULiveDraft] {
        guard let attributeRegex = try? NSRegularExpression(pattern: #"([A-Za-z0-9_-]+)=\"([^\"]*)\""#) else { return [] }
        let wanted: Set<String> = [
            "tvg-name", "group-title", "tvg-chno", "channel-number", "ch-number",
            "tvc-guide-stationid", "tvg-id", "channel-id", "tvg-logo", "logo", "x-tvg-url"
        ]
        var drafts: [M3ULiveDraft] = []
        drafts.reserveCapacity(min(30_000, max(64, text.count / 180)))
        var meta = ""

        for raw in text.components(separatedBy: .newlines) {
            if Task.isCancelled { return drafts }
            let line = raw.trimmingCharacters(in: .whitespacesAndNewlines)
            if line.hasPrefix("#EXTINF") { meta = line; continue }
            if line.isEmpty || line.hasPrefix("#") { continue }
            guard !meta.isEmpty else { continue }

            let metaNS = meta as NSString
            var attrs: [String: String] = [:]
            attrs.reserveCapacity(8)
            for match in attributeRegex.matches(in: meta, range: NSRange(location: 0, length: metaNS.length)) {
                guard match.numberOfRanges > 2 else { continue }
                let key = metaNS.substring(with: match.range(at: 1)).lowercased()
                guard wanted.contains(key) else { continue }
                attrs[key] = metaNS.substring(with: match.range(at: 2)).trimmingCharacters(in: .whitespacesAndNewlines)
            }

            let fallbackName = meta.components(separatedBy: ",").last?.trimmingCharacters(in: .whitespacesAndNewlines)
                ?? "Channel \(drafts.count + 1)"
            let displayName = Self.firstNonEmpty(attrs["tvg-name"], fallbackName)
            let group = attrs["group-title"] ?? ""
            let number = Self.firstNonEmpty(attrs["tvg-chno"], attrs["channel-number"], attrs["ch-number"])
            let tvgID = Self.firstNonEmpty(attrs["tvc-guide-stationid"], attrs["tvg-id"], attrs["channel-id"])
            let rawIcon = Self.firstNonEmpty(attrs["tvg-logo"], attrs["logo"], attrs["x-tvg-url"])
            let icon = Self.absoluteProviderURL(rawIcon, base: baseURL)
            let streamURL = Self.absoluteProviderURL(line, base: baseURL)
            let category = Self.inferCategoryOffMain(name: displayName, explicit: group)
            let logo = Self.channelLogoOffMain(name: displayName)
            let idSeed = "\(source)|\(number)|\(displayName)|\(streamURL)".unicodeScalars.reduce(0) { ($0 &* 31 &+ Int($1.value)) & 0x7fffffff }
            drafts.append(M3ULiveDraft(
                id: max(1, idSeed),
                logo: logo,
                number: number,
                name: displayName,
                category: category,
                streamURL: streamURL,
                iconURL: icon,
                tvgID: tvgID
            ))
            meta = ""
        }
        return drafts
    }

    private nonisolated static func firstNonEmpty(_ values: String?...) -> String {
        for value in values {
            let clean = (value ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
            if !clean.isEmpty { return clean }
        }
        return ""
    }

    private nonisolated static func absoluteProviderURL(_ raw: String, base: String) -> String {
        let clean = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !clean.isEmpty else { return "" }
        if clean.lowercased().hasPrefix("http") { return clean }
        if clean.hasPrefix("/") { return base.trimmingCharacters(in: CharacterSet(charactersIn: "/")) + clean }
        if !base.isEmpty { return base.trimmingCharacters(in: CharacterSet(charactersIn: "/")) + "/" + clean }
        return clean
    }

    private nonisolated static func channelLogoOffMain(name: String) -> String {
        let words = name.components(separatedBy: CharacterSet.alphanumerics.inverted).filter { !$0.isEmpty }
        if words.count >= 2 { return words.prefix(2).compactMap { $0.first.map(String.init) }.joined().uppercased() }
        return String(name.prefix(8)).uppercased()
    }

    private nonisolated static func inferCategoryOffMain(name: String, explicit: String) -> String {
        let cleaned = explicit.split(separator: ";").first.map(String.init) ?? explicit
        if !cleaned.isEmpty && cleaned.lowercased() != "channels dvr" && cleaned.lowercased() != "iptv" {
            return normalizeCategoryOffMain(cleaned, fallback: cleaned)
        }
        return normalizeCategoryOffMain("", fallback: name)
    }

    private nonisolated static func normalizeCategoryOffMain(_ raw: String, fallback: String) -> String {
        let lower = (raw + " " + fallback).lowercased()
        if lower.contains("sport") || lower.contains("sports") || lower.contains("ppv") || lower.contains("event") || lower.contains("nfl") || lower.contains("nba") || lower.contains("mlb") || lower.contains("nhl") || lower.contains("ufc") || lower.contains("wwe") || lower.contains("espn") || lower.contains("bein") || lower.contains("sky sports") || lower.contains("tnt sports") || lower.contains("dazn") { return "Sports" }
        if lower.contains("news") || lower.contains("cnn") || lower.contains("msnbc") { return "News" }
        if lower.contains("kid") || lower.contains("cartoon") || lower.contains("disney") || lower.contains("nick") { return "Kids" }
        if lower.contains("movie") || lower.contains("hbo") || lower.contains("cinema") || lower.contains("starz") { return "Movies" }
        if lower.contains("favorite") { return "Favorites" }
        if lower.contains("hd") { return "HD" }
        if lower.contains("drama") { return "Drama" }
        return raw.isEmpty ? "All" : raw
    }

    private func loadDeferredXtreamShortGuide(
        server: String,
        username: String,
        password: String,
        channels xtreamChannels: [LiveTVChannel],
        generation: Int
    ) async {
        guard !xtreamChannels.isEmpty,
              generation == refreshGeneration,
              !Task.isCancelled,
              !VODExclusivePlaybackGate.isActive else { return }
        status = "Xtream Live loaded • loading guide in safe batches…"
        Self.sessionStatus = status
        let parsed = await loadXtreamShortGuidePrograms(server: server, username: username, password: password, channels: xtreamChannels)
        guard generation == refreshGeneration, !Task.isCancelled, !VODExclusivePlaybackGate.isActive else { return }
        guard !parsed.isEmpty else {
            status = "Xtream Live loaded • guide unavailable or provider returned no current EPG • recovery armed"
            Self.sessionStatus = status
            guideCacheManager.resetRefreshClock()
            return
        }
        // vBRDC203: a successful native EPG must not wait forever behind stale post-sleep
        // focus ownership. Give geometry a short courtesy window, then publish the newest
        // provider generation atomically.
        _ = await UnityFrameRuntime.shared.waitUntilPermitted(.interactiveMetadata, maxWait: 1.20)
        guard generation == refreshGeneration, !Task.isCancelled, !VODExclusivePlaybackGate.isActive else { return }
        let merged = guideRetainingArtwork(parsed, previous: guidePrograms)
        let publishedGuide = mergeGuideProgramsAtomically(merged)
        applyXtreamGuideToVisibleChannels(merged)
        Self.sessionGuidePrograms = publishedGuide
        persistGuidePrograms(publishedGuide)
        if hasCurrentOrUpcomingGuideCoverage(publishedGuide) {
            guideCacheManager.markRefreshed()
        } else {
            guideCacheManager.resetRefreshClock()
        }
        let rows = parsed.values.reduce(0) { $0 + $1.count }
        status = "Xtream Live • \(xtreamChannels.count) channel(s) • native provider EPG matched \(parsed.count) key(s) / \(rows) row(s)"
        Self.sessionStatus = status
    }

    private func commitXtreamChannelsInVisibleBatches(_ xtreamChannels: [LiveTVChannel], existing loaded: [LiveTVChannel], messages: [String]) async {
        guard !xtreamChannels.isEmpty else { return }
        var staged = dedupe(loaded)
        let batchSize = 120
        var committed = 0
        while committed < xtreamChannels.count {
            let nextEnd = min(committed + batchSize, xtreamChannels.count)
            let slice = xtreamChannels[committed..<nextEnd]
            staged = dedupe(staged + Array(slice))
            // vBRDC152: channel identity is first-frame UI, not deferred metadata. Give D-pad
            // geometry a bounded courtesy window, then publish the fetched batch even if a
            // transient frame-lane owner failed to clear. The guide still uses durable gating.
            _ = await UnityFrameRuntime.shared.waitUntilPermitted(.interactiveMetadata, maxWait: 0.45)
            guard !Task.isCancelled, !VODExclusivePlaybackGate.isActive else { return }
            let nextChannels = staged.sorted { channelSortKey($0.number) < channelSortKey($1.number) || (channelSortKey($0.number) == channelSortKey($1.number) && $0.name < $1.name) }
            _ = publishChannelsIfChanged(nextChannels)
            if isLoading { isLoading = false }
            status = (messages + ["Xtream Live visible batch \(nextEnd)/\(xtreamChannels.count) • guide loading in background"]).joined(separator: " • ")
            Self.sessionChannels = nextChannels
            Self.sessionGuidePrograms = guidePrograms
            Self.sessionStatus = status
            try? await Task.sleep(nanoseconds: 25_000_000)
            committed = nextEnd
        }
    }

    private func loadXtreamShortGuidePrograms(server: String, username: String, password: String, channels xtreamChannels: [LiveTVChannel]) async -> [String: [LiveProgram]] {
        let base = normalizeServerBase(server, defaultPort: nil)
        let user = urlQueryEncode(username)
        let pass = urlQueryEncode(password)
        let now = Date()
        let cutoff = now.addingTimeInterval(TimeInterval(liveGuideDurationSeconds))
        var resolved: [String: [LiveProgram]] = [:]
        // v537: use the provider's native Xtream compact EPG pipeline, like IPTV editors do:
        // get_short_epg first, get_simple_data_table second. This stays small per request but
        // covers the full visible tvOS lineup instead of only the first 80 channels.
        let safeChannels = Array(xtreamChannels.prefix(5000))
        var processed = 0
        for channel in safeChannels {
            guard let streamId = xtreamStreamID(from: channel.streamURL), !streamId.isEmpty else { continue }
            let encodedStreamID = urlEncode(streamId)
            let urls = [
                "\(base)/player_api.php?username=\(user)&password=\(pass)&action=get_short_epg&stream_id=\(encodedStreamID)&limit=6",
                "\(base)/player_api.php?username=\(user)&password=\(pass)&action=get_simple_data_table&stream_id=\(encodedStreamID)"
            ]
            var programs: [LiveProgram] = []
            for url in urls {
                guard let text = await fetchText(url, accept: "application/json,*/*", maxBytes: 192 * 1024, timeout: 10),
                      let data = text.data(using: .utf8) else { continue }
                // vBRDC119: native Xtream EPG JSON parsing/date formatting is provider work,
                // not focus work. LiveTVSourceModel is @MainActor, so the old synchronous
                // parser could steal the animation frame after every network response.
                let parseWorker = Task.detached(priority: .utility) {
                    Self.parseXtreamShortEPGOffMain(data: data, now: now, cutoff: cutoff)
                }
                let parsedPrograms = await withTaskCancellationHandler(operation: {
                    await parseWorker.value
                }, onCancel: {
                    parseWorker.cancel()
                })
                guard !parsedPrograms.isEmpty else { continue }
                programs = parsedPrograms
                break
            }
            guard !programs.isEmpty else { continue }
            for key in xtreamGuideStorageKeys(for: channel) { resolved[key] = programs }
            processed += 1
            if processed % 25 == 0 {
                // vBRDC110: a completed native EPG batch is durable; frame arbitration
                // may postpone publication but may not throw the batch away.
                guard await UnityFrameRuntime.shared.waitUntilPermittedDurably(.interactiveMetadata) else { return resolved }
                guard !Task.isCancelled, !VODExclusivePlaybackGate.isActive else { return resolved }
                let publishedGuide = mergeGuideProgramsAtomically(resolved)
                applyXtreamGuideToVisibleChannels(resolved)
                Self.sessionGuidePrograms = publishedGuide
                persistGuidePrograms(publishedGuide)
                status = "Xtream Live loaded • native EPG loading \(processed)/\(safeChannels.count)…"
                Self.sessionStatus = status
            }
            if resolved.values.reduce(0, { $0 + $1.count }) >= 20000 { break }
        }
        return resolved
    }


    private func xtreamGuideStorageKeys(for channel: LiveTVChannel) -> [String] {
        var keys = Set<String>()
        // v537: Xtream EPG must not be stored under generic channel numbers/names, because
        // that lets stale XMLTV rows from unrelated providers make every Xtream card show
        // the same programme. Keep Xtream guide keys source/account specific.
        keys.insert(channelKey(channel))
        if let streamID = xtreamStreamID(from: channel.streamURL), !streamID.isEmpty {
            keys.insert("xtream-stream:\(channel.source.lowercased()):\(streamID)")
        }
        let tvg = normalizeGuideKey(channel.tvgID)
        if !tvg.isEmpty { keys.insert("xtream-tvg:\(channel.source.lowercased()):\(tvg)") }
        return Array(keys)
    }

    private func xtreamGuideLookupKeys(for channel: LiveTVChannel) -> [String] {
        var keys: [String] = [channelKey(channel)]
        if let streamID = xtreamStreamID(from: channel.streamURL), !streamID.isEmpty {
            keys.append("xtream-stream:\(channel.source.lowercased()):\(streamID)")
        }
        let tvg = normalizeGuideKey(channel.tvgID)
        if !tvg.isEmpty { keys.append("xtream-tvg:\(channel.source.lowercased()):\(tvg)") }
        return keys
    }

    private func applyXtreamGuideToVisibleChannels(_ parsed: [String: [LiveProgram]]) {
        guard !parsed.isEmpty else { return }
        let updated = channels.map { channel -> LiveTVChannel in
            guard channel.isXtreamSource else { return channel }
            let programs = xtreamGuideLookupKeys(for: channel).compactMap { parsed[$0] }.first(where: { !$0.isEmpty })
            guard let programs, let current = programs.first else { return channel }
            let next = programs.dropFirst().first?.title ?? channel.next
            return LiveTVChannel(id: channel.id, logo: channel.logo, number: channel.number, name: channel.name, category: channel.category, now: current.title, next: next, description: current.description.ifEmpty(channel.description), accent: channel.accent, streamURL: channel.streamURL, iconURL: channel.iconURL, tvgID: channel.tvgID, source: channel.source)
        }
        _ = publishChannelsIfChanged(updated)
        Self.sessionChannels = updated
        let persist = updated.map { LiveTVLoadedChannel(id: $0.id, logo: $0.logo, number: $0.number, name: $0.name, category: $0.category, now: $0.now, next: $0.next, description: $0.description, streamURL: $0.streamURL, iconURL: $0.iconURL, tvgID: $0.tvgID, source: $0.source) }
        guideCacheManager.persistChannels(persist)
        persistGuidePrograms(guidePrograms)
    }

    private func xtreamStreamID(from streamURL: String) -> String? {
        guard let url = URL(string: streamURL) else { return nil }
        let last = url.lastPathComponent
        if let dot = last.firstIndex(of: ".") { return String(last[..<dot]) }
        return last.isEmpty ? nil : last
    }

    private nonisolated static func parseXtreamShortEPGOffMain(data: Data, now: Date, cutoff: Date) -> [LiveProgram] {
        guard !Task.isCancelled, let root = try? JSONSerialization.jsonObject(with: data) else { return [] }
        var rows: [[String: Any]] = []
        if let obj = root as? [String: Any] {
            rows = (obj["epg_listings"] as? [[String: Any]])
                ?? (obj["listings"] as? [[String: Any]])
                ?? (obj["epg"] as? [[String: Any]])
                ?? (obj["data"] as? [[String: Any]])
                ?? (obj["programmes"] as? [[String: Any]])
                ?? (obj["programs"] as? [[String: Any]])
                ?? []
            if rows.isEmpty, let nested = obj["js"] as? [String: Any] {
                rows = (nested["epg_listings"] as? [[String: Any]]) ?? (nested["data"] as? [[String: Any]]) ?? []
            }
        } else if let arr = root as? [[String: Any]] {
            rows = arr
        }
        guard !rows.isEmpty else { return [] }

        // One formatter set per provider response replaces DateFormatter construction for
        // every start/end field. These objects stay entirely inside this utility worker.
        let posix = Locale(identifier: "en_US_POSIX")
        let localFormatter = DateFormatter()
        localFormatter.locale = posix
        localFormatter.timeZone = .current
        localFormatter.dateFormat = "yyyy-MM-dd HH:mm:ss"
        let isoFormatter = DateFormatter()
        isoFormatter.locale = posix
        isoFormatter.dateFormat = "yyyy-MM-dd'T'HH:mm:ssZ"
        let isoMillisFormatter = DateFormatter()
        isoMillisFormatter.locale = posix
        isoMillisFormatter.dateFormat = "yyyy-MM-dd'T'HH:mm:ss.SSSZ"
        let shortTimeFormatter = DateFormatter()
        shortTimeFormatter.locale = .autoupdatingCurrent
        shortTimeFormatter.timeZone = .autoupdatingCurrent
        shortTimeFormatter.dateStyle = .none
        shortTimeFormatter.timeStyle = .short

        @inline(__always) func stringValue(_ row: [String: Any], keys: [String]) -> String {
            for key in keys {
                guard let value = row[key], !(value is NSNull) else { continue }
                let text = String(describing: value).trimmingCharacters(in: .whitespacesAndNewlines)
                if !text.isEmpty { return text }
            }
            return ""
        }
        func parseDate(_ raw: String) -> Date? {
            let value = raw.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !value.isEmpty else { return nil }
            if let seconds = TimeInterval(value) {
                return Date(timeIntervalSince1970: seconds > 10_000_000_000 ? seconds / 1000.0 : seconds)
            }
            return localFormatter.date(from: value)
                ?? isoFormatter.date(from: value)
                ?? isoMillisFormatter.date(from: value)
        }

        let staleCutoff = now.addingTimeInterval(-10 * 60)
        var out: [LiveProgram] = []
        out.reserveCapacity(min(12, rows.count))
        for row in rows.prefix(12) {
            if Task.isCancelled { return [] }
            let title = stringValue(row, keys: ["title", "name", "programme", "program", "program_title", "event", "event_name"])
                .base64DecodedIfPossible()
                .ifEmpty("No information")
            let desc = stringValue(row, keys: ["description", "desc", "plot", "subtitle", "long_description"])
                .base64DecodedIfPossible()
            let start = parseDate(stringValue(row, keys: ["start", "start_timestamp", "start_time", "start_time_timestamp", "startTime", "starttime"]))
            let end = parseDate(stringValue(row, keys: ["end", "stop", "end_timestamp", "end_time", "stop_time", "stop_timestamp", "endTime", "stoptime"]))
            if let end, end < staleCutoff { continue }
            if let start, start > cutoff { continue }
            let minutes: Int
            if let start, let end, end > start { minutes = max(5, Int(end.timeIntervalSince(start) / 60.0)) }
            else { minutes = 30 }
            let isLive = (start ?? .distantFuture) <= now && now < (end ?? .distantPast)
            let width = CGFloat(max(120, min(560, Int((Double(minutes) / 30.0) * 120.0))))
            out.append(LiveProgram(
                title: title,
                width: width,
                isLive: isLive,
                description: desc,
                startText: start.map(shortTimeFormatter.string(from:)) ?? "",
                endText: end.map(shortTimeFormatter.string(from:)) ?? "",
                imageURL: "",
                startDate: start,
                endDate: end
            ))
        }
        return out.sorted { ($0.startDate ?? .distantPast) < ($1.startDate ?? .distantPast) }
    }

    private func loadXtream(server: String, username: String, password: String, sourceName: String = "Xtream/IPTV") async -> (channels: [LiveTVChannel], message: String) {
        let base = normalizeServerBase(server, defaultPort: nil)
        let user = urlQueryEncode(username)
        let pass = urlQueryEncode(password)
        async let categoriesText = fetchText("\(base)/player_api.php?username=\(user)&password=\(pass)&action=get_live_categories", accept: "application/json,*/*", maxBytes: 8 * 1024 * 1024, timeout: 12, attempts: 1)
        async let liveText = fetchText("\(base)/player_api.php?username=\(user)&password=\(pass)&action=get_live_streams", accept: "application/json,*/*", maxBytes: 128 * 1024 * 1024, timeout: 28, attempts: 1)
        let parsed = await parseXtreamPayloadOffMain(categoriesText: categoriesText, liveText: liveText)
        guard let parsed, !parsed.liveRows.isEmpty else {
            let fallback = await loadXtreamM3UPlaylist(base: base, user: user, pass: pass)
            if !fallback.isEmpty { return (fallback.map { Self.retagChannel($0, source: sourceName) }, "\(sourceName) Live • \(fallback.count) channel(s) via safe M3U fallback") }
            return ([], "Xtream failed or returned no live channels")
        }
        let channels = parsed.liveRows.prefix(30000).compactMap { draft -> LiveTVChannel? in
            let cat = draft.categoryName.ifEmpty(parsed.categoryMap[draft.categoryID] ?? "IPTV")
            return makeChannel(name: draft.name, number: draft.number, url: "\(base)/live/\(user)/\(pass)/\(draft.streamID).\(draft.extensionName.ifEmpty("m3u8"))", source: sourceName, category: inferCategory(name: draft.name, explicit: cat), iconURL: draft.iconURL, tvgID: draft.epgID)
        }
        return (channels, channels.isEmpty ? "\(sourceName) returned no live channels" : "\(sourceName) Live • \(channels.count) channel(s)")
    }

    private nonisolated func parseXtreamPayloadOffMain(categoriesText: String?, liveText: String?) async -> XtreamParsedPayload? {
        guard !Task.isCancelled else { return nil }
        var categoryMap: [String: String] = [:]
        if let categoriesText, let data = categoriesText.data(using: .utf8), let arr = try? JSONSerialization.jsonObject(with: data) as? [[String: Any]] {
            for (index, obj) in arr.prefix(5000).enumerated() {
                if index.isMultiple(of: 256), Task.isCancelled { return nil }
                let id = Self.jsonString(obj, keys: ["category_id"])
                let name = Self.jsonString(obj, keys: ["category_name"])
                if !id.isEmpty && !name.isEmpty { categoryMap[id] = name }
            }
        }
        guard !Task.isCancelled,
              let liveText,
              let data = liveText.data(using: .utf8),
              let arr = try? JSONSerialization.jsonObject(with: data) as? [[String: Any]] else { return nil }
        var drafts: [XtreamLiveDraft] = []
        drafts.reserveCapacity(min(arr.count, 30000))
        for (index, obj) in arr.prefix(30000).enumerated() {
            if index.isMultiple(of: 256), Task.isCancelled { return nil }
            let id = Self.jsonString(obj, keys: ["stream_id"])
            guard !id.isEmpty else { continue }
            drafts.append(XtreamLiveDraft(
                streamID: id,
                extensionName: Self.jsonString(obj, keys: ["container_extension"]).ifEmpty("m3u8"),
                name: Self.jsonString(obj, keys: ["name"]).ifEmpty("Channel \(id)"),
                categoryName: Self.jsonString(obj, keys: ["category_name"]),
                categoryID: Self.jsonString(obj, keys: ["category_id"]),
                epgID: Self.jsonString(obj, keys: ["epg_channel_id", "epg_id", "tvg_id", "tvg-id", "channel_id", "id"]),
                number: Self.jsonString(obj, keys: ["num"]),
                iconURL: Self.jsonString(obj, keys: ["stream_icon"])
            ))
        }
        return Task.isCancelled ? nil : XtreamParsedPayload(categoryMap: categoryMap, liveRows: drafts)
    }

    private nonisolated static func jsonString(_ obj: [String: Any], keys: [String]) -> String {
        for key in keys {
            if let value = obj[key] as? String { return value.trimmingCharacters(in: .whitespacesAndNewlines) }
            if let value = obj[key] as? NSNumber { return value.stringValue }
            if let value = obj[key] { return "\(value)".trimmingCharacters(in: .whitespacesAndNewlines) }
        }
        return ""
    }

    private func loadXtreamM3UPlaylist(base: String, user: String, pass: String) async -> [LiveTVChannel] {
        let url = "\(base)/get.php?username=\(user)&password=\(pass)&type=m3u_plus&output=m3u8"
        guard let text = await fetchText(url, accept: "audio/x-mpegurl,application/x-mpegURL,text/plain,*/*", maxBytes: 128 * 1024 * 1024, timeout: 22, attempts: 1) else { return [] }
        let parsed = await parseM3U(text, source: "Xtream/IPTV", baseURL: base)
        return Array(parsed.prefix(30000))
    }

    private func makeChannel(name: String, number: String, url: String, source: String, category: String, iconURL: String, tvgID: String) -> LiveTVChannel {
        let cleanLogo = channelLogo(name: name)
        let idSeed = "\(source)|\(number)|\(name)|\(url)".unicodeScalars.reduce(0) { ($0 &* 31 &+ Int($1.value)) & 0x7fffffff }
        return LiveTVChannel(id: max(1, idSeed), logo: cleanLogo, number: number, name: name, category: category, now: name, next: "Guide data loading", description: source, accent: Self.accent(for: category), streamURL: url, iconURL: iconURL, tvgID: tvgID, source: source)
    }

    private func applyXMLTVIcons(_ xml: String, to channels: [LiveTVChannel], baseURL: String = "") -> [LiveTVChannel] {
        let icons = xmltvChannelIcons(xml)
        guard !icons.isEmpty else { return channels }
        return channels.map { channel in
            if !channel.iconURL.isEmpty { return channel }
            let keys = channelMatchingKeys(channel)
            guard let rawIcon = keys.compactMap({ icons[$0] }).first(where: { !$0.isEmpty }) else { return channel }
            let icon = absoluteLogoURL(rawIcon, base: baseURL)
            return LiveTVChannel(id: channel.id, logo: channel.logo, number: channel.number, name: channel.name, category: channel.category, now: channel.now, next: channel.next, description: channel.description, accent: channel.accent, streamURL: channel.streamURL, iconURL: icon, tvgID: channel.tvgID, source: channel.source)
        }
    }

    private func xmltvChannelIcons(_ xml: String) -> [String: String] {
        // vBRDC119: compile the three XMLTV channel metadata patterns once per document.
        // The previous helper rebuilt icon/display-name regexes for every channel entry,
        // which is measurable CPU churn on large Gracenote/XMLTV feeds.
        guard let channelRegex = try? NSRegularExpression(
            pattern: #"<channel\s+[^>]*id=\"([^\"]+)\"[^>]*>(.*?)</channel>"#,
            options: [.caseInsensitive, .dotMatchesLineSeparators]
        ), let displayNameRegex = try? NSRegularExpression(
            pattern: #"<display-name[^>]*>(.*?)</display-name>"#,
            options: [.caseInsensitive, .dotMatchesLineSeparators]
        ), let iconRegex = try? NSRegularExpression(
            pattern: #"<icon[^>]*src=\"([^\"]+)\"[^>]*/?>"#,
            options: [.caseInsensitive]
        ) else { return [:] }

        var out: [String: String] = [:]
        let ns = xml as NSString
        for match in channelRegex.matches(in: xml, range: NSRange(location: 0, length: ns.length)) {
            if Task.isCancelled { break }
            let id = ns.substring(with: match.range(at: 1)).xmlDecoded()
            let body = ns.substring(with: match.range(at: 2))
            let bodyNS = body as NSString
            guard let iconMatch = iconRegex.firstMatch(in: body, range: NSRange(location: 0, length: bodyNS.length)),
                  iconMatch.numberOfRanges > 1 else { continue }
            let icon = bodyNS.substring(with: iconMatch.range(at: 1)).xmlDecoded()
            guard !icon.isEmpty else { continue }
            var keys = Set<String>()
            for key in xmltvLookupKeys(id) { keys.insert(key) }
            for nameMatch in displayNameRegex.matches(in: body, range: NSRange(location: 0, length: bodyNS.length)) where nameMatch.numberOfRanges > 1 {
                let display = bodyNS.substring(with: nameMatch.range(at: 1)).xmlDecoded()
                for key in xmltvLookupKeys(display) { keys.insert(key) }
            }
            for key in keys where !key.isEmpty { out[key] = icon }
        }
        return out
    }

    private func cappedGuideURL(_ raw: String) -> String {
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard var components = URLComponents(string: trimmed) else { return trimmed }
        var items = components.queryItems ?? []
        let hasDuration = items.contains { $0.name.lowercased() == "duration" }
        if hasDuration {
            items = items.map { item in
                item.name.lowercased() == "duration" ? URLQueryItem(name: item.name, value: String(liveGuideDurationSeconds)) : item
            }
        } else if trimmed.lowercased().contains("/guide/xmltv") {
            items.append(URLQueryItem(name: "duration", value: String(liveGuideDurationSeconds)))
        }
        components.queryItems = items.isEmpty ? nil : items
        return components.string ?? trimmed
    }

    private func parseXMLTV(_ xml: String, channels: [LiveTVChannel]) async -> [String: [LiveProgram]] {
        // vBRDC065: XMLTV programme parsing used to run synchronously on LiveTVSourceModel's
        // MainActor. Large provider guides can contain hundreds of thousands of programmes;
        // that normalization loop can hold the tvOS main thread long enough for FrontBoard's
        // process-exit watchdog (0x8BADF00D) to terminate the app.
        //
        // Resolve channel identities on MainActor, then move only value data into a utility
        // worker. Parent cancellation is explicitly forwarded so a stale guide parse cannot
        // continue after leaving Live TV or entering exclusive VOD playback.
        let snapshots = channels.map { channel in
            XMLTVGuideChannelSnapshot(
                resultKey: channelKey(channel),
                lookupKeys: channelMatchingKeys(channel)
            )
        }
        let durationSeconds = liveGuideDurationSeconds
        let maxRows = liveGuideMaxProgramRows
        let worker = Task.detached(priority: .utility) {
            LiveTVXMLTVBackgroundParser.parse(
                xml: xml,
                channels: snapshots,
                guideDurationSeconds: durationSeconds,
                guideMaxProgramRows: maxRows
            )
        }
        return await withTaskCancellationHandler(operation: {
            await worker.value
        }, onCancel: {
            worker.cancel()
        })
    }


    // vBRDC119: legacy per-row XMLTV DateFormatter/regex helpers were removed after
    // the background parser became authoritative. Keeping them invited accidental
    // reintroduction of main-thread formatter/regex construction.

    // vBRDC119: these lookup expressions are reused for every channel identity. The old
    // String regular-expression convenience API rebuilt regex machinery on first-use paths
    // for potentially thousands of channels. Compile once for the Live TV model lifetime.
    private static let xmltvLookupDigitRegex = try! NSRegularExpression(pattern: #"[0-9]{3,}"#)
    private static let xmltvLookupNumberedNameRegex = try! NSRegularExpression(pattern: #"^([0-9]+(?:[.\-_][0-9]+)?)\s+(.+)$"#)

    private func xmltvLookupKeys(_ raw: String) -> [String] {
        let value = raw.xmlDecoded().trimmingCharacters(in: .whitespacesAndNewlines)
        guard !value.isEmpty else { return [] }
        var keys = Set<String>()
        func add(_ candidate: String) {
            let clean = candidate.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !clean.isEmpty else { return }
            keys.insert(clean.lowercased())
            let normalized = normalizeGuideKey(clean)
            if !normalized.isEmpty { keys.insert(normalized) }
        }
        add(value)
        add(value.replacingOccurrences(of: ".", with: "-"))
        add(value.replacingOccurrences(of: "-", with: "."))
        add(value.replacingOccurrences(of: "_", with: "."))
        add(value.components(separatedBy: ".").first ?? value)
        add(value.components(separatedBy: "-").first ?? value)

        let ns = value as NSString
        let fullRange = NSRange(location: 0, length: ns.length)
        if let digitMatch = Self.xmltvLookupDigitRegex.firstMatch(in: value, range: fullRange) {
            add(ns.substring(with: digitMatch.range))
        }
        if let match = Self.xmltvLookupNumberedNameRegex.firstMatch(in: value, range: fullRange) {
            let pair = ns.substring(with: match.range).split(maxSplits: 1, whereSeparator: { $0.isWhitespace })
            if let first = pair.first {
                add(String(first))
                add(String(first).replacingOccurrences(of: "-", with: "."))
                add(String(first).replacingOccurrences(of: ".", with: "-"))
            }
            if pair.count > 1 { add(String(pair[1])) }
        }
        return Array(keys)
    }

    private func normalizeGuideKey(_ value: String) -> String {
        var clean = value.lowercased()
        for token in ["fhd", "uhd", "4k", "hd"] { clean = clean.replacingOccurrences(of: token, with: "") }
        return clean.components(separatedBy: CharacterSet.alphanumerics.inverted).joined()
    }


    // vBRDC119: removed the unused legacy instance XMLTV channel-name parser; the
    // detached LiveTVXMLTVBackgroundParser is the sole authoritative parser.


    func programs(for channel: LiveTVChannel) -> [LiveProgram] {
        if let compactPrograms = playbackQuickGuidePrograms[channel.id], !compactPrograms.isEmpty {
            return compactPrograms
        }
        if channel.isXtreamSource {
            for key in xtreamGuideLookupKeys(for: channel) {
                if let direct = guidePrograms[key], !direct.isEmpty { return direct }
            }
            return [
                LiveProgram(title: "No Xtream EPG returned yet", width: 300, isLive: true, description: "Waiting for provider XMLTV or native short EPG for this stream.", startText: "Now", endText: ""),
                LiveProgram(title: "Guide data loading", width: 360, isLive: false, description: channel.description, startText: "+30m", endText: "")
            ]
        }
        for key in channelMatchingKeys(channel) {
            if let direct = guidePrograms[key], !direct.isEmpty { return direct }
        }
        let legacyKey = channelKey(channel)
        if let direct = guidePrograms[legacyKey], !direct.isEmpty { return direct }
        return [
            LiveProgram(title: channel.now, width: 240, isLive: true, description: channel.description, startText: "Now", endText: ""),
            LiveProgram(title: channel.next, width: 360, isLive: false, description: channel.description, startText: "+30m", endText: ""),
            LiveProgram(title: channel.category == "Sports" ? "Live Sports" : channel.now, width: 300, isLive: false, description: channel.description),
            LiveProgram(title: channel.category == "Movies" ? "Feature Presentation" : channel.next, width: 330, isLive: false, description: channel.description)
        ]
    }

    func currentProgram(for channel: LiveTVChannel, at now: Date = Date()) -> LiveProgram? {
        if let cached = currentProgramCache[channel.id],
           cached.channel == channel,
           now < cached.validUntil {
            return cached.program
        }

        let rows = programs(for: channel)
        let resolved: LiveProgram?
        if let airing = rows.first(where: { $0.hasRealTiming && $0.isAiring(at: now) }) {
            resolved = airing
        } else if let untimed = rows.first(where: { !$0.hasRealTiming && $0.isLive }) {
            resolved = untimed
        } else if rows.allSatisfy({ !$0.hasRealTiming }) {
            resolved = rows.first
        } else {
            resolved = nil
        }

        let nextBoundary = rows.compactMap(\.startDate).filter { $0 > now }.min()
        let validUntil: Date
        if let end = resolved?.endDate, end > now {
            validUntil = end
        } else if let nextBoundary {
            validUntil = nextBoundary
        } else if resolved?.hasRealTiming == false {
            // Untimed provider fallback rows change only when channel/provider state changes.
            validUntil = .distantFuture
        } else {
            // Real-timing guide with no current/future row: retry occasionally in case a
            // clock-edge lands between incremental guide batches, without doing it per frame.
            validUntil = now.addingTimeInterval(5)
        }
        currentProgramCache[channel.id] = CurrentProgramCacheEntry(
            channel: channel,
            program: resolved,
            validUntil: validUntil
        )
        return resolved
    }

    func nextProgram(for channel: LiveTVChannel, after current: LiveProgram? = nil, at now: Date = Date()) -> LiveProgram? {
        let rows = programs(for: channel)
        let active = current ?? currentProgram(for: channel, at: now)

        // v1172: selecting the earliest qualifying row is equivalent to sorting the full
        // guide array and taking the first match, but avoids sorting up to 96 programme rows
        // every time focus changes or Quick Guide metadata refreshes.
        if let currentEnd = active?.endDate {
            let threshold = currentEnd.addingTimeInterval(-1)
            if let next = rows.lazy.filter({ candidate in
                guard let start = candidate.startDate else { return false }
                if let active, candidate.id == active.id { return false }
                return start >= threshold
            }).min(by: { ($0.startDate ?? .distantFuture) < ($1.startDate ?? .distantFuture) }) {
                return next
            }
        }
        if let upcoming = rows.lazy.filter({ candidate in
            guard let start = candidate.startDate else { return false }
            if let active, candidate.id == active.id { return false }
            return start > now
        }).min(by: { ($0.startDate ?? .distantFuture) < ($1.startDate ?? .distantFuture) }) {
            return upcoming
        }
        if let active, let index = rows.firstIndex(where: { $0.id == active.id }), rows.indices.contains(index + 1) {
            return rows[index + 1]
        }
        return rows.dropFirst().first
    }

    private func channelMatchingKeys(_ channel: LiveTVChannel) -> [String] {
        let fingerprint = [channel.tvgID, channel.number, channel.name, channel.logo]
            .joined(separator: "|#|")
        if let cached = channelMatchingKeyCache[channel.id], cached.fingerprint == fingerprint {
            return cached.keys
        }
        var keys = Set<String>()
        for raw in [channel.tvgID, channel.number, channel.name, channel.logo, "\(channel.number) \(channel.name)", "\(channel.number) \(channel.logo)", "\(channel.logo) \(channel.number)", "\(channel.name) \(channel.number)"] {
            for key in xmltvLookupKeys(raw) { keys.insert(key) }
        }
        let resolved = Array(keys)
        channelMatchingKeyCache[channel.id] = (fingerprint, resolved)
        return resolved
    }


    private func channelKey(_ channel: LiveTVChannel) -> String { "\(channel.source)|\(channel.number)|\(channel.name)".lowercased() }

    private func dedupe(_ channels: [LiveTVChannel]) -> [LiveTVChannel] {
        var seen = Set<String>()
        var out: [LiveTVChannel] = []
        for channel in channels {
            let key = !channel.streamURL.isEmpty ? "url:\(channel.streamURL)" : (!channel.number.isEmpty ? "source-num:\(channel.source.lowercased()):\(channel.number)" : "source-name:\(channel.source.lowercased()):\(channel.name.lowercased())")
            if seen.insert(key).inserted { out.append(channel) }
        }
        return out
    }

    // vBRDC153: Live TV provider/bootstrap transport recovery.
    // MediaFlow may itself be configured on plain HTTP. The old path forced every http://
    // bootstrap through PlainHTTPClient, which intentionally implements only a tiny HTTP/1.1
    // subset and therefore misses URLSession's redirect/content-decoding behavior. That is
    // acceptable as a last-resort ATS compatibility lane, but not as the primary transport for
    // MediaFlow JSON/M3U/XMLTV responses. Use the same connectivity-aware URLSession first for
    // both HTTP and HTTPS, then fall back to PlainHTTPClient only when a plain-HTTP request truly
    // cannot be completed by URLSession. `attempts` lets lineup probes stay bounded while the
    // heavier guide path retains the historical transient retry.
    private func fetchText(_ urlString: String, accept: String = "*/*", maxBytes: Int = 4 * 1024 * 1024, timeout: TimeInterval = 45, attempts: Int = 2) async -> String? {
        guard !VODExclusivePlaybackGate.isActive, !Task.isCancelled else { return nil }
        guard let url = URL(string: urlString) else { return nil }
        var request = URLRequest(url: url, timeoutInterval: timeout)
        request.setValue(accept, forHTTPHeaderField: "Accept")
        request.setValue("DebridChannels-tvOS/560", forHTTPHeaderField: "User-Agent")
        request.setValue("identity", forHTTPHeaderField: "Accept-Encoding")

        // vBRDC115 contract stays intact: bootstrap traffic still routes through MediaFlow
        // when enabled; this change only repairs how the already-routed response is fetched.
        let lowerAccept = accept.lowercased()
        let lowerURLString = urlString.lowercased()
        let isEPGRequest = lowerAccept.contains("xml") ||
            lowerURLString.contains("xmltv") ||
            lowerURLString.contains("/guide/xmltv") ||
            lowerURLString.hasSuffix(".xml") ||
            lowerURLString.contains(".xml?")
        guard let networkRequests = MediaFlowProxyRouter.liveTVBootstrapRequestsIfAllowed(request, epg: isEPGRequest) else { return nil }

        let boundedAttempts = max(1, min(attempts, 2))
        for networkRequest in networkRequests {
            guard let networkURL = networkRequest.url else { continue }
            let networkAccept = networkRequest.value(forHTTPHeaderField: "Accept") ?? "*/*"
            let networkUserAgent = networkRequest.value(forHTTPHeaderField: "User-Agent") ?? "DebridChannels-tvOS/MediaFlow"
            var shouldTryNextRoute = false

            for attempt in 0..<boundedAttempts {
                guard !Task.isCancelled, !VODExclusivePlaybackGate.isActive else { return nil }

                // Primary path for *both* http:// and https://. App Transport Security already
                // allows arbitrary loads in this target, and URLSession correctly handles 30x,
                // chunked transfer, gzip/content-encoding, cookies disabled by the ephemeral
                // provider session, and modern MediaFlow response framing.
                do {
                    let (data, response) = try await Self.providerSession.data(for: networkRequest)
                    guard !Task.isCancelled, !VODExclusivePlaybackGate.isActive else { return nil }
                    let bounded = Data(data.prefix(maxBytes))
                    if let http = response as? HTTPURLResponse {
                        if (200...299).contains(http.statusCode) {
                            return String(data: bounded, encoding: .utf8)
                                ?? String(data: bounded, encoding: .isoLatin1)
                        }
                        if http.statusCode < 500 { shouldTryNextRoute = true; break }
                    } else if !bounded.isEmpty {
                        return String(data: bounded, encoding: .utf8)
                            ?? String(data: bounded, encoding: .isoLatin1)
                    }
                } catch {
                    guard !Task.isCancelled else { return nil }

                    // Compatibility fallback only. This keeps old sideload/HTTP appliances
                    // working if URLSession is unexpectedly blocked while preventing the raw
                    // helper from owning normal MediaFlow traffic.
                    if networkURL.scheme?.lowercased() == "http" {
                        do {
                            let plain = try await PlainHTTPClient.fetchData(
                                from: networkURL,
                                accept: networkAccept,
                                userAgent: networkUserAgent,
                                maxBytes: maxBytes,
                                timeout: timeout
                            )
                            guard !Task.isCancelled, !VODExclusivePlaybackGate.isActive else { return nil }
                            if (200...299).contains(plain.statusCode) {
                                return String(data: plain.data, encoding: .utf8)
                                    ?? String(data: plain.data, encoding: .isoLatin1)
                            }
                            if plain.statusCode < 500 { shouldTryNextRoute = true; break }
                        } catch {
                            guard !Task.isCancelled else { return nil }
                        }
                    }
                }

                if attempt + 1 < boundedAttempts {
                    try? await Task.sleep(nanoseconds: 350_000_000)
                }
            }
            if shouldTryNextRoute { continue }
        }
        return nil
    }

    // vBRDC119: EXTINF attributes are parsed in one precompiled-regex pass inside
    // parseM3UDrafts; the old one-regex-per-attribute helper is intentionally removed.

    private func channelLogo(name: String) -> String {
        let words = name.components(separatedBy: CharacterSet.alphanumerics.inverted).filter { !$0.isEmpty }
        if words.count >= 2 { return words.prefix(2).compactMap { $0.first.map(String.init) }.joined().uppercased() }
        return String(name.prefix(8)).uppercased()
    }

    private func inferCategory(name: String, explicit: String) -> String {
        let cleaned = explicit.split(separator: ";").first.map(String.init) ?? explicit
        if !cleaned.isEmpty && cleaned.lowercased() != "channels dvr" && cleaned.lowercased() != "iptv" { return normalizeCategory(cleaned, fallback: cleaned) }
        return normalizeCategory("", fallback: name)
    }

    private func normalizeCategory(_ raw: String, fallback: String) -> String {
        let lower = (raw + " " + fallback).lowercased()
        if lower.contains("sport") || lower.contains("sports") || lower.contains("ppv") || lower.contains("event") || lower.contains("nfl") || lower.contains("nba") || lower.contains("mlb") || lower.contains("nhl") || lower.contains("ufc") || lower.contains("wwe") || lower.contains("espn") || lower.contains("bein") || lower.contains("sky sports") || lower.contains("tnt sports") || lower.contains("dazn") { return "Sports" }
        if lower.contains("news") || lower.contains("cnn") || lower.contains("msnbc") { return "News" }
        if lower.contains("kid") || lower.contains("cartoon") || lower.contains("disney") || lower.contains("nick") { return "Kids" }
        if lower.contains("movie") || lower.contains("hbo") || lower.contains("cinema") || lower.contains("starz") { return "Movies" }
        if lower.contains("favorite") { return "Favorites" }
        if lower.contains("hd") { return "HD" }
        if lower.contains("drama") { return "Drama" }
        return raw.isEmpty ? "All" : raw
    }

    private func absoluteLogoURL(_ raw: String, base: String) -> String {
        let clean = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !clean.isEmpty else { return "" }
        if clean.lowercased().hasPrefix("http") { return clean }
        if clean.hasPrefix("/") { return base.trimmingCharacters(in: CharacterSet(charactersIn: "/")) + clean }
        if !base.isEmpty { return base.trimmingCharacters(in: CharacterSet(charactersIn: "/")) + "/" + clean }
        return clean
    }

    private func absoluteStreamURL(_ raw: String, base: String) -> String {
        let clean = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !clean.isEmpty else { return "" }
        if clean.lowercased().hasPrefix("http") { return clean }
        if clean.hasPrefix("/") { return base.trimmingCharacters(in: CharacterSet(charactersIn: "/")) + clean }
        if !base.isEmpty { return base.trimmingCharacters(in: CharacterSet(charactersIn: "/")) + "/" + clean }
        return clean
    }

    private func urlEncode(_ value: String) -> String { value.addingPercentEncoding(withAllowedCharacters: .urlPathAllowed) ?? value }
    private func urlQueryEncode(_ value: String) -> String {
        var allowed = CharacterSet.urlQueryAllowed
        allowed.remove(charactersIn: "+&=?#%")
        return value.addingPercentEncoding(withAllowedCharacters: allowed) ?? value
    }
    private func channelSortKey(_ value: String) -> Double { Double(value.replacingOccurrences(of: ".", with: ".").components(separatedBy: CharacterSet(charactersIn: "0123456789.").inverted).joined()) ?? Double.greatestFiniteMagnitude }
}

private extension String {
    func ifEmpty(_ replacement: String) -> String { isEmpty ? replacement : self }
    func xmlDecoded() -> String {
        replacingOccurrences(of: "&amp;", with: "&")
            .replacingOccurrences(of: "&lt;", with: "<")
            .replacingOccurrences(of: "&gt;", with: ">")
            .replacingOccurrences(of: "&quot;", with: "\"")
            .replacingOccurrences(of: "&#39;", with: "'")
    }
    func base64DecodedIfPossible() -> String {
        let trimmed = trimmingCharacters(in: .whitespacesAndNewlines)
        guard trimmed.count >= 8,
              trimmed.range(of: #"^[A-Za-z0-9+/=]+$"#, options: .regularExpression) != nil,
              let data = Data(base64Encoded: trimmed),
              let decoded = String(data: data, encoding: .utf8),
              !decoded.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return self }
        return decoded.xmlDecoded()
    }
}

