private enum LiveTVGridFocusRingPalette {
    static let names = ["White", "Cyan", "Orange", "Blue", "Purple", "Green", "Red", "Gold"]

    static func normalized(_ raw: String) -> String {
        names.contains(raw) ? raw : "White"
    }

    static func next(after raw: String) -> String {
        let current = normalized(raw)
        guard let index = names.firstIndex(of: current) else { return names[0] }
        return names[(index + 1) % names.count]
    }

    static func color(_ raw: String) -> Color {
        switch normalized(raw) {
        case "Cyan": return .cyan
        case "Orange": return .orange
        case "Blue": return .blue
        case "Purple": return .purple
        case "Green": return .green
        case "Red": return .red
        case "Gold": return Color(red: 1.0, green: 0.77, blue: 0.20)
        default: return .white
        }
    }
}

