// timers, provider state, focus, or grid geometry. The repeating animations are compositor-only
// and are explicitly stopped whenever the persistent Live TV root is covered.
private struct LiveTVAnimatedHeaderLogo: View {
    let styleName: String
    let active: Bool
    let accent: Color
    @State private var pulse: Bool = false
    @State private var shine: Bool = false

    private var style: String { LiveTVAnimatedHeaderLogoStyle.normalized(styleName) }

    var body: some View {
        Group {
            switch style {
            case "Retro Tube": retroTubeLogo
