                Text("TV NETWORK").font(.system(size: 7, weight: .black, design: .rounded)).tracking(1.2).foregroundStyle((shine ? Color.cyan : accent).opacity(0.90))
            }
        }
    }

    private func synchronizeAnimation(_ enabled: Bool) {
        if enabled {
            pulse = false
            shine = false
            withAnimation(.easeInOut(duration: 2.15).repeatForever(autoreverses: true)) { pulse = true }
            withAnimation(.easeInOut(duration: 3.20).repeatForever(autoreverses: true)) { shine = true }
        } else {
            var transaction = Transaction()
            transaction.animation = nil
            withTransaction(transaction) {
                pulse = false
                shine = false
            }
        }
    }
}

