        .onAppear {
            glow = false
            withAnimation(.easeInOut(duration: 1.55).repeatForever(autoreverses: true)) { glow = true }
        }
        .accessibilityLabel("Exit Guide with Back or Menu")
    }
}

// vBRDC348: this is a real Live TV dashboard layout, not an artwork/card effect.
// The persistent provider/Gracenote model and existing twelve native focus targets are shared.
private enum SignalLiveTVDashboardStyle {
    static let names = ["Golden", "Preview Mirror"]
    static func normalized(_ raw: String) -> String { names.contains(raw) ? raw : "Golden" }
    static func next(_ raw: String) -> String {
        let index = names.firstIndex(of: normalized(raw)) ?? 0
        return names[(index + 1) % names.count]
    }
}

// One chrome renderer is shared by the non-interactive customization confirmation and
// the real, interactive Preview Mirror dashboard. No independent sample-card UI is added.
private struct SignalLiveTVMirrorHeader<ModeChip: View>: View {
    @AppStorage("signalChromeLogoSizeV346") private var logoSize: String = "Small"
    let category: String
    let channelCount: Int
    let logoStyle: String
    let showLiveLogo: Bool
    let liveLogoActive: Bool
    let accent: Color
    let showMenuHint: Bool
    let upNextProgram: LiveProgram?
    let showUpNext: Bool
    let showCornerClock: Bool
    let modeChip: ModeChip

    init(category: String, channelCount: Int, logoStyle: String, showLiveLogo: Bool,
         liveLogoActive: Bool, accent: Color, showMenuHint: Bool = false,
         upNextProgram: LiveProgram? = nil, showUpNext: Bool = false,
         showCornerClock: Bool = false,
         @ViewBuilder modeChip: () -> ModeChip) {
        self.category = category
        self.channelCount = channelCount
        self.logoStyle = logoStyle
        self.showLiveLogo = showLiveLogo
        self.liveLogoActive = liveLogoActive
        self.accent = accent
        self.showMenuHint = showMenuHint
        self.upNextProgram = upNextProgram
        self.showUpNext = showUpNext
        self.showCornerClock = showCornerClock
        self.modeChip = modeChip()
    }

    var body: some View {
        HStack(alignment: .top, spacing: 28) {
            // Preview Mirror: UP NEXT sits ABOVE both the Live TV and animated Signal marks.
            // Keep its text in the header flow, not underneath either animation.
            VStack(alignment: .leading, spacing: showUpNext ? 5 : 0) {
                if showUpNext {
                    HStack(spacing: 8) {
                        Text("UP NEXT")
                            .font(.system(size: 10, weight: .black, design: .rounded))
                            .tracking(1.2)
                            .foregroundStyle(accent.opacity(0.94))
                        if let upNextProgram {
                            Text(upNextProgram.startText)
                                .font(.system(size: 10, weight: .bold, design: .rounded))
                                .foregroundStyle(.white.opacity(0.42))
                            Text(upNextProgram.title)
                                .font(.system(size: 11, weight: .semibold, design: .rounded))
                                .foregroundStyle(.white.opacity(0.76))
                                .lineLimit(1)
                        } else {
                            Text("Schedule unavailable")
                                .font(.system(size: 10, weight: .medium, design: .rounded))
                                .foregroundStyle(.white.opacity(0.46))
                        }
                    }
                    .padding(.leading, 2)
                }
                HStack(spacing: 28) {
                    DebridChannelsChromeWordmark()
                        .frame(width: SignalChromeLogoSize.width(logoSize), height: 52, alignment: .leading)
                    if showLiveLogo {
                        LiveTVAnimatedHeaderLogo(styleName: logoStyle, active: liveLogoActive, accent: accent)
                            .frame(width: 190, height: 66, alignment: .leading)
                    }
                }
            }
            Spacer(minLength: 15)
            if showMenuHint {
                Text("↑  ↑  REVEAL TOP MENU")
                    .font(.system(size: 11, weight: .medium))
                    .tracking(1.2)
                    .foregroundStyle(Color.white.opacity(0.56))
                    .accessibilityLabel("From the top channel row, press Up twice to reveal the top menu")
                    .fixedSize(horizontal: true, vertical: false)
                    .padding(.top, 10)
            }
            Spacer(minLength: 15)
            VStack(alignment: .leading, spacing: 2) {
                Text(category == "All" ? "ALL CHANNELS" : category.uppercased())
                    .font(.system(size: 16, weight: .bold)).tracking(2)
                    .lineLimit(1)
                Text("\(channelCount) CHANNELS")
                    .font(.system(size: 12, weight: .regular))
                    .foregroundStyle(.white.opacity(0.62))
            }
            modeChip
                .padding(.top, 2)
        }
        .foregroundStyle(.white)
        .frame(height: 92, alignment: .top)
        // Clock belongs to the always-visible mirror header, not to the 15-second
        // auto-hiding navigation. Trailing alignment keeps a consistent right inset.
        .overlay(alignment: .topTrailing) {
            if showCornerClock {
                LiveClockText(fontSize: 15)
                    .fixedSize(horizontal: true, vertical: false)
                    .padding(.trailing, 2)
                    .offset(y: -25)
                    .allowsHitTesting(false)
            }
        }
    }
}

