// vBRDC342: live-card presentation only. The focus/navigation grid remains the v334 lattice.
// The confirmation dashboard below and production card renderer use this same theme contract.
// vBRDC344: no fake themes. Shape, depth effect and visible card size are independent.
// Original UNITY preserves the established rounded card. Old v342 names migrate safely.
private enum SignalLiveTVCardTheme {
    static let names = ["Original UNITY", "Squared", "Soft Rounded", "Cinema Curve", "Pill"]
    static func normalized(_ raw: String) -> String { names.contains(raw) ? raw : "Original UNITY" }
    static func next(_ raw: String) -> String {
        let i = names.firstIndex(of: normalized(raw)) ?? 0
        return names[(i + 1) % names.count]
    }
    static func radius(_ raw: String) -> CGFloat {
        switch normalized(raw) {
        case "Squared": return 3
        case "Soft Rounded": return 13
        case "Cinema Curve": return 38
        case "Pill": return 72
        default: return 24
        }
    }
}

// vBRDC346: independent Live TV typography; all are system/platform fonts.
private enum SignalLiveTVCardTypography {
    static let names = ["UNITY Original", "SF Pro Light", "SF Pro Regular", "SF Pro Medium", "SF Rounded", "Avenir Light", "Avenir Regular", "Cinema Serif", "Broadcast Condensed"]
    static func normalized(_ raw: String) -> String { names.contains(raw) ? raw : "UNITY Original" }
    static func next(_ raw: String) -> String {
        let index = names.firstIndex(of: normalized(raw)) ?? 0
        return names[(index + 1) % names.count]
    }
    static func title(_ raw: String, focused: Bool) -> Font {
        let size: CGFloat = focused ? 16 : 15
        switch normalized(raw) {
        case "SF Pro Light": return .system(size: size, weight: .light)
        case "SF Pro Regular": return .system(size: size, weight: .regular)
        case "SF Pro Medium": return .system(size: size, weight: .medium)
        case "SF Rounded": return .system(size: size, weight: .regular, design: .rounded)
        case "Avenir Light": return .custom("AvenirNext-UltraLight", size: size)
        case "Avenir Regular": return .custom("AvenirNext-Regular", size: size)
        case "Cinema Serif": return .system(size: size, weight: .regular, design: .serif)
        case "Broadcast Condensed": return .system(size: size, weight: .medium, design: .rounded)
        default: return .system(size: size, weight: .heavy, design: .rounded)
        }
    }
    static func secondary(_ raw: String) -> Font {
        .system(size: 11, weight: normalized(raw) == "UNITY Original" ? .bold : .regular, design: .rounded)
    }
}

private enum SignalLiveTVCardEffect {
    static let names = ["Original", "Tilt Left", "Tilt Right", "Dual Inward", "Split Inward", "Dual Inward Strong", "Split Inward Strong"]
    static func normalized(_ raw: String) -> String { names.contains(raw) ? raw : "Original" }
    static func resolved(_ raw: String, legacyShape: String) -> String {
        if normalized(raw) == "Original" {
            if legacyShape == "UNITY 3D Left" { return "Tilt Left" }
            if legacyShape == "UNITY 3D Right" { return "Tilt Right" }
        }
        return normalized(raw)
    }
    static func next(_ raw: String) -> String {
        let i = names.firstIndex(of: normalized(raw)) ?? 0
        return names[(i + 1) % names.count]
    }
}

private enum SignalLiveTVCardSize {
    static let names = ["Compact", "Standard", "Large"]
    static func normalized(_ raw: String) -> String { names.contains(raw) ? raw : "Standard" }
    static func next(_ raw: String) -> String {
        let i = names.firstIndex(of: normalized(raw)) ?? 1
        return names[(i + 1) % names.count]
    }
    // Compositor-only sizing: card positions and the 12-slot focus lattice never change.
    static func scale(_ raw: String) -> CGFloat {
        switch normalized(raw) {
        case "Compact": return 0.90
        case "Large": return 1.04
        default: return 1.0
        }
    }
}

// vBRDC126: the Live TV focus engine owns navigation; this tiny host owns only the
// visual transform. The card subtree explicitly rejects the host's focus transaction,
// so footer/artwork/preview/ring state cannot accidentally inherit a second spring.
// Defocus settles quickly while focus remains velocity-friendly for rapid Siri Remote input.
private struct LiveTVGridFocusMotionHost<Content: View>: View {
    let isFocused: Bool
    let gridLockedMode: Bool
    let firstColumn: Bool
    let dimmed: Bool
    let previewPopOut: Bool
    let accent: Color
    let cardTheme: String
    let cardEffect: String
    let cardSize: String
    let columnIndex: Int
    let content: Content

    init(
        isFocused: Bool,
        gridLockedMode: Bool,
        firstColumn: Bool,
        dimmed: Bool,
        previewPopOut: Bool,
        accent: Color,
        cardTheme: String,
        cardEffect: String,
        cardSize: String,
        columnIndex: Int = 0,
        @ViewBuilder content: () -> Content
    ) {
        self.isFocused = isFocused
        self.gridLockedMode = gridLockedMode
        self.firstColumn = firstColumn
        self.dimmed = dimmed
        self.previewPopOut = previewPopOut
        self.accent = accent
        self.cardTheme = cardTheme
        self.cardEffect = cardEffect
        self.cardSize = cardSize
        self.columnIndex = columnIndex
        self.content = content()
    }

    // Columns 0/1 face right; columns 2/3 face left. This is independent of
    // focus, so the two halves are visibly angled even before selecting a tile.
    private var isDualEffect: Bool {
        let effect = SignalLiveTVCardEffect.normalized(cardEffect)
        return effect == "Dual Inward" || effect == "Split Inward" || effect == "Dual Inward Strong" || effect == "Split Inward Strong"
    }
    private var tiltDegrees: Double {
        switch SignalLiveTVCardEffect.normalized(cardEffect) {
        case "Tilt Left": return isFocused ? -7 : 0
        case "Tilt Right": return isFocused ? 7 : 0
        case "Dual Inward", "Split Inward":
            return (columnIndex < 2 ? 1.0 : -1.0) * (isFocused ? 8.5 : 4.0)
        case "Dual Inward Strong", "Split Inward Strong":
            // Larger fixed perspective, no additional per-card state or navigation targets.
            return (columnIndex < 2 ? 1.0 : -1.0) * (isFocused ? 14.0 : 8.0)
        default: return isFocused ? -1.55 : 0
        }
    }
    private var tiltAxis: (x: CGFloat, y: CGFloat, z: CGFloat) {
        switch SignalLiveTVCardEffect.normalized(cardEffect) {
        case "Tilt Left", "Tilt Right", "Dual Inward", "Split Inward", "Dual Inward Strong", "Split Inward Strong":
            return (x: 0.12, y: 1, z: 0)
        default: return (x: 0.96, y: 0.12, z: 0)
        }
    }
    private var effectScale: CGFloat { 1.078 }
    private var usesYPerspective: Bool {
        let effect = SignalLiveTVCardEffect.normalized(cardEffect)
        return effect.hasPrefix("Tilt") || isDualEffect
    }
    var body: some View {
        content
            .transaction { transaction in
                // vBRDC296: Live TV paging/focus now follows tvOS' own focus cadence.
                // The card keeps the same visual geometry but does not run an overlapping
                // spring state machine that can make rapid page moves bounce or hitch.
                transaction.animation = nil
            }
            .scaleEffect(SignalLiveTVCardSize.scale(cardSize) * (isFocused ? (previewPopOut ? (gridLockedMode ? 1.085 : 1.125) : (gridLockedMode ? 1.055 : effectScale)) : 1.0))
            .rotation3DEffect(
                .degrees(tiltDegrees),
                axis: tiltAxis,
                perspective: usesYPerspective ? 0.58 : 0.72
            )
            .offset(
                x: (gridLockedMode && isFocused && firstColumn) ? 28 : 0,
                y: isFocused ? (previewPopOut ? (gridLockedMode ? -10 : -18) : (gridLockedMode ? -3 : -8)) : 0
            )
            .opacity(dimmed ? 0.28 : 1.0)
            .shadow(
                color: .black.opacity(isFocused ? 0.78 : 0.18),
                radius: isFocused ? (previewPopOut ? 42 : 28) : 5,
                y: isFocused ? (previewPopOut ? 24 : 18) : 3
            )
            // Channels-style focus handoff: rise quickly, settle/defocus more slowly.
            // Critically damped/ease-out only — no spring overshoot or bounce.
            .animation(.easeOut(duration: isFocused ? 0.20 : 0.36), value: isFocused)
            .animation(.easeOut(duration: 0.22), value: previewPopOut)
    }
}

private final class LiveTVGridInteractionRuntime: ObservableObject {
    var previewArmTask: Task<Void, Never>? = nil
    var previewStopTask: Task<Void, Never>? = nil
    var previewGeneration: Int = 0
    var guidePreviewWarmupGeneration: Int = 0
    var guidePreviewWarmupTask: Task<Void, Never>? = nil
    var guideSelectionCommitTask: Task<Void, Never>? = nil
    var artworkPrefetchTask: Task<Void, Never>? = nil
    var selectionPersistenceTask: Task<Void, Never>? = nil
    var windowMaintenanceTask: Task<Void, Never>? = nil

    func cancelGridWork() {
        previewArmTask?.cancel()
        previewArmTask = nil
        previewStopTask?.cancel()
        previewStopTask = nil
        artworkPrefetchTask?.cancel()
        artworkPrefetchTask = nil
        guidePreviewWarmupTask?.cancel()
        guidePreviewWarmupTask = nil
        guideSelectionCommitTask?.cancel()
        guideSelectionCommitTask = nil
        selectionPersistenceTask?.cancel()
        selectionPersistenceTask = nil
        windowMaintenanceTask?.cancel()
        windowMaintenanceTask = nil
    }

    deinit {
        cancelGridWork()
    }
}

private struct LiveTVGridFocusRingOverlay: View {
    let colorName: String
    let motionName: String
    // vBRDC177 compile fix: this must be an explicit stored-property initializer input.
    // A `let` with an inline default is not emitted as an overridable memberwise argument,
    // while the active card shell supplies its exact visual corner radius.
    let cornerRadius: CGFloat

    private var ringColor: Color { LiveTVGridFocusRingPalette.color(colorName) }
    private var motion: String { LiveTVGridFocusRingMotionStyle.normalized(motionName) }
    private var animated: Bool { motion == "Soft Pulse" || motion == "Breathing Glow" }

    var body: some View {
        TimelineView(.animation(minimumInterval: 1.0 / 30.0, paused: !animated)) { context in
            let phase = pulsePhase(at: context.date)
            let phaseCGFloat = CGFloat(phase)
            let cardShape = RoundedRectangle(cornerRadius: cornerRadius, style: .continuous)
            let haloOpacity: Double = {
                switch motion {
                case "Soft Pulse": return 0.18 + (0.46 * phase)
                case "Breathing Glow": return 0.14 + (0.38 * phase)
                case "Classic Glow": return 0.36
                default: return 0.0
                }
            }()
            let haloWidth: CGFloat = {
                switch motion {
                case "Soft Pulse": return 5.5 + (2.5 * phaseCGFloat)
                case "Breathing Glow": return 5.0 + (2.0 * phaseCGFloat)
                case "Classic Glow": return 6.0
                default: return 0.0
                }
            }()
            let haloBlur: CGFloat = {
                switch motion {
                case "Soft Pulse": return 1.8 + (2.6 * phaseCGFloat)
                case "Breathing Glow": return 2.4 + (3.4 * phaseCGFloat)
                case "Classic Glow": return 2.8
                default: return 0.0
                }
            }()

            ZStack {
                // vBRDC175: use the exact card radius supplied by LiveTVGridTileContent. No sibling
                // host geometry or pulse scale is allowed to create a second silhouette.
                cardShape
                    .stroke(
                        ringColor.opacity(motion == "Steady Ring" ? 0.84 : 0.92),
                        lineWidth: motion == "Steady Ring" ? 2.0 : 2.5
                    )

                if motion != "Steady Ring" {
                    cardShape
                        .stroke(ringColor.opacity(haloOpacity), lineWidth: haloWidth)
                        .blur(radius: haloBlur)
                        .shadow(
                            color: ringColor.opacity(haloOpacity * 0.90),
                            radius: motion == "Classic Glow" ? 11 : (8 + (9 * phaseCGFloat))
                        )
                }
            }
        }
        .allowsHitTesting(false)
    }

    private func pulsePhase(at date: Date) -> Double {
        guard animated else { return 1.0 }
        let period = motion == "Soft Pulse" ? 1.90 : 3.10
        let radians = (date.timeIntervalSinceReferenceDate / period) * 2.0 * Double.pi
        return 0.5 + (0.5 * sin(radians))
    }
}


struct GridLockedDockPoster: View {
    let item: MediaItem
    let index: Int
    let isFocused: Bool

    private var w: CGFloat { isFocused ? 292 : 258 }
    private var h: CGFloat { isFocused ? 164 : 146 }

    var body: some View {
        ZStack(alignment: .bottomLeading) {
            Color.black.opacity(0.34)
            RemoteImageFit(url: item.landscapeURL ?? item.posterURL, mode: .fill)
            LinearGradient(colors: [.clear, Color.black.opacity(isFocused ? 0.78 : 0.64)], startPoint: .center, endPoint: .bottom)
            Text(item.title)
                .font(.system(size: isFocused ? 16 : 13, weight: .black, design: .rounded))
                .foregroundStyle(.white.opacity(0.92))
                .lineLimit(1)
                .padding(.horizontal, isFocused ? 14 : 10)
                .padding(.bottom, isFocused ? 12 : 9)
        }
        .frame(width: w, height: h)
        .clipShape(RoundedRectangle(cornerRadius: isFocused ? 18 : 14, style: .continuous))
        .overlay(RoundedRectangle(cornerRadius: isFocused ? 18 : 14, style: .continuous).stroke(isFocused ? Color.white.opacity(0.86) : Color.white.opacity(0.10), lineWidth: isFocused ? 3 : 1))
        .shadow(color: .black.opacity(isFocused ? 0.72 : 0.40), radius: isFocused ? 18 : 8, y: isFocused ? 10 : 5)
        .scaleEffect(isFocused ? 1.02 : 1.0)
        .animation(.spring(response: 0.30, dampingFraction: 0.88), value: isFocused)
    }
}
// UNITY: Home/Movies/Shows/Sports retain the one real LiveTVScreen visual root.
// No synthetic/frozen donor is permitted in the UNITY shared-root path.

// vBRDC170: Live TV Grid owns the dynamic wallpaper as one full-screen ambient surface.
// It stays alive through grid focus/page motion and the grid's own quick panel only. The full
// Guide deliberately uses its static broadcast background and never mounts this wallpaper.
private struct LiveTVUnityDynamicWallpaperSurface: View {
    @ObservedObject private var unityAnimations = UnityAnimationCoordinator.shared
    let builtInStyle: String
    let performanceMode: String
    let customEnabled: Bool
    let customURL: String

    var body: some View {
        // vBRDC347: Navigation owns every frame while the remote is moving. Pausing
        // the existing renderer/player (rather than mounting a second instance or
        // lowering display quality) removes wallpaper work immediately. The shared
        // coordinator publishes only at burst begin/end; no per-tile subscriptions.
        let yieldToNavigation = unityAnimations.navigationBurstActive
            || unityAnimations.postNavigationVisualRecoveryActive
            || unityAnimations.surfaceHandoffActive
            || !unityAnimations.allows(.dynamicWallpaper)
        DynamicWallpaperSurface(
            builtInStyle: builtInStyle,
            performanceMode: performanceMode,
            paused: yieldToNavigation,
            continuousWhileBrowsing: false,
            customEnabled: customEnabled,
            customURL: customURL
        )
        .frame(maxWidth: .infinity, maxHeight: .infinity)
    }
}

