    @AppStorage("myFavoriteChannelIds") private var myFavoriteChannelIdsRaw: String = ""
    @AppStorage("sportsAssignedGroups") private var sportsAssignedGroupsRaw: String = ""
    @AppStorage("sportsManualChannelIds") private var sportsManualChannelIdsRaw: String = ""
    @AppStorage("sportsExcludedChannelIds") private var sportsExcludedChannelIdsRaw: String = ""
    @AppStorage("liveTVGridThemePreset") private var liveTVGridThemePreset: String = "Classic Dark"
    @AppStorage("mainGridBackgroundPreset") private var mainGridBackgroundPreset: String = "Midnight Graphite"
    @AppStorage("dynamicMainGridWallpaperEnabled") private var dynamicMainGridWallpaperEnabled: Bool = false
    @AppStorage("dynamicMainGridWallpaperPreset") private var dynamicMainGridWallpaperPreset: String = "Cinematic Smoke"
    @AppStorage("dynamicMainGridWallpaperCustomEnabledV1") private var dynamicMainGridWallpaperCustomEnabled: Bool = false
