    @AppStorage("liveTVGridFocusRingMotionV1") private var liveTVGridFocusRingMotion: String = "Classic Glow"
    @AppStorage("liveTVCardArtworkStyle") private var liveTVCardArtworkStyle: String = "frosted"
    @AppStorage("liveTVAnimatedHeaderLogoEnabledV1") private var liveTVAnimatedHeaderLogoEnabled: Bool = true
    @AppStorage("liveTVAnimatedHeaderLogoStyleV1") private var liveTVAnimatedHeaderLogoStyle: String = "Signal TV"
    @AppStorage("liveTVChannelNumberPositionV1") private var liveTVChannelNumberPosition: String = "Top Right"
    @AppStorage("liveTVGridLayoutStyleV1") private var liveTVGridLayoutStyle: String = "Current"
    @AppStorage("liveTVDashboardStyleV348") private var liveTVDashboardStyle: String = "Golden"
    @AppStorage("liveTVPreviewMirrorShowTopMenuV350") private var mirrorShowTopMenu: Bool = false
    @AppStorage("signalLiveTVCardThemeV342") private var signalLiveTVCardTheme: String = "Original UNITY"
    @AppStorage("signalLiveTVCardEffectV344") private var signalLiveTVCardEffect: String = "Dual Inward"
    @AppStorage("signalLiveTVCardSizeV344") private var signalLiveTVCardSize: String = "Standard"
    @AppStorage("signalLiveTVCardTypographyV346") private var signalLiveTVCardTypography: String = "UNITY Original"
    @AppStorage("liveTVLastSelectedChannelID") private var liveTVLastSelectedChannelID: Int = 0

    @State private var selectedCategory: String = "All"
    @State private var selectedChannelID: Int = 6003
    // vBRDC225: Grid and Guide are the two user-facing renderers over one persistent LiveTVSourceModel.
    // Switching presentation never reloads the lineup/guide or recreates provider state.
    @State private var liveTVBrowseMode: LiveTVBrowseMode = .grid
    @State private var showGuide: Bool = false
    @State private var guideCategoryMenuVisible: Bool = false
    // vBRDC291: Guide opens with the category rail owning focus. Moving right collapses
    // the rail and lets the EPG reclaim that width; moving left from the guide expands it.
    @State private var guideCategoryRailCollapsed: Bool = false
    @FocusState private var liveTVBrowseModeChipFocused: Bool
    private enum MirrorFooterTarget: Hashable { case categories, guide, options }
    @FocusState private var mirrorFooterFocus: MirrorFooterTarget?
    @State private var mirrorCategoriesVisible: Bool = false
    @FocusState private var mirrorCategoryFocus: String?
    @FocusState private var guideCategoryChipFocused: Bool
    @FocusState private var guideCategoryMenuFocus: Int?
    // vBRDC310: source-of-truth for a category -> timeline handoff. Native tvOS may move
    // focus to a valid channel before a child onMoveCommand fires, so keep the last focused
    // category index separately and resolve the destination from focus-state math instead.
    @State private var guideCategoryHandoffSourceIndex: Int?
    @FocusState private var categoryFocus: String?
    @FocusState private var tileFocus: Int?
    // visionOS gaze is the selected card identity, not merely a decorative hover.
    @State private var visionGazeChannelID: Int? = nil
    @FocusState private var guideFocus: Int?
    @State private var lastDpadMoveAt: Date = .distantPast
    @State private var lastSelectAt: Date = .distantPast
    // vBRDC169: Dynamic Live TV Wallpaper is independent of Live TV navigation/scroll bursts.
    // LiveTVScreen still does not subscribe the Gracenote grid to animation revisions; only
    // the full-screen wallpaper plane advances continuously while Live TV owns the surface.
    @State private var rightEdgeGuideArmedTileID: Int? = nil
    @State private var leftEdgePanelArmedTileID: Int? = nil
    @State private var leftEdgePanelArmedAt: Date = .distantPast
