    @State private var liveTVGridPageIndex: Int = 0
    private let liveTVGridPageSize: Int = 12
    @State private var liveTVGuideDockOriginChannelID: Int? = nil
    @State private var guideExitLeftArmedAt: Date = .distantPast
    @State private var quickWindowVisible: Bool = false
    @State private var quickPanelOpenAtCategory: Bool = false
    @State private var quickWindowHideToken: Int = 0
    // vBRDC124: visible Live TV focus is held independently from tvOS FocusState while a
    // menu/catalog handoff is moving. This prevents the selected card from shrinking under
