    @State private var liveTVVisualFocusPinned: Bool = false
    @StateObject private var liveTVAsyncRuntime = LiveTVScreenAsyncTaskRuntime()
    private var liveTVFocusHandoffTask: Task<Void, Never>? {
            get { liveTVAsyncRuntime.liveTVFocusHandoffTask }
            nonmutating set { liveTVAsyncRuntime.liveTVFocusHandoffTask = newValue }
        }
    @State private var liveTVSurfaceFocusHandoffActive: Bool = false
    @State private var quickWindowFocusHandoffActive: Bool = false
    @State private var lastObservedLiveTVTab: AppTab = .live
    @State private var previewChannelID: Int? = nil
    @State private var previewPlaybackSuppressed: Bool = false
    // vBRDC105: Live TV grid preview is a one-shot focus session, never a polling owner.
    // One card must remain focused for 3.0 seconds before the player exists; it is then
    // allowed to live for the user-selected wall-clock duration and is destroyed on any focus/surface edge.
    @State private var gridFocusPreviewChannelID: Int? = nil
    @StateObject private var gridInteractionRuntime = LiveTVGridInteractionRuntime()
    // v1172: keep only 24 rows (96 focusable cards) mounted around focus. The old
    // 240-card window gave the tvOS Focus Engine 60 rows to maintain even though only a
