    private enum LiveTVBrowseMode: String, CaseIterable, Hashable {
        case grid = "Grid"
        case carousel = "Carousel"
        case list = "List"
        case epg = "Guide"

        var systemImage: String {
            switch self {
            case .grid: return "square.grid.2x2.fill"
            case .carousel: return "rectangle.3.group.fill"
            case .list: return "list.bullet.rectangle.portrait.fill"
            case .epg: return "rectangle.grid.1x2.fill"
            }
        }

        var next: LiveTVBrowseMode {
            switch self {
            case .grid: return .epg
            case .epg: return .grid
            // Retired renderers remain compiled only for rollback safety; they are no longer
            // reachable from the Live TV mode selector.
            case .carousel, .list: return .grid
            }
        }
    }

    private enum LiveTVChannelActionFocus: Hashable {
        case favorite
        case sports
    }

    private var currentLiveTVBrowseMode: LiveTVBrowseMode {
        showGuide ? .epg : liveTVBrowseMode
    }

    private var categories: [String] {
        var result = baseCategories
        var seen = Set(baseCategories)
        for category in liveModel.browseCategoryNames() where category != "Movies" {
            if seen.insert(category).inserted { result.append(category) }
        }
        return result
    }

    private var myFavoriteChannelIDs: Set<Int> {
        Set(myFavoriteChannelIdsRaw.split(separator: ",").compactMap { Int($0.trimmingCharacters(in: .whitespacesAndNewlines)) })
    }

    private var sportsAssignedGroups: Set<String> {
        Set(sportsAssignedGroupsRaw.split(separator: "|").map { String($0).trimmingCharacters(in: .whitespacesAndNewlines) }.filter { !$0.isEmpty })
    }

    private var sportsManualChannelIDs: Set<Int> {
        Set(sportsManualChannelIdsRaw.split(separator: ",").compactMap { Int($0.trimmingCharacters(in: .whitespacesAndNewlines)) })
    }

    private var visibleChannels: [LiveTVChannel] {
        if selectedCategory == "All" { return liveModel.channels }
        if selectedCategory == "My Favorites" { return liveModel.browseFavoriteChannels(ids: myFavoriteChannelIDs) }
        if selectedCategory == "HD" { return liveModel.browseHDChannels() }
        return liveModel.browseChannels(inExactCategory: selectedCategory)
    }

    private var renderedChannels: [LiveTVChannel] {
        // v331: keep the tvOS Focus Engine away from thousands of focusable grid cells.
        // vBRDC003: the moving window is row-aligned. The old arbitrary index start could
        // turn (for example) absolute index 29 from column 2 into column 1 after a recenter,
        // changing vertical focus neighbors underneath an active D-pad move.
        let source = visibleChannels
        guard source.count > renderedChannelLimit else { return source }
        let start = alignedLiveTVWindowStart(renderedWindowStart, sourceCount: source.count)
        let end = min(source.count, start + renderedChannelLimit)
        return Array(source[start..<end])
    }

    private func maximumAlignedLiveTVWindowStart(sourceCount: Int) -> Int {
        guard sourceCount > renderedChannelLimit else { return 0 }
        let rawMaximum = max(0, sourceCount - renderedChannelLimit)
        // Round UP to a complete row at the tail. A slightly shorter final window is safer
        // than dropping the last one-to-three channels or breaking column identity.
        return ((rawMaximum + liveTVGridColumnCount - 1) / liveTVGridColumnCount) * liveTVGridColumnCount
    }

    private func alignedLiveTVWindowStart(_ proposed: Int, sourceCount: Int) -> Int {
        guard sourceCount > renderedChannelLimit else { return 0 }
        let maximum = maximumAlignedLiveTVWindowStart(sourceCount: sourceCount)
        let clamped = min(max(proposed, 0), maximum)
        return (clamped / liveTVGridColumnCount) * liveTVGridColumnCount
    }

    private func liveTVVirtualGridMetrics(rowSpacing: CGFloat, cardHeight: CGFloat) -> (top: CGFloat, bottom: CGFloat) {
        let sourceCount = visibleChannels.count
        guard sourceCount > renderedChannelLimit else { return (0, 0) }
        let start = alignedLiveTVWindowStart(renderedWindowStart, sourceCount: sourceCount)
        let renderedCount = min(renderedChannelLimit, max(0, sourceCount - start))
        let topRows = start / liveTVGridColumnCount
        let renderedRows = (renderedCount + liveTVGridColumnCount - 1) / liveTVGridColumnCount
        let totalRows = (sourceCount + liveTVGridColumnCount - 1) / liveTVGridColumnCount
        let bottomRows = max(0, totalRows - topRows - renderedRows)
        let stride = cardHeight + rowSpacing
        return (CGFloat(topRows) * stride, CGFloat(bottomRows) * stride)
    }

    private func visibleChannelIndex(for channelID: Int) -> Int? {
        if selectedCategory == "My Favorites" {
            return visibleChannels.firstIndex(where: { $0.id == channelID })
        }
        return liveModel.browsePosition(of: channelID, category: selectedCategory)
    }

    private var selectedChannel: LiveTVChannel {
        liveModel.channel(id: selectedChannelID) ?? liveModel.channels.first ?? LiveTVScreen.sampleChannels[0]
    }

    private var previewChannel: LiveTVChannel {
        previewChannelID.flatMap { liveModel.channel(id: $0) } ?? selectedChannel
    }

    private var liveTVGridPageCount: Int {
        max(1, (visibleChannels.count + liveTVGridPageSize - 1) / liveTVGridPageSize)
    }

    private var normalizedLiveTVGridPageIndex: Int {
        min(max(0, liveTVGridPageIndex), max(0, liveTVGridPageCount - 1))
    }

    private var liveTVGridPageChannels: [LiveTVChannel] {
        let source = visibleChannels
        guard !source.isEmpty else { return [] }
        let lower = min(source.count, normalizedLiveTVGridPageIndex * liveTVGridPageSize)
        let upper = min(source.count, lower + liveTVGridPageSize)
        guard lower < upper else { return [] }
        return Array(source[lower..<upper])
    }

    private func liveTVGridPage(for channelID: Int) -> Int {
        guard let index = visibleChannelIndex(for: channelID) else { return 0 }
        return min(max(0, index / liveTVGridPageSize), max(0, liveTVGridPageCount - 1))
    }

    private func liveTVGridLocalIndex(for channelID: Int) -> Int? {
        guard let absolute = visibleChannelIndex(for: channelID) else { return nil }
        let local = absolute - (normalizedLiveTVGridPageIndex * liveTVGridPageSize)
        guard local >= 0, local < liveTVGridPageSize else { return nil }
        return local
    }

    private var isFocusedTileLastBoxInRow: Bool {
        let focused = tileFocus ?? selectedChannelID
        guard let index = liveTVGridLocalIndex(for: focused) else { return false }
        return ((index + 1) % liveTVGridColumnCount == 0) || index == liveTVGridPageChannels.count - 1
    }

    private var isFocusedTileFirstBoxInRow: Bool {
        let focused = tileFocus ?? selectedChannelID
        guard let index = liveTVGridLocalIndex(for: focused) else { return false }
        return index % liveTVGridColumnCount == 0
    }

    private var isFocusedTileBottomRow: Bool {
        let focused = tileFocus ?? selectedChannelID
        guard let index = liveTVGridLocalIndex(for: focused), !liveTVGridPageChannels.isEmpty else { return false }
        return (index / liveTVGridColumnCount) == ((liveTVGridPageChannels.count - 1) / liveTVGridColumnCount)
    }

    private var isFocusedTileTopRow: Bool {
        let focused = tileFocus ?? selectedChannelID
        return isLiveTVTileTopRow(channelID: focused)
    }

    // vBRDC251: edge routing must use the actual card that received the Siri Remote move,
    // never the previous @FocusState/@State snapshot. During a fast UP repeat tvOS can deliver
    // the card's onMoveCommand before tileFocus/selectedChannelID publish their next value; the
    // old global math could therefore think row 2 was already row 1 and jump straight to the
    // Grid/List/EPG chip. These helpers make row/column ownership deterministic from channel ID.
    private func isLiveTVTileTopRow(channelID: Int) -> Bool {
        if liveTVBrowseMode == .carousel { return true }
        if liveTVBrowseMode == .list {
            guard let index = visibleChannelIndex(for: channelID) else { return false }
            return index == 0
        }
        guard let index = liveTVGridLocalIndex(for: channelID) else { return false }
        return index / max(1, liveTVGridColumnCount) == 0
    }

    private func isLiveTVTileBottomRow(channelID: Int) -> Bool {
        guard let index = liveTVGridLocalIndex(for: channelID), !liveTVGridPageChannels.isEmpty else { return false }
        return (index / liveTVGridColumnCount) == ((liveTVGridPageChannels.count - 1) / liveTVGridColumnCount)
    }

    private func isLiveTVTileFirstBoxInRow(channelID: Int) -> Bool {
        guard let index = liveTVGridLocalIndex(for: channelID) else { return false }
        return index % liveTVGridColumnCount == 0
    }

    private func isLiveTVTileLastBoxInRow(channelID: Int) -> Bool {
        guard let index = liveTVGridLocalIndex(for: channelID) else { return false }
        return ((index + 1) % liveTVGridColumnCount == 0) || index == liveTVGridPageChannels.count - 1
    }

    var body: some View {
        GeometryReader { geo in
            ZStack(alignment: .topLeading) {
                liveBackground(channel: selectedChannel)

                // vBRDC170: the dynamic wallpaper is a dedicated full-geometry Live TV GRID
                // plane. It is intentionally mounted outside the deck so the Canvas/video/GIF
                // receives the full television dimensions instead of an intrinsic card/deck
                // proposal. Guide owns its own calmer background and never mounts this plane.
                if liveWallpaperOwnsRenderBudget {
                    LiveTVUnityDynamicWallpaperSurface(
                        builtInStyle: dynamicMainGridWallpaperPreset,
                        performanceMode: visualPerformanceMode,
                        customEnabled: dynamicMainGridWallpaperCustomEnabled,
                        customURL: dynamicMainGridWallpaperCustomURL
                    )
                    .frame(width: geo.size.width, height: geo.size.height)
                    .opacity(0.96)
                    .overlay(
                        LinearGradient(
                            colors: [Color.black.opacity(0.02), Color.clear, Color.black.opacity(0.08)],
                            startPoint: .top,
                            endPoint: .bottom
                        )
                    )
                    .ignoresSafeArea()
                    .allowsHitTesting(false)
                    .zIndex(0)
                }

                // v983: observe the tvOS Select press at the window level while a
                // Live TV grid tile owns focus. SwiftUI's simultaneous long-press
                // gesture was not consistently delivered by the tvOS focus engine,
                // so the Favorites/Sports panel could fail to appear entirely.
                LiveTVSelectHoldMonitor(
                    minimumDuration: 0.32,
                    isEnabled: !showGuide
                        && !quickWindowVisible
                        && channelActionChannelID == nil
                        && tileFocus != nil,
                    onRecognized: {
                        guard let focusedID = tileFocus,
                              liveTVLongPressFiredChannelID != focusedID,
                              let channel = liveModel.channel(id: focusedID) else { return }
                        liveTVLongPressFiredChannelID = focusedID
                        suppressChannelTap(for: focusedID)
                        presentLiveTVChannelActions(for: channel)
                        print("[LiveTVActions][v983] window Select hold channel=\(focusedID)")
                    },
                    onEnded: {
                        liveTVLongPressFiredChannelID = nil
                    }
                )
                .frame(width: 1, height: 1)
                .opacity(0.001)
                .allowsHitTesting(false)

                // vBRDC230: Grid and Guide share one persistent Live TV browse tree; retired List/Carousel code is unreachable.
                // The shared broadcast header (including the mode chip) never remounts or moves
                // when the presentation changes. Only the content lane beneath it changes.
                // This also removes the old Guide-specific outer geometry/popup feel and keeps
                // Current/Spread Out on the exact same top/focus plane.
                liveTVUnifiedBrowseSurface(size: geo.size)
                    // vBRDC292: Guide is a full-canvas TV surface. Keep the ordinary
                    // Grid safe margins, but let Guide reclaim the television width;
                    // interactive labels remain inset inside the Guide itself.
                    .padding(.leading, showGuide ? 8 : (mirrorDashboardActive ? 40 : (gridLockedMode ? 398 : (appCanvasExpanded ? 52 : 72))))
                    .padding(.trailing, showGuide ? 8 : (mirrorDashboardActive ? 40 : (appCanvasExpanded ? 46 : 76)))
                    .padding(.top, showGuide ? 106 : (mirrorDashboardActive ? 50 : (gridLockedMode ? 92 : (appCanvasExpanded ? 104 : 132))))
                // vBRDC124: the Live TV grid itself never participates in the left-panel
                // animation transaction. Only the panel moves; the selected card is visually
                // pinned and the grid remains frozen until real focus ownership is rebound.
                .disabled(quickWindowVisible || quickWindowFocusHandoffActive || mirrorCategoriesVisible || channelActionChannelID != nil)
                .allowsHitTesting(!quickWindowVisible && !quickWindowFocusHandoffActive && !mirrorCategoriesVisible && channelActionChannelID == nil)

                // Golden retains its original left tool rail. In Preview Mirror the
                // rail is NOT mounted, and category selection is a separate right popup.
                if !mirrorDashboardActive {
                    gridQuickControlWindow(size: geo.size)
                        .offset(x: (quickWindowVisible || gridLockedMode) && !showGuide ? 0 : -390)
                        .opacity((quickWindowVisible || gridLockedMode) && !showGuide ? 1.0 : 0.0)
                        .allowsHitTesting(quickWindowVisible && !quickWindowFocusHandoffActive && !showGuide)
                        .animation(.spring(response: 0.42, dampingFraction: 0.86), value: gridLockedMode)
                        .zIndex(1800)
                }

                if mirrorDashboardActive && mirrorCategoriesVisible {
                    Color.black.opacity(0.56)
                        .ignoresSafeArea()
                        .allowsHitTesting(true)
                        .zIndex(2000)
                    VStack {
                        Spacer(minLength: 0)
                        HStack {
                            Spacer(minLength: 0)
                            mirrorCategoriesPanel
                        }
                        .padding(.trailing, 50)
                        .padding(.bottom, 87)
                    }
                    .frame(width: geo.size.width, height: geo.size.height)
                    .zIndex(2100)
                }

                if !showGuide, gridLockedMode {
                    gridLockedCatalogDock(size: geo.size)
                        .allowsHitTesting(store.selectedTab == .home || store.selectedTab == .movies || store.selectedTab == .shows)
                        .transition(.move(edge: .bottom).combined(with: .opacity))
                        .zIndex(1200)
                }

                if let actionChannelID = channelActionChannelID,
                   let actionChannel = liveModel.channel(id: actionChannelID) {
                    liveTVChannelActionOverlay(channel: actionChannel)
                        .transition(.opacity.combined(with: .scale(scale: 0.98)))
                        .zIndex(5000)
                }

                if liveModel.isLoading {
                    ProgressView()
                        .tint(.white)
                        .position(x: geo.size.width - 120, y: 92)
                }

            }
            .frame(width: geo.size.width, height: geo.size.height)
            .signalVisionFocusSection()
            .onAppear {
                synchronizeUnityGuideAnimationActivity(reason: "Live TV appear")
                lastObservedLiveTVTab = store.selectedTab
                gridLockedModeStored = false
                // UNITY: RootView retains this exact visual instance behind non-playback
                // surfaces. Never mutate selectedTab from onAppear; dedicated tabs are valid
                // cover owners and must not be bounced back into Live TV.
                liveModel.loadCachedOrDemo()
                // vBRDC142: movie/show playback destroys this persistent Live TV root just like
                // Live TV playback does, but it has no LiveTVFocusSnapshot to drive the dedicated
                // channel-return lane. Consume one store-owned VOD-return generation here so the
                // newly mounted grid gets its bounded Gracenote + native channel-logo corridor
                // back even when Movies/Shows still covers it. Normal covered startup remains
                // completely quiescent, and no provider/XMLTV refresh is started by this path.
                let postVODRecoveryGeneration = store.liveTVPostVODArtworkRecoveryGeneration
                let recoveringArtworkAfterVOD = postVODRecoveryGeneration > store.liveTVPostVODArtworkRecoveryConsumedGeneration
                if recoveringArtworkAfterVOD {
                    store.liveTVPostVODArtworkRecoveryConsumedGeneration = postVODRecoveryGeneration
                }
                let restoringFromPlayback = !recoveringArtworkAfterVOD && store.playbackURL == nil && store.liveTVFocusSnapshot != nil
                // vBRDC105: a Live TV playback return must bind the saved channel before any
                // artwork bootstrap/guide refresh work is allowed to publish. A VOD return uses
                // the separate bounded corridor above so Gracenote/channel identity is warm before
                // the retained grid is exposed again. Cold/non-playback mounts keep the existing
                // readiness behavior.
                if recoveringArtworkAfterVOD {
                    beginForcedLiveTVArtworkBootstrap(reason: "movie/show playback return")
                } else if !restoringFromPlayback, store.selectedTab == .live {
                    // vBRDC139: ordinary persistent-root mounts underneath a catalog stay dark.
                    // Only an actual post-VOD remount gets the bounded exception above.
                    beginForcedLiveTVArtworkBootstrap(reason: "Live TV root mounted active")
                }
                // vBRDC098: a real provider lineup does not use the demo channel ID 6003.
                // Repair the selection immediately after the cached/session lineup is published
                // so the initial artwork corridor has a real anchor before the user moves focus.
                synchronizeLiveTVSelectionWithPublishedLineup(reason: "grid appear lineup")
                // vBRDC140: do not start provider/Gracenote work under Home/Movies/Shows.
                // The selected-tab entry path starts the authoritative refresh as soon as Live TV
                // owns the surface; hidden startup work was competing with catalog focus/rendering.
                liveTVMountGeneration &+= 1
                if !restoringFromPlayback { scheduleLiveTVScheduleBoundaryRefresh(reason: "grid appear") }
                let liveOwnsInitialFocus = !restoringFromPlayback && store.selectedTab == .live
                categoryFocus = liveOwnsInitialFocus ? selectedCategory : nil
                tileFocus = liveOwnsInitialFocus ? selectedChannelID : nil
                guideFocus = nil
                quickWindowVisible = false
                quickWindowFocusHandoffActive = false
                liveTVSurfaceFocusHandoffActive = false
                    liveTVGuideDockOriginChannelID = nil
                liveTVVisualFocusPinned = false
                channelActionChannelID = nil
                channelActionFocus = nil
                store.liveQuickPanelOpen = false
                quickPanelFocus = false
                leftEdgePanelArmedTileID = nil
                leftEdgePanelArmedAt = .distantPast
                leftEdgePanelArmCount = 0
                previewChannelID = nil
                previewPlaybackSuppressed = restoringFromPlayback
                if let snapshot = store.liveTVFocusSnapshot, restoringFromPlayback {
                    selectedCategory = categories.contains(snapshot.categoryID) ? snapshot.categoryID : "All"
                    selectedChannelID = snapshot.playedChannelID
                    renderedWindowStart = alignedLiveTVWindowStart(snapshot.renderedWindowStart, sourceCount: visibleChannels.count)
                    liveTVGridPageIndex = liveTVGridPage(for: selectedChannelID)
                } else {
                    resetVirtualChannelWindow(to: selectedChannelID)
                    liveTVGridPageIndex = liveTVGridPage(for: selectedChannelID)
                }
                consumeGuideStartupRequestIfNeeded()
                if restoringFromPlayback {
                    scheduleLiveTVFocusRestore(reason: "grid mounted with pending snapshot")
                } else {
                    startLiveTVRefreshIfActive(reason: "grid appear")
                }
            }
            .onChange(of: store.guideStartupRequestToken) { _ in
                consumeGuideStartupRequestIfNeeded()
            }
            .onChange(of: scenePhase) { phase in
                if phase != .active {
                    liveGuideRecoveryTask?.cancel()
                    liveGuideRecoveryTask = nil
                    gridInteractionRuntime.artworkPrefetchTask?.cancel()
                    gridInteractionRuntime.artworkPrefetchTask = nil
                    gridInteractionRuntime.guidePreviewWarmupTask?.cancel()
                    gridInteractionRuntime.guidePreviewWarmupTask = nil
                    cancelLiveTVGridFocusPreview()
                    LiveTVBoundedArtworkLoader.suspendForCoveredSurface(reason: "scene inactive")
                    return
                }
                guard store.playbackURL == nil, !VODExclusivePlaybackGate.isActive else { return }
                // vBRDC139: returning from the tvOS app switcher can leave mounted artwork
                // owners with cancelled requests or a tile-local failed URL from the previous
                // network generation. Re-arm the exact retained owners immediately. If Live TV
                // is the active surface, its ordinary refreshIfNeeded lane performs any due
                // provider validation; covered catalogs receive zero hidden decoder/network work.
                if store.selectedTab == .live {
                    LiveTVBoundedArtworkLoader.resumeRetainedRequests()
                    liveTVArtworkRefreshToken &+= 1
                    synchronizeLiveTVSelectionWithPublishedLineup(reason: "scene active")
                    beginForcedLiveTVArtworkBootstrap(reason: "scene active")
                    startLiveTVRefreshIfActive(reason: "scene active")
                    armPersistentGuideRecovery(reason: "scene active")
                } else {
                    // Covered catalogs stay fully quiescent. The selected-tab entry path
                    // performs provider validation + artwork re-arm when Live TV becomes active.
                }
            }
            .onChange(of: store.onboardingForceFullGuide) { value in
                guard store.onboardingTourActive else { return }
                    liveTVGuideDockOriginChannelID = nil
                guideExitLeftArmedAt = .distantPast
                liveTVBrowseMode = value ? .epg : .grid
                withAnimation(.spring(response: 0.36, dampingFraction: 0.86)) {
                    showGuide = value
                    quickWindowVisible = false
                    store.liveQuickPanelOpen = false
                    guideFocus = selectedChannelID
                    tileFocus = selectedChannelID
                    rightEdgeGuideArmedTileID = nil
                    leftEdgePanelArmedTileID = nil
                    leftEdgePanelArmedAt = .distantPast
                    leftEdgePanelArmCount = 0
                }
                if value { scheduleLivePreviewWarmup(immediate: true) }
            }
            .onDisappear {
                unityAnimations.setGuideActive(false)
                guideHintHideTask?.cancel()
                liveRefreshTask?.cancel()
                liveGuideRecoveryTask?.cancel()
                liveGuideRecoveryTask = nil
                liveTVForcedArtworkBootstrapTask?.cancel()
                liveTVForcedArtworkBootstrapTask = nil
                liveTVForcedArtworkBootstrapActive = false
                liveTVVisibilityResumeTask?.cancel()
                liveTVVisibilityResumeTask = nil
                liveTVFocusHandoffTask?.cancel()
                liveTVFocusHandoffTask = nil
                liveTVSurfaceFocusHandoffActive = false
                quickWindowFocusHandoffActive = false
                liveTVVisualFocusPinned = false
                liveTVCoveredCompactionTask?.cancel()
                liveTVCoveredCompactionTask = nil
                liveForceRefreshTask?.cancel()
                liveTVFocusRestoreTask?.cancel()
                liveTVFocusRestoreTask = nil
                liveTVScheduleBoundaryTask?.cancel()
                liveTVScheduleBoundaryTask = nil
                gridInteractionRuntime.artworkPrefetchTask?.cancel()
                gridInteractionRuntime.artworkPrefetchTask = nil
                gridInteractionRuntime.selectionPersistenceTask?.cancel()
                gridInteractionRuntime.selectionPersistenceTask = nil
                gridInteractionRuntime.windowMaintenanceTask?.cancel()
                gridInteractionRuntime.windowMaintenanceTask = nil
                cancelLiveTVGridFocusPreview()
                if liveTVLastSelectedChannelID != selectedChannelID {
                    liveTVLastSelectedChannelID = selectedChannelID
                }
                LiveTVBoundedArtworkLoader.cancelObsoletePrefetches(keeping: [])
                channelActionChannelID = nil
                channelActionFocus = nil
                liveTVRestoreScrollChannelID = nil
                liveTVRestoreScrollReadyChannelID = nil
                liveTVRestoreMaterializedChannelID = nil
                liveTVLongPressFiredChannelID = nil
                liveModel.suspendForVODPlayback()
            }
            .signalMoveCommand { direction in
                routeLiveSpecialMove(direction)
            }
            .onChange(of: liveTVDashboardStyle) { _ in
                // A layout change cannot retain an offscreen category popup or
                // resurrect a Golden Quick Guide beneath the Mirror footer.
                mirrorCategoriesVisible = false
                mirrorCategoryFocus = nil
                mirrorFooterFocus = nil
                if quickWindowVisible { quickWindowVisible = false; store.liveQuickPanelOpen = false }
            }
            .onChange(of: store.selectedTab) { tab in
                if tab != .live {
                    mirrorCategoriesVisible = false
                    mirrorCategoryFocus = nil
                    mirrorFooterFocus = nil
                }
            }
            .onChange(of: unityCore.topNavigationSession) { _, _ in
                guard unityCore.topNavigationActive,
                      store.selectedTab == .live,
                      store.playbackURL == nil,
                      !showGuide,
                      !quickWindowVisible,
                      channelActionChannelID == nil else { return }
                // vBRDC182: the persistent UNITY shell publishes one shared top-navigation
                // session instead of posting an ad-hoc notification. Live TV can quiesce its
                // auxiliary decoder/prefetch work without any cross-tree focus forcing.
                cancelLiveTVGridFocusPreview()
                gridInteractionRuntime.artworkPrefetchTask?.cancel()
                gridInteractionRuntime.artworkPrefetchTask = nil
                var transaction = Transaction()
                transaction.disablesAnimations = true
                withTransaction(transaction) {
                    liveTVVisualFocusPinned = false
                }
            }
            .onChange(of: selectedChannelID) { value in
                scheduleLiveTVSelectionPersistence(value)
                // vBRDC225: Guide and List both use the bounded 96-channel virtual corridor.
                // Grid remains the fixed 12-card page and therefore needs no corridor maintenance.
                if showGuide {
                    scheduleLiveTVVirtualWindowMaintenance(focusedID: value)
                    scheduleLivePreviewWarmup()
                } else if liveTVBrowseMode == .list || liveTVBrowseMode == .carousel {
                    scheduleLiveTVVirtualWindowMaintenance(focusedID: value)
                } else {
                    gridInteractionRuntime.windowMaintenanceTask?.cancel()
                    gridInteractionRuntime.windowMaintenanceTask = nil
                }
            }
            .onChange(of: renderedWindowStart) { _ in
                // The program-boundary timer depends on the rendered 96-card window, not on
                // every individual focus step inside that same window.
                scheduleLiveTVScheduleBoundaryRefresh(reason: "render window changed")
            }
            .onChange(of: tileFocus) { value in
                guard value == selectedChannelID,
                      store.selectedTab == .live,
                      !quickWindowVisible,
                      !quickWindowFocusHandoffActive,
                      !liveTVSurfaceFocusHandoffActive,
                      liveTVVisualFocusPinned else { return }
                // Real FocusState and visual focus now describe the same card. Drop the
                // temporary visual pin without animating; `isFocused` remains true throughout.
                var transaction = Transaction()
                transaction.disablesAnimations = true
                withTransaction(transaction) { liveTVVisualFocusPinned = false }
            }
            .onChange(of: guideCategoryMenuFocus) { value in
                guard showGuide, let value else { return }
                guideCategoryHandoffSourceIndex = value
            }
            .onChange(of: guideFocus) { value in
                guard showGuide, let value else { return }

                // vBRDC310: do not depend on category-row onMoveCommand to collapse the rail.
                // When tvOS finds a valid focus target to the right it can transfer focus
                // directly, which means the child move handler is never called. Detect that
                // source->destination ownership transition here and remap the channel by row.
                if !guideCategoryRailCollapsed,
                   let sourceIndex = guideCategoryHandoffSourceIndex,
                   handoffGuideCategoryToTimeline(categoryIndex: sourceIndex, nativeFocusedChannelID: value) {
                    return
                }

                unityAnimations.registerNavigationActivity(source: "live-guide")
                gridInteractionRuntime.guideSelectionCommitTask?.cancel()
                gridInteractionRuntime.guideSelectionCommitTask = Task { @MainActor in
                    // Keep native focus immediate, but defer hero metadata/decoder/cache work
                    // until the remote has been still for a fraction of a second.
                    try? await Task.sleep(nanoseconds: 300_000_000)
                    guard !Task.isCancelled, showGuide, guideFocus == value else { return }
                    var transaction = Transaction()
                    transaction.disablesAnimations = true
                    withTransaction(transaction) { selectedChannelID = value }
                    gridInteractionRuntime.guideSelectionCommitTask = nil
                }
            }
            .onChange(of: showGuide) { value in
                if value {
                    if liveTVBrowseMode != .epg { liveTVBrowseMode = .epg }
                } else if liveTVBrowseMode == .epg {
                    liveTVBrowseMode = .grid
                }
                // vBRDC090: one observer owns the guide visibility edge. The donor had two
                // separate handlers for the same value, creating duplicate body callbacks on
                // every guide transition.
                synchronizeUnityGuideAnimationActivity(reason: "guide visibility")
                if value {
                    cancelLiveTVGridFocusPreview()
                    scheduleGuideExitHintAutoHide()
                    if !previewPlaybackSuppressed { scheduleLivePreviewWarmup(immediate: true) }
                } else {
                    guideExitHintHideTask?.cancel()
                    guideExitHintHideTask = nil
                    guideExitHintVisible = false
                    guideStartupOpen = false
                    guideExitLeftArmedAt = .distantPast
                    liveTVGridPageIndex = liveTVGridPage(for: selectedChannelID)
                    gridInteractionRuntime.guidePreviewWarmupGeneration &+= 1
                    previewChannelID = nil
                    if let focusedID = tileFocus { scheduleLiveTVGridFocusPreview(for: focusedID) }
                }
            }
            .onChange(of: store.liveQuickPanelOpen) { open in
                if open { cancelLiveTVGridFocusPreview() }
            }
            .onChange(of: channelActionChannelID) { actionID in
                if actionID != nil {
                    cancelLiveTVGridFocusPreview()
                } else if !showGuide, let focusedID = tileFocus {
                    scheduleLiveTVGridFocusPreview(for: focusedID)
                }
            }
            .onChange(of: liveTVGridFocusPreviewEnabled) { enabled in
                if enabled, !showGuide, let focusedID = tileFocus {
                    scheduleLiveTVGridFocusPreview(for: focusedID)
                } else {
                    cancelLiveTVGridFocusPreview()
                }
            }
            .onChange(of: unityCore.activeTab) { tab in
                let previousTab = lastObservedLiveTVTab
                lastObservedLiveTVTab = tab
                stageLiveTVSurfaceFocusHandoff(from: previousTab, to: tab)
                liveTVVisibilityResumeTask?.cancel()
                liveTVVisibilityResumeTask = nil
                liveTVCoveredCompactionTask?.cancel()
                liveTVCoveredCompactionTask = nil
                if tab != .live {
                    gridInteractionRuntime.windowMaintenanceTask?.cancel()
                    gridInteractionRuntime.windowMaintenanceTask = nil
                    cancelLiveTVGridFocusPreview()
                }
                if tab == .live {
                    // vBRDC098: Live can be entered after the persistent root was initialized
                    // under Home/Settings with the demo selection still in State. Canonicalize
                    // against the published real lineup before artwork/focus work is enabled.
                    synchronizeLiveTVSelectionWithPublishedLineup(reason: "Live tab selected")
                    liveTVGridPageIndex = liveTVGridPage(for: selectedChannelID)
                    beginForcedLiveTVArtworkBootstrap(reason: "Live tab selected")
                    // Expand the virtual corridor before the catalog fade exposes the root.
                    // This is a layout-only change behind the still-visible outgoing branch.
                    if renderedChannelLimit != interactiveRenderedChannelLimit {
                        var transaction = Transaction()
                        transaction.animation = nil
                        withTransaction(transaction) {
                            renderedChannelLimit = interactiveRenderedChannelLimit
                            keepFocusedChannelInVirtualWindow()
                        }
                    }
                    // Reveal the persistent root immediately, but delay all nonvisual Live TV
                    // wake-up until the catalog reverse transition and focus handoff are over.
                    liveTVVisibilityResumeTask = Task { @MainActor in
                        try? await Task.sleep(nanoseconds: 390_000_000)
                        guard !Task.isCancelled, store.selectedTab == .live, store.playbackURL == nil else { return }
                        startLiveTVRefreshIfActive(reason: "Live TV handoff settled")
                        scheduleLiveTVScheduleBoundaryRefresh(reason: "Live TV handoff settled")
                        scheduleLiveTVArtworkPrefetch(immediate: true)
                        if !showGuide, let focusedID = tileFocus { scheduleLiveTVGridFocusPreview(for: focusedID) }
                        liveTVVisibilityResumeTask = nil
                    }
                } else {
                    // UNITY: the same LiveTVScreen stays mounted under catalog/dedicated
                    // branches, but only Live TV may own network/EPG/prefetch work.
                    // Covered branches keep the already-decoded pixels without a second model.
                    liveRefreshTask?.cancel()
                    liveRefreshTask = nil
                    liveGuideRecoveryTask?.cancel()
                    liveGuideRecoveryTask = nil
                    liveForceRefreshTask?.cancel()
                    liveForceRefreshTask = nil
                    liveTVScheduleBoundaryTask?.cancel()
                    liveTVScheduleBoundaryTask = nil
                    gridInteractionRuntime.artworkPrefetchTask?.cancel()
                    gridInteractionRuntime.artworkPrefetchTask = nil
                    LiveTVBoundedArtworkLoader.suspendForCoveredSurface(reason: "Live TV tab covered")

                    // Wait until the incoming branch has completely covered the grid, then
                    // shrink only the off-screen virtual corridor. The first visible rows and
                    // their decoded images keep the same view identity and remain mounted.
                    liveTVCoveredCompactionTask = Task { @MainActor in
                        try? await Task.sleep(nanoseconds: 390_000_000)
                        guard !Task.isCancelled,
                              store.selectedTab != .live,
                              store.playbackURL == nil,
                              !VODExclusivePlaybackGate.isActive else { return }
                        if renderedChannelLimit != coveredRenderedChannelLimit {
                            var transaction = Transaction()
                            transaction.animation = nil
                            withTransaction(transaction) {
                                renderedChannelLimit = coveredRenderedChannelLimit
                                keepFocusedChannelInVirtualWindow()
                            }
                            print("[UNITY][vBRDC093] persistent Live TV corridor compacted=\(coveredRenderedChannelLimit) tab=\(store.selectedTab.rawValue)")
                        }
                        liveTVCoveredCompactionTask = nil
                    }
                }
                guard gridLockedMode else { return }
                if tab == .home || tab == .movies || tab == .shows {
                    quickWindowVisible = false
                    store.liveQuickPanelOpen = false
                    tileFocus = nil
                    gridLockedDockRowIndex = 0
                    gridLockedDockFocus = 0
                    gridLockedDockLocked = true
                } else if tab == .live {
                    gridLockedDockFocus = nil
                    gridLockedDockLocked = false
                    tileFocus = selectedChannelID
                }
            }
            .onChange(of: store.liveTVMenuFocusEntryToken) { _ in
                guard store.selectedTab == .live,
                      store.playbackURL == nil,
                      !showGuide,
                      !quickWindowVisible,
                      channelActionChannelID == nil else { return }
                // vBRDC128: Down from the top menu enters the already-mounted native grid.
                // No focusable predicates or persistent ownership locks are involved.
                synchronizeLiveTVSelectionWithPublishedLineup(reason: "top-menu Down")
                liveTVGridPageIndex = liveTVGridPage(for: selectedChannelID)
                var focus = Transaction()
                focus.disablesAnimations = true
                withTransaction(focus) {
                    liveTVVisualFocusPinned = false
                    liveTVSurfaceFocusHandoffActive = false
                    categoryFocus = nil
                    guideFocus = nil
                    tileFocus = selectedChannelID
                }
            }
            .onChange(of: store.liveTVFocusRestoreToken) { _ in
                scheduleLiveTVFocusRestore(reason: "player close token")
            }
            .onChange(of: store.playbackURL) { value in
                guard value == nil else {
                    cancelLiveTVGridFocusPreview()
                    liveTVFocusRestoreTask?.cancel()
                    liveTVFocusRestoreTask = nil
                    return
                }
                // vBRDC099: player dismissal creates a fresh LiveTVScreen root. Force its
                // bounded visual corridor immediately even when Home/Movies/Shows covers it,
                // and do not make a D-pad move the trigger for Gracenote rehydration.
                synchronizeLiveTVSelectionWithPublishedLineup(reason: "playback URL cleared")
                scheduleLiveTVFocusRestore(reason: "playback URL cleared")
            }
        }
        .background(Color.black.ignoresSafeArea())
    }


    private func consumeGuideStartupRequestIfNeeded() {
        let token = store.guideStartupRequestToken
        guard token > 0, token != handledGuideStartupRequestToken else { return }
        handledGuideStartupRequestToken = token
        guideStartupOpen = true
        quickWindowVisible = false
        store.liveQuickPanelOpen = false
        quickPanelFocus = false
        quickPanelItemFocus = nil
        channelActionChannelID = nil
        channelActionFocus = nil
        liveTVGuideDockOriginChannelID = nil
        guideExitLeftArmedAt = .distantPast
        selectedCategory = "All"

        let target = liveModel.channel(id: liveTVLastSelectedChannelID)
            ?? store.liveTVFocusSnapshot.flatMap { liveModel.channel(id: $0.playedChannelID) }
            ?? liveModel.channels.first
        if let target {
            selectedChannelID = target.id
            liveTVLastSelectedChannelID = target.id
            resetVirtualChannelWindow(to: target.id)
            liveTVGridPageIndex = liveTVGridPage(for: target.id)
        }

        categoryFocus = nil
        tileFocus = nil
        liveTVBrowseMode = .epg
        var startupGuideTransaction = Transaction()
        startupGuideTransaction.disablesAnimations = true
        withTransaction(startupGuideTransaction) {
            showGuide = true
            guideFocus = target?.id ?? selectedChannelID
            rightEdgeGuideArmedTileID = nil
            leftEdgePanelArmedTileID = nil
            leftEdgePanelArmedAt = .distantPast
            leftEdgePanelArmCount = 0
        }
        scheduleLivePreviewWarmup(immediate: true)
        print("[GuideStartup][v1082] request consumed channel=\(target?.id ?? selectedChannelID)")
    }

    private func synchronizeUnityGuideAnimationActivity(reason: String) {
        unityAnimations.setGuideActive(showGuide)
        print("[UNITY Animation][Live TV] guide sync reason=\(reason) active=\(showGuide)")
    }

    @MainActor
    private func synchronizeLiveTVSelectionWithPublishedLineup(reason: String) {
        let allChannels = liveModel.channels
        guard !allChannels.isEmpty else { return }

        // Provider lineups use stable hashed/provider IDs, while LiveTVScreen intentionally
        // starts with demo ID 6003 so the view has a safe placeholder before configuration.
        // If that placeholder survives into a real lineup, the old artwork corridor lookup
        // returned an empty Set and no mounted card was allowed to request Gracenote until
        // focus movement supplied a real ID. Keep selection identity valid independently of
        // whether the tvOS Focus Engine has moved yet.
        if !categories.contains(selectedCategory) {
            selectedCategory = "All"
        }

        // vBRDC292: an intentionally selected empty group stays selected instead of
        // snapping back to All Channels. Use the provider lineup only as a hidden identity
        // repair fallback; it never changes the visible category choice.
        let visible = visibleChannels.isEmpty ? allChannels : visibleChannels
        let candidateIDs: [Int?] = [
            selectedChannelID,
            liveTVLastSelectedChannelID > 0 ? liveTVLastSelectedChannelID : nil,
            store.liveTVFocusSnapshot?.playedChannelID,
            store.liveTVFocusSnapshot?.focusedChannelID
        ]
        let target = candidateIDs.compactMap { $0 }.compactMap { id in
            visible.first(where: { $0.id == id })
        }.first ?? visible.first ?? allChannels[0]

        let selectionWasInvalid = !visible.contains(where: { $0.id == selectedChannelID })
        let tileFocusWasInvalid = tileFocus.map { id in !visible.contains(where: { $0.id == id }) } ?? true

        if selectionWasInvalid {
            var transaction = Transaction()
            transaction.animation = nil
            withTransaction(transaction) {
                selectedChannelID = target.id
                resetVirtualChannelWindow(to: target.id)
            }
        } else if !renderedChannels.contains(where: { $0.id == selectedChannelID }) {
            resetVirtualChannelWindow(to: selectedChannelID)
        }

        if liveTVLastSelectedChannelID <= 0 || !allChannels.contains(where: { $0.id == liveTVLastSelectedChannelID }) {
            liveTVLastSelectedChannelID = target.id
        }

        if store.selectedTab == .live,
           store.playbackURL == nil,
           !showGuide,
           !quickWindowVisible,
           channelActionChannelID == nil,
           (selectionWasInvalid || tileFocusWasInvalid) {
            var transaction = Transaction()
            transaction.animation = nil
            withTransaction(transaction) {
                categoryFocus = selectedCategory
                tileFocus = target.id
            }
        }

        if selectionWasInvalid || tileFocusWasInvalid {
            print("[LiveTVBootstrap][vBRDC098] repaired zero-scroll anchor reason=\(reason) channel=\(target.id) lineup=\(allChannels.count)")
        }
    }

    private func scheduleLiveTVSelectionPersistence(_ channelID: Int) {
        gridInteractionRuntime.selectionPersistenceTask?.cancel()
        gridInteractionRuntime.selectionPersistenceTask = Task { @MainActor in
            // vBRDC297: persistence follows settled focus, never the repeat cadence.
            try? await Task.sleep(nanoseconds: 350_000_000)
            guard await UnityFrameRuntime.shared.waitUntilPermittedDurably(.persistence) else { return }
            guard !Task.isCancelled, selectedChannelID == channelID else { return }
            if liveTVLastSelectedChannelID != channelID {
                liveTVLastSelectedChannelID = channelID
            }
            gridInteractionRuntime.selectionPersistenceTask = nil
        }
    }

    private func startLiveTVGuideRecoveryLoopIfNeeded(reason: String) {
        guard store.playbackURL == nil,
              scenePhase == .active,
              !VODExclusivePlaybackGate.isActive,
              liveModel.guideRecoveryRequired else {
            liveGuideRecoveryTask?.cancel()
            liveGuideRecoveryTask = nil
            return
        }
        guard liveGuideRecoveryTask == nil else { return }

        liveGuideRecoveryTask = VODExclusiveWorkRegistry.start {
            // vBRDC203: old Debrid Channels behavior kept trying until guide data existed.
            // Restore that reliability without hammering Gracenote/XMLTV: retries back off
            // to five minutes, keep last-known-good channels visible, and stop immediately
            // when Live TV leaves the foreground or VOD starts.
            let delays: [UInt64] = [10, 30, 60, 120, 300]
            var attempt = 0
            while !Task.isCancelled,
                  store.playbackURL == nil,
                  scenePhase == .active,
                  !VODExclusivePlaybackGate.isActive,
                  liveModel.guideRecoveryRequired {
                let seconds = delays[min(attempt, delays.count - 1)]
                try? await Task.sleep(nanoseconds: seconds * 1_000_000_000)
                guard !Task.isCancelled,
                      store.playbackURL == nil,
                      scenePhase == .active,
                      !VODExclusivePlaybackGate.isActive,
                      liveModel.guideRecoveryRequired else { break }
                await liveModel.retryIncompleteGuideRecovery()
                if !liveModel.guideRecoveryRequired {
                    if store.selectedTab == .live {
                        synchronizeLiveTVSelectionWithPublishedLineup(reason: "guide self-heal")
                        LiveTVBoundedArtworkLoader.resumeRetainedRequests()
                        liveTVArtworkRefreshToken &+= 1
                        scheduleLiveTVArtworkPrefetch(immediate: true)
                        scheduleLiveTVScheduleBoundaryRefresh(reason: "guide self-heal complete")
                    }
                    print("[LiveTVGuideRecovery][vBRDC203] recovered reason=\(reason) attempts=\(attempt + 1)")
                    break
                }
                attempt += 1
            }
            liveGuideRecoveryTask = nil
        }
    }

    private func armPersistentGuideRecovery(reason: String) {
        guard scenePhase == .active,
              store.playbackURL == nil,
              !VODExclusivePlaybackGate.isActive else { return }

        // Restore durable lineup/EPG first. This is async utility-queue IO and does not mount
        // the Live TV surface. If the persisted guide is stale or incomplete, the existing
        // bounded recovery loop continues silently behind Home/Movies/Shows.
        liveRefreshTask?.cancel()
        liveRefreshTask = VODExclusiveWorkRegistry.start {
            await liveModel.refreshIfNeeded()
            guard !Task.isCancelled, !VODExclusivePlaybackGate.isActive else { return }
            startLiveTVGuideRecoveryLoopIfNeeded(reason: reason)
        }
    }

    private func startLiveTVRefreshIfActive(reason: String) {
        guard store.playbackURL == nil,
              store.selectedTab == .live,
              !VODExclusivePlaybackGate.isActive else { return }
        liveRefreshTask?.cancel()
        liveRefreshTask = VODExclusiveWorkRegistry.start {
            await liveModel.refreshIfNeeded()
            // Start guide self-healing before waiting on nonessential focus/selection work.
            // A stale post-sleep interactive lane must never prevent the EPG retry owner from
            // being armed after the provider model itself has returned.
            startLiveTVGuideRecoveryLoopIfNeeded(reason: reason)
            guard await UnityFrameRuntime.shared.waitUntilPermittedDurably(.interactiveMetadata) else { return }
            guard !Task.isCancelled,
                  !VODExclusivePlaybackGate.isActive,
                  store.selectedTab == .live else { return }
            synchronizeLiveTVSelectionWithPublishedLineup(reason: "active refresh publication")
            if guideStartupOpen,
               let preferred = liveModel.channel(id: liveTVLastSelectedChannelID) {
                selectedCategory = "All"
                selectedChannelID = preferred.id
                guideFocus = preferred.id
                tileFocus = nil
            } else if store.liveTVFocusSnapshot == nil,
                      let first = visibleChannels.first,
                      selectedChannelID == LiveTVScreen.sampleChannels[0].id {
                selectedChannelID = first.id
                if showGuide { guideFocus = first.id } else { tileFocus = first.id }
            }
            if store.playbackURL == nil, store.liveTVFocusSnapshot != nil {
                await MainActor.run { scheduleLiveTVFocusRestore(reason: "grid refresh complete") }
            }
            // Wake the exact currently-mounted artwork owners after guide publication.
            // vBRDC137 directly re-arms any blank owner whose previous request was cancelled
            // or failed during process/network startup, then the token makes every mounted
            // tile recompute its current program/channel source in place.
            LiveTVBoundedArtworkLoader.resumeRetainedRequests()
            liveTVArtworkRefreshToken &+= 1
            scheduleLiveTVArtworkPrefetch(immediate: true)
            scheduleLiveTVScheduleBoundaryRefresh(reason: "guide refresh complete")
            print("[ScrollBudget][vBRDC097] active Live TV refresh completed reason=\(reason)")
        }
    }

    // vBRDC225: Dynamic Wallpaper belongs to the interactive Live TV Grid/List surface.
    // It keeps animating through channel focus/mode changes and the shared left controls, but
    // the full Guide deliberately uses its dedicated static broadcast background. This keeps
    // the feature visible across the whole grid canvas without leaking into the Guide or app.
    private var liveWallpaperOwnsRenderBudget: Bool {
        dynamicMainGridWallpaperEnabled
            && scenePhase == .active
            && store.selectedTab == .live
            && !showGuide
            && !store.searchActive
            && store.selectedDetail == nil
            && store.playbackURL == nil
    }

    private func acceptSingleDpadStep() -> Bool {
        let now = Date()
        guard now.timeIntervalSince(lastDpadMoveAt) > 0.16 else { return false }
        lastDpadMoveAt = now
        return true
    }

    private func acceptSingleSelect() -> Bool {
        let now = Date()
        guard now.timeIntervalSince(lastSelectAt) > 0.30 else { return false }
        lastSelectAt = now
        return true
    }

    private func acceptSingleQuickPanelStep() -> Bool {
        let now = Date()
        guard now.timeIntervalSince(lastQuickPanelMoveAt) > 0.42 else { return false }
        lastQuickPanelMoveAt = now
        return true
    }

    private func routeLiveSpecialMove(_ direction: SignalMoveDirection, channelID: Int? = nil) {
        guard channelActionChannelID == nil else { return }

        // The grid-only Tools rail owns navigation before the underlying grid does.
        // Full Guide uses its separate compact Channels chip/drop-down below.
        if quickWindowVisible {
            guard acceptSingleQuickPanelStep() else { return }
            switch direction {
            case .left, .right:
                closeQuickWindow()
            case .up:
                quickPanelSelectionIndex = max(0, quickPanelSelectionIndex - 1)
                quickPanelItemFocus = quickPanelSelectionIndex
            case .down:
                quickPanelSelectionIndex = min(quickPanelItemCount - 1, quickPanelSelectionIndex + 1)
                quickPanelItemFocus = quickPanelSelectionIndex
            @unknown default:
                break
            }
            return
        }

        // vBRDC327: RIGHT is the Guide's universal "collapse to full mode" command.
        // It must work whether focus currently belongs to a category, channel/program lane,
        // header control, or a geometry edge. Once collapsed, native Guide navigation resumes.
        if showGuide {
            if direction == .right, !guideCategoryRailCollapsed {
                collapseGuideRailFromCurrentFocus()
            }
            return
        }

        if mirrorDashboardActive && direction == .up && liveTVBrowseModeChipFocused {
            liveTVBrowseModeChipFocused = false
            tileFocus = nil
            unityCore.revealMirrorTopMenu()
            unityCore.requestTopNavigationFocus(origin: .live, reason: "Mirror fallback Up from GRID")
            return
        }

        // Root-level onMoveCommand can receive the same physical gesture after a child card.
        // Never let that bubbled event run channel-edge math against stale global focus state.
        // Card-owned routing below always supplies its exact channel ID.
        guard let focusedID = channelID else { return }

        // vBRDC284: Carousel and Modern List are linear focus surfaces. They keep native
        // left/right or up/down motion and only override the deliberate chrome edges.
        if liveTVBrowseMode == .carousel {
            routeLiveCarouselSpecialMove(direction, channelID: focusedID)
            return
        }
        if liveTVBrowseMode == .list {
            routeModernLiveListSpecialMove(direction, channelID: focusedID)
            return
        }

        // The original v280 Grid keeps its proven mode-chip and page-edge focus contract.
        if direction == .up, isLiveTVTileTopRow(channelID: focusedID) {
            guard acceptSingleDpadStep() else { return }
            cancelLiveTVGridFocusPreview()
            var transaction = Transaction()
            transaction.disablesAnimations = true
            withTransaction(transaction) {
                liveTVBrowseModeChipFocused = true
            }
            return
        }

        // vBRDC228: EPG is reachable only from the unified Grid/List/EPG mode chip.
        // DOWN on the third Grid row no longer arms or opens Guide.

        if gridLockedMode, gridLockedDockLocked || ((store.selectedTab == .home || store.selectedTab == .movies || store.selectedTab == .shows) && gridLockedDockFocus != nil) {
            guard acceptSingleQuickPanelStep() else { return }
            switch direction {
            case .up:
                if gridLockedDockRowIndex > 0 { gridLockedDockRowIndex -= 1 }
                gridLockedDockFocus = gridLockedDockFocus ?? 0
            case .down:
                gridLockedDockRowIndex = min(gridLockedDockRowIndex + 1, 6)
                gridLockedDockFocus = gridLockedDockFocus ?? 0
            case .left:
                gridLockedDockFocus = max(0, (gridLockedDockFocus ?? 0) - 1)
            case .right:
                gridLockedDockFocus = min(7, (gridLockedDockFocus ?? 0) + 1)
            @unknown default:
                break
            }
            return
        }


        if direction == .down, isLiveTVTileBottomRow(channelID: focusedID) {
            if mirrorDashboardActive {
                guard acceptSingleDpadStep() else { return }
                selectedChannelID = focusedID
                liveTVGuideDockOriginChannelID = nil
                tileFocus = nil
                mirrorFooterFocus = .categories
                return
            }
            // Grid is intentionally a fixed 4 x 3 page. EPG now has one authoritative entry
            // point: the mode chip. Keep focus on the third row instead of exposing hidden
            // Guide navigation or letting tvOS escape to non-channel chrome.
            guard acceptSingleDpadStep() else { return }
            selectedChannelID = focusedID
            liveTVGuideDockOriginChannelID = nil
            var transaction = Transaction()
            transaction.disablesAnimations = true
            withTransaction(transaction) { tileFocus = focusedID }
            return
        }

        if direction == .right, isLiveTVTileLastBoxInRow(channelID: focusedID) {
            guard acceptSingleDpadStep() else { return }
            leftEdgePanelArmedTileID = nil
            leftEdgePanelArmedAt = .distantPast
            leftEdgePanelArmCount = 0
            liveTVGuideDockOriginChannelID = nil

            if rightEdgeGuideArmedTileID == focusedID {
                rightEdgeGuideArmedTileID = nil
                advanceLiveTVGridPage(forward: true)
            } else {
                // First RIGHT at the edge is a real stop on the fourth card. Only the
                // second RIGHT from that same focused card crosses to the next page.
                rightEdgeGuideArmedTileID = focusedID
                selectedChannelID = focusedID
                tileFocus = focusedID
            }
            return
        }

        if direction == .left, isLiveTVTileFirstBoxInRow(channelID: focusedID) {
            rightEdgeGuideArmedTileID = nil
            liveTVGuideDockOriginChannelID = nil

            // Page 2+ also requires two LEFT presses: first holds the first card, second
            // crosses to the previous page. Page 1 keeps its existing two-LEFT Live Controls.
            if normalizedLiveTVGridPageIndex > 0 {
                guard acceptSingleDpadStep() else { return }
                let now = Date()
                let isSecondLeft = leftEdgePanelArmedTileID == focusedID
                let deliberateGap = now.timeIntervalSince(leftEdgePanelArmedAt)
                if isSecondLeft && deliberateGap >= 0.65 {
                    leftEdgePanelArmedTileID = nil
                    leftEdgePanelArmedAt = .distantPast
                    leftEdgePanelArmCount = 0
                    advanceLiveTVGridPage(forward: false)
                } else {
                    // vBRDC301: tvOS can emit a second LEFT command from the same physical
                    // Siri Remote gesture while the edge card still owns focus. Treat repeats
                    // inside 650 ms as the same first press instead of accidentally paging.
                    leftEdgePanelArmedTileID = focusedID
                    if !isSecondLeft || deliberateGap >= 0.65 { leftEdgePanelArmedAt = now }
                    leftEdgePanelArmCount = 0
                    selectedChannelID = focusedID
                    tileFocus = focusedID
                }
                return
            }

            // Preview Mirror has no left Quick Guide rail; the real category chooser
            // is entered with Select on the bottom-right CATEGORIES button instead.
            if mirrorDashboardActive {
                guard acceptSingleDpadStep() else { return }
                selectedChannelID = focusedID
                tileFocus = focusedID
                return
            }

            // vBRDC146: page 1's Live Controls edge is intentionally stronger than page
            // paging. Three deliberate LEFT commands from the same first-column card are
            // required, preventing a single Siri Remote swipe/repeat from exposing the tool.
            guard acceptSingleDpadStep() else { return }
            selectedChannelID = focusedID
            tileFocus = focusedID
            let now = Date()
            let sameArmedCard = leftEdgePanelArmedTileID == focusedID
            let withinWindow = now.timeIntervalSince(leftEdgePanelArmedAt) < 2.6
            if !sameArmedCard || !withinWindow {
                leftEdgePanelArmedTileID = focusedID
                leftEdgePanelArmedAt = now
                leftEdgePanelArmCount = 1
                return
            }

            leftEdgePanelArmCount += 1
            leftEdgePanelArmedAt = now
            if leftEdgePanelArmCount >= 3 {
                leftEdgePanelArmedTileID = nil
                leftEdgePanelArmedAt = .distantPast
                leftEdgePanelArmCount = 0
                openQuickWindow()
            }
            return
        }

        if direction != .right {
            rightEdgeGuideArmedTileID = nil
        }
        if direction != .left {
            leftEdgePanelArmedTileID = nil
            leftEdgePanelArmedAt = .distantPast
            leftEdgePanelArmCount = 0
        }
        if direction != .down {
            liveTVGuideDockOriginChannelID = nil
        }
    }

    private func advanceLiveTVGridPage(forward: Bool) {
        let currentPage = normalizedLiveTVGridPageIndex
        let focusedID = tileFocus ?? selectedChannelID
        let nextPage = forward
            ? min(liveTVGridPageCount - 1, currentPage + 1)
            : max(0, currentPage - 1)
        guard nextPage != currentPage else {
            // Trap the physical edge on the first/last page instead of letting tvOS escape
            // to unrelated chrome when there is no adjacent channel page.
            DispatchQueue.main.async { tileFocus = focusedID }
            return
        }

        let currentLocal = liveTVGridLocalIndex(for: focusedID) ?? 0
        let row = currentLocal / liveTVGridColumnCount
        let targetPageStart = nextPage * liveTVGridPageSize
        let targetPageEnd = min(visibleChannels.count, targetPageStart + liveTVGridPageSize)
        guard targetPageStart < targetPageEnd else { return }

        let targetCount = targetPageEnd - targetPageStart
        let preferredLocal = row * liveTVGridColumnCount + (forward ? 0 : liveTVGridColumnCount - 1)
        let targetLocal = min(max(0, preferredLocal), targetCount - 1)
        let target = visibleChannels[targetPageStart + targetLocal]

        cancelLiveTVGridFocusPreview()
        gridInteractionRuntime.windowMaintenanceTask?.cancel()
        gridInteractionRuntime.windowMaintenanceTask = nil
        var transaction = Transaction()
        transaction.disablesAnimations = true
        withTransaction(transaction) {
            liveTVGridPageIndex = nextPage
            visionGazeChannelID = target.id
            selectedChannelID = target.id
            // vBRDC296: do not clear FocusState between pages. The nil -> target two-step
            // was visible as a bounce and forced two layout/focus passes for every page.
            tileFocus = target.id
            liveTVGuideDockOriginChannelID = nil
        }

        // Let the incoming page settle before background artwork work is allowed to compete
        // with the focus handoff. Preview still uses its existing three-second dwell gate.
        scheduleLiveTVGridFocusPreview(for: target.id)
    }

    private func openFullLiveTVGuide(from channelID: Int) {
        mirrorCategoriesVisible = false
        mirrorCategoryFocus = nil
        mirrorFooterFocus = nil
        let targetID = liveModel.channel(id: channelID)?.id ?? selectedChannelID
        liveTVBrowseMode = .epg
        guideHintVisible = false
        guideHintHideTask?.cancel()
        liveTVGuideDockOriginChannelID = nil
        guideExitLeftArmedAt = .distantPast
        guideCategoryMenuVisible = false
        guideCategoryChipFocused = false
        guideCategoryRailCollapsed = false
        guideCategoryMenuFocus = nil
        cancelLiveTVGridFocusPreview()
        selectedChannelID = targetID
        keepFocusedChannelInVirtualWindow()
        // vBRDC230: EPG is a mode of the persistent Live TV tree, not a presented popup.
        // Commit the mode/focus ownership in place without a separate spring presentation.
        var guideTransaction = Transaction()
        guideTransaction.disablesAnimations = true
        withTransaction(guideTransaction) {
            showGuide = true
            tileFocus = nil
            guideFocus = nil
            rightEdgeGuideArmedTileID = nil
            leftEdgePanelArmedTileID = nil
            leftEdgePanelArmedAt = .distantPast
            leftEdgePanelArmCount = 0
        }
        let categoryIndex = categories.firstIndex(of: selectedCategory) ?? 0
        DispatchQueue.main.async { guideCategoryMenuFocus = categoryIndex }
        scheduleLivePreviewWarmup(immediate: true)
    }

    private func closeFullLiveTVGuide() {
        let restoreID = guideFocus ?? selectedChannelID
        // vBRDC307: leaving Guide is a lifecycle boundary, not just a visual mode change.
        // Cancel work that can otherwise finish after the user has already navigated away.
        _ = liveTVAsyncRuntime.beginNewGeneration()
            _ = SignalSurfaceGenerationRegistry.shared.begin("guide")
            _ = SignalSurfaceGenerationRegistry.shared.begin("live-preview")
        cancelLiveTVGridFocusPreview()
        gridInteractionRuntime.guidePreviewWarmupTask?.cancel()
        gridInteractionRuntime.guidePreviewWarmupTask = nil
        gridInteractionRuntime.guidePreviewWarmupGeneration &+= 1
        liveTVFocusHandoffTask?.cancel()
        liveTVFocusHandoffTask = nil
        liveTVBrowseMode = .grid
        guideExitHintHideTask?.cancel()
        guideExitHintHideTask = nil
        guideExitHintVisible = false
        guideExitLeftArmedAt = .distantPast
        guideCategoryMenuVisible = false
        guideCategoryChipFocused = false
        guideCategoryMenuFocus = nil
        guideStartupOpen = false
        selectedChannelID = restoreID
        liveTVGridPageIndex = liveTVGridPage(for: restoreID)
        var guideTransaction = Transaction()
        guideTransaction.disablesAnimations = true
        withTransaction(guideTransaction) {
            showGuide = false
            guideFocus = nil
            liveTVGuideDockOriginChannelID = nil
            tileFocus = restoreID
            rightEdgeGuideArmedTileID = nil
        }
    }

    // vBRDC126: do not remount/recenter the 96-card virtual corridor in the same
    // transaction as a native tvOS focus move. Five rows of donor headroom let routine
    // maintenance wait until the focus transform has already begun settling; only a two-row
    // emergency edge recenters immediately. Rapid D-pad movement coalesces to the latest card.
    private func scheduleLiveTVVirtualWindowMaintenance(focusedID: Int) {
        gridInteractionRuntime.windowMaintenanceTask?.cancel()
        gridInteractionRuntime.windowMaintenanceTask = nil

        if showGuide {
            keepFocusedChannelInVirtualWindow()
            return
        }

        let source = visibleChannels
        guard source.count > renderedChannelLimit else {
            if renderedWindowStart != 0 {
                var transaction = Transaction()
                transaction.disablesAnimations = true
                withTransaction(transaction) { renderedWindowStart = 0 }
            }
            return
        }
        guard let index = visibleChannelIndex(for: focusedID) else { return }
        let safeStart = alignedLiveTVWindowStart(renderedWindowStart, sourceCount: source.count)
        let safeEnd = min(source.count, safeStart + renderedChannelLimit)
        let maintenanceBuffer = 20 // five rows, same donor protection corridor
        let emergencyBuffer = 8    // two rows: never risk walking out of mounted focus hosts
        let needsMaintenance = index < safeStart + maintenanceBuffer || index >= safeEnd - maintenanceBuffer
        guard needsMaintenance else {
            if renderedWindowStart != safeStart {
                var transaction = Transaction()
                transaction.disablesAnimations = true
                withTransaction(transaction) { renderedWindowStart = safeStart }
            }
            return
        }

        let emergency = index < safeStart + emergencyBuffer || index >= safeEnd - emergencyBuffer
        if emergency {
            var transaction = Transaction()
            transaction.disablesAnimations = true
            withTransaction(transaction) { keepFocusedChannelInVirtualWindow() }
            return
        }

        gridInteractionRuntime.windowMaintenanceTask = Task { @MainActor in
            do {
                try await Task.sleep(nanoseconds: 125_000_000)
            } catch { return }
            guard !Task.isCancelled,
                  store.selectedTab == .live,
                  store.playbackURL == nil,
                  !showGuide,
                  selectedChannelID == focusedID,
                  tileFocus == focusedID else { return }
            var transaction = Transaction()
            transaction.disablesAnimations = true
            withTransaction(transaction) { keepFocusedChannelInVirtualWindow() }
            gridInteractionRuntime.windowMaintenanceTask = nil
        }
    }

    private func keepFocusedChannelInVirtualWindow() {
        let source = visibleChannels
        guard source.count > renderedChannelLimit else {
            renderedWindowStart = 0
            return
        }
        let focusedID = tileFocus ?? guideFocus ?? selectedChannelID
        guard let index = source.firstIndex(where: { $0.id == focusedID }) else { return }
        let safeStart = alignedLiveTVWindowStart(renderedWindowStart, sourceCount: source.count)
        let safeEnd = min(source.count, safeStart + renderedChannelLimit)
        let edgeBuffer = 20 // five complete four-card rows
        if index < safeStart + edgeBuffer || index >= safeEnd - edgeBuffer {
            let targetStart = alignedLiveTVWindowStart(index - renderedChannelLimit / 2, sourceCount: source.count)
            if targetStart != renderedWindowStart { renderedWindowStart = targetStart }
        } else if renderedWindowStart != safeStart {
            // Normalize any legacy/restored unaligned snapshot without changing the focused row.
            renderedWindowStart = safeStart
        }
    }

    private func resetVirtualChannelWindow(to channelID: Int? = nil) {
        let source = visibleChannels
        guard source.count > renderedChannelLimit else {
            renderedWindowStart = 0
            return
        }
        let index = channelID.flatMap { id in source.firstIndex(where: { $0.id == id }) } ?? 0
        renderedWindowStart = alignedLiveTVWindowStart(index - renderedChannelLimit / 2, sourceCount: source.count)
    }

    private func saveLiveTVFocusSnapshot(channel: LiveTVChannel, origin: String) {
        let focusedID = showGuide ? (guideFocus ?? channel.id) : (tileFocus ?? channel.id)
        // Returning from playback should target the card that actually launched the
        // channel. The focused ID remains a fallback for guide/provider mutations.
        let index = visibleChannelIndex(for: channel.id)
            ?? visibleChannelIndex(for: focusedID)
            ?? 0
        store.liveTVFocusSnapshot = LiveTVFocusSnapshot(
            playedChannelID: channel.id,
            playedChannelStreamURL: channel.streamURL,
            playedChannelTVGID: channel.tvgID,
            playedChannelNumber: channel.number,
            playedChannelName: channel.name,
            playedChannelSource: channel.source,
            focusedChannelID: focusedID,
            channelIndex: index,
            categoryID: selectedCategory,
            renderedWindowStart: renderedWindowStart,
            origin: origin,
            showGuide: showGuide,
            capturedAt: Date()
        )
        print("[LiveTVFocus][v978] snapshot played=\(channel.id) focused=\(focusedID) category=\(selectedCategory) index=\(index) window=\(renderedWindowStart)")
    }

    private func scheduleLiveTVFocusRestore(reason: String) {
        guard store.playbackURL == nil else { return }
        // vBRDC105: once a snapshot has been consumed, late root recovery tokens must not
        // push focus to the first channel. A token without a snapshot is a no-op unless the
        // new Live TV tree genuinely has no focus owner at all.
        guard store.liveTVFocusSnapshot != nil else {
            if tileFocus == nil, guideFocus == nil, store.selectedTab == .live {
                restoreLiveTVFocusFallback()
            }
            return
        }
        liveTVFocusRestoreTask?.cancel()
        let mountGeneration = liveTVMountGeneration
        liveTVFocusRestoreTask = Task { @MainActor in
            await Task.yield()
            try? await Task.sleep(nanoseconds: 24_000_000)
            guard !Task.isCancelled,
                  store.playbackURL == nil,
                  mountGeneration == liveTVMountGeneration else { return }
            restoreLiveTVStructureBeforeFocus(reason: reason)
        }
    }

    private func restoreLiveTVStructureBeforeFocus(reason: String) {
        guard store.playbackURL == nil, let snapshot = store.liveTVFocusSnapshot else { return }

        selectedCategory = categories.contains(snapshot.categoryID) ? snapshot.categoryID : "All"
        var channels = visibleChannels
        if channels.isEmpty, selectedCategory != "All" {
            selectedCategory = "All"
            channels = visibleChannels
        }
        guard !channels.isEmpty else {
            tileFocus = nil
            guideFocus = nil
            categoryFocus = categories.first
            liveTVFocusRestoreTask = nil
            return
        }

        let nearestIndex = min(max(snapshot.channelIndex, 0), channels.count - 1)
        let cleanStream = snapshot.playedChannelStreamURL.trimmingCharacters(in: .whitespacesAndNewlines)
        let cleanTVGID = snapshot.playedChannelTVGID.trimmingCharacters(in: .whitespacesAndNewlines)
        let target = channels.first(where: { $0.id == snapshot.playedChannelID })
            ?? (!cleanStream.isEmpty ? channels.first(where: { $0.streamURL == cleanStream }) : nil)
            ?? (!cleanTVGID.isEmpty ? channels.first(where: { $0.tvgID.caseInsensitiveCompare(cleanTVGID) == .orderedSame }) : nil)
            ?? channels.first(where: {
                $0.number == snapshot.playedChannelNumber
                && $0.source.caseInsensitiveCompare(snapshot.playedChannelSource) == .orderedSame
            })
            ?? channels.first(where: { $0.name.caseInsensitiveCompare(snapshot.playedChannelName) == .orderedSame })
            ?? channels.first(where: { $0.id == snapshot.focusedChannelID })

        guard let target else {
            // Provider publication has not restored the exact channel yet. Keep the snapshot
            // and show a usable nearest card without starting a retry storm; the existing
            // provider refresh completion will call this method once more.
            let fallback = channels[nearestIndex]
            selectedChannelID = fallback.id
            liveTVGridPageIndex = min(max(0, nearestIndex / liveTVGridPageSize), max(0, liveTVGridPageCount - 1))
            if snapshot.showGuide || snapshot.origin == "guide" {
                liveTVBrowseMode = .epg
                showGuide = true
                tileFocus = nil
                guideFocus = fallback.id
            } else {
                liveTVBrowseMode = snapshot.origin == "list" ? .list : .grid
                showGuide = false
                guideFocus = nil
                tileFocus = fallback.id
            }
            liveTVFocusRestoreTask = nil
            return
        }

        // Rebuild the exact structural state in one animation-free transaction. The grid is
        // visible immediately; only the final scroll/focus binding is deferred by render turns.
        var structureTransaction = Transaction()
        structureTransaction.animation = nil
        withTransaction(structureTransaction) {
            selectedChannelID = target.id
            let targetIndex = channels.firstIndex(where: { $0.id == target.id }) ?? nearestIndex
            liveTVGridPageIndex = min(max(0, targetIndex / liveTVGridPageSize), max(0, liveTVGridPageCount - 1))
            let snapshotStart = alignedLiveTVWindowStart(snapshot.renderedWindowStart, sourceCount: channels.count)
            let targetVisibleAtSnapshot = targetIndex >= snapshotStart && targetIndex < snapshotStart + renderedChannelLimit
            renderedWindowStart = targetVisibleAtSnapshot
                ? snapshotStart
                : alignedLiveTVWindowStart(targetIndex - renderedChannelLimit / 2, sourceCount: channels.count)
            quickWindowVisible = false
            store.liveQuickPanelOpen = false
            quickPanelFocus = false
            quickPanelItemFocus = nil
            gridLockedDockFocus = nil
            gridLockedDockLocked = false
            rightEdgeGuideArmedTileID = nil
            leftEdgePanelArmedTileID = nil
            leftEdgePanelArmedAt = .distantPast
            leftEdgePanelArmCount = 0
            categoryFocus = nil
            tileFocus = nil
            guideFocus = nil
            let restoringGuide = snapshot.showGuide || snapshot.origin == "guide"
            showGuide = restoringGuide
            liveTVBrowseMode = restoringGuide ? .epg : (snapshot.origin == "list" ? .list : .grid)
        }

        if showGuide {
            liveTVRestoreScrollChannelID = nil
            liveTVRestoreScrollReadyChannelID = nil
        } else if liveTVBrowseMode == .list {
            // vBRDC228: continuous vertical List owns a ScrollViewReader just like the older
            // donor grid. Materialize the exact restored card before returning tvOS focus.
            liveTVRestoreScrollReadyChannelID = nil
            liveTVRestoreMaterializedChannelID = nil
            liveTVRestoreScrollChannelID = target.id
            liveTVRestoreScrollToken &+= 1
        } else {
            // Paged Grid mounts the target 12-card page directly.
            liveTVRestoreScrollChannelID = nil
            liveTVRestoreMaterializedChannelID = target.id
            liveTVRestoreScrollReadyChannelID = target.id
        }

        let expectedMountGeneration = liveTVMountGeneration
        liveTVFocusRestoreTask?.cancel()
        liveTVFocusRestoreTask = Task { @MainActor in
            await Task.yield()
            try? await Task.sleep(nanoseconds: 38_000_000)
            guard !Task.isCancelled,
                  store.playbackURL == nil,
                  expectedMountGeneration == liveTVMountGeneration else { return }

            if !renderedChannels.contains(where: { $0.id == target.id }) {
                resetVirtualChannelWindow(to: target.id)
            }
            if !showGuide, liveTVBrowseMode == .grid,
               !liveTVGridPageChannels.contains(where: { $0.id == target.id }) {
                liveTVGridPageIndex = liveTVGridPage(for: target.id)
                await Task.yield()
                try? await Task.sleep(nanoseconds: 24_000_000)
            }

            if !showGuide, liveTVBrowseMode == .list {
                var scrollReady = liveTVRestoreScrollReadyChannelID == target.id
                for attempt in 0..<8 where !scrollReady {
                    guard !Task.isCancelled, store.playbackURL == nil else { return }
                    if attempt == 3 {
                        liveTVRestoreScrollToken &+= 1
                    }
                    try? await Task.sleep(nanoseconds: 45_000_000)
                    scrollReady = liveTVRestoreScrollReadyChannelID == target.id
                }
                guard scrollReady else {
                    liveTVFocusRestoreTask = nil
                    return
                }
            }

            let targetMounted = showGuide
                || ((liveTVBrowseMode == .list || liveTVBrowseMode == .carousel)
                    ? renderedChannels.contains(where: { $0.id == target.id })
                    : liveTVGridPageChannels.contains(where: { $0.id == target.id }))
            guard !Task.isCancelled,
                  store.playbackURL == nil,
                  targetMounted else {
                liveTVFocusRestoreTask = nil
                return
            }

            var focusTransaction = Transaction()
            focusTransaction.animation = nil
            withTransaction(focusTransaction) {
                selectedChannelID = target.id
                if showGuide {
                    tileFocus = nil
                    guideFocus = target.id
                } else {
                    guideFocus = nil
                    tileFocus = target.id
                }
            }
            await Task.yield()
            try? await Task.sleep(nanoseconds: 52_000_000)
            guard !Task.isCancelled, store.playbackURL == nil else { return }

            var focusedID = showGuide ? guideFocus : tileFocus
            if focusedID != target.id {
                var retryTransaction = Transaction()
                retryTransaction.animation = nil
                withTransaction(retryTransaction) {
                    if showGuide { guideFocus = target.id } else { tileFocus = target.id }
                }
                await Task.yield()
                try? await Task.sleep(nanoseconds: 42_000_000)
                focusedID = showGuide ? guideFocus : tileFocus
            }

            guard !Task.isCancelled, store.playbackURL == nil else { return }
            if focusedID == target.id {
                liveTVRestoreScrollChannelID = nil
                liveTVRestoreScrollReadyChannelID = nil
                store.liveTVFocusSnapshot = nil
                LiveTVMemoryAuditManager.shared.markGridRestored(
                    channelID: target.id,
                    renderedWindowStart: renderedWindowStart,
                    guideVisible: showGuide
                )

                // Focus owns the return first. Only now can Gracenote/artwork/network work wake.
                previewPlaybackSuppressed = false
                beginForcedLiveTVArtworkBootstrap(reason: "post-playback focus restored")
                scheduleLiveTVArtworkPrefetch(focusedID: target.id, immediate: true)
                scheduleLiveTVScheduleBoundaryRefresh(reason: "post-playback focus restored")
                startLiveTVRefreshIfActive(reason: "post-playback focus restored")
                if showGuide {
                    scheduleLivePreviewWarmup(immediate: false)
                } else {
                    scheduleLiveTVGridFocusPreview(for: target.id)
                }
                print("[LiveTVFocus][vBRDC105] fast restore reason=\(reason) channel=\(target.id) category=\(selectedCategory) guide=\(showGuide) window=\(renderedWindowStart)")
            } else {
                print("[LiveTVFocus][vBRDC105] focus not yet accepted target=\(target.id); snapshot retained for provider/scene retry")
            }
            liveTVFocusRestoreTask = nil
        }
    }

    private func restoreLiveTVFocusFallback() {
        liveTVRestoreScrollChannelID = nil
        liveTVRestoreScrollReadyChannelID = nil
        let channels = visibleChannels.isEmpty ? liveModel.channels : visibleChannels
        guard let first = channels.first else { return }
        selectedChannelID = first.id
        liveTVGridPageIndex = liveTVGridPage(for: first.id)
        liveTVBrowseMode = .grid
        showGuide = false
        guideFocus = nil
        categoryFocus = nil
        tileFocus = first.id
        resetVirtualChannelWindow(to: first.id)
    }

    // vBRDC126: one-shot Live TV grid focus preview. There is intentionally no polling,
    // retry loop, neighbor probing, or persistent decoder. A new focus identity owns one
    // 3-second arm. If every guard is still true at that edge, one audible preview is created.
    // Its wall-clock lifetime is user-selectable (15/30/60 seconds or Unlimited); every
    // focus/surface/playback edge still destroys the preview immediately.
    @MainActor
    private func cancelLiveTVGridFocusPreview(invalidateSession: Bool = true) {
        gridInteractionRuntime.previewArmTask?.cancel()
        gridInteractionRuntime.previewArmTask = nil
        gridInteractionRuntime.previewStopTask?.cancel()
        gridInteractionRuntime.previewStopTask = nil
        if invalidateSession { gridInteractionRuntime.previewGeneration &+= 1 }
        gridFocusPreviewChannelID = nil
    }

    @MainActor
    private func scheduleLiveTVGridFocusPreview(for channelID: Int) {
        cancelLiveTVGridFocusPreview(invalidateSession: true)
        let generation = gridInteractionRuntime.previewGeneration

        guard liveTVGridFocusPreviewEnabled,
              store.selectedTab == .live,
              store.playbackURL == nil,
              !VODExclusivePlaybackGate.isActive,
              !showGuide,
              !quickWindowVisible,
              channelActionChannelID == nil,
              (visionGazeChannelID ?? tileFocus) == channelID,
              let channel = liveModel.channel(id: channelID),
              !channel.streamURL.isEmpty else { return }

        gridInteractionRuntime.previewArmTask = Task { @MainActor in
            do {
                try await Task.sleep(nanoseconds: 3_000_000_000)
            } catch { return }

            // Strict no-compete rule: if another video owner has claimed the decoder when
            // the 3-second dwell expires, this preview is skipped. It is never retried.
            guard !Task.isCancelled,
                  generation == gridInteractionRuntime.previewGeneration,
                  liveTVGridFocusPreviewEnabled,
                  store.selectedTab == .live,
                  store.playbackURL == nil,
                  !VODExclusivePlaybackGate.isActive,
                  !AuxiliaryVideoPlaybackCoordinator.shared.isAuxiliaryPlaybackSuppressed(),
                  !showGuide,
                  !quickWindowVisible,
                  channelActionChannelID == nil,
                  (visionGazeChannelID ?? tileFocus) == channelID,
                  !UnityFrameRuntime.shared.snapshot.navigationActive else {
                gridInteractionRuntime.previewArmTask = nil
                return
            }

            gridFocusPreviewChannelID = channelID
            gridInteractionRuntime.previewArmTask = nil

            // Wall-clock ceiling is deliberately independent of buffering/playback clocks.
            // Unlimited keeps this one preview alive only while focus remains on the card;
            // every normal cancellation edge above still tears the decoder down immediately.
            if let duration = LiveTVGridPreviewDuration.seconds(liveTVGridFocusPreviewDuration) {
                gridInteractionRuntime.previewStopTask = Task { @MainActor in
                    do {
                        try await Task.sleep(nanoseconds: UInt64(duration * 1_000_000_000))
                    } catch { return }
                    guard !Task.isCancelled, generation == gridInteractionRuntime.previewGeneration else { return }
                    if gridFocusPreviewChannelID == channelID {
                        gridFocusPreviewChannelID = nil
                    }
                    gridInteractionRuntime.previewStopTask = nil
                }
            } else {
                gridInteractionRuntime.previewStopTask = nil
            }
        }
    }

    private func liveTVGridFocusPreviewURL(for channel: LiveTVChannel) -> URL? {
        guard gridFocusPreviewChannelID == channel.id,
              liveTVGridFocusPreviewEnabled,
              store.selectedTab == .live,
              store.playbackURL == nil,
              !showGuide,
              !quickWindowVisible,
              channelActionChannelID == nil,
              let originalURL = URL(string: channel.streamURL),
              !channel.streamURL.isEmpty else { return nil }
        return MediaFlowProxyRouter.playbackURLIfAllowed(for: originalURL, kind: .liveTV)
    }

    private func scheduleLivePreviewWarmup(immediate: Bool = false) {
        let __signalPreviewGeneration = SignalSurfaceGenerationRegistry.shared.begin("live-preview")

        previewPlaybackSuppressed = false
        gridInteractionRuntime.guidePreviewWarmupTask?.cancel()
        gridInteractionRuntime.guidePreviewWarmupTask = nil
        guard showGuide else {
            gridInteractionRuntime.guidePreviewWarmupGeneration &+= 1
            return
        }
        keepFocusedChannelInVirtualWindow()
        let targetID = selectedChannelID
        let targetStream = liveModel.channel(id: targetID)?.streamURL ?? selectedChannel.streamURL
        guard !targetStream.isEmpty else { return }
        gridInteractionRuntime.guidePreviewWarmupGeneration &+= 1
        let token = gridInteractionRuntime.guidePreviewWarmupGeneration

        // Even the guide's initial preview yields one frame so focus/layout can establish
        // ownership before a live decoder is created. Subsequent channel changes get a
        // longer dwell and never instantiate KSPlayer during an active navigation burst.
        let delay: UInt64 = immediate ? 360_000_000 : 850_000_000
        gridInteractionRuntime.guidePreviewWarmupTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: delay)
            guard !Task.isCancelled, SignalSurfaceGenerationRegistry.shared.isCurrent("live-preview", token: __signalPreviewGeneration),
                  !VODExclusivePlaybackGate.isActive,
                  token == gridInteractionRuntime.guidePreviewWarmupGeneration,
                  showGuide,
                  selectedChannelID == targetID else { return }

            if UnityFrameRuntime.shared.snapshot.navigationActive {
                guard await UnityFrameRuntime.shared.waitUntilPermitted(.criticalArtwork, maxWait: 1.20) else {
                    gridInteractionRuntime.guidePreviewWarmupTask = nil
                    return
                }
            }
            guard !Task.isCancelled,
                  token == gridInteractionRuntime.guidePreviewWarmupGeneration,
                  showGuide,
                  selectedChannelID == targetID,
                  !UnityFrameRuntime.shared.snapshot.navigationActive else {
                gridInteractionRuntime.guidePreviewWarmupTask = nil
                return
            }
            previewChannelID = targetID
            gridInteractionRuntime.guidePreviewWarmupTask = nil
        }
    }

    private func moveGuideFocus(_ delta: Int) {
        guard let current = guideFocus ?? tileFocus ?? visibleChannels.first?.id, let index = visibleChannelIndex(for: current) else { return }
        let target = min(max(index + delta, 0), visibleChannels.count - 1)
        selectedChannelID = visibleChannels[target].id
        guideFocus = selectedChannelID
    }

    private func liveBackground(channel: LiveTVChannel) -> some View {
        ZStack {
            if showGuide {
                // vBRDC182: Guide is a separate UNITY presentation surface. It consumes the
                // shared app palette rather than inheriting Live TV Grid card/theme definitions.
                // Dynamic Wallpaper remains grid-only; the Guide receives the selected global
                // background + accent while keeping its own geometry and schedule presentation.
                UnitySurfaceBackdrop()
                RadialGradient(
                    colors: [unityCore.palette.accent.opacity(unityCore.palette.isPureBlack ? 0.0 : 0.10), channel.accent.opacity(0.035), .clear],
                    center: .topLeading,
                    startRadius: 20,
                    endRadius: 920
                )
                LinearGradient(
                    colors: [Color.clear, Color.black.opacity(0.08), Color.black.opacity(0.30)],
                    startPoint: .top,
                    endPoint: .bottom
                )
            } else if liveTVGridThemePreset.lowercased().contains("artwork") {
                // v1151: Artwork/Hero themes no longer force the underlying main grid to pure black.
                MainGridBackgroundView(
                    preset: mainGridBackgroundPreset,
                    dynamicEnabled: false,
                    dynamicPreset: dynamicMainGridWallpaperPreset
                )
            } else {
                LiveTVGridBackgroundThemeView(theme: liveTVGridThemePreset, accent: mirrorDashboardActive ? .orange : channel.accent, showGuide: false)
            }
        }
        .ignoresSafeArea()
        .allowsHitTesting(false)
    }

    private func gridLockedCatalogDock(size: CGSize) -> some View {
        let sourceRows = store.rows
        let wantedType: String? = store.selectedTab == .movies ? "movie" : (store.selectedTab == .shows ? "series" : nil)
        let targetRows = sourceRows.filter { row in
            row.items.contains { item in
                if let wantedType { return item.type == wantedType }
                return item.type == "movie" || item.type == "series"
            }
        }
        let fallbackRows = sourceRows.filter { row in row.items.contains { $0.type == "movie" || $0.type == "series" } }
        let rowsForDock = targetRows.isEmpty ? fallbackRows : targetRows
        let safeRowIndex = rowsForDock.isEmpty ? 0 : min(max(gridLockedDockRowIndex, 0), rowsForDock.count - 1)
        let activeRow = rowsForDock.indices.contains(safeRowIndex) ? rowsForDock[safeRowIndex] : sourceRows.first
        let nextIndex = safeRowIndex + 1
        let nextRow = rowsForDock.indices.contains(nextIndex) ? rowsForDock[nextIndex] : nil
        let rawItems = activeRow?.items ?? []
        let filteredItems = wantedType == nil ? rawItems.filter { $0.type == "movie" || $0.type == "series" } : rawItems.filter { $0.type == wantedType }
        let items = Array((filteredItems.isEmpty ? rawItems : filteredItems).prefix(8))
        let dockIsActive = store.selectedTab == .home || store.selectedTab == .movies || store.selectedTab == .shows
        let title = store.selectedTab == .shows ? "FEATURED SHOWS" : (store.selectedTab == .movies ? "FEATURED MOVIES" : "FEATURED PICKS")
        return VStack(alignment: .leading, spacing: 10) {
            HStack(alignment: .center, spacing: 12) {
                ThemedPanelLogo(title: title)
                    .scaleEffect(0.42, anchor: .leading)
                    .frame(width: 260, height: 36, alignment: .leading)
                Spacer(minLength: 0)
            }
            .padding(.horizontal, 30)
            .padding(.top, 16)

            HStack(alignment: .bottom, spacing: 16) {
                ForEach(Array(items.enumerated()), id: \.element.id) { index, item in
                    let isFocused = dockIsActive && gridLockedDockFocus == index
                    GridLockedDockPoster(item: item, index: index, isFocused: isFocused)
                        .contentShape(RoundedRectangle(cornerRadius: isFocused ? 18 : 14, style: .continuous))
                        .focusable(dockIsActive)
                        .focused($gridLockedDockFocus, equals: index)
                        .modifier(TransparentTVFocusVisual())
                        .onTapGesture {
                            guard dockIsActive else { return }
                            store.openDetail(item, pushCurrent: false)
                        }
                }
                Spacer(minLength: 0)
            }
            .padding(.horizontal, 30)
            .padding(.top, 2)
            .frame(height: 196, alignment: .bottomLeading)

            Text(nextRow?.title ?? "Continue Watching")
                .font(.system(size: 20, weight: .black, design: .rounded))
                .foregroundStyle(.white.opacity(0.44))
                .padding(.horizontal, 32)
                .padding(.bottom, 18)
        }
        .frame(width: max(1060, size.width - 398), height: 318, alignment: .topLeading)
        .background(
            UnevenRoundedRectangle(topLeadingRadius: 34, bottomLeadingRadius: 0, bottomTrailingRadius: 0, topTrailingRadius: 34, style: .continuous)
                .fill(
                    LinearGradient(
                        colors: [Color.black.opacity(0.70), Color.black.opacity(0.54), Color(red: 0.015, green: 0.018, blue: 0.026).opacity(0.46)],
                        startPoint: .topLeading,
                        endPoint: .bottomTrailing
                    )
                )
        )
        .shadow(color: .black.opacity(0.62), radius: 34, y: -8)
        .signalVisionFocusSection()
        .signalVisionExitCommand {
            gridLockedDockLocked = false
            gridLockedDockFocus = nil
            store.selectedTab = .live
            tileFocus = selectedChannelID
        }
        .signalMoveCommand { direction in
            guard dockIsActive else { return }
            if direction == .up {
                // v430: stay inside the bottom dock while browsing rows.
                // Live TV focus is restored only by selecting Live TV/RIGHT/LEFT path, not accidental UP.
                if gridLockedDockRowIndex > 0 { gridLockedDockRowIndex -= 1 }
                gridLockedDockFocus = gridLockedDockFocus ?? 0
            } else if direction == .down {
                gridLockedDockRowIndex = min(gridLockedDockRowIndex + 1, max(0, rowsForDock.count - 1))
                gridLockedDockFocus = gridLockedDockFocus ?? 0
            }
        }
        .position(x: size.width * 0.5 + 158, y: size.height - 158)
    }

    private func gridQuickControlWindow(size: CGSize) -> some View {
        VStack(alignment: .leading, spacing: 16) {
            quickPanelHeader
            if !gridLockedMode {
                quickPanelRefreshButton
            }
            quickPanelCategorySection
            if !gridLockedMode {
                quickPanelCloseHint
            }
            Spacer(minLength: 0)
        }
        .frame(width: gridLockedMode ? 302 : 306, height: gridLockedMode ? 850 : 780, alignment: .topLeading)
        .background(quickPanelBackground)
        .overlay(quickPanelBorder)
        .padding(.leading, gridLockedMode ? 18 : 18)
        .padding(.top, gridLockedMode ? 72 : 96)
        .signalVisionFocusSection()
        .focusable(quickWindowVisible && !quickWindowFocusHandoffActive)
        .focused($quickPanelFocus)
        .signalVisionFocusEffectPolicy()
        .modifier(TransparentTVFocusVisual())
        .onTapGesture { activateQuickPanelSelection() }
        .onSubmit { activateQuickPanelSelection() }
        .signalMoveCommand { direction in
            routeLiveSpecialMove(direction)
        }
        .signalVisionPlayPauseCommand { activateQuickPanelSelection() }
        .signalVisionExitCommand { closeQuickWindow() }
        .onAppear {
            quickPanelSelectionIndex = quickPanelInitialIndex
            if quickWindowVisible && !quickWindowFocusHandoffActive {
                quickPanelItemFocus = quickPanelSelectionIndex
            }
        }
        .onChange(of: quickWindowVisible) { visible in
            if visible {
                cancelLiveTVGridFocusPreview()
            } else if !showGuide, let focusedID = tileFocus {
                scheduleLiveTVGridFocusPreview(for: focusedID)
            }
            if !visible { quickPanelItemFocus = nil }
        }
        .onChange(of: quickPanelItemFocus) { value in
            if let value, quickWindowVisible { quickPanelSelectionIndex = min(max(value, 0), quickPanelItemCount - 1) }
        }
    }


