    private func runQuickPanelForceRefresh() {
        guard acceptSingleSelect() else { return }
        quickPanelFocus = true
        // vBRDC201: Force Guide owns the provider generation. Cancel a TTL/resume refresh
        // that may still be awaiting a post-sleep publication lane before starting it.
        liveRefreshTask?.cancel()
        liveRefreshTask = nil
        liveGuideRecoveryTask?.cancel()
        liveGuideRecoveryTask = nil
        liveForceRefreshTask?.cancel()
        liveForceRefreshTask = VODExclusiveWorkRegistry.start {
            await liveModel.forceRefreshGuide()
            guard !Task.isCancelled, !VODExclusivePlaybackGate.isActive else { return }

            // vBRDC203: Force Guide now means force-until-authoritative, not one request.
            // Keep retrying silently with bounded backoff while this Live TV surface remains
            // active. Cached lineup/last-known-good EPG stays visible between attempts.
            let retryDelays: [UInt64] = [10, 30, 60, 120, 300]
            var retryIndex = 0
            while liveModel.guideRecoveryRequired,
                  !Task.isCancelled,
                  store.playbackURL == nil,
                  store.selectedTab == .live,
                  scenePhase == .active,
                  !VODExclusivePlaybackGate.isActive {
                let seconds = retryDelays[min(retryIndex, retryDelays.count - 1)]
                try? await Task.sleep(nanoseconds: seconds * 1_000_000_000)
                guard !Task.isCancelled,
                      store.playbackURL == nil,
                      store.selectedTab == .live,
                      scenePhase == .active,
                      !VODExclusivePlaybackGate.isActive else { break }
                await liveModel.retryIncompleteGuideRecovery()
                retryIndex += 1
            }

            guard !Task.isCancelled, !VODExclusivePlaybackGate.isActive else { return }
            selectedCategory = "All"
            if let first = visibleChannels.first {
                selectedChannelID = first.id
                // v252: real guide refresh can update selection, but must not move focus behind the open rail.
                if !quickWindowVisible { tileFocus = first.id }
            }
            LiveTVBoundedArtworkLoader.resumeRetainedRequests()
            liveTVArtworkRefreshToken &+= 1
            scheduleLiveTVArtworkPrefetch(immediate: true)
            scheduleLiveTVScheduleBoundaryRefresh(reason: "Force Guide completed")
            DispatchQueue.main.async {
                guard !VODExclusivePlaybackGate.isActive else { return }
                quickPanelFocus = true
            }
        }
    }

