    @MainActor
    private func stageLiveTVSurfaceFocusHandoff(from oldTab: AppTab, to newTab: AppTab) {
        liveTVFocusHandoffTask?.cancel()
        liveTVFocusHandoffTask = nil
        liveTVSurfaceFocusHandoffActive = true

        let leavingCatalogForLiveRoot = UnitySurfaceSystem.catalogBranchActive(for: oldTab) && (newTab == .live || newTab == .sports)
        let enteringCatalogFromLiveRoot = (oldTab == .live || oldTab == .sports) && UnitySurfaceSystem.catalogBranchActive(for: newTab)
        let profile = UnityFrameRuntime.shared.catalogTransitionProfile(
            leavingCatalogForLiveRoot: leavingCatalogForLiveRoot,
            enteringCatalogFromLiveRoot: enteringCatalogFromLiveRoot
        )

        var pin = Transaction()
        pin.disablesAnimations = true
        withTransaction(pin) {
            // vBRDC139: when a catalog branch is taking ownership, the retained Live TV grid
            // must become visually unfocused in the same transaction that real FocusState is
            // cleared. Keeping the old visual pin through catalog preflight exposed the first/
            // selected Live TV ring underneath translucent rows and made the hidden grid keep
            // focused-card work alive. Reverse catalog -> Live TV still uses the visual pin.
            liveTVVisualFocusPinned = !enteringCatalogFromLiveRoot
            if newTab != .live {
                tileFocus = nil
                categoryFocus = nil
                guideFocus = nil
            }
        }

        if newTab == .live {
            liveTVFocusHandoffTask = Task { @MainActor in
                // Match RootView's shared UNITY timing. The catalog is completely gone before
                // real Live TV FocusState is rebound, while the exact selected tile remains
                // visually focused underneath for every frame of the reverse transition.
                try? await Task.sleep(nanoseconds: UnityFrameRuntime.nanoseconds(profile.focusBind))
                guard !Task.isCancelled,
                      store.selectedTab == .live,
                      store.playbackURL == nil,
                      !VODExclusivePlaybackGate.isActive else { return }
                if store.topMenuSelectionHoldTab != .live {
                    var focus = Transaction()
                    focus.disablesAnimations = true
                    withTransaction(focus) {
                        categoryFocus = nil
                        if showGuide {
                            guideFocus = selectedChannelID
                        } else {
                            tileFocus = selectedChannelID
                        }
                    }
                    await Task.yield()
                    guard !Task.isCancelled, store.selectedTab == .live else { return }
                }
                var release = Transaction()
                release.disablesAnimations = true
                withTransaction(release) {
                    liveTVVisualFocusPinned = false
                    liveTVSurfaceFocusHandoffActive = false
                }
                liveTVFocusHandoffTask = nil
            }
            return
        }

        let hideDelay = max(profile.preflight + profile.branchSettle + profile.focusSettle, 0.30)
        liveTVFocusHandoffTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: UnityFrameRuntime.nanoseconds(hideDelay))
            guard !Task.isCancelled, store.selectedTab == newTab, newTab != .live else { return }
            var release = Transaction()
            release.disablesAnimations = true
            withTransaction(release) {
                liveTVVisualFocusPinned = false
                liveTVSurfaceFocusHandoffActive = false
            }
            liveTVFocusHandoffTask = nil
        }
    }

    private func openQuickWindow(startingAtCategory: Bool = false) {
        quickPanelOpenAtCategory = startingAtCategory
        quickWindowHideToken += 1
        liveTVFocusHandoffTask?.cancel()
        liveTVFocusHandoffTask = nil
        liveTVSurfaceFocusHandoffActive = false

        // Preflight owns focus without animation. The selected card is visually pinned first,
        // then its real FocusState is removed, so there is never a shrink/re-grow frame under
        // the opening menu. Global navigation remains hidden for the entire handoff.
        var preflight = Transaction()
        preflight.disablesAnimations = true
        withTransaction(preflight) {
            liveTVVisualFocusPinned = true
            quickWindowFocusHandoffActive = true
            store.liveQuickPanelOpen = true
            quickPanelSelectionIndex = quickPanelInitialIndex
            tileFocus = nil
            categoryFocus = nil
            guideFocus = nil
            quickPanelFocus = false
            quickPanelItemFocus = nil
            rightEdgeGuideArmedTileID = nil
            leftEdgePanelArmedTileID = nil
            leftEdgePanelArmedAt = .distantPast
            leftEdgePanelArmCount = 0
        }

        // vBRDC124 golden motion: one compositor-owned ease-out. No grid/focus state is
        // mutated inside this transaction, so repeated tvOS focus reconciliation cannot
        // retarget the panel spring halfway through its visible travel.
        withAnimation(.timingCurve(0.16, 1.0, 0.30, 1.0, duration: 0.28)) {
            quickWindowVisible = true
        }

        liveTVFocusHandoffTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: 45_000_000)
            guard !Task.isCancelled,
                  quickWindowVisible,
                  store.selectedTab == .live,
                  !VODExclusivePlaybackGate.isActive else { return }
            var focus = Transaction()
            focus.disablesAnimations = true
            withTransaction(focus) {
                quickWindowFocusHandoffActive = false
                quickPanelSelectionIndex = quickPanelInitialIndex
                quickPanelItemFocus = quickPanelSelectionIndex
                quickPanelFocus = true
            }
            liveTVFocusHandoffTask = nil
        }
    }

    private func closeQuickWindow() {
        quickWindowHideToken += 1
        liveTVFocusHandoffTask?.cancel()
        liveTVFocusHandoffTask = nil
        liveTVSurfaceFocusHandoffActive = false

        // Keep the selected grid card visually frozen while the rail reverses. The grid stays
        // outside the focus graph until the final panel frame, so tvOS cannot auto-reclaim a
        // neighbor and cause the familiar closing snap/shift.
        var preflight = Transaction()
        preflight.disablesAnimations = true
        withTransaction(preflight) {
            liveTVVisualFocusPinned = true
            quickWindowFocusHandoffActive = true
            quickPanelFocus = false
            quickPanelItemFocus = nil
        }
        withAnimation(.timingCurve(0.32, 0.0, 0.22, 1.0, duration: 0.24)) {
            quickWindowVisible = false
        }

        liveTVFocusHandoffTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: 250_000_000)
            guard !Task.isCancelled,
                  store.selectedTab == .live,
                  store.playbackURL == nil,
                  !VODExclusivePlaybackGate.isActive else { return }
            var focus = Transaction()
            focus.disablesAnimations = true
            withTransaction(focus) {
                quickWindowFocusHandoffActive = false
                store.liveQuickPanelOpen = false
                if showGuide {
                    tileFocus = nil
                    categoryFocus = nil
                    guideFocus = selectedChannelID
                } else {
                    guideFocus = nil
                    tileFocus = selectedChannelID
                }
            }
            await Task.yield()
            let restoredOwnerMatches = showGuide ? (guideFocus == selectedChannelID) : (tileFocus == selectedChannelID)
            guard !Task.isCancelled, restoredOwnerMatches else { return }
            var release = Transaction()
            release.disablesAnimations = true
            withTransaction(release) { liveTVVisualFocusPinned = false }
            liveTVFocusHandoffTask = nil
        }
    }

    private func scheduleQuickWindowHide(delay: Double) {
        // v223: the utility panel is no longer a timed/autoloading hint. It only opens
        // intentionally when the user presses LEFT from the first grid card, and closes
        // when the user presses RIGHT/LEFT from the panel.
        quickWindowHideToken += 1
    }

    private var topCategoryRail: some View {
        HStack(spacing: 34) {
            ForEach(categories, id: \.self) { category in
                let isFocused = categoryFocus == category
                let isSelected = category == selectedCategory
                Text(category)
                    .font(.system(size: 28, weight: isSelected || isFocused ? .heavy : .semibold))
                    .foregroundStyle(isFocused ? Color.black : (isSelected ? .white : .white.opacity(0.58)))
                    .lineLimit(1)
                    .minimumScaleFactor(0.72)
                    .padding(.horizontal, isFocused ? 28 : 18)
                    .padding(.vertical, isFocused ? 12 : 10)
                    .background(
                        Capsule()
                            .fill(isFocused ? Color.white.opacity(0.94) : Color.clear)
                    )
                    .overlay(alignment: .bottom) {
                        if isSelected && !isFocused {
                            Capsule().fill(Color.orange.opacity(0.95)).frame(height: 5).offset(y: 8)
                        }
                    }
                    .contentShape(Capsule())
                    .focusable(!quickWindowVisible)
                    .focused($categoryFocus, equals: category)
                    .modifier(TransparentTVFocusVisual())
                    .onTapGesture {
                        guard !quickWindowVisible else { return }
                        selectedCategory = category
                        resetVirtualChannelWindow()
                        if let first = visibleChannels.first {
                            selectedChannelID = first.id
                            resetVirtualChannelWindow(to: first.id)
                            tileFocus = first.id
                        }
                    }
            }
        }
        .padding(.horizontal, 22)
        .padding(.vertical, 10)
        .frame(maxWidth: .infinity, alignment: .center)
        .background(RoundedRectangle(cornerRadius: 8).fill(Color.black.opacity(0.10)))
    }

    private func isMyFavorite(_ channel: LiveTVChannel) -> Bool {
        myFavoriteChannelIDs.contains(channel.id)
    }

    private func toggleMyFavorite(_ channel: LiveTVChannel) {
        var ids = myFavoriteChannelIDs
        if ids.contains(channel.id) {
            ids.remove(channel.id)
        } else {
            ids.insert(channel.id)
        }
        myFavoriteChannelIdsRaw = ids.sorted().map(String.init).joined(separator: ",")
        if selectedCategory == "My Favorites", visibleChannels.isEmpty {
            selectedCategory = "All"
            resetVirtualChannelWindow()
        }
    }

    private func myFavoriteActionTitle(for channel: LiveTVChannel) -> String {
        isMyFavorite(channel) ? "Remove from My Favorites" : "Add to My Favorites"
    }

    private func isManualSportsChannel(_ channel: LiveTVChannel) -> Bool {
        sportsManualChannelIDs.contains(channel.id)
    }

    private func toggleManualSportsChannel(_ channel: LiveTVChannel) {
        var ids = sportsManualChannelIDs
        if ids.contains(channel.id) {
            ids.remove(channel.id)
            store.status = "Removed \(channel.name) from Sports Hub."
        } else {
            ids.insert(channel.id)
            store.status = "Added \(channel.name) to Sports Hub."
        }
        sportsManualChannelIdsRaw = ids.sorted().map(String.init).joined(separator: ",")
    }

    private func manualSportsActionTitle(for channel: LiveTVChannel) -> String {
        isManualSportsChannel(channel) ? "Remove from Sports" : "Add to Sports"
    }

    // vBRDC284: single mode chip cycles Grid -> Full Guide -> Grid; List/Carousel are retired while preserving
    // channel/category/guide identity in this one persistent LiveTVScreen instance.
    private var liveTVBrowseModeChip: some View {
        let mode = currentLiveTVBrowseMode
        let focused = liveTVBrowseModeChipFocused
        let shape = RoundedRectangle(cornerRadius: 13, style: .continuous)
        return HStack(spacing: 10) {
            Image(systemName: mode.systemImage)
                .font(.system(size: 15, weight: .black))
            Text(mode.rawValue.uppercased())
                .font(.system(size: 14, weight: .black, design: .rounded))
                .tracking(1.0)
            Image(systemName: "arrow.triangle.2.circlepath")
                .font(.system(size: 10, weight: .black))
                .opacity(0.62)
        }
        .foregroundStyle(focused ? Color.black : Color.white.opacity(0.92))
        .padding(.horizontal, 15)
        .frame(height: 38)
        .background(shape.fill(focused ? Color.white.opacity(0.96) : Color.black.opacity(0.48)))
        .overlay(shape.stroke(focused ? Color.white : selectedChannel.accent.opacity(0.48), lineWidth: focused ? 2 : 1))
        .contentShape(shape)
        .focusable(true)
        .focused($liveTVBrowseModeChipFocused)
        .signalVisionFocusEffectPolicy()
        .modifier(TransparentTVFocusVisual())
        .onTapGesture { cycleLiveTVBrowseMode() }
        .signalVisionPlayPauseCommand { cycleLiveTVBrowseMode() }
        .signalMoveCommand { direction in
            switch direction {
            case .up:
                // vBRDC232: complete the focus chain: channel -> mode chip -> top menu.
                // This is explicit so Current and Spread Out layouts behave identically.
                liveTVBrowseModeChipFocused = false
                tileFocus = nil
                guideFocus = nil
                unityCore.requestTopNavigationFocus(origin: .live, reason: "Live TV mode chip up to top menu")
            case .down:
                restoreLiveTVContentFocusFromModeChip()
            default:
                break
            }
        }
        .accessibilityLabel("Live TV view: \(mode.rawValue). Select for \(mode.next.rawValue).")
    }

    private func cycleLiveTVBrowseMode() {
        guard channelActionChannelID == nil, !quickWindowVisible else { return }
        let next = currentLiveTVBrowseMode.next
        cancelLiveTVGridFocusPreview()
        guideCategoryMenuVisible = false
        guideCategoryChipFocused = false
        guideCategoryMenuFocus = nil

        switch next {
        case .grid:
            liveTVBrowseMode = .grid
            if showGuide {
                closeFullLiveTVGuide()
            } else {
                guideFocus = nil
                resetVirtualChannelWindow(to: selectedChannelID)
                liveTVGridPageIndex = liveTVGridPage(for: selectedChannelID)
            }
        case .carousel:
            if showGuide {
                showGuide = false
                guideFocus = nil
            }
            liveTVBrowseMode = .carousel
            resetVirtualChannelWindow(to: selectedChannelID)
            scheduleLiveTVArtworkPrefetch(focusedID: selectedChannelID, immediate: true)
        case .list:
            if showGuide {
                showGuide = false
                guideFocus = nil
            }
            liveTVBrowseMode = .list
            resetVirtualChannelWindow(to: selectedChannelID)
            scheduleLiveTVArtworkPrefetch(focusedID: selectedChannelID, immediate: true)
        case .epg:
            liveTVBrowseMode = .epg
            openFullLiveTVGuide(from: selectedChannelID)
        }

        // Keep the chip focused so repeated Select presses can cycle all three modes rapidly.
        // The underlying selected channel remains stable and is rebound when focus leaves the chip.
        DispatchQueue.main.async { liveTVBrowseModeChipFocused = true }
    }

    private func restoreLiveTVContentFocusFromModeChip() {
        liveTVBrowseModeChipFocused = false
        var focus = Transaction()
        focus.disablesAnimations = true
        withTransaction(focus) {
            if showGuide {
                guideCategoryRailCollapsed = false
                guideFocus = nil
                tileFocus = nil
            } else {
                guideFocus = nil
                tileFocus = selectedChannelID
            }
        }
        if showGuide {
            let categoryIndex = categories.firstIndex(of: selectedCategory) ?? 0
            DispatchQueue.main.async { guideCategoryMenuFocus = categoryIndex }
        }
    }

    // vBRDC230: one persistent Live TV browse shell. Grid/List/EPG share the
    // same header, insets, focus plane and root geometry instead of presenting the Guide as
    // a separately padded subtree. The selected channel/category remains owned by this shell.
    private var mirrorDashboardActive: Bool {
        SignalLiveTVDashboardStyle.normalized(liveTVDashboardStyle) == "Preview Mirror" && !showGuide
    }

    @ViewBuilder
    private func liveTVUnifiedBrowseSurface(size: CGSize) -> some View {
        let spacing: CGFloat = LiveTVGridLayoutStyle.normalized(liveTVGridLayoutStyle) == "Spread Out" ? 17 : 13
        VStack(alignment: .leading, spacing: spacing) {
            if mirrorDashboardActive && currentLiveTVBrowseMode == .grid {
                mirrorLiveTVHeader
                    .zIndex(600)
                    .signalVisionFocusSection()
            } else {
                liveTVGridBroadcastHeader
                    .zIndex(600)
                    .signalVisionFocusSection()
            }

            Group {
                switch currentLiveTVBrowseMode {
                case .grid:
                    if mirrorDashboardActive {
                        VStack(spacing: 0) {
                            liveGridContent(size: size)
                            mirrorLiveTVFooter
                                .signalVisionFocusSection()
                                .zIndex(700)
                                .layoutPriority(1)
                        }
                    } else {
                        liveGridContent(size: size)
                    }
                case .carousel:
                    liveCarouselContent(size: size)
                case .list:
                    liveModernListContent(size: size)
                case .epg:
                    guideView(size: size)
                }
            }
        }
        .frame(height: max(0, size.height - (mirrorDashboardActive ? 36 : 92)), alignment: .top)
    }

    // vBRDC348: the production grid uses the SAME header/footer chrome as the screenshot
    // confirmation. The real LiveTVSourceModel, card/EPG, paging and focus handlers remain.
    private var mirrorLiveTVHeader: some View {
        SignalLiveTVMirrorHeader(
            category: selectedCategory,
            channelCount: visibleChannels.count,
            logoStyle: liveTVAnimatedHeaderLogoStyle,
            showLiveLogo: liveTVAnimatedHeaderLogoEnabled,
            liveLogoActive: store.selectedTab == .live && store.playbackURL == nil,
            accent: selectedChannel.accent,
            showMenuHint: !mirrorShowTopMenu,
            upNextProgram: liveModel.nextProgram(for: selectedChannel, after: liveModel.currentProgram(for: selectedChannel)),
            showUpNext: true,
            showCornerClock: true
        ) {
            mirrorGridModeChip
        }
    }

    private var mirrorGridModeChip: some View {
        mirrorGridModeChipBase
            .focusable(true)
            .focused($liveTVBrowseModeChipFocused)
            .signalVisionFocusEffectPolicy()
            .modifier(TransparentTVFocusVisual())
            .onTapGesture(perform: cycleLiveTVBrowseMode)
            .signalVisionPlayPauseCommand { cycleLiveTVBrowseMode() }
            .signalMoveCommand(perform: handleMirrorGridModeMove)
            .accessibilityLabel("Grid view. Select to open Guide; press Up for app navigation.")
    }

    private var mirrorGridModeChipBase: some View {
        let focused = liveTVBrowseModeChipFocused
        return HStack(spacing: 10) {
            Text("GRID")
                .font(.system(size: 17, weight: .medium))
            Image(systemName: "square.grid.2x2.fill")
                .font(.system(size: 16, weight: .medium))
        }
        .foregroundStyle(focused ? Color.black : Color.white.opacity(0.92))
        .padding(.horizontal, 18)
        .frame(height: 48)
        .background(mirrorGridModeChipShape.fill(focused ? Color.white.opacity(0.96) : Color.white.opacity(0.10)))
        .contentShape(mirrorGridModeChipShape)
    }

    private var mirrorGridModeChipShape: RoundedRectangle {
        RoundedRectangle(cornerRadius: 13, style: .continuous)
    }

    private func handleMirrorGridModeMove(_ direction: SignalMoveDirection) {
        if direction == .up {
            liveTVBrowseModeChipFocused = false
            tileFocus = nil
            guideFocus = nil
            unityCore.revealMirrorTopMenu()
            unityCore.requestTopNavigationFocus(origin: .live, reason: "Preview Mirror GRID up to top menu")
        } else if direction == .down {
            restoreLiveTVContentFocusFromModeChip()
        }
    }

    private var mirrorLiveTVFooter: some View {
        SignalLiveTVMirrorFooter(channelName: selectedChannel.name) {
            HStack(spacing: 24) {
                mirrorFooterAction("CATEGORIES", focus: .categories) { openMirrorCategories() }
                mirrorFooterAction("GUIDE", focus: .guide) {
                    mirrorFooterFocus = nil
                    openFullLiveTVGuide(from: selectedChannelID)
                }
                mirrorFooterAction("OPTIONS", focus: .options) { openMirrorSettings() }
            }
        }
    }

    // Real Buttons are native tvOS focus targets: OK/Select, not a hover or directional
    // gesture, activates the corresponding action. Up/Down establish a deterministic
    // return to the selected bottom-row channel; Left/Right move between footer targets.
    private func mirrorFooterAction(_ label: String, focus: MirrorFooterTarget,
                                    action: @escaping () -> Void) -> some View {
        let chipShape = Capsule(style: .continuous)
        return Button(action: action) {
            Text(label)
                .font(.system(size: 13, weight: mirrorFooterFocus == focus ? .semibold : .medium))
                .tracking(1)
                .foregroundStyle(mirrorFooterFocus == focus ? Color.white : Color.white.opacity(0.75))
                .padding(.horizontal, 16)
                .frame(height: 34)
                .background(chipShape.fill(mirrorFooterFocus == focus ? Color.white.opacity(0.18) : Color.clear))
                .overlay(chipShape.stroke(mirrorFooterFocus == focus ? Color.white.opacity(0.22) : Color.clear, lineWidth: 1))
                .contentShape(chipShape)
        }
        .buttonStyle(.plain)
        .focused($mirrorFooterFocus, equals: focus)
        .signalVisionFocusEffectPolicy()
        .modifier(TransparentTVFocusVisual())
        .signalMoveCommand { direction in
            switch direction {
            case .up:
                mirrorFooterFocus = nil
                tileFocus = selectedChannelID
            case .left:
                if focus == .guide { mirrorFooterFocus = .categories }
                if focus == .options { mirrorFooterFocus = .guide }
            case .right:
                if focus == .categories { mirrorFooterFocus = .guide }
                if focus == .guide { mirrorFooterFocus = .options }
            default: break
            }
        }
        .accessibilityLabel(label == "CATEGORIES" ? "Choose live TV channel category" :
                            (label == "GUIDE" ? "Open the full live program guide" : "Open normal app settings"))
    }

    private func openMirrorCategories() {
        guard mirrorDashboardActive, !mirrorCategoriesVisible else { return }
        cancelLiveTVGridFocusPreview()
        mirrorFooterFocus = nil
        tileFocus = nil
        liveTVBrowseModeChipFocused = false
        mirrorCategoriesVisible = true
        DispatchQueue.main.async {
            guard mirrorCategoriesVisible else { return }
            mirrorCategoryFocus = categories.contains(selectedCategory) ? selectedCategory : categories.first
        }
    }

    private func closeMirrorCategories(restoreToGrid: Bool = false) {
        mirrorCategoriesVisible = false
        mirrorCategoryFocus = nil
        if restoreToGrid {
            tileFocus = selectedChannelID
        } else {
            mirrorFooterFocus = .categories
        }
    }

    private func chooseMirrorCategory(_ category: String) {
        guard mirrorCategoriesVisible, categories.contains(category) else { return }
        closeMirrorCategories()
        selectQuickPanelCategory(category) // Preserve real filtered channel and EPG ownership.
        mirrorFooterFocus = nil
        DispatchQueue.main.async { tileFocus = selectedChannelID }
    }

    private func openMirrorSettings() {
        guard mirrorDashboardActive else { return }
        cancelLiveTVGridFocusPreview()
        mirrorFooterFocus = nil
        mirrorCategoryFocus = nil
        mirrorCategoriesVisible = false
        tileFocus = nil
        store.topMenuSelectionHoldTab = nil
        store.topMenuFocusLocked = false
        store.liveQuickPanelOpen = false
        store.catalogRowsPresented = false
        unityCore.hideMirrorTopMenu()
        unityCore.select(.settings, store: store, reason: "Preview Mirror OPTIONS Select")
    }

