        .padding(23)
        .frame(width: 470)
        .background(RoundedRectangle(cornerRadius: 22).fill(Color(red: 0.045, green: 0.045, blue: 0.055).opacity(0.97)))
        .overlay(RoundedRectangle(cornerRadius: 22).stroke(Color.white.opacity(0.18), lineWidth: 1))
        .shadow(color: .black.opacity(0.75), radius: 32, y: 12)
        .signalVisionFocusSection()
        .onAppear { mirrorCategoryFocus = categories.contains(selectedCategory) ? selectedCategory : categories.first }
        .signalVisionExitCommand { closeMirrorCategories() }
    }

    // vBRDC284: Mockup #5 becomes a real focus-driven carousel. The selected channel
    // stays centered while neighboring stations recede, tilt and slide around it. This is a
    // separate renderer over the same LiveTVSourceModel, so provider/EPG state never reloads.
    private func liveCarouselContent(size: CGSize) -> some View {
        let mountedChannels = renderedChannels
        let artworkLoadIDs = liveTVLinearArtworkLoadIDs(in: mountedChannels)
        let viewportHeight = max(360, size.height - 205)

        return ScrollViewReader { proxy in
            VStack(spacing: 10) {
                Spacer(minLength: 6)
                ScrollView(.horizontal, showsIndicators: false) {
                    LazyHStack(alignment: .center, spacing: 32) {
                        ForEach(mountedChannels) { channel in
                            liveCarouselCard(
                                channel: channel,
                                loadArtwork: artworkLoadIDs.contains(channel.id)
                            )
                            .id(channel.id)
                        }
                    }
                    .padding(.horizontal, max(300, size.width * 0.32))
                    .padding(.vertical, 34)
                }
                .scrollClipDisabled()
                .frame(height: min(470, viewportHeight - 58))

                if let current = liveModel.currentProgram(for: selectedChannel) {
                    HStack(spacing: 14) {
                        LiveTVChannelLogoArtwork(
                            url: PremiumArtworkURL.url(selectedChannel.iconURL),
                            fallbackText: selectedChannel.logo,
                            maxPixelSize: 320,
                            contentPadding: 3,
                            fallbackFont: .system(size: 22, weight: .black)
                        )
                        .frame(width: 82, height: 42)

                        VStack(alignment: .leading, spacing: 2) {
                            Text(current.title)
                                .font(.system(size: 24, weight: .black, design: .rounded))
                                .foregroundStyle(.white.opacity(0.96))
                                .lineLimit(1)
                            Text([current.startText, current.endText].filter { !$0.isEmpty }.joined(separator: " – "))
                                .font(.system(size: 14, weight: .semibold, design: .rounded))
                                .foregroundStyle(.white.opacity(0.50))
                        }
                        Spacer(minLength: 0)
                    }
                    .frame(maxWidth: 760)
                    .padding(.horizontal, 22)
                }
                Spacer(minLength: 0)
            }
            .frame(height: viewportHeight, alignment: .top)
            .onAppear {
                resetVirtualChannelWindow(to: selectedChannelID)
                scheduleLiveTVArtworkPrefetch(focusedID: selectedChannelID, immediate: true)
                DispatchQueue.main.async {
                    proxy.scrollTo(selectedChannelID, anchor: .center)
                }
            }
            .onChange(of: tileFocus) { value in
                guard liveTVBrowseMode == .carousel, let value, !quickWindowVisible else {
                    if value == nil { cancelLiveTVGridFocusPreview() }
                    return
                }
                unityAnimations.registerNavigationActivity(source: "live-tv-carousel")
                selectedChannelID = value
                scheduleLiveTVVirtualWindowMaintenance(focusedID: value)
                scheduleLiveTVArtworkPrefetch(focusedID: value)
                scheduleLiveTVGridFocusPreview(for: value)
                withAnimation(.spring(response: 0.34, dampingFraction: 0.84)) {
                    proxy.scrollTo(value, anchor: .center)
                }
            }
            .onChange(of: renderedWindowStart) { _ in
                guard liveTVBrowseMode == .carousel, !showGuide else { return }
                DispatchQueue.main.async {
                    guard renderedChannels.contains(where: { $0.id == selectedChannelID }) else { return }
                    var transaction = Transaction()
                    transaction.animation = nil
                    withTransaction(transaction) { proxy.scrollTo(selectedChannelID, anchor: .center) }
                }
            }
        }
    }

    private func liveTVLinearArtworkLoadIDs(in channels: [LiveTVChannel]) -> Set<Int> {
        guard !channels.isEmpty else { return [] }
        let activeID = tileFocus ?? selectedChannelID
        let index = channels.firstIndex(where: { $0.id == activeID }) ?? 0
        let lower = max(0, index - 7)
        let upper = min(channels.count - 1, index + 7)
        return Set(channels[lower...upper].map(\.id))
    }

    private func liveCarouselCard(channel: LiveTVChannel, loadArtwork: Bool) -> some View {
        let isFocused = tileFocus == channel.id || (liveTVVisualFocusPinned && selectedChannelID == channel.id)
        let program = liveModel.currentProgram(for: channel)
        let focusedIndex = visibleChannelIndex(for: tileFocus ?? selectedChannelID) ?? 0
        let channelIndex = visibleChannelIndex(for: channel.id) ?? focusedIndex
        let delta = channelIndex - focusedIndex
        let absoluteDelta = abs(delta)
        let scale: CGFloat = isFocused ? 1.16 : (absoluteDelta == 1 ? 0.93 : 0.84)
        let opacity: Double = isFocused ? 1.0 : (absoluteDelta <= 1 ? 0.80 : 0.52)
        let angle = Double(max(-1, min(1, delta))) * -7.0
        let shape = RoundedRectangle(cornerRadius: 24, style: .continuous)
        let previewURL = isFocused ? liveTVGridFocusPreviewURL(for: channel) : nil

        return ZStack(alignment: .bottomLeading) {
            LiveTVGridTileArtwork(
                channel: channel,
                program: program,
                loadArtwork: loadArtwork,
                refreshToken: liveTVArtworkRefreshToken,
                gridLockedMode: false,
                fullCardArtwork: true
            )
            .frame(width: 286, height: 332)
            .clipped()

            if let previewURL, isFocused {
                LiveTVGridFocusPreviewSurface(url: previewURL)
                    .frame(width: 286, height: 332)
                    .clipped()
                    .allowsHitTesting(false)
            }

            LinearGradient(
                colors: [.clear, .black.opacity(0.10), .black.opacity(0.94)],
                startPoint: .top,
                endPoint: .bottom
            )

            VStack(alignment: .leading, spacing: 7) {
                HStack(spacing: 8) {
                    Text(channel.number)
                        .font(.system(size: 14, weight: .black, design: .rounded))
                    LiveTVChannelLogoArtwork(
                        url: PremiumArtworkURL.url(channel.iconURL),
                        fallbackText: channel.logo,
                        maxPixelSize: 320,
                        contentPadding: 2,
                        fallbackFont: .system(size: 18, weight: .black)
                    )
                    .frame(width: 62, height: 30)
                    Spacer(minLength: 0)
                    if program?.isLive == true {
                        Text("LIVE")
                            .font(.system(size: 10, weight: .black, design: .rounded))
                            .foregroundStyle(.white)
                            .padding(.horizontal, 8)
                            .frame(height: 24)
                            .background(Capsule().fill(Color.red.opacity(0.94)))
                    }
                }

                Spacer(minLength: 0)

                Text(program?.title ?? channel.name)
                    .font(.system(size: isFocused ? 23 : 20, weight: .black, design: .rounded))
                    .foregroundStyle(.white)
                    .lineLimit(2)

                if let program {
                    Text([program.startText, program.endText].filter { !$0.isEmpty }.joined(separator: " – "))
                        .font(.system(size: 12, weight: .semibold, design: .rounded))
                        .foregroundStyle(.white.opacity(0.62))
                        .lineLimit(1)

                    if program.hasRealTiming {
                        TimelineView(.periodic(from: Date(), by: 1.0)) { context in
                            GeometryReader { geo in
                                ZStack(alignment: .leading) {
                                    Capsule().fill(Color.white.opacity(0.18))
                                    Capsule()
                                        .fill(Color.white.opacity(isFocused ? 0.94 : 0.66))
                                        .frame(width: max(3, geo.size.width * program.progress(at: context.date)))
                                }
                            }
                            .frame(height: 5)
                        }
                    }
                }
            }
            .padding(16)
        }
        .frame(width: 286, height: 332)
        .background(Color.black.opacity(0.72))
        .clipShape(shape)
        .overlay(shape.stroke(isFocused ? channel.accent.opacity(0.96) : Color.white.opacity(0.10), lineWidth: isFocused ? 2.4 : 1))
        .shadow(color: isFocused ? channel.accent.opacity(0.24) : .black.opacity(0.34), radius: isFocused ? 24 : 12, y: 10)
        .scaleEffect(scale)
        .rotation3DEffect(.degrees(angle), axis: (x: 0, y: 1, z: 0), perspective: 0.55)
        .opacity(opacity)
        .zIndex(isFocused ? 50 : Double(max(0, 20 - absoluteDelta)))
        .animation(.spring(response: 0.32, dampingFraction: 0.84), value: selectedChannelID)
        .contentShape(shape)
        .focusable(!quickWindowVisible && !quickWindowFocusHandoffActive && channelActionChannelID == nil)
        .focused($tileFocus, equals: channel.id)
        .signalVisionFocusEffectPolicy()
        .modifier(TransparentTVFocusVisual())
        .onTapGesture {
            guard !consumeSuppressedChannelTap(for: channel.id), acceptSingleSelect() else { return }
            selectedChannelID = channel.id
            play(channel: channel)
        }
        .signalVisionPlayPauseCommand {
            guard acceptSingleSelect() else { return }
            selectedChannelID = channel.id
            play(channel: channel)
        }
        .onLongPressGesture(minimumDuration: 0.62) {
            guard channelActionChannelID == nil else { return }
            presentLiveTVChannelActions(for: channel)
        }
        .signalMoveCommand { direction in
            routeLiveSpecialMove(direction, channelID: channel.id)
        }
    }

    // vBRDC284: Mockup #9 replaces the legacy Gracenote-card List renderer after the v280 rollback. The channel
    // column stays on the left while a large artwork/live-preview information pane owns the
    // right side. Full Guide remains a separate fourth presentation mode.
    private func liveModernListContent(size: CGSize) -> some View {
        let mountedChannels = renderedChannels
        let viewportHeight = max(430, size.height - 188)

        return HStack(alignment: .top, spacing: 28) {
            ScrollViewReader { proxy in
                ScrollView(.vertical, showsIndicators: false) {
                    LazyVStack(spacing: 7) {
                        ForEach(mountedChannels) { channel in
                            liveModernListRow(channel: channel)
                                .id(channel.id)
                        }
                    }
                    .padding(.vertical, 10)
                }
                .frame(width: 500, height: viewportHeight)
                .scrollClipDisabled()
                .onAppear {
                    resetVirtualChannelWindow(to: selectedChannelID)
                    scheduleLiveTVArtworkPrefetch(focusedID: selectedChannelID, immediate: true)
                    DispatchQueue.main.async {
                        proxy.scrollTo(selectedChannelID, anchor: .center)
                    }
                    if let targetID = liveTVRestoreScrollChannelID {
                        performLiveTVRestoreScroll(proxy: proxy, targetID: targetID)
                    }
                }
                .onChange(of: tileFocus) { value in
                    guard liveTVBrowseMode == .list, let value, !quickWindowVisible else {
                        if value == nil { cancelLiveTVGridFocusPreview() }
                        return
                    }
                    unityAnimations.registerNavigationActivity(source: "live-tv-modern-list")
                    selectedChannelID = value
                    scheduleLiveTVVirtualWindowMaintenance(focusedID: value)
                    scheduleLiveTVArtworkPrefetch(focusedID: value)
                    scheduleLiveTVGridFocusPreview(for: value)
                    withAnimation(.easeOut(duration: 0.16)) {
                        proxy.scrollTo(value, anchor: .center)
                    }
                }
                .onChange(of: renderedWindowStart) { _ in
                    guard liveTVBrowseMode == .list, !showGuide else { return }
                    DispatchQueue.main.async {
                        guard renderedChannels.contains(where: { $0.id == selectedChannelID }) else { return }
                        var transaction = Transaction()
                        transaction.animation = nil
                        withTransaction(transaction) { proxy.scrollTo(selectedChannelID, anchor: .center) }
                    }
                }
                .onChange(of: liveTVRestoreScrollToken) { _ in
                    guard liveTVBrowseMode == .list,
                          let targetID = liveTVRestoreScrollChannelID else { return }
                    performLiveTVRestoreScroll(proxy: proxy, targetID: targetID)
                }
            }

            liveModernListDetail(channel: selectedChannel)
                .frame(maxWidth: .infinity, minHeight: viewportHeight, maxHeight: viewportHeight, alignment: .top)
        }
        .frame(height: viewportHeight, alignment: .top)
    }

    // vBRDC291: Keep the modern-list visual tree in its own concrete View type.
    // The vBRDC289 GitHub build reached this row but Swift's Release type checker
    // timed out on the single deeply-nested HStack + modifier expression.
    private struct LiveModernListRowVisual: View {
        let channel: LiveTVChannel
        let program: LiveProgram?
        let isFocused: Bool

        var body: some View {
            let numberOpacity = isFocused ? 0.98 : 0.64
            let nameOpacity = isFocused ? 1.0 : 0.78
            let programOpacity = isFocused ? 0.72 : 0.42
            let backgroundColor = isFocused ? channel.accent.opacity(0.17) : Color.black.opacity(0.30)
            let strokeColor = isFocused ? channel.accent.opacity(0.94) : Color.white.opacity(0.065)
            let strokeWidth: CGFloat = isFocused ? 2 : 1
            let shape = RoundedRectangle(cornerRadius: 16, style: .continuous)

            HStack(spacing: 14) {
                Text(channel.number)
                    .font(.system(size: 17, weight: .black, design: .rounded))
                    .foregroundStyle(.white.opacity(numberOpacity))
                    .frame(width: 54, alignment: .leading)

                LiveTVChannelLogoArtwork(
                    url: PremiumArtworkURL.url(channel.iconURL),
                    fallbackText: channel.logo,
                    maxPixelSize: 320,
                    contentPadding: 4,
                    fallbackFont: .system(size: 18, weight: .black)
                )
                .frame(width: 72, height: 42)

                VStack(alignment: .leading, spacing: 3) {
                    Text(channel.name)
                        .font(.system(size: 17, weight: .bold, design: .rounded))
                        .foregroundStyle(.white.opacity(nameOpacity))
                        .lineLimit(1)
                    Text(program?.title ?? channel.now)
                        .font(.system(size: 14, weight: .semibold, design: .rounded))
                        .foregroundStyle(.white.opacity(programOpacity))
                        .lineLimit(1)
                }

                Spacer(minLength: 0)

                if program?.isLive == true {
                    Text("LIVE")
                        .font(.system(size: 9, weight: .black, design: .rounded))
                        .foregroundStyle(.red.opacity(0.96))
                }
            }
            .padding(.horizontal, 14)
            .frame(height: 70)
            .background(shape.fill(backgroundColor))
            .overlay(shape.stroke(strokeColor, lineWidth: strokeWidth))
            .contentShape(shape)
        }
    }

    private func liveModernListRow(channel: LiveTVChannel) -> some View {
        let isFocused = tileFocus == channel.id || (liveTVVisualFocusPinned && selectedChannelID == channel.id)
        let program = liveModel.currentProgram(for: channel)
        let canFocus = !quickWindowVisible && !quickWindowFocusHandoffActive && channelActionChannelID == nil

        let focusableRow = LiveModernListRowVisual(
            channel: channel,
            program: program,
            isFocused: isFocused
        )
        .focusable(canFocus)
        .focused($tileFocus, equals: channel.id)
        .signalVisionFocusEffectPolicy()
        .modifier(TransparentTVFocusVisual())
        .scaleEffect(isFocused ? 1.018 : 1.0)
        .animation(.easeOut(duration: 0.12), value: isFocused)

        return focusableRow
            .onAppear {
                if liveTVRestoreScrollChannelID == channel.id {
                    liveTVRestoreMaterializedChannelID = channel.id
                }
            }
            .onTapGesture {
                guard !consumeSuppressedChannelTap(for: channel.id), acceptSingleSelect() else { return }
                selectedChannelID = channel.id
                play(channel: channel)
            }
            .signalVisionPlayPauseCommand {
                guard acceptSingleSelect() else { return }
                selectedChannelID = channel.id
                play(channel: channel)
            }
            .onLongPressGesture(minimumDuration: 0.62) {
                guard channelActionChannelID == nil else { return }
                presentLiveTVChannelActions(for: channel)
            }
            .signalMoveCommand { direction in
                routeLiveSpecialMove(direction, channelID: channel.id)
            }
    }

    private func liveModernListDetail(channel: LiveTVChannel) -> some View {
        let program = liveModel.currentProgram(for: channel)
        let nextProgram = liveModel.nextProgram(for: channel, after: program)
        let previewActive = liveTVGridFocusPreviewEnabled
            && gridFocusPreviewChannelID == channel.id
            && store.selectedTab == .live
            && store.playbackURL == nil
            && !quickWindowVisible
        let shape = RoundedRectangle(cornerRadius: 24, style: .continuous)

        return VStack(alignment: .leading, spacing: 18) {
            livePreviewWindow(channel: channel, program: program, active: previewActive)
                .aspectRatio(16.0 / 9.0, contentMode: .fit)
                .frame(maxWidth: .infinity)
                .background(Color.black)
                .clipShape(shape)
                .overlay(shape.stroke(channel.accent.opacity(previewActive ? 0.55 : 0.16), lineWidth: previewActive ? 2 : 1))

            HStack(spacing: 14) {
                LiveTVChannelLogoArtwork(
                    url: PremiumArtworkURL.url(channel.iconURL),
                    fallbackText: channel.logo,
                    maxPixelSize: 320,
                    contentPadding: 5,
                    fallbackFont: .system(size: 26, weight: .black)
                )
                .frame(width: 96, height: 54)

                VStack(alignment: .leading, spacing: 2) {
                    HStack(spacing: 10) {
                        Text(channel.number)
                            .font(.system(size: 17, weight: .black, design: .rounded))
                        Text(channel.name)
                            .font(.system(size: 20, weight: .bold, design: .rounded))
                            .lineLimit(1)
                        if program?.isLive == true {
                            Text("LIVE")
                                .font(.system(size: 9, weight: .black, design: .rounded))
                                .foregroundStyle(.white)
                                .padding(.horizontal, 8)
                                .frame(height: 22)
                                .background(Capsule().fill(Color.red.opacity(0.94)))
                        }
                    }
                    .foregroundStyle(.white.opacity(0.94))
                    Text(channel.source)
                        .font(.system(size: 12, weight: .semibold, design: .rounded))
                        .foregroundStyle(.white.opacity(0.40))
                        .lineLimit(1)
                }
                Spacer(minLength: 0)
            }

            Text(program?.title ?? channel.now)
                .font(.system(size: 34, weight: .black, design: .rounded))
                .foregroundStyle(.white)
                .lineLimit(2)

            if let program {
                HStack(spacing: 12) {
                    Text([program.startText, program.endText].filter { !$0.isEmpty }.joined(separator: " – "))
                        .font(.system(size: 15, weight: .bold, design: .rounded))
                        .foregroundStyle(.white.opacity(0.56))
                    Spacer(minLength: 0)
                }

                if program.hasRealTiming {
                    TimelineView(.periodic(from: Date(), by: 1.0)) { context in
                        GeometryReader { geo in
                            ZStack(alignment: .leading) {
                                Capsule().fill(Color.white.opacity(0.14))
                                Capsule()
                                    .fill(channel.accent.opacity(0.96))
                                    .frame(width: max(4, geo.size.width * program.progress(at: context.date)))
                            }
                        }
                        .frame(height: 6)
                    }
                }

                if !program.description.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                    Text(program.description)
                        .font(.system(size: 16, weight: .medium, design: .rounded))
                        .foregroundStyle(.white.opacity(0.58))
                        .lineLimit(3)
                }
            }

            if let nextProgram {
                HStack(spacing: 10) {
                    Text("NEXT")
                        .font(.system(size: 10, weight: .black, design: .rounded))
                        .tracking(1.0)
                        .foregroundStyle(.white.opacity(0.82))
                        .padding(.horizontal, 10)
                        .frame(height: 28)
                        .background(RoundedRectangle(cornerRadius: 8, style: .continuous).fill(Color.white.opacity(0.08)))
                    Text(nextProgram.startText)
                        .font(.system(size: 13, weight: .semibold, design: .rounded))
                        .foregroundStyle(.white.opacity(0.44))
                    Text(nextProgram.title)
                        .font(.system(size: 15, weight: .bold, design: .rounded))
                        .foregroundStyle(.white.opacity(0.82))
