    // vBRDC228: List mode is not a textual channel list. It is the same current
    // four-column Gracenote card grid as Grid mode, but restored to the older continuous
    // vertical-scroll contract from the user-provided v987 donor. Grid stays 12-card paged;
    // List is one long vertical page while retaining the bounded 96-card focus corridor.
    private func liveListContent(size: CGSize) -> some View {
        let spreadOutGrid = LiveTVGridLayoutStyle.normalized(liveTVGridLayoutStyle) == "Spread Out"
        let columnSpacing: CGFloat = gridLockedMode ? 18 : 28
        let rowSpacing: CGFloat = gridLockedMode ? 18 : (spreadOutGrid ? 30 : 25)
        // vBRDC233: List deliberately shows three complete Gracenote rows at a time.
        // Size those rows from the actual viewport so they fill the screen down toward the
        // bottom edge without revealing a fourth row. Grid mode keeps its existing sizing.
        let listViewportHeight = max(0, size.height - 188)
        let topBreathingRoom: CGFloat = 34
        let computedThreeRowHeight = (listViewportHeight - topBreathingRoom - (rowSpacing * 2)) / 3
        let cardHeight: CGFloat = max(210, computedThreeRowHeight)
        let metrics = liveTVVirtualGridMetrics(rowSpacing: rowSpacing, cardHeight: cardHeight)
        let mountedChannels = renderedChannels
        let artworkLoadIDs = liveTVArtworkLoadIDs(in: mountedChannels)

        return ScrollViewReader { proxy in
                ScrollView(.vertical, showsIndicators: false) {
                    VStack(spacing: 0) {
                        // These spacers preserve the full-library scroll height while only the
                        // bounded focus corridor is mounted. To the viewer this behaves like one
                        // continuous page from channel 1 through the final channel.
                        if metrics.top > 0 {
                            Color.clear
                                .frame(height: metrics.top)
                                .allowsHitTesting(false)
                        }

                        LazyVGrid(
                            columns: Array(
                                repeating: GridItem(.flexible(), spacing: columnSpacing),
                                count: liveTVGridColumnCount
                            ),
                            spacing: rowSpacing
                        ) {
                            ForEach(mountedChannels) { channel in
                                liveTile(
                                    channel: channel,
                                    loadArtwork: artworkLoadIDs.contains(channel.id),
                                    cardHeight: cardHeight
                                )
                                .id(channel.id)
                            }
                        }
                        .frame(maxWidth: .infinity, alignment: .topLeading)

                        if metrics.bottom > 0 {
                            Color.clear
                                .frame(height: metrics.bottom)
                                .allowsHitTesting(false)
                        }
                    }
                    .padding(.top, topBreathingRoom)
                    .padding(.bottom, 110)
                }
                // vBRDC233: the focused first row gets a real overscan/focus-scale cushion,
                // while the calculated row height keeps exactly three complete rows visible.
                .scrollClipDisabled()
                .frame(height: listViewportHeight)
                .onAppear {
                    resetVirtualChannelWindow(to: selectedChannelID)
                    scheduleLiveTVArtworkPrefetch(focusedID: selectedChannelID, immediate: true)
                    beginForcedLiveTVArtworkBootstrap(reason: "continuous Gracenote list mounted")
                    DispatchQueue.main.async {
                        guard renderedChannels.contains(where: { $0.id == selectedChannelID }) else { return }
                        var transaction = Transaction()
                        transaction.animation = nil
                        let nearTop = (visibleChannelIndex(for: selectedChannelID) ?? liveTVGridColumnCount) < liveTVGridColumnCount
                        withTransaction(transaction) {
                            proxy.scrollTo(selectedChannelID, anchor: nearTop ? UnitPoint(x: 0.5, y: 0.07) : .center)
                        }
                    }
                    if let targetID = liveTVRestoreScrollChannelID {
                        performLiveTVRestoreScroll(proxy: proxy, targetID: targetID)
                    }
                }
                .onChange(of: tileFocus) { value in
                    guard let value, !quickWindowVisible else { return }
                    unityAnimations.registerNavigationActivity(source: "live-tv-list")
                    var selection = Transaction()
                    selection.disablesAnimations = true
                    withTransaction(selection) { selectedChannelID = value }
                    scheduleLiveTVVirtualWindowMaintenance(focusedID: value)
                    scheduleLiveTVArtworkPrefetch(focusedID: value)
                    scheduleLiveTVGridFocusPreview(for: value)
                    let nearTop = (visibleChannelIndex(for: value) ?? liveTVGridColumnCount) < liveTVGridColumnCount
                    withAnimation(.easeOut(duration: 0.14)) {
                        proxy.scrollTo(value, anchor: nearTop ? UnitPoint(x: 0.5, y: 0.07) : .center)
                    }
                }
                .onChange(of: renderedWindowStart) { _ in
                    guard liveTVBrowseMode == .list, !showGuide else { return }
                    DispatchQueue.main.async {
                        guard renderedChannels.contains(where: { $0.id == selectedChannelID }) else { return }
                        var transaction = Transaction()
                        transaction.animation = nil
                        withTransaction(transaction) {
                            proxy.scrollTo(selectedChannelID, anchor: .center)
                        }
                    }
                }
                .onChange(of: liveTVRestoreScrollToken) { _ in
                    guard liveTVBrowseMode == .list,
                          let targetID = liveTVRestoreScrollChannelID else { return }
                    performLiveTVRestoreScroll(proxy: proxy, targetID: targetID)
                }
            }
        .frame(height: max(0, size.height - 188), alignment: .top)
    }

    private func isLiveListFirstColumn(channelID: Int) -> Bool {
        // vBRDC284 Modern List is one vertical channel column; every station row is the
        // deliberate left edge for the existing three-LEFT Live Controls gesture.
        visibleChannelIndex(for: channelID) != nil
    }

    private func armLinearLiveControls(channelID: Int) {
        guard acceptSingleDpadStep() else { return }
        let now = Date()
        let sameCard = leftEdgePanelArmedTileID == channelID
        let withinWindow = now.timeIntervalSince(leftEdgePanelArmedAt) < 1.35
        if sameCard && withinWindow {
            leftEdgePanelArmCount += 1
        } else {
            leftEdgePanelArmedTileID = channelID
            leftEdgePanelArmCount = 1
        }
        leftEdgePanelArmedAt = now
        selectedChannelID = channelID
        tileFocus = channelID
        if leftEdgePanelArmCount >= 3 {
            leftEdgePanelArmedTileID = nil
            leftEdgePanelArmedAt = .distantPast
            leftEdgePanelArmCount = 0
            openQuickWindow()
        }
    }

    private func focusLiveTVModeChipFromLinearSurface() {
        cancelLiveTVGridFocusPreview()
        var transaction = Transaction()
        transaction.disablesAnimations = true
        withTransaction(transaction) { liveTVBrowseModeChipFocused = true }
    }

    private func routeModernLiveListSpecialMove(_ direction: SignalMoveDirection, channelID: Int) {
        guard !showGuide, liveTVBrowseMode == .list, channelActionChannelID == nil else { return }
        switch direction {
        case .up:
            if visibleChannelIndex(for: channelID) == 0 {
                guard acceptSingleDpadStep() else { return }
                focusLiveTVModeChipFromLinearSurface()
            }
        case .left:
            armLinearLiveControls(channelID: channelID)
        default:
            leftEdgePanelArmedTileID = nil
            leftEdgePanelArmedAt = .distantPast
            leftEdgePanelArmCount = 0
        }
    }

    private func routeLiveCarouselSpecialMove(_ direction: SignalMoveDirection, channelID: Int) {
        guard !showGuide, liveTVBrowseMode == .carousel, channelActionChannelID == nil else { return }
        switch direction {
        case .up:
            guard acceptSingleDpadStep() else { return }
            focusLiveTVModeChipFromLinearSurface()
        case .left:
            if visibleChannelIndex(for: channelID) == 0 {
                armLinearLiveControls(channelID: channelID)
            } else {
                leftEdgePanelArmedTileID = nil
                leftEdgePanelArmedAt = .distantPast
                leftEdgePanelArmCount = 0
            }
        default:
            leftEdgePanelArmedTileID = nil
            leftEdgePanelArmedAt = .distantPast
            leftEdgePanelArmCount = 0
        }
    }

    private func liveGridContent(size: CGSize) -> some View {
        // vBRDC179: real Live TV presentation rebuild. The fixed 12-channel page/focus contract
        // remains intact, but the old "deck + themed backdrop" composition is gone. The grid now
        // owns a broadcast header, open wallpaper canvas, and borderless full-bleed channel windows.
        let mountedChannels = liveTVGridPageChannels
        let artworkLoadIDs = liveTVArtworkLoadIDs(in: mountedChannels)
        let spreadOutGrid = LiveTVGridLayoutStyle.normalized(liveTVGridLayoutStyle) == "Spread Out"
        let splitInward = ["Split Inward", "Split Inward Strong"].contains(SignalLiveTVCardEffect.normalized(signalLiveTVCardEffect))
        let columnSpacing: CGFloat = mirrorDashboardActive ? 29 : (gridLockedMode ? 18 : 28)
        let rowSpacing: CGFloat = mirrorDashboardActive ? 23 : (gridLockedMode ? 18 : (spreadOutGrid ? 30 : 25))
        // Fit the screenshot's full-width 16:9 cards without cutting the third row on
        // smaller TV safe areas. No geometry-driven state or extra channel views.
        let mirrorCardWidth = (size.width - 80 - 3 * columnSpacing - (splitInward ? 46 : 0)) / 4
        let mirrorCardHeight = min(mirrorCardWidth * 9 / 16, max(164, (size.height - 305 - 2 * rowSpacing) / 3))
        let cardHeight: CGFloat = mirrorDashboardActive ? mirrorCardHeight : (gridLockedMode ? 340 : (spreadOutGrid ? 252 : 210))

        return VStack(alignment: .leading, spacing: mirrorDashboardActive ? 0 : (spreadOutGrid ? 17 : 13)) {
            // vBRDC303: a page is only twelve cards, so keep all twelve mounted in a stable
            // non-lazy 3x4 focus graph. LazyVGrid could unmount/remount edge cards during page
            // handoff, which made LEFT navigation feel like a double step even though RIGHT
            // often looked fine. This mirrors the stable-row principle that fixed catalogs.
            VStack(spacing: rowSpacing) {
                ForEach(0..<Int(ceil(Double(mountedChannels.count) / Double(liveTVGridColumnCount))), id: \.self) { row in
                    HStack(spacing: columnSpacing) {
                        // Keep four stable slots and the original channel IDs. Only the
                        // Split Inward visual effect inserts an inert gutter at column 2;
                        // there are no new focus targets, timers, or geometry writes.
                        ForEach(0..<liveTVGridColumnCount, id: \.self) { column in
                            if splitInward && column == 2 {
                                Color.clear.frame(width: 46, height: 1)
                                    .accessibilityHidden(true)
                            }
                            if row * liveTVGridColumnCount + column < mountedChannels.count {
                                let channel = mountedChannels[row * liveTVGridColumnCount + column]
                                liveTile(channel: channel, loadArtwork: artworkLoadIDs.contains(channel.id), cardHeight: cardHeight)
                                    .id(channel.id)
                                    .frame(maxWidth: .infinity)
                            } else {
                                Color.clear.frame(maxWidth: .infinity, minHeight: cardHeight)
                                    .accessibilityHidden(true)
                            }
                        }
                    }
                }
            }
            .frame(maxWidth: .infinity, alignment: .topLeading)

            // vBRDC352: Preview Mirror uses the production grid's existing page badge,
            // current-page index and filtered-category total. Keep this non-focusable
            // readout below the cards (above the Mirror footer), just like Golden.
            HStack(alignment: .center, spacing: 14) {
                Spacer(minLength: 0)
                Button {
                    advanceLiveTVGridPage(forward: false)
                } label: {
                    Image(systemName: "chevron.left")
                        .font(.system(size: 17, weight: .bold))
                        .frame(width: 48, height: 44)
                }
                .buttonStyle(.bordered)
                .disabled(normalizedLiveTVGridPageIndex == 0)
                .hoverEffect(.highlight)
                .accessibilityLabel("Previous Live TV grid page")
                liveTVGridPagePositionBadge
                    .padding(.trailing, 4)
                Button {
                    advanceLiveTVGridPage(forward: true)
                } label: {
                    Image(systemName: "chevron.right")
                        .font(.system(size: 17, weight: .bold))
                        .frame(width: 48, height: 44)
                }
                .buttonStyle(.bordered)
                .disabled(normalizedLiveTVGridPageIndex >= liveTVGridPageCount - 1)
                .hoverEffect(.highlight)
                .accessibilityLabel("Next Live TV grid page")
            }
            .frame(maxWidth: .infinity)
        }
        .frame(height: max(0, size.height - (mirrorDashboardActive ? 280 : (gridLockedMode ? 150 : 178))), alignment: .top)
        // Intentionally no grid-level backdrop/panel/halo. Dynamic Wallpaper is the canvas.
        .onAppear {
            if store.selectedTab == .live {
                liveTVGridPageIndex = liveTVGridPage(for: selectedChannelID)
                beginForcedLiveTVArtworkBootstrap(reason: "visible paged grid mounted")
            }
            scheduleLiveTVArtworkPrefetch(immediate: true)
        }
        .onChange(of: liveTVGridPageIndex) { _ in
            // The paging function publishes the destination focus before changing pages.
            // Keep it visible instead of briefly removing Signal's real ring.
            cancelLiveTVGridFocusPreview()
            // Incoming mounted cards own their artwork requests. Page switching itself does
            // no speculative image work, leaving the focus handoff and layout as the only
            // work on this frame.
            LiveTVBoundedArtworkLoader.cancelObsoletePrefetches(keeping: [])
        }
        .onChange(of: tileFocus) { value in
            rightEdgeGuideArmedTileID = nil
            liveTVGuideDockOriginChannelID = nil
            guard let value, !quickWindowVisible else {
                cancelLiveTVGridFocusPreview()
                return
            }
            unityAnimations.registerNavigationActivity(source: "live-tv")
            // vBRDC347: retain the ONE bounded page prefetch during movements within
            // the same page. Repeated cancel/restart here orphaned network/decode work
            // and accumulated behind the visible card requests during long scrolls.
            // A real page change and surface exit still cancel obsolete prefetch.
            var selectionTransaction = Transaction()
            selectionTransaction.disablesAnimations = true
            withTransaction(selectionTransaction) { selectedChannelID = value }
            let targetPage = liveTVGridPage(for: value)
            if targetPage != normalizedLiveTVGridPageIndex {
                withTransaction(selectionTransaction) { liveTVGridPageIndex = targetPage }
            }
            scheduleLiveTVGridFocusPreview(for: value)
        }
    }

