    private func performLiveTVRestoreScroll(proxy: ScrollViewProxy, targetID: Int) {
        guard store.playbackURL == nil,
              liveTVRestoreScrollChannelID == targetID,
              renderedChannels.contains(where: { $0.id == targetID }) else { return }

        liveTVRestoreScrollReadyChannelID = nil
        let requestToken = liveTVRestoreScrollToken
        Task { @MainActor in
            // vBRDC105: ScrollViewReader can materialize a known ID directly. The donor
            // retried this up to fourteen times, then the focus restorer polled another
            // eighteen times; on device that looked like a frozen grid. Two non-animated
            // layout-turn placements are sufficient while preserving exact saved position.
            var transaction = Transaction()
            transaction.animation = nil
            withTransaction(transaction) {
                proxy.scrollTo(targetID, anchor: .center)
            }
            await Task.yield()
            try? await Task.sleep(nanoseconds: 48_000_000)
            guard !Task.isCancelled,
                  store.playbackURL == nil,
                  requestToken == liveTVRestoreScrollToken,
                  liveTVRestoreScrollChannelID == targetID else { return }

            var settleTransaction = Transaction()
            settleTransaction.animation = nil
            withTransaction(settleTransaction) {
                proxy.scrollTo(targetID, anchor: .center)
            }
            await Task.yield()
            try? await Task.sleep(nanoseconds: 42_000_000)
            guard !Task.isCancelled,
                  store.playbackURL == nil,
                  requestToken == liveTVRestoreScrollToken,
                  liveTVRestoreScrollChannelID == targetID else { return }
            liveTVRestoreScrollReadyChannelID = targetID
        }
    }

    // vBRDC002: replace the v1166 5-second root-grid poll with a one-shot refresh at
    // the next real EPG boundary. The Live TV screen is deliberately mounted behind
    // Home/Movies/Shows for some visual themes; a repeating main-run-loop timer there
    // caused system-wide focus hitches even when the Live TV grid was not interactive.
    private func scheduleLiveTVScheduleBoundaryRefresh(reason: String) {
        liveTVScheduleBoundaryTask?.cancel()
        liveTVScheduleBoundaryTask = nil

        guard store.playbackURL == nil,
              store.selectedTab == .live else { return }

        let now = Date()
        let boundaryChannels = (showGuide || liveTVBrowseMode == .list || liveTVBrowseMode == .carousel) ? renderedChannels : liveTVGridPageChannels
        let boundaries = boundaryChannels.compactMap { liveModel.currentProgram(for: $0)?.endDate }
            .filter { $0 > now }
        guard let nextBoundary = boundaries.min() else { return }

        let delay = max(0.20, nextBoundary.timeIntervalSince(now) + 0.12)
        let expectedMountGeneration = liveTVMountGeneration
        liveTVScheduleBoundaryTask = Task { @MainActor in
            do {
                try await Task.sleep(nanoseconds: UInt64(delay * 1_000_000_000))
            } catch { return }
            guard !Task.isCancelled,
                  expectedMountGeneration == liveTVMountGeneration,
                  store.playbackURL == nil,
                  store.selectedTab == .live else { return }

            // vBRDC102: schedule publication shares the same frame authority as catalog
            // metadata and artwork. The old local 450/320 ms heuristic could still wake in
            // the middle of a slower theme or row-motion transaction.
            guard await UnityFrameRuntime.shared.waitUntilPermitted(.liveSchedule, maxWait: 1.20) else {
                liveTVScheduleBoundaryTask = nil
                scheduleLiveTVScheduleBoundaryRefresh(reason: "boundary deferred by UNITY frame runtime")
                return
            }
            guard !Task.isCancelled, store.selectedTab == .live else { return }

            liveTVScheduleBoundaryEpoch &+= 1
            liveTVScheduleBoundaryTask = nil
            scheduleLiveTVScheduleBoundaryRefresh(reason: "program boundary")
        }
    }

    private func scheduleLiveTVArtworkPrefetch(focusedID: Int? = nil, immediate: Bool = false) {
        let requestedID = focusedID ?? tileFocus ?? selectedChannelID
        gridInteractionRuntime.artworkPrefetchTask?.cancel()
        gridInteractionRuntime.artworkPrefetchTask = Task { @MainActor in
            if !immediate {
                try? await Task.sleep(nanoseconds: 350_000_000)
            }
            guard !Task.isCancelled,
                  !VODExclusivePlaybackGate.isActive,
                  store.selectedTab == .live,
                  !showGuide,
                  !quickWindowVisible,
                  channelActionChannelID == nil else { return }

            // vBRDC178: channel-logo first paint and prefetch now share the same bounded
            // Live TV cache. This keeps page-turn identity warm without creating a second
            // native image pipeline beside the mounted card/footer/Guide logo owners.
            guard await UnityFrameRuntime.shared.waitUntilPermitted(.backgroundPrefetch, maxWait: 1.25) else {
                gridInteractionRuntime.artworkPrefetchTask = nil
                return
            }
            guard !Task.isCancelled,
                  !VODExclusivePlaybackGate.isActive,
                  store.selectedTab == .live,
                  !showGuide,
                  !quickWindowVisible,
                  channelActionChannelID == nil else { return }
            if !immediate, let focused = tileFocus, focused != requestedID { return }
            prefetchLiveTVArtworkAroundFocusedChannel(
                focusedID: requestedID,
                // vBRDC269: remote focus can move far faster than program-art decoding.
                // Warm channel identity on every settled move, but reserve the heavier
                // 512px program-art lane for page/bootstrap work instead of each D-pad step.
                includeProgramArtwork: immediate
            )
            gridInteractionRuntime.artworkPrefetchTask = nil
        }
    }

    private func prefetchLiveTVArtworkAroundFocusedChannel(
        focusedID: Int? = nil,
        includeProgramArtwork: Bool = true
    ) {
        // vBRDC143: grid prefetch follows the mounted 12-card page. Full Guide keeps the
        // existing rendered corridor. This avoids waking dozens of off-page image owners.
        let channels = (showGuide || liveTVBrowseMode == .list || liveTVBrowseMode == .carousel) ? renderedChannels : liveTVGridPageChannels
        guard !channels.isEmpty else { return }
        let activeID = focusedID ?? tileFocus ?? selectedChannelID
        let activeIndex = channels.firstIndex(where: { $0.id == activeID }) ?? 0
        // vBRDC263: keep prefetch inside the immediately visible/future corridor. The old
        // 17-channel window could start several 640px program decodes after every focus move.
        let leading = gridLockedMode ? 2 : 2
        let trailing = gridLockedMode ? 6 : 6
        let lower = max(0, activeIndex - leading)
        let upper = min(channels.count - 1, activeIndex + trailing)

        var channelLogoURLs: [URL] = []
        var programURLs: [URL] = []
        for channel in channels[lower...upper] {
            if let logoURL = PremiumArtworkURL.url(channel.iconURL), !channel.iconURL.isEmpty {
                channelLogoURLs.append(logoURL)
            }
            if includeProgramArtwork,
               abs((channels.firstIndex(where: { $0.id == channel.id }) ?? activeIndex) - activeIndex) <= 2,
               let programArt = liveModel.currentProgram(for: channel)?.imageURL,
               let url = PremiumArtworkURL.url(programArt) {
                programURLs.append(url)
            }
        }

        // vBRDC178: channel identity is now the first prefetch lane. The same bounded cache
        // backs the footer, card fallback and Guide logo owners, so page turns/fast scrolling
        // hit warm 320px logos instead of creating fresh native AsyncImage requests.
        let retainedURLs = Set(channelLogoURLs + programURLs)
        LiveTVBoundedArtworkLoader.cancelObsoletePrefetches(keeping: retainedURLs)
        if !channelLogoURLs.isEmpty {
            LiveTVBoundedArtworkLoader.prefetch(channelLogoURLs, maxPixelSize: 320, cancelObsolete: false)
        }
        if !programURLs.isEmpty {
            LiveTVBoundedArtworkLoader.prefetch(programURLs, maxPixelSize: 512, cancelObsolete: false)
        }
    }

    private func liveTile(channel: LiveTVChannel, loadArtwork: Bool, cardHeight: CGFloat = 278) -> some View {
        let isFocused = (visionGazeChannelID != nil
            ? visionGazeChannelID == channel.id
            : tileFocus == channel.id)
            || channelActionChannelID == channel.id
            || (liveTVVisualFocusPinned && selectedChannelID == channel.id)
        let program = liveModel.currentProgram(for: channel)
        // v1172: UP NEXT is visible only on the focused grid card. Avoid resolving/sorting
        // future guide rows for every off-screen/unfocused tile during each focus movement.
        let nextProgram = isFocused ? liveModel.nextProgram(for: channel, after: program) : nil
        let gridPreviewURL = isFocused ? liveTVGridFocusPreviewURL(for: channel) : nil
        // vBRDC126: preserve the exact grid geometry, but give focus transform ownership to
        // one compositor-only host. The tile subtree no longer inherits the focus spring,
        // eliminating the previous scale + border/glow/footer/preview animation convoy.
        let dimmedByPreview = liveTVGridDimOthersDuringPreview
            && gridFocusPreviewChannelID != nil
            && gridFocusPreviewChannelID != channel.id
        let firstColumn = liveTVBrowseMode == .list
            ? isLiveListFirstColumn(channelID: channel.id)
            : isFocusedTileFirstBoxInRow
        return Button {
            guard !consumeSuppressedChannelTap(for: channel.id) else { return }
            guard !quickWindowVisible, channelActionChannelID == nil, acceptSingleSelect() else { return }
            selectedChannelID = channel.id
            play(channel: channel)
        } label: {
        LiveTVGridFocusMotionHost(
            isFocused: isFocused,
            gridLockedMode: gridLockedMode,
            firstColumn: gridLockedMode && firstColumn,
            dimmed: dimmedByPreview,
            previewPopOut: gridPreviewURL != nil && LiveTVGridPreviewStyle.normalized(liveTVGridFocusPreviewStyle) == "Pop Out",
            accent: channel.accent,
            cardTheme: signalLiveTVCardTheme,
            cardEffect: SignalLiveTVCardEffect.resolved(signalLiveTVCardEffect, legacyShape: signalLiveTVCardTheme),
            cardSize: signalLiveTVCardSize,
            columnIndex: (liveTVGridLocalIndex(for: channel.id) ?? 0) % liveTVGridColumnCount
        ) {
            LiveTVGridTileContent(
                channel: channel,
                isFocused: isFocused,
                program: program,
                nextProgram: nextProgram,
                previewURL: gridPreviewURL,
                loadArtwork: loadArtwork,
                artworkRefreshToken: liveTVArtworkRefreshToken,
                gridLockedMode: gridLockedMode,
                fullCardArtwork: liveTVCardArtworkStyle == "full",
                showProgramProgress: liveTVGridProgramProgressEnabled,
                progressTick: liveTVScheduleBoundaryEpoch,
                focusRingColor: liveTVGridFocusRingColor,
                focusRingMotion: liveTVGridFocusRingMotion,
                channelNumberPosition: liveTVChannelNumberPosition,
                cardHeight: cardHeight,
                cardTheme: signalLiveTVCardTheme,
                cardTypography: signalLiveTVCardTypography
            )
            .equatable()
        }
        }
            .buttonStyle(.plain)
            .zIndex(isFocused ? 20 : 0)
            .contentShape(RoundedRectangle(cornerRadius: 20, style: .continuous))
            .focusable(!quickWindowVisible && !quickWindowFocusHandoffActive && channelActionChannelID == nil)
            .focused($tileFocus, equals: channel.id)
            // The existing Unity ring is the gaze cue; suppress our duplicate native
            // hover platter (not Apple's system-owned pinch indicator).
            .hoverEffectDisabled(true)
            .onHover { hovering in
                // When visionOS delivers gaze hover, bind it to the EXISTING focus
                // identity, ring and preview owner. Never instantiate a parallel grid.
                if !hovering { return }
                guard !showGuide, !quickWindowVisible,
                      store.selectedTab == .live, store.playbackURL == nil,
                      channelActionChannelID == nil else { return }
                // Gaze changes the true Unity selection used by rings, artwork and preview.
                // Pin visual identity independently because visionOS can drop FocusState.
                visionGazeChannelID = channel.id
                tileFocus = channel.id
                selectedChannelID = channel.id
                scheduleLiveTVGridFocusPreview(for: channel.id)
            }
            .modifier(TransparentTVFocusVisual())
            .hoverEffectDisabled(true)
            .simultaneousGesture(
                DragGesture(minimumDistance: 14)
                    .onChanged { gesture in
                        guard !showGuide, !quickWindowVisible,
                              store.selectedTab == .live, store.playbackURL == nil,
                              channelActionChannelID == nil else { return }
                        let channels = liveTVGridPageChannels
                        guard let origin = channels.firstIndex(where: { $0.id == channel.id }), !channels.isEmpty else { return }
                        // This remains on the current 12-card page; dedicated arrows page.
                        let originRow = origin / liveTVGridColumnCount
                        let originColumn = origin % liveTVGridColumnCount
                        let columnShift = Int((gesture.translation.width / 122).rounded(.towardZero))
                        let rowShift = Int((gesture.translation.height / 112).rounded(.towardZero))
                        let row = min(max(0, originRow + rowShift), (channels.count - 1) / liveTVGridColumnCount)
                        let column = min(max(0, originColumn + columnShift), liveTVGridColumnCount - 1)
                        let destination = channels[min(row * liveTVGridColumnCount + column, channels.count - 1)]
                        guard selectedChannelID != destination.id || visionGazeChannelID != destination.id else { return }
                        visionGazeChannelID = destination.id
                        tileFocus = destination.id
                        selectedChannelID = destination.id
                        scheduleLiveTVGridFocusPreview(for: destination.id)
                    }
                    .onEnded { gesture in
                        // Release only settles the focus/preview: NEVER start playback.
                        guard !showGuide, !quickWindowVisible, store.playbackURL == nil else { return }
                        if let id = visionGazeChannelID, liveTVGridPageChannels.contains(where: { $0.id == id }) {
                            tileFocus = id
                            selectedChannelID = id
                            scheduleLiveTVGridFocusPreview(for: id)
                        }
                    }
            )
            .signalVisionPlayPauseCommand {
                guard !quickWindowVisible, channelActionChannelID == nil, acceptSingleSelect() else { return }
                selectedChannelID = channel.id
                play(channel: channel)
            }
            .onAppear {
                if liveTVRestoreScrollChannelID == channel.id {
                    liveTVRestoreMaterializedChannelID = channel.id
                }
            }
            .signalMoveCommand { direction in
                // vBRDC251: route from the card that actually owns this event. This avoids
                // one-frame FocusState lag from skipping the top channel row on fast UP input.
                routeLiveSpecialMove(direction, channelID: channel.id)
            }
    }

    private func suppressChannelTap(for channelID: Int) {
        suppressedChannelTapID = channelID
        suppressChannelTapUntil = Date().addingTimeInterval(1.25)
    }

    private func consumeSuppressedChannelTap(for channelID: Int) -> Bool {
        guard suppressedChannelTapID == channelID,
              Date() < suppressChannelTapUntil else {
            if Date() >= suppressChannelTapUntil {
                suppressedChannelTapID = nil
            }
            return false
        }
        suppressedChannelTapID = nil
        suppressChannelTapUntil = .distantPast
        return true
    }

    private func presentLiveTVChannelActions(for channel: LiveTVChannel) {
        channelActionPresentedAt = Date()
        lastSelectAt = Date()
        selectedChannelID = channel.id
        quickWindowVisible = false
        store.liveQuickPanelOpen = false
        if showGuide {
            guideFocus = channel.id
        } else {
            tileFocus = channel.id
        }
        withAnimation(.easeOut(duration: 0.16)) {
            channelActionChannelID = channel.id
        }
        DispatchQueue.main.async {
            channelActionFocus = .favorite
        }
    }

    private func dismissLiveTVChannelActions() {
        let restoreID = channelActionChannelID ?? selectedChannelID
        channelActionFocus = nil
        withAnimation(.easeOut(duration: 0.14)) {
            channelActionChannelID = nil
        }
        DispatchQueue.main.async {
            selectedChannelID = restoreID
            if showGuide {
                guideFocus = restoreID
            } else {
                tileFocus = restoreID
            }
        }
    }

    private func liveTVChannelActionOverlay(channel: LiveTVChannel) -> some View {
        ZStack {
            Color.black.opacity(0.46)
                .ignoresSafeArea()
                .contentShape(Rectangle())

            VStack(alignment: .leading, spacing: 14) {
                VStack(alignment: .leading, spacing: 4) {
                    Text(channel.name)
                        .font(.system(size: 26, weight: .black, design: .rounded))
                        .foregroundStyle(.white)
                        .lineLimit(1)
                    Text([channel.number, channel.source].filter { !$0.isEmpty }.joined(separator: " • "))
                        .font(.system(size: 16, weight: .semibold, design: .rounded))
                        .foregroundStyle(.white.opacity(0.56))
                        .lineLimit(1)
                }
                .padding(.horizontal, 8)

                liveTVChannelActionButton(
                    title: myFavoriteActionTitle(for: channel),
                    systemImage: isMyFavorite(channel) ? "star.slash.fill" : "star.fill",
                    focus: .favorite
                ) {
                    toggleMyFavorite(channel)
                    dismissLiveTVChannelActions()
                }

                liveTVChannelActionButton(
                    title: manualSportsActionTitle(for: channel),
                    systemImage: isManualSportsChannel(channel) ? "minus.circle.fill" : "sportscourt.fill",
                    focus: .sports
                ) {
                    toggleManualSportsChannel(channel)
                    dismissLiveTVChannelActions()
                }
            }
            .padding(22)
            .frame(width: 500, alignment: .leading)
            .background(
                RoundedRectangle(cornerRadius: 24, style: .continuous)
                    .fill(Color.black.opacity(0.88))
                    .overlay(
                        RoundedRectangle(cornerRadius: 24, style: .continuous)
                            .stroke(Color.white.opacity(0.18), lineWidth: 1)
                    )
                    .shadow(color: .black.opacity(0.68), radius: 34, y: 18)
            )
            .signalVisionFocusSection()
            .signalVisionExitCommand { dismissLiveTVChannelActions() }
        }
    }

    private func liveTVChannelActionButton(
        title: String,
        systemImage: String,
        focus: LiveTVChannelActionFocus,
        action: @escaping () -> Void
    ) -> some View {
        let selected = channelActionFocus == focus
        let chipShape = RoundedRectangle(cornerRadius: 18, style: .continuous)
        let visual = HStack(spacing: 15) {
            Image(systemName: systemImage)
                .font(.system(size: 21, weight: .bold))
                .frame(width: 28)
            Text(title)
                .font(.system(size: 23, weight: .bold, design: .rounded))
                .lineLimit(1)
            Spacer(minLength: 0)
        }
        .foregroundStyle(selected ? Color.black : Color.white.opacity(0.92))
        .padding(.horizontal, 20)
        .frame(height: 64)
        .background(chipShape.fill(selected ? Color.white : Color.white.opacity(0.08)))
        .overlay(chipShape.stroke(selected ? Color.white.opacity(0.96) : Color.white.opacity(0.12), lineWidth: selected ? 2 : 1))
        .contentShape(chipShape)
        .clipShape(chipShape)
        .compositingGroup()
        // Separate the visual and interactive modifier graphs for the SwiftUI type checker.
        return visual
        // A focusable custom chip avoids Button's system focus platter entirely.
        .focusable(true)
        .focused($channelActionFocus, equals: focus)
        .signalVisionFocusEffectPolicy()
        .scaleEffect(selected ? 1.012 : 1.0)
        .animation(.easeOut(duration: 0.12), value: selected)
        .onTapGesture {
            guard Date().timeIntervalSince(channelActionPresentedAt) >= 0.38 else { return }
            action()
        }
        .signalVisionPlayPauseCommand {
            guard Date().timeIntervalSince(channelActionPresentedAt) >= 0.38 else { return }
            action()
        }
    }

    private func liveTVArtworkLoadIDs(in mountedChannels: [LiveTVChannel]) -> Set<Int> {
        guard store.playbackURL == nil,
              !showGuide,
              !quickWindowVisible,
              channelActionChannelID == nil else { return [] }

        // Normally only interactive Live TV may wake its decoder corridor. vBRDC099 adds
        // one bounded exception for a newly mounted persistent root (cold launch or playback
        // return), allowing a small covered corridor to rehydrate before Home/Movies/Shows
        // exposes generic/blank channel cards behind its UNITY presentation.
        let interactiveLiveTV = store.selectedTab == .live
        guard interactiveLiveTV || liveTVForcedArtworkBootstrapActive else { return [] }

        // vBRDC098: artwork readiness must never depend on the Focus Engine producing its
        // first real provider ID. On cold launch selectedChannelID can still be demo 6003
        // while mountedChannels already contains hashed/provider IDs. Returning [] here was
        // the exact reason Gracenote stayed empty until the first scroll. Prefer the current
        // focus/selection when valid, then the persisted channel, and finally bootstrap from
        // the first mounted row so visible cards begin loading without any user interaction.
        let preferredIDs = [tileFocus, guideFocus, Optional(selectedChannelID), liveTVLastSelectedChannelID > 0 ? Optional(liveTVLastSelectedChannelID) : nil]
            .compactMap { $0 }
        let focusedIndex = preferredIDs.compactMap { id in
            mountedChannels.firstIndex(where: { $0.id == id })
        }.first ?? 0
        let focusedRow = focusedIndex / liveTVGridColumnCount
        let radius = interactiveLiveTV ? 2 : 2
        let firstRow = max(0, focusedRow - radius)
        let lastRow = min((mountedChannels.count - 1) / liveTVGridColumnCount, focusedRow + radius)
        let lower = firstRow * liveTVGridColumnCount
        let upperExclusive = min(mountedChannels.count, (lastRow + 1) * liveTVGridColumnCount)
        guard lower < upperExclusive else { return [] }
        return Set(mountedChannels[lower..<upperExclusive].map(\.id))
    }

    @MainActor
    private func beginForcedLiveTVArtworkBootstrap(reason: String) {
        guard store.playbackURL == nil, !VODExclusivePlaybackGate.isActive else { return }
        liveTVForcedArtworkBootstrapTask?.cancel()
        // Repair a stale demo/persisted anchor before enabling the covered load corridor.
        synchronizeLiveTVSelectionWithPublishedLineup(reason: "\(reason) artwork bootstrap")
        liveTVForcedArtworkBootstrapActive = true
        LiveTVBoundedArtworkLoader.resumeRetainedRequests()
        liveTVArtworkRefreshToken &+= 1
        liveTVForcedArtworkBootstrapTask = Task { @MainActor in
            // Reinforce twice after LazyVGrid has had time to remount. Each token only causes
            // blank/failed owners in the bounded corridor to re-evaluate; already decoded
            // Gracenote cards short-circuit and do not refetch. This removes the last
            // "scroll once to wake artwork" dependency after playback or cold remounts.
            try? await Task.sleep(nanoseconds: 650_000_000)
            guard !Task.isCancelled, store.playbackURL == nil else { return }
            LiveTVBoundedArtworkLoader.resumeRetainedRequests()
            liveTVArtworkRefreshToken &+= 1

            try? await Task.sleep(nanoseconds: 1_350_000_000)
            guard !Task.isCancelled, store.playbackURL == nil else { return }
            LiveTVBoundedArtworkLoader.resumeRetainedRequests()
            liveTVArtworkRefreshToken &+= 1

            // Keep the covered bootstrap lane alive long enough for waitsForConnectivity and
            // the loader's own bounded retry, then return hidden Live TV to zero image work.
            try? await Task.sleep(nanoseconds: 8_000_000_000)
            guard !Task.isCancelled else { return }
            liveTVForcedArtworkBootstrapActive = false
            liveTVForcedArtworkBootstrapTask = nil
            print("[LiveTVArtwork][vBRDC099] forced visible bootstrap settled reason=\(reason)")
        }
    }

    private func scheduleGuideHintAutoHide() {
        guideHintHideTask?.cancel()
        withAnimation(.easeOut(duration: 0.18)) { guideHintVisible = true }
        guideHintHideTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: 10_000_000_000)
            guard !Task.isCancelled else { return }
            withAnimation(.easeOut(duration: 0.24)) { guideHintVisible = false }
            guideHintHideTask = nil
        }
    }

    private func scheduleGuideExitHintAutoHide() {
        guideExitHintHideTask?.cancel()
        withAnimation(.easeOut(duration: 0.18)) { guideExitHintVisible = true }
        guideExitHintHideTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: 30_000_000_000)
            guard !Task.isCancelled, showGuide else { return }
            withAnimation(.easeOut(duration: 0.30)) { guideExitHintVisible = false }
            guideExitHintHideTask = nil
        }
    }

    // vBRDC182: Guide presentation is independent from Live TV Grid appearance. The shared
    // UNITY palette supplies color only; Guide geometry/cells/header remain Guide-owned.
    private var guideThemeKey: String {
        unityCore.themeState.backgroundPreset.lowercased()
    }

    private var guideThemeAccent: Color {
        unityCore.palette.accent
    }

    private var guideThemeSurface: Color {
        let palette = unityCore.palette
        if palette.isPureBlack { return Color.black.opacity(0.78) }
        return palette.elevatedSurface.opacity(0.96)
    }

    private var guideThemeSurfaceSecondary: Color {
        let palette = unityCore.palette
        if palette.isPureBlack { return Color.white.opacity(0.026) }
        return palette.surface.opacity(0.92)
    }

    // vBRDC291: Guide keeps the v280 Live TV shell but uses a cable-guide focus model.
    // The category rail is the first focus stop; Right collapses it and the EPG expands
    // into the reclaimed width. The timeline owns a strict clipping viewport so rows can
    // never bleed into the fixed time header or hero/preview.
    private func guideView(size: CGSize) -> some View {
        GeometryReader { guideGeo in
            let availableWidth = max(1180, guideGeo.size.width)
            let availableHeight = max(560, guideGeo.size.height)
            let expandedRailWidth = min(318, max(270, availableWidth * 0.185))
            let railWidth: CGFloat = guideCategoryRailCollapsed ? 0 : expandedRailWidth
            let gap: CGFloat = guideCategoryRailCollapsed ? 0 : 18
            let mainWidth = max(820, availableWidth - railWidth - gap)
            let heroHeight = min(344, max(264, availableHeight * 0.40))
            let timelineHeight = max(280, availableHeight - heroHeight)

            HStack(alignment: .top, spacing: gap) {
                rollbackGoogleGuideCategoryRail(height: availableHeight)
                    .frame(width: railWidth, height: availableHeight, alignment: .topLeading)
                    .opacity(guideCategoryRailCollapsed ? 0 : 1)
                    .clipped()
                    .allowsHitTesting(!guideCategoryRailCollapsed)

                VStack(alignment: .leading, spacing: 0) {
                    rollbackGoogleGuideHero(channel: selectedChannel, width: mainWidth, height: heroHeight)
                        .frame(width: mainWidth, height: heroHeight, alignment: .topLeading)
                        .zIndex(10)

                    rollbackGoogleGuideTimeline(width: mainWidth, height: timelineHeight)
                        .frame(width: mainWidth, height: timelineHeight, alignment: .topLeading)
                        .clipped()
                }
                .frame(width: mainWidth, height: availableHeight, alignment: .topLeading)
            }
            .frame(width: availableWidth, height: availableHeight, alignment: .topLeading)
            .background(Color.black)
            .animation(.easeOut(duration: 0.20), value: guideCategoryRailCollapsed)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
        .onAppear {
            guideCategoryMenuVisible = false
            guideCategoryRailCollapsed = false
            guideFocus = nil
            let index = categories.firstIndex(of: selectedCategory) ?? 0
            guideCategoryHandoffSourceIndex = index
            DispatchQueue.main.async { guideCategoryMenuFocus = index }
            scheduleLivePreviewWarmup(immediate: true)
        }
        .signalVisionExitCommand { closeFullLiveTVGuide() }
    }

    private func rollbackGoogleGuideTimeline(width: CGFloat, height: CGFloat) -> some View {
        let headerHeight: CGFloat = 48
        let stationWidth: CGFloat = 220
        let slotWidth: CGFloat = 260
        let minute = Calendar.current.component(.minute, from: Date())
        let minuteInHalfHour = CGFloat(minute % 30)
        let nowX = stationWidth + (minuteInHalfHour / 30.0) * slotWidth

        return ZStack(alignment: .topLeading) {
            VStack(spacing: 0) {
                googleGuideTimelineHeader
                    .frame(width: width, height: headerHeight, alignment: .leading)
                    .zIndex(50)

                ScrollView(.vertical, showsIndicators: false) {
                    LazyVStack(spacing: 4) {
                        ForEach(renderedChannels) { channel in
                            googleGuideTimelineRow(channel: channel, rowWidth: width)
                                .id(channel.id)
                        }
                    }
                    .padding(.bottom, 110)
                }
                .frame(width: width, height: max(220, height - headerHeight), alignment: .topLeading)
                .clipped()
            }
            .frame(width: width, height: height, alignment: .topLeading)
            .clipped()

            Rectangle()
                .fill(Color.red.opacity(0.82))
                .frame(width: 2, height: height)
                .offset(x: min(max(stationWidth, nowX), max(stationWidth, width - 2)))
                .allowsHitTesting(false)
                .zIndex(60)
        }
        .background(Color.black)
        .clipped()
    }

    private func rollbackGoogleGuideCategoryRail(height: CGFloat) -> some View {
        VStack(alignment: .leading, spacing: 14) {
            Text("YOUR CHANNELS")
                .font(.system(size: 13, weight: .bold, design: .rounded))
                .tracking(1.5)
                .foregroundStyle(.white.opacity(0.44))
                .padding(.leading, 12)
