            ScrollView(.vertical, showsIndicators: false) {
                LazyVStack(spacing: 8) {
                    ForEach(Array(categories.enumerated()), id: \.element) { index, category in
                        rollbackGoogleGuideCategoryRow(category, index: index)
                    }
                }
                .padding(.horizontal, 4)
                .padding(.bottom, 80)
            }
        }
        .frame(height: height, alignment: .topLeading)
        .background(Color.black)
    }

    private func rollbackGoogleGuideCategoryRow(_ category: String, index: Int) -> some View {
        let focused = guideCategoryMenuFocus == index
        let selected = selectedCategory == category
        let active = focused
        let shape = RoundedRectangle(cornerRadius: 18, style: .continuous)
        let count = guideChannels(for: category).count

        return HStack(spacing: 15) {
            ZStack {
                Circle()
                    .fill(active ? Color.black.opacity(0.08) : Color.white.opacity(0.07))
                    .frame(width: 44, height: 44)
                Image(systemName: iconForGuideCategory(category))
                    .font(.system(size: 18, weight: .bold))
                    .foregroundStyle(active ? Color.black.opacity(0.86) : Color.white.opacity(0.78))
            }

            VStack(alignment: .leading, spacing: 2) {
                Text(category == "All" ? "All Channels" : category)
                    .font(.system(size: 21, weight: .semibold, design: .rounded))
                    .foregroundStyle(active ? Color.black : Color.white.opacity(0.92))
                    .lineLimit(1)
                Text("\(count) channels")
                    .font(.system(size: 13, weight: .medium, design: .rounded))
                    .foregroundStyle(active ? Color.black.opacity(0.55) : Color.white.opacity(0.40))
            }
            Spacer(minLength: 0)
        }
        .padding(.horizontal, 16)
        .frame(height: 78)
        .background(shape.fill(active ? Color.white.opacity(0.96) : (selected ? Color.white.opacity(0.055) : Color.clear)))
        .contentShape(shape)
        .focusable(true)
        .focused($guideCategoryMenuFocus, equals: index)
        .signalVisionFocusEffectPolicy()
        .modifier(TransparentTVFocusVisual())
        .onTapGesture { selectGuideCategory(category) }
        .signalVisionPlayPauseCommand { selectGuideCategory(category) }
        .signalMoveCommand { direction in
            if direction == .right {
                // Fallback only. On most rows tvOS can find a native channel target and this
                // handler will not fire; the guideFocus observer above then performs the same
                // centralized handoff. Bottom/edge rows that have no geometric target still
                // arrive here and use identical row-mapping math.
                guideCategoryHandoffSourceIndex = index
                _ = handoffGuideCategoryToTimeline(categoryIndex: index, nativeFocusedChannelID: nil)
            }
        }
    }

    private func collapseGuideRailFromCurrentFocus() {
        guard showGuide, !guideCategoryRailCollapsed else { return }

        // If the category rail owns focus, preserve its row/category mapping through the
        // existing handoff math. Otherwise preserve the currently focused/selected channel.
        if let categoryIndex = guideCategoryMenuFocus ?? guideCategoryHandoffSourceIndex,
           handoffGuideCategoryToTimeline(categoryIndex: categoryIndex, nativeFocusedChannelID: guideFocus) {
            return
        }

        let targetID = guideFocus ?? selectedChannelID
        guard visibleChannels.contains(where: { $0.id == targetID }) ||
              renderedChannels.contains(where: { $0.id == targetID }) else {
            var transaction = Transaction()
            transaction.disablesAnimations = true
            withTransaction(transaction) {
                guideCategoryRailCollapsed = true
                guideCategoryChipFocused = false
                guideCategoryMenuFocus = nil
            }
            return
        }

        gridInteractionRuntime.guideSelectionCommitTask?.cancel()
        gridInteractionRuntime.guideSelectionCommitTask = nil
        var transaction = Transaction()
        transaction.disablesAnimations = true
        withTransaction(transaction) {
            guideCategoryRailCollapsed = true
            guideCategoryChipFocused = false
            liveTVBrowseModeChipFocused = false
            guideCategoryMenuFocus = nil
            guideCategoryHandoffSourceIndex = nil
            selectedChannelID = targetID
            guideFocus = targetID
        }
        scheduleLiveTVVirtualWindowMaintenance(focusedID: targetID)
    }

    @discardableResult
    private func handoffGuideCategoryToTimeline(categoryIndex: Int, nativeFocusedChannelID: Int?) -> Bool {
        guard showGuide, !categories.isEmpty else { return false }

        let safeCategoryIndex = min(max(0, categoryIndex), categories.count - 1)
        let targetCategory = categories[safeCategoryIndex]
        let targetChannels = guideChannels(for: targetCategory)
        guard !targetChannels.isEmpty else { return false }

        // Preserve the *visible row lane* rather than relying on geometric nearest-neighbor
        // focus. If tvOS already landed on a channel, use that channel's ordinal inside the
        // currently rendered corridor. Then clamp the same ordinal into the new category.
        // This works at the top, middle and bottom of the category list and is independent
        // of whether SwiftUI delivered the original RIGHT move command.
        let nativeRowIndex: Int = {
            guard let nativeFocusedChannelID else { return 0 }
            if let renderedIndex = renderedChannels.firstIndex(where: { $0.id == nativeFocusedChannelID }) {
                return renderedIndex
            }
            if let visibleIndex = visibleChannels.firstIndex(where: { $0.id == nativeFocusedChannelID }) {
                return max(0, visibleIndex - renderedWindowStart)
            }
            return 0
        }()
        let targetRowIndex = min(max(0, nativeRowIndex), targetChannels.count - 1)
        let target = targetChannels[targetRowIndex]

        guideCategoryHandoffSourceIndex = nil
        gridInteractionRuntime.guideSelectionCommitTask?.cancel()
        gridInteractionRuntime.guideSelectionCommitTask = nil

        var transaction = Transaction()
        transaction.disablesAnimations = true
        withTransaction(transaction) {
            selectedCategory = targetCategory
            selectedChannelID = target.id
            resetVirtualChannelWindow(to: target.id)
            guideCategoryChipFocused = false
            liveTVBrowseModeChipFocused = false
            guideCategoryMenuFocus = nil
            guideCategoryRailCollapsed = true
            guideFocus = target.id
        }

        scheduleLiveTVVirtualWindowMaintenance(focusedID: target.id)
        scheduleLivePreviewWarmup()
        return true
    }

    private func rollbackGoogleGuideHero(channel: LiveTVChannel, width: CGFloat, height: CGFloat) -> some View {
        let program = liveModel.currentProgram(for: channel)
        let nextProgram = liveModel.nextProgram(for: channel, after: program)
        // vBRDC305: keep the Guide preview on a true 16:9 canvas. The old width*0.56
        // calculation could create an ultra-wide viewport, forcing AspectFill to crop the
        // live video vertically/horizontally. Bound width from the actual hero height.
        let nativePreviewAspect: CGFloat = 16.0 / 9.0
        let previewWidth = min(max(560, width * 0.56), height * nativePreviewAspect)
        let textWidth = max(500, width - previewWidth * 0.58)
        let description = program?.description.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""

        return ZStack(alignment: .leading) {
            Color.black

            HStack(spacing: 0) {
                Spacer(minLength: 0)
                rollbackGoogleGuideBackdropPreview(channel: channel, program: program)
                    .frame(width: previewWidth, height: height)
            }

            LinearGradient(
                stops: [
                    .init(color: .black, location: 0.00),
                    .init(color: .black, location: 0.38),
                    .init(color: .black.opacity(0.96), location: 0.49),
                    .init(color: .black.opacity(0.74), location: 0.61),
                    .init(color: .black.opacity(0.30), location: 0.78),
                    .init(color: .clear, location: 1.00)
                ],
                startPoint: .leading,
                endPoint: .trailing
            )

            VStack(alignment: .leading, spacing: 11) {
                HStack(spacing: 12) {
                    LiveTVChannelLogoArtwork(
                        url: PremiumArtworkURL.url(channel.iconURL),
                        fallbackText: channel.logo,
                        maxPixelSize: 320,
                        contentPadding: 2,
                        fallbackFont: .system(size: 24, weight: .black)
                    )
                    .frame(width: 94, height: 46)

                    Text(channel.number)
                        .font(.system(size: 19, weight: .bold, design: .rounded))
                        .foregroundStyle(.white.opacity(0.78))

                    if program?.isLive == true {
                        Text("LIVE")
                            .font(.system(size: 10, weight: .black, design: .rounded))
                            .foregroundStyle(.white)
                            .padding(.horizontal, 10)
                            .frame(height: 26)
                            .background(Capsule().fill(Color.red.opacity(0.94)))
                    }
                }

                Text(program?.title ?? channel.now)
                    .font(.system(size: 46, weight: .medium, design: .rounded))
                    .foregroundStyle(.white)
                    .lineLimit(2)
                    .minimumScaleFactor(0.72)

                if let program {
                    HStack(spacing: 12) {
                        Text([program.startText, program.endText].filter { !$0.isEmpty }.joined(separator: " – "))
                        if program.hasRealTiming {
                            if let remaining = program.secondsRemaining(at: Date()) {
                            Text("\(Int(max(0, (remaining + 59.0) / 60.0))) min remaining")
                        }
                        }
                    }
                    .font(.system(size: 17, weight: .semibold, design: .rounded))
                    .foregroundStyle(.white.opacity(0.68))
                }

                if !description.isEmpty {
                    Text(description)
                        .font(.system(size: 16, weight: .medium, design: .rounded))
                        .foregroundStyle(.white.opacity(0.52))
                        .lineLimit(2)
                }

                if let nextProgram {
                    HStack(spacing: 10) {
                        Text("NEXT")
                            .font(.system(size: 10, weight: .black, design: .rounded))
                            .tracking(1.2)
                            .foregroundStyle(.white.opacity(0.84))
                            .padding(.horizontal, 10)
                            .frame(height: 28)
                            .background(RoundedRectangle(cornerRadius: 8).fill(Color.white.opacity(0.08)))
                        Text(nextProgram.startText)
                            .font(.system(size: 13, weight: .semibold, design: .rounded))
                            .foregroundStyle(.white.opacity(0.45))
                        Text(nextProgram.title)
                            .font(.system(size: 15, weight: .bold, design: .rounded))
                            .foregroundStyle(.white.opacity(0.82))
                            .lineLimit(1)
                    }
                }
            }
            .frame(width: textWidth, alignment: .leading)
            .padding(.leading, 16)
            .padding(.vertical, 18)
        }
        .frame(width: width, height: height, alignment: .leading)
        .clipped()
    }

    private func rollbackGoogleGuideBackdropPreview(channel: LiveTVChannel, program: LiveProgram?) -> some View {
        let previewActive = previewChannelID == channel.id
            && store.selectedTab == .live
            && store.playbackURL == nil
            && !quickWindowVisible

        return ZStack {
            Color.black

            if previewActive,
               let originalStreamURL = URL(string: channel.streamURL),
               !channel.streamURL.isEmpty,
               let streamURL = MediaFlowProxyRouter.playbackURLIfAllowed(for: originalStreamURL, kind: .liveTV) {
                #if canImport(KSPlayer)
                // vBRDC296: Guide uses the same live-compatible decoder family as full Live TV.
                // Decoder creation is dwell-gated by scheduleLivePreviewWarmup so it never
                // starts while the user is actively moving through guide rows.
                KSPlayerVideoSurface(
                    url: streamURL,
                    shouldPlay: true,
                    seekSerial: 0,
                    seekSeconds: 0,
                    seekIsAbsolute: false,
                    reloadToken: 0,
                    startTimeSeconds: 0,
                    externalAudioURL: nil,
                    externalAudioOffsetMS: 0,
                    muteAudio: false,
                    contentMode: .scaleAspectFit,
                    isLiveStream: true,
                    routeHint: "live-guide-google-backdrop"
                )
                .id("live-guide-google-\(streamURL.absoluteString)")
                .marksAuxiliaryVideoActivity(true)
                .allowsHitTesting(false)
                #else
                SilentVideoBackground(url: streamURL, isMuted: false)
                    .id("live-guide-google-fallback-\(streamURL.absoluteString)")
                    .marksAuxiliaryVideoActivity(true)
                    .allowsHitTesting(false)
                #endif
            } else if let artURL = PremiumArtworkURL.url(program?.imageURL ?? ""), !(program?.imageURL ?? "").isEmpty {
                AsyncImage(url: artURL) { phase in
                    switch phase {
                    case .success(let image):
                        image.resizable().scaledToFit()
                    default:
                        LiveTVChannelLogoBackdrop(
                            url: PremiumArtworkURL.url(channel.iconURL),
                            fallbackText: channel.logo,
                            size: CGSize(width: 640, height: 360)
                        )
                    }
                }
            } else {
                LiveTVChannelLogoBackdrop(
                    url: PremiumArtworkURL.url(channel.iconURL),
                    fallbackText: channel.logo,
                    size: CGSize(width: 640, height: 360)
                )
            }
        }
        .clipped()
        // vBRDC292: the preview is part of the Guide background, not a video rectangle.
        // Feather every edge while keeping the strongest dissolve on the information side.
        .mask(
            LinearGradient(
                stops: [
                    .init(color: .clear, location: 0.00),
                    .init(color: .black.opacity(0.28), location: 0.07),
                    .init(color: .black.opacity(0.82), location: 0.20),
                    .init(color: .black, location: 0.36),
                    .init(color: .black, location: 0.97),
                    .init(color: .black.opacity(0.72), location: 1.00)
                ],
                startPoint: .leading,
                endPoint: .trailing
            )
        )
        .mask(
            LinearGradient(
                stops: [
                    .init(color: .black.opacity(0.40), location: 0.00),
                    .init(color: .black, location: 0.045),
                    .init(color: .black, location: 0.955),
                    .init(color: .black.opacity(0.40), location: 1.00)
                ],
                startPoint: .top,
                endPoint: .bottom
            )
        )
    }

