    private func openGuideCategoryMenu() {
        guard showGuide else { return }
        guideCategoryMenuVisible = true
    }

    private func closeGuideCategoryMenu() {
        guideCategoryMenuVisible = false
        guideCategoryMenuFocus = nil
    }

    private func guideChannels(for category: String) -> [LiveTVChannel] {
        if category == "All" { return liveModel.channels }
        if category == "My Favorites" { return liveModel.browseFavoriteChannels(ids: myFavoriteChannelIDs) }
        if category == "HD" { return liveModel.browseHDChannels() }
        return liveModel.browseChannels(inExactCategory: category)
    }

    private func selectGuideCategory(_ category: String) {
        let targetChannels = guideChannels(for: category)
        let categoryIndex = categories.firstIndex(of: category) ?? 0
        selectedCategory = category
        liveTVGridPageIndex = 0
        resetVirtualChannelWindow()
        if !targetChannels.contains(where: { $0.id == selectedChannelID }), let first = targetChannels.first {
            selectedChannelID = first.id
            resetVirtualChannelWindow(to: first.id)
        }
        guideCategoryMenuVisible = false
        // vBRDC292: selecting a chip must not surrender focus to tvOS. The old nil
        // assignment caused the focus engine to fall back to the first All Channels row.
        guideFocus = nil
        DispatchQueue.main.async { guideCategoryMenuFocus = categoryIndex }
        scheduleLiveTVArtworkPrefetch(focusedID: selectedChannelID, immediate: true)
        scheduleLivePreviewWarmup(immediate: true)
    }

    private func googleGuideHero(channel: LiveTVChannel, size: CGSize) -> some View {
        let currentProgram = liveModel.currentProgram(for: channel)
        let nextProgram = liveModel.nextProgram(for: channel, after: currentProgram)
        let heroHeight: CGFloat = 246

        return GeometryReader { heroGeo in
            let width = heroGeo.size.width
            let gap: CGFloat = 14
            let hintWidth: CGFloat = 50
            let previewWidth = min(390, max(350, width * 0.27))
            let infoWidth = max(570, width - previewWidth - hintWidth - (gap * 2))
            let previewHeight = (previewWidth - 16) * 9.0 / 16.0
            let previewShape = RoundedRectangle(cornerRadius: 20, style: .continuous)

            HStack(alignment: .top, spacing: gap) {
                // LOCKED: the Guide live preview stays exactly on its proven playback path.
                VStack(spacing: 8) {
                    livePreviewWindow(
                        channel: previewChannel,
                        program: liveModel.currentProgram(for: previewChannel) ?? currentProgram,
                        active: showGuide && !previewPlaybackSuppressed && !previewChannel.streamURL.isEmpty
                    )
                    .frame(width: previewWidth - 16, height: previewHeight)
                    .background(Color.black)
                    .clipShape(RoundedRectangle(cornerRadius: 16, style: .continuous))
                    .overlay(RoundedRectangle(cornerRadius: 16, style: .continuous).stroke(Color.white.opacity(0.12), lineWidth: 1))

                    HStack(spacing: 9) {
                        Circle().fill(Color.red.opacity(0.94)).frame(width: 7, height: 7)
                        Text("LIVE PREVIEW")
                            .font(.system(size: 11, weight: .black, design: .rounded))
                            .tracking(1.25)
                        Spacer(minLength: 6)
                        Text([previewChannel.number, previewChannel.name].filter { !$0.isEmpty }.joined(separator: "  •  "))
                            .font(.system(size: 12, weight: .semibold, design: .rounded))
                            .foregroundStyle(.white.opacity(0.58))
                            .lineLimit(1)
                    }
                    .foregroundStyle(.white.opacity(0.82))
                    .padding(.horizontal, 8)
                }
                .padding(8)
                .frame(width: previewWidth, height: heroHeight, alignment: .top)
                .background(previewShape.fill(Color.black.opacity(0.68)))
                .overlay(previewShape.stroke(Color.white.opacity(0.075), lineWidth: 1))

                // LOCKED: Exit / Back Menu hint remains beside the preview, never over video.
                ZStack(alignment: .top) {
                    if guideExitHintVisible {
                        LiveTVGuideExitHint()
                            .transition(.opacity.combined(with: .scale(scale: 0.97)))
                    }
                }
                .frame(width: hintWidth, height: heroHeight, alignment: .top)
                .padding(.top, 10)
                .allowsHitTesting(false)
                .accessibilityHidden(true)

                guideNowPlayingConsole(
                    channel: channel,
                    currentProgram: currentProgram,
                    nextProgram: nextProgram,
                    width: infoWidth,
                    height: heroHeight
                )
            }
            .frame(width: width, height: heroHeight, alignment: .topLeading)
        }
        .frame(maxWidth: .infinity, minHeight: heroHeight, maxHeight: heroHeight, alignment: .topLeading)
    }

    // vBRDC180: completely new Guide information architecture. One open broadcast console
    // replaces the old stacked header-card + program-card arrangement.
    private func guideNowPlayingConsole(
        channel: LiveTVChannel,
        currentProgram: LiveProgram?,
        nextProgram: LiveProgram?,
        width: CGFloat,
        height: CGFloat
    ) -> some View {
        let accent = guideThemeAccent
        let title = currentProgram?.title ?? channel.now
        let description = (currentProgram?.description ?? "").ifEmpty(channel.description)
        let start = (currentProgram?.startText ?? "Now").ifEmpty("Now")
        let end = (currentProgram?.endText ?? "").ifEmpty("Next")
        let consoleShape = RoundedRectangle(cornerRadius: 18, style: .continuous)

        return HStack(spacing: 0) {
            Rectangle()
                .fill(accent.opacity(0.86))
                .frame(width: 3)
                .padding(.vertical, 16)

            VStack(alignment: .leading, spacing: 0) {
                HStack(spacing: 12) {
                    guideHeroChannelLogo(channel: channel)
                        .frame(width: 48, height: 48)

                    VStack(alignment: .leading, spacing: 2) {
                        HStack(spacing: 8) {
                            Text(channel.name)
                                .font(.system(size: 16, weight: .black, design: .rounded))
                                .foregroundStyle(.white.opacity(0.96))
                                .lineLimit(1)
                            Text(channel.number)
                                .font(.system(size: 10, weight: .black, design: .rounded))
                                .foregroundStyle(.white.opacity(0.78))
                                .padding(.horizontal, 7)
                                .frame(height: 19)
                                .background(Capsule().fill(Color.white.opacity(0.07)))
                        }
                        Text([channel.category, channel.source].filter { !$0.isEmpty }.joined(separator: "  •  "))
                            .font(.system(size: 10, weight: .semibold, design: .rounded))
                            .foregroundStyle(.white.opacity(0.42))
                            .lineLimit(1)
                    }

                    Spacer(minLength: 8)

                    HStack(spacing: 6) {
                        Circle().fill(Color.red.opacity(0.94)).frame(width: 6, height: 6)
                        Text("NOW")
                            .font(.system(size: 10, weight: .black, design: .rounded))
                            .tracking(1.2)
                    }
                    .foregroundStyle(.white.opacity(0.88))
                }
                .frame(height: 58)

                HStack(alignment: .center, spacing: 18) {
                    VStack(alignment: .leading, spacing: 6) {
                        Text(title)
                            .font(.system(size: 31, weight: .bold, design: .rounded))
                            .foregroundStyle(.white)
                            .lineLimit(1)
                            .minimumScaleFactor(0.56)

                        HStack(spacing: 8) {
                            Text(start)
                            Rectangle().fill(accent.opacity(0.62)).frame(width: 22, height: 1)
                            Text(end)
                        }
                        .font(.system(size: 13, weight: .bold, design: .rounded))
                        .foregroundStyle(.white.opacity(0.62))

                        Text(description)
                            .font(.system(size: 14, weight: .medium, design: .rounded))
                            .foregroundStyle(.white.opacity(0.55))
                            .lineLimit(2)
                            .minimumScaleFactor(0.76)
                    }
                    .layoutPriority(1)

                    Spacer(minLength: 8)

                    guideHeroProgramArtwork(artURL: currentProgram?.imageURL ?? "", channel: channel)
                        .frame(width: 190, height: 108)
                }
                .frame(maxHeight: .infinity)

                if let nextProgram {
                    HStack(spacing: 8) {
                        Text("UP NEXT")
                            .font(.system(size: 9, weight: .black, design: .rounded))
                            .tracking(1.2)
                            .foregroundStyle(accent.opacity(0.94))
                        Text(nextProgram.startText)
                            .font(.system(size: 10, weight: .bold, design: .rounded))
                            .foregroundStyle(.white.opacity(0.38))
                        Text(nextProgram.title)
                            .font(.system(size: 11, weight: .semibold, design: .rounded))
                            .foregroundStyle(.white.opacity(0.66))
                            .lineLimit(1)
                        Spacer(minLength: 0)
                    }
                    .frame(height: 28)
                }
            }
            .padding(.leading, 15)
            .padding(.trailing, 14)
        }
        .frame(width: width, height: height, alignment: .leading)
        .background(consoleShape.fill(guideThemeSurface))
        .overlay(consoleShape.stroke(Color.white.opacity(guideThemeKey.contains("pure black") ? 0.07 : 0.10), lineWidth: 1))
    }

