    private func livePreviewWindow(channel: LiveTVChannel, program: LiveProgram?, active: Bool) -> some View {
        ZStack(alignment: .bottomLeading) {
            Color.black
            if active,
               let originalStreamURL = URL(string: channel.streamURL),
               !channel.streamURL.isEmpty,
               let streamURL = MediaFlowProxyRouter.playbackURLIfAllowed(for: originalStreamURL, kind: .liveTV) {
                #if canImport(KSPlayer)
                // vBRDC169: Guide preview is an information monitor, not a hero crop.
                // Preserve the complete broadcast frame so score bugs, tickers, captions and
                // edge graphics are never cut off by the unusually wide Guide preview slot.
                KSPlayerVideoSurface(url: streamURL, shouldPlay: true, seekSerial: 0, seekSeconds: 0, seekIsAbsolute: false, reloadToken: 0, startTimeSeconds: 0, externalAudioURL: nil, externalAudioOffsetMS: 0, muteAudio: false, contentMode: .scaleAspectFit, isLiveStream: true, routeHint: "live-guide-preview")
                    .id("live-preview-ks-\(streamURL.absoluteString)")
                    .marksAuxiliaryVideoActivity(true)
                    .allowsHitTesting(false)
                #else
                SilentVideoBackground(url: streamURL, isMuted: false)
                    .id("live-preview-avfallback-\(streamURL.absoluteString)")
                    .marksAuxiliaryVideoActivity(true)
                    .allowsHitTesting(false)
                #endif
            } else if let url = PremiumArtworkURL.url(program?.imageURL ?? ""), !(program?.imageURL ?? "").isEmpty {
                AsyncImage(url: url) { phase in
                    switch phase {
                    case .success(let image):
                        image.resizable().scaledToFit().padding(10)
                    default:
                        Color.black
                    }
                }
            }
            // v348: no text/channel caption on the preview surface. Keep it a plain
            // blended video box so labels do not overlap or look like a second info row.
        }
        .background(Color.black)
        .clipped()
        .clipShape(RoundedRectangle(cornerRadius: 10))
    }

