            ForEach(Array(guideTimeSlots.prefix(4)), id: \.self) { time in
                Text(time)
                    .font(.system(size: 15, weight: time == guideTimeSlots.first ? .bold : .semibold, design: .rounded))
                    .foregroundStyle(time == guideTimeSlots.first ? Color.red.opacity(0.92) : Color.white.opacity(0.58))
                    .frame(width: 260, alignment: .leading)
            }
        }
        .frame(height: 48, alignment: .leading)
        .background(Color.black.opacity(0.98))
