    private func googleGuideTimelineRow(channel: LiveTVChannel, rowWidth: CGFloat) -> some View {
        let isFocused = guideFocus == channel.id
        let programs = Array(liveModel.programs(for: channel).prefix(10))
        let minProgramWidth: CGFloat = 190
        return HStack(spacing: 4) {
            guideStationLane(channel: channel, isFocused: isFocused)
                .frame(width: 220, height: 82)

            ForEach(programs) { program in
                LiveTVGuideScheduleCell(
                    program: program,
                    width: max(minProgramWidth, min(410, program.width * 0.92)),
                    themeAccent: guideThemeAccent,
                    surface: guideThemeSurfaceSecondary,
                    isSelected: isFocused && program.isLive
                )
            }

            if programs.count < 10 {
                ForEach(0..<(10 - programs.count), id: \.self) { _ in
                    LiveTVGuideEmptyScheduleCell(width: 260, themeAccent: guideThemeAccent, surface: guideThemeSurfaceSecondary)
                }
            }
        }
        .frame(width: rowWidth, alignment: .leading)
        .background(isFocused ? guideThemeAccent.opacity(0.035) : Color.clear)
        .contentShape(Rectangle())
        .focusable(true)
        .focused($guideFocus, equals: channel.id)
        .modifier(TransparentTVFocusVisual())
        .onTapGesture {
            guard acceptSingleSelect() else { return }
            selectedChannelID = channel.id
            guideFocus = channel.id
            play(channel: channel)
        }
        .signalVisionPlayPauseCommand {
            guard acceptSingleSelect() else { return }
            selectedChannelID = channel.id
            guideFocus = channel.id
            play(channel: channel)
        }
        .onLongPressGesture(minimumDuration: 0.62) {
            guard channelActionChannelID == nil else { return }
            presentLiveTVChannelActions(for: channel)
        }
        .signalMoveCommand { direction in
            if direction == .left {
                let index = categories.firstIndex(of: selectedCategory) ?? 0
                withAnimation(.easeOut(duration: 0.20)) {
                    guideCategoryRailCollapsed = false
                }
                guideFocus = nil
                guideCategoryHandoffSourceIndex = index
                DispatchQueue.main.async { guideCategoryMenuFocus = index }
            }
        }
    }

    private func guideStationLane(channel: LiveTVChannel, isFocused: Bool) -> some View {
