    // vBRDC171: retired the obsolete full Guide side-rail implementation. The active
    // Guide owns only its compact inline category drop-down; the larger left control panel
    // belongs exclusively to the Live TV grid.

    private func channelCount(for category: String) -> Int {
        // vBRDC124: opening the Live Controls rail must not rescan a 5k–30k provider
        // lineup once for every category label. Reuse the provider-built browse indexes.
        if category == "All" { return liveModel.channels.count }
        if category == "My Favorites" {
            return myFavoriteChannelIDs.reduce(into: 0) { count, channelID in
                if liveModel.channel(id: channelID) != nil { count += 1 }
            }
        }
        if category == "HD" { return liveModel.browseHDChannels().count }
        return liveModel.browseChannels(inExactCategory: category).count
    }

    private func iconForGuideCategory(_ category: String) -> String {
        switch category.lowercased() {
        case "my favorites": return "heart.fill"
        case "favorites": return "star.fill"
        case "movies": return "movieclapper.fill"
        case "sports": return "sportscourt.fill"
        case "news": return "newspaper.fill"
        case "kids": return "face.smiling.fill"
        case "hd": return "tv.fill"
        default: return "rectangle.grid.2x2.fill"
        }
    }

    // vBRDC171: retired the pre-inline legacy Guide side rail / static preview renderer.
    // Keeping dead view trees here made future focus/layout regressions easier to reintroduce.

    private var guideTimeSlots: [String] {
        let calendar = Calendar.current
        let now = Date()
        let minute = calendar.component(.minute, from: now)
        let flooredMinute = minute < 30 ? 0 : 30
        let base = calendar.date(bySettingHour: calendar.component(.hour, from: now), minute: flooredMinute, second: 0, of: now) ?? now
        return (0..<6).compactMap { offset in
            calendar.date(byAdding: .minute, value: offset * 30, to: base)?.formatted(date: .omitted, time: .shortened)
        }
    }

