    private func play(channel: LiveTVChannel) {
        guard let originalURL = URL(string: channel.streamURL), !channel.streamURL.isEmpty else { liveModel.status = "No playable URL for \(channel.name). Configure Channels DVR/M3U/Xtream source."; return }
        gridInteractionRuntime.selectionPersistenceTask?.cancel()
        gridInteractionRuntime.selectionPersistenceTask = nil
        cancelLiveTVGridFocusPreview()
        if liveTVLastSelectedChannelID != channel.id { liveTVLastSelectedChannelID = channel.id }
        LiveTVMemoryAuditManager.shared.beginPlaybackCycle(channelID: channel.id, channelName: channel.name)
        let origin = showGuide
            ? "guide"
            : (liveTVBrowseMode == .list
                ? "list"
                : (selectedCategory == "My Favorites" ? "favorites" : selectedCategory == "All" ? "grid" : "category:\(selectedCategory)"))
        saveLiveTVFocusSnapshot(channel: channel, origin: origin)
        // Phase 3: cancel view-local refresh/restore work before the heavy Live TV
        // hierarchy is removed. The store-owned snapshot is the only state retained.
        liveTVFocusRestoreTask?.cancel()
        liveTVFocusRestoreTask = nil
        liveRefreshTask?.cancel()
        liveForceRefreshTask?.cancel()
        guideHintHideTask?.cancel()
        liveModel.suspendForVODPlayback()
        PremiumRemoteImageLoader.cancelObsoletePrefetches(keeping: [])
        // v347: stop/suppress the KS guide preview before routing into full KS Live TV playback.
        // This keeps the preview surface from continuing audio while the full channel opens.
        previewPlaybackSuppressed = true
        gridInteractionRuntime.guidePreviewWarmupGeneration &+= 1
        previewChannelID = nil
        store.liveQuickPanelOpen = false
        let program = liveModel.currentProgram(for: channel)
        let programTitle = (program?.title ?? channel.now).trimmingCharacters(in: .whitespacesAndNewlines)
        let programDescription = (program?.description ?? channel.description).trimmingCharacters(in: .whitespacesAndNewlines)
        let timeLine = [program?.startText ?? "Now", program?.endText ?? ""].filter { !$0.isEmpty }.joined(separator: " - ")
        let smartDescription = [programTitle, timeLine, programDescription].filter { !$0.isEmpty }.joined(separator: "\n")
        let item = MediaItem(id: "live-\(channel.id)-\(channel.streamURL.hashValue)", title: channel.name, year: "Live", type: "live", catalog: channel.source, description: smartDescription.ifEmpty(channel.description), genres: [channel.category, channel.source, timeLine].filter { !$0.isEmpty }, rating: "", posterURL: (program?.imageURL ?? "").ifEmpty(channel.iconURL), landscapeURL: program?.imageURL, logoURL: channel.iconURL, previewURL: nil)
        let routeLabel = "Live TV direct stream: \(channel.name) • \(channel.logo) • \(channel.tvgID) • \(programTitle.ifEmpty(channel.now)) • \(channel.source) • \(channel.number) • Live TV route"
        let cbsProfile = LiveTVCBSChannelsDVRProfile.profile(for: channel, routeLabel: routeLabel) ?? LiveTVCBSChannelsDVRProfile.profile(for: originalURL, channelName: channel.name, logo: channel.logo, tvgID: channel.tvgID, source: channel.source, number: channel.number, routeLabel: routeLabel)
        let finalPlaybackURL = cbsProfile?.finalURL ?? originalURL
        let finalPlaybackLabel = cbsProfile.map { routeLabel + " • \($0.debugLabel)" } ?? routeLabel
        Task { @MainActor in
            // vBRDC105: a grid/guide preview is an auxiliary decoder owner. Destroy it and
            // honor the existing short decoder handoff only when needed; normal channel taps
            // with no preview remain immediate. This prevents the 15-second preview from ever
            // competing with full-screen Live TV startup.
            await waitForAuxiliaryVideoHandoffIfNeeded(reason: "Live TV grid/guide preview → full playback")
            guard store.playbackURL == nil,
                  store.liveTVFocusSnapshot?.playedChannelID == channel.id else { return }
            liveModel.prepareForFullScreenPlayback()
            // vBRDC099: capture exact currently visible Live TV pixels before playbackURL removes
            // the root. RootView's playback observer is the ONE destructive Live TV suspension
            // owner; do not clear this cache a second time here.
            LiveTVBoundedArtworkLoader.prepareForFullScreenPlayback(reason: "Live TV playback entry")
            PremiumRemoteImageLoader.releaseDecodedArtworkForLiveTVPlayback()
            store.startPlayback(item: item, url: finalPlaybackURL, alternates: [], subtitles: [], label: finalPlaybackLabel)
        }
    }

