// vBRDC165: focused Live TV grid preview restores channel audio. The parent LiveTVScreen owns
// the exact 3-second arm and user-selected wall-clock lifetime; this leaf owns the
// decoder/audio surface and is created for one focused channel at a time.
private struct LiveTVGridFocusPreviewSurface: View {
    let url: URL

    var body: some View {
        ZStack {
            Color.black
            #if canImport(KSPlayer)
            // vBRDC296: restore the live-compatible preview surface. The three-second dwell
            // gate above prevents this decoder from being created during remote navigation.
            KSPlayerVideoSurface(
                url: url,
                shouldPlay: true,
                seekSerial: 0,
                seekSeconds: 0,
                seekIsAbsolute: false,
                reloadToken: 0,
                startTimeSeconds: 0,
                externalAudioURL: nil,
                externalAudioOffsetMS: 0,
                muteAudio: false,
                contentMode: .scaleAspectFill,
                isLiveStream: true,
                routeHint: "live-grid-focus-preview"
            )
            .id("live-grid-focus-preview-\(url.absoluteString)")
            .marksAuxiliaryVideoActivity(true)
            #else
            SilentVideoBackground(url: url, isMuted: false)
                .id("live-grid-focus-preview-fallback-\(url.absoluteString)")
                .marksAuxiliaryVideoActivity(true)
            #endif
        }
        .brightness(0.045)
        .contrast(1.035)
    }
}

// Full TV-screen confirmation: the selected candidate is not applied until explicit Apply.
// Siri Remote Back/Exit cancels without modifying the persisted value.
private struct SignalLiveTVThemeConfirmationScreen: View {
    @Binding var candidate: String
    @Binding var effectCandidate: String
    @Binding var sizeCandidate: String
    @Binding var typographyCandidate: String
    @Binding var selectedTypography: String
    @Binding var selectedTheme: String
    @Binding var selectedEffect: String
    @Binding var selectedSize: String
    @Binding var isPresented: Bool
    @FocusState private var nextFocused: Bool

    var body: some View {
        ZStack {
            Color.black.ignoresSafeArea()
            VStack(alignment: .leading, spacing: 15) {
                HStack(spacing: 16) {
                    Text("LIVE TV • CARD CUSTOMIZATION")
                        .font(.system(size: 27, weight: .semibold))
                    Spacer(minLength: 12)
                    Button("Shape: \(SignalLiveTVCardTheme.normalized(candidate))") {
                        candidate = SignalLiveTVCardTheme.next(candidate)
                    }.focused($nextFocused)
                    Button("Effect: \(SignalLiveTVCardEffect.normalized(effectCandidate))") {
                        effectCandidate = SignalLiveTVCardEffect.next(effectCandidate)
                    }
                    Button("Size: \(SignalLiveTVCardSize.normalized(sizeCandidate))") {
                        sizeCandidate = SignalLiveTVCardSize.next(sizeCandidate)
                    }
                    Button("Font: \(SignalLiveTVCardTypography.normalized(typographyCandidate))") {
                        typographyCandidate = SignalLiveTVCardTypography.next(typographyCandidate)
                    }
                }
                .font(.system(size: 16, weight: .medium))
                .foregroundStyle(.white)
                .buttonStyle(.bordered)
                .frame(width: 1600)

                // This is the production card renderer with real cached channels/EPG data.
                // A deterministic demo fallback is only used before a real lineup exists.
                SignalLiveTVDashboardConfirmation(shape: candidate, effect: effectCandidate, cardSize: sizeCandidate, typography: typographyCandidate)
                    .frame(width: 1500, height: 785)
                    .frame(width: 1600)

                HStack(spacing: 22) {
                    Text("Dual faces inward; Split adds a center gutter. Strong variants increase the 3D depth.")
                        .font(.system(size: 16, weight: .regular))
                        .foregroundStyle(.white.opacity(0.70))
                    Spacer()
                    Button("Cancel") { isPresented = false }
                    Button("Apply to Live TV") {
                        selectedTheme = SignalLiveTVCardTheme.normalized(candidate)
                        selectedEffect = SignalLiveTVCardEffect.normalized(effectCandidate)
                        selectedSize = SignalLiveTVCardSize.normalized(sizeCandidate)
                        selectedTypography = SignalLiveTVCardTypography.normalized(typographyCandidate)
                        isPresented = false
                    }
                }
                .buttonStyle(.borderedProminent)
                .frame(width: 1600)
            }
        }
        .onAppear { nextFocused = true }
        .signalVisionExitCommand { isPresented = false }
    }
}

// Shared production card renderer, real stored channel identities/EPG, real Live TV logo,
// stable non-interactive grid. No independent card mockup or second focus/navigation engine.
private struct SignalLiveTVDashboardConfirmation: View {
    let shape: String
    let effect: String
    let cardSize: String
    let typography: String
    @State private var cachedChannels: [LiveTVChannel] = []
    @AppStorage("liveTVAnimatedHeaderLogoStyleV1") private var logoStyle: String = "Signal TV"
    @AppStorage("liveTVGridThemePreset") private var background: String = "Classic Dark"
    @AppStorage("liveTVCardArtworkStyle") private var artworkStyle: String = "frosted"
    @AppStorage("liveTVGridProgramProgressEnabled") private var showProgress: Bool = true
    @AppStorage("liveTVGridFocusRingColorV1") private var ringColor: String = "White"
    @AppStorage("liveTVGridFocusRingMotionV1") private var ringMotion: String = "Classic Glow"
    @AppStorage("liveTVChannelNumberPositionV1") private var numberPosition: String = "Top Right"
    @AppStorage("signalChromeLogoSizeV346") private var logoSize: String = "Small"

    private var channels: [LiveTVChannel] {
        Array((cachedChannels.isEmpty ? LiveTVScreen.sampleChannels : cachedChannels).prefix(12))
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 14) {
            SignalLiveTVMirrorHeader(
                category: "All",
                channelCount: cachedChannels.isEmpty ? 12 : cachedChannels.count,
                logoStyle: logoStyle,
                showLiveLogo: true,
                liveLogoActive: false,
                accent: .orange
            ) {
                Text("GRID   ▦")
                    .font(.system(size: 17, weight: .medium))
                    .padding(.horizontal, 18).padding(.vertical, 11)
                    .background(RoundedRectangle(cornerRadius: 13).fill(Color.white.opacity(0.10)))
            }
            .padding(.horizontal, 34)

            VStack(spacing: 17) {
                ForEach(0..<3, id: \.self) { row in
                    HStack(spacing: 23) {
                        ForEach(0..<4, id: \.self) { column in
                            if ["Split Inward", "Split Inward Strong"].contains(SignalLiveTVCardEffect.normalized(effect)) && column == 2 {
                                Color.clear.frame(width: 39, height: 1)
                                    .accessibilityHidden(true)
                            }
                            if row * 4 + column < channels.count {
                                previewTile(channels[row * 4 + column], columnIndex: column)
                                    .frame(maxWidth: .infinity)
                            } else {
                                Color.clear.frame(maxWidth: .infinity, minHeight: 183)
                            }
                        }
                    }
                }
            }
            .padding(.horizontal, 34)
            Spacer(minLength: 0)
            SignalLiveTVMirrorFooter(channelName: channels.first?.name ?? "LIVE TV") {
                Text("CATEGORIES     GUIDE     OPTIONS")
                    .font(.system(size: 13, weight: .medium)).tracking(1)
            }
            .padding(.horizontal, 34)
        }
        .padding(.vertical, 16)
        .frame(width: 1500, height: 785)
        .background(LiveTVGridBackgroundThemeView(theme: background, accent: .orange, showGuide: false))
        .clipShape(RoundedRectangle(cornerRadius: 18))
        .allowsHitTesting(false)
        .onAppear {
            // Read existing shared snapshots once, not on every theme selection or focus tick.
            cachedChannels = LiveTVSourceModel.cachedRealAmbientChannels(limit: 48)
        }
        .accessibilityLabel("Live TV dashboard preview: shape \(shape), effect \(effect), size \(cardSize)")
    }

    private func previewTile(_ channel: LiveTVChannel, columnIndex: Int) -> some View {
        let focused = channel.id == channels.first?.id
        return LiveTVGridFocusMotionHost(
            isFocused: focused,
            gridLockedMode: false,
            firstColumn: false,
            dimmed: false,
            previewPopOut: false,
            accent: channel.accent,
            cardTheme: shape,
            cardEffect: effect,
            cardSize: cardSize,
            columnIndex: columnIndex
        ) {
            LiveTVGridTileContent(
                channel: channel,
                isFocused: focused,
                program: LiveTVSourceModel.cachedAmbientProgram(for: channel),
                nextProgram: nil,
                previewURL: nil,
                loadArtwork: !cachedChannels.isEmpty,
                artworkRefreshToken: 0,
                gridLockedMode: false,
                fullCardArtwork: artworkStyle == "full",
                showProgramProgress: showProgress,
                progressTick: 0,
                focusRingColor: ringColor,
                focusRingMotion: ringMotion,
                channelNumberPosition: numberPosition,
                cardHeight: 183,
                cardTheme: shape,
                cardTypography: typography
            )
            .equatable()
        }
        .frame(height: 183)
    }
}

private struct LiveTVGridTileContent: View, Equatable {
    let channel: LiveTVChannel
    let isFocused: Bool
    let program: LiveProgram?
    let nextProgram: LiveProgram?
    let previewURL: URL?
    let loadArtwork: Bool
    let artworkRefreshToken: Int
    let gridLockedMode: Bool
    let fullCardArtwork: Bool
    let showProgramProgress: Bool
    let progressTick: Int
    let focusRingColor: String
    let focusRingMotion: String
    let channelNumberPosition: String
    let cardHeight: CGFloat
    let cardTheme: String
    let cardTypography: String
    private var theme: String { SignalLiveTVCardTheme.normalized(cardTheme) }
    private var radius: CGFloat { SignalLiveTVCardTheme.radius(theme) }

    var body: some View {
        GeometryReader { geo in
            let stageShape = RoundedRectangle(cornerRadius: radius, style: .continuous)
            ZStack(alignment: .bottomLeading) {
                // vBRDC143: fixed-page cards no longer need a per-card drawingGroup. The
                // artwork remains one static plane while only the focused outer host moves.
                LiveTVGridTileArtwork(channel: channel, program: program, loadArtwork: loadArtwork, refreshToken: artworkRefreshToken, gridLockedMode: gridLockedMode, fullCardArtwork: fullCardArtwork)
                    .frame(width: artworkWidth(geo.size.width), height: artworkHeight(geo.size.height))
                    .clipShape(RoundedRectangle(cornerRadius: max(2, radius - 7), style: .continuous))
                    .frame(width: geo.size.width, height: geo.size.height, alignment: artworkAlignment)
                    .clipped()

                if let previewURL, isFocused {
                    LiveTVGridFocusPreviewSurface(url: previewURL)
                        .frame(width: geo.size.width, height: geo.size.height)
                        .clipped()
                        .allowsHitTesting(false)
                }

                // The lower broadcast shelf replaces the old flat card treatment without
                // introducing Material blur or continuous animation on twelve cards.
                LinearGradient(
                    colors: [Color.clear, Color.black.opacity(0.10), Color.black.opacity(0.90)],
                    startPoint: .top,
                    endPoint: .bottom
                )
                .allowsHitTesting(false)

                LiveTVGridTileFooter(channel: channel, isFocused: isFocused, program: program, nextProgram: nextProgram, channelNumberPosition: channelNumberPosition, cardTheme: theme, typography: cardTypography)
                    .frame(width: geo.size.width, height: 78, alignment: .bottom)

                LiveTVGridBroadcastChrome(channel: channel, isFocused: isFocused, position: channelNumberPosition)

                if showProgramProgress, isFocused, let program, program.hasRealTiming {
                    TimelineView(.periodic(from: Date(), by: 1.0)) { context in
                        LiveTVProgramProgressLine(
                            progress: program.progress(at: context.date),
                            isFocused: true,
                            width: geo.size.width - 32,
                            tick: progressTick
                        )
                    }
                    .padding(.horizontal, 16)
                    .padding(.bottom, 5)
                    .frame(width: geo.size.width, height: geo.size.height, alignment: .bottom)
                    .allowsHitTesting(false)
                }
            }
            .frame(width: geo.size.width, height: geo.size.height, alignment: .center)
            .background(Color.black.opacity(0.62))
            .clipShape(stageShape)
            .overlay { if theme == "Original UNITY" { baseTileBorder } }
            .overlay(alignment: .top) {
                if isFocused && theme == "Original UNITY" {
                    LinearGradient(
                        colors: [Color.white.opacity(0.20), Color.white.opacity(0.025), Color.clear],
                        startPoint: .top,
                        endPoint: .bottom
                    )
                    .frame(height: 58)
                    .clipShape(stageShape)
                    .allowsHitTesting(false)
                }
            }
            .overlay {
                if isFocused {
                    LiveTVGridFocusRingOverlay(
                        colorName: focusRingColor,
                        motionName: focusRingMotion,
                        cornerRadius: radius
                    )
                }
            }
        }
        .aspectRatio(gridLockedMode ? 1.22 : (16.0 / 9.0), contentMode: .fit)
        .frame(height: gridLockedMode ? 340 : cardHeight)
    }

    private func artworkWidth(_ width: CGFloat) -> CGFloat { width }
    private func artworkHeight(_ height: CGFloat) -> CGFloat { height }
    private var artworkAlignment: Alignment { .center }
    private var footerHeight: CGFloat { 78 }
    private func footerWidth(_ width: CGFloat) -> CGFloat { width }
    private var baseTileBorder: some View {
        RoundedRectangle(cornerRadius: 24, style: .continuous)
            .stroke(
                LinearGradient(
                    colors: [Color.white.opacity(isFocused ? 0.24 : 0.10), Color.white.opacity(0.025)],
                    startPoint: .topLeading,
                    endPoint: .bottomTrailing
                ),
                lineWidth: isFocused ? 1.35 : 1
            )
    }
}

private struct LiveTVGridBroadcastChrome: View {
    let channel: LiveTVChannel
    let isFocused: Bool
    let position: String

    private var normalizedPosition: String {
        LiveTVChannelNumberPosition.normalized(position)
    }

    private var badge: some View {
        Text(channel.number)
            .font(.system(size: 13, weight: .black, design: .rounded))
            .foregroundStyle(.white.opacity(0.94))
            .padding(.horizontal, 10)
            .frame(height: 26)
            .background(
                RoundedRectangle(cornerRadius: 9, style: .continuous)
                    .fill(Color.black.opacity(isFocused ? 0.64 : 0.50))
                    .overlay(
                        RoundedRectangle(cornerRadius: 9, style: .continuous)
                            .stroke(Color.white.opacity(isFocused ? 0.14 : 0.07), lineWidth: 1)
                    )
            )
    }

    var body: some View {
        Group {
            if normalizedPosition != "Off" {
                HStack {
                    Spacer(minLength: 8)
                    badge
                }
                .padding(.horizontal, 12)
                .padding(.top, normalizedPosition == "Top Right" ? 11 : 0)
                .padding(.bottom, normalizedPosition == "Bottom Right" ? 48 : 0)
                .frame(
                    maxHeight: .infinity,
                    alignment: normalizedPosition == "Bottom Right" ? .bottomTrailing : .topTrailing
                )
            }
        }
        .allowsHitTesting(false)
    }
}

private struct LiveTVGridTileArtwork: View {
    let channel: LiveTVChannel
    let program: LiveProgram?
    let loadArtwork: Bool
    let refreshToken: Int
    let gridLockedMode: Bool
    let fullCardArtwork: Bool

    @StateObject private var artworkLoader = LiveTVBoundedArtworkLoader()
    // vBRDC095: the persistent UNITY root owns the last successfully requested artwork
    // identity independently from whether background loading is currently allowed. This is
    // presentation state, not a request trigger: covered catalog/sports surfaces can freeze
    // the exact recent Live TV pixels without keeping network/decode work active.
    @State private var retainedArtworkSource: ArtworkSource? = nil

    private enum ArtworkSource: Equatable {
        case program(URL)
        case provider(URL)

        var url: URL {
            switch self {
            case .program(let url), .provider(let url): return url
            }
        }
    }

    // vBRDC002: every potentially large Live TV grid bitmap now flows through the same
    // display-sized ImageIO decoder. The v1172 fallback path still used AsyncImage for
    // provider/channel artwork, which could decode an original-size provider image beside
    // the new bounded Gracenote image path and re-create long-session pressure.
    private var candidateArtworkSource: ArtworkSource? {
        // vBRDC178: bounded high-cost artwork and channel identity remain independent owners.
        // Gracenote/program art stays preferred here; channel identity is handled by the
        // dedicated immediate-publication logo cache below and cannot be blocked by this ladder.
        if let url = PremiumArtworkURL.url(program?.imageURL), !artworkLoader.failedURLs.contains(url) {
            return .program(url)
        }
        if let url = providerChannelPosterURL, !artworkLoader.failedURLs.contains(url) {
            return .provider(url)
        }
        return nil
    }

    private var candidateArtworkURL: URL? { candidateArtworkSource?.url }

    private var resolvedArtworkSource: ArtworkSource? {
        // Prefer whichever source actually owns the retained decoded bitmap. That keeps the
        // exact card image visible while a new program image is being decoded and, critically,
        // while Catalog covers the grid and loadArtwork becomes false.
        if let imageURL = artworkLoader.imageURL, artworkLoader.image != nil {
            if let candidate = candidateArtworkSource, candidate.url == imageURL { return candidate }
            if let retained = retainedArtworkSource, retained.url == imageURL { return retained }
        }
        return loadArtwork ? candidateArtworkSource : retainedArtworkSource
    }

    var body: some View {
        GeometryReader { geo in
            ZStack(alignment: .center) {
                programArtBackground(size: geo.size)
                    .frame(width: geo.size.width, height: geo.size.height)
                    .clipped()
                LinearGradient(colors: [.black.opacity(0.02), .black.opacity(0.24)], startPoint: .center, endPoint: .bottom)
            }
            .frame(width: geo.size.width, height: geo.size.height)
            .clipped()
        }
        .onAppear { synchronizeArtworkRequest() }
        .onChange(of: candidateArtworkURL) { _ in
            guard loadArtwork else { return }
            synchronizeArtworkRequest()
        }
        .onChange(of: loadArtwork) { _ in
            synchronizeArtworkRequest()
        }
        .onChange(of: fullCardArtwork) { _ in
            // Same URL, different display decode size: re-evaluate the existing owner.
            synchronizeArtworkRequest()
        }
        .onChange(of: refreshToken) { _ in
            // A guide refresh may update program artwork while this LazyVGrid tile remains
            // physically mounted. Re-evaluate the existing loader instead of requiring the
            // user to scroll far enough for SwiftUI to recreate the card. Also clear failures
            // from the previous network generation: a cold-start DNS/TLS miss is not proof
            // that this Gracenote URL is permanently bad.
            guard loadArtwork else { return }
            artworkLoader.resetFailedURLsForAuthoritativeRefresh()
            synchronizeArtworkRequest()
        }
        .onChange(of: artworkLoader.imageURL) { newValue in
            guard let newValue, artworkLoader.image != nil else { return }
            if let candidate = candidateArtworkSource, candidate.url == newValue {
                retainedArtworkSource = candidate
            }
        }
        .onChange(of: artworkLoader.failedURLs) { _ in
            // Advance the fallback ladder immediately after a genuine request failure.
            // This removes any dependency on a LazyVGrid remount/scroll to try the logo.
            guard loadArtwork else { return }
            synchronizeArtworkRequest()
        }
        .onDisappear { artworkLoader.cancel() }
    }

    @MainActor
    private func synchronizeArtworkRequest() {
        guard loadArtwork else {
            // Do not call load(nil): that path intentionally clears the loader's UIImage.
            // Covered UNITY surfaces need request work suspended while the last real card
            // pixels remain mounted beneath the catalog.
            artworkLoader.suspendPreservingImage()
            return
        }
        guard let candidate = candidateArtworkSource else {
            retainedArtworkSource = nil
            artworkLoader.load(nil, maxPixelSize: 512)
            return
        }

        if artworkLoader.image == nil || artworkLoader.imageURL == nil {
            retainedArtworkSource = candidate
        }
        artworkLoader.load(
            candidate.url,
            maxPixelSize: fullCardArtwork ? 768 : 512,
            preserveCurrentImage: true,
            allowImmediatePublication: false
        )
    }

    @ViewBuilder
    private func programArtBackground(size: CGSize) -> some View {
        if let source = resolvedArtworkSource {
            if let image = artworkLoader.image, artworkLoader.imageURL == source.url {
                switch source {
                case .program:
                    programImageLayers(image: image, size: size)
                case .provider:
                    ZStack {
                        gradientBackground
                        boundedPosterImageLayers(image: image, size: size, foregroundPadding: 0)
                    }
                }
            } else {
                channelIdentityFallback(size: size)
            }
        } else {
            channelIdentityFallback(size: size)
        }
    }

    @ViewBuilder
    private func channelIdentityFallback(size: CGSize) -> some View {
        ZStack {
            gradientBackground
            if loadArtwork,
               let iconURL = PremiumArtworkURL.url(channel.iconURL),
               !channel.iconURL.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                // vBRDC178: one bounded owner now owns both the real logo and its text fallback.
                // Do not keep generated channel letters underneath a transparent PNG; that was
                // capable of making a real network logo look doubled while scrolling.
                LiveTVChannelLogoBackdrop(
                    url: iconURL,
                    fallbackText: channel.logo,
                    size: size
                )
            } else {
                generatedChannelPoster
            }
        }
    }

    @ViewBuilder
    private func programImageLayers(image: UIImage, size: CGSize) -> some View {
        if fullCardArtwork {
            // vBRDC346: fill without stretching the source aspect ratio. Crop only excess
            // outside the fixed 16:9 card, retaining a sharp ImageIO-decoded frame.
            ZStack {
                Color.black.opacity(0.92)
                Image(uiImage: image)
                    .resizable()
                    .interpolation(.high)
                    .antialiased(true)
                    .scaledToFill()
                    .frame(width: size.width, height: size.height)
                    .clipped()
            }
        } else {
            // Preserve the v857 Frosted Edges presentation: blurred fill behind the full,
            // uncropped aspect-fit foreground. Both layers reuse one decoded UIImage.
            ZStack {
                Color.black.opacity(0.88)
                Image(uiImage: image)
                    .resizable()
                    .interpolation(.high)
                    .antialiased(true)
                    .scaledToFill()
                    .frame(width: size.width, height: size.height)
                    .clipped()
                    .blur(radius: 10)
                    .opacity(0.48)
                    .saturation(1.10)
                Image(uiImage: image)
                    .resizable()
                    .interpolation(.high)
                    .antialiased(true)
                    .scaledToFit()
                    .frame(width: size.width, height: size.height)
                    .clipped()
            }
        }
    }

    private func boundedPosterImageLayers(image: UIImage, size: CGSize, foregroundPadding: CGFloat) -> some View {
        ZStack {
            Image(uiImage: image)
                .resizable()
                .interpolation(.high)
                .antialiased(true)
                .scaledToFill()
                .frame(width: size.width, height: size.height)
                .clipped()
                .blur(radius: foregroundPadding > 0 ? 18 : 10)
                .opacity(foregroundPadding > 0 ? 0.26 : 0.48)
            Image(uiImage: image)
                .resizable()
                .interpolation(.high)
                .antialiased(true)
                .scaledToFit()
                .padding(foregroundPadding)
                .frame(width: size.width, height: size.height)
                .shadow(color: .black.opacity(0.65), radius: 12, y: 5)
        }
    }

    private var providerChannelPosterURL: URL? {
        // v539: Xtream should use the actual current programme as the Gracenotes-style replacement key.
        // Only block provider lookup when the Xtream EPG did not provide a real programme title; otherwise
        // ask the backend for a TMDB/Fanart/TVDB now-playing poster/backdrop and keep channel logo fallback.
        let currentTitle = (program?.title ?? channel.now).trimmingCharacters(in: .whitespacesAndNewlines)
        if currentTitle.isEmpty { return nil }
        let sourceKey = channel.source.lowercased()
        // v888: HDHomeRun/Gracenotes artwork is still unreliable after the rollback.
        // For HDHomeRun sources, skip now-playing artwork lookup entirely and fall back
        // to the stable channel logo card only.
        if sourceKey.contains("hdhomerun") || sourceKey.contains("hd home") || sourceKey.contains("hdhr") {
            return nil
        }
        if sourceKey.contains("xtream") {
            let lower = currentTitle.lowercased()
            if currentTitle.caseInsensitiveCompare(channel.name) == .orderedSame || lower == "no information" || lower == "no guide data" || lower == "unknown" {
                return nil
            }
        }
        let configuredBase = (UserDefaults.standard.string(forKey: "backendBaseURL") ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .trimmingCharacters(in: CharacterSet(charactersIn: "/"))
        let base = configuredBase.isEmpty ? "https://api.skylinejay187.it.com" : configuredBase
        guard var comps = URLComponents(string: base + "/api/artwork/now-playing") else { return nil }
        comps.queryItems = [
            URLQueryItem(name: "channel", value: channel.name),
            URLQueryItem(name: "program", value: currentTitle),
            URLQueryItem(name: "tvgId", value: channel.tvgID),
            URLQueryItem(name: "number", value: channel.number),
            URLQueryItem(name: "source", value: channel.source),
            URLQueryItem(name: "type", value: "tv")
        ]
        return comps.url
    }

    private var generatedChannelPoster: some View {
        VStack(spacing: 10) {
            Text(channel.logo)
                .font(.system(size: channel.logo.count > 6 ? 26 : 38, weight: .black, design: .rounded))
                .foregroundStyle(.white.opacity(0.92))
                .lineLimit(1)
                .minimumScaleFactor(0.32)
            Text(channel.name)
                .font(.system(size: 14, weight: .heavy, design: .rounded))
                .foregroundStyle(.white.opacity(0.72))
                .lineLimit(1)
                .minimumScaleFactor(0.55)
        }
        .padding(.horizontal, 24)
        .shadow(color: .black.opacity(0.72), radius: 8, y: 3)
    }

    private var gradientBackground: some View {
        RoundedRectangle(cornerRadius: 4)
            .fill(
                LinearGradient(
                    colors: [Color.black.opacity(0.78), channel.accent.opacity(0.34), Color.black.opacity(0.90)],
                    startPoint: .topLeading,
                    endPoint: .bottomTrailing
                )
            )
    }
}


private struct LiveTVGridTileFooter: View {
    let channel: LiveTVChannel
    let isFocused: Bool
    let program: LiveProgram?
    let nextProgram: LiveProgram?
    let channelNumberPosition: String
    let cardTheme: String
    let typography: String

    private var footerChannelIcon: some View {
        // vBRDC108: a provider/Gracenote logo and the generated text logo are mutually
        // exclusive. The previous resident text underlay leaked through transparent PNGs
        // (for example History), producing a real logo plus duplicate generic letters.
        // RemoteImageFit now exposes text only after a real URL is unavailable/failed.
        LiveTVChannelLogoArtwork(
            url: PremiumArtworkURL.url(channel.iconURL),
            fallbackText: channel.logo,
            maxPixelSize: 160,
            contentPadding: 0,
            fallbackFont: .system(size: channel.logo.count > 6 ? 12 : 16, weight: .black, design: .rounded)
        )
    }

    private func focusedTimelineSummary(at now: Date) -> String {
        var parts: [String] = []
        let remaining = LiveTVTimelineFormatter.remaining(program, at: now)
        if !remaining.isEmpty { parts.append(remaining) }
        if let nextProgram {
            let startsIn = LiveTVTimelineFormatter.startsIn(nextProgram, at: now)
            let start = nextProgram.startText.ifEmpty("soon")
            let timing = [start, startsIn].filter { !$0.isEmpty }.joined(separator: " • ")
            parts.append("Next \(timing) • \(nextProgram.title)")
        }
        return parts.joined(separator: "  •  ")
    }

    var body: some View {
        HStack(spacing: 11) {
            footerChannelIcon
                .frame(width: 42, height: 27, alignment: .leading)
                .shadow(color: .black.opacity(0.82), radius: 3, y: 1)
            VStack(alignment: .leading, spacing: 2) {
                Text(program?.title ?? channel.now)
                    .font(SignalLiveTVCardTypography.title(typography, focused: isFocused))
                    .tracking(-0.15)
                    .lineLimit(1)
                    .minimumScaleFactor(0.55)
                    .shadow(color: .black.opacity(0.90), radius: 4, y: 2)

                HStack(spacing: 7) {
                    Text(channel.name)
                        .font(SignalLiveTVCardTypography.secondary(typography))
                        .foregroundStyle(.white.opacity(0.70))
                        .lineLimit(1)
                        .minimumScaleFactor(0.55)
                    if isFocused && channel.source != "Theme Preview" {
                        Circle()
                            .fill(Color.white.opacity(0.34))
                            .frame(width: 3, height: 3)
                        TimelineView(.periodic(from: Date(), by: 1.0)) { context in
                            Text(focusedTimelineSummary(at: context.date))
                        }
                        .font(.system(size: 9, weight: .bold, design: .rounded))
                        .foregroundStyle(.white.opacity(0.58))
                        .lineLimit(1)
                        .minimumScaleFactor(0.50)
                    }
                }
            }
            Spacer(minLength: 0)
        }
        .foregroundStyle(.white.opacity(0.98))
        .padding(.leading, 16)
        .padding(.trailing, LiveTVChannelNumberPosition.normalized(channelNumberPosition) == "Bottom Right" ? 86 : 16)
        .padding(.bottom, 13)
        .frame(height: 74, alignment: .bottomLeading)
    }
}


// v1103: read-only Catalog Health rows participate in the tvOS focus chain so
// the containing ScrollView advances through every provider, failure, and row option.
private struct CatalogHealthPassiveFocusModifier: ViewModifier {
    let cornerRadius: CGFloat
    @FocusState private var isFocused: Bool

    func body(content: Content) -> some View {
        let shape = RoundedRectangle(cornerRadius: cornerRadius, style: .continuous)
        content
            .contentShape(shape)
            .focusable(true)
            .focused($isFocused)
            .signalVisionFocusEffectPolicy()
            .scaleEffect(isFocused ? 1.008 : 1.0)
            .overlay(
                shape.stroke(
                    isFocused ? Color.orange.opacity(0.88) : Color.clear,
                    lineWidth: isFocused ? 2.5 : 0
                )
            )
            .animation(.easeOut(duration: 0.16), value: isFocused)
    }
}


