// v983: one window-level Select hold recognizer for the Live TV grid. Attaching
// to the window lets UIKit observe the focused remote press without making an
// invisible overlay focusable or changing the card's existing tap/DPAD path.
private struct LiveTVSelectHoldMonitor: UIViewRepresentable {
    let minimumDuration: TimeInterval
    let isEnabled: Bool
    let onRecognized: () -> Void
    let onEnded: () -> Void

    func makeCoordinator() -> Coordinator {
        Coordinator(
            minimumDuration: minimumDuration,
            isEnabled: isEnabled,
            onRecognized: onRecognized,
            onEnded: onEnded
        )
    }

    func makeUIView(context: Context) -> WindowAttachmentView {
        let view = WindowAttachmentView(frame: .zero)
        view.backgroundColor = .clear
        view.isUserInteractionEnabled = false
        view.windowDidChange = { [weak coordinator = context.coordinator] window in
            coordinator?.attach(to: window)
        }
        DispatchQueue.main.async { [weak view, weak coordinator = context.coordinator] in
            coordinator?.attach(to: view?.window)
        }
        return view
    }

    func updateUIView(_ uiView: WindowAttachmentView, context: Context) {
        context.coordinator.update(
            minimumDuration: minimumDuration,
            isEnabled: isEnabled,
            onRecognized: onRecognized,
            onEnded: onEnded
        )
        context.coordinator.attach(to: uiView.window)
    }

    static func dismantleUIView(_ uiView: WindowAttachmentView, coordinator: Coordinator) {
        uiView.windowDidChange = nil
        coordinator.detach()
    }

    final class WindowAttachmentView: UIView {
        var windowDidChange: ((UIWindow?) -> Void)?

        override func didMoveToWindow() {
            super.didMoveToWindow()
            windowDidChange?(window)
        }
    }

    final class Coordinator: NSObject, UIGestureRecognizerDelegate {
        private weak var installedView: UIView?
        private var isEnabled: Bool
        private var onRecognized: () -> Void
        private var onEnded: () -> Void
        private let recognizer: UILongPressGestureRecognizer

        init(
            minimumDuration: TimeInterval,
            isEnabled: Bool,
            onRecognized: @escaping () -> Void,
            onEnded: @escaping () -> Void
        ) {
            self.isEnabled = isEnabled
            self.onRecognized = onRecognized
            self.onEnded = onEnded
            self.recognizer = UILongPressGestureRecognizer()
            super.init()
            recognizer.minimumPressDuration = minimumDuration
            recognizer.cancelsTouchesInView = false
            recognizer.delaysTouchesBegan = false
            recognizer.delaysTouchesEnded = false
            recognizer.delegate = self
            recognizer.addTarget(self, action: #selector(handleLongPress(_:)))
#if os(tvOS)
            recognizer.allowedPressTypes = [NSNumber(value: UIPress.PressType.select.rawValue)]
#endif
        }

        func update(
            minimumDuration: TimeInterval,
            isEnabled: Bool,
            onRecognized: @escaping () -> Void,
            onEnded: @escaping () -> Void
        ) {
            recognizer.minimumPressDuration = minimumDuration
            self.isEnabled = isEnabled
            self.onRecognized = onRecognized
            self.onEnded = onEnded
        }

        func attach(to view: UIView?) {
            if let current = installedView, let view, current === view { return }
            if installedView == nil && view == nil { return }
            installedView?.removeGestureRecognizer(recognizer)
            installedView = view
            view?.addGestureRecognizer(recognizer)
        }

        func detach() {
            installedView?.removeGestureRecognizer(recognizer)
            installedView = nil
        }

        @objc private func handleLongPress(_ gesture: UILongPressGestureRecognizer) {
            switch gesture.state {
            case .began:
                guard isEnabled else { return }
                onRecognized()
            case .ended, .cancelled, .failed:
                onEnded()
            default:
                break
            }
        }

        func gestureRecognizerShouldBegin(_ gestureRecognizer: UIGestureRecognizer) -> Bool {
            isEnabled
        }

        func gestureRecognizer(
            _ gestureRecognizer: UIGestureRecognizer,
            shouldRecognizeSimultaneouslyWith otherGestureRecognizer: UIGestureRecognizer
        ) -> Bool {
            true
        }

        deinit {
            detach()
        }
    }
}

