struct ProviderBrandMark: View {
    let title: String
    var compact: Bool = false
    var presentation: CatalogRowPresentation? = nil

    private var normalized: String { title.trimmingCharacters(in: .whitespacesAndNewlines) }
    private var key: String { normalized.lowercased() }
    private var displayTitle: String { normalized.isEmpty ? "Catalog" : normalized }

    private func color(from hex: String?) -> Color? {
        guard var value = hex?.trimmingCharacters(in: .whitespacesAndNewlines), !value.isEmpty else { return nil }
        if value.hasPrefix("#") { value.removeFirst() }
        guard value.count == 6, let raw = Int(value, radix: 16) else { return nil }
        return Color(
            red: Double((raw >> 16) & 0xff) / 255.0,
            green: Double((raw >> 8) & 0xff) / 255.0,
            blue: Double(raw & 0xff) / 255.0
        )
    }

    private var accent: Color {
        if let themed = color(from: presentation?.theme?.accentHex) { return themed }
        if key.contains("prime") || key.contains("amazon") { return Color(red: 0.00, green: 0.66, blue: 1.00) }
        if key.contains("disney") { return Color(red: 0.28, green: 0.52, blue: 1.00) }
        if key.contains("netflix") { return Color(red: 0.90, green: 0.02, blue: 0.05) }
        if key.contains("hulu") { return Color(red: 0.11, green: 0.88, blue: 0.38) }
        if key == "max" || key.contains("hbo") { return Color(red: 0.43, green: 0.30, blue: 1.00) }
        if key.contains("apple") { return .white }
        if key.contains("paramount") { return Color(red: 0.05, green: 0.32, blue: 0.95) }
        if key.contains("peacock") { return Color(red: 0.98, green: 0.76, blue: 0.20) }
        if key.contains("starz") { return .white }
        return .white
    }

    private var usesThemedPresentation: Bool {
        presentation?.theme != nil || presentation?.themeLogoURL?.isEmpty == false || presentation?.providerName?.isEmpty == false
    }

    private var isKnownProvider: Bool {
        presentation?.rowKind == "provider" ||
        key.contains("prime") || key.contains("amazon") || key.contains("disney") ||
        key.contains("netflix") || key.contains("hulu") || key == "max" ||
        key.contains("hbo") || key.contains("apple") || key.contains("paramount") ||
        key.contains("peacock") || key.contains("starz")
    }

    var body: some View {
        HStack(spacing: compact ? 7 : 10) {
            Capsule()
                .fill(
                    LinearGradient(
                        colors: [Color.white.opacity(compact ? 0.36 : 0.66), accent.opacity(compact ? 0.56 : 0.92)],
                        startPoint: .top,
                        endPoint: .bottom
                    )
                )
                .frame(width: compact ? 3 : 4, height: compact ? 18 : 24)
                .shadow(color: accent.opacity(compact ? 0.10 : 0.28), radius: compact ? 4 : 8)

            Text(displayTitle)
                .font(.system(
                    size: compact ? (isKnownProvider ? 22 : 20) : (isKnownProvider ? 31 : 27),
                    weight: .black,
                    design: .rounded
                ))
                .kerning(key.contains("netflix") ? 1.6 : (usesThemedPresentation ? 0.8 : 0.4))
                .foregroundStyle(usesThemedPresentation || isKnownProvider ? accent : Color.white.opacity(compact ? 0.78 : 0.96))
                .lineLimit(1)
                .minimumScaleFactor(0.70)
                .shadow(color: accent.opacity(compact ? 0.08 : 0.16), radius: compact ? 5 : 10, y: 2)
        }
        .accessibilityLabel(displayTitle)
    }
}

