@MainActor
final class SportsLiveZoneModel: ObservableObject {
    @Published var ticker: [String] = ["Loading public sports ticker…"]
    @Published var liveNow: [SportsLiveEvent] = []
    @Published var today: [SportsLiveEvent] = []
    @Published var upcoming: [SportsLiveEvent] = []
    @Published var favoriteTeams: [SportsLiveTeam] = []
    @Published var sportsOnlyChannels: [SportsLiveEvent] = []
    @Published var highlights: [SportsLiveEvent] = []
    @Published var commandCenter: [SportsLiveEvent] = []
    @Published var theaterMode: [SportsLiveEvent] = []
    @Published var heatMap: [SportsLiveEvent] = []
    @Published var ppvEvents: [SportsLiveEvent] = []
    @Published var status: String = "Sports Live Zone warming up public data…"

    var favoriteTeamCards: [SportsLiveEvent] {
        tickerFavoritesManager.favoriteTeamCards(from: favoriteTeams)
    }

    private var loaded = false
    private var loadGeneration: UInt64 = 0
    private let scoresProvider = SportsScoresScheduleProvider.shared
    private let tickerFavoritesManager = SportsTickerFavoriteTeamsManager.shared
    private let sportsKeywords = ["sport", "sports", "ppv", "event", "events", "redzone", "nfl", "nba", "mlb", "nhl", "soccer", "football", "basketball", "baseball", "hockey", "ufc", "mma", "boxing", "wwe", "aew", "wrestling", "tennis", "golf", "f1", "formula", "racing", "nascar", "espn", "fs1", "fs2", "bein", "sky sports", "tnt sports", "dazn", "fubo", "nbcsn", "ppv"]

    func load(favoriteTeams rawFavorites: String, xtreamAccounts rawAccounts: String, customSources rawSportsSources: String = "") async {
        guard !VODExclusivePlaybackGate.isActive, !loaded else { return }
        loaded = true
        loadGeneration &+= 1
        let generation = loadGeneration
        status = "Loading schedules, team art, and scoreboards…"
        async let sportsDBEvents = scoresProvider.loadSportsDBToday()
        async let espnEvents = scoresProvider.loadESPNScores()
        async let teamArt = tickerFavoritesManager.loadFavoriteTeams(rawFavorites)
        async let highlightFeed = loadSportsHighlights()
        async let customSportsChannels = loadSportsOnlyM3USources(rawSportsSources)
        let (dbEvents, scoreEvents, teams, highlightEvents, channels) = await (sportsDBEvents, espnEvents, teamArt, highlightFeed, customSportsChannels)
        guard !Task.isCancelled, !VODExclusivePlaybackGate.isActive, generation == loadGeneration else {
            loaded = false
            return
        }
        // vBRDC102 UNITY Frame Runtime: sports network work may finish at any time, but
        // its multi-rail @Published payload must never land in the same frame as Siri
        // Remote navigation or a cross-surface handoff. One shared lane now owns the
        // publication point for every Sports theme/rail while preserving the visuals.
        guard await UnityFrameRuntime.shared.waitUntilPermittedDurably(.interactiveMetadata),
              !Task.isCancelled,
              !VODExclusivePlaybackGate.isActive,
              generation == loadGeneration else {
            loaded = false
            return
        }
        favoriteTeams = teams
        sportsOnlyChannels = channels
        highlights = highlightEvents
        let combined = scoreEvents + dbEvents
        ppvEvents = makePPVEvents(from: combined + channels)
        commandCenter = makeCommandCenter(events: combined, favorites: teams, channels: channels, ppv: ppvEvents)
        theaterMode = makeTheaterModes(events: combined, channels: channels)
        heatMap = makeSportsHeatMap(events: combined, highlights: highlightEvents, channels: channels)
        liveNow = combined.filter { event in
            let s = event.status.lowercased()
            return s.contains("live") || s.contains("in progress") || s.contains("halftime") || s.contains("period") || s.contains("quarter")
        }
        today = combined.isEmpty ? tickerFavoritesManager.fallbackTodayEvents(favoriteTeams: rawFavorites) : Array(combined.prefix(18))
        upcoming = Array((dbEvents + fallbackUpcomingEvents()).prefix(18))
        if highlights.isEmpty { highlights = fallbackHighlights() }
        ticker = tickerFavoritesManager.makeTicker(events: combined, favorites: teams, channels: channels)
        status = "Command Center ready • \(today.count) today • \(liveNow.count) live • \(ppvEvents.count) PPV/event cards"
    }

    func suspendForVODPlayback() {
        loadGeneration &+= 1
        loaded = false
    }

    // vBRDC081: leaving Sports invalidates all in-flight score/highlight/custom-source
    // publications before the destination grid starts reclaiming MainActor/focus ownership.
    // vBRDC091: also drop Sports-only presentation payloads immediately. SwiftUI may retain
    // the outgoing branch briefly during a tab handoff, so relying on deinit alone can keep
    // hundreds of event/card strings and artwork URLs resident while Home starts scrolling.
    func suspendForSurfaceExit() {
        loadGeneration &+= 1
        loaded = false
        ticker.removeAll(keepingCapacity: false)
        liveNow.removeAll(keepingCapacity: false)
        today.removeAll(keepingCapacity: false)
        upcoming.removeAll(keepingCapacity: false)
        favoriteTeams.removeAll(keepingCapacity: false)
        sportsOnlyChannels.removeAll(keepingCapacity: false)
        highlights.removeAll(keepingCapacity: false)
        commandCenter.removeAll(keepingCapacity: false)
        theaterMode.removeAll(keepingCapacity: false)
        heatMap.removeAll(keepingCapacity: false)
        ppvEvents.removeAll(keepingCapacity: false)
        status = "Sports surface released"
    }

    // v777: Sports score/schedule network fetching moved to SportsScoresScheduleProvider.

    // v778: Favorite-team lookup and ticker generation moved to SportsTickerFavoriteTeamsManager.

    private func loadSportsOnlyXtreamChannels(_ rawAccounts: String) async -> [SportsLiveEvent] {
        // Normal Xtream/M3U imports stay in Live TV. Automatic sports routing remains backlogged.
        return []
    }

    private func loadSportsOnlyM3USources(_ raw: String) async -> [SportsLiveEvent] {
        let urls = raw.components(separatedBy: CharacterSet(charactersIn: "\n,"))
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty && ($0.lowercased().hasPrefix("http://") || $0.lowercased().hasPrefix("https://")) }
        guard !urls.isEmpty else { return [] }
        var output: [SportsLiveEvent] = []
        for (idx, rawURL) in urls.prefix(6).enumerated() {
            guard !Task.isCancelled else { break }
            guard let url = URL(string: rawURL), let text = await fetchText(url, maxBytes: 3_000_000) else { continue }
            guard !Task.isCancelled else { break }
            output += parseSportsM3U(text, sourceIndex: idx, trustSportsOnlySource: true)
            if output.count >= 300 { break }
        }
        return Array(output.prefix(300))
    }

    private func parseSportsM3U(_ text: String, sourceIndex: Int, trustSportsOnlySource: Bool = false) -> [SportsLiveEvent] {
        var output: [SportsLiveEvent] = []
        let lines = text.components(separatedBy: .newlines)
        var pendingName = "Sports Channel"
        var pendingLogo: String? = nil
        var pendingGroup = "Sports Only"
        var hasPendingEXTINF = false

        for (lineIndex, rawLine) in lines.enumerated() {
            if lineIndex.isMultiple(of: 256), Task.isCancelled { break }
            let line = rawLine.trimmingCharacters(in: .whitespacesAndNewlines)
            if line.hasPrefix("#EXTINF") {
                pendingName = Self.extinfName(line)
                pendingLogo = Self.attribute("tvg-logo", in: line)
                pendingGroup = Self.attribute("group-title", in: line) ?? "Sports Only"
                hasPendingEXTINF = true
            } else if line.lowercased().hasPrefix("http") {
                let haystack = "\(pendingName) \(pendingGroup)".lowercased()
                let looksSports = sportsKeywords.contains(where: { haystack.contains($0) })
                // Settings labels these sources Sports-only. Trust that explicit user
                // classification instead of silently dropping generic PPV/event names.
                if trustSportsOnlySource || looksSports {
                    let title = hasPendingEXTINF ? pendingName : "Sports Channel \(output.count + 1)"
                    output.append(SportsLiveEvent(
                        id: "sports-m3u-\(sourceIndex)-\(output.count)-\(title)",
                        title: title,
                        subtitle: pendingGroup,
                        league: "Sports M3U",
                        status: "Watch Live",
                        artworkURL: pendingLogo,
                        accent: .cyan,
                        streamURL: line
                    ))
                }
                pendingName = "Sports Channel"
                pendingLogo = nil
                pendingGroup = "Sports Only"
                hasPendingEXTINF = false
                if output.count >= 250 { break }
            }
        }
        return output
    }


    private func loadSportsHighlights() async -> [SportsLiveEvent] {
        // v549: public/free highlight foundation. ScoreBat covers global soccer highlights;
        // fallback cards keep every major sport represented until each provider plugin is enabled.
        guard let url = URL(string: "https://www.scorebat.com/video-api/v3/") else { return [] }
        guard let root = await fetchJSON(url), let response = root["response"] as? [[String: Any]] else { return [] }
        return response.prefix(14).enumerated().map { idx, item in
            let title = item["title"] as? String ?? "Soccer Highlight"
            let competition = ((item["competition"] as? [String: Any])?["name"] as? String) ?? "Soccer Highlights"
            let thumb = item["thumbnail"] as? String
            let matchURL = item["matchviewUrl"] as? String
            return SportsLiveEvent(id: "scorebat-highlight-\(idx)-\(title)", title: title, subtitle: "Video highlight ready", league: competition, status: "Highlight", artworkURL: thumb, accent: .purple, webURL: matchURL)
        }
    }

    private func fallbackHighlights() -> [SportsLiveEvent] {
        ["NFL", "NBA", "MLB", "NHL", "Soccer", "UFC", "Boxing", "WWE", "AEW", "TNA", "NJPW", "F1", "NASCAR", "Tennis", "Golf"].enumerated().map { idx, league in
            SportsLiveEvent(id: "fallback-highlight-\(idx)", title: "\(league) Highlights", subtitle: "Highlight rail ready", league: league, status: "Highlight", artworkURL: nil, accent: .purple)
        }
    }

    private func makePPVEvents(from events: [SportsLiveEvent]) -> [SportsLiveEvent] {
        let ppvWords = ["ppv", "pay per view", "ufc", "boxing", "fight", "wwe", "aew", "tna", "njpw", "mania", "slam", "title", "event"]
        let matched = events.filter { event in
            let haystack = "\(event.title) \(event.subtitle) \(event.league) \(event.status)".lowercased()
            return ppvWords.contains(where: { haystack.contains($0) })
        }
        if !matched.isEmpty {
            return Array(matched.prefix(18)).map { event in
                SportsLiveEvent(id: "ppv-\(event.id)", title: event.title, subtitle: event.subtitle.ifEmpty("Event card"), league: event.league, status: "PPV / Event", artworkURL: event.artworkURL, accent: .red)
            }
        }
        return ["UFC / Fight Night", "Boxing PPV", "WWE Premium Live Event", "AEW PPV", "TNA Special Event", "NJPW Event", "Big Game Events"].enumerated().map { idx, title in
            SportsLiveEvent(id: "fallback-ppv-\(idx)", title: title, subtitle: "Add sports-only M3U or manual sports channels to light up this card", league: "PPV", status: "Event Watch", artworkURL: nil, accent: .red)
        }
    }

    private func makeCommandCenter(events: [SportsLiveEvent], favorites: [SportsLiveTeam], channels: [SportsLiveEvent], ppv: [SportsLiveEvent]) -> [SportsLiveEvent] {
        let liveCount = events.filter { $0.status.lowercased().contains("live") || $0.status.lowercased().contains("progress") }.count
        let startingSoon = events.filter { $0.status.lowercased().contains("pre") || $0.status.lowercased().contains("scheduled") }.count
        return [
            SportsLiveEvent(id: "command-live", title: "What Matters Right Now", subtitle: "\(liveCount) live • \(startingSoon) starting soon", league: "Command Center", status: "Pulse", artworkURL: nil, accent: .green),
            SportsLiveEvent(id: "command-ppv", title: "PPV / Event Watch", subtitle: "\(ppv.count) fight, wrestling, and big-event cards", league: "Events", status: "PPV", artworkURL: nil, accent: .red),
            SportsLiveEvent(id: "command-teams", title: "My Team Intelligence", subtitle: favorites.isEmpty ? "Choose favorite teams to unlock dashboards" : "\(favorites.count) favorite team dashboard(s)", league: "My Teams", status: "Priority", artworkURL: favorites.first?.badgeURL, accent: .yellow),
            SportsLiveEvent(id: "command-sources", title: "Sports Sources", subtitle: channels.isEmpty ? "Sports-only M3U ready" : "\(channels.count) sports-only channel cards", league: "Sources", status: "Channels", artworkURL: channels.first?.artworkURL, accent: .cyan)
        ]
    }

    private func makeTheaterModes(events: [SportsLiveEvent], channels: [SportsLiveEvent]) -> [SportsLiveEvent] {
        let active = events.prefix(5).map { event in
            SportsLiveEvent(id: "theater-\(event.id)", title: "Theater: \(event.title)", subtitle: "Scores • highlights • channels • alerts", league: event.league, status: "Theater", artworkURL: event.artworkURL, accent: .orange)
        }
        if !active.isEmpty { return Array(active) }
        return ["NFL Sunday", "NBA Night", "Fight Night", "Wrestling Night", "Race Day", "Soccer Saturday"].enumerated().map { idx, title in
            SportsLiveEvent(id: "fallback-theater-\(idx)", title: title, subtitle: "Multi-panel sports cockpit foundation", league: "Theater Mode", status: "Preview", artworkURL: channels.first?.artworkURL, accent: .orange)
        }
    }

    private func makeSportsHeatMap(events: [SportsLiveEvent], highlights: [SportsLiveEvent], channels: [SportsLiveEvent]) -> [SportsLiveEvent] {
        let leagues = ["NFL", "NBA", "MLB", "NHL", "Soccer", "NCAA", "UFC", "Boxing", "Wrestling", "F1", "NASCAR", "Tennis", "Golf", "PPV"]
        return leagues.map { league in
            let score = events.filter { $0.league.localizedCaseInsensitiveContains(league) || $0.title.localizedCaseInsensitiveContains(league) }.count
                + highlights.filter { $0.league.localizedCaseInsensitiveContains(league) || $0.title.localizedCaseInsensitiveContains(league) }.count
                + channels.filter { $0.title.localizedCaseInsensitiveContains(league) || $0.subtitle.localizedCaseInsensitiveContains(league) }.count
            let bars = String(repeating: "█", count: max(1, min(10, score + 1)))
            return SportsLiveEvent(id: "heat-\(league)", title: "\(league) Heat", subtitle: bars, league: "Activity Map", status: score > 0 ? "Active" : "Ready", artworkURL: nil, accent: score > 0 ? .green : .blue)
        }
    }

    private func fallbackUpcomingEvents() -> [SportsLiveEvent] {
        ["NFL", "NBA", "MLB", "NHL", "Soccer", "NCAA", "UFC", "Boxing", "WWE", "AEW", "TNA", "NJPW", "F1", "NASCAR", "Tennis", "Golf"].enumerated().map { idx, league in
            SportsLiveEvent(id: "fallback-upcoming-\(idx)", title: "\(league) Upcoming", subtitle: "Schedule rail ready", league: league, status: "Upcoming", artworkURL: nil, accent: .blue)
        }
    }

    private func fetchJSON(_ url: URL) async -> [String: Any]? {
        var req = URLRequest(url: url, timeoutInterval: 10)
        req.setValue("application/json,*/*", forHTTPHeaderField: "Accept")
        req.setValue("DebridChannels-tvOS/560", forHTTPHeaderField: "User-Agent")
        do {
            let (data, response) = try await URLSession.shared.data(for: req)
            guard ((response as? HTTPURLResponse)?.statusCode ?? 200) < 400 else { return nil }
            return try JSONSerialization.jsonObject(with: data) as? [String: Any]
        } catch { return nil }
    }

    private func fetchText(_ url: URL, maxBytes: Int) async -> String? {
        do {
            let data: Data
            let statusCode: Int
            if url.scheme?.lowercased() == "http" {
                let plain = try await PlainHTTPClient.fetchData(from: url, accept: "audio/x-mpegurl,text/plain,*/*", userAgent: "DebridChannels-tvOS/560", maxBytes: maxBytes, timeout: 12)
                data = plain.data
                statusCode = plain.statusCode
            } else {
                var req = URLRequest(url: url, timeoutInterval: 12)
                req.setValue("audio/x-mpegurl,text/plain,*/*", forHTTPHeaderField: "Accept")
                req.setValue("DebridChannels-tvOS/560", forHTTPHeaderField: "User-Agent")
                let (sessionData, response) = try await URLSession.shared.data(for: req)
                data = sessionData
                statusCode = (response as? HTTPURLResponse)?.statusCode ?? 200
            }
            guard statusCode < 400 else { return nil }
            return String(data: Data(data.prefix(maxBytes)), encoding: .utf8)
        } catch { return nil }
    }

    private static func dayString(_ date: Date) -> String {
        let f = DateFormatter()
        f.dateFormat = "yyyy-MM-dd"
        return f.string(from: date)
    }

    private static func normalizeServer(_ raw: String) -> String {
        var clean = raw.trimmingCharacters(in: .whitespacesAndNewlines).trimmingCharacters(in: CharacterSet(charactersIn: "/"))
        if !clean.lowercased().hasPrefix("http://") && !clean.lowercased().hasPrefix("https://") { clean = "http://" + clean }
        return clean
    }

    private static func attribute(_ name: String, in line: String) -> String? {
        guard let range = line.range(of: "\(name)=\"") else { return nil }
        let rest = line[range.upperBound...]
        guard let end = rest.firstIndex(of: "\"") else { return nil }
        return String(rest[..<end])
    }

    private static func extinfName(_ line: String) -> String {
        if let comma = line.lastIndex(of: ",") { return String(line[line.index(after: comma)...]).trimmingCharacters(in: .whitespacesAndNewlines) }
        return attribute("tvg-name", in: line) ?? "Sports Channel"
    }
}

struct SportsHubScreen: View {
    @EnvironmentObject var store: CatalogStore
    @EnvironmentObject var unityCore: UnityAppCore
    @AppStorage("sportsCustomSourcesJSON") private var sportsCustomSourcesJSON: String = ""
    @AppStorage("sportsFavoriteTeams") private var sportsFavoriteTeams: String = ""
    @AppStorage("sportsScoreTickerEnabled") private var sportsScoreTickerEnabled: Bool = false
    @AppStorage("liveXtreamAccounts") private var liveXtreamAccounts: String = ""
    @StateObject private var liveZone = SportsLiveZoneModel()
    @StateObject private var sportsCenterVM = SportsCenterViewModel()
    @AppStorage("sportsAssignedGroups") private var sportsAssignedGroupsRaw: String = ""
    @AppStorage("sportsManualChannelIds") private var sportsManualChannelIdsRaw: String = ""
    @AppStorage("sportsExcludedChannelIds") private var sportsExcludedChannelIdsRaw: String = ""
    @AppStorage("sportsExcludedChannelNames") private var sportsExcludedChannelNamesRaw: String = ""
    @StateObject private var sportsAsyncRuntime = SportsAsyncTaskRuntime()
    private var sportsSurfaceLoadTask: Task<Void, Never>? {
            get { sportsAsyncRuntime.sportsSurfaceLoadTask }
            nonmutating set { sportsAsyncRuntime.sportsSurfaceLoadTask = newValue }
        }
    private var sportsRowsRefreshTask: Task<Void, Never>? {
            get { sportsAsyncRuntime.sportsRowsRefreshTask }
            nonmutating set { sportsAsyncRuntime.sportsRowsRefreshTask = newValue }
        }
    @State private var sportsSurfaceActive: Bool = false

    var body: some View {
        // v808: Sports now uses the same one-row-at-a-time quick-panel architecture as Movies/Shows.
        // Only the active Sports row is visible; Down/Up swaps rows instead of stacking all Sports rows.
        SportsFoundationQuickPanelSurface(
            rows: sportsFoundationRows(),
            sourceStatus: liveZone.status.ifEmpty(sportsCenterVM.sourceStatus)
        )
        .onAppear {
            sportsSurfaceActive = true
            store.liveQuickPanelOpen = false
            store.topMenuFocusLocked = true
            store.contentFocusToken &+= 1
            // vBRDC091: Sports reads the process-wide retained Live TV snapshot directly.
            // Do not instantiate a second LiveTVSourceModel, duplicate thousands of channel
            // structs, rebuild its browse indexes, or retain another guide dictionary merely
            // to classify Sports rows.
            refreshSportsRows()
            startSportsSurfaceWork()
        }
        .signalVisionExitCommand { closeSportsQuickPanel() }
        .onDisappear {
            stopSportsSurfaceWork(reason: "Sports disappeared")
        }
        .onChange(of: sportsAssignedGroupsRaw) { _, _ in
            refreshSportsRows()
        }
        .onChange(of: sportsManualChannelIdsRaw) { _, _ in
            refreshSportsRows()
        }
        .onChange(of: sportsExcludedChannelIdsRaw) { _, _ in
            refreshSportsRows()
        }
        .onChange(of: sportsExcludedChannelNamesRaw) { _, _ in
            refreshSportsRows()
        }
        .onChange(of: sportsCustomSourcesJSON) { _, _ in
            guard sportsSurfaceActive, unityCore.isRuntimeOwner(.sports) else { return }
            liveZone.suspendForSurfaceExit()
            startSportsSurfaceWork()
        }
        .onChange(of: unityCore.effectiveSurface) { _, surface in
            if surface == .sports {
                guard !sportsSurfaceActive else { return }
                sportsSurfaceActive = true
                refreshSportsRows()
                startSportsSurfaceWork()
            } else if sportsSurfaceActive {
                stopSportsSurfaceWork(reason: "UNITY owner moved to \(surface.rawValue)")
            }
        }
    }

    @MainActor
    private func startSportsSurfaceWork() {
        sportsSurfaceLoadTask?.cancel()
        sportsSurfaceLoadTask = Task { @MainActor in
            await liveZone.load(
                favoriteTeams: sportsFavoriteTeams,
                xtreamAccounts: liveXtreamAccounts,
                customSources: sportsCustomSourcesJSON
            )
            guard !Task.isCancelled, sportsSurfaceActive, unityCore.isRuntimeOwner(.sports) else { return }
            refreshSportsRows()
            sportsSurfaceLoadTask = nil
        }
    }

    @MainActor
    private func stopSportsSurfaceWork(reason: String) {
        guard sportsSurfaceActive || sportsSurfaceLoadTask != nil else { return }
        sportsSurfaceActive = false
        sportsSurfaceLoadTask?.cancel()
        sportsSurfaceLoadTask = nil
        sportsRowsRefreshTask?.cancel()
        sportsRowsRefreshTask = nil
        liveZone.suspendForSurfaceExit()
        sportsCenterVM.releaseForSurfaceExit()
        PremiumRemoteImageLoader.releaseTransientSurfaceResources(domain: .sports, reason: reason)
        print("[UNITY Lifecycle][Sports] outgoing work invalidated reason=\(reason)")
    }

    private func refreshSportsRows() {
        sportsRowsRefreshTask?.cancel()

        // The first retained snapshot is pre-bound before Sports becomes visibly interactive,
        // so its existing UNITY theme never opens onto an empty rail. Later rebuilds yield to
        // active Siri Remote geometry instead of mapping hundreds of Live TV channels mid-scroll.
        if sportsCenterVM.sportsRows.isEmpty {
            rebuildSportsRowsNow()
            return
        }

        sportsRowsRefreshTask = Task { @MainActor in
            guard await UnityFrameRuntime.shared.waitUntilPermittedDurably(.interactiveMetadata),
                  !Task.isCancelled,
                  sportsSurfaceActive,
                  unityCore.isRuntimeOwner(.sports) else {
                sportsRowsRefreshTask = nil
                return
            }
            rebuildSportsRowsNow()
            sportsRowsRefreshTask = nil
        }
    }

    private func rebuildSportsRowsNow() {
        let retainedChannels = LiveTVSourceModel.cachedRealAmbientChannels(limit: 600)
        sportsCenterVM.refresh(
            channels: retainedChannels,
            assignedGroupsRaw: sportsAssignedGroupsRaw,
            manualChannelIdsRaw: sportsManualChannelIdsRaw,
            excludedChannelIdsRaw: sportsExcludedChannelIdsRaw,
            excludedChannelNamesRaw: sportsExcludedChannelNamesRaw
        ) { channel in
            LiveTVSourceModel.cachedAmbientProgram(for: channel)
        }
    }

    private func sportsFoundationRows() -> [MediaRow] {
        let liveEvents = Array((liveZone.liveNow + liveZone.today + liveZone.commandCenter + liveZone.upcoming).prefix(18))
        let liveItems = liveEvents.isEmpty
            ? [sportsPlaceholderItem(id: "sports-live-placeholder", title: "Live & Upcoming Games", subtitle: liveZone.status.ifEmpty("Sports scores and upcoming games will appear here."), symbolHint: "Live")]
            : liveEvents.enumerated().map { idx, event in sportsMediaItem(from: event, rowID: "live-upcoming", index: idx) }

        // v1154: Sports channel rows must contain the real live MediaItems, not an
        // intermediate league/category summary card. The summary cards had type="sports"
        // and no stream URL, which forced M3U channels into VOD Media Information.
        // Keeping the original classifier rows exposes every automatic/manual sports M3U
        // assignment as an immediately playable type="live" card.
        let leagueRows = sportsCenterVM.sportsRows
        let channelRows: [MediaRow] = leagueRows.enumerated().map { idx, row in
            let slug = row.0.lowercased().replacingOccurrences(of: " ", with: "-")
            return MediaRow(
                id: "sports-channels-\(idx)-\(slug)",
                title: row.0,
                items: Array(row.1.prefix(row.0 == "Live Sports Channels" ? 48 : 36))
            )
        }

        let favoriteNames = sportsFavoriteTeams
            .split(separator: "|")
            .map { String($0).trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
        let favoriteItems: [MediaItem] = favoriteNames.isEmpty
            ? [sportsPlaceholderItem(id: "sports-favorite-teams-placeholder", title: "Favorite Teams", subtitle: "Add favorite teams in Settings to build this Sports row.", symbolHint: "Favorites")]
            : favoriteNames.enumerated().map { idx, team in
                MediaItem(
                    id: "sports-favorite-team-\(idx)-\(team.lowercased().replacingOccurrences(of: " ", with: "-"))",
                    title: team,
                    year: "Team",
                    type: "sports",
                    catalog: "Sports",
                    description: "Favorite team row item. Live scores and team widgets arrive in v810.",
                    genres: ["Sports", "Favorite Teams"],
                    rating: "",
                    posterURL: nil,
                    landscapeURL: nil,
                    logoURL: nil,
                    previewURL: nil,
                    addonName: "Favorite Teams",
                    addonIconURL: nil
                )
            }

        let highlightItems: [MediaItem] = liveZone.highlights.isEmpty
            ? [sportsPlaceholderItem(id: "sports-highlights-placeholder", title: "Highlights", subtitle: "Sports highlights will appear here as public feeds return verified clips.", symbolHint: "Highlights")]
            : liveZone.highlights.enumerated().map { idx, event in sportsMediaItem(from: event, rowID: "highlights", index: idx) }

        let sportsNewsItems: [MediaItem] = sportsNewsFallbackItems()

        let removableItems = Array(leagueRows.flatMap { $0.1 }.prefix(18))
        let removeItems: [MediaItem] = removableItems.isEmpty
            ? [sportsPlaceholderItem(id: "sports-remove-channel-placeholder", title: "Remove Channel", subtitle: "Sports channels you add or assign will appear here for quick removal.", symbolHint: "Remove")]
            : removableItems.enumerated().map { idx, item in
                MediaItem(
                    id: "sports-remove-\(idx)-\(item.id)",
                    title: item.title,
                    year: "Remove",
                    type: "sports-remove",
                    catalog: item.catalog,
                    description: "Press Select to remove this channel from Sports without deleting it from Live TV.",
                    genres: ["Sports", "Remove Channel"] + item.genres.prefix(2),
                    rating: "Remove",
                    posterURL: item.posterURL,
                    landscapeURL: item.landscapeURL,
                    logoURL: item.logoURL,
                    previewURL: item.previewURL,
                    addonName: "Remove Channel",
                    addonIconURL: item.addonIconURL
                )
            }

        var result: [MediaRow] = [
            MediaRow(id: "sports-live-upcoming", title: "Live & Upcoming Games", items: liveItems)
        ]
        result.append(contentsOf: channelRows)
        result.append(contentsOf: [
            MediaRow(id: "sports-favorite-teams", title: "Favorite Teams", items: Array(favoriteItems.prefix(18))),
            MediaRow(id: "sports-highlights", title: "Highlights", items: Array(highlightItems.prefix(18))),
            MediaRow(id: "sports-news", title: "Sports News", items: Array(sportsNewsItems.prefix(18))),
            MediaRow(id: "sports-remove-channel", title: "Remove Channel", items: Array(removeItems.prefix(18)))
        ])
        return result
    }

    private func sportsNewsFallbackItems() -> [MediaItem] {
        let newsCards: [(String, String, String)] = [
            ("Top Sports Headlines", "Daily sports news hub ready for live providers.", "Headlines"),
            ("NFL News", "Latest NFL stories and game-day context.", "NFL"),
            ("NBA News", "Latest NBA stories, injuries, trades, and matchup notes.", "NBA"),
            ("MLB News", "Latest MLB scores, standings, and series context.", "MLB"),
            ("NHL News", "Latest NHL game notes and league headlines.", "NHL"),
            ("Soccer News", "Global football headlines and highlight links.", "Soccer"),
            ("Fight Sports News", "UFC, boxing, wrestling, and PPV watchlist.", "Fight")
        ]
        return newsCards.enumerated().map { idx, card in
            MediaItem(
                id: "sports-news-\(idx)-\(card.2.lowercased())",
                title: card.0,
                year: card.2,
                type: "sports",
                catalog: "Sports News",
                description: card.1,
                genres: ["Sports", "News", card.2],
                rating: "News",
                posterURL: nil,
                landscapeURL: nil,
                logoURL: nil,
                previewURL: nil,
                addonName: "Sports News",
                addonIconURL: nil
            )
        }
    }

    private func sportsMediaItem(from event: SportsLiveEvent, rowID: String, index: Int) -> MediaItem {
        MediaItem(
            id: "sports-\(rowID)-\(index)-\(event.id)",
            title: event.title,
            year: event.status,
            type: event.streamURL == nil ? "sports" : "live",
            catalog: "Sports",
            description: event.subtitle.ifEmpty(event.league),
            genres: ["Sports", event.league, event.status].filter { !$0.isEmpty },
            rating: event.status,
            posterURL: event.artworkURL,
            landscapeURL: event.artworkURL,
            logoURL: event.artworkURL,
            previewURL: event.streamURL,
            addonName: event.league.ifEmpty("Sports"),
            addonIconURL: event.artworkURL
        )
    }

    private func sportsPlaceholderItem(id: String, title: String, subtitle: String, symbolHint: String) -> MediaItem {
        MediaItem(
            id: id,
            title: title,
            year: symbolHint,
            type: "sports",
            catalog: "Sports",
            description: subtitle,
            genres: ["Sports", symbolHint],
            rating: "",
            posterURL: nil,
            landscapeURL: nil,
            logoURL: nil,
            previewURL: nil,
            addonName: symbolHint,
            addonIconURL: nil
        )
    }

    private func removeFromSportsSection(_ item: MediaItem) {
        if let channelID = sportsChannelID(from: item) {
            var excluded = intSet(from: sportsExcludedChannelIdsRaw)
            excluded.insert(channelID)
            sportsExcludedChannelIdsRaw = excluded.sorted().map(String.init).joined(separator: ",")

            var manual = intSet(from: sportsManualChannelIdsRaw)
            manual.remove(channelID)
            sportsManualChannelIdsRaw = manual.sorted().map(String.init).joined(separator: ",")
        }

        let normalizedName = normalizedSportsChannelName(item.title)
        if !normalizedName.isEmpty {
            var names = pipeSet(from: sportsExcludedChannelNamesRaw)
            names.insert(normalizedName)
            sportsExcludedChannelNamesRaw = names.sorted().joined(separator: "|")
        }
        store.status = "Removed \(item.title) from Sports Section."
        refreshSportsRows()
    }

    private func sportsChannelID(from item: MediaItem) -> Int? {
        let parts = item.id.split(separator: "-")
        guard parts.count >= 3 else { return nil }
        return Int(parts[2])
    }

    private func intSet(from raw: String) -> Set<Int> {
        Set(raw.split(separator: ",").compactMap { Int($0.trimmingCharacters(in: .whitespacesAndNewlines)) })
    }

    private func pipeSet(from raw: String) -> Set<String> {
        Set(raw.split(separator: "|").map { String($0).trimmingCharacters(in: .whitespacesAndNewlines) }.filter { !$0.isEmpty })
    }

    private func normalizedSportsChannelName(_ value: String) -> String {
        value
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
            .replacingOccurrences(of: "|", with: " ")
    }

    private func closeSportsQuickPanel() {
        stopSportsSurfaceWork(reason: "Sports Back/Exit")
        store.clearSportsPresentationStateForNavigation(reason: "Sports Back/Exit")
        unityCore.select(.live, store: store, reason: "Sports close")
        // clearSportsPresentationState + Root UNITY handoff own the bounded focus tokens.
        // Do not fire a third immediate token from the outgoing Sports tree.
    }
}



struct SportsFoundationQuickPanelSurface: View {
    @EnvironmentObject var store: CatalogStore
    @AppStorage("liveTVGridThemePreset") private var liveTVGridThemePreset: String = "Classic Dark"
    let rows: [MediaRow]
    let sourceStatus: String
    @State private var activeRowIndex: Int = 0
    @State private var selectedIndices: [String: Int] = [:]
    @FocusState private var focusedRow: Int?

    private let gridLeadingInset: CGFloat = 72
    private let gridTrailingInset: CGFloat = 76

    private var safeRowIndex: Int {
        guard !rows.isEmpty else { return 0 }
        return min(max(activeRowIndex, 0), rows.count - 1)
    }

    private var activeRow: MediaRow? {
        guard !rows.isEmpty else { return nil }
        return rows[safeRowIndex]
    }

    private var activeSelectedItem: MediaItem? {
        guard let row = activeRow, !row.items.isEmpty else { return nil }
        let index = min(max(selectedIndices[row.id, default: 0], 0), row.items.count - 1)
        return row.items[index]
    }

    var body: some View {
        GeometryReader { geo in
            let panelWidth = max(1100, geo.size.width - gridLeadingInset - gridTrailingInset)
            let panelHeight = min(geo.size.height * 0.265, 258)
            let cardWidth: CGFloat = 390
            let cardHeight: CGFloat = 220
            let railHeight: CGFloat = 246
            let cardBottomInset: CGFloat = -14
            let rowTop = max(520, geo.size.height - 314)
            let heroTop = max(250, rowTop - 218)

            ZStack(alignment: .topLeading) {
                // vBRDC071: Sports is a true UNITY visual branch now, not only a navigation
                // branch. Hero/artwork presets are resolved through the exact same
                // liveTVGridThemePreset + CatalogArtworkCacheManager flags used by
                // Home/Movies/Shows. The real Live TV root remains mounted underneath.
                sportsUnityThemeBackdrop(size: geo.size, item: activeSelectedItem)

                LinearGradient(
                    colors: [Color.clear, Color.black.opacity(0.14), Color.black.opacity(0.34)],
                    startPoint: .top,
                    endPoint: .bottom
                )
                .frame(width: panelWidth, height: 286)
                .position(x: gridLeadingInset + panelWidth / 2, y: geo.size.height - 143)
                .allowsHitTesting(false)

                if !rows.isEmpty {
                    let row = rows[safeRowIndex]

                    sportsUnityHeroArea(row: row, panelWidth: panelWidth)
                        .frame(width: panelWidth, height: 184, alignment: .leading)
                        .padding(.leading, gridLeadingInset)
                        .padding(.top, heroTop)
                        .allowsHitTesting(false)

                    VStack(alignment: .leading, spacing: 0) {
                        HStack(spacing: 10) {
                            Image(systemName: "sportscourt.fill")
                                .font(.system(size: 15, weight: .black))
                                .foregroundStyle(Color.cyan.opacity(0.90))
                            Text("Sports")
                                .font(.system(size: 18, weight: .black, design: .rounded))
                                .kerning(0.8)
                                .foregroundStyle(.white.opacity(0.96))
                            Text(row.title)
                                .font(.system(size: 13, weight: .bold, design: .rounded))
                                .foregroundStyle(.white.opacity(0.58))
                                .lineLimit(1)
                            Spacer(minLength: 0)
                            Text("\(safeRowIndex + 1)/\(rows.count)")
                                .font(.system(size: 11, weight: .black, design: .rounded))
                                .foregroundStyle(.white.opacity(0.52))
                        }
                        .padding(.leading, 2)
                        .padding(.bottom, -2)

                        GridOSFixedSlotCatalogRail(
                            row: row,
                            rowIndex: safeRowIndex,
                            maxRowIndex: max(rows.count - 1, 0),
                            cardWidth: cardWidth,
                            cardHeight: cardHeight,
                            railHeight: railHeight,
                            cardBottomInset: cardBottomInset,
                            focusedRow: $focusedRow,
                            selectedIndex: Binding(
                                get: { selectedIndices[row.id, default: 0] },
                                set: { selectedIndices[row.id] = $0 }
                            ),
                            onRowMove: { delta in moveSportsRow(delta) },
                            onNavigationActivity: { _ in
                                UnityAnimationCoordinator.shared.registerNavigationActivity(
                                    source: "sports",
                                    settleAfter: 0.22
                                )
                            }
                        )
                        // vBRDC103: Sports shares the same persistent fixed-slot engine as
                        // Home/Movies/Shows; row identity is data, not a remount trigger.
                        .transition(.identity)

                        nextSportsRowTitle(after: safeRowIndex)
                            .padding(.leading, 4)
                            .padding(.top, -4)
                    }
                    .frame(width: panelWidth, height: panelHeight, alignment: .bottomLeading)
                    .padding(.leading, gridLeadingInset)
                    .padding(.top, rowTop)
                }
            }
            .frame(width: geo.size.width, height: geo.size.height, alignment: .topLeading)
            .signalVisionFocusSection()
            .animation(nil, value: activeRowIndex)
            .onAppear { restoreSportsRowFocus() }
            .onChange(of: rows.map(\.id).joined(separator: "|")) { _, _ in
                activeRowIndex = min(activeRowIndex, max(rows.count - 1, 0))
                restoreSportsRowFocus()
            }
        }
    }

    private var sportsUnityThemeFlags: CatalogArtworkCacheManager.ThemeFlags {
        CatalogArtworkCacheManager.themeFlags(for: liveTVGridThemePreset)
    }

    private var sportsUnityHeroThemeActive: Bool {
        sportsUnityThemeFlags.usesArtworkBackground
        || liveTVGridThemePreset.lowercased().contains("pure black")
    }

    @ViewBuilder
    private func sportsUnityThemeBackdrop(size: CGSize, item: MediaItem?) -> some View {
        let flags = sportsUnityThemeFlags
        let key = liveTVGridThemePreset.lowercased()
        if sportsUnityHeroThemeActive {
            ZStack {
                if flags.usesArtwork3Hero || key.contains("pure black") {
                    // Artwork 3 / Pure Black intentionally keep the actual Live TV root
                    // visible, matching the catalog branch contract. Only protective
                    // gradients are added here; no duplicate grid or fake snapshot.
                    Color.black.opacity(flags.usesArtwork3Hero ? 0.18 : 0.34)
                    LinearGradient(
                        colors: [Color.black.opacity(0.92), Color.black.opacity(0.58), Color.black.opacity(0.12)],
                        startPoint: .leading,
                        endPoint: .trailing
                    )
                } else if let item, let artworkURL = CatalogArtworkCacheManager.preferredBackdropURL(for: item) {
                    RemoteImageFit(
                        url: artworkURL,
                        mode: .fill,
                        maxPixelSize: 3840,
                        preservePreviousOnURLChange: true,
                        publishDuringSurfaceHandoff: true,
                        deferHeavyLoadDuringNavigation: true
                    )
                        .frame(width: size.width, height: size.height)
                        .clipped()
                        .opacity(flags.backdropOpacity)
                        .saturation(flags.backdropSaturation)
                        .contrast(flags.backdropContrast)
                        .transition(.identity)
                        .overlay(
                            LinearGradient(
                                colors: flags.usesArtwork2
                                    ? [Color.black.opacity(0.20), Color.black.opacity(0.03), Color.black.opacity(0.22)]
                                    : [Color.black.opacity(0.64), Color.black.opacity(0.10), Color.black.opacity(0.70)],
                                startPoint: .leading,
                                endPoint: .trailing
                            )
                        )
                        .overlay(
                            LinearGradient(
                                colors: [Color.black.opacity(0.30), Color.clear, Color.black.opacity(0.58)],
                                startPoint: .top,
                                endPoint: .bottom
                            )
                        )
                }

                if let item {
                    UnityCatalogHeroAura(item: item, intensity: flags.usesArtwork3Hero ? 0.58 : 0.78)
                }
            }
            .frame(width: size.width, height: size.height)
            .ignoresSafeArea()
            .allowsHitTesting(false)
            .transition(.opacity)
        }
    }

    @ViewBuilder
    private func sportsUnityHeroArea(row: MediaRow, panelWidth: CGFloat) -> some View {
        if sportsUnityHeroThemeActive {
            SportsUnityHeroThemeArea(
                row: row,
                item: activeSelectedItem,
                rowIndex: safeRowIndex,
                rowCount: rows.count,
                sourceStatus: sourceStatus,
                themePreset: liveTVGridThemePreset
            )
            .frame(width: panelWidth, height: 184, alignment: .leading)
        } else {
            SportsHeroWidgetArea(
                row: row,
                item: activeSelectedItem,
                rowIndex: safeRowIndex,
                rowCount: rows.count,
                sourceStatus: sourceStatus
            )
            .frame(width: panelWidth, height: 184, alignment: .leading)
        }
    }

    @ViewBuilder
    private func nextSportsRowTitle(after index: Int) -> some View {
        if index + 1 < rows.count {
            ProviderBrandMark(title: rows[index + 1].title, compact: true)
        } else {
            Text(sourceStatus)
                .font(.system(size: 11, weight: .bold, design: .rounded))
                .foregroundStyle(.white.opacity(0.34))
                .lineLimit(1)
        }
    }

    private func moveSportsRow(_ delta: Int) {
        guard !rows.isEmpty else { return }
        let next = min(max(activeRowIndex + delta, 0), rows.count - 1)
        guard next != activeRowIndex else {
            restoreSportsRowFocus()
            return
        }
        activeRowIndex = next
        restoreSportsRowFocus()
    }

    private func restoreSportsRowFocus() {
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.05) {
            guard !VODExclusivePlaybackGate.isActive else { return }
            focusedRow = safeRowIndex
        }
    }
}

struct SportsUnityHeroThemeArea: View {
