struct SportsMinimalOneRowQuickPanelSurface: View {
    @EnvironmentObject var store: CatalogStore
    let liveGames: [SportsLiveEvent]
    let sourceStatus: String
    @FocusState private var firstFocused: Bool

    private let gridLeadingInset: CGFloat = 72
    private let gridTrailingInset: CGFloat = 76
    private let cardWidth: CGFloat = 330
    private let cardHeight: CGFloat = 176

    private var fallbackEvent: SportsLiveEvent {
        SportsLiveEvent(
            id: "sports-minimal-placeholder",
