struct SportsScratchQuickPanelSurface: View {
    @EnvironmentObject var store: CatalogStore
    let featured: SportsLiveEvent?
    let liveGames: [SportsLiveEvent]
    let upcoming: [SportsLiveEvent]
    let favoriteEvents: [SportsLiveEvent]
    let sportsRows: [(String, [MediaItem])]
    let sourceStatus: String
    let removeChannel: (MediaItem) -> Void
    @FocusState private var heroFocused: Bool

    private let gridLeadingInset: CGFloat = 72
    private let gridTrailingInset: CGFloat = 76

    private var allChannels: [MediaItem] { Array(sportsRows.flatMap { $0.1 }.prefix(24)) }
    private var leagueChannels: [MediaItem] {
        Array(sportsRows
            .filter { !$0.0.localizedCaseInsensitiveContains("live sports") }
            .flatMap { $0.1 }
            .prefix(24))
    }
    private var leagueDisplayChannels: [MediaItem] {
        let source = leagueChannels.isEmpty ? allChannels : leagueChannels
        return Array(source.prefix(24))
    }
    private var highlightsTrending: [SportsLiveEvent] {
        Array((liveGames + upcoming + favoriteEvents).prefix(18))
    }
    private var sportsNewsItems: [SportsLiveEvent] {
        let source = upcoming.isEmpty ? liveGames : upcoming
        return Array(source.prefix(18))
    }
    private var primaryChannel: MediaItem? { allChannels.first }
    private var primaryEvent: SportsLiveEvent {
        featured ?? liveGames.first ?? upcoming.first ?? SportsLiveEvent(
            id: "sports-quick-panel-placeholder",
            title: "Live Sports",
            subtitle: "Scores, upcoming games, and sports channels stay on this quick panel.",
            league: "DC Sports",
            status: "Ready",
            artworkURL: primaryChannel?.landscapeURL ?? primaryChannel?.posterURL ?? primaryChannel?.logoURL,
            accent: .red,
            streamURL: primaryChannel?.previewURL
        )
    }

    var body: some View {
        GeometryReader { geo in
            let panelWidth = max(1100, geo.size.width - gridLeadingInset - gridTrailingInset)
            ZStack(alignment: .topLeading) {
                LinearGradient(
                    colors: [Color.black.opacity(0.32), Color.black.opacity(0.18), Color.black.opacity(0.46)],
                    startPoint: .top,
                    endPoint: .bottom
                )
                .ignoresSafeArea()
                .allowsHitTesting(false)

                ScrollView(.vertical, showsIndicators: false) {
                    VStack(alignment: .leading, spacing: 20) {
                        SportsScratchQuickPanelHero(event: primaryEvent, channel: primaryChannel, sourceStatus: sourceStatus)
                            .frame(width: panelWidth, height: 386)
                            .focused($heroFocused)

                        SportsScratchEventRow(title: "LIVE & UPCOMING GAMES", events: Array((liveGames + upcoming).prefix(18)))
                            .frame(width: panelWidth, alignment: .leading)

                        SportsScratchChannelRow(title: "SPORTS CHANNELS", items: allChannels, removeChannel: removeChannel)
                            .frame(width: panelWidth, alignment: .leading)

                        SportsScratchChannelRow(title: "LEAGUES", items: leagueDisplayChannels, removeChannel: removeChannel)
                            .frame(width: panelWidth, alignment: .leading)

                        SportsScratchEventRow(title: "FAVORITE TEAMS", events: favoriteEvents)
                            .frame(width: panelWidth, alignment: .leading)

                        SportsScratchEventRow(title: "HIGHLIGHTS / TRENDING", events: highlightsTrending)
                            .frame(width: panelWidth, alignment: .leading)

                        SportsScratchEventRow(title: "SPORTS NEWS", events: sportsNewsItems)
                            .frame(width: panelWidth, alignment: .leading)

                        if sportsNewsItems.isEmpty && allChannels.isEmpty {
                            SportsScratchEmptyRow(sourceStatus: sourceStatus)
                                .frame(width: panelWidth, alignment: .leading)
                        }

                        Spacer(minLength: 110)
                    }
                    .padding(.top, 126)
                    .padding(.bottom, 90)
                }
                .frame(width: panelWidth, height: geo.size.height, alignment: .topLeading)
                .padding(.leading, gridLeadingInset)
            }
            .frame(width: geo.size.width, height: geo.size.height, alignment: .topLeading)
            .signalVisionFocusSection()
            .onAppear {
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.08) {
                    guard !VODExclusivePlaybackGate.isActive else { return }
                    heroFocused = true
                }
            }
        }
    }
}

struct SportsScratchQuickPanelHero: View {
    @EnvironmentObject var store: CatalogStore
    let event: SportsLiveEvent
    let channel: MediaItem?
    let sourceStatus: String
    @FocusState private var focused: Bool

    private var heroArtwork: String? {
        event.artworkURL ?? channel?.landscapeURL ?? channel?.posterURL ?? channel?.logoURL
    }

    private var isLive: Bool {
        let lower = event.status.lowercased()
        return lower.contains("live") || lower.contains("q") || lower.contains("period") || lower.contains("inning") || lower.contains("half")
    }

    var body: some View {
        Button(action: playBestAvailable) {
            ZStack(alignment: .bottomLeading) {
                RemoteImageFit(url: heroArtwork, mode: .fill)
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                    .background(SportsRebornBackdrop())

                ZStack {
                    LinearGradient(colors: [Color.black.opacity(0.92), Color.black.opacity(0.58), Color.black.opacity(0.10)], startPoint: .leading, endPoint: .trailing)
                    LinearGradient(colors: [Color.clear, Color.black.opacity(0.88)], startPoint: .top, endPoint: .bottom)
                    SportsCenterDiagonalStripes().opacity(0.08)
                }

                VStack(alignment: .leading, spacing: 14) {
                    HStack(spacing: 10) {
                        Text("SPORTS")
                            .font(.system(size: 14, weight: .black, design: .rounded))
                            .kerning(1.5)
                            .foregroundStyle(.black)
                            .padding(.horizontal, 14)
                            .padding(.vertical, 8)
                            .background(Capsule().fill(Color.white.opacity(0.92)))
                        Text(event.league.uppercased())
                            .font(.system(size: 14, weight: .black, design: .rounded))
                            .foregroundStyle(.white.opacity(0.78))
                        Text(isLive ? "LIVE" : event.status.uppercased())
                            .font(.system(size: 12, weight: .black, design: .rounded))
                            .foregroundStyle(.white)
                            .padding(.horizontal, 10)
                            .padding(.vertical, 6)
                            .background(Capsule().fill(isLive ? Color.red.opacity(0.95) : Color.orange.opacity(0.78)))
                    }

                    Text(event.title)
                        .font(.system(size: 54, weight: .black, design: .rounded))
                        .foregroundStyle(.white)
                        .lineLimit(2)
                        .minimumScaleFactor(0.62)
                        .frame(maxWidth: 760, alignment: .leading)
                        .shadow(color: .black.opacity(0.70), radius: 12, x: 0, y: 7)

                    Text(event.subtitle.ifEmpty(sourceStatus))
                        .font(.system(size: 20, weight: .bold, design: .rounded))
                        .foregroundStyle(.white.opacity(0.74))
                        .lineLimit(2)
                        .frame(maxWidth: 720, alignment: .leading)

                    Label(event.streamURL == nil ? (channel == nil ? "Open Sports" : "Watch Live") : "Go to Game", systemImage: "play.fill")
                        .font(.system(size: 22, weight: .black, design: .rounded))
                        .foregroundStyle(.black)
                        .padding(.horizontal, 28)
                        .padding(.vertical, 14)
                        .background(Capsule().fill(Color.white.opacity(0.96)))
                }
                .padding(.leading, 36)
                .padding(.bottom, 34)
            }
            .clipShape(RoundedRectangle(cornerRadius: 30, style: .continuous))
            .overlay(RoundedRectangle(cornerRadius: 30, style: .continuous).stroke(focused ? Color.white.opacity(0.90) : Color.white.opacity(0.14), lineWidth: focused ? 2.4 : 1.1))
            .shadow(color: .black.opacity(0.58), radius: focused ? 38 : 24, x: 0, y: 20)
            .scaleEffect(focused ? 1.012 : 1.0)
        }
        .buttonStyle(SportsNoPlatterButtonStyle())
        .focused($focused)
        .signalVisionFocusEffectPolicy()
        .modifier(TransparentTVFocusVisual())
    }

    private func playBestAvailable() {
        if let raw = event.streamURL, let url = URL(string: raw) {
            store.playbackURL = url
            store.playbackItem = MediaItem(id: event.id, title: event.title, year: "Live", type: "live", catalog: event.league, description: event.subtitle, genres: [event.league, event.status], rating: event.status, posterURL: event.artworkURL, landscapeURL: event.artworkURL, logoURL: event.artworkURL, previewURL: raw, addonName: event.status, addonIconURL: event.artworkURL)
            store.status = "Opening live sports event: \(event.title)."
            return
        }
        if let channel, let raw = channel.previewURL, let url = URL(string: raw) {
            store.playbackURL = url
            store.playbackItem = channel
            store.status = "Opening sports channel: \(channel.title)."
        } else {
            store.status = "Sports quick panel ready. Add or map sports channels to watch live."
        }
    }
}

