struct SportsRebornLiveStage: View {
    @EnvironmentObject var store: CatalogStore
    let event: SportsLiveEvent
    let channel: MediaItem?
    let channels: [MediaItem]
    let scores: [SportsLiveEvent]
    let sourceStatus: String
    @FocusState private var watchFocused: Bool

    private var isLive: Bool {
        let lower = event.status.lowercased()
        return lower.contains("live") || lower.contains("q") || lower.contains("period") || lower.contains("inning") || lower.contains("half")
    }

    private var stageArt: String? {
        event.artworkURL ?? channel?.landscapeURL ?? channel?.posterURL ?? channel?.logoURL
    }

    private var teamParts: [String] {
        for sep in [" at ", " vs ", " v ", " @ "] {
            let parts = event.title.components(separatedBy: sep)
            if parts.count >= 2 { return [parts[0], parts[1]].map { $0.trimmingCharacters(in: .whitespacesAndNewlines) } }
        }
        return [event.title]
    }

    var body: some View {
        ZStack(alignment: .bottomLeading) {
            RemoteImageFit(url: stageArt, mode: .fill)
                .frame(maxWidth: .infinity, maxHeight: .infinity)
                .background(SportsRebornBackdrop())

            ZStack {
                LinearGradient(colors: [Color.black.opacity(0.96), Color.black.opacity(0.80), Color.black.opacity(0.18)], startPoint: .leading, endPoint: .trailing)
                LinearGradient(colors: [Color.clear, Color.black.opacity(0.92)], startPoint: .top, endPoint: .bottom)
                SportsCenterDiagonalStripes().opacity(0.10)
            }

            HStack(alignment: .bottom, spacing: 24) {
                VStack(alignment: .leading, spacing: 18) {
                    HStack(spacing: 12) {
                        Text("LIVE SPORTS")
                            .font(.system(size: 15, weight: .black, design: .rounded))
                            .kerning(1.5)
                            .foregroundStyle(.black)
                            .padding(.horizontal, 16)
                            .padding(.vertical, 9)
                            .background(Capsule().fill(Color.white.opacity(0.94)))
                        Text(event.league.uppercased())
                            .font(.system(size: 16, weight: .black, design: .rounded))
                            .kerning(1.2)
                            .foregroundStyle(.white.opacity(0.82))
                        Text(isLive ? "ON NOW" : event.status.uppercased())
                            .font(.system(size: 13, weight: .black, design: .rounded))
                            .foregroundStyle(.white)
                            .padding(.horizontal, 12)
                            .padding(.vertical, 7)
                            .background(Capsule().fill(isLive ? Color.red.opacity(0.96) : Color.orange.opacity(0.78)))
                    }

                    VStack(alignment: .leading, spacing: 6) {
                        if teamParts.count >= 2 {
                            Text(teamParts[0])
                                .font(.system(size: 60, weight: .black, design: .rounded))
                                .foregroundStyle(.white)
                                .lineLimit(1)
                            Text("vs  \(teamParts[1])")
                                .font(.system(size: 60, weight: .black, design: .rounded))
                                .foregroundStyle(.white.opacity(0.92))
                                .lineLimit(1)
                        } else {
                            Text(event.title)
                                .font(.system(size: 64, weight: .black, design: .rounded))
                                .foregroundStyle(.white)
                                .lineLimit(2)
                                .minimumScaleFactor(0.54)
                        }
                    }
                    .shadow(color: .black.opacity(0.78), radius: 18, x: 0, y: 10)

                    Text(event.subtitle.ifEmpty(sourceStatus))
                        .font(.system(size: 22, weight: .bold, design: .rounded))
                        .foregroundStyle(.white.opacity(0.76))
                        .lineLimit(2)
                        .frame(maxWidth: 650, alignment: .leading)

                    HStack(spacing: 14) {
                        Button(action: playBest) {
                            Label(channel == nil ? "Open Sports" : "Watch Live", systemImage: "play.fill")
                                .font(.system(size: 25, weight: .black, design: .rounded))
                                .foregroundStyle(.black)
                                .padding(.horizontal, 34)
                                .padding(.vertical, 17)
                                .background(Capsule().fill(Color.white.opacity(0.96)))
                        }
                        .buttonStyle(SportsNoPlatterButtonStyle())
                        .focused($watchFocused)
                        .signalVisionFocusEffectPolicy()
                        .modifier(TransparentTVFocusVisual())

                        if let channel {
                            Text("ON  \(channel.title.uppercased())")
                                .font(.system(size: 16, weight: .black, design: .rounded))
                                .foregroundStyle(.white.opacity(0.80))
                                .padding(.horizontal, 18)
                                .padding(.vertical, 13)
                                .background(Capsule().fill(Color.black.opacity(0.44)))
                                .overlay(Capsule().stroke(Color.white.opacity(0.14), lineWidth: 1))
                        }
                    }

                    if !channels.isEmpty {
                        HStack(spacing: 12) {
                            ForEach(channels) { item in
                                SportsRebornMiniChannel(item: item)
                            }
                        }
                    }
                }
                .padding(.leading, 54)
                .padding(.bottom, 48)

                Spacer(minLength: 0)

                SportsRebornScoreBoard(events: scores, status: sourceStatus)
                    .frame(width: 430)
                    .padding(.trailing, 34)
                    .padding(.bottom, 44)
            }
        }
        .clipShape(RoundedRectangle(cornerRadius: 38, style: .continuous))
        .overlay(RoundedRectangle(cornerRadius: 38, style: .continuous).stroke(Color.white.opacity(0.16), lineWidth: 1.2))
        .shadow(color: Color.black.opacity(0.62), radius: 42, x: 0, y: 28)
    }

    private func playBest() {
        if let raw = event.streamURL, let url = URL(string: raw) {
            store.playbackURL = url
            store.playbackItem = MediaItem(id: event.id, title: event.title, year: "Live", type: "live", catalog: event.league, description: event.subtitle, genres: [event.league, event.status], rating: isLive ? "LIVE" : "", posterURL: event.artworkURL, landscapeURL: event.artworkURL, logoURL: event.artworkURL, previewURL: raw, addonName: event.status, addonIconURL: event.artworkURL)
            store.status = "Opening live sports event: \(event.title)."
            return
        }
        if let channel, let raw = channel.previewURL, let url = URL(string: raw) {
            store.playbackURL = url
            store.playbackItem = channel
            store.status = "Opening sports channel: \(channel.title)."
        } else {
            store.status = "Smart Sports Center ready. Add sports channels or wait for public scores."
        }
    }
}

