struct SportsRebornChannelCard: View {
    @EnvironmentObject var store: CatalogStore
    @AppStorage("sportsExcludedChannelIds") private var sportsExcludedChannelIdsRaw: String = ""
    @AppStorage("sportsManualChannelIds") private var sportsManualChannelIdsRaw: String = ""
    let item: MediaItem
    @FocusState private var focused: Bool

    private var isExcluded: Bool {
        guard let id = parsedChannelID else { return false }
        return intSet(from: sportsExcludedChannelIdsRaw).contains(id)
    }

    @ViewBuilder
    var body: some View {
        if !isExcluded {
        Button(action: play) {
            VStack(alignment: .leading, spacing: 12) {
                ZStack {
                    RoundedRectangle(cornerRadius: 18, style: .continuous)
                        .fill(LinearGradient(colors: [Color.white.opacity(0.10), Color.black.opacity(0.48)], startPoint: .topLeading, endPoint: .bottomTrailing))
                    RemoteImageFit(url: item.logoURL ?? item.posterURL ?? item.landscapeURL, mode: .fit)
                        .padding(22)
                }
                .frame(width: 220, height: 116)
                Text(item.title)
                    .font(.system(size: 17, weight: .black, design: .rounded))
                    .foregroundStyle(.white)
                    .lineLimit(1)
                Text(item.genres.first ?? item.catalog)
                    .font(.system(size: 12, weight: .bold, design: .rounded))
                    .foregroundStyle(.white.opacity(0.52))
                    .lineLimit(1)
                Text("Hold Select to remove")
                    .font(.system(size: 10, weight: .black, design: .rounded))
                    .foregroundStyle(.orange.opacity(focused ? 0.92 : 0.0))
                    .lineLimit(1)
            }
            .padding(14)
            .frame(width: 252, height: 214, alignment: .topLeading)
            .background(RoundedRectangle(cornerRadius: 28, style: .continuous).fill(focused ? Color.white.opacity(0.16) : Color.black.opacity(0.26)))
            .overlay(RoundedRectangle(cornerRadius: 28, style: .continuous).stroke(focused ? Color.white.opacity(0.86) : Color.white.opacity(0.10), lineWidth: focused ? 2 : 1))
            .scaleEffect(focused ? 1.045 : 1.0)
        }
        .buttonStyle(SportsNoPlatterButtonStyle())
        .focused($focused)
        .signalVisionFocusEffectPolicy()
        .modifier(TransparentTVFocusVisual())
        .contextMenu {
            Button(role: .destructive) { removeFromSportsSection() } label: {
                Label("Remove from Sports Section", systemImage: "minus.circle.fill")
            }
        }
        .onLongPressGesture(minimumDuration: 0.75) {
            // v800: tvOS context menus can be inconsistent on custom focused buttons.
            // Long-press still performs the user-requested removal immediately and persists the exclusion.
            removeFromSportsSection()
        }
        }
    }

    private var parsedChannelID: Int? {
        let parts = item.id.split(separator: "-")
        guard parts.count >= 3 else { return nil }
        return Int(parts[2])
    }

    private func removeFromSportsSection() {
        guard let channelID = parsedChannelID else {
            store.status = "Could not remove \(item.title): missing channel id."
            return
        }
        var excluded = intSet(from: sportsExcludedChannelIdsRaw)
        excluded.insert(channelID)
        sportsExcludedChannelIdsRaw = excluded.sorted().map(String.init).joined(separator: ",")

        var manual = intSet(from: sportsManualChannelIdsRaw)
        manual.remove(channelID)
        sportsManualChannelIdsRaw = manual.sorted().map(String.init).joined(separator: ",")
        store.status = "Removed \(item.title) from Sports Section."
    }

    private func intSet(from raw: String) -> Set<Int> {
        Set(raw.split(separator: ",").compactMap { Int($0.trimmingCharacters(in: .whitespacesAndNewlines)) })
    }

    private func play() {
        if let raw = item.previewURL, let url = URL(string: raw) {
            store.playbackURL = url
            store.playbackItem = item
            store.status = "Playing sports channel: \(item.title)."
        } else {
            store.status = "\(item.title) has no playable stream URL yet."
        }
    }
}

