struct SportsMediaCenterFullLayout: View {
    @EnvironmentObject var store: CatalogStore
    let featured: SportsLiveEvent?
    let liveGames: [SportsLiveEvent]
    let upcoming: [SportsLiveEvent]
    let favoriteEvents: [SportsLiveEvent]
    let sportsRows: [(String, [MediaItem])]
    let tickerItems: [String]
    let tickerEnabled: Bool
    let sourceStatus: String

    private var primaryEvent: SportsLiveEvent {
        // v789: Keep the Sports Center hero stable. Live score data should populate the
        // score column/rails, but it must not replace the header with a giant team
        // artwork card after async feeds load. That was causing the Sports page to
        // jump from the approved hub layout into the oversized game-art layout.
        SportsLiveEvent(id: "sports-placeholder", title: "Smart Sports Center", subtitle: "Live sports channels, scores, favorite teams, and upcoming events stay together.", league: "DC Sports", status: "Ready", artworkURL: nil, accent: .red)
    }

    private var quickChannels: [MediaItem] { Array(sportsRows.flatMap { $0.1 }.prefix(10)) }

    var body: some View {
        VStack(alignment: .leading, spacing: 22) {
            SportsCommandHeader(sourceStatus: sourceStatus, liveCount: liveGames.count, channelCount: quickChannels.count)

            SportsMediaViewingSurface(event: primaryEvent, quickChannels: quickChannels, scoreItems: liveGames, sourceStatus: sourceStatus)
                .frame(height: 470)

            // v789/v797: Preserve stable order while giving Sports its own standalone look:
            // feeds return: hero -> quick switch -> channel rows -> live/upcoming.
            // This prevents the live/upcoming score rail from inserting itself above
            // the channel rows and forcing tvOS to scroll the whole page down.
            if !quickChannels.isEmpty {
                SmartSportsChannelQuickSwitch(items: quickChannels)
            }

            ForEach(sportsRows, id: \.0) { row in
                SmartSportsLeagueChannelRow(title: row.0, items: row.1)
            }

            SportsMediaLiveUpcomingRail(title: "LIVE & UPCOMING", events: Array((liveGames + upcoming).prefix(18)))

            if tickerEnabled {
                SportsInsideScoreCrawl(items: tickerItems)
                    .frame(height: 54)
                    .padding(.top, -4)
            }

            if !favoriteEvents.isEmpty {
                SportsMediaLiveUpcomingRail(title: "MY TEAMS", events: favoriteEvents)
            }
        }
    }
}


