struct SportsMediaViewingSurface: View {
    @EnvironmentObject var store: CatalogStore
    let event: SportsLiveEvent
    let quickChannels: [MediaItem]
    let scoreItems: [SportsLiveEvent]
    let sourceStatus: String
    @FocusState private var surfaceFocused: Bool

    private var isLive: Bool {
        let lower = event.status.lowercased()
        return lower.contains("live") || lower.contains("q") || lower.contains("period") || lower.contains("inning") || lower.contains("half")
    }

    private var teams: [String] {
        let separators = [" at ", " vs ", " v ", " @ "]
        for sep in separators {
            let parts = event.title.components(separatedBy: sep)
            if parts.count >= 2 { return [parts[0], parts[1]].map { $0.trimmingCharacters(in: .whitespacesAndNewlines) } }
        }
        return [event.title, event.league]
    }

    var body: some View {
        ZStack(alignment: .bottomLeading) {
            RemoteImageFit(url: event.artworkURL, mode: .fill)
                .frame(maxWidth: .infinity, maxHeight: .infinity)
                .background(SportsMediaCenterBackdrop())
                .clipShape(RoundedRectangle(cornerRadius: 0, style: .continuous))

            ZStack {
                LinearGradient(colors: [Color.black.opacity(0.98), Color.black.opacity(0.72), Color.black.opacity(0.10)], startPoint: .leading, endPoint: .trailing)
                LinearGradient(colors: [Color.black.opacity(0.28), Color.clear, Color.black.opacity(0.96)], startPoint: .top, endPoint: .bottom)
            }

            HStack(alignment: .bottom, spacing: 28) {
                VStack(alignment: .leading, spacing: 18) {
                    HStack(spacing: 10) {
                        Text(event.league.uppercased())
                            .font(.system(size: 18, weight: .black, design: .rounded))
                            .foregroundStyle(.white)
                            .padding(.horizontal, 18)
                            .padding(.vertical, 10)
                            .background(Capsule().fill(Color.black.opacity(0.58)))
                            .overlay(Capsule().stroke(Color.white.opacity(0.16), lineWidth: 1))
                        Text(isLive ? "LIVE" : event.status.uppercased())
                            .font(.system(size: 14, weight: .black, design: .rounded))
                            .foregroundStyle(.white)
                            .padding(.horizontal, 12)
                            .padding(.vertical, 8)
                            .background(Capsule().fill(isLive ? Color.red.opacity(0.96) : Color.white.opacity(0.16)))
                    }

                    VStack(alignment: .leading, spacing: 8) {
                        Text(teams.first ?? event.title)
                            .font(.system(size: 52, weight: .black, design: .rounded))
                            .foregroundStyle(.white)
                            .lineLimit(1)
                            .shadow(color: .black.opacity(0.8), radius: 10, x: 0, y: 6)
                        Text(teams.dropFirst().first ?? event.subtitle)
                            .font(.system(size: 52, weight: .black, design: .rounded))
                            .foregroundStyle(.white)
                            .lineLimit(1)
                            .shadow(color: .black.opacity(0.8), radius: 10, x: 0, y: 6)
                    }

                    Text(event.subtitle.ifEmpty(sourceStatus))
                        .font(.system(size: 22, weight: .bold, design: .rounded))
                        .foregroundStyle(.white.opacity(0.76))
                        .lineLimit(2)
                        .frame(maxWidth: 560, alignment: .leading)

                    Button(action: watchBestAvailable) {
                        Text(quickChannels.isEmpty ? "View Game" : "Go to Game")
                            .font(.system(size: 26, weight: .black, design: .rounded))
                            .foregroundStyle(.black)
                            .padding(.horizontal, 42)
                            .padding(.vertical, 18)
                            .background(Capsule().fill(Color.white.opacity(0.96)))
                    }
                    .buttonStyle(SportsNoPlatterButtonStyle())
                    .focused($surfaceFocused)
                    .signalVisionFocusEffectPolicy()
                    .modifier(TransparentTVFocusVisual())
                }
                .padding(.leading, 54)
                .padding(.bottom, 78)

                Spacer(minLength: 0)

                SportsMediaScoreColumn(events: scoreItems, status: sourceStatus)
                    .frame(width: 420)
                    .padding(.trailing, 38)
                    .padding(.bottom, 66)
            }

        }
        .clipShape(RoundedRectangle(cornerRadius: 34, style: .continuous))
        .overlay(RoundedRectangle(cornerRadius: 34, style: .continuous).stroke(Color.white.opacity(0.14), lineWidth: 1))
        .shadow(color: .black.opacity(0.55), radius: 34, x: 0, y: 22)
    }

    private func watchBestAvailable() {
        if let raw = event.streamURL, let url = URL(string: raw) {
            store.playbackURL = url
            store.playbackItem = MediaItem(id: event.id, title: event.title, year: "Live", type: "live", catalog: event.league, description: event.subtitle, genres: [event.league, event.status], rating: isLive ? "LIVE" : "", posterURL: event.artworkURL, landscapeURL: event.artworkURL, logoURL: event.artworkURL, previewURL: raw, addonName: event.status, addonIconURL: event.artworkURL)
            store.status = "Opening live sports event: \(event.title)."
            return
        }
        if let item = quickChannels.first, let raw = item.previewURL, let url = URL(string: raw) {
            store.playbackURL = url
            store.playbackItem = item
            store.status = "Opening sports channel: \(item.title)."
        } else {
            store.status = "Sports Center ready. Add or map sports channels to watch live."
        }
    }
}

