struct MoviesShowsReleaseTickerOverlay: View {
    @EnvironmentObject var store: CatalogStore
    @AppStorage("newEpisodeAlertTheme") private var newEpisodeAlertThemeRaw: String = NewEpisodeAlertTheme.glass.rawValue
    private let tickerManager = MoviesShowsTickerManager.shared

    private var releaseItems: [MediaItem] {
        tickerManager.releaseItems(from: store.rows)
    }

    private var alertTheme: NewEpisodeAlertTheme {
        NewEpisodeAlertTheme(rawValue: newEpisodeAlertThemeRaw) ?? .glass
    }

    var body: some View {
        GeometryReader { geo in
            // v803: anchor to the actual top-right Live TV card frame. The ticker
            // trails with that card and sits just above it without touching the menu.
            let gridLeading: CGFloat = 72
            let gridTrailing: CGFloat = 76
            let gridTop: CGFloat = 174
            let gridInnerTop: CGFloat = 0
            let gridColumnSpacing: CGFloat = 36
            let cardWidth: CGFloat = 360
            let cardHeight: CGFloat = 58
            let availableWidth = max(0, geo.size.width - gridLeading - gridTrailing - (gridColumnSpacing * 3))
            let liveCardWidth = availableWidth / 4
            let rightmostCardFrame = CGRect(
                x: gridLeading + (liveCardWidth + gridColumnSpacing) * 3,
                y: gridTop + gridInnerTop,
                width: liveCardWidth,
                height: 278
            )
            // v807: match the ticker to the safe gap between the Search/Time area and
            // the top-right Live TV grid card. This keeps it visibly above the card without
            // touching the top controls.
            let topControlsClearanceBottom: CGFloat = 66
            let safeGapTop = topControlsClearanceBottom
            let safeGapBottom = rightmostCardFrame.minY
            let matchedGapCenterY = safeGapTop + ((safeGapBottom - safeGapTop) / 2)
            let tickerTrailing = rightmostCardFrame.maxX
            let tickerX = tickerTrailing - cardWidth / 2
            let tickerY = max(topControlsClearanceBottom + cardHeight / 2 + 2, min(matchedGapCenterY, rightmostCardFrame.minY - cardHeight / 2 - 8))
            let clearsCard = tickerY + cardHeight / 2 <= rightmostCardFrame.minY - 8
            let clearsMenu = tickerY - cardHeight / 2 >= topControlsClearanceBottom
            if geo.size.height >= 820 && clearsCard && clearsMenu {
                MoviesShowsReleaseTickerCard(items: releaseItems, theme: alertTheme)
                    .position(x: tickerX, y: tickerY)
            }
        }
        .allowsHitTesting(false)
    }
}

