        .padding(.vertical, 10)
        .frame(width: 340, height: 52, alignment: .leading)
        .background(
            RoundedRectangle(cornerRadius: 18, style: .continuous)
                .fill(LinearGradient(colors: [Color.black.opacity(0.88), Color(red: 0.16, green: 0.015, blue: 0.02).opacity(0.84)], startPoint: .leading, endPoint: .trailing))
        )
        .overlay(RoundedRectangle(cornerRadius: 18, style: .continuous).stroke(Color.white.opacity(0.12), lineWidth: 1))
        .shadow(color: Color.black.opacity(0.40), radius: 18, x: 0, y: 10)
        .onChange(of: displayItems.joined(separator: "|")) { _ in activeIndex = 0 }
        .task(id: "\(displayItems.joined(separator: "|"))|\(unityAnimations.revision)") {
            guard displayItems.count > 1, unityAnimations.allows(.tickerMotion) else { return }
            while !Task.isCancelled {
                try? await Task.sleep(nanoseconds: 4_000_000_000)
                guard !Task.isCancelled,
