struct PremiumSportsTickerShell: View {
    @ObservedObject private var unityAnimations = UnityAnimationCoordinator.shared
    let favoriteTeams: String
    var liveItems: [String] = []
    private var teams: [String] {
        favoriteTeams
            .components(separatedBy: CharacterSet(charactersIn: ",\n"))
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
    }
    private var tickerItems: [String] {
        if !liveItems.isEmpty { return Array(liveItems.prefix(18)) }
        let base = teams.isEmpty ? ["Choose favorite teams", "Sports-only M3U ready", "PPV/Event Watch ready"] : teams
        return base.prefix(8).map { "★ \($0): waiting for verified live feed" } + [
            "NFL • NBA • MLB • NHL • WNBA • NCAA",
            "Soccer • UFC • Boxing • WWE • AEW • F1 • NASCAR",
            "Sports Center ticker can be turned off in Settings"
        ]
    }
    private var tickerText: String {
        tickerItems.joined(separator: "     ◆     ") + "     ◆     "
    }
    var body: some View {
        HStack(spacing: 0) {
            HStack(spacing: 10) {
                ZStack {
                    RoundedRectangle(cornerRadius: 8, style: .continuous).fill(Color.red.opacity(0.94))
                    Text("DC")
                        .font(.system(size: 18, weight: .black, design: .rounded))
                        .foregroundStyle(.white)
                }
                .frame(width: 42, height: 34)
                VStack(alignment: .leading, spacing: 0) {
                    Text("SPORTSCENTER")
                        .font(.system(size: 13, weight: .black, design: .rounded))
                        .kerning(1.8)
                    Text("LIVE TICKER")
                        .font(.system(size: 9, weight: .black, design: .rounded))
                        .kerning(1.1)
                        .foregroundStyle(.white.opacity(0.62))
                }
            }
            .foregroundStyle(.white)
            .padding(.horizontal, 16)
            .frame(width: 214, height: 66)
            .background(
                LinearGradient(colors: [Color.black.opacity(0.94), Color(red: 0.23, green: 0.02, blue: 0.025).opacity(0.94)], startPoint: .leading, endPoint: .trailing)
            )
            .overlay(Rectangle().fill(Color.red.opacity(0.95)).frame(width: 4), alignment: .trailing)

            GeometryReader { proxy in
                let text = tickerText
                // vBRDC090: deterministic Timeline motion replaces an uncancellable
                // repeatForever transaction. The ticker remains visually mounted but its
                // frame clock pauses whenever another navigation/overlay lane owns budget.
                TimelineView(.animation(minimumInterval: 1.0 / 30.0, paused: !unityAnimations.allows(.tickerMotion))) { timeline in
                    let travel = max(1200, proxy.size.width)
                    let cycle: TimeInterval = 28
                    let elapsed = timeline.date.timeIntervalSinceReferenceDate.truncatingRemainder(dividingBy: cycle)
                    let phase = CGFloat(elapsed / cycle)
                    let offset = proxy.size.width - phase * (proxy.size.width + travel)
                    HStack(spacing: 90) {
                        Text(text)
                        Text(text)
                    }
                    .font(.system(size: 20, weight: .black, design: .rounded))
                    .foregroundStyle(.white.opacity(0.92))
                    .lineLimit(1)
                    .offset(x: offset)
                    .frame(height: proxy.size.height, alignment: .center)
                    .clipped()
                }
            }
            .padding(.horizontal, 22)
            .frame(height: 66)
            .background(
                ZStack {
                    LinearGradient(colors: [Color(red: 0.025, green: 0.027, blue: 0.030).opacity(0.96), Color.black.opacity(0.94)], startPoint: .topLeading, endPoint: .bottomTrailing)
                    HStack(spacing: 22) {
                        ForEach(0..<18, id: \.self) { i in
                            Rectangle()
                                .fill(i % 2 == 0 ? Color.white.opacity(0.035) : Color.red.opacity(0.045))
                                .frame(width: 3)
                        }
                        Spacer()
                    }
                }
            )
        }
        .frame(height: 66)
        .clipShape(RoundedRectangle(cornerRadius: 18, style: .continuous))
