// v536: Global Favorites tab foundation. It keeps the tab visible now and reads the existing Live TV
// My Favorites store so channels added from Live TV appear outside the Live TV surface too.
struct GlobalFavoritesScreen: View {
    @EnvironmentObject var store: CatalogStore
    @EnvironmentObject var unityCore: UnityAppCore
    @AppStorage("favoriteMediaIds") private var favoriteMediaIdsRaw: String = ""
    @AppStorage("favoriteMediaRestoreGenerationV1") private var favoriteMediaRestoreGeneration: Int = 0
    @SceneStorage("globalFavorites.selectedIndex") private var selectedIndex: Int = 0
    @FocusState private var focusedRow: Int?
    @FocusState private var removeFocused: Bool
    @State private var cachedFavoriteItems: [MediaItem] = []
    @State private var displayedFavoriteBackdropURL: String? = nil
    @State private var cachedFavoriteSignature: Int = 0
    @State private var favoritesSurfaceActive: Bool = false
    @StateObject private var favoritesAsyncRuntime = FavoritesAsyncTaskRuntime()
    private var favoritesRebuildTask: Task<Void, Never>? {
            get { favoritesAsyncRuntime.favoritesRebuildTask }
            nonmutating set { favoritesAsyncRuntime.favoritesRebuildTask = newValue }
        }
    private var favoriteSnapshotHydrationTask: Task<Void, Never>? {
            get { favoritesAsyncRuntime.favoriteSnapshotHydrationTask }
            nonmutating set { favoritesAsyncRuntime.favoriteSnapshotHydrationTask = newValue }
        }
    private var favoriteBackdropSettleTask: Task<Void, Never>? {
            get { favoritesAsyncRuntime.favoriteBackdropSettleTask }
            nonmutating set { favoritesAsyncRuntime.favoriteBackdropSettleTask = newValue }
        }

    private var selectedFavorite: MediaItem? {
        guard !cachedFavoriteItems.isEmpty else { return nil }
        return cachedFavoriteItems[min(max(selectedIndex, 0), cachedFavoriteItems.count - 1)]
    }

    private var selectedFavoriteBackdropURL: String? {
        guard let selectedFavorite else { return nil }
        let landscape = selectedFavorite.landscapeURL?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        // vBRDC163: a portrait poster is never promoted to the full-screen Favorites hero.
        // That fallback was the source of the giant/stretched poster treatment captured on
        // device when a saved title had no true landscape artwork. Missing backdrops now
        // fall through to the existing neutral gradient instead of distorting the surface.
        return landscape.isEmpty ? nil : landscape
    }

    private var row: MediaRow {
        MediaRow(id: "catalog-favorites-quick-panel", title: "Favorite Movies & Shows", items: cachedFavoriteItems)
    }

    var body: some View {
        let unityPalette = unityCore.palette
        ZStack(alignment: .bottomLeading) {
            ZStack {
                LinearGradient(colors: unityPalette.backgroundGradient, startPoint: .topLeading, endPoint: .bottomTrailing)
                RadialGradient(
                    colors: [unityPalette.accent.opacity(unityPalette.isPureBlack ? 0.0 : 0.085), .clear],
                    center: .topTrailing,
                    startRadius: 20,
                    endRadius: 920
                )

                if let artworkURL = displayedFavoriteBackdropURL ?? selectedFavoriteBackdropURL {
                    GeometryReader { viewport in
                        RemoteImageFit(
                            url: artworkURL,
                            mode: .fill,
                            maxPixelSize: 1920,
                            preservePreviousOnURLChange: true,
                            publishDuringSurfaceHandoff: true,
                            deferHeavyLoadDuringNavigation: true
                        )
                        .frame(width: viewport.size.width, height: viewport.size.height)
                        .clipped()
                    }
                        .opacity(0.46)
                        .saturation(1.08)
                        .contrast(1.04)
                        .overlay(
                            LinearGradient(
                                colors: [
                                    Color.black.opacity(0.92),
                                    Color.black.opacity(0.74),
                                    Color.black.opacity(0.52),
                                    Color.black.opacity(0.36)
                                ],
                                startPoint: .leading,
                                endPoint: .trailing
                            )
                        )
                        .overlay(
                            LinearGradient(
                                colors: [Color.black.opacity(0.78), Color.black.opacity(0.20), Color.black.opacity(0.88)],
                                startPoint: .top,
                                endPoint: .bottom
                            )
                        )
                }

                LinearGradient(colors: [Color.black.opacity(0.20), Color.clear, Color.black.opacity(0.34)], startPoint: .topLeading, endPoint: .bottomTrailing)
            }
            .ignoresSafeArea()

            VStack(alignment: .leading, spacing: 18) {
                Spacer()
                HStack(alignment: .bottom, spacing: 18) {
                    ThemedPanelLogo(title: "Favorites")
                        .frame(height: 34, alignment: .leading)
                    Text("Movies & Shows quick panel")
                        .font(.system(size: 19, weight: .heavy, design: .rounded))
                        .foregroundStyle(.white.opacity(0.62))
                    Spacer()
                }

                if cachedFavoriteItems.isEmpty {
                    VStack(alignment: .leading, spacing: 14) {
                        Text("No movie or show favorites yet")
                            .font(.system(size: 34, weight: .black, design: .rounded))
                            .foregroundStyle(.white)
                        Text("Hold Select on a movie or show card, then choose Add to Favorites. Live TV channel favorites stay in Live TV → My Favorites.")
                            .font(.system(size: 21, weight: .semibold, design: .rounded))
                            .foregroundStyle(.white.opacity(0.62))
                            .lineLimit(3)
                    }
                    .padding(34)
                    .frame(maxWidth: .infinity, minHeight: 240, alignment: .leading)
                    .background(RoundedRectangle(cornerRadius: 34, style: .continuous).fill(Color.white.opacity(0.045)))
                    .overlay(RoundedRectangle(cornerRadius: 34, style: .continuous).stroke(Color.white.opacity(0.10), lineWidth: 1))
                    .focusable(true)
                    .focused($focusedRow, equals: 0)
                    .modifier(TransparentTVFocusVisual())
                } else {
                    GridOSFixedSlotCatalogRail(
                        row: row,
                        rowIndex: 0,
                        focusedRow: $focusedRow,
                        selectedIndex: $selectedIndex,
                        onNavigationActivity: { _ in
                            UnityAnimationCoordinator.shared.registerNavigationActivity(source: "favorites", settleAfter: 0.22)
                        },
                        allowsLazyRefresh: false,
                        allowsRailAnimations: false,
                        fixedPreviewCardWidth: 142
                    )

                    HStack(spacing: 14) {
                        if let selectedFavorite {
                            Text("Remove from Favorites")
                                .font(.system(size: 18, weight: .black, design: .rounded))
                                .padding(.horizontal, 22)
                                .padding(.vertical, 12)
                                .background(Capsule().fill(removeFocused ? Color.red.opacity(0.70) : Color.white.opacity(0.10)))
                                .overlay(Capsule().stroke(removeFocused ? Color.white.opacity(0.70) : Color.white.opacity(0.14), lineWidth: 1))
                                .contentShape(Capsule())
                                .focusable(true)
                                .focused($removeFocused)
                                .onTapGesture { removeFavorite(selectedFavorite) }
                                .accessibilityAddTraits(.isButton)
                            Text("Press Select to open details here")
                                .font(.system(size: 16, weight: .bold, design: .rounded))
                                .foregroundStyle(.white.opacity(0.52))
                        }
                    }
                    .padding(.top, 4)
                }
            }
            .padding(.horizontal, 86)
            .padding(.bottom, 74)
        }
        .onAppear {
            favoritesSurfaceActive = true
            store.liveQuickPanelOpen = false
            store.topMenuFocusLocked = false
            rebuildFavoritesCache(force: true)
            scheduleMissingFavoriteSnapshotHydration()
            selectedIndex = min(max(selectedIndex, 0), max(cachedFavoriteItems.count - 1, 0))
            displayedFavoriteBackdropURL = selectedFavoriteBackdropURL
            focusedRow = 0
        }
        .onDisappear {
            favoritesSurfaceActive = false
            favoritesRebuildTask?.cancel()
            favoritesRebuildTask = nil
            favoriteSnapshotHydrationTask?.cancel()
            favoriteSnapshotHydrationTask = nil
            favoriteBackdropSettleTask?.cancel()
            favoriteBackdropSettleTask = nil
            displayedFavoriteBackdropURL = nil
            // vBRDC091: Favorites is a short-lived surface. Drop its snapshot rather than
            // letting SwiftUI's outgoing branch retain MediaItems/artwork identities while
            // the destination catalog begins its first scroll transaction.
            cachedFavoriteItems.removeAll(keepingCapacity: false)
            cachedFavoriteSignature = 0
            PremiumRemoteImageLoader.releaseTransientSurfaceResources(domain: .favorites, reason: "Favorites disappeared")
        }
        .onChange(of: favoriteMediaIdsRaw) { _ in
            guard favoritesSurfaceActive else { return }
            scheduleFavoritesCacheRebuild(force: true)
            scheduleMissingFavoriteSnapshotHydration()
        }
        .onChange(of: favoriteMediaRestoreGeneration) { _ in
            guard favoritesSurfaceActive else { return }
            rebuildFavoritesCache(force: true)
            scheduleMissingFavoriteSnapshotHydration()
        }
        .onChange(of: selectedIndex) { _ in
            scheduleFavoriteBackdropUpdate()
        }
        .onChange(of: store.selectedDetail?.id) { detailID in
            guard detailID == nil,
                  unityCore.isRuntimeOwner(.favorites),
                  store.playbackURL == nil,
                  !store.searchActive else { return }
            DispatchQueue.main.async {
                focusedRow = 0
                scheduleFavoritesCacheRebuild(force: true)
            }
        }
        .onChange(of: store.contentFocusToken) { _ in
            // vBRDC154: explicit counterpart to the top-menu Favorites DOWN handoff.
            // Clear any secondary-button focus and reacquire the Favorites rail on the
            // next run-loop turn so tvOS cannot resolve the command against the hidden
            // persistent Live TV surface underneath this dedicated screen.
            guard favoritesSurfaceActive,
                  unityCore.isRuntimeOwner(.favorites),
                  store.playbackURL == nil,
                  !store.searchActive else { return }
            removeFocused = false
            focusedRow = nil
            DispatchQueue.main.async {
                guard favoritesSurfaceActive,
                      unityCore.isRuntimeOwner(.favorites),
                      store.playbackURL == nil,
                      !store.searchActive else { return }
                focusedRow = 0
            }
        }
        .signalMoveCommand { direction in
            UnityAnimationCoordinator.shared.registerNavigationActivity(source: "favorites", settleAfter: 0.22)
            if direction == .up { store.menuFocusToken += 1 }
            if direction == .down && !cachedFavoriteItems.isEmpty { removeFocused = true }
        }
        .signalVisionExitCommand { closeFavoritesSurface() }
    }

    @MainActor
    private func closeFavoritesSurface() {
        favoritesSurfaceActive = false
        favoritesRebuildTask?.cancel()
        favoritesRebuildTask = nil
        favoriteSnapshotHydrationTask?.cancel()
        favoriteSnapshotHydrationTask = nil
        PremiumRemoteImageLoader.releaseTransientSurfaceResources(domain: .favorites, reason: "Favorites Back/Exit")
        focusedRow = nil
        removeFocused = false
        store.liveQuickPanelOpen = false
        store.topMenuFocusLocked = false
        // vBRDC086: clear Favorites-owned detail/hero restore identity before Home mounts.
        // Root repeats this invariant on the tab handoff as a second line of defense.
        store.clearFavoritesPresentationStateForNavigation(reason: "Favorites exit command")
        unityCore.select(.home, store: store, reason: "Favorites close")
    }

    @MainActor
    private func scheduleFavoriteBackdropUpdate() {
        favoriteBackdropSettleTask?.cancel()
        let expectedIndex = selectedIndex
        let expectedURL = selectedFavoriteBackdropURL
        favoriteBackdropSettleTask = Task { @MainActor in
            // vBRDC158: keep the already-decoded background while the user rapidly moves
            // across Favorites. A full-screen image decode starts only after focus settles.
            try? await Task.sleep(nanoseconds: 300_000_000)
            guard !Task.isCancelled, favoritesSurfaceActive, selectedIndex == expectedIndex else { return }
            displayedFavoriteBackdropURL = expectedURL
            favoriteBackdropSettleTask = nil
        }
    }

    @MainActor
    private func scheduleFavoritesCacheRebuild(force: Bool) {
        favoritesRebuildTask?.cancel()
        favoritesRebuildTask = Task { @MainActor in
            // vBRDC102: provider chatter joins the same interactive-metadata lane as
            // catalog rows and Live TV/Gracenote instead of racing Favorites focus.
            await Task.yield()
            try? await Task.sleep(nanoseconds: 90_000_000)
            guard await UnityFrameRuntime.shared.waitUntilPermittedDurably(.interactiveMetadata) else {
                favoritesRebuildTask = nil
                return
            }
            guard !Task.isCancelled,
                  favoritesSurfaceActive,
                  unityCore.isRuntimeOwner(.favorites),
                  store.playbackURL == nil else { return }
            rebuildFavoritesCache(force: force)
            favoritesRebuildTask = nil
        }
    }

    @MainActor
    private func scheduleMissingFavoriteSnapshotHydration() {
        favoriteSnapshotHydrationTask?.cancel()
        let keys = favoriteMediaKeySet(favoriteMediaIdsRaw)
        guard !keys.isEmpty else {
            favoriteSnapshotHydrationTask = nil
            return
        }

        let persisted = persistedFavoriteMediaItems(matching: keys)
        let snapshotMissingKeys = keys.filter { key in
            !persisted.contains { mediaFavoriteKeys(for: $0).contains(key) }
        }
        guard !snapshotMissingKeys.isEmpty else {
            favoriteSnapshotHydrationTask = nil
            return
        }

        // vBRDC159: only touch the large catalog collection when a durable Favorite record
        // is genuinely missing. Normal Favorites entry is snapshot-first and does not flatten
        // or hash thousands of provider items on the Siri Remote navigation path.
        var catalogRecovered: [String: MediaItem] = [:]
        var unresolved = snapshotMissingKeys
        for row in store.rows where !unresolved.isEmpty {
            for item in row.items where isFavoriteMovieOrShow(item) && !unresolved.isEmpty {
                let aliases = mediaFavoriteKeys(for: item)
                let matches = unresolved.filter { aliases.contains($0) }
                for key in matches { catalogRecovered[key] = item }
                unresolved.subtract(matches)
            }
        }
        let missingKeys = unresolved.sorted()

        favoriteSnapshotHydrationTask = Task { @MainActor in
            // First convert any currently loaded catalog matches into durable snapshots so
            // subsequent Favorites entries never need to scan the catalog for them again.
            var recovered = 0
            var migratedKeys = keys
            var migrated = false
            for (key, item) in catalogRecovered {
                guard !Task.isCancelled else { return }
                persistFavoriteMediaSnapshot(item)
                let modern = mediaFavoriteKey(item)
                if modern != key {
                    migratedKeys.remove(key)
                    migratedKeys.insert(modern)
                    migrated = true
                }
                recovered += 1
            }

            // Older profile backups can still contain ID-only favorites that are absent from
            // all loaded catalogs. Reconstruct those directly from Cinemeta/TMDB.
            for key in missingKeys.prefix(64) {
                guard !Task.isCancelled, favoritesSurfaceActive, unityCore.isRuntimeOwner(.favorites) else { break }
                if let item = await store.rehydrateFavoriteMediaItem(fromFavoriteKey: key),
                   isFavoriteMovieOrShow(item) {
                    persistFavoriteMediaSnapshot(item)
                    let modern = mediaFavoriteKey(item)
                    if modern != key {
                        migratedKeys.remove(key)
                        migratedKeys.insert(modern)
                        migrated = true
                    }
                    recovered += 1
                }
                await Task.yield()
            }
            guard !Task.isCancelled else { return }
            if migrated { favoriteMediaIdsRaw = migratedKeys.sorted().joined(separator: "|") }
            if recovered > 0 || migrated { rebuildFavoritesCache(force: true) }
            favoriteSnapshotHydrationTask = nil
        }
    }

    private func rebuildFavoritesCache(force: Bool) {
        let keys = favoriteMediaKeySet(favoriteMediaIdsRaw)
        // Decode/merge the durable snapshot store once per rebuild instead of twice.
        let persistedItems = persistedFavoriteMediaItems(matching: keys)
        var hasher = Hasher()
        hasher.combine(favoriteMediaIdsRaw)
        for item in persistedItems.sorted(by: { mediaFavoriteKey($0) < mediaFavoriteKey($1) }) {
            hasher.combine(mediaFavoriteKey(item))
            hasher.combine(item.logoURL ?? "")
            hasher.combine(item.posterURL ?? "")
            hasher.combine(item.landscapeURL ?? "")
        }
        let signature = hasher.finalize()
        guard force || signature != cachedFavoriteSignature else { return }

        var seen = Set<String>()
        var snapshot: [MediaItem] = []
        snapshot.reserveCapacity(keys.count)

        // vBRDC159: persisted Favorites are the primary render source. This makes normal
        // entry O(number-of-favorites) instead of O(all catalog/provider items).
        for item in persistedItems where isFavoriteMovieOrShow(item) {
            let aliases = mediaFavoriteKeys(for: item)
            let alreadyRepresented = snapshot.contains { !aliases.isDisjoint(with: mediaFavoriteKeys(for: $0)) }
            if !alreadyRepresented, seen.insert(mediaFavoriteKey(item)).inserted { snapshot.append(item) }
        }

        // Only consult catalog rows for favorite identities that still have no durable
        // snapshot (old restore codes / very old installs). Once found, the hydration path
        // persists them so this fallback disappears on the next entry.
        let represented = snapshot.reduce(into: Set<String>()) { partial, item in
            partial.formUnion(mediaFavoriteKeys(for: item))
        }
        let missingKeys = keys.subtracting(represented)
        if !missingKeys.isEmpty {
            for catalogRow in store.rows {
                for item in catalogRow.items where isFavoriteMovieOrShow(item) {
                    guard !missingKeys.isDisjoint(with: mediaFavoriteKeys(for: item)) else { continue }
                    let aliases = mediaFavoriteKeys(for: item)
                    let alreadyRepresented = snapshot.contains { !aliases.isDisjoint(with: mediaFavoriteKeys(for: $0)) }
                    if !alreadyRepresented, seen.insert(mediaFavoriteKey(item)).inserted { snapshot.append(item) }
                }
            }
        }
        cachedFavoriteItems = snapshot
        cachedFavoriteSignature = signature
        selectedIndex = min(max(selectedIndex, 0), max(snapshot.count - 1, 0))
    }

    private func removeFavorite(_ item: MediaItem) {
        var keys = favoriteMediaKeySet(favoriteMediaIdsRaw)
        keys.subtract(mediaFavoriteKeys(for: item))
        removeFavoriteMediaSnapshot(for: item)
        favoriteMediaIdsRaw = keys.sorted().joined(separator: "|")
        store.status = "Removed \(item.title) from Favorites."
    }
}

struct FavoriteLiveChannelCard: View {
    let channel: LiveTVChannel
    let action: () -> Void
    @FocusState private var focused: Bool

    var body: some View {
        VStack(alignment: .leading, spacing: 12) {
                RemoteImageFit(url: channel.bestArtworkURL, mode: .fit)
                    .frame(width: 270, height: 150)
                    .background(Color.black.opacity(0.30))
                    .clipShape(RoundedRectangle(cornerRadius: 24, style: .continuous))
                Text(channel.name)
                    .font(.system(size: 21, weight: .black, design: .rounded))
                    .foregroundStyle(.white)
                    .lineLimit(1)
                Text([channel.number, channel.category, channel.source].filter { !$0.isEmpty }.joined(separator: " • "))
                    .font(.system(size: 14, weight: .semibold, design: .rounded))
                    .foregroundStyle(.white.opacity(0.56))
                    .lineLimit(1)
            }
            .padding(14)
            .frame(width: 304, height: 250, alignment: .topLeading)
            .background(RoundedRectangle(cornerRadius: 30, style: .continuous).fill(Color.black.opacity(focused ? 0.72 : 0.42)))
            .overlay(RoundedRectangle(cornerRadius: 30, style: .continuous).stroke(focused ? Color(red: 0.24, green: 0.72, blue: 1.0).opacity(0.96) : Color.white.opacity(0.10), lineWidth: focused ? 2 : 1))
            .scaleEffect(focused ? 1.04 : 1.0)
        .contentShape(RoundedRectangle(cornerRadius: 30, style: .continuous))
        .focusable(true)
        .focused($focused)
        .onTapGesture(perform: action)
        .accessibilityAddTraits(.isButton)
    }
}
